"""Library catalog: model books as nodes and walk the shelf with a librarian walker."""

node Book {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

walker Librarian {
    has shelf_label: str = "Main";

    can start with Root entry {
        print(f"Shelving books for {self.shelf_label} shelf");
        visit [-->];
    }

    can shelve with Book entry {
        status = "IN" if here.available else "OUT";
        print(f"[{status}] {here.title} ({here.year})");
        visit [-->];
    }
}

with entry {
    root ++> Book(title="Dune", year=1965)
        ++> Book(title="Neuromancer", year=1984)
        ++> Book(title="Circe", year=2018, available=False);
    root spawn Librarian(shelf_label="Sci-Fi & Fantasy");
}

"""Delivery cost calculator: cities as nodes, roads as typed edges with per-km tolls."""

node City {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

edge Road {
    has length_km: float = 0.0;
}

walker Courier {
    has total_cost: float = 0.0;
    has toll_per_km: float = 0.25;

    can start with Root entry {
        visit [-->] else { disengage; }
    }

    can arrive with City entry {
        print(f"Courier at {here.title}");
        visit [->:Road:->] else { disengage; }
    }

    can travel with Road entry {
        leg_toll = here.length_km * self.toll_per_km;
        self.total_cost += leg_toll;
        print(f"  road {here.length_km} km @ ${self.toll_per_km}/km -> ${leg_toll:.2f}");
        visit [-->];
    }
}

with entry {
    portland = City(title="Portland");
    seattle = City(title="Seattle");
    vancouver = City(title="Vancouver");
    root ++> portland;
    portland +>:Road(length_km=12.5):+> seattle;
    seattle +>:Road(length_km=8.0):+> vancouver;
    courier = Courier();
    root spawn courier;
    print(f"Total delivery cost: ${courier.total_cost:.2f}");
}

"""Delivery cost calculator: cities as nodes, roads as typed edges with per-km tolls."""

node City {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

edge Road: City --> City {
    has length_km: float = 0.0;

    can charge with Courier entry {
        leg_toll = self.length_km * visitor.toll_per_km;
        visitor.total_cost += leg_toll;
        print(f"  road {self.length_km} km @ ${visitor.toll_per_km}/km -> ${leg_toll:.2f}");
    }
}

walker Courier {
    has total_cost: float = 0.0;
    has toll_per_km: float = 0.25;

    can start with Root entry {
        visit [-->] else { disengage; }
    }

    can arrive with City entry {
        print(f"Courier at {here.title}");
        visit [->:Road:->][?:City] else { disengage; }
    }
}

with entry {
    portland = City(title="Portland");
    seattle = City(title="Seattle");
    vancouver = City(title="Vancouver");
    root ++> portland;
    portland +>:Road(length_km=12.5):+> seattle;
    seattle +>:Road(length_km=8.0):+> vancouver;
    courier = Courier();
    root spawn courier;
    print(f"Total delivery cost: ${courier.total_cost:.2f}");
}

