    has title: str = "Trailhead";
    has year: int = 0;
    has available: bool = True;
}

node Waypoint {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

node Summit {
    has title: str = "Summit";
    has year: int = 0;
    has available: bool = True;
}

walker Hiker {
    has stops: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can hike with Trailhead entry {
        print("Departing trailhead");
        visit [-->];
    }

    can hike with Waypoint entry {
        self.stops += 1;
        print(f"Stop {self.stops}");
        visit [-->];
    }

    can hike with Summit entry {
        print(f"Trail complete — passed {self.stops} waypoints to the summit");
        disengage;
    }
}

