"""Hiking trail: chain waypoints from trailhead to summit and walk them with a hiker."""

node Trailhead {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

node Waypoint {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

node Summit {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

walker Hiker {
    has stop_number: int = 0;
    has waypoints_passed: int = 0;
    has target_waypoints: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can begin with Trailhead entry {
        self.stop_number += 1;
        print(f"Stop {self.stop_number}: trailhead");
        visit [-->];
    }

    can pass with Waypoint entry {
        self.stop_number += 1;
        self.waypoints_passed += 1;
        print(f"Stop {self.stop_number}: waypoint {self.waypoints_passed}");
        visit [-->];
    }

    can finish with Summit entry {
        self.stop_number += 1;
        print(f"Stop {self.stop_number}: summit");
        visit [-->] else {
            print(
                f"Trail complete — passed {self.waypoints_passed} of "
                f"{self.target_waypoints} waypoints in {self.stop_number} stops."
            );
            disengage;
        };
    }
}

