"""Flight network: priced legs as edges, scout reports peak fare, legs show cost fraction."""

node Airport {
    has code: str = "";
}

edge FlightLeg {
    has price: float = 0.0;
    has label: str = "";

    def fare_fraction(peak: float) -> float {
        if peak <= 0.0 {
            return 0.0;
        }
        return self.price / peak;
    }
}

walker FareScout {
    has peak_fare: float = 0.0;
    has collected: list[float] = [];
    has seen: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can hub with Airport entry {
        if here.code in self.seen {
            disengage;
        }
        self.seen.append(here.code);
        visit [->:FlightLeg:->] else {
            visit [-->];
        }
    }

    can gather with FlightLeg entry {
        self.collected.append(here.price);
        new_peak = here.price if here.price > self.peak_fare else self.peak_fare;
        self.peak_fare = new_peak;
        visit [-->];
    }

    can wrap with Root exit {
        report self.peak_fare;
    }
}

with entry {
    lax = Airport(code="LAX");
    jfk = Airport(code="JFK");
    ord_hub = Airport(code="ORD");
    sfo = Airport(code="SFO");
