    has name: str = "";
    has year: int = 0;
    has available: bool = True;
}

edge Road {
    has length_km: float = 0.0;
}

walker Courier {
    has total_cost: float = 0.0;
    has toll_per_km: float = 0.25;

    can start with Root entry {
        visit [-->];
    }

    can arrive with City entry {
        visit [->:Road:->] else { disengage; }
    }

    can drive with Road entry {
        segment_toll = here.length_km * self.toll_per_km;
        self.total_cost += segment_toll;
        print(f"Road {here.length_km} km @ ${self.toll_per_km}/km -> ${segment_toll:.2f}");
        visit [-->];
    }
}

