"""Flight network: priced legs as typed edges with fare normalization."""

node Airport {
    has code: str = "";
}

edge FlightLeg {
    has price: float = 0.0;

    def fraction_of_top(top_fare: float) -> float {
        if top_fare <= 0.0 {
            return 0.0;
        }
        return self.price / top_fare;
    }
}

walker Scout {
    has fares: list[float] = [];
    has top_fare: float = 0.0;
    has visited: dict[str, bool] = {};

    can start with Root entry {
        visit [-->];
    }

    can survey with Airport entry {
        if here.code in self.visited {
            disengage;
        }
        self.visited[here.code] = True;
        for leg in [edge here ->:FlightLeg:->] {
            self.fares.append(leg.price);
            if leg.price > self.top_fare {
                self.top_fare = leg.price;
            }
        }
        visit [->:FlightLeg:->] else { disengage; };
    }

    can finish with Root exit {
        report self.fares;
        report self.top_fare;
    }
}

