    has code: str = "";
}

edge FlightLeg {
    has price: float = 0.0;
    has dest_code: str = "";

    def fraction_of_top(top_fare: float) -> float {
        if top_fare <= 0.0 {
            return 0.0;
        }
        return self.price / top_fare;
    }
}

walker Scout {
    has prices: list[float] = [];
    has max_fare: float = 0.0;
    has seen: dict[str, bool] = {};

    can start with Root entry {
        visit [-->];
    }

    can survey with Airport entry {
        if here.code in self.seen {
            disengage;
        }
        self.seen[here.code] = True;
        for leg in [edge here ->:FlightLeg:->] {
            self.prices.append(leg.price);
        }
        visit [here->:FlightLeg:->] else { disengage; };
    }

    def report() -> float {
        top = 0.0;
        for p in self.prices {
            if p > top {
                top = p;
            }
        }
        self.max_fare = top;
        return self.max_fare;
    }
}

