    has student_name: str = "";
    has score: int = 0;
}

walker Grader {
    has collected: list[int] = [];

    can start with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can grade with Quiz entry {
        self.collected.append(here.score);
        visit [-->];
    }

    can disengage {
        total = 0;
        for s in self.collected {
            total += s;
        }
        class_avg = 0;
        if self.collected {
            class_avg = total // len(self.collected);
        }
        report class_avg;
    }
}

with entry {
    root ++> Quiz(student_name="Alice", score=92)
        ++> Quiz(student_name="Bob", score=85)
        ++> Quiz(student_name="Carol", score=78)
        ++> Quiz(student_name="Diego", score=88);
    grader = Grader();
    class_average = root spawn grader;
    print(f"Collected scores: {grader.collected}");
    print(f"Class average: {class_average}");
}

"""Weather sweep: model stations as nodes and walk the network to collect readings."""

node WeatherStation {
    has location: str = "";
    has celsius: float = 0.0;
}

walker WeatherSweep {
    has readings: list[str] = [];
    has temps: list[float] = [];

    can start with Root entry {
        visit [-->];
    }

    can log_reading with WeatherStation entry {
        print(f"{here.location}: {here.celsius}C");
        self.readings.append(f"{here.location}={here.celsius}C");
        self.temps.append(here.celsius);
        visit [-->] else { disengage; }
    }

    report {
        print(f"All readings: {self.readings}");
        lo = min(self.temps);
        hi = max(self.temps);
        print(f"Min: {lo}C, Max: {hi}C");
    }
}

with entry {
    root ++> WeatherStation(location="Downtown", celsius=22.5)
        ++> WeatherStation(location="Harbor", celsius=18.0)
        ++> WeatherStation(location="Hills", celsius=31.2)
        ++> WeatherStation(location="Airport", celsius=15.8);
    root spawn WeatherSweep();
}

"""Weather sweep: visit weather stations, report temperatures, and summarize min and max."""

node WeatherStation {
    has location: str = "";
    has celsius: float = 0.0;
}

walker WeatherSweeper {
    has locations: list[str] = [];
    has temps: list[float] = [];

    def print_summary() {
        print("Full readings:");
        for (loc, temp) in zip(self.locations, self.temps) {
            print(f"  {loc}: {temp} C");
        }
        if len(self.temps) == 0 {
            print("Min: N/A, Max: N/A");
            return;
        }
        min_temp = self.temps[0];
        max_temp = self.temps[0];
        for t in self.temps {
            if t < min_temp { min_temp = t; }
            if t > max_temp { max_temp = t; }
        }
        print(f"Min: {min_temp} C, Max: {max_temp} C");
    }

    can start with Root entry {
        visit [-->]; else {
            self.print_summary();
            disengage;
        }
    }

    can sweep with WeatherStation entry {
        print(f"{here.location}: {here.celsius} C");
        self.locations.append(here.location);
        self.temps.append(here.celsius);
        visit [-->]; else {
            self.print_summary();
            disengage;
        }
    }
}

with entry {
    root ++> WeatherStation(location="Boston", celsius=18.5)
        ++> WeatherStation(location="Miami", celsius=29.3)
        ++> WeatherStation(location="Denver", celsius=12.1);
    root spawn WeatherSweeper();
}

