"""Order auditor: skip invalid orders while continuing the walk, halt immediately on fraud."""

node Order {
    has amount: float = 0.0;
    has valid: bool = True;
    has fraud_flag: bool = False;
}

walker OrderAuditor {
    can start with Root entry {
        print("Order audit starting");
        visit [-->] else { disengage; }
    }

    can audit with Order entry {
        if here.fraud_flag {
            print(f"HALT fraud flagged order amount={here.amount}");
            disengage;
        } else if not here.valid {
            print(f"SKIP invalid order amount={here.amount}");
            visit [-->] else { disengage; }
        } else {
            print(f"AUDIT valid order amount={here.amount}");
            visit [-->] else { disengage; }
        }
    }
}

