    root ++> Order(amount=100.0, valid=True, fraud_flag=False)
        ++> Order(amount=50.0, valid=False, fraud_flag=False)
        ++> Order(amount=200.0, valid=True, fraud_flag=False)
        ++> Order(amount=999.0, valid=True, fraud_flag=True)
        ++> Order(amount=75.0, valid=True, fraud_flag=False);
    root spawn OrderAuditor();
}

