        ++> StockItem(sku="BOLT-7", quantity=8)
        ++> StockItem(sku="GASKET-3", quantity=15);

    result = root spawn Counter();

    total_units = 0;
    smallest_count = 0;
    first = True;
    for item in result.reports {
        print(f"{item.sku}: {item.quantity} units on shelf");
        total_units += item.quantity;
        if first {
            smallest_count = item.quantity;
            first = False;
        } else if item.quantity < smallest_count {
            smallest_count = item.quantity;
        }
    }
    print(f"Total units in warehouse: {total_units}");
    print(f"Smallest shelf count: {smallest_count}");
}

