"""Warehouse stock take: model stock items as nodes and count shelf quantities with a counter walker."""

node StockItem {
    has sku: str = "";
    has quantity: int = 0;
}

walker Counter {
    can start with Root entry {
        visit [-->];
    }

    can count with StockItem entry {
        print(f"[SWEEP] {here.sku}: {here.quantity} on shelf");
        report [here.sku, here.quantity];
        visit [-->];
    }
}

with entry {
    root ++> StockItem(sku="WDG-001", quantity=42)
        ++> StockItem(sku="WDG-002", quantity=7)
        ++> StockItem(sku="WDG-003", quantity=19);

    result = root spawn Counter();

    total_units = 0;
    smallest = 0;
    seen = False;

    for (sku, qty) in result.reports {
        print(f"{sku}: {qty}");
        total_units += qty;
        if not seen {
            smallest = qty;
            seen = True;
        } else {
            if qty < smallest {
                smallest = qty;
            }
        }
    }

    print(f"Total units in warehouse: {total_units}");
    print(f"Smallest shelf count: {smallest}");
}

