"""Alumni mentorship network: typed Mentor edges and a year-filtered finder walker."""

node Alumni {
    has name: str = "";
    has grad_year: int = 0;
}

edge Mentor: Alumni --> Alumni {
    has year: int = 0;
}

walker MentorFinder {
    has since_year: int = 2020;
    has listed: dict[str, bool] = {};

    can start with Root entry {
        print(f"Mentees with mentorship starting in {self.since_year} or later:");
        visit [-->[?:Alumni]] else { disengage; };
    }

    can scan with Alumni entry {
        for link in [edge here ->:Mentor:->] {
            if link.year >= self.since_year {
                for mentee in [link -->][?:Alumni] {
                    if mentee.name not in self.listed {
                        self.listed[mentee.name] = True;
                        print(
                            f"  {mentee.name} (class of {mentee.grad_year}, "
                            f"since {link.year})"
                        );
                    }
                }
            }
        }
        visit [-->[?:Alumni]] else { disengage; };
    }
}

