"""Hiking trail: chain waypoints from trailhead to summit and count each stop."""

node Trailhead {
    has name: str = "Trailhead";
}

node Waypoint {
    has label: str = "";
}

node Summit {
    has name: str = "Summit";
}

walker Hiker {
    has stop_count: int = 0;
    has total_waypoints: int = 0;

    can start with Root entry {
        print("Setting out on the trail");
        visit [-->];
    }

    can hike with Trailhead entry {
        print(f"Departing from {here.name}");
        visit [-->];
    }

    can hike with Waypoint entry {
        self.stop_count += 1;
        print(f"Stop {self.stop_count}");
        visit [-->];
    }

    can arrive with Summit entry {
        if self.stop_count >= self.total_waypoints {
            print(
                f"Trail complete: passed {self.stop_count} waypoints to {here.name}."
            );
        } else {
            print(
                f"Reached {here.name} after only {self.stop_count} "
                f"of {self.total_waypoints} waypoints."
            );
        }
        disengage;
    }
}

with entry {
    head = Trailhead();
  summit = Summit();
    root ++> head
        ++> Waypoint()
        ++> Waypoint()
        ++> Waypoint()
        ++> summit;
    root spawn Hiker(total_waypoints=3);
}

