"""Flight network: priced legs as edges, scout fare report, and per-leg top-fare fractions."""

node Airport {
    has code: str = "";
}

edge FlightLeg {
    has price: float = 0.0;

    def fare_fraction(max_fare: float) -> float {
        if max_fare <= 0.0 {
            return 0.0;
        }
        return self.price / max_fare;
    }
}

walker Scout {
    has fare_report: list[float] = [];
    has max_fare: float = 0.0;

    can start with Root entry {
        visit [-->] else { disengage; };
    }

    can hub with Airport entry {
        visit [->:FlightLeg:->] else { disengage; };
    }

    can leg with FlightLeg entry {
        self.fare_report.append(here.price);
        if here.price > self.max_fare {
            self.max_fare = here.price;
        }
        visit [-->] else { disengage; };
    }
}

with entry {
    nyc = Airport(code="NYC");
    chi = Airport(code="CHI");
    lax = Airport(code="LAX");
    den = Airport(code="DEN");

    root ++> nyc;
    leg_nyc_chi = nyc +>:FlightLeg(price=450.0):+> chi;
    leg_chi_lax = chi +>:FlightLeg(price=320.0):+> lax;
    leg_lax_den = lax +>:FlightLeg(price=275.0):+> den;

    scout = Scout();
    root spawn scout;

    print(f"Scout fare report: {scout.fare_report} (top fare: {scout.max_fare})");

    for leg in [leg_nyc_chi, leg_chi_lax, leg_lax_den] {
        frac = leg.fare_fraction(scout.max_fare);
        print(f"${leg.price} costs {frac:.2f} of the top fare (${scout.max_fare})");
    }
}

"""Flight network: Leg edges store ticket prices; FareScout reports every fare and each leg normalizes against the network maximum."""

node Airport {
    has code: str = "";
}

edge Leg {
    has price: int = 0;

    def fraction_of_top(max_fare: int) -> float {
        if max_fare <= 0 {
            return 0.0;
        }
        return float(self.price) / float(max_fare);
    }
}

walker FareScout {
    has prices: list[int] = [];
    has max_fare: int = 0;

    can start with Root entry {
        visit [-->[?:Airport]] else { disengage; };
    }

    can gather with Airport entry {
        for dest in here[->:Leg:->] {
            leg = here -->:Leg:--> dest;
            self.prices.append(leg.price);
            report leg.price;
            if leg.price > self.max_fare {
                self.max_fare = leg.price;
            }
        }
        visit [->:Leg:->];
    }
}

with entry {
    nyc = Airport(code="NYC");
    ord = Airport(code="ORD");
    lax = Airport(code="LAX");
    den = Airport(code="DEN");

    root ++> nyc;
    nyc +>:Leg(price=580):+> ord;
    ord +>:Leg(price=320):+> lax;
    nyc +>:Leg(price=450):+> den;
    den +>:Leg(price=275):+> lax;

    scout = root spawn FareScout();

    print(f"Scout reports: {scout.prices} (top fare: ${scout.max_fare})");

    for hub in [nyc, ord, den] {
        for dest in hub[->:Leg:->] {
            leg = hub -->:Leg:--> dest;
            frac = leg.fraction_of_top(scout.max_fare);
            print(f"{hub.code}->{dest.code}: ${leg.price} is {frac} of top fare (${scout.max_fare})");
        }
    }
}

