"""Flight network: priced legs as edges, scout reports all fares, each leg normalizes against the network peak."""

node Airport {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

edge FlightLeg {
    has price: float = 0.0;

    def fare_fraction(top_fare: float) -> float {
        if top_fare <= 0.0 {
            return 0.0;
        }
        return self.price / top_fare;
    }
}

walker Scout {
    has reports: list[float] = [];
    has max_fare: float = 0.0;
    has visited: list[object] = [];
    has seen_legs: list[object] = [];

    can start with Root entry {
        visit [-->] else { disengage; };
    }

    can scan with Airport entry {
        if here in self.visited {
            disengage;
        }
        self.visited.append(here);
        visit [->:FlightLeg:->] else { disengage; };
    }

    can tally with FlightLeg entry {
        if edge in self.seen_legs {
            return;
        }
        self.seen_legs.append(edge);
        self.reports.append(edge.price);
        if edge.price > self.max_fare {
            self.max_fare = edge.price;
        }
    }
}

