edge FlightLeg {
    has price: float = 0.0;

    def fare_fraction(max_fare: float) -> float {
        if max_fare <= 0.0 {
            return 0.0;
        }
        return self.price / max_fare;
    }

    can log_fare with Scout entry {
        visitor.prices.append(self.price);
        visitor.legs.append(self);
        if self.price > visitor.max_fare {
            visitor.max_fare = self.price;
        }
    }
