        if here.code in self.visited_codes {
            disengage;
        }
        self.visited_codes.append(here.code);
        visit [->:FlightLeg:->] else { disengage; };
    }

    can depart with Root exit {
        report {"prices": self.prices, "max_fare": self.max_fare};
    }
}

