    deep_root = WorkflowRoot(label="wf-deep");
    cycle_root = WorkflowRoot(label="wf-cycle");

    root ++> stale_root ++> live_root ++> deep_root ++> cycle_root;

    stale_root +>:DescendantOf:+> Issue(title="closed-a", live=False);
    stale_root +>:DescendantOf:+> Wisp(name="dead-wisp", live=False);

    live_root +>:DescendantOf:+> Issue(title="closed-b", live=False);
    live_root +>:DescendantOf:+> Wisp(name="active-wisp", live=True);

    d1 = Issue(title="d1", live=False);
    d2 = Issue(title="d2", live=False);
    d3 = Issue(title="d3", live=False);
    d4 = Issue(title="d4", live=False);
    d5 = Issue(title="d5", live=False);
    deep_root +>:DescendantOf:+> d1;
    d1 +>:DescendantOf:+> d2;
    d2 +>:DescendantOf:+> d3;
    d3 +>:DescendantOf:+> d4;
    d4 +>:DescendantOf:+> d5;

