    cyc_b +>:DependsOn:+> cyc_a;

    print(">>> Cycle 1: fail-open count wrapper (the bug)");
    root spawn StaleRootReaper(depth_cap=3, fail_open=True);

    print("");
    print(">>> Cycle 2: fail-closed count wrapper (recommended fix)");
    root spawn StaleRootReaper(depth_cap=3, fail_open=False);
}

"""Zu M4 query kernels: recursive BFS frontier, ANY SHORTEST TRAIL paths, and triangle counting."""

node GraphVertex {
    has label: str = "";
}

edge Knows {
    has since: int = 0;
}

walker RecursiveBFS {
    has hop_limit: int = 2;
    has current_hop: int = 0;
    has visited_labels: list[str] = [];
    has banner: bool = False;

    can expand with GraphVertex entry {
        if not self.banner {
            self.banner = True;
            print("=== Recursive BFS (frontier expansion with cycle guard) ===");
        }
        if here.label in self.visited_labels {
            disengage;
        }
        self.visited_labels.append(here.label);
        print(f"  hop {self.current_hop}: {here.label}");
        if self.current_hop < self.hop_limit {
            saved_hop = self.current_hop;
            self.current_hop += 1;
            visit [->:Knows:->];
            self.current_hop = saved_hop;
        }
    }
}

walker ShortestTrail {
    has target: str = "";
    has depth: int = 0;
    has found: bool = False;
    has best_depth: int = 999;
    has visited: list[str] = [];
    has path: list[str] = [];
    has banner: bool = False;

    can seek with GraphVertex entry {
        if not self.banner {
            self.banner = True;
            print(f"=== ANY SHORTEST TRAIL to {self.target} ===");
        }
        if self.found and self.depth >= self.best_depth {
            disengage;
        }
        if here.label in self.visited {
            disengage;
        }
        self.visited.append(here.label);
        self.path.append(here.label);
        if here.label == self.target {
            self.found = True;
            self.best_depth = self.depth;
            trail = " -> ".join(self.path);
            print(f"TRAIL path ({self.best_depth} hops): {trail}");
            disengage;
        }
        next_depth = self.depth + 1;
        self.depth = next_depth;
        visit [->:Knows:->];
        self.depth = next_depth - 1;
        self.path.pop();
        self.visited.pop();
    }
}

walker TriangleCounter {
    has total: int = 0;
    has pivot_label: str = "";
    has mid_label: str = "";
    has tail_label: str = "";
    has banner: bool = False;

    can start with Root entry {
        if not self.banner {
            self.banner = True;
            print("=== Triangle counting (degree-ordered orientation) ===");
        }
        visit [-->];
    }

    can pivot with GraphVertex entry {
        self.pivot_label = here.label;
        visit [->:Knows:->];
    }

    can mid with GraphVertex entry {
        if here.label <= self.pivot_label {
            disengage;
        }
        self.mid_label = here.label;
        visit [->:Knows:->];
    }

    can tail with GraphVertex entry {
        if here.label <= self.mid_label {
            disengage;
        }
        self.tail_label = here.label;
        visit [->:Knows:->];
    }

    can close with GraphVertex entry {
        if here.label == self.pivot_label {
            self.total += 1;
            print(f"  triangle: {self.pivot_label}-{self.mid_label}-{self.tail_label}");
        }
        disengage;
    }

    can finish with Root exit {
        print(f"Triangle count: {self.total}");
    }
}

with entry {
    a = GraphVertex(label="A");
    b = GraphVertex(label="B");
    c = GraphVertex(label="C");
    d = GraphVertex(label="D");

    root ++> a;
    a +>:Knows(since=2020):+> b;
    b +>:Knows:+> c;
    c +>:Knows:+> a;
    b +>:Knows:+> d;

    a spawn RecursiveBFS(hop_limit=2);
    a spawn ShortestTrail(target="D");
    root spawn TriangleCounter();
}

"""A-08.02 graph templates: grid BFS reachability, DAG topo sort, DFS cycle detection, and peer flood-fill components."""

node Cell {
    has row: int = 0;
    has col: int = 0;
}

node Lesson {
    has code: str = "";
    has group_id: int = -1;
}

node CycleTopic {
    has code: str = "";
}

edge Adjacent { }
edge Prereq { }
edge Peer { }
edge CyclicNext { }

walker GridBfs {
    has seen: list[str] = [];
    has steps: int = 0;
    has goal_row: int = 2;
    has goal_col: int = 2;
    has reached_goal: bool = False;

    def key(c: Cell) -> str {
        return f"{c.row},{c.col}";
    }

    can start with Root entry {
        visit [-->[?:Cell]] else { disengage; }
    }

    can expand with Cell entry {
        k = self.key(here);
        if k in self.seen {
            visit [->:Adjacent:->];
            disengage;
        }
        self.seen.append(k);
        self.steps += 1;
        if here.row == self.goal_row and here.col == self.goal_col {
            self.reached_goal = True;
        }
        print(f"BFS visit {k} step {self.steps}");
        visit [->:Adjacent:->];
    }
}

walker TopoPlanner {
    has order: list[str] = [];
    has visiting: list[str] = [];
    has done: list[str] = [];
    has cycle_found: bool = False;

    can start with Root entry {
        visit [-->[?:Lesson]] else { disengage; }
    }

    can descend with Lesson entry {
        if here.code in self.done {
            disengage;
        }
        if here.code in self.visiting {
            self.cycle_found = True;
            disengage;
        }
        self.visiting.append(here.code);
        visit [->:Prereq:->] else { }
    }

    can ascend with Lesson exit {
        if here.code in self.done {
            disengage;
        }
        self.done.append(here.code);
        self.order.append(here.code);
        remaining = [];
        for (c) in self.visiting {
            if c != here.code {
                remaining.append(c);
            }
        }
        self.visiting = remaining;
    }
}

walker CycleDetector {
    has visiting: list[str] = [];
    has done: list[str] = [];
    has has_cycle: bool = False;

    can start with Root entry {
        visit [-->[?:CycleTopic]] else { disengage; }
    }

    can probe with CycleTopic entry {
        if here.code in self.done {
            disengage;
        }
        if here.code in self.visiting {
            self.has_cycle = True;
            disengage;
        }
        self.visiting.append(here.code);
        visit [->:CyclicNext:->] else { }
    }

    can unwind with CycleTopic exit {
        if here.code in self.done {
            disengage;
        }
        self.done.append(here.code);
        remaining = [];
        for (c) in self.visiting {
            if c != here.code {
                remaining.append(c);
            }
        }
        self.visiting = remaining;
    }
}

walker ComponentFlood {
    has next_label: int = 0;
    has active_label: int = 0;

    can start with Root entry {
        visit [-->[?:Lesson]] else { disengage; }
    }

    can claim with Lesson entry {
        if here.group_id >= 0 {
            visit [->:Peer:->];
            disengage;
        }
        here.group_id = self.active_label;
        visit [->:Peer:->];
    }

    can close with Lesson exit {
        if here.group_id == self.active_label {
            self.next_label += 1;
            self.active_label = self.next_label;
        }
    }
}

