            self.summarize();
            disengage;
        }
    }

    can walk with Issue | Wisp entry {
        expand = False;
        if not self.query_failed {
            key = f"{here}";
            if key not in self.visited_keys {
                self.visited_keys += [key];
                self.walk_depth += 1;
                if self.walk_depth > self.depth_cap {
                    self.query_failed = True;
                    print(
                        f"  Error 1105: row read wait exceeded at depth "
                        f"{self.walk_depth}"
                    );
                } else {
                    expand = True;
                    if here.live {
                        self.live_found = True;
                    }
                }
            }
        }
        if expand {
            visit [->:DescendantOf:->];
            visit [->:DependsOn:->];
        }
        visit [-->] else { disengage; }
    }
}

