"""Zu M4 query kernels: recursive BFS frontier, ANY SHORTEST TRAIL paths, and triangle counting."""

node GraphVertex {
    has label: str = "";
}

edge Knows {
    has since: int = 0;
}

walker RecursiveBFS {
    has hop_limit: int = 2;
    has current_hop: int = 0;
    has visited_labels: list[str] = [];
    has banner: bool = False;

    can expand with GraphVertex entry {
        if not self.banner {
            self.banner = True;
            print("=== Recursive BFS (frontier expansion with cycle guard) ===");
        }
        if here.label in self.visited_labels {
            disengage;
        }
        self.visited_labels.append(here.label);
        print(f"  hop {self.current_hop}: {here.label}");
        if self.current_hop < self.hop_limit {
            next_hop = self.current_hop + 1;
            self.current_hop = next_hop;
            visit [->:Knows:->];
            self.current_hop = next_hop - 1;
        }
    }
}

walker ShortestTrail {
    has target: str = "";
    has depth: int = 0;
    has found: bool = False;
    has best_depth: int = 999;
    has visited: list[str] = [];
    has path: list[str] = [];
    has banner: bool = False;

    can seek with GraphVertex entry {
        if not self.banner {
            self.banner = True;
            print(f"=== ANY SHORTEST TRAIL to {self.target} ===");
        }
        if self.found and self.depth >= self.best_depth {
            disengage;
        }
        if here.label in self.visited {
            disengage;
        }
        self.visited.append(here.label);
        self.path.append(here.label);
        if here.label == self.target {
            self.found = True;
            self.best_depth = self.depth;
            trail = " -> ".join(self.path);
            print(f"TRAIL path ({self.best_depth} hops): {trail}");
            disengage;
        }
        next_depth = self.depth + 1;
        self.depth = next_depth;
        visit [->:Knows:->] else { disengage; }
        self.depth = next_depth - 1;
        self.path.pop();
        self.visited.pop();
    }
}

walker TriangleCounter {
    has total: int = 0;
    has pivot_label: str = "";
    has mid_label: str = "";
    has walk_depth: int = 0;
    has banner: bool = False;

    can start with Root entry {
        if not self.banner {
            self.banner = True;
            print("=== Triangle counting (degree-ordered orientation) ===");
        }
        visit [-->];
    }

    can pivot with GraphVertex entry {
        if self.walk_depth != 0 {
            disengage;
        }
        self.pivot_label = here.label;
        self.walk_depth = 1;
        visit [->:Knows:->] else { disengage; }
        self.walk_depth = 0;
        visit [-->];
    }

    can mid with GraphVertex entry {
        if self.walk_depth != 1 {
            disengage;
        }
        if here.label <= self.pivot_label {
            disengage;
        }
        self.mid_label = here.label;
        self.walk_depth = 2;
        visit [->:Knows:->] else { disengage; }
        self.walk_depth = 1;
    }

    can tail with GraphVertex entry {
        if self.walk_depth != 2 {
            disengage;
        }
        if here.label <= self.mid_label {
            disengage;
        }
        tail_label = here.label;
        self.walk_depth = 3;
        visit [->:Knows:->] else { disengage; }
        self.walk_depth = 2;
        if tail_label == self.pivot_label {
            self.total += 1;
            print(f"  triangle: {self.pivot_label}-{self.mid_label}-{tail_label}");
        }
    }

    can finish with Root exit {
        print(f"Triangle count: {self.total}");
    }
}

with entry {
    a = GraphVertex(label="A");
    b = GraphVertex(label="B");
    c = GraphVertex(label="C");
    d = GraphVertex(label="D");

    root ++> a;
    a +>:Knows(since=2020):+> b;
    b +>:Knows:+> c;
    c +>:Knows:+> a;
    b +>:Knows:+> d;

    a spawn RecursiveBFS(hop_limit=2);
    a spawn ShortestTrail(target="D");
    root spawn TriangleCounter();
}

"""Reaper stale workflow-root scan: bounded descendant walk with fail-open vs fail-closed counting."""

node WorkflowEntity {
    has live: bool = True;
}

node WorkflowRoot {
    has label: str = "";
}

node Issue(WorkflowEntity) {
    has title: str = "";
}

node Wisp(WorkflowEntity) {
    has name: str = "";
}

edge DescendantOf { }

edge DependsOn { }

walker StaleRootReaper {
    has depth_cap: int = 3;
    has fail_open: bool = True;
    has stale_count: int = 0;
    has query_failed: bool = False;
    has live_found: bool = False;
    has walk_depth: int = 0;
    has visited_keys: list[str] = [];

    def get_sql_count() -> int {
        if self.query_failed {
            if self.fail_open {
                return 0;
            }
            return -1;
        }
        return self.stale_count;
    }

    def summarize() {
        count = self.get_sql_count();
        mode = "fail-open" if self.fail_open else "fail-closed";
        print(f"--- {mode} decision path ---");
        print(f"get_sql_count() => {count}");
        if self.query_failed and self.fail_open {
            print("ANOMALY: walk failure coerced to 0 — reaper reads 'nothing to reap'");
        }
        if self.query_failed and not self.fail_open {
            print("fail-closed: count unknown — do not conclude empty");
        }
        if not self.query_failed and count > 0 {
            print(f"action: reap {count} stale workflow root(s)");
        }
        if not self.query_failed and count == 0 {
            print("action: nothing stale to reap");
        }
    }

    can start with Root entry {
        print(
            f"Reap cycle begin (depth_cap={self.depth_cap}, "
            f"fail_open={self.fail_open})"
        );
        visit [-->[?:WorkflowRoot]] else {
            self.summarize();
            disengage;
        }
    }

    can screen with WorkflowRoot entry {
        self.live_found = False;
        self.walk_depth = 0;
        self.visited_keys = [];
        print(f"scanning workflow root: {here.label}");
        visit [->:DescendantOf:->];
        visit [->:DependsOn:->];
        if not self.query_failed and not self.live_found {
            self.stale_count += 1;
            print(f"  => stale candidate (no live descendants)");
        }
        if not self.query_failed and self.live_found {
            print(f"  => has live descendants, skip");
        }
        if self.query_failed {
            print(f"  => descendant walk FAILED (timeout / unbounded)");
        }
        visit [-->[?:WorkflowRoot]] else {
            self.summarize();
            disengage;
        }
    }

    can walk with Issue | Wisp entry {
        key = f"{here}";
        if self.query_failed {
            visit [-->] else { disengage; };
        } elif key in self.visited_keys {
            visit [-->] else { disengage; };
        } else {
            self.visited_keys += [key];
            self.walk_depth += 1;
            if self.walk_depth > self.depth_cap {
                self.query_failed = True;
                print(
                    f"  Error 1105: row read wait exceeded at depth "
                    f"{self.walk_depth}"
                );
                visit [-->] else { disengage; };
            } else {
                if here.live {
                    self.live_found = True;
                }
                visit [->:DescendantOf:->];
                visit [->:DependsOn:->];
                visit [-->] else { disengage; };
            }
        }
    }
}

