"""A-08.02 graph templates: grid BFS reachability, DAG topo sort, DFS cycle detection, and peer flood-fill components."""

node Cell {
    has row: int = 0;
    has col: int = 0;
}

node Lesson {
    has code: str = "";
    has group_id: int = -1;

    def tag_component(label: int) {
        self.group_id = label;
    }
}

node CycleTopic {
    has code: str = "";
}

edge Adjacent { }
edge Prereq { }
edge Peer { }
edge CyclicNext { }

walker GridBfs {
    has seen: list[str] = [];
    has steps: int = 0;
    has goal_row: int = 2;
    has goal_col: int = 2;
    has reached_goal: bool = False;

    can start with Root entry {
        visit [-->] else { disengage; }
    }

    can expand with Cell entry {
        k = f"{here.row},{here.col}";
        if k in self.seen {
            disengage;
        }
        self.seen.append(k);
        next_step = self.steps + 1;
        self.steps = next_step;
        if here.row == self.goal_row and here.col == self.goal_col {
            self.reached_goal = True;
        }
        print(f"BFS visit {k} step {self.steps}");
        visit [->:Adjacent:->] else { disengage; }
    }
}

walker TopoPlanner {
    has order: list[str] = [];
    has visiting: list[str] = [];
    has done: list[str] = [];
    has cycle_found: bool = False;

    can start with Root entry {
        visit [-->] else { disengage; }
    }

    can descend with Lesson entry {
        if here.code in self.done {
            disengage;
        }
        if here.code in self.visiting {
            self.cycle_found = True;
            disengage;
        }
        self.visiting.append(here.code);
        visit [->:Prereq:->] else { disengage; }
    }

    can ascend with Lesson exit {
        if here.code in self.done {
            disengage;
        }
        self.done.append(here.code);
        self.order.append(here.code);
        if len(self.visiting) > 0 {
            self.visiting.pop();
        }
    }
}

walker CycleDetector {
    has visiting: list[str] = [];
    has done: list[str] = [];
    has has_cycle: bool = False;

    can start with Root entry {
        visit [-->] else { disengage; }
    }

    can probe with CycleTopic entry {
        if here.code in self.done {
            disengage;
        }
        if here.code in self.visiting {
            self.has_cycle = True;
            disengage;
        }
        self.visiting.append(here.code);
        visit [->:CyclicNext:->] else { disengage; }
    }

    can unwind with CycleTopic exit {
        if here.code in self.done {
            disengage;
        }
        self.done.append(here.code);
        if len(self.visiting) > 0 {
            self.visiting.pop();
        }
    }
}

walker ComponentFlood {
    has next_label: int = 0;
    has paint: int = -1;

    can start with Root entry {
        visit [-->] else { disengage; }
    }

    can claim with Lesson entry {
        if here.group_id >= 0 {
            disengage;
        }
        if self.paint < 0 {
            self.paint = self.next_label;
            bumped = self.next_label + 1;
            self.next_label = bumped;
        }
        here.tag_component(self.paint);
        visit [->:Peer:->] else { disengage; }
    }

    can release with Lesson exit {
        self.paint = -1;
    }
}

