"""Zu M4 query kernels: recursive BFS frontier, ANY SHORTEST TRAIL paths, and triangle counting."""

node GraphVertex {
    has label: str = "";
}

edge Knows {
    has since: int = 0;
}

walker RecursiveBFS {
    has hop_limit: int = 2;
    has start_label: str = "A";
    has current_hop: int = 0;
    has visited_labels: list[str] = [];
    has bfs_engaged: bool = False;
    has banner: bool = False;

    can start with Root entry {
        if not self.banner {
            self.banner = True;
            print("=== Recursive BFS (frontier expansion with cycle guard) ===");
        }
        visit [-->];
    }

    can expand with GraphVertex entry {
        if not self.bfs_engaged {
            if here.label != self.start_label {
                visit [-->] else { disengage; };
            }
            self.bfs_engaged = True;
        }
        if here.label in self.visited_labels {
            visit [-->] else { disengage; };
        }
        self.visited_labels.append(here.label);
        print(f"  hop {self.current_hop}: {here.label}");
        if self.current_hop < self.hop_limit {
            next_hop = self.current_hop + 1;
            self.current_hop = next_hop;
            visit [->:Knows:->] else { disengage; };
            self.current_hop = next_hop - 1;
            visit [-->] else { disengage; };
        } else {
            visit [-->] else { disengage; };
        }
    }
}

walker ShortestTrail {
    has target: str = "";
    has start_label: str = "A";
    has depth: int = 0;
    has found: bool = False;
    has best_depth: int = 999;
    has visited: list[str] = [];
    has path: list[str] = [];
    has trail_engaged: bool = False;
    has banner: bool = False;

    can start with Root entry {
        if not self.banner {
            self.banner = True;
            print(f"=== ANY SHORTEST TRAIL to {self.target} ===");
        }
        visit [-->];
    }

    can seek with GraphVertex entry {
        if not self.trail_engaged {
            if here.label != self.start_label {
                visit [-->] else { disengage; };
            }
            self.trail_engaged = True;
        }
        if self.found and self.depth >= self.best_depth {
            visit [-->] else { disengage; };
        }
        if here.label in self.visited {
            visit [-->] else { disengage; };
        }
        self.visited.append(here.label);
        self.path.append(here.label);
        if here.label == self.target {
            self.found = True;
            self.best_depth = self.depth;
            trail = " -> ".join(self.path);
            print(f"TRAIL path ({self.best_depth} hops): {trail}");
            self.path.pop();
            self.visited.pop();
            visit [-->] else { disengage; };
        }
        next_depth = self.depth + 1;
        self.depth = next_depth;
        visit [->:Knows:->] else { disengage; };
        self.depth = next_depth - 1;
        self.path.pop();
        self.visited.pop();
        visit [-->] else { disengage; };
    }
}

walker TriangleCounter {
    has total: int = 0;
    has pivot_label: str = "";
    has mid_label: str = "";
    has walk_depth: int = 0;
    has banner: bool = False;

    can start with Root entry {
        if not self.banner {
            self.banner = True;
            print("=== Triangle counting (degree-ordered orientation) ===");
        }
        visit [-->];
    }

    can pivot with GraphVertex entry {
        if self.walk_depth != 0 {
            visit [-->] else { disengage; };
        } else {
            self.pivot_label = here.label;
            self.walk_depth = 1;
            visit [->:Knows:->] else { disengage; };
            self.walk_depth = 0;
            visit [-->] else { disengage; };
        }
    }

    can mid with GraphVertex entry {
        if self.walk_depth != 1 {
            visit [-->] else { disengage; };
        } else {
            if here.label <= self.pivot_label {
                visit [-->] else { disengage; };
            } else {
                self.mid_label = here.label;
                self.walk_depth = 2;
                visit [->:Knows:->] else { disengage; };
                self.walk_depth = 1;
                visit [-->] else { disengage; };
            }
        }
    }

    can tail with GraphVertex entry {
        if self.walk_depth != 2 {
            visit [-->] else { disengage; };
        } else {
            if here.label <= self.mid_label {
                visit [-->] else { disengage; };
            } else {
                tail_label = here.label;
                self.walk_depth = 3;
                visit [->:Knows:->] else { disengage; };
                self.walk_depth = 2;
                if tail_label == self.pivot_label {
                    self.total += 1;
                    print(f"  triangle: {self.pivot_label}-{self.mid_label}-{tail_label}");
                }
                visit [-->] else { disengage; };
            }
        }
    }

    can finish with Root exit {
        print(f"Triangle count: {self.total}");
    }
}

with entry {
    a = GraphVertex(label="A");
    b = GraphVertex(label="B");
    c = GraphVertex(label="C");
    d = GraphVertex(label="D");

    root ++> a;
    a +>:Knows(since=2020):+> b;
    b +>:Knows:+> c;
    c +>:Knows:+> a;
    b +>:Knows:+> d;

    root spawn RecursiveBFS(hop_limit=2, start_label="A");
    root spawn ShortestTrail(target="D", start_label="A");
    root spawn TriangleCounter();
}

"""EIP-712 typed-data encoding: model type graphs and guard the HashStruct walk against cycles, runaway work, and malformed arrays."""

node Eip712Type {
    has name: str = "";
}

node TypeField {
    has field_name: str = "";
    has field_type: str = "";
}

edge HasField { }
edge References { }

walker SafeHasher {
    has max_depth: int = 64;
    has work_budget: int = 100000;
    has depth: int = 0;
    has work_done: int = 0;
    has path: list[str] = [];
    has status: str = "ok";
    has reason: str = "";

    def is_malformed_array(field_type: str) -> bool {
        if field_type.endswith("]") {
            return "[" not in field_type;
        }
        return False;
    }

    can start with Root entry {
        visit [-->];
    }

    can hash_struct with Eip712Type entry {
        if self.status != "ok" {
            disengage;
        }
        if here.name in self.path {
            self.status = "InvalidParams";
            self.reason = f"cyclic type graph at {here.name}";
            disengage;
        }
        self.work_done += 1;
        if self.work_done > self.work_budget {
            self.status = "InvalidParams";
            self.reason = "encoding work budget exceeded";
            disengage;
        }
        next_depth = self.depth + 1;
        self.depth = next_depth;
        if self.depth > self.max_depth {
            self.status = "InvalidParams";
            self.reason = f"encoding depth cap {self.max_depth} exceeded";
            disengage;
        }
        pushed_path = self.path + [here.name];
        self.path = pushed_path;
        visit [->:HasField:->] else {
            # zero-field struct encodes from nil — legal leaf
        };
        popped_len = len(self.path) - 1;
        trimmed_path = self.path[:popped_len];
        self.path = trimmed_path;
        prior_depth = self.depth - 1;
        self.depth = prior_depth;
    }

    can encode_field with TypeField entry {
        if self.status != "ok" {
            disengage;
        }
        if self.is_malformed_array(here.field_type) {
            self.status = "InvalidParams";
            self.reason = f"malformed array type: {here.field_type}";
            disengage;
        }
        self.work_done += 1;
        if self.work_done > self.work_budget {
            self.status = "InvalidParams";
            self.reason = "encoding work budget exceeded";
            disengage;
        }
        visit [->:References:->] else {
            disengage;
        };
    }
}

def build_self_loop() -> Eip712Type {
    loop_t = Eip712Type(name="Loop");
    self_f = TypeField(field_name="self", field_type="Loop");
    loop_t +>:HasField:+> self_f;
    self_f +>:References:+> loop_t;
    return loop_t;
}

def build_indirect_cycle() -> Eip712Type {
    type_a = Eip712Type(name="A");
    type_b = Eip712Type(name="B");
    to_b = TypeField(field_name="b", field_type="B");
    to_a = TypeField(field_name="a", field_type="A");
    type_a +>:HasField:+> to_b;
    to_b +>:References:+> type_b;
    type_b +>:HasField:+> to_a;
    to_a +>:References:+> type_a;
    return type_a;
}

def build_deep_fanout(levels: int, breadth: int) -> Eip712Type {
    types: list[Eip712Type] = [];
    for i in range(levels) {
        types += [Eip712Type(name=f"T{i}")];
    }
    for i in range(levels - 1) {
        current = types[i];
        nxt = types[i + 1];
        for j in range(breadth) {
            fld = TypeField(field_name=f"f{j}", field_type=nxt.name);
            current +>:HasField:+> fld;
            fld +>:References:+> nxt;
        }
    }
    return types[0];
}

def build_malformed_array() -> Eip712Type {
    bad = Eip712Type(name="BadArray");
    broken = TypeField(field_name="x", field_type="]");
    bad +>:HasField:+> broken;
    return bad;
}

def run_vector(label: str, primary: Eip712Type, budget: int) {
    hasher = SafeHasher(work_budget=budget);
    root ++> primary;
    root spawn hasher;
    if hasher.status == "ok" {
        print(f"[{label}] OK — work units={hasher.work_done}");
    } else {
        print(f"[{label}] {hasher.status}: {hasher.reason}");
    }
}

with entry {
    run_vector("A self-reference", build_self_loop(), 100000);
    run_vector("B indirect cycle", build_indirect_cycle(), 100000);
    run_vector("C deep fanout", build_deep_fanout(6, 4), 250);
    run_vector("D malformed array", build_malformed_array(), 100000);
}

"""Wayfinder live map: stack-safe, dependency-ordered activation of implementation slices."""

node TrackerNode {
    has issue_id: int = 0;
    has title: str = "";
}

node Milestone(TrackerNode) {
    has closed: bool = True;
}

node Slice(TrackerNode) {
    has status: str = "blocked";
}

edge DependsOn { }

edge Governs { }

walker SliceCatalog {
    can start with Root entry {
        print("=== Wayfinder inventory ===");
        visit [-->];
    }

    can record with Milestone | Slice entry {
        print(f"  #{here.issue_id} {here.title}");
        visit [-->];
    }
}

walker ResidualScanner {
    has residual_count: int = 0;

    can start with Root entry {
        print("=== Residual scope scan ===");
        visit [-->];
    }

    can tally with Slice entry {
        if here.status == "ready" or here.status == "blocked" {
            self.residual_count += 1;
            tag = "next-gate" if here.status == "ready" else "deferred";
            print(f"  [{tag}] #{here.issue_id} {here.title}");
        }
        visit [-->];
    }
}

walker Wayfinder {
    has max_depth: int = 256;
    has depth: int = 0;
    has visited_ids: list[int] = [];
    has landing_order: list[int] = [];
    has fault: str = "";
    has phase: str = "root";

    can admit with Slice entry {
        if self.phase == "root" {
            if here.status != "ready" {
                disengage;
            }
            print(f"=== Admission probe: #{here.issue_id} {here.title} ===");
            self.phase = "prereq";
            self.depth = 0;
            self.visited_ids = [];
            self.fault = "";
            visit [->:DependsOn:->] else {
                disengage;
            };
            if self.fault == "" {
                self.landing_order.append(here.issue_id);
                print(
                    f"PASS: #{here.issue_id} stack-safe — cleared for landing"
                );
            } else {
                reason = "cyclic dependency graph";
                if self.fault == "depth" {
                    reason = "logical-depth policy exceeded";
                }
                if self.fault == "blocked" {
                    reason = "unmerged prerequisite remains";
                }
                print(f"FAIL: #{here.issue_id} rejected ({reason})");
            }
            disengage;
        } else {
            if self.fault != "" {
                disengage;
            }
            if here.issue_id in self.visited_ids {
                self.fault = "cycle";
                print(f"  CYCLE re-entry at #{here.issue_id}");
                disengage;
            }
            next_depth = self.depth + 1;
            if next_depth > self.max_depth {
                self.fault = "depth";
                print(
                    f"  DEPTH {self.max_depth} exceeded at #{here.issue_id}"
                );
                disengage;
            }
            self.visited_ids.append(here.issue_id);
            self.depth = next_depth;
            merged = (
                here.status == "merged" or here.status == "completed"
            );
            if not merged {
                self.fault = "blocked";
                print(
                    f"  BLOCKED: #{here.issue_id} still [{here.status}]"
                );
                disengage;
            }
            visit [->:DependsOn:->] else {
                disengage;
            };
        }
    }
}

