walker AffectedAnalyzer {
    has visited: list[str] = [];
    has affected: list[str] = [];
    has depth: int = 0;
    has max_depth: int = 50;

    can start with Root entry {
        print("Reverse impact: walking referencers with evidence tiers");
        visit [-->];
    }

    can trace with Method | Class entry {
        if here.name in self.visited {
            print(f"[cycle guard] re-entry blocked at {here.name}");
            disengage;
        }
        if self.depth >= self.max_depth {
            print(f"[depth cap] stopping at {here.name}");
            disengage;
