        self.depth = self.depth + 1;
        self.visited.append(here.name);
        self.affected.append(here.name);
        tier_label = "impact";
        print(f"[{tier_label}] affected: {here.name} (depth={self.depth})");
        visit [->:DefinedAt:->];
        visit [<--:ExtractedRef:--];
        visit [<--:InferredRef:--] else { disengage; };
    }

    can show_site with SourceSite entry {
        print(f"  evidence site: {here.path}:{here.line}");
        disengage;
    }
