    has blocked: list[str] = [];
    has seeded: bool = False;

    can probe with Method | Class entry {
        if not self.seeded {
            self.seeded = True;
            print(f"Fail-closed probe at anchor {here.name}");
            visit [<--:AmbiguousRef:--] else {
                print(f"No ambiguous inbound refs at {here.name}");
                disengage;
            };
