"""Wayfinder admission: stack-safe dependency-ordered slice landing with cycle and depth guards."""

node Tracker {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has issue_id: int = 0;
}

node Milestone(Tracker) {
    has closed: bool = True;
}

node Slice(Tracker) {
    has status: str = "blocked";
}

edge DependsOn { }

edge Governs { }

walker ResidualLister {
    has seen: list[int] = [];

    can start with Root entry {
        print("=== Residual scope scan ===");
        visit [-->[?:Slice]] else { disengage; };
    }

    can tally with Slice entry {
        if here.issue_id in self.seen {
            disengage;
        }
        self.seen.append(here.issue_id);
        if here.status == "ready" or here.status == "blocked" {
            tag = "next-gate" if here.status == "ready" else "deferred";
            print(f"  [{tag}] #{here.issue_id} {here.title}");
        }
        disengage;
    }
}

walker Wayfinder {
    has max_depth: int = 256;
    has depth: int = 0;
    has visited_ids: list[int] = [];
    has fault: str = "";
    has probing: bool = False;

    can start with Root entry {
        visit [-->[?:Slice]] else { disengage; };
    }

    can evaluate with Slice entry {
        if not self.probing {
            if here.status != "ready" {
                disengage;
            }
            print(f"=== Admission probe: #{here.issue_id} {here.title} ===");
            self.probing = True;
            self.depth = 0;
            self.visited_ids = [];
            self.fault = "";
            visit [->:DependsOn:->] else { disengage; };
            if self.fault == "" {
                print(
                    f"PASS: #{here.issue_id} stack-safe — cleared for landing"
                );
            } else {
                reason = "cyclic dependency graph";
                if self.fault == "depth" {
                    reason = "logical-depth policy exceeded";
                }
                if self.fault == "blocked" {
                    reason = "unmerged prerequisite remains";
                }
                print(f"FAIL: #{here.issue_id} rejected ({reason})");
            }
            self.probing = False;
            disengage;
        } else {
            if self.fault != "" {
                disengage;
            }
            if here.issue_id in self.visited_ids {
                self.fault = "cycle";
                print(f"  CYCLE re-entry at #{here.issue_id}");
                disengage;
            }
            next_depth = self.depth + 1;
            if next_depth > self.max_depth {
                self.fault = "depth";
                print(
                    f"  DEPTH {self.max_depth} exceeded at #{here.issue_id}"
                );
                disengage;
            }
            self.visited_ids.append(here.issue_id);
            self.depth = next_depth;
            merged = here.status == "merged" or here.status == "completed";
            if not merged {
                self.fault = "blocked";
                print(
                    f"  BLOCKED: #{here.issue_id} still [{here.status}]"
                );
                disengage;
            }
            visit [->:DependsOn:->] else { disengage; };
        }
    }
}

