"""ECS hierarchy walks: budgeted transform BFS, parent-chain climb, and post-order bounds detect Parent/Children cycles."""

node Entity {
    has name: str = "";
    has local_x: float = 0.0;
    has world_x: float = 0.0;
    has min_x: float = 0.0;
    has max_x: float = 0.0;
}

edge ChildOf { }

walker TransformPropagator {
    has max_steps: int = 64;
    has steps: int = 0;
    has visited: list[str] = [];
    has cycle_detected: bool = False;
    has parent_world_x: float = 0.0;

    can start with Root entry {
        print("--- Transform propagation (budgeted BFS) ---");
        visit [-->] else { disengage; }
    }

    can propagate with Entity entry {
        if here.name in self.visited {
            self.cycle_detected = True;
            print(f"ERROR: cycle detected at '{here.name}' after {self.steps} steps");
            disengage;
        }
        if self.steps >= self.max_steps {
            self.cycle_detected = True;
            print(f"ERROR: propagation budget exhausted at {self.max_steps} steps");
            disengage;
        }
        self.visited.append(here.name);
        self.steps += 1;
        here.world_x = self.parent_world_x + here.local_x;
        print(f"  [{self.steps}] {here.name} world_x={here.world_x}");
        saved_parent = self.parent_world_x;
        self.parent_world_x = here.world_x;
        visit [->:ChildOf:->] else { }
        self.parent_world_x = saved_parent;
        visit [-->] else { disengage; }
    }
}

walker BoundsParentClimber {
    has max_depth: int = 32;
    has depth: int = 0;
    has visited: list[str] = [];
    has chain: list[str] = [];
    has cycle_detected: bool = False;

    can start with Entity entry {
        print("--- Bounds parent-chain climb (budgeted) ---");
        self.chain = [here.name];
        self.visited = [here.name];
        self.depth = 1;
        visit [<-:ChildOf:<-] else {
            chain_text = "";
            for (i, label) in enumerate(self.chain) {
                sep = " -> " if i > 0 else "";
                chain_text += f"{sep}{label}";
            }
            print(f"  parent chain: {chain_text}");
            disengage;
        }
    }

    can ascend with Entity entry {
        if here.name in self.visited {
            self.cycle_detected = True;
            print(f"ERROR: parent climb cycle at '{here.name}' depth {self.depth}");
            disengage;
        }
        if self.depth >= self.max_depth {
            self.cycle_detected = True;
            print(f"ERROR: parent climb budget exhausted at depth {self.max_depth}");
            disengage;
        }
        self.visited.append(here.name);
        self.chain.append(here.name);
        self.depth += 1;
        visit [<-:ChildOf:<-] else {
            chain_text = "";
            for (i, label) in enumerate(self.chain) {
                sep = " -> " if i > 0 else "";
                chain_text += f"{sep}{label}";
            }
            print(f"  parent chain: {chain_text}");
            disengage;
        }
    }
}

walker BoundsPostOrder {
    has max_steps: int = 64;
    has steps: int = 0;
    has stack: list[str] = [];
    has cycle_detected: bool = False;

    can start with Root entry {
        print("--- Bounds post-order walk (budgeted) ---");
        visit [-->] else { disengage; }
    }

    can aggregate with Entity entry {
        if here.name in self.stack {
            self.cycle_detected = True;
            print(f"ERROR: post-order cycle at '{here.name}' after {self.steps} steps");
            disengage;
        }
        if self.steps >= self.max_steps {
            self.cycle_detected = True;
            print(f"ERROR: post-order budget exhausted at {self.max_steps} steps");
            disengage;
        }
        self.stack.append(here.name);
        self.steps += 1;
        visit [->:ChildOf:->] else { }
        stack_len = len(self.stack);
        if stack_len > 0 {
            self.stack = self.stack[:stack_len - 1];
        }
        here.min_x = here.world_x;
        here.max_x = here.world_x;
        print(f"  post-order {here.name}: bounds [{here.min_x}, {here.max_x}]");
        visit [-->] else { disengage; }
    }
}

with entry {
    torso = Entity(name="torso", local_x=10.0);
    arm = Entity(name="arm", local_x=5.0);
    cycle_a = Entity(name="cycle_a", local_x=1.0);
    cycle_b = Entity(name="cycle_b", local_x=2.0);

    root ++> torso;
    torso +>:ChildOf:+> arm;
    root ++> cycle_a;
    cycle_a +>:ChildOf:+> cycle_b;
    cycle_b +>:ChildOf:+> cycle_a;

    propagator = TransformPropagator(max_steps=16);
    root spawn propagator;
    if propagator.cycle_detected {
        print("Propagation halted: cyclic Children graph would hang an unguarded BFS");
    }

    torso.world_x = 10.0;
    arm.world_x = 15.0;
    climber = BoundsParentClimber(max_depth=8);
    arm spawn climber;

    post_order = BoundsPostOrder(max_steps=16);
    root spawn post_order;
    if post_order.cycle_detected {
        print("Post-order halted: cyclic hierarchy would recurse forever without guards");
    }
}

