                disengage;
            }
            if here.issue_id in self.visited_ids {
                self.fault = "cycle";
                print(f"  CYCLE re-entry at #{here.issue_id}");
                disengage;
            }
            next_depth = self.depth + 1;
            if next_depth > self.max_depth {
                self.fault = "depth";
