            merged = here.status == "merged" or here.status == "completed";
            if not merged {
                self.fault = "blocked";
                print(
                    f"  BLOCKED: #{here.issue_id} still [{here.status}]"
                );
                disengage;
            }
            visit [->:DependsOn:->] else { disengage; };
        }
    }
}

