    has view_name: str = "";
}

edge DerivesFrom { }

edge FeedsMeasure {
    has weight: float = 1.0;
}

edge DependsOn {
    has kind: str = "blocks";
}

walker SchematicExplorer {
    has actor_role: str = "viewer";
    has denied: int = 0;
    has traced: int = 0;

    can start with Root entry {
        print(f"=== Governed schematic exploration (role={self.actor_role}) ===");
        visit [-->];
    }

    can open with SchematicView entry {
        print(f"[VIEW] {here.view_name}");
        visit [-->];
