        status = "FRESH" if here.fresh else "STALE";
        print(
            f"  [MEASURE] {here.title} v{here.version} "
            f"({here.unit}) [{status}] owner={here.owner}"
        );
        visit [<--:FeedsMeasure:--];
        visit [-->];
    }

    can inspect_insight with Insight entry {
        review_flag = "REVIEWED" if here.reviewed else "PENDING";
        print(
            f"  [INSIGHT:{review_flag}] {here.title} "
            f"via {here.method} (conf={here.confidence})"
        );
        visit [->:DerivesFrom:->] else { disengage; }
    }

    can follow_source with SourceRecord entry {
        if not here.permitted and self.actor_role != "admin" {
