"""Ownership unwrapping: policy-driven recursive assessment with cycle guards and effective shareholding."""

node Policy {
    has policy_id: str = "";
    has name: str = "";
    has version: str = "";
    has beneficial_owner_threshold: float = 25.0;
    has material_link_threshold: float = 5.0;
}

node Skill {
    has skill_id: str = "";
    has name: str = "";
}

node Entity {
    has legal_name: str = "";
    has entity_id: str = "";
    has jurisdiction: str = "";
    has endpoint_kind: str = "";

    def is_terminal() -> bool {
        return False;
    }
}

node CorporateEntity(Entity) {
    has entity_kind: str = "corporate";
}

node AssessedEntity(CorporateEntity) {
    has entity_kind: str = "assessed";
}

node NaturalPerson(Entity) {
    has endpoint_kind: str = "natural_person";

    override def is_terminal() -> bool {
        return True;
    }
}

node ListedCompany(Entity) {
    has endpoint_kind: str = "listed_company";

    override def is_terminal() -> bool {
        return True;
    }
}

node GovernmentBody(Entity) {
    has endpoint_kind: str = "government_body";

    override def is_terminal() -> bool {
        return True;
    }
}

node OwnershipRecord {
    has percent: float = 0.0;
    has source: str = "";
    has source_date: str = "";
    has ownership_type: str = "direct";
}

edge RecordsOwnership { }
edge PointsToOwner { }
edge UsesPolicy { }

walker OwnershipUnwrapper {
    has policy: Policy;
    has visited: list[str] = [];
    has path_effective: float = 100.0;
    has findings: list[str] = [];
    has gaps: list[str] = [];

    can start with Root entry {
        print("unwrap-ownership SKILL: begin orchestration");
        visit [-->];
    }

    can load_skill with Skill entry {
        print(f"  [1] Load SKILL: {here.skill_id} ({here.name})");
        visit [-->];
    }

    can load_policy with Policy entry {
        self.policy = here;
        print(
            f"  [2] Load policy: {here.policy_id} v{here.version} "
            f"(BO>={here.beneficial_owner_threshold}%, "
            f"material>={here.material_link_threshold}%)"
        );
        visit [-->];
    }

    can unwrap with AssessedEntity | CorporateEntity entry {
        if here.entity_id in self.visited {
            gap = f"cycle:{here.entity_id}";
            self.gaps.append(gap);
            print(f"  [8] CYCLE at {here.legal_name} ({here.entity_id})");
            disengage;
        }
        self.visited.append(here.entity_id);
        action = "Assess" if here.entity_kind == "assessed" else "Unwrap";
        print(
            f"  [{action}] {here.legal_name} "
            f"({here.jurisdiction}) path={self.path_effective:.2f}%"
        );
        saved_path = self.path_effective;
        visit [->:RecordsOwnership:->] else {
            gap = f"incomplete:{here.entity_id}";
            self.gaps.append(gap);
            print(f"  [GAP] No ownership records for {here.legal_name}");
            disengage;
        };
        self.path_effective = saved_path;
    }

    can follow_record with OwnershipRecord entry {
        if here.percent < self.policy.material_link_threshold {
            print(
                f"    [SKIP] Immaterial link {here.percent}% "
                f"(<{self.policy.material_link_threshold}%)"
            );
            disengage;
        }
        saved_path = self.path_effective;
        new_effective = self.path_effective * (here.percent / 100.0);
        self.path_effective = new_effective;
        print(
            f"    Link {here.percent}% {here.ownership_type} "
            f"-> effective {new_effective:.2f}% "
            f"(src={here.source}, {here.source_date})"
        );
        visit [->:PointsToOwner:->] else {
            gap = f"missing_owner:{here.source}";
            self.gaps.append(gap);
            print("    [GAP] Ownership record has no owner target");
            disengage;
        };
        self.path_effective = saved_path;
    }

    can continue_unwrap with CorporateEntity entry {
        saved_path = self.path_effective;
        visit [->:RecordsOwnership:->] else { disengage; };
        self.path_effective = saved_path;
    }

    can record_ultimate with NaturalPerson | ListedCompany | GovernmentBody entry {
        effective = self.path_effective;
        outcome = "manual_review";
        if here.endpoint_kind == "natural_person" {
            outcome = (
                "beneficial_owner_identified"
                if effective >= self.policy.beneficial_owner_threshold
                else "below_threshold"
            );
        } elif here.endpoint_kind == "listed_company" {
            outcome = "listed_company_endpoint";
        } else {
            outcome = "government_body_endpoint";
