"""Interprocedural compiler verification: upstream witness facts through summary composition, bounded recursive closure, and publication currentness."""

node Routine {
    has title: str = "";
    has routine_name: str = "";
    has generation: int = 0;
    has year: int = 0;
    has available: bool = True;
}

node CallSite {
    has title: str = "";
    has context: str = "scalar";
    has year: int = 0;
    has available: bool = True;
}

node Fact {
    has title: str = "";
    has fact_kind: str = "";
    has place: str = "";
    has is_caller_visible: bool = True;
    has year: int = 0;
    has available: bool = True;
}

node ResultFact(Fact) {
    has origin: str = "local";
}

node EffectFact(Fact) {
    has effect_order: int = 0;
}

node Summary {
    has title: str = "";
    has generation: int = 0;
    has published_generation: int = 0;
    has published: bool = False;
    has complete: bool = False;
    has year: int = 0;
    has available: bool = True;
}

node RecursiveComponent {
    has title: str = "";
    has component_id: str = "";
    has closure_complete: bool = False;
    has member_count: int = 0;
    has year: int = 0;
    has available: bool = True;
}

node CompilerWorld {
    has title: str = "";
    has current_generation: int = 0;
    has year: int = 0;
    has available: bool = True;
}

edge HasFact { }
edge SummarizedAs { }
edge Calls { has arg_binding: str = "positional"; }
edge CallsTo { }
edge MemberOf { }
edge Hosts { }
edge Publishes { }

walker ProofAssembler {
    has proof_cells: int = 0;
    has visited_names: list[str] = [];
    has closure_depth: int = 0;
    has max_depth: int = 8;

    can start with Root entry {
        print("=== witness facts -> summary -> substitution -> closure ===");
        visit [-->];
    }

    can enter_world with CompilerWorld entry {
        print(f"CompilerWorld current_generation={here.current_generation}");
        visit [->:Hosts:->];
    }

    can assemble with Routine entry {
        if here.routine_name in self.visited_names {
            print(f"CYCLE_GUARD re-entry blocked: {here.routine_name}");
            disengage;
        }
        if self.closure_depth >= self.max_depth {
            print(f"DEPTH_CAP blocked: {here.routine_name}");
            disengage;
        }
        self.visited_names.append(here.routine_name);
        self.closure_depth += 1;
        print(f"routine {here.routine_name} gen={here.generation} depth={self.closure_depth}");
        visit [->:HasFact:->];
        visit [->:SummarizedAs:->];
        visit [->:Calls:->] else { visit [-->] else { disengage; }; };
    }

    can read_fact with ResultFact | EffectFact entry {
        scope_tag = "caller_visible" if here.is_caller_visible else "callee_private";
        print(f"  fact [{here.fact_kind}] place={here.place} scope={scope_tag}");
        self.proof_cells += 1;
    }

    can bind_summary with Summary entry {
        label = "COMPLETE" if here.complete else "PARTIAL";
        print(f"  summary {label} gen={here.generation}");
        self.proof_cells += 1;
    }

    can substitute with CallSite entry {
        print(f"  callsite ctx={here.context} direct_substitution");
        visit [->:CallsTo:->] else { visit [-->] else { disengage; }; };
        self.proof_cells += 1;
    }

    can close_component with RecursiveComponent entry {
        print(f"component {here.component_id} members={here.member_count}");
        visit [->:MemberOf:->] else { disengage; };
        here.closure_complete = True;
        self.proof_cells += 1;
    }
}

walker CurrentnessAuditor {
    has world_generation: int = 0;
    has stale_count: int = 0;
    has current_count: int = 0;

    can start with Root entry {
        print("=== publication currentness invalidation ===");
        visit [-->];
    }

    can audit_world with CompilerWorld entry {
        self.world_generation = here.current_generation;
        visit [->:Publishes:->] else { disengage; };
    }

    can audit_summary with Summary entry {
        if here.published {
            if here.published_generation < self.world_generation {
                print(f"STALE {here.title} pub={here.published_generation} world={self.world_generation}");
                self.stale_count += 1;
            } else {
                print(f"CURRENT {here.title} pub={here.published_generation}");
                self.current_count += 1;
            }
        }
    }
}

with entry {
    world = CompilerWorld(title="world", current_generation=2);
    main_fn = Routine(title="main", routine_name="main", generation=2);
