    main_result = ResultFact(title="main_result", fact_kind="result", place="$sum", is_caller_visible=True, origin="call");
    main_effect = EffectFact(title="main_effect", fact_kind="effect", place="$y", is_caller_visible=True, effect_order=1);
    add_result = ResultFact(title="add_result", fact_kind="result", place="$_", is_caller_visible=False, origin="local");
    add_warn = ResultFact(title="add_warn", fact_kind="warning", place="useless_use", is_caller_visible=True, origin="builtin");

    solo_comp = RecursiveComponent(title="solo_rec", component_id="factorial_loop", member_count=1);
    mutual_comp = RecursiveComponent(title="mutual_rec", component_id="even_odd_pair", member_count=2);

    root ++> world ++> main_fn;
