    add_fn +>:SummarizedAs:+> add_summary;

    solo_comp +>:MemberOf:+> factorial_fn;
    factorial_fn +>:Calls:+> fact_call;
    fact_call +>:CallsTo:+> factorial_fn;

    mutual_comp +>:MemberOf:+> even_fn;
    mutual_comp +>:MemberOf:+> odd_fn;
    even_fn +>:Calls:+> even_call;
    even_call +>:CallsTo:+> odd_fn;
    odd_fn +>:Calls:+> odd_call;
    odd_call +>:CallsTo:+> even_fn;

    assembler = ProofAssembler();
    root spawn assembler;
    print(f"assembler proof_cells={assembler.proof_cells} visited={assembler.visited_names}");

    auditor = CurrentnessAuditor();
    root spawn auditor;
    print(f"auditor stale={auditor.stale_count} current={auditor.current_count}");
}

"""App Factory enterprise pipeline: stage dependency ordering with checkpoint evidence staleness."""

node MasterHead {
    has sha: str = "";
    has label: str = "master";
}

node Stage {
    has number: int = 0;
    has name: str = "";
    has complete: bool = False;
}

node Checkpoint {
    has pr_id: int = 0;
    has head_sha: str = "";
    has ci_pass: bool = False;
    has stale: bool = False;
}

node Capability {
    has name: str = "";
    has status: str = "BLOCKED";
}

edge DependsOn {
    has note: str = "";
}

edge Validates {
    has gate: str = "";
}

edge RecordedAt {
    has when: str = "";
}

edge Resolves {
    has priority: int = 0;
}

walker StageCoordinator {
    has ready: list[str] = [];
    has blocked: list[str] = [];

    can start with Root entry {
        print("=== Stage dependency audit ===");
        visit [-->];
    }

    can begin with MasterHead entry {
        visit [->:DependsOn:->] else { disengage; };
    }

    can audit with Stage entry {
        if here.complete {
            self.ready.append(here.name);
            print(f"[READY] Stage {here.number}: {here.name}");
        } else {
            self.blocked.append(here.name);
            print(f"[BLOCKED] Stage {here.number}: {here.name}");
        }
        visit [->:DependsOn:->] else { disengage; };
    }
}

walker EvidenceAuditor {
    has current_sha: str = "";
    has fresh_count: int = 0;
    has stale_count: int = 0;

    can start with Root entry {
        print(f"=== Evidence audit against master {self.current_sha} ===");
        visit [-->];
    }

    can begin with MasterHead entry {
        visit [->:RecordedAt:->] else { disengage; };
    }

    can inspect with Checkpoint entry {
        if here.head_sha != self.current_sha {
            here.stale = True;
            self.stale_count += 1;
            verdict = "STALE";
        } else {
            here.stale = False;
            self.fresh_count += 1;
            verdict = "FRESH";
        }
        gate = "PASS" if here.ci_pass else "FAIL";
        print(f"PR #{here.pr_id} [{verdict}] CI={gate} @ {here.head_sha}");
        visit [->:Validates:->] else { disengage; };
    }

    can report with Stage entry {
        label = "DONE" if here.complete else "PENDING";
        print(f"  validates Stage {here.number} ({here.name}): {label}");
        visit [-->] else { disengage; };
    }
}

walker CapabilityResolver {
    has resolved: list[str] = [];

    can start with Root entry {
        print("=== Capability resolution ===");
        visit [-->];
    }

    can scan with Stage entry {
        visit [->:Resolves:->] else { disengage; };
    }

    can resolve with Capability entry {
        self.resolved.append(f"{here.name}={here.status}");
        print(f"  {here.name}: {here.status}");
        visit [-->] else { disengage; };
    }
}

