    main_fn +>:HasFact:+> main_result;
    main_fn +>:HasFact:+> main_effect;
    main_fn +>:SummarizedAs:+> main_summary;
    main_fn +>:Calls(arg_binding="positional"):+> main_call;
    main_call +>:CallsTo:+> add_fn;

    add_fn +>:HasFact:+> add_result;
    add_fn +>:HasFact:+> add_warn;
    add_fn +>:SummarizedAs:+> add_summary;

    solo_comp +>:MemberOf:+> factorial_fn;
    factorial_fn +>:Calls:+> fact_call;
    fact_call +>:CallsTo:+> factorial_fn;

