"""Security: atomically reserve miner bundle root before packaging writes.

Models issue #683 — pathname-based cleanup plus recursive mkdir allows a raced
symlink/junction at the per-platform bundle leaf to redirect cp/writeFile/chmod
outside the bound miner-release root. Reservation must exclusive-create the bundle
directory, verify it is a real directory whose parent remains the bound release
root, and fail closed before any child pathname operation. External sentinel bytes
must remain untouched when the race wins.
"""

edge UnderRelease {
    has canonical: bool = True;
}

edge MaterializedAs {
    has exclusive: bool = False;
}

edge QueuedWrite {
    has pending: bool = True;
}

edge OutsideBoundary {
    has leaked: bool = False;
}

node ReleaseRoot {
    has bound_path: str = "";
    has custody_bound: bool = True;
}

node BundleSlot {
    has platform: str = "";
    has pathname: str = "";
    has phase: str = "idle";
}

node FsObject {
    has path: str = "";
    has outside_target: str = "";

    def is_directory() -> bool {
        return False;
    }

    def is_trap() -> bool {
        return False;
    }
}

node RealDir(FsObject) {
    override def is_directory() -> bool {
        return True;
    }
}

node SymlinkTrap(FsObject) {
    override def is_trap() -> bool {
        return True;
    }
}

node Sentinel {
    has label: str = "";
    has touched: bool = False;
}

node PackageWrite {
    has op: str = "";
    has rel_segment: str = "";
}

walker PathnamePackager {
    has leaked_outside: bool = False;
    has visited_slots: list[str] = [];

    can start with Root entry {
        print("VULNERABLE: pathname cleanup then recursive mkdir without bundle-root custody");
        visit [->:UnderRelease:->] else { disengage; };
    }

    can cross_release with ReleaseRoot entry {
        visit [->:UnderRelease:->] else { disengage; };
    }

    can at_slot with BundleSlot entry {
        if here.pathname in self.visited_slots {
            disengage;
        }
        self.visited_slots.append(here.pathname);
        here.phase = "cleaned";
        visit [->:MaterializedAs:->] else {
            visit [->:QueuedWrite:->] else { disengage; };
        };
    }

    can follow_trap with SymlinkTrap entry {
        self.leaked_outside = True;
        print(f"VULNERABLE: followed trap to {here.outside_target}");
        visit [->:QueuedWrite:->] else { disengage; };
    }

    can blind_write with PackageWrite entry {
        print(f"VULNERABLE pathname write: {here.op} on {here.rel_segment}");
        visit [-->] else { disengage; };
    }
}

walker BundleReserver {
    has custody_ok: bool = False;
    has reserved: bool = False;
    has fail_closed: bool = False;
    has visited_slots: list[str] = [];

    can start with Root entry {
        print("SECURE: bind miner-release root then exclusive non-recursive bundle reservation");
        visit [->:UnderRelease:->] else { disengage; };
    }

    can bind with ReleaseRoot entry {
        if here.custody_bound {
            self.custody_ok = True;
            visit [->:UnderRelease:->] else { disengage; };
        } else {
            self.fail_closed = True;
            disengage;
        }
    }

    can at_slot with BundleSlot entry {
        if here.pathname in self.visited_slots {
            disengage;
        }
        self.visited_slots.append(here.pathname);
        here.phase = "cleaned";

        visit [->:MaterializedAs:->] else {
            here +>:MaterializedAs(exclusive=True):+> (bundle_dir := RealDir(path=here.pathname));
            here.phase = "reserved";
            self.reserved = True;
        };

        visit [->:MaterializedAs:->] else { disengage; };
    }

    can verify_fs with RealDir | SymlinkTrap entry {
        if here.is_trap() {
            self.fail_closed = True;
            print(f"FAIL CLOSED: raced bundle symlink trap {here.path} -> {here.outside_target}");
            disengage;
        }
        print(f"verified real bundle directory under bound release root: {here.path}");
        visit [->:QueuedWrite:->] else { disengage; };
    }

    can safe_write with PackageWrite entry {
        if self.fail_closed or not self.custody_ok {
            disengage;
        }
        print(f"handle-bound write: {here.op} on {here.rel_segment}");
        visit [-->] else { disengage; };
    }
}

with entry {
    sentinel = Sentinel(label="outside-miner-release", touched=False);

    release = ReleaseRoot(bound_path="/miner-release", custody_bound=True);
    root +>:UnderRelease:+> release;
    release +>:OutsideBoundary:+> sentinel;

    raced = BundleSlot(
        platform="linux-amd64",
        pathname="/miner-release/linux-amd64"
    );
    release +>:UnderRelease:+> raced;
    trap = SymlinkTrap(
        path="/miner-release/linux-amd64",
        outside_target="/tmp/evil-sentinel"
    );
    raced +>:MaterializedAs:+> trap;
    raced +>:QueuedWrite:+> PackageWrite(op="writeFile", rel_segment="miner.json");

    naive = PathnamePackager();
    root spawn naive;
    sentinel.touched = naive.leaked_outside;
    print(f"naive raced bundle: leaked_outside={naive.leaked_outside}, sentinel.touched={sentinel.touched}");

    clean = BundleSlot(
        platform="darwin-arm64",
        pathname="/miner-release/darwin-arm64"
    );
    release +>:UnderRelease:+> clean;
    clean +>:QueuedWrite:+> PackageWrite(op="cp", rel_segment="miner-runtime/bin");

    guard = BundleReserver();
    root spawn guard;
    print(f"secure clean bundle: reserved={guard.reserved}, fail_closed={guard.fail_closed}, sentinel.touched={sentinel.touched}");
}

