"""Nested group membership: reject self-reference and cyclic adds via descendant walk."""

node Group {
    has name: str = "";
    has gid: str = "";
}

edge Contains { }

walker DescendantProbe {
    has seek_gid: str = "";
    has found: bool = False;
    has visited: list[str] = [];

    can start with Group entry {
        if here.gid in self.visited {
            disengage;
        }
        self.visited += [here.gid];
        if here.gid == self.seek_gid {
            self.found = True;
            disengage;
        }
        visit [->:Contains:->] else { disengage; };
    }

    can walk_member with Group entry {
        if here.gid in self.visited {
            disengage;
        }
        self.visited += [here.gid];
        if here.gid == self.seek_gid {
            self.found = True;
            disengage;
        }
        visit [->:Contains:->] else { disengage; };
    }
}

def reachable_from(member: Group, target_gid: str) -> bool {
    probe = DescendantProbe(seek_gid=target_gid);
    member spawn probe;
    return probe.found;
}

def try_add_member(member: Group, target: Group) -> bool {
    if member.gid == target.gid {
        print(f"REJECT self-reference: {target.name} -> {member.name}");
        return False;
    }
    if reachable_from(member, target.gid) {
        print(f"REJECT cycle: {target.name} reachable inside {member.name}");
        return False;
    }
    target +>:Contains:+> member;
    print(f"OK: {member.name} now member of {target.name}");
    return True;
}

