def sort_payouts(rows: list[tuple[int, int]]) -> list[tuple[int, int]] {
    result: list[tuple[int, int]] = [];
    for row in rows {
        result.append(row);
    }
    n = len(result);
    for i in range(n) {
        for j in range(i + 1, n) {
            (ci, ni) = result[i];
            (cj, nj) = result[j];
            swap_needed = False;
            if ci < cj {
                swap_needed = True;
            } else {
                if ci == cj and ni > nj {
                    swap_needed = True;
                }
            }
            if swap_needed {
                tmp = result[i];
                result[i] = result[j];
                result[j] = tmp;
            }
        }
    }
    return result;
}

