"""Nested group membership: reject self-reference and cyclic adds via descendant walk."""

node Group {
    has name: str = "";
    has gid: str = "";
}

edge Contains { }

walker DescendantProbe {
    has seek_gid: str = "";
    has found: bool = False;
    has visited: list[str] = [];

    can descend with Group entry {
        if here.gid in self.visited {
            visit [-->] else { disengage; };
        } else {
            self.visited += [here.gid];
            if here.gid == self.seek_gid {
                self.found = True;
                visit [-->] else { disengage; };
            } else {
                visit [->:Contains:->] else { disengage; };
            }
        }
    }
}

def reachable_from(member: Group, target_gid: str) -> bool {
    probe = DescendantProbe(seek_gid=target_gid);
    member spawn probe;
    return probe.found;
}

def try_add_member(member: Group, target: Group) -> bool {
    if member.gid == target.gid {
        print(f"REJECT self-reference: {target.name} -> {member.name}");
        return False;
    }
    if reachable_from(member, target.gid) {
        print(f"REJECT cycle: {target.name} reachable inside {member.name}");
        return False;
    }
    target +>:Contains:+> member;
    print(f"OK: {member.name} now member of {target.name}");
    return True;
}

with entry {
    root ++> (alpha := Group(name="Alpha", gid="g-alpha"))
        ++> (beta := Group(name="Beta", gid="g-beta"))
        ++> (gamma := Group(name="Gamma", gid="g-gamma"))
        ++> (delta := Group(name="Delta", gid="g-delta"));

    alpha +>:Contains:+> beta;
    beta +>:Contains:+> gamma;

    print("--- valid add: delta into alpha ---");
    try_add_member(delta, alpha);

    print("--- reject self-reference: beta into beta ---");
    try_add_member(beta, beta);

    print("--- reject cycle: alpha into beta (alpha already contains beta) ---");
    try_add_member(alpha, beta);

    print("--- reject cycle: alpha into gamma (alpha nests beta nests gamma) ---");
    try_add_member(alpha, gamma);
}

"""Agent-first architecture standard: profile inheritance, dependency legibility, and context-locality probes over a module graph."""

node ArchitectureProfile {
    has profile_name: str = "";
    has version: str = "";
    has is_default: bool = False;
}

node Module {
    has name: str = "";
    has contract_revision: str = "";
    has contract_sufficient: bool = True;
    has responsibility: str = "";
    has undeclared_coupling: bool = False;
}

edge GovernedBy { }

edge DependsOn {
    has declared: bool = True;
}

walker ProfileResolver {
    has resolved_label: str = "";

    can start with Module entry {
        print(f"Resolving architecture profile for module '{here.name}'");
        visit [->:GovernedBy:->] else {
            self.resolved_label = "Agent-First-Default-v1.0.0 (inherited)";
            print(f"[INHERIT] no custom profile bound; using {self.resolved_label}");
            disengage;
        };
    }

    can accept with ArchitectureProfile entry {
        bound_label = f"{here.profile_name} v{here.version}";
        if here.is_default {
            self.resolved_label = bound_label;
            print(f"[INHERIT] default standard applied: {bound_label}");
        } else {
            self.resolved_label = bound_label;
            print(f"[CUSTOM] durable custom profile retained: {bound_label}");
        }
        disengage;
    }
}

walker DependencyAuditor {
    has stack: list[str] = [];
    has cycles: list[str] = [];
    has violations: list[str] = [];
    has modules_seen: int = 0;

    can start with Root entry {
        print("=== Dependency legibility audit ===");
        visit [-->];
    }

    can audit_module with Module entry {
        self.modules_seen += 1;
        if here.name in self.stack {
            trail = " -> ".join(self.stack + [here.name]);
            cycle_msg = f"dependency cycle: {trail}";
            self.cycles.append(cycle_msg);
            print(f"[FAIL] {cycle_msg}");
            disengage;
        }
        self.stack.append(here.name);
        if not here.contract_sufficient {
            v = f"contract insufficient at '{here.name}' (rev {here.contract_revision})";
            self.violations.append(v);
            print(f"[FAIL] contract sufficiency: {v}");
        }
        if here.undeclared_coupling {
            v = f"undeclared cross-module reach at '{here.name}'";
            self.violations.append(v);
            print(f"[FAIL] dependency legibility: {v}");
        }
        print(f"[CHECK] {here.name} ({here.responsibility}) rev={here.contract_revision}");
        visit [->:DependsOn:->] else { disengage; };
        self.stack.pop();
    }

    can audit_profile with ArchitectureProfile entry {
        print(f"[PROFILE] {here.profile_name} v{here.version} default={here.is_default}");
        visit [-->];
    }
}

walker ContextProbe {
    has origin: str = "";
    has consulted: list[str] = [];
    has foreign_reads: int = 0;
    has depth: int = 0;
    has max_depth: int = 3;
    has locality_ok: bool = True;

    can start with Module entry {
        if not self.origin {
            self.origin = here.name;
            print(f"=== Context locality probe (origin='{self.origin}') ===");
        }
        if here.name != self.origin {
            self.foreign_reads += 1;
            if not here.contract_sufficient {
                self.locality_ok = False;
                print(f"[VIOLATION] foreign implementation read: '{here.name}' lacks sufficient contract");
            } else {
                print(f"[INFO] bounded foreign contract read: '{here.name}'");
            }
        }
        if here.name not in self.consulted {
            self.consulted.append(here.name);
        }
        self.depth += 1;
        if self.depth >= self.max_depth {
            print(f"[STOP] depth cap {self.max_depth} reached at '{here.name}'");
            disengage;
        }
        visit [->:DependsOn:->] else { disengage; };
    }
}

with entry {
    default_profile = ArchitectureProfile(
        profile_name="Agent-First",
