    print(f"Context consulted {len(probe.consulted)} modules, {probe.foreign_reads} foreign reads; locality_ok={probe.locality_ok}");
}

"""Issue dependency board: classify READY vs BLOCKED, rank payout impact, and detect title drift."""

node Issue {
    has number: int = 0;
    has title: str = "";
    has open: bool = True;
}

edge BlockedBy { }

def extract_dep(title: str) -> int {
    needle = "depends on #";
    idx = title.find(needle);
    if idx < 0 {
        return 0;
    }
    rest = title[idx + len(needle) :];
    num_str = "";
    for ch in rest {
        if ch >= "0" and ch <= "9" {
            num_str += ch;
        } else {
            break;
        }
    }
    if num_str == "" {
        return 0;
    }
    if len(rest) > len(num_str) {
        next_ch = rest[len(num_str)];
        if (next_ch >= "a" and next_ch <= "z") or (next_ch >= "A" and next_ch <= "Z") {
            return 0;
        }
    }
    return int(num_str);
}

def issue_open(num: int) -> bool {
    finder = OpenLookup(target=num);
    root spawn finder;
    return finder.found_open;
}

def sort_payouts(rows: list[tuple[int, int]]) -> list[tuple[int, int]] {
    result: list[tuple[int, int]] = [];
    for row in rows {
        result.append(row);
    }
    n = len(result);
    for i in range(n) {
        for j in range(i + 1, n) {
            (ci, ni) = result[i];
            (cj, nj) = result[j];
            swap_needed = False;
            if ci < cj {
                swap_needed = True;
            } else {
                if ci == cj and ni > nj {
                    swap_needed = True;
                }
            }
            if swap_needed {
                tmp = result[i];
                result[i] = result[j];
                result[j] = tmp;
            }
        }
    }
    return result;
}

walker BlockerProbe {
    has has_open_blocker: bool = False;
    has seen: list[int] = [];

    can start with Issue entry {
        visit [<--:BlockedBy:--] else {
            disengage;
        };
    }

    can inspect with Issue entry {
        if here.number in self.seen {
            disengage;
        }
        self.seen.append(here.number);
        if here.open {
            self.has_open_blocker = True;
            disengage;
        }
        visit [<--:BlockedBy:--] else {
            disengage;
        };
    }
}

walker DownstreamCounter {
    has count: int = 0;
    has seen: list[int] = [];

    can start with Issue entry {
        visit [->:BlockedBy:->] else {
            disengage;
        };
    }

    can tally with Issue entry {
        if here.number in self.seen {
            disengage;
        }
        self.seen.append(here.number);
        if here.open {
            self.count += 1;
        }
        visit [->:BlockedBy:->] else {
            disengage;
        };
    }
}

walker BlockedByLinker {
    has target: int = 0;
    has linked: bool = False;
    has seen: list[int] = [];

    can start with Issue entry {
        visit [<--:BlockedBy:--] else {
            disengage;
        };
    }

    can match with Issue entry {
        if here.number in self.seen {
            disengage;
        }
        self.seen.append(here.number);
        if here.number == self.target {
            self.linked = True;
            disengage;
        }
        visit [<--:BlockedBy:--] else {
            disengage;
        };
    }
}

walker OpenLookup {
    has target: int = 0;
    has found_open: bool = False;

    can start with Root entry {
        visit [-->];
    }

    can seek with Issue entry {
        if here.number == self.target and here.open {
            self.found_open = True;
            disengage;
        }
        visit [-->];
    }
}

walker BoardClassifier {
    has ready: list[int] = [];
    has blocked: list[int] = [];
    has payouts: list[tuple[int, int]] = [];

    can start with Root entry {
        visit [-->];
    }

    can classify with Issue entry {
        probe = BlockerProbe();
        here spawn probe;
        if probe.has_open_blocker {
            self.blocked.append(here.number);
        } else {
            self.ready.append(here.number);
            counter = DownstreamCounter();
            here spawn counter;
            self.payouts.append((counter.count, here.number));
        }
        visit [-->];
    }
}

walker DriftChecker {
    has drift_violations: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can check_drift with Issue entry {
        ref = extract_dep(here.title);
        if ref > 0 and issue_open(ref) {
            linker = BlockedByLinker(target=ref);
            here spawn linker;
            if not linker.linked {
                self.drift_violations.append(
                    f"#{here.number} title cites #{ref} missing from blockedBy"
                );
            }
        }
        visit [-->];
    }
}

