"""Partition arrangement stitching: apply border twins, reconcile components, validate face cycles."""

node Partition {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has partition_id: int = 0;
    has global_component: int = -1;
}

node BorderSpan {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has obs_id: str = "";
    has direction: str = "forward";
    has physical: bool = True;
    has twin_applied: bool = False;
}

node Face {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has face_id: int = 0;
    has is_unbounded: bool = False;
    has cycle_valid: bool = False;
    has global_face_id: int = -1;
}

edge DeclaredBorder { has label: str = ""; }
edge TwinCandidate { }
edge NextHalfedge { }
edge Hosts { }

walker TwinStitcher {
    has pairs_applied: int = 0;
    has rejections: int = 0;
    has pending_obs: str = "";
    has pending_dir: str = "";

    can start with Root entry {
        print("=== Phase 1: validate and apply atomic twin pairs ===");
        visit [-->];
    }

    can enter_partition with Partition entry {
        visit [->:Hosts:->];
    }

    can apply_twin with BorderSpan entry {
        if here.twin_applied {
            visit [-->];
        } else if !here.physical {
            print(f"  reject {here.obs_id}: span is not physical");
            self.rejections += 1;
            visit [-->];
        } else {
