"""Computer Use AX tree: safe accessibility traversal with cycle, depth, and invalidation guards."""

node AxNode {
    has ax_id: str = "";
    has role: str = "";
    has label: str = "";
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has alive: bool = True;
}

node MacApp {
    has bundle_id: str = "";
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

node SemanticGroup(AxNode) {
    has grouping_kind: str = "";
}

node TextLeaf(AxNode) {
    has text_value: str = "";
}

node MediaView(AxNode) {
    has media_kind: str = "player";
}

edge AxChild {
    has ordinal: int = 0;
}

walker AppStateCollector {
    has max_depth: int = 32;
    has depth: int = 0;
    has nodes_collected: int = 0;
    has visited: list[str] = [];
    has warnings: list[str] = [];

    can start with Root entry {
        print("AppStateCollector: begin AX tree walk");
        visit [->:AxChild:->];
    }

    can attach with MacApp entry {
        print(f"AppShot attach target {here.bundle_id} ({here.title})");
        visit [->:AxChild:->];
    }

    can collect with AxNode entry {
        if not here.available {
            self.warnings.append(
                f"lazy AX skip {here.ax_id} ({here.role}) not exposed"
            );
            visit [->:AxChild:->] else { disengage; };
            return;
        }
        if not here.alive {
            self.warnings.append(
                f"invalidated subtree at {here.ax_id} ({here.role})"
            );
            visit [->:AxChild:->] else { disengage; };
            return;
        }
        if here.ax_id in self.visited {
            self.warnings.append(f"cycle detected at {here.ax_id}");
            disengage;
            return;
        }
        if self.depth >= self.max_depth {
            self.warnings.append(f"depth cap reached at {here.ax_id}");
            disengage;
            return;
        }
        self.visited.append(here.ax_id);
        self.depth += 1;
        self.nodes_collected += 1;
        state_tag = "OK" if here.alive else "STALE";
        print(
            f"  [{state_tag}] depth={self.depth} "
            f"{here.role} {here.label} ({here.ax_id})"
        );
        visit [->:AxChild:->] else { disengage; };
        self.depth -= 1;
    }

    can probe_wrap_hazard with SemanticGroup | TextLeaf entry {
        kind = "semantic-wrap" if here.role == "group" else "appkit-text";
        print(f"    topology probe: {kind} at {here.ax_id}");
    }
}

