"""JaxPP four-stage MPMD pipeline deadlock when DIME transfers meet ragged collectives."""

edge DimeTransfer {
    has lane: int = 0;
}

edge OwnsRank {
}

edge OwnsCollective {
}

node PipelineStage {
    has stage_id: int = 0;
    has label: str = "";
    has transfer_done: bool = False;
}

node GpuRank {
    has rank_id: int = 0;
    has blocked_in: str = "";
    has memory_gib: float = 0.0;
}

node CollectiveOp {
    has op_name: str = "";
    has checksum: int = 0;
    has finished: bool = False;
}

walker DeadlockAuditor {
    has stages_visited: int = 0;
    has stuck_ranks: int = 0;
    has mixed_waits: bool = False;
    has first_wait: str = "";
    has pending_collectives: int = 0;
    has deadlock_detected: bool = False;

    can start with Root entry {
        print("DeadlockAuditor: scanning four-stage JaxPP pipeline");
        visit [-->];
    }

    can audit_stage with PipelineStage entry {
        self.stages_visited += 1;
        xfer_status = "done" if here.transfer_done else "pending";
        print(f"Stage {here.stage_id} ({here.label}): transfer {xfer_status}");
        visit [->:OwnsRank:->];
        visit [->:OwnsCollective:->];
        visit [->:DimeTransfer:->] else { disengage; };
    }

    can check_rank with GpuRank entry {
        print(
            f"  rank {here.rank_id}: blocked_in={here.blocked_in}, "
            f"mem={here.memory_gib} GiB"
        );
        if here.blocked_in != "" {
            self.stuck_ranks += 1;
            if self.first_wait == "" {
                self.first_wait = here.blocked_in;
            } else {
                if here.blocked_in != self.first_wait {
                    self.mixed_waits = True;
                    self.deadlock_detected = True;
                }
            }
        }
    }

    can check_collective with CollectiveOp entry {
        done_label = "finished" if here.finished else "pending";
        print(
            f"  collective {here.op_name}: {done_label}, "
            f"checksum={here.checksum}"
        );
        if here.op_name == "ragged_all_to_all" {
            if not here.finished {
                self.pending_collectives += 1;
                if self.stuck_ranks > 0 {
                    self.deadlock_detected = True;
                }
            }
        }
    }
}

