walker WavePlanner {
    has stack: list[str] = [];
    has cycle_found: bool = False;
    has dep_max: int = 0;

    can start with Root entry {
        print("=== Dynamic wave projection (replaces static plan_waves.py) ===");
        visit [-->];
    }

    can assign with IntentTicket entry {
        if here.title in self.stack {
            self.cycle_found = True;
            print(f"[CYCLE] schedulable dependency loop at {here.title}");
            disengage;
        }
        self.stack.append(here.title);
        self.dep_max = 0;
        visit [->:DependsOn:->];
        here.wave = self.dep_max + 1;
        print(f"  wave {here.wave}: {here.title}");
        self.stack.pop();
        visit [-->];
    }

    can bump_wave with IntentTicket exit {
        next_max = here.wave if here.wave > self.dep_max else self.dep_max;
        self.dep_max = next_max;
    }
}

walker ReadyScanner {
    has blocked: bool = False;
    has checking: bool = False;

    can start with Root entry {
        print("\n--- Ready set (all DependsOn predecessors done) ---");
        visit [-->];
    }

    can probe with IntentTicket | ExecTask entry {
        if self.checking {
            if here.status != "done" {
                self.blocked = True;
            }
            disengage;
        }
        self.blocked = False;
        self.checking = True;
        visit [->:DependsOn:->];
        self.checking = False;
        if not self.blocked and here.status == "pending" {
            print(f"  [READY] {here.title}");
        }
        visit [-->];
    }
}

walker FailureCascade {
    can start with ExecTask entry {
        here.status = "failed";
        print(f"\n--- Gate failure on {here.title} ---");
        visit [<-:DependsOn:<-] else { disengage; };
    }

    can invalidate with IntentTicket | ExecTask entry {
        if here.status != "blocked" {
            here.status = "blocked";
            print(f"  [BLOCKED] downstream {here.title}");
        }
        visit [<-:DependsOn:<-] else { disengage; };
    }
}

walker EvidenceRecorder {
    has entries: int = 0;

    can start with Root entry {
        print("\n--- Evidence journal (append-only gate observations) ---");
        visit [-->];
    }

    can record with ExecTask entry {
        if here.status == "failed" {
            obs = JournalEntry(
                reason_code="GATE_FAIL",
                detail=f"{here.title} attempt {here.attempt}"
            );
            here +>:Records:+> obs;
            self.entries += 1;
            print(f"  [JOURNAL] {obs.reason_code}: {obs.detail}");
        }
        visit [-->];
    }
}

with entry {
