"""Partition arrangement stitching: apply border twins, reconcile components, validate face cycles."""

node Partition {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has partition_id: int = 0;
    has global_component: int = -1;
}

node BorderSpan {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has obs_id: str = "";
    has direction: str = "forward";
    has physical: bool = True;
    has twin_applied: bool = False;
}

node Face {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has face_id: int = 0;
    has is_unbounded: bool = False;
    has cycle_valid: bool = False;
    has global_face_id: int = -1;
}

edge DeclaredBorder { has label: str = ""; }
edge TwinCandidate { }
edge NextHalfedge { }
edge Hosts { }

walker TwinStitcher {
    has pairs_applied: int = 0;
    has rejections: int = 0;
    has pending_obs: str = "";
    has pending_dir: str = "";

    can start with Root entry {
        print("=== Phase 1: validate and apply atomic twin pairs ===");
        visit [-->];
    }

    can enter_partition with Partition entry {
        visit [->:Hosts:->];
    }

    can apply_twin with BorderSpan entry {
        if here.twin_applied {
            visit [-->];
        } else {
            if not here.physical {
                print(f"  reject {here.obs_id}: span is not physical");
                self.rejections += 1;
                visit [-->];
            } else {
                self.pending_obs = here.obs_id;
                self.pending_dir = here.direction;
                visit [->:TwinCandidate:->] else {
                    print(f"  reject {here.obs_id}: no twin candidate on declared border");
                    self.rejections += 1;
                    visit [-->];
                };
            }
        }
    }

    can match_twin with BorderSpan entry {
        if here.obs_id == self.pending_obs {
            print(f"  reject {here.obs_id}: self-twin not allowed");
            self.rejections += 1;
            visit [-->];
        } else {
            if here.direction == self.pending_dir {
                print(f"  reject {self.pending_obs}<->{here.obs_id}: same direction");
                self.rejections += 1;
                visit [-->];
            } else {
                if not here.physical {
                    print(f"  reject {self.pending_obs}<->{here.obs_id}: twin not physical");
                    self.rejections += 1;
                    visit [-->];
                } else {
                    here.twin_applied = True;
                    print(f"  apply twin {self.pending_obs} ({self.pending_dir}) <-> {here.obs_id} ({here.direction})");
                    self.pairs_applied += 1;
                    visit [-->];
                }
            }
        }
    }
}

walker ComponentMerger {
    has next_global_id: int = 1;
    has active_component: int = -1;

    can start with Root entry {
        print("=== Phase 2: reconcile global connected components ===");
        visit [-->];
    }

    can reconcile with Partition entry {
        if here.global_component == -1 {
            if self.active_component == -1 {
                self.active_component = self.next_global_id;
                self.next_global_id += 1;
            }
            here.global_component = self.active_component;
            print(f"  partition {here.partition_id} ({here.title}) -> component {here.global_component}");
            visit [->:DeclaredBorder:->];
            visit [-->];
        } else {
            self.active_component = -1;
            visit [-->];
        }
    }
}

walker FaceCycleValidator {
    has hop: int = 0;
    has max_hops: int = 32;
    has visited_obs: list[str] = [];
    has start_obs: str = "";
    has target_face_id: int = -1;
    has closed_ok: bool = False;

    can start with Root entry {
        print("=== Phase 3: validate stitched face cycles (explicit cycle guard) ===");
        visit [-->];
    }

    can enter_partition with Partition entry {
        visit [->:Hosts:->];
    }

    can begin_face with Face entry {
        if here.cycle_valid {
            visit [-->];
        } else {
            self.target_face_id = here.face_id;
            self.hop = 0;
            self.visited_obs = [];
            self.start_obs = "";
            self.closed_ok = False;
            visit [->:NextHalfedge:->] else {
                print(f"  face {here.face_id}: empty boundary — invalid");
                visit [-->];
            };
        }
    }

    can walk_halfedge with BorderSpan entry {
        if self.hop == 0 {
            self.start_obs = here.obs_id;
        }
        if here.obs_id in self.visited_obs {
            if here.obs_id == self.start_obs and self.hop >= 3 {
                self.closed_ok = True;
                print(f"  face {self.target_face_id}: closed cycle in {self.hop} hops");
                disengage;
            } else {
                print(f"  face {self.target_face_id}: cycle error — revisits {here.obs_id}");
                disengage;
            }
        } else {
            self.visited_obs.append(here.obs_id);
            self.hop += 1;
            if self.hop > self.max_hops {
                print(f"  face {self.target_face_id}: cycle error — hop limit exceeded");
                disengage;
            } else {
                visit [->:NextHalfedge:->] else {
                    verdict = "open chain" if not self.closed_ok else "closed";
                    print(f"  face {self.target_face_id}: {verdict} ends at {here.obs_id}");
                    disengage;
                };
            }
        }
    }
}

walker GlobalFaceBuilder {
    has next_global_face: int = 1;

    can start with Root entry {
        print("=== Phase 4: assign global face identities ===");
        visit [-->];
    }

    can enter_partition with Partition entry {
        visit [->:Hosts:->];
    }

    can assign_global with Face entry {
        if here.global_face_id == -1 {
            here.global_face_id = self.next_global_face;
            self.next_global_face += 1;
            bounded = "unbounded" if here.is_unbounded else "bounded";
            print(f"  local face {here.face_id} ({here.title}, {bounded}) -> global {here.global_face_id}");
        }
        visit [-->];
    }
}

