    s_beta = RankScore(entity_uuid="bbb", score=0.31);
    s_orphan = RankScore(entity_uuid="ddd", score=0.05);
    rank_layer +>:LayerMember:+> s_alpha;
    rank_layer +>:LayerMember:+> s_beta;
    rank_layer +>:LayerMember:+> s_orphan;

    embed_layer = ResultLayer(family="embedding", generation=3);
    root ++> embed_layer;
    e_ok = EmbeddingRow(
