        visit [->:PeelTo:->] else { disengage; };
    }

    can resolve with Commit entry {
        self.target_commit = here.oid;
        print(f"canonical commit {here.oid}: {here.message}");
        disengage;
    }
}

walker PackResolver {
    has resolved: int = 0;
    has depth: int = 0;
    has max_depth: int = 64;
    has seen: list[str] = [];

    can start with Root entry {
        visit [->:DeltaBase:->] else { disengage; };
    }

    can walk_delta with PackDelta entry {
        for prior in self.seen {
            if prior == here.oid {
                print(f"CYCLE: delta chain blocked at {here.oid}");
                disengage;
            }
        }
        if self.depth >= self.max_depth {
            print(f"DELTA_LIMIT: exceeded at {here.oid}");
            disengage;
        }
        self.seen.append(here.oid);
        self.depth += 1;
        print(f"pack: {here.obj_type} {here.oid} depth={self.depth}");
        visit [->:DeltaBase:->] else { disengage; };
    }

    can materialize_base with Commit entry {
        self.resolved += 1;
        print(f"pack reconstructed -> {here.oid}");
        disengage;
    }
}

walker SafeCheckout {
    has staged: int = 0;
    has rejected: int = 0;

    def is_safe_path(p: str) -> bool {
        if p == "" { return False; }
        if p.startswith("/") { return False; }
        if p.startswith("..") { return False; }
        if ".." in p { return False; }
        return True;
    }

    can start with Root entry {
        visit [-->];
    }

    can enter_commit with Commit entry {
        print(f"materialize tree at {here.oid}");
        visit [->:TreeChild:->] else { disengage; };
    }

    can stage with TreeEntry entry {
        safe = self.is_safe_path(here.rel_path);
        verdict = "STAGED" if safe else "REJECTED";
        if safe {
            self.staged += 1;
            here.rejected = False;
        } else {
            self.rejected += 1;
            here.rejected = True;
        }
        print(f"[{verdict}] {here.rel_path} mode={here.mode}");
        visit [->:TreeChild:->] else { disengage; };
    }
}

