"""Non-current frame scalar mutation: enter an exact caller frame, assign one
scalar, read-back, restore context; same-name scalars stay frame-distinct."""

node Scalar {
    has name: str = "";
    has value: str = "";
    has writable: bool = True;
}

node Frame {
    has frame_id: str = "";
    has frame_class: str = "ordinary";
    has is_current: bool = False;
    has is_stale: bool = False;
}

node DebugContext {
    has current_frame_id: str = "";
}

edge Calls { }
edge Owns { }
edge SuspendedAt { }

walker MutationBroker {
    has target_frame_id: str = "";
    has scalar_name: str = "";
    has new_value: str = "";
    has outcome: str = "pending";
    has refused: bool = False;
    has entered_frame_id: str = "";

    can start with Root entry {
        visit [-->];
    }

    can bind_context with DebugContext entry {
        if here.current_frame_id == "" {
            self.refused = True;
            self.outcome = "refused_no_current_authority";
            disengage;
        }
        visit [->:SuspendedAt:->] else {
            self.refused = True;
            self.outcome = "refused_stale_context_before_dispatch";
            disengage;
        };
    }

    can audit with Frame entry {
        if self.refused {
            disengage;
        }
        if here.is_stale {
            self.refused = True;
            self.outcome = "refused_stale_before_dispatch";
            disengage;
        }
        if here.frame_class != "ordinary" {
            self.refused = True;
            self.outcome = f"refused_class_{here.frame_class}";
            disengage;
        }
        if here.frame_id == self.target_frame_id {
            self.entered_frame_id = here.frame_id;
            visit [->:Owns:->] else {
                self.refused = True;
                self.outcome = "refused_missing_scalar_in_target";
                disengage;
            };
            disengage;
        }
        visit [->:Calls:->] else {
            if self.entered_frame_id == "" and not self.refused {
                self.refused = True;
                self.outcome = "refused_exact_frame_not_found_no_fallback";
            }
            disengage;
        };
    }

    can apply with Scalar entry {
        if self.refused {
            disengage;
        }
        if here.name != self.scalar_name {
            disengage;
        }
        if here.writable == False {
            self.refused = True;
            self.outcome = "assignment_rejected_restoration_proven";
            disengage;
        }
        prior = here.value;
        here.value = self.new_value;
        read_back = here.value;
        if read_back != self.new_value {
            self.outcome = "read_back_failed_authority_invalidated";
            disengage;
        }
        restore_tag = "restored" if self.entered_frame_id != "" else "skipped";
        self.outcome = f"mutated_{prior}_to_{read_back}_{restore_tag}";
        disengage;
    }
}

