}

"""XYG composes GraphForge analytical overlays onto a canonical base graph by UUID join.

Preserves persisted topology, surfaces derived similarity as a distinct overlay,
validates rank-score identity coverage, and blocks dishonest embedding projection.
"""

edge PersistedLink { }

edge LayerMember { }

edge DerivedSimilarity {
    has score: float = 0.0;
}

node CanonicalNode {
    has uuid: str = "";
    has label: str = "";
}

node RankScore {
    has entity_uuid: str = "";
    has score: float = 0.0;
}

node EmbeddingRow {
    has entity_uuid: str = "";
    has coords: list[float] = [];
    has projection_declared: str = "";
}

node ResultLayer {
    has family: str = "";
    has generation: int = 1;
    has catalog_uuids: list[str] = [];
    has catalog_scores: list[float] = [];
    has seen_uuids: list[str] = [];

    def record_score(entity_uuid: str, score: float) {
        self.catalog_uuids.append(entity_uuid);
        self.catalog_scores.append(score);
    }

    def mark_seen(uuid: str) {
        self.seen_uuids.append(uuid);
    }

    def report_orphans() {
        for uid in self.catalog_uuids {
            if uid not in self.seen_uuids {
                print(f"[EXTRA ID] overlay row {uid} has no matching canonical node");
            }
        }
    }
}

walker LayerCataloger {
    has layer: ResultLayer | None = None;

    can start with Root entry {
        visit [-->];
    }

    can capture with ResultLayer entry {
        if here.family != "rank" {
            visit [-->] else { disengage; };
        } else {
            self.layer = here;
            visit [->:LayerMember:->];
        }
    }

    can ingest with RankScore entry {
        if self.layer is not None {
            self.layer.record_score(here.entity_uuid, here.score);
        }
        visit [-->] else { disengage; };
    }
}

walker OverlayComposer {
    has layer: ResultLayer;
    has joined: int = 0;
    has missing: int = 0;
    has visited_topo: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can bind with ResultLayer entry {
        if here.family != "rank" {
            visit [-->] else { disengage; };
        } else {
            visit [-->] else { disengage; };
        }
    }

    can join with CanonicalNode entry {
        if here.uuid in self.visited_topo {
            print(f"[CYCLE GUARD] blocking revisit of {here.uuid}");
            disengage;
        }
        self.visited_topo.append(here.uuid);
        self.layer.mark_seen(here.uuid);
        found = False;
        for (i, uid) in enumerate(self.layer.catalog_uuids) {
            if uid == here.uuid {
                sc = self.layer.catalog_scores[i];
                print(f"[JOIN rank] {here.label} uuid={uid} score={sc}");
                self.joined += 1;
                found = True;
                break;
            }
        }
        if not found {
            print(f"[MISSING ID] canonical {here.uuid} has no rank overlay row");
            self.missing += 1;
        }
        visit [->:PersistedLink:->] else { disengage; };
    }
}

walker DerivedTracer {
    can start with CanonicalNode entry {
        print(f"[DERIVED overlay] similarity from {here.label} (not persisted topology)");
        visit [->:DerivedSimilarity:->] else { disengage; };
    }

    can land with CanonicalNode entry {
        print(f"[DERIVED target] overlay lands on {here.label} — distinct from canonical edges");
        visit [-->] else { disengage; };
    }
}

walker EmbeddingAuditor {
    has blocked: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can open with ResultLayer entry {
        if here.family != "embedding" {
            visit [-->] else { disengage; };
        } else {
            visit [->:LayerMember:->];
        }
    }

    can check with EmbeddingRow entry {
        dim_count = len(here.coords);
        if dim_count > 2 and here.projection_declared == "" {
            print(
                f"[BLOCKED] embedding {here.entity_uuid}: "
                f"{dim_count} dims require honest projection"
            );
            self.blocked += 1;
        } else {
            view_label = (
                here.projection_declared if here.projection_declared != "" else "dims_ok"
            );
            print(f"[OK] embedding {here.entity_uuid}: view={view_label}");
        }
        visit [-->] else { disengage; };
    }
}

with entry {
    n_alpha = CanonicalNode(uuid="aaa", label="Alpha");
    n_beta = CanonicalNode(uuid="bbb", label="Beta");
    n_gamma = CanonicalNode(uuid="ccc", label="Gamma");

    root ++> n_alpha;
