"""Native Git acquisition: peel refs to a canonical commit, resolve pack deltas with cycle guards, and stage tree entries under a safe-path policy."""

node GitRef {
    has name: str = "";
    has oid: str = "";
}

node AnnotatedTag {
    has name: str = "";
    has oid: str = "";
}

node Commit {
    has oid: str = "";
    has message: str = "";
}

node PackDelta {
    has oid: str = "";
    has obj_type: str = "";
}

node TreeEntry {
