"""fe2o3 compiler pipeline: megakernel fusion, persistent task execution, and plan invalidation with cycle guard."""

node Plan {
    has plan_id: str = "";
    has valid: bool = True;
}

node DispatchGraph {
    has graph_id: str = "";
    has fused: bool = False;
}

node GraphOp {
    has op_name: str = "";
    has algorithm_id: str = "";
}

node FusionPlan(Plan) {
    has verified: bool = False;
}

node PersistentPlan(Plan) {
    has scheduler_id: str = "";
    has resident: bool = True;
    has drained: bool = False;
}

node InferenceTask {
    has task_id: str = "";
    has completed: bool = False;

    def kind() -> str {
        return "task";
    }
}

node GemmTask(InferenceTask) {
    has m: int = 0;
    has n: int = 0;
    has k: int = 0;

    override def kind() -> str {
        return "gemm";
    }
}

node AttentionTask(InferenceTask) {
    has seq_len: int = 0;
    has head_dim: int = 0;

    override def kind() -> str {
        return "attention";
    }
}

node MoeTask(InferenceTask) {
    has experts: int = 0;
    has tokens: int = 0;

    override def kind() -> str {
        return "moe";
    }
}

edge FusesOp {
    has phase: int = 0;
}

edge DependsOn {
    has order_key: int = 0;
}

edge RefinesTo { }

edge Schedules { }

edge Invalidates {
    has reason: str = "";
}

walker FusionCompiler {
    has ops_fused: int = 0;

    can start with DispatchGraph entry {
        print(f"[fusion] planning megakernel for graph {here.graph_id}");
        visit [->:FusesOp:->];
        here.fused = True;
        print(f"[fusion] graph {here.graph_id} fused {self.ops_fused} ops into one dispatch");
        visit [->:RefinesTo:->] else { disengage; };
    }

    can absorb with GraphOp entry {
        print(f"  phase fuse: {here.op_name} ({here.algorithm_id})");
        self.ops_fused += 1;
    }

    can certify with FusionPlan entry {
        here.verified = True;
        print(f"[refinement] {here.plan_id} maps fused phases to source graph nodes");
        disengage;
    }
}

walker PersistentWorker {
    has tasks_done: int = 0;

    can start with PersistentPlan entry {
        if not here.resident {
            disengage;
        }
        print(f"[persistent] worker {here.plan_id} online scheduler={here.scheduler_id}");
        visit [->:Schedules:->] else { disengage; };
    }

    can dispatch with GemmTask | AttentionTask | MoeTask entry {
        if here.completed {
            visit [-->];
        } else {
            for dep in [-->:DependsOn:--] here {
                if not dep.completed {
                    status = "blocked" if not dep.completed else "ready";
                    print(f"  {status}: {here.task_id} waits on {dep.task_id}");
                    visit [-->];
                }
            }
            print(f"  acquire -> execute {here.kind()} {here.task_id}");
            here.completed = True;
            self.tasks_done += 1;
            visit [-->];
        }
    }

    can finish with PersistentPlan exit {
        here.drained = True;
        print(f"[drain] {here.plan_id} completed {self.tasks_done} tasks");
    }
}

walker InvalidationAuditor {
    has seen: list[str] = [];

    can start with FusionPlan entry {
        print(f"[invalidation] auditing from fusion plan {here.plan_id}");
        visit [->:Invalidates:->] else { disengage; };
    }

    can cascade with PersistentPlan entry {
        if here.plan_id in self.seen {
            print(f"[cycle] detected revisiting {here.plan_id}; halting cascade");
            disengage;
        }
        self.seen.append(here.plan_id);
        stale_label = "stale" if not here.valid else "valid";
        print(f"[audit] {here.plan_id} currently {stale_label}");
        here.valid = False;
        reason_text = "gfx942 resource contract changed";
        print(f"[invalidate] {here.plan_id}: {reason_text}");
        visit [->:DependsOn:->] else { disengage; };
    }

    can follow with FusionPlan entry {
        if here.plan_id in self.seen {
            print(f"[cycle] detected revisiting {here.plan_id}; halting cascade");
            disengage;
        }
        self.seen.append(here.plan_id);
        here.valid = False;
        print(f"[invalidate] dependent fusion plan {here.plan_id}");
        visit [->:DependsOn:->] else { disengage; };
    }
}

with entry {
    graph = DispatchGraph(graph_id="flash-moe-subgraph");
    graph +>:FusesOp(phase=0):+> GraphOp(op_name="gemm_qkv", algorithm_id="alg-gemm-01");
    graph +>:FusesOp(phase=1):+> GraphOp(op_name="flash_attn", algorithm_id="alg-attn-02");
    graph +>:FusesOp(phase=2):+> GraphOp(op_name="moe_ffn", algorithm_id="alg-moe-03");

    fusion = FusionPlan(plan_id="fp-001");
    graph +>:RefinesTo:+> fusion;

    worker_plan = PersistentPlan(
        plan_id="pp-gfx942",
        scheduler_id="queue-fifo"
    );

    gemm = GemmTask(task_id="t-gemm", m=4096, n=4096, k=4096);
    attn = AttentionTask(task_id="t-attn", seq_len=8192, head_dim=128);
    moe = MoeTask(task_id="t-moe", experts=8, tokens=1024);

    worker_plan +>:Schedules:+> gemm;
    gemm +>:DependsOn(order_key=0):+> attn;
    attn +>:DependsOn(order_key=1):+> moe;

    fusion +>:Invalidates(reason="target rebinding"):+> worker_plan;
    worker_plan +>:DependsOn(order_key=0):+> fusion;

    root ++> graph;
    root ++> worker_plan;

    graph spawn FusionCompiler();
    worker_plan spawn PersistentWorker();
    fusion spawn InvalidationAuditor();
}

"""XYG composes GraphForge analytical overlays onto a canonical base graph by UUID join.

Preserves persisted topology, surfaces derived similarity as a distinct overlay,
validates rank-score identity coverage, and blocks dishonest embedding projection.
"""

edge PersistedLink { }

edge LayerMember { }

edge DerivedSimilarity {
    has score: float = 0.0;
}

node CanonicalNode {
    has uuid: str = "";
    has label: str = "";
}

node RankScore {
    has entity_uuid: str = "";
    has score: float = 0.0;
}

node EmbeddingRow {
    has entity_uuid: str = "";
    has coords: list[float] = [];
    has projection_declared: str = "";
}

node ResultLayer {
    has family: str = "";
    has generation: int = 1;
    has catalog_uuids: list[str] = [];
    has catalog_scores: list[float] = [];
    has seen_uuids: list[str] = [];

    def record_score(entity_uuid: str, score: float) {
        self.catalog_uuids.append(entity_uuid);
        self.catalog_scores.append(score);
    }

    def mark_seen(uuid: str) {
        self.seen_uuids.append(uuid);
    }

    def report_orphans() {
        for uid in self.catalog_uuids {
            if uid not in self.seen_uuids {
                print(f"[EXTRA ID] overlay row {uid} has no matching canonical node");
            }
        }
    }
}

walker LayerCataloger {
    has layer: ResultLayer | None = None;

    can start with Root entry {
        visit [-->];
    }

    can capture with ResultLayer entry {
        if here.family != "rank" {
            visit [-->] else { disengage; };
        } else {
            self.layer = here;
            visit [->:LayerMember:->];
        }
    }

    can ingest with RankScore entry {
        if self.layer is not None {
            self.layer.record_score(here.entity_uuid, here.score);
        }
        visit [-->] else { disengage; };
    }
}

walker OverlayComposer {
    has layer: ResultLayer;
    has joined: int = 0;
    has missing: int = 0;
    has visited_topo: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can bind with ResultLayer entry {
        if here.family != "rank" {
            visit [-->] else { disengage; };
        } else {
            visit [-->] else { disengage; };
        }
    }

    can join with CanonicalNode entry {
        if here.uuid in self.visited_topo {
            print(f"[CYCLE GUARD] blocking revisit of {here.uuid}");
            disengage;
        }
        self.visited_topo.append(here.uuid);
        self.layer.mark_seen(here.uuid);
        found = False;
        for (i, uid) in enumerate(self.layer.catalog_uuids) {
            if uid == here.uuid {
                sc = self.layer.catalog_scores[i];
                print(f"[JOIN rank] {here.label} uuid={uid} score={sc}");
                self.joined += 1;
                found = True;
                break;
            }
        }
        if not found {
            print(f"[MISSING ID] canonical {here.uuid} has no rank overlay row");
            self.missing += 1;
        }
        visit [->:PersistedLink:->] else { disengage; };
    }
}

walker DerivedTracer {
    can start with CanonicalNode entry {
        print(f"[DERIVED overlay] similarity from {here.label} (not persisted topology)");
        visit [->:DerivedSimilarity:->] else { disengage; };
    }

    can land with CanonicalNode entry {
        print(f"[DERIVED target] overlay lands on {here.label} — distinct from canonical edges");
        visit [-->] else { disengage; };
    }
}

walker EmbeddingAuditor {
    has blocked: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can open with ResultLayer entry {
        if here.family != "embedding" {
            visit [-->] else { disengage; };
        } else {
            visit [->:LayerMember:->];
        }
    }

    can check with EmbeddingRow entry {
        dim_count = len(here.coords);
        if dim_count > 2 and here.projection_declared == "" {
            print(
                f"[BLOCKED] embedding {here.entity_uuid}: "
                f"{dim_count} dims require honest projection"
            );
            self.blocked += 1;
        } else {
            view_label = (
                here.projection_declared if here.projection_declared != "" else "dims_ok"
            );
            print(f"[OK] embedding {here.entity_uuid}: view={view_label}");
        }
        visit [-->] else { disengage; };
    }
}

