walker PreAuditReader {
    has visited: list[str] = [];
    has cycle_detected: bool = False;
    has reads: int = 0;

    can start with Root entry {
        print("=== Mandatory pre-audit ledger read ===");
        visit [-->];
    }

    can scan_audit with AuditEntry entry {
        if here.item_id in self.visited {
            self.cycle_detected = True;
            print(f"CYCLE FAIL-CLOSED at audit {here.item_id}");
            disengage;
        }
        self.visited.append(here.item_id);
        self.reads += 1;
        print(
            f"[AUDIT] {here.item_id} — {here.title} "
            f"({here.status}) @ {here.baseline_sha}"
        );
        visit [->:MustReadBefore:->];
        visit [->:Records:->];
    }

    can scan_decision with Decision entry {
        if here.item_id in self.visited {
            self.cycle_detected = True;
            print(f"CYCLE FAIL-CLOSED at decision {here.item_id}");
            disengage;
        }
        self.visited.append(here.item_id);
        self.reads += 1;
        print(f"[DECISION] {here.item_id}: {here.verdict} — {here.summary}");
        visit [->:Validates:->];
    }

    can cite with Evidence entry {
        print(f"  evidence: {here.kind} {here.ref}");
    }
}

walker SupersessionGuard {
    can start with Root entry {
        print("=== Supersession guard (no DEFER/REJECT re-proposal) ===");
        visit [-->];
    }

    can review with Decision entry {
        if here.verdict == "ACCEPTED" {
            print(f"Active decision {here.item_id} supersedes:");
            visit [->:Supersedes:->];
        }
        visit [-->];
    }

    can mark_retired with Decision entry {
        block_label = "BLOCKED" if here.verdict != "ACCEPTED" else "NOTED";
        print(
            f"  {block_label}: {here.item_id} ({here.verdict}) "
            f"— do not re-propose without new evidence"
        );
    }
}

