"""No-publish rehearsal oracle: audit reachable workflow authority, compare external public surfaces, and prove predecessor failure blocks publication."""

node ReachableNode {
    def is_blocking() -> bool {
        return False;
    }
}

node WorkflowNode(ReachableNode) {
    has name: str = "";
    has classification: str = "read_only";
    has eligible: bool = True;

    override def is_blocking() -> bool {
        return self.classification == "public_mutation_authorized"
            or self.classification == "not_proven";
    }
}

node PublisherSecret(ReachableNode) {
    has secret_name: str = "";
    has inherited: bool = False;

    override def is_blocking() -> bool {
        return True;
    }
}

node PublicSurface {
    has channel: str = "";
    has before_hash: str = "";
    has after_hash: str = "";
    has observer_status: str = "observed";
}

node RehearsalCandidate {
    has digest: str = "";
    has publish_authorized: bool = False;
    has published_channels: list[str] = [];
    has release_cut: bool = False;
    has predecessor_failed: bool = False;
}

edge Calls { }
edge Observes { has phase: str = "baseline"; }

walker AuthorityAuditor {
    has preflight_clear: bool = True;
    has nodes_seen: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can begin with RehearsalCandidate entry {
        print(f"=== Authority preflight ({here.digest}) ===");
        if here.publish_authorized {
            print("FAIL: publish_authorized must be false");
            self.preflight_clear = False;
        }
        visit [->:Calls:->] else { disengage; };
    }

    can inspect with WorkflowNode | PublisherSecret entry {
        self.nodes_seen += 1;
        tag = "BLOCK" if here.is_blocking() else "OK";
        print(f"[{tag}] reachable {here}");
        if here.is_blocking() {
            self.preflight_clear = False;
        }
        visit [->:Calls:->] else { visit [-->] else { disengage; }; };
    }
}

walker PublicStateGuard {
    has surfaces_stable: bool = True;
    has surfaces_checked: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can begin with RehearsalCandidate entry {
        print("=== Public-state before/after comparison ===");
        visit [->:Observes:->] else { disengage; };
    }

    can compare with PublicSurface entry {
        self.surfaces_checked += 1;
        if here.observer_status == "not_applicable" {
            print(f"SKIP: {here.channel} (topology deferred)");
        } elif here.before_hash != here.after_hash {
            print(f"DRIFT: {here.channel} changed");
            self.surfaces_stable = False;
        } else {
            print(f"STABLE: {here.channel} unchanged ({here.before_hash})");
        }
        visit [->:Observes:->] else { disengage; };
    }
}

walker FailureProof {
    has failure_injected: bool = False;
    has no_publish_dispatch: bool = True;

    can start with Root entry {
        visit [-->];
    }

    can begin with RehearsalCandidate entry {
        self.failure_injected = here.predecessor_failed;
        print("=== Deliberate predecessor-failure proof ===");
        visit [->:Calls:->] else { disengage; };
    }

    can prove with WorkflowNode entry {
        if here.name == "sbom" and self.failure_injected {
            print("Injected SBOM checksum mismatch — archive ineligible");
            here.eligible = False;
        }
        if here.name == "publish" {
            if here.eligible {
                print("FAIL: publish job became eligible");
                self.no_publish_dispatch = False;
            } else {
                print("PASS: no downstream publish dispatch");
            }
        }
        visit [->:Calls:->] else { disengage; };
    }
}

with entry {
    rehearsal = RehearsalCandidate(
        digest="sha256:deadbeef",
        publish_authorized=False,
        published_channels=[],
        release_cut=False,
        predecessor_failed=True
    );

    lint = WorkflowNode(name="lint", classification="read_only");
    build = WorkflowNode(name="build", classification="artifact_local_write");
    sbom = WorkflowNode(name="sbom", classification="candidate_evidence_write");
    publish = WorkflowNode(
        name="publish",
        classification="public_mutation_unreachable",
        eligible=False
    );

    gh_tags = PublicSurface(
        channel="github_tags", before_hash="v1.0.0", after_hash="v1.0.0"
    );
    crates = PublicSurface(
        channel="crates.io", before_hash="0.42.0", after_hash="0.42.0"
    );
    vsix = PublicSurface(
        channel="open_vsx", before_hash="2.1.0", after_hash="2.1.0"
    );
    brew = PublicSurface(
        channel="homebrew",
        before_hash="",
        after_hash="",
        observer_status="not_applicable"
    );

    root ++> rehearsal;
    rehearsal +>:Calls:+> lint;
    lint +>:Calls:+> build;
    build +>:Calls:+> sbom;
    sbom +>:Calls:+> publish;

    rehearsal +>:Observes(phase="before"):+> gh_tags;
    gh_tags +>:Observes(phase="after"):+> crates;
    crates +>:Observes(phase="after"):+> vsix;
    vsix +>:Observes(phase="after"):+> brew;

    auditor = AuthorityAuditor();
    root spawn auditor;
    guard = PublicStateGuard();
    root spawn guard;
    proof = FailureProof();
    root spawn proof;

    oracle_green = (
        auditor.preflight_clear
        and guard.surfaces_stable
        and proof.no_publish_dispatch
    );
    label = "GREEN" if oracle_green else "RED";
    print(f"=== No-publish oracle verdict: {label} ===");
    print(
        f"authority_nodes={auditor.nodes_seen} "
        f"surfaces={guard.surfaces_checked}"
    );
}

