    has local_effects: str = "";
    has closure_effects: str = "";
    has prev_closure: str = "";
}

node RecComponent {
    has name: str = "";
}

node ExternalCallee {
    has name: str = "";
    has summary_effects: str = "";
}

edge MemberOf { }

edge InternalCall {
    has callsite: str = "";
}

edge ExternalCall { }

walker MonotoneClosure {
    has max_rounds: int = 8;
    has round: int = 0;
    has changed: bool = True;
    has active_caller: MemberCallable | None = None;

    can start with Root entry {
        visit [-->];
    }

    can fixpoint with RecComponent entry {
        while self.round < self.max_rounds and self.changed {
            self.round += 1;
            self.changed = False;
            print(f"[worklist] round {self.round} component={here.name}");
            visit [->:MemberOf:->];
        }
        label = "semantic_closure_stable" if not self.changed else "recursive_convergence_not_proven";
        print(f"[result] {here.name}: {label} after {self.round} rounds");
        disengage;
    }

    can member_pass with MemberCallable entry {
        caller = self.active_caller;
        if caller is not None {
            merged = f"{caller.closure_effects}|{here.closure_effects}";
            if merged != caller.closure_effects {
                caller.closure_effects = merged;
            }
            disengage;
        }
        prior = here.prev_closure;
        here.closure_effects = here.local_effects;
        self.active_caller = here;
        visit [->:InternalCall:->] else { disengage; }
        visit [->:ExternalCall:->] else { disengage; }
        self.active_caller = None;
        here.prev_closure = here.closure_effects;
        if here.closure_effects != prior {
            self.changed = True;
        }
    }

    can absorb_external with ExternalCallee entry {
        caller = self.active_caller;
        if caller is None {
            disengage;
        }
        merged = f"{caller.closure_effects}|{here.summary_effects}";
        if merged != caller.closure_effects {
            caller.closure_effects = merged;
        }
        disengage;
    }
}

with entry {
    comp = RecComponent(name="parse_scc");
    parse_fn = MemberCallable(name="parse", local_effects="read");
    expr_fn = MemberCallable(name="parse_expr", local_effects="read,write");
    token = ExternalCallee(name="token_read", summary_effects="io");

    root ++> comp;
    comp +>:MemberOf:+> parse_fn;
    comp +>:MemberOf:+> expr_fn;
    parse_fn +>:InternalCall(callsite="body"):+> expr_fn;
    expr_fn +>:InternalCall(callsite="tail"):+> parse_fn;
    parse_fn +>:ExternalCall:+> token;

    root spawn MonotoneClosure(max_rounds=8);

    print(f"  parse      closure={parse_fn.closure_effects}");
    print(f"  parse_expr closure={expr_fn.closure_effects}");
    print(f"  external   summary={token.summary_effects} (unchanged)");
}

"""No-publish rehearsal oracle: audit reachable workflow authority, compare external public surfaces, and prove predecessor failure blocks publication."""

node ReachableNode {
    def is_blocking() -> bool {
        return False;
    }
}

node WorkflowNode(ReachableNode) {
    has name: str = "";
    has classification: str = "read_only";
    has eligible: bool = True;

    override def is_blocking() -> bool {
        return self.classification == "public_mutation_authorized"
            or self.classification == "not_proven";
    }
}

node PublisherSecret(ReachableNode) {
    has secret_name: str = "";
    has inherited: bool = False;

    override def is_blocking() -> bool {
        return True;
    }
}

node PublicSurface {
    has channel: str = "";
    has before_hash: str = "";
    has after_hash: str = "";
    has observer_status: str = "observed";
}

node RehearsalCandidate {
    has digest: str = "";
    has publish_authorized: bool = False;
    has published_channels: list[str] = [];
    has release_cut: bool = False;
    has predecessor_failed: bool = False;
}

edge Calls { }
edge Observes { has phase: str = "baseline"; }

walker AuthorityAuditor {
    has preflight_clear: bool = True;
    has nodes_seen: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can begin with RehearsalCandidate entry {
        print(f"=== Authority preflight ({here.digest}) ===");
        if here.publish_authorized {
            print("FAIL: publish_authorized must be false");
            self.preflight_clear = False;
        }
        visit [->:Calls:->] else { disengage; };
    }

    can inspect with WorkflowNode | PublisherSecret entry {
        self.nodes_seen += 1;
        tag = "BLOCK" if here.is_blocking() else "OK";
        print(f"[{tag}] reachable {here}");
        if here.is_blocking() {
            self.preflight_clear = False;
        }
        visit [->:Calls:->] else { visit [-->] else { disengage; }; };
    }
}

walker PublicStateGuard {
    has surfaces_stable: bool = True;
    has surfaces_checked: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can begin with RehearsalCandidate entry {
        print("=== Public-state before/after comparison ===");
        visit [->:Observes:->] else { disengage; };
    }

    can compare with PublicSurface entry {
        self.surfaces_checked += 1;
        if here.observer_status == "not_applicable" {
            print(f"SKIP: {here.channel} (topology deferred)");
        } elif here.before_hash != here.after_hash {
            print(f"DRIFT: {here.channel} changed");
            self.surfaces_stable = False;
        } else {
            print(f"STABLE: {here.channel} unchanged ({here.before_hash})");
        }
        visit [->:Observes:->] else { disengage; };
    }
}

walker FailureProof {
    has failure_injected: bool = False;
    has no_publish_dispatch: bool = True;

    can start with Root entry {
        visit [-->];
    }

    can begin with RehearsalCandidate entry {
        self.failure_injected = here.predecessor_failed;
        print("=== Deliberate predecessor-failure proof ===");
        visit [->:Calls:->] else { disengage; };
    }

    can prove with WorkflowNode entry {
        if here.name == "sbom" and self.failure_injected {
            print("Injected SBOM checksum mismatch — archive ineligible");
            here.eligible = False;
        }
        if here.name == "publish" {
            if here.eligible {
                print("FAIL: publish job became eligible");
                self.no_publish_dispatch = False;
            } else {
                print("PASS: no downstream publish dispatch");
            }
        }
        visit [->:Calls:->] else { disengage; };
    }
}

with entry {
    rehearsal = RehearsalCandidate(
        digest="sha256:deadbeef",
        publish_authorized=False,
        published_channels=[],
        release_cut=False,
        predecessor_failed=True
    );

    lint = WorkflowNode(name="lint", classification="read_only");
    build = WorkflowNode(name="build", classification="artifact_local_write");
    sbom = WorkflowNode(name="sbom", classification="candidate_evidence_write");
    publish = WorkflowNode(
        name="publish",
        classification="public_mutation_unreachable",
        eligible=False
    );

    gh_tags = PublicSurface(
        channel="github_tags", before_hash="v1.0.0", after_hash="v1.0.0"
    );
    crates = PublicSurface(
        channel="crates.io", before_hash="0.42.0", after_hash="0.42.0"
    );
    vsix = PublicSurface(
        channel="open_vsx", before_hash="2.1.0", after_hash="2.1.0"
    );
    brew = PublicSurface(
        channel="homebrew",
        before_hash="",
        after_hash="",
        observer_status="not_applicable"
    );

    root ++> rehearsal;
    rehearsal +>:Calls:+> lint;
    lint +>:Calls:+> build;
    build +>:Calls:+> sbom;
    sbom +>:Calls:+> publish;

    rehearsal +>:Observes(phase="before"):+> gh_tags;
    gh_tags +>:Observes(phase="after"):+> crates;
    crates +>:Observes(phase="after"):+> vsix;
    vsix +>:Observes(phase="after"):+> brew;

    auditor = AuthorityAuditor();
    root spawn auditor;
    guard = PublicStateGuard();
    root spawn guard;
    proof = FailureProof();
    root spawn proof;

    oracle_green = (
        auditor.preflight_clear
        and guard.surfaces_stable
        and proof.no_publish_dispatch
    );
    label = "GREEN" if oracle_green else "RED";
    print(f"=== No-publish oracle verdict: {label} ===");
    print(
        f"authority_nodes={auditor.nodes_seen} "
        f"surfaces={guard.surfaces_checked}"
    );
}

"""fe2o3 compiler pipeline: megakernel fusion, persistent task execution, and plan invalidation with cycle guard."""

node Plan {
    has plan_id: str = "";
    has valid: bool = True;
}

node DispatchGraph {
    has graph_id: str = "";
    has fused: bool = False;
}

node GraphOp {
    has op_name: str = "";
    has algorithm_id: str = "";
}

node FusionPlan(Plan) {
    has verified: bool = False;
}

node PersistentPlan(Plan) {
    has scheduler_id: str = "";
    has resident: bool = True;
    has drained: bool = False;
}

node InferenceTask {
    has task_id: str = "";
    has completed: bool = False;

    def kind() -> str {
        return "task";
    }
}

node GemmTask(InferenceTask) {
    has m: int = 0;
    has n: int = 0;
    has k: int = 0;

    override def kind() -> str {
        return "gemm";
    }
}

node AttentionTask(InferenceTask) {
    has seq_len: int = 0;
    has head_dim: int = 0;

    override def kind() -> str {
        return "attention";
    }
}

node MoeTask(InferenceTask) {
    has experts: int = 0;
    has tokens: int = 0;

    override def kind() -> str {
        return "moe";
    }
}

edge FusesOp {
    has phase: int = 0;
}

edge DependsOn {
    has order_key: int = 0;
}

edge RefinesTo { }

edge Schedules { }

edge Invalidates {
    has reason: str = "";
}

walker FusionCompiler {
    has ops_fused: int = 0;

    can start with DispatchGraph entry {
        print(f"[fusion] planning megakernel for graph {here.graph_id}");
        visit [->:FusesOp:->];
        here.fused = True;
        print(f"[fusion] graph {here.graph_id} fused {self.ops_fused} ops into one dispatch");
        visit [->:RefinesTo:->] else { disengage; };
    }

    can absorb with GraphOp entry {
        print(f"  phase fuse: {here.op_name} ({here.algorithm_id})");
        self.ops_fused += 1;
    }

    can certify with FusionPlan entry {
        here.verified = True;
        print(f"[refinement] {here.plan_id} maps fused phases to source graph nodes");
        disengage;
    }
}

walker PersistentWorker {
    has tasks_done: int = 0;

    can start with PersistentPlan entry {
        if not here.resident {
            disengage;
        }
        print(f"[persistent] worker {here.plan_id} online scheduler={here.scheduler_id}");
        visit [->:Schedules:->] else { disengage; };
    }

    can dispatch with GemmTask | AttentionTask | MoeTask entry {
        if here.completed {
            visit [-->];
        } else {
            blocked = False;
            for dep in here[->:DependsOn:->] {
                if not dep.completed {
                    blocked = True;
                    print(f"  blocked: {here.task_id} waits on {dep.task_id}");
                }
            }
            if blocked {
                visit [-->];
            } else {
                print(f"  acquire -> execute {here.kind()} {here.task_id}");
                here.completed = True;
                self.tasks_done += 1;
                visit [-->];
            }
        }
    }

    can finish with PersistentPlan exit {
        here.drained = True;
        print(f"[drain] {here.plan_id} completed {self.tasks_done} tasks");
    }
}

walker InvalidationAuditor {
    has seen: list[str] = [];

    can start with FusionPlan entry {
        print(f"[invalidation] auditing from fusion plan {here.plan_id}");
        visit [->:Invalidates:->] else { disengage; };
    }

    can cascade with PersistentPlan entry {
        if here.plan_id in self.seen {
            print(f"[cycle] detected revisiting {here.plan_id}; halting cascade");
            disengage;
        }
        self.seen.append(here.plan_id);
        stale_label = "stale" if not here.valid else "valid";
        print(f"[audit] {here.plan_id} currently {stale_label}");
        here.valid = False;
        reason_text = "gfx942 resource contract changed";
        print(f"[invalidate] {here.plan_id}: {reason_text}");
        visit [->:DependsOn:->] else { disengage; };
    }

    can follow with FusionPlan entry {
        if here.plan_id in self.seen {
            print(f"[cycle] detected revisiting {here.plan_id}; halting cascade");
            disengage;
        }
        self.seen.append(here.plan_id);
        here.valid = False;
        print(f"[invalidate] dependent fusion plan {here.plan_id}");
        visit [->:DependsOn:->] else { disengage; };
    }
}

with entry {
    graph = DispatchGraph(graph_id="flash-moe-subgraph");
    graph +>:FusesOp(phase=0):+> GraphOp(op_name="gemm_qkv", algorithm_id="alg-gemm-01");
    graph +>:FusesOp(phase=1):+> GraphOp(op_name="flash_attn", algorithm_id="alg-attn-02");
    graph +>:FusesOp(phase=2):+> GraphOp(op_name="moe_ffn", algorithm_id="alg-moe-03");

    fusion = FusionPlan(plan_id="fp-001");
    graph +>:RefinesTo:+> fusion;

    worker_plan = PersistentPlan(
        plan_id="pp-gfx942",
        scheduler_id="queue-fifo"
    );

    gemm = GemmTask(task_id="t-gemm", m=4096, n=4096, k=4096);
    attn = AttentionTask(task_id="t-attn", seq_len=8192, head_dim=128);
    moe = MoeTask(task_id="t-moe", experts=8, tokens=1024);

    worker_plan +>:Schedules:+> gemm;
    gemm +>:DependsOn(order_key=0):+> attn;
    attn +>:DependsOn(order_key=1):+> moe;

    fusion +>:Invalidates(reason="target rebinding"):+> worker_plan;
    worker_plan +>:DependsOn(order_key=0):+> fusion;

    root ++> graph;
    root ++> worker_plan;

    graph spawn FusionCompiler();
    worker_plan spawn PersistentWorker();
    fusion spawn InvalidationAuditor();
}

"""Wayfinder control plane: bounded recursive delegation, local skill dispatch, and evidence-gated task promotion."""

edge IssuesContract {
    has contract_id: str = "";
}

edge EndowedWith { }

edge BindsTask { }

node Controller {
    has name: str = "";
}

node Agent {
    has name: str = "";
    has depth: int = 0;
    has max_depth: int = 3;
    has status: str = "idle";
}

node Skill {
    has title: str = "";
    has risk: str = "low";
    has available: bool = True;
}

node Task {
    has goal: str = "";
    has required_skill: str = "";
    has attested: bool = False;
    has promoted: bool = False;
}

walker Wayfinder {
    has seen: list[str] = [];

    can start with Root entry {
        print("=== Wayfinder: skill-aware fleet dispatch ===");
        visit [-->];
    }

    can orient with Controller entry {
        print(f"Controller [{here.name}] scanning delegation tree");
        visit [->:IssuesContract:->] else { disengage; };
    }

    can delegate with Agent entry {
        if here.name in self.seen {
            print(f"[CYCLE] blocked re-entry to agent {here.name}");
            disengage;
        }
        self.seen.append(here.name);
        if here.depth >= here.max_depth {
            print(f"[DEPTH] {here.name} at budget {here.max_depth}, stopping branch");
            disengage;
        }
        status_label = "ACTIVE" if here.status == "active" else "IDLE";
        print(f"[{status_label}] {here.name} depth={here.depth}");
        visit [->:EndowedWith:->];
        visit [->:IssuesContract:->] else { disengage; };
    }

    can match_skill with Skill entry {
        avail = "OK" if here.available else "OUT";
        print(f"  local skill [{avail}] {here.title} (risk={here.risk})");
    }
}

walker EvidenceArbiter {
    has promotions: int = 0;

    can start with Root entry {
        print("=== EvidenceArbiter: promote only verified results ===");
        visit [-->];
    }

    can scan with Controller entry {
        visit [->:BindsTask:->] else { disengage; };
    }

    can judge with Task entry {
        if here.attested {
            here.promoted = True;
            self.promotions += 1;
            verdict = "PROMOTED";
            label = "fresh attestation";
        } else {
            verdict = "HELD";
            label = "stale cache / no attestation";
        }
        print(f"[{verdict}] {here.goal} ({label})");
    }
}

with entry {
    ctrl = Controller(name="Primary");
    root ++> ctrl;

    lead = Agent(name="lead-1", status="active", depth=0);
    worker = Agent(name="worker-2", depth=1);
    specialist = Agent(name="spec-3", depth=2);

    ctrl +>:IssuesContract(contract_id="DC-100"):+> lead;
    lead +>:IssuesContract(contract_id="DC-101"):+> worker;
    worker +>:IssuesContract(contract_id="DC-102"):+> specialist;
    specialist +>:IssuesContract(contract_id="DC-cycle"):+> lead;

    review = Skill(title="code-review", risk="low");
    dispatch = Skill(title="local-dispatch", risk="low");
    lead +>:EndowedWith:+> review;
    worker +>:EndowedWith:+> dispatch;

    verified_job = Task(
        goal="assistance.local-dispatch PR review",
        required_skill="code-review",
        attested=True,
    );
    held_job = Task(
        goal="unverified refactor",
        required_skill="refactor",
        attested=False,
    );
    ctrl +>:BindsTask:+> verified_job;
    ctrl +>:BindsTask:+> held_job;

    root spawn Wayfinder();
    arbiter = EvidenceArbiter();
    root spawn arbiter;
    print(f"EvidenceArbiter promoted {arbiter.promotions} task(s)");
}

