walker GtInstall {
    has deadline_units: int = 30;
    has outcome: str = "ok";

    can start with Root entry {
        visit [-->];
    }

    can install with HqDatabase entry {
        print(
            f"gt install: opening hq={here.title} "
            f"prefix={here.issue_prefix} schema=v{here.schema_version} "
            f"deadline={self.deadline_units}s"
        );
        visit [->:PendingOn:->] else {
            print("gt install: no pending migrations");
            disengage;
        };
    }

    can run_migration with SchemaMigration entry {
        if not here.available {
            visit [-->];
            return;
        }
        if not here.uses_recursive {
            print(f"migrate: skip non-recursive {here.title}");
            visit [-->];
            return;
        }
        print(f"migrate: applying {here.title} (v{here.year})");
        worker = Migration0059(deadline_units=self.deadline_units);
        here spawn worker;
        if worker.timed_out {
            self.outcome = (
                f"initializing HQ Dolt database: ensuring issue_prefix for "
                f"existing database: opening beads database: failed to "
                f"initialize schema: context deadline exceeded "
                f"(staging_dirty={worker.staging_dirty}, "
                f"work={worker.work_units}, recomputed={worker.recomputed})"
            );
            print(f"FAIL: {self.outcome}");
            disengage;
        }
