"""KohakuHub #101: unbounded repo-wide metadata scans time out; bounded commit paths stay fast."""

node Repo {
    has name: str = "";
    has branch_objects: int = 0;
    has payload_bytes: int = 0;
}

node TreeEntry {
    has path: str = "";
}

node Directory(TreeEntry) {
    has descendant_count: int = 0;
}

node FileObject(TreeEntry) {
    has payload_bytes: int = 0;
}

node Commit {
    has message: str = "";
    has changed_path_count: int = 0;
}

edge Hosts { }
edge Contains { }
edge ChangedIn { }

walker RepoWideMetadataAPI {
    has objects_seen: int = 0;
    has scan_budget: int = 10;
    has timed_out: bool = False;
    has total_bytes: int = 0;

    can start with Repo entry {
        print("paths-info(expand=true): unbounded descendant enumeration");
        print(
            f"revision info for {here.name}: "
            f"{here.branch_objects} branch objects, "
            f"{here.payload_bytes} logical payload bytes"
        );
        visit [->:Hosts:->] else { disengage; };
    }

    can expand_dir with Directory entry {
        if self.objects_seen >= self.scan_budget {
            self.timed_out = True;
            print(
                f"[HTTP 504] Gateway timeout after ~60s while scanning "
                f"{self.objects_seen} objects (unbounded repo walk)"
            );
            disengage;
        }
        self.objects_seen += 1;
        visit [->:Contains:->] else { disengage; };
    }

    can expand_file with FileObject entry {
        if self.objects_seen >= self.scan_budget {
            self.timed_out = True;
            print(
                f"[HTTP 504] Gateway timeout after ~60s while scanning "
                f"{self.objects_seen} objects (unbounded repo walk)"
            );
            disengage;
        }
        self.objects_seen += 1;
        self.total_bytes += here.payload_bytes;
        visit [->:Contains:->] else { disengage; };
    }
}

walker RecentCommitPaths {
    has paths_read: int = 0;

    can start with Commit entry {
        print("bounded commit delta: O(changed paths) only");
        print(
            f"recent commit: {here.message} "
            f"({here.changed_path_count} changed paths)"
