"""Cloud repository audit: model audit cycles and findings as a graph and walk health checks."""

node Repository {
    has name: str = "";
    has commit: str = "";
}

node AuditCycle {
    has cycle_name: str = "";
    has status: str = "";
}

node Finding {
    has title: str = "";
    has severity: str = "";
    has category: str = "";
}

edge RunsCycle { }

edge ReportsFinding { }

walker CloudAuditor {
    has high_count: int = 0;
    has medium_count: int = 0;
    has low_count: int = 0;
    has blocked: bool = False;

    can start with Root entry {
        visit [-->];
    }

    can audit_repo with Repository entry {
        print(f"Auditing {here.name} @ {here.commit[:12]}");
        visit [->:RunsCycle:->];
    }

    can run_cycle with AuditCycle entry {
        label = "PASS" if here.status == "PASS" else "FINDINGS";
        print(f"  [{label}] cycle: {here.cycle_name}");
        visit [->:ReportsFinding:->];
    }

    can triage with Finding entry {
        if here.severity == "HIGH" {
            self.high_count += 1;
            if here.category == "tests" or here.category == "dependencies" {
                self.blocked = True;
            }
        } elif here.severity == "MEDIUM" {
            self.medium_count += 1;
        } else {
            self.low_count += 1;
        }
        print(f"    [{here.severity}] {here.title} ({here.category})");
        visit [-->] else { disengage; };
    }
}

