"""GitHub Actions evidence normalization, receipt v2 construction, and lifecycle gate auditing."""

node TaskMilestone {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has task_id: int = 0;
    has complete: bool = False;
}

node ActionsRun {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has repository_id: str = "";
    has workflow_id: str = "";
    has run_id: str = "";
    has attempt: int = 0;
    has head_sha: str = "";
    has conclusion: str = "";
    has classification: str = "";
    has stale_epoch: bool = False;
    has wrong_sha: bool = False;
    has policy_mismatch: bool = False;
    has platform_outage: bool = False;
    has no_slow_impact: bool = False;
    has normalized: bool = False;

    def logical_key() -> str {
        return f"github-actions:{self.repository_id}:{self.workflow_id}:{self.run_id}:{self.attempt}:{self.head_sha}";
    }

    def exclusion_reason() -> str {
        if self.platform_outage {
            return "platform outage";
        }
        if self.stale_epoch {
            return "stale epoch";
        }
        if self.wrong_sha {
            return "wrong SHA";
        }
        if self.policy_mismatch {
            return "policy hash mismatch";
        }
        return "contract-invalid";
    }

    def disposition() -> str {
        if self.platform_outage or self.stale_epoch or self.wrong_sha or self.policy_mismatch {
            return "excluded";
        }
        return "recorded-non-cycle";
    }
}

node MeasurementEvidence {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has logical_key: str = "";
    has classification: str = "";
    has disposition: str = "";
    has exclusion_reason: str = "";
    has evidence_source: str = "github-actions";
}

node LifecycleGate {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has gate_name: str = "";
    has evidence_source: str = "";
    has passed: bool = False;
    has accepted: bool = False;
}

edge Prerequisite { }
edge NormalizesTo { }
edge BuildsReceipt { }
edge GateEvidence { }

walker TaskReadiness {
    has task11_ready: bool = True;

    can start with Root entry {
        visit [-->];
    }

    can assess with TaskMilestone entry {
        if here.task_id != 11 {
            visit [-->];
        } else {
            self.task11_ready = True;
            visit [->:Prerequisite:->] else {
                print("[TASK 11] no prerequisite edges found");
                visit [-->];
            };
        }
    }

    can require with TaskMilestone entry {
        if not here.complete {
            self.task11_ready = False;
            print(f"[BLOCKED] prerequisite task {here.task_id} ({here.title}) incomplete");
        }
        visit [-->] else {
            disengage;
        };
    }
}

walker ActionsAdapter {
    has adapted: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can adapt with ActionsRun entry {
        if here.normalized {
            visit [-->];
        } else {
            class_label = here.classification;
            if here.no_slow_impact {
                class_label = "no-slow-impact";
            }
            evidence = MeasurementEvidence(
                title=here.title,
                logical_key=here.logical_key(),
                classification=class_label,
                disposition=here.disposition(),
                exclusion_reason=here.exclusion_reason() if here.disposition() == "excluded" else ""
            );
            here +>:NormalizesTo:+> evidence;
            here.normalized = True;
            self.adapted += 1;
            print(f"[ADAPT] {here.logical_key()} -> {class_label} ({here.disposition()})");
            visit [-->];
        }
    }
}

walker ReceiptBuilder {
    has built: int = 0;
    has excluded: int = 0;
    has seen_keys: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can traverse with ActionsRun entry {
        visit [->:NormalizesTo:->] else {
            visit [-->];
        };
    }

    can validate with MeasurementEvidence entry {
        if here.logical_key in self.seen_keys {
            here.disposition = "recorded-non-cycle";
            print(f"[CYCLE GUARD] revisiting {here.logical_key}");
            disengage;
        }
        self.seen_keys.append(here.logical_key);

        if here.disposition == "excluded" {
            self.excluded += 1;
            print(f"[EXCLUDED] {here.logical_key}: {here.exclusion_reason}");
            visit [-->];
        } else {
            receipt_id = here.logical_key;
            here +>:BuildsReceipt:+> MeasurementEvidence(
                title=f"receipt-v2:{receipt_id}",
                logical_key=receipt_id,
                classification=here.classification,
                disposition="recorded-non-cycle",
                evidence_source="github-actions"
            );
            self.built += 1;
            print(f"[RECEIPT v2] {receipt_id} class={here.classification}");
            visit [-->];
        }
    }
}

walker LifecycleAuditor {
    has passed: int = 0;
    has failed: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can audit with LifecycleGate entry {
        source_ok = here.evidence_source == "github-actions" or here.evidence_source == "agent";
        here.accepted = source_ok and here.passed;
        if here.accepted {
            self.passed += 1;
            verdict = "PASS";
        } else {
            self.failed += 1;
            verdict = "FAIL";
