"""Foundry exact registry resolution: mutable tags become exact candidates, artifacts are integrity-verified and content-addressed, and transactions pin digest-bound inputs so apply cannot substitute drifted content."""

node PackageRequest {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has tag: str = "latest";
}

node ExactCandidate {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has version: str = "";
    has integrity: str = "";
    has evidence_state: str = "observed-unverified";
}

node Artifact {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has digest: str = "";
    has verified: bool = False;
}

node Transaction {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has tx_id: str = "";
    has proposal_digest: str = "";
}

edge ResolvesTo { }
edge StagedAs { }
edge PinnedBy { }

walker RegistryResolver {
    has resolved: int = 0;
    has seen_digests: list[str] = [];
    has phase: str = "discover";

    can start with Root entry {
        visit [-->];
    }

    can resolve with PackageRequest entry {
        self.phase = "discover";
        print(f"[RESOLVE] {here.title}@{here.tag} (mutable tag -> exact candidate)");
        visit [->:ResolvesTo:->] else { disengage; };
    }

    can handle with ExactCandidate entry {
        if self.phase == "discover" {
            label = "REVIEWED" if here.evidence_state == "reviewed" else "OBSERVED-UNVERIFIED";
            print(f"  exact: {here.title}@{here.version} [{label}] integrity={here.integrity}");
            self.resolved += 1;
            self.phase = "promote";
            visit [->:StagedAs:->] else { disengage; };
        } else {
            if here.evidence_state == "observed-unverified" {
                here.evidence_state = "reviewed";
                print(f"  PROMOTED: {here.title}@{here.version} discovery -> reviewed evidence");
            }
            self.phase = "discover";
            visit [-->] else { disengage; };
        }
    }

    can admit with Artifact entry {
        if here.digest in self.seen_digests {
            print(f"  CYCLE blocked at digest {here.digest[:16]}");
            disengage;
        }
        self.seen_digests.append(here.digest);
        if here.digest == "" {
            here.verified = False;
            print("  REJECT: empty digest — partial download not admitted");
        } else {
            here.verified = True;
            print(f"  ADMIT: content-addressed artifact {here.digest[:16]}... integrity OK");
        }
        visit [<--:StagedAs:<-];
    }
}

walker TransactionGuard {
    has pinned_digests: list[str] = [];
    has blocked: bool = False;

    can start with Root entry {
        visit [-->[?:Transaction]];
    }

    can stage with Transaction entry {
        self.pinned_digests = [];
        self.blocked = False;
        print(f"[TX {here.tx_id}] pinning artifacts for proposal {here.proposal_digest[:16]}...");
        visit [->:PinnedBy:->] else { disengage; };
        if self.blocked {
            print(f"[TX {here.tx_id}] APPLY BLOCKED — unverified artifact");
        } elif here.proposal_digest in self.pinned_digests {
            print(f"[TX {here.tx_id}] APPLY OK — exact artifact locked, no tag substitution");
        } else {
            print(f"[TX {here.tx_id}] APPLY BLOCKED — digest mismatch after approval");
        }
    }

    can pin with Artifact entry {
        if not here.verified {
            print(f"  PIN FAIL: {here.digest[:16]}... not integrity-verified");
            self.blocked = True;
        } else {
            self.pinned_digests.append(here.digest);
            print(f"  PINNED: {here.digest[:16]}...");
        }
    }
}

with entry {
    lodash_req = PackageRequest(title="lodash", tag="latest");
    lodash_cand = ExactCandidate(title="lodash", version="4.17.21", integrity="sha512-abc123foundry");
    lodash_art = Artifact(title="lodash-tarball", digest="sha512-abc123foundry");

    chalk_req = PackageRequest(title="chalk", tag="^5.0.0");
    chalk_cand = ExactCandidate(title="chalk", version="5.3.0", integrity="sha512-def456foundry");
    chalk_art = Artifact(title="chalk-tarball", digest="sha512-def456foundry");

    good_tx = Transaction(tx_id="apply-001", proposal_digest="sha512-abc123foundry");
    bad_tx = Transaction(tx_id="apply-002", proposal_digest="sha512-tag-drifted");

    root ++> lodash_req +>:ResolvesTo:+> lodash_cand +>:StagedAs:+> lodash_art;
    root ++> chalk_req +>:ResolvesTo:+> chalk_cand +>:StagedAs:+> chalk_art;
    root ++> good_tx +>:PinnedBy:+> lodash_art;
    root ++> bad_tx +>:PinnedBy:+> chalk_art;

    root spawn RegistryResolver();
    root spawn TransactionGuard();
}

"""GasTown HQ install: migration 0059 recursive is_blocked recompute vs hardcoded deadline."""

node HqDatabase {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has schema_version: int = 0;
    has issue_prefix: str = "";
}

node Issue {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has is_blocked: bool = False;
}

node Wisp {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

node SchemaMigration {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has uses_recursive: bool = False;
}

edge Contains { }
edge DependsOn { has blocks: bool = True; }
edge StagingRow { }
edge PendingOn { }

walker GtInstall {
    has deadline_units: int = 30;
    has outcome: str = "ok";

    can start with Root entry {
        visit [-->];
    }

    can install with HqDatabase entry {
        print(
            f"gt install: opening hq={here.title} "
            f"prefix={here.issue_prefix} schema=v{here.schema_version} "
            f"deadline={self.deadline_units}s"
        );
        visit [->:PendingOn:->] else {
            print("gt install: no pending migrations");
            disengage;
        };
    }

    can run_migration with SchemaMigration entry {
        if not here.available {
            visit [-->];
        } else {
            if not here.uses_recursive {
                print(f"migrate: skip non-recursive {here.title}");
                visit [-->];
            } else {
                print(f"migrate: applying {here.title} (v{here.year})");
                worker = Migration0059(deadline_units=self.deadline_units);
                here spawn worker;
                if worker.timed_out {
                    self.outcome = (
                        f"initializing HQ Dolt database: ensuring issue_prefix for "
                        f"existing database: opening beads database: failed to "
                        f"initialize schema: context deadline exceeded "
                        f"(staging_dirty={worker.staging_dirty}, "
                        f"work={worker.work_units}, recomputed={worker.recomputed})"
                    );
                    print(f"FAIL: {self.outcome}");
                    disengage;
                }
                hq = worker.target_db;
                if hq is not None {
                    hq.schema_version = here.year;
                    print(f"gt install: schema advanced hq to v{hq.schema_version}");
                }
                visit [-->];
            }
        }
    }
}

walker Migration0059 {
    has deadline_units: int = 30;
    has work_units: int = 0;
    has timed_out: bool = False;
    has staging_dirty: bool = False;
    has visited: list[str] = [];
    has recomputed: int = 0;
    has target_db: HqDatabase | None = None;

    can start with SchemaMigration entry {
        visit [->:PendingOn:->] else { disengage; };
    }

    can open_hq with HqDatabase entry {
        self.target_db = here;
        print(f"0059: staging wisp rows for {here.title}");
        visit [->:StagingRow:->];
        print(f"0059: recursive is_blocked recompute over issues/dependencies");
        visit [->:Contains:->] else { disengage; };
    }

    can stage_wisp with Wisp entry {
        self.work_units += 1;
        if self.work_units > self.deadline_units {
            self.timed_out = True;
            self.staging_dirty = True;
            print(
                f"0059: deadline exceeded during staging "
                f"(work={self.work_units})"
            );
            disengage;
        }
        visit [-->];
    }

    can recompute with Issue entry {
        key = here.title;
        if key in self.visited {
            print(f"0059: cycle guard on {key}");
            disengage;
        }
        self.visited.append(key);
        self.work_units += 1;
        if self.work_units > self.deadline_units {
            self.timed_out = True;
            self.staging_dirty = True;
            print(
                f"0059: deadline exceeded during recompute "
                f"(work={self.work_units})"
            );
            disengage;
        }
        visit [->:DependsOn:->];
        blocked_flag = self.dependency_blocks(here);
        here.is_blocked = blocked_flag;
        open_flag = not blocked_flag;
        here.available = open_flag;
        status = "BLOCKED" if blocked_flag else "OPEN";
        print(f"  [{status}] {here.title} (y{here.year})");
        self.recomputed += 1;
        visit [-->];
    }

    def dependency_blocks(issue: Issue) -> bool {
        probe = DepProbe();
        issue spawn probe;
        return probe.found_blocker;
    }
}

walker DepProbe {
    has found_blocker: bool = False;
    has seen: list[str] = [];

    can start with Issue entry {
        visit [->:DependsOn:->] else { disengage; };
    }

    can follow with Issue entry {
        key = here.title;
        if key in self.seen {
            disengage;
        }
        self.seen.append(key);
        if not here.available {
            self.found_blocker = True;
            disengage;
        }
        visit [->:DependsOn:->] else { disengage; };
    }
}

with entry {
    hq = HqDatabase(
        title="hq",
        year=2026,
        schema_version=58,
        issue_prefix="gt-",
    );
    mig059 = SchemaMigration(
        title="0059_recompute_null_gate_is_blocked",
