"""Foundry exact registry resolution: mutable tags become exact candidates, artifacts are integrity-verified and content-addressed, and transactions pin digest-bound inputs so apply cannot substitute drifted content."""

node PackageRequest {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has tag: str = "latest";
}

node ExactCandidate {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has version: str = "";
    has integrity: str = "";
    has evidence_state: str = "observed-unverified";
}

node Artifact {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has digest: str = "";
    has verified: bool = False;
}

node Transaction {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has tx_id: str = "";
    has proposal_digest: str = "";
}

edge ResolvesTo { }
edge StagedAs { }
edge PinnedBy { }

walker RegistryResolver {
    has resolved: int = 0;
    has seen_digests: list[str] = [];
    has phase: str = "discover";

    can start with Root entry {
        visit [-->];
    }

    can resolve with PackageRequest entry {
        self.phase = "discover";
        print(f"[RESOLVE] {here.title}@{here.tag} (mutable tag -> exact candidate)");
        visit [->:ResolvesTo:->] else { disengage; };
    }

    can handle with ExactCandidate entry {
        if self.phase == "discover" {
            label = "REVIEWED" if here.evidence_state == "reviewed" else "OBSERVED-UNVERIFIED";
            print(f"  exact: {here.title}@{here.version} [{label}] integrity={here.integrity}");
            self.resolved += 1;
            self.phase = "promote";
            visit [->:StagedAs:->] else { disengage; };
        } else {
            if here.evidence_state == "observed-unverified" {
                here.evidence_state = "reviewed";
                print(f"  PROMOTED: {here.title}@{here.version} discovery -> reviewed evidence");
            }
            self.phase = "discover";
            visit [-->] else { disengage; };
        }
    }

    can admit with Artifact entry {
        if here.digest in self.seen_digests {
            print(f"  CYCLE blocked at digest {here.digest[:16]}");
            disengage;
        }
        self.seen_digests.append(here.digest);
        if here.digest == "" {
            here.verified = False;
            print("  REJECT: empty digest — partial download not admitted");
        } else {
            here.verified = True;
            print(f"  ADMIT: content-addressed artifact {here.digest[:16]}... integrity OK");
        }
        visit [<--:StagedAs:--];
    }
}

walker TransactionGuard {
    has pinned_digests: list[str] = [];
    has blocked: bool = False;

    can start with Root entry {
        visit [-->];
    }

    can stage with Transaction entry {
        self.pinned_digests = [];
        self.blocked = False;
        print(f"[TX {here.tx_id}] pinning artifacts for proposal {here.proposal_digest[:16]}...");
        visit [->:PinnedBy:->] else { disengage; };
        if self.blocked {
            print(f"[TX {here.tx_id}] APPLY BLOCKED — unverified artifact");
        } elif here.proposal_digest in self.pinned_digests {
            print(f"[TX {here.tx_id}] APPLY OK — exact artifact locked, no tag substitution");
        } else {
            print(f"[TX {here.tx_id}] APPLY BLOCKED — digest mismatch after approval");
        }
    }

    can pin with Artifact entry {
        if not here.verified {
            print(f"  PIN FAIL: {here.digest[:16]}... not integrity-verified");
            self.blocked = True;
        } else {
            self.pinned_digests.append(here.digest);
            print(f"  PINNED: {here.digest[:16]}...");
        }
    }
}

with entry {
    lodash_req = PackageRequest(title="lodash", tag="latest");
    lodash_cand = ExactCandidate(title="lodash", version="4.17.21", integrity="sha512-abc123foundry");
    lodash_art = Artifact(title="lodash-tarball", digest="sha512-abc123foundry");

    chalk_req = PackageRequest(title="chalk", tag="^5.0.0");
    chalk_cand = ExactCandidate(title="chalk", version="5.3.0", integrity="sha512-def456foundry");
    chalk_art = Artifact(title="chalk-tarball", digest="sha512-def456foundry");

    good_tx = Transaction(tx_id="apply-001", proposal_digest="sha512-abc123foundry");
    bad_tx = Transaction(tx_id="apply-002", proposal_digest="sha512-tag-drifted");

    root ++> lodash_req +>:ResolvesTo:+> lodash_cand +>:StagedAs:+> lodash_art;
    root ++> chalk_req +>:ResolvesTo:+> chalk_cand +>:StagedAs:+> chalk_art;
    root ++> good_tx +>:PinnedBy:+> lodash_art;
    root ++> bad_tx +>:PinnedBy:+> chalk_art;

    root spawn RegistryResolver();
    root spawn TransactionGuard();
}

"""GitHub Actions evidence normalization, receipt v2 construction, and lifecycle gate auditing."""

node TaskMilestone {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has task_id: int = 0;
    has complete: bool = False;
}

node ActionsRun {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has repository_id: str = "";
    has workflow_id: str = "";
    has run_id: str = "";
    has attempt: int = 0;
    has head_sha: str = "";
    has conclusion: str = "";
    has classification: str = "";
    has stale_epoch: bool = False;
    has wrong_sha: bool = False;
    has policy_mismatch: bool = False;
    has platform_outage: bool = False;
    has no_slow_impact: bool = False;
    has normalized: bool = False;

    def logical_key() -> str {
        return f"github-actions:{self.repository_id}:{self.workflow_id}:{self.run_id}:{self.attempt}:{self.head_sha}";
    }

    def exclusion_reason() -> str {
        if self.platform_outage {
            return "platform outage";
        }
        if self.stale_epoch {
            return "stale epoch";
        }
        if self.wrong_sha {
            return "wrong SHA";
        }
        if self.policy_mismatch {
            return "policy hash mismatch";
        }
        return "contract-invalid";
    }

    def disposition() -> str {
        if self.platform_outage or self.stale_epoch or self.wrong_sha or self.policy_mismatch {
            return "excluded";
        }
        return "recorded-non-cycle";
    }
}

node MeasurementEvidence {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has logical_key: str = "";
    has classification: str = "";
    has disposition: str = "";
    has exclusion_reason: str = "";
    has evidence_source: str = "github-actions";
}

node LifecycleGate {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has gate_name: str = "";
    has evidence_source: str = "";
    has passed: bool = False;
    has accepted: bool = False;
}

edge Prerequisite { }
edge NormalizesTo { }
edge BuildsReceipt { }

walker TaskReadiness {
    has task11_ready: bool = True;

    can start with TaskMilestone entry {
        if here.task_id != 11 {
            disengage;
        }
        print(f"[TASK 11] checking prerequisites for {here.title}");
        visit [->:Prerequisite:->] else {
            print("[TASK 11] no prerequisite edges found");
            disengage;
        };
        if self.task11_ready {
            print("[TASK 11] all prerequisites satisfied");
        } else {
            print("[TASK 11] blocked by incomplete prerequisites");
        }
        disengage;
    }

    can require with TaskMilestone entry {
        if not here.complete {
            self.task11_ready = False;
            print(f"[BLOCKED] prerequisite task {here.task_id} ({here.title}) incomplete");
        } else {
            print(f"[OK] prerequisite task {here.task_id} ({here.title}) complete");
        }
        disengage;
    }
}

walker ActionsAdapter {
    has adapted: int = 0;

    can start with ActionsRun entry {
        if not here.normalized {
            class_label = here.classification;
            if here.no_slow_impact {
                class_label = "no-slow-impact";
            }
            disp = here.disposition();
            excl = "";
            if disp == "excluded" {
                excl = here.exclusion_reason();
            }
            evidence = MeasurementEvidence(
                title=here.title,
                logical_key=here.logical_key(),
                classification=class_label,
                disposition=disp,
                exclusion_reason=excl
            );
            here +>:NormalizesTo:+> evidence;
            here.normalized = True;
            self.adapted += 1;
            print(f"[ADAPT] {here.logical_key()} -> {class_label} ({disp})");
        }
        visit [-->[?:ActionsRun]] else { disengage; };
    }

    can adapt with ActionsRun entry {
        if not here.normalized {
            class_label = here.classification;
            if here.no_slow_impact {
                class_label = "no-slow-impact";
            }
            disp = here.disposition();
            excl = "";
            if disp == "excluded" {
                excl = here.exclusion_reason();
            }
            evidence = MeasurementEvidence(
                title=here.title,
                logical_key=here.logical_key(),
                classification=class_label,
                disposition=disp,
                exclusion_reason=excl
            );
            here +>:NormalizesTo:+> evidence;
            here.normalized = True;
            self.adapted += 1;
            print(f"[ADAPT] {here.logical_key()} -> {class_label} ({disp})");
        }
        visit [-->[?:ActionsRun]] else { disengage; };
    }
}

walker ReceiptBuilder {
    has built: int = 0;
    has excluded: int = 0;
    has seen_keys: list[str] = [];

    can start with ActionsRun entry {
        visit [->:NormalizesTo:->] else { };
        visit [-->[?:ActionsRun]] else { disengage; };
    }

    can build with ActionsRun entry {
        visit [->:NormalizesTo:->] else { };
        visit [-->[?:ActionsRun]] else { disengage; };
    }

    can validate with MeasurementEvidence entry {
        if here.logical_key in self.seen_keys {
            print(f"[CYCLE GUARD] revisiting {here.logical_key}");
            disengage;
        }
        self.seen_keys.append(here.logical_key);
        if here.disposition == "excluded" {
            self.excluded += 1;
            print(f"[EXCLUDED] {here.logical_key}: {here.exclusion_reason}");
        } else {
            receipt_id = here.logical_key;
            here +>:BuildsReceipt:+> MeasurementEvidence(
                title=f"receipt-v2:{receipt_id}",
                logical_key=receipt_id,
                classification=here.classification,
                disposition="recorded-non-cycle",
                evidence_source="github-actions"
            );
            self.built += 1;
            print(f"[RECEIPT v2] {receipt_id} class={here.classification}");
        }
        disengage;
    }
}

walker LifecycleAuditor {
    has passed: int = 0;
    has failed: int = 0;

    can start with LifecycleGate entry {
        source_ok = here.evidence_source == "github-actions" or here.evidence_source == "agent";
        here.accepted = source_ok and here.passed;
        if here.accepted {
            self.passed += 1;
            verdict = "PASS";
        } else {
            self.failed += 1;
            verdict = "FAIL";
        }
        print(f"[GATE] {here.gate_name} source={here.evidence_source} -> {verdict}");
        visit [-->[?:LifecycleGate]] else { disengage; };
    }

    can audit with LifecycleGate entry {
        source_ok = here.evidence_source == "github-actions" or here.evidence_source == "agent";
        here.accepted = source_ok and here.passed;
        if here.accepted {
            self.passed += 1;
            verdict = "PASS";
        } else {
            self.failed += 1;
            verdict = "FAIL";
        }
        print(f"[GATE] {here.gate_name} source={here.evidence_source} -> {verdict}");
        visit [-->[?:LifecycleGate]] else { disengage; };
    }
}

