"""Foundry exact registry resolution: mutable tags become exact candidates, artifacts are integrity-verified and content-addressed, and transactions pin digest-bound inputs so apply cannot substitute drifted content."""

node PackageRequest {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has tag: str = "latest";
}

node ExactCandidate {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has version: str = "";
    has integrity: str = "";
    has evidence_state: str = "observed-unverified";
}

node Artifact {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has digest: str = "";
    has verified: bool = False;
}

node Transaction {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has tx_id: str = "";
    has proposal_digest: str = "";
}

edge ResolvesTo { }
edge StagedAs { }
edge PinnedBy { }

walker RegistryResolver {
    has resolved: int = 0;
    has seen_digests: list[str] = [];
    has phase: str = "discover";

    can start with Root entry {
        visit [-->];
    }

    can resolve with PackageRequest entry {
        self.phase = "discover";
        print(f"[RESOLVE] {here.title}@{here.tag} (mutable tag -> exact candidate)");
        visit [->:ResolvesTo:->] else { disengage; };
    }

    can handle with ExactCandidate entry {
        if self.phase == "discover" {
            label = "REVIEWED" if here.evidence_state == "reviewed" else "OBSERVED-UNVERIFIED";
            print(f"  exact: {here.title}@{here.version} [{label}] integrity={here.integrity}");
            self.resolved += 1;
            self.phase = "promote";
            visit [->:StagedAs:->] else { disengage; };
        } else {
            if here.evidence_state == "observed-unverified" {
                here.evidence_state = "reviewed";
                print(f"  PROMOTED: {here.title}@{here.version} discovery -> reviewed evidence");
            }
            self.phase = "discover";
            visit [-->];
        }
    }

    can admit with Artifact entry {
        if here.digest in self.seen_digests {
            print(f"  CYCLE blocked at digest {here.digest[:16]}");
            disengage;
        }
        self.seen_digests.append(here.digest);
        if here.digest == "" {
            here.verified = False;
            print("  REJECT: empty digest — partial download not admitted");
        } else {
            here.verified = True;
            print(f"  ADMIT: content-addressed artifact {here.digest[:16]}... integrity OK");
        }
        visit [<-:StagedAs:<-] else { disengage; };
    }
}

walker TransactionGuard {
    has pinned_digests: list[str] = [];
    has blocked: bool = False;

    can start with Root entry {
        visit [-->];
    }

    can stage with Transaction entry {
        self.pinned_digests = [];
        self.blocked = False;
        print(f"[TX {here.tx_id}] pinning artifacts for proposal {here.proposal_digest[:16]}...");
        visit [->:PinnedBy:->] else { disengage; };
        if self.blocked {
            print(f"[TX {here.tx_id}] APPLY BLOCKED — unverified artifact");
        } elif here.proposal_digest in self.pinned_digests {
            print(f"[TX {here.tx_id}] APPLY OK — exact artifact locked, no tag substitution");
        } else {
            print(f"[TX {here.tx_id}] APPLY BLOCKED — digest mismatch after approval");
        }
    }

    can pin with Artifact entry {
        if not here.verified {
            print(f"  PIN FAIL: {here.digest[:16]}... not integrity-verified");
            self.blocked = True;
        } else {
            self.pinned_digests.append(here.digest);
            print(f"  PINNED: {here.digest[:16]}...");
        }
    }
}

with entry {
    lodash_req = PackageRequest(title="lodash", tag="latest");
    lodash_cand = ExactCandidate(title="lodash", version="4.17.21", integrity="sha512-abc123foundry");
    lodash_art = Artifact(title="lodash-tarball", digest="sha512-abc123foundry");

    chalk_req = PackageRequest(title="chalk", tag="^5.0.0");
    chalk_cand = ExactCandidate(title="chalk", version="5.3.0", integrity="sha512-def456foundry");
    chalk_art = Artifact(title="chalk-tarball", digest="sha512-def456foundry");

    good_tx = Transaction(tx_id="apply-001", proposal_digest="sha512-abc123foundry");
    bad_tx = Transaction(tx_id="apply-002", proposal_digest="sha512-tag-drifted");

    root ++> lodash_req +>:ResolvesTo:+> lodash_cand +>:StagedAs:+> lodash_art;
    root ++> chalk_req +>:ResolvesTo:+> chalk_cand +>:StagedAs:+> chalk_art;
    root ++> good_tx +>:PinnedBy:+> lodash_art;
    root ++> bad_tx +>:PinnedBy:+> chalk_art;

    root spawn RegistryResolver();
    root spawn TransactionGuard();
}

