"""Pipeline composition follow-up: nested local invocations, bounded ONE_TO_ONE self-recursion, and mutual-recursion cycle rejection."""

node RunContext {
    has execution_id: str = "";
    has owner_label: str = "root";
}

node CompositionCatalog {
    has catalogue_name: str = "";
}

node Pipeline {
    has logical_id: str = "";
    has cardinality: str = "ONE_TO_ONE";
    has max_recursion_depth: int = 2;
    has accepts_await: bool = False;
}

edge OwnsRun { }

edge Invokes {
    has step_kind: str = "NEXT_LOCAL";
}

edge SelfRecurses { }

walker InvokeAuditor {
    has invoke_stack: list[str] = [];
    has lineage: list[str] = [];
    has mutual_cycle_detected: bool = False;
    has cycle_path: str = "";
    has run_id: str = "";

    can start with Root entry {
        visit [-->];
    }

    can bind_run with RunContext entry {
        self.run_id = here.execution_id;
        visit [->:OwnsRun:->] else { visit [-->]; }
    }

    can open_catalog with CompositionCatalog entry {
        visit [->:Invokes:->] else { disengage; }
    }

    can walk_invoke with Pipeline entry {
        lid = here.logical_id;
        if lid in self.invoke_stack {
            self.mutual_cycle_detected = True;
            path_tail = lid;
            for frame in self.invoke_stack {
                path_tail = f"{frame} -> {path_tail}";
            }
            self.cycle_path = f"{path_tail} -> {lid}";
            disengage;
        }
        self.invoke_stack.append(lid);
        self.lineage.append(lid);
        visit [->:Invokes:->] else {
            self.invoke_stack.pop();
            disengage;
        }
        self.invoke_stack.pop();
    }
}

walker BoundedRecursionWalker {
    has recursion_depth: int = 0;
    has depth_capped: bool = False;
    has recurse_trace: list[str] = [];
    has entering_recursion: bool = False;

    can start with Root entry {
        visit [-->];
    }

    can bind_run with RunContext entry {
        visit [->:OwnsRun:->] else { visit [-->]; }
    }

    can reach_catalog with CompositionCatalog entry {
        visit [->:Invokes:->] else { visit [-->]; }
    }

    can reach_pipeline with Pipeline entry {
        if here.logical_id == "agent_loop" {
            self.recurse_trace.append(here.logical_id);
            self.entering_recursion = True;
            visit [->:SelfRecurses:->] else { disengage; }
        } else {
            visit [->:Invokes:->] else { visit [-->]; }
        }
    }

    can bounded_self_recurse with Pipeline entry {
        if not self.entering_recursion {
            disengage;
        }
        if self.recursion_depth >= here.max_recursion_depth {
            self.depth_capped = True;
            self.entering_recursion = False;
            disengage;
        }
        self.recursion_depth += 1;
        frame_label = f"{here.logical_id}@depth{self.recursion_depth}";
        self.recurse_trace.append(frame_label);
        self.entering_recursion = True;
        visit [->:SelfRecurses:->] else {
            self.entering_recursion = False;
            disengage;
        }
    }
}

with entry {
    run = RunContext(execution_id="exec-root-001", owner_label="telemetry-run");
    catalog = CompositionCatalog(catalogue_name="local_pipelines");
    main_pipe = Pipeline(logical_id="main", cardinality="ONE_TO_ONE");
    preprocess = Pipeline(logical_id="preprocess", cardinality="ONE_TO_ONE");
    agent_loop = Pipeline(
        logical_id="agent_loop",
        cardinality="ONE_TO_ONE",
        max_recursion_depth=2,
        accepts_await=False
    );
    publish = Pipeline(logical_id="publish", cardinality="ONE_TO_ONE");
    cycle_catalog = CompositionCatalog(catalogue_name="mutual_cycle_probe");
    cycle_a = Pipeline(logical_id="cycle_a", cardinality="ONE_TO_ONE");
    cycle_b = Pipeline(logical_id="cycle_b", cardinality="ONE_TO_ONE");

    root ++> run;
    run +>:OwnsRun:+> catalog;
    catalog +>:Invokes(step_kind="NEXT_LOCAL"):+> main_pipe;
    main_pipe +>:Invokes(step_kind="NEXT_LOCAL"):+> preprocess;
    preprocess +>:Invokes(step_kind="NEXT_LOCAL"):+> agent_loop;
    agent_loop +>:Invokes(step_kind="RETURN"):+> publish;
    agent_loop +>:SelfRecurses:+> agent_loop;
    root ++> cycle_catalog;
    cycle_catalog +>:Invokes(step_kind="NEXT_LOCAL"):+> cycle_a;
    cycle_a +>:Invokes(step_kind="NEXT_LOCAL"):+> cycle_b;
    cycle_b +>:Invokes(step_kind="NEXT_LOCAL"):+> cycle_a;

    auditor = InvokeAuditor();
    root spawn auditor;
    bounded = BoundedRecursionWalker();
    run spawn bounded;

    linear_label = "linear";
    if auditor.lineage {
        linear_label = auditor.lineage[0];
    }
    cycle_status = "none";
    if auditor.mutual_cycle_detected {
        cycle_status = auditor.cycle_path;
    }
    recurse_status = "within bound";
    if bounded.depth_capped {
        recurse_status = "capped";
    }
    print(
        f"run={auditor.run_id} linear_head={linear_label} "
        f"mutual_cycle={cycle_status} self_recursion={recurse_status} "
        f"trace={bounded.recurse_trace}"
    );
}

"""Frontier sweep: L0 packaging through L3 swarm with parallel L2 lanes and QA feedback."""

node FrontierLevel {
    has title: str = "";
    has ring: int = 0;
    has landed: bool = False;
}

node ConsumerLane {
    has issue_num: int = 0;
    has title: str = "";
    has landed: bool = False;
    has commit_hash: str = "";
}

node QALane {
    has label: str = "Lane E";
    has reviews_done: int = 0;
    has gate_green: bool = False;
}

edge Spine {
    has order: int = 0;
}

edge Hosts { }

edge Monitors { }

walker FrontierSweeper {
    has visited_keys: list[str] = [];
    has landed_levels: int = 0;
    has landed_lanes: int = 0;
    has lanes_seen: int = 0;

    can start with Root entry {
        print("=== FRONTIER SWEEP: L0 surface -> L1 spine -> L2 consumers -> L3 pattern ===");
        visit [->:Spine:->] else { disengage; };
    }

    can sweep_level with FrontierLevel entry {
        key = f"{here.title}:r{here.ring}";
        if key in self.visited_keys {
            print(f"[CYCLE-GUARD] reflexive edge blocked at {here.title}");
            disengage;
        }
        self.visited_keys.append(key);
        status = "LANDED" if here.landed else "OPEN";
        print(f"[Ring {here.ring}] {here.title} — {status}");
        if here.landed {
            self.landed_levels += 1;
        }
        if here.title == "L2 consumers" {
            visit [->:Hosts:->] else { };
            visit [->:Spine:->] else { disengage; };
        } else {
            visit [->:Spine:->] else { disengage; };
        }
    }

    can audit_lane with ConsumerLane entry {
        self.lanes_seen += 1;
        status = "LANDED" if here.landed else "PENDING";
        if here.landed {
            self.landed_lanes += 1;
        }
        hash_suffix = f" @{here.commit_hash}" if here.landed else "";
        print(f"    L2 #{here.issue_num} [{status}] {here.title}{hash_suffix}");
    }
}

walker QAPatrol {
    has pass_count: int = 0;
    has watch_count: int = 0;

    can start with Root entry {
        print("--- Lane E: continuous QA / downstream review ---");
        visit [->:Monitors:->] else { disengage; };
    }

    can review with FrontierLevel | ConsumerLane entry {
        verdict = "PASS" if here.landed else "WATCH";
        if here.landed {
            self.pass_count += 1;
        } else {
            self.watch_count += 1;
        }
        print(f"[QA] {verdict}: {here.title}");
        visit [-->];
    }

    can close_ledger with QALane entry {
        here.reviews_done = self.pass_count + self.watch_count;
        here.gate_green = self.watch_count == 0;
        gate_label = "GREEN" if here.gate_green else "WATCH";
        print(f"[QA] {here.label}: {here.reviews_done} reviews, gate {gate_label}");
    }
}

