"""LLxprt 0.12.0 plugin isolation: trusted optional Google plugins load before provider aliases; published-base boundary gates forbidden dependencies."""

node Runtime {
    has name: str = "";
    has is_published_base: bool = True;
}

node Plugin {
    has package_root: str = "";
    has trusted: bool = True;
    has compatible: bool = True;
    has loaded: bool = False;
}

node Provider {
    has alias: str = "";
    has needs_plugin: bool = False;
    has activated: bool = False;
}

node Dependency {
    has pkg_name: str = "";
    has forbidden_in_base: bool = False;
}

edge Hosts { }
edge Activates { }
edge Pulls { }
edge PluginRequires { }

walker StartupLoader {
    has plugin_count: int = 0;
    has provider_count: int = 0;
    has alias_failures: int = 0;
    has visited_plugins: list = [];

    can start with Root entry {
        print("=== Explicit trusted plugin loading (before aliases) ===");
        visit [-->];
    }

    can onboard with Runtime entry {
        visit [-->[?:Plugin]];
        print("--- Phase 2: alias-compatible provider registration ---");
        visit [-->[?:Provider]];
        visit [-->];
    }

    can validate_plugin with Plugin entry {
        if here.package_root in self.visited_plugins {
            print(f"[PLUGIN FAIL] duplicate: {here.package_root}");
            visit [-->];
        } else {
            self.visited_plugins.append(here.package_root);
            if not here.trusted {
                print(f"[PLUGIN FAIL] reject specifier: {here.package_root}");
                visit [-->];
            } elif not here.compatible {
                print(f"[PLUGIN FAIL] incompatible: {here.package_root}");
                visit [-->];
            } else {
                here.loaded = True;
                self.plugin_count += 1;
                print(f"[PLUGIN OK] {here.package_root}");
                visit [->:PluginRequires:->] else { disengage; };
                visit [->:Activates:->] else { disengage; };
                visit [-->];
            }
        }
    }

    can order_plugins with Plugin entry {
        if here.package_root in self.visited_plugins {
            print(f"[ORDER CYCLE] {here.package_root}");
            disengage;
        } else {
            self.visited_plugins.append(here.package_root);
            visit [->:PluginRequires:->] else { disengage; };
        }
    }

    can wire_factory with Provider entry {
        here.activated = True;
        print(f"[PLUGIN->ALIAS] factory wired for '{here.alias}'");
        visit [-->];
    }

    can register_alias with Provider entry {
        if here.needs_plugin {
            if here.activated {
                self.provider_count += 1;
                print(f"[ALIAS OK] '{here.alias}' (plugin-supplied)");
            } else {
                self.alias_failures += 1;
                print(f"[ALIAS FAIL] '{here.alias}' — install matching plugin");
            }
        } else {
            here.activated = True;
            self.provider_count += 1;
            print(f"[ALIAS OK] '{here.alias}' (base runtime)");
        }
        visit [-->];
    }
}

walker BoundaryGate {
    has violations: int = 0;

    can start with Root entry {
        print("=== Published-base forbidden-dependency gate ===");
        visit [-->];
    }

    can audit_base with Runtime entry {
        if here.is_published_base {
            visit [->:Pulls:->] else { disengage; };
        }
        visit [-->];
    }

    can inspect_pull with Dependency entry {
        if here.forbidden_in_base {
            self.violations += 1;
            print(f"[BOUNDARY FAIL] {here.pkg_name} leaked into base");
        } else {
            print(f"[BOUNDARY OK] {here.pkg_name} allowed in base");
        }
        visit [-->];
    }
}

