                print(f"[PLUGIN FAIL] incompatible: {here.package_root}");
                visit [-->];
            } else {
                here.loaded = True;
                self.plugin_count += 1;
                print(f"[PLUGIN OK] {here.package_root}");
                visit [->:RequiresPlugin:->];
                visit [->:Activates:->];
                visit [-->];
            }
        }
    }

    can wire_factory with Provider entry {
        here.activated = True;
        print(f"[PLUGIN->ALIAS] factory wired for '{here.alias}'");
        visit [-->];
    }

    can register_alias with Provider entry {
        if here.needs_plugin {
            if here.activated {
                self.provider_count += 1;
                print(f"[ALIAS OK] '{here.alias}' (plugin-supplied)");
            } else {
                self.alias_failures += 1;
                print(f"[ALIAS FAIL] '{here.alias}' — install matching plugin");
            }
        } else {
            here.activated = True;
            self.provider_count += 1;
            print(f"[ALIAS OK] '{here.alias}' (base runtime)");
        }
        visit [-->];
    }
}

walker BoundaryGate {
    has violations: int = 0;

    can start with Root entry {
        print("=== Published-base forbidden-dependency gate ===");
        visit [-->];
    }

    can audit_base with BaseInstall entry {
        if here.is_published_base {
            visit [->:Pulls:->] else { disengage; };
        }
        visit [-->];
    }

    can inspect_pull with Dependency entry {
        if here.forbidden_in_base {
            self.violations += 1;
            print(f"[BOUNDARY FAIL] {here.pkg_name} leaked into base");
        } else {
            print(f"[BOUNDARY OK] {here.pkg_name} allowed in base");
        }
        visit [-->];
    }
}

