edge OwnsRole { }

node StaffTarget {
    has username: str = "";
    has is_active: bool = True;
}

node StudioRole {
    has role_code: str = "";
    has title: str = "";
    has owned: bool = True;
}

node ExternalGroup {
    has group_name: str = "";
    has preserved: bool = True;
}

node AuditEntry {
    has action: str = "";
    has row_count: int = 0;
    has redacted: bool = True;
}

node DeploymentProfile {
    has profile: str = "development";
    has admin_enabled: bool = True;
}

walker ProductionGuard {
    can start with Root entry {
        visit [-->];
    }

    can inspect with DeploymentProfile entry {
        if here.profile == "production" {
            here.admin_enabled = False;
            print("FAIL_CLOSED: /admin returns private 404 in production");
        } else {
            state = "enabled" if here.admin_enabled else "disabled";
            print(f"DEV_OK: admin {state} for {here.profile}");
        }
        visit [-->];
    }
}

walker RoleAdministrator {
    has authority: str = "";
    has target_limit: int = 100;
    has processed: int = 0;
    has seen_staff: list[str] = [];
    has replaced_owned: list[str] = [];

    can start with Root entry {
        if self.authority != "core.manage_studio_roles" {
            print("DENIED: missing core.manage_studio_roles authority");
            disengage;
        }
        print("Role admin: seven code-owned roles, preserve unrelated groups");
        visit [->:InStudio:->] else { disengage; }
    }

    can review_staff with StaffTarget entry {
        if here.username in self.seen_staff {
            print(f"CYCLE: staff traversal blocked at {here.username}");
            disengage;
        }
        self.seen_staff.append(here.username);
        if not here.is_active {
            print(f"SKIP inactive staff target {here.username}");
            visit [-->];
        } else {
            if self.processed >= self.target_limit {
                print("OVER_BOUND: more than 100 active staff targets");
                disengage;
            }
            self.processed += 1;
            print(f"STAFF target {here.username} ({self.processed}/{self.target_limit})");
            visit [-->];
        }
    }

    can replace_owned with StudioRole entry {
        if here.owned {
            self.replaced_owned.append(here.role_code);
            print(f"[REPLACE] owned group {here.role_code} ({here.title})");
        }
        visit [->:OwnsRole:->] else { visit [->:DelegatesTo:->] else { visit [-->]; } }
    }

    can preserve_external with ExternalGroup entry {
        if here.preserved {
            print(f"PRESERVE unrelated group {here.group_name}");
        }
        visit [-->];
    }
}

walker AuditExporter {
    has max_rows: int = 1000;
    has exported: int = 0;

    can start with Root entry {
        print("Audit export: redacted CSV snapshot");
        visit [->:Records:->] else { disengage; }
    }

    can export_row with AuditEntry entry {
        if self.exported >= self.max_rows {
            print("OVER_LIMIT: audit export capped at 1000 rows");
            disengage;
        }
        status = "REDACTED" if here.redacted else "OPEN";
        print(f"[{status}] {here.action} rows={here.row_count}");
        self.exported += 1;
        visit [->:Records:->] else { disengage; }
    }
}

