"""Dependency graph integrity: reject Current-induced Count drift before semantic processing."""

node CountRegistry {
    has known_count: int = 0;
    has bound_count: int = 0;

    def rebind_count() -> bool {
        return self.bound_count == self.known_count;
    }

    def induce_drift(delta: int) {
        self.bound_count += delta;
    }
}

node SemanticElement {
    has element_id: str = "";
    has staged: bool = False;
    has materialized: bool = False;
    has induces_count_drift: bool = False;

    def stage() {
        self.staged = True;
    }

    def materialize() {
        self.materialized = True;
    }
}

edge MemberOf { }

walker Rebuild {
    has drift_detected: bool = False;
    has elements_staged: int = 0;
    has registry: CountRegistry = CountRegistry();

    can start with Root entry {
        visit [-->[?:CountRegistry]] else { disengage; };
    }

    can begin_rebuild with CountRegistry entry {
        self.registry = here;
        self.registry.bound_count = self.registry.known_count;
        visit [->:MemberOf:->] else { disengage; };
    }

    can read_current with SemanticElement entry {
        if here.induces_count_drift {
            self.registry.induce_drift(1);
