"""OAS3 CSV enum fix pass: hand-built schema graphs need explicit cycle guards.

Models fixer/enum_csv.go recursion over Schema, PathItem callbacks, and
Encoding mutual refs. Without per-kind path stacks the walk would loop
forever on pointer cycles reachable only from hand-built documents.
"""

node Schema {
    has name: str = "";
    has enum_csv: str = "";
    has fixed: bool = False;
}

node PathItem {
    has path: str = "";
    has enum_csv: str = "";
    has fixed: bool = False;
}

node Encoding {
    has key: str = "";
    has enum_csv: str = "";
    has fixed: bool = False;
}

edge SchemaDef { }
edge ItemsChain { }
edge DependentOn { }
edge PatternKey { }
edge CallbackTo { }
edge EncodesWith { }
edge ItemEncodes { }

walker CSVEnumFixer {
    has schema_stack: list[Schema] = [];
    has path_stack: list[PathItem] = [];
    has encoding_stack: list[Encoding] = [];
    has fixes_applied: int = 0;
    has cycle_hits: int = 0;

    can start with Root entry {
        print("fixSchemaCSVEnums: starting pass with cycle guard");
        visit [-->];
    }

    can fix_schema with Schema entry {
        if here in self.schema_stack {
            print(f"[cycle-guard] schema '{here.name}' re-entry blocked");
            self.cycle_hits += 1;
        } else {
            self.schema_stack.append(here);
            if here.enum_csv != "" and not here.fixed {
                here.fixed = True;
                self.fixes_applied += 1;
                print(f"[fix] schema '{here.name}': split enum_csv");
            }
            visit [->:SchemaDef:->];
            visit [->:ItemsChain:->];
            visit [->:DependentOn:->];
            visit [->:PatternKey:->];
        }
    }

    can unwind_schema with Schema exit {
        if len(self.schema_stack) > 0 and self.schema_stack[-1] is here {
            self.schema_stack.pop();
        }
    }

    can fix_path with PathItem entry {
        if here in self.path_stack {
            print(f"[cycle-guard] pathItem '{here.path}' callback cycle blocked");
            self.cycle_hits += 1;
        } else {
            self.path_stack.append(here);
            if here.enum_csv != "" and not here.fixed {
                here.fixed = True;
                self.fixes_applied += 1;
                print(f"[fix] pathItem '{here.path}': split enum_csv");
            }
            visit [->:CallbackTo:->];
        }
    }

    can unwind_path with PathItem exit {
        if len(self.path_stack) > 0 and self.path_stack[-1] is here {
            self.path_stack.pop();
        }
    }

    can fix_encoding with Encoding entry {
        if here in self.encoding_stack {
            print(f"[cycle-guard] encoding '{here.key}' mutual ref blocked");
            self.cycle_hits += 1;
        } else {
            self.encoding_stack.append(here);
            if here.enum_csv != "" and not here.fixed {
                here.fixed = True;
                self.fixes_applied += 1;
                print(f"[fix] encoding '{here.key}': split enum_csv");
            }
            visit [->:EncodesWith:->];
            visit [->:ItemEncodes:->];
        }
    }

    can unwind_encoding with Encoding exit {
        if len(self.encoding_stack) > 0 and self.encoding_stack[-1] is here {
            self.encoding_stack.pop();
        }
    }
}

with entry {
    user = Schema(name="User", enum_csv="admin,user,guest");
    profile = Schema(name="Profile", enum_csv="full,minimal");
    item = Schema(name="Item", enum_csv="widget,gadget");
    list_schema = Schema(name="ItemList");
    user +>:SchemaDef:+> profile;
    profile +>:DependentOn:+> user;
    list_schema +>:ItemsChain:+> item;

    get_users = PathItem(path="/users", enum_csv="get,post");
    user_cb = PathItem(path="onUserEvent");
    get_users +>:CallbackTo:+> user_cb;
    user_cb +>:CallbackTo:+> get_users;

    body_enc = Encoding(key="body", enum_csv="json,xml");
    item_enc = Encoding(key="itemEncoding");
    body_enc +>:EncodesWith:+> item_enc;
    item_enc +>:ItemEncodes:+> body_enc;

    root ++> user;
    root ++> list_schema;
    root ++> get_users;
    root ++> body_enc;

    fixer = CSVEnumFixer();
    root spawn fixer;
    print(f"pass complete: {fixer.fixes_applied} enum_csv fixes, "
          f"{fixer.cycle_hits} cycle guards fired");
}

