node ParserCrate {
    has name: str = "";
    has version: str = "0.1.0";
}

node ProductCrate {
    has name: str = "";
}

node SplitGate {
    has gate_id: str = "";
    has label: str = "";
    has satisfied: bool = False;
}

edge DependsOn { }
edge BlockedBy { }

walker TopoProofer {
    has visiting: list[str] = [];
    has proved: list[str] = [];
    has publish_order: list[str] = [];
    has cycle_found: bool = False;

    can start with Root entry {
        print("=== G7 topological package proof ===");
        visit [-->[?:ParserCrate]];
    }

    can prove with ParserCrate entry {
        if here.name in self.visiting {
            print(f"[CYCLE] dependency loop at {here.name}");
            self.cycle_found = True;
            disengage;
        }
        if here.name in self.proved {
            visit [-->] else { disengage; };
        } else {
            self.visiting += [here.name];
            visit [->:DependsOn:->] else { };
            if len(self.visiting) > 0 {
                self.visiting.pop();
            }
            self.proved += [here.name];
            self.publish_order += [here.name];
            print(f"  pack-order: {here.name}");
            visit [-->] else { disengage; };
        }
    }

    can leaf_product with ProductCrate entry {
        visit [-->] else { disengage; };
    }
}

walker BoundaryAuditor {
    has current_pkg: str = "";
    has violations: list[str] = [];

    can start with Root entry {
        print("=== forbidden dependency boundary audit ===");
        visit [-->[?:ParserCrate]];
    }

    can scan with ParserCrate entry {
        self.current_pkg = here.name;
        visit [->:DependsOn:->] else {
            visit [-->] else { disengage; };
        };
    }

    can flag with ProductCrate entry {
        msg = f"{self.current_pkg} -> {here.name} (product boundary violation)";
        self.violations += [msg];
        print(f"[VIOLATION] {msg}");
        visit [-->] else { disengage; };
    }
}

walker SplitGateAuditor {
    has blocked: list[str] = [];

    can start with Root entry {
        print("=== split gate readiness (G1-G8) ===");
        visit [-->[?:ParserCrate]];
    }

    can check with ParserCrate entry {
        visit [->:BlockedBy:->] else {
            print(f"[READY] {here.name} — all gates clear");
            visit [-->] else { disengage; };
        };
    }

    can at_gate with SplitGate entry {
        status_lbl = "PASS" if here.satisfied else "BLOCK";
        print(f"  [{status_lbl}] {here.gate_id}: {here.label}");
        if not here.satisfied {
            self.blocked += [f"{here.gate_id}:{here.label}"];
        }
        visit [-->] else { disengage; };
    }
}

with entry {
    pos = ParserCrate(name="perl-position-tracking", version="0.3.0");
    tok = ParserCrate(name="perl-token", version="0.5.0");
    ast = ParserCrate(name="perl-ast", version="0.8.0");
    lex = ParserCrate(name="perl-lexer", version="0.9.0");
    core = ParserCrate(name="perl-parser-core", version="1.0.0");
    parser = ParserCrate(name="perl-parser", version="1.0.0");
    analyzer = ParserCrate(name="perl-semantic-analyzer", version="0.7.0");
    workspace = ProductCrate(name="perl-workspace");

    g1 = SplitGate(
        gate_id="G1",
        label="facade authority",
        satisfied=True,
    );
    g7 = SplitGate(
        gate_id="G7",
        label="package/release isolation",
        satisfied=False,
    );

    tok +>:DependsOn:+> pos;
    lex +>:DependsOn:+> tok;
    core +>:DependsOn:+> lex;
    core +>:DependsOn:+> ast;
    parser +>:DependsOn:+> core;
    analyzer +>:DependsOn:+> core;
    analyzer +>:DependsOn:+> workspace;

    parser +>:BlockedBy:+> g1;
    parser +>:BlockedBy:+> g7;

    root ++> parser ++> core ++> lex ++> tok ++> pos;
    root ++> ast;
    root ++> analyzer;
    root ++> workspace;

    root spawn TopoProofer();
    root spawn BoundaryAuditor();
    root spawn SplitGateAuditor();
}

"""Paket Linux integration recovery: walk failed suites, classify drift clusters, and flag unpinned dependency violations."""

node TestSuite {
    has name: str = "";
    has target: str = "";
    has failed: int = 0;
    has passed: int = 0;
}

node IntegrationTest {
    has issue_id: str = "";
    has title: str = "";
    has passed: bool = False;
}

node FailureCluster {
    has cluster_name: str = "";
    has classification: str = "";
    has remedy: str = "";
}

node PackageSpec {
    has package_name: str = "";
    has constraint_max: int = 0;
    has resolved_major: int = 0;
    has resolved_version: str = "";
}

edge InSuite { }

edge InCluster { }

edge AssertsPackage { }

walker RecoveryAuditor {
    has pins_needed: int = 0;
    has regressions: int = 0;

    can start with Root entry {
        print("=== Paket Linux integration suite recovery audit ===");
        visit [-->];
    }

    can audit_suite with TestSuite entry {
        print(
            f"\nSuite {here.name} [{here.target}]: "
            f"{here.failed} failed, {here.passed} passed"
        );
        visit [->:InSuite:->];
        visit [-->] else { disengage; };
    }

    can inspect_test with IntegrationTest entry {
        if here.passed {
            visit [-->] else { disengage; };
        } else {
            print(f"  [FAIL] #{here.issue_id} {here.title}");
            visit [->:InCluster:->] else {
                visit [-->] else { disengage; };
            };
        }
    }

    can classify with FailureCluster entry {
        print(f"    -> {here.cluster_name} [{here.classification}]");
        print(f"       remedy: {here.remedy}");
        if here.classification == "product_regression" {
            self.regressions += 1;
        }
        if here.classification == "unpinned_feed" {
            visit [->:AssertsPackage:->] else {
                visit [-->] else { disengage; };
            };
        } else {
            visit [-->] else { disengage; };
        }
    }

    can check_package with PackageSpec entry {
        if here.resolved_major >= here.constraint_max {
            print(
                f"       DRIFT: {here.package_name} resolved "
                f"{here.resolved_version} (major {here.resolved_major}) "
                f"violates < {here.constraint_max}"
            );
            self.pins_needed += 1;
        } else {
            print(
                f"       OK: {here.package_name} {here.resolved_version} "
                f"satisfies < {here.constraint_max}"
            );
        }
        visit [-->] else { disengage; };
    }
}

with entry {
    web_utilities = PackageSpec(
        package_name="Microsoft.AspNetCore.WebUtilities",
        constraint_max=9,
        resolved_major=10,
        resolved_version="10.0.11"
    );

    feed_drift = FailureCluster(
        cluster_name="Live Feeds & Dependency Resolution",
        classification="unpinned_feed",
        remedy="Pin versions where the test validates Paket, not latest NuGet"
    );
    feed_drift +>:AssertsPackage:+> web_utilities;

    mixed_groups = FailureCluster(
        cluster_name="Mixed group dependencies",
        classification="product_regression",
        remedy="Fix Paket behavior before updating fixtures (#2394, #4183)"
    );

    metadata_drift = FailureCluster(
        cluster_name="Assembly Metadata / Package Name Output",
        classification="stale_expectation",
        remedy="Make nupkg assertions SemVer-aware for CI build metadata"
    );

    fw_restriction = IntegrationTest(
        issue_id="framework-restriction",
        title="apply framework restriction force true/false NuGet v2/v3",
        passed=False
    );
    fw_restriction +>:InCluster:+> feed_drift;

    mix_deps = IntegrationTest(
        issue_id="2394",
        title="mix dependencies from multiple groups with conditions",
        passed=False
    );
    mix_deps +>:InCluster:+> mixed_groups;

    net9 = TestSuite(
        name="Linux integration",
        target="net9",
        failed=13,
        passed=203
    );
    net9 +>:InSuite:+> fw_restriction;
    net9 +>:InSuite:+> mix_deps;

    binding_redirect = IntegrationTest(
        issue_id="1783",
        title="generates binding redirect when assembly version differs in main group",
        passed=False
    );
    binding_redirect +>:InCluster:+> metadata_drift;

    fsharp_core = IntegrationTest(
        issue_id="2528",
        title="sdk-2 install should not warn with FSharp.Core",
        passed=False
    );
    fsharp_core +>:InCluster:+> mixed_groups;

    net461 = TestSuite(
        name="Linux integration",
        target="net461",
        failed=3,
        passed=55
    );
    net461 +>:InSuite:+> binding_redirect;
    net461 +>:InSuite:+> fsharp_core;

    root ++> net9 ++> net461;

    auditor = root spawn RecoveryAuditor();
    print(
        f"\nAudit complete: {auditor.pins_needed} pin(s) required, "
        f"{auditor.regressions} regression cluster(s) flagged for product fix"
    );
}

