"""LeetCode Top Interview 150: curated study track with checklist walk and prerequisite cycle guard."""

node Labeled {
    has line: str = "";
}

node StudyPlan(Labeled) {
    has title: str = "";
}

node Topic(Labeled) {
    has name: str = "";
    has focus: str = "";
}

node Problem {
    has title: str = "";
    has technique: str = "";
    has completed: bool = False;
}

edge InTopic { }
edge Requires { }

walker ChecklistWalker {
    has total: int = 0;
    has done: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can open_section with StudyPlan | Topic entry {
        print(here.line);
        visit [->:InTopic:->];
    }

    can mark with Problem entry {
        box = "x" if here.completed else " ";
        print(f"    [{box}] {here.title} ({here.technique})");
        self.total += 1;
        if here.completed {
            self.done += 1;
        }
        visit [-->];
    }
}

walker PrereqGuard {
    has on_path: list[str] = [];
    has settled: list[str] = [];
    has cyclic: bool = False;

    can start with Root entry {
        visit [-->];
    }

    can descend with StudyPlan | Topic entry {
        visit [->:InTopic:->] else {
            visit [-->];
        };
    }

    can probe with Problem entry {
        label = here.title;
        if label in self.on_path {
            self.cyclic = True;
            print(f"    CYCLE blocked at {label}");
            disengage;
        }
        if label in self.settled {
            visit [-->];
            return;
        }
        self.on_path.append(label);
        visit [->:Requires:->] else {
            # no outgoing prerequisites from this problem
        };
        self.settled.append(label);
        trimmed: list[str] = [];
        for item in self.on_path {
            if item != label {
                trimmed.append(item);
            }
        }
        self.on_path = trimmed;
        visit [-->];
    }
}

with entry {
    plan = StudyPlan(
        title="Top Interview 150",
        line="Plan: Top Interview 150"
    );
    root ++> plan;

    arrays = Topic(
        name="Arrays & hashing",
        focus="hash map lookup",
        line="  Arrays & hashing — hash map lookup"
    );
    graphs = Topic(
        name="Trees & graphs",
        focus="DFS/BFS traversal",
        line="  Trees & graphs — DFS/BFS traversal"
    );
    plan +>:InTopic:+> arrays;
    plan +>:InTopic:+> graphs;

    two_sum = Problem(
        title="Two Sum",
        technique="hash map lookup",
        completed=True
    );
    anagram = Problem(
        title="Valid Anagram",
        technique="frequency counting",
        completed=True
    );
    arrays +>:InTopic:+> two_sum;
    arrays +>:InTopic:+> anagram;
    anagram +>:Requires:+> two_sum;

    islands = Problem(
        title="Number of Islands",
        technique="grid DFS/BFS",
        completed=True
    );
    clone_g = Problem(
        title="Clone Graph",
        technique="traversal + visited map"
    );
    schedule = Problem(
        title="Course Schedule",
        technique="cycle detection / topo sort"
    );
    graphs +>:InTopic:+> islands;
    graphs +>:InTopic:+> clone_g;
    graphs +>:InTopic:+> schedule;
    clone_g +>:Requires:+> islands;
    schedule +>:Requires:+> clone_g;
    islands +>:Requires:+> schedule;

    checklist = ChecklistWalker();
    root spawn checklist;
    print(f"Checklist progress: {checklist.done}/{checklist.total} complete");

    guard = PrereqGuard();
    root spawn guard;
    if guard.cyclic {
        print("Prerequisite graph: cyclic — fix ordering before studying");
    } else {
        print(f"Prerequisite graph: acyclic ({len(guard.settled)} problems ordered)");
    }
}

