    node_compact = node_ty.debug_compact;
    needs_unsafe = deriver.root_requires_unsafe;
}

"""Paket Linux integration recovery: walk failed suites, classify drift clusters, and flag unpinned dependency violations."""

edge InSuite { }

edge InCluster { }

edge AssertsPackage { }

node TestSuite {
    has name: str = "";
    has target: str = "";
    has failed: int = 0;
    has passed: int = 0;
}

node IntegrationTest {
    has issue_id: str = "";
    has title: str = "";
    has passed: bool = False;
}

node FailureCluster {
    has cluster_name: str = "";
    has classification: str = "";
    has remedy: str = "";
}

node PackageSpec {
    has package_name: str = "";
    has constraint_max: int = 0;
    has resolved_major: int = 0;
    has resolved_version: str = "";
}

walker RecoveryAuditor {
    has pins_needed: int = 0;
    has regressions: int = 0;

    can start with Root entry {
        print("=== Paket Linux integration suite recovery audit ===");
        visit [-->];
    }

    can audit_suite with TestSuite entry {
        print(
            f"\nSuite {here.name} [{here.target}]: "
            f"{here.failed} failed, {here.passed} passed"
        );
        visit [->:InSuite:->] else {
            visit [-->] else { disengage; };
        };
    }

    can inspect_test with IntegrationTest entry {
        if here.passed {
            visit [-->] else { disengage; };
        } else {
            print(f"  [FAIL] #{here.issue_id} {here.title}");
            visit [->:InCluster:->] else {
                visit [-->] else { disengage; };
            };
        }
    }

    can classify with FailureCluster entry {
        print(f"    -> {here.cluster_name} [{here.classification}]");
        print(f"       remedy: {here.remedy}");
        if here.classification == "product_regression" {
            self.regressions += 1;
        }
        if here.classification == "unpinned_feed" {
            visit [->:AssertsPackage:->] else {
                visit [-->] else { disengage; };
            };
        } else {
            visit [-->] else { disengage; };
        }
    }

    can check_package with PackageSpec entry {
        if here.resolved_major >= here.constraint_max {
            print(
                f"       DRIFT: {here.package_name} resolved "
                f"{here.resolved_version} (major {here.resolved_major}) "
                f"violates < {here.constraint_max}"
            );
            self.pins_needed += 1;
        } else {
            print(
                f"       OK: {here.package_name} {here.resolved_version} "
                f"satisfies < {here.constraint_max}"
            );
        }
        visit [-->] else { disengage; };
    }
}

with entry {
    web_utilities = PackageSpec(
        package_name="Microsoft.AspNetCore.WebUtilities",
        constraint_max=9,
        resolved_major=10,
        resolved_version="10.0.11"
    );

    feed_drift = FailureCluster(
        cluster_name="Live Feeds & Dependency Resolution",
        classification="unpinned_feed",
        remedy="Pin versions where the test validates Paket, not latest NuGet"
    );
    feed_drift +>:AssertsPackage:+> web_utilities;

    mixed_groups = FailureCluster(
        cluster_name="Mixed group dependencies",
        classification="product_regression",
        remedy="Fix Paket behavior before updating fixtures (#2394, #4183)"
    );

    metadata_drift = FailureCluster(
        cluster_name="Assembly Metadata / Package Name Output",
        classification="stale_expectation",
        remedy="Make nupkg assertions SemVer-aware for CI build metadata"
    );

    fw_restriction = IntegrationTest(
        issue_id="framework-restriction",
        title="apply framework restriction force true/false NuGet v2/v3",
        passed=False
    );
    fw_restriction +>:InCluster:+> feed_drift;

    mix_deps = IntegrationTest(
        issue_id="2394",
        title="mix dependencies from multiple groups with conditions",
        passed=False
    );
    mix_deps +>:InCluster:+> mixed_groups;

    net9 = TestSuite(
        name="Linux integration",
        target="net9",
        failed=13,
        passed=203
    );
    net9 +>:InSuite:+> fw_restriction;
    net9 +>:InSuite:+> mix_deps;

    binding_redirect = IntegrationTest(
        issue_id="1783",
        title="generates binding redirect when assembly version differs in main group",
        passed=False
    );
    binding_redirect +>:InCluster:+> metadata_drift;

    fsharp_core = IntegrationTest(
        issue_id="2528",
        title="sdk-2 install should not warn with FSharp.Core",
        passed=False
    );
    fsharp_core +>:InCluster:+> mixed_groups;

    net461 = TestSuite(
        name="Linux integration",
        target="net461",
        failed=3,
        passed=55
    );
    net461 +>:InSuite:+> binding_redirect;
    net461 +>:InSuite:+> fsharp_core;

    root ++> net9 ++> net461;

    auditor = root spawn RecoveryAuditor();
    print(
        f"\nAudit complete: {auditor.pins_needed} pin(s) required, "
        f"{auditor.regressions} regression cluster(s) flagged for product fix"
    );
}

"""LeetCode Top Interview 150: curated study track with checklist walk and prerequisite cycle guard."""

node Labeled {
    has line: str = "";
}

node StudyPlan(Labeled) {
    has title: str = "";
}

node Topic(Labeled) {
    has name: str = "";
    has focus: str = "";
}

node Problem {
    has title: str = "";
    has technique: str = "";
    has completed: bool = False;
}

edge InTopic { }
edge Requires { }

walker ChecklistWalker {
    has total: int = 0;
    has done: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can tour with StudyPlan | Topic entry {
        print(here.line);
        visit [->:InTopic:->];
    }

    can mark with Problem entry {
        box = "x" if here.completed else " ";
        print(f"    [{box}] {here.title} ({here.technique})");
        self.total += 1;
        if here.completed {
            self.done += 1;
        }
    }
}

walker PrereqGuard {
    has on_path: list[str] = [];
    has settled: list[str] = [];
    has cyclic: bool = False;

    can start with Root entry {
        visit [-->];
    }

    can descend with StudyPlan | Topic entry {
        visit [->:InTopic:->];
    }

    can probe with Problem entry {
        label = here.title;
        if label in self.on_path {
            self.cyclic = True;
            print(f"    CYCLE blocked at {label}");
            disengage;
        }
        if label in self.settled {
            disengage;
        }
        self.on_path.append(label);
        visit [->:Requires:->] else {
            # no outgoing prerequisites from this problem
        };
        self.settled.append(label);
        trimmed: list[str] = [];
        for item in self.on_path {
            if item != label {
                trimmed.append(item);
            }
        }
        self.on_path = trimmed;
    }
}

with entry {
    plan = StudyPlan(
        title="Top Interview 150",
        line="Plan: Top Interview 150"
    );
    root ++> plan;

    arrays = Topic(
        name="Arrays & hashing",
        focus="hash map lookup",
        line="  Arrays & hashing — hash map lookup"
    );
    graphs = Topic(
        name="Trees & graphs",
        focus="DFS/BFS traversal",
        line="  Trees & graphs — DFS/BFS traversal"
    );
    plan +>:InTopic:+> arrays;
    plan +>:InTopic:+> graphs;

    two_sum = Problem(
        title="Two Sum",
        technique="hash map lookup",
        completed=True
    );
    anagram = Problem(
        title="Valid Anagram",
        technique="frequency counting",
        completed=True
    );
    arrays +>:InTopic:+> two_sum;
    arrays +>:InTopic:+> anagram;
    anagram +>:Requires:+> two_sum;

    islands = Problem(
        title="Number of Islands",
        technique="grid DFS/BFS",
        completed=True
    );
    clone_g = Problem(
        title="Clone Graph",
        technique="traversal + visited map"
    );
    schedule = Problem(
        title="Course Schedule",
        technique="cycle detection / topo sort"
    );
    graphs +>:InTopic:+> islands;
    graphs +>:InTopic:+> clone_g;
    graphs +>:InTopic:+> schedule;
    clone_g +>:Requires:+> islands;
    schedule +>:Requires:+> clone_g;
    islands +>:Requires:+> schedule;

    checklist = ChecklistWalker();
    root spawn checklist;
    print(f"Checklist progress: {checklist.done}/{checklist.total} complete");

    guard = PrereqGuard();
    root spawn guard;
    if guard.cyclic {
        print("Prerequisite graph: cyclic — fix ordering before studying");
    } else {
        print(f"Prerequisite graph: acyclic ({len(guard.settled)} problems ordered)");
    }
}

