walker DebugDeriver {
    has depth: int = 0;
    has max_depth: int = 64;
    has visited_keys: list[str] = [];
    has scratch_compact: str = "";
    has scratch_pretty: str = "";
    has child_unsafe: bool = False;
    has field_parts_compact: list[str] = [];
    has field_parts_pretty: list[str] = [];
    has variant_parts_compact: list[str] = [];
    has variant_parts_pretty: list[str] = [];
    has root_requires_unsafe: bool = False;

    can start with Root entry {
        visit [->:Registers:->] else { visit [-->] else { disengage; } };
    }

    can format_primitive with PrimitiveType entry {
        if here.type_key in self.visited_keys {
            here.debug_compact = f"<cycle:{here.name}>";
            here.debug_pretty = f"<cycle:{here.name}>";
            disengage;
        }
        if self.depth >= self.max_depth {
            here.debug_compact = "<depth>";
            here.debug_pretty = "<depth>";
            disengage;
        }
        self.visited_keys.append(here.type_key);
        unsafe_leaf = here.is_raw_pointer;
        here.requires_unsafe = unsafe_leaf;
        compact = here.name;
        pretty = here.name;
        if unsafe_leaf {
            compact = f"unsafe:{compact}";
            pretty = f"unsafe:{pretty}";
            self.root_requires_unsafe = True;
        }
        here.debug_compact = compact;
        here.debug_pretty = pretty;
        self.scratch_compact = compact;
        self.scratch_pretty = pretty;
        if here.requires_unsafe {
            self.child_unsafe = True;
        }
        visit [-->];
    }

    can enter_box with BoxType entry {
        if here.type_key in self.visited_keys {
            here.debug_compact = f"<cycle:{here.name}>";
            here.debug_pretty = f"<cycle:{here.name}>";
            disengage;
        }
        if self.depth >= self.max_depth {
            here.debug_compact = "<depth>";
            here.debug_pretty = "<depth>";
            disengage;
        }
        self.visited_keys.append(here.type_key);
        depth_next = self.depth + 1;
        self.depth = depth_next;
        self.child_unsafe = False;
        visit [->:HasInner:->] else { disengage; }
    }

    can exit_box with BoxType exit {
        inner_c = self.scratch_compact;
        inner_p = self.scratch_pretty;
        compact = f"Box({inner_c})";
        pretty = f"Box(\n  {inner_p}\n)";
        here.requires_unsafe = self.child_unsafe;
        if self.child_unsafe {
            self.root_requires_unsafe = True;
            compact = f"unsafe:{compact}";
            pretty = f"unsafe:{pretty}";
        }
        here.debug_compact = compact;
        here.debug_pretty = pretty;
        self.scratch_compact = compact;
        self.scratch_pretty = pretty;
        self.depth = self.depth - 1;
        self.visited_keys.pop();
    }

    can enter_struct with StructType entry {
        if here.type_key in self.visited_keys {
            here.debug_compact = f"<cycle:{here.name}>";
            here.debug_pretty = f"<cycle:{here.name}>";
            disengage;
        }
        if self.depth >= self.max_depth {
            here.debug_compact = "<depth>";
            here.debug_pretty = "<depth>";
            disengage;
        }
        self.visited_keys.append(here.type_key);
        depth_next = self.depth + 1;
        self.depth = depth_next;
        self.field_parts_compact = [];
        self.field_parts_pretty = [];
        self.child_unsafe = False;
        visit [->:InStruct:->] else { disengage; }
    }

    can exit_struct with StructType exit {
        inner_c = "";
        for (i, part) in enumerate(self.field_parts_compact) {
            sep = ", " if i > 0 else "";
            inner_c = f"{inner_c}{sep}{part}";
        }
        inner_p = "";
        for (i, part) in enumerate(self.field_parts_pretty) {
            sep = ",\n  " if i > 0 else "";
            inner_p = f"{inner_p}{sep}{part}";
        }
        compact = f"{here.name} {{ {inner_c} }}";
        pretty = f"{here.name} {{\n  {inner_p}\n}}";
        here.requires_unsafe = self.child_unsafe;
        if self.child_unsafe {
            self.root_requires_unsafe = True;
            compact = f"unsafe:{compact}";
            pretty = f"unsafe:{pretty}";
        }
        here.debug_compact = compact;
        here.debug_pretty = pretty;
        self.scratch_compact = compact;
        self.scratch_pretty = pretty;
        self.depth = self.depth - 1;
        self.visited_keys.pop();
    }

    can enter_enum with EnumType entry {
        if here.type_key in self.visited_keys {
            here.debug_compact = f"<cycle:{here.name}>";
            here.debug_pretty = f"<cycle:{here.name}>";
            disengage;
        }
        if self.depth >= self.max_depth {
            here.debug_compact = "<depth>";
            here.debug_pretty = "<depth>";
            disengage;
        }
        self.visited_keys.append(here.type_key);
        depth_next = self.depth + 1;
        self.depth = depth_next;
        self.variant_parts_compact = [];
        self.variant_parts_pretty = [];
        self.child_unsafe = False;
        visit [->:InEnum:->] else { disengage; }
    }

    can exit_enum with EnumType exit {
        inner_c = "";
        for (i, part) in enumerate(self.variant_parts_compact) {
            sep = " | " if i > 0 else "";
            inner_c = f"{inner_c}{sep}{part}";
        }
        inner_p = "";
        for (i, part) in enumerate(self.variant_parts_pretty) {
            sep = "\n| " if i > 0 else "";
            inner_p = f"{inner_p}{sep}{part}";
        }
        compact = f"{here.name}({inner_c})";
        pretty = f"{here.name}(\n{inner_p}\n)";
        here.requires_unsafe = self.child_unsafe;
        if self.child_unsafe {
            self.root_requires_unsafe = True;
            compact = f"unsafe:{compact}";
            pretty = f"unsafe:{pretty}";
        }
        here.debug_compact = compact;
        here.debug_pretty = pretty;
        self.scratch_compact = compact;
        self.scratch_pretty = pretty;
        self.depth = self.depth - 1;
        self.visited_keys.pop();
    }

    can enter_field with FieldSlot entry {
        self.child_unsafe = False;
        visit [->:FieldType:->] else { disengage; }
    }

    can exit_field with FieldSlot exit {
        part_c = f"{here.field_name}: {self.scratch_compact}";
        part_p = f"{here.field_name}: {self.scratch_pretty}";
        self.field_parts_compact.append(part_c);
        self.field_parts_pretty.append(part_p);
        if self.child_unsafe {
            self.root_requires_unsafe = True;
        }
        visit [-->];
    }

    can enter_variant with VariantSlot entry {
        self.child_unsafe = False;
        visit [->:VariantType:->] else { disengage; }
    }

    can exit_variant with VariantSlot exit {
        part_c = f"{here.variant_name}({self.scratch_compact})";
        part_p = f"{here.variant_name}(\n  {self.scratch_pretty}\n)";
        self.variant_parts_compact.append(part_c);
        self.variant_parts_pretty.append(part_p);
        if self.child_unsafe {
            self.root_requires_unsafe = True;
        }
        visit [-->];
    }

    can bubble_unsafe with PrimitiveType | BoxType | StructType | EnumType entry {
        if here.requires_unsafe {
            self.child_unsafe = True;
        }
        visit [-->];
    }
}

with entry {
    i32 = PrimitiveType(type_key="prim.i32", name="i32");
    raw_ptr = PrimitiveType(
        type_key="prim.raw_ptr",
        name="*const u8",
        is_raw_pointer=True
    );
    point = StructType(type_key="struct.Point", name="Point");
    node_ty = StructType(type_key="struct.Node", name="Node");
