    option_compact = option.debug_compact;
    option_pretty = option.debug_pretty;
    node_compact = node_ty.debug_compact;
    needs_unsafe = deriver.root_requires_unsafe;
}

"""Session artifacts: recursive flat listing and nested cleanup with inode cycle guards."""

glob ARTIFACT_METADATA_FILE = ".spur-artifacts.json";

node SessionArtifacts {
    has session_id: str = "";
}

node ArtifactDir {
    has name: str = "";
    has dev: int = 0;
    has ino: int = 0;
}

node ArtifactFile {
    has name: str = "";
    has relative_path: str = "";
    has updated_at: int = 0;
    has available: bool = True;
}

edge Contains { }

walker ArtifactLister {
    has listed: list[str] = [];
    has prefix: str = "";
    has chain: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can walk_session with SessionArtifacts entry {
        visit [->:Contains:->] else { disengage; };
    }

    can walk_dir with ArtifactDir entry {
        key = f"{here.dev}:{here.ino}";
        cyclic = False;
        for seen in self.chain {
            if seen == key {
                cyclic = True;
            }
        }
        if cyclic {
            print(f"[cycle-guard] skip {self.prefix}{here.name}/");
            visit [-->];
        } else {
            self.chain.append(key);
            saved_prefix = self.prefix;
            next_prefix = f"{self.prefix}{here.name}/" if self.prefix else f"{here.name}/";
            self.prefix = next_prefix;
            visit [->:Contains:->] else { };
            self.prefix = saved_prefix;
            self.chain.pop();
            visit [-->];
        }
    }

    can list_file with ArtifactFile entry {
        if not here.available {
            visit [-->];
        } else if here.name == ARTIFACT_METADATA_FILE {
            visit [-->];
        } else {
            rel = here.relative_path if here.relative_path else f"{self.prefix}{here.name}";
            self.listed.append(rel);
            print(f"[artifact] {rel} (updated={here.updated_at})");
            visit [-->];
        }
    }
}

walker ArtifactCleaner {
    has keep_names: list[str] = [];
    has removed: list[str] = [];
    has prefix: str = "";
    has chain: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can clean_session with SessionArtifacts entry {
        visit [->:Contains:->] else { disengage; };
    }

    can clean_dir with ArtifactDir entry {
        key = f"{here.dev}:{here.ino}";
        cyclic = False;
        for seen in self.chain {
            if seen == key {
                cyclic = True;
            }
        }
        if cyclic {
            visit [-->];
        } else {
            self.chain.append(key);
            saved_prefix = self.prefix;
            next_prefix = f"{self.prefix}{here.name}/" if self.prefix else f"{here.name}/";
            self.prefix = next_prefix;
            visit [->:Contains:->] else { };
            self.prefix = saved_prefix;
            self.chain.pop();
            visit [-->];
        }
    }

    can purge_file with ArtifactFile entry {
        rel = here.relative_path if here.relative_path else f"{self.prefix}{here.name}";
        should_keep = False;
        if here.name == ARTIFACT_METADATA_FILE {
            should_keep = True;
        }
        for k in self.keep_names {
            if k == here.name {
                should_keep = True;
            }
        }
        if should_keep {
            print(f"[keep] {rel}");
        } else {
            here.available = False;
            self.removed.append(rel);
            print(f"[rm] {rel}");
        }
        visit [-->];
    }
}

