"""Edge-deletion diameter profile: source diameter plus one row per source edge."""

node Vertex {
    has name: str = "";
    has dist: int = -1;
}

edge Link {
    has edge_id: int = 0;
}

node ProfileRow {
    has edge_id: int = 0;
    has left_name: str = "";
    has right_name: str = "";
    has status: str = "";
    has post_diameter: int = -1;
}

walker DepthClear {
    can start with Root entry {
        visit [-->[?:Vertex]] else { disengage; };
    }

    can wipe with Vertex entry {
        here.dist = -1;
        visit [-->];
    }
}

walker PropagateStep {
    has blocked: int = -1;
    has parent_dist: int = 0;

    can start with Root entry {
        visit [-->[?:Vertex]] else { disengage; };
    }

    can relay with Vertex entry {
        if here.dist < 0 {
            disengage;
        }
        self.parent_dist = here.dist;
        visit [->:Link:->];
    }

    can hop with Link entry {
        if here.edge_id == self.blocked {
            disengage;
        }
        visit [-->];
    }

    can relax with Vertex entry {
        cand = self.parent_dist + 1;
        if here.dist < 0 {
            here.dist = cand;
        } else {
            if cand < here.dist {
                here.dist = cand;
            }
        }
        visit [-->];
    }
}

walker EccScan {
    has max_val: int = 0;

    can start with Root entry {
        visit [-->[?:Vertex]] else { disengage; };
    }

    can sweep with Vertex entry {
        if here.dist > self.max_val {
            self.max_val = here.dist;
        }
        visit [-->];
    }
}

walker EccentricityMeasure {
    has blocked: int = -1;
    has origin: str = "";
    has limit: int = 0;
    has eccentricity: int = 0;

    can start with Root entry {
        DepthClear() spawn root;
        visit [-->[?:Vertex]] else { disengage; };
    }

    can seed with Vertex entry {
        if here.name != self.origin {
            disengage;
        }
        here.dist = 0;
        r = 0;
        while r < self.limit {
            PropagateStep(blocked=self.blocked) spawn root;
            r += 1;
        }
        es = EccScan();
        root spawn es;
        self.eccentricity = es.max_val;
        visit [-->];
    }
}

walker DiameterMeasure {
    has blocked: int = -1;
    has names: list[str] = [];
    has limit: int = 0;
    has diameter: int = 0;

    can start with Root entry {
        for nm in self.names {
            em = EccentricityMeasure(
                blocked=self.blocked,
                origin=nm,
                limit=self.limit
            );
            root spawn em;
            next_dia = em.eccentricity if em.eccentricity > self.diameter else self.diameter;
            self.diameter = next_dia;
        }
        visit [-->];
    }
}

walker ReachTally {
    has blocked: int = -1;
    has count: int = 0;
    has seen: list[str] = [];

    can start with Vertex entry {
        if here.name in self.seen {
            disengage;
        }
        self.seen.append(here.name);
        self.count += 1;
        visit [->:Link:->] else { disengage; };
    }

    can hop with Link entry {
        if here.edge_id == self.blocked {
            disengage;
        }
        visit [-->];
    }

    can flood with Vertex entry {
        if here.name in self.seen {
            disengage;
        }
        self.seen.append(here.name);
        self.count += 1;
        visit [->:Link:->] else { disengage; };
    }
}

walker BridgeCheck {
    has blocked: int = -1;
    has expected: int = 0;
    has connected: bool = False;
    has probed: bool = False;

    can start with Root entry {
        visit [-->[?:Vertex]] else { disengage; };
    }

    can probe with Vertex entry {
        if self.probed {
            disengage;
        }
        self.probed = True;
        rt = ReachTally(blocked=self.blocked);
        here spawn rt;
        self.connected = rt.count == self.expected;
        disengage;
    }
}

walker DeletionProfiler {
    has roster: list[int] = [];
    has left_names: list[str] = [];
    has right_names: list[str] = [];
    has names: list[str] = [];
    has rows: list[ProfileRow] = [];

    can start with Root entry {
        visit [-->[?:Vertex]] else { disengage; };
        n = len(self.names);
        dm0 = DiameterMeasure(blocked=-1, names=self.names, limit=n);
        root spawn dm0;
        print(f"source diameter: {dm0.diameter}");
        for (i, eid) in enumerate(self.roster) {
            bc = BridgeCheck(blocked=eid, expected=n);
            root spawn bc;
            if bc.connected {
                dm = DiameterMeasure(blocked=eid, names=self.names, limit=n);
                root spawn dm;
                row = ProfileRow(
                    edge_id=eid,
                    left_name=self.left_names[i],
                    right_name=self.right_names[i],
                    status="OK",
                    post_diameter=dm.diameter
                );
            } else {
                row = ProfileRow(
                    edge_id=eid,
                    left_name=self.left_names[i],
                    right_name=self.right_names[i],
                    status="DISCONNECTED",
                    post_diameter=-1
                );
            }
            self.rows.append(row);
            outcome = f"{row.post_diameter}" if row.status == "OK" else row.status;
            print(
                f"edge {row.edge_id} ({row.left_name}-{row.right_name}): "
                f"{row.status} post_diameter={outcome}"
            );
        }
        visit [-->];
    }

    can collect with Vertex entry {
        self.names.append(here.name);
        visit [-->];
    }
}

with entry {
    a = Vertex(name="A");
    b = Vertex(name="B");
    c = Vertex(name="C");
    d = Vertex(name="D");
    root ++> a ++> b ++> c ++> d;
    a +>:Link(edge_id=0):+> b;
    b +>:Link(edge_id=0):+> a;
    b +>:Link(edge_id=1):+> c;
    c +>:Link(edge_id=1):+> b;
    c +>:Link(edge_id=2):+> d;
    d +>:Link(edge_id=2):+> c;
    d +>:Link(edge_id=3):+> a;
    a +>:Link(edge_id=3):+> d;
    prof = DeletionProfiler(
        roster=[0, 1, 2, 3],
        left_names=["A", "B", "C", "D"],
        right_names=["B", "C", "D", "A"]
    );
    root spawn prof;
}

"""CDN security PILOT-03: inventory NestJS-scale projects, run cold/warm analysis, and cascade cache invalidation over dependency stages."""

node Project {
    has name: str = "";
    has file_count: int = 0;
}

node Controller {
    has name: str = "";
    has route_prefix: str = "";
}

node Operation {
    has http_method: str = "";
    has route: str = "";
}

node AnalysisArtifact {
    has label: str = "";
    has cached: bool = False;
}

node OpenAPISpec(AnalysisArtifact) {
    has operation_count: int = 0;
}

node PolicyBundle(AnalysisArtifact) {
    has rule_count: int = 0;
}

node SourceModule(AnalysisArtifact) {
    has ts_file_count: int = 0;
}

node Finding {
    has severity: str = "Warning";
    has category: str = "";
    has instance_id: str = "";
    has reviewed: bool = False;
}

edge Hosts { }
edge Exposes { }
edge DependsOn { has stage_order: int = 0; }
edge Emits { }

walker ScaleInventory {
    has controller_total: int = 0;
    has operation_total: int = 0;
    has error_total: int = 0;
    has warning_total: int = 0;
    has partial_total: int = 0;

    can start with Root entry {
        print("=== PILOT-03 Pre-run Inventory ===");
        visit [-->];
    }

    can inventory with Project entry {
        print(f"Project '{here.name}': {here.file_count} source files");
        visit [->:Hosts:->];
    }

    can tally_controller with Controller entry {
        self.controller_total += 1;
        print(f"  Controller {here.name} @ {here.route_prefix}");
        visit [->:Exposes:->];
    }

    can tally_operation with Operation entry {
        self.operation_total += 1;
        print(f"    Operation {here.http_method} {here.route}");
        visit [->:Emits:->];
    }

    can review_finding with Finding entry {
        if here.severity == "Error" {
            self.error_total += 1;
            here.reviewed = True;
            print(f"      [ERROR]   {here.category} ({here.instance_id}) — reviewed");
        } else {
            if here.severity == "Warning" {
                self.warning_total += 1;
                print(f"      [WARNING] {here.category} ({here.instance_id})");
            } else {
                self.partial_total += 1;
                print(f"      [PARTIAL] {here.category} ({here.instance_id})");
            }
        }
        disengage;
    }
}

walker AnalysisRunner {
    has mode: str = "cold";
    has stages_run: int = 0;
    has cache_hits: int = 0;

    can start with Root entry {
        mode_label = self.mode.upper();
        print(f"=== {mode_label} Source-aware Analysis ===");
        visit [-->];
    }

    can execute with OpenAPISpec | PolicyBundle | SourceModule entry {
        if here.cached and self.mode == "warm" {
            self.cache_hits += 1;
            print(f"  [CACHE HIT] {here.label}");
        } else {
            self.stages_run += 1;
            here.cached = True;
            print(f"  [ANALYZE] {here.label}");
        }
        visit [->:DependsOn:->] else { disengage; };
    }
}

walker CacheInvalidator {
    has visited_labels: list[str] = [];
    has invalidated_count: int = 0;

    can invalidate_origin with OpenAPISpec | PolicyBundle | SourceModule entry {
        here.cached = False;
        self.invalidated_count += 1;
        print(f"  Invalidated origin: {here.label}");
        visit [->:DependsOn:->] else { disengage; };
    }

    can cascade with PolicyBundle | SourceModule entry {
        label = here.label;
        if label in self.visited_labels {
            print(f"  [CYCLE GUARD] stopping at {label}");
            disengage;
        }
        self.visited_labels.append(label);
        here.cached = False;
        self.invalidated_count += 1;
        print(f"  Invalidated downstream: {here.label}");
        visit [->:DependsOn:->] else { disengage; };
    }
}

