"""Edge-deletion diameter profile: source diameter plus one row per source edge."""

node Vertex {
    has name: str = "";
    has dist: int = -1;
}

edge Link {
    has edge_id: int = 0;
}

node ProfileRow {
    has edge_id: int = 0;
    has left_name: str = "";
    has right_name: str = "";
    has status: str = "";
    has post_diameter: int = -1;
}

walker DistWipe {
    can start with Root entry {
        visit [-->];
    }

    can wipe with Vertex entry {
        here.dist = -1;
        visit [-->];
    }
}

walker SeedOrigin {
    has origin: str = "";

    can start with Root entry {
        visit [-->];
    }

    can mark with Vertex entry {
        if here.name == self.origin {
            here.dist = 0;
        }
        visit [-->];
    }
}

walker PropagateLayer {
    has blocked: int = -1;
    has layer: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can expand with Vertex entry {
        if here.dist == self.layer {
            visit [->:Link:->] else { visit [-->]; };
        } else {
            visit [-->];
        }
    }

    can hop with Link entry {
        if here.edge_id == self.blocked {
            disengage;
        }
        visit [-->];
    }

    can settle with Vertex entry {
        if here.dist < 0 {
            here.dist = self.layer + 1;
        }
        disengage;
    }
}

walker MaxDistScan {
    has max_val: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can scan with Vertex entry {
        next_m = here.dist if here.dist > self.max_val else self.max_val;
        self.max_val = next_m;
        visit [-->];
    }
}

walker EccentricityCalc {
    has blocked: int = -1;
    has origin: str = "";
    has limit: int = 0;
    has eccentricity: int = 0;

    can start with Root entry {
        DistWipe() spawn root;
        SeedOrigin(origin=self.origin) spawn root;
        layer = 0;
        while layer < self.limit {
            PropagateLayer(blocked=self.blocked, layer=layer) spawn root;
            layer += 1;
        }
        mds = MaxDistScan();
        root spawn mds;
        self.eccentricity = mds.max_val;
        disengage;
    }
}

walker DiameterCalc {
    has blocked: int = -1;
    has names: list[str] = [];
    has limit: int = 0;
    has diameter: int = 0;

    can start with Root entry {
        for nm in self.names {
            ec = EccentricityCalc(
                blocked=self.blocked,
                origin=nm,
                limit=self.limit
            );
            root spawn ec;
            next_d = ec.eccentricity if ec.eccentricity > self.diameter else self.diameter;
            self.diameter = next_d;
        }
        disengage;
    }
}

walker ReachCount {
    has blocked: int = -1;
    has seen: list[str] = [];
    has count: int = 0;

    can start with Vertex entry {
        if here.name in self.seen {
            disengage;
        }
        self.seen.append(here.name);
        self.count += 1;
        visit [->:Link:->] else { disengage; };
    }

    can hop with Link entry {
        if here.edge_id == self.blocked {
            disengage;
        }
        visit [-->];
    }

    can extend with Vertex entry {
        if here.name in self.seen {
            disengage;
        }
        self.seen.append(here.name);
        self.count += 1;
        visit [->:Link:->] else { disengage; };
    }
}

walker BridgeCheck {
    has blocked: int = -1;
    has expected: int = 0;
    has connected: bool = False;

    can start with Root entry {
        visit [-->];
    }

    can probe with Vertex entry {
        rc = ReachCount(blocked=self.blocked);
        here spawn rc;
        self.connected = rc.count == self.expected;
        disengage;
    }
}

walker DeletionProfiler {
    has roster: list[int] = [];
    has left_names: list[str] = [];
    has right_names: list[str] = [];
    has names: list[str] = [];
    has rows: list[ProfileRow] = [];

    can start with Root entry {
        visit [-->];
        n = len(self.names);
        dm0 = DiameterCalc(blocked=-1, names=self.names, limit=n);
        root spawn dm0;
        print(f"source diameter: {dm0.diameter}");
        for (i, eid) in enumerate(self.roster) {
            bc = BridgeCheck(blocked=eid, expected=n);
            root spawn bc;
            if bc.connected {
                dm = DiameterCalc(blocked=eid, names=self.names, limit=n);
                root spawn dm;
                row = ProfileRow(
                    edge_id=eid,
                    left_name=self.left_names[i],
                    right_name=self.right_names[i],
                    status="OK",
                    post_diameter=dm.diameter
                );
            } else {
                row = ProfileRow(
                    edge_id=eid,
                    left_name=self.left_names[i],
                    right_name=self.right_names[i],
                    status="DISCONNECTED",
                    post_diameter=-1
                );
            }
            self.rows.append(row);
            outcome = f"{row.post_diameter}" if row.status == "OK" else row.status;
            print(
                f"edge {row.edge_id} ({row.left_name}-{row.right_name}): "
                f"{row.status} post_diameter={outcome}"
            );
        }
        disengage;
    }

    can collect with Vertex entry {
        self.names.append(here.name);
        visit [-->];
    }
}

with entry {
    a = Vertex(name="A");
    b = Vertex(name="B");
    c = Vertex(name="C");
    d = Vertex(name="D");
    root ++> a ++> b ++> c ++> d;
    a +>:Link(edge_id=0):+> b;
    b +>:Link(edge_id=0):+> a;
    b +>:Link(edge_id=1):+> c;
    c +>:Link(edge_id=1):+> b;
    c +>:Link(edge_id=2):+> d;
    d +>:Link(edge_id=2):+> c;
    d +>:Link(edge_id=3):+> a;
    a +>:Link(edge_id=3):+> d;
    prof = DeletionProfiler(
        roster=[0, 1, 2, 3],
        left_names=["A", "B", "C", "D"],
        right_names=["B", "C", "D", "A"]
    );
    root spawn prof;
}

"""Session artifacts: recursive flat listing and nested cleanup with inode cycle guards."""

node SessionArtifacts {
    has session_id: str = "";
}

node ArtifactDir {
    has name: str = "";
    has dev: int = 0;
    has ino: int = 0;
}

node ArtifactFile {
    has name: str = "";
    has relative_path: str = "";
    has updated_at: int = 0;
    has available: bool = True;
}

edge Contains { }

walker ArtifactLister {
    has listed: list[str] = [];
    has prefix: str = "";
    has chain: list[str] = [];

    def in_chain(key: str) -> bool {
        for seen in self.chain {
            if seen == key {
                return True;
            }
        }
        return False;
    }

    can start with Root entry {
        visit [-->];
    }

    can walk_session with SessionArtifacts entry {
        visit [->:Contains:->] else { disengage; };
    }

    can walk_dir with ArtifactDir entry {
        key = f"{here.dev}:{here.ino}";
        if self.in_chain(key) {
            print(f"[cycle-guard] skip {self.prefix}{here.name}/");
            visit [-->];
        } else {
            self.chain.append(key);
            saved_prefix = self.prefix;
            if self.prefix != "" {
                next_prefix = f"{self.prefix}{here.name}/";
            } else {
                next_prefix = f"{here.name}/";
            }
            self.prefix = next_prefix;
            visit [->:Contains:->];
            self.prefix = saved_prefix;
            self.chain.pop();
            visit [-->];
        }
    }

    can list_file with ArtifactFile entry {
        if not here.available {
            visit [-->];
        } else {
            if here.name == ".spur-artifacts.json" {
                visit [-->];
            } else {
                if here.relative_path != "" {
                    rel = here.relative_path;
                } else {
                    rel = f"{self.prefix}{here.name}";
                }
                self.listed.append(rel);
                print(f"[artifact] {rel} (updated={here.updated_at})");
                visit [-->];
            }
        }
    }
}

walker ArtifactCleaner {
    has keep_names: list[str] = [];
    has removed: list[str] = [];
    has prefix: str = "";
    has chain: list[str] = [];

    def in_chain(key: str) -> bool {
        for seen in self.chain {
            if seen == key {
                return True;
            }
        }
        return False;
    }

    def should_keep(name: str) -> bool {
        if name == ".spur-artifacts.json" {
            return True;
        }
        for k in self.keep_names {
            if k == name {
                return True;
            }
        }
        return False;
    }

    can start with Root entry {
        visit [-->];
    }

    can clean_session with SessionArtifacts entry {
        visit [->:Contains:->] else { disengage; };
    }

    can clean_dir with ArtifactDir entry {
        key = f"{here.dev}:{here.ino}";
        if self.in_chain(key) {
            visit [-->];
        } else {
            self.chain.append(key);
            saved_prefix = self.prefix;
            if self.prefix != "" {
                next_prefix = f"{self.prefix}{here.name}/";
            } else {
                next_prefix = f"{here.name}/";
            }
            self.prefix = next_prefix;
            visit [->:Contains:->];
            self.prefix = saved_prefix;
            self.chain.pop();
            visit [-->];
        }
    }

    can purge_file with ArtifactFile entry {
        if here.relative_path != "" {
            rel = here.relative_path;
        } else {
            rel = f"{self.prefix}{here.name}";
        }
        if self.should_keep(here.name) {
            print(f"[keep] {rel}");
        } else {
            here.available = False;
            self.removed.append(rel);
            print(f"[rm] {rel}");
        }
        visit [-->];
    }
}

with entry {
    session = SessionArtifacts(session_id="spur-59f6");
    root ++> session;

    session +>:Contains:+> ArtifactFile(
