"""Edge-deletion diameter profile: source diameter plus one row per source edge."""

node Vertex {
    has name: str = "";
    has dist: int = -1;
}

edge Link {
    has edge_id: int = 0;
}

node EdgeSlot {
    has edge_id: int = 0;
    has slot_left: Vertex;
    has slot_right: Vertex;
}

node ProfileRow {
    has edge_id: int = 0;
    has left_name: str = "";
    has right_name: str = "";
    has status: str = "";
    has post_diameter: int = -1;
}

walker DistReset {
    can start with Root entry {
        visit [-->];
    }

    can clear with Vertex entry {
        here.dist = -1;
        visit [-->];
    }
}

walker SeedOrigin {
    has origin: str = "";

    can start with Root entry {
        visit [-->];
    }

    can mark with Vertex entry {
        if here.name == self.origin {
            here.dist = 0;
        }
        visit [-->];
    }
}

walker ExpandLayer {
    has layer: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can step with Vertex entry {
        if here.dist < 0 {
            here.dist = self.layer + 1;
            disengage;
        } elif here.dist == self.layer {
            visit [->:Link:->] else { visit [-->]; };
        } else {
            visit [-->];
        }
    }
}

walker MaxDistScan {
    has max_val: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can scan with Vertex entry {
        next_m = here.dist if here.dist > self.max_val else self.max_val;
        self.max_val = next_m;
        visit [-->];
    }
}

walker EccentricityCalc {
    has origin: str = "";
    has limit: int = 0;
    has eccentricity: int = 0;

    can start with Root entry {
        DistReset() spawn root;
        SeedOrigin(origin=self.origin) spawn root;
        layer = 0;
        while layer < self.limit {
            ExpandLayer(layer=layer) spawn root;
            layer += 1;
        }
        scan = MaxDistScan();
        root spawn scan;
        self.eccentricity = scan.max_val;
        disengage;
    }
}

walker DiameterCalc {
    has names: list[str] = [];
    has limit: int = 0;
    has diameter: int = 0;

    can start with Root entry {
        for nm in self.names {
            ec = EccentricityCalc(origin=nm, limit=self.limit);
            root spawn ec;
            next_d = ec.eccentricity if ec.eccentricity > self.diameter else self.diameter;
            self.diameter = next_d;
        }
        disengage;
    }
}

walker ReachCount {
    has seen: list[str] = [];
    has count: int = 0;

    can walk with Vertex entry {
        if here.name in self.seen {
            disengage;
        }
        self.seen.append(here.name);
        self.count += 1;
        visit [->:Link:->] else { disengage; };
    }
}

walker DeletionProfiler {
    has names: list[str] = [];
    has n: int = 0;
    has rows: list[ProfileRow] = [];

    can start with Root entry {
        visit [-->];
        base = DiameterCalc(names=self.names, limit=self.n);
        root spawn base;
        print(f"source diameter: {base.diameter}");
        visit [-->[?:EdgeSlot]] else { disengage; };
    }

    can collect with Vertex entry {
        self.names.append(here.name);
        self.n += 1;
        visit [-->];
    }

    can audit with EdgeSlot entry {
        u = here.slot_left;
        v = here.slot_right;
        eid = here.edge_id;
        u del ->:Link:-> v;
        v del ->:Link:-> u;
        probe = ReachCount();
        u spawn probe;
        if probe.count == self.n {
            dm = DiameterCalc(names=self.names, limit=self.n);
            root spawn dm;
            row = ProfileRow(
                edge_id=eid,
                left_name=u.name,
                right_name=v.name,
                status="OK",
                post_diameter=dm.diameter
            );
        } else {
            row = ProfileRow(
                edge_id=eid,
                left_name=u.name,
                right_name=v.name,
                status="DISCONNECTED",
                post_diameter=-1
            );
        }
        u +>:Link(edge_id=eid):+> v;
        v +>:Link(edge_id=eid):+> u;
        self.rows.append(row);
        outcome = f"{row.post_diameter}" if row.status == "OK" else row.status;
        print(
            f"edge {row.edge_id} ({row.left_name}-{row.right_name}): "
            f"{row.status} post_diameter={outcome}"
        );
        visit [-->];
    }
}

with entry {
    a = Vertex(name="A");
    b = Vertex(name="B");
    c = Vertex(name="C");
    d = Vertex(name="D");
    root ++> a ++> b ++> c ++> d;
    a +>:Link(edge_id=0):+> b;
    b +>:Link(edge_id=0):+> a;
    b +>:Link(edge_id=1):+> c;
    c +>:Link(edge_id=1):+> b;
    c +>:Link(edge_id=2):+> d;
    d +>:Link(edge_id=2):+> c;
    d +>:Link(edge_id=3):+> a;
    a +>:Link(edge_id=3):+> d;
    s0 = EdgeSlot(edge_id=0, slot_left=a, slot_right=b);
    s1 = EdgeSlot(edge_id=1, slot_left=b, slot_right=c);
    s2 = EdgeSlot(edge_id=2, slot_left=c, slot_right=d);
    s3 = EdgeSlot(edge_id=3, slot_left=d, slot_right=a);
    root ++> s0 ++> s1 ++> s2 ++> s3;
    root spawn DeletionProfiler();
}

