walker Orchestrator {
    has visiting: list = [];
    has finished: list = [];
    has run_order: list = [];

    can start with Root entry {
        visit [-->] else { disengage; }
    }

    can open_pack with SkillPack entry {
        print(f"=== {here.skill_name} ({here.status}) ===");
        visit [->:Bundles:->] else { disengage; }
    }

    can queue with RunbookStep entry {
        if here.title in self.finished {
            disengage;
        }
        if here.title in self.visiting {
            print(f"[CYCLE] blocked re-entry at {here.title}");
            disengage;
        }
        self.visiting.append(here.title);
        visit [->:DependsOn:->] else {
            state = "READY" if here.ready else "PENDING";
            self.run_order.append(here.title);
            self.finished.append(here.title);
            print(f"  [{state}] {here.op_kind}: {here.title}");
        };
        self.visiting.pop();
    }
}

walker MigrationReviewer {
    has bash_risks: int = 0;
    has top_pick: str = "";

    can start with Root entry {
        visit [-->] else { disengage; }
    }

    can scan_pack with SkillPack entry {
        print(f"reviewing skill {here.skill_name}");
