    can touch with Variable entry {
        if here.name in self.visited {
            disengage;
        }
        self.visited.append(here.name);
        self.steps += 1;
        visit [->:Causes:->] else { disengage; };
    }
}

walker ReachabilityProbe {
    has goal_name: str = "";
    has found: bool = False;
    has visited: list[str] = [];

    can probe with Variable entry {
        if here.name == self.goal_name {
            self.found = True;
            disengage;
        }
        if here.name in self.visited {
            disengage;
        }
        self.visited.append(here.name);
        visit [->:Causes:->] else { disengage; };
    }
}

