"""Everflow 408 visualizer: ordered validation gates block deploy; syllabus walk prunes non-408 modules while honoring shared dependencies."""

node ValidationGate {
    has name: str = "";
    has passed: bool = False;
}

node VisualizerModule {
    has slug: str = "";
    has subject: str = "";
    has is_408_core: bool = True;
}

node DeployTarget {
    has path: str = "";
    has armed: bool = False;
}

edge NextGate {
}

edge CatalogEntry {
}

edge RequiresShared {
}

walker GateRunner {
    has all_cleared: bool = True;
    has failed_at: str = "";

    can start with Root entry {
        visit [->:NextGate:->] else { disengage; };
    }

    can run_gate with ValidationGate entry {
        if not here.passed {
            self.all_cleared = False;
            self.failed_at = here.name;
            disengage;
        }
        print(f"[gate] {here.name} cleared");
        visit [->:NextGate:->] else { disengage; };
    }
}

walker SyllabusPruner {
    has pruned_count: int = 0;
    has kept_count: int = 0;

    can start with Root entry {
        visit [->:CatalogEntry:->] else { disengage; };
    }

    can review with VisualizerModule entry {
        if here.is_408_core {
            self.kept_count += 1;
            print(f"[keep] {here.slug} ({here.subject})");
        } else {
            self.pruned_count += 1;
            print(f"[prune] {here.slug} ({here.subject})");
        }
        visit [->:RequiresShared:->] else { disengage; };
    }
}

