"""Workflow execution graph: dependency ordering and downstream reachability.

Models genfeed.ai #1346 — workflow steps as graph nodes, DependsOn edges for
execution prerequisites, a canonical topological planner (replacing a local
topologicalSort duplicate), and a downstream collector over dependent steps.
"""

node WorkflowStep {
    has name: str = "";
    has family: str = "workflows";
    has on_stack: bool = False;
    has planned: bool = False;
}

edge DependsOn { }

walker TopologicalPlanner {
    has order: list[str] = [];
    has cycle_at: str = "";

    can start with Root entry {
        visit [-->[?:WorkflowStep]];
    }

    can schedule with WorkflowStep entry {
        if here.planned {
            disengage;
        }
        if here.on_stack {
            self.cycle_at = here.name;
            disengage;
        }
        here.on_stack = True;
        visit [->:DependsOn:->];
        here.on_stack = False;
        here.planned = True;
        self.order.append(here.name);
    }
}

walker DownstreamCollector {
    has collected: list[str] = [];
    has seen: list[str] = [];

    can start with WorkflowStep entry {
        visit [<--:DependsOn:--];
    }

    can gather with WorkflowStep entry entry {
        if here.name in self.seen {
            disengage;
        }
        self.seen.append(here.name);
        self.collected.append(here.name);
        visit [<--:DependsOn:--];
    }
}

