    transform spawn collector;
    print(f"downstream of transform: {collector.collected}");

    cycle_msg = f"cycle detected at {planner.cycle_at}" if planner.cycle_at != "" else "acyclic graph";
    print(cycle_msg);
}

"""Chronicle 2-layer model: session lineage trees, turn-centric transcripts, and cascade invalidation."""

edge ChildOf { has note: str = ""; }
edge OwnsTurn { has ingest_rank: int = 0; }
edge StepOf { has pair_rank: int = 0; }

node Session {
    has session_id: str = "";
    has role: str = "";
    has depth: int = 0;
    has root_id: str = "";
    has active: bool = True;
}

node Turn {
    has turn_index: int = 0;
    has speaker: str = "";
    has token_count: int = 0;
    has relevance: float = 0.0;
}

node TranscriptStep {
    has ordinal: int = 0;
    has phase: str = "";
    has tool_name: str = "";
    has exit_code: int = 0;
    has error_headline: str = "";
    has duration_ms: int = 0;
    has output_preview: str = "";
}

walker LineageWalker {
    has seen: list[str] = [];
    has depth_limit: int = 10;
    has cycle_detected: bool = False;

    can start with Session entry {
        print("=== Session lineage (Layer 1 topology) ===");
        sid = here.session_id;
        self.seen.append(sid);
        state = "live" if here.active else "void";
        print(f"{here.role} ({sid}) depth={here.depth} [{state}] root={here.root_id}");
        visit [->:ChildOf:->];
    }

    can descend with Session entry {
        sid = here.session_id;
        if sid in self.seen {
            print(f"  [CYCLE] revisiting {sid} — halting branch");
            self.cycle_detected = True;
            disengage;
        }
        if here.depth >= self.depth_limit {
            print(f"  [DEPTH CAP] {sid} at depth {here.depth}");
            disengage;
        }
        self.seen.append(sid);
        state = "live" if here.active else "void";
        pad = "  " * here.depth;
        print(f"{pad}{here.role} ({sid}) depth={here.depth} [{state}]");
        visit [->:ChildOf:->];
    }
}

walker TranscriptWalker {
    has pending_tool: str = "";

    can start with Session entry {
        print(f"=== Transcript for {here.session_id} (Layer 2 turns + paired steps) ===");
        visit [->:OwnsTurn:->] else { disengage; };
    }

    can read_turn with Turn entry {
        print(f"  turn {here.turn_index}: [{here.speaker}] tokens={here.token_count} relevance={here.relevance}");
        self.pending_tool = "";
        visit [->:StepOf:->];
    }

    can read_step with TranscriptStep entry {
        if here.phase == "invoke" {
            self.pending_tool = here.tool_name;
            print(f"    [{here.ordinal}] invoke {here.tool_name}");
        } else {
            tool = here.tool_name if here.tool_name else self.pending_tool;
            outcome = "OK" if here.exit_code == 0 else f"ERR({here.exit_code})";
            err = f" — {here.error_headline}" if here.error_headline else "";
            print(f"    [{here.ordinal}] result {tool}: {outcome}{err} ({here.duration_ms}ms) {here.output_preview}");
            self.pending_tool = "";
        }
    }
}

walker CascadeInvalidator {
    has seen: list[str] = [];

    can start with Session entry {
        print(f"=== Cascade invalidate from {here.session_id} ===");
        visit [->:ChildOf:->];
        here.active = False;
        print(f"  voided {here.session_id} ({here.role})");
    }

    can purge with Session entry {
        sid = here.session_id;
        if sid in self.seen {
            disengage;
        }
        self.seen.append(sid);
        visit [->:ChildOf:->];
        here.active = False;
        print(f"  voided {sid} ({here.role})");
    }
}

walker RelevanceScanner {
    has anchor: float = 0.80;
    has hit_count: int = 0;

    can start with Session entry {
        print(f"=== Ingestion-local relevance scan (anchor={self.anchor}) ===");
        visit [->:OwnsTurn:->] else { disengage; };
    }

    can score with Turn entry {
        if here.relevance >= self.anchor {
            self.hit_count += 1;
            print(f"  hit turn {here.turn_index}: relevance={here.relevance}");
        }
    }
}

