edge DependsOn { }

walker TopologicalPlanner {
    has order: list[str] = [];
    has cycle_at: str = "";

    can start with Root entry {
        visit [-->];
    }

    can schedule with WorkflowStep entry {
        if here.planned {
            disengage;
        }
        if here.on_stack {
            self.cycle_at = here.name;
            disengage;
        }
        here.on_stack = True;
        visit [->:DependsOn:->] else { disengage; };
        here.on_stack = False;
        here.planned = True;
        self.order.append(here.name);
        visit [-->];
    }
}

walker DownstreamCollector {
    has collected: list[str] = [];
    has seen: list[str] = [];

    can collect with WorkflowStep entry {
        if here.name in self.seen {
            disengage;
        }
        self.seen.append(here.name);
        self.collected.append(here.name);
        visit [<-:DependsOn:<-] else { disengage; };
    }
}

with entry {
