    cycle_detail = f" at {planner.cycle_at}" if planner.cycle_at != "" else "";
    print(f"{cycle_label}{cycle_detail}");
}

"""DNA Racing integration closure: audit phased rollout over exports, tournament rules, and evidence gates."""

node Phase {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has phase_num: int = 0;
    has label: str = "";
    has closed: bool = False;
}

node DataExport {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has export_kind: str = "";
    has record_count: int = 0;
    has fresh: bool = True;
}

node TournamentConfig {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has version: int = 1;
    has snapshot_bound: bool = False;
}

node Evidence {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has status: str = "incomplete";
}

edge DependsOn { has since_phase: int = 0; }
edge Requires { has min_records: int = 0; }
edge GatedBy { }
edge SnapshotOf { }

walker IntegrationAuditor {
    has shelf_label: str = "Phase-9-Closure";
    has seen: list[int] = [];
    has blockers: list[str] = [];
    has cleared: int = 0;

    def already_seen(phase_id: int) -> bool {
        for pid in self.seen {
            if pid == phase_id {
                return True;
            }
        }
        return False;
    }

    def note_blocker(msg: str) {
        self.blockers.append(msg);
    }

    can start with Root entry {
        print(f"Integration audit ({self.shelf_label})");
        visit [->:DependsOn:->] else { disengage; };
    }

    can audit with Phase entry {
        pid = here.phase_num;
        if self.already_seen(pid) {
            self.note_blocker(f"cycle detected at phase {pid} ({here.label})");
            disengage;
        }
        self.seen.append(pid);

        ready = True;
        for req in [-->:Requires:--] {
            if req.record_count < 1 {
                need = 1;
            } else {
                need = req.record_count;
            }
            if (not req.fresh) or (req.record_count < need) {
                ready = False;
                self.note_blocker(
                    f"phase {pid} blocked: export {req.export_kind} "
                    f"fresh={req.fresh} rows={req.record_count}"
                );
            }
        }

        for gate in [-->:GatedBy:--] {
            if gate.status != "complete" {
                ready = False;
                gate_msg = "review_only" if gate.status == "review_only" else "incomplete";
                self.note_blocker(
                    f"phase {pid} gated: evidence '{gate.title}' is {gate_msg}"
                );
            }
        }

        for cfg in [-->:SnapshotOf:--] {
            if (not cfg.snapshot_bound) or (not cfg.available) {
                ready = False;
                self.note_blocker(
                    f"phase {pid} blocked: tournament v{cfg.version} "
                    f"snapshot_bound={cfg.snapshot_bound}"
                );
            }
        }

        if ready {
            here.closed = True;
            self.cleared += 1;
            verdict = "CLOSABLE";
        } else {
            verdict = "BLOCKED";
        }
        print(f"[{verdict}] P{pid}: {here.label}");
        visit [->:DependsOn:->] else { disengage; };
    }
}

