"""Share frozen owned runtime images across evaluation contexts.

Models certified Consent-owned library images reused read-only by multiple
evaluation contexts instead of per-context graph reboxing; mutation attempts
against frozen objects fail deterministically while shared literal topology
(cycles and sharing) is preserved.
"""

edge PublishedAs {
}

edge Reuses {
}

edge Shares {
}

node FrozenObject {
    has object_id: str = "";
    has frozen: bool = False;
}

node LibraryForm(FrozenObject) {
    has path: str = "";
    has source_hash: str = "";
}

node LiteralDatum(FrozenObject) {
    has value_repr: str = "";
}

node FrozenImage {
    has image_id: str = "";
    has cache_key: str = "";
    has certified: bool = False;
    has frozen: bool = False;
    has form_count: int = 0;
}

node EvalContext {
    has ctx_id: str = "";
    has loader_config: str = "";
    has runtime_version: str = "";
}

walker ContextReuseReporter {
    has first_image: str = "";
    has contexts_seen: int = 0;
    has reuse_hits: int = 0;
    has forms_in_image: int = 2;

    can start with Root entry {
        print("=== loading source libraries into evaluation contexts ===");
        visit [-->];
        copies_avoided = self.reuse_hits * self.forms_in_image;
        print(
            f"summary: {self.contexts_seen} contexts, "
            f"{self.reuse_hits} shared-image reuse hits, "
            f"~{copies_avoided} per-context graph copies avoided"
        );
    }

    can audit with EvalContext entry {
        self.contexts_seen += 1;
        ctx_name = here.ctx_id;
        print(f"context {ctx_name} ({here.loader_config}, rv={here.runtime_version})");
        visit [->:Reuses:->] else {
            print(f"  {ctx_name}: cache miss — would copy parsed forms");
        };
        visit [-->];
    }

    can bind with FrozenImage entry {
        if not here.certified {
            print(f"  reject: image {here.image_id} is not certified");
        } else {
            if not here.frozen {
                print(f"  reject: image {here.image_id} is not frozen");
            } else {
                if self.first_image == "" {
                    self.first_image = here.image_id;
                    print(
                        f"  publish certified frozen image {here.image_id} "
                        f"(key={here.cache_key}, forms={here.form_count})"
                    );
                } else {
                    if self.first_image == here.image_id {
                        self.reuse_hits += 1;
                        print(
                            f"  reuse read-only image {here.image_id} "
                            f"(no per-context rebox)"
                        );
                    } else {
                        print(
                            f"  cache invalidation: distinct image {here.image_id} "
                            f"replaces {self.first_image}"
                        );
                        self.first_image = here.image_id;
                    }
                }
            }
        }
    }
}

walker MutationProbe {
    has rejections: int = 0;

    can start with FrozenImage entry {
        print("=== probing frozen-image mutation rejection ===");
        if here.certified and here.frozen {
            print(f"certified heap {here.image_id} is immutable");
            visit [->:PublishedAs:->];
        } else {
            print(f"heap {here.image_id} is not publishable");
        }
        print(f"mutation probe finished with {self.rejections} rejections");
    }

    can guard with LibraryForm | LiteralDatum entry {
        verdict = "REJECTED" if here.frozen else "allowed";
        if here.frozen {
            self.rejections += 1;
        }
        print(f"  mutate {here.object_id}: {verdict}");
        visit [->:Shares:->] else {
            disengage;
        };
    }
}

walker ShareInspector {
    has steps: int = 0;
    has step_cap: int = 6;

    can start with LibraryForm entry {
        print(f"=== literal sharing topology from {here.path} ===");
        visit [->:Shares:->] else {
            disengage;
        };
    }

    can hop with LiteralDatum entry {
        self.steps += 1;
        print(f"  step {self.steps}: {here.object_id} = {here.value_repr}");
        if self.steps >= self.step_cap {
            print("  cycle guard: step cap reached (shared/cyclic topology preserved)");
            disengage;
        }
        visit [->:Shares:->] else {
            disengage;
        };
    }
}

with entry {
    runtime_img = FrozenImage(
