"""Flux kustomization tree: inventory recursion with cycle detection.

Models flux tree kustomization (issue #5998): Kustomizations reference each
other via status.inventory edges; cyclic inventories cause unbounded recursion
without a visited set.
"""

node GitRepository {
    has url: str = "";
}

node Kustomization {
    has name: str = "";
    has path: str = "";
    has ready: bool = True;
}

edge SourcedFrom {
    has source_kind: str = "git";
}

edge InventoryRef {
    has via_status: bool = True;
}

walker KustomizationTree {
    has visited: list[str] = [];
    has depth: int = 0;

    can start with Root entry {
        print("flux tree kustomization (cycle-safe)");
        visit [-->];
    }

    can recurse with Kustomization entry {
        if here.name in self.visited {
            indent = "  " * self.depth;
            print(f"{indent}[CYCLE] back-reference to {here.name} - stopping descent");
            disengage;
        }
        self.visited = self.visited + [here.name];
        indent = "  " * self.depth;
        ready_tag = "Ready" if here.ready else "NotReady";
        print(f"{indent}{here.name}  path={here.path}  [{ready_tag}]");
        self.depth += 1;
        visit [->:InventoryRef:->] else { disengage; }
        self.depth -= 1;
    }
}

with entry {
    repo = GitRepository(url="https://github.com/example/flux-config.git");
    ks_a = Kustomization(name="treebomb-a", path="./treebomb/a", ready=True);
    ks_b = Kustomization(name="treebomb-b", path="./treebomb/b", ready=True);
    ks_a +>:SourcedFrom(source_kind="git"):+> repo;
    ks_b +>:SourcedFrom(source_kind="git"):+> repo;
    root ++> ks_a;
    ks_a +>:InventoryRef(via_status=True):+> ks_b;
    ks_b +>:InventoryRef(via_status=True):+> ks_a;
    tree = KustomizationTree();
    root spawn tree;
    print(f"flux tree: {len(tree.visited)} unique kustomization(s) rendered");
}

"""Workspace liveness graph rail: immutable admission, SCC condensation, independent closures, exact queries."""

node ExecutionUnit {
    has name: str = "";
    has unit_kind: str = "";
    has component_id: int = -1;
    has in_production_closure: bool = False;
    has in_test_closure: bool = False;
    has is_exposed: bool = False;
    has is_blocked: bool = False;
}

edge RuntimeDepends { has priority: int = 0; }
edge ScopedBlocker { has reason: str = ""; }
edge InterfaceExposure { has surface: str = ""; }

walker GraphAdmitter {
    has node_count: int = 0;

    can start with Root entry {
        print("G1: admitting immutable workspace liveness snapshot");
        visit [-->[?:ExecutionUnit]];
    }

    can tally with ExecutionUnit entry {
        self.node_count += 1;
        visit [-->[?:ExecutionUnit]];
    }
}

walker ComponentFlood {
    has component_id: int = 0;
    has visited: list[str] = [];

    can flood with ExecutionUnit entry {
        unit_name = here.name;
        if unit_name in self.visited {
            disengage;
        }
        self.visited.append(unit_name);
        here.component_id = self.component_id;
        visit [->:RuntimeDepends:->] else { };
        visit [<--:RuntimeDepends:--] else { };
    }
}

walker SccCondenser {
    has next_id: int = 0;
    has assigned: list[str] = [];

    can start with Root entry {
        print("G2: condensing strongly connected components");
        visit [-->[?:ExecutionUnit]];
    }

    can schedule with ExecutionUnit entry {
        unit_name = here.name;
        if unit_name in self.assigned {
            visit [-->[?:ExecutionUnit]];
        } else {
            flood = ComponentFlood(component_id=self.next_id);
            here spawn flood;
            for (i, member) in enumerate(flood.visited) {
                if member not in self.assigned {
                    self.assigned.append(member);
                }
            }
            self.next_id += 1;
            visit [-->[?:ExecutionUnit]];
        }
    }
}

walker ClosureWalker {
    has root_kind: str = "";
    has visited: list[str] = [];

    can propagate with ExecutionUnit entry {
        unit_name = here.name;
        if unit_name in self.visited {
            disengage;
        }
        if here.is_blocked {
            disengage;
        }
        self.visited.append(unit_name);
        if self.root_kind == "production" {
            here.in_production_closure = True;
        } else {
            here.in_test_closure = True;
        }
        visit [->:RuntimeDepends:->] else { disengage; };
    }
}

walker ClosureOrchestrator {
    has label: str = "";

    can start with Root entry {
        print(f"G3: computing {self.label} closure from roots");
        visit [-->[?:ExecutionUnit]];
    }

    can launch with ExecutionUnit entry {
        expected = f"{self.label}_root";
        if here.unit_kind == expected {
            walker = ClosureWalker(root_kind=self.label);
            here spawn walker;
        }
        visit [-->[?:ExecutionUnit]];
    }
}

walker QueryAuthority {
    can start with Root entry {
        print("G4: exact snapshot-bound entity queries");
        visit [-->[?:ExecutionUnit]];
    }

    can report with ExecutionUnit | ScopedBlocker entry {
        if here is ExecutionUnit {
            prod_flag = "Y" if here.in_production_closure else "N";
            test_flag = "Y" if here.in_test_closure else "N";
            exposed_flag = "exposed" if here.is_exposed else "hidden";
            blocked_flag = "blocked" if here.is_blocked else "live";
            print(
                f"  {here.name}: scc={here.component_id} "
                f"prod={prod_flag} test={test_flag} "
                f"{exposed_flag} {blocked_flag}"
            );
        }
        visit [-->[?:ExecutionUnit]];
    }
}

with entry {
    prod = ExecutionUnit(name="ProdRoot", unit_kind="production_root");
    test = ExecutionUnit(name="TestRoot", unit_kind="test_root");
    a = ExecutionUnit(name="A");
    b = ExecutionUnit(name="B");
    c = ExecutionUnit(name="C");
    d = ExecutionUnit(name="D");
    e = ExecutionUnit(name="E");
    f = ExecutionUnit(name="F", is_exposed=True, is_blocked=True);
    blocker = ExecutionUnit(name="ScopedBlocker");
    iface = ExecutionUnit(name="PublicAPI");

    root ++> prod;
    root ++> test;
    root ++> a;
    root ++> b;
    root ++> c;
    root ++> d;
    root ++> e;
    root ++> f;
    root ++> blocker;
    root ++> iface;

    prod +>:RuntimeDepends(priority=1):+> a;
    a +>:RuntimeDepends(priority=1):+> b;
    b +>:RuntimeDepends(priority=1):+> c;
    c +>:RuntimeDepends(priority=1):+> a;
    a +>:RuntimeDepends(priority=2):+> d;

    test +>:RuntimeDepends(priority=1):+> e;
    e +>:RuntimeDepends(priority=1):+> f;

    blocker +>:ScopedBlocker(reason="scoped_policy"):+> f;
