}

node DataExport {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has export_kind: str = "";
    has record_count: int = 0;
    has fresh: bool = True;
    has min_required: int = 1;
}

node TournamentConfig {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has version: int = 1;
    has snapshot_bound: bool = False;
}

node Evidence {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has status: str = "incomplete";
}

edge DependsOn { has since_phase: int = 0; }
edge Requires { has min_records: int = 0; }
edge GatedBy { }
edge SnapshotOf { }

walker IntegrationAuditor {
    has shelf_label: str = "Phase-9-Closure";
    has seen: list[int] = [];
    has blockers: list[str] = [];
    has cleared: int = 0;

    def note_blocker(msg: str) {
        self.blockers.append(msg);
    }

    can start with Root entry {
        print(f"Integration audit ({self.shelf_label})");
        visit [-->];
    }

    can audit with Phase entry {
        pid = here.phase_num;
        if pid in self.seen {
            self.note_blocker(f"cycle detected at phase {pid} ({here.label})");
            disengage;
        }
        self.seen.append(pid);

        ready = True;
        for req in [->:Requires:->] {
            if req.min_required < 1 {
                need = 1;
            } else {
                need = req.min_required;
            }
            if (not req.fresh) or (req.record_count < need) {
                ready = False;
                self.note_blocker(
                    f"phase {pid} blocked: export {req.export_kind} "
                    f"fresh={req.fresh} rows={req.record_count}"
                );
            }
        }

        for gate in [->:GatedBy:->] {
            if gate.status != "complete" {
                ready = False;
                gate_msg = "review_only" if gate.status == "review_only" else "incomplete";
                self.note_blocker(
                    f"phase {pid} gated: evidence '{gate.title}' is {gate_msg}"
                );
            }
        }

        for cfg in [->:SnapshotOf:->] {
            if (not cfg.snapshot_bound) or (not cfg.available) {
                ready = False;
                self.note_blocker(
                    f"phase {pid} blocked: tournament v{cfg.version} "
                    f"snapshot_bound={cfg.snapshot_bound}"
                );
            }
        }

        if ready {
            here.closed = True;
            self.cleared += 1;
            verdict = "CLOSABLE";
        } else {
            verdict = "BLOCKED";
        }
        print(f"[{verdict}] P{pid}: {here.label}");
        visit [->:DependsOn:->] else { disengage; };
    }
}

