node ExecutionUnit {
    has name: str = "";
    has unit_kind: str = "";
    has component_id: int = -1;
    has in_production_closure: bool = False;
    has in_test_closure: bool = False;
    has is_exposed: bool = False;
    has is_blocked: bool = False;
}

edge RuntimeDepends { has priority: int = 0; }
edge ScopedBlocker { has reason: str = ""; }
edge InterfaceExposure { has surface: str = ""; }

walker GraphAdmitter {
    has node_count: int = 0;

    can start with Root entry {
        print("G1: admitting immutable workspace liveness snapshot");
        visit [-->];
    }

    can tally with ExecutionUnit entry {
        self.node_count += 1;
        visit [-->];
    }
}

walker ComponentFlood {
    has component_id: int = 0;
    has visited: list[str] = [];

    can flood with ExecutionUnit entry {
        unit_name = here.name;
        if unit_name in self.visited {
            disengage;
        }
        self.visited.append(unit_name);
        here.component_id = self.component_id;
        visit [->:RuntimeDepends:->];
        visit [<--:RuntimeDepends:--];
    }
}

walker SccCondenser {
    has next_id: int = 0;
    has assigned: list[str] = [];

    can start with Root entry {
        print("G2: condensing strongly connected components");
        visit [-->];
    }

    can schedule with ExecutionUnit entry {
        unit_name = here.name;
        if unit_name in self.assigned {
            visit [-->];
        } else {
            flood = ComponentFlood(component_id=self.next_id);
            here spawn flood;
            for (i, member) in enumerate(flood.visited) {
                if member not in self.assigned {
                    self.assigned.append(member);
                }
            }
            self.next_id += 1;
            visit [-->];
        }
    }
}

walker ClosureWalker {
    has root_kind: str = "";
    has visited: list[str] = [];

    can propagate with ExecutionUnit entry {
        unit_name = here.name;
        if unit_name in self.visited {
            disengage;
        }
        if here.is_blocked {
            disengage;
        }
        self.visited.append(unit_name);
        if self.root_kind == "production" {
            here.in_production_closure = True;
        } else {
