}

node Principal {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

node Team {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

node Grant {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has mask: int = 0;
}

edge SubprojectOf { }
edge TaskInProject { }
edge HasGrant { }
edge GrantTo { }
edge MemberOf { }

walker FgacAuditor {
    has actor: Principal;
    has targets: list[str] = [];
    has effective: int = 0;
    has pending_mask: int = 0;
    has denied: list[str] = [];
    has bit_state: int = 1;
    has bit_title: int = 2;
    has bit_due: int = 4;
    has bit_comments: int = 8;
    has admin_mask: int = 18446744073709551615;

    def all_task_bits() -> int {
        return self.bit_state | self.bit_title | self.bit_due | self.bit_comments;
    }

    def coarse_to_mask(level: int) -> int {
        mask = 0;
        if level == 0 {
            mask = 0;
        } else if level == 1 {
            mask = self.bit_state | self.bit_comments;
        } else if level == 2 {
            mask = self.all_task_bits();
        } else {
            mask = self.admin_mask;
        }
        return mask;
    }

    def bit_for_name(name: str) -> int {
        bit = 0;
        if name == "state" {
            bit = self.bit_state;
        } else if name == "title" {
            bit = self.bit_title;
        } else if name == "due_date" {
            bit = self.bit_due;
        } else if name == "comments" {
            bit = self.bit_comments;
        } else {
            bit = 0;
        }
        return bit;
    }

    def field_allowed(bit: int) -> bool {
        allowed = False;
        if self.effective == self.admin_mask {
            allowed = True;
        } else if bit != 0 {
            allowed = (self.effective & bit) != 0;
        } else {
            allowed = False;
        }
        return allowed;
    }

    def validate_patch() {
        self.denied = [];
        for field in self.targets {
            bit = self.bit_for_name(field);
            if not self.field_allowed(bit) {
                self.denied.append(field);
            }
        }
    }

    def writable_fields() -> list[str] {
        names = ["state", "title", "due_date", "comments"];
        out = [];
        for name in names {
            if self.field_allowed(self.bit_for_name(name)) {
                out.append(name);
            }
        }
        return out;
    }

    can start with Root entry {
        visit [-->];
    }

    can audit with Task entry {
        self.effective = 0;
        visit [<--:TaskInProject:--];
        self.validate_patch();
        code = "OK" if len(self.denied) == 0 else "403";
        print(
            f"PATCH /tasks/{here.title}: effective=0x{self.effective:x} -> {code}"
        );
        if len(self.denied) > 0 {
            print(f"  unauthorized_fields: {self.denied}");
        } else {
            print(f"  writable_fields: {self.writable_fields()}");
        }
        visit [-->];
    }

    can resolve with Project entry {
        if here.use_fine_grained {
            visit [->:HasGrant:->] else {
                noop = 0;
            };
        } else {
            self.effective = self.effective | self.coarse_to_mask(here.coarse_level);
        }
        visit [->:SubprojectOf:->] else {
            disengage;
        };
    }

    can take_grant with Grant entry {
        self.pending_mask = here.mask;
        visit [->:GrantTo:->];
    }

    can credit_team with Team entry {
        visit [<--:MemberOf:--];
    }

    can credit_principal with Principal entry {
        if here.title == self.actor.title {
            self.effective = self.effective | self.pending_mask;
        }
        disengage;
    }
}

