"""FabricPC group-vmap demo: partition stackable compute nodes by static signature, traverse in dependency order, and batch phase updates with segment-sum aggregation over variable in-degree."""

node ComputeNode {
    has name: str = "";
    has node_class: str = "Linear";
    has shape_tag: str = "4";
    has degree_class: str = "internal";
    has sig_key: str = "";
    has latent: float = 0.0;
    has latent_grad: float = 0.0;
    has input_agg: float = 0.0;
    has clamped: bool = False;
    has updated: bool = False;
}

edge Feeds {
    has weight: float = 1.0;
}

walker PredSum {
    has total: float = 0.0;
    has skip_self: bool = True;

    can gather with ComputeNode entry {
        if self.skip_self {
            self.skip_self = False;
            visit [<--:Feeds:--] else {
                disengage;
            }
            return;
        }
        self.total += here.latent;
        disengage;
    }
}

walker SignatureTagger {
    can start with Root entry {
        visit [-->];
    }

    can tag with ComputeNode entry {
        clamp_tag = "clamped" if here.clamped else "free";
        here.sig_key = f"{here.node_class}:{here.shape_tag}:{here.degree_class}:{clamp_tag}";
        visit [->:Feeds:->] else {
            disengage;
        }
    }
}

walker InferenceEngine {
    has phase: str = "zero";
    has visit_guard: list[str] = [];
    has order_idx: int = 0;
    has sig_keys: list[str] = [];
    has sig_counts: list[int] = [];

    can start with Root entry {
        print("=== phase: zero latent gradients ===");
        self.phase = "zero";
        visit [-->];
        print("=== phase: forward (topo via Feeds) ===");
        self.phase = "forward";
        self.visit_guard = [];
        visit [-->];
        print("=== phase: latent update ===");
        self.phase = "latent";
        visit [-->];
        print("=== phase: group-vmap tally ===");
        self.phase = "group";
        visit [-->];
        print("=== vmap groups (static signature -> stack size) ===");
        for (i, key) in enumerate(self.sig_keys) {
            count = self.sig_counts[i];
            batch_note = "scalar" if count == 1 else f"vmap x{count}";
            print(f"  [{key}] -> {batch_note}");
        }
    }

    can zero_grads with ComputeNode entry {
        if self.phase != "zero" {
            visit [->:Feeds:->] else {
                disengage;
            }
            return;
        }
        here.latent_grad = 0.0;
        visit [->:Feeds:->] else {
            disengage;
        }
    }

    can forward_pass with ComputeNode entry {
        if self.phase != "forward" {
            visit [->:Feeds:->] else {
                disengage;
            }
            return;
        }
        if here.name in self.visit_guard {
            print(f"[cycle-guard] blocked revisit of {here.name}");
            disengage;
            return;
        }
        self.visit_guard.append(here.name);
        if here.degree_class == "source" {
            here.latent = 1.0;
            here.latent_grad = 0.0;
        } else {
            summator = PredSum();
            here spawn summator;
            here.input_agg = summator.total;
            scale = 0.5 if here.degree_class == "internal" else 0.9;
            here.latent = here.input_agg * scale;
            here.latent_grad = here.latent * 0.1;
        }
        self.order_idx += 1;
        print(
            f"[forward #{self.order_idx}] {here.name} "
            f"deg={here.degree_class} latent={here.latent:.4f} "
            f"in_sum={here.input_agg:.4f} sig={here.sig_key}"
        );
        visit [->:Feeds:->] else {
            disengage;
        }
    }

    can latent_update with ComputeNode entry {
        if self.phase != "latent" {
            visit [->:Feeds:->] else {
                disengage;
            }
            return;
        }
        if not here.clamped {
            step = -0.01 * here.latent_grad;
            here.latent += step;
            here.updated = True;
        }
        visit [->:Feeds:->] else {
            disengage;
        }
    }

    can group_vmap with ComputeNode entry {
        if self.phase != "group" {
            disengage;
            return;
        }
        found = False;
        for (i, key) in enumerate(self.sig_keys) {
            if key == here.sig_key {
                self.sig_counts[i] += 1;
                found = True;
                break;
            }
        }
        if not found {
            self.sig_keys.append(here.sig_key);
            self.sig_counts.append(1);
        }
        visit [->:Feeds:->] else {
            disengage;
        }
    }
}

with entry {
    src_a = ComputeNode(
        name="src_a",
        node_class="Linear",
        shape_tag="4",
        degree_class="source"
    );
    src_b = ComputeNode(
