    root spawn SignatureTagger();
    root spawn InferenceEngine();
}

"""DNA Racing integration closure: audit phased rollout over exports, tournament rules, and evidence gates."""

node Phase {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has phase_num: int = 0;
    has label: str = "";
    has closed: bool = False;
}

node DataExport {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has export_kind: str = "";
    has record_count: int = 0;
    has fresh: bool = True;
    has min_required: int = 1;
}

node TournamentConfig {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has version: int = 1;
    has snapshot_bound: bool = False;
}

node Evidence {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has status: str = "incomplete";
}

edge DependsOn { has since_phase: int = 0; }
edge Requires { has min_records: int = 0; }
edge GatedBy { }
edge SnapshotOf { }

walker IntegrationAuditor {
    has shelf_label: str = "Phase-9-Closure";
    has seen: list[int] = [];
    has blockers: list[str] = [];
    has cleared: int = 0;
    has phase_ready: bool = True;
    has active_pid: int = 0;

    def note_blocker(msg: str) {
        self.blockers.append(msg);
    }

    can start with Root entry {
        print(f"Integration audit ({self.shelf_label})");
        visit [-->];
    }

    can audit with Phase entry {
        pid = here.phase_num;
        if pid in self.seen {
            self.note_blocker(f"cycle detected at phase {pid} ({here.label})");
            disengage;
        }
        self.seen.append(pid);
        self.phase_ready = True;
        self.active_pid = pid;

        visit [->:Requires:->];
        visit [->:GatedBy:->];
        visit [->:SnapshotOf:->];

        if self.phase_ready {
            here.closed = True;
            self.cleared += 1;
            verdict = "CLOSABLE";
        } else {
            verdict = "BLOCKED";
        }
        print(f"[{verdict}] P{pid}: {here.label}");
        visit [->:DependsOn:->] else { disengage; };
    }

    can check_export with DataExport entry {
        threshold = here.min_required;
        if threshold < 1 {
            threshold = 1;
        }
        if (not here.fresh) or (here.record_count < threshold) {
            self.phase_ready = False;
            self.note_blocker(
                f"phase {self.active_pid} blocked: export {here.export_kind} "
                f"fresh={here.fresh} rows={here.record_count}"
            );
        }
    }

    can check_evidence with Evidence entry {
        if here.status != "complete" {
            self.phase_ready = False;
            gate_msg = "review_only" if here.status == "review_only" else "incomplete";
            self.note_blocker(
                f"phase {self.active_pid} gated: evidence '{here.title}' is {gate_msg}"
            );
        }
    }

    can check_config with TournamentConfig entry {
        if (not here.snapshot_bound) or (not here.available) {
            self.phase_ready = False;
            self.note_blocker(
                f"phase {self.active_pid} blocked: tournament v{here.version} "
                f"snapshot_bound={here.snapshot_bound}"
            );
        }
    }
}

