"""Jolt aspect-pack gate audit: fork-fixed issues require portable regressions or extraction debt."""

node CorrectnessPack {
    has pack_name: str = "";
    has baseline_fork_fixed: int = 0;
}

node FailureClass {
    has name: str = "";
    has rank: int = 0;
    has leverage: str = "";
}

node Issue {
    has issue_id: int = 0;
    has title: str = "";
    has status: str = "open";
}

node PortableRegression {
    has script: str = "";
    has bad_sha: str = "";
    has fixed_sha: str = "";
}

node ExtractionDebt {
    has reason: str = "";
    has issue_tag: str = "";
}

node PhaseStep {
    has phase: str = "";
    has label: str = "";
    has observation_valid: bool = True;
}

edge PackTracks { }
edge Classifies { }
edge CoveredBy { }
edge OwedDebt { }
edge NextPhase { }

walker GateAuditor {
    has current_issue: int = 0;
    has regressions_found: int = 0;
    has debt_found: int = 0;
    has gaps: int = 0;

    can start with Root entry {
        print("=== Gate non-vacuity audit (fork-fixed issues) ===");
        visit [-->];
    }

    can audit_pack with CorrectnessPack entry {
        print(f"Pack: {here.pack_name} (baseline fork-fixed={here.baseline_fork_fixed})");
        visit [->:PackTracks:->] else { disengage; };
    }

    can audit_class with FailureClass entry {
        priority = "PRIORITY" if here.rank == 0 else "ranked";
        print(f"  [{priority}] class #{here.rank}: {here.name} ({here.leverage})");
        visit [->:Classifies:->] else { disengage; };
    }

    can audit_issue with Issue entry {
        if here.status != "fork-fixed" {
            disengage;
        }
        self.current_issue = here.issue_id;
        print(f"    Issue #{here.issue_id}: {here.title}");
        visit [->:CoveredBy:->] else {
            visit [->:OwedDebt:->] else {
                print("      [VIOLATION] no portable regression or extraction debt row");
                self.gaps += 1;
            };
        };
    }

    can confirm_regression with PortableRegression entry {
        print(f"      [OK] script={here.script} shas={here.bad_sha}..{here.fixed_sha}");
        self.regressions_found += 1;
        disengage;
    }

    can confirm_debt with ExtractionDebt entry {
        print(f"      [DEBT] {here.issue_tag}: {here.reason}");
        self.debt_found += 1;
        disengage;
    }
}

walker PhaseAuditor {
    has observation: str = "";
    has reserve_seen: bool = False;
    has lost_update: bool = False;

    can start with Root entry {
        print("=== Phase join audit (reserve / register / commit) ===");
        visit [-->];
    }

    can walk_phase with PhaseStep entry {
        if here.phase == "reserve" {
            self.observation = here.label;
            self.reserve_seen = True;
            print(f"  [reserve] observed pending={here.label}");
        } else {
            if here.phase == "commit" {
                if not self.reserve_seen {
                    self.lost_update = True;
                    print("  [commit] LOST UPDATE: commit without prior reserve");
                } else {
                    if not here.observation_valid {
                        self.lost_update = True;
                        print(f"  [commit] LOST UPDATE: stale observation '{self.observation}'");
                    } else {
                        print(f"  [commit] published pending={self.observation}");
                    }
                }
            } else {
                print(f"  [{here.phase}] staged {here.label}");
            }
        }
        visit [->:NextPhase:->] else { disengage; };
    }
}

