"""Recursive planner sub-graph: dead cycle-detection vs validated PlanGraph return."""

node Task {
    has task_id: str = "";
    has label: str = "";
}

edge DependsOn { }

walker GraphValidator {
    has reason: str = "";
    has on_stack: list[str] = [];
    has finished: list[str] = [];
    has order: list[str] = [];
    has cyclic: bool = False;

    can start with Root entry {
        visit [-->[?:Task]] else { disengage; };
    }

    can validate with Task entry {
        if self.cyclic {
            disengage;
        }
        tid = here.task_id;
        if tid in self.finished {
            disengage;
        }
        if tid in self.on_stack {
            self.cyclic = True;
            print(f"CyclicDependencyError: cycle at {tid} ({self.reason})");
            disengage;
        }
        self.on_stack.append(tid);
        visit [->:DependsOn:->] else {
            self.on_stack.pop();
            self.order.append(tid);
            self.finished.append(tid);
        };
    }
}

walker SubGraphBuilder {
    has use_raw_escape: bool = False;
    has reason: str = "recursive expansion";

    can start with Root entry {
        checker = GraphValidator(reason=self.reason);
        root spawn checker;
        if self.use_raw_escape {
            print("[buildSubGraph] PlanGraph.fromTasks() called — result discarded");
            print("[buildSubGraph] createWithRawEdges returned (unvalidated, unsorted)");
        } else {
            if checker.cyclic {
                print("[buildSubGraph] fixed path: reject cyclic sub-graph at build time");
                disengage;
            } else {
                print(f"[buildSubGraph] returning validated order: {checker.order}");
            }
        }
        visit [-->] else { disengage; };
    }
}

walker TopoExecutor {
    has reason: str = "_exec topoSort";

    can start with Root entry {
        visit [-->[?:Task]] else {
            checker = GraphValidator(reason=self.reason);
            root spawn checker;
            if checker.cyclic {
                print("[_exec] CyclicDependencyError at topoSort (late detection)");
            } else {
                print(f"[_exec] executing in order: {checker.order}");
            }
            disengage;
        };
    }

    can stage with Task entry {
        visit [-->];
    }
}

