"""Metadata type-shell query: one bounded walker over typed inheritance and MethodImpl edges."""

enum Compatibility {
    Compatible,
    Incompatible,
    Unknown
}

enum MethodDisposition {
    Ordinary,
    Virtual,
    AuthenticatedOverride,
    ExplicitImplementation,
    Declined
}

node TypeDefinition {
    has handle: int = 0;
    has name: str = "";
    has compatibility: Compatibility = Compatibility.Unknown;
}

node MethodDefinition {
    has handle: int = 0;
    has name: str = "";
    has disposition: MethodDisposition = MethodDisposition.Ordinary;
    has row_owner_handle: int = 0;
}

node MethodImplRow {
    has row_id: int = 0;
    has owner_handle: int = 0;
    has body_handle: int = 0;
    has declaration_handle: int = 0;
    has rejection: str = "";
    has authenticated: bool = False;
}

edge InheritsFrom {
    has substitution: str = "";
}

edge OwnsMethod {
    has ordinal: int = 0;
}

edge MethodImplBody {
    has row_id: int = 0;
}

edge DeclaresOverride {
    has slot: int = 0;
}

walker MetadataQuery {
    has budget: int = 8;
    has spent: int = 0;
    has target_handle: int = 0;
    has visited_handles: list[int] = [];
    has method_impl_rows: list[int] = [];
    has override_paths: list[str] = [];
    has failed_closed: bool = False;
    has failure_reason: str = "";

    can start with Root entry {
        visit [-->];
    }

    can query_type with TypeDefinition entry {
        if self.spent >= self.budget {
            self.failed_closed = True;
            self.failure_reason = "budget exhausted";
            disengage;
        }
        self.spent += 1;
        if here.handle in self.visited_handles {
            self.failed_closed = True;
            self.failure_reason = f"cycle at type handle {here.handle}";
            disengage;
        }
        self.visited_handles.append(here.handle);
        if here.handle == self.target_handle {
            print(f"[QUERY] indexing {here.name} (handle={here.handle}, "
                  f"compat={here.compatibility})");
            visit [->:OwnsMethod:->];
            visit [->:MethodImplBody:->];
            visit [->:InheritsFrom:->];
        } else {
            visit [->:InheritsFrom:->];
        }
    }

    can collect_method with MethodDefinition entry {
        if here.disposition == MethodDisposition.AuthenticatedOverride {
            path = f"{here.row_owner_handle}->{here.handle}:{here.name}";
            self.override_paths.append(path);
            print(f"  method {here.name} ({here.handle}) "
                  f"disposition={here.disposition}");
        } else {
            print(f"  method {here.name} ({here.handle}) "
                  f"disposition={here.disposition}");
        }
        visit [-->] else { disengage; }
    }

    can authenticate_impl with MethodImplRow entry {
        owner = here.owner_handle;
        body = here.body_handle;
        if owner != self.target_handle {
            here.authenticated = False;
            here.rejection = "row owner is not querying type";
            print(f"  REJECT MethodImpl row {here.row_id}: {here.rejection}");
        } else {
            if here.rejection != "" {
                here.authenticated = False;
                print(f"  REJECT MethodImpl row {here.row_id}: {here.rejection}");
            } else {
                here.authenticated = True;
                self.method_impl_rows.append(here.row_id);
                print(f"  AUTH MethodImpl row {here.row_id} "
                      f"owner={owner} body={body} decl={here.declaration_handle}");
            }
        }
        visit [->:MethodImplBody:->] else { disengage; }
    }

    can report with Root exit {
        if self.failed_closed {
            print(f"[FAIL-CLOSED] {self.failure_reason}");
        } else {
            print(f"[FACTS] handles visited={self.visited_handles} "
                  f"method_impl_rows={self.method_impl_rows} "
                  f"override_paths={self.override_paths} "
                  f"budget_spent={self.spent}/{self.budget}");
        }
    }
}

