"""Recursive planner sub-graph: dead cycle-detection vs validated PlanGraph return."""

node Task {
    has task_id: str = "";
    has label: str = "";
}

edge DependsOn { }

walker SubGraphBuilder {
    has use_raw_escape: bool = False;
    has reason: str = "recursive expansion";
    has on_stack: list[str] = [];
    has finished: list[str] = [];
    has order: list[str] = [];
    has cyclic: bool = False;

    can start with Root entry {
        if self.use_raw_escape {
            print("[buildSubGraph] PlanGraph.fromTasks() called — result discarded");
            print("[buildSubGraph] createWithRawEdges returned (unvalidated, unsorted)");
            visit [-->];
            disengage;
        }
        visit [-->];
        if self.cyclic {
            print(f"[buildSubGraph] fixed path: reject cyclic sub-graph at build time ({self.reason})");
        } else {
            print(f"[buildSubGraph] returning validated order: {self.order}");
        }
    }

    can validate with Task entry {
        if self.use_raw_escape {
            disengage;
        }
        if self.cyclic {
            disengage;
        }
        tid = here.task_id;
        if tid in self.finished {
            disengage;
        }
        if tid in self.on_stack {
            self.cyclic = True;
            print(f"CyclicDependencyError: cycle at {tid} ({self.reason})");
            disengage;
        }
        self.on_stack.append(tid);
        visit [->:DependsOn:->] else {
            if self.cyclic {
                disengage;
            }
            self.on_stack.pop();
            self.order.append(tid);
            self.finished.append(tid);
        };
    }
}

walker TopoExecutor {
    has reason: str = "_exec topoSort";
    has on_stack: list[str] = [];
    has finished: list[str] = [];
    has order: list[str] = [];
    has cyclic: bool = False;

    can start with Root entry {
        visit [-->];
        if self.cyclic {
            print(f"[_exec] CyclicDependencyError at topoSort (late detection) ({self.reason})");
        } else {
            print(f"[_exec] executing in order: {self.order}");
        }
    }

    can topo_sort with Task entry {
        if self.cyclic {
            disengage;
        }
        tid = here.task_id;
        if tid in self.finished {
            disengage;
        }
        if tid in self.on_stack {
            self.cyclic = True;
            print(f"CyclicDependencyError: cycle at {tid} ({self.reason})");
            disengage;
        }
        self.on_stack.append(tid);
        visit [->:DependsOn:->] else {
            if self.cyclic {
                disengage;
            }
            self.on_stack.pop();
            self.order.append(tid);
            self.finished.append(tid);
        };
    }
