"""Semantic relationship schema: source-anchored typed propositions with inheritance, roles, re-exports, and boundary targets."""

edge AnchoredAt {
    has note: str = "";
}

edge ResolvesTo {
    has note: str = "";
}

edge ReexportHop {
    has note: str = "";
}

node Entity {
    has entity_id: str = "";
    has name: str = "";
    has root_id: str = "";
}

node Package {
    has package_id: str = "";
    has title: str = "";
    has available: bool = True;
}

node BoundaryTarget {
    has state: str = "ambiguous";
    has reason: str = "";
}

node SemanticRel {
    has rel_id: str = "";
    has kind: str = "";
    has ordinal: int = 0;
    has source_anchor: str = "";
    has source_rev: str = "";
    has phase: str = "";
    has confidence: float = 1.0;
    has limitation: str = "";
    has producer: str = "";
}

walker LineageResolver {
    can start with Entity entry {
        print(f"=== Inheritance resolution for {here.name} ({here.entity_id}) ===");
        visit [->:AnchoredAt:->] else { disengage; }
    }

    can read_fact with SemanticRel entry {
        if here.kind == "ComposesRole" {
            print(f"[ROLE] ord={here.ordinal} phase={here.phase} "
                  f"anchor={here.source_anchor} (distinct from inheritance)");
            disengage;
        } elif here.kind == "Inherits" {
            print(f"[INHERITS] ord={here.ordinal} rev={here.source_rev} "
                  f"anchor={here.source_anchor} conf={here.confidence}");
            if here.limitation != "" {
                print(f"  limitation: {here.limitation}");
            }
            visit [->:ResolvesTo:->] else { disengage; }
        } elif here.kind == "GeneratedBy" {
            print(f"[GENERATED] producer={here.producer} "
                  f"anchor={here.source_anchor}");
            visit [->:ResolvesTo:->] else { disengage; }
        } else {
            disengage;
        }
    }

    can resolve_target with Entity | BoundaryTarget entry {
        if here is Entity {
            print(f"  -> {here.name} ({here.entity_id})");
        } else {
            print(f"  -> BOUNDARY [{here.state}]: {here.reason}");
        }
        disengage;
    }
}

walker CycleDetector {
    has chain_ids: list[str] = [];

    can start with Entity entry {
        print(f"=== Cycle detection from {here.name} ({here.entity_id}) ===");
        self.chain_ids += [here.entity_id];
        visit [->:AnchoredAt:->] else { disengage; }
    }

    can read_inherits with SemanticRel entry {
        if here.kind != "Inherits" {
            disengage;
        }
        visit [->:ResolvesTo:->] else { disengage; }
    }

    can step with Entity entry {
        if here.entity_id in self.chain_ids {
            print(f"  CYCLE at {here.entity_id}");
            disengage;
        }
        self.chain_ids += [here.entity_id];
        print(f"  -> {here.name} ({here.entity_id})");
        visit [->:AnchoredAt:->] else { disengage; }
    }
}

walker ReexportTracer {
    can start with Package entry {
        print(f"=== Re-export chain from {here.package_id} ({here.title}) ===");
        visit [->:ReexportHop:->] else {
            print(f"  origin reached: {here.package_id}");
            disengage;
        }
    }

    can hop with Package entry {
        print(f"  re-exports -> {here.package_id} ({here.title})");
        visit [->:ReexportHop:->] else {
            print(f"  origin reached: {here.package_id}");
        }
    }
}

walker FactValidator {
    has invalid: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can scan_entity with Entity entry {
        visit [->:AnchoredAt:->];
        visit [-->];
    }

    can check with SemanticRel entry {
        ok = True;
        if here.source_anchor == "" {
            ok = False;
        }
        if here.source_rev == "" {
            ok = False;
        }
        if here.rel_id == "" {
            ok = False;
        }
        label = "OK" if ok else "INVALID";
        if not ok {
            self.invalid += 1;
        }
        print(f"[validate] {here.rel_id} ({here.kind}) {label}");
        visit [-->];
    }
}

