"""OLE2 CFB comprehension: cycle-safe FAT traversal and legacy .doc/.xls/.ppt text extraction."""

node CompoundFile {
    has label: str = "";
    has sector_budget: int = 64;
}

node DirectoryEntry {
    has name: str = "";
    has offset: int = 0;
    has length: int = 0;
    has stream_bound: int = 4096;
    has kind: str = "";
}

node Sector {
    has index: int = 0;
    has tag: str = "";
}

node TextPiece {
    has body: str = "";

    def enc_label() -> str {
        return "ansi";
    }
}

node TextCharsAtom(TextPiece) {
    override def enc_label() -> str {
        return "utf16";
    }
}

node TextBytesAtom(TextPiece) {
    override def enc_label() -> str {
        return "ansi";
    }
}

edge Contains { }
edge ChainStart { }
edge FatNext { }
edge Yields { }

walker Comprehension {
    has visited: list[int] = [];
    has walked: int = 0;
    has budget: int = 64;
    has status: str = "Ok";
    has reason: str = "";
    has pieces: list[str] = [];

    can comprehend with CompoundFile entry {
        self.visited = [];
        self.walked = 0;
        self.budget = here.sector_budget;
        self.status = "Ok";
        self.reason = "";
        self.pieces = [];
        print(f"\n=== Comprehending {here.label} ===");
        visit [->:Contains:->] else { disengage; };
    }

    can inspect_stream with DirectoryEntry entry {
        if here.kind == "macro" {
            print(f"SKIP macro storage: {here.name} (presence only, never read)");
            return;
        }
        if here.kind == "embedded" {
            self.status = "Failed";
            self.reason = "embedded OLE refused";
            print(f"REFUSE embedded OLE: {here.name}");
            disengage;
        }
        end_off = here.offset + here.length;
        if end_off > here.stream_bound {
            self.status = "Failed";
            self.reason = "out-of-stream bounds";
            print(f"FAIL invalid bounds on {here.name}");
            disengage;
        }
        print(f"Stream {here.name} ({here.kind}) @ {here.offset}+{here.length}");
        visit [->:ChainStart:->];
        visit [->:Yields:->];
    }

    can traverse_fat with Sector entry {
        if here.index in self.visited {
            self.status = "Failed";
            self.reason = "cyclic FAT chain";
            print(f"FAIL cyclic FAT at sector {here.index}");
            disengage;
        }
        self.visited.append(here.index);
        self.walked += 1;
        if self.walked > self.budget {
            self.status = "Failed";
            self.reason = "sector budget exceeded";
            disengage;
        }
        label = here.tag if here.tag else f"sector-{here.index}";
        print(f"  FAT[{here.index}] {label}");
        visit [->:FatNext:->] else {
            # end of chain — validated sector walk complete
        };
    }

    can harvest with TextCharsAtom | TextBytesAtom entry {
        enc = here.enc_label();
        self.pieces.append(here.body);
        print(f"    [{enc}] {here.body}");
    }

    can finish with CompoundFile exit {
        if self.status == "Failed" {
            print(f"=> {self.status}: {self.reason} (ShouldRetry: false)\n");
        } else {
            combined = "";
            for (piece) in self.pieces {
                gap = " " if combined else "";
                combined = f"{combined}{gap}{piece}";
            }
            print(f"=> {self.status}: \"{combined}\"\n");
        }
    }
}

