walker HierarchyReader {
    has accumulated_points: int = 0;
    has depth: int = 0;
    has max_depth: int = 16;
    has visited_keys: list[str] = [];

    can start with Root entry {
        visit [-->[?:CopcDataset]];
    }

    can open_dataset with CopcDataset entry {
        label = "BASELINE" if here.is_baseline else "DATASET";
        print(f"[{label}] {here.name} hierarchy ({here.point_count} pts)");
        visit [->:HierarchyChild:->] else { visit [-->]; };
    }

    can descend with HierarchyNode entry {
        if self.depth >= self.max_depth {
            print(f"  [DEPTH] cap at {here.node_key}");
            disengage;
        }
        for prior_key in self.visited_keys {
            if prior_key == here.node_key {
                print(f"  [CYCLE] blocked at {here.node_key}");
                disengage;
            }
        }
        self.visited_keys += [here.node_key];
        self.accumulated_points += here.point_count;
        next_depth = self.depth + 1;
        self.depth = next_depth;
        print(f"  node {here.node_key} offset={here.byte_offset} "
              f"len={here.byte_length} pts={here.point_count}");
        visit [->:HierarchyChild:->] else { disengage; };
    }
}

walker DifferentialValidator {
    has checks_run: int = 0;
    has mismatches: int = 0;

    can start with Root entry {
        visit [-->[?:CopcDataset]];
    }

    can inspect_dataset with CopcDataset entry {
        print(f"Diff-checking {here.name}");
        visit [->:ComparedOn:->] else { visit [-->]; };
    }

    can compare_backends with CopcJsBackend | RustBackend entry {
        self.checks_run += 1;
        verdict = "default" if here.is_default else "candidate";
        print(f"  {here.backend_id} role={here.role_label()} status={verdict}");
        visit [-->];
    }
}

walker MigrationAuditor {
    has highest_passed_phase: int = 0;

    can start with Root entry {
        visit [-->[?:ValidationGate]];
    }

    can review_gate with ValidationGate entry {
        status = "PASS" if here.passed else "BLOCKED";
        print(f"Phase {here.phase} {here.gate_name}: {status}");
        if here.passed {
            candidate_phase = here.phase;
            next_highest = candidate_phase if candidate_phase > self.highest_passed_phase else self.highest_passed_phase;
            self.highest_passed_phase = next_highest;
        }
        visit [-->];
    }
}

