"""Place/Route topology backend: hierarchy, reachability, shortest-hop paths, and integrity audit."""

node Place {
    has name: str = "";
    has active: bool = True;
}

edge ChildOf { }

edge Route {
    has cost: int = 1;
    has enabled: bool = True;
}

walker HierarchyWalker {
    has depth: int = 0;

    can start with Root entry {
        print("=== place hierarchy (ChildOf) ===");
        visit [->:ChildOf:->] else { disengage; }
    }

    can visit_place with Place entry {
        pad = "";
        d = 0;
        while d < self.depth {
            pad += "  ";
            d += 1;
        }
        flag = "active" if here.active else "disabled";
        print(f"{pad}- {here.name} ({flag})");
        self.depth += 1;
        visit [->:ChildOf:->] else { # leaf }
        self.depth -= 1;
    }
}

walker ReachabilityProbe {
    has target: str = "";
    has found: bool = False;
    has on_path: list[str] = [];

    can start with Place entry {
        if here.name == self.target {
            self.found = True;
            print(f"=== reachability -> {self.target}: REACHABLE ===");
            disengage;
        }
        self.on_path.append(here.name);
        visit [->:Route:->] else {
            tag = "REACHABLE" if self.found else "UNREACHABLE";
            print(f"=== reachability -> {self.target}: {tag} ===");
            disengage;
        }
    }

    can walk with Place entry {
        if here.name in self.on_path {
            disengage;
        }
        if here.name == self.target {
            self.found = True;
            disengage;
        }
        self.on_path.append(here.name);
        visit [->:Route:->] else {
            self.on_path.pop();
            disengage;
        }
    }
}

walker ShortestPath {
    has goal: str = "";
    has best_hops: int = 999999;
    has best_path: list[str] = [];
    has hops: int = 0;
    has trail: list[str] = [];
    has on_trail: list[str] = [];

    can start with Place entry {
        self.trail = [here.name];
        self.on_trail = [here.name];
        self.hops = 0;
        if here.name == self.goal {
            self.record_candidate();
            self.print_result();
            disengage;
        }
        visit [->:Route:->] else {
            self.print_result();
            disengage;
        }
    }

    can advance with Place entry {
        if here.name in self.on_trail {
            disengage;
        }
        self.trail.append(here.name);
        self.on_trail.append(here.name);
        self.hops += 1;
        if here.name == self.goal {
            self.record_candidate();
            self.trail.pop();
            self.on_trail.pop();
            self.hops -= 1;
            disengage;
        }
        visit [->:Route:->] else {
            self.trail.pop();
            self.on_trail.pop();
            self.hops -= 1;
            disengage;
        }
    }

    def record_candidate() {
        if self.hops < self.best_hops {
            self.best_hops = self.hops;
            self.best_path = list(self.trail);
        } elif self.hops == self.best_hops {
            cand = self.path_label(self.trail);
            best = self.path_label(self.best_path);
            if not self.best_path or cand < best {
                self.best_path = list(self.trail);
            }
        }
    }

    def path_label(path: list[str]) -> str {
        label = "";
        for n in path {
            if label {
                label += "|";
            }
            label += n;
        }
        return label;
    }

    def print_result() {
        if self.best_path {
            joined = self.path_label(self.best_path);
            joined = joined.replace("|", " -> ");
            print(f"=== shortest path -> {self.goal}: {joined} ({self.best_hops} hops) ===");
        } else {
            print(f"=== shortest path -> {self.goal}: none ===");
        }
    }
}

walker IntegrityGuard {
    has violations: list[str] = [];
    has seen: list[str] = [];

    can start with Root entry {
        print("=== topology integrity ===");
        visit [->:ChildOf:->] else { disengage; }
        if not self.violations {
            print("  OK: hierarchy and route endpoints valid");
        } else {
            for v in self.violations {
                print(f"  VIOLATION: {v}");
            }
        }
        disengage;
    }

    can audit with Place entry {
        if here.name in self.seen {
            self.violations.append(f"cycle in ChildOf at {here.name}");
            disengage;
        }
        self.seen.append(here.name);
        if not here.active {
            self.violations.append(f"inactive place referenced: {here.name}");
        }
        visit [->:ChildOf:->] else { # no children }
        visit [->:Route:->] else { # no routes }
    }
}

with entry {
    sector = Place(name="sector", active=True);
    dock = Place(name="dock", active=True);
    warehouse = Place(name="warehouse", active=True);
    gate = Place(name="gate", active=True);
    annex = Place(name="annex", active=False);

    root +>:ChildOf:+> sector;
    sector +>:ChildOf:+> dock;
    sector +>:ChildOf:+> warehouse;
    warehouse +>:ChildOf:+> gate;

    dock +>:Route(cost=4, enabled=True):+> warehouse;
    dock +>:Route(cost=10, enabled=False):+> gate;
    warehouse +>:Route(cost=2, enabled=True):+> gate;
    gate +>:Route(cost=1, enabled=True):+> annex;

    print("=== route catalog (integer costs) ===");
    print("  dock -> warehouse: cost=4, enabled=True");
    print("  dock -> gate: cost=10, enabled=False (removed from traversal)");
    print("  warehouse -> gate: cost=2, enabled=True");
    print("  gate -> annex: cost=1, enabled=True (inactive endpoint)");

    dock del ->:Route:-> gate;

    root spawn HierarchyWalker();
    dock spawn ReachabilityProbe(target="gate");
    dock spawn ShortestPath(goal="gate");
    dock spawn ReachabilityProbe(target="annex");
    root spawn IntegrityGuard();
}

"""Governed loop package export: preview transitive dependency closure with omissions."""

node Artifact {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has identity: str = "";
    has content_hash: str = "";
    has is_secret: bool = False;
    has unresolved: bool = False;
    has kind: str = "";
}

node LoopRevision(Artifact) {
    has kind: str = "loop_revision";
}

node Template(Artifact) {
    has kind: str = "template";
}

node ExternalRef(Artifact) {
    has kind: str = "external";
    has unresolved: bool = True;
}

edge Required {
    has dep_kind: str = "Required";
}

edge Optional {
    has dep_kind: str = "Optional";
}

walker ClosurePreviewer {
    has export_mode: str = "DefinitionOnly";
    has max_depth: int = 32;
    has visited_ids: list[str] = [];
    has depth: int = 0;
    has included: int = 0;
    has omissions: int = 0;
    has plan_complete: bool = True;

    can start with Root entry {
        print(f"=== Export preview mode={self.export_mode} max_depth={self.max_depth} ===");
        visit [-->];
        plan_status = "Complete" if self.plan_complete else "Incomplete";
        print(
            f"=== Closure {plan_status}: {self.included} included, "
            f"{self.omissions} omitted ==="
        );
    }

    can preview with LoopRevision | Template | ExternalRef entry {
        traverse_deps = True;

        if here.identity in self.visited_ids {
            print(f"[CYCLE] {here.identity} ({here.title})");
            traverse_deps = False;
        } else {
            self.visited_ids.append(here.identity);

            if self.depth > self.max_depth {
                print(f"[OMIT:over_limit] {here.title} depth={self.depth}");
                self.omissions += 1;
                self.plan_complete = False;
                traverse_deps = False;
            } elif here.is_secret {
                print(f"[OMIT:policy_forbidden] {here.title} ({here.identity})");
                self.omissions += 1;
                self.plan_complete = False;
                traverse_deps = False;
            } elif not here.available {
                print(f"[OMIT:optional_absent] {here.title} ({here.identity})");
                self.omissions += 1;
            } elif here.unresolved {
                print(f"[OMIT:externalized_rebind] {here.title} ({here.identity})");
                self.omissions += 1;
            } else {
                mode_allows = True;
                if self.export_mode == "DefinitionOnly" {
                    mode_allows = here.kind == "loop_revision";
                } elif self.export_mode == "ReusableTemplate" {
                    mode_allows = here.kind == "loop_revision" or here.kind == "template";
                } else {
                    mode_allows = True;
                }

                if not mode_allows {
                    print(f"[OMIT:mode_excluded] {here.title} kind={here.kind}");
                    self.omissions += 1;
                } else {
                    print(
                        f"[INCLUDE] {here.title} id={here.identity} "
                        f"hash={here.content_hash} schema={here.year}"
                    );
                    self.included += 1;
                }
            }
        }

        if traverse_deps {
            self.depth += 1;
            visit [->:Required:->];
            visit [->:Optional:->] else { disengage; };
            self.depth -= 1;
        } else {
            visit [-->] else { disengage; };
        }
    }
}

