"""RAD cross-system service: Severity x Probability RAC scoring, DEA dependency ordering with cycle guard, and APN routing for physical hazards."""

node Assessable {
    has label: str = "";
    has rac: int = 0;
}

node RiskAssessment(Assessable) {
    has subject: str = "";
    has severity: int = 1;
    has probability: int = 1;
    has is_physical: bool = False;

    def lock_in() {
        self.rac = self.severity * self.probability;
        self.label = self.subject;
    }

    def route() -> str {
        return "APN" if self.is_physical else "DEA";
    }
}

node WorkItem(Assessable) {
    has title: str = "";
    has deadline_days: int = 999;
    has waiting_days: int = 0;
    has readiness: int = 0;

    def refresh() {
        self.label = self.title;
    }
}

edge HasAssessment { }
edge DependsOn { }

walker RADCalculator {
    can start with Root entry {
        visit [-->[?:RiskAssessment]];
    }

    can brief with RiskAssessment entry {
        here.lock_in();
        band = "icy-blue";
        if here.rac > 0 {
            band = "CRITICAL" if here.rac <= 4 else "ELEVATED" if here.rac <= 9 else "ROUTINE";
        }
        print(
            f"RAD: {here.subject} S={here.severity} P={here.probability} "
            f"RAC={here.rac} [{band}] -> {here.route()}"
        );
        visit [-->] else { disengage; };
    }
}

walker DEAOrderer {
    has execution_plan: list[str] = [];
    has scheduled: list[str] = [];
    has active_path: list[str] = [];

    can start with Root entry {
        visit [-->[?:WorkItem]];
    }

    can rank with WorkItem entry {
        key = here.title;
        if key in self.scheduled {
            visit [-->] else { disengage; };
        }
        for prior in self.active_path {
            if prior == key {
                print(f"DEA: cycle detected at '{key}' — ordering halted");
                disengage;
            }
        }
        self.active_path.append(key);
        visit [->:DependsOn:->] else {
            self.active_path.pop();
            here.refresh();
            slot = (
                f"{here.label} RAC={here.rac} deadline={here.deadline_days}d "
                f"wait={here.waiting_days}d ready={here.readiness}"
            );
            self.scheduled.append(key);
            self.execution_plan.append(slot);
            visit [-->] else { disengage; };
        };
    }
}

walker DIMSAudit {
    can start with Root entry {
        print("DIMS audit — assessed items:");
        visit [-->];
    }

    can summarize with RiskAssessment | WorkItem entry {
        print(f"  [{here.rac}] {here.label}");
        visit [-->] else { disengage; };
    }
}

