}

"""Inline diff review pane: flow-ordered change units, anchored observations, read-only Q&A."""

node Commit {
    has sha: str = "";
    has message: str = "";
}

node ChangeUnit {
    has unit_key: str = "";
    has intent: str = "";
}

node DiffLine {
    has path: str = "";
    has side: str = "";
    has line_num: int = 0;
    has text: str = "";
}

node Observation {
    has body: str = "";
}

node Question {
    has text: str = "";
}

node Answer {
    has text: str = "";
}

edge InCommit { }
edge DependsOn { }
edge Touches { }
edge AnchoredTo { }
edge AboutLine { }
edge ReplyTo { }

walker FlowOrderer {
    has ordered: list[str] = [];
    has visiting: list[str] = [];
    has found_cycle: bool = False;

    can start with Commit entry {
        print(f"Commit {here.sha}: deriving flow-ordered story");
        visit [->:InCommit:->];
        if self.found_cycle {
            print("Flow ordering aborted: cyclic unit dependencies detected.");
        } else {
            story = ", ".join(self.ordered);
            print(f"Story order: {story}");
        }
    }

    can order with ChangeUnit entry {
        key = here.unit_key;
        for v in self.visiting {
            if v == key {
                self.found_cycle = True;
                print(f"[CYCLE] unit {key} reached again while resolving deps");
                disengage;
            }
        }
        for o in self.ordered {
            if o == key {
                disengage;
            }
        }
        self.visiting.append(key);
        visit [->:DependsOn:->];
        self.visiting.pop();
        self.ordered.append(key);
        slot = len(self.ordered);
        print(f"  [{slot}] {key} — {here.intent}");
        disengage;
    }
}

walker ReviewReader {
    can start with Commit entry {
        print(f"=== Diff review: {here.sha} ===");
        visit [->:InCommit:->];
    }

    can narrate with ChangeUnit entry {
        print(f"\n## {here.unit_key}: {here.intent}");
        visit [->:Touches:->];
        visit [-->] else { disengage; };
    }

    can annotate with DiffLine entry {
        loc = f"{here.path}:{here.side}:{here.line_num}";
        print(f"  {loc} | {here.text}");
        visit [<--:AnchoredTo:--];
        visit [<--:AboutLine:--];
        disengage;
    }

    can note with Observation entry {
        print(f"    [obs] {here.body}");
        disengage;
    }

    can ask with Question entry {
        print(f"    [Q] {here.text}");
        visit [<--:ReplyTo:--];
        disengage;
    }

    can answer with Answer entry {
        print(f"    [A] {here.text} (read-only)");
        disengage;
    }
}

with entry {
    commit = Commit(
        sha="abc1234",
        message="Inline diff review pane with anchored observations",
    );
    u_imports = ChangeUnit(
        unit_key="imports",
        intent="Add shiki tokenizer and parse-diff imports",
    );
    u_parser = ChangeUnit(
        unit_key="hunk-parser",
        intent="Parse hunks into anchorable diff lines",
    );
    u_pane = ChangeUnit(
