        visit [->:Hosts:->];
        visit [->:PreviousGen:->] else { };
    }

    can audit_target with Exposure entry {
        prior = self.conflict_src;
        if prior != "" {
            self.collisions += 1;
            print(f"COLLISION deny: {prior} vs {here.relative_path}");
            disengage;
        }
        self.conflict_src = here.relative_path;
        digest = here.sha256[:12] if len(here.sha256) >= 12 else here.sha256;
        print(f"  {here.kind} {here.relative_path} mode={here.mode} sha={digest}");
        visit [here->:PathConflict:->] else {
