}

"""Inline diff review pane: flow-ordered change units, anchored observations, read-only Q&A."""

node Commit {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has sha: str = "";
    has message: str = "";
}

node ChangeUnit {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has unit_key: str = "";
    has intent: str = "";
}

node DiffLine {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has path: str = "";
    has side: str = "";
    has line_num: int = 0;
    has text: str = "";
}

node Observation {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has body: str = "";
}

node Question {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has text: str = "";
}

node Answer {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has text: str = "";
}

edge InCommit { }
edge DependsOn { }
edge Touches { }
edge AnchoredTo { }
edge AboutLine { }
edge ReplyTo { }

walker FlowOrderer {
    has ordered: list[str] = [];
    has visiting: list[str] = [];
    has found_cycle: bool = False;

    can start with Commit entry {
        print(f"Commit {here.sha}: deriving flow-ordered story");
        visit [->:InCommit:->];
        if self.found_cycle {
            print("Flow ordering aborted: cyclic unit dependencies detected.");
        } else {
            story = ", ".join(self.ordered);
            print(f"Story order: {story}");
        }
    }

    can order with ChangeUnit entry {
        key = here.unit_key;
        for v in self.visiting {
            if v == key {
                self.found_cycle = True;
                print(f"[CYCLE] unit {key} reached again while resolving deps");
                disengage;
            }
        }
        for o in self.ordered {
            if o == key {
                disengage;
            }
        }
        self.visiting.append(key);
        visit [->:DependsOn:->];
        self.visiting.pop();
        self.ordered.append(key);
        slot = len(self.ordered);
        print(f"  [{slot}] {key} — {here.intent}");
        visit [-->] else { disengage; };
    }
}

walker ReviewReader {
    can start with Commit entry {
        print(f"=== Diff review: {here.sha} ===");
        visit [->:InCommit:->];
    }

    can narrate with ChangeUnit entry {
        print(f"\n## {here.unit_key}: {here.intent}");
        visit [->:Touches:->];
        visit [-->] else { disengage; };
    }

    can annotate with DiffLine entry {
        loc = f"{here.path}:{here.side}:{here.line_num}";
        print(f"  {loc} | {here.text}");
        visit [->:AnchoredTo:->];
        visit [->:AboutLine:->];
        visit [-->] else { disengage; };
    }

    can note with Observation entry {
        print(f"    [obs] {here.body}");
        visit [-->] else { disengage; };
    }

    can ask with Question entry {
        print(f"    [Q] {here.text}");
        visit [->:ReplyTo:->];
        visit [-->] else { disengage; };
    }

    can answer with Answer entry {
        print(f"    [A] {here.text} (read-only)");
        visit [-->] else { disengage; };
    }
}

with entry {
    commit = Commit(
        sha="abc1234",
        message="Inline diff review pane with anchored observations",
    );
    u_imports = ChangeUnit(
        unit_key="imports",
        intent="Add shiki tokenizer and parse-diff imports",
    );
    u_parser = ChangeUnit(
        unit_key="hunk-parser",
        intent="Parse hunks into anchorable diff lines",
    );
    u_pane = ChangeUnit(
        unit_key="review-pane",
        intent="Present flow-ordered units in the TUI review pane",
    );
    u_pane +>:DependsOn:+> u_parser;
    u_parser +>:DependsOn:+> u_imports;
    commit +>:InCommit:+> u_imports;
    commit +>:InCommit:+> u_parser;
    commit +>:InCommit:+> u_pane;
    line = DiffLine(
        path="src/review.ts",
        side="new",
        line_num=42,
        text="visit forward else disengage on empty frontier",
    );
    u_parser +>:Touches:+> line;
    obs = Observation(body="Prefer explicit empty-frontier handling over hang.");
    line +>:AnchoredTo:+> obs;
    q = Question(text="Does visit dedupe on dependency cycles?");
    line +>:AboutLine:+> q;
    a = Answer(text="No — walkers need an explicit cycle guard.");
    q +>:ReplyTo:+> a;

    print("--- Flow-ordered semantic units ---");
    commit spawn FlowOrderer();
    print("");
    print("--- Anchored observations and read-only Q&A ---");
    commit spawn ReviewReader();
}

"""Nix-home realization boundary: preflight collision checks and explicit generation rollback."""

node StateRoot {
    has schema: int = 1;
    has owner_uid: int = 0;
}

node Generation {
    has selector: str = "";
    has retained: bool = True;
    has has_gcroot: bool = False;
}

node Exposure {
    has relative_path: str = "";
    has kind: str = "";
    has sha256: str = "";
    has mode: int = 493;
    has store_safe: bool = True;
}

edge CurrentGen { }
edge PreviousGen { }
edge Hosts { }
edge PathConflict {
    has reason: str = "";
}

walker PreflightAuditor {
    has collisions: int = 0;
    has rollback_ready: bool = False;
    has visited_gens: list[str] = [];
    has conflict_src: str = "";

    can start with Root entry {
        visit [-->];
    }

    can inspect_state with StateRoot entry {
        print(f"preflight schema={here.schema} uid={here.owner_uid}");
        visit [->:CurrentGen:->] else { disengage; };
    }

    can audit_generation with Generation entry {
        if here.selector in self.visited_gens {
            print(f"CYCLE denied at generation {here.selector}");
            disengage;
        }
        self.visited_gens.append(here.selector);
        if here.retained and here.has_gcroot {
            self.rollback_ready = True;
        }
        print(f"generation {here.selector} retained={here.retained} gcroot={here.has_gcroot}");
        visit [->:Hosts:->];
        visit [->:PreviousGen:->] else { # no previous generation chain
        };
    }

    can audit_target with Exposure entry {
        prior = self.conflict_src;
        if prior != "" {
            self.collisions += 1;
            print(f"COLLISION deny: {prior} vs {here.relative_path}");
            disengage;
        }
        self.conflict_src = here.relative_path;
        digest = here.sha256[:12] if len(here.sha256) >= 12 else here.sha256;
        print(f"  {here.kind} {here.relative_path} mode={here.mode} sha={digest}");
        visit [here->:PathConflict:->] else {
            self.conflict_src = prior;
        };
        self.conflict_src = prior;
        visit [-->];
    }
}

walker RollbackOperator {
    has phase: int = 0;
    has walked: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can find_state with StateRoot entry {
        visit [->:CurrentGen:->] else { disengage; };
    }

    can rollback with Generation entry {
        if here.selector in self.walked {
            print(f"rollback cycle guard at {here.selector}");
            disengage;
        }
        self.walked.append(here.selector);
        if self.phase == 0 {
            print(f"leaving current generation {here.selector}");
            self.phase = 1;
            visit [->:PreviousGen:->] else {
                print("rollback denied: no previous generation");
                disengage;
            };
        } else {
            print(f"restored previous generation {here.selector}");
            visit [->:Hosts:->];
            disengage;
        }
    }

    can prove_exposure with Exposure entry {
        digest = here.sha256[:12] if len(here.sha256) >= 12 else here.sha256;
        print(f"  exposure {here.kind}:{here.relative_path} sha={digest}");
        visit [-->];
    }
}

with entry {
