"""Workbook cell-graph: dependency-order evaluation, symbolic binding resolution, and SUMIFS semantics."""

node Cell {
    has label: str = "";
    has num_value: float = 0.0;
    has evaluated: bool = False;
    has mark: int = 0;
}

node LiteralCell(Cell) {
    has literal: float = 0.0;
}

node FormulaCell(Cell) { }

node SumifsCell(Cell) {
    has grant_criterion: str = "";
    has date_cutoff: str = "";
    has text_criterion: str = "";
    has mode: str = "date";
}

node CompareCell(Cell) {
    has threshold: float = 0.0;
}

node DataRow {
    has grant_id: str = "";
    has amount: float = 0.0;
    has as_of: str = "";
    has status: str = "";
    has amount_is_text: bool = False;
    has is_blank: bool = False;

    def matches_grant(criterion: str) -> bool {
        if self.is_blank {
            return False;
        }
        return self.grant_id == criterion;
    }

    def matches_date(cutoff: str) -> bool {
        if self.is_blank or self.amount_is_text {
            return False;
        }
        if self.as_of == "" {
            return False;
        }
        return self.as_of <= cutoff;
    }

    def matches_text(criterion: str) -> bool {
        if self.is_blank or self.status == "" {
            return False;
        }
        return self.status == criterion;
    }
}

node SymbolRef {
    has role: str = "";
    has grant_id: str = "";
}

edge DependsOn { }
edge BindsTo { }
edge InSumRange { }

walker Evaluator {
    has cycle_error: str = "";
    has evaluated_count: int = 0;
    has resolving: bool = False;
    has running_total: float = 0.0;
    has sum_grant: str = "";
    has sum_cutoff: str = "";
    has sum_text: str = "";
    has sum_mode: str = "date";
    has formula_acc: float = 0.0;
    has formula_cell: FormulaCell | None = None;
    has compare_cell: CompareCell | None = None;
    has compare_input: float = 0.0;

    can start with Root entry {
        visit [-->];
    }

    can enter with Cell entry {
        if self.cycle_error != "" {
            disengage;
        }
        if self.resolving {
            if here.evaluated {
                if self.formula_cell is not None {
                    self.formula_acc += here.num_value;
                }
                if self.compare_cell is not None {
                    self.compare_input = here.num_value;
                }
            }
            disengage;
        }
        if here.mark == 1 {
            self.cycle_error = f"CycleDetected: {here.label}";
            disengage;
        }
        if here.mark == 2 {
            disengage;
        }
        here.mark = 1;
        visit [->:DependsOn:->] else { };
    }

    can resolve_sym with SymbolRef entry {
        if self.resolving {
            visit [->:BindsTo:->] else { disengage; };
        }
    }

    can leave_literal with LiteralCell exit {
        if self.cycle_error != "" {
            disengage;
        }
        here.num_value = here.literal;
        here.evaluated = True;
        here.mark = 2;
        self.evaluated_count += 1;
        print(f"  [{here.label}] = {here.num_value}");
    }

    can leave_sumifs with SumifsCell exit {
        if self.cycle_error != "" {
            disengage;
        }
        self.running_total = 0.0;
        self.sum_grant = here.grant_criterion;
        self.sum_cutoff = here.date_cutoff;
        self.sum_text = here.text_criterion;
        self.sum_mode = here.mode;
        visit [->:InSumRange:->] else { };
        here.num_value = self.running_total;
        here.evaluated = True;
        here.mark = 2;
        self.evaluated_count += 1;
        mode_label = "date" if here.mode == "date" else "text";
        print(f"  [{here.label}] SUMIFS({mode_label}) = {here.num_value}");
    }

    can tally with DataRow entry {
        grant_ok = here.matches_grant(self.sum_grant);
        if self.sum_mode == "date" {
            crit_ok = here.matches_date(self.sum_cutoff);
        } else {
            crit_ok = here.matches_text(self.sum_text);
        }
        if grant_ok and crit_ok {
            self.running_total += here.amount;
        }
    }

    can leave_formula with FormulaCell exit {
        if self.cycle_error != "" {
            disengage;
        }
        self.formula_acc = 0.0;
        self.formula_cell = here;
        self.resolving = True;
        visit [->:DependsOn:->] else { };
        self.resolving = False;
        here.num_value = self.formula_acc;
        here.evaluated = True;
        here.mark = 2;
        self.formula_cell = None;
        self.evaluated_count += 1;
        print(f"  [{here.label}] = {here.num_value}");
    }

    can leave_compare with CompareCell exit {
        if self.cycle_error != "" {
            disengage;
        }
        self.compare_cell = here;
        self.compare_input = 0.0;
        self.resolving = True;
        visit [->:DependsOn:->] else { };
        self.resolving = False;
        check_val = 1.0 if self.compare_input >= here.threshold else 0.0;
        here.num_value = check_val;
        here.evaluated = True;
        here.mark = 2;
        self.compare_cell = None;
        self.evaluated_count += 1;
        print(f"  [{here.label}] check({self.compare_input} >= {here.threshold}) = {here.num_value}");
    }
}

with entry {
    print("=== Cycle detection ===");
    ca = FormulaCell(label="A");
    cb = FormulaCell(label="B");
    root ++> ca ++> cb;
    ca +>:DependsOn:+> cb;
    cb +>:DependsOn:+> ca;
    cyc = Evaluator();
    root spawn cyc;
    if cyc.cycle_error != "" {
        print(cyc.cycle_error);
    } else {
        print("no cycle");
    }
    del ca;
    del cb;

    print("=== Workbook evaluation (order-independent) ===");
    as_of = LiteralCell(label="as_of", literal=20250630.0);
    sum_date = SumifsCell(
        label="sum_g1_date",
        grant_criterion="G1",
