        text_criterion="pending",
        mode="text"
    );
    sub_via_sym = FormulaCell(label="sub_via_sym");
    main_formula = FormulaCell(label="main_formula");
    check = CompareCell(label="summary_check", threshold=100.0);
    sym = SymbolRef(role="grant", grant_id="G1");

    r1 = DataRow(grant_id="G1", amount=100.0, as_of="20250115");
    r2 = DataRow(grant_id="G1", amount=50.0, as_of="20250601");
    r3 = DataRow(grant_id="G1", amount=999.0, as_of="20250701");
    r4 = DataRow(grant_id="G1", amount=25.0, as_of="20250301", amount_is_text=True);
    r5 = DataRow(grant_id="G1", amount=0.0, is_blank=True);
    p1 = DataRow(grant_id="G1", amount=10.0, status="pending");
    p2 = DataRow(grant_id="G1", amount=20.0, status="closed");
    p3 = DataRow(grant_id="G1", amount=5.0, status="pending", is_blank=True);

    root ++> as_of ++> sum_pending ++> sub_via_sym ++> main_formula ++> check ++> sum_date;
    sum_date +>:InSumRange:+> r3;
