"""SSSD AD group cache: serial memberOf rebuild starves the backend watchdog."""

node Principal {
    has name: str = "";
    has memberof_size: int = 0;
}

node User(Principal) {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

node Group(Principal) {
    has gid: int = 0;
    has stale: bool = False;
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

node Backend {
    has domain: str = "ad.example";
    has watchdog_budget: int = 10;
    has work_units: int = 0;
    has kills: int = 0;
    has alive: bool = True;
}

edge Member { }

walker MembershipRebuild {
    has backend: Backend | None = None;
    has recomputes: int = 0;
    has pam_blocked: bool = False;
    has ancestor_seen: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can bind with Backend entry {
        if not here.alive {
            print(f"sssd_be: Starting up ('{here.domain}':'%BE_{here.domain}')");
            here.alive = True;
            here.work_units = 0;
        }
        self.backend = here;
        visit [-->];
    }

    can purge_group with Group entry {
        if here.stale {
            print(f"sysdb_delete_group: invalidating '{here.name}' (gid={here.gid})");
            here.stale = False;
            visit [->:Member:->];
        } else {
            visit [-->];
        }
    }

    can recompute_memberof with User | Group entry {
        self.recomputes += 1;
        self.backend.work_units += 1;
        here.memberof_size += 1;
        print(
            f"  memberOf recompute #{self.recomputes} for '{here.name}' "
            f"(memberof_size={here.memberof_size}, work={self.backend.work_units})"
        );
        if self.backend.work_units >= self.backend.watchdog_budget {
            self.backend.alive = False;
            self.backend.kills += 1;
            self.pam_blocked = True;
            print(
                f"sssd: Child ('{self.backend.domain}':"
                f"'%BE_{self.backend.domain}') was terminated by own WATCHDOG"
            );
            disengage;
        }
        if here.name in self.ancestor_seen {
            disengage;
        }
        self.ancestor_seen.append(here.name);
        visit [<--:Member:<--];
        self.ancestor_seen.pop();
        visit [-->];
    }
}

walker PamAccountCheck {
    has username: str = "test-user";

    can start with Root entry {
        principal = self.username.upper();
        print(
            f"sshd-session: Authorized to {self.username}, "
            f"krb5 principal {principal}@AD.EXAMPLE"
        );
