    sum_pending +>:InSumRange:+> p1;
    sum_date +>:DependsOn:+> as_of;
    sub_via_sym +>:DependsOn:+> sum_date;
    sym +>:BindsTo:+> sub_via_sym;
    main_formula +>:DependsOn:+> sym;
    check +>:DependsOn:+> sum_date;

    print("Evaluate (insertion order shuffled; topo order is deterministic):");
    root spawn Evaluator();
    print(f"sum_g1_date={sum_date.num_value} (expect 150.0; excludes text+blank+post-cutoff)");
    print(f"sum_g1_pending={sum_pending.num_value} (expect 10.0; text-eq only)");
    print(f"main_formula={main_formula.num_value} (expect 150.0 via symbolic bind)");
    print(f"summary_check={check.num_value} (expect 1.0)");
}

"""Teranode subtree validation: quadratic slow-path dependency leveling vs ordered linear fast path."""

edge SpendsFrom { }
edge InSubtree { }
edge InBlock { }

node Subtree {
    has name: str = "";
}

node Transaction {
    has tx_id: str = "";
    has level: int = -1;
}

walker ParentProbe {
    has all_ready: bool = True;
    has max_parent_level: int = -1;

    can start with Transaction entry {
        visit [->:SpendsFrom:->] else { disengage; }
    }

    can check_parent with Transaction entry {
        if here.level < 0 {
            self.all_ready = False;
            disengage;
        }
        if here.level > self.max_parent_level {
            self.max_parent_level = here.level;
        }
        visit [->:SpendsFrom:->] else { disengage; }
    }
}

walker TxCounter {
    has count: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can enter with Subtree entry {
        visit [->:InSubtree:->];
    }

    can tally with Transaction entry {
        self.count += 1;
    }
}

walker LevelResetter {
    can start with Root entry {
        visit [-->];
    }

    can enter with Subtree entry {
        visit [->:InSubtree:->];
    }

    can reset with Transaction entry {
        here.level = -1;
    }
}

walker SlowLevelPass {
    has scans: int = 0;
    has made_progress: bool = False;

    can start with Root entry {
        visit [-->];
    }

    can enter with Subtree entry {
        visit [->:InSubtree:->];
    }

    can try_assign with Transaction entry {
        if here.level < 0 {
            self.scans += 1;
            probe = ParentProbe();
            here spawn probe;
            if probe.all_ready {
                here.level = probe.max_parent_level + 1;
                self.made_progress = True;
            }
        }
    }
}

walker SlowPathPreparer {
    has outer_passes: int = 0;
    has inner_scans: int = 0;

    can start with Root entry {
        counter = TxCounter();
        root spawn counter;
        tx_n = counter.count;
        max_iter = tx_n + 1;
        for i in range(0, max_iter) {
            pass_w = SlowLevelPass();
            root spawn pass_w;
            self.inner_scans += pass_w.scans;
            self.outer_passes += 1;
            if pass_w.made_progress == False {
                break;
            }
        }
        quad_note = "quadratic rescans on deep chains";
        if tx_n > 0 {
            quad_note = f"~{self.inner_scans // tx_n}x rescans per tx on chain";
        }
        print(
            f"Slow path (UseOrderedLevelAlgorithm=false): {tx_n} txs, "
            f"{self.outer_passes} outer passes, {self.inner_scans} inner scans "
            f"({quad_note})"
        );
        disengage;
    }
}

walker FastPathPreparer {
    has scans: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can enter with Subtree entry {
        visit [->:InBlock:->];
    }

    can assign_ordered with Transaction entry {
        self.scans += 1;
        probe = ParentProbe();
        here spawn probe;
        here.level = probe.max_parent_level + 1;
        visit [->:InBlock:->] else { disengage; }
    }
}

