walker JsonTraverser {
    has path_buf: str = "";
    has key_masks: dict[str, int] = {};
    has keys_processed: int = 0;
    has dup_key_hits: int = 0;
    has depth: int = 0;
    has max_depth: int = 64;

    can start with Root entry {
        print("JSONExtractTree traverse (reusable path buffer + bitmask dup keys)");
        visit [-->[?:JsonObject]];
    }

    can walk_object with JsonObject entry {
        if self.depth >= self.max_depth {
            print(f"depth cap reached at {self.path_buf}");
            disengage;
        }
        self.depth += 1;
        saved_path = self.path_buf;
        saved_masks: dict[str, int] = self.key_masks;
        self.key_masks = {};

        if here.key_name != "" {
            joined = here.key_name;
            if self.path_buf != "" {
                joined = self.path_buf + "." + here.key_name;
            }
            self.path_buf = joined;
        }

        print(f"[object] path={self.path_buf}");
        visit [->:Child:->];
        self.path_buf = saved_path;
        self.key_masks = saved_masks;
        self.depth -= 1;
    }

