"""JSON extract tree traversal: reusable path buffer and two-bit duplicate-key masks per object."""

node JsonValue {
    has key_name: str = "";
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

node JsonObject(JsonValue) {
}

node JsonScalar(JsonValue) {
    has element_kind: int = 0;
    has value_repr: str = "";
}

edge Child { }

walker JsonTraverser {
    has path_buf: str = "";
    has key_masks: dict[str, int] = {};
    has keys_processed: int = 0;
    has dup_key_hits: int = 0;
    has depth: int = 0;
    has max_depth: int = 64;

    can start with Root entry {
        print("JSONExtractTree traverse (reusable path buffer + bitmask dup keys)");
        visit [-->];
    }

    can walk_object with JsonObject entry {
        if self.depth >= self.max_depth {
            print(f"depth cap reached at {self.path_buf}");
            disengage;
        }
        self.depth += 1;
        saved_path = self.path_buf;
        saved_masks: dict[str, int] = self.key_masks;
        self.key_masks = {};

        if here.key_name != "" {
            joined = here.key_name;
            if self.path_buf != "" {
                joined = self.path_buf + "." + here.key_name;
            }
            self.path_buf = joined;
        }

        print(f"[object] path={self.path_buf}");
        visit [->:Child:->];
        self.path_buf = saved_path;
        self.key_masks = saved_masks;
        self.depth -= 1;
    }

    can walk_scalar with JsonScalar entry {
        key = here.key_name;
        kind: int = here.element_kind;
        bit: int = 1 << kind;

        prior: int = 0;
        if key in self.key_masks {
            prior = self.key_masks[key];
        }

        kind_label = "STRING" if kind == 0 else "NUMBER";
        dot_path = key;
        if self.path_buf != "" {
            dot_path = self.path_buf + "." + key;
        }

        if (prior & bit) != 0 {
            self.dup_key_hits += 1;
            print(f"  [dup-key] path={dot_path} kind={kind_label} mask={prior}");
        }

        new_mask: int = prior | bit;
        self.key_masks[key] = new_mask;
        self.keys_processed += 1;
        print(f"  [scalar] path={dot_path} kind={kind_label} val={here.value_repr} mask={new_mask}");
    }
}

