"""OpenCrawling ReBAC demo: relationship tuples in an authorization graph replace static document ACL payloads."""

node Principal {
    has name: str = "";
}

node Group {
    has name: str = "";
}

node Folder {
    has name: str = "";
}

node Document {
    has doc_id: str = "";
    has title: str = "";
    has legacy_acl_allow: bool = False;
}

edge MemberOf { }
edge CanView { }
edge Contains { }
edge Subfolder { }

walker TupleWriter {
    has tuples_written: int = 0;

    can start with Root entry {
        print("oc-core ingestion: writing OpenFGA relationship tuples");
        visit [-->];
        print(f"  tuples written: {self.tuples_written}");
        disengage;
    }

    can descend with Folder entry {
        visit [->:Subfolder:->];
        visit [->:Contains:->];
        visit [-->];
    }

    can emit with Document entry {
        if here.legacy_acl_allow {
            print(f"  skip {here.doc_id} (MetadataBasedAuthorizationProvider fallback)");
        } else {
            print(f"  write document:{here.doc_id}#parent@folder (Contains edge)");
            self.tuples_written += 1;
        }
        visit [-->];
    }
}

walker RebacEvaluator {
    has subject: Principal;
    has candidates: list[str] = [];
    has authorized: list[str] = [];
    has granted: bool = False;
    has visited_folders: list[str] = [];

    can start with Root entry {
        print(f"McpVectorServer: batch-check for {self.subject.name}");
        visit [-->];
        print(f"  vector hits: {self.candidates}");
        print(f"  authorized subset: {self.authorized}");
        disengage;
    }

    can descend with Folder entry {
        visit [->:Subfolder:->];
        visit [->:Contains:->];
        visit [-->];
    }

    can evaluate with Document entry {
        if not (here.doc_id in self.candidates) {
            visit [-->];
        } else {
            self.granted = False;
            self.visited_folders = [];
            source = "rebac-graph";
            if here.legacy_acl_allow {
                self.granted = True;
                source = "metadata-fallback";
            } else {
                visit [<-:CanView:<-];
                visit [<-:Contains:<-];
            }
            verdict = "ALLOW" if self.granted else "DENY";
            print(f"  [{verdict}/{source}] {here.doc_id}: {here.title}");
            if self.granted {
                self.authorized.append(here.doc_id);
            }
            visit [-->];
        }
    }

    can group_grant with Group entry {
        if self.granted {
            disengage;
        }
        visit [<-:MemberOf:<-];
    }

    can member_match with Principal exit {
        if here.name == self.subject.name {
            self.granted = True;
        }
    }

    can folder_inherit with Folder entry {
        if self.granted {
            disengage;
        }
        for key in self.visited_folders {
            if key == here.name {
                disengage;
            }
        }
        self.visited_folders.append(here.name);
        visit [<-:CanView:<-];
        visit [<-:Subfolder:<-] else { disengage; }
    }
}

with entry {
    repo = Folder(name="sharepoint-root");
    specs = Folder(name="engineering-specs");
    eng = Group(name="engineering");
    alice = Principal(name="alice");
    bob = Principal(name="bob");

    alice +>:MemberOf:+> eng;
    eng +>:CanView:+> repo;

    repo +>:Subfolder:+> specs;

    api_doc = Document(
        doc_id="doc-101",
        title="API Specification",
        legacy_acl_allow=False
    );
    secret_doc = Document(
        doc_id="doc-102",
        title="Q4 Roadmap",
        legacy_acl_allow=False
    );
    legacy_doc = Document(
        doc_id="doc-099",
        title="Pre-migration Export",
        legacy_acl_allow=True
    );

    specs +>:Contains:+> api_doc;
    specs +>:Contains:+> secret_doc;

    root ++> repo ++> legacy_doc;

    root spawn TupleWriter();

    hits = ["doc-101", "doc-102", "doc-099"];
    root spawn RebacEvaluator(subject=alice, candidates=hits);
    root spawn RebacEvaluator(subject=bob, candidates=hits);
}

"""Forge pipeline linter: validate step dependencies, detect DAG cycles, and emit style warnings."""

node Pipeline {
    has name: str = "";
}

node Step {
    has step_id: str = "";
    has image: str = "";
    has step_type: str = "generator";
    has has_timeout: bool = False;
    has depends_on: list[str] = [];
}

edge DependsOn { }

walker Linter {
    has known_ids: list[str] = [];
    has seen_ids: list[str] = [];
    has errors: list[str] = [];
    has warnings: list[str] = [];
    has step_total: int = 0;
    has check_deps: bool = False;
    has allowed_types: list[str] = ["generator", "pipeline", "approval", "release"];

    can start with Root entry {
        visit [-->];
    }

    can walk_pipeline with Pipeline entry {
        visit [-->];
    }

    can audit with Step entry {
        if not self.check_deps {
            self.step_total += 1;
            if here.step_id in self.seen_ids {
                self.errors.append(f"✗ Duplicate step ID \"{here.step_id}\"");
            } else {
                self.seen_ids.append(here.step_id);
                self.known_ids.append(here.step_id);
            }
            if here.step_type not in self.allowed_types {
                self.errors.append(
                    f"✗ Step \"{here.step_id}\" has unrecognized type \"{here.step_type}\""
                );
            }
            if not here.has_timeout {
                self.warnings.append(
                    f"⚠ Step \"{here.step_id}\" has no timeout configured"
                );
            }
            if ":latest" in here.image {
                self.warnings.append(
                    f"⚠ image: {here.image}  -consider pinning to a specific version"
                );
            }
        } else {
            for dep_id in here.depends_on {
                if dep_id not in self.known_ids {
                    self.errors.append(
                        f"✗ Step \"{here.step_id}\" depends on \"{dep_id}\" which is not defined"
                    );
                }
            }
        }
        visit [-->];
    }
}

walker CycleGuard {
    has visiting: list[str] = [];
    has finished: list[str] = [];
    has cycle_found: bool = False;

    can start with Root entry {
        visit [-->[?:Step]] else { disengage; };
    }

    can probe with Step entry {
        if self.cycle_found {
            disengage;
        }
        if here.step_id in self.finished {
            visit [-->[?:Step]] else { disengage; };
        }
        if here.step_id in self.visiting {
            self.cycle_found = True;
            disengage;
        }
        self.visiting.append(here.step_id);
        visit [->:DependsOn:->] else { };
        if len(self.visiting) > 0 {
            self.visiting = self.visiting[:-1];
        }
        self.finished.append(here.step_id);
        visit [-->[?:Step]] else { disengage; };
    }
}

with entry {
    pipeline = Pipeline(name="forge-ci");
    build = Step(
        step_id="build",
        image="golang:1.22",
        step_type="generator",
        has_timeout=True
    );
    test = Step(
        step_id="test",
        image="python:latest",
        step_type="generator",
        depends_on=["build"]
    );
    deploy = Step(
        step_id="deploy",
        image="ubuntu:22.04",
        step_type="release",
        depends_on=["test", "build-arm64"]
    );

    root ++> pipeline;
    pipeline ++> build;
    pipeline ++> test;
    pipeline ++> deploy;
    test +>:DependsOn:+> build;
    deploy +>:DependsOn:+> test;

    collector = Linter();
    root spawn collector;
    print(f"✓ Parsed successfully ({collector.step_total} steps)");
    for warn in collector.warnings {
        print(warn);
    }
    for err in collector.errors {
        print(err);
    }

    checker = Linter(check_deps=True);
    checker.known_ids = collector.known_ids;
    root spawn checker;
    for err in checker.errors {
        print(err);
    }

    guard = CycleGuard();
    root spawn guard;
    if guard.cycle_found {
        print("✗ Cycle detected in depends_on graph");
    } else {
        print("✓ No cycles detected");
    }
}

"""Code-intelligence call graph: persist resolved Calls edges and traverse them.

Models WAVE-1 graph persistence (edges instead of flattened CSV metadata)
and WAVE-2 consumers: forward call tracing, reverse impact analysis, and
orphan detection over functions unreachable from entry points.
"""

node Module {
    has path: str = "";
}

node Function {
    has name: str = "";
    has qualified_name: str = "";
    has is_entry: bool = False;
}

edge Defines { }

edge Calls {
    has resolved: bool = True;
    has provenance: str = "extracted";
}

walker GraphIndexer {
    can start with Root entry {
        print("Indexer: traversing persisted graph (not CSV metadata)");
        visit [-->];
    }

    can scan with Module entry {
        print(f"module {here.path}");
        visit [->:Defines:->] else { disengage; };
    }

    can inspect with Function entry {
        print(f"  fn {here.qualified_name}");
        visit [->:Calls:->] else { disengage; };
    }
}

walker CallGraphExplorer {
    has seen: list[str] = [];

    can walk with Function entry {
        if here.qualified_name in self.seen {
            print(f"  [cycle-guard] skipping {here.qualified_name}");
            disengage;
        }
        self.seen.append(here.qualified_name);
        entry_mark = " (entry)" if here.is_entry else "";
        print(f"  call-chain -> {here.qualified_name}{entry_mark}");
        visit [->:Calls:->] else { disengage; };
    }
}

walker ImpactTracer {
    has seen: list[str] = [];

    can trace with Function entry {
        if here.qualified_name in self.seen {
            disengage;
        }
        self.seen.append(here.qualified_name);
        print(f"  impact <- {here.qualified_name}");
        visit [<--:Calls:--] else { disengage; };
    }
}

walker ReachabilityMarker {
    has reachable: list[str] = [];

    can mark with Function entry {
        if here.qualified_name in self.reachable {
            disengage;
        }
        self.reachable.append(here.qualified_name);
        visit [->:Calls:->] else { disengage; };
    }
}

walker OrphanAuditor {
    has reachable: list[str] = [];

    can start with Root entry {
        visit [-->[?:Function]] else { disengage; };
    }

    can audit with Function entry {
        qname = here.qualified_name;
        linked = here.is_entry or (qname in self.reachable);
        status = "LINKED" if linked else "ORPHAN";
        print(f"  [{status}] {qname}");
        disengage;
    }
}

with entry {
    main_mod = Module(path="app/main.py");
    util_mod = Module(path="app/utils.py");
    root ++> main_mod;
    root ++> util_mod;

    main_fn = Function(name="main", qualified_name="app.main.main", is_entry=True);
    helper_fn = Function(name="helper", qualified_name="app.main.helper");
    utils_fn = Function(name="utils", qualified_name="app.utils.utils");
    orphan_fn = Function(name="cleanup", qualified_name="app.main.cleanup");

    main_mod +>:Defines:+> main_fn;
    main_mod +>:Defines:+> helper_fn;
    main_mod +>:Defines:+> orphan_fn;
    util_mod +>:Defines:+> utils_fn;

    main_fn +>:Calls(resolved=True, provenance="extracted"):+> helper_fn;
    helper_fn +>:Calls(resolved=True, provenance="extracted"):+> utils_fn;
    utils_fn +>:Calls(resolved=True, provenance="inferred"):+> helper_fn;

    discarded_csv = "main->helper,helper->utils,utils->helper";
    print(f"discarded pattern: calls=\"{discarded_csv}\" (untraversable metadata)");
    print("");

    root spawn GraphIndexer();
    print("");

    print("forward call-graph from entry:");
    main_fn spawn CallGraphExplorer();
    print("");

    print("reverse impact on app.utils.utils:");
    utils_fn spawn ImpactTracer();
    print("");

    marker = ReachabilityMarker();
    main_fn spawn marker;
    print("orphan audit:");
    auditor = OrphanAuditor(reachable=marker.reachable);
    root spawn auditor;
}

