"""Small-datapath lab spine: three chaining RV32I labs with prerequisite blockers."""

node Lab {
    has title: str = "";
    has stage: int = 0;
    has complete: bool = False;
    has held: bool = False;
}

node Prereq {
    has issue_id: int = 0;
    has title: str = "";
    has merged: bool = False;
}

edge FeedsInto {
    has note: str = "";
}

edge BlockedBy { }

walker SpineAuditor {
    has stages_seen: int = 0;
    has seen_stages: list[int] = [];
    has spine_ok: bool = True;

    can start with Root entry {
        print("Walking datapath lab spine: ALU slice -> register/bus -> control");
        visit [-->];
    }

    can audit with Lab entry {
        if here.stage in self.seen_stages {
            print(f"[CYCLE] stage {here.stage} revisited — aborting");
            self.spine_ok = False;
            disengage;
        }
        self.seen_stages.append(here.stage);
        if here.held {
            print(f"[HELD] stage {here.stage}: {here.title} — spine parked");
            self.spine_ok = False;
            disengage;
        }
        status = "DONE" if here.complete else "OPEN";
        print(f"[{status}] stage {here.stage}: {here.title}");
        self.stages_seen += 1;
        visit [->:FeedsInto:->] else {
            print(f"Spine terminus after {self.stages_seen} lab(s)");
            disengage;
        };
    }
}

walker PrereqProbe {
    has blocker_count: int = 0;

    can start with Root entry {
        print("Scanning unmerged prerequisite blockers on the spine");
        visit [-->];
    }

    can scan with Lab entry {
        self.blocker_count = 0;
        visit [->:BlockedBy:->];
        if self.blocker_count > 0 {
            print(f"stage {here.stage} ({here.title}) blocked by "
                  f"{self.blocker_count} unmerged prereq(s)");
        } else {
            print(f"stage {here.stage} ({here.title}) has no open blockers");
        }
        visit [->:FeedsInto:->] else { disengage; };
    }

    can tally with Prereq entry {
        if not here.merged {
            self.blocker_count += 1;
            print(f"  blocker #{here.issue_id}: {here.title}");
        }
    }
}

