    pipeline ++> build;
    pipeline ++> test;
    pipeline ++> deploy;
    test +>:DependsOn:+> build;
    deploy +>:DependsOn:+> test;

    collector = Linter();
    root spawn collector;
    print(f"✓ Parsed successfully ({collector.step_total} steps)");
    for warn in collector.warnings {
        print(warn);
    }
    for err in collector.errors {
        print(err);
    }

    checker = Linter(check_deps=True);
    checker.known_ids = collector.known_ids;
    root spawn checker;
    for err in checker.errors {
        print(err);
    }

    guard = CycleGuard();
    root spawn guard;
    if guard.cycle_found {
        print("✗ Cycle detected in depends_on graph");
