"""Postgres 19 SQL/PGQ demo: multi-hop FK graph reachability with depth caps and cycle guards."""

node DbTable {
    has table_name: str = "";
    has schema_name: str = "public";
}

node BenchmarkConfig {
    has max_hops: int = 3;
    has query_label: str = "GRAPH_TABLE";
}

edge ForeignKey {
    has fk_column: str = "";
    has ref_column: str = "id";
}

walker GraphTableWalker {
    has max_hops: int = 3;
    has query_label: str = "GRAPH_TABLE";
    has current_hop: int = -1;
    has visited: list[str] = [];
    has reachable_count: int = 0;
    has cycles_blocked: int = 0;

    can start with Root entry {
        print(f"[{self.query_label}] multi-hop FK traversal (max {self.max_hops} hops)");
        visit [-->];
    }

    can load_config with BenchmarkConfig entry {
        self.max_hops = here.max_hops;
        self.query_label = here.query_label;
        visit [-->];
    }

    can traverse with DbTable entry {
        key = f"{here.schema_name}.{here.table_name}";
        if key in self.visited {
            self.cycles_blocked += 1;
            disengage;
        }
        self.visited.append(key);
        self.current_hop += 1;
        self.reachable_count += 1;
        print(f"  [{self.query_label}] hop {self.current_hop}: {key}");
        if self.current_hop >= self.max_hops {
            disengage;
        }
        visit [->:ForeignKey:->] else { disengage; };
