"""DSA syllabus checklist: model modules and topics as nodes, walk in order to audit progress and find the next pending item."""

node ChecklistItem {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

node Module(ChecklistItem) {
    has section_label: str = "";
}

node Topic(ChecklistItem) {
}

edge Contains { }

edge NextInOrder {
    has seq: int = 0;
}

walker SyllabusAuditor {
    has completed_count: int = 0;
    has pending_count: int = 0;
    has modules_done: int = 0;
    has modules_pending: int = 0;

    can start with Root entry {
        print("=== DSA Syllabus Audit — Pratyaksh ===");
        visit [-->];
    }

    can audit_module with Module entry {
        module_mark = "[x]" if not here.available else "[ ]";
        print(f"{module_mark} {here.title} (module #{here.year})");
        if here.available {
            self.modules_pending += 1;
        } else {
            self.modules_done += 1;
        }
        visit [->:Contains:->];
        visit [->:NextInOrder:->];
    }

    can tally with Module | Topic entry {
        if here.available {
            self.pending_count += 1;
        } else {
            self.completed_count += 1;
        }
    }

    can audit_topic with Topic entry {
        topic_mark = "[x]" if not here.available else "[ ]";
        print(f"    {topic_mark} {here.title}");
        if here.available {
            self.pending_count += 1;
        } else {
            self.completed_count += 1;
        }
        visit [->:NextInOrder:->];
    }

    can finish with Root exit {
        print(f"--- totals: {self.completed_count} done, {self.pending_count} pending "
              f"({self.modules_done} modules complete, {self.modules_pending} in progress) ---");
    }
}

walker NextItemFinder {
    has next_title: str = "";
    has next_seq: int = 0;
    has found: bool = False;
    has seen: list = [];

    can start with Root entry {
        visit [-->];
    }

    can seek_module with Module entry {
        if self.found {
            disengage;
        }
        node_key = f"module:{here.title}";
        for key in self.seen {
            if key == node_key {
                disengage;
            }
        }
        self.seen.append(node_key);
        visit [->:Contains:->] else {
            if here.available and not self.found {
                self.next_title = here.title;
                self.next_seq = here.year;
                self.found = True;
                disengage;
            }
        };
        if not self.found {
            visit [->:NextInOrder:->] else { disengage; };
        }
    }

    can seek_topic with Topic entry {
        if self.found {
            disengage;
        }
        node_key = f"topic:{here.title}";
        for key in self.seen {
            if key == node_key {
                disengage;
            }
        }
        self.seen.append(node_key);
        if here.available and not self.found {
            self.next_title = here.title;
            self.next_seq = here.year;
            self.found = True;
            disengage;
        }
        visit [->:NextInOrder:->] else { disengage; };
    }
}

