"""GitHub Project hierarchy tree: build nested issue rows and flatten with collapse."""

node ProjectRow {
    has url: str = "";
    has title: str = "";
    has parent_url: str = "";
    has row_id: str = "";
    has depth: int = 0;
    has is_child: bool = False;
}

edge ParentOf { }

walker HierarchyBuilder {
    has rows: list = [];

    can start with Root entry {
        visit [-->];
    }

    can collect with ProjectRow entry {
        self.rows.append(here);
        visit [-->];
    }

    def find_by_url(target: str) -> ProjectRow | None {
        for row in self.rows {
            if row.url == target {
                return row;
            }
        }
        return None;
    }

    def resolve_parent(row: ProjectRow) -> ProjectRow | None {
        if row.parent_url == "" {
            return None;
        }
        if row.url != "" and row.parent_url == row.url {
            return None;
        }
        return self.find_by_url(row.parent_url);
    }

    def link_rows() -> list {
        for row in self.rows {
            parent = self.resolve_parent(row);
            if parent is not None {
                parent +>:ParentOf:+> row;
                row.is_child = True;
            }
        }
        roots = [];
        for row in self.rows {
            if not row.is_child {
                roots.append(row);
            }
        }
        print(f"Built tree: {len(roots)} root rows from {len(self.rows)} input rows");
        return roots;
    }
}

walker TreeFlattener {
    has collapsed_ids: list = [];
    has depth: int = 0;

    can start with ProjectRow entry {
        self.depth = 0;
        self.emit_node(here);
        collapsed = self.is_collapsed(here);
        if not collapsed {
            child_depth = self.depth + 1;
            self.depth = child_depth;
            visit [->:ParentOf:->] else { };
            self.depth = 0;
        }
    }

    can on_child with ProjectRow entry {
        self.emit_node(here);
        collapsed = self.is_collapsed(here);
        if not collapsed {
            saved = self.depth;
            next_depth = saved + 1;
            self.depth = next_depth;
            visit [->:ParentOf:->] else { };
            self.depth = saved;
        }
    }

    def is_collapsed(row: ProjectRow) -> bool {
        for cid in self.collapsed_ids {
            if cid == row.row_id {
                return True;
            }
        }
        return False;
    }

    def emit_node(row: ProjectRow) {
        pad = "";
        for _ in range(self.depth) {
            pad += "  ";
        }
        label = row.url if row.url != "" else "(no url)";
        print(f"{pad}{row.title} [{label}] depth={self.depth}");
    }
}

