node Test {
    has selector: str = "";
    has body_fp: str = "";
    has available: bool = True;
}

node Seam {
    has seam_id: str = "";
    has owner: str = "";
    has kind: str = "";
    has aggregate_class: str = "Opaque";
    has available: bool = True;
}

