    has module_path: str = "";
}

node GripSummary {
    has selector: str = "";
    has seam_id: str = "";
    has reason: str = "";
    has confidence: float = 0.0;
    has reach: str = "NotProven";
    has activate: str = "NotProven";
    has propagate: str = "NotProven";
    has observe: str = "NotProven";
    has discriminate: str = "NotProven";
    has disposition: str = "Pending";
    has fingerprint: str = "";
    has available: bool = True;
}

edge PairProjection { }
edge TargetsSeam { }
edge BatchRequest { }

walker GripProjector {
    has selectors: list[str] = [];
    has hard_cap: int = 10;
    has emitted: int = 0;
    has omitted: int = 0;
    has inspected_tests: int = 0;
    has inspected_seams: int = 0;

    def selector_requested(sel: str) -> bool {
        for wanted in self.selectors {
            if wanted == sel {
                return True;
            }
        }
        return False;
    }

    def stage_line(summary: GripSummary) -> str {
        return (
            f"reach={summary.reach} activate={summary.activate} "
            f"propagate={summary.propagate} observe={summary.observe} "
            f"discriminate={summary.discriminate}"
        );
    }

    can start with Root entry {
        print(
            f"batch projection: {len(self.selectors)} selector(s), "
            f"cap={self.hard_cap}"
        );
        visit [->:BatchRequest:->] else { disengage; };
    }

    can resolve with Test entry {
        if not self.selector_requested(here.selector) {
            visit [-->];
            return;
        }
        self.inspected_tests += 1;
        print(f"resolved test: {here.selector} (fp={here.body_fp})");
        visit [here->:PairProjection:->] else {
            print(
                f"  no mapped seam for {here.selector}; "
                f"not reporting strong grip from assertions alone"
            );
            visit [-->];
        };
    }

    can emit with GripSummary entry {
        if self.emitted >= self.hard_cap {
            self.omitted += 1;
            disengage;
        }
        stages = self.stage_line(here);
        print(
            f"  pairwise [{here.disposition}] {here.selector} -> "
            f"{here.seam_id}: {stages}"
        );
        print(
            f"    reason={here.reason} confidence={here.confidence} "
            f"fp={here.fingerprint}"
        );
        self.emitted += 1;
        visit [here->:TargetsSeam:->] else { visit [-->]; };
    }

    can contrast with UnitSeam | IntegrationSeam entry {
        self.inspected_seams += 1;
        label = here.kind if here.kind else "seam";
        print(
            f"    seam aggregate (NOT copied): {here.seam_id} "
            f"{label} class={here.aggregate_class}"
        );
        visit [-->];
    }

    can finish with Seam entry {
        visit [-->];
    }
}

