walker PhaseSweep {
    can start with Root entry {
        print("=== json-schema-rs phased roadmap ===");
        visit [-->];
    }

    can enter with Phase entry {
        print(f"\nPhase {here.num} — {here.label}");
        visit [->:Hosts:->] else { visit [-->]; };
    }

    can list with Epic | Bug entry {
        status = "DONE" if here.done else "open";
        kind = "epic" if isinstance(here, Epic) else "bug";
