"""Go level-3 dataflow substrate: CFG blocks, PDG data sites, SDG SUMMARY reachability."""

node Callable {
    has name: str = "";
    has signature: str = "";
}

node Block {
    has label: str = "";
    has kind: str = "stmt";
}

node DataSite {
    has site_id: str = "";
    has expr: str = "";
    has is_source: bool = False;
    has is_sink: bool = False;
}

edge CFGFlow { }
edge DeferResume { }
edge DataDep { }
edge Summary { }
edge Calls { }

walker CFGExplorer {
    has step: int = 0;

    can start with Root entry {
        print("--- CFG (exceptional edges incl. defer_resume) ---");
        visit [-->];
    }

    can open_callable with Callable entry {
        print(f"callable {here.name}{here.signature}");
        visit [-->[?:Block]];
    }

    can walk_block with Block entry {
        self.step += 1;
        tag = "ENTRY" if here.kind == "entry" else "EXIT" if here.kind == "exit" else "STMT";
        print(f"  [{self.step}] {tag}: {here.label}");
        visit [->:CFGFlow:->];
        visit [->:DeferResume:->];
    }
}

walker SourceSinkProbe {
    has flows: list[str] = [];
    has stack: list[str] = [];
    has depth: int = 0;
    has max_depth: int = 32;

    can start with Root entry {
        print("--- PDG + SDG SUMMARY source-to-sink reachability ---");
        visit [-->];
    }

    can scan_callable with Callable entry {
        visit [-->[?:DataSite]];
        visit [->:Calls:->];
    }

    can seed with DataSite entry {
        if not here.is_source {
            disengage;
        }
        self.stack = [here.site_id];
        self.depth = 0;
        print(f"source: {here.expr} [{here.site_id}]");
        visit [->:DataDep:->] else { visit [->:Summary:->] else { disengage; }; };
    }

    can follow with DataSite entry {
        if len(self.stack) == 0 {
            disengage;
        }
        if here.is_source {
            disengage;
        }
        if here.site_id in self.stack {
            print(f"  cycle guard at {here.site_id}");
            disengage;
        }
        if self.depth >= self.max_depth {
            print(f"  depth cap at {here.site_id}");
            disengage;
        }
        self.depth += 1;
        self.stack.append(here.site_id);
        if here.is_sink {
            path = " -> ".join(self.stack);
            self.flows.append(path);
            print(f"  REACHES SINK: {here.expr} via {path}");
            disengage;
        }
        visit [->:DataDep:->] else { visit [->:Summary:->] else { disengage; }; };
    }

    can finish with Root exit {
        print(f"source-to-sink paths found: {len(self.flows)}");
    }
}

with entry {
    main_fn = Callable(name="main", signature="()");
    proc_fn = Callable(name="processInput", signature="(string)");

    entry_blk = Block(label="ENTRY", kind="entry");
    read_blk = Block(label="read_request", kind="stmt");
    call_blk = Block(label="call_processInput", kind="stmt");
    defer_blk = Block(label="defer_cleanup", kind="stmt");
    exit_blk = Block(label="EXIT", kind="exit");

    user_in = DataSite(site_id="main.read", expr="r.Body", is_source=True);
    call_arg = DataSite(site_id="main.arg", expr="userInput");
    dirty_val = DataSite(site_id="main.dirty", expr="result");
    sink_site = DataSite(site_id="main.sink", expr="w.Write(result)", is_sink=True);

    proc_param = DataSite(site_id="proc.param", expr="param");
    proc_ret = DataSite(site_id="proc.ret", expr="return param");

    root ++> main_fn ++> proc_fn;
    main_fn ++> entry_blk;

    entry_blk +>:CFGFlow:+> read_blk;
    read_blk +>:CFGFlow:+> call_blk;
    call_blk +>:CFGFlow:+> exit_blk;
    call_blk +>:DeferResume:+> defer_blk;
    defer_blk +>:CFGFlow:+> exit_blk;

    read_blk ++> user_in;
    call_blk ++> call_arg ++> dirty_val ++> sink_site;
    call_blk +>:Calls:+> proc_fn;
    proc_fn ++> proc_param ++> proc_ret;

    user_in +>:DataDep:+> call_arg;
    call_arg +>:Summary:+> proc_param;
    proc_param +>:DataDep:+> proc_ret;
    proc_ret +>:Summary:+> dirty_val;
    dirty_val +>:DataDep:+> sink_site;

    root spawn CFGExplorer();
    root spawn SourceSinkProbe();
}

"""Runway linked-record lazy loading: selection-scoped frontier batching with cycle guards."""

node SelectionScope {
    has mode: str = "LAZY";
}

node Exchange {
    has name: str = "";
    has record_id: int = 0;
}

node LinkField {
    has field_name: str = "";
    has state: str = "UNLOADED";
}

edge InSelection { }
edge HasLinkField { }
edge ChildLink { }
edge ParentLink { }

walker LazySelector {
    has rtts: int = 0;
    has identity: list[int] = [];

    def charge(detail: str) {
        self.rtts += 1;
        print(f"RTT {self.rtts}: {detail}");
    }

    def remember_id(rid: int) {
        if rid not in self.identity {
            self.identity.append(rid);
        }
    }

    can start with Root entry {
        print("=== LAZY selection: roots without navigating linked records ===");
        self.charge("select root cohort (scalar paths + raw link ids only)");
        visit [->:InSelection:->] else { disengage; };
    }

    can bind_scope with SelectionScope entry {
        print(f"  effective mode: {here.mode}");
        visit [-->];
    }

    can hydrate_root with Exchange entry {
        self.remember_id(here.record_id);
        print(
            f"  partial Record {here.name} (id={here.record_id}) — linked fields deferred"
        );
        visit [-->];
    }

    can finish with Root exit {
        print(f"  lazy selector total RTTs: {self.rtts}");
    }
}

walker FieldResolver {
    has rtts: int = 0;
    has identity: list[int] = [];
    has target_field: str = "";
    has phase: str = "init";

    def charge(detail: str) {
        self.rtts += 1;
        print(f"RTT {self.rtts}: {detail}");
    }

    def remember_id(rid: int) {
        if rid not in self.identity {
            self.identity.append(rid);
        }
    }

    def mapped(rid: int) -> bool {
        return rid in self.identity;
    }

    can anchor with Exchange entry {
        if self.phase == "init" {
            self.phase = "scan";
            self.remember_id(here.record_id);
            visit [->:HasLinkField:->] else { disengage; };
        } else {
            if self.target_field == "children" {
                visit [->:ChildLink:->] else { disengage; };
            } else {
                visit [->:ParentLink:->] else { disengage; };
            }
        }
    }

    can touch_field with LinkField entry {
        if here.field_name != self.target_field {
            visit [-->] else { disengage; };
        }
        if here.state == "LOADED" {
            print(f"  {here.field_name} already LOADED on anchor — 0 RTT");
            disengage;
        }
        if here.state == "FAILED" {
            print(f"  {here.field_name} FAILED — skip resolution");
            disengage;
        }
        here.state = "LOADING";
        self.charge(
            f"bulk-resolve immediate {here.field_name} frontier (single-flight)"
        );
        here.state = "LOADED";
        self.phase = "resolve";
        visit [<--:HasLinkField:--] else { disengage; };
    }

    can deliver with Exchange entry {
        if self.mapped(here.record_id) {
            print(f"    identity-map hit: {here.name} (0 RTT)");
            disengage;
        }
        self.remember_id(here.record_id);
        print(f"    frontier resolved: {here.name} (id={here.record_id})");
        disengage;
    }

    can finish with Exchange exit {
        print(f"  field resolver RTTs this access: {self.rtts}");
    }
}

walker EagerPrefetch {
    has rtts: int = 0;
    has guard: list[int] = [];

    def charge(detail: str) {
        self.rtts += 1;
        print(f"RTT {self.rtts}: {detail}");
    }

    can start with Root entry {
        print("=== EAGER selection: recursive link prefetch ===");
        self.charge("eager navigate + prefetch all reachable links");
        visit [->:InSelection:->];
        visit [-->] else { disengage; };
    }

    can prefetch with Exchange entry {
        if here.record_id in self.guard {
            print(f"  cycle guard: stop at {here.name}");
            disengage;
        }
        self.guard.append(here.record_id);
        print(f"  prefetched: {here.name} (id={here.record_id})");
        visit [->:ChildLink:->];
        visit [->:ParentLink:->] else { disengage; };
    }

    can finish with Root exit {
        print(f"  eager prefetch total RTTs: {self.rtts}");
    }
}

with entry {
    scope = SelectionScope(mode="LAZY");
    root +>:InSelection:+> scope;

    nyse = Exchange(name="NYSE", record_id=1);
    aapl = Exchange(name="AAPL", record_id=2);
    msft = Exchange(name="MSFT", record_id=3);
    opts = Exchange(name="OPTIONS", record_id=4);

    scope ++> nyse ++> aapl;

    nyse_children = LinkField(field_name="children", state="UNLOADED");
    nyse_parent = LinkField(field_name="parent", state="LOADED");
    aapl_children = LinkField(field_name="children", state="LOADED");
    aapl_parent = LinkField(field_name="parent", state="UNLOADED");
    msft_children = LinkField(field_name="children", state="UNLOADED");
    msft_parent = LinkField(field_name="parent", state="LOADED");
    opts_children = LinkField(field_name="children", state="LOADED");
    opts_parent = LinkField(field_name="parent", state="LOADED");

    nyse +>:HasLinkField:+> nyse_children;
    nyse +>:HasLinkField:+> nyse_parent;
    aapl +>:HasLinkField:+> aapl_children;
    aapl +>:HasLinkField:+> aapl_parent;
    msft +>:HasLinkField:+> msft_children;
    msft +>:HasLinkField:+> msft_parent;
    opts +>:HasLinkField:+> opts_children;
