"""SARA MCP graph-aware retrieval: search requirements, trace upstream/downstream, and analyze impact."""

node Document {
    has doc_id: str = "";
    has title: str = "";
    has summary: str = "";
    has keywords: str = "";
}

node Requirement(Document) {
    has status: str = "active";
}

node Specification(Document) {
    has version: str = "1.0";
}

edge DependsOn { }

edge Specifies { }

walker SearchAgent {
    has query: str = "";
    has hits: list[str] = [];

    def matches(doc: Document) -> bool {
        needle = self.query.lower();
        in_title = needle in doc.title.lower();
        in_keys = needle in doc.keywords.lower();
        in_summary = needle in doc.summary.lower();
        return in_title or in_keys or in_summary;
    }

    can start with Root entry {
        print(f"[search] query={self.query!r}");
        visit [-->];
        print(f"[search] matched_ids={self.hits}");
        disengage;
    }

    can scan with Requirement | Specification entry {
        if self.matches(here) {
            self.hits.append(here.doc_id);
            print(f"  hit {here.doc_id}: {here.title}");
        }
        visit [-->];
    }
}

walker TraceAgent {
    has direction: str = "both";
    has visited: list[str] = [];
    has depth: int = 0;
    has max_depth: int = 5;

    def seen(doc_id: str) -> bool {
        for marker in self.visited {
            if marker == doc_id {
                return True;
            }
        }
        return False;
    }

    def walk_step() {
        if self.seen(here.doc_id) {
            disengage;
        }
        self.visited.append(here.doc_id);
        tag = "graph";
        if self.direction == "upstream" {
            tag = "upstream";
        } else {
            if self.direction == "downstream" {
                tag = "downstream";
            }
        }
        print(f"  [{tag}] {here.doc_id}: {here.title} — {here.summary}");
        if self.depth >= self.max_depth {
            disengage;
        }
        self.depth += 1;
        if self.direction == "upstream" {
            visit [<--:DependsOn:--] else { };
            visit [<--:Specifies:--] else { };
        } else {
            if self.direction == "downstream" {
                visit [->:DependsOn:->] else { };
                visit [->:Specifies:->] else { };
            } else {
                visit [<--:DependsOn:--] else { };
                visit [<--:Specifies:--] else { };
                visit [->:DependsOn:->] else { };
                visit [->:Specifies:->] else { };
            }
        }
        self.depth -= 1;
        disengage;
    }

    can start with Requirement | Specification entry {
        self.walk_step();
    }

    can traverse with Requirement | Specification entry {
        self.walk_step();
    }
}

walker ImpactAnalyzer {
    has affected: list[str] = [];
    has visited: list[str] = [];

    def seen(doc_id: str) -> bool {
        for marker in self.visited {
            if marker == doc_id {
                return True;
            }
        }
        return False;
    }

    can start with Requirement | Specification entry {
        print(f"[impact] change at {here.doc_id}: {here.title}");
        visit [->:DependsOn:->] else { };
        visit [->:Specifies:->] else { };
        disengage;
    }

    can ripple with Requirement | Specification entry {
        if self.seen(here.doc_id) {
            disengage;
        }
        self.visited.append(here.doc_id);
        self.affected.append(here.doc_id);
        print(f"  [affected] {here.doc_id}: {here.title}");
        visit [->:DependsOn:->] else { };
        visit [->:Specifies:->] else { };
        disengage;
    }
}

with entry {
    core = Requirement(
        doc_id="REQ-CORE",
        title="Core Platform",
        summary="Shared runtime and configuration kernel.",
        keywords="platform core foundation"
    );
    auth = Requirement(
