    can follow_env with StoredLambda entry {
        lid = here.lambda_id;
        if self.seen(lid) {
            disengage;
        }
        self.mark_seen(lid);
        self.record_id(lid);
        visit [->:SelfRec:->] else {
            disengage;
        };
    }
}

walker ScopePopper {
