"""Go types2 mono.go: type-parameter instantiation graph with Tarjan SCC and positive InstRef cycle detection."""

node TypeParam {
    has name: str = "";
    has disc: int = 0;
    has low: int = 0;
    has on_stack: bool = False;
    has scc: int = -1;
    has active: bool = True;
}

edge InstRef {
    has positive: bool = True;
}

walker TarjanMono {
    has clock: int = 0;
    has scc_next: int = 0;
    has stack: list[str] = [];
    has registry: dict[str, TypeParam] = {};
    has parent: str = "";

    can start with Root entry {
        visit [-->[?:TypeParam]] else { disengage; };
    }

    can connect with TypeParam entry {
        if here.disc > 0 {
            if here.on_stack && self.parent != "" {
                par = self.registry[self.parent];
                if here.disc < par.low {
                    par.low = here.disc;
                }
            }
            if self.parent != "" {
                disengage;
            } else {
                visit [-->[?:TypeParam]] else { disengage; };
            }
            return;
        }
        self.clock += 1;
        here.disc = self.clock;
        here.low = self.clock;
        here.on_stack = True;
        self.stack.append(here.name);
        prev_parent = self.parent;
        self.parent = here.name;
        visit [->:InstRef:->] else { };
        self.parent = prev_parent;
        if here.low == here.disc {
            self.scc_next += 1;
            while len(self.stack) > 0 {
                popped = self.stack.pop();
                tp = self.registry[popped];
                tp.scc = self.scc_next;
                tp.on_stack = False;
                if popped == here.name {
                    break;
                }
            }
        }
        visit [-->[?:TypeParam]] else { disengage; };
    }
}

walker PosCycleReporter {
    has registry: dict[str, TypeParam] = {};
    has src_name: str = "";
    has mode: str = "scan";
    has findings: list[str] = [];

    can start with Root entry {
        visit [-->[?:TypeParam]] else { disengage; };
    }

    can scan with TypeParam entry {
        if self.mode == "target" {
            src = self.registry[self.src_name];
            if src.scc == here.scc && src.scc > 0 {
                msg = f"positive InstRef in SCC {src.scc}: {src.name} -> {here.name}";
                self.findings.append(msg);
            }
            self.mode = "scan";
            disengage;
        }
        self.src_name = here.name;
        self.mode = "target";
        visit [->:InstRef(positive=True):->] else {
            self.mode = "scan";
            visit [-->];
        };
    }
}

with entry {
    t0 = TypeParam(name="T0");
    t1 = TypeParam(name="T1");
    s1 = TypeParam(name="S1");
    s2 = TypeParam(name="S2");
    s3 = TypeParam(name="S3");
    root ++> t0;
    root ++> t1;
    root ++> s1 ++> s2 ++> s3;
    t0 +>:InstRef(positive=True):+> t1;
    t1 +>:InstRef(positive=True):+> t0;
    s1 +>:InstRef(positive=True):+> s2;
    s2 +>:InstRef(positive=True):+> s3;
    reg = {
        "T0": t0,
        "T1": t1,
        "S1": s1,
        "S2": s2,
        "S3": s3,
    };
    root spawn TarjanMono(registry=reg);
    rep = PosCycleReporter(registry=reg);
    root spawn rep;
    for msg in rep.findings {
        print(msg);
    }
}

"""Runway linked-record lazy loading: selection-scoped frontier batching with cycle guards."""

node SelectionScope {
    has mode: str = "LAZY";
}

node Exchange {
    has name: str = "";
    has record_id: int = 0;
}

node LinkField {
    has field_name: str = "";
    has state: str = "UNLOADED";
}

edge InSelection { }
edge HasLinkField { }
edge ChildLink { }
edge ParentLink { }

walker LazySelector {
    has rtts: int = 0;
    has identity: list[int] = [];

    def charge(detail: str) {
        self.rtts += 1;
        print(f"RTT {self.rtts}: {detail}");
    }

    def remember_id(rid: int) {
        if rid not in self.identity {
            self.identity.append(rid);
        }
    }

    can start with Root entry {
        print("=== LAZY selection: roots without navigating linked records ===");
        self.charge("select root cohort (scalar paths + raw link ids only)");
        visit [->:InSelection:->] else { disengage; };
    }

    can bind_scope with SelectionScope entry {
        print(f"  effective mode: {here.mode}");
        visit [-->];
    }

    can hydrate_root with Exchange entry {
        self.remember_id(here.record_id);
        print(f"  partial Record {here.name} (id={here.record_id}) - linked fields deferred");
        visit [-->];
    }

    can finish with Root exit {
        print(f"  lazy selector total RTTs: {self.rtts}");
    }
}

walker FieldResolver {
    has rtts: int = 0;
    has identity: list[int] = [];
    has target_field: str = "";
    has anchor_id: int = 0;
    has step: str = "scan";

    def charge(detail: str) {
        self.rtts += 1;
        print(f"RTT {self.rtts}: {detail}");
    }

    def remember_id(rid: int) {
        if rid not in self.identity {
            self.identity.append(rid);
        }
    }

    def mapped(rid: int) -> bool {
        return rid in self.identity;
    }

    can resolve with Exchange entry {
        if self.step == "scan" {
            if self.anchor_id == 0 {
                self.anchor_id = here.record_id;
                self.remember_id(here.record_id);
            }
            visit [->:HasLinkField:->] else { disengage; };
        } else {
            if here.record_id == self.anchor_id {
                if self.target_field == "children" {
                    visit [->:ChildLink:->] else { disengage; };
                } else {
                    visit [->:ParentLink:->] else { disengage; };
                }
            } else {
                if self.mapped(here.record_id) {
                    print(f"    identity-map hit: {here.name} (0 RTT)");
                } else {
                    self.remember_id(here.record_id);
                    print(f"    frontier resolved: {here.name} (id={here.record_id})");
                }
                disengage;
            }
        }
    }

    can scan_field with LinkField entry {
        if here.field_name != self.target_field {
            visit [-->];
        } else {
            if here.state == "LOADED" {
                print(f"  {here.field_name} already LOADED on anchor - 0 RTT");
                disengage;
            }
            if here.state == "FAILED" {
                print(f"  {here.field_name} FAILED - skip resolution");
                disengage;
            }
            here.state = "LOADING";
            self.charge(f"bulk-resolve immediate {here.field_name} frontier (single-flight)");
            here.state = "LOADED";
            self.step = "deliver";
            visit [<--] else { disengage; };
        }
    }

    can finish with Exchange exit {
        print(f"  field resolver RTTs this access: {self.rtts}");
    }
}

walker EagerPrefetch {
    has rtts: int = 0;
    has guard: list[int] = [];

    def charge(detail: str) {
        self.rtts += 1;
        print(f"RTT {self.rtts}: {detail}");
    }

    can start with Root entry {
        print("=== EAGER selection: recursive link prefetch ===");
        self.charge("eager navigate + prefetch all reachable links");
        visit [->:InSelection:->];
        visit [-->];
    }

    can prefetch with Exchange entry {
        if here.record_id in self.guard {
            print(f"  cycle guard: stop at {here.name}");
            disengage;
        }
        self.guard.append(here.record_id);
        print(f"  prefetched: {here.name} (id={here.record_id})");
        visit [->:ChildLink:->];
        visit [->:ParentLink:->] else { disengage; };
    }

    can finish with Root exit {
        print(f"  eager prefetch total RTTs: {self.rtts}");
    }
}

with entry {
    scope = SelectionScope(mode="LAZY");
    root +>:InSelection:+> scope;

    nyse = Exchange(name="NYSE", record_id=1);
    aapl = Exchange(name="AAPL", record_id=2);
    msft = Exchange(name="MSFT", record_id=3);
    opts = Exchange(name="OPTIONS", record_id=4);

    scope ++> nyse ++> aapl;

    nyse_children = LinkField(field_name="children", state="UNLOADED");
    nyse_parent = LinkField(field_name="parent", state="LOADED");
    aapl_children = LinkField(field_name="children", state="LOADED");
    aapl_parent = LinkField(field_name="parent", state="UNLOADED");
    msft_children = LinkField(field_name="children", state="UNLOADED");
    msft_parent = LinkField(field_name="parent", state="LOADED");
    opts_children = LinkField(field_name="children", state="LOADED");
    opts_parent = LinkField(field_name="parent", state="LOADED");

    nyse +>:HasLinkField:+> nyse_children;
    nyse +>:HasLinkField:+> nyse_parent;
    aapl +>:HasLinkField:+> aapl_children;
    aapl +>:HasLinkField:+> aapl_parent;
    msft +>:HasLinkField:+> msft_children;
    msft +>:HasLinkField:+> msft_parent;
    opts +>:HasLinkField:+> opts_children;
    opts +>:HasLinkField:+> opts_parent;

    nyse +>:ChildLink:+> aapl;
    nyse +>:ChildLink:+> msft;
    msft +>:ChildLink:+> opts;
    aapl +>:ParentLink:+> nyse;

    root spawn LazySelector();

    print("");
    print("--- first children access on NYSE (bulk frontier) ---");
    shared_map = [1, 2];
    FieldResolver(identity=shared_map, target_field="children") spawn nyse;

    print("");
