        if here.disc > 0 {
            if here.on_stack && self.parent_name != "" {
                par = self.nodes[self.parent_name];
                if here.disc < par.low {
                    par.low = here.disc;
                }
            }
            disengage;
        }
        self.clock += 1;
        here.disc = self.clock;
        here.low = self.clock;
        here.on_stack = True;
        self.stack.append(here.name);
        saved_parent = self.parent_name;
        self.parent_name = here.name;
        visit [->:PosInstRef:->] else { };
        self.parent_name = saved_parent;
        if here.low == here.disc {
            self.scc_id += 1;
            while len(self.stack) > 0 {
                popped = self.stack.pop();
                n = self.nodes[popped];
                n.scc = self.scc_id;
                n.on_stack = False;
                if popped == here.name {
                    break;
                }
            }
        }
        visit [-->];
    }
}

walker PosCycleFinder {
    has nodes: dict[str, TypeParam] = {};
    has findings: list[str] = [];
    has src_name: str = "";
    has phase: str = "source";

    can start with Root entry {
        visit [-->];
    }

    can work with TypeParam entry {
        if self.phase == "target" {
            src = self.nodes[self.src_name];
            if src.scc == here.scc && src.scc > 0 {
                msg = f"positive PosInstRef in SCC {src.scc}: {src.name} -> {here.name}";
                self.findings.append(msg);
            }
            self.phase = "source";
            disengage;
        }
        self.src_name = here.name;
        self.phase = "target";
        visit [->:PosInstRef:->] else { };
        self.phase = "source";
        visit [-->];
    }
}

with entry {
