    has title: str = "";
    has status: str = "";
    has locality: str = "";
    has assignee: str = "";
    has escalated_from: list[str] = [];
}

edge ReportsTo { }

def states_for(roles: list[str]) -> list[str] {
    allowed: list[str] = [];
    if "GRO" in roles {
        allowed.append("PENDING_L1");
    }
    if "HOD" in roles {
        allowed.append("PENDING_L2");
    }
    return allowed;
}

def in_jurisdiction(locality: str, jurisdictions: list[str]) -> bool {
    return locality in jurisdictions;
}

def queue_match(
    tab: str,
    version: int,
    status: str,
    assignee: str,
    viewer_name: str,
    my_roles: list[str],
    reportee_roles: list[str],
    has_reportees: bool,
    escalated_from: list[str]
) -> bool {
    my_states = states_for(my_roles);
    rep_states = states_for(reportee_roles);
    if version == 1 {
        if tab == "my" {
            return status in my_states;
        }
        if has_reportees {
            return status in rep_states;
        }
        return status in my_states;
    }
    escalated_hit = (viewer_name in escalated_from) and (assignee != viewer_name);
    if tab == "my" {
        return assignee == viewer_name;
    }
    mine_bucket = (status in my_states) and ((assignee == viewer_name) or (assignee == ""));
    if version >= 3 {
        if has_reportees {
            return mine_bucket or (status in rep_states) or escalated_hit;
        }
        return mine_bucket or escalated_hit;
    }
    if has_reportees {
        return mine_bucket or (status in rep_states);
    }
    return mine_bucket;
}

walker ReporteeCollector {
    has max_depth: int = 1;
    has current_depth: int = 0;
    has origin: str = "";
    has roles: list[str] = [];

    can start with Employee entry {
        self.origin = here.name;
        visit [<--:ReportsTo:<--] else { disengage; };
