"""SARA MCP graph-aware retrieval: search requirements, trace upstream/downstream, and analyze impact."""

node Document {
    has doc_id: str = "";
    has title: str = "";
    has summary: str = "";
    has keywords: str = "";

    def get_doc_id() -> str {
        return self.doc_id;
    }

    def get_title() -> str {
        return self.title;
    }

    def get_summary() -> str {
        return self.summary;
    }

    def matches_query(needle: str) -> bool {
        in_title = needle in self.title.lower();
        in_keys = needle in self.keywords.lower();
        in_summary = needle in self.summary.lower();
        return in_title or in_keys or in_summary;
    }
}

node Requirement(Document) {
    has status: str = "active";
}

node Specification(Document) {
    has version: str = "1.0";
}

edge DependsOn { }

edge Specifies { }

walker SearchAgent {
    has query: str = "";
    has hits: list[str] = [];

    can start with Root entry {
        print(f"[search] query={self.query}");
        visit [-->];
        print(f"[search] matched_ids={self.hits}");
        disengage;
    }

    can scan with Requirement | Specification entry {
        needle = self.query.lower();
        if here.matches_query(needle) {
            hit_id = here.get_doc_id();
            self.hits.append(hit_id);
            print(f"  hit {hit_id}: {here.get_title()}");
        }
        visit [-->];
    }
}

walker TraceAgent {
    has direction: str = "both";
    has visited: list[str] = [];
    has depth: int = 0;
    has max_depth: int = 5;

    def seen(doc_id: str) -> bool {
        for marker in self.visited {
            if marker == doc_id {
                return True;
            }
        }
        return False;
    }

    can start with Requirement | Specification entry {
        self.trace_step();
    }

    can traverse with Requirement | Specification entry {
        self.trace_step();
    }

    def trace_step() {
        doc_id = here.get_doc_id();
        if self.seen(doc_id) {
            return;
        }
        self.visited.append(doc_id);
        tag = "graph";
        if self.direction == "upstream" {
            tag = "upstream";
        } else {
            if self.direction == "downstream" {
                tag = "downstream";
            }
        }
        print(f"  [{tag}] {doc_id}: {here.get_title()} — {here.get_summary()}");
        if self.depth >= self.max_depth {
            return;
        }
        self.depth += 1;
        if self.direction == "upstream" {
            visit [<-:DependsOn:<-];
            visit [<-:Specifies:<-];
        } else {
            if self.direction == "downstream" {
                visit [->:DependsOn:->];
                visit [->:Specifies:->];
            } else {
                visit [<-:DependsOn:<-];
                visit [<-:Specifies:<-];
                visit [->:DependsOn:->];
                visit [->:Specifies:->];
            }
        }
        self.depth -= 1;
    }
}

walker ImpactAnalyzer {
    has affected: list[str] = [];
    has visited: list[str] = [];

    def seen(doc_id: str) -> bool {
        for marker in self.visited {
            if marker == doc_id {
                return True;
            }
        }
        return False;
    }

    can start with Requirement | Specification entry {
        print(f"[impact] change at {here.get_doc_id()}: {here.get_title()}");
        visit [->:DependsOn:->];
        visit [->:Specifies:->];
        disengage;
    }

    can ripple with Requirement | Specification entry {
        doc_id = here.get_doc_id();
        if self.seen(doc_id) {
            disengage;
        }
        self.visited.append(doc_id);
        self.affected.append(doc_id);
        print(f"  [affected] {doc_id}: {here.get_title()}");
        visit [->:DependsOn:->];
        visit [->:Specifies:->];
    }
}

with entry {
    core = Requirement(
