"""JSONata letrec redesign: side-table lambda tags, O(n) escape walk on scope exit, and letrec cycles."""

node Scope {
    has name: str = "";
    has depth: int = 0;
}

node StoredLambda {
    has lambda_id: str = "";
    has body_hint: str = "";
    has recursive: bool = False;
}

node LambdaRef {
    has lambda_id: str = "";
}

node LambdaTag(LambdaRef) {
}

node Closure(LambdaRef) {
}

node ValueNode {
    has kind: str = "";
    has node_key: str = "";
}

edge ChildScope { }

edge Binds {
    has var_name: str = "";
}

edge SideTable { }

edge Holds { }

edge Nested { }

edge SelfRec { }

edge EscapedFrom { }

walker EscapeAnalyzer {
    has live_ids: list[str] = [];
    has visited_keys: list[str] = [];

    def seen(key: str) -> bool {
        for k in self.visited_keys {
            if k == key {
                return True;
            }
        }
        return False;
    }

    def mark_seen(key: str) {
        self.visited_keys.append(key);
    }

    def record_id(lambda_id: str) {
        for existing in self.live_ids {
            if existing == lambda_id {
                return;
            }
        }
        self.live_ids.append(lambda_id);
    }

    can start with Root entry {
        visit [-->];
    }

    can pass_scope with Scope entry {
        visit [-->];
    }

    can walk with ValueNode entry {
        key = here.node_key;
        if key != "" {
            if self.seen(key) {
                disengage;
            }
            self.mark_seen(key);
        }
        visit [->:Nested:->];
        visit [->:Holds:->];
    }

    can collect_ref with LambdaTag | Closure entry {
        self.record_id(here.lambda_id);
    }

    can follow_closure with Closure entry {
        visit [->:SelfRec:->];
    }

    can follow_env with StoredLambda entry {
        lid = here.lambda_id;
        if self.seen(lid) {
            disengage;
        }
        self.mark_seen(lid);
        self.record_id(lid);
        visit [->:SelfRec:->] else {
            disengage;
        };
    }
}

walker ScopePopper {
    has preserve_ids: list[str] = [];
    has migrated_ids: list[str] = [];

    def should_preserve(lambda_id: str) -> bool {
        for pid in self.preserve_ids {
            if pid == lambda_id {
                return True;
            }
        }
        return False;
    }

    def mark_migrated(lambda_id: str) {
        for mid in self.migrated_ids {
            if mid == lambda_id {
                return;
            }
        }
        self.migrated_ids.append(lambda_id);
    }

    can start with Root entry {
        visit [-->];
    }

    can on_scope with Scope entry {
        if here.depth == 1 {
            visit [->:SideTable:->];
            visit [<--:ChildScope:--] else {
                disengage;
            };
        } else {
            visit [-->];
        }
    }

    can migrate_lambda with StoredLambda entry {
        if self.should_preserve(here.lambda_id) {
            self.mark_migrated(here.lambda_id);
        }
    }
}

with entry {
    outer = Scope(name="outer", depth=0);
    inner = Scope(name="inner", depth=1);
    root ++> outer;
    outer +>:ChildScope:+> inner;

    side_lam = StoredLambda(
        lambda_id="f1",
        body_hint="function(){ $f() }",
        recursive=True
    );
    inner +>:SideTable:+> side_lam;
    side_lam +>:SelfRec:+> side_lam;

    tag = LambdaTag(lambda_id="f1");
    bind_cell = ValueNode(kind="bind", node_key="bind_f");
    inner +>:Binds(var_name="f"):+> bind_cell;
    bind_cell +>:Holds:+> tag;

    result = ValueNode(kind="array", node_key="escaped_result");
    elem = ValueNode(kind="elem", node_key="elem0");
    inner +>:EscapedFrom:+> result;
    result +>:Nested:+> elem;
    elem +>:Holds:+> tag;

    capt_env = ValueNode(kind="capture_env", node_key="captures");
    letrec_lam = StoredLambda(
        lambda_id="f1_body",
        body_hint="letrec self-call",
        recursive=True
    );
    carried = Closure(lambda_id="f1");
    elem +>:Nested:+> capt_env;
    capt_env +>:Holds:+> carried;
    carried +>:SelfRec:+> letrec_lam;
    letrec_lam +>:SelfRec:+> letrec_lam;

    analyzer = EscapeAnalyzer();
    root spawn analyzer;
    print(f"escape walk live ids: {analyzer.live_ids}");

    popper = ScopePopper(preserve_ids=analyzer.live_ids);
    root spawn popper;
    print(f"scope pop migrated ids: {popper.migrated_ids}");
}

"""Go types2 mono.go: type-parameter instantiation graph with Tarjan SCC and positive PosInstRef cycle detection."""

node TypeParam {
    has name: str = "";
    has disc: int = 0;
    has low: int = 0;
    has on_stack: bool = False;
    has scc: int = -1;
}

edge PosInstRef { }

walker GraphSeeder {
    can start with Root entry {
        visit [-->];
    }

    can touch with TypeParam entry {
        disengage;
    }
}

walker TarjanSCC {
    has clock: int = 0;
    has scc_id: int = 0;
    has stack: list[str] = [];
    has nodes: dict[str, TypeParam] = {};
    has parent_name: str = "";

    can dfs with TypeParam entry {
        if here.disc > 0 {
            if here.on_stack && self.parent_name != "" {
                par = self.nodes[self.parent_name];
                if here.disc < par.low {
                    par.low = here.disc;
                }
            }
            disengage;
        }
        self.clock += 1;
        here.disc = self.clock;
        here.low = self.clock;
        here.on_stack = True;
        self.stack.append(here.name);
        saved_parent = self.parent_name;
        self.parent_name = here.name;
        visit [->:PosInstRef:->] else { };
        self.parent_name = saved_parent;
        if here.low == here.disc {
            self.scc_id += 1;
            while len(self.stack) > 0 {
                popped = self.stack.pop();
                n = self.nodes[popped];
                n.scc = self.scc_id;
                n.on_stack = False;
                if popped == here.name {
                    break;
                }
            }
        }
        disengage;
    }
}

walker PosCycleFinder {
    has nodes: dict[str, TypeParam] = {};
    has findings: list[str] = [];
    has src_name: str = "";

    can check_src with TypeParam entry {
        self.src_name = here.name;
        visit [->:PosInstRef:->] else { disengage; };
    }

    can check_tgt with TypeParam entry {
        src = self.nodes[self.src_name];
        if src.scc == here.scc && src.scc > 0 {
            msg = f"positive PosInstRef in SCC {src.scc}: {src.name} -> {here.name}";
            self.findings.append(msg);
        }
        disengage;
    }
}

with entry {
    t0 = TypeParam(name="T0");
    t1 = TypeParam(name="T1");
    s1 = TypeParam(name="S1");
    s2 = TypeParam(name="S2");
    s3 = TypeParam(name="S3");
    root ++> t0;
    root ++> t1;
    root ++> s1 ++> s2 ++> s3;
    t0 +>:PosInstRef:+> t1;
    t1 +>:PosInstRef:+> t0;
    s1 +>:PosInstRef:+> s2;
    s2 +>:PosInstRef:+> s3;
    names = ["T0", "T1", "S1", "S2", "S3"];
    reg = {
        "T0": t0,
        "T1": t1,
        "S1": s1,
        "S2": s2,
        "S3": s3,
    };
    root spawn GraphSeeder();
    tarjan = TarjanSCC(nodes=reg);
    for nm in names {
        n = reg[nm];
        if n.disc == 0 {
            n spawn tarjan;
        }
    }
    finder = PosCycleFinder(nodes=reg);
    for nm in names {
        reg[nm] spawn finder;
    }
    for msg in finder.findings {
        print(msg);
    }
}

