    can start with Root entry {
        visit [-->];
    }

    can from_super with SuperEntry entry {
        self.reachable.append(here.label);
        visit [->:Control:->] else { disengage; }
    }

    can from_block with FlowBlock entry {
        if here.block_id in self.visited_ids {
            disengage;
        }
        self.visited_ids.append(here.block_id);
        self.reachable.append(here.name);
        visit [->:Control:->] else { disengage; }
