"""Egeria verifier graph indexes: control vs executable views, reachability, SCC, and dominators."""

node FlowBlock {
    has name: str = "";
    has block_id: int = 0;
}

node SuperEntry {
    has label: str = "";
}

node DataSink {
    has name: str = "";
}

edge FlowControl { has edge_class: str = "control"; }
edge FlowFailure { has edge_class: str = "failure"; }
edge FlowSwitch { has case_label: str = ""; has edge_class: str = "switch"; }
edge FlowData { has edge_class: str = "data"; }

walker ControlOnlyReachability {
    has visited_ids: list[int] = [];
    has reachable: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can from_super with SuperEntry entry {
        self.reachable.append(here.label);
        visit [->:FlowControl:->] else { disengage; }
    }

    can from_block with FlowBlock entry {
        if here.block_id in self.visited_ids {
            disengage;
        }
        self.visited_ids.append(here.block_id);
        self.reachable.append(here.name);
        visit [->:FlowControl:->] else { disengage; }
    }

    can summarize with Root exit {
        print(f"[control-only] reachable: {self.reachable}");
    }
}

walker ExecutableReachability {
    has visited_ids: list[int] = [];
    has reachable: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can from_super with SuperEntry entry {
        self.reachable.append(here.label);
        visit [->:FlowControl:->] else {
            visit [->:FlowFailure:->] else {
                visit [->:FlowSwitch:->] else { disengage; }
            }
        }
    }

    can from_block with FlowBlock entry {
        if here.block_id in self.visited_ids {
            disengage;
        }
        self.visited_ids.append(here.block_id);
        self.reachable.append(here.name);
        visit [->:FlowControl:->] else {
            visit [->:FlowFailure:->] else {
                visit [->:FlowSwitch:->] else { disengage; }
            }
        }
    }

    can summarize with Root exit {
        print(f"[executable] reachable: {self.reachable}");
    }
}

walker StronglyConnectedScan {
    has stack_ids: list[int] = [];
    has finished_ids: list[int] = [];
    has components: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can from_super with SuperEntry entry {
        visit [->:FlowControl:->] else {
            visit [->:FlowFailure:->] else {
                visit [->:FlowSwitch:->] else { disengage; }
            }
        }
    }

    can probe with FlowBlock entry {
        bid = here.block_id;
        if bid in self.stack_ids {
            note = f"back-edge into {here.name} (failure-cycle class)";
            self.components.append(note);
        }
        if bid in self.finished_ids {
            disengage;
        }
        self.stack_ids.append(bid);
        visit [->:FlowControl:->] else {
            visit [->:FlowFailure:->] else {
                visit [->:FlowSwitch:->] else { disengage; }
            }
        }
        trimmed = [];
        for sid in self.stack_ids {
            if sid != bid {
                trimmed.append(sid);
            }
        }
        self.stack_ids = trimmed;
        self.finished_ids.append(bid);
    }

    can summarize with Root exit {
        if self.components {
            print(f"[SCC] components flagged: {self.components}");
        } else {
            print("[SCC] acyclic on scanned executable subgraph");
        }
    }
}

walker DominatorWalk {
    has chain: list[str] = [];

    can start with SuperEntry entry {
        idom = "(synthetic super-root)";
        print(f"[dominators] {here.label} idom={idom}");
        visit [->:FlowControl:->] else { disengage; }
    }

    can descend with FlowBlock entry {
        idom = "(super)";
        if self.chain {
            idom = self.chain[len(self.chain) - 1];
        }
        print(f"[dominators] {here.name} idom={idom}");
        self.chain.append(here.name);
        visit [->:FlowControl:->] else {
            visit [->:FlowSwitch:->] else { disengage; }
        }
        trimmed = [];
        for (i, n) in enumerate(self.chain) {
            if i < len(self.chain) - 1 {
                trimmed.append(n);
            }
        }
        self.chain = trimmed;
    }
}

walker AnalysisContext {
    has indexes_ready: bool = False;

    can prime with Root entry {
        if self.indexes_ready {
            print("[AnalysisContext] reusing cached graph indexes");
            disengage;
        }
        self.indexes_ready = True;
        print("[AnalysisContext] building shared control, executable, and data views");
        visit [-->];
    }

    can touch_super with SuperEntry entry {
        visit [->:FlowControl:->] else { disengage; }
    }

    can touch_block with FlowBlock entry {
        visit [->:FlowControl:->] else {
            visit [->:FlowFailure:->] else {
                visit [->:FlowSwitch:->] else { disengage; }
            }
        }
    }

    can touch_data with DataSink entry {
        print(f"[data-only] sink indexed: {here.name}");
        disengage;
    }
}

with entry {
