    left = FlowBlock(name="left_arm", block_id=4);
    right = FlowBlock(name="right_arm", block_id=5);
    join = FlowBlock(name="merge", block_id=6);
    done = FlowBlock(name="end", block_id=7);
    retry = FlowBlock(name="retry_head", block_id=10);
