"""Dependency tree: global expanded-set elision vs per-path expansion for shared subtrees."""

node Package {
    has name: str = "";
    has version: str = "0.0.0";
}

edge DependsOn { }

walker GlobalExpandedTree {
    has expanded: list[str] = [];
    has depth: int = 0;

    def indent_line(label: str) -> None {
        pad = "";
        for _ in range(self.depth) {
            pad += "  ";
        }
        print(f"{pad}{label}");
    }

    can start with Root entry {
        visit [-->];
    }

    can show with Package entry {
        if here.name in self.expanded {
            self.indent_line(f"{here.name}");
            disengage;
        }
        self.indent_line(f"{here.name}@{here.version}");
        self.expanded.append(here.name);
        self.depth += 1;
        visit [->:DependsOn:->] else {
            # no dependencies
        }
        self.depth -= 1;
        disengage;
    }
}

walker PerPathTree {
    has path: list[str] = [];

    def indent_line(label: str) -> None {
        pad = "";
        for _ in range(len(self.path)) {
            pad += "  ";
        }
        print(f"{pad}{label}");
    }

    can start with Root entry {
        visit [-->];
    }

    can show with Package entry {
        if here.name in self.path {
            self.indent_line(f"{here.name} [cycle]");
            disengage;
        }
        self.indent_line(f"{here.name}@{here.version}");
        self.path.append(here.name);
        visit [->:DependsOn:->] else {
            # no dependencies
        }
        self.path.pop();
        disengage;
    }
}

walker MarkedCompactTree {
    has shown: list[str] = [];
    has path: list[str] = [];

    def indent_line(label: str) -> None {
        pad = "";
        for _ in range(len(self.path)) {
            pad += "  ";
        }
        print(f"{pad}{label}");
    }

    can start with Root entry {
        visit [-->];
    }

    can show with Package entry {
        if here.name in self.path {
            self.indent_line(f"{here.name} [cycle]");
            disengage;
        }
        if here.name in self.shown {
            self.indent_line(f"{here.name} (already_shown)");
            disengage;
        }
        self.indent_line(f"{here.name}@{here.version}");
        self.shown.append(here.name);
        self.path.append(here.name);
        visit [->:DependsOn:->] else {
            # no dependencies
        }
        self.path.pop();
        disengage;
    }
}

with entry {
    app = Package(name="myapp", version="1.0.0");
    lib_a = Package(name="lib_a", version="0.1.0");
    lib_b = Package(name="lib_b", version="0.2.0");
