"""NeuroHarness Issue #11: ticket dependency ordering and harness control workflows."""

node HarnessTicket {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has ticket_id: int = 0;
    has complete: bool = False;
}

node HarnessAction {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has kind: str = "";
    has duration_ms: int = 0;
}

node ControlStrategy {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has strategy_name: str = "";
    has success: bool = False;
    has ttv_ms: int = 0;
    has action_count: int = 0;
}

edge DependsOn { }
edge Precedes { }
edge UsesStrategy { }

walker DependencyAuditor {
    has order: list[str] = [];
    has seen: list[int] = [];
    has cycle_found: bool = False;

    can start with Root entry {
        visit [->:DependsOn:->];
    }

    can audit with HarnessTicket entry {
        if here.ticket_id in self.seen {
            self.cycle_found = True;
            print(f"[CYCLE] ticket #{here.ticket_id} revisited");
            disengage;
        }
        self.seen.append(here.ticket_id);
        if not here.complete {
            self.order.append(f"#{here.ticket_id}:{here.title}");
        }
        visit [->:DependsOn:->] else {
            disengage;
        }
    }
}

walker WorkflowRunner {
    has strategy_label: str = "";
    has elapsed_ms: int = 0;
    has steps_taken: int = 0;
    has verified: bool = False;

    can start with Root entry {
        visit [->:UsesStrategy:->];
    }

    can bind with ControlStrategy entry {
        self.strategy_label = here.strategy_name;
        print(f"[{self.strategy_label}] starting harness workflow");
        visit [->:Precedes:->];
    }

    can execute with HarnessAction entry {
        if not here.available {
            print(f"  skip {here.kind} (unavailable)");
            visit [->:Precedes:->] else {
                disengage;
            }
        } else {
            self.elapsed_ms += here.duration_ms;
            self.steps_taken += 1;
            print(f"  {here.kind} (+{here.duration_ms}ms)");
            if here.kind == "VERIFY" {
                self.verified = True;
            }
            visit [->:Precedes:->] else {
                disengage;
            }
        }
    }

    can finish with ControlStrategy exit {
        here.ttv_ms = self.elapsed_ms;
        here.action_count = self.steps_taken;
        here.success = self.verified;
        outcome = "PASS" if self.verified else "FAIL";
        print(f"[{self.strategy_label}] {outcome} ttv={self.elapsed_ms}ms actions={self.steps_taken}");
    }
}

walker ExperimentComparator {
    has results: list[str] = [];

    can start with Root entry {
        visit [-->[?:ControlStrategy]];
    }

    can score with ControlStrategy entry {
        label = f"{here.strategy_name}:ttv={here.ttv_ms}:actions={here.action_count}";
        verdict = "verified" if here.success else "failed";
        row = f"{label}:{verdict}";
        self.results.append(row);
        print(f"[METRIC] {row}");
        visit [-->[?:ControlStrategy]] else {
            disengage;
        }
    }
}

with entry {
