"""Fast-sync SHAMap: fixed root lanes vs dynamic frontier scheduling on skewed branches."""

node TraversalNode {
    has label: str = "";
    has work_units: int = 1;
    has depth: int = 0;
    has missing: bool = False;
}

node ShamapBranch(TraversalNode) {
    has branch_idx: int = 0;
}

node ShamapLeaf(TraversalNode) {
    has node_id: str = "";
}

node SyncPivot {
    has ledger: int = 20286288;
    has worker_pool: int = 8;
    has max_missing: int = 64;
}

edge RootLane { has lane_id: int = 0; }
edge Descends { }

walker FixedLaneScheduler {
    has pool_size: int = 8;
    has open_lanes: int = 0;
    has peak_active: int = 0;
    has tail_active: int = 0;
    has missing_found: int = 0;
    has work_done: int = 0;
    has lanes_finished: int = 0;
    has root_lane_count: int = 0;

    can start with SyncPivot entry {
        self.pool_size = here.worker_pool;
        print(f"[fixed-lanes] pivot={here.ledger} pool={self.pool_size}");
        visit [->:RootLane:->] else { disengage; }
        idle = self.pool_size - self.tail_active;
        print(f"[fixed-lanes] root_lanes={self.root_lane_count} peak_active={self.peak_active} "
              f"tail_active={self.tail_active} idle_at_tail={idle} "
              f"missing={self.missing_found} work={self.work_done}");
        disengage;
    }

    can open_lane with ShamapBranch entry {
        self.root_lane_count += 1;
        self.open_lanes += 1;
        if self.open_lanes > self.peak_active {
            self.peak_active = self.open_lanes;
        }
        self.tail_active = self.open_lanes;
        self.work_done += here.work_units;
        if here.missing {
            self.missing_found += 1;
        }
        visit [->:Descends:->] else {
            self.open_lanes -= 1;
            self.lanes_finished += 1;
            self.tail_active = self.open_lanes if self.open_lanes > 0 else 1;
            disengage;
        }
    }

    can walk_descendant with ShamapBranch | ShamapLeaf entry {
        self.work_done += here.work_units;
        if here.missing {
            self.missing_found += 1;
        }
        visit [->:Descends:->] else {
            disengage;
        }
    }
}

walker DynamicFrontierScheduler {
    has pool_size: int = 8;
    has frontier: list[int] = [];
    has peak_active: int = 0;
    has tail_active: int = 0;
    has missing_found: int = 0;
    has work_done: int = 0;
    has splits: int = 0;
    has chunk_size: int = 3;

    can start with SyncPivot entry {
        self.pool_size = here.worker_pool;
        print(f"[dynamic-frontier] pivot={here.ledger} pool={self.pool_size}");
        visit [->:RootLane:->] else { disengage; }
        idle = self.pool_size - self.tail_active;
        print(f"[dynamic-frontier] splits={self.splits} peak_active={self.peak_active} "
              f"tail_active={self.tail_active} idle_at_tail={idle} "
              f"missing={self.missing_found} work={self.work_done}");
        disengage;
    }

    can enqueue_branch with ShamapBranch entry {
        units = here.work_units;
        while units > 0 {
            take = self.chunk_size if units > self.chunk_size else units;
            self.frontier.append(take);
            units -= take;
            if units > 0 {
                self.splits += 1;
            }
        }
        self._drain_frontier();
        visit [->:Descends:->] else { disengage; }
    }

    can collect_leaf with ShamapLeaf entry {
        self.frontier.append(here.work_units);
        self._drain_frontier();
        if here.missing {
            self.missing_found += 1;
        }
        visit [->:Descends:->] else { disengage; }
    }

    def _drain_frontier() {
        active = len(self.frontier) if len(self.frontier) < self.pool_size else self.pool_size;
        if active > self.peak_active {
            self.peak_active = active;
        }
        self.tail_active = active if active > 0 else 0;
        drained = 0;
        for chunk in self.frontier {
            self.work_done += chunk;
            drained += 1;
            if drained >= self.pool_size {
                break;
            }
        }
        if drained >= len(self.frontier) {
            self.frontier = [];
        } else {
            self.frontier = self.frontier[drained:];
            self.tail_active = len(self.frontier) if len(self.frontier) < self.pool_size else self.pool_size;
        }
    }
}

with entry {
    pivot = SyncPivot(ledger=20286288, worker_pool=8);

    heavy = ShamapBranch(label="branch-0-skewed", branch_idx=0, work_units=18, depth=1);
    slim_a = ShamapBranch(label="branch-1", branch_idx=1, work_units=2, depth=1);
    slim_b = ShamapBranch(label="branch-2", branch_idx=2, work_units=2, depth=1);
    slim_c = ShamapBranch(label="branch-3", branch_idx=3, work_units=2, depth=1);

    pivot +>:RootLane(lane_id=0):+> heavy;
    pivot +>:RootLane(lane_id=1):+> slim_a;
    pivot +>:RootLane(lane_id=2):+> slim_b;
    pivot +>:RootLane(lane_id=3):+> slim_c;

    heavy +>:Descends:+> ShamapLeaf(node_id="0:aa", work_units=2, depth=2, missing=True);
    heavy +>:Descends:+> ShamapLeaf(node_id="0:ab", work_units=2, depth=2);
    heavy +>:Descends:+> ShamapLeaf(node_id="0:ac", work_units=2, depth=2, missing=True);
    heavy +>:Descends:+> ShamapLeaf(node_id="0:ad", work_units=2, depth=2);

    slim_a +>:Descends:+> ShamapLeaf(node_id="1:aa", work_units=2, depth=2);
    slim_b +>:Descends:+> ShamapLeaf(node_id="2:aa", work_units=2, depth=2, missing=True);
    slim_c +>:Descends:+> ShamapLeaf(node_id="3:aa", work_units=2, depth=2);

    root ++> pivot;

    root spawn FixedLaneScheduler();
    root spawn DynamicFrontierScheduler();
}

"""ECC Pi session-start hooks: resolve a real Node runtime to stop recursive OMP spawn chains."""

edge Hosts { }
edge Triggers { }
edge Respawns { has reason: str = "session_start"; }

node HostRuntime {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has exec_path: str = "";
    has release_name: str = "node";
    has bun_version: str = "";
    has hook_node_override: str = "";
    has use_exec_path_naively: bool = False;

    def is_node_runtime() -> bool {
        if self.release_name != "node" {
            return False;
        }
        if self.bun_version != "" {
            return False;
        }
        if self.exec_path.endswith("/node")
            or self.exec_path.endswith("/nodejs")
            or self.exec_path.endswith("/node.exe")
            or self.exec_path.endswith("/nodejs.exe")
            or self.exec_path == "node"
            or self.exec_path == "nodejs" {
            return True;
        }
        return False;
    }

    def resolve_hook_runtime() -> str {
        if self.hook_node_override != "" {
            return self.hook_node_override;
        }
        if self.is_node_runtime() {
            return self.exec_path;
        }
        return "node";
    }

    def pick_runtime() -> str {
        if self.use_exec_path_naively {
            return self.exec_path;
        }
        return self.resolve_hook_runtime();
    }
}

node HookSpec {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has hook_id: str = "session:start";
    has script: str = "run-with-flags.js";
    has profiles: str = "minimal,standard,strict";
}

walker SessionStartExecutor {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has max_depth: int = 6;
    has seen: list[str] = [];
    has launches: int = 0;
    has current_runtime: str = "";

    can start with Root entry {
        visit [->:Hosts:->] else { disengage; };
    }

    can on_host with HostRuntime entry {
        self.current_runtime = here.pick_runtime();
        mode = "naive-execPath" if here.use_exec_path_naively else "guarded-runtime";
        print(f"[{mode}] host={here.title} interpreter={self.current_runtime}");
        visit [->:Triggers:->] else { disengage; };
    }

    can execute with HookSpec entry {
        sig = f"{self.current_runtime}:{here.hook_id}";
        if sig in self.seen {
            print(f"  [CYCLE] {sig} re-entered after {self.launches} launches; disengaging");
            disengage;
        }
        self.seen.append(sig);
        self.launches += 1;
        print(
            f"  launch {self.launches}: {self.current_runtime} "
            f"{here.script} {here.profiles}"
        );
        is_omp_interp = (
            self.current_runtime.endswith("/omp")
            or self.current_runtime.endswith("/omp.exe")
            or self.current_runtime == "omp"
        );
        if is_omp_interp {
            if self.launches >= self.max_depth {
                print(f"  [TIMEOUT] handler timed out after 30000ms at depth {self.launches}");
                disengage;
            }
            visit [->:Respawns:->] else { disengage; };
        } else {
            print(f"  [OK] hook completed once under {self.current_runtime}");
            disengage;
        }
    }
}

