"""Message subtree: one walker pass fetches nested replies with depth cap (CTE-style), avoiding n+1 queries."""

node Message {
    has message_id: str = "";
    has body: str = "";
    has sent_at: str = "";
    has author: str = "";
}

edge HasReply { }

walker SubtreeFetcher {
    has max_depth: int = 3;
    has depth: int = 0;
    has rows: list[str] = [];
    has seen_ids: list[str] = [];

    can collect with Message entry {
        if here.message_id in self.seen_ids {
            return;
        }
        self.seen_ids.append(here.message_id);
        self.rows.append(
            f"depth={self.depth} sent_at={here.sent_at} id={here.message_id} author={here.author} body={here.body}"
        );
        child_depth = self.depth + 1;
        if child_depth <= self.max_depth {
            saved_depth = self.depth;
            self.depth = child_depth;
            visit [->:HasReply:->] else { };
            self.depth = saved_depth;
        }
    }
}

walker ThreadRenderer {
    has depth: int = 0;

    can render with Message entry {
        indent = "";
        for _ in range(self.depth) {
            indent += "  ";
        }
        print(f"{indent}└─ [{here.author}] {here.body} ({here.sent_at})");
        next_depth = self.depth + 1;
        saved_depth = self.depth;
        self.depth = next_depth;
        visit [->:HasReply:->] else { };
        self.depth = saved_depth;
    }
}

