"""Fast-sync SHAMap: fixed root lanes vs dynamic frontier scheduling on skewed branches."""

node SyncPivot {
    has ledger: int = 20286288;
    has worker_pool: int = 8;
    has max_missing: int = 64;
}

node ShamapBranch {
    has label: str = "";
    has branch_idx: int = 0;
    has work_units: int = 1;
    has depth: int = 0;
    has missing: bool = False;
}

node ShamapLeaf {
    has node_id: str = "";
    has work_units: int = 1;
    has depth: int = 0;
    has missing: bool = False;
}

edge RootLane {
    has lane_id: int = 0;
}

edge Descends { }

walker FixedLaneScheduler {
    has pool_size: int = 8;
    has open_lanes: int = 0;
    has peak_active: int = 0;
    has tail_active: int = 0;
    has missing_found: int = 0;
    has work_done: int = 0;
    has root_lane_count: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can schedule with SyncPivot entry {
        self.pool_size = here.worker_pool;
        print(f"[fixed-lanes] pivot={here.ledger} pool={self.pool_size}");
        visit [->:RootLane:->] else { disengage; }
        idle = self.pool_size - self.tail_active;
        print(f"[fixed-lanes] root_lanes={self.root_lane_count} peak_active={self.peak_active} "
              f"tail_active={self.tail_active} idle_at_tail={idle} "
              f"missing={self.missing_found} work={self.work_done}");
        disengage;
    }

    can open_lane with ShamapBranch entry {
        self.root_lane_count += 1;
        self.open_lanes += 1;
        if self.open_lanes > self.peak_active {
            self.peak_active = self.open_lanes;
        }
        self.tail_active = self.open_lanes;
        self.work_done += here.work_units;
        if here.missing {
            self.missing_found += 1;
        }
        visit [->:Descends:->] else {
            self.open_lanes -= 1;
            active = self.open_lanes if self.open_lanes > 0 else 0;
            self.tail_active = active;
            disengage;
        }
    }

    can walk_leaf with ShamapLeaf entry {
        self.work_done += here.work_units;
        if here.missing {
            self.missing_found += 1;
        }
        visit [->:Descends:->] else { disengage; }
    }
}

walker DynamicFrontierScheduler {
    has pool_size: int = 8;
    has pending_tasks: int = 0;
    has peak_active: int = 0;
    has tail_active: int = 0;
    has missing_found: int = 0;
    has work_done: int = 0;
    has splits: int = 0;
    has chunk_size: int = 3;

    can start with Root entry {
        visit [-->];
    }

    can schedule with SyncPivot entry {
        self.pool_size = here.worker_pool;
        print(f"[dynamic-frontier] pivot={here.ledger} pool={self.pool_size}");
        visit [->:RootLane:->] else { disengage; }
        idle = self.pool_size - self.tail_active;
        print(f"[dynamic-frontier] splits={self.splits} peak_active={self.peak_active} "
              f"tail_active={self.tail_active} idle_at_tail={idle} "
              f"missing={self.missing_found} work={self.work_done}");
        disengage;
    }

    can enqueue_branch with ShamapBranch entry {
        remaining = here.work_units;
        while remaining > 0 {
            take = self.chunk_size if remaining > self.chunk_size else remaining;
            self.pending_tasks += 1;
            self.work_done += take;
            self._update_active();
            self.pending_tasks -= 1;
            remaining -= take;
            if remaining > 0 {
                self.splits += 1;
            }
        }
        visit [->:Descends:->] else { disengage; }
    }

    can collect_leaf with ShamapLeaf entry {
        self.pending_tasks += 1;
        self.work_done += here.work_units;
        if here.missing {
            self.missing_found += 1;
        }
        self._update_active();
        self.pending_tasks -= 1;
        visit [->:Descends:->] else { disengage; }
    }

    def _update_active() {
        active = self.pending_tasks;
        if active > self.pool_size {
            active = self.pool_size;
        }
        if active > self.peak_active {
            self.peak_active = active;
        }
        self.tail_active = active;
    }
}

