    slim_b = ShamapBranch(label="branch-2", branch_idx=2, work_units=2, depth=1);
    slim_c = ShamapBranch(label="branch-3", branch_idx=3, work_units=2, depth=1);

    pivot +>:RootLane(lane_id=0):+> heavy;
    pivot +>:RootLane(lane_id=1):+> slim_a;
    pivot +>:RootLane(lane_id=2):+> slim_b;
    pivot +>:RootLane(lane_id=3):+> slim_c;

    heavy +>:Descends:+> ShamapLeaf(node_id="0:aa", work_units=2, depth=2, missing=True);
    heavy +>:Descends:+> ShamapLeaf(node_id="0:ab", work_units=2, depth=2);
    heavy +>:Descends:+> ShamapLeaf(node_id="0:ac", work_units=2, depth=2, missing=True);
    heavy +>:Descends:+> ShamapLeaf(node_id="0:ad", work_units=2, depth=2);

    slim_a +>:Descends:+> ShamapLeaf(node_id="1:aa", work_units=2, depth=2);
