    slim_c +>:Descends:+> ShamapLeaf(node_id="3:aa", work_units=2, depth=2);

    root ++> pivot;

    root spawn FixedLaneScheduler();
    root spawn DynamicFrontierScheduler();
}

"""Git pack delta: bounded OFS/REF dependency resolution with cycle detection."""

node PackObject {
    has object_id: str = "";
    has entry_offset: int = 0;
    has result_size: int = 0;
    has reconstructed: bool = False;

    def kind_label() -> str {
        return "PACK";
    }

    def base_hint() -> str {
        return "";
    }
}

node StoredObject(PackObject) {
    has content: str = "";

    override def kind_label() -> str {
        return "STORED";
    }

    override def base_hint() -> str {
        return self.content;
    }
}

node OfsDelta(PackObject) {
    has backward_offset: int = 0;

    override def kind_label() -> str {
        return "OFS_DELTA";
    }

    override def base_hint() -> str {
        return f"offset -{self.backward_offset}";
    }
}

node RefDelta(PackObject) {
    has ref_id: str = "";

    override def kind_label() -> str {
        return "REF_DELTA";
    }

    override def base_hint() -> str {
        return f"ref {self.ref_id}";
    }
}

edge DependsOn { }

walker DeltaResolver {
    has max_depth: int = 6;
    has max_lookups: int = 20;
    has depth: int = 0;
    has peak_depth: int = 0;
    has lookups: int = 0;
    has stack: list[str] = [];

    can start with Root entry {
        print("Pack delta resolver: bounded OFS/REF dependency walk");
        visit [-->] else { disengage; }
        print(f"Finished — {self.lookups} lookups, peak depth {self.peak_depth}");
    }

    can resolve with OfsDelta | RefDelta entry {
        if self.lookups >= self.max_lookups {
            print(f"[BUDGET] lookup cap at {here.object_id}");
            disengage;
        }
        if self.depth >= self.max_depth {
            print(f"[BUDGET] depth cap at {here.object_id}");
            disengage;
        }
        if here.object_id in self.stack {
            print(f"[CYCLE] {here.object_id} already on resolution stack");
            disengage;
        }
        self.stack.append(here.object_id);
        self.depth += 1;
        new_peak = self.depth if self.depth > self.peak_depth else self.peak_depth;
        self.peak_depth = new_peak;
        self.lookups += 1;
        print(f"[{here.kind_label()}] {here.object_id} ({here.base_hint()})");
        visit [->:DependsOn:->] else {
            print(f"[MISSING] no base for {here.object_id}");
            disengage;
        };
        here.reconstructed = True;
        print(f"[RECON] {here.object_id} -> {here.result_size} bytes");
        self.stack.pop();
        self.depth -= 1;
        visit [-->] else { disengage; }
    }

    can walk with StoredObject entry {
        if self.depth > 0 {
            self.lookups += 1;
            tag = "memo" if here.reconstructed else "base";
            if not here.reconstructed {
                here.reconstructed = True;
                print(f"  [{tag}] {here.object_id} ({here.result_size}B): {here.content}");
            } else {
                print(f"  [{tag}] {here.object_id} ({here.result_size}B)");
            }
        } else {
            visit [-->] else { disengage; };
        }
    }
}

