"""Schema apply: multi-COT cross-references, topological ordering, and a re-entrancy guard preventing get_models RecursionError."""

node CustomObjectType {
    has name: str = "";
    has slug: str = "";
    has model_built: bool = False;
    has on_stack: bool = False;
    has sorted: bool = False;
}

node ObjectField {
    has field_name: str = "";
    has related_slug: str = "";
}

node SchemaRegistry {
    has generating: bool = False;
    has models_built: int = 0;
    has reentry_blocked: int = 0;

    def try_enter() -> bool {
        if self.generating {
            self.reentry_blocked += 1;
            return False;
        }
        self.generating = True;
        return True;
    }

    def leave() {
        self.generating = False;
    }

    def mark_built() {
        self.models_built += 1;
    }

    def simulate_get_for_model() {
        if self.generating {
            self.reentry_blocked += 1;
            print("    [GUARD] get_models re-entry blocked (_after_model_generation path)");
        }
    }
}

edge HasField { }
edge DependsOn { }
edge References { has target_slug: str = ""; }

walker TopologicalApply {
    has registry: SchemaRegistry;
    has apply_count: int = 0;
    has cycle_found: bool = False;

    can start with Root entry {
        print("Schema apply: topological ordering for cross-referencing COTs");
        visit [-->[?:CustomObjectType]];
    }

    can order with CustomObjectType entry {
        if here.on_stack {
            self.cycle_found = True;
            print(f"  [CYCLE] CircularDependencyError at {here.slug}");
            disengage;
        }
        if here.sorted {
            disengage;
        }
        here.on_stack = True;
        visit [->:DependsOn:->] else { }
        here.on_stack = False;
        here.sorted = True;
        print(f"  apply order: {here.slug}");
        here spawn ModelBuilder(registry=self.registry);
        self.apply_count += 1;
        visit [-->];
    }
}

walker ModelBuilder {
    has registry: SchemaRegistry;

    can generate with CustomObjectType entry {
        if not self.registry.try_enter() {
            print(f"  [GUARD] blocked top-level re-entry for {here.slug}");
            disengage;
        }
        print(f"  get_model({here.slug})");
        visit [->:HasField:->];
        self.registry.simulate_get_for_model();
        here.model_built = True;
        self.registry.mark_built();
        self.registry.leave();
        status = "ok" if here.model_built else "fail";
        print(f"  model {status}: {here.slug}");
    }

    can inspect_field with ObjectField entry {
        label = here.related_slug if here.related_slug else "(primary)";
        print(f"    field {here.field_name} [{label}]");
        visit [->:References:->] else { disengage; }
    }
}

