"""Trail Blazer: walk an unbounded degree-2 string and slam the first hub."""

node TrailSegment {
    has name: str = "";
    has damage_taken: int = 0;
}

node TrailHub {
    has name: str = "";
    has damage_taken: int = 0;
    has arity: int = 3;
}

node BranchStub {
    has name: str = "";
}

edge TrailLink { }
edge BranchArm { }

walker TrailBlazer {
    has hop_count: int = 0;
    has base_damage: int = 5;
    has damage_per_hop: int = 2;
    has visited: list[str] = [];
    has legacy_max_hops: int = 20;

    can ignite with Root entry {
        print("Trail Blazer: no hop cap — walking the full degree-2 string");
        visit [-->];
    }

    can blaze with TrailSegment entry {
        if here.name not in self.visited {
            self.visited.append(here.name);
            hit = self.base_damage + self.hop_count * self.damage_per_hop;
            here.damage_taken += hit;
            print(
                f"  hop {self.hop_count}: {here.name} +{hit} "
                f"(running {here.damage_taken})"
            );
            self.hop_count += 1;
            visit [->:TrailLink:->] else { disengage; }
        }
    }

    can slam with TrailHub entry {
        if here.name not in self.visited {
            self.visited.append(here.name);
            hit = self.base_damage + self.hop_count * self.damage_per_hop;
            slam = hit * 2;
            here.damage_taken += hit + slam;
            print(
                f"  SLAM on {here.name} (arity {here.arity}): "
                f"hit {hit} + 2x {slam} = {here.damage_taken}"
            );
            seg_count = self.hop_count;
            bound_note = (
                f"legacy max_hops={self.legacy_max_hops} would truncate early"
            );
            print(
                f"Finished {seg_count} segment hops across "
                f"{len(self.visited)} nodes — {bound_note}"
            );
            disengage;
        }
    }
}

