"""GUIDANCE frontier compiler: prerequisite-ordered obligations to earliest unresolved decision with bounded context."""

node IntentGuidanceRequest {
    has role: str = "";
    has change_ref: str = "";
}

node Obligation {
    has label: str = "";
    has phase: str = "";
    has resolved: bool = False;
    has constrains_choice: bool = False;
}

node RelationshipFact {
    has subject: str = "";
    has currentness: str = "current";
}

edge Prerequisite { }
edge Affects { }

walker FrontierCompiler {
    has request_role: str = "";
    has frontier_label: str = "";
    has frontier_phase: str = "";
    has result_class: str = "semantic_frontier";
    has now_items: list[str] = [];
    has guardrail_items: list[str] = [];
    has forecast_items: list[str] = [];
    has stale_warning: str = "";
    has seen_keys: list[str] = [];

    can start with Root entry {
        print(f"Compiling guidance for role={self.request_role}");
        visit [-->];
    }

    can scan with Obligation entry {
        node_key = f"{here.phase}:{here.label}";
        if node_key in self.seen_keys {
            print(f"Cycle guard tripped at {node_key}");
            disengage;
        }
        self.seen_keys += [node_key];
        visit [->:Affects:->];
        if here.resolved {
            visit [->:Prerequisite:->] else { disengage; };
        } else {
            if self.frontier_label == "" {
                self.frontier_label = here.label;
                self.frontier_phase = here.phase;
                self.now_items += [here.label];
            } else {
                bucket = "guardrail" if here.constrains_choice else "forecast";
                if bucket == "guardrail" {
                    self.guardrail_items += [here.label];
                } else {
                    self.forecast_items += [here.label];
                }
            }
            visit [->:Prerequisite:->] else { disengage; };
        }
    }

    can assess_currentness with RelationshipFact entry {
        if here.currentness != "current" {
            stale_subj = here.subject;
            self.stale_warning = stale_subj;
        }
    }

    can finish with Root exit {
        print(f"IntentGuidanceResultV1 class={self.result_class}");
        print(f"  frontier: {self.frontier_label} ({self.frontier_phase})");
        print(f"  Now: {self.now_items}");
        print(f"  Guardrail: {self.guardrail_items}");
        print(f"  Forecast: {self.forecast_items}");
        if self.stale_warning != "" {
            print(f"  staleness: suspect currentness on {self.stale_warning}");
        }
    }
}

