"""Orchestrator dependency gating: a stalled task freezes downstream work under rigid rules but smart file-overlap dispatch allows partial progress."""

node Task {
    has task_id: int = 0;
    has title: str = "";
    has status: str = "todo";
    has files: str = "";
    has effort: str = "";
}

edge HardDependsOn { }

edge SoftDependsOn { }

walker StallRipple {
    has origin_id: int = 0;
    has frozen: list[int] = [];
    has visited: list[int] = [];

    can ripple with Task entry {
        if self.origin_id == 0 {
            self.origin_id = here.task_id;
            print(f"Stall at #{here.task_id} ({here.title}) freezes downstream:");
            self.visited.append(here.task_id);
            visit [<--:HardDependsOn:--|<--:SoftDependsOn:--];
            disengage;
        }
        if here.task_id in self.visited {
            visit [<--:HardDependsOn:--|<--:SoftDependsOn:--];
        }
        self.visited.append(here.task_id);
        if here.status == "todo" {
            self.frozen.append(here.task_id);
            print(f"  [#{here.task_id}] {here.title} stuck at todo");
        }
        visit [<--:HardDependsOn:--|<--:SoftDependsOn:--];
    }
}

walker RigidDispatch {
    has origin_id: int = 0;
    has blockers: list[int] = [];
    has visited: list[int] = [];

    can audit with Task entry {
        if self.origin_id == 0 {
            self.origin_id = here.task_id;
            self.visited.append(here.task_id);
            visit [<--:HardDependsOn:--];
            visit [<--:SoftDependsOn:--];
            self.report(here.task_id, "Rigid");
            disengage;
        }
        if here.task_id in self.visited {
            visit [<--:HardDependsOn:--];
            visit [<--:SoftDependsOn:--];
        }
        self.visited.append(here.task_id);
        if here.status == "todo" {
            self.blockers.append(here.task_id);
        }
        visit [<--:HardDependsOn:--];
        visit [<--:SoftDependsOn:--];
    }

    def report(task_id: int, label: str) -> None {
        if self.blockers {
            ids = ", ".join([f"#{bid}" for bid in self.blockers]);
            print(f"{label}: #{task_id} BLOCKED by open issue(s): {ids}");
        } else {
            print(f"{label}: #{task_id} ELIGIBLE for dispatch");
        }
    }
}

walker SmartDispatch {
    has origin_id: int = 0;
    has target_files: str = "";
    has blockers: list[int] = [];
    has visited: list[int] = [];

    can audit with Task entry {
        if self.origin_id == 0 {
            self.origin_id = here.task_id;
            self.target_files = here.files;
            self.visited.append(here.task_id);
            visit [<--:HardDependsOn:--];
            self.report(here.task_id);
            disengage;
        }
        if here.task_id in self.visited {
            visit [<--:HardDependsOn:--];
        }
        self.visited.append(here.task_id);
        if here.status == "todo" and self.overlaps(self.target_files, here.files) {
            self.blockers.append(here.task_id);
        }
        visit [<--:HardDependsOn:--];
    }

    def overlaps(target: str, dep: str) -> bool {
        if target == "" or dep == "" {
            return False;
        }
        for (part) in target.split(",") {
            token = part.strip();
            if token != "" and token in dep {
                return True;
            }
        }
        return False;
    }

    def report(task_id: int) -> None {
        if self.blockers {
            ids = ", ".join([f"#{bid}" for bid in self.blockers]);
            print(f"Smart: #{task_id} BLOCKED by overlapping open dep(s): {ids}");
        } else {
            print(f"Smart: #{task_id} ELIGIBLE (no overlapping open hard deps)");
        }
    }
}

walker ForceDispatch {
    has warned: bool = False;

    can override with Task entry {
        if not self.warned {
            self.warned = True;
            print(f"WARN: force-dispatch #{here.task_id} ({here.title}) — bypassing gates");
        }
        disengage;
    }
}

