        label = f"S{i:02d}";
        nxt = TrailSegment(name=label);
        tail +>:TrailLink:+> nxt;
        tail = nxt;
    }
    east = TrailHub(name="EastFork", arity=4);
    tail +>:TrailLink:+> east;
    west = TrailHub(name="WestFork", arity=3);
    west +>:BranchArm:+> BranchStub(name="west_a");
    west +>:BranchArm:+> BranchStub(name="west_b");
    west +>:BranchArm:+> head;
    root spawn TrailBlazer(legacy_max_hops=20);
}

