"""LCM-X roadmap: milestones, work items, and blocking dependencies.

Models post-v0.23.1 release sequencing from issue #323: items belong to
milestones, blockers form a directed graph, and walkers audit scope plus
trace blocker chains with an explicit cycle guard (jac 0.36.1 has no
built-in visited set).
"""

node WorkItem {
    has number: int = 0;
    has title: str = "";
    has status: str = "open";
}

node Milestone {
    has name: str = "";
    has version: str = "";
    has released: bool = False;
}

node Roadmap {
    has title: str = "";
    has frozen: bool = False;
}

edge Blocks { }
edge InMilestone { }
edge ContainsMilestone { }

walker MilestoneAuditor {
    can start with Root entry {
        visit [-->];
    }

    can review_roadmap with Roadmap entry {
        freeze_label = "frozen" if here.frozen else "active";
        print(f"Roadmap [{freeze_label}]: {here.title}");
        visit [->:ContainsMilestone:->];
        visit [-->];
    }

    can review_milestone with Milestone entry {
        ship_label = "SHIPPED" if here.released else "IN-FLIGHT";
        print(f"  Milestone {here.version} ({here.name}) [{ship_label}]");
        visit [->:InMilestone:->];
        visit [-->];
    }

    can list_item with WorkItem entry {
        print(f"    #{here.number} {here.title} [{here.status}]");
        visit [-->];
    }
}

walker BlockerTracer {
    has seen: list[int] = [];
    has depth: int = 0;

    can start with WorkItem entry {
        print(f"Blocker chain for #{here.number} ({here.title}):");
        if here.number in self.seen {
            print(f"  CYCLE detected at #{here.number}");
            disengage;
        }
        self.seen.append(here.number);
        visit [<--:Blocks:--] else {
            print("  (no upstream blockers)");
            disengage;
        };
    }

    can walk_blocker with WorkItem entry {
        if here.number in self.seen {
            print(f"  CYCLE at #{here.number}");
            disengage;
        }
        self.seen.append(here.number);
        indent = "";
        for _ in range(self.depth + 1) {
            indent += "  ";
        }
        state_label = "cleared" if here.status == "closed" else "BLOCKING";
        print(f"{indent}#{here.number} {here.title} [{state_label}]");
        self.depth += 1;
        visit [<--:Blocks:--] else { disengage; };
    }
}

walker ReadinessProbe {
    has open_blockers: int = 0;

    can start with Milestone entry {
        if here.released {
            print(f"{here.version}: already released");
            disengage;
        }
        print(f"Readiness probe for {here.version}:");
        visit [->:InMilestone:->] else {
            print("  no scoped work items");
            disengage;
        };
    }

    can check_item with WorkItem entry {
        if here.status == "closed" {
            visit [-->];
        } else {
            print(f"  OPEN #{here.number} {here.title}");
            self.open_blockers += 1;
            visit [-->];
        }
    }

    can summarize with Milestone exit {
        if self.open_blockers == 0 {
            print(f"  {here.version}: ready (no open scoped items)");
        } else {
            print(f"  {here.version}: NOT ready ({self.open_blockers} open item(s))");
        }
    }
}

