and campaign batches; walk dependency topology to schedule campaign work and
audit that every task has comparable results across all three arms."""

node BenchmarkTask {
    has title: str = "";
    has task_id: str = "";
    has dataset_revision: str = "";
}

node ExperimentalArm {
    has arm_name: str = "";
    has pinned_model: str = "gpt-4o-benchmark-pin";
}

node RunRecord {
    has arm_name: str = "";
    has tokens: int = 0;
    has wall_seconds: float = 0.0;
    has interactions: int = 0;
    has exit_state: str = "pending";
    has tests_passed: bool = False;
}

node CampaignBatch {
    has batch_name: str = "";
    has protocol_version: str = "v1.0-frozen";
}

edge DependsOn { }
edge InCampaign { }
edge RecordsRun {
    has captured_at: str = "";
}
edge DefinesArm { }

walker CampaignScheduler {
    has order: list[str] = [];
    has visiting: list[str] = [];
    has cycle_detected: bool = False;

    can start with Root entry {
        print("=== Campaign dependency schedule ===");
        visit [-->];
    }

    can enter_batch with CampaignBatch entry {
        visit [->:InCampaign:->];
    }

    can schedule with BenchmarkTask entry {
        if here.task_id in self.order {
            visit [-->] else { disengage; };
        }
        if here.task_id in self.visiting {
            self.cycle_detected = True;
            print(f"[CYCLE] dependency loop at {here.task_id}");
            disengage;
        }
        self.visiting.append(here.task_id);
        visit [<--:DependsOn:--];
        if self.cycle_detected {
            disengage;
        }
        self.order.append(here.task_id);
        print(f"[SCHEDULE] {here.title} ({here.task_id})");
        if self.visiting {
            self.visiting = self.visiting[:-1];
