    has inferred_contributions: bool = False;

    override def display_name() -> str {
        return self.title;
    }
}

node Evidence(GraphEntity) {
    has summary: str = "";
    has retention: str = "active";
    has proof_active: bool = True;

    override def display_name() -> str {
        return self.summary;
    }
}

edge MemberOf {
    has source: str = "";
    has explanation: str = "";
    has valid: bool = True;
}

edge ContributedTo {
    has source: str = "";
    has explanation: str = "";
    has inferred: bool = False;
    has valid: bool = True;
}

edge Produced {
    has source: str = "";
    has explanation: str = "";
    has valid: bool = True;
}

edge VerifiedBy {
    has source: str = "";
    has explanation: str = "";
    has valid: bool = True;
}

walker ProofExplorer {
    has tenant_id: str = "";
    has role: str = "member";
    has visited: list[GraphEntity] = [];
    has depth: int = 0;
    has max_depth: int = 10;

    def permitted(entity: GraphEntity) -> bool {
        if entity.tenant != self.tenant_id {
            return False;
        }
        if entity.visibility == "restricted" and self.role != "admin" {
            return False;
        }
        return True;
    }

    def begin(entity: GraphEntity) -> bool {
        if entity in self.visited {
            print("[cycle] proof graph loop detected — halting branch");
            return False;
        }
        if self.depth > self.max_depth {
            print("[bound] traversal depth limit reached");
            return False;
        }
        if not self.permitted(entity) {
            return False;
        }
        self.visited.append(entity);
        pad = "  " * self.depth;
        vis_label = "restricted" if entity.visibility == "restricted" else "visible";
        print(f"{pad}+ {entity.display_name()} ({vis_label})");
        self.depth += 1;
        return True;
    }

    def end_visit() {
        self.depth -= 1;
    }

    can start with Root entry {
        print(f"=== proof-chain audit tenant={self.tenant_id} role={self.role} ===");
        visit [-->];
    }

    can walk_person with Person entry {
        if not self.begin(here) {
            disengage;
        }
        visit [->:MemberOf:->];
        visit [->:ContributedTo:->];
        self.end_visit();
    }

    can walk_team with Team entry {
        if not self.begin(here) {
            disengage;
        }
        visit [-->];
        self.end_visit();
    }

    can walk_project with Project entry {
        if not self.begin(here) {
            disengage;
        }
        if here.inferred_contributions {
            pad = "  " * self.depth;
            print(f"{pad}! unapproved inferred contributions present");
        }
        visit [->:Produced:->] else { disengage; };
        self.end_visit();
    }

    can walk_evidence with Evidence entry {
        if not self.begin(here) {
            disengage;
        }
        if here.retention == "withdrawn" or not here.proof_active {
            pad = "  " * self.depth;
            print(f"{pad}! evidence withdrawn — downstream proof invalid");
            disengage;
        }
        visit [->:VerifiedBy:->] else { disengage; };
        self.end_visit();
    }
}

walker RetentionAuditor {
    has invalidated: int = 0;

    can start with Root entry {
        print("=== retention invalidation sweep ===");
        visit [-->[?:Evidence]] else { disengage; };
    }

    can revoke with Evidence entry {
        if here.retention != "withdrawn" {
            visit [-->];
        } else {
            here.proof_active = False;
            print(f"[invalidate] suspended proof chain for: {here.summary}");
            self.invalidated += 1;
            visit [-->];
        }
    }
}

