"""Orchestrator dependency gating: a stalled task freezes downstream work under rigid rules but smart file-overlap dispatch allows partial progress."""

node Task {
    has task_id: int = 0;
    has title: str = "";
    has status: str = "todo";
    has files: str = "";
    has effort: str = "";
}

edge HardDependsOn { }

edge SoftDependsOn { }

edge DownstreamOf { }

walker StallRipple {
    has origin_id: int = 0;
    has frozen: list[int] = [];
    has visited: list[int] = [];

    can ripple with Task entry {
        if here.task_id in self.visited {
            disengage;
        }
        self.visited.append(here.task_id);
        if self.origin_id == 0 {
            self.origin_id = here.task_id;
            print(f"Stall at #{here.task_id} ({here.title}) freezes downstream:");
        } else {
            if here.status == "todo" {
                self.frozen.append(here.task_id);
                print(f"  (#{here.task_id}) {here.title} stuck at todo");
            }
        }
        visit [->:DownstreamOf:->] else { disengage; }
    }
}

walker RigidDispatch {
    has target_id: int = 0;
    has blockers: list[int] = [];
    has visited: list[int] = [];

    can audit with Task entry {
        if self.target_id == 0 {
            self.target_id = here.task_id;
        }
        if here.task_id in self.visited {
            disengage;
        }
        self.visited.append(here.task_id);
        if here.task_id != self.target_id and here.status == "todo" {
            self.blockers.append(here.task_id);
        }
        visit [->:HardDependsOn:->];
        visit [->:SoftDependsOn:->];
        if here.task_id == self.target_id {
            self.show_verdict("Rigid");
            disengage;
        }
    }

    def show_verdict(label: str) {
        if self.blockers {
            ids = ", ".join([f"#{bid}" for bid in self.blockers]);
            print(f"{label}: #{self.target_id} BLOCKED by open issue(s): {ids}");
        } else {
            print(f"{label}: #{self.target_id} ELIGIBLE for dispatch");
        }
    }
}

walker SmartDispatch {
    has target_id: int = 0;
    has target_files: str = "";
    has blockers: list[int] = [];
    has visited: list[int] = [];

    can audit with Task entry {
        if self.target_id == 0 {
            self.target_id = here.task_id;
            self.target_files = here.files;
        }
        if here.task_id in self.visited {
            disengage;
        }
        self.visited.append(here.task_id);
        if (
            here.task_id != self.target_id
            and here.status == "todo"
            and self.overlaps(self.target_files, here.files)
        ) {
            self.blockers.append(here.task_id);
        }
        visit [->:HardDependsOn:->];
        if here.task_id == self.target_id {
            self.show_verdict();
            disengage;
        }
    }

    def overlaps(target: str, dep: str) -> bool {
        if target == "" or dep == "" {
            return False;
        }
        for (part) in target.split(",") {
            token = part.strip();
            if token != "" and token in dep {
                return True;
            }
        }
        return False;
    }

    def show_verdict() {
        if self.blockers {
            ids = ", ".join([f"#{bid}" for bid in self.blockers]);
            print(
                f"Smart: #{self.target_id} BLOCKED by overlapping open dep(s): {ids}"
            );
        } else {
            print(
                f"Smart: #{self.target_id} ELIGIBLE (no overlapping open hard deps)"
            );
        }
    }
}

walker ForceDispatch {
    has warned: bool = False;

    can override with Task entry {
        if not self.warned {
            self.warned = True;
            print(
                f"WARN: force-dispatch #{here.task_id} ({here.title}) — bypassing gates"
            );
        }
        disengage;
    }
}

