"""Topocode demo: multi-scale containment hierarchy and import-cycle detection."""

node ArchNode {
    has name: str = "";
    has healthy: bool = True;

    def tier_label() -> str {
        return "node";
    }

    def detail_text() -> str {
        return "";
    }
}

node Package(ArchNode) {
    override def tier_label() -> str {
        return "package";
    }
}

node Module(ArchNode) {
    has loc: int = 0;

    override def tier_label() -> str {
        return "module";
    }

    override def detail_text() -> str {
        return f"loc={self.loc}";
    }
}

node Symbol(ArchNode) {
    has unit_kind: str = "class";
    has complexity: int = 0;

    override def tier_label() -> str {
        return self.unit_kind;
    }

    override def detail_text() -> str {
        return f"cc={self.complexity}";
    }
}

edge Contains { }

edge Imports {
    has is_dev: bool = False;
}

walker TopoMapper {
    has depth: int = 0;

    can start with Root entry {
        print("=== Topocode: semantic zoom map ===");
        visit [->:Contains:->] else { disengage; }
    }

    can zoom with Package | Module entry {
        pad = "";
        for i in range(self.depth) {
            pad += "  ";
        }
        health_tag = "ok" if here.healthy else "warn";
        detail = here.detail_text();
        suffix = f" {detail}" if detail else "";
        print(f"{pad}[{here.tier_label()}] {here.name} ({health_tag}){suffix}");
        self.depth += 1;
        visit [->:Contains:->] else { };
        self.depth -= 1;
    }

    can leaf with Symbol entry {
        pad = "";
        for i in range(self.depth) {
            pad += "  ";
        }
        detail = here.detail_text();
        print(f"{pad}<{here.tier_label()}> {here.name} ({detail})");
    }
}

walker DepAuditor {
    has stack: list[str] = [];
    has order: list[str] = [];
    has found_cycle: bool = False;

    can start with Root entry {
        print("\n=== Topocode: dependency audit ===");
        visit [->:Contains:->] else { disengage; }
    }

    can scan_pkg with Package entry {
        visit [->:Contains:->] else { };
    }

    can audit with Module entry {
        if here.name in self.stack {
            self.found_cycle = True;
            chain = " -> ".join(self.stack + [here.name]);
            print(f"CYCLE: {chain}");
            disengage;
        }
        self.stack.append(here.name);
        visit [->:Imports:->] else { };
    }

    can leave with Module exit {
        if len(self.stack) > 0 {
            trimmed = [];
            last_idx = len(self.stack) - 1;
            for (i, label) in enumerate(self.stack) {
                if i < last_idx {
                    trimmed.append(label);
                }
            }
            self.stack = trimmed;
        }
        self.order.append(here.name);
    }
}

