"""Adept benchmark epic: model benchmark tasks, experimental arms, run records,
and campaign batches; walk dependency topology to schedule campaign work and
audit that every task has comparable results across all three arms."""

node BenchmarkTask {
    has title: str = "";
    has task_id: str = "";
    has dataset_revision: str = "";
}

node ExperimentalArm {
    has arm_name: str = "";
    has pinned_model: str = "gpt-4o-benchmark-pin";
}

node RunRecord {
    has arm_name: str = "";
    has tokens: int = 0;
    has wall_seconds: float = 0.0;
    has interactions: int = 0;
    has exit_state: str = "pending";
    has tests_passed: bool = False;
}

node CampaignBatch {
    has batch_name: str = "";
    has protocol_version: str = "v1.0-frozen";
}

edge DependsOn { }
edge InCampaign { }
edge RecordsRun {
    has captured_at: str = "";
}
edge DefinesArm { }

walker CampaignScheduler {
    has order: list[str] = [];
    has visiting: list[str] = [];
    has cycle_detected: bool = False;

    can start with Root entry {
        print("=== Campaign dependency schedule ===");
        visit [-->];
    }

    can enter_batch with CampaignBatch entry {
        visit [->:InCampaign:->];
    }

    can schedule with BenchmarkTask entry {
        if here.task_id in self.order {
            visit [-->] else { disengage; };
        }
        if here.task_id in self.visiting {
            self.cycle_detected = True;
            print(f"[CYCLE] dependency loop at {here.task_id}");
            disengage;
        }
        self.visiting.append(here.task_id);
        visit [->:DependsOn:->];
        if self.cycle_detected {
            disengage;
        }
        self.order.append(here.task_id);
        print(f"[SCHEDULE] {here.title} ({here.task_id})");
        if self.visiting {
            trimmed = self.visiting[:-1];
            self.visiting = trimmed;
        }
        visit [-->] else { disengage; };
    }
}

walker CompletenessAuditor {
    has required_arms: list[str] = ["Bare", "GenericWorkflow", "Adept"];
    has gap_count: int = 0;
    has arms_found: list[str] = [];

    can start with Root entry {
        print("=== Cross-arm completeness audit ===");
        visit [-->];
    }

    can enter_batch with CampaignBatch entry {
        visit [->:InCampaign:->];
    }

    can audit_task with BenchmarkTask entry {
        self.arms_found = [];
        visit [->:RecordsRun:->];
        for arm in self.required_arms {
            if arm not in self.arms_found {
                self.gap_count += 1;
                print(f"[GAP] {here.task_id} missing arm {arm}");
            } else {
                print(f"[OK] {here.task_id} covered arm {arm}");
            }
        }
        visit [-->] else { disengage; };
    }

    can tally_record with RunRecord entry {
        self.arms_found.append(here.arm_name);
        visit [-->] else { disengage; };
    }
}

