"""Hexo deploy catalog: model site pipelines as a graph and walk build-to-publish order."""

node HexoSite {
    has name: str = "";
    has node_min_version: str = "10.13";
    has recommended: str = "";
}

node DeployMethod {
    has title: str = "";
    has slug: str = "";
    has official: bool = False;
    has trigger_branch: str = "main";
}

node WorkflowJob {
    has name: str = "";
    has phase: str = "";
    has runner: str = "ubuntu-latest";
    has node_version: str = "20";
    has ready: bool = True;
}

node BuildJob(WorkflowJob) {
    has output_dir: str = "public";
}

node DeployJob(WorkflowJob) {
    has publish_dir: str = "public";
    has publish_branch: str = "gh-pages";
    has uses_peaceiris: bool = False;
}

node PublishTarget {
    has name: str = "";
    has channel: str = "";
    has branch: str = "gh-pages";
}

edge OffersMethod {
    has rank: int = 0;
}

edge FirstJob {
    has order: int = 1;
}

edge NextStep {
    has order: int = 0;
}

edge PublishesTo {
    has artifact: str = "public";
}

walker ReleaseEngineer {
    has methods_seen: int = 0;
    has jobs_seen: int = 0;
    has last_phase: str = "";
    has order_ok: bool = True;

    can start with Root entry {
        print("=== Hexo deployment pipeline audit ===");
        visit [-->];
    }

    can open_site with HexoSite entry {
        print(
            f"Site {here.name} (Node >= {here.node_min_version}); "
            f"recommended: {here.recommended}"
        );
        visit [->:OffersMethod:->] else {
            disengage;
        };
    }

    can review_method with DeployMethod entry {
        self.methods_seen += 1;
        self.last_phase = "";
        badge = "OFFICIAL" if here.official else "ALT";
        print(
            f"\n[{badge}] {here.title} "
            f"(trigger={here.trigger_branch}, slug={here.slug})"
        );
        visit [->:FirstJob:->] else {
            print("  (no workflow jobs wired)");
            visit [->:PublishesTo:->] else {
                disengage;
            };
        };
    }

    can run_job with BuildJob | DeployJob entry {
        self.jobs_seen += 1;
        if self.last_phase == "deploy" and here.phase == "build" {
            self.order_ok = False;
        }
        self.last_phase = here.phase;
        gate = "READY" if here.ready else "BLOCKED";
        print(
            f"  [{gate}] {here.phase}: {here.name} "
            f"on {here.runner} (node {here.node_version})"
        );
        visit [->:NextStep:->] else {
            visit [->:PublishesTo:->] else {
                disengage;
            };
        };
    }

    can confirm_target with PublishTarget entry {
        print(
            f"  -> publish to {here.name} via {here.channel} "
            f"(branch={here.branch})"
        );
        disengage;
    }

    can finish with Root exit {
        verdict = "valid" if self.order_ok else "INVALID";
        print(
            f"\nAudited {self.methods_seen} methods, "
            f"{self.jobs_seen} jobs; pipeline order {verdict}"
        );
    }
}

