"""Workflow DAG validator: detect dependency cycles, enforce limits, and topo-order steps."""

node WorkflowSchema {
    has schema_version: int = 1;
    has title: str = "workflow-definition";
    has year: int = 0;
    has available: bool = True;
}

node WorkflowStep {
    has step_id: str = "";
    has title: str = "";
    has step_type: str = "action";
    has binds_from: str = "";
    has available: bool = True;

    def nesting_depth() -> int {
        return 0;
    }

    def branch_limit() -> int {
        return 0;
    }
}

node IfElseStep(WorkflowStep) {
    has depth: int = 0;
    has branch_count: int = 0;

    override def nesting_depth() -> int {
        return self.depth;
    }

    override def branch_limit() -> int {
        return self.branch_count;
    }
}

edge Defines { }
edge DependsOn { }

walker WorkflowValidator {
    has visiting: list[str] = [];
    has done: list[str] = [];
    has topo_order: list[str] = [];
    has cycle_nodes: list[str] = [];
    has binding_errors: list[str] = [];
    has step_count: int = 0;
    has max_steps: int = 100;
    has max_if_depth: int = 5;
    has valid: bool = True;

    def in_list(items: list[str], needle: str) -> bool {
        for item in items {
            if item == needle {
                return True;
            }
        }
        return False;
    }

    def finalize_step() -> None {
        last_i = len(self.visiting) - 1;
        if last_i >= 0 and self.visiting[last_i] == here.step_id {
            self.visiting.pop();
        }
        if not self.in_list(self.done, here.step_id) {
            self.done.append(here.step_id);
            self.topo_order.append(here.step_id);
        }
    }

    can start with Root entry {
        visit [-->[?:WorkflowSchema]] else { disengage; };
    }

    can read_limits with WorkflowSchema entry {
        self.max_steps = here.schema_version * 100;
        visit [-->[?:WorkflowStep]] else { disengage; };
    }

    can audit with WorkflowStep entry {
        if not self.valid {
            disengage;
        }
        if self.in_list(self.done, here.step_id) {
            disengage;
        }
        if self.in_list(self.visiting, here.step_id) {
            print(f"[CYCLE] step '{here.step_id}' closes a dependency loop");
            if not self.in_list(self.cycle_nodes, here.step_id) {
                self.cycle_nodes.append(here.step_id);
            }
            self.valid = False;
            disengage;
        }
        self.step_count += 1;
        if self.step_count > self.max_steps {
            print(f"[LIMIT] workflow exceeds {self.max_steps} steps");
            self.valid = False;
            disengage;
        }
        nest = here.nesting_depth();
        if nest > self.max_if_depth {
            print(f"[DEPTH] '{here.step_id}' if/else depth {nest} > {self.max_if_depth}");
            self.valid = False;
        }
        branches = here.branch_limit();
        if branches > 2 {
            print(f"[BRANCH] '{here.step_id}' has {branches} branches (max 2)");
            self.valid = False;
        }
        if here.binds_from != "" and not self.in_list(self.done, here.binds_from) {
            print(f"[BIND] '{here.step_id}' references missing or future step '{here.binds_from}'");
            if not self.in_list(self.binding_errors, here.step_id) {
                self.binding_errors.append(here.step_id);
            }
            self.valid = False;
        }
        self.visiting.append(here.step_id);
        visit [->:DependsOn:->] else {
            self.finalize_step();
            visit [-->[?:WorkflowStep]] else { disengage; };
        };
    }

    can close with WorkflowStep exit {
        if not self.valid {
            disengage;
        }
        self.finalize_step();
        visit [-->[?:WorkflowStep]] else { disengage; };
    }
}

