    def in_list(items: list[str], needle: str) -> bool {
        for item in items {
            if item == needle {
                return True;
            }
        }
        return False;
    }

    def finalize_step(step_id: str) {
        last_i = len(self.visiting) - 1;
        if last_i >= 0 and self.visiting[last_i] == step_id {
            self.visiting.pop();
        }
        if not self.in_list(self.done, step_id) {
            self.done.append(step_id);
            self.topo_order.append(step_id);
        }
