        if not self.valid {
            disengage;
        }
        if self.in_list(self.done, here.step_id) {
            disengage;
        }
        if self.in_list(self.visiting, here.step_id) {
            print(f"[CYCLE] step '{here.step_id}' closes a dependency loop");
            if not self.in_list(self.cycle_nodes, here.step_id) {
                self.cycle_nodes.append(here.step_id);
            }
            self.valid = False;
            disengage;
        }
        self.step_count += 1;
        if self.step_count > self.max_steps {
            print(f"[LIMIT] workflow exceeds {self.max_steps} steps");
            self.valid = False;
            disengage;
        }
        nest = here.nesting_depth();
        if nest > self.max_if_depth {
            print(f"[DEPTH] '{here.step_id}' if/else depth {nest} > {self.max_if_depth}");
            self.valid = False;
        }
        branches = here.branch_limit();
        if branches > 2 {
            print(f"[BRANCH] '{here.step_id}' has {branches} branches (max 2)");
            self.valid = False;
        }
        if here.binds_from != "" and not self.in_list(self.done, here.binds_from) {
            print(f"[BIND] '{here.step_id}' references missing or future step '{here.binds_from}'");
            if not self.in_list(self.binding_errors, here.step_id) {
