walker ConformanceAuditor {
    has run_label: str = "";
    has last_signal_bar: int = -1;
    has fill_model: str = "";
    has accepted: int = 0;
    has violations: int = 0;

    can start with Root entry {
        print("=== LEAN execution bridge conformance audit ===");
        visit [-->];
        print(
            f"=== Result: {self.accepted} accepted, "
            f"{self.violations} violations (deterministic replay required) ==="
        );
    }

    can bind_config with ExecutionConfig entry {
        self.fill_model = here.fill_model;
        print(
            f"Run {here.run_id}: fill_model={here.fill_model}, "
            f"slippage={here.slippage_bps}bps, "
            f"deterministic={here.deterministic}"
        );
        visit [-->];
    }

    can capture_signal with Signal entry {
        self.last_signal_bar = here.bar_id;
        print(
            f"Signal {here.symbol} {here.side} @ bar {here.bar_id} "
            f"(artifact v{here.version})"
        );
        visit [->:DerivedFrom:->];
        visit [-->];
    }

    can check_order with Order entry {
        print(f"  Order {here.symbol} qty={here.quantity} status={here.status}");
        visit [->:FillOn:->] else {
            print("  REJECT: no fill bar scheduled");
            here.status = "rejected";
            self.violations += 1;
        };
    }

    can validate_fill with Bar entry {
        fill_bar = here.bar_id;
        if self.last_signal_bar >= fill_bar {
            verdict = "REJECT";
            reason = "same-bar fill impossible";
            self.violations += 1;
            here.available = False;
        } else {
            verdict = "ACCEPT";
            reason = "fill after signal bar (next-bar-open discipline)";
            self.accepted += 1;
            here.available = True;
        }
        print(
            f"  [{verdict}] {reason}: signal bar {self.last_signal_bar}, "
            f"fill bar {fill_bar}, model={self.fill_model}"
        );
    }
}

