"""Wide-feature coverage manifest: audit coverage coordinates, lineage mass, and feature dependency order."""

node EvidenceUnit {
    has unit_id: str = "";
    has evidence_mass: float = 1.0;
    has descendant_weight_total: float = 0.0;
}

node Feature {
    has feature_id: str = "";
    has namespace: str = "";
    has available_at: int = 0;

    def label() -> str {
        return f"{self.namespace}.{self.feature_id}";
    }
}

node BarFeature(Feature) {
    has bar_timeframe: str = "1m";
}

node StrategyFeature(Feature) {
    has strategy_id: str = "";

    override def label() -> str {
        return f"strategy.{self.strategy_id}.{self.feature_id}";
    }
}

node DatasetView {
    has view_name: str = "";
    has policy_id: str = "";
}

node CoverageCoordinate {
    has state: str = "unsupported";
    has reason: str = "";
}

edge DescendantOf {
    has weight: float = 0.0;
}

edge Requires {}

edge BindsEvidence {}

edge BindsFeature {}

edge BindsView {}

walker CoverageAuditor {
    has eligible: int = 0;
    has available: int = 0;
    has row_cutoff: int = 1000;
    has ctx_state: str = "";
    has ctx_reason: str = "";
    has ctx_feature_at: int = 0;
    has ctx_unit: str = "";
    has ctx_view: str = "";
    has ctx_label: str = "";

    can start with Root entry {
        print("=== Coverage rectangle audit ===");
        visit [-->[?:CoverageCoordinate]];
    }

    can audit with CoverageCoordinate entry {
        self.eligible += 1;
        self.ctx_state = here.state;
        self.ctx_reason = here.reason;
        self.ctx_feature_at = 0;
        self.ctx_unit = "?";
        self.ctx_view = "?";
        self.ctx_label = "?";
        visit [<--:BindsFeature:<--] else { disengage; };
        visit [<--:BindsEvidence:<--] else { disengage; };
        visit [<--:BindsView:<--] else { disengage; };
        late_flag = self.ctx_feature_at > self.row_cutoff;
        if late_flag {
            late_note = "causally_late";
            print(f"[{late_note}] {self.ctx_label} unit={self.ctx_unit} view={self.ctx_view}");
        } else if self.ctx_state == "observed" or self.ctx_state == "imputed" {
            self.available += 1;
            print(f"[{self.ctx_state}] {self.ctx_label} unit={self.ctx_unit} view={self.ctx_view}");
        } else {
            print(f"[{self.ctx_state}] {self.ctx_reason} ({self.ctx_label})");
        }
    }

    can bind_feature with BarFeature | StrategyFeature entry {
        self.ctx_feature_at = here.available_at;
        self.ctx_label = here.label();
        disengage;
    }

    can bind_evidence with EvidenceUnit entry {
        self.ctx_unit = here.unit_id;
        disengage;
    }

    can bind_view with DatasetView entry {
        self.ctx_view = here.view_name;
        disengage;
    }
}

walker LineageAuditor {
    has visited_units: list[str] = [];
    has violations: int = 0;

    can start with Root entry {
        print("=== Evidence mass invariant ===");
        visit [-->[?:EvidenceUnit]];
    }

    can walk with EvidenceUnit entry {
        if here.unit_id in self.visited_units {
            print(f"CYCLE at evidence unit {here.unit_id}");
            self.violations += 1;
            disengage;
        }
        self.visited_units.append(here.unit_id);
        if here.descendant_weight_total > here.evidence_mass {
            print(f"VIOLATION {here.unit_id}: {here.descendant_weight_total} > {here.evidence_mass}");
            self.violations += 1;
        } else {
            print(f"OK {here.unit_id}: {here.descendant_weight_total} <= {here.evidence_mass}");
        }
        visit [->:DescendantOf:->] else { disengage; };
    }
}

walker DependencyPlanner {
    has ordered: list[str] = [];
    has visiting: list[str] = [];
    has cycle_detected: bool = False;

    can start with Root entry {
        print("=== Feature dependency order ===");
        visit [-->[?:Feature]];
    }

    can plan with Feature entry {
        if here.feature_id in self.visiting {
            print(f"CYCLE at feature {here.feature_id}");
            self.cycle_detected = True;
            disengage;
        }
        if here.feature_id in self.ordered {
            disengage;
        }
        self.visiting.append(here.feature_id);
        visit [->:Requires:->] else { disengage; };
    }

    can finish with Feature exit {
        updated: list[str] = [];
        for vid in self.visiting {
            if vid != here.feature_id {
                updated.append(vid);
            }
        }
        self.visiting = updated;
        if here.feature_id not in self.ordered {
            self.ordered.append(here.feature_id);
            print(f"  order: {here.label()}");
        }
    }
}

