}

"""SparrowDB label ACL: scope the catalog once at ReadSnapshot construction, not at 86 call sites."""

node CatalogLabel {
    has name: str = "";
    has row_count: int = 0;
    has available: bool = True;
}

node Principal {
    has name: str = "";
    has token: str = "";
}

node ReadSnapshot {
    has owner: str = "";
    has built: bool = False;
}

edge CatalogMember { }
edge MayAccess { }
edge Permits { }

walker SnapshotBuilder {
    has snap: ReadSnapshot = ReadSnapshot();

    can start with Root entry {
        print("Phase 2: build scoped catalog views at the single chokepoint");
        visit [-->[?:Principal]];
    }

    can construct with Principal entry {
        self.snap = ReadSnapshot(owner=here.name, built=True);
        root ++> self.snap;
        print(f"[CHOKEPOINT] ReadSnapshot for principal '{here.name}'");
        visit [->:MayAccess:->] else {
            print("  (no labels granted)");
            self.snap spawn CatalogProbe(mode="scoped");
            visit [-->[?:Principal]] else { disengage; };
        };
    }

    can grant with CatalogLabel entry {
        self.snap +>:Permits:+> here;
        print(f"  permits label '{here.name}' ({here.row_count} rows)");
        visit [->:MayAccess:->] else {
            self.snap spawn CatalogProbe(mode="scoped");
            visit [-->[?:Principal]] else { disengage; };
        };
    }
}

walker CatalogProbe {
    has mode: str = "scoped";
    has listed: int = 0;
    has lookup_target: str = "Secret";

    can start with ReadSnapshot entry {
        if self.mode != "scoped" {
            disengage;
        }
        print(f"list_labels() for '{here.owner}' (scoped snapshot):");
        visit [->:Permits:->] else {
            print("  (empty catalog view)");
            disengage;
        };
    }

    can start with Root entry {
        if self.mode != "leak" {
            disengage;
        }
        print("UNGUARDED fast path — counts every catalog label (fail-open class):");
        visit [->:CatalogMember:->] else { disengage; };
    }

    can list with CatalogLabel entry {
        if self.mode == "scoped" {
            self.listed += 1;
            print(f"  visible: {here.name}  count={here.row_count}");
            visit [->:Permits:->] else {
                self.probe_get_label();
                disengage;
            };
        } else {
            print(f"  leaked:  {here.name}  count={here.row_count}");
            visit [->:CatalogMember:->] else { disengage; };
        }
    }

    def probe_get_label() -> None {
        verdict = "absent";
        if self.lookup_target == "Secret" and self.listed < 3 {
            verdict = "forbidden-or-absent";
        }
        print(f"get_label('{self.lookup_target}') -> None  ({verdict} to caller)");
        print(f"  snapshot saw {self.listed} label(s); node-level ACL deferred (no single materialisation path)");
    }
}

with entry {
    pub = CatalogLabel(name="Public", row_count=100);
    internal = CatalogLabel(name="Internal", row_count=50);
    secret = CatalogLabel(name="Secret", row_count=10, available=False);
    root +>:CatalogMember:+> pub;
    root +>:CatalogMember:+> internal;
    root +>:CatalogMember:+> secret;

    analyst = Principal(name="analyst", token="tok-analyst");
    admin = Principal(name="admin", token="tok-admin");
    root ++> analyst ++> admin;

    analyst +>:MayAccess:+> pub;
    analyst +>:MayAccess:+> internal;
    admin +>:MayAccess:+> pub;
    admin +>:MayAccess:+> internal;
    admin +>:MayAccess:+> secret;

    root spawn SnapshotBuilder();
    root spawn CatalogProbe(mode="leak");
}

"""Delta HNSW insert/search hang: cyclic neighbor graphs need visited sets and step bounds."""

node HnswIndex {
    has title: str = "delta-hnsw";
    has year: int = 0;
    has available: bool = True;
    has dim: int = 128;
    has insert_target: int = 100;
}

node VectorEntry {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

edge Neighbor {
    has distance: float = 0.0;
}

walker UnguardedSearch {
    has k: int = 10;
    has steps: int = 0;
    has step_cap: int = 25;
    has found: list[str] = [];

    can start with Root entry {
        print("Unguarded search: no visited set on cyclic neighbor graph");
        visit [-->];
    }

    can enter_index with HnswIndex entry {
        visit [->:Neighbor:->] else { disengage; };
    }

    can crawl with VectorEntry entry {
        self.steps += 1;
        print(f"  unguarded step {self.steps}: {here.title}");
        if here.available {
            self.found.append(here.title);
        }
        if self.steps >= self.step_cap {
            print(f"  HANG PATTERN: {self.steps} steps, no termination (found {len(self.found)})");
            disengage;
        }
        if len(self.found) >= self.k {
            disengage;
        }
        visit [->:Neighbor:->] else { disengage; };
    }
}

walker SafeKnnSearch {
    has k: int = 10;
    has max_steps: int = 100;
    has steps: int = 0;
    has visited: list[str] = [];
    has found: list[str] = [];

    can start with Root entry {
        print("Safe search: visited set + step bound");
        visit [-->];
    }

    can enter_index with HnswIndex entry {
        visit [->:Neighbor:->] else { disengage; };
    }

    can explore with VectorEntry entry {
        if here.title in self.visited {
            visit [->:Neighbor:->] else { disengage; };
        }
        self.visited.append(here.title);
        self.steps += 1;
        if self.steps > self.max_steps {
            print(f"  FAIL LOUD: exceeded {self.max_steps} probe steps");
            disengage;
        }
        if here.available {
            self.found.append(here.title);
        }
        if len(self.found) >= self.k {
            print(f"  search done: {len(self.found)} hits in {self.steps} steps");
            disengage;
        }
        visit [->:Neighbor:->] else { disengage; };
    }
}

walker DeltaInserter {
    has inserted: int = 0;
    has limit: int = 10;
    has probe_steps: int = 0;
    has max_probe_steps: int = 50;
    has visited: list[str] = [];

    can start with Root entry {
        print("Insert probe: bounded neighbor walk for insertion point");
        visit [-->];
    }

    can at_index with HnswIndex entry {
        print(f"  index dim={here.dim} target={here.insert_target}");
        visit [->:Neighbor:->] else { disengage; };
    }

    can probe with VectorEntry entry {
        if here.title in self.visited {
            visit [->:Neighbor:->] else { disengage; };
        }
        self.visited.append(here.title);
        self.probe_steps += 1;
        if self.probe_steps > self.max_probe_steps {
            print(f"  insert probe bounded at {self.max_probe_steps} steps");
            disengage;
        }
        self.inserted += 1;
        print(f"  inserted {self.inserted}/{self.limit}: {here.title}");
        if self.inserted >= self.limit {
            print(f"  insert complete: {self.inserted} vectors indexed");
            disengage;
        }
        visit [->:Neighbor:->] else { disengage; };
    }
}

