"""Homelab service mesh: dependency graph traversal, cycle detection, topo startup order, and health cascade invalidation."""

node Service {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

edge DependsOn { }

walker CycleDetector {
    has path: list[str] = [];
    has found_cycle: bool = False;
    has cycle_at: str = "";

    can start with Root entry {
        print("scanning dependency graph for cycles");
        visit [-->];
    }

    can probe with Service entry {
        if self.found_cycle {
            disengage;
        }
        name = here.title;
        if name in self.path {
            self.found_cycle = True;
            self.cycle_at = name;
            disengage;
        }
        self.path.append(name);
        visit [->:DependsOn:->] else {
            visit [-->] else { disengage; };
        };
        self.path.pop();
        visit [-->] else { disengage; };
    }
}

walker StartupPlanner {
    has visited: list[str] = [];
    has startup_order: list[str] = [];

    can start with Root entry {
        print("planning startup order (deps before dependents)");
        visit [-->];
    }

    can plan with Service entry {
        name = here.title;
        if name in self.visited {
            visit [-->] else { disengage; };
        }
        self.visited.append(name);
        visit [->:DependsOn:->];
        self.startup_order.append(name);
        visit [-->] else { disengage; };
    }
}

walker HealthCascade {
    has invalidated: list[str] = [];
    has visited: list[str] = [];
    has from_cascade: bool = False;

    can start with Root entry {
        print("cascading health failure through dependents");
        visit [-->];
    }

    can cascade with Service entry {
        name = here.title;
        if name in self.visited {
            visit [-->] else { disengage; };
        }
        self.visited.append(name);
        should_fail = not here.available or self.from_cascade;
        self.from_cascade = False;
        if should_fail {
            here.available = False;
            self.invalidated.append(name);
            self.from_cascade = True;
            visit [<--:DependsOn:--] else {
                self.from_cascade = False;
                visit [-->] else { disengage; };
            };
            self.from_cascade = False;
        } else {
            visit [-->] else { disengage; };
        }
    }
}

with entry {
    db = Service(title="database", available=False);
    cache = Service(title="cache");
    api = Service(title="api");
    web = Service(title="web");
    nginx = Service(title="nginx");

    root ++> db ++> cache ++> api ++> web ++> nginx;

    api +>:DependsOn:+> db;
    cache +>:DependsOn:+> api;
    api +>:DependsOn:+> cache;
    web +>:DependsOn:+> api;
    nginx +>:DependsOn:+> web;

    detector = CycleDetector();
    root spawn detector;
    cycle_msg = f"cycle detected at {detector.cycle_at}" if detector.found_cycle else "no cycle found";
    print(cycle_msg);

    planner = StartupPlanner();
    root spawn planner;
    print(f"startup order: {planner.startup_order}");

    cascade = HealthCascade();
    root spawn cascade;
    print(f"invalidated services: {cascade.invalidated}");
}

"""Delta HNSW insert/search hang: cyclic neighbor graphs need visited sets and step bounds."""

node HnswIndex {
    has title: str = "delta-hnsw";
    has year: int = 0;
    has available: bool = True;
    has dim: int = 128;
    has insert_target: int = 100;
}

node VectorEntry {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

edge Neighbor {
    has distance: float = 0.0;
}

walker UnguardedSearch {
    has k: int = 10;
    has steps: int = 0;
    has step_cap: int = 25;
    has found: list[str] = [];

    can start with Root entry {
        print("Unguarded search: no visited set on cyclic neighbor graph");
        visit [-->];
    }

    can enter_index with HnswIndex entry {
        visit [->:Neighbor:->] else { disengage; };
    }

    can crawl with VectorEntry entry {
        self.steps += 1;
        print(f"  unguarded step {self.steps}: {here.title}");
        if here.available {
            self.found.append(here.title);
        }
        if self.steps >= self.step_cap {
            print(f"  HANG PATTERN: {self.steps} steps, no termination (found {len(self.found)})");
            disengage;
        }
        if len(self.found) >= self.k {
            disengage;
        }
        visit [->:Neighbor:->] else { disengage; };
    }
}

walker SafeKnnSearch {
    has k: int = 10;
    has max_steps: int = 100;
    has steps: int = 0;
    has visited: list[str] = [];
    has found: list[str] = [];

    can start with Root entry {
        print("Safe search: visited set + step bound");
        visit [-->];
    }

    can enter_index with HnswIndex entry {
        visit [->:Neighbor:->] else { disengage; };
    }

    can explore with VectorEntry entry {
        if here.title in self.visited {
            visit [->:Neighbor:->] else { disengage; };
        }
        self.visited.append(here.title);
        self.steps += 1;
        if self.steps > self.max_steps {
            print(f"  FAIL LOUD: exceeded {self.max_steps} probe steps");
            disengage;
        }
        if here.available {
            self.found.append(here.title);
        }
        if len(self.found) >= self.k {
            print(f"  search done: {len(self.found)} hits in {self.steps} steps");
            disengage;
        }
        visit [->:Neighbor:->] else { disengage; };
    }
}

walker DeltaInserter {
    has inserted: int = 0;
    has limit: int = 10;
    has probe_steps: int = 0;
    has max_probe_steps: int = 50;
    has visited: list[str] = [];

    can start with Root entry {
        print("Insert probe: bounded neighbor walk for insertion point");
        visit [-->];
    }

    can at_index with HnswIndex entry {
        print(f"  index dim={here.dim} target={here.insert_target}");
        visit [->:Neighbor:->] else { disengage; };
    }

    can probe with VectorEntry entry {
        if here.title in self.visited {
            visit [->:Neighbor:->] else { disengage; };
        }
        self.visited.append(here.title);
        self.probe_steps += 1;
        if self.probe_steps > self.max_probe_steps {
            print(f"  insert probe bounded at {self.max_probe_steps} steps");
            disengage;
        }
        self.inserted += 1;
        print(f"  inserted {self.inserted}/{self.limit}: {here.title}");
        if self.inserted >= self.limit {
            print(f"  insert complete: {self.inserted} vectors indexed");
            disengage;
        }
        visit [->:Neighbor:->] else { disengage; };
    }
}

