"""Ground and evidence: reconstruct the record spine, trace asset anchors, and demote defeated claims."""

node RecordClaim {
    has claim_id: str = "";
    has statement: str = "";
    has standing: bool = True;
    has expected_hash: str = "";
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

node AssetVersion {
    has asset_id: str = "";
    has payload_hash: str = "";
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

node Attestation {
    has witness_id: str = "";
    has observed: str = "";
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

edge Provenance { has seq: int = 0; }
edge Anchors { has recorded_hash: str = ""; }
edge Corroborates { has weight: float = 1.0; }
edge Refutes { has reason: str = ""; }

walker IntegrityWitness {
    has seen: list[str] = [];
    has demotions: int = 0;
    has visit_mode: str = "";
    has mark_demote: bool = False;
    has pending_hash: str = "";
    has hash_drift: bool = False;

    can start with Root entry {
        print("witness: reconstructing record spine and evidence");
        visit [-->];
    }

    can audit with RecordClaim entry {
        if here.claim_id in self.seen {
            print(f"[CYCLE] blocked at {here.claim_id}");
            disengage;
        }
        self.seen.append(here.claim_id);

        self.mark_demote = False;
        self.hash_drift = False;
        self.visit_mode = "refute";
        visit [<--:Refutes:--];
        self.visit_mode = "corroborate";
        visit [<--:Corroborates:--];

        self.pending_hash = here.expected_hash;
        self.visit_mode = "anchor";
        visit [->:Anchors:->];

        if self.hash_drift {
            here.standing = False;
            self.mark_demote = True;
            print(f"  payload drift on anchor for {here.claim_id}");
        }

        if self.mark_demote {
            here.standing = False;
            self.demotions += 1;
            status_label = "DEMOTED";
        } else {
            status_label = "STANDING" if here.standing else "DEMOTED";
        }
        print(f"[{status_label}] {here.claim_id}: {here.statement}");

        self.visit_mode = "provenance";
        visit [->:Provenance:->];
        visit [-->];
    }

    can encounter with Attestation entry {
        if self.visit_mode == "refute" {
            self.mark_demote = True;
            print(f"  defeat by {here.witness_id}: {here.observed}");
        } else {
            if self.visit_mode == "corroborate" {
                print(f"  corroborated by {here.witness_id}: {here.observed}");
            }
        }
    }

    can verify_asset with AssetVersion entry {
        drift_note = "";
        if self.pending_hash != "" {
            if here.payload_hash != self.pending_hash {
                self.hash_drift = True;
                drift_note = " MISMATCH";
            }
        }
        print(f"  asset {here.asset_id} hash={here.payload_hash}{drift_note}");
    }
}

with entry {
