"""Homelab service mesh: dependency graph traversal, cycle detection, topo startup order, and health cascade invalidation."""

node Service {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

edge DependsOn { }

walker CycleDetector {
    has path: list[str] = [];
    has found_cycle: bool = False;
    has cycle_at: str = "";

    can start with Root entry {
        print("scanning dependency graph for cycles");
        visit [-->];
    }

    can probe with Service entry {
        if self.found_cycle {
            disengage;
        }
        name = here.title;
        if name in self.path {
            self.found_cycle = True;
            self.cycle_at = name;
            disengage;
        }
        self.path.append(name);
        visit [->:DependsOn:->] else {
            visit [-->] else { disengage; };
        };
        self.path.pop();
        visit [-->] else { disengage; };
    }
}

walker StartupPlanner {
    has visited: list[str] = [];
    has startup_order: list[str] = [];

    can start with Root entry {
        print("planning startup order (deps before dependents)");
        visit [-->];
    }

    can plan with Service entry {
        name = here.title;
        if name in self.visited {
            visit [-->] else { disengage; };
        }
        self.visited.append(name);
        visit [->:DependsOn:->] else { disengage; };
        self.startup_order.append(name);
        visit [-->] else { disengage; };
    }
}

walker HealthCascade {
    has invalidated: list[str] = [];
    has visited: list[str] = [];
    has from_cascade: bool = False;

    can start with Root entry {
        print("cascading health failure through dependents");
        visit [-->];
    }

    can cascade with Service entry {
        name = here.title;
        if name in self.visited {
            visit [-->] else { disengage; };
        }
        self.visited.append(name);
        should_fail = not here.available or self.from_cascade;
        self.from_cascade = False;
        if should_fail {
            here.available = False;
            self.invalidated.append(name);
            self.from_cascade = True;
            visit [<--:DependsOn:<--] else {
                self.from_cascade = False;
                visit [-->] else { disengage; };
            };
            self.from_cascade = False;
        } else {
            visit [-->] else { disengage; };
        }
    }
}

with entry {
    db = Service(title="database", available=False);
    cache = Service(title="cache");
    api = Service(title="api");
    web = Service(title="web");
    nginx = Service(title="nginx");

    root ++> db ++> cache ++> api ++> web ++> nginx;

    api +>:DependsOn:+> db;
    cache +>:DependsOn:+> api;
    api +>:DependsOn:+> cache;
    web +>:DependsOn:+> api;
    nginx +>:DependsOn:+> web;

    detector = CycleDetector();
    root spawn detector;
    cycle_msg = f"cycle detected at {detector.cycle_at}" if detector.found_cycle else "no cycle found";
    print(cycle_msg);

    planner = StartupPlanner();
    root spawn planner;
    print(f"startup order: {planner.startup_order}");

    cascade = HealthCascade();
    root spawn cascade;
    print(f"invalidated services: {cascade.invalidated}");
}

"""AsyncAPI component schema export: discover named schemas, guard cyclic internal refs, and emit a deterministic Draft 07 bundle."""

node ApiDocument {
    has source_uri: str = "";
    has spec_version: str = "";
}

node ComponentSchema {
    has name: str = "";
    has authored_id: str = "";
    has schema_format: str = "";
    has description: str = "";
    has is_boolean: bool = False;
    has boolean_value: bool = True;
    has parser_metadata: bool = False;
}

edge Defines { }

edge RefersTo {
    has ref_pointer: str = "";
}

walker SchemaBundler {
    has collected: list[str] = [];
    has seen_ids: list[str] = [];
    has stripped: int = 0;
    has errors: list[str] = [];

    can start with Root entry {
        print("Bundling components.schemas for JSON Schema Draft 07 export");
        visit [-->];
    }

    can scan with ApiDocument entry {
        print(f"Source snapshot: {here.source_uri} (AsyncAPI {here.spec_version})");
        visit [->:Defines:->] else { disengage; };
    }

    can collect with ComponentSchema entry {
        if here.parser_metadata {
            self.stripped += 1;
        }
        if here.authored_id != "" {
            if here.authored_id in self.seen_ids {
                self.errors.append(
                    f"duplicate $id {here.authored_id} on component {here.name}"
                );
            } else {
                self.seen_ids.append(here.authored_id);
            }
        }
        if here.name not in self.collected {
            self.collected.append(here.name);
        }
        disengage;
    }

    def report() {
        ordered = sorted(self.collected);
        print("");
        print(f"Validated bundle — {len(ordered)} component schema(s)");
        print(f"Parser metadata fields stripped from {self.stripped} schema(s)");
        if self.errors {
            for err in self.errors {
                print(f"ERROR: {err}");
            }
        }
        print("definitions (deterministic byte order):");
        for name in ordered {
            kind = "boolean" if name == "EnabledFlag" else "object";
            print(f"  \"{name}\" ({kind})");
        }
        print("(inline message payloads excluded — not in components.schemas)");
    }
}

walker RefAuditor {
    has visiting: list[str] = [];
    has guarded: int = 0;

    can start with ComponentSchema entry {
        self.visiting.append(here.name);
        visit [->:RefersTo:->] else { disengage; };
    }

    can follow with ComponentSchema entry {
        if here.name in self.visiting {
            self.guarded += 1;
            print(f"  cycle guard: stopped at internal $ref to {here.name}");
            disengage;
        }
        self.visiting.append(here.name);
        visit [->:RefersTo:->] else { disengage; };
    }
}

