"""AsyncAPI component schema export: discover named schemas, guard cyclic internal refs, and emit a deterministic Draft 07 bundle."""

node ApiDocument {
    has source_uri: str = "";
    has spec_version: str = "";
}

node ComponentSchema {
    has name: str = "";
    has authored_id: str = "";
    has schema_format: str = "";
    has description: str = "";
    has is_boolean: bool = False;
    has boolean_value: bool = True;
    has parser_metadata: bool = False;
}

edge Defines { }

edge RefersTo {
    has ref_pointer: str = "";
}

walker SchemaBundler {
    has collected: list[str] = [];
    has seen_ids: list[str] = [];
    has stripped: int = 0;
    has errors: list[str] = [];

    can start with Root entry {
        print("Bundling components.schemas for JSON Schema Draft 07 export");
        visit [-->];
    }

    can scan with ApiDocument entry {
        print(f"Source snapshot: {here.source_uri} (AsyncAPI {here.spec_version})");
        visit [->:Defines:->] else { disengage; };
    }

    can collect with ComponentSchema entry {
        if here.parser_metadata {
            self.stripped += 1;
        }
        if here.authored_id != "" {
            if here.authored_id in self.seen_ids {
                self.errors.append(
                    f"duplicate $id {here.authored_id} on component {here.name}"
                );
            } else {
                self.seen_ids.append(here.authored_id);
            }
        }
        if here.name not in self.collected {
            self.collected.append(here.name);
        }
        disengage;
    }

    def report() {
        ordered = sorted(self.collected);
        print("");
        print(f"Validated bundle — {len(ordered)} component schema(s)");
        print(f"Parser metadata fields stripped from {self.stripped} schema(s)");
        if self.errors {
            for err in self.errors {
                print(f"ERROR: {err}");
            }
        }
        print("definitions (deterministic byte order):");
        for name in ordered {
            kind = "boolean" if name == "EnabledFlag" else "object";
            print(f"  \"{name}\" ({kind})");
        }
        print("(inline message payloads excluded — not in components.schemas)");
    }
}

walker RefAuditor {
    has visiting: list[str] = [];
    has guarded: int = 0;

    can start with ComponentSchema entry {
        self.visiting.append(here.name);
        visit [->:RefersTo:->] else { disengage; };
    }

    can follow with ComponentSchema entry {
        if here.name in self.visiting {
            self.guarded += 1;
            print(f"  cycle guard: stopped at internal $ref to {here.name}");
            disengage;
        }
        self.visiting.append(here.name);
        visit [->:RefersTo:->] else { disengage; };
    }
}

with entry {
    doc = ApiDocument(
        source_uri="file:///pets.asyncapi.yaml",
        spec_version="3.1.0"
    );
    user = ComponentSchema(
        name="User",
        authored_id="https://example.com/schemas/user",
        schema_format="application/schema+json;version=draft-07",
        description="Pet owner"
    );
    address = ComponentSchema(
        name="Address",
        authored_id="https://example.com/schemas/address",
        description="Postal address"
    );
    order = ComponentSchema(
        name="Order",
        authored_id="https://example.com/schemas/order",
        description="Placed order"
    );
    enabled = ComponentSchema(
        name="EnabledFlag",
        is_boolean=True,
        boolean_value=True
    );
    unused = ComponentSchema(
        name="UnusedWidget",
        description="Unused but still exported"
    );
    leaky = ComponentSchema(
        name="LegacyShape",
        parser_metadata=True,
        description="Carries x-parser-* metadata in parser output"
    );

    root ++> doc;
    doc +>:Defines:+> user;
    doc +>:Defines:+> address;
    doc +>:Defines:+> order;
    doc +>:Defines:+> enabled;
    doc +>:Defines:+> unused;
    doc +>:Defines:+> leaky;

    order +>:RefersTo(ref_pointer="#/components/schemas/User"):+> user;
    order +>:RefersTo(ref_pointer="#/components/schemas/Address"):+> address;
    user +>:RefersTo(ref_pointer="#/components/schemas/User"):+> user;

    bundler = SchemaBundler();
    root spawn bundler;
    bundler.report();

    print("");
    print("Auditing internal $ref graphs (bundle, not dereference):");
    order_auditor = RefAuditor();
    order spawn order_auditor;
    user_auditor = RefAuditor();
    user spawn user_auditor;
    print(f"Order graph cycle guards: {order_auditor.guarded}");
    print(f"User self-ref cycle guards: {user_auditor.guarded}");
}

"""2+1 CDT orchestration: typed proposal telemetry, density audit, and checkpoint resume."""

node CdtState {
    has state_id: str = "";
    has num_simplices: int = 0;
    has spatial_volume: float = 0.0;
    has offered_sites: int = 0;
}

node ProposalRecord {
    has transition_id: int = 0;
    has chain_id: int = 0;
    has selected_family: str = "";
    has reverse_family: str = "";
    has forward_prob: float = 0.0;
    has reverse_prob: float = 0.0;
    has forward_log_q: float = 0.0;
    has reverse_log_q: float = 0.0;
    has action_delta: float = 0.0;
    has volume_delta: float = 0.0;
    has outcome: str = "";
    has accepted: bool = False;
}

node VersionedCheckpoint {
    has schema_version: str = "2.1";
    has chunk_index: int = 0;
    has topology_version: str = "2plus1-v3";
    has move_contract_version: str = "mc-v2";
    has rng_seed: int = 0;
    has digest: str = "";
}

node InjectedPolicy {
    has policy_name: str = "";
    has is_learned: bool = False;
    has dimension: str = "2+1";
}

edge AppliesTo { }
edge Binds { }

walker TransitionRunner {
    has proposals_logged: int = 0;
    has policy_eval_ms: int = 0;

    can start with Root entry {
        print("=== 2+1 shared CDT boundary: conventional and learned share surface ===");
        visit [-->];
    }

    can inject_policy with InjectedPolicy entry {
        kind = "learned" if here.is_learned else "conventional";
        print(f"injected {kind} policy '{here.policy_name}' ({here.dimension})");
        visit [->:AppliesTo:->] else { visit [-->]; };
    }

    can observe_state with CdtState entry {
        print(f"state {here.state_id}: simplices={here.num_simplices} "
              f"vol={here.spatial_volume} offered={here.offered_sites}");
        visit [-->];
    }

    can emit_telemetry with ProposalRecord entry {
        mh_label = "accepted" if here.accepted else here.outcome;
        print(f"  proposal t{here.transition_id} chain={here.chain_id} "
              f"{here.selected_family}<->{here.reverse_family} "
              f"p_fwd={here.forward_prob} p_rev={here.reverse_prob} "
              f"log_q_f={here.forward_log_q} log_q_r={here.reverse_log_q} "
              f"dS={here.action_delta} dV={here.volume_delta} -> {mh_label}");
        self.proposals_logged += 1;
        self.policy_eval_ms += 2;
        visit [-->];
    }

    can flush_chunk with VersionedCheckpoint entry {
        print(f"chunk {here.chunk_index} sealed "
              f"schema={here.schema_version} topo={here.topology_version} "
              f"move={here.move_contract_version} digest={here.digest}");
        print(f"telemetry flushed: {self.proposals_logged} records, "
              f"policy_eval={self.policy_eval_ms}ms (serialization excluded)");
        disengage;
    }
}

walker DensityAuditor {
    has q_checks_passed: int = 0;

    can start with Root entry {
        print("--- asymmetric-policy forward/reverse q audit ---");
        visit [-->];
    }

    can skip with InjectedPolicy | CdtState | VersionedCheckpoint entry {
        visit [-->];
    }

    can audit_q with ProposalRecord entry {
        reversible = here.selected_family != here.reverse_family;
        balance = here.forward_log_q + here.reverse_log_q;
        ok = True if not reversible else abs(balance) < 0.15;
        verdict = "PASS" if ok else "FAIL";
        print(f"  audit t{here.transition_id}: "
              f"q_fwd+q_rev={balance:.3f} {verdict}");
        if ok {
            self.q_checks_passed += 1;
        }
        visit [-->];
    }
}

walker ResumeProbe {
    has resumed_state_id: str = "";

    can start with VersionedCheckpoint entry {
        print(f"--- checkpoint round-trip seed={here.rng_seed} "
              f"chunk={here.chunk_index} ---");
        visit [<-:Binds:--] else { disengage; };
    }

    can continue_from with CdtState entry {
        self.resumed_state_id = here.state_id;
        print(f"deterministic resume at {here.state_id} "
              f"(simplices={here.num_simplices}, sites={here.offered_sites})");
        disengage;
    }
}

