"""Homelab service mesh: dependency graph traversal, cycle detection, topo startup order, and health cascade invalidation."""

node Service {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

edge DependsOn { }

walker CycleDetector {
    has path: list[str] = [];
    has found_cycle: bool = False;
    has cycle_at: str = "";

    can start with Root entry {
        print("scanning dependency graph for cycles");
        visit [-->];
    }

    can probe with Service entry {
        if self.found_cycle {
            disengage;
        }
        name = here.title;
        if name in self.path {
            self.found_cycle = True;
            self.cycle_at = name;
            disengage;
        }
        self.path.append(name);
        visit [->:DependsOn:->] else {
            visit [-->] else { disengage; };
        };
        self.path.pop();
        visit [-->] else { disengage; };
    }
}

walker StartupPlanner {
    has visited: list[str] = [];
    has startup_order: list[str] = [];

    can start with Root entry {
        print("planning startup order (deps before dependents)");
        visit [-->];
    }

    can plan with Service entry {
        name = here.title;
        if name in self.visited {
            visit [-->] else { disengage; };
        }
        self.visited.append(name);
        visit [->:DependsOn:->] else { disengage; };
        self.startup_order.append(name);
        visit [-->] else { disengage; };
    }
}

walker HealthCascade {
    has invalidated: list[str] = [];
    has visited: list[str] = [];
    has from_cascade: bool = False;

    can start with Root entry {
        print("cascading health failure through dependents");
        visit [-->];
    }

    can cascade with Service entry {
        name = here.title;
        if name in self.visited {
            visit [-->] else { disengage; };
        }
        self.visited.append(name);
        should_fail = not here.available or self.from_cascade;
        self.from_cascade = False;
        if should_fail {
            here.available = False;
            self.invalidated.append(name);
            self.from_cascade = True;
            visit [<-:DependsOn:<-] else {
                self.from_cascade = False;
                visit [-->] else { disengage; };
            };
            self.from_cascade = False;
        } else {
            visit [-->] else { disengage; };
        }
    }
}

with entry {
    db = Service(title="database", available=False);
    cache = Service(title="cache");
    api = Service(title="api");
    web = Service(title="web");
    nginx = Service(title="nginx");

    root ++> db ++> cache ++> api ++> web ++> nginx;

    api +>:DependsOn:+> db;
    cache +>:DependsOn:+> api;
    api +>:DependsOn:+> cache;
    web +>:DependsOn:+> api;
    nginx +>:DependsOn:+> web;

    detector = CycleDetector();
    root spawn detector;
    cycle_msg = f"cycle detected at {detector.cycle_at}" if detector.found_cycle else "no cycle found";
    print(cycle_msg);

    planner = StartupPlanner();
    root spawn planner;
    print(f"startup order: {planner.startup_order}");

    cascade = HealthCascade();
    root spawn cascade;
    print(f"invalidated services: {cascade.invalidated}");
}

"""Governed sub-model analysis: delegate immutable derived views to helper models under budget, lineage, and admission control."""

node Traceable {
    has trace_id: str = "";

    def checkpoint_label() -> str {
        return self.trace_id;
    }
}

node SourceRef {
    has name: str = "";
    has revision: str = "";
}

node DerivedView {
    has view_hash: str = "";
    has filter_desc: str = "";
    has snapshot_pin: bool = True;
}

node AnalysisRequest(Traceable) {
    has purpose: str = "";
    has prompt_hash: str = "";
    has model_route: str = "";
    has token_budget: int = 500;
    has cost_budget: int = 50;

    override def checkpoint_label() -> str {
        return f"request:{self.purpose}";
    }
}

node CallResult(Traceable) {
    has response_hash: str = "";
    has tokens_used: int = 0;
    has cost_used: int = 0;
    has admitted: bool = False;
    has screen_note: str = "";

    override def checkpoint_label() -> str {
        return f"result:{self.response_hash}";
    }
}

edge DerivedFrom {
    has pinned_at: str = "";
}

edge DelegatesTo {
    has call_id: str = "";
}

edge Produces { }

edge LineageLink {
    has delegate_depth: int = 0;
}

walker DelegationGovernor {
    has depth: int = 0;
    has total_tokens: int = 0;
    has total_cost: int = 0;
    has max_depth: int = 2;
    has max_tokens: int = 800;
    has max_cost: int = 80;
    has lineage_seen: list[str] = [];
    has ledger: list[str] = [];

    can start with Root entry {
        print("Governor: sweep derived views for governed helper delegation");
        visit [-->];
    }

    can inspect_source with SourceRef entry {
        self.ledger += [f"source={here.name} rev={here.revision}"];
        visit [->:DerivedFrom:->];
    }

    can inspect_view with DerivedView entry {
        if here.view_hash in self.lineage_seen {
            print(f"CYCLE_FAIL: view hash {here.view_hash} already in lineage");
            disengage;
        }
        self.lineage_seen += [here.view_hash];
        self.ledger += [f"view={here.view_hash}:{here.filter_desc}"];
        visit [->:DelegatesTo:->];
    }

    can route_request with AnalysisRequest entry {
        print(f"  checkpoint {here.checkpoint_label()} at depth {self.depth}");
        next_depth = self.depth + 1;
        if next_depth > self.max_depth {
            print(f"BUDGET_FAIL: depth {next_depth} exceeds max {self.max_depth} for {here.purpose}");
            disengage;
        }
        self.depth = next_depth;
        self.ledger += [
            f"delegate purpose={here.purpose} model={here.model_route} "
            f"prompt={here.prompt_hash} call={here.trace_id}"
        ];
        visit [->:Produces:->] else {
            print(f"delegate {here.trace_id} produced no helper result");
            disengage;
        }
    }

    can screen_result with CallResult entry {
        print(f"  checkpoint {here.checkpoint_label()} at depth {self.depth}");
        projected_tokens = self.total_tokens + here.tokens_used;
        projected_cost = self.total_cost + here.cost_used;
        fail_note = "";

        if projected_tokens > self.max_tokens {
            fail_note = f"token budget exceeded ({projected_tokens}>{self.max_tokens})";
        } else {
            if projected_cost > self.max_cost {
                fail_note = f"cost budget exceeded ({projected_cost}>{self.max_cost})";
            } else {
                if here.response_hash.startswith("INJECT") {
                    fail_note = "injection-shaped output quarantined";
                }
            }
        }

        if fail_note != "" {
            here.admitted = False;
            here.screen_note = fail_note;
            print(f"ADMISSION_FAIL: {here.screen_note}");
            self.ledger += [f"result={here.response_hash} admitted=False reason={fail_note}"];
            disengage;
        }

        here.admitted = True;
        here.screen_note = "passed admission floor";
        self.total_tokens = projected_tokens;
        self.total_cost = projected_cost;
        print(f"ADMITTED result {here.response_hash} (tokens={here.tokens_used} cost={here.cost_used})");
        self.ledger += [f"result={here.response_hash} admitted=True"];
        visit [->:LineageLink:->];
    }
}

walker LineageAuditor {
    has chain: list[str] = [];

    can start with CallResult entry {
        self.chain += [f"result:{here.response_hash}"];
        visit [<--:Produces:--] else {
            disengage;
        }
    }

    can trace_request with AnalysisRequest entry {
        self.chain += [f"delegate:{here.purpose}:{here.trace_id}"];
        visit [<--:DelegatesTo:--] else {
            disengage;
        }
    }

    can trace_view with DerivedView entry {
        self.chain += [f"view:{here.view_hash}"];
        visit [<--:DerivedFrom:--] else {
            disengage;
        }
    }

    can trace_source with SourceRef entry {
        self.chain += [f"source:{here.name} rev={here.revision}"];
        print("LineageAuditor: root-to-result chain");
        for link in self.chain {
            print(f"  {link}");
        }
        disengage;
    }
}

with entry {
