"""Upstream subgraph at definition granularity: quotient leaf NodeSpecs by scope and path root."""

node LeafSpec {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has scope: str = "";
    has path_root: str = "";
    has kind: str = "";
    has leaf_name: str = "";
    has user_metadata: str = "";
    has compute_time_s: float = 0.0;

    def def_key() -> str {
        return f"{self.scope}::{self.kind}::{self.path_root}";
    }

    def leaf_id() -> str {
        return f"{self.def_key()}#{self.leaf_name}";
    }
}

edge DependsOn { }

walker UpstreamQuotient {
    has target_key: str = "";
    has walked_leaves: list[str] = [];
    has def_keys: list[str] = [];
    has def_edges: list[str] = [];
    has metadata_by_key: list[str] = [];
    has compute_by_key: list[float] = [];
    has child_def: str = "";
    has total_compute_s: float = 0.0;

    def contains(items: list[str], needle: str) -> bool {
        for item in items {
            if item == needle {
                return True;
            }
        }
        return False;
    }

    def index_of(items: list[str], needle: str) -> int {
        for (i, item) in enumerate(items) {
            if item == needle {
                return i;
            }
        }
        return -1;
    }

    def note_def(leaf: LeafSpec) -> None {
        key = leaf.def_key();
        if not self.contains(self.def_keys, key) {
            self.def_keys.append(key);
            self.metadata_by_key.append(leaf.user_metadata);
            self.compute_by_key.append(leaf.compute_time_s);
            self.total_compute_s += leaf.compute_time_s;
            print(f"  + {key}  metadata={leaf.user_metadata}  ({leaf.compute_time_s}s)");
        }
    }

    def note_edge(upstream: str, downstream: str) -> None {
        if upstream == downstream {
            return;
        }
        label = f"{upstream} -> {downstream}";
        if not self.contains(self.def_edges, label) {
            self.def_edges.append(label);
        }
    }

    can start with Root entry {
        print(f"Upstream subgraph for target {self.target_key}:");
        visit [-->] else { disengage; };
    }

    can seek with LeafSpec entry {
        if here.def_key() == self.target_key {
            self.note_def(here);
            self.child_def = here.def_key();
            lid = here.leaf_id();
            if not self.contains(self.walked_leaves, lid) {
                self.walked_leaves.append(lid);
            }
            visit [<--:DependsOn:--] else { disengage; };
        } else {
            visit [-->] else { disengage; };
        }
    }

    can climb with LeafSpec entry {
        upstream = here.def_key();
        self.note_edge(upstream, self.child_def);
        self.note_def(here);
        lid = here.leaf_id();
        if self.contains(self.walked_leaves, lid) {
            disengage;
        }
        self.walked_leaves.append(lid);
        prior_child = self.child_def;
        self.child_def = upstream;
        visit [<--:DependsOn:--] else { disengage; };
        self.child_def = prior_child;
    }

    can finish with Root exit {
        print(f"Definition nodes ({len(self.def_keys)}):");
        for (i, key) in enumerate(self.def_keys) {
            meta = self.metadata_by_key[i];
            secs = self.compute_by_key[i];
            print(f"    {key}  [{meta}, {secs}s]");
        }
        print(f"Definition edges ({len(self.def_edges)}):");
        for edge_label in self.def_edges {
            print(f"    {edge_label}");
        }
        print(f"Set-aggregate compute_time_s = {self.total_compute_s}s (each definition counted once)");
    }
}

