        user_metadata="branch_a", compute_time_s=3.0
    );
    calc_b_out1 = LeafSpec(
        scope="main", kind="@", path_root="calc_b", leaf_name="out1",
        user_metadata="branch_b", compute_time_s=2.5
    );
    cross_out = LeafSpec(
        scope="lib", kind="@", path_root="imported", leaf_name="out",
        user_metadata="cross_scope", compute_time_s=0.5
    );
    verif_in1 = LeafSpec(
        scope="main", kind="?", path_root="verif", leaf_name="in1",
        user_metadata="target_verif", compute_time_s=0.25
    );
    verif_in2 = LeafSpec(
        scope="main", kind="?", path_root="verif", leaf_name="in2",
        user_metadata="target_verif", compute_time_s=0.25
    );

    calc_a_out1 +>:DependsOn:+> model_out1;
    calc_a_out1 +>:DependsOn:+> shared_out;
    calc_a_out2 +>:DependsOn:+> model_out1;
    calc_b_out1 +>:DependsOn:+> model_out2;
    calc_b_out1 +>:DependsOn:+> shared_out;
    verif_in1 +>:DependsOn:+> calc_a_out1;
    verif_in1 +>:DependsOn:+> calc_b_out1;
    verif_in1 +>:DependsOn:+> cross_out;
    verif_in2 +>:DependsOn:+> calc_a_out2;

    root ++> model_out1
        ++> model_out2
        ++> shared_out
        ++> calc_a_out1
        ++> calc_a_out2
        ++> calc_b_out1
        ++> cross_out
        ++> verif_in1
        ++> verif_in2;

    root spawn UpstreamQuotient(target_key="main::?::verif");
}

"""Governed sub-model analysis: delegate immutable derived views to helper models under budget, lineage, and admission control."""

node Traceable {
    has trace_id: str = "";

    def checkpoint_label() -> str {
        return self.trace_id;
    }
}

node SourceRef {
    has name: str = "";
    has revision: str = "";
}

node DerivedView {
    has view_hash: str = "";
    has filter_desc: str = "";
    has snapshot_pin: bool = True;
}

node AnalysisRequest(Traceable) {
    has purpose: str = "";
    has prompt_hash: str = "";
    has model_route: str = "";
    has token_budget: int = 500;
    has cost_budget: int = 50;

    override def checkpoint_label() -> str {
        return f"request:{self.purpose}";
    }
}

node CallResult(Traceable) {
    has response_hash: str = "";
    has tokens_used: int = 0;
    has cost_used: int = 0;
    has admitted: bool = False;
    has screen_note: str = "";

    override def checkpoint_label() -> str {
        return f"result:{self.response_hash}";
    }
}

edge DerivedFrom {
    has pinned_at: str = "";
}

edge DelegatesTo {
    has call_id: str = "";
}

edge Produces { }

edge LineageLink {
    has delegate_depth: int = 0;
}

walker DelegationGovernor {
    has depth: int = 0;
    has total_tokens: int = 0;
    has total_cost: int = 0;
    has max_depth: int = 2;
    has max_tokens: int = 800;
    has max_cost: int = 80;
    has lineage_seen: list[str] = [];
    has ledger: list[str] = [];

    can start with Root entry {
        print("Governor: sweep derived views for governed helper delegation");
        visit [-->];
    }

    can inspect_source with SourceRef entry {
        self.ledger += [f"source={here.name} rev={here.revision}"];
        visit [->:DerivedFrom:->];
    }

    can inspect_view with DerivedView entry {
        if here.view_hash in self.lineage_seen {
            print(f"CYCLE_FAIL: view hash {here.view_hash} already in lineage");
            disengage;
        }
        self.lineage_seen += [here.view_hash];
        self.ledger += [f"view={here.view_hash}:{here.filter_desc}"];
        visit [->:DelegatesTo:->];
    }

    can route_request with AnalysisRequest entry {
        print(f"  checkpoint {here.checkpoint_label()} at depth {self.depth}");
        next_depth = self.depth + 1;
        if next_depth > self.max_depth {
            print(f"BUDGET_FAIL: depth {next_depth} exceeds max {self.max_depth} for {here.purpose}");
            disengage;
        }
        self.depth = next_depth;
        self.ledger += [
            f"delegate purpose={here.purpose} model={here.model_route} "
            f"prompt={here.prompt_hash} call={here.trace_id}"
        ];
        visit [->:Produces:->] else {
            print(f"delegate {here.trace_id} produced no helper result");
            disengage;
        };
    }

    can screen_result with CallResult entry {
        print(f"  checkpoint {here.checkpoint_label()} at depth {self.depth}");
        projected_tokens = self.total_tokens + here.tokens_used;
        projected_cost = self.total_cost + here.cost_used;
        fail_note = "";

        if projected_tokens > self.max_tokens {
            fail_note = f"token budget exceeded ({projected_tokens} over max {self.max_tokens})";
        } else {
            if projected_cost > self.max_cost {
                fail_note = f"cost budget exceeded ({projected_cost} over max {self.max_cost})";
            } else {
                if here.response_hash.startswith("INJECT") {
                    fail_note = "injection-shaped output quarantined";
                }
            }
        }

        if fail_note != "" {
            here.admitted = False;
            here.screen_note = fail_note;
            print(f"ADMISSION_FAIL: {here.screen_note}");
            self.ledger += [f"result={here.response_hash} admitted=False reason={fail_note}"];
            disengage;
        }

        here.admitted = True;
        here.screen_note = "passed admission floor";
        self.total_tokens = projected_tokens;
        self.total_cost = projected_cost;
        print(f"ADMITTED result {here.response_hash} (tokens={here.tokens_used} cost={here.cost_used})");
        self.ledger += [f"result={here.response_hash} admitted=True"];
        visit [->:LineageLink:->];
    }
}

walker LineageAuditor {
    has chain: list[str] = [];

    can start with CallResult entry {
        self.chain += [f"result:{here.response_hash}"];
        visit [<--:Produces:<--] else {
            disengage;
        };
    }

    can trace_request with AnalysisRequest entry {
        self.chain += [f"delegate:{here.purpose}:{here.trace_id}"];
        visit [<--:DelegatesTo:<--] else {
            disengage;
        };
    }

    can trace_view with DerivedView entry {
        self.chain += [f"view:{here.view_hash}"];
        visit [<--:DerivedFrom:<--] else {
            disengage;
        };
    }

    can trace_source with SourceRef entry {
        self.chain += [f"source:{here.name} rev={here.revision}"];
        print("LineageAuditor: root-to-result chain");
        for link in self.chain {
            print(f"  {link}");
        }
        disengage;
    }
}

