"""Essay scoring calibration: traverse sparse rating designs and validate rater fit."""

node EssayPrompt {
    has title: str = "";
    has task_difficulty: float = 0.0;
}

node EssaySubmission {
    has essay_id: str = "";
    has word_count: int = 0;
    has subgroup: str = "";
}

node RubricCriterion {
    has name: str = "";
    has trait: str = "";
}

node Rating {
    has score: int = 0;
    has confidence: float = 1.0;
}

node Rater {
    has rater_id: str = "";
    has family: str = "";
    has severity: float = 0.0;
    has subgroup_bias: float = 0.0;
    has min_given: int = 6;
    has max_given: int = 1;
    has total_given: int = 0;

    def absorb(score: int) {
        if self.total_given == 0 {
            self.min_given = score;
            self.max_given = score;
        } else {
            if score < self.min_given {
                self.min_given = score;
            }
            if score > self.max_given {
                self.max_given = score;
            }
        }
        self.total_given += 1;
    }

    def is_severe() -> bool {
        return self.severity > 1.2;
    }

    def is_compressed() -> bool {
        if self.total_given < 2 {
            return False;
        }
        span = self.max_given - self.min_given;
        return span < 2;
    }
}

edge ForPrompt { }
edge HasRating { }
edge ScoredBy { }
edge OnCriterion { }

walker CalibrationOrchestrator {
    has visited_essays: list[str] = [];
    has rating_count: int = 0;
    has gaps_found: int = 0;
    has pending_score: int = 0;

    can start with Root entry {
        print("=== Calibration: walking sparse rating design ===");
        visit [-->];
    }

    can open_prompt with EssayPrompt entry {
        print(f"Prompt [{here.title}] difficulty={here.task_difficulty}");
        visit [->:ForPrompt:->] else {
            self.gaps_found += 1;
            print("  [GAP] prompt has no linked essays");
        }
        visit [-->];
    }

    can walk_essay with EssaySubmission entry {
        if here.essay_id in self.visited_essays {
            disengage;
        }
        self.visited_essays.append(here.essay_id);
        print(f"  Essay {here.essay_id} ({here.word_count} words, {here.subgroup})");
        visit [->:HasRating:->] else {
            self.gaps_found += 1;
            print("    [GAP] essay lacks ratings");
        }
    }

    can tally with Rating entry {
        self.rating_count += 1;
        self.pending_score = here.score;
        visit [->:OnCriterion:->];
        visit [->:ScoredBy:->] else {
            self.gaps_found += 1;
            print(f"    [GAP] rating {here.score} has no rater");
        }
    }

    can label_criterion with RubricCriterion entry {
        print(f"    -> {here.name} ({here.trait})");
        disengage;
    }

    can bind_rater with Rater entry {
        here.absorb(self.pending_score);
        print(f"    score {self.pending_score} rater={here.rater_id} ({here.family})");
        disengage;
    }

    can close with Root exit {
        status = "CONNECTED" if self.gaps_found == 0 else "DISCONNECTED";
        print(f"Design {status}: {self.rating_count} ratings, "
              f"{len(self.visited_essays)} essays, gaps={self.gaps_found}");
    }
}

walker ValidationAuditor {
    has current_wc: int = 0;
    has current_subgroup: str = "";
    has length_pairs: list[tuple[int, int]] = [];
    has flag_count: int = 0;

    can start with Root entry {
        print("\n=== Validation: rater fit and shortcut checks ===");
        visit [-->];
    }

    can audit_prompt with EssayPrompt entry {
        visit [->:ForPrompt:->] else {
            disengage;
        }
        visit [-->];
    }

    can audit_essay with EssaySubmission entry {
        self.current_wc = here.word_count;
        self.current_subgroup = here.subgroup;
        visit [->:HasRating:->] else {
            disengage;
        }
    }

    can check_rating with Rating entry {
        self.length_pairs.append((self.current_wc, here.score));
        visit [->:ScoredBy:->];
    }

    can diagnose with Rater entry {
        if here.is_severe() {
            self.flag_count += 1;
            print(f"[FLAG] SEVERE rater {here.rater_id} severity={here.severity}");
        }
        if here.is_compressed() {
            self.flag_count += 1;
            span = here.max_given - here.min_given;
            print(f"[FLAG] RANGE-COMPRESSED rater {here.rater_id} span={span}");
        }
        if abs(here.subgroup_bias) > 0.8 {
            self.flag_count += 1;
            print(f"[FLAG] SUBGROUP-BIASED rater {here.rater_id} bias={here.subgroup_bias}");
        }
        disengage;
    }

    can finish with Root exit {
        high_scores: list[int] = [];
        low_scores: list[int] = [];
        for (wc, sc) in self.length_pairs {
            if wc >= 400 {
                high_scores.append(sc);
            } else {
                low_scores.append(sc);
            }
        }
        if len(high_scores) > 0 and len(low_scores) > 0 {
            high_sum: int = 0;
            for s in high_scores {
                high_sum += s;
            }
            low_sum: int = 0;
            for s in low_scores {
                low_sum += s;
            }
            high_avg = high_sum / len(high_scores);
            low_avg = low_sum / len(low_scores);
            delta = high_avg - low_avg;
            if delta >= 2.0 {
                self.flag_count += 1;
                print(f"[FLAG] LENGTH-SHORTCUT dependence (avg delta={delta})");
            }
        }
        print(f"Validation complete: {self.flag_count} flags raised");
    }
}

