"""2+1 CDT orchestration: typed proposal telemetry, density audit, and checkpoint resume."""

node CdtState {
    has state_id: str = "";
    has num_simplices: int = 0;
    has spatial_volume: float = 0.0;
    has offered_sites: int = 0;
}

node ProposalRecord {
    has transition_id: int = 0;
    has chain_id: int = 0;
    has selected_family: str = "";
    has reverse_family: str = "";
    has forward_prob: float = 0.0;
    has reverse_prob: float = 0.0;
    has forward_log_q: float = 0.0;
    has reverse_log_q: float = 0.0;
    has action_delta: float = 0.0;
    has volume_delta: float = 0.0;
    has outcome: str = "";
    has accepted: bool = False;
}

node VersionedCheckpoint {
    has schema_version: str = "2.1";
    has chunk_index: int = 0;
    has topology_version: str = "2plus1-v3";
    has move_contract_version: str = "mc-v2";
    has rng_seed: int = 0;
    has digest: str = "";
}

node InjectedPolicy {
    has policy_name: str = "";
    has is_learned: bool = False;
    has dimension: str = "2+1";
}

edge AppliesTo { }
edge Binds { }

walker TransitionRunner {
    has proposals_logged: int = 0;
    has policy_eval_ms: int = 0;

    can start with Root entry {
        print("=== 2+1 shared CDT boundary: conventional and learned share surface ===");
        visit [-->];
    }

    can inject_policy with InjectedPolicy entry {
        kind = "learned" if here.is_learned else "conventional";
        print(f"injected {kind} policy '{here.policy_name}' ({here.dimension})");
        visit [->:AppliesTo:->] else { visit [-->]; };
    }

    can observe_state with CdtState entry {
        print(f"state {here.state_id}: simplices={here.num_simplices} "
              f"vol={here.spatial_volume} offered={here.offered_sites}");
        visit [-->];
    }

    can emit_telemetry with ProposalRecord entry {
        mh_label = "accepted" if here.accepted else here.outcome;
        family_pair = f"{here.selected_family} <-> {here.reverse_family}";
        print(f"  proposal t{here.transition_id} chain={here.chain_id} "
              f"{family_pair} "
              f"p_fwd={here.forward_prob} p_rev={here.reverse_prob} "
              f"log_q_f={here.forward_log_q} log_q_r={here.reverse_log_q} "
              f"dS={here.action_delta} dV={here.volume_delta} -> {mh_label}");
        self.proposals_logged += 1;
        self.policy_eval_ms += 2;
        visit [-->];
    }

    can flush_chunk with VersionedCheckpoint entry {
        print(f"chunk {here.chunk_index} sealed "
              f"schema={here.schema_version} topo={here.topology_version} "
              f"move={here.move_contract_version} digest={here.digest}");
        print(f"telemetry flushed: {self.proposals_logged} records, "
              f"policy_eval={self.policy_eval_ms}ms (serialization excluded)");
        disengage;
    }
}

walker DensityAuditor {
    has q_checks_passed: int = 0;

    can start with Root entry {
        print("--- asymmetric-policy forward/reverse q audit ---");
        visit [-->];
    }

    can skip with InjectedPolicy | CdtState | VersionedCheckpoint entry {
        visit [-->];
    }

    can audit_q with ProposalRecord entry {
        reversible = here.selected_family != here.reverse_family;
        balance = here.forward_log_q + here.reverse_log_q;
        bal_sq = balance * balance;
        ok = True if not reversible else bal_sq < 0.0225;
        verdict = "PASS" if ok else "FAIL";
        balance_text = f"{balance:.3f}";
        print(f"  audit t{here.transition_id}: "
              f"q_fwd+q_rev={balance_text} {verdict}");
        if ok {
            self.q_checks_passed += 1;
        }
        visit [-->];
    }
}

walker ResumeProbe {
    has resumed_state_id: str = "";

    can start with VersionedCheckpoint entry {
        print(f"--- checkpoint round-trip seed={here.rng_seed} "
              f"chunk={here.chunk_index} ---");
        visit [<-:Binds:<-] else { disengage; };
    }

    can continue_from with CdtState entry {
        self.resumed_state_id = here.state_id;
        print(f"deterministic resume at {here.state_id} "
              f"(simplices={here.num_simplices}, sites={here.offered_sites})");
        disengage;
    }
}

with entry {
    conv = InjectedPolicy(
        policy_name="uniform-2plus1-families",
        is_learned=False,
        dimension="2+1"
    );
    s0 = CdtState(state_id="S0", num_simplices=120, spatial_volume=48.5, offered_sites=8);
    p0 = ProposalRecord(
        transition_id=1, chain_id=0,
        selected_family="add_simplex", reverse_family="remove_simplex",
        forward_prob=0.25, reverse_prob=0.25,
        forward_log_q=-2.08, reverse_log_q=-1.95,
        action_delta=-0.04, volume_delta=0.01,
        outcome="accepted", accepted=True
    );
    s1 = CdtState(state_id="S1", num_simplices=121, spatial_volume=48.6, offered_sites=9);
    p1 = ProposalRecord(
        transition_id=2, chain_id=0,
        selected_family="barycenter_p", reverse_family="barycenter_p",
        forward_prob=0.10, reverse_prob=0.10,
        forward_log_q=0.0, reverse_log_q=0.0,
        action_delta=0.01, volume_delta=0.0,
        outcome="ordinary-rejection", accepted=False
    );
    s2 = CdtState(state_id="S2", num_simplices=121, spatial_volume=48.6, offered_sites=9);
    p2 = ProposalRecord(
        transition_id=3, chain_id=0,
        selected_family="remove_simplex", reverse_family="add_simplex",
        forward_prob=0.25, reverse_prob=0.25,
        forward_log_q=-1.95, reverse_log_q=-2.08,
        action_delta=0.02, volume_delta=-0.01,
        outcome="post-validation", accepted=False
    );
    ckpt = VersionedCheckpoint(
        chunk_index=1, rng_seed=424242,
