"""Root Vex Operations: scoped roots, G01–G05 completion sequencing, and
dependency-aware traversal for whole-program visibility on Windows VexLife."""

node ScopedRoot {
    has scope_ref: str = "";
    has machine_scope: str = "";
    has state: str = "";
    has role: str = "";
}

node CompletionGroup {
    has group_id: str = "";
    has label: str = "";
    has completion_state: str = "";
    has memory_consolidated: bool = False;
    has model_weights_changed: bool = False;
    has candidate_trained: bool = False;
    has candidate_accepted: bool = False;
    has sync_available: bool = False;
    has sync_authorized: bool = False;
}

node Capability {
    has name: str = "";
    has status: str = "";
    has layer: str = "";
}

node AdmissionRecord {
    has admission_ref: str = "";
    has recorded_at: str = "";
    has event_kind: str = "";
}

edge ParentOf {
    has relation: str = "subordinate";
}

edge SiblingOf {
    has bound_at: str = "";
}

edge SequencesTo {
    has ordering: str = "strict";
}

edge DependsOn {
    has required: bool = True;
}

edge AdmittedTo {
    has admitted: bool = True;
}

walker ScopeNavigator {
    has visited_refs: list[str] = [];
    has lines: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can survey with ScopedRoot entry {
        if here.scope_ref in self.visited_refs {
            disengage;
        }
        self.visited_refs.append(here.scope_ref);
        self.lines.append(
            f"[SCOPE] {here.scope_ref} machine={here.machine_scope} "
            f"state={here.state}"
        );
        visit [->:ParentOf:->];
        visit [->:SiblingOf:->];
        visit [-->];
    }

    can report with Root exit {
        for line in self.lines {
            print(line);
        }
    }
}

walker CompletionAuditor {
    has visited_ids: list[str] = [];
    has violations: list[str] = [];
    has route: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can audit with CompletionGroup entry {
        if here.group_id in self.visited_ids {
            self.violations.append(
                f"cycle at {here.group_id} — sequencing must not collapse"
            );
            disengage;
        }
        self.visited_ids.append(here.group_id);
        self.route.append(here.group_id);

        if here.memory_consolidated and here.model_weights_changed {
            self.violations.append(
                f"{here.group_id}: memoryConsolidated must not imply "
                f"modelWeightsChanged"
            );
        }
        if here.candidate_trained and here.candidate_accepted {
            self.violations.append(
                f"{here.group_id}: candidateTrained must not imply "
                f"candidateAccepted"
            );
        }
        if here.sync_available and here.sync_authorized {
            self.violations.append(
                f"{here.group_id}: syncAvailable must not imply "
                f"synchronizationAuthorized"
            );
        }

        status = "DONE" if here.completion_state == "ACCEPTED" else "PENDING";
        print(
            f"[{status}] {here.group_id} {here.label} "
            f"({here.completion_state})"
        );
        visit [->:SequencesTo:->] else {
            disengage;
        }
    }

    can report with Root exit {
        route_text = " -> ".join(self.route);
        print(f"sequencing route: {route_text}");
        if self.violations {
            for v in self.violations {
                print(f"VIOLATION: {v}");
            }
