walker SemanticQuery {
    has query_proj: float = 0.0;
    has collecting: bool = False;
    has searching: bool = False;
    has allowed: dict[int, bool] = {};

    can start with Root entry {
        visit [-->[?:QueryVector]];
        visit [-->[?:StructuralFilter]];
        visit [-->[?:VectorIndex]] else { disengage; };
    }

    can load_query with QueryVector entry {
        self.query_proj = here.projection;
        print(f"query vector loaded: projection={self.query_proj}");
        visit [-->] else { disengage; };
    }

    can collect with StructuralFilter entry {
        print(f"structural filter: {here.title}");
        self.collecting = True;
        visit [->:Allowlisted:->];
        self.collecting = False;
        visit [-->] else { disengage; };
    }

    can search with VectorIndex entry {
        bits = here.quant_bits;
        print(f"dense index: {here.title} dim={here.year} quant={bits}bit");
        self.searching = True;
        visit [->:IndexedIn:->];
        self.searching = False;
        visit [-->] else { disengage; };
    }

    can rank with CodeSymbol entry {
        if self.collecting {
            self.allowed[here.year] = True;
            print(f"allowlisted candidate: {here.title} (id={here.year})");
        } else {
            if self.searching {
                if not self.allowed.get(here.year, False) {
                    print(f"filtered out: {here.title} (id={here.year})");
                } else {
                    dist = abs(here.projection - self.query_proj);
                    score = 1.0 - dist;
                    print(f"rerank [{score:.3f}] {here.title} (id={here.year})");
                }
            }
        }
        visit [-->] else { disengage; };
    }
}

