"""RBAC scoped permission: batched multi-seed ancestor resolution vs per-group N+1 PG round-trips."""

node AgentGroup {
    has name: str = "";
    has gid: str = "";
    has grants_scope: bool = False;
}

edge ParentOf { }

walker NaiveAncestorLookup {
    has member_gids: list[str] = [];
    has ancestor_gids: list[str] = [];
    has pg_round_trips: int = 0;
    has active_seed: str = "";
    has visited: list[str] = [];
    has hops: int = 0;
    has max_hops: int = 32;

    can start with Root entry {
        if not self.member_gids {
            disengage;
        }
        self.active_seed = self.member_gids[0];
        self.member_gids = self.member_gids[1:];
        self.pg_round_trips += 1;
        self.visited = [];
        self.hops = 0;
        visit [-->:AgentGroup:--];
    }

    can seed_entry with AgentGroup entry {
        if here.gid != self.active_seed {
            visit [-->] else { disengage; };
        }
        visit [<--:ParentOf:--] else {
            if self.member_gids {
                self.active_seed = self.member_gids[0];
                self.member_gids = self.member_gids[1:];
                self.pg_round_trips += 1;
                self.visited = [];
                self.hops = 0;
                visit [-->:AgentGroup:--];
            } else {
                disengage;
            }
        };
    }

    can climb with AgentGroup entry {
        if here.gid in self.visited {
            if self.member_gids {
                self.active_seed = self.member_gids[0];
                self.member_gids = self.member_gids[1:];
                self.pg_round_trips += 1;
                self.visited = [];
                self.hops = 0;
                visit [-->:AgentGroup:--];
            } else {
                disengage;
            }
        }
        if self.hops >= self.max_hops {
            disengage;
        }
        self.visited.append(here.gid);
        self.ancestor_gids.append(here.gid);
        self.hops += 1;
        visit [<--:ParentOf:--] else {
            if self.member_gids {
                self.active_seed = self.member_gids[0];
                self.member_gids = self.member_gids[1:];
                self.pg_round_trips += 1;
                self.visited = [];
                self.hops = 0;
                visit [-->:AgentGroup:--];
            } else {
                disengage;
            }
        };
    }
}

walker BatchedAncestorLookup {
    has member_gids: list[str] = [];
    has ancestor_gids: list[str] = [];
    has pg_round_trips: int = 1;
    has visited: list[str] = [];
    has frontier: list[str] = [];
    has hops: int = 0;
    has max_hops: int = 32;

    can start with Root entry {
        self.frontier = self.member_gids;
        visit [-->:AgentGroup:--];
    }

    can seed_wave with AgentGroup entry {
        if here.gid not in self.frontier {
            visit [-->] else { disengage; };
        }
        if here.gid in self.visited {
            visit [-->] else { disengage; };
        }
        self.visited.append(here.gid);
        visit [<--:ParentOf:--] else { visit [-->] else { disengage; }; };
    }

    can climb with AgentGroup entry {
        if here.gid in self.visited {
            visit [-->] else { disengage; };
        }
        if self.hops >= self.max_hops {
            disengage;
        }
        self.visited.append(here.gid);
        self.ancestor_gids.append(here.gid);
        visit [<--:ParentOf:--] else { visit [-->] else { disengage; }; };
    }

    can advance_wave with AgentGroup entry {
        visit [-->] else {
            if self.hops >= self.max_hops {
                disengage;
            }
            next_frontier: list[str] = [];
            for anc in self.ancestor_gids {
                if anc not in next_frontier {
                    next_frontier.append(anc);
                }
            }
            self.hops += 1;
            self.frontier = next_frontier;
            if not self.frontier {
                disengage;
            }
            visit [-->:AgentGroup:--];
        };
    }
}

walker ScopedPermissionCheck {
    has member_gids: list[str] = [];
    has ancestor_gids: list[str] = [];
    has pg_round_trips: int = 0;
    has granted: bool = False;
    has mode: str = "naive";

    can start with Root entry {
        if self.mode == "batched" {
            resolver = BatchedAncestorLookup(member_gids=self.member_gids);
            root spawn resolver;
            self.ancestor_gids = resolver.ancestor_gids;
            self.pg_round_trips = resolver.pg_round_trips;
        } else {
            resolver = NaiveAncestorLookup(member_gids=self.member_gids);
            root spawn resolver;
            self.ancestor_gids = resolver.ancestor_gids;
            self.pg_round_trips = resolver.pg_round_trips;
        }
        visit [-->:AgentGroup:--];
    }

    can audit with AgentGroup entry {
        if here.grants_scope {
            if here.gid in self.ancestor_gids {
                self.granted = True;
            }
            for seed in self.member_gids {
                if here.gid == seed {
                    self.granted = True;
                }
            }
        }
        visit [-->] else { disengage; };
    }
}

with entry {
    org = AgentGroup(name="Organization", gid="g-org", grants_scope=True);
    eng = AgentGroup(name="Engineering", gid="g-eng");
    backend = AgentGroup(name="Backend", gid="g-backend");
    frontend = AgentGroup(name="Frontend", gid="g-frontend");
    platform = AgentGroup(name="Platform", gid="g-platform");

    root ++> org;
    org +>:ParentOf:+> eng;
    eng +>:ParentOf:+> backend;
    eng +>:ParentOf:+> frontend;
    org +>:ParentOf:+> platform;

    operator_groups = ["g-backend", "g-frontend"];

    naive_check = ScopedPermissionCheck(
        member_gids=operator_groups,
        mode="naive"
    );
    root spawn naive_check;

    batched_check = ScopedPermissionCheck(
        member_gids=operator_groups,
        mode="batched"
    );
    root spawn batched_check;

    print(f"member groups: {operator_groups}");
    print(f"naive ancestors: {naive_check.ancestor_gids} "
          f"({naive_check.pg_round_trips} PG round-trips)");
    print(f"batched ancestors: {batched_check.ancestor_gids} "
          f"({batched_check.pg_round_trips} PG round-trip)");
    print(f"naive scoped permission granted: {naive_check.granted}");
    print(f"batched scoped permission granted: {batched_check.granted}");
}

