    }
}

"""Daily technical indicator pipeline: symbols, bars, pluggable defs, dependency-ordered backfill."""

node Symbol {
    has ticker: str = "";
    has symbol_id: int = 0;
}

node DailyBar {
    has bar_date: str = "";
    has close: float = 0.0;
    has volume: float = 0.0;
}

node IndicatorDef {
    has code: str = "";
    has version: int = 1;
    has window: int = 0;
    has active: bool = True;
    has display_name: str = "";
    has adjustment: str = "adjusted";

    def compute(close: float) -> float {
        return close * float(self.window) * 0.001;
    }
}

edge HasBar { }
edge DependsOn { has role: str = ""; }

walker DependencyAuditor {
    has plan: list[str] = [];
    has stack: list[str] = [];
    has has_cycle: bool = False;

    can audit with IndicatorDef entry {
        if here.code in self.stack {
            self.has_cycle = True;
            print(f"ERROR: dependency cycle at {here.code}");
            disengage;
        }
        self.stack.append(here.code);
        visit [->:DependsOn:->] else { }
        if len(self.stack) > 0 {
            self.stack = self.stack[: len(self.stack) - 1];
        }
        if here.code not in self.plan {
            self.plan.append(here.code);
        }
        visit [-->] else { disengage; }
    }
}

walker BarCompute {
    has bar_date: str = "";
    has close: float = 0.0;
    has ticker: str = "";
    has computed: list[str] = [];
    has upsert_count: int = 0;
    has rerun: bool = False;

    can run with IndicatorDef entry {
        if here.code in self.computed {
            visit [-->] else { disengage; }
        } else {
            visit [->:DependsOn:->] else { }
            if here.active {
                value = here.compute(self.close);
                action = "overwrite" if self.rerun else "insert";
                print(
                    f"    UPSERT({action}) {self.ticker} {here.code} "
                    f"v{here.version} {self.bar_date} adj={here.adjustment} "
                    f"=> {value:.4f}"
                );
                self.computed.append(here.code);
                self.upsert_count += 1;
            }
            visit [-->] else { disengage; }
        }
    }
}

walker BackfillWorker {
    has registry_head: IndicatorDef;
    has current_ticker: str = "";
    has bars_processed: int = 0;

    can start with Root entry {
        print("=== daily indicator backfill (idempotent) ===");
        visit [->:HasBar:->] else { disengage; }
    }

    can on_symbol with Symbol entry {
        self.current_ticker = here.ticker;
        print(f"backfill {here.ticker} (symbol_id={here.symbol_id})");
        visit [->:HasBar:->] else {
            print(f"  skip: no bar history for {here.ticker}");
        }
    }

    can on_bar with DailyBar entry {
        print(
            f"  bar {here.bar_date} close={here.close} "
            f"vol={int(here.volume)}"
        );
        BarCompute(
            bar_date=here.bar_date,
            close=here.close,
            ticker=self.current_ticker,
            rerun=False
        ) spawn self.registry_head;
        BarCompute(
            bar_date=here.bar_date,
            close=here.close,
            ticker=self.current_ticker,
            rerun=True
        ) spawn self.registry_head;
        self.bars_processed += 1;
        visit [->:HasBar:->] else { }
    }
}

