"""Semantic search spike: structural filters narrow TurboQuant index candidates before dense rerank."""

node CodeSymbol {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has symbol_id: int = 0;
    has projection: float = 0.0;
}

node VectorIndex {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has dim: int = 768;
    has quant_bits: int = 4;
}

node StructuralFilter {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

node QueryVector {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has projection: float = 0.0;
}

edge Allowlisted { }
edge IndexedIn { has quant_bits: int = 4; }
edge Calls { }

walker SemanticQuery {
    has query_proj: float = 0.0;
    has collecting: bool = False;
    has searching: bool = False;
    has allowed: dict[int, bool] = {};

    can start with Root entry {
        visit [-->];
    }

    can load_query with QueryVector entry {
        self.query_proj = here.projection;
        print(f"query vector loaded: projection={self.query_proj}");
        visit [-->];
    }

    can collect with StructuralFilter entry {
        print(f"structural filter: {here.title}");
        self.collecting = True;
        visit [->:Allowlisted:->];
        self.collecting = False;
        visit [-->];
    }

    can search with VectorIndex entry {
        bits = here.quant_bits;
        print(f"dense index: {here.title} dim={here.dim} quant={bits}bit");
        self.searching = True;
        visit [->:IndexedIn:->];
        self.searching = False;
    }

    can rank with CodeSymbol entry {
        if self.collecting {
            self.allowed[here.symbol_id] = True;
            print(f"allowlisted candidate: {here.title} (id={here.symbol_id})");
        } elif self.searching {
            is_allowed = self.allowed.get(here.symbol_id, False);
            if not is_allowed {
                print(f"filtered out: {here.title} (id={here.symbol_id})");
            } else {
                delta = here.projection - self.query_proj;
                dist_sq = delta * delta;
                score = 1.0 / (1.0 + dist_sq);
                print(f"rerank [{score:.3f}] {here.title} (id={here.symbol_id})");
            }
        }
    }
}

walker CallTracer {
    has visited: dict[int, bool] = {};
    has depth: int = 0;
    has max_depth: int = 8;

    can start with Root entry {
        visit [-->];
    }

    can pass with QueryVector | StructuralFilter | VectorIndex entry {
        visit [-->];
    }

    can trace with CodeSymbol entry {
        if self.visited.get(here.symbol_id, False) {
            print(f"[cycle] blocked re-entry to {here.title}");
        } elif self.depth > self.max_depth {
            print(f"[depth] cap at {here.title}");
        } else {
            self.visited[here.symbol_id] = True;
            print(f"[call] depth={self.depth} {here.title} (id={here.symbol_id})");
            next_depth = self.depth + 1;
            self.depth = next_depth;
            visit [->:Calls:->];
            prev_depth = self.depth - 1;
            self.depth = prev_depth;
        }
    }
}

walker IndexAuditor {
    can start with Root entry {
        visit [-->];
    }

    can pass with QueryVector | StructuralFilter entry {
        visit [-->];
    }

    can audit with VectorIndex entry {
        print(f"auditing index: {here.title}");
        visit [->:IndexedIn:->];
    }

    can check with CodeSymbol entry {
        if not here.available {
            print(f"[purge] remove id={here.symbol_id} {here.title} from dense index");
        } else {
            print(f"[index] ok id={here.symbol_id} {here.title}");
        }
    }
}

with entry {
    main_sym = CodeSymbol(title="main", symbol_id=1, projection=0.90);
    helper_sym = CodeSymbol(title="helper", symbol_id=2, projection=0.85);
    util_sym = CodeSymbol(title="util", symbol_id=3, projection=0.80, available=False);
    filter_node = StructuralFilter(title="bm25+graph");
    index_node = VectorIndex(title="turboquant_index", quant_bits=4);
    query_node = QueryVector(title="semantic_query", projection=0.88);

    main_sym +>:Calls:+> helper_sym;
    helper_sym +>:Calls:+> util_sym;
    helper_sym +>:Calls:+> main_sym;

    filter_node +>:Allowlisted:+> main_sym;
    filter_node +>:Allowlisted:+> helper_sym;

    index_node +>:IndexedIn(quant_bits=4):+> main_sym;
    index_node +>:IndexedIn(quant_bits=4):+> helper_sym;
    index_node +>:IndexedIn(quant_bits=4):+> util_sym;

    root ++> query_node ++> filter_node ++> index_node;
    root ++> main_sym;

    root spawn SemanticQuery();
    root spawn CallTracer();
    root spawn IndexAuditor();
}

"""RBAC scoped permission: batched multi-seed ancestor resolution vs per-group N+1 PG round-trips."""

node AgentGroup {
    has name: str = "";
    has gid: str = "";
    has grants_scope: bool = False;
}

edge ParentOf { }

walker NaiveAncestorLookup {
    has member_gids: list[str] = [];
    has pending: list[str] = [];
    has ancestor_gids: list[str] = [];
    has pg_round_trips: int = 0;
    has active_seed: str = "";
    has climbing: bool = False;
    has path_seen: list[str] = [];
    has hops: int = 0;
    has max_hops: int = 32;

    can start with Root entry {
        self.pending = self.member_gids;
        if not self.pending {
            disengage;
        }
        self.active_seed = self.pending[0];
        self.pending = self.pending[1:];
        self.pg_round_trips += 1;
        self.climbing = False;
        self.path_seen = [];
        self.hops = 0;
        visit [-->[?:AgentGroup]];
    }

    can query with AgentGroup entry {
        if not self.climbing {
            if here.gid != self.active_seed {
                visit [-->][?:AgentGroup] else {
                    if self.pending {
                        self.active_seed = self.pending[0];
                        self.pending = self.pending[1:];
                        self.pg_round_trips += 1;
                        self.climbing = False;
                        self.path_seen = [];
                        self.hops = 0;
                        visit [-->[?:AgentGroup]];
                    } else {
                        disengage;
                    }
                };
            } else {
                self.climbing = True;
                visit [<--:ParentOf:--] else {
                    if self.pending {
                        self.active_seed = self.pending[0];
                        self.pending = self.pending[1:];
                        self.pg_round_trips += 1;
                        self.climbing = False;
                        self.path_seen = [];
                        self.hops = 0;
                        visit [-->[?:AgentGroup]];
                    } else {
                        disengage;
                    }
                };
            }
        } else {
            if here.gid in self.path_seen {
                if self.pending {
                    self.active_seed = self.pending[0];
                    self.pending = self.pending[1:];
                    self.pg_round_trips += 1;
                    self.climbing = False;
                    self.path_seen = [];
                    self.hops = 0;
                    visit [-->[?:AgentGroup]];
                } else {
                    disengage;
                }
            }
            if self.hops >= self.max_hops {
                disengage;
            }
            self.path_seen.append(here.gid);
            self.ancestor_gids.append(here.gid);
            self.hops += 1;
            visit [<--:ParentOf:--] else {
                if self.pending {
                    self.active_seed = self.pending[0];
                    self.pending = self.pending[1:];
                    self.pg_round_trips += 1;
                    self.climbing = False;
                    self.path_seen = [];
                    self.hops = 0;
                    visit [-->[?:AgentGroup]];
                } else {
                    disengage;
                }
            };
        }
    }
}

walker BatchedAncestorLookup {
    has member_gids: list[str] = [];
    has ancestor_gids: list[str] = [];
    has pg_round_trips: int = 1;
    has wave: list[str] = [];
    has next_wave: list[str] = [];
    has climbing: bool = False;
    has path_seen: list[str] = [];
    has hops: int = 0;
    has max_hops: int = 32;

    can start with Root entry {
        self.wave = self.member_gids;
        if not self.wave {
            disengage;
        }
        visit [-->[?:AgentGroup]];
    }

    can batch_query with AgentGroup entry {
        if not self.climbing {
            if here.gid not in self.wave {
                visit [-->][?:AgentGroup] else {
                    if not self.next_wave {
                        disengage;
                    }
                    self.hops += 1;
                    if self.hops >= self.max_hops {
                        disengage;
                    }
                    self.wave = self.next_wave;
                    self.next_wave = [];
                    self.climbing = False;
                    self.path_seen = [];
                    visit [-->[?:AgentGroup]];
                };
            } else {
                self.climbing = True;
                visit [<--:ParentOf:--] else {
                    self.climbing = False;
                    visit [-->][?:AgentGroup] else {
                        if not self.next_wave {
                            disengage;
                        }
                        self.hops += 1;
                        if self.hops >= self.max_hops {
                            disengage;
                        }
                        self.wave = self.next_wave;
                        self.next_wave = [];
                        visit [-->[?:AgentGroup]];
                    };
                };
            }
        } else {
            if here.gid in self.path_seen {
                self.climbing = False;
                visit [-->][?:AgentGroup] else {
                    if not self.next_wave {
                        disengage;
                    }
                    self.hops += 1;
                    if self.hops >= self.max_hops {
                        disengage;
                    }
                    self.wave = self.next_wave;
                    self.next_wave = [];
                    visit [-->[?:AgentGroup]];
                };
            }
            if here.gid not in self.ancestor_gids {
                self.ancestor_gids.append(here.gid);
            }
            if here.gid not in self.next_wave {
                self.next_wave.append(here.gid);
            }
            self.path_seen.append(here.gid);
            visit [<--:ParentOf:--] else {
                self.climbing = False;
                visit [-->][?:AgentGroup] else {
                    if not self.next_wave {
                        disengage;
                    }
                    self.hops += 1;
                    if self.hops >= self.max_hops {
                        disengage;
                    }
                    self.wave = self.next_wave;
                    self.next_wave = [];
                    self.path_seen = [];
                    visit [-->[?:AgentGroup]];
                };
            };
        }
    }
}

walker ScopedPermissionCheck {
    has member_gids: list[str] = [];
    has ancestor_gids: list[str] = [];
    has pg_round_trips: int = 0;
    has granted: bool = False;
    has mode: str = "naive";

    can start with Root entry {
        if self.mode == "batched" {
            resolver = BatchedAncestorLookup(member_gids=self.member_gids);
            root spawn resolver;
            self.ancestor_gids = resolver.ancestor_gids;
            self.pg_round_trips = resolver.pg_round_trips;
        } else {
            resolver = NaiveAncestorLookup(member_gids=self.member_gids);
            root spawn resolver;
            self.ancestor_gids = resolver.ancestor_gids;
            self.pg_round_trips = resolver.pg_round_trips;
        }
        visit [-->[?:AgentGroup]];
    }

    can audit with AgentGroup entry {
        if here.grants_scope {
            if here.gid in self.ancestor_gids {
                self.granted = True;
            }
            for seed in self.member_gids {
                if here.gid == seed {
                    self.granted = True;
                }
            }
        }
        visit [-->][?:AgentGroup] else { disengage; };
    }
}

with entry {
    org = AgentGroup(name="Organization", gid="g-org", grants_scope=True);
    eng = AgentGroup(name="Engineering", gid="g-eng");
    backend = AgentGroup(name="Backend", gid="g-backend");
