    print(f"batched ancestors: {batched_check.ancestor_gids} "
          f"({batched_check.pg_round_trips} PG round-trip)");
    print(f"naive scoped permission granted: {naive_check.granted}");
    print(f"batched scoped permission granted: {batched_check.granted}");
}

"""CinderPeak graph traversal: BFS and DFS walkers with visitor early-exit and reachability."""

node Vertex {
    has name: str = "";
    has value: int = 0;
}

edge Link { }

walker BreadthFirstSearch {
    has visited: list[str] = [];
    has order: list[str] = [];
    has stop_on: str = "";

    can traverse with Vertex entry {
        if here.name in self.visited {
            disengage;
        }
        self.visited.append(here.name);
        self.order.append(here.name);
        if self.stop_on != "" and here.name == self.stop_on {
            disengage;
        }
        visit [->:Link:->] else { disengage; };
    }
}

walker DepthFirstSearch {
    has visited: list[str] = [];
    has order: list[str] = [];
    has stop_on: str = "";

    can traverse with Vertex entry {
        if here.name in self.visited {
            disengage;
        }
        self.visited.append(here.name);
        self.order.append(here.name);
        if self.stop_on != "" and here.name == self.stop_on {
            disengage;
        }
        visit [here->:Link:->] else { disengage; };
    }
}

walker ReachableFrom {
    has visited: list[str] = [];
    has reachable: list[str] = [];

    can gather with Vertex entry {
        if here.name in self.visited {
            disengage;
        }
        self.visited.append(here.name);
        self.reachable.append(here.name);
        visit [->:Link:->] else { disengage; };
    }
}

with entry {
    a = Vertex(name="A", value=1);
    b = Vertex(name="B", value=2);
    c = Vertex(name="C", value=3);
    d = Vertex(name="D", value=4);
    e = Vertex(name="E", value=5);

    root ++> a;
    a +>:Link:+> b;
    b +>:Link:+> c;
    c +>:Link:+> a;
    a +>:Link:+> d;
    root ++> e;

    bfs = BreadthFirstSearch(stop_on="C");
    a spawn bfs;
    print(f"BFS order (halt at C): {bfs.order}");

    dfs = DepthFirstSearch();
    a spawn dfs;
    print(f"DFS order: {dfs.order}");

    reach = ReachableFrom();
    a spawn reach;
    print(f"reachableFrom(A): {reach.reachable}");
}

"""Hydra buildRecalledContext: naive O(chunks×relations) scans vs indexed typed-edge lookup."""

node Chunk {
    has chunk_uuid: str = "";
    has snippet: str = "";
    has year: int = 0;
    has available: bool = True;
}

node Relation {
    has gid: str = "";
    has predicate: str = "";
    has triplet_chunk_ids: list[str] = [];
    has year: int = 0;
    has available: bool = True;
}

node ChunkShelf {
    has title: str = "chunks";
    has year: int = 0;
    has available: bool = True;
}

node RelationShelf {
    has title: str = "relations";
    has year: int = 0;
    has available: bool = True;
}

edge IndexedLink { }

walker NaiveRecaller {
    has chunks: list[Chunk] = [];
    has relations: list[Relation] = [];
    has scans: int = 0;
    has matches: int = 0;

    can start with Root entry {
        visit [-->[?:ChunkShelf]] else { disengage; }
    }

    can enter_chunks with ChunkShelf entry {
        visit [-->];
    }

    can collect_chunk with Chunk entry {
        self.chunks.append(here);
        visit [-->]; else {
            visit [<--];
            visit [<--];
            visit [-->[?:RelationShelf]] else { disengage; }
        }
    }

    can enter_rels with RelationShelf entry {
        visit [-->];
    }

    can collect_rel with Relation entry {
        self.relations.append(here);
        visit [-->]; else {
            self.run_naive_pass();
            disengage;
        }
    }

    def run_naive_pass() {
        for c in self.chunks {
            for r in self.relations {
                self.scans += 1;
                if c.chunk_uuid in r.triplet_chunk_ids {
                    self.matches += 1;
                    print(f"NAIVE match {c.chunk_uuid} <- {r.gid}");
                }
            }
        }
    }
}

walker IndexBuilder {
    has chunks: list[Chunk] = [];
    has built: int = 0;

    can start with Root entry {
        visit [-->[?:ChunkShelf]] else { disengage; }
    }

    can enter_chunks with ChunkShelf entry {
        visit [-->];
    }

    can collect_chunk with Chunk entry {
        self.chunks.append(here);
        visit [-->]; else {
            visit [<--];
            visit [<--];
            visit [-->[?:RelationShelf]] else { disengage; }
        }
    }

    can enter_rels with RelationShelf entry {
        visit [-->];
    }

    can link with Relation entry {
        for c in self.chunks {
            if c.chunk_uuid in here.triplet_chunk_ids {
                c +>:IndexedLink:+> here;
                self.built += 1;
            }
        }
        visit [-->]; else { disengage; }
    }
}

walker IndexedRecaller {
    has lookups: int = 0;
    has matches: int = 0;

    can start with Root entry {
        visit [-->[?:ChunkShelf]] else { disengage; }
    }

    can enter with ChunkShelf entry {
        visit [-->];
    }

    can recall with Chunk entry {
        self.lookups += 1;
