"""RBAC scoped permission: batched multi-seed ancestor resolution vs per-group N+1 PG round-trips."""

node AgentGroup {
    has name: str = "";
    has gid: str = "";
    has grants_scope: bool = False;
}

edge ParentOf { }

walker NaiveAncestorLookup {
    has member_gids: list[str] = [];
    has pending: list[str] = [];
    has ancestor_gids: list[str] = [];
    has pg_round_trips: int = 0;
    has active_seed: str = "";
    has climbing: bool = False;
    has path_seen: list[str] = [];

    can start with Root entry {
        self.pending = self.member_gids;
        if not self.pending {
            disengage;
        }
        self.active_seed = self.pending[0];
        self.pending = self.pending[1:];
        self.pg_round_trips += 1;
        self.climbing = False;
        self.path_seen = [];
        visit [-->];
    }

    can walk with AgentGroup entry {
        if self.climbing {
            if here.gid in self.path_seen {
                if self.pending {
                    self.active_seed = self.pending[0];
                    self.pending = self.pending[1:];
                    self.pg_round_trips += 1;
                    self.climbing = False;
                    self.path_seen = [];
                    visit [-->];
                } else {
                    disengage;
                }
            } else {
                if here.gid not in self.ancestor_gids {
                    self.ancestor_gids.append(here.gid);
                }
                self.path_seen.append(here.gid);
                visit [<--:ParentOf:--] else {
                    if self.pending {
                        self.active_seed = self.pending[0];
                        self.pending = self.pending[1:];
                        self.pg_round_trips += 1;
                        self.climbing = False;
                        self.path_seen = [];
                        visit [-->];
                    } else {
                        disengage;
                    }
                };
            }
        } else {
            if here.gid == self.active_seed {
                self.climbing = True;
                visit [<--:ParentOf:--] else {
                    if self.pending {
                        self.active_seed = self.pending[0];
                        self.pending = self.pending[1:];
                        self.pg_round_trips += 1;
                        self.climbing = False;
                        self.path_seen = [];
                        visit [-->];
                    } else {
                        disengage;
                    }
                };
            } else {
                visit [->:ParentOf:->] else {
                    if self.pending {
                        self.active_seed = self.pending[0];
                        self.pending = self.pending[1:];
                        self.pg_round_trips += 1;
                        self.climbing = False;
                        self.path_seen = [];
                        visit [-->];
                    } else {
                        disengage;
                    }
                };
            }
        }
    }
}

walker BatchedAncestorLookup {
    has member_gids: list[str] = [];
    has ancestor_gids: list[str] = [];
    has pg_round_trips: int = 1;
    has pending: list[str] = [];
    has climbing: bool = False;
    has path_seen: list[str] = [];

    can start with Root entry {
        self.pending = self.member_gids;
        if not self.pending {
            disengage;
        }
        visit [-->];
    }

    can walk with AgentGroup entry {
        if self.climbing {
            if here.gid in self.path_seen {
                self.climbing = False;
                visit [->:ParentOf:->] else { disengage; };
            } else {
                if here.gid not in self.ancestor_gids {
                    self.ancestor_gids.append(here.gid);
                }
                self.path_seen.append(here.gid);
                visit [<--:ParentOf:--] else {
                    self.climbing = False;
                    visit [->:ParentOf:->] else { disengage; };
                };
            }
        } else {
            if here.gid in self.pending {
                remaining = [];
                for gid in self.pending {
                    if gid != here.gid {
                        remaining.append(gid);
                    }
                }
                self.pending = remaining;
                self.climbing = True;
                self.path_seen = [];
                visit [<--:ParentOf:--] else {
                    self.climbing = False;
                    visit [->:ParentOf:->] else { disengage; };
                };
            } else {
                visit [->:ParentOf:->] else { disengage; };
            }
        }
    }
}

walker ScopedPermissionCheck {
    has member_gids: list[str] = [];
    has ancestor_gids: list[str] = [];
    has pg_round_trips: int = 0;
    has granted: bool = False;
    has mode: str = "naive";

    can start with Root entry {
        if self.mode == "batched" {
            resolver = BatchedAncestorLookup(member_gids=self.member_gids);
            root spawn resolver;
            self.ancestor_gids = resolver.ancestor_gids;
            self.pg_round_trips = resolver.pg_round_trips;
        } else {
            resolver = NaiveAncestorLookup(member_gids=self.member_gids);
            root spawn resolver;
            self.ancestor_gids = resolver.ancestor_gids;
            self.pg_round_trips = resolver.pg_round_trips;
        }
        visit [-->];
    }

    can audit with AgentGroup entry {
        if here.grants_scope {
            for seed in self.member_gids {
                if here.gid == seed {
                    self.granted = True;
                }
            }
            for aid in self.ancestor_gids {
                if here.gid == aid {
                    self.granted = True;
                }
            }
        }
        visit [->:ParentOf:->] else { disengage; };
    }
}

with entry {
    org = AgentGroup(name="Organization", gid="g-org", grants_scope=True);
    eng = AgentGroup(name="Engineering", gid="g-eng");
    backend = AgentGroup(name="Backend", gid="g-backend");
    frontend = AgentGroup(name="Frontend", gid="g-frontend");
    platform = AgentGroup(name="Platform", gid="g-platform");

    root ++> org;
    org +>:ParentOf:+> eng;
    eng +>:ParentOf:+> backend;
    eng +>:ParentOf:+> frontend;
    org +>:ParentOf:+> platform;

    operator_groups = ["g-backend", "g-frontend"];

    naive_check = ScopedPermissionCheck(
        member_gids=operator_groups,
        mode="naive"
    );
    root spawn naive_check;

    batched_check = ScopedPermissionCheck(
        member_gids=operator_groups,
        mode="batched"
    );
    root spawn batched_check;

    print(f"member groups: {operator_groups}");
    print(f"naive ancestors: {naive_check.ancestor_gids} "
          f"({naive_check.pg_round_trips} PG round-trips)");
    print(f"batched ancestors: {batched_check.ancestor_gids} "
          f"({batched_check.pg_round_trips} PG round-trip)");
    print(f"naive scoped permission granted: {naive_check.granted}");
    print(f"batched scoped permission granted: {batched_check.granted}");
}

"""Hydra buildRecalledContext: naive O(chunks×relations) scans vs indexed typed-edge lookup."""

node Chunk {
    has chunk_uuid: str = "";
    has snippet: str = "";
    has year: int = 0;
    has available: bool = True;
}

node Relation {
    has gid: str = "";
    has predicate: str = "";
    has triplet_chunk_ids: list[str] = [];
    has year: int = 0;
    has available: bool = True;
}

edge IndexedLink { }

walker NaiveRecaller {
    has chunks: list[Chunk] = [];
    has relations: list[Relation] = [];
    has scans: int = 0;
    has matches: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can collect with Chunk entry {
        self.chunks.append(here);
        visit [-->];
    }

    can collect with Relation entry {
        self.relations.append(here);
        visit [-->] else {
            self.run_naive_pass();
            disengage;
        }
    }

    def run_naive_pass() {
        for c in self.chunks {
            for r in self.relations {
                self.scans += 1;
                if c.chunk_uuid in r.triplet_chunk_ids {
                    self.matches += 1;
                    print(f"NAIVE match {c.chunk_uuid} <- {r.gid}");
                }
            }
        }
    }
}

walker IndexBuilder {
    has chunk_by_uuid: dict[str, Chunk] = {};
    has built: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can index_chunk with Chunk entry {
        self.chunk_by_uuid[here.chunk_uuid] = here;
        visit [-->];
    }

    can link with Relation entry {
        for cid in here.triplet_chunk_ids {
            c = self.chunk_by_uuid.get(cid, None);
            if c is not None {
                c +>:IndexedLink:+> here;
                self.built += 1;
            }
        }
        visit [-->];
    }
}

walker IndexedRecaller {
    has lookups: int = 0;
    has matches: int = 0;

    can start with Root entry {
        visit [-->[?:Chunk]] else { disengage; }
    }

    can recall with Chunk entry {
        self.lookups += 1;
        print(f"INDEXED recall {here.chunk_uuid}");
        visit [->:IndexedLink:->];
        visit [-->[?:Chunk]] else { disengage; }
    }

    can match with Relation entry {
        self.matches += 1;
        print(f"INDEXED match {here.gid} ({here.predicate})");
    }
}

with entry {
    root ++> Chunk(chunk_uuid="uuid-1", snippet="alpha")
        ++> Chunk(chunk_uuid="uuid-2", snippet="beta")
        ++> Chunk(chunk_uuid="uuid-3", snippet="gamma")
        ++> Relation(
            gid="g-1",
            predicate="mentions",
            triplet_chunk_ids=["uuid-1", "uuid-2"]
        )
        ++> Relation(gid="g-2", predicate="defines", triplet_chunk_ids=["uuid-2"])
        ++> Relation(gid="g-3", predicate="links", triplet_chunk_ids=["uuid-1"])
        ++> Relation(gid="g-4", predicate="quotes", triplet_chunk_ids=["uuid-3"])
        ++> Relation(gid="g-5", predicate="orphan", triplet_chunk_ids=["uuid-99"]);

    print("=== buildRecalledContext: naive O(n^2) relation scan ===");
    naive = NaiveRecaller();
    root spawn naive;
    print(f"Naive scans={naive.scans} matches={naive.matches}");

    print("=== pre-build chunkId -> relationIds index ===");
    indexer = IndexBuilder();
    root spawn indexer;
    print(f"IndexedLink edges built={indexer.built}");

