    has available: bool = True;
    has report_name: str = "";
    has saved_access_version: int = 0;
}

edge GovernedRelation { }
edge HasField { }
edge SelectsField { }
edge Targets { }
edge AnchorsScope { }
edge HostsReport { }

walker ReportExecutor {
    has user_caps: list[str] = [];
    has allowed_columns: list[str] = [];
    has scope_version: int = 0;

    can start with Root entry {
        visit [->:AnchorsScope:->];
        visit [->:HostsReport:->];
    }

    can ingest_scope with TenantScope entry {
        self.scope_version = here.access_version;
        print(f"Scope accessVersion={here.access_version}");
    }

    can run with ReportDefinition entry {
        if here.saved_access_version != self.scope_version {
            verdict = "STALE";
            print(f"[{verdict}] {here.report_name} — saved v{here.saved_access_version} != scope v{self.scope_version}");
        } else {
            print(f"=== Executing: {here.report_name} ===");
            visit [->:SelectsField:->] else { disengage; };
            visit [->:Targets:->];
        }
    }

    can gate_field with FieldCatalog entry {
        permitted = here.read_capability in self.user_caps;
        if permitted {
            self.allowed_columns.append(here.label);
            print(f"  SELECT {here.label} ({here.data_type})");
        } else {
            print(f"  DENY  {here.field_id} (missing {here.read_capability})");
        }
    }

    can preview_target with Customer | WorkOrder entry {
        print(f"  root object: {here.object_type} {here.object_key}");
    }
}

walker GovernedTraverser {
    has visited_keys: list[str] = [];
    has max_depth: int = 3;
    has depth: int = 0;

    can traverse with Customer | WorkOrder entry {
        key = here.object_key;
        if key in self.visited_keys {
            print(f"  [CYCLE] blocked revisit of {key}");
            disengage;
        }
        if self.depth > self.max_depth {
            print(f"  [DEPTH] cap before {key}");
            disengage;
        }
        self.visited_keys.append(key);
        print(f"  traverse {here.object_type}:{key} (depth={self.depth})");
        self.depth += 1;
        visit [->:GovernedRelation:->] else { };
        visit [->:HasField:->];
        self.depth -= 1;
    }

    can catalog_field with FieldCatalog entry {
        state = "visible" if here.available else "hidden";
        print(f"    field {here.field_id} [{state}]");
    }
}

