"""Hydra buildRecalledContext: naive O(chunks×relations) scans vs indexed typed-edge lookup."""

node ChunkShelf {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

node Chunk {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has chunk_uuid: str = "";
    has snippet: str = "";
}

node Relation {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has gid: str = "";
    has predicate: str = "";
    has triplet_chunk_ids: list[str] = [];
}

edge IndexedLink { }

walker NaiveRecaller {
    has chunks: list[Chunk] = [];
    has relations: list[Relation] = [];
    has scans: int = 0;
    has matches: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can gather_chunk with Chunk entry {
        self.chunks.append(here);
        visit [-->];
    }

    can gather_relation with Relation entry {
        self.relations.append(here);
        visit [-->] else {
            self.run_naive_pass();
            disengage;
        }
    }

    def run_naive_pass() {
        for c in self.chunks {
            for r in self.relations {
                self.scans += 1;
                if c.chunk_uuid in r.triplet_chunk_ids {
                    self.matches += 1;
                    print(f"NAIVE match {c.chunk_uuid} <- {r.gid}");
                }
            }
        }
    }
}

walker IndexBuilder {
    has chunk_by_uuid: dict[str, Chunk] = {};
    has built: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can index_chunk with Chunk entry {
        self.chunk_by_uuid[here.chunk_uuid] = here;
        visit [-->];
    }

    can link with Relation entry {
        for cid in here.triplet_chunk_ids {
            c = self.chunk_by_uuid.get(cid, None);
            if c is not None {
                c +>:IndexedLink:+> here;
                self.built += 1;
            }
        }
        visit [-->];
    }
}

walker IndexedRecaller {
    has lookups: int = 0;
    has matches: int = 0;

    can start with ChunkShelf entry {
        visit [-->];
    }

    can recall with Chunk entry {
        self.lookups += 1;
        print(f"INDEXED recall {here.chunk_uuid}");
        visit [->:IndexedLink:->];
        visit [-->];
    }

    can match with Relation entry {
        self.matches += 1;
        print(f"INDEXED match {here.gid} ({here.predicate})");
    }
}

with entry {
    shelf = ChunkShelf(title="chunk-shelf");
    root ++> shelf
        ++> Chunk(
            title="alpha",
            chunk_uuid="uuid-1",
            snippet="alpha"
        )
        ++> Chunk(
            title="beta",
            chunk_uuid="uuid-2",
            snippet="beta"
        )
        ++> Chunk(
            title="gamma",
            chunk_uuid="uuid-3",
            snippet="gamma"
        );
    root ++> Relation(
        title="mentions",
        gid="g-1",
        predicate="mentions",
        triplet_chunk_ids=["uuid-1", "uuid-2"]
    )
        ++> Relation(
            title="defines",
            gid="g-2",
            predicate="defines",
            triplet_chunk_ids=["uuid-2"]
        )
        ++> Relation(
            title="links",
            gid="g-3",
            predicate="links",
            triplet_chunk_ids=["uuid-1"]
        )
        ++> Relation(
            title="quotes",
            gid="g-4",
            predicate="quotes",
            triplet_chunk_ids=["uuid-3"]
        )
        ++> Relation(
            title="orphan",
            gid="g-5",
            predicate="orphan",
            triplet_chunk_ids=["uuid-99"]
        );

    print("=== buildRecalledContext: naive O(n^2) relation scan ===");
    naive = NaiveRecaller();
    root spawn naive;
    print(f"Naive scans={naive.scans} matches={naive.matches}");

    print("=== pre-build chunkId -> relationIds index ===");
    indexer = IndexBuilder();
    root spawn indexer;
    print(f"IndexedLink edges built={indexer.built}");

    print("=== indexed O(1) lookup per chunk ===");
    indexed = IndexedRecaller();
