"""Artifact Build Graph: DAG validation, dependency-ordered stage execution, and stale-artifact cache invalidation."""

node BuildStage {
    has stage_id: str = "";
    has kind: str = "";
    has status: str = "pending";
    has cache_hit: bool = False;
}

node Artifact {
    has artifact_id: str = "";
    has contract_id: str = "";
    has digest: str = "";
    has validation_state: str = "pending";
    has invalidated: bool = False;
}

edge DependsOn { }
edge Produces { }
edge Requires { }

walker DagValidator {
    has visiting: list[str] = [];
    has cycle_detected: bool = False;

    can start with Root entry {
        visit [-->[?:BuildStage]] else { disengage; };
        verdict = "VALID DAG" if not self.cycle_detected else "CYCLE REJECTED";
        print(f"[VALIDATE] {verdict}");
    }

    can audit with BuildStage entry {
        if here.stage_id in self.visiting {
            self.cycle_detected = True;
            print(f"[CYCLE] stage {here.stage_id} closes a dependency loop");
            disengage;
        }
        self.visiting.append(here.stage_id);
        visit [->:DependsOn:->];
        if len(self.visiting) > 0 and self.visiting[-1] == here.stage_id {
            _ = self.visiting.pop();
        }
    }
}

walker StageExecutor {
    has done: list[str] = [];
    has execution_log: list[str] = [];

    can run with BuildStage entry {
        visit [->:DependsOn:->];
        if here.stage_id in self.done {
            disengage;
        }
        action = "CACHE_HIT" if here.cache_hit else "EXECUTE";
        print(f"[{action}] {here.kind} :: {here.stage_id}");
        here.status = "complete";
        self.done.append(here.stage_id);
        self.execution_log.append(here.stage_id);
    }
}

walker InvalidationCascade {
    has invalidated_count: int = 0;

    can start with Artifact entry {
        if here.validation_state != "stale" {
            disengage;
        }
        print(f"[INVALIDATE] stale source {here.contract_id} ({here.artifact_id})");
        visit [<--:Requires:--] else { disengage; };
    }

    can rebuild with BuildStage entry {
        here.status = "pending";
        here.cache_hit = False;
        print(f"  stage {here.stage_id} queued for rebuild");
        visit [->:Produces:->];
    }

    can invalidate with Artifact entry {
        if here.invalidated {
            disengage;
        }
        here.invalidated = True;
        here.validation_state = "invalid";
        self.invalidated_count += 1;
        print(f"  artifact {here.contract_id} ({here.artifact_id}) invalidated");
        visit [<--:Requires:--];
    }
}

with entry {
    scope = BuildStage(stage_id="scope", kind="deterministic_transform");
    search = BuildStage(
        stage_id="search",
        kind="local_structured_generation",
        cache_hit=True
    );
    evidence = BuildStage(stage_id="evidence", kind="deterministic_transform");
    synth = BuildStage(stage_id="synth", kind="frontier_reasoning");
    verify = BuildStage(stage_id="verify", kind="verification");

    plan = Artifact(
        artifact_id="art-plan",
        contract_id="research_plan",
        digest="sha256:plan",
        validation_state="valid"
    );
    norm = Artifact(
        artifact_id="art-norm",
        contract_id="normalized_evidence",
        digest="sha256:norm",
        validation_state="valid"
    );
    doc = Artifact(
        artifact_id="art-doc",
        contract_id="markdown_document",
        digest="sha256:doc",
        validation_state="valid"
    );
    report = Artifact(
        artifact_id="art-report",
        contract_id="review_report",
        digest="sha256:report",
        validation_state="valid"
    );

    root ++> scope ++> search ++> evidence ++> synth ++> verify;

    search +>:DependsOn:+> scope;
    evidence +>:DependsOn:+> search;
    synth +>:DependsOn:+> evidence;
    verify +>:DependsOn:+> synth;

    scope +>:Produces:+> plan;
    search +>:Requires:+> plan;
    evidence +>:Produces:+> norm;
    synth +>:Requires:+> norm;
    synth +>:Produces:+> doc;
    verify +>:Requires:+> doc;
    verify +>:Produces:+> report;

    print("=== Build Graph: DAG Validation ===");
    root spawn DagValidator();

    print("=== Build Graph: Dependency-Ordered Execution ===");
    verify spawn StageExecutor();

    print("=== Build Graph: Stale Evidence Cascade ===");
    norm.validation_state = "stale";
    norm spawn InvalidationCascade();

    print("=== Build Graph: Incremental Rebuild ===");
    verify spawn StageExecutor();
}

"""CinderPeak graph traversal: BFS and DFS walkers with visitor early-exit and reachability."""

node Vertex {
    has name: str = "";
    has value: int = 0;
}

edge Link { }

walker BreadthFirstSearch {
    has visited: list[str] = [];
    has order: list[str] = [];
    has stop_on: str = "";

    can start with Root entry {
        visit [-->];
    }

    can traverse with Vertex entry {
        if here.name in self.visited {
            disengage;
        }
        self.visited.append(here.name);
        self.order.append(here.name);
        if self.stop_on != "" and here.name == self.stop_on {
            disengage;
        }
        visit [->:Link:->] else { disengage; };
    }
}

walker DepthFirstSearch {
    has visited: list[str] = [];
    has order: list[str] = [];
    has stop_on: str = "";

    can start with Root entry {
        visit [-->];
    }

    can traverse with Vertex entry {
        if here.name in self.visited {
            disengage;
        }
        self.visited.append(here.name);
        self.order.append(here.name);
        if self.stop_on != "" and here.name == self.stop_on {
            disengage;
        }
        visit [here->:Link:->] else { disengage; };
    }
}

walker ReachableFrom {
    has visited: list[str] = [];
    has reachable: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can gather with Vertex entry {
        if here.name in self.visited {
            disengage;
        }
        self.visited.append(here.name);
        self.reachable.append(here.name);
        visit [->:Link:->] else { disengage; };
    }
}

with entry {
    a = Vertex(name="A", value=1);
    b = Vertex(name="B", value=2);
    c = Vertex(name="C", value=3);
    d = Vertex(name="D", value=4);
    Vertex(name="E", value=5);

    root ++> a;
    a +>:Link:+> b;
    b +>:Link:+> c;
    c +>:Link:+> a;
    a +>:Link:+> d;

    bfs_walker = BreadthFirstSearch(stop_on="C");
    root spawn bfs_walker;
    print(f"BFS order (halt at C): {bfs_walker.order}");

    dfs_walker = DepthFirstSearch();
    root spawn dfs_walker;
    print(f"DFS order: {dfs_walker.order}");

    reach_walker = ReachableFrom();
    root spawn reach_walker;
    print(f"reachableFrom(A): {reach_walker.reachable}");
}

