"""Filesystem exploration: model directories and files as a graph, then walk it to search by glob pattern or content and to list directory trees with depth limits."""

node Directory {
    has name: str = "";
    has path: str = "";
}

node File {
    has name: str = "";
    has path: str = "";
    has lines: list[str] = [];

    def glob_match(pattern: str) -> bool {
        if pattern == "*" {
            return True;
        }
        if pattern.startswith("*.") {
            suffix = pattern[1:];
            return self.name.endswith(suffix);
        }
        return self.name == pattern;
    }

    def content_hits(term: str) -> list[int] {
        hits: list[int] = [];
        if term == "" {
            return hits;
        }
        for (i, line) in enumerate(self.lines) {
            if term in line {
                hits.append(i + 1);
            }
        }
        return hits;
    }
}

edge Contains { }

walker FileSearcher {
    has pattern: str = "*";
    has directory: str = "";
    has content_term: str = "";
    has max_results: int = 20;
    has allowed_base: str = "";
    has results: list[str] = [];
    has visited: list[str] = [];
    has done: bool = False;

    def in_search_scope(path: str) -> bool {
        if self.directory == "" {
            return True;
        }
        return path == self.directory or path.startswith(self.directory + "/");
    }

    def in_sandbox(path: str) -> bool {
        if self.allowed_base == "" {
            return True;
        }
        return path.startswith(self.allowed_base);
    }

    can start with Root entry {
        visit [->:Contains:->] else { disengage; }
    }

    can search with Directory entry {
        if self.done {
            disengage;
        }
        if not self.in_sandbox(here.path) {
            disengage;
        }
        if here.path in self.visited {
            disengage;
        }
        self.visited.append(here.path);
        visit [->:Contains:->] else { disengage; }
    }

    can inspect with File entry {
        if self.done {
            disengage;
        }
        if not self.in_sandbox(here.path) {
            disengage;
        }
        if here.path in self.visited {
            disengage;
        }
        self.visited.append(here.path);
        if self.in_search_scope(here.path) {
            if self.content_term != "" {
                hits = here.content_hits(self.content_term);
                if hits {
                    hit_str = ", ".join([str(n) for n in hits]);
                    self.results.append(
                        f"{here.path} (lines: {hit_str})"
                    );
                }
            } else {
                if here.glob_match(self.pattern) {
                    self.results.append(here.path);
                }
            }
        }
        if len(self.results) >= self.max_results {
            self.done = True;
            disengage;
        }
        visit [->:Contains:->] else { disengage; }
    }
}

walker DirectoryLister {
    has path: str = "";
    has recursive: bool = False;
    has max_depth: int = 3;
    has allowed_base: str = "";
    has depth: int = 0;
    has entries: list[str] = [];
    has visited: list[str] = [];
    has listing: bool = False;

    def in_sandbox(path: str) -> bool {
        if self.allowed_base == "" {
            return True;
        }
        return path.startswith(self.allowed_base);
    }

    def in_list_scope(path: str) -> bool {
        if self.path == "" {
            return True;
        }
        return path == self.path or path.startswith(self.path + "/");
    }

    def is_ancestor_of_target(dir_path: str) -> bool {
        if self.path == "" {
            return False;
        }
        return self.path.startswith(dir_path + "/") and dir_path != self.path;
    }

    can start with Root entry {
        visit [->:Contains:->] else { disengage; }
    }

    can list_dir with Directory entry {
        if not self.in_sandbox(here.path) {
            disengage;
        }
        if here.path in self.visited {
            disengage;
        }
        self.visited.append(here.path);
        if self.is_ancestor_of_target(here.path) {
            visit [->:Contains:->] else { disengage; }
        } else {
            if self.in_list_scope(here.path) {
                if here.path == self.path {
                    self.listing = True;
                    self.depth = 0;
                }
                if self.listing {
                    kind = "dir";
                    indent = "  " * self.depth;
                    self.entries.append(f"{indent}[{kind}] {here.path}");
                    next_depth = self.depth + 1;
                    if self.recursive and next_depth <= self.max_depth {
                        self.depth = next_depth;
                        visit [->:Contains:->] else {
                            self.depth = self.depth - 1;
                            disengage;
                        }
                        self.depth = self.depth - 1;
                    } else {
                        visit [->:Contains:->] else { disengage; }
                    }
                } else {
                    visit [->:Contains:->] else { disengage; }
                }
            } else {
                visit [->:Contains:->] else { disengage; }
            }
        }
    }

    can list_file with File entry {
        if not self.in_sandbox(here.path) {
            disengage;
        }
        if here.path in self.visited {
            disengage;
        }
        self.visited.append(here.path);
        if self.listing and self.in_list_scope(here.path) {
            kind = "file";
            indent = "  " * self.depth;
            self.entries.append(f"{indent}[{kind}] {here.path}");
        }
        visit [->:Contains:->] else { disengage; }
    }
}

