"""CDG implication graph: prime-power components, forced residue edges, and iterative Tarjan SCC grouping."""

node PrimePower {
    has p: int = 0;
    has two_e: int = 0;
    has idx: int = 0;
}

edge Implies {
    has modulus: int = 0;
}

walker ForcedCandidateBuilder {
    has registry: list[PrimePower] = [];
    has adj: list[list[int]] = [];

    def divisors_gt_one(n: int) -> list[int] {
        out: list[int] = [];
        for d in range(2, n + 1) {
            if n % d == 0 {
                out.append(d);
            }
        }
        return out;
    }

    can start with Root entry {
        print("Phase 1: derive forced-candidate implication edges");
        visit [-->];
    }

    can derive with PrimePower entry {
        modulus_n = here.two_e + 1;
        for d in self.divisors_gt_one(modulus_n) {
            for comp in self.registry {
                if comp.p % d == 1 and comp.idx != here.idx {
                    here +>:Implies(modulus=d):+> comp;
                    self.adj[here.idx].append(comp.idx);
                    print(
                        f"  [{here.idx}] --mod {d}--> [{comp.idx}] "
                        f"(p={comp.p})"
                    );
                }
            }
        }
        visit [-->];
    }
}

walker SccComputer {
    has adj: list[list[int]] = [];
    has n: int = 0;
    has index: list[int] = [];
    has lowlink: list[int] = [];
    has on_stack: list[bool] = [];
    has stack: list[int] = [];
    has comp_to_scc: list[int] = [];
    has scc_groups: list[list[int]] = [];
    has time: int = 0;
    has scc_count: int = 0;
    has work: list[int] = [];
    has work_phase: list[int] = [];
    has work_iter: list[int] = [];

    def tarjan_from(start: int) -> None {
        self.work.append(start);
        self.work_phase.append(0);
        self.work_iter.append(0);
        while len(self.work) > 0 {
            v = self.work[-1];
            phase = self.work_phase[-1];
            if phase == 0 {
                self.index[v] = self.time;
                self.lowlink[v] = self.time;
                self.time += 1;
                self.stack.append(v);
                self.on_stack[v] = True;
                self.work_phase[-1] = 1;
            } else {
                neighbors = self.adj[v];
                i = self.work_iter[-1];
                if i < len(neighbors) {
                    w = neighbors[i];
                    self.work_iter[-1] = i + 1;
                    if self.index[w] < 0 {
                        self.work.append(w);
                        self.work_phase.append(0);
                        self.work_iter.append(0);
                    } elif self.on_stack[w] {
                        new_low = self.index[w];
                        if new_low < self.lowlink[v] {
                            self.lowlink[v] = new_low;
                        }
                    }
                } else {
                    if self.lowlink[v] == self.index[v] {
                        group: list[int] = [];
                        while True {
                            w = self.stack.pop();
                            self.on_stack[w] = False;
                            self.comp_to_scc[w] = self.scc_count;
                            group.append(w);
                            if w == v {
                                break;
                            }
                        }
                        self.scc_groups.append(group);
                        self.scc_count += 1;
                    }
                    popped_low = self.lowlink[v];
                    self.work.pop();
                    self.work_phase.pop();
                    self.work_iter.pop();
                    if len(self.work) > 0 {
                        parent = self.work[-1];
                        if popped_low < self.lowlink[parent] {
                            self.lowlink[parent] = popped_low;
                        }
                    }
                }
            }
        }
    }

    def run_tarjan() -> None {
        for v in range(self.n) {
            if self.index[v] < 0 {
                self.tarjan_from(v);
            }
        }
    }

    can start with Root entry {
        print("Phase 2: iterative Tarjan SCC over implication graph");
        self.run_tarjan();
        for (sid, members) in enumerate(self.scc_groups) {
            print(f"  SCC {sid}: components {members}");
        }
        disengage;
    }
}

walker ImplicationAuditor {
    has visiting: list[bool] = [];
    has n: int = 0;

    can start with Root entry {
        print("Phase 3: audit implication edges (cycle-guarded walk)");
        visit [-->];
    }

    can audit with PrimePower entry {
        if self.visiting[here.idx] {
            print(f"  cycle guard: re-entry at component {here.idx}");
            disengage;
        }
        self.visiting[here.idx] = True;
        print(f"  auditing component {here.idx} (p={here.p})");
        visit [->:Implies:->] else { };
        self.visiting[here.idx] = False;
        visit [-->];
    }
}

