"""EL-36 desktop test matrix: verification suites depend on foundation work, verify contract artifacts, and gate release."""

node MatrixEntity {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;

    def is_clear() -> bool {
        return self.available;
    }
}

node VerificationSuite(MatrixEntity) {
    has category: str = "";
    has passed: bool = False;

    override def is_clear() -> bool {
        return self.available and self.passed;
    }
}

node ContractArtifact(MatrixEntity) {
    has kind: str = "";
    has drift_detected: bool = False;

    override def is_clear() -> bool {
        return self.available and (not self.drift_detected);
    }
}

node ReleaseGate(MatrixEntity) {
    has gate_id: str = "";
    has open: bool = False;

    override def is_clear() -> bool {
        return self.open;
    }
}

edge DependsOn { has note: str = ""; }
edge Verifies { has surface: str = ""; }
edge Blocks { has track: str = ""; }

walker ReleaseAuditor {
    has evidence: list[str] = [];
    has on_path: list[str] = [];
    has release_blocked: bool = False;

    can start with Root entry {
        print("Auditing EL-36 desktop verification matrix");
        visit [-->];
    }

    can audit_suite with VerificationSuite entry {
        if here.title in self.on_path {
            msg = f"CYCLE detected at {here.title}";
            print(msg);
            self.evidence.append(msg);
            self.release_blocked = True;
            disengage;
        }
        self.on_path.append(here.title);
        if not here.is_clear() {
            finding = f"SUITE FAIL: {here.title} [{here.category}]";
            self.evidence.append(finding);
            print(finding);
            self.release_blocked = True;
        } else {
            outcome = "PASS" if here.passed else "HOLD";
            print(f"[{outcome}] {here.category}: {here.title} (#{here.year})");
        }
        visit [->:Verifies:->] else { }
        visit [->:DependsOn:->] else { visit [-->]; };
        if len(self.on_path) > 0 {
            self.on_path.pop();
        }
    }

    can check_artifact with ContractArtifact entry {
        tag = "CLEAN" if here.is_clear() else "DRIFT";
        print(f"[{tag}] {here.kind}: {here.title}");
        if not here.is_clear() {
            self.release_blocked = True;
            self.evidence.append(f"DRIFT: {here.title}");
        }
        visit [-->];
    }

    can judge_gate with ReleaseGate entry {
        open_now = (not self.release_blocked) and here.available;
        here.open = open_now;
        state_label = "OPEN" if open_now else "BLOCKED";
        print(f"Release gate {here.gate_id} (#{here.year}): {state_label}");
        if len(self.evidence) > 0 {
            print(f"  findings recorded: {len(self.evidence)}");
        }
        visit [-->];
    }
}

