"""Bounded hop-depth graph retrieval ablation: cycle-safe, path-preserving passage sweep."""

node Passage {
    has title: str = "";
    has text: str = "";
    has facet_refs: int = 1;
}

node BenchmarkQuery {
    has query_id: int = 0;
    has label: str = "";
}

edge Seeds {
    has priority: int = 1;
}

edge References {
    has evidence: str = "";
    has weight: float = 0.0;
}

walker HopAblation {
    has max_hops: int = 2;
    has depth: int = 0;
    has visited: list[str] = [];
    has path: list[str] = [];
    has collected: int = 0;
    has two_facet_hits: int = 0;
    has run_label: str = "";

    can start with Root entry {
        print(f"== ablation {self.run_label} max_hops={self.max_hops} ==");
        self.collected = 0;
        self.two_facet_hits = 0;
        visit [-->];
        facet_recall = self.two_facet_hits / 6.0;
        print(
            f"SUMMARY {self.run_label}: passages={self.collected} "
            f"two_facet_hits={self.two_facet_hits} "
            f"two_facet_recall={facet_recall}"
        );
    }

    can run_query with BenchmarkQuery entry {
        print(f"Q{here.query_id} {here.label}");
        self.depth = 0;
        self.visited = [];
        self.path = [];
        visit [->:Seeds:->] else {
            print(f"  empty seed — traversal skipped");
        };
        visit [-->] else { disengage; };
    }

    can traverse with Passage entry {
        key = here.title;
        if key in self.visited {
            print(f"    cycle_guard: blocked revisit of {key}");
        } else {
            self.visited.append(key);
            self.path.append(key);
            self.collected += 1;
            facet_tag = "TWO-FACET" if here.facet_refs == 2 else "std";
            if here.facet_refs == 2 {
                self.two_facet_hits += 1;
            }
            print(
                f"    hop {self.depth}/{self.max_hops} {facet_tag} "
                f"{key} path={self.path}"
            );
            if self.depth < self.max_hops {
                self.depth += 1;
                visit [->:References:->] else {
                    # no outgoing references from this depth
                };
                self.depth -= 1;
            }
            self.path.pop();
        }
        visit [-->] else { disengage; };
    }
}

with entry {
    p0 = Passage(title="seed-A", text="entry passage", facet_refs=1);
    p1 = Passage(title="hop1-B", text="first-hop context", facet_refs=1);
    p2 = Passage(
        title="hop2-C", text="second-hop two-facet target", facet_refs=2
    );
    p3 = Passage(title="hop3-D", text="third-hop graph noise", facet_refs=1);
    p_noise = Passage(title="orphan-E", text="unreachable noise", facet_refs=1);

    p0 +>:References(evidence="cite-AB", weight=0.92):+> p1;
    p1 +>:References(evidence="cite-BC", weight=0.87):+> p2;
    p2 +>:References(evidence="cite-CA", weight=0.31):+> p0;
    p2 +>:References(evidence="", weight=0.40):+> p3;
    p1 +>:References(evidence="cite-BN", weight=0.15):+> p_noise;

    q9 = BenchmarkQuery(query_id=9, label="two-ref facet");
    q14 = BenchmarkQuery(query_id=14, label="two-ref facet");
    q17 = BenchmarkQuery(query_id=17, label="two-ref facet");
    q18 = BenchmarkQuery(query_id=18, label="two-ref facet");
    q19 = BenchmarkQuery(query_id=19, label="two-ref facet");
    q20 = BenchmarkQuery(query_id=20, label="two-ref facet");
    q_empty = BenchmarkQuery(query_id=0, label="empty-seed control");

    root ++> q9 ++> q14 ++> q17 ++> q18 ++> q19 ++> q20 ++> q_empty;
    q9 +>:Seeds(priority=1):+> p0;
