"""CDG implication graph: prime-power components, forced residue edges, and iterative Tarjan SCC grouping."""

node PrimePower {
    has p: int = 0;
    has two_e: int = 0;
    has idx: int = 0;
}

edge Implies {
    has modulus: int = 0;
}

walker ForcedCandidateBuilder {
    has registry: list[PrimePower] = [];
    has adj: list[list[int]] = [];

    def divisors_gt_one(n: int) -> list[int] {
        out: list[int] = [];
        for d in range(2, n + 1) {
            if n % d == 0 {
                out.append(d);
            }
        }
        return out;
    }

    can start with Root entry {
        print("Phase 1: derive forced-candidate implication edges");
        visit [-->[?:PrimePower]];
    }

    can map_forced with PrimePower entry {
        modulus_n = here.two_e + 1;
        for d in self.divisors_gt_one(modulus_n) {
            for comp in self.registry {
                if comp.p % d == 1 and comp.idx != here.idx {
                    here +>:Implies(modulus=d):+> comp;
                    self.adj[here.idx].append(comp.idx);
                    print(
                        f"  [{here.idx}] --mod {d}--> [{comp.idx}] "
                        f"(p={comp.p})"
                    );
                }
            }
        }
    }
}

walker SccComputer {
    has adj: list[list[int]] = [];
    has n: int = 0;
    has index: list[int] = [];
    has lowlink: list[int] = [];
    has on_stack: list[bool] = [];
    has stack: list[int] = [];
    has comp_to_scc: list[int] = [];
    has scc_groups: list[list[int]] = [];
    has time: int = 0;
    has scc_count: int = 0;
    has work: list[int] = [];
    has work_phase: list[int] = [];
    has work_iter: list[int] = [];

    def tarjan_from(start: int) -> None {
        self.work.append(start);
        self.work_phase.append(0);
        self.work_iter.append(0);
        while len(self.work) > 0 {
            v = self.work[-1];
            phase = self.work_phase[-1];
            if phase == 0 {
                self.index[v] = self.time;
                self.lowlink[v] = self.time;
                self.time += 1;
                self.stack.append(v);
                self.on_stack[v] = True;
                self.work_phase[-1] = 1;
            } else {
                neighbors = self.adj[v];
                i = self.work_iter[-1];
                if i < len(neighbors) {
                    w = neighbors[i];
                    self.work_iter[-1] = i + 1;
                    if self.index[w] < 0 {
                        self.work.append(w);
                        self.work_phase.append(0);
                        self.work_iter.append(0);
                    } elif self.on_stack[w] {
                        new_low = self.index[w];
                        if new_low < self.lowlink[v] {
                            self.lowlink[v] = new_low;
                        }
                    }
                } else {
                    if self.lowlink[v] == self.index[v] {
                        group: list[int] = [];
                        while True {
                            w = self.stack.pop();
                            self.on_stack[w] = False;
                            self.comp_to_scc[w] = self.scc_count;
                            group.append(w);
                            if w == v {
                                break;
                            }
                        }
                        self.scc_groups.append(group);
                        self.scc_count += 1;
                    }
                    popped_low = self.lowlink[v];
                    self.work.pop();
                    self.work_phase.pop();
                    self.work_iter.pop();
                    if len(self.work) > 0 {
                        parent = self.work[-1];
                        if popped_low < self.lowlink[parent] {
                            self.lowlink[parent] = popped_low;
                        }
                    }
                }
            }
        }
    }

    def run_tarjan() -> None {
        for v in range(self.n) {
            if self.index[v] < 0 {
                self.tarjan_from(v);
            }
        }
    }

    can start with Root entry {
        print("Phase 2: iterative Tarjan SCC over implication graph");
        self.run_tarjan();
        for (sid, members) in enumerate(self.scc_groups) {
            print(f"  SCC {sid}: components {members}");
        }
        visit [-->[?:PrimePower]] else { disengage; };
    }

    can label with PrimePower entry {
        sid = self.comp_to_scc[here.idx];
        print(f"  component {here.idx} (p={here.p}) -> SCC {sid}");
    }
}

walker ImplicationAuditor {
    has visiting: list[bool] = [];
    has n: int = 0;

    can start with Root entry {
        print("Phase 3: audit implication edges (cycle-guarded walk)");
        visit [-->[?:PrimePower]];
    }

    can audit with PrimePower entry {
        if self.visiting[here.idx] {
            print(f"  cycle guard: re-entry at component {here.idx}");
            disengage;
        }
        self.visiting[here.idx] = True;
        print(f"  auditing component {here.idx} (p={here.p})");
        visit [->:Implies:->] else { };
        self.visiting[here.idx] = False;
    }
}

with entry {
    c0 = PrimePower(p=3, two_e=2, idx=0);
    c1 = PrimePower(p=7, two_e=6, idx=1);
    c2 = PrimePower(p=13, two_e=12, idx=2);
    c3 = PrimePower(p=15, two_e=2, idx=3);
    registry = [c0, c1, c2, c3];
    root ++> c0;
    root ++> c1;
    root ++> c2;
    root ++> c3;

    adj: list[list[int]] = [[], [], [], []];

    builder = ForcedCandidateBuilder(registry=registry, adj=adj);
    root spawn builder;

    scc = SccComputer(adj=adj, n=4);
    scc.index = [-1, -1, -1, -1];
    scc.lowlink = [-1, -1, -1, -1];
    scc.on_stack = [False, False, False, False];
    scc.comp_to_scc = [-1, -1, -1, -1];
    root spawn scc;

    auditor = ImplicationAuditor(n=4);
    auditor.visiting = [False, False, False, False];
    root spawn auditor;
}

"""EL-36 desktop test matrix: walk dependency-ordered verification suites, detect contract drift, and judge the release gate."""

node MatrixEntity {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;

    def is_clear() -> bool {
        return self.available;
    }
}

node VerificationSuite(MatrixEntity) {
    has category: str = "";
    has passed: bool = False;

    override def is_clear() -> bool {
        return self.available and self.passed;
    }
}

node ContractArtifact(MatrixEntity) {
    has kind: str = "";
    has drift_detected: bool = False;

    override def is_clear() -> bool {
        return self.available and (not self.drift_detected);
    }
}

node ReleaseGate(MatrixEntity) {
    has gate_id: str = "";
    has open: bool = False;

    override def is_clear() -> bool {
        return self.open;
    }
}

edge DependsOn { has note: str = ""; }
edge Verifies { has surface: str = ""; }
edge Blocks { has track: str = ""; }

walker MatrixAuditor {
    has visited: list[str] = [];
    has dep_stack: list[str] = [];
    has findings: list[str] = [];
    has blocked: bool = False;

    can start with Root entry {
        print("Auditing EL-36 desktop verification matrix");
        visit [-->[?:VerificationSuite]] else { disengage; };
    }

    can walk_deps with VerificationSuite entry {
        if here.title in self.dep_stack {
            note = f"CYCLE detected at {here.title}";
            print(note);
            self.findings.append(note);
            self.blocked = True;
            disengage;
        }
        if here.title in self.visited {
            disengage;
        }
        self.visited.append(here.title);
        self.dep_stack.append(here.title);
        if not here.is_clear() {
            line = f"SUITE FAIL: {here.title} [{here.category}]";
            print(line);
            self.findings.append(line);
            self.blocked = True;
        } else {
            mark = "PASS" if here.passed else "HOLD";
            print(f"[{mark}] {here.category}: {here.title} (#{here.year})");
        }
        visit [->:Verifies:->] else { disengage; };
        visit [->:DependsOn:->] else { disengage; };
        visit [->:Blocks:->] else { disengage; };
        if len(self.dep_stack) > 0 {
            self.dep_stack.pop();
        }
    }

    can check_contract with ContractArtifact entry {
        if here.title in self.visited {
            disengage;
        }
        self.visited.append(here.title);
        tag = "CLEAN" if here.is_clear() else "DRIFT";
        print(f"[{tag}] {here.kind}: {here.title}");
        if not here.is_clear() {
            self.blocked = True;
            self.findings.append(f"DRIFT: {here.title}");
        }
        disengage;
    }

    can judge with ReleaseGate entry {
        if here.title in self.visited {
            disengage;
        }
        self.visited.append(here.title);
        gate_open = (not self.blocked) and here.available;
        here.open = gate_open;
        state = "OPEN" if gate_open else "BLOCKED";
        print(f"Release gate {here.gate_id} (#{here.year}): {state}");
        if len(self.findings) > 0 {
            print(f"  findings recorded: {len(self.findings)}");
        }
        disengage;
    }
}

