"""Bounded hop-depth graph retrieval ablation: cycle-safe, path-preserving passage sweep."""

node Passage {
    has title: str = "";
    has text: str = "";
    has facet_refs: int = 1;
}

node BenchmarkQuery {
    has query_id: int = 0;
    has label: str = "";
}

node RunStats {
    has collected: int = 0;
    has two_facet_hits: int = 0;
}

edge Seeds {
    has priority: int = 1;
}

edge References {
    has evidence: str = "";
    has weight: float = 0.0;
}

walker SeedSweep {
    has max_hops: int = 2;
    has depth: int = 0;
    has visited: list[str] = [];
    has path: list[str] = [];
    has stats: RunStats;

    can hop with Passage entry {
        key = here.title;
        do_expand = False;
        if key in self.visited {
            print(f"    cycle_guard: blocked revisit of {key}");
        } else {
            self.visited.append(key);
            self.path.append(key);
            self.stats.collected += 1;
            facet_tag = "TWO-FACET" if here.facet_refs == 2 else "std";
            if here.facet_refs == 2 {
                self.stats.two_facet_hits += 1;
            }
            print(
                f"    hop {self.depth}/{self.max_hops} {facet_tag} "
                f"{key} path={self.path}"
            );
            do_expand = self.depth < self.max_hops;
        }
        if do_expand {
            self.depth += 1;
            visit [->:References:->] else {
                disengage;
            };
            self.depth -= 1;
        }
        visit [-->];
    }
}

walker HopAblation {
    has max_hops: int = 2;
    has stats: RunStats;
    has run_label: str = "";

    can start with Root entry {
        self.stats = RunStats();
        print(f"== ablation {self.run_label} max_hops={self.max_hops} ==");
        visit [-->];
        facet_recall = self.stats.two_facet_hits / 6.0;
        print(
            f"SUMMARY {self.run_label}: passages={self.stats.collected} "
            f"two_facet_hits={self.stats.two_facet_hits} "
            f"two_facet_recall={facet_recall}"
        );
    }

    can run_query with BenchmarkQuery entry {
        print(f"Q{here.query_id} {here.label}");
        visit [->:Seeds:->] else {
            print(f"  empty seed — traversal skipped");
        };
        visit [-->];
    }

    can on_seed with Passage entry {
        here spawn SeedSweep(
            max_hops=self.max_hops,
            stats=self.stats,
            depth=0,
            visited=[],
            path=[]
        );
        visit [-->];
    }
}

