}

"""Canon v2 substrate demo: spine-anchored DEPENDS closure, SUCCEEDS frontier heads, and stale propagation."""

node Proposition {
    has title: str = "";
    has committed: bool = True;
    has demoted: bool = False;
}

node SpineAnchor(Proposition) {
    has term: str = "";
}

node Claim(Proposition) {
    has year: int = 0;
}

node Binding {
    has term: str = "";
    has committed: bool = True;
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

edge Depends {
    has polarity: int = 1;
}

edge Succeeds { }

walker FrontierResolver {
    can start with Root entry {
        visit [-->[?:Binding]];
    }

    can head with Binding entry {
        visit [->:Succeeds:->] else {
            tag = "frontier" if here.committed else "retracted";
            print(f"[{tag}] {here.term}");
            disengage;
        }
    }
}

walker ClosureAuditor {
    has trail: list[str] = [];
    has anchored: bool = False;
    has tracing: bool = False;

    can start with Root entry {
        visit [-->[?:Claim]];
    }

    can audit with Claim entry {
        if not self.tracing {
            self.trail = [];
            self.anchored = False;
            if here.demoted {
                print(f"[STALE] {here.title}: demoted ground");
            } else {
                self.tracing = True;
                visit [->:Depends:->] else {
                    visit [-->[?:SpineAnchor]] else {
                        self.anchored = False;
                    };
                };
                self.tracing = False;
                verdict = "GROUNDED" if self.anchored else "UNGROUNDED";
                print(f"[{verdict}] {here.title}");
            }
        }
    }

    can reach_anchor with SpineAnchor entry {
        if self.tracing {
            self.anchored = True;
            disengage;
        }
    }

    can follow_support with Claim entry {
        if self.tracing {
            if here.demoted {
                self.anchored = False;
                disengage;
            }
            if here.title in self.trail {
                print(f"[CYCLE] depends loop at {here.title}");
                disengage;
            }
            self.trail.append(here.title);
            visit [->:Depends:->] else {
                visit [-->[?:SpineAnchor]] else {
                    self.anchored = False;
                };
            };
        }
    }
}

