"""Persistent directed graph: vertices and weighted edges model graph values; walkers implement reachability, traversal, cycle detection, topological integration, and cascade invalidation."""

node Graph {
    has name: str = "";
    has persistent: bool = True;
}

node Vertex {
    has label: str = "";
    has active: bool = True;
    has version: int = 0;
}

edge Directed {
    has weight: int = 1;
}

walker ReachabilityProbe {
    has target_label: str = "";
    has found: bool = False;
    has seen: list[str] = [];

    def label_seen(label: str) -> bool {
        for item in self.seen {
            if item == label {
                return True;
            }
        }
        return False;
    }

    can probe with Vertex entry {
        if here.label == self.target_label {
            self.found = True;
            disengage;
        }
        if self.label_seen(here.label) {
            disengage;
        }
        next_seen = self.seen + [here.label];
        self.seen = next_seen;
        visit [->:Directed:->] else { disengage; };
    }
}

walker TraversalAuditor {
    has seen: list[str] = [];
    has order: list[str] = [];

    def label_seen(label: str) -> bool {
        for item in self.seen {
            if item == label {
                return True;
            }
        }
        return False;
    }

    can enter with Graph entry {
        visit [->:Directed:->] else { disengage; };
    }

    can step with Vertex entry {
        if self.label_seen(here.label) {
            disengage;
        }
        next_seen = self.seen + [here.label];
        self.seen = next_seen;
        next_order = self.order + [here.label];
        self.order = next_order;
        visit [->:Directed:->] else { disengage; };
    }
}

walker CycleGuard {
    has seen: list[str] = [];
    has detected: bool = False;

    def label_seen(label: str) -> bool {
        for item in self.seen {
            if item == label {
                return True;
            }
        }
        return False;
    }

    can detect with Vertex entry {
        if self.label_seen(here.label) {
            self.detected = True;
            disengage;
        }
        next_seen = self.seen + [here.label];
        self.seen = next_seen;
        visit [->:Directed:->] else { disengage; };
    }
}

walker TopoIntegrator {
    has seen: list[str] = [];
    has order: list[str] = [];

    def label_seen(label: str) -> bool {
        for item in self.seen {
            if item == label {
                return True;
            }
        }
        return False;
    }

    can integrate with Graph entry {
        visit [->:Directed:->] else { disengage; };
    }

    can integrate with Vertex entry {
        if self.label_seen(here.label) {
            disengage;
        }
        next_seen = self.seen + [here.label];
        self.seen = next_seen;
        visit [->:Directed:->] else { disengage; };
    }

    can finish with Vertex exit {
        next_order = self.order + [here.label];
        self.order = next_order;
    }
}

walker InvalidateCascade {
    has touch_count: int = 0;

    can invalidate with Vertex entry {
        if not here.active {
            visit [->:Directed:->] else { disengage; };
        }
        here.active = False;
        self.touch_count += 1;
        visit [->:Directed:->] else { disengage; };
    }
}

with entry {
    g = Graph(name="persistent-demo", persistent=True);
    root ++> g;
    a = Vertex(label="A", version=1);
    b = Vertex(label="B", version=1);
    c = Vertex(label="C", version=1);
    d = Vertex(label="D", version=1);
    e = Vertex(label="E", version=1);
    f = Vertex(label="F", version=1);
    g +>:Directed(weight=1):+> a;
    a +>:Directed(weight=2):+> b;
    b +>:Directed(weight=1):+> c;
    a +>:Directed(weight=3):+> c;
    c +>:Directed(weight=1):+> d;
    e +>:Directed(weight=1):+> f;
    f +>:Directed(weight=1):+> e;

    reach = ReachabilityProbe(target_label="D");
    a spawn reach;
    reach_txt = "yes" if reach.found else "no";
    print(f"reachable A to D: {reach_txt}");

    audit = TraversalAuditor();
    g spawn audit;
    print(f"traversal order: {audit.order}");

    guard = CycleGuard();
    e spawn guard;
    cycle_txt = "yes" if guard.detected else "no";
    print(f"cycle from E: {cycle_txt}");

    topo = TopoIntegrator();
    g spawn topo;
