"""Canon v2 substrate demo: spine-anchored DEPENDS closure, SUCCEEDS frontier heads, and stale propagation."""

node Proposition {
    has title: str = "";
    has year: int = 0;
    has committed: bool = True;
    has demoted: bool = False;
}

node SpineAnchor(Proposition) {
    has term: str = "";
}

node Claim(Proposition) {
    has available: bool = True;
}

node NameBinding {
    has term: str = "";
    has title: str = "";
    has year: int = 0;
    has committed: bool = True;
    has available: bool = True;
}

edge Depends {
    has polarity: int = 1;
}

edge Succeeds { }

walker FrontierResolver {
    can start with Root entry {
        visit [-->];
    }

    can head with NameBinding entry {
        visit [->:Succeeds:->] else {
            tag = "frontier" if here.committed else "retracted";
            print(f"[{tag}] {here.term} -> {here.title} ({here.year})");
            disengage;
        }
    }
}

walker SupportTracer {
    has trail: list[str] = [];
    has origin: str = "";

    can start with Claim entry {
        self.origin = here.title;
        self.trail = [here.title];
        if here.demoted {
            print(f"[STALE] {here.title}: demoted ground");
            disengage;
        }
        visit [->:Depends:->] else {
            print(f"[UNGROUNDED] {self.origin}");
            disengage;
        };
    }

    can walk with Claim entry {
        if here.title in self.trail {
            print(f"[CYCLE] depends loop at {here.title}");
            disengage;
        }
        if here.demoted {
            print(f"[UNGROUNDED] {self.origin}");
            disengage;
        }
        self.trail.append(here.title);
        visit [->:Depends:->] else {
            print(f"[UNGROUNDED] {self.origin}");
            disengage;
        };
    }

    can found with SpineAnchor entry {
        print(f"[GROUNDED] {self.origin}");
        disengage;
    }
}

walker ClosureAuditor {
    can start with Root entry {
        visit [-->];
    }

    can audit with Claim entry {
        here spawn SupportTracer();
        visit [-->];
    }
}

with entry {
    spine = SpineAnchor(title="coupling_core", term="coupling_scales", year=2020);
    ground = Claim(title="coupling_ground", demoted=True, year=2024);
    revised = Claim(title="coupling_revised", year=2026);
    higgs = Claim(title="higgs_reframing", year=2025);
    koide = Claim(title="koide_head", year=2026);

    koide_old = NameBinding(term="koide_formula", title="koide_v1", year=2024);
    koide_new = NameBinding(term="koide_formula", title="koide_v2", year=2026);
    contested_a = NameBinding(term="higgs_mass", title="higgs_a", year=2025);
    contested_b = NameBinding(term="higgs_mass", title="higgs_b", year=2025);

    root ++> spine ++> revised ++> ground;
    revised +>:Depends(polarity=1):+> spine;
    ground +>:Depends(polarity=1):+> revised;
    root ++> higgs ++> koide;
    higgs +>:Depends(polarity=1):+> ground;
    koide +>:Depends(polarity=1):+> revised;

    root ++> koide_old;
    koide_old +>:Succeeds:+> koide_new;
    root ++> contested_a ++> contested_b;

    print("--- frontier-default reads (SUCCEEDS resolved) ---");
    root spawn FrontierResolver();

    print("--- grounded-closure audit (DEPENDS+ to spine) ---");
    root spawn ClosureAuditor();
}

