"""Belief-guided maneuver portfolio: project ScenarioBelief, expand multimodal forecasts, rank feasible maneuvers, commit with hysteresis, and fail closed through CBF."""

node PedestrianBelief {
    has track_id: str = "";
    has confidence: float = 0.0;
    has visible: bool = True;
    has stale: bool = False;
}

node ForecastMode {
    has mode_name: str = "";
    has likelihood: float = 0.0;
}

node ManeuverCandidate {
    has maneuver: str = "";
    has feasible: bool = True;
    has risk_score: float = 0.0;
    has route_progress: float = 0.0;
}

edge ProjectsTo { }

edge SpawnsCandidate { }

walker LocalPlannerPipeline {
    has best_score: float = -999.0;
    has best_maneuver: str = "stop";
    has best_risk: float = 1.0;
    has committed: str = "route_follow";
    has hold_remaining: int = 0;
    has hold_duration: int = 2;
    has switch_margin: float = 0.10;
    has max_risk: float = 0.75;
    has cbf_override: bool = False;

    def apply_commitment() {
        if self.hold_remaining > 0 {
            self.hold_remaining -= 1;
            print(
                f"[hysteresis] holding {self.committed}, "
                f"{self.hold_remaining} ticks remain"
            );
        } else {
            incumbent_score = self.route_progress_for(self.committed);
            challenger = self.best_maneuver;
            challenger_score = self.best_score;
            margin_met = challenger_score >= incumbent_score + self.switch_margin;
            if self.committed != challenger and margin_met {
                print(
                    f"[commit] switch {self.committed} -> {challenger} "
                    f"(delta={challenger_score - incumbent_score:.2f})"
                );
                self.committed = challenger;
                self.hold_remaining = self.hold_duration;
            } else {
                print(f"[commit] retain {self.committed}");
            }
        }
    }

    def route_progress_for(maneuver: str) -> float {
        if maneuver == "pass_left" {
            return 0.8;
        }
        if maneuver == "route_follow" {
            return 0.6;
        }
        if maneuver == "yield_creep" {
            return 0.4;
        }
        return 0.0;
    }

    def apply_cbf() {
        if self.best_risk > self.max_risk {
            self.cbf_override = True;
            self.committed = "stop";
            print(
                f"[CBF] fail-closed: risk {self.best_risk:.2f} "
                f"> limit {self.max_risk:.2f}"
            );
        } else {
            print(f"[CBF] approved committed maneuver {self.committed}");
        }
    }

    can start with Root entry {
        print("[pipeline] belief-guided maneuver portfolio local planner");
        visit [-->];
        self.apply_commitment();
        self.apply_cbf();
        print(
            f"[result] best={self.best_maneuver} risk={self.best_risk:.2f} "
            f"committed={self.committed} cbf_override={self.cbf_override}"
        );
    }

    can project with PedestrianBelief entry {
        if here.stale or here.confidence < 0.30 {
            print(
                f"[skip] belief {here.track_id}: "
                f"stale={here.stale} conf={here.confidence:.2f}"
            );
        } else {
            print(
                f"[project] belief {here.track_id} "
                f"visible={here.visible} conf={here.confidence:.2f}"
            );
            visit [->:ProjectsTo:->];
        }
        visit [-->];
    }

    can expand with ForecastMode entry {
        print(f"[forecast] mode={here.mode_name} likelihood={here.likelihood:.2f}");
        visit [->:SpawnsCandidate:->];
        visit [-->];
    }

    can rank with ManeuverCandidate entry {
        if not here.feasible {
            print(f"[rank] reject infeasible {here.maneuver}");
        } else {
            score = here.route_progress - here.risk_score;
            print(
                f"[rank] {here.maneuver} progress={here.route_progress:.2f} "
                f"risk={here.risk_score:.2f} score={score:.2f}"
            );
            if score > self.best_score {
                self.best_score = score;
                self.best_maneuver = here.maneuver;
                self.best_risk = here.risk_score;
            }
        }
        visit [-->];
    }
}

