"""Canon v2 substrate demo: spine-anchored DEPENDS closure, SUCCEEDS frontier heads, and stale propagation."""

node Proposition {
    has title: str = "";
    has year: int = 0;
    has committed: bool = True;
    has demoted: bool = False;
}

node SpineAnchor(Proposition) {
    has term: str = "";
}

node Claim(Proposition) {
    has available: bool = True;
}

node NameBinding {
    has term: str = "";
    has title: str = "";
    has year: int = 0;
    has committed: bool = True;
    has available: bool = True;
}

edge Depends {
    has polarity: int = 1;
}

edge Succeeds { }

walker SuccessionHead {
    has seen: list[str] = [];

    can start with NameBinding entry {
        self.seen = [here.title];
        visit [->:Succeeds:->] else {
            tag = "frontier" if here.committed else "retracted";
            print(f"[{tag}] {here.term} -> {here.title} ({here.year})");
            disengage;
        };
    }

    can hop with NameBinding entry {
        if here.title in self.seen {
            print(f"[CYCLE] succession at {here.title}");
            disengage;
        }
        self.seen.append(here.title);
        visit [->:Succeeds:->] else {
            tag = "frontier" if here.committed else "retracted";
            print(f"[{tag}] {here.term} -> {here.title} ({here.year})");
            disengage;
        };
    }
}

walker FrontierCatalog {
    has seen_nodes: list[str] = [];
    has reported_terms: list[str] = [];

    can start with Root entry {
        visit [-->] else { disengage; };
    }

    can scan with NameBinding entry {
        nid = here.title;
        if nid in self.seen_nodes {
            disengage;
        }
        self.seen_nodes.append(nid);
        term_key = here.term;
        if term_key not in self.reported_terms {
            self.reported_terms.append(term_key);
            here spawn SuccessionHead();
        }
        visit [-->] else { disengage; };
    }

    can pass with Claim | SpineAnchor entry {
        nid = here.title;
        if nid in self.seen_nodes {
            disengage;
        }
        self.seen_nodes.append(nid);
        visit [-->] else { disengage; };
    }
}

walker SupportTracer {
    has trail: list[str] = [];
    has origin: str = "";

    can start with Claim entry {
        self.origin = here.title;
        self.trail = [here.title];
        if here.demoted {
            print(f"[STALE] {self.origin}: demoted ground");
            disengage;
        }
        visit [->:Depends:->] else {
            print(f"[UNGROUNDED] {self.origin}");
            disengage;
        };
    }

    can descend with Claim entry {
        if here.title in self.trail {
            print(f"[CYCLE] depends loop at {here.title}");
            disengage;
        }
        if here.demoted {
            print(f"[UNGROUNDED] {self.origin}");
            disengage;
        }
        self.trail.append(here.title);
        visit [->:Depends:->] else {
            print(f"[UNGROUNDED] {self.origin}");
            disengage;
        };
    }

    can anchor with SpineAnchor entry {
        print(f"[GROUNDED] {self.origin}");
        disengage;
    }
}

walker ClosureAuditor {
    has seen_nodes: list[str] = [];

    can start with Root entry {
        visit [-->] else { disengage; };
    }

    can audit with Claim entry {
        nid = here.title;
        if nid in self.seen_nodes {
            disengage;
        }
        self.seen_nodes.append(nid);
        here spawn SupportTracer();
        visit [-->] else { disengage; };
    }

    can pass with SpineAnchor | NameBinding entry {
        nid = here.title;
        if nid in self.seen_nodes {
            disengage;
        }
        self.seen_nodes.append(nid);
        visit [-->] else { disengage; };
    }
}

