"""Cycle-safe comment log: cyclic replyTo chains render flat instead of vanishing."""

node Comment {
    has comment_id: str = "";
    has body: str = "";
    has author: str = "";
    has stale_reply_to: str = "";
    has has_parent: bool = False;
}

edge ReplyTo { }

edge HasReply { }

node CommentLog {
    has cycle_ids: list[str] = [];
}

walker CycleDetector {
    has trail: list[str] = [];
    has log: CommentLog;

    can start with CommentLog entry {
        self.log = here;
        visit [--> else { disengage; }];
    }

    can inspect with Comment entry {
        self.trail = [];
        self.trail.append(here.comment_id);
        visit [->:ReplyTo:->] else { };
        visit [--> else { disengage; }];
    }

    can follow with Comment entry {
        cid = here.comment_id;
        if cid in self.trail {
            in_cycle = False;
            for tid in self.trail {
                if tid == cid {
                    in_cycle = True;
                }
                if in_cycle {
                    if tid not in self.log.cycle_ids {
                        self.log.cycle_ids.append(tid);
                    }
                }
            }
            if cid not in self.log.cycle_ids {
                self.log.cycle_ids.append(cid);
            }
            disengage;
        }
        self.trail.append(cid);
        visit [->:ReplyTo:->] else { };
        trimmed: list[str] = [];
        for tid in self.trail {
            if tid != cid {
                trimmed.append(tid);
            }
        }
        self.trail = trimmed;
    }
}

walker SubtreeWalker {
    has depth: int = 1;

    can start with Comment entry {
        visit [->:HasReply:->] else { disengage; };
    }

    can show_reply with Comment entry {
        indent = self.make_indent();
        print(f"{indent}{here.author}: {here.body}");
        saved_depth = self.depth;
        child_depth = self.depth + 1;
        self.depth = child_depth;
        visit [->:HasReply:->] else { };
        self.depth = saved_depth;
    }

    def make_indent() -> str {
        spaces = "";
        i = 0;
        while i < self.depth {
            spaces += "  ";
            i += 1;
        }
        return spaces;
    }
}

walker CommentLogRenderer {
    has log: CommentLog;

    can start with CommentLog entry {
        self.log = here;
        print("--- Comments Log ---");
        visit [--> else { disengage; }];
    }

    can render with Comment entry {
        cid = here.comment_id;
        if cid in self.log.cycle_ids {
            print(f"FLAT {here.author}: {here.body} (cycle)");
        } else {
            if here.stale_reply_to != "" {
                print(
                    f"FLAT {here.author}: {here.body} "
                    f"(orphan reply to {here.stale_reply_to})"
                );
            } else {
                if not here.has_parent {
                    print(f"THREAD {here.author}: {here.body}");
                    here spawn SubtreeWalker(depth=1);
                }
            }
        }
        visit [--> else { disengage; }];
    }
}

with entry {
    log = CommentLog();
    root ++> log;

    welcome = Comment(comment_id="c1", body="Sprint kickoff", author="Sam");
    reply1 = Comment(comment_id="c2", body="Sounds good", author="Alex");
    reply2 = Comment(comment_id="c3", body="+1", author="Jordan");
    loop_a = Comment(comment_id="c4", body="Cycle A", author="Pat");
    loop_b = Comment(comment_id="c5", body="Cycle B", author="Quinn");
    narcissist = Comment(comment_id="c6", body="I reply to myself", author="Riley");
    ghost = Comment(
        comment_id="c7",
        body="Orphan comment",
        author="Casey",
        stale_reply_to="missing-99"
    );

    log ++> welcome ++> reply1 ++> reply2;
    log ++> loop_a ++> loop_b;
    log ++> narcissist;
    log ++> ghost;

    reply1.has_parent = True;
    reply1 +>:ReplyTo:+> welcome;
    welcome +>:HasReply:+> reply1;
    reply2.has_parent = True;
    reply2 +>:ReplyTo:+> reply1;
    reply1 +>:HasReply:+> reply2;

    loop_a.has_parent = True;
    loop_a +>:ReplyTo:+> loop_b;
    loop_b.has_parent = True;
    loop_b +>:ReplyTo:+> loop_a;

    narcissist.has_parent = True;
    narcissist +>:ReplyTo:+> narcissist;

    log spawn CycleDetector();
    log spawn CommentLogRenderer();
}

"""re-spirv loop DCE: OpPhi back-edge out-degree miscount breaks optimized shaders."""

node Instruction {
    has inst_id: int = 0;
    has opcode: str = "";
    has alive: bool = True;
    has out_degree: int = 0;
}

edge Uses { }
edge BackEdge { }

walker TopoSort {
    has order: list[int] = [];

    can start with Root entry {
        visit [-->] else { disengage; };
    }

    can walk with Instruction entry {
        self.order.append(here.inst_id);
        visit [->:Uses:->] else { disengage; };
    }
}

walker OutDegreeSeeder {
    has count_back_edges: bool = False;
    has scratch: int = 0;
    has target: Instruction;

    can start with Root entry {
        visit [-->] else { disengage; };
    }

    can seed with Instruction entry {
        self.target = here;
        self.scratch = 0;
        visit [->:Uses:->] else {
            if self.count_back_edges {
                visit [->:BackEdge:->] else {
                    self.target.out_degree = self.scratch;
                    visit [-->] else { disengage; };
                };
            } else {
                self.target.out_degree = self.scratch;
                visit [-->] else { disengage; };
            }
        };
    }

    can tally with Instruction entry {
        self.scratch += 1;
        visit [->:Uses:->] else {
            if self.count_back_edges {
                visit [->:BackEdge:->] else { disengage; };
            } else {
                disengage;
            }
        };
    }
}

walker DeadCodeEliminator {
    has topo: list[int] = [];
    has removed: list[int] = [];

    can start with Root entry {
        idx = len(self.topo) - 1;
        while idx >= 0 {
            visit [-->[?:Instruction]] else { disengage; };
            idx -= 1;
        }
    }

    can purge with Instruction entry {
        if here.inst_id not in self.topo {
            visit [-->] else { disengage; };
            return;
        }
        if here.out_degree == 0 and here.opcode != "OpLabel" {
            here.alive = False;
            self.removed.append(here.inst_id);
            if here.opcode == "OpPhi" {
                visit [<--:BackEdge:--] else { disengage; };
            }
        }
        visit [-->] else { disengage; };
    }

    can decr_source with Instruction entry {
        if here.alive {
            here.out_degree -= 1;
        }
        visit [<--:BackEdge:--] else { disengage; };
    }
}

walker ForwardRefValidator {
    has dangling: list[int] = [];

    can start with Root entry {
        visit [-->] else { disengage; };
    }

    can check_phi with Instruction entry {
        if here.opcode != "OpPhi" {
            visit [-->] else { disengage; };
            return;
        }
        visit [<--:BackEdge:--] else { disengage; };
    }

    can probe_operand with Instruction entry {
        if not here.alive {
            self.dangling.append(here.inst_id);
        }
        visit [<--:BackEdge:--] else { disengage; };
    }
}

walker OptimizerRun {
    has count_back_edges: bool = False;
    has topo: list[int] = [];
    has removed: list[int] = [];
    has dangling: list[int] = [];

    can start with Root entry {
        sorter = TopoSort();
        root spawn sorter;
        self.topo = sorter.order;

        seeder = OutDegreeSeeder(count_back_edges=self.count_back_edges);
        root spawn seeder;

        dce = DeadCodeEliminator(topo=self.topo);
        root spawn dce;
        self.removed = dce.removed;

        validator = ForwardRefValidator();
        root spawn validator;
        self.dangling = validator.dangling;
    }
}

with entry {
    header = Instruction(inst_id=10, opcode="OpLabel");
    phi = Instruction(inst_id=41, opcode="OpPhi");
    body = Instruction(inst_id=11, opcode="OpLabel");
    iadd = Instruction(inst_id=35, opcode="OpIAdd");

    root ++> header ++> phi ++> body;
    phi +>:Uses:+> iadd;
    iadd +>:BackEdge:+> phi;

    print("=== stock adjacency (back edges omitted from out-degree) ===");
    buggy = OptimizerRun(count_back_edges=False);
    root spawn buggy;
    print(f"topo order: {buggy.topo}");
    print(f"removed: {buggy.removed}");
    print(f"forward-ref violations: {buggy.dangling}");
  status = "CORRUPT" if len(buggy.dangling) > 0 else "valid";
    print(f"module status: {status}");

    header.alive = True;
    phi.alive = True;
    body.alive = True;
    iadd.alive = True;
    header.out_degree = 0;
    phi.out_degree = 0;
    body.out_degree = 0;
    iadd.out_degree = 0;

    print("");
    print("=== patched (back edges counted into out-degree) ===");
    fixed = OptimizerRun(count_back_edges=True);
    root spawn fixed;
    print(f"topo order: {fixed.topo}");
    print(f"removed: {fixed.removed}");
    print(f"forward-ref violations: {fixed.dangling}");
    fixed_status = "CORRUPT" if len(fixed.dangling) > 0 else "valid";
    print(f"module status: {fixed_status}");
}

"""Label-aware augmentation lineage: versioned policies, stable per-sample seeds, and dataset-to-model artifacts."""

node SourceDataset {
    has name: str = "";
    has export_format: str = "yolo";
    has sample_count: int = 0;
}

node AugPolicy {
    has policy_name: str = "";
    has horizontal_flip_p: float = 0.5;
    has brightness_p: float = 0.2;
    has artifact_json: str = "";

    def serialize() -> str {
        return f'{{"hflip_p":{self.horizontal_flip_p},"bc_p":{self.brightness_p}}}';
    }
}

node TrainingSample {
    has sample_id: str = "";
    has sample_idx: int = 0;
    has class_labels: list[str] = [];
    has bbox_count: int = 0;
    has transform_seed: int = 0;
    has augmented: bool = False;
}

node AugmentedDataset {
    has name: str = "";
    has pipeline_seed: int = 0;
    has samples_ready: int = 0;
}

node TrainedModel {
    has model_name: str = "";
    has version: str = "";
}

edge Contains { }
edge GovernedBy { has pipeline_seed: int = 0; }
edge LineageFrom { }
edge TrainsOn { }

walker LineageRunner {
    has pipeline_seed: int = 5191;
    has policy_artifact: str = "";
    has augmented_count: int = 0;
    has seen_ids: list[str] = [];

    can start with Root entry {
        print("=== augmentation lineage: source -> policy+seed -> dataset -> model ===");
        visit [-->];
    }

    can ingest_source with SourceDataset entry {
        print(f"Source dataset: {here.name} ({here.export_format}, {here.sample_count} samples)");
        visit [->:Contains:->];
        visit [-->];
    }

    can materialize_policy with AugPolicy entry {
        here.artifact_json = here.serialize();
        self.policy_artifact = here.artifact_json;
        print(f"Policy artifact '{here.policy_name}': {here.artifact_json}");
        visit [-->];
    }

    can prepare_output with AugmentedDataset entry {
        self.pipeline_seed = here.pipeline_seed;
        print(f"Augmented dataset '{here.name}' using pipeline_seed={here.pipeline_seed}");
        visit [-->];
    }

    can augment_sample with TrainingSample entry {
        for sid in self.seen_ids {
            if sid == here.sample_id {
                print(f"CYCLE GUARD: sample {here.sample_id} already augmented — stopping");
                disengage;
            }
        }
        self.seen_ids.append(here.sample_id);
        stable_seed = self.pipeline_seed * 1000 + here.sample_idx;
        flip = (stable_seed % 2) == 0;
        here.transform_seed = stable_seed;
        here.augmented = True;
        self.augmented_count += 1;
        aug_tag = "HFLIP+labels" if flip else "labels-only";
        label_text = ",".join(here.class_labels);
        print(f"  [{here.sample_id}] seed={stable_seed} labels=[{label_text}] "
              f"bboxes={here.bbox_count} -> {aug_tag}");
        visit [-->] else { disengage; };
    }

    can finalize_model with TrainedModel entry {
        print(f"Model artifact: {here.model_name} ({here.version})");
        print(f"Lineage complete: export -> policy({self.policy_artifact}) "
              f"+ seed({self.pipeline_seed}) -> {self.augmented_count} transformed samples -> model");
        disengage;
    }
}

with entry {
    source = SourceDataset(name="fiftyone_coco_yolo", export_format="yolo", sample_count=3);
    policy = AugPolicy(policy_name="detect_v1", horizontal_flip_p=0.5, brightness_p=0.2);
    aug = AugmentedDataset(name="aug_train_v1", pipeline_seed=5191);
    model = TrainedModel(model_name="yolov8n", version="run-001");

    s1 = TrainingSample(sample_id="img_001", sample_idx=1, class_labels=["person"], bbox_count=2);
    s2 = TrainingSample(sample_id="img_002", sample_idx=2, class_labels=["car", "person"], bbox_count=3);
    s3 = TrainingSample(sample_id="img_003", sample_idx=3, class_labels=["dog"], bbox_count=1);

    root ++> source ++> policy ++> aug ++> model;
    source +>:Contains:+> s1;
    source +>:Contains:+> s2;
    source +>:Contains:+> s3;
    policy +>:GovernedBy(pipeline_seed=5191):+> aug;
    source +>:LineageFrom:+> aug;
    aug +>:TrainsOn:+> model;

    root spawn LineageRunner();
}

"""RIPR P7 adoption: model producer-native staged identity, currentness filtering,
and test-harness suppression cleanup versus consumer-side workarounds."""

edge NeedsCapability { }
edge StagedAs { }
edge BridgedVia { }
edge Analyzes { }
edge LocatedIn { }
edge GuardedBy { }
edge BlockedOn { }

node Capability {
    has cap_id: str = "";
    has released: bool = False;
}

node AdoptionSlice {
    has slice_id: str = "";
    has label: str = "";
    has workaround: str = "";
    has retired: bool = False;
}

node GatePlan {
    has staged_tree_oid: str = "";
    has draft: bool = True;
}

node SubjectTree {
    has tree_oid: str = "";
}

node SandboxBridge {
    has checkout_path: str = "";
}

node HeadLineExtents {
    has filter_name: str = "HeadLineExtents";
    has active: bool = True;
}

node SourceFile {
    has path: str = "";
    has is_test_harness: bool = False;
}

node Finding {
    has disposition: str = "NOT_PROVEN";
    has line: int = 0;
    has in_deleted_base: bool = False;
    has suppressed: bool = False;
    has suppression_rationale: str = "";
}

walker RiprAdoptionAuditor {
    has seen_slices: str = "|";
    has retired_workarounds: int = 0;
    has consumer_gaps: int = 0;

    can start with Root entry {
        print("=== RIPR P7 producer-native adoption audit ===");
        visit [-->];
    }

    can enter_slice with AdoptionSlice entry {
        if f"|{here.slice_id}|" in self.seen_slices {
            print(f"[CYCLE-GUARD] refusing re-entry to slice {here.slice_id}");
            disengage;
        }
        self.seen_slices += f"{here.slice_id}|";
        print(f"\n-- Slice {here.slice_id}: {here.label}");
        print(f"   consumer workaround: {here.workaround}");
        visit [->:NeedsCapability:->];
        visit [->:GuardedBy:->];
        visit [->:BlockedOn:->];
        visit [-->] else { disengage; };
    }

    can leave_slice with AdoptionSlice exit {
        if here.retired {
            self.retired_workarounds += 1;
            print(f"   -> workaround '{here.workaround}' retired");
        } else {
            print(f"   -> workaround '{here.workaround}' still required");
            self.consumer_gaps += 1;
        }
    }

    can check_capability with Capability entry {
        status = "RELEASED" if here.released else "BLOCKED";
        print(f"   upstream capability {here.cap_id}: {status}");
        visit [-->] else { disengage; };
    }

    can audit_gate with GatePlan entry {
        mode = "draft" if here.draft else "committed";
        print(f"\n-- GatePlan staged_tree_oid={here.staged_tree_oid} ({mode})");
        visit [->:StagedAs:->];
        visit [->:BridgedVia:->] else {
            print("   no consumer sandbox bridge (producer-native only)");
        };
        visit [-->] else { disengage; };
    }

    can verify_immutable with SubjectTree entry {
        parity = "PARITY" if here.tree_oid else "MISSING";
        print(f"   immutable candidate subject [{parity}] tree_oid={here.tree_oid}");
        visit [->:Analyzes:->];
        visit [-->] else { disengage; };
    }

    can flag_bridge with SandboxBridge entry {
        print(f"   [WORKAROUND] frozen checkout bridge at {here.checkout_path}");
        self.consumer_gaps += 1;
        visit [-->] else { disengage; };
    }

    can apply_extents with HeadLineExtents entry {
        if here.active {
            print(f"   [WORKAROUND] {here.filter_name} deleted-base currentness filter active");
            self.consumer_gaps += 1;
        } else {
            print(f"   {here.filter_name} filter inactive (producer owns currentness)");
        }
        visit [-->] else { disengage; };
    }

    can inspect_finding with Finding entry {
        disp = here.disposition;
        if here.in_deleted_base and disp == "ACTIONABLE" {
            disp = "NOT_PROVEN";
            print(f"   finding line {here.line}: deleted-base ACTIONABLE downgraded -> NOT_PROVEN");
        } else if here.suppressed {
            print(f"   finding line {here.line}: suppressed ({here.suppression_rationale})");
        } else if disp == "ACTIONABLE" {
            print(f"   finding line {here.line}: ACTIONABLE production gap");
            self.consumer_gaps += 1;
        } else {
            print(f"   finding line {here.line}: {disp}");
        }
        visit [->:LocatedIn:->];
        visit [-->] else { disengage; };
    }

    can classify_source with SourceFile entry {
        role = "test-harness" if here.is_test_harness else "production";
        print(f"      located in {role} file {here.path}");
        visit [-->] else { disengage; };
    }
}

with entry {
