walker QueueAuditor {
    has pending_keys: list[str] = [];
    has resolved_keys: list[str] = [];
    has seen_seq: list[int] = [];

    can start with Root entry {
        visit [-->];
    }

    can enter with ControlTower entry {
        print(f"Scanning {here.title}");
        visit [->:Appended:->] else { disengage; };
    }

    can scan with ReviewRequest entry {
        if here.seq in self.seen_seq {
            print(f"CYCLE blocked at request seq={here.seq}");
            disengage;
        }
