"""Proto-array prune: O(N) descendant BFS vs fixed-point full-array scans on back-linked forks."""

node Block {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has idx: int = 0;
    has keep: bool = False;
}

node ProtoRegistry {
    has name: str = "";
    has finalized_idx: int = 0;
}

edge ParentOf { }
edge Member { }

walker BfsPruner {
    has kept: int = 0;
    has visits: int = 0;
    has seen: list[int] = [];

    can mark with Block entry {
        if here.idx in self.seen {
            disengage;
        }
        self.seen.append(here.idx);
        self.visits += 1;
        if not here.keep {
            here.keep = True;
            self.kept += 1;
        }
        visit [->:ParentOf:->] else { disengage; };
    }
}

walker FixedPointPruner {
    has passes: int = 0;
    has kept: int = 0;
    has changed: bool = True;
    has finalized: Block;
    has finished: bool = False;

    can pass_gate with ProtoRegistry entry {
        if self.finished {
            disengage;
        }
        if self.passes > 0 and not self.changed {
            print(
                f"FixedPointPruner: {self.passes} full-array scans, "
                f"{self.kept} blocks kept"
            );
            self.finished = True;
            disengage;
        }
        self.changed = False;
        self.passes += 1;
        visit [->:Member:->] else { disengage; };
    }

    can scan with Block entry {
        if here.idx == self.finalized.idx {
            if not here.keep {
                here.keep = True;
                self.kept += 1;
                self.changed = True;
            }
        } else {
            for p in here[<--:ParentOf:--] {
                if p.keep and not here.keep {
                    here.keep = True;
                    self.kept += 1;
                    self.changed = True;
                }
            }
        }
        visit [->:Member:->] else { disengage; };
    }
}

