    );
    hostile +>:ContainsEntry(ordinal=3):+> ArchiveEntry(
        entry_path="../etc/passwd",
        byte_size=10,
        title="Traversal",
        year=2026
    );

    zip_bomb = ArchiveBundle(
        label="zip_bomb",
        max_entries=2,
        max_entry_bytes=100,
        max_total_bytes=150,
        title="ZipBomb",
        year=2026
    );
    zip_bomb +>:ContainsEntry(ordinal=1):+> ArchiveEntry(
        entry_path="payload.bin",
        byte_size=200,
        title="Payload",
        year=2026
    );

    clean = ArchiveBundle(
        label="clean_pkg",
        max_entries=5,
        max_entry_bytes=1000,
        max_total_bytes=5000,
        title="Clean",
        year=2026
    );
    clean +>:ContainsEntry(ordinal=1):+> ArchiveEntry(
        entry_path="readme.txt",
