    );
    clean +>:ContainsEntry(ordinal=2):+> ArchiveEntry(
        entry_path="data/table.csv",
        byte_size=128,
        title="Table",
        year=2026
    );

    root ++> core ++> prov_v3 ++> hostile ++> zip_bomb ++> clean;

    print("--- dependency depth limit ---");
    core spawn DependencyAuditor(max_depth=3, max_closure=10);

    print("--- dependency cycle detection ---");
    cycle_a spawn DependencyAuditor(max_depth=10, max_closure=10);

    print("--- provenance chain (cycle-safe) ---");
    prov_v3 spawn ProvenanceAuditor(max_depth=5);

    print("--- archive path traversal ---");
    hostile spawn ArchiveVerifier();

    print("--- archive zip-bomb bounds ---");
    zip_bomb spawn ArchiveVerifier();

    print("--- archive within profile ---");
    clean spawn ArchiveVerifier();
}

