"""Calm RefNo hierarchy engine: synthesize gappy levels, reject cycles, and emit a preflight data-loss register."""

node CatalogueRecord {
    has ref_no: str = "";
    has title: str = "";
    has level: str = "";
    has available: bool = True;

    def parent_ref() -> str {
        if "/" not in self.ref_no {
            return "";
        }
        pos = self.ref_no.rfind("/");
        return self.ref_no[0:pos];
    }

    def segment_depth() -> int {
        if not self.ref_no {
            return 0;
        }
        depth = 1;
        for ch in self.ref_no {
            if ch == "/" {
                depth += 1;
            }
        }
        return depth;
    }
}

node SyntheticLevel(CatalogueRecord) {
    has available: bool = True;
}

node LossEntry {
    has field_name: str = "";
    has action: str = "";
    has source_value: str = "";
    has available: bool = True;
}

edge ChildOf { }
edge RegistersLoss { }

walker HierarchyEngine {
    has phase: int = 1;
    has index_refs: list[str] = [];
    has index_nodes: list[CatalogueRecord] = [];
    has write_order: list[str] = [];
    has synth_refs: list[str] = [];
    has cycle_error: str = "";
    has visiting: list[str] = [];

    can start with Root entry {
        self.phase = 1;
        visit [-->];
        if self.cycle_error {
            print(f"[REJECT] {self.cycle_error}");
            disengage;
        }
        self.phase = 2;
        visit [-->];
        if self.cycle_error {
            print(f"[REJECT] {self.cycle_error}");
            disengage;
        }
        n = len(self.index_refs);
        order_idx = [];
        for i in range(n) {
            order_idx.append(i);
        }
        for i in range(n) {
            for j in range(i + 1, n) {
                di = self.index_nodes[order_idx[i]].segment_depth();
                dj = self.index_nodes[order_idx[j]].segment_depth();
                if dj < di {
                    tmp = order_idx[i];
                    order_idx[i] = order_idx[j];
                    order_idx[j] = tmp;
                }
            }
        }
        for idx in order_idx {
            self.write_order.append(self.index_refs[idx]);
        }
        print("Write order (parents before children):");
        for ref in self.write_order {
            print(f"  -> {ref}");
        }
        if self.synth_refs {
            print(f"Synthesized {len(self.synth_refs)} intermediate level(s):");
            for sref in self.synth_refs {
                print(f"  + {sref}");
            }
        } else {
            print("No intermediate levels needed.");
        }
    }

    can collect with CatalogueRecord entry {
        if self.phase != 1 {
            visit [-->] else { disengage; };
        }
        if here.ref_no in self.index_refs {
            self.cycle_error = f"duplicate RefNo {here.ref_no}";
            disengage;
        }
        self.index_refs.append(here.ref_no);
        self.index_nodes.append(here);
        visit [-->] else { disengage; };
    }

    can build with CatalogueRecord entry {
        if self.phase != 2 {
            visit [-->] else { disengage; };
        }
        missing = here.parent_ref();
        while missing and missing not in self.index_refs {
            if missing in self.visiting {
                self.cycle_error = f"cycle in RefNo chain at {missing}";
                disengage;
            }
            self.visiting.append(missing);
            synth = SyntheticLevel(
                ref_no=missing,
                title=f"[SYNTH] {missing}",
                level="Subcollection"
            );
            root ++> synth;
            self.index_refs.append(missing);
            self.index_nodes.append(synth);
            self.synth_refs.append(missing);
            if "/" in missing {
                pos = missing.rfind("/");
                missing = missing[0:pos];
            } else {
                missing = "";
            }
        }
        self.visiting = [];
        pref = here.parent_ref();
        if pref {
            for (i, r) in enumerate(self.index_refs) {
                if r == pref {
                    self.index_nodes[i] +>:ChildOf:+> here;
                    break;
                }
            }
        }
        visit [-->] else { disengage; };
    }
}

walker PreflightAuditor {
    has losses: list[str] = [];
    has acknowledged: bool = False;

    can start with Root entry {
        visit [-->];
        print("Preflight data-loss register:");
        if not self.losses {
            print("  (no losses)");
        } else {
            for line in self.losses {
                print(f"  ! {line}");
            }
        }
        if self.losses and not self.acknowledged {
            print("[FAIL CLOSED] operator has not acknowledged register");
        } else {
            print("[OK] preflight complete");
        }
    }

    can audit with CatalogueRecord entry {
        if here.level == "Piece" {
            folded = "Item";
            msg = (
                f"fold level Piece -> {folded} for "
                f"{here.ref_no} ({here.title})"
            );
            self.losses.append(msg);
            entry = LossEntry(
                field_name="level",
                action="fold",
                source_value="Piece"
            );
            here +>:RegistersLoss:+> entry;
        }
        visit [-->] else { disengage; };
    }
}

