"""Infrahub MCP GCF encoding: blast-radius dependency traversal and format-aware response encoding."""

node ServerConfig {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has response_format: str = "toon";
}

node Encodable {
    has name: str = "";
    has title: str = "";
    has year: int = 0;
    has available: bool = True;

    def est_tokens_toon() -> int {
        return len(self.name);
    }

    def est_tokens_gcf() -> int {
        return len(self.name);
    }
}

node SchemaKind(Encodable) {
    has field_count: int = 0;

    override def est_tokens_toon() -> int {
        return self.field_count * 5 + len(self.name);
    }

    override def est_tokens_gcf() -> int {
        return (self.field_count * 4) + len(self.name);
    }
}

node InfraNode(Encodable) {
    has attr_count: int = 0;

    override def est_tokens_toon() -> int {
        return (self.attr_count * 4) + len(self.name);
    }

    override def est_tokens_gcf() -> int {
        return (self.attr_count * 3) + len(self.name);
    }
}

edge DependsOn { }
edge InstanceOf { }

walker ResponseEncoder {
    has active_format: str = "toon";
    has total_active: int = 0;
    has total_toon: int = 0;
    has total_gcf: int = 0;
    has encoded_count: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can load_config with ServerConfig entry {
        self.active_format = here.response_format;
        print(f"Active response format: {self.active_format}");
        visit [-->];
    }

    can encode_payload with InfraNode | SchemaKind entry {
        toon_cost = here.est_tokens_toon();
        gcf_cost = here.est_tokens_gcf();
        self.total_toon += toon_cost;
        self.total_gcf += gcf_cost;
        self.encoded_count += 1;
        if self.active_format == "gcf" {
            active_cost = gcf_cost;
            label = "GCF";
        } else {
            active_cost = toon_cost;
            label = "TOON";
        }
        self.total_active += active_cost;
        print(f"[{label}] {here.name} ~{active_cost} tokens");
        visit [-->];
    }
}

walker ReachabilityWalker {
    has visited: list[str] = [];
    has reachable: list[str] = [];
    has depth: int = 0;
    has max_depth: int = 8;

    can walk with InfraNode entry {
        if here.name in self.visited {
            print(f"[CYCLE] guard tripped at {here.name}");
            disengage;
        }
        self.visited.append(here.name);
        self.reachable.append(here.name);
        print(f"[REACH] depth={self.depth} node={here.name}");
        if self.depth >= self.max_depth {
            disengage;
        }
        self.depth += 1;
        visit [->:DependsOn:->] else { disengage; }
        self.depth -= 1;
    }
}

with entry {
    config = ServerConfig(response_format="gcf");
    device = SchemaKind(name="Device", field_count=15);
    rack = SchemaKind(name="Rack", field_count=8);

    router = InfraNode(name="core-router", attr_count=22);
    switch = InfraNode(name="edge-switch", attr_count=18);
    server = InfraNode(name="app-server", attr_count=30);
    db = InfraNode(name="postgres-db", attr_count=25, available=False);

    root ++> config;
    root ++> device ++> rack;
    root ++> router;
    root ++> switch;
    root ++> server;
    root ++> db;

    router +>:DependsOn:+> switch;
    switch +>:DependsOn:+> server;
    server +>:DependsOn:+> db;

    router +>:InstanceOf:+> device;
    switch +>:InstanceOf:+> device;
    server +>:InstanceOf:+> device;
    db +>:InstanceOf:+> device;

    encoder = ResponseEncoder();
    root spawn encoder;

    radius = ReachabilityWalker();
    radius spawn router;

    savings_pct = 0;
    if encoder.total_toon > 0 {
        savings_pct = (encoder.total_toon - encoder.total_gcf) * 100 / encoder.total_toon;
    }
    print(f"Encoded {encoder.encoded_count} payloads: "
          f"active={encoder.total_active}, toon={encoder.total_toon}, "
          f"gcf={encoder.total_gcf}, savings={savings_pct}%");
    print(f"Blast radius from core-router: {radius.reachable}");
}

"""Resource limits: reject pathological dependency closure, provenance cycles, and archive abuse before execution."""

node SemanticModel {
    has name: str = "";
    has assertion_count: int = 0;
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

node ArchiveBundle {
    has label: str = "";
    has max_entries: int = 100;
    has max_entry_bytes: int = 1048576;
    has max_total_bytes: int = 10485760;
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

node ArchiveEntry {
    has entry_path: str = "";
    has byte_size: int = 0;
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

edge DependsOn { }
edge ContainsEntry { has ordinal: int = 0; }
edge ProvenanceLink { has step: int = 0; }

walker DependencyAuditor {
    has max_depth: int = 4;
    has max_closure: int = 8;
    has depth: int = 0;
    has seen: list[str] = [];
    has count: int = 0;
    has rejected: bool = False;
    has reason: str = "";

    can audit with SemanticModel entry {
        if self.rejected {
            disengage;
        }
        if here.name in self.seen {
            self.rejected = True;
            self.reason = f"dependency cycle at {here.name}";
            print(f"REJECT: {self.reason}");
            disengage;
        }
        self.seen.append(here.name);
        self.count += 1;
        if self.count > self.max_closure {
            self.rejected = True;
            self.reason = f"closure exceeds {self.max_closure} models";
            print(f"REJECT: {self.reason}");
            disengage;
        }
        if self.depth > self.max_depth {
            self.rejected = True;
            self.reason = f"dependency depth exceeds {self.max_depth}";
            print(f"REJECT: {self.reason}");
            disengage;
        }
        print(f"  ok model {here.name} depth={self.depth} assertions={here.assertion_count}");
        self.depth += 1;
        visit [->:DependsOn:->] else {
            if not self.rejected and self.count > 0 {
                print(f"ACCEPT: dependency closure {self.count} models within depth {self.max_depth}");
            }
            disengage;
        };
    }

    can retreat with SemanticModel exit {
        self.depth -= 1;
    }
}

walker ProvenanceAuditor {
    has max_depth: int = 5;
    has depth: int = 0;
    has seen: list[str] = [];
    has rejected: bool = False;
    has reason: str = "";

    can trace with SemanticModel entry {
        if self.rejected {
            disengage;
        }
        if here.name in self.seen {
            self.rejected = True;
            self.reason = f"provenance cycle at {here.name}";
            print(f"REJECT: {self.reason}");
            disengage;
        }
        self.seen.append(here.name);
        if self.depth > self.max_depth {
            self.rejected = True;
            self.reason = f"provenance depth exceeds {self.max_depth}";
            print(f"REJECT: {self.reason}");
            disengage;
        }
        print(f"  ok provenance step={self.depth} artifact={here.name}");
        self.depth += 1;
        visit [->:ProvenanceLink:->] else {
            if not self.rejected {
                print(f"ACCEPT: provenance chain depth {self.depth} within limit {self.max_depth}");
            }
            disengage;
        };
    }

    can unwind with SemanticModel exit {
        self.depth -= 1;
    }
}

walker ArchiveVerifier {
    has max_entries: int = 5;
    has max_entry_bytes: int = 1000;
    has max_total_bytes: int = 5000;
    has entries_seen: int = 0;
    has bytes_total: int = 0;
    has normalized_paths: list[str] = [];
    has rejected: bool = False;
    has reason: str = "";
    has bundle_label: str = "";

    can inspect with ArchiveBundle entry {
        self.bundle_label = here.label;
        self.max_entries = here.max_entries;
        self.max_entry_bytes = here.max_entry_bytes;
        self.max_total_bytes = here.max_total_bytes;
        print(f"=== archive audit: {self.bundle_label} ===");
        visit [->:ContainsEntry:->] else {
            if not self.rejected {
                print(f"ACCEPT: archive {self.bundle_label} ({self.entries_seen} entries, {self.bytes_total} bytes)");
            }
            disengage;
        };
    }

    can scan with ArchiveEntry entry {
        if self.rejected {
            disengage;
        }
        path = here.entry_path;
        if path.startswith("/") {
            self.rejected = True;
            self.reason = "absolute archive path rejected";
            print(f"REJECT: {self.reason} ({path})");
            disengage;
        }
        if "../" in path or path == ".." {
            self.rejected = True;
            self.reason = "path traversal rejected";
            print(f"REJECT: {self.reason} ({path})");
            disengage;
        }
        norm = path.lower();
        if norm in self.normalized_paths {
            self.rejected = True;
            self.reason = f"duplicate normalized path ({norm})";
            print(f"REJECT: {self.reason}");
            disengage;
        }
        if here.byte_size > self.max_entry_bytes {
            self.rejected = True;
            self.reason = f"entry exceeds {self.max_entry_bytes} bytes";
            print(f"REJECT: {self.reason} ({here.byte_size})");
            disengage;
        }
        next_count = self.entries_seen + 1;
        if next_count > self.max_entries {
            self.rejected = True;
            self.reason = f"entry count exceeds {self.max_entries}";
            print(f"REJECT: {self.reason}");
            disengage;
        }
        next_total = self.bytes_total + here.byte_size;
        if next_total > self.max_total_bytes {
            self.rejected = True;
            self.reason = f"total uncompressed exceeds {self.max_total_bytes}";
            print(f"REJECT: {self.reason}");
            disengage;
        }
        self.normalized_paths.append(norm);
        self.entries_seen = next_count;
        self.bytes_total = next_total;
        print(f"  ok entry {path} ({here.byte_size} bytes)");
        visit [-->] else { disengage; };
    }
}

