"""Resource limits: reject pathological dependency closure, provenance cycles, and archive abuse before execution."""

node SemanticModel {
    has name: str = "";
    has assertion_count: int = 0;
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

node ArchiveBundle {
    has label: str = "";
    has max_entries: int = 100;
    has max_entry_bytes: int = 1048576;
    has max_total_bytes: int = 10485760;
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

node ArchiveEntry {
    has entry_path: str = "";
    has byte_size: int = 0;
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

edge DependsOn { }
edge ContainsEntry { has ordinal: int = 0; }
edge ProvenanceLink { has step: int = 0; }

walker DependencyAuditor {
    has max_depth: int = 4;
    has max_closure: int = 8;
    has depth: int = 0;
    has seen: list[str] = [];
    has count: int = 0;
    has rejected: bool = False;
    has reason: str = "";

    can audit with SemanticModel entry {
        if not self.rejected {
            if here.name in self.seen {
                self.rejected = True;
                self.reason = f"dependency cycle at {here.name}";
                print(f"REJECT: {self.reason}");
            } else {
                self.seen.append(here.name);
                self.count += 1;
                if self.count > self.max_closure {
                    self.rejected = True;
                    self.reason = f"closure exceeds {self.max_closure} models";
                    print(f"REJECT: {self.reason}");
                } elif self.depth > self.max_depth {
                    self.rejected = True;
                    self.reason = f"dependency depth exceeds {self.max_depth}";
                    print(f"REJECT: {self.reason}");
                } else {
                    print(f"  ok model {here.name} depth={self.depth} assertions={here.assertion_count}");
                }
            }
        }
        if not self.rejected {
            self.depth += 1;
            visit [->:DependsOn:->] else {
                if self.count > 0 {
                    print(f"ACCEPT: dependency closure {self.count} models within depth {self.max_depth}");
                }
                disengage;
            };
        } else {
            visit [-->] else { disengage; };
        }
    }

    can retreat with SemanticModel exit {
        if not self.rejected {
            self.depth -= 1;
        }
        visit [<--];
    }
}

walker ProvenanceAuditor {
    has max_depth: int = 5;
    has depth: int = 0;
    has seen: list[str] = [];
    has rejected: bool = False;
    has reason: str = "";

    can trace with SemanticModel entry {
        if not self.rejected {
            if here.name in self.seen {
                self.rejected = True;
                self.reason = f"provenance cycle at {here.name}";
                print(f"REJECT: {self.reason}");
            } elif self.depth > self.max_depth {
                self.rejected = True;
                self.reason = f"provenance depth exceeds {self.max_depth}";
                print(f"REJECT: {self.reason}");
            } else {
                print(f"  ok provenance step={self.depth} artifact={here.name}");
            }
        }
        if not self.rejected {
            self.depth += 1;
            visit [->:ProvenanceLink:->] else {
                print(f"ACCEPT: provenance chain depth {self.depth} within limit {self.max_depth}");
                disengage;
            };
        } else {
            visit [-->] else { disengage; };
        }
    }

    can unwind with SemanticModel exit {
        if not self.rejected {
            self.depth -= 1;
        }
        visit [<--];
    }
}

walker ArchiveVerifier {
    has max_entries: int = 5;
    has max_entry_bytes: int = 1000;
    has max_total_bytes: int = 5000;
    has entries_seen: int = 0;
    has bytes_total: int = 0;
    has normalized_paths: list[str] = [];
    has rejected: bool = False;
    has reason: str = "";
    has bundle_label: str = "";

    can inspect with ArchiveBundle entry {
        self.bundle_label = here.label;
        self.max_entries = here.max_entries;
        self.max_entry_bytes = here.max_entry_bytes;
        self.max_total_bytes = here.max_total_bytes;
        print(f"=== archive audit: {self.bundle_label} ===");
        visit [->:ContainsEntry:->] else {
            if not self.rejected {
                print(f"ACCEPT: archive {self.bundle_label} ({self.entries_seen} entries, {self.bytes_total} bytes)");
            }
            disengage;
        };
    }

    can scan with ArchiveEntry entry {
        if not self.rejected {
            path = here.entry_path;
            if path.startswith("/") {
                self.rejected = True;
                self.reason = "absolute archive path rejected";
                print(f"REJECT: {self.reason} ({path})");
            } elif "../" in path or path == ".." {
                self.rejected = True;
                self.reason = "path traversal rejected";
                print(f"REJECT: {self.reason} ({path})");
            } else {
                norm = path.lower();
                if norm in self.normalized_paths {
                    self.rejected = True;
                    self.reason = f"duplicate normalized path ({norm})";
                    print(f"REJECT: {self.reason}");
                } elif here.byte_size > self.max_entry_bytes {
                    self.rejected = True;
                    self.reason = f"entry exceeds {self.max_entry_bytes} bytes";
                    print(f"REJECT: {self.reason} ({here.byte_size})");
                } else {
                    next_count = self.entries_seen + 1;
                    if next_count > self.max_entries {
                        self.rejected = True;
                        self.reason = f"entry count exceeds {self.max_entries}";
                        print(f"REJECT: {self.reason}");
                    } else {
                        next_total = self.bytes_total + here.byte_size;
                        if next_total > self.max_total_bytes {
                            self.rejected = True;
                            self.reason = f"total uncompressed exceeds {self.max_total_bytes}";
                            print(f"REJECT: {self.reason}");
                        } else {
                            self.normalized_paths.append(norm);
                            self.entries_seen = next_count;
                            self.bytes_total = next_total;
                            print(f"  ok entry {path} ({here.byte_size} bytes)");
                        }
                    }
                }
            }
        }
        visit [-->] else { disengage; };
    }
}

