"""cxpak blast_radius: distinguish index misses from honest zero dependents."""

node IndexedFile {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

edge Import { }

walker BlastRadius {
    has seed: str = "";
    has mode: str = "scan";
    has not_found: list[str] = [];
    has affected: list[str] = [];
    has visited: list[str] = [];

    def emit_ok() {
        count = len(self.affected);
        print(
            f"blast_radius files=[{self.seed}] not_found=[] "
            f"total_affected={count} affected={self.affected}"
        );
    }

    def emit_missing() {
        print(
            f"blast_radius files=[{self.seed}] not_found=[{self.seed}] "
            f"(≠ in-index empty blast)"
        );
    }

    can start with Root entry {
        visit [-->[?:IndexedFile]] else { disengage; }
    }

    can scan with IndexedFile entry {
        if self.mode != "scan" {
            disengage;
        }
        if here.title == self.seed {
            self.mode = "blast";
            visit [<--:Import:--] else {
                self.emit_ok();
                disengage;
            }
            disengage;
        }
        visit [-->[?:IndexedFile]] else {
            self.not_found.append(self.seed);
            self.emit_missing();
            disengage;
        }
    }

    can blast with IndexedFile entry {
        if self.mode != "blast" {
            disengage;
        }
        if here.title in self.visited {
            visit [<--:Import:--] else {
                self.emit_ok();
                disengage;
            }
        }
        self.visited.append(here.title);
        self.affected.append(here.title);
        visit [<--:Import:--] else {
            self.emit_ok();
            disengage;
        }
    }
}

