}

"""Infrahub MCP GCF encoding: blast-radius dependency traversal and format-aware response encoding."""

node ServerConfig {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has response_format: str = "toon";
}

node Encodable {
    has name: str = "";
    has title: str = "";
    has year: int = 0;
    has available: bool = True;

    def est_tokens_toon() -> int {
        return len(self.name);
    }

    def est_tokens_gcf() -> int {
        return len(self.name);
    }
}

node SchemaKind(Encodable) {
    has field_count: int = 0;

    override def est_tokens_toon() -> int {
        return self.field_count * 5 + len(self.name);
    }

    override def est_tokens_gcf() -> int {
        return (self.field_count * 4) + len(self.name);
    }
}

node InfraNode(Encodable) {
    has attr_count: int = 0;

    override def est_tokens_toon() -> int {
        return (self.attr_count * 4) + len(self.name);
    }

    override def est_tokens_gcf() -> int {
        return (self.attr_count * 3) + len(self.name);
    }
}

edge DependsOn { }
edge InstanceOf { }

walker ResponseEncoder {
    has active_format: str = "toon";
    has total_active: int = 0;
    has total_toon: int = 0;
    has total_gcf: int = 0;
    has encoded_count: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can load_config with ServerConfig entry {
        self.active_format = here.response_format;
        print(f"Active response format: {self.active_format}");
        visit [-->];
    }

    can encode_payload with InfraNode | SchemaKind entry {
        toon_cost = here.est_tokens_toon();
        gcf_cost = here.est_tokens_gcf();
        self.total_toon += toon_cost;
        self.total_gcf += gcf_cost;
        self.encoded_count += 1;
        if self.active_format == "gcf" {
            active_cost = gcf_cost;
            label = "GCF";
        } else {
            active_cost = toon_cost;
            label = "TOON";
        }
        self.total_active += active_cost;
        print(f"[{label}] {here.name} ~{active_cost} tokens");
        visit [-->];
    }
}

walker ReachabilityWalker {
    has visited: list[str] = [];
    has reachable: list[str] = [];
    has depth: int = 0;
    has max_depth: int = 8;

    can trace with InfraNode entry {
        if here.name in self.visited {
            print(f"[CYCLE] guard tripped at {here.name}");
            disengage;
        }
        self.visited.append(here.name);
        self.reachable.append(here.name);
        print(f"[REACH] depth={self.depth} node={here.name}");
        if self.depth >= self.max_depth {
            disengage;
        }
        self.depth += 1;
        visit [->:DependsOn:->] else { disengage; };
    }

    can retreat with InfraNode exit {
        self.depth -= 1;
    }
}

with entry {
    config = ServerConfig(response_format="gcf");
    device = SchemaKind(name="Device", field_count=15);
    rack = SchemaKind(name="Rack", field_count=8);

    router = InfraNode(name="core-router", attr_count=22);
    switch = InfraNode(name="edge-switch", attr_count=18);
    server = InfraNode(name="app-server", attr_count=30);
    db = InfraNode(name="postgres-db", attr_count=25, available=False);

    root ++> config;
    root ++> device ++> rack;
    root ++> router;
    root ++> switch;
    root ++> server;
    root ++> db;

    router +>:DependsOn:+> switch;
    switch +>:DependsOn:+> server;
    server +>:DependsOn:+> db;

    router +>:InstanceOf:+> device;
    switch +>:InstanceOf:+> device;
    server +>:InstanceOf:+> device;
    db +>:InstanceOf:+> device;

    encoder = ResponseEncoder();
    root spawn encoder;

    radius = ReachabilityWalker();
    router spawn radius;

    savings_pct = 0;
    if encoder.total_toon > 0 {
        savings_pct = (encoder.total_toon - encoder.total_gcf) * 100 / encoder.total_toon;
    }
    print(f"Encoded {encoder.encoded_count} payloads: "
          f"active={encoder.total_active}, toon={encoder.total_toon}, "
          f"gcf={encoder.total_gcf}, savings={savings_pct}%");
    print(f"Blast radius from core-router: {radius.reachable}");
}

