"""cxpak blast_radius: distinguish index misses from honest zero dependents."""

node IndexedFile {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

node FileIndex {
    has title: str = "index";
    has year: int = 0;
    has available: bool = True;
}

edge InIndex { }
edge Import { }

walker BlastRadius {
    has seed: str = "";
    has phase: str = "lookup";
    has resolved: bool = False;
    has not_found: list[str] = [];
    has affected: list[str] = [];
    has seen: list[str] = [];

    def emit_ok() {
        count = len(self.affected);
        print(
            f"blast_radius files=[{self.seed}] not_found=[] "
            f"total_affected={count} affected={self.affected}"
        );
    }

    def emit_missing() {
        print(
            f"blast_radius files=[{self.seed}] not_found=[{self.seed}] "
            f"(distinct from in-index empty blast)"
        );
    }

    can start with Root entry {
        visit [-->];
    }

    can lookup_index with FileIndex entry {
        visit [->:InIndex:->] else {
            if not self.resolved {
                self.not_found.append(self.seed);
                self.emit_missing();
            }
            disengage;
        }
    }

    can on_file with IndexedFile entry {
        if self.phase == "lookup" {
            if here.title == self.seed {
                self.resolved = True;
                self.phase = "blast";
                visit [<-:Import:<-] else {
                    self.emit_ok();
                    disengage;
                }
                disengage;
            }
        } else {
            if self.phase == "blast" {
                path = here.title;
                if path in self.seen {
                    visit [<-:Import:<-] else {
                        self.emit_ok();
                        disengage;
                    }
                    disengage;
                }
                self.seen.append(path);
                self.affected.append(path);
                visit [<-:Import:<-] else {
                    self.emit_ok();
                    disengage;
                }
            }
        }
    }
}

