"""RI3.7 relationship authority: impact traversal expands only on authoritative proof paths."""

node CodeUnit {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has kind: str = "";
}

node TestCase {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has required: bool = False;
}

edge AuthCalls { has proof_kind: str = ""; }
edge AuthReferences { has proof_kind: str = ""; }
edge CorrCalls { has proof_kind: str = ""; }
edge HeurCalls { }
edge Covers { has proof_kind: str = ""; }

walker ImpactAnalyzer {
    has policy_minimum: str = "authoritative";
    has seed_title: str = "";
    has mode: str = "";
    has proven_impact: list[str] = [];
    has possible_impact: list[str] = [];
    has heuristic_hints: list[str] = [];
    has visited_proven: list[str] = [];
    has proof_paths: list[str] = [];

    def note_proven(target: str, edge_label: str, proof: str) {
        if target not in self.proven_impact {
            self.proven_impact.append(target);
            path = f"{self.seed_title} --{edge_label} [{proof}]--> {target}";
            self.proof_paths.append(path);
            print(f"[PROVEN] {path}");
        }
    }

    def note_possible(target: str, edge_label: str, proof: str) {
        if target not in self.possible_impact {
            self.possible_impact.append(target);
            print(f"[POSSIBLE] {self.seed_title} --{edge_label} [{proof}]--> {target}");
        }
    }

    def note_heuristic(target: str) {
        if target not in self.heuristic_hints {
            self.heuristic_hints.append(target);
            print(
                f"[HINT] {self.seed_title} --HeurCalls--> {target} "
                f"(context only, no hard blast radius)"
            );
        }
    }

    can start with Root entry {
        visit [-->];
    }

    can analyze with CodeUnit entry {
        if self.seed_title == "" {
            self.seed_title = here.title;
            print(f"Impact seed: {here.title} (minimum authority: {self.policy_minimum})");
            self.visited_proven.append(here.title);
            self.mode = "proven";
            visit [->:AuthCalls:->] else { disengage; };
            self.mode = "corr";
            visit [->:CorrCalls:->] else { disengage; };
            self.mode = "heur";
            visit [->:HeurCalls:->] else { disengage; };
            self.mode = "";
            disengage;
        }
        if self.mode == "proven" {
            if here.title in self.visited_proven {
                disengage;
            }
            self.visited_proven.append(here.title);
            edge_label = "REFERENCES" if here.kind == "record" else "CALLS";
            edge_proof = "ExactReference" if here.kind == "record" else "ExactCallSite";
            self.note_proven(here.title, edge_label, edge_proof);
            visit [->:AuthCalls:->] else { disengage; };
            visit [->:AuthReferences:->] else { disengage; };
            disengage;
        }
        if self.mode == "corr" {
            self.note_possible(here.title, "CALLS", "RuntimeTrace");
            disengage;
        }
        if self.mode == "heur" {
            self.note_heuristic(here.title);
            disengage;
        }
        disengage;
    }
}

walker TestSelector {
    has required_tests: list[str] = [];
    has optional_tests: list[str] = [];
    has covers_via: str = "";

    can start with Root entry {
        visit [-->];
    }

    can select with CodeUnit entry {
        self.covers_via = "auth";
        visit [->:Covers:->] else { disengage; };
        self.covers_via = "corr";
        visit [->:CorrCalls:->] else { disengage; };
        visit [->:HeurCalls:->] else { disengage; };
        visit [->:AuthCalls:->] else { disengage; };
    }

    can require_test with TestCase entry {
        if self.covers_via == "auth" {
            if here.title not in self.required_tests {
                self.required_tests.append(here.title);
                here.required = True;
                print(f"[REQUIRED] {here.title} (authoritative Covers proof)");
            }
        } else {
            if here.title not in self.optional_tests {
                self.optional_tests.append(here.title);
                print(f"[OPTIONAL] {here.title} (corroborating/heuristic only)");
            }
        }
        disengage;
    }
}

