}

node GDNLayer(ComputeStage) {
    has cost_ms: float = 155.0;
}

node Expert {
    has expert_id: int = 0;
    has resident: bool = False;
    has footprint_bytes: int = 1671168;
}

node ResidentPool {
    has cap_slots: int = 4;
    has top_k: int = 8;
    has assumed_slot_bytes: int = 2147483648;
    has actual_slot_bytes: int = 1671168;
}

edge Routes {
