"""Semantic symbol dependency graph: modules, operations, scenarios, and policies linked by typed relation edges with provenance; walkers demonstrate forward dependencies, reverse callers, Requires-cycle diagnosis, and bounded path reachability."""

node SemanticSymbol {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has symbol_id: str = "";
    has kind: str = "";
    has module_name: str = "";
}

node Module(SemanticSymbol) {
}

node Operation(SemanticSymbol) {
    has signature: str = "";
}

node Scenario(SemanticSymbol) {
    has step: str = "";
}

node Policy(SemanticSymbol) {
    has requirement_code: str = "";
}

edge Requires {
    has confidence: float = 1.0;
    has provenance: str = "";
}

edge References {
    has confidence: float = 1.0;
    has provenance: str = "";
}

edge Authorizes {
    has confidence: float = 1.0;
    has provenance: str = "";
}

edge Implements {
    has confidence: float = 1.0;
    has provenance: str = "";
}

walker ForwardDeps {
    has report_lines: list[str] = [];
    has visited: list[str] = [];

    can show with Operation entry {
        line = f"show {here.symbol_id}";
        self.report_lines.append(line);
        self.visited.append(here.symbol_id);
        visit [->:Requires:->];
        visit [->:References:->];
    }

    can step with Operation | Scenario | Policy entry {
        if here.symbol_id in self.visited {
            disengage;
        }
        self.visited.append(here.symbol_id);
        label = f"  -> {here.symbol_id} [{here.kind}]";
        self.report_lines.append(label);
        visit [->:Requires:->];
        visit [->:References:->];
    }
}

walker CallersAudit {
    has callers: list[str] = [];

    can audit with Operation entry {
        visit [<--:Requires:<-] else { disengage; };
    }

    can register with Scenario | Operation entry {
        caller_line = f"{here.symbol_id} (provenance edge)";
        self.callers.append(caller_line);
        visit [<--:Requires:<-] else { disengage; };
    }
}

walker CycleDiagnostician {
    has visited: list[str] = [];
    has diagnosis: str = "ok";

    can diagnose with Scenario entry {
        self.visited.append(here.symbol_id);
        visit [->:Requires:->] else { disengage; };
    }

    can follow with Operation | Scenario entry {
        if here.symbol_id in self.visited {
            self.diagnosis = f"invalid Requires cycle involving {here.symbol_id}";
            disengage;
        }
        self.visited.append(here.symbol_id);
        visit [->:Requires:->] else { disengage; };
    }
}

walker PathFinder {
    has goal_id: str = "";
    has route: list[str] = [];
    has result: str = "";

    can seek with Policy entry {
        self.route.append(here.symbol_id);
        if here.symbol_id == self.goal_id {
            self.result = " -> ".join(self.route);
            disengage;
        }
        visit [->:References:->] else { disengage; };
    }

    can advance with Operation | Scenario | Policy entry {
        self.route.append(here.symbol_id);
        if here.symbol_id == self.goal_id {
            self.result = " -> ".join(self.route);
            disengage;
        }
        visit [->:References:->] else { disengage; };
    }
}

with entry {
    planner = Module(
        title="Planner",
        symbol_id="planner",
        kind="module",
        module_name="planner"
    );
    focus = Operation(
        title="focus_task",
        symbol_id="planner.focus_task",
        kind="operation",
        module_name="planner",
        signature="focus_task()"
    );
    switch_focus = Scenario(
        title="switch_focus",
        symbol_id="planner.scenario.switch_focus",
        kind="scenario",
        module_name="planner",
        step="switch"
    );
    policy = Policy(
        title="PLANNER-001",
        symbol_id="req:PLANNER-001",
        kind="policy",
        module_name="planner",
        requirement_code="PLANNER-001"
    );

    root ++> planner ++> focus;
    planner +>:Implements(
        confidence=1.0,
        provenance="module:planner"
    ):+> switch_focus;
    switch_focus +>:Requires(
        confidence=1.0,
        provenance="ir:planner/scenarios.jac"
    ):+> focus;
    focus +>:Requires(
        confidence=0.8,
        provenance="ir:planner/ops.jac"
    ):+> switch_focus;
    focus +>:References(
        confidence=0.95,
        provenance="decl:planner/ops.jac"
    ):+> policy;
    policy +>:Authorizes(
        confidence=1.0,
        provenance="policy:PLANNER-001"
    ):+> focus;
    policy +>:References(
        confidence=1.0,
        provenance="policy:PLANNER-001"
    ):+> switch_focus;

    fwd = ForwardDeps();
    focus spawn fwd;
    callers = CallersAudit();
    focus spawn callers;
    cycle = CycleDiagnostician();
    switch_focus spawn cycle;
    path = PathFinder(goal_id="planner.scenario.switch_focus");
    policy spawn path;

    print("=== lekalo graph show planner.focus_task ===");
    for line in fwd.report_lines {
        print(line);
    }
    print("=== lekalo graph callers planner.focus_task ===");
    for caller in callers.callers {
        print(f"  caller {caller}");
    }
    print("=== lekalo graph cycle check (Requires) ===");
    print(cycle.diagnosis);
    print("=== lekalo graph path req:PLANNER-001 planner.scenario.switch_focus ===");
    path_label = path.result if path.result else "unreachable";
    print(path_label);
}

"""Fledge #508: diamond task deps falsely rejected when cycle check conflates on-stack with completed."""

node Task {
    has name: str = "";
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

edge DependsOn { }

walker BuggyCycleCheck {
    has visited: list[str] = [];
    has ok: bool = True;
    has message: str = "";

    can start with Root entry {
        visit [-->];
    }

    can validate with Task entry {
        if here.name in self.visited {
            self.ok = False;
            self.message = f"Circular dependency detected: task '{here.name}' depends on itself";
            disengage;
        }
        self.visited.append(here.name);
        visit [->:DependsOn:->] else { disengage; };
    }
}

walker CorrectCycleCheck {
    has on_stack: list[str] = [];
    has completed: list[str] = [];
    has ok: bool = True;
    has message: str = "";

    can start with Root entry {
        visit [-->];
    }

    can validate with Task entry {
        if here.name in self.completed {
            disengage;
        }
        if here.name in self.on_stack {
            self.ok = False;
            self.message = f"Circular dependency detected involving task '{here.name}'";
            disengage;
        }
        self.on_stack.append(here.name);
        visit [->:DependsOn:->] else { disengage; };
    }

    can unwind with Task exit {
        trimmed: list[str] = [];
        for n in self.on_stack {
            if n != here.name {
                trimmed.append(n);
            }
        }
        self.on_stack = trimmed;
        if here.name not in self.completed {
            self.completed.append(here.name);
        }
    }
}

with entry {
    d = Task(name="d", title="echo d");
    b = Task(name="b", title="echo b");
    c = Task(name="c", title="echo c");
    a = Task(name="a", title="echo a");
    a +>:DependsOn:+> b;
    a +>:DependsOn:+> c;
    b +>:DependsOn:+> d;
    c +>:DependsOn:+> d;
    root ++> a;

    print("=== Diamond DAG: a -> [b, c] -> d (no cycle) ===");

    buggy = BuggyCycleCheck();
    root spawn buggy;
    buggy_label = "PASS" if buggy.ok else "FAIL";
    print(f"Buggy single visited set: {buggy_label} — {buggy.message}");

    fixed = CorrectCycleCheck();
    root spawn fixed;
    fixed_label = "PASS" if fixed.ok else "FAIL";
    print(f"Correct on-stack + completed: {fixed_label}");

    print("=== True cycle: xa -> xb -> xa ===");

    xb = Task(name="xb", title="cycle b");
    xa = Task(name="xa", title="cycle a");
    xa +>:DependsOn:+> xb;
    xb +>:DependsOn:+> xa;

    guard = CorrectCycleCheck();
    guard spawn xa;
    guard_label = "FAIL (expected)" if not guard.ok else "PASS (unexpected)";
    print(f"Correct on-stack + completed: {guard_label} — {guard.message}");
}

