"""Recursive runtime.Caller reachability: order-dependent DFS memo vs fixed point."""

node Function {
    has name: str = "";
    has uses_caller: bool = False;
    has may_reach: bool = False;
    has memo_done: bool = False;

    def reset_analysis() -> None {
        self.may_reach = False;
        self.memo_done = False;
    }

    def callees() -> list[Function] {
        out: list[Function] = [];
        for callee in self-->:Calls:--> {
            out.append(callee);
        }
        return out;
    }
}

edge Calls { }

walker BuggyOrderedBatch {
    has targets: list[Function] = [];
    has visiting: list[str] = [];

    can start with Root entry {
        for fn in self.targets {
            self.visiting = [];
            fn.may_reach = self.probe(fn);
        }
        visit [-->] else { disengage; };
    }

    def probe(fn: Function) -> bool {
        if fn.uses_caller {
            return True;
        }
        if fn.name in self.visiting {
            return False;
        }
        if fn.memo_done {
            return fn.may_reach;
        }
        self.visiting.append(fn.name);
        hit = False;
        for callee in fn.callees() {
            if self.probe(callee) {
                hit = True;
            }
        }
        if len(self.visiting) > 0 {
            self.visiting.pop();
        }
        fn.may_reach = hit;
        fn.memo_done = True;
        return hit;
    }
}

walker FixedPointReach {
    has changed: bool = False;

    can start with Root entry {
        self.changed = True;
        while self.changed {
            self.changed = False;
            visit [-->[?:Function]] else { disengage; };
        }
        visit [-->] else { disengage; };
    }

    can propagate with Function entry {
        if here.uses_caller {
            if not here.may_reach {
                here.may_reach = True;
                self.changed = True;
            }
        } else {
            for callee in here.callees() {
                if callee.may_reach and not here.may_reach {
                    here.may_reach = True;
                    self.changed = True;
                }
            }
        }
        visit [-->[?:Function]] else { disengage; };
    }
}

with entry {
    a = Function(name="a", uses_caller=True);
    b = Function(name="b");
    a +>:Calls:+> b;
    b +>:Calls:+> a;

    a.reset_analysis();
    b.reset_analysis();
    root spawn BuggyOrderedBatch(targets=[a, b]);
    verdict_a_first = f"a={a.may_reach} b={b.may_reach}";

    a.reset_analysis();
    b.reset_analysis();
    root spawn BuggyOrderedBatch(targets=[b, a]);
    verdict_b_first = f"a={a.may_reach} b={b.may_reach}";

    a.reset_analysis();
    b.reset_analysis();
    root spawn FixedPointReach();
    verdict_fixed = f"a={a.may_reach} b={b.may_reach}";

    print(f"buggy analyze a then b: {verdict_a_first}");
    print(f"buggy analyze b then a: {verdict_b_first}");
    print(f"fixed-point SCC lift:   {verdict_fixed}");
}

"""OberWatch test discovery: recursive yaml find, run scenarios, and CLI exit semantics."""

node SuiteDir {
    has name: str = "";
    has path: str = "";
}

node TestFile {
    has filename: str = "";
    has year: int = 0;
    has available: bool = True;
}

node Scenario {
    has name: str = "";
    has passed: bool = True;
    has attempt: int = 0;
}

node MockUpstream {
    has host: str = "127.0.0.1";
    has port: int = 8080;
    has available: bool = True;
}

edge Contains { }
edge Declares { has order: int = 0; }
edge Serves { }

walker Discoverer {
    has found: int = 0;
    has depth: int = 0;
    has max_depth: int = 8;
    has exit_code: int = 0;
    has seen: list[str] = [];

    can start with Root entry {
        print("=== DISCOVERY ===");
        visit [->:Contains:->] else { disengage; };
    }

    can descend with SuiteDir entry {
        key = here.path;
        if key in self.seen {
            print(f"[EXIT 2] cycle detected at {here.path}");
            self.exit_code = 2;
            disengage;
        }
        self.seen.append(key);
        if self.depth >= self.max_depth {
            print(f"[EXIT 2] depth limit at {here.path}");
            self.exit_code = 2;
            disengage;
        }
        self.depth += 1;
        print(f"[DIR] {here.path}");
        visit [->:Contains:->] else { disengage; };
        self.depth -= 1;
    }

    can pickup with TestFile entry {
        is_yaml = here.filename.endswith(".yaml") or here.filename.endswith(".yml");
        if is_yaml {
            self.found += 1;
            print(f"[FOUND] {here.filename}");
            visit [->:Declares:->] else { disengage; };
        }
    }

    can preview with Scenario entry {
        label = "PASS" if here.passed else "FAIL";
        print(f"  preview {here.name} [{label}]");
    }
}

walker Runner {
    has retries: int = 0;
    has fail_fast: bool = False;
    has dry_run: bool = False;
    has fail_under_pct: int = 100;
    has passed: int = 0;
    has failed: int = 0;
    has exit_code: int = 0;
    has halted: bool = False;

    can start with Root entry {
        print("=== RUN ===");
        visit [->:Contains:->] else { disengage; };
    }

    can enter with SuiteDir entry {
        if self.halted {
            disengage;
        }
        visit [->:Contains:->] else { disengage; };
    }

    can run_file with TestFile entry {
        if self.halted {
            disengage;
        }
        is_yaml = here.filename.endswith(".yaml") or here.filename.endswith(".yml");
        if not is_yaml {
            disengage;
        }
        if self.dry_run {
            print(f"[DRY-RUN] {here.filename}");
            disengage;
        }
        print(f"[RUN] {here.filename}");
        visit [->:Serves:->];
        visit [->:Declares:->] else { disengage; };
    }

    can check_upstream with MockUpstream entry {
        if not here.available {
            print(f"[EXIT 2] mock upstream down {here.host}:{here.port}");
            self.exit_code = 2;
            self.halted = True;
            disengage;
        }
        print(f"  mock upstream {here.host}:{here.port} ok");
    }

    can execute with Scenario entry {
        if self.halted {
            disengage;
        }
        ok = here.passed;
        attempts = 1;
        if not ok and self.retries > 0 {
            here.attempt = 1;
            ok = here.passed;
            attempts = 2;
        }
        status = "PASS" if ok else "FAIL";
        print(f"  {here.name}: {status} (attempts={attempts})");
        if ok {
            self.passed += 1;
        } else {
            self.failed += 1;
            if self.fail_fast {
                print("  fail-fast: halting");
                self.halted = True;
                disengage;
            }
        }
    }
}

with entry {
    tests = SuiteDir(name="tests", path="tests");
    api = SuiteDir(name="api", path="tests/api");
    root +>:Contains:+> tests;
    tests +>:Contains:+> api;

    health = TestFile(filename="health.yaml", year=2026);
    orders = TestFile(filename="orders.yml", year=2026);
    notes = TestFile(filename="README.md", year=2026, available=False);
    api +>:Contains:+> health;
    api +>:Contains:+> orders;
    tests +>:Contains:+> notes;

    mock = MockUpstream(host="127.0.0.1", port=9090, available=True);
    health +>:Serves:+> mock;
    orders +>:Serves:+> mock;

    health +>:Declares(order=1):+> Scenario(name="upstream_ok", passed=True);
    health +>:Declares(order=2):+> Scenario(name="latency", passed=True);
    orders +>:Declares(order=1):+> Scenario(name="create_order", passed=False);
    orders +>:Declares(order=2):+> Scenario(name="refund", passed=True);

    disc = Discoverer();
    root spawn disc;

    runner = Runner(retries=1, fail_fast=True, fail_under_pct=100);
    root spawn runner;

    total = runner.passed + runner.failed;
    rate = 100 if total == 0 else (runner.passed * 100 // total);
    threshold_met = rate >= runner.fail_under_pct;
    final_exit = 0;
    if disc.exit_code == 2 or runner.exit_code == 2 {
        final_exit = 2;
    } elif runner.failed > 0 or not threshold_met {
        final_exit = 1;
    }
    runner.exit_code = final_exit;

    print(f"=== REPORT: discovered={disc.found} passed={runner.passed} "
          f"failed={runner.failed} rate={rate}% exit={runner.exit_code} ===");
}

"""Sepolia testnet acceptance: dependency gates, claim-order audit, and evidence report compilation."""

node Tracked {
    has name: str = "";
    has ok: bool = False;
}

node Epic(Tracked) {
    has issue_num: int = 0;
}

node TestCase(Tracked) {
    has category: str = "";
    has failure_rank: int = 1;
}

node Criterion {
    has key: str = "";
    has description: str = "";
}

node Evidence {
    has rel_path: str = "";
    has digest: str = "";
    has claim_rank: int = 0;
}

edge BlockedBy { }
edge MapsTo { }
edge Satisfies { }

walker DependencyGate {
    has target_num: int = 4;
    has pending: list[int] = [];
    has agent_ready: bool = False;

    can start with Root entry {
        visit [-->];
    }

    can scan with Epic entry {
        if here.issue_num == self.target_num {
            visit [<--:BlockedBy:--] else { disengage; };
        } else {
            visit [-->];
        }
    }

    can check_blocker with Epic entry {
        if not here.ok {
            self.pending.append(here.issue_num);
        }
        disengage;
    }
}

walker ClaimAuditor {
    has violations: list[str] = [];
    has allowed_rank: int = 8;

    can start with Root entry {
        visit [-->[?:TestCase]];
    }

    can audit with TestCase entry {
        if not here.ok {
            self.allowed_rank = here.failure_rank;
            visit [->:MapsTo:->] else { disengage; };
        } else {
            print(f"[PASS] {here.name} ({here.category})");
            visit [-->];
        }
    }

    can check_evidence with Evidence entry {
        if here.claim_rank > self.allowed_rank {
            msg = f"rank {here.claim_rank} exceeds allowed stage {self.allowed_rank}";
            self.violations.append(f"{here.rel_path}: {msg}");
            print(f"[VIOLATION] {here.rel_path}: {msg}");
        } else {
            print(f"[ALLOWED] {here.rel_path} rank={here.claim_rank}");
        }
        disengage;
    }
}

walker ReportCompiler {
    has lines: list[str] = [];
    has current_key: str = "";

    can start with Root entry {
        visit [-->[?:Criterion]];
    }

    can compile with Criterion entry {
        self.current_key = here.key;
        visit [->:Satisfies:->] else {
            gap = f"{self.current_key}: MISSING";
            self.lines.append(gap);
            print(f"[GAP] {gap}");
            visit [-->];
        };
    }

    can record with Evidence entry {
        line = f"{self.current_key} -> {here.rel_path} sha256={here.digest}";
        self.lines.append(line);
        print(f"[EVIDENCE] {line}");
        disengage;
    }
}

walker StatusProbe {
    can start with Root entry {
        visit [-->];
    }

    can probe with Epic | TestCase entry {
        state = "OK" if here.ok else "FAIL";
        print(f"[{state}] {here.name}");
        visit [-->];
    }
}

