"""Postgres knowledge-memory graph: namespaces, documents, chunks, citations, and hybrid-retrieval walkers."""

node Namespace {
    has name: str = "";
    has active: bool = True;
}

node Document {
    has title: str = "";
    has version: int = 0;
    has available: bool = True;
}

node Chunk {
    has snippet: str = "";
    has rank: int = 0;
    has bm25_ready: bool = False;
    has vector_ready: bool = False;
    has available: bool = True;
}

edge InNamespace { }

edge HasChunk {
    has ordinal: int = 0;
}

edge Cites {
    has cite_label: str = "";
}

walker IngestAuditor {
    has rrf_ready: int = 0;
    has pending: int = 0;

    can start with Root entry {
        print("=== Phase-1 hybrid retrieval ingest audit ===");
        visit [-->];
    }

    can scan_ns with Namespace entry {
        label = "active" if here.active else "idle";
        print(f"Namespace [{label}]: {here.name}");
        visit [->:InNamespace:->];
    }

    can scan_doc with Document entry {
        status = "LIVE" if here.available else "TOMBSTONE";
        print(f"  Document [{status}] {here.title} (v{here.version})");
        visit [->:HasChunk:->];
    }

    can scan_chunk with Chunk entry {
        hybrid = here.bm25_ready and here.vector_ready and here.available;
        if hybrid {
            self.rrf_ready += 1;
            print(f"    [RRF] rank {here.rank}: {here.snippet}");
        } else {
            self.pending += 1;
            reason = "invalidated" if not here.available else "indexing";
            print(f"    [{reason}] rank {here.rank}: {here.snippet}");
        }
    }
}

walker CitationTracer {
    has on_path: list[str] = [];
    has cycles: int = 0;

    can start with Root entry {
        print("\n=== Citation graph traversal (cycle-guarded) ===");
        visit [-->];
    }

    can enter_ns with Namespace entry {
        visit [->:InNamespace:->];
    }

    can enter_doc with Document entry {
        visit [->:HasChunk:->];
    }

    can follow with Chunk entry {
        key = here.snippet;
        for seen in self.on_path {
            if seen == key {
                self.cycles += 1;
                print(f"    [CYCLE] at '{key}' — cycle policy: disengage");
                disengage;
            }
        }
        self.on_path.append(key);
        trail = " -> ".join(self.on_path);
        print(f"    cite path: {trail}");
        visit [->:Cites:->];
        self.on_path.pop();
    }
}

walker DeletionCascade {
    has tombstoned_chunks: int = 0;

    can start with Root entry {
        print("\n=== Version tombstone cascade invalidation ===");
        visit [-->];
    }

    can traverse_ns with Namespace entry {
        visit [->:InNamespace:->];
    }

    can purge_doc with Document entry {
        if not here.available {
            print(f"  Tombstoned document v{here.version}: {here.title}");
            visit [->:HasChunk:->];
        }
    }

    can invalidate with Chunk entry {
        if here.available {
            here.available = False;
            self.tombstoned_chunks += 1;
            print(f"    invalidated rank {here.rank}: {here.snippet}");
        }
    }
}

