"""Agent session refactor: thin facade delegates to domain controllers over a branching session tree."""

node SessionBranch {
    has label: str = "";
    has turn_budget: int = 0;
    has abandoned: bool = False;
}

node DomainController {
    has name: str = "";
    has domain: str = "";
    has active: bool = True;
    has handled: int = 0;
}

node LifecycleController(DomainController) { }
node CompactionController(DomainController) { }
node SettleController(DomainController) { }
node ToolDispatchController(DomainController) { }

node AgentSessionFacade {
    has session_id: str = "";
    has disposed: bool = False;
}

edge ChildBranch { }
edge DelegatesTo { has priority: int = 0; }

walker SessionNavigator {
    has depth: int = 0;
    has max_depth: int = 8;
    has seen: list[str] = [];
    has path: str = "";

    can start with Root entry {
        visit [->:ChildBranch:->] else { disengage; };
    }

    can walk_branch with SessionBranch entry {
        for prior in self.seen {
            if prior == here.label {
                print(f"[CYCLE] blocked revisit of {here.label} at depth {self.depth}");
                disengage;
            }
        }
        self.seen.append(here.label);
        next_path = f"{self.path}/{here.label}" if self.path else here.label;
        self.path = next_path;
        status = "abandoned" if here.abandoned else "active";
        print(f"[nav d={self.depth}] {here.label} ({status}, budget={here.turn_budget})");
        next_depth = self.depth + 1;
        if next_depth > self.max_depth {
            print(f"[nav] depth cap {self.max_depth} at {here.label}");
            disengage;
        }
        self.depth = next_depth;
        visit [->:ChildBranch:->] else { disengage; };
    }
}

walker EventRouter {
    has route_count: int = 0;

    can start with AgentSessionFacade entry {
        if here.disposed {
            print(f"[router] session {here.session_id} disposed — no dispatch");
            disengage;
        }
        print(f"[router] dispatching session {here.session_id}");
        visit [->:DelegatesTo:->] else { disengage; };
    }

    can dispatch with LifecycleController | CompactionController | SettleController | ToolDispatchController entry {
        if not here.active {
            print(f"[router] skip inactive {here.name}");
        } else {
            here.handled += 1;
            self.route_count += 1;
            print(f"[router] -> {here.name} ({here.domain}) handled={here.handled}");
        }
    }
}

walker DisposeCascade {
    can start with AgentSessionFacade entry {
        here.disposed = True;
        print(f"[dispose] tearing down {here.session_id}");
        visit [->:DelegatesTo:->] else { disengage; };
    }

    can invalidate with LifecycleController | CompactionController | SettleController | ToolDispatchController entry {
        was_active = here.active;
        here.active = False;
        state = "deactivated" if was_active else "already inactive";
        print(f"[dispose] {here.name}: {state}");
    }
}

with entry {
    main = SessionBranch(label="main", turn_budget=50);
    explore = SessionBranch(label="explore", turn_budget=20);
    fix_bug = SessionBranch(label="fix-bug", turn_budget=10, abandoned=True);
    hotfix = SessionBranch(label="hotfix", turn_budget=5);
    root +>:ChildBranch:+> main;
    main +>:ChildBranch:+> explore;
    explore +>:ChildBranch:+> fix_bug;
