}

edge DependsOn { }

walker TopoSort {
    has stack: list[int] = [];
    has done: list[int] = [];
    has order: list = [];
    has cyclic: bool = False;

    can start with SubGraph entry {
        visit [-->];
    }

    can descend with PlanTask entry {
        if here.task_id in self.stack {
            self.cyclic = True;
            disengage;
        }
        if here.task_id in self.done {
            disengage;
        }
        self.stack.append(here.task_id);
        visit [->:DependsOn:->];
    }

    can ascend with PlanTask exit {
        if self.cyclic {
            disengage;
        }
        self.stack.pop();
        self.done.append(here.task_id);
        self.order.append(here);
    }
}

walker RawEdgeCollector {
    has raw_order: list = [];

    can start with SubGraph entry {
        visit [-->];
