"""RBAC role composition: resolve effective permissions by walking composed child roles."""

node Role {
    has name: str = "";
    has permissions: list[str] = [];
}

node User {
    has username: str = "";
}

edge Composes { }

edge AssignedRole { }

walker PermissionResolver {
    has effective: list[str] = [];
    has visited: list[str] = [];

    can resolve with Role entry {
        if here.name in self.visited {
            visit [-->] else { disengage; };
        } else {
            self.visited.append(here.name);
            for key in here.permissions {
                if key not in self.effective {
                    self.effective.append(key);
                }
            }
            visit [->:Composes:->] else { disengage; };
        }
    }

    def report() {
        sorted_keys = sorted(self.effective);
        label = ", ".join(sorted_keys);
        print(f"Effective permissions ({len(self.effective)}): {label}");
    }
}

walker UserAuthzChecker {
    has effective: list[str] = [];
    has username: str = "";

    can start with User entry {
        if here.username != self.username {
            disengage;
        }
        print(f"Resolving authz for user {here.username}");
        visit [->:AssignedRole:->] else { disengage; };
    }

    can merge_role with Role entry {
        sub = PermissionResolver();
        here spawn sub;
        for key in sub.effective {
            if key not in self.effective {
                self.effective.append(key);
            }
        }
        visit [-->] else { disengage; };
    }

    def report() {
        sorted_keys = sorted(self.effective);
        label = ", ".join(sorted_keys);
        print(f"User effective permissions ({len(self.effective)}): {label}");
    }
}

with entry {
    childA = Role(
        name="childA",
        permissions=["A:read", "B:read", "B:update"]
    );
    childC = Role(name="childC", permissions=["D:read"]);
    childB = Role(
        name="childB",
        permissions=["A:read", "A:update", "A:create"]
    );
    parent = Role(
        name="parent",
        permissions=["D:update", "C:read", "C:update", "C:create"]
    );

    parent +>:Composes:+> childA;
    parent +>:Composes:+> childB;
    childB +>:Composes:+> childC;

    operator = User(username="ops-lead");
    operator +>:AssignedRole:+> parent;

    root ++> operator;

    print("=== parent role effective set (union of self + descendants) ===");
    parent_resolver = PermissionResolver();
    parent spawn parent_resolver;
    parent_resolver.report();

    print("=== childB alone (no parent or sibling grants) ===");
    childB_resolver = PermissionResolver();
    childB spawn childB_resolver;
    childB_resolver.report();

    print("=== user assigned only parent ===");
    checker = UserAuthzChecker(username="ops-lead");
    operator spawn checker;
    checker.report();
}

"""Recursive planner subgraph: validated topological order vs raw edge order.

Models frankenbeast issue #4184 where PlanGraph.fromTasks validation is
discarded and createWithRawEdges returns tasks in arbitrary insertion order.
"""

node PlanTask {
    has title: str = "";
    has task_id: int = 0;
    has insert_order: int = 0;
}

node SubGraph {
    has reason: str = "";
}

edge DependsOn { }

walker TopoSort {
    has stack: list[int] = [];
    has done: list[int] = [];
    has order: list[PlanTask] = [];
    has cyclic: bool = False;

    can start with SubGraph entry {
        visit [-->];
    }

    can descend with PlanTask entry {
        if here.task_id in self.stack {
            self.cyclic = True;
            disengage;
        }
        if here.task_id in self.done {
            disengage;
        }
        self.stack.append(here.task_id);
        visit [->:DependsOn:->];
    }

    can ascend with PlanTask exit {
        if self.cyclic {
            disengage;
        }
        self.stack.pop();
        self.done.append(here.task_id);
        self.order.append(here);
    }
}

walker RawEdgeCollector {
    has raw_order: list[PlanTask] = [];

    can start with SubGraph entry {
        visit [-->];
    }

    can collect with PlanTask entry {
        self.raw_order.append(here);
        visit [-->];
    }
}

walker RecursivePlanner {
    has reason: str = "recursive expansion";
    has discard_validated: bool = False;

    can start with Root entry {
        visit [-->[?:SubGraph]] else { disengage; };
    }

    can build with SubGraph entry {
        validator = TopoSort();
        here spawn validator;
        if validator.cyclic {
            print(f"CyclicDependencyError during {self.reason}");
            disengage;
        }
        if self.discard_validated {
            collector = RawEdgeCollector();
            here spawn collector;
            execution_order = collector.raw_order;
            path_label = "BUG: discarded validated fromTasks, returned raw edges";
        } else {
            execution_order = validator.order;
            path_label = "FIX: returned validated fromTasks graph";
        }
        print(f"[{path_label}] {here.reason}");
        for task in execution_order {
            print(f"  -> {task.title} (insert_order={task.insert_order})");
        }
        visit [-->];
    }
}

with entry {
    sg = SubGraph(reason="recursive expansion");
    root ++> sg;

    lint = PlanTask(title="lint", task_id=1, insert_order=3);
    test = PlanTask(title="test", task_id=2, insert_order=4);
    compile = PlanTask(title="compile", task_id=3, insert_order=2);
    deploy = PlanTask(title="deploy", task_id=4, insert_order=1);

    sg ++> deploy ++> compile ++> lint ++> test;

    compile +>:DependsOn:+> lint;
    compile +>:DependsOn:+> test;
    deploy +>:DependsOn:+> compile;

    print("=== Buggy _buildSubGraph (validate then discard) ===");
    root spawn RecursivePlanner(discard_validated=True);

    print("=== Fixed _buildSubGraph (return fromTasks) ===");
    root spawn RecursivePlanner(discard_validated=False);

    print("=== Cycle probe ===");
    sg_cycle = SubGraph(reason="cycle probe");
    root ++> sg_cycle;
    task_a = PlanTask(title="task_a", task_id=10, insert_order=1);
    task_b = PlanTask(title="task_b", task_id=11, insert_order=2);
    sg_cycle ++> task_a ++> task_b;
    task_a +>:DependsOn:+> task_b;
    task_b +>:DependsOn:+> task_a;
    cycle_check = TopoSort();
    sg_cycle spawn cycle_check;
    if cycle_check.cyclic {
        print("CyclicDependencyError: cycle detected in task dependencies");
    }
}

