walker SpawnPolicyAuditor {
    has max_depth: int = 4;
    has max_running: int = 4;
    has running_slots: int = 0;

    can start with Root entry {
        print("=== spawn policy audit ===");
        visit [-->];
        cap_label = "OK" if self.running_slots <= self.max_running else "OVER";
        print(f"tree running slots: {self.running_slots}/{self.max_running} ({cap_label})");
    }

    can tally with Agent entry {
        if here.available {
            self.running_slots += 1;
        }
        visit [->:SpawnedBy:->] else { disengage; };
    }

    can audit_pi_nested with PiAgent entry {
        child_depth = here.year + 1;
        depth_ok = child_depth <= self.max_depth;
        verdict = "ALLOW" if depth_ok else "DENY(depth)";
        print(f"  {here.title}: nested spawn(pi) -> {verdict}");
        visit [->:SpawnedBy:->] else { disengage; };
    }

    can audit_non_pi_nested with ClaudeAgent | CodexAgent entry {
        nested_ctx = here.year > 0;
        verdict = "DENY(policy)" if nested_ctx else "ALLOW(top-level)";
        print(f"  {here.title}: nested spawn(non-pi) -> {verdict}");
        visit [->:SpawnedBy:->] else { disengage; };
    }
}

walker SubtreeCanceler {
    can start with Agent entry {
        visit [->:SpawnedBy:->] else { disengage; };
        here.available = False;
        print(f"CANCELLED subtree node: {here.title}");
    }
}

