"""Class and instance semantics: inheritance member resolution, cycle detection, and cascade invalidation."""

node ProtoField {
    has name: str = "";
    has value: str = "";
}

node ClassDef {
    has class_name: str = "";
    has valid: bool = True;
}

node ClassInstance {
    has instance_name: str = "";
    has valid: bool = True;
}

edge Extends { }

edge TypedAs { }

edge Declares { }

walker MemberResolver {
    has target_name: str = "";
    has result_value: str = "";
    has found: bool = False;
    has visited_classes: list[str] = [];
    has current_depth: int = 0;
    has max_depth: int = 8;
    has error_message: str = "";

    can resolve with ClassInstance entry {
        visit [->:Declares:->];
        if not self.found {
            visit [->:TypedAs:->] else { disengage; };
        }
    }

    can lookup_field with ProtoField entry {
        if not self.found and here.name == self.target_name {
            self.result_value = here.value;
            self.found = True;
            disengage;
        }
    }

    can resolve_class with ClassDef entry {
        if self.found {
            disengage;
        }
        if self.current_depth >= self.max_depth {
            self.error_message = "depth limit exceeded";
            disengage;
        }
        if here.class_name in self.visited_classes {
            self.error_message = f"inheritance cycle at {here.class_name}";
            disengage;
        }
        self.visited_classes.append(here.class_name);
        self.current_depth += 1;
        visit [->:Declares:->];
        if not self.found {
            visit [->:Extends:->] else { disengage; };
        }
    }
}

walker InheritanceValidator {
    has visited_classes: list[str] = [];
    has cycle_detected: bool = False;
    has cycle_at: str = "";

    can audit with ClassDef entry {
        if here.class_name in self.visited_classes {
            self.cycle_detected = True;
            self.cycle_at = here.class_name;
            disengage;
        }
        self.visited_classes.append(here.class_name);
        visit [->:Extends:->] else { disengage; };
    }
}

walker CascadeInvalidator {
    has invalidated: list[str] = [];

    can invalidate with ClassDef entry {
        here.valid = False;
        self.invalidated.append(here.class_name);
        visit [<--:TypedAs:--];
        visit [<--:Extends:--];
    }

    can invalidate_instance with ClassInstance entry {
        here.valid = False;
        self.invalidated.append(here.instance_name);
    }
}

with entry {
    animal = ClassDef(class_name="Animal");
    dog = ClassDef(class_name="Dog");
    cat = ClassDef(class_name="Cat");

    animal +>:Declares:+> ProtoField(name="species", value="mammal");
    dog +>:Declares:+> ProtoField(name="breed", value="labrador");
    dog +>:Declares:+> ProtoField(name="name", value="Canine");
    dog +>:Extends:+> animal;
