    name_lookup = MemberResolver(target_name="name");
    rover spawn name_lookup;
    print(f"name={name_lookup.result_value} found={name_lookup.found}");

    cycle_a = ClassDef(class_name="CycleA");
    cycle_b = ClassDef(class_name="CycleB");
    cycle_a +>:Extends:+> cycle_b;
