"""RBAC demo: multi-role membership, polymorphic resource-scoped grants, and permission resolution with OU and role-hierarchy walks."""

node Tenant {
    has name: str = "";
}

node Profile {
    has display_name: str = "";
}

node Role {
    has name: str = "";
    has permissions: list[str] = [];
}

node OrganizationalUnit {
    has ou_name: str = "";
}

node PluginResource {
    has resource_type: str = "";
    has resource_id: str = "";
}

edge Membership {
    has tenant_id: str = "";
}

edge ProfileOuPlacement { }

edge OuParent { }

edge RoleParent { }

edge ResourceRoleGrant {
    has tenant_id: str = "";
    has profile_id: str = "";
}

walker PermissionResolver {
    has target_profile: str = "";
    has tenant_id: str = "";
    has target_resource_type: str = "";
    has target_resource_id: str = "";
    has phase: str = "init";
    has roles_collected: list[str] = [];
    has permissions: list[str] = [];
    has visited_ou: list[str] = [];
    has expanded_roles: list[str] = [];
    has ou_depth: int = 0;
    has role_depth: int = 0;
    has max_depth: int = 10;
    has max_ou_depth: int = 5;

    def add_role(self, role_name: str) {
        if role_name in self.roles_collected {
            return;
        }
        self.roles_collected.append(role_name);
    }

    def merge_permissions(self, perms: list[str]) {
        for p in perms {
            if p not in self.permissions {
                self.permissions.append(p);
            }
        }
    }

    def begin_resource_grant(self) {
        self.phase = "resource_grant";
        visit [-->[?:PluginResource]] else {
            self.begin_expand();
        };
    }

    def begin_expand(self) {
        self.phase = "expand";
        self.expanded_roles = [];
        self.role_depth = 0;
        visit [<--] else {
            self.report();
        };
    }

    def report(self) {
        print(f"[RBAC] profile={self.target_profile} tenant={self.tenant_id} "
              f"resource={self.target_resource_type}:{self.target_resource_id}");
        print(f"  effective roles: {self.roles_collected}");
        print(f"  effective permissions: {self.permissions}");
    }

    can start with Root entry {
        visit [-->];
    }

    can enter_tenant with Tenant entry {
        if here.name != self.tenant_id {
            visit [-->];
        } else {
            visit [-->];
        }
    }

    can begin_resolution with Profile entry {
        if here.display_name != self.target_profile {
            visit [-->];
        } else {
            self.phase = "memberships";
            visit [->:Membership:->];
            self.phase = "ou_walk";
            self.visited_ou = [];
            self.ou_depth = 0;
            visit [->:ProfileOuPlacement:->] else {
                self.begin_resource_grant();
            };
            disengage;
        }
    }

    can climb_ou with OrganizationalUnit entry {
        if self.phase != "ou_walk" {
            visit [-->];
        } else {
            if here.ou_name in self.visited_ou {
                print(f"[RBAC] OU ancestor cycle at {here.ou_name}");
                disengage;
            }
            if self.ou_depth >= self.max_ou_depth {
                disengage;
            }
            self.visited_ou.append(here.ou_name);
            visit [->:ResourceRoleGrant:->];
            self.ou_depth += 1;
            visit [->:OuParent:->] else {
                self.ou_depth = 0;
                self.begin_resource_grant();
            };
        }
    }

    can check_resource with PluginResource entry {
        if self.phase != "resource_grant" {
            visit [-->];
        } else {
            if here.resource_type != self.target_resource_type or here.resource_id != self.target_resource_id {
                disengage;
            } else {
                visit [->:ResourceRoleGrant:->];
                self.begin_expand();
            }
        }
    }

    can absorb_role with Role entry {
        if self.phase == "memberships" {
            self.add_role(here.name);
            disengage;
        } else if self.phase == "ou_walk" {
            self.add_role(here.name);
            disengage;
        } else if self.phase == "resource_grant" {
            self.add_role(here.name);
            disengage;
        } else if self.phase == "expand" {
            if here.name not in self.roles_collected {
                disengage;
            }
            self.merge_permissions(here.permissions);
            if here.name in self.expanded_roles {
                print(f"[RBAC] role inheritance cycle at {here.name}");
                disengage;
            }
            if self.role_depth >= self.max_depth {
                disengage;
            }
            self.expanded_roles.append(here.name);
            self.role_depth += 1;
            visit [->:RoleParent:->] else { disengage; };
            self.role_depth -= 1;
            disengage;
        } else {
            visit [-->];
        }
    }

    can expand_from_tenant with Tenant entry {
        if self.phase == "expand" {
            visit [-->[?:Role]] else {
                self.report();
                disengage;
            };
        } else {
            visit [-->];
        }
    }
}

with entry {
    tenant = Tenant(name="acme");
    alice = Profile(display_name="Alice");
    editor = Role(name="editor", permissions=["content:edit"]);
    admin = Role(name="admin", permissions=["content:delete", "tenant:manage"]);
    viewer = Role(name="viewer", permissions=["content:read"]);
    engineering = OrganizationalUnit(ou_name="Engineering");
    platform = OrganizationalUnit(ou_name="Platform");
    doc = PluginResource(resource_type="my_plugin", resource_id="doc-42");

    root ++> tenant;
    tenant ++> alice;
    tenant ++> editor;
    tenant ++> admin;
    tenant ++> viewer;
    tenant ++> engineering;
    tenant ++> platform;
    alice ++> doc;

    alice +>:Membership(tenant_id="acme"):+> editor;
    alice +>:Membership(tenant_id="acme"):+> viewer;
    alice +>:ProfileOuPlacement:+> engineering;
    engineering +>:OuParent:+> platform;
    platform +>:ResourceRoleGrant(tenant_id="acme"):+> admin;
    doc +>:ResourceRoleGrant(tenant_id="acme", profile_id="Alice"):+> editor;
    admin +>:RoleParent:+> editor;

    root spawn PermissionResolver(
        target_profile="Alice",
        tenant_id="acme",
        target_resource_type="my_plugin",
        target_resource_id="doc-42"
    );
}

"""HEALPix nested topology: directional neighbour export and connected-component labeling over typed edges."""

node Pixel {
    has cell_id: int = 0;
    has depth: int = 0;
    has label: int = -1;
}

node SingularityPixel(Pixel) {
    has pole: str = "";
}

node TopologyAdapter {
    has backend_name: str = "healpix-geo";
    has api: str = "nested.neighbours";
}

node DirectionalNeighbour {
    has direction: str = "";
    has dest_id: int = -1;
}

edge FromPixel { }

edge Adjacent { }

walker NeighbourExport {
    has connectivity: str = "edge";

    can start with Root entry {
        print(f"topology adapter -> {self.connectivity} via healpix-geo");
        visit [-->];
    }

    can emit with Pixel | SingularityPixel entry {
        dirs = ["SW", "NW", "NE", "SE"];
        if self.connectivity == "edge_or_vertex" {
            dirs = ["SW", "W", "NW", "N", "NE", "E", "SE", "S"];
        }
        row = [];
        for d in dirs {
            row.append(-1);
        }
        scout = EdgeScout(dirs=dirs, row=row);
        here spawn scout;
        width = len(dirs);
        print(f"nested_neighbours cell={here.cell_id} depth={here.depth} "
              f"connectivity={self.connectivity} shape=(1, {width}) "
              f"dtype=int64 order={dirs} -> {scout.row}");
        visit [-->] else { disengage; };
    }
}

walker EdgeScout {
    has dirs: list[str] = [];
    has row: list[int] = [];

    can start with Pixel | SingularityPixel entry {
        visit [->:FromPixel:->] else { disengage; };
    }

    can read with DirectionalNeighbour entry {
        for (i, d) in enumerate(self.dirs) {
            if d == here.direction {
                self.row[i] = here.dest_id;
            }
        }
    }
}

walker ComponentLabeler {
    has next_label: int = 0;

    can start with Root entry {
        print("connected-component analysis over edge neighbours");
        visit [-->];
    }

    can discover with Pixel | SingularityPixel entry {
        if here.label >= 0 {
            visit [-->] else { disengage; };
        } else {
            tag = self.next_label;
            self.next_label += 1;
            filler = FloodFill(comp_id=tag);
            here spawn filler;
            visit [-->] else { disengage; };
        }
    }
}

walker FloodFill {
    has comp_id: int = 0;
    has seen: list[int] = [];

    can flood with Pixel | SingularityPixel entry {
        if here.cell_id in self.seen {
            disengage;
        }
        self.seen.append(here.cell_id);
        here.label = self.comp_id;
        print(f"  label cell {here.cell_id} -> component {self.comp_id}");
        visit [->:Adjacent:->] else { disengage; };
    }
}

