"""1+1 CDT graph-distance demo: direct-lattice and dual-lattice BFS shells and balls from a fixed root."""

node Vertex {
    has label: str = "";
    has bfs_dist: int = -1;
}

node Triangle {
    has label: str = "";
    has bfs_dist: int = -1;
}

edge Link { }
edge DualLink { }
edge Incidence { }

walker DirectShellWalker {
    has root: Vertex;
    has target_r: int = 0;
    has next_dist: int = 0;
    has shell_count: int = 0;
    has ball_count: int = 0;

    can start with Root entry {
        visit [-->[?:Vertex]] else { disengage; };
    }

    can measure with Vertex entry {
        if here.bfs_dist >= 0 {
            disengage;
        }
        dist = 0;
        if here is not self.root {
            dist = self.next_dist;
        }
        here.bfs_dist = dist;
        if dist <= self.target_r {
            self.ball_count += 1;
        }
        if dist == self.target_r {
            self.shell_count += 1;
            print(f"direct S_{self.target_r}({self.root.label}): {here.label} (dist={dist})");
        }
        if dist < self.target_r {
            self.next_dist = dist + 1;
            visit [here->:Link:->] else { disengage; };
        }
        disengage;
    }
}

walker DualShellWalker {
    has root: Triangle;
    has target_r: int = 0;
    has next_dist: int = 0;
    has shell_count: int = 0;
    has ball_count: int = 0;

    can start with Root entry {
        visit [-->[?:Triangle]] else { disengage; };
    }

    can measure with Triangle entry {
        if here.bfs_dist >= 0 {
            disengage;
        }
        dist = 0;
        if here is not self.root {
            dist = self.next_dist;
        }
