"""VFS stale-while-revalidate: serve cached directory snapshots during non-blocking refresh."""

node VfsMount {
    has name: str = "";
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

node Directory {
    has path: str = "";
    has generation: int = 0;
    has snapshot: str = "";
    has snapshot_valid: bool = False;
    has freshness: int = 0;
    has refreshing: bool = False;
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

edge Hosts { }
edge Contains { }

walker CacheClient {
    has label: str = "SSH-MountMate";
    has reads: int = 0;

    can start with Root entry {
        visit [->:Hosts:->] else { disengage; };
    }

    can enter_mount with VfsMount entry {
        visit [->:Contains:->] else { disengage; };
    }

    can read_dir with Directory entry {
        self.read_snapshot(here);
        visit [->:Contains:->] else { disengage; };
    }

    def read_snapshot(target: Directory) {
        if target.snapshot_valid {
            mode = "stale-while-revalidate" if target.refreshing else "cached";
            print(
                f"[{self.label}] ReadDir {target.path} ({mode}): {target.snapshot}"
            );
            self.reads += 1;
        } else {
            print(f"[{self.label}] ReadDir {target.path}: BLOCKED (no valid snapshot)");
        }
    }
}

walker StaleRefresher {
    has stale: bool = True;
    has recursive: bool = False;
    has retries_left: int = 3;
    has simulate_conflicts: int = 0;
    has force_listing_fail: bool = False;
    has new_listing: str = "";

    can start with Root entry {
        if self.stale and self.recursive {
            print("REJECT vfs/refresh: stale=true cannot combine with recursive=true");
            disengage;
        }
        visit [->:Hosts:->] else { disengage; };
    }

    can enter_mount with VfsMount entry {
        visit [->:Contains:->] else { disengage; };
    }

    can revalidate with Directory entry {
        if not self.stale {
            disengage;
        }
        if not here.snapshot_valid {
            print(f"SKIP {here.path}: not cached or snapshot invalid");
            if self.recursive {
                visit [->:Contains:->] else { disengage; };
            } else {
                disengage;
            }
        } else {
            self.refresh_one(here);
            if self.recursive {
                visit [->:Contains:->] else { disengage; };
            } else {
                disengage;
            }
        }
    }

    def refresh_one(target: Directory) {
        kept_snapshot = target.snapshot;
        kept_freshness = target.freshness;
        print(f"REFRESH {target.path}: background listing (Dir.mu not held)");
        target.refreshing = True;
        self.new_listing = f"{target.path}/report.pdf,{target.path}/slides/,{target.path}/notes.md";
        print(f"  remote listing fetched off-lock -> {self.new_listing}");
        client = CacheClient(label="during-refresh");
        client.read_snapshot(target);
        merged = False;
        attempt = 0;
        while attempt < 3 and not merged and self.retries_left > 0 {
            captured_gen = target.generation;
            if self.force_listing_fail {
                print(f"  listing cancelled/failed; retaining snapshot");
                break;
            }
            if self.simulate_conflicts > 0 {
                target.generation += 1;
                self.simulate_conflicts -= 1;
            }
            if target.generation != captured_gen {
                self.retries_left -= 1;
                attempt += 1;
                print(
                    f"  generation conflict on {target.path}; "
                    f"retry {attempt}/3 (retries_left={self.retries_left})"
                );
            } else {
                target.snapshot = self.new_listing;
                target.freshness = kept_freshness + 1;
                merged = True;
                print(f"  merged new snapshot under short lock for {target.path}");
            }
        }
        if not merged {
            target.snapshot = kept_snapshot;
            target.freshness = kept_freshness;
            if self.retries_left <= 0 {
                print(
                    f"  max retries on {target.path}; "
                    f"kept cache (still changing): {target.snapshot}"
                );
            }
        }
        target.refreshing = False;
    }
}

walker BlockingRefresher {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;

    can start with Root entry {
        visit [->:Hosts:->] else { disengage; };
    }

    can enter_mount with VfsMount entry {
        visit [->:Contains:->] else { disengage; };
    }

    can refresh with Directory entry {
        if not here.snapshot_valid {
            visit [->:Contains:->] else { disengage; };
        } else {
            print(f"BLOCKING refresh {here.path}: holding Dir.mu for full listing");
            here.refreshing = True;
            here.snapshot_valid = False;
            client = CacheClient(label="blocked-client");
            client.read_snapshot(here);
            here.snapshot = f"{here.path}/rebuilt-only.tar";
            here.snapshot_valid = True;
            here.freshness += 1;
            here.refreshing = False;
            print(f"  blocking refresh done for {here.path}");
            disengage;
        }
    }
}

