    mount = VfsMount(name="ssh-remote");
    docs = Directory(
        path="/docs",
        generation=1,
        snapshot="report.pdf,slides/",
        snapshot_valid=True,
        freshness=1700
    );
    photos = Directory(
        path="/docs/photos",
