    root +>:Hosts:+> mount;
    mount +>:Contains:+> docs;
    docs +>:Contains:+> photos;
    mount +>:Contains:+> archive;
    mount +>:Contains:+> uncached;

    print("\n-- client reads before refresh --");
    root spawn CacheClient(label="pre-refresh");

    print("\n-- stale=true non-recursive refresh with conflict retries --");
    root spawn StaleRefresher(stale=True, recursive=False, simulate_conflicts=2);

    print("\n-- stale=true + recursive=true rejected --");
    root spawn StaleRefresher(stale=True, recursive=True);

    print("\n-- stale refresh skips uncached directory --");
