"""HEALPix nested topology: directional neighbour export and connected-component labeling over typed edges."""

node Pixel {
    has cell_id: int = 0;
    has depth: int = 0;
    has label: int = -1;
}

node SingularityPixel(Pixel) {
    has pole: str = "";
}

node TopologyAdapter {
    has backend_name: str = "healpix-geo";
    has api: str = "nested.neighbours";
}

node DirectionalNeighbour {
    has direction: str = "";
    has dest_id: int = -1;
}

edge FromPixel { }

edge Adjacent { }

walker NeighbourExport {
    has connectivity: str = "edge";

    can start with Root entry {
        print(f"topology adapter -> {self.connectivity} via healpix-geo");
        visit [-->];
    }

    can emit with Pixel | SingularityPixel entry {
        dirs = ["SW", "NW", "NE", "SE"];
        if self.connectivity == "edge_or_vertex" {
            dirs = ["SW", "W", "NW", "N", "NE", "E", "SE", "S"];
        }
        row = [];
        for d in dirs {
            row.append(-1);
        }
        scout = EdgeScout(dirs=dirs, row=row);
        here spawn scout;
        width = len(dirs);
        print(f"nested_neighbours cell={here.cell_id} depth={here.depth} "
              f"connectivity={self.connectivity} shape=(1, {width}) "
              f"dtype=int64 order={dirs} -> {scout.row}");
        visit [-->] else { disengage; };
    }
}

walker EdgeScout {
    has dirs: list[str] = [];
    has row: list[int] = [];

    can start with Pixel | SingularityPixel entry {
        visit [->:FromPixel:->] else { disengage; };
    }

    can read with DirectionalNeighbour entry {
        for (i, d) in enumerate(self.dirs) {
            if d == here.direction {
                self.row[i] = here.dest_id;
            }
        }
        visit [-->] else { disengage; };
    }
}

walker ComponentLabeler {
    has next_label: int = 0;

    can start with Root entry {
        print("connected-component analysis over edge neighbours");
        visit [-->];
    }

    can discover with Pixel | SingularityPixel entry {
        if here.label >= 0 {
            visit [-->] else { disengage; };
        } else {
            tag = self.next_label;
            self.next_label += 1;
            filler = FloodFill(comp_id=tag);
            here spawn filler;
            visit [-->] else { disengage; };
        }
    }
}

walker FloodFill {
    has comp_id: int = 0;
    has seen: list[int] = [];

    can flood with Pixel | SingularityPixel entry {
        if here.cell_id in self.seen {
            disengage;
        }
        self.seen.append(here.cell_id);
        here.label = self.comp_id;
        print(f"  label cell {here.cell_id} -> component {self.comp_id}");
        visit [->:Adjacent:->] else { disengage; };
    }
}

