    root spawn CacheClient(label="pre-refresh");

    print("\n-- stale=true non-recursive refresh with conflict retries --");
    root spawn StaleRefresher(stale=True, recursive=False, simulate_conflicts=2);

    print("\n-- stale=true + recursive=true rejected --");
    root spawn StaleRefresher(stale=True, recursive=True);

    print("\n-- stale refresh skips uncached directory --");
    root spawn StaleRefresher(stale=True, recursive=False);

    print("\n-- listing failure retains existing cache --");
    root spawn StaleRefresher(
        stale=True,
        recursive=False,
        force_listing_fail=True
    );

    print("\n-- blocking refresh (no stale) makes snapshot unavailable --");
    root spawn BlockingRefresher();
}

"""RBAC demo: multi-role membership, polymorphic resource-scoped grants, and permission resolution with OU and role-hierarchy walks."""

node Tenant {
    has name: str = "";
}

node Profile {
    has display_name: str = "";
}

node Role {
    has name: str = "";
    has permissions: list[str] = [];
}

node OrganizationalUnit {
    has ou_name: str = "";
}

node PluginResource {
    has resource_type: str = "";
    has resource_id: str = "";
}

edge Membership {
    has tenant_id: str = "";
}

edge ProfileOuPlacement { }

edge OuParent { }

edge RoleParent { }

edge ResourceRoleGrant {
    has tenant_id: str = "";
    has profile_id: str = "";
}

walker PermissionResolver {
    has target_profile: str = "";
    has tenant_id: str = "";
    has target_resource_type: str = "";
    has target_resource_id: str = "";
    has phase: str = "init";
    has roles_collected: list[str] = [];
    has permissions: list[str] = [];
    has visited_ou: list[str] = [];
    has expanded_roles: list[str] = [];
    has ou_depth: int = 0;
    has role_depth: int = 0;
    has max_depth: int = 10;
    has max_ou_depth: int = 5;

    def add_role(role_name: str) {
        if role_name in self.roles_collected {
            return;
        }
        self.roles_collected.append(role_name);
    }

    def merge_permissions(perms: list[str]) {
        for p in perms {
            if p not in self.permissions {
                self.permissions.append(p);
            }
        }
    }

    def begin_resource_grant() {
        self.phase = "resource_grant";
        visit [-->[?:PluginResource]] else {
            self.begin_expand();
        };
    }

    def begin_expand() {
        self.phase = "expand";
        self.expanded_roles = [];
        self.role_depth = 0;
        visit [<--] else {
            self.report();
        };
    }

    def report() {
        print(f"[RBAC] profile={self.target_profile} tenant={self.tenant_id} "
              f"resource={self.target_resource_type}:{self.target_resource_id}");
        print(f"  effective roles: {self.roles_collected}");
        print(f"  effective permissions: {self.permissions}");
    }

    can start with Root entry {
        visit [-->];
    }

    can enter_tenant with Tenant entry {
        if here.name != self.tenant_id {
            visit [-->];
        } else {
            visit [-->];
        }
    }

    can begin_resolution with Profile entry {
        if here.display_name != self.target_profile {
            visit [-->];
        } else {
            self.phase = "memberships";
            visit [->:Membership:->];
            self.phase = "ou_walk";
            self.visited_ou = [];
            self.ou_depth = 0;
            visit [->:ProfileOuPlacement:->] else {
                self.begin_resource_grant();
            };
            disengage;
        }
    }

    can climb_ou with OrganizationalUnit entry {
        if self.phase != "ou_walk" {
            visit [-->];
        } else {
            if here.ou_name in self.visited_ou {
                print(f"[RBAC] OU ancestor cycle at {here.ou_name}");
                disengage;
            }
            if self.ou_depth >= self.max_ou_depth {
                disengage;
            }
            self.visited_ou.append(here.ou_name);
            visit [->:ResourceRoleGrant:->];
            self.ou_depth += 1;
            visit [->:OuParent:->] else {
                self.ou_depth = 0;
                self.begin_resource_grant();
            };
        }
    }

    can check_resource with PluginResource entry {
        if self.phase != "resource_grant" {
            visit [-->];
        } else {
            if here.resource_type != self.target_resource_type or here.resource_id != self.target_resource_id {
                disengage;
            } else {
                visit [->:ResourceRoleGrant:->];
                self.begin_expand();
            }
        }
    }

    can absorb_role with Role entry {
        if self.phase == "memberships" {
            self.add_role(here.name);
            disengage;
        } elif self.phase == "ou_walk" {
            self.add_role(here.name);
            disengage;
        } elif self.phase == "resource_grant" {
            self.add_role(here.name);
            disengage;
        } elif self.phase == "expand" {
            if here.name not in self.roles_collected {
                disengage;
            }
            self.merge_permissions(here.permissions);
            if here.name in self.expanded_roles {
                print(f"[RBAC] role inheritance cycle at {here.name}");
                disengage;
            }
            if self.role_depth >= self.max_depth {
                disengage;
            }
            self.expanded_roles.append(here.name);
            self.role_depth += 1;
            visit [->:RoleParent:->] else { disengage; };
            self.role_depth -= 1;
            disengage;
        } else {
            visit [-->];
        }
    }

    can expand_from_tenant with Tenant entry {
        if self.phase == "expand" {
            visit [-->[?:Role]] else {
                self.report();
                disengage;
            };
        } else {
            visit [-->];
        }
    }
}

with entry {
    tenant = Tenant(name="acme");
    alice = Profile(display_name="Alice");
    editor = Role(name="editor", permissions=["content:edit"]);
    admin = Role(name="admin", permissions=["content:delete", "tenant:manage"]);
    viewer = Role(name="viewer", permissions=["content:read"]);
    engineering = OrganizationalUnit(ou_name="Engineering");
    platform = OrganizationalUnit(ou_name="Platform");
    doc = PluginResource(resource_type="my_plugin", resource_id="doc-42");

    root ++> tenant;
    tenant ++> alice;
    tenant ++> editor;
    tenant ++> admin;
    tenant ++> viewer;
    tenant ++> engineering;
    tenant ++> platform;
    alice ++> doc;

    alice +>:Membership(tenant_id="acme"):+> editor;
    alice +>:Membership(tenant_id="acme"):+> viewer;
    alice +>:ProfileOuPlacement:+> engineering;
    engineering +>:OuParent:+> platform;
    platform +>:ResourceRoleGrant(tenant_id="acme"):+> admin;
    doc +>:ResourceRoleGrant(tenant_id="acme", profile_id="Alice"):+> editor;
    admin +>:RoleParent:+> editor;

    root spawn PermissionResolver(
        target_profile="Alice",
        tenant_id="acme",
        target_resource_type="my_plugin",
        target_resource_id="doc-42"
    );
}

"""1+1 CDT graph-distance demo: direct-lattice and dual-lattice BFS shells and balls from a fixed root."""

node Vertex {
    has label: str = "";
    has dist: int = -1;
}

node Triangle {
    has label: str = "";
    has dist: int = -1;
}

edge Link { }
edge DualLink { }
edge Incidence { }

walker DirectShellWalker {
    has fixed_root: Vertex;
    has target_r: int = 0;
    has frontier_depth: int = 0;
    has shell_count: int = 0;
    has ball_count: int = 0;
    has begun: bool = False;

    can start with Root entry {
        visit [-->];
    }

    can locate with Vertex entry {
        if self.begun {
            disengage;
        }
        if here is not self.fixed_root {
            visit [-->];
            disengage;
        }
        self.begun = True;
        here.dist = 0;
        self.ball_count = 1;
        if self.target_r == 0 {
            self.shell_count = 1;
            print(f"direct S_0({self.fixed_root.label}): {here.label} (dist=0)");
            disengage;
        }
        self.frontier_depth = 1;
        visit [here->:Link:->] else { disengage; };
    }

    can expand with Vertex entry {
        if here.dist >= 0 {
            disengage;
        }
        here.dist = self.frontier_depth;
        self.ball_count += 1;
        if here.dist == self.target_r {
            self.shell_count += 1;
            print(f"direct S_{self.target_r}({self.fixed_root.label}): {here.label} (dist={here.dist})");
        }
        if here.dist < self.target_r {
            saved_depth = self.frontier_depth;
            self.frontier_depth = here.dist + 1;
            visit [here->:Link:->];
            self.frontier_depth = saved_depth;
        }
        disengage;
    }
}

walker DualShellWalker {
    has fixed_root: Triangle;
    has target_r: int = 0;
    has frontier_depth: int = 0;
    has shell_count: int = 0;
    has ball_count: int = 0;
    has begun: bool = False;

    can start with Root entry {
        visit [-->];
    }

    can locate with Triangle entry {
        if self.begun {
            disengage;
        }
        if here is not self.fixed_root {
            visit [-->];
            disengage;
        }
        self.begun = True;
        here.dist = 0;
        self.ball_count = 1;
        if self.target_r == 0 {
            self.shell_count = 1;
            print(f"dual S_0({self.fixed_root.label}): {here.label} (dist=0)");
            disengage;
        }
        self.frontier_depth = 1;
        visit [here->:DualLink:->] else { disengage; };
    }

    can expand with Triangle entry {
        if here.dist >= 0 {
            disengage;
        }
        here.dist = self.frontier_depth;
        self.ball_count += 1;
        if here.dist == self.target_r {
            self.shell_count += 1;
            print(f"dual S_{self.target_r}({self.fixed_root.label}): {here.label} (dist={here.dist})");
        }
        if here.dist < self.target_r {
            saved_depth = self.frontier_depth;
            self.frontier_depth = here.dist + 1;
            visit [here->:DualLink:->];
            self.frontier_depth = saved_depth;
        }
        disengage;
    }
}

with entry {
    v0 = Vertex(label="v0");
    v1 = Vertex(label="v1");
    v2 = Vertex(label="v2");
    v3 = Vertex(label="v3");
    v4 = Vertex(label="v4");
    v0 +>:Link:+> v1 +>:Link:+> v2 +>:Link:+> v3 +>:Link:+> v4;

    t0 = Triangle(label="t0");
