node FieldRelation {
    has table_name: str = "";
    has column_name: str = "";
    has fqn_segment: str = "";
    has explicit_present: bool = True;
    has oneof_variant: str = "";
    has bytes_hex: str = "";
    has is_repeated: bool = False;
}

walker ImportEmitter {
    has rows_emitted: int = 0;
    has failures: int = 0;
    has cycle_blocks: int = 0;
    has max_depth: int = 8;
    has closure_stack: list[str] = [];

    can start with Root entry {
        print("=== kat import hitrace: Native Hook source emit ===");
        visit [-->];
    }

    can bind_route with ProfilerEnvelope entry {
        self.closure_stack = [];
        if not here.decode_ok {
            self.failures += 1;
            print(f"[FAIL] occurrence {here.occurrence_id}: decode/emit abort on route {here.route}");
            disengage;
        }
        route = here.route;
        if route == "nativehook" or route == "hookdaemon" {
            target = "kat.native_hook.BatchNativeHookData";
            print(f"[BIND] {route} -> {target} (occ {here.occurrence_id}, clock_id={here.clock_id})");
            visit [->:Provenance:->] else { disengage; };
        } else if route == "nativehook_config" or route == "hookdaemon_config" {
            target = "kat.native_hook.NativeHookConfig";
            print(f"[BIND] {route} -> {target} (occ {here.occurrence_id}, clock_id={here.clock_id})");
            visit [->:Provenance:->] else { disengage; };
        } else {
            print(f"[SKIP] unregistered plugin route: {route}");
            disengage;
        }
    }

    can emit_root with BatchNativeHookData | NativeHookConfig entry {
        print(f"  root {here.describe()}");
        self.rows_emitted += 1;
        visit [->:ChildField:->] else { disengage; };
    }

    can emit_field with FieldRelation entry {
        seg = here.fqn_segment;
        if seg in self.closure_stack {
            self.cycle_blocks += 1;
            print(f"  [CYCLE] blocked re-entry at {seg}");
            disengage;
        }
        if len(self.closure_stack) >= self.max_depth {
            print(f"  [DEPTH] cap {self.max_depth} at {seg}");
            disengage;
        }
        self.closure_stack.append(seg);
        presence = "explicit" if here.explicit_present else "absent";
        oneof = here.oneof_variant if here.oneof_variant else "-";
        rep = "repeated" if here.is_repeated else "singular";
        bytes_note = f" bytes={here.bytes_hex}" if here.bytes_hex else "";
        print(f"  [{rep}] {here.table_name}.{here.column_name} presence={presence} oneof={oneof}{bytes_note}");
        self.rows_emitted += 1;
        visit [->:ChildField:->] else { disengage; };
        self.closure_stack.pop();
    }
}

walker ProvenanceTracer {
    can start with Root entry {
        print("--- provenance trace (payload root -> envelope) ---");
        visit [-->[?:BatchNativeHookData]];
