"""Workflow task center: transition-generated tasks, assignment policies, lifecycle actions, and reassignment."""

node WorkflowTransition {
    has name: str = "";
}

node WorkflowTask {
    has title: str = "";
    has status: str = "pending";
    has due_date: str = "";
    has assignee_name: str = "";
}

node AssignmentPolicy {
    has policy_name: str = "";
    has role: str = "";
}

node Assignee {
    has display_name: str = "";
}

edge Creates { }
edge GovernedBy { }
edge HeldBy { }

walker TaskCenter {
    has listed: int = 0;
    has pending_count: int = 0;
    has in_progress_count: int = 0;
    has complete_count: int = 0;

    can start with Root entry {
        print("=== Admin Task Center (/admin/workflow/tasks) ===");
        visit [-->];
        print(f"Listed {self.listed} tasks "
              f"(pending={self.pending_count}, "
              f"in_progress={self.in_progress_count}, "
              f"complete={self.complete_count})");
    }

    can from_transition with WorkflowTransition entry {
        print(f"Transition fired: {here.name}");
        visit [->:Creates:->];
        visit [-->];
    }

    can show_task with WorkflowTask entry {
        if here.status == "pending" {
            self.pending_count += 1;
        } else if here.status == "in_progress" {
            self.in_progress_count += 1;
        } else if here.status == "complete" {
            self.complete_count += 1;
        }
        print(f"  [{here.status}] {here.title} | due {here.due_date} | -> {here.assignee_name}");
        visit [->:GovernedBy:->];
        self.listed += 1;
        visit [-->];
    }

    can policy_badge with AssignmentPolicy entry {
        print(f"    policy badge: {here.policy_name} (role={here.role})");
    }
}

walker LifecycleAdvancer {
    has advanced: int = 0;

    can start with Root entry {
        print("--- Advancing task lifecycle (pending -> in_progress -> complete) ---");
        visit [-->];
        print(f"Advanced {self.advanced} task(s)");
    }

    can advance with WorkflowTask entry {
        next_status = here.status;
        if here.status == "pending" {
            next_status = "in_progress";
        } else if here.status == "in_progress" {
            next_status = "complete";
        }
        if next_status != here.status {
            print(f"  {here.title}: {here.status} -> {next_status}");
            here.status = next_status;
            self.advanced += 1;
        }
        visit [-->];
    }
}

walker DueDateEditor {
    has target_title: str = "";
    has new_due: str = "";

    can start with Root entry {
        print("--- Editing due date ---");
        visit [-->];
    }

    can edit with WorkflowTask entry {
        if here.title == self.target_title {
            old_due = here.due_date;
            here.due_date = self.new_due;
            print(f"  {here.title}: due {old_due} -> {here.due_date}");
        }
        visit [-->];
    }
}

walker TaskReassigner {
    has target_title: str = "";
    has new_holder: Assignee | None = None;

    can start with Root entry {
        print("--- Reassigning task ---");
        visit [-->];
    }

    can reassign with WorkflowTask entry {
        if here.title == self.target_title and self.new_holder is not None {
            here.assignee_name = self.new_holder.display_name;
            print(f"  {here.title} reassigned to {here.assignee_name}");
        }
        visit [-->];
    }
}

