"""Docker diagnostic golden scenarios: model compose stacks as service graphs and audit them with a regression walker."""

node Scenario {
    has name: str = "";
    has expected_category: str = "";
    has expected_severity: str = "";
}

node Service {
    has name: str = "";
    has healthy: bool = True;
    has restart_loop: bool = False;
    has blocking_error: str = "";
    has missing: bool = False;
    has stale_fatal_log: bool = False;
    has synthetic_secret: str = "";
    has log_redacted: bool = True;
}

edge Hosts { }
edge DependsOn { has required: bool = True; }

walker RegressionAuditor {
    has scenarios_passed: int = 0;
    has scenarios_failed: int = 0;
    has last_category: str = "none";
    has last_severity: str = "info";
    has visited_deps: list[str] = [];

    def reset_verdict() {
        self.last_category = "none";
        self.last_severity = "info";
    }

    def record(category: str, severity: str) {
        order = {"info": 0, "warn": 1, "error": 2, "critical": 3};
        cur_rank = order[self.last_severity] if self.last_severity in order else 0;
        new_rank = order[severity] if severity in order else 0;
        if new_rank > cur_rank {
            self.last_category = category;
            self.last_severity = severity;
        }
    }

    def diagnose_service(svc: Service) {
        if svc.restart_loop and svc.blocking_error != "" {
            print(f"[RUNTIME] {svc.name}: restart loop — {svc.blocking_error}");
            self.record("runtime", "critical");
        } elif svc.missing {
            print(f"[DEP] {svc.name}: missing or unreachable dependency");
            self.record("dependency", "error");
        } elif svc.synthetic_secret != "" and not svc.log_redacted {
            print(f"[SECRET] synthetic credential leaked in {svc.name} output");
            self.record("security", "critical");
        } elif svc.stale_fatal_log and svc.healthy {
            print(f"[LOG] {svc.name}: stale fatal log from prior start (service healthy)");
            self.record("log_noise", "warn");
        } elif not svc.healthy {
            print(f"[HEALTH] {svc.name}: service unhealthy");
            self.record("health", "error");
        } else {
            print(f"[OK] {svc.name}: nominal");
        }
    }

    can start with Root entry {
        print("=== Docker diagnostic golden regression suite ===");
        visit [-->];
        print(f"=== Summary: {self.scenarios_passed} passed, {self.scenarios_failed} failed ===");
    }

    can run_scenario with Scenario entry {
        print(f"\n--- Scenario: {here.name} ---");
        self.reset_verdict();
        self.visited_deps = [];
        visit [->:Hosts:->] else { disengage; };
        passed = (
            self.last_category == here.expected_category
            and self.last_severity == here.expected_severity
        );
        if passed {
            self.scenarios_passed += 1;
            label = "PASS";
        } else {
            self.scenarios_failed += 1;
            label = "FAIL";
        }
        print(
            f"[{label}] verdict {self.last_category}/{self.last_severity} "
            f"(expected {here.expected_category}/{here.expected_severity})"
        );
        visit [-->];
    }

    can inspect with Service entry {
        if here.name in self.visited_deps {
            print(f"[CYCLE] dependency loop detected at {here.name}");
            self.record("dependency", "error");
            disengage;
        }
        self.visited_deps.append(here.name);
        visit [->:DependsOn:->] else { };
        self.diagnose_service(here);
    }
}

with entry {
    bridge = Scenario(
        name="healthy_bridge_network",
        expected_category="none",
        expected_severity="info",
    );
    web = Service(name="web", healthy=True);
    db = Service(name="db", healthy=True);
    bridge +>:Hosts:+> web;
    bridge +>:Hosts:+> db;
    web +>:DependsOn(required=True):+> db;

    restart_sc = Scenario(
        name="restart_loop_bind_error",
        expected_category="runtime",
        expected_severity="critical",
    );
    api = Service(
        name="api",
        healthy=False,
        restart_loop=True,
        blocking_error="bind: address already in use",
    );
    restart_sc +>:Hosts:+> api;

    dep_miss = Scenario(
        name="missing_dependency",
        expected_category="dependency",
        expected_severity="error",
    );
    app = Service(name="app", healthy=False);
    cache = Service(name="cache", healthy=False, missing=True);
    dep_miss +>:Hosts:+> app;
    app +>:DependsOn(required=True):+> cache;

    stale = Scenario(
        name="stale_fatal_log",
        expected_category="log_noise",
        expected_severity="warn",
    );
    worker = Service(name="worker", healthy=True, stale_fatal_log=True);
    stale +>:Hosts:+> worker;

    root ++> bridge ++> restart_sc ++> dep_miss ++> stale;
    root spawn RegressionAuditor();
}

