              f"(pending={self.pending_count}, "
              f"in_progress={self.in_progress_count}, "
              f"complete={self.complete_count})");
    }

    can from_transition with WorkflowTransition entry {
        print(f"Transition fired: {here.name}");
        visit [->:Creates:->];
        visit [-->];
    }

