"""Issue #104 demo: write-path quota checks fan out across owned spaces and time out."""

node Account {
    has did: str = "";
    has label: str = "";
}

node Space {
    has space_id: str = "";
    has store_size: int = 0;
    has precomputed_limit: int = 0;
}

node BillingShard {
    has endpoint: str = "";
}

node NodeShard {
    has endpoint: str = "";
}

edge Owns { }
edge Bills { }
edge HostedOn { }

walker QuotaStorm {
    has call_budget: int = 8;
    has call_count: int = 0;
    has phase: int = 0;
    has timed_out: bool = False;
    has write_target: str = "";

    can start with Space entry {
        self.write_target = here.space_id;
        print(f"WRITE on {here.space_id} ({here.store_size} bytes) — quota cache miss");
        self.call_count += 1;
        visit [<--:Owns:<--];
    }

    can at_owner with Account entry {
        if self.phase == 0 {
            self.phase = 1;
            print(f"  node -> GET {here.label} billing /api/quota/{self.write_target}");
            self.call_count += 1;
            visit [->:Bills:->];
        } else {
            print(f"  billing fan-out across spaces owned by {here.did}");
            visit [->:Owns:->] else {
                if self.timed_out {
                    print(f"WRITE FAILED: upstream timeout after {self.call_count} mutual calls");
                } else {
                    print(f"WRITE OK under storm budget ({self.call_count} calls)");
                }
                disengage;
            };
        }
    }

