"""Deployable cluster gear: OoP consumers fail local hub resolve unless remote cluster is reachable."""

node Profile {
    has name: str = "";
    has provider: str = "";
}

node Backend {
    has kind: str = "";
    has dsn: str = "";
    has pool_key: str = "";
}

node ClientHub {
    has label: str = "";
}

node Gear {
    has gear_name: str = "";
    has out_of_process: bool = False;
    has is_cluster_gear: bool = False;
}

edge Hosts { }
edge Binds { has slot: str = ""; }
edge Serves { }
edge RemoteTo { }

walker ProfileResolver {
    has target_profile: str = "default";
    has resolved: int = 0;
    has failed: int = 0;
    has visited_keys: list[str] = [];
    has depth: int = 0;
    has max_depth: int = 12;

    def key_for(node_ref: object) -> str {
        return f"{node_ref}";
    }

    def already_seen(node_ref: object) -> bool {
        k = self.key_for(node_ref);
        for item in self.visited_keys {
            if item == k {
                return True;
            }
        }
        return False;
    }

    def mark_seen(node_ref: object) {
        k = self.key_for(node_ref);
        if not self.already_seen(node_ref) {
            self.visited_keys.append(k);
        }
    }

    can start with Root entry {
        print(f"Resolving cluster:{self.target_profile} for each gear");
        visit [-->];
    }

    can inspect with Gear entry {
        if self.already_seen(here) {
            print(f"[CYCLE] blocked re-entry at gear {here.gear_name}");
            disengage;
        }
        self.mark_seen(here);
        if self.depth >= self.max_depth {
            print(f"[DEPTH] cap hit at gear {here.gear_name}");
            disengage;
        }
        mode = "OoP" if here.out_of_process else "in-process";
        role = "cluster" if here.is_cluster_gear else "consumer";
        print(f"[{mode}/{role}] {here.gear_name} resolving cluster:{self.target_profile}");
        visit [->:Hosts:->];
    }

    can probe_hub with ClientHub entry {
        if self.already_seen(here) {
            disengage;
        }
        self.mark_seen(here);
        slot = f"cluster:{self.target_profile}";
        found = False;
        for bind_edge in [-->:Binds:--] {
            if bind_edge.slot == slot {
                visit [bind_edge->:Binds:->];
                found = True;
            }
        }
        if not found {
            print(f"  hub {here.label}: ProfileNotBound for {slot}");
            visit [-->];
        }
    }

    can on_bind with Backend entry {
        print(f"  local hit: {here.kind} pool={here.pool_key} dsn={here.dsn}");
        self.resolved += 1;
        disengage;
    }

    can fallback with Gear entry {
        if here.out_of_process and not here.is_cluster_gear {
            print(f"  {here.gear_name} falling back to remote cluster gear");
            visit [->:RemoteTo:->] else { self.failed += 1; disengage; };
        } else {
            self.failed += 1;
            disengage;
        }
    }

    can remote_serve with Gear entry {
        if not here.is_cluster_gear {
            disengage;
        }
        if self.already_seen(here) {
            disengage;
        }
        self.mark_seen(here);
        print(f"  remote cluster gear {here.gear_name} serving profile");
        visit [->:Serves:->] else { self.failed += 1; disengage; };
    }

    can remote_backend with Backend entry {
        print(f"  remote hit: {here.kind} pool={here.pool_key} dsn={here.dsn}");
        self.resolved += 1;
        disengage;
    }
}

walker PoolDeduper {
    has seen_pools: list[str] = [];
    has unique_pools: int = 0;
    has shared_hits: int = 0;

    can start with Root entry {
        print("BackendInstanceCache: dedupe pools by (provider, dsn)");
        visit [-->[?:Gear]];
    }

    can scan_cluster with Gear entry {
        if not here.is_cluster_gear {
            disengage;
        }
        visit [->:Serves:->];
    }

    can tally with Backend entry {
        tag = here.pool_key;
        known = False;
        for item in self.seen_pools {
            if item == tag {
                known = True;
            }
        }
        if known {
            self.shared_hits += 1;
            print(f"  reuse pool {tag} ({here.kind})");
        } else {
            self.seen_pools.append(tag);
            self.unique_pools += 1;
            print(f"  open pool {tag} ({here.kind}) dsn={here.dsn}");
        }
    }
}

