    prof_embedded = Profile(name="embedded", provider="postgres");
    prof_k8s = Profile(name="k8s-native", provider="postgres");

    cache_a = Backend(kind="ClusterCacheBackend", dsn="postgres://coord/db", pool_key="postgres://coord/db");
