"""HEC-DuckDB connector demo: attach RAS/HMS schemas, walk prerequisites, cascade fingerprint refresh."""

node HecProject {
    has name: str = "";
    has kind: str = "ras";
    has fingerprint: str = "";
    has stale: bool = False;
}

node Schema {
    has name: str = "";
}

node Relation {
    has table_name: str = "";
    has virtual: bool = True;
    has materialized: bool = False;
    has stale: bool = False;
}

node Prereq {
    has title: str = "";
    has issue: int = 0;
    has ready: bool = False;
}

edge AttachedTo {
}

edge Exposes {
}

edge Unlocks {
}

walker AttachAuditor {
    has schema_count: int = 0;
    has relation_count: int = 0;

    can start with Root entry {
        print("=== attach RAS/HMS model sources ===");
        visit [->:AttachedTo:->] else { disengage; };
    }

    can on_project with HecProject entry {
        print(f"attach_{here.kind}('{here.name}', schema='{here.kind}') fp={here.fingerprint}");
        visit [->:AttachedTo:->] else { disengage; };
    }

    can on_schema with Schema entry {
        self.schema_count += 1;
        print(f"  bound schema '{here.name}'");
        visit [->:Exposes:->] else { disengage; };
    }

    can on_relation with Relation entry {
        self.relation_count += 1;
        storage = "virtual" if here.virtual else "materialized";
        status = "stale" if here.stale else "fresh";
        print(f"    {here.table_name} ({storage}, {status})");
        visit [-->];
    }
}

walker PrereqOrder {
    has seen: list[str] = [];
    has order: list[str] = [];
    has blocked: bool = False;

    can start with Root entry {
        print("=== prerequisite ordering (#306 -> #307 -> #308) ===");
        visit [->:Unlocks:->] else { disengage; };
    }

    can step with Prereq entry {
        token = str(here.issue);
        if token in self.seen {
            print(f"CYCLE detected at issue #{here.issue}");
            disengage;
        }
        self.seen.append(token);
        state = "ready" if here.ready else "BLOCKED";
        print(f"#{here.issue} {here.title}: {state}");
        if not here.ready {
            self.blocked = True;
            disengage;
        }
        self.order.append(here.title);
        visit [->:Unlocks:->] else { disengage; };
    }
}

walker RefreshCascade {
    has invalidated: int = 0;

    can start with Root entry {
        print("=== fingerprint refresh cascade ===");
        visit [->:AttachedTo:->] else { disengage; };
    }

    can on_project with HecProject entry {
        if here.stale {
            print(f"refresh '{here.name}': fingerprint changed ({here.fingerprint})");
        }
        visit [->:AttachedTo:->] else { disengage; };
    }

    can on_schema with Schema entry {
        visit [->:Exposes:->] else { disengage; };
    }

    can invalidate with Relation entry {
        if here.materialized and not here.stale {
            here.stale = True;
            self.invalidated += 1;
            print(f"  invalidated materialized table '{here.table_name}'");
        }
        visit [-->];
    }
}

with entry {
    ras = HecProject(name="muncie", kind="ras", fingerprint="fp-ras-v2", stale=True);
    hms = HecProject(name="watershed", kind="hms", fingerprint="fp-hms-v1");
    ras_schema = Schema(name="ras");
    hms_schema = Schema(name="hms");
    mesh_results = Relation(table_name="mesh_results", virtual=True);
    mesh_summary = Relation(table_name="mesh_summary", virtual=False, materialized=True);
    hms_series = Relation(table_name="element_timeseries", virtual=True);

    cap306 = Prereq(title="HDF slicing and bounded reductions", issue=306, ready=True);
    cap307 = Prereq(title="Chunked readers and geometry-free extraction", issue=307, ready=True);
    cap308 = Prereq(title="Lazy queryable result return type", issue=308, ready=True);

    root +>:AttachedTo:+> ras;
    ras +>:AttachedTo:+> ras_schema;
    ras_schema +>:Exposes:+> mesh_results;
    ras_schema +>:Exposes:+> mesh_summary;

    root +>:AttachedTo:+> hms;
    hms +>:AttachedTo:+> hms_schema;
    hms_schema +>:Exposes:+> hms_series;

    root +>:Unlocks:+> cap306 +>:Unlocks:+> cap307 +>:Unlocks:+> cap308;

    auditor = AttachAuditor();
    root spawn auditor;
    prereq_walk = PrereqOrder();
    root spawn prereq_walk;
    refresh = RefreshCascade();
    root spawn refresh;

    print(f"audit: {auditor.schema_count} schemas, "
          f"{auditor.relation_count} relations exposed");
    print(f"prereqs blocked: {prereq_walk.blocked}");
    print(f"refresh invalidated {refresh.invalidated} materialized relation(s)");
}

