        tag = here.pool_key;
        known = False;
        for item in self.seen_pools {
            if item == tag {
                known = True;
            }
        }
        if known {
            self.shared_hits += 1;
            print(f"  reuse pool {tag} ({here.kind})");
        } else {
            self.seen_pools.append(tag);
            self.unique_pools += 1;
            print(f"  open pool {tag} ({here.kind}) dsn={here.dsn}");
        }
    }
}

