"""Contract amendment resolution: graph-grounded retrieval honors amendment precedence to find the operative termination clause, not superseded language."""

node Clause {
    has clause_id: str = "";
    has topic: str = "";
    has days: int = 0;
    has operative: bool = True;
}

node ContractDoc {
    has title: str = "";
    has doc_type: str = "";
}

edge Contains { }

edge Supersedes {
    has effective_date: str = "";
}

walker VectorOnlyRetriever {
    has query_topic: str = "";
    has selected_days: int = 0;
    has locked: bool = False;

    can start with Root entry {
        visit [-->];
    }

    can scan with ContractDoc entry {
        visit [->:Contains:->];
        visit [-->];
    }

    can pick_first with Clause entry {
        if not self.locked and here.topic == self.query_topic {
            self.selected_days = here.days;
            self.locked = True;
            status = "operative" if here.operative else "superseded";
            print(
                f"[VECTOR] Picked clause {here.clause_id}: "
                f"{here.days}-day termination ({status}, no precedence check)"
            );
            disengage;
        }
        visit [-->];
    }
}

walker GraphGroundedRetriever {
    has query_topic: str = "";
    has operative_days: int = 0;
    has operative_clause_id: str = "";
    has resolved: bool = False;
    has visited_docs: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can review with ContractDoc entry {
        if here.title in self.visited_docs {
            visit [-->];
        } else {
            self.visited_docs.append(here.title);
            print(f"[GRAPH] Reviewing {here.doc_type} document: {here.title}");
            visit [->:Contains:->];
            if here.doc_type == "amendment" {
                visit [->:Supersedes:->];
            }
            visit [-->];
        }
    }

    can assess with Clause entry {
        if here.topic == self.query_topic {
            label = "OPERATIVE" if here.operative else "SUPERSEDED";
            print(
                f"[GRAPH] Clause {here.clause_id}: "
                f"{here.days}-day termination ({label})"
            );
            if here.operative {
                self.operative_days = here.days;
                self.operative_clause_id = here.clause_id;
                self.resolved = True;
            }
        }
        visit [-->];
    }
}

with entry {
    base = ContractDoc(title="Master Services Agreement", doc_type="base");
    amend = ContractDoc(title="Amendment No. 1", doc_type="amendment");
    old_term = Clause(
        clause_id="4.2",
        topic="termination",
        days=60,
        operative=False
    );
    new_term = Clause(
        clause_id="4.2",
        topic="termination",
        days=90,
        operative=True
    );

    root ++> base ++> amend;
    base +>:Contains:+> old_term;
    amend +>:Supersedes(effective_date="2023-01-15"):+> old_term;
    amend +>:Contains:+> new_term;

    print("=== Vector-only retrieval (first semantic match) ===");
    root spawn VectorOnlyRetriever(query_topic="termination");

    print("=== Graph-grounded retrieval (amendment precedence) ===");
    root spawn GraphGroundedRetriever(query_topic="termination");

    print(
        f"Outcome: vector-only answers 60 days; "
        f"controlling operative term is 90 days."
    );
}

"""Deployable cluster gear: OoP consumers fail local hub resolve unless remote cluster is reachable."""

node Gear {
    has gear_name: str = "";
    has out_of_process: bool = False;
    has is_cluster_gear: bool = False;
}

node ClientHub {
    has label: str = "";
}

node Backend {
    has kind: str = "";
    has dsn: str = "";
    has pool_key: str = "";
    has profile: str = "";
}

edge Hosts { }
edge Binds { has slot: str = ""; }
edge Serves { has active: bool = True; }
edge RemoteTo { }
edge Fallback { }

walker ProfileResolver {
    has target_profile: str = "k8s-native";
    has resolved: int = 0;
    has failed: int = 0;
    has visited_keys: list[str] = [];
    has max_depth: int = 12;
    has depth: int = 0;

    def key_for(node_ref: object) -> str {
        return f"{node_ref}";
    }

    def already_seen(node_ref: object) -> bool {
        k = self.key_for(node_ref);
        for item in self.visited_keys {
            if item == k {
                return True;
            }
        }
        return False;
    }

    def mark_seen(node_ref: object) {
        k = self.key_for(node_ref);
        if not self.already_seen(node_ref) {
            self.visited_keys.append(k);
        }
    }

    can start with Root entry {
        print(f"Resolving cluster:{self.target_profile} for each gear");
        visit [-->];
    }

    can inspect with Gear entry {
        if self.already_seen(here) {
            print(f"[CYCLE] blocked re-entry at gear {here.gear_name}");
            disengage;
        }
        self.mark_seen(here);
        if self.depth >= self.max_depth {
            print(f"[DEPTH] cap hit at gear {here.gear_name}");
            disengage;
        }
        mode = "OoP" if here.out_of_process else "in-process";
        role = "cluster" if here.is_cluster_gear else "consumer";
        print(f"[{mode}/{role}] {here.gear_name} resolving cluster:{self.target_profile}");
        if here.is_cluster_gear {
            print(f"  remote cluster gear {here.gear_name} serving profile");
            visit [->:Serves:->] else { self.failed += 1; disengage; };
        } else {
            visit [->:Hosts:->] else {
                if here.out_of_process {
                    print(f"  {here.gear_name} no local hub; using remote cluster gear");
                    visit [->:RemoteTo:->] else { self.failed += 1; disengage; };
                } else {
                    self.failed += 1;
                    disengage;
                }
            };
        }
    }

    can probe_hub with ClientHub entry {
        if self.already_seen(here) {
            disengage;
        }
        self.mark_seen(here);
        visit [->:Binds:->] else {
            print(f"  hub {here.label}: ProfileNotBound for cluster:{self.target_profile}");
            visit [->:Fallback:->] else { self.failed += 1; disengage; };
        };
    }

    can on_backend with Backend entry {
        if here.profile != self.target_profile {
            disengage;
        }
        lane = "remote" if self.depth > 0 else "local";
        print(f"  {lane} hit: {here.kind} pool={here.pool_key} dsn={here.dsn}");
        self.resolved += 1;
        disengage;
    }

    can remote_cluster with Gear entry {
        if not here.is_cluster_gear {
            disengage;
        }
        if self.already_seen(here) {
            disengage;
        }
        self.mark_seen(here);
        self.depth += 1;
        print(f"  reached remote cluster gear {here.gear_name}");
        visit [->:Serves:->] else { self.failed += 1; disengage; };
    }
}

walker PoolDeduper {
    has seen_pools: list[str] = [];
    has unique_pools: int = 0;
    has shared_hits: int = 0;

    can start with Root entry {
