    all_devices = SecurityGroup(name="All-Devices", entity_id="g-all");
    it_nested = SecurityGroup(name="IT-Nested", entity_id="g-it");
    empty_grp = SecurityGroup(name="Empty-Group", entity_id="g-empty");
    cycle_a = SecurityGroup(name="Cycle-A", entity_id="g-cyc-a");
    cycle_b = SecurityGroup(name="Cycle-B", entity_id="g-cyc-b");

