    );
    site_imported_foo = CallSiteContribution(
        site_id="cs-imported-foo",
        dispatch_kind="imported_unqualified",
        selector_name="foo",
        callee_state="exact_entity",
        anchor_line=70
    );

    dyn_boundary_cb = DynamicBoundary(
        boundary_id="dyn-cb-invoke",
