    );
    dyn_boundary_sel = DynamicBoundary(
        boundary_id="dyn-symbolic-selector",
        limitation="symbolic selector — no fabricated callee name"
    );

    root ++> main_pkg ++> user_pkg ++> order_pkg ++> utils_pkg;
    main_pkg ++> process;
    user_pkg ++> user_save;
    order_pkg ++> order_save;
    utils_pkg ++> format_string;
    main_pkg ++> local_foo;

    process +>:Encloses:+> site_user_save;
    process +>:Encloses:+> site_order_save;
    process +>:Encloses:+> site_fq_call;
    process +>:Encloses:+> site_direct_foo;
    process +>:Encloses:+> site_coderef;
    process +>:Encloses:+> site_method_foo;
    process +>:Encloses:+> site_dynamic_sel;
