    site_user_save +>:ReceiverCandidate(rank=1):+> user_save;
    site_order_save +>:ReceiverCandidate(rank=1):+> order_save;
    site_fq_call +>:ExactTarget(confidence=1.0):+> format_string;
    site_direct_foo +>:ExactTarget:+> local_foo;
