"""Linux-hello Ubuntu archive entry: audit Rust crate dependencies and assess packaging blockers."""

node Project {
    has name: str = "";
    has source_format: str = "3.0 (native)";
}

node Crate {
    has name: str = "";
    has version: str = "";
    has in_archive: bool = False;
    has ecosystem: str = "";
}

node Blocker {
    has title: str = "";
    has effort_rank: int = 0;
    has cleared: bool = False;
}

edge DependsOn { }
edge Blocks { }

walker DependencyAuditor {
    has seen: list[str] = [];
    has total: int = 0;
    has packaged: int = 0;
    has missing: int = 0;

    can start with Root entry {
        print("=== Cargo.lock vs Debian archive audit ===");
        visit [-->];
    }

    can begin with Project entry {
        print(f"Project: {here.name} (debian/source/format: {here.source_format})");
        visit [->:DependsOn:->] else { disengage; };
    }

    can audit with Crate entry {
        if here.name in self.seen {
            disengage;
        }
        self.seen.append(here.name);
        self.total += 1;
        status_tag = "OK" if here.in_archive else "GAP";
        if here.in_archive {
            self.packaged += 1;
        } else {
            self.missing += 1;
        }
        eco_label = here.ecosystem if here.ecosystem else "common";
        print(f"  [{status_tag}] librust-{here.name}-{here.version}-dev ({eco_label})");
        visit [->:DependsOn:->] else { disengage; };
    }
}

walker BlockerAssessor {
    has open_count: int = 0;

    can start with Root entry {
        print("\n=== Archive entry blockers ===");
        visit [-->];
    }

    can review with Project entry {
        visit [<--:Blocks:--] else { disengage; };
    }

    can assess with Blocker entry {
        state_label = "CLEAR" if here.cleared else "OPEN";
        if not here.cleared {
            self.open_count += 1;
        }
        print(f"  [{state_label}] #{here.effort_rank}: {here.title}");
    }
}

with entry {
    hello = Project(name="linux-hello", source_format="3.0 (native)");

    serde_crate = Crate(name="serde", version="1.0", in_archive=True);
    zbus_crate = Crate(name="zbus", version="5.16", in_archive=True);
    tract_core = Crate(
        name="tract-core", version="0.21", in_archive=False, ecosystem="tract"
    );
    tract_onnx = Crate(
        name="tract-onnx", version="0.21", in_archive=False, ecosystem="tract"
    );
    ort_crate = Crate(name="ort", version="2.0", in_archive=False, ecosystem="ort");
    v4l_crate = Crate(name="v4l", version="0.14", in_archive=False, ecosystem="v4l");

    root ++> hello;
    hello +>:DependsOn:+> serde_crate;
    hello +>:DependsOn:+> zbus_crate;
    hello +>:DependsOn:+> tract_onnx;
    hello +>:DependsOn:+> ort_crate;
    hello +>:DependsOn:+> v4l_crate;
    tract_onnx +>:DependsOn:+> tract_core;

    vendoring = Blocker(
        title="~30-45 crates lack librust-*-dev (tract, ort, v4l families)",
        effort_rank=1,
        cleared=False,
    );
    source_fmt = Blocker(
        title="Switch debian/source/format to 3.0 (quilt)",
        effort_rank=2,
        cleared=False,
    );
    onnx_lic = Blocker(
        title="ONNX model license must be DFSG-free for universe",
        effort_rank=3,
        cleared=False,
    );
    sponsor = Blocker(
        title="No Debian/Ubuntu sponsor identified",
        effort_rank=4,
        cleared=False,
    );

    vendoring +>:Blocks:+> hello;
    source_fmt +>:Blocks:+> hello;
    onnx_lic +>:Blocks:+> hello;
    sponsor +>:Blocks:+> hello;

    auditor = DependencyAuditor();
    root spawn auditor;
    pct_num = auditor.packaged * 100;
    pct_den = auditor.total if auditor.total > 0 else 1;
    pct = pct_num // pct_den;
    print(f"\nSummary: {auditor.packaged}/{auditor.total} in archive (~{pct}%)");
    print(f"Gaps: {auditor.missing} crates — critical: tract-*, ort, v4l");

    assessor = BlockerAssessor();
    root spawn assessor;
    ready_label = "READY" if assessor.open_count == 0 else "NOT READY";
    print(f"\nArchive status: {ready_label} ({assessor.open_count} open blockers)");
}

"""Semantic workspace navigation: change-impact traversal over symbols, tests, and config surfaces."""

node SourceFile {
    has path: str = "";
    has revision: str = "";
}

node Symbol {
    has name: str = "";
    has kind: str = "";
}

node ImpactSurface {
    has name: str = "";
    has surface_kind: str = "";
}

node TestCase(ImpactSurface) {
    has surface_kind: str = "test";
}

node ConfigSurface(ImpactSurface) {
    has surface_kind: str = "config";
}

edge DeclaresIn { }
edge Uses { }
edge Covers { }
edge DependsOn { }

walker ImpactAnalyzer {
    has changed_path: str = "";
    has hop_limit: int = 3;
    has hops: int = 0;
    has seen: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can on_changed with SourceFile entry {
        if here.path != self.changed_path {
            visit [-->];
        } else {
            print(f"changed file: {here.path} (rev {here.revision})");
            visit [->:DeclaresIn:->] else { disengage; };
        }
    }

    can root_symbol with Symbol entry {
        if self.hops != 0 {
            disengage;
        }
        key = f"{here.name}::{here.kind}";
        if key in self.seen {
            disengage;
        }
        self.seen.append(key);
        print(f"  impact root: {here.name} ({here.kind})");
        self.hops = 1;
        visit [<--:Uses:--];
        visit [<--:Covers:--];
        visit [<--:DependsOn:--];
    }

    can downstream with Symbol entry {
        if self.hops == 0 {
            disengage;
        }
        key = f"{here.name}::{here.kind}";
        if key in self.seen {
            disengage;
        }
        self.seen.append(key);
        depth_label = self.hops;
        print(f"  consumer[{depth_label}]: {here.name} ({here.kind})");
        if self.hops >= self.hop_limit {
            disengage;
        }
        self.hops += 1;
        visit [<--:Uses:--];
        visit [<--:Covers:--];
        visit [<--:DependsOn:--];
    }

    can on_surface with TestCase | ConfigSurface entry {
        print(f"  {here.surface_kind}: {here.name}");
    }
}

walker ReferenceFinder {
    has target: str = "";
    has phase: str = "seek";

    can start with Root entry {
        visit [-->];
    }

    can query with Symbol entry {
        if self.phase == "seek" {
            if here.name != self.target {
                visit [-->];
            } else {
                print(f"definition: {here.name} ({here.kind})");
                self.phase = "refs";
                visit [<--:Uses:--] else { disengage; };
            }
        } else {
            if here.name != self.target {
                print(f"  referenced by: {here.name} ({here.kind})");
            }
            visit [-->];
        }
    }
}

with entry {
    runtime_file = SourceFile(path="lib/runtime.ts", revision="a1b2c3");
    runtime = Symbol(name="RuntimeContract", kind="interface");
    runtime_file +>:DeclaresIn:+> runtime;

