}

"""IntuneGraph traversal demo: policy target resolution, blast-radius audit, and orphan detection."""

node ManagedEntity {
    has name: str = "";
    has entity_id: str = "";
}

node Device(ManagedEntity) { }

node User(ManagedEntity) { }

node SecurityGroup(ManagedEntity) { }

node Policy {
    has name: str = "";
    has policy_id: str = "";
    has policy_type: str = "compliance";
}

edge MemberOf { }

edge NestedIn { }

edge AssignsTo { }

walker TargetResolver {
    has visited_groups: list[str] = [];
    has target_names: list[str] = [];
    has resolving: bool = False;

    can start with Root entry {
        visit [-->];
    }

    can resolve with Policy entry {
        print(f"[Get-IntuneTarget] {here.name} ({here.policy_type})");
        self.resolving = True;
        self.visited_groups = [];
        self.target_names = [];
        visit [->:AssignsTo:->] else {
            print("  => no group assignments");
            self.resolving = False;
            visit [-->];
            disengage;
        };
        summary = "resolved" if self.target_names else "empty";
        print(f"  => {len(self.target_names)} target(s) [{summary}]: {self.target_names}");
        self.resolving = False;
        visit [-->];
    }

    can expand with SecurityGroup entry {
        if not self.resolving {
            visit [-->];
            disengage;
        }
        if here.entity_id in self.visited_groups {
            print(f"  [cycle-guard] skip group {here.name}");
            disengage;
        }
        self.visited_groups.append(here.entity_id);
        visit [<--:MemberOf:--];
        visit [<--:NestedIn:--];
    }

    can collect with Device | User entry {
        if self.resolving {
            if here.name not in self.target_names {
                self.target_names.append(here.name);
                print(f"    + target {here.name}");
            }
            disengage;
        } else {
            visit [-->];
        }
    }

    can pass_group with SecurityGroup entry {
        if not self.resolving {
            visit [-->];
        }
    }
}

walker BlastRadiusAuditor {
    has seed_name: str = "IT-Nested";
    has initialized: bool = False;
    has visited_groups: list[str] = [];
    has policy_names: list[str] = [];
    has member_names: list[str] = [];
    has ascending: bool = False;

    can start with Root entry {
        visit [-->];
    }

    can blast with SecurityGroup entry {
        if here.name != self.seed_name and not self.initialized {
            visit [-->];
        } else {
            if here.name == self.seed_name and not self.initialized {
                print(f"[Get-IntuneBlastRadius] simulating change in {here.name}");
                self.initialized = True;
                self.visited_groups = [];
                self.policy_names = [];
                self.member_names = [];
                self.ascending = False;
            }
            if here.entity_id in self.visited_groups {
                if here.name == self.seed_name {
                    print(f"  => policies: {self.policy_names}");
                    print(f"  => members: {self.member_names}");
                    disengage;
                }
                disengage;
            }
            self.visited_groups.append(here.entity_id);
            visit [<--:AssignsTo:--];
            visit [<--:MemberOf:--];
            visit [<--:NestedIn:--];
            if not self.ascending {
                self.ascending = True;
                visit [->:NestedIn:->];
                self.ascending = False;
            }
            if here.name == self.seed_name {
                print(f"  => policies: {self.policy_names}");
                print(f"  => members: {self.member_names}");
                disengage;
            }
        }
    }

    can note_policy with Policy entry {
        if here.name not in self.policy_names {
            self.policy_names.append(here.name);
        }
        visit [-->];
    }

    can note_member with Device | User entry {
        if here.name not in self.member_names {
            self.member_names.append(here.name);
        }
        visit [-->];
    }
}

walker OrphanFinder {
    has orphans: list[str] = [];

    can start with Root entry {
        self.orphans = [];
        visit [-->];
        print(f"[Find-IntuneOrphan] {len(self.orphans)} orphan(s): {self.orphans}");
    }

    can check_member with Device | User entry {
        visit [->:MemberOf:->] else {
            label = f"{here.name} (no group membership)";
            if label not in self.orphans {
                self.orphans.append(label);
            }
        };
        visit [-->];
    }

    can check_policy with Policy entry {
        visit [->:AssignsTo:->] else {
            label = f"{here.name} (no assignment target)";
            if label not in self.orphans {
                self.orphans.append(label);
            }
        };
        visit [-->];
    }

    can check_group with SecurityGroup entry {
        visit [<--:MemberOf:--] else {
            visit [<--:AssignsTo:--] else {
                visit [<--:NestedIn:--] else {
                    visit [->:NestedIn:->] else {
                        label = f"{here.name} (empty group)";
                        if label not in self.orphans {
                            self.orphans.append(label);
                        }
                    };
                };
            };
        };
        visit [-->];
    }
}

