"""Call-site contributions: canonical CallSiteContribution facts with typed
caller, callee, and receiver identity — no LSP rescanning or label-merged edges."""

node PackageScope {
    has name: str = "";
}

node CallableEntity {
    has name: str = "";
    has package: str = "";
    has entity_id: str = "";
}

node CallSiteContribution {
    has site_id: str = "";
    has dispatch_kind: str = "";
    has selector_name: str = "";
    has callee_state: str = "";
    has anchor_line: int = 0;
}

node DynamicBoundary {
    has boundary_id: str = "";
    has limitation: str = "";
}

edge Encloses { }
edge ExactTarget { has confidence: float = 1.0; }
edge ReceiverCandidate { has rank: int = 0; }
edge DependsOn { has reason: str = ""; }
edge DynamicDispatch { }

walker ContributionAuditor {
    has phase: str = "";
    has findings: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can audit_package with PackageScope entry {
        self.findings.append(f"scope {here.name}");
        visit [-->];
    }

    can audit_caller with CallableEntity entry {
        if self.phase != "" {
            disengage;
        }
        self.findings.append(
            f"caller {here.package}::{here.name} [{here.entity_id}]"
        );
        visit [->:Encloses:->];
        visit [-->] else { disengage; }
    }

    can inspect_site with CallSiteContribution entry {
        self.findings.append(
            f"  {here.site_id} line={here.anchor_line} "
            f"{here.dispatch_kind} sel={here.selector_name} "
            f"state={here.callee_state}"
        );
        self.phase = "exact";
        visit [->:ExactTarget:->];
        self.phase = "candidate";
        visit [->:ReceiverCandidate:->];
        self.phase = "dynamic";
        visit [->:DynamicDispatch:->];
        self.phase = "";
        visit [-->] else { disengage; }
    }

    can annotate_exact with CallableEntity entry {
        if self.phase != "exact" {
            disengage;
        }
        self.findings.append(
            f"    exact -> {here.package}::{here.name}"
        );
        disengage;
    }

    can annotate_candidate with CallableEntity entry {
        if self.phase != "candidate" {
            disengage;
        }
        self.findings.append(
            f"    candidate -> {here.package}::{here.name}"
        );
        disengage;
    }

    can annotate_dynamic with DynamicBoundary entry {
        if self.phase != "dynamic" {
            disengage;
        }
        self.findings.append(
            f"    dynamic boundary {here.boundary_id}: "
            f"{here.limitation}"
        );
        disengage;
    }
}

walker InvalidationWalker {
    has changed_id: str = "";
    has invalidated: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can traverse with PackageScope entry {
        visit [-->];
    }

    can from_entity with CallableEntity entry {
        if here.entity_id == self.changed_id {
            visit [<--:DependsOn:--];
        } else {
            visit [-->];
        }
        visit [-->] else { disengage; }
    }

    can collect with CallSiteContribution entry {
        self.invalidated.append(here.site_id);
        disengage;
    }
}

