"""Semantic workspace navigation: change-impact traversal over symbols, tests, and config surfaces."""

node SourceFile {
    has path: str = "";
    has revision: str = "";
}

node Symbol {
    has name: str = "";
    has kind: str = "";
}

node ImpactSurface {
    has name: str = "";
    has surface_kind: str = "";
}

node TestCase(ImpactSurface) {
    has surface_kind: str = "test";
}

node ConfigSurface(ImpactSurface) {
    has surface_kind: str = "config";
}

edge DeclaresIn { }
edge Uses { }
edge Covers { }
edge DependsOn { }

walker ImpactAnalyzer {
    has changed_path: str = "";
    has hop_limit: int = 3;
    has hops: int = 0;
    has seen: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can on_changed with SourceFile entry {
        if here.path != self.changed_path {
            visit [-->];
        } else {
            print(f"changed file: {here.path} (rev {here.revision})");
            visit [->:DeclaresIn:->] else { disengage; };
        }
    }

    can root_symbol with Symbol entry {
        if self.hops != 0 {
            disengage;
        }
        key = f"{here.name}::{here.kind}";
        if key in self.seen {
            disengage;
        }
        self.seen.append(key);
        print(f"  impact root: {here.name} ({here.kind})");
        self.hops = 1;
        visit [<--:Uses:-->];
        visit [<--:Covers:-->];
        visit [<--:DependsOn:-->];
    }

    can downstream with Symbol entry {
        if self.hops == 0 {
            disengage;
        }
        key = f"{here.name}::{here.kind}";
        if key in self.seen {
            disengage;
        }
        self.seen.append(key);
        depth_label = self.hops;
        print(f"  consumer[{depth_label}]: {here.name} ({here.kind})");
        if self.hops >= self.hop_limit {
            disengage;
        }
        self.hops += 1;
        visit [<--:Uses:-->];
        visit [<--:Covers:-->];
        visit [<--:DependsOn:-->];
    }

    can on_surface with TestCase | ConfigSurface entry {
        print(f"  {here.surface_kind}: {here.name}");
    }
}

walker ReferenceFinder {
    has target: str = "";
    has phase: str = "seek";

    can start with Root entry {
        visit [-->];
    }

    can query with Symbol entry {
        if self.phase == "seek" {
            if here.name != self.target {
                visit [-->];
            } else {
                print(f"definition: {here.name} ({here.kind})");
                self.phase = "refs";
                visit [<--:Uses:-->] else { disengage; };
            }
        } else {
            if here.name != self.target {
                print(f"  referenced by: {here.name} ({here.kind})");
            }
            visit [-->];
        }
    }
}

