"""Scratch telemetry blind spot: engine per-frame scratches unreported while renderer rows size from draw_commands."""

node ScratchBase {
    has name: str = "";
    has capacity: int = 0;
    has used: int = 0;
}

node EngineScratch(ScratchBase) {
    has group: str = "engine";
}

node RendererScratch(ScratchBase) {
    has group: str = "renderer";
    has in_telemetry: bool = True;
}

node TelemetryReport {
    has scope_label: str = "renderer";
    has row_count: int = 0;
}

edge SizesFrom { }

edge ReportsTo { }

walker ScratchCoverageAuditor {
    has phase: str = "";
    has covered_rows: int = 0;
    has blind_rows: int = 0;
    has draw_commands_used: int = 0;
    has draw_commands_cap: int = 0;
    has sized_renderer_count: int = 0;

    can start with Root entry {
        print("=== scratch telemetry audit (issue #3694) ===");
        visit [-->];
        print(
            f"summary: covered={self.covered_rows} blind={self.blind_rows} "
            f"draw_commands={self.draw_commands_used}/{self.draw_commands_cap} "
            f"renderer_sized_from_draw={self.sized_renderer_count}"
        );
    }

    can open_report with TelemetryReport entry {
        print(f"ctx.scratch scope: {here.scope_label} rows={here.row_count}");
        self.phase = "reporting";
        visit [->:ReportsTo:->] else {
            disengage;
        };
    }

    can tally_renderer with RendererScratch entry {
        if self.phase != "reporting" {
            disengage;
        }
        wasted = here.capacity - here.used;
        self.covered_rows += 1;
        print(
            f"  [reported] renderer:{here.name} "
            f"{here.used}/{here.capacity} wasted={wasted}"
        );
        disengage;
    }

    can audit_engine with EngineScratch entry {
        wasted = here.capacity - here.used;
        self.blind_rows += 1;
        print(
            f"  [BLIND] engine:{here.name} "
            f"{here.used}/{here.capacity} wasted={wasted}"
        );
        if here.name == "draw_commands" {
            self.draw_commands_used = here.used;
            self.draw_commands_cap = here.capacity;
            self.phase = "sizing";
            visit [->:SizesFrom:->] else {
                disengage;
            };
        } else {
            visit [-->] else {
                disengage;
            };
        }
    }

    can count_sized with RendererScratch entry {
        if self.phase != "sizing" {
            disengage;
        }
        self.sized_renderer_count += 1;
        print(
            f"    -> renderer:{here.name} reserve(draw_commands.len()="
            f"{self.draw_commands_used}) driver unreported"
        );
        visit [-->] else {
            disengage;
        };
    }
}

