walker AllocationSteward {
    has round: int = 1;
    has total_capacity: int = 0;
    has weight_sum: int = 125;
    has override_authority: bool = False;

    can start with Root entry {
        if self.override_authority {
            self.weight_sum = 16;
            print(f"=== Round {self.round}: emergency override allocation ===");
        } else {
            self.weight_sum = 125;
            print(f"=== Round {self.round}: consent-path allocation ===");
        }
        visit [-->[?:Mirror]] else {
            visit [-->[?:Habitat]] else { disengage; };
        };
    }

    can survey with Mirror entry {
        if here.failed and not here.in_repair {
            effective = 0;
            print(f"  [FAIL] {here.name} offline (-{here.capacity} capacity)");
        } elif here.in_repair {
            effective = here.capacity // 2;
            print(f"  [REPAIR] {here.name} partial recovery ({effective})");
        } else {
            effective = here.capacity;
            print(f"  [OK] {here.name} contributing {effective}");
        }
        self.total_capacity += effective;
        visit [-->[?:Mirror]] else {
            print(f"  Network capacity: {self.total_capacity}");
            visit [-->[?:Habitat]] else { disengage; };
        };
    }

    can allocate with Habitat entry {
        if self.override_authority {
            weight = here.contract_strength;
            mode = "OVERRIDE";
        } else {
            weight = here.need + here.precedent_pct;
            mode = "CONSENT";
        }
        share = (weight * self.total_capacity) // self.weight_sum;
        here.allocated = share;
        if share >= here.need {
            status = "met";
        } else {
            status = "SHORT";
        }
        print(
            f"  [{mode}] {here.name}: {share}/{here.need} ({status}) "
            f"— cites {here.precedent_pct}% precedent"
        );
        visit [-->[?:Habitat]] else {
            if self.override_authority {
                print("  Compliance degrading: habitats draining buffers, blocking repair berth");
            } else {
                print("  Negotiation complete; allocations stand until next capacity shift");
            }
            disengage;
        };
    }
}

walker FailureCascade {
    has seen: list[str] = [];

    can start with Root entry {
        print("=== Failure cascade along orbital mirror ring ===");
        visit [-->[?:Mirror]] else { disengage; };
    }

    can propagate with Mirror entry {
        if here.name in self.seen {
            disengage;
        }
        self.seen.append(here.name);
        if here.failed {
            print(f"  Debris lane seeded on {here.name} track — transfer routes degraded");
