"""LiteRT-LM encumbrance notice: trace patent priority chains and cascade preservation demands."""

node Repository {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has name: str = "";
    has encumbered: bool = False;
}

node PatentApplication {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has app_number: str = "";
    has subject: str = "";
    has filed_year: int = 0;
    has priority_year: int = 0;
    has is_provisional: bool = False;
}

node ReleaseArtifact {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has version: str = "";
    has preserved: bool = False;
}

node LegalNotice {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has notice_date: str = "";
    has matter_id: str = "";
}

edge ClaimsEncumbrance {
    has since: str = "";
}

edge ProvisionalPriority {
    has priority_date: str = "";
}

edge PreservationDemand {
    has scope: str = "";
}

walker EncumbranceAuditor {
    has visited: list[str] = [];
    has depth: int = 0;
    has max_depth: int = 8;
    has trace: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can audit_repo with Repository entry {
        status = "ENCUMBERED" if here.encumbered else "CLEAR";
        self.trace += [f"repository {here.name}: {status}"];
        visit [->:ClaimsEncumbrance:->] else {
            visit [-->] else { disengage; };
        };
    }

    can follow_claim with PatentApplication entry {
        if here.app_number in self.visited {
            self.trace += [f"cycle detected at {here.app_number}"];
            disengage;
        }
        self.visited += [here.app_number];
        role = "provisional" if here.is_provisional else "utility";
        self.trace += [f"{role} {here.app_number}: {here.subject}"];
        if self.depth >= self.max_depth {
            disengage;
        }
        self.depth += 1;
        visit [<--:ProvisionalPriority:<--] else {
            self.depth -= 1;
            visit [-->] else { disengage; };
        };
    }
}

walker PreservationGuard {
    has preserved_count: int = 0;
    has log: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can serve_notice with LegalNotice entry {
        self.log += [f"notice {here.matter_id} filed {here.notice_date}"];
        visit [->:PreservationDemand:->] else {
            visit [-->] else { disengage; };
        };
    }

    can lock_artifact with ReleaseArtifact entry {
        if not here.preserved {
            here.preserved = True;
            self.preserved_count += 1;
            self.log += [f"preserved release artifact {here.version}"];
        }
        visit [-->] else { disengage; };
    }
}

