"""Pre-ATN parser rule inlining: walk the rule-call graph, reject unsafe candidates, and accept cost-bounded pure single-use inlines."""

node ParserRule {
    has name: str = "";
    has body_size: int = 0;
    has use_count: int = 0;
    has is_pure: bool = True;
    has has_actions: bool = False;
    has has_labels: bool = False;
    has is_left_recursive: bool = False;
    has in_precedence: bool = False;
}

node LexerRule {
    has name: str = "";
    has priority: int = 0;
}

edge Calls { }

walker CycleChecker {
    has stack: list[str] = [];
    has cyclic: bool = False;

    can descend with ParserRule entry {
        if here.name in self.stack {
            self.cyclic = True;
            disengage;
        }
        self.stack.append(here.name);
        visit [->:Calls:->] else { disengage; };
    }

    can ascend with ParserRule exit {
        if len(self.stack) > 0 and self.stack[len(self.stack) - 1] == here.name {
            self.stack = self.stack[: len(self.stack) - 1];
        }
    }
}

walker InliningPass {
    has manifest: list[str] = [];
    has growth_used: int = 0;
    has growth_cap: int = 12;

    can start with Root entry {
        print("=== Recognition-preserving pre-ATN rule inlining (dry-run) ===");
        visit [-->];
        print("--- Eligibility manifest ---");
        for line in self.manifest {
            print(line);
        }
        print(f"--- Expansion budget used: {self.growth_used}/{self.growth_cap} body tokens ---");
    }

    can skip_lexer with LexerRule entry {
        self.manifest.append(
            f"DECLINE {here.name}: lexer rule (out of scope; order defines token priority)"
        );
        visit [-->];
    }

    can audit with ParserRule entry {
        reason = "";
        if here.has_actions {
            reason = "contains actions, predicates, or @init/@after blocks";
        } elif here.has_labels {
            reason = "alternative or element labels would rebind generated accessors";
        } elif here.is_left_recursive or here.in_precedence {
            reason = "left-recursive or precedence-rule participant";
        } else {
            checker = CycleChecker();
            here spawn checker;
            if checker.cyclic {
                reason = "acyclic constraint violated (direct or mutual recursion)";
            }
        }
        if reason != "" {
            self.manifest.append(f"DECLINE {here.name}: {reason}");
        } elif here.use_count != 1 {
            self.manifest.append(
                f"DECLINE {here.name}: use_count={here.use_count} (requires single-use call site)"
            );
        } elif not here.is_pure {
            self.manifest.append(f"DECLINE {here.name}: not a pure structural parser rule");
        } else {
            projected = self.growth_used + here.body_size;
            if projected > self.growth_cap {
                self.manifest.append(
                    f"DECLINE {here.name}: expansion cap exceeded ({projected}>{self.growth_cap})"
                );
            } else {
                self.manifest.append(
                    f"ACCEPT {here.name}: inline structurally at sole call site (tokens={here.body_size})"
                );
                self.growth_used = projected;
            }
        }
        visit [-->];
    }
}

walker CallSiteRewriter {
    has rewrites: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can walk_rules with ParserRule entry {
        visit [here->:Calls:->];
        visit [-->];
    }

    can rewrite with ParserRule entry {
        caller_name = "unknown";
        for parent in [<-:Calls:<-] {
            caller_name = parent.name;
        }
        self.rewrites.append(
            f"REWRITE {caller_name} -> ({here.name})  # parenthesized structural copy"
        );
        visit [-->];
    }

    can report with Root exit {
        if len(self.rewrites) > 0 {
            print("--- Accepted call-site rewrites ---");
            for line in self.rewrites {
                print(line);
            }
        }
    }
}

with entry {
    id_unpack = ParserRule(name="identifiers_to_unpack", body_size=4, use_count=1);
    bare_id = ParserRule(name="bare_identifier", body_size=2, use_count=1);
    builtin_name = ParserRule(name="builtin_name", body_size=2, use_count=1);
    builtin_call = ParserRule(name="builtin_call", body_size=3, use_count=1);
    assign = ParserRule(name="assignment", body_size=8, use_count=1);
    expr = ParserRule(name="expr", body_size=15, use_count=3, in_precedence=True);
    term = ParserRule(name="term", body_size=5, use_count=2);
    with_action = ParserRule(name="log_action", body_size=5, use_count=1, has_actions=True);
    with_label = ParserRule(name="labeled_alt", body_size=4, use_count=1, has_labels=True);
    left_rec = ParserRule(name="expr_lr", body_size=6, use_count=1, is_left_recursive=True);
    mutual_a = ParserRule(name="mutual_a", body_size=2, use_count=1);
    mutual_b = ParserRule(name="mutual_b", body_size=2, use_count=1);
    self_ref = ParserRule(name="direct_rec", body_size=2, use_count=1);
    kw_if = LexerRule(name="KW_IF", priority=1);

    root ++> assign ++> expr ++> term;
    assign +>:Calls:+> id_unpack;
    id_unpack +>:Calls:+> bare_id;
    expr +>:Calls:+> builtin_call;
    builtin_call +>:Calls:+> builtin_name;
    expr +>:Calls:+> left_rec;
    mutual_a +>:Calls:+> mutual_b;
    mutual_b +>:Calls:+> mutual_a;
    self_ref +>:Calls:+> self_ref;
    root ++> with_action ++> with_label;
    root ++> mutual_a;
    root ++> self_ref;
    root ++> kw_if;

    auditor = InliningPass(growth_cap=12);
