}

"""Frontier retry guard demo: permanent Redis outage stalls silently; terminal MISCONF fails the run."""

node CrawlerRun {
    has run_id: str = "";
    has status: str = "running";
    has progress: int = 0;
    has error_msg: str = "";
}

node RedisFrontier {
    has name: str = "";
    has retry_count: int = 0;
}

node RedisBackend {
    has host: str = "";
    has error_kind: str = "healthy";
    has error_detail: str = "";
}

edge Uses { }
edge ConnectsTo { }

walker Orchestrator {
    has demo_cap: int = 4;
    has ticks: int = 0;
    has phase: str = "fetch";
    has active_run: CrawlerRun = None;
    has active_frontier: RedisFrontier = None;

    can start with Root entry {
        visit [-->];
    }

    can drive with CrawlerRun entry {
        print(f"\n=== Run {here.run_id} (status={here.status}) ===");
        self.active_run = here;
        self.active_frontier = None;
        self.ticks = 0;
        self.phase = "fetch";
        visit [->:Uses:->] else {
            print("  no frontier attached");
            visit [-->];
        };
    }

    can frontier_next with RedisFrontier entry {
        self.active_frontier = here;
        if self.phase == "done" {
            visit [-->];
        } else {
            if self.phase == "retry" {
                self.phase = "fetch";
            }
            visit [->:ConnectsTo:->] else {
                print("  frontier empty - zero progress");
                self.phase = "done";
                visit [-->];
            };
        }
    }

    can redis_op with RedisBackend entry {
        self.ticks += 1;
        kind = here.error_kind;
        detail = here.error_detail;
        frontier = self.active_frontier;
        run = self.active_run;

        if kind == "healthy" {
            run.progress += 1;
            print(f"  Next OK - progress={run.progress}");
            self.phase = "done";
            visit [<--:ConnectsTo:<--];
        } else {
            if kind == "terminal" {
                run.status = "failed";
                run.error_msg = detail;
                print(f"  TERMINAL: {detail}");
                print("  orchestrator marks run FAILED");
                self.phase = "done";
                visit [<--:ConnectsTo:<--];
            } else {
                frontier.retry_count += 1;
                label = "transient blip" if kind == "transient" else "permanent outage";
                print(f"  retry {frontier.retry_count} [{label}]: {detail}");
                print(f"    run still '{run.status}', progress={run.progress}, no error recorded");
                if self.ticks >= self.demo_cap {
                    print("  [demo cap] ADR-0024 retry guard loops forever - silent stall");
                    self.phase = "done";
                    visit [<--:ConnectsTo:<--];
                } else {
                    self.phase = "retry";
                    visit [<--:ConnectsTo:<--];
                }
            }
        }
    }
}

