"""Recursive submodule checkout: detect when a pinned gateway-proxy commit is unreachable from its remote."""

node Superproject {
    has name: str = "";
}

node Submodule {
    has path: str = "";
    has remote_url: str = "";
    has pinned_sha: str = "";
}

node Commit {
    has sha: str = "";
    has note: str = "";
}

node Remote {
    has url: str = "";
}

edge SubmoduleOf { }
edge ConfiguredAt { }
edge Advertises { }

walker RecursiveCheckout {
    has checkout_ok: bool = True;
    has active_pin: str = "";
    has pin_reachable: bool = False;
    has stack: list[str] = [];

    can start with Root entry {
        print("git clone --recurse-submodules");
        visit [-->];
    }

    can clone_super with Superproject entry {
        print(f"materializing superproject {here.name}");
        visit [->:SubmoduleOf:->] else {
            disengage;
        };
    }

    can init_submodule with Submodule entry {
        if here.path in self.stack {
            print(f"cycle guard: submodule {here.path} already on checkout stack");
            self.checkout_ok = False;
            disengage;
        }
        self.stack.append(here.path);
        self.active_pin = here.pinned_sha;
        self.pin_reachable = False;
        print(f"init submodule {here.path} pinned to {self.active_pin}");
        visit [->:ConfiguredAt:->] else {
            print(f"FAILED: no remote configured for {here.path}");
            self.checkout_ok = False;
            disengage;
        };
        if not self.pin_reachable {
            print(
                f"FAILED: {here.path} missing commit {self.active_pin} on {here.remote_url}"
            );
            self.checkout_ok = False;
        } else {
            print(f"OK: {here.path} checked out at {self.active_pin}");
        }
        visit [->:SubmoduleOf:->] else {
            disengage;
        };
    }

    can fetch_remote with Remote entry {
        print(f"fetching {here.url}");
        visit [->:Advertises:->] else {
            print(f"remote {here.url} advertises no commits");
            disengage;
        };
    }

    can match_ad with Commit entry {
        if here.sha == self.active_pin {
            self.pin_reachable = True;
            print(f"remote serves pinned object {here.sha} ({here.note})");
        }
        visit [->:Advertises:->] else {
            disengage;
        };
    }
}

