"""AuthKit plugin host pipeline: discovery cache, compatibility gate,
dependency graph validation, Kahn ordering, and outcome logging."""

node DiscoveryCache {
    has title: str = "plugin-discovery";
    has fingerprint: str = "";
    has schema_version: int = 1;
    has available: bool = True;
}

node Plugin {
    has plugin_id: str = "";
    has title: str = "";
    has priority: int = 0;
    has enabled: bool = True;
    has min_host_version: str = "1.0";
    has location: str = "";
    has source_fingerprint: str = "";
    has outcome: str = "pending";
    has reject_reason: str = "";
}

edge DependsOn { }

walker DiscoveryPhase {
    has cache_fingerprint: str = "";
    has cache_hit: bool = False;

    can start with Root entry {
        visit [-->[?:DiscoveryCache]];
    }

    can probe with DiscoveryCache entry {
        hit_token = "HIT" if here.fingerprint == self.cache_fingerprint else "MISS";
        cache_state = hit_token == "HIT";
        self.cache_hit = cache_state;
        print(f"[discovery] cache {hit_token} schema={here.schema_version}");
        visit [-->[?:Plugin]];
    }

    can discover with Plugin entry {
        print(
            f"[discovery] found {here.plugin_id} "
            f"at {here.location} fp={here.source_fingerprint}"
        );
        visit [-->];
    }
}

walker CompatibilityGate {
    has host_version: str = "2.0";

    can start with Root entry {
        visit [-->[?:Plugin]];
    }

    can gate with Plugin entry {
        if not here.enabled {
            here.outcome = "skipped";
            here.reject_reason = "disabled";
            print(f"[gate] SKIP {here.plugin_id} (disabled)");
        } elif float(self.host_version) < float(here.min_host_version) {
            here.outcome = "rejected";
            here.reject_reason = "incompatible-host";
            print(
                f"[gate] REJECT {here.plugin_id} "
                f"min_host={here.min_host_version}"
            );
        } else {
            here.outcome = "accepted";
            print(f"[gate] ACCEPT {here.plugin_id}");
        }
        visit [-->];
    }
}

walker DepOutcomeCheck {
    has blocked: bool = False;
    has reason: str = "";

    can start with Plugin entry {
        visit [->:DependsOn:->] else { disengage; };
    }

    can probe with Plugin entry {
        if here.outcome == "skipped" {
            self.blocked = True;
            dep_tag = here.reject_reason if here.reject_reason else "disabled";
            self.reason = f"dependency-unavailable ({here.plugin_id} {dep_tag})";
            disengage;
        }
        if here.outcome == "rejected" {
            self.blocked = True;
            self.reason = f"dependency-unavailable ({here.plugin_id})";
            disengage;
        }
        visit [-->];
    }
}

walker DepAvailability {
    can start with Root entry {
        visit [-->[?:Plugin]];
    }

    can scan with Plugin entry {
        if here.outcome != "accepted" {
            visit [-->];
        } else {
            chk = DepOutcomeCheck();
            here spawn chk;
            if chk.blocked {
                here.outcome = "rejected";
                here.reject_reason = chk.reason;
                print(f"[deps] REJECT {here.plugin_id} {chk.reason}");
            }
            visit [-->];
        }
    }
}

walker CycleDetector {
    has visiting: list[str] = [];
    has cycle_found: bool = False;
    has cycle_detail: str = "";

    can start with Root entry {
        visit [-->[?:Plugin]];
    }

    can inspect with Plugin entry {
        if here.outcome != "accepted" {
            visit [-->];
        } elif here.plugin_id in self.visiting {
            self.cycle_found = True;
            self.cycle_detail = f"{here.plugin_id}";
            print(f"[graph] CYCLE at {here.plugin_id}");
            disengage;
        } else {
            self.visiting.append(here.plugin_id);
            visit [->:DependsOn:->] else { };
            trimmed: list[str] = [];
            for (i, pid) in enumerate(self.visiting) {
                if i < len(self.visiting) - 1 {
                    trimmed.append(pid);
                }
            }
            self.visiting = trimmed;
            visit [-->];
        }
    }
}

walker DepReadyCheck {
    has load_order: list[str] = [];
    has ready: bool = True;

    can start with Plugin entry {
        visit [->:DependsOn:->] else { disengage; };
    }

    can verify with Plugin entry {
        if here.plugin_id not in self.load_order {
            self.ready = False;
            disengage;
        }
        visit [-->];
    }
}

walker WaveScan {
    has load_order: list[str] = [];
    has pick_priority: int = -1;
    has pick_id: str = "";
    has found_candidate: bool = False;

    can start with Root entry {
        visit [-->[?:Plugin]];
    }

    can scan with Plugin entry {
        if here.outcome != "accepted" {
            visit [-->];
        } elif here.plugin_id in self.load_order {
            visit [-->];
        } else {
            chk = DepReadyCheck(load_order=self.load_order);
            here spawn chk;
            if chk.ready {
                take = False;
                if not self.found_candidate {
                    take = True;
                } elif here.priority < self.pick_priority {
                    take = True;
                }
                if take {
                    self.found_candidate = True;
                    self.pick_priority = here.priority;
                    self.pick_id = here.plugin_id;
                }
            }
            visit [-->];
        }
    }
}

walker DependencyOrderer {
    has load_order: list[str] = [];
    has startup_failed: bool = False;
    has failure_reason: str = "";
    has wave: int = 0;

    can start with Root entry {
        self._kahn(root);
    }

    def _kahn(r: Root) -> None {
        placed = 0;
        total = 0;
        counter = WaveScan(load_order=[]);
        r spawn counter;
        for pid in counter.load_order {
            total += 1;
        }
        total = 0;
        tally = WaveScan(load_order=[]);
        r spawn tally;
        visit_scan = WaveScan(load_order=[]);
        r spawn visit_scan;
        for _pid in visit_scan.load_order {
            total += 1;
        }
        total = 0;
        head = WaveScan(load_order=[]);
        r spawn head;
        for _p in head.load_order {
            total += 1;
        }
        total = 0;
        census = PluginCensus();
        r spawn census;
        total = census.count;
        while placed < total {
            self.wave += 1;
            scan = WaveScan(load_order=self.load_order);
            r spawn scan;
            if not scan.found_candidate {
                self.startup_failed = True;
                self.failure_reason = "missing-dependency-or-cycle";
                print(f"[order] STARTUP FAIL {self.failure_reason}");
                break;
            }
            self.load_order.append(scan.pick_id);
            placed += 1;
            print(
                f"[order] wave={self.wave} placed {scan.pick_id} "
                f"priority={scan.pick_priority}"
            );
        }
    }
}

walker PluginCensus {
    has count: int = 0;

    can start with Root entry {
        visit [-->[?:Plugin]];
    }

    can tally with Plugin entry {
        if here.outcome == "accepted" {
            self.count += 1;
        }
        visit [-->];
    }
}

walker OutcomeReporter {
    has load_order: list[str] = [];

    can start with Root entry {
        visit [-->[?:Plugin]];
    }

    can report with Plugin entry {
        tag = here.outcome;
        extra = f" reason={here.reject_reason}" if here.reject_reason else "";
        loaded = " LOADED" if here.plugin_id in self.load_order else "";
        print(f"[final] {here.plugin_id} {tag}{extra}{loaded}");
        visit [-->];
    }
}

