"""Pre-ATN parser rule inlining: walk the rule-call graph, reject unsafe candidates, and accept cost-bounded pure single-use inlines."""

node ParserRule {
    has name: str = "";
    has body_size: int = 0;
    has use_count: int = 0;
    has is_pure: bool = True;
    has has_actions: bool = False;
    has has_labels: bool = False;
    has is_left_recursive: bool = False;
    has in_precedence: bool = False;
}

node LexerRule {
    has name: str = "";
    has priority: int = 0;
}

edge Calls { }

walker CycleChecker {
    has stack: list[str] = [];
    has cyclic: bool = False;

    can descend with ParserRule entry {
        if here.name in self.stack {
            self.cyclic = True;
            disengage;
        }
        self.stack.append(here.name);
        visit [->:Calls:->] else { disengage; };
    }

    can ascend with ParserRule exit {
        if len(self.stack) > 0 and self.stack[len(self.stack) - 1] == here.name {
            self.stack.pop();
        }
    }
}

def rule_decline_reason(rule: ParserRule) -> str {
    if rule.has_actions {
        return "contains actions, predicates, or @init/@after blocks";
    }
    if rule.has_labels {
        return "alternative or element labels would rebind generated accessors";
    }
    if rule.is_left_recursive or rule.in_precedence {
        return "left-recursive or precedence-rule participant";
    }
    checker = CycleChecker();
    rule spawn checker;
    if checker.cyclic {
        return "acyclic constraint violated (direct or mutual recursion)";
    }
    return "";
}

walker InliningPass {
    has manifest: list[str] = [];
    has growth_used: int = 0;
    has growth_cap: int = 12;

    can start with Root entry {
        print("=== Recognition-preserving pre-ATN rule inlining (dry-run) ===");
        visit [-->];
        print("--- Eligibility manifest ---");
        for line in self.manifest {
            print(line);
        }
        print(f"--- Expansion budget used: {self.growth_used}/{self.growth_cap} body tokens ---");
    }

    can skip_lexer with LexerRule entry {
        self.manifest.append(
            f"DECLINE {here.name}: lexer rule (out of scope; order defines token priority)"
        );
        visit [-->];
    }

    can audit with ParserRule entry {
        decline_reason = rule_decline_reason(here);
        if decline_reason != "" {
            self.manifest.append(f"DECLINE {here.name}: {decline_reason}");
        } elif here.use_count != 1 {
            self.manifest.append(
                f"DECLINE {here.name}: use_count={here.use_count} (requires single-use call site)"
            );
        } elif not here.is_pure {
            self.manifest.append(f"DECLINE {here.name}: not a pure structural parser rule");
        } else {
            projected = self.growth_used + here.body_size;
            if projected > self.growth_cap {
                self.manifest.append(
                    f"DECLINE {here.name}: expansion cap exceeded ({projected}>{self.growth_cap})"
                );
            } else {
                caller_name = "unknown";
                for caller in [<-:Calls:<-] {
                    if caller is ParserRule {
                        caller_name = caller.name;
                    }
                }
                self.manifest.append(
                    f"ACCEPT {here.name}: inline structurally at sole call site (tokens={here.body_size})"
                );
                self.manifest.append(
                    f"REWRITE {caller_name} -> ({here.name})  # parenthesized structural copy"
                );
                self.growth_used = projected;
            }
        }
        visit [-->];
    }
}

with entry {
    id_unpack = ParserRule(name="identifiers_to_unpack", body_size=4, use_count=1);
    bare_id = ParserRule(name="bare_identifier", body_size=2, use_count=1);
    builtin_name = ParserRule(name="builtin_name", body_size=2, use_count=1);
    builtin_call = ParserRule(name="builtin_call", body_size=3, use_count=1);
    assign = ParserRule(name="assignment", body_size=8, use_count=1);
    expr = ParserRule(name="expr", body_size=15, use_count=3, in_precedence=True);
    term = ParserRule(name="term", body_size=5, use_count=2);
    with_action = ParserRule(name="log_action", body_size=5, use_count=1, has_actions=True);
    with_label = ParserRule(name="labeled_alt", body_size=4, use_count=1, has_labels=True);
    left_rec = ParserRule(name="expr_lr", body_size=6, use_count=1, is_left_recursive=True);
    mutual_a = ParserRule(name="mutual_a", body_size=2, use_count=1);
    mutual_b = ParserRule(name="mutual_b", body_size=2, use_count=1);
    self_ref = ParserRule(name="direct_rec", body_size=2, use_count=1);
    kw_if = LexerRule(name="KW_IF", priority=1);

    root ++> assign ++> expr ++> term;
    assign +>:Calls:+> id_unpack;
    id_unpack +>:Calls:+> bare_id;
    expr +>:Calls:+> builtin_call;
    builtin_call +>:Calls:+> builtin_name;
    expr +>:Calls:+> left_rec;
    mutual_a +>:Calls:+> mutual_b;
    mutual_b +>:Calls:+> mutual_a;
    self_ref +>:Calls:+> self_ref;
    root ++> with_action ++> with_label;
    root ++> mutual_a;
    root ++> self_ref;
    root ++> kw_if;

    root spawn InliningPass(growth_cap=12);
}

"""Issue #253: DependencyReducer re-parses shared csproj files per deploy candidate unless xmlCache is hoisted to repo scope."""

node Repo {
    has name: str = "";
    has xml_cache: dict = {};

    def evict(path: str) -> None {
        if path in self.xml_cache {
            del self.xml_cache[path];
            print(f"  [EVICT] {path} (reducer rewrote csproj)");
        }
    }
}

node Project {
    has name: str = "";
    has path: str = "";
    has deploy_candidate: bool = False;
    has disk_parse_count: int = 0;

    def simulate_disk_load() -> None {
        self.disk_parse_count += 1;
        print(f"    XmlDocument.Load: {self.path}");
    }
}

edge References { }

walker PerProjectReducer {
    has xml_cache: dict = {};
    has pass_loads: int = 0;

    can start with Project entry {
        print(f"\n  GetProjectsToDeploy: {here.name} (fresh xmlCache dict)");
        self.xml_cache = {};
        self.pass_loads = 0;
        self.get_or_load(here);
        visit [->:References:->] else { disengage; };
    }

    can resolve_ref with Project entry {
        self.get_or_load(here);
        visit [->:References:->] else { disengage; };
    }

    def get_or_load(project: Project) -> None {
        key = project.path;
        if key not in self.xml_cache {
            project.simulate_disk_load();
            self.xml_cache[key] = True;
            self.pass_loads += 1;
        }
    }
}

walker RepoScopeReducer {
    has repo: Repo;
    has pass_label: str = "";

    can start with Project entry {
        print(f"\n  GetProjectsToDeploy: {here.name} ({self.pass_label})");
        self.repo_get_or_load(here);
        visit [->:References:->] else { disengage; };
    }

    can resolve_ref with Project entry {
        self.repo_get_or_load(here);
        visit [->:References:->] else { disengage; };
    }

    def repo_get_or_load(project: Project) -> None {
        key = project.path;
        if key not in self.repo.xml_cache {
            project.simulate_disk_load();
            self.repo.xml_cache[key] = True;
        }
    }
}

with entry {
    repo = Repo(name="credfeto-dotnet-repo-tools");
    root ++> repo;

    utils = Project(name="Utils", path="src/Utils/Utils.csproj");
    core = Project(name="CoreLib", path="src/CoreLib/CoreLib.csproj");
    web = Project(
        name="WebApp",
        path="src/WebApp/WebApp.csproj",
        deploy_candidate=True
    );
    api = Project(
        name="Api",
        path="src/Api/Api.csproj",
        deploy_candidate=True
    );

    web +>:References:+> core +>:References:+> utils;
    api +>:References:+> core;

    repo ++> web;
    repo ++> api;

    print("=== Per-project xmlCache (O(P x T) redundant parses) ===");
    bad_web = PerProjectReducer();
    web spawn bad_web;
    print(f"  Pass disk loads: {bad_web.pass_loads}");
    bad_api = PerProjectReducer();
    api spawn bad_api;
    print(f"  Pass disk loads: {bad_api.pass_loads}");
    print(
        f"  CoreLib parsed {core.disk_parse_count} times; "
        f"Utils parsed {utils.disk_parse_count} times"
    );

    reset_targets = [utils, core, web, api];
    for target in reset_targets {
        target.disk_parse_count = 0;
    }
    repo.xml_cache = {};

    print("\n=== Repo-scoped xmlCache (hoisted fix) ===");
    good_web = RepoScopeReducer(
        repo=repo,
        pass_label="shared repo cache"
    );
    web spawn good_web;
    good_api = RepoScopeReducer(
        repo=repo,
        pass_label="shared repo cache"
    );
    api spawn good_api;
    print(f"  Unique cached csproj paths: {len(repo.xml_cache)}");
    print(
        f"  CoreLib parsed {core.disk_parse_count} time; "
        f"Utils parsed {utils.disk_parse_count} time"
    );

    repo.evict(core.path);
    recheck = RepoScopeReducer(
        repo=repo,
        pass_label="after eviction"
    );
    web spawn recheck;
    print(
        f"  After rewrite eviction: CoreLib parsed "
        f"{core.disk_parse_count} total times, Utils still "
        f"{utils.disk_parse_count}"
    );
}

"""AuthKit plugin host pipeline: discovery cache, compatibility gate,
dependency propagation, cycle detection, Kahn ordering, and outcome logging."""

node DiscoveryCache {
    has title: str = "plugin-discovery";
    has fingerprint: str = "";
    has year: int = 0;
    has available: bool = True;
    has schema_version: int = 1;
}

node Plugin {
    has plugin_id: str = "";
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has priority: int = 0;
    has enabled: bool = True;
    has min_host_version: str = "1.0";
    has location: str = "";
    has source_fingerprint: str = "";
    has outcome: str = "pending";
    has reject_reason: str = "";
}

edge DependsOn { }

walker DiscoveryPhase {
    has cache_fingerprint: str = "";
    has cache_hit: bool = False;

    can start with Root entry {
        visit [-->];
    }

    can probe with DiscoveryCache entry {
        hit_token = "HIT" if here.fingerprint == self.cache_fingerprint else "MISS";
        self.cache_hit = hit_token == "HIT";
        print(f"[discovery] cache {hit_token} schema={here.schema_version}");
        visit [-->];
    }

    can discover with Plugin entry {
        print(
            f"[discovery] found {here.plugin_id} "
            f"at {here.location} fp={here.source_fingerprint}"
        );
        visit [-->];
    }
}

walker CompatibilityGate {
    has host_version: str = "2.0";

    can start with Root entry {
        visit [-->];
    }

    can gate with DiscoveryCache entry {
        visit [-->];
    }

    can gate with Plugin entry {
        if not here.enabled {
            here.outcome = "skipped";
            here.reject_reason = "disabled";
            print(f"[gate] SKIP {here.plugin_id} (disabled)");
        } elif float(self.host_version) < float(here.min_host_version) {
            here.outcome = "rejected";
            here.reject_reason = "incompatible-host";
            print(
                f"[gate] REJECT {here.plugin_id} "
                f"min_host={here.min_host_version}"
            );
        } else {
            here.outcome = "accepted";
            print(f"[gate] ACCEPT {here.plugin_id}");
        }
        visit [-->];
    }
}

walker DepOutcomeCheck {
    has blocked: bool = False;
    has reason: str = "";

    can start with Plugin entry {
        visit [->:DependsOn:->] else { disengage; };
    }

    can probe with Plugin entry {
        if here.outcome == "skipped" {
            self.blocked = True;
            dep_tag = here.reject_reason if here.reject_reason else "disabled";
            self.reason = f"dependency-unavailable ({here.plugin_id} {dep_tag})";
        } elif here.outcome == "rejected" {
            self.blocked = True;
            self.reason = f"dependency-unavailable ({here.plugin_id})";
        }
    }
}

walker DepAvailability {
    can start with Root entry {
        visit [-->];
    }

    can scan with DiscoveryCache entry {
        visit [-->];
    }

    can scan with Plugin entry {
        if here.outcome == "accepted" {
            chk = DepOutcomeCheck();
            here spawn chk;
            if chk.blocked {
                here.outcome = "rejected";
                here.reject_reason = chk.reason;
                print(f"[deps] REJECT {here.plugin_id} {chk.reason}");
            }
        }
        visit [-->];
    }
}

walker CycleProbe {
    has visiting: list[str] = [];
    has cycle_found: bool = False;

    can start with Plugin entry {
        if here.plugin_id in self.visiting {
            self.cycle_found = True;
            disengage;
        }
        self.visiting.append(here.plugin_id);
        visit [->:DependsOn:->] else { disengage; };
        trimmed: list[str] = [];
        for (i, pid) in enumerate(self.visiting) {
            if i < len(self.visiting) - 1 {
                trimmed.append(pid);
            }
        }
        self.visiting = trimmed;
    }

    can descend with Plugin entry {
        if here.plugin_id in self.visiting {
            self.cycle_found = True;
            disengage;
        }
        self.visiting.append(here.plugin_id);
        visit [->:DependsOn:->] else { disengage; };
        trimmed: list[str] = [];
        for (i, pid) in enumerate(self.visiting) {
            if i < len(self.visiting) - 1 {
                trimmed.append(pid);
            }
        }
        self.visiting = trimmed;
    }
}

walker CycleDetector {
    has cycle_found: bool = False;
    has cycle_detail: str = "";

    can start with Root entry {
        visit [-->];
    }

    can inspect with DiscoveryCache entry {
        visit [-->];
    }

    can inspect with Plugin entry {
        if here.outcome == "accepted" {
            probe = CycleProbe();
            here spawn probe;
            if probe.cycle_found {
                self.cycle_found = True;
                self.cycle_detail = here.plugin_id;
                print(f"[graph] CYCLE involving {here.plugin_id}");
            }
        }
        visit [-->];
    }
}

walker DepReadyCheck {
    has load_order: list[str] = [];
    has ready: bool = True;

    can start with Plugin entry {
        visit [->:DependsOn:->] else { disengage; };
    }

    can verify with Plugin entry {
        if here.plugin_id not in self.load_order {
            self.ready = False;
        }
    }
}

walker AcceptCounter {
    has count: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can tally with DiscoveryCache entry {
        visit [-->];
    }

    can tally with Plugin entry {
        if here.outcome == "accepted" {
            self.count += 1;
        }
        visit [-->];
    }
}

walker ReadyScan {
    has load_order: list[str] = [];
    has pick_id: str = "";
    has pick_priority: int = -1;

    can start with Root entry {
        visit [-->];
    }

    can scan with DiscoveryCache entry {
        visit [-->];
    }

    can scan with Plugin entry {
        if here.outcome != "accepted" {
            visit [-->];
        } elif here.plugin_id in self.load_order {
            visit [-->];
        } else {
            chk = DepReadyCheck(load_order=self.load_order);
            here spawn chk;
            if chk.ready {
                if self.pick_id == "" or here.priority > self.pick_priority {
                    self.pick_priority = here.priority;
                    self.pick_id = here.plugin_id;
                }
            }
            visit [-->];
        }
    }
}

walker KahnOrderer {
    has load_order: list[str] = [];
    has startup_failed: bool = False;
    has failure_reason: str = "";

    can start with Root entry {
        census = AcceptCounter();
        root spawn census;
        total = census.count;
        placed = 0;
        wave = 0;
        while placed < total and wave < total + 1 {
            wave += 1;
            scan = ReadyScan(load_order=self.load_order);
            root spawn scan;
            if scan.pick_id == "" {
                self.startup_failed = True;
                self.failure_reason = "missing-dependency-or-cycle";
                print(f"[order] STARTUP FAIL {self.failure_reason}");
                break;
            }
            self.load_order.append(scan.pick_id);
            placed += 1;
            print(
                f"[order] wave={wave} placed {scan.pick_id} "
                f"priority={scan.pick_priority}"
            );
        }
    }
}

walker OutcomeReporter {
    has load_order: list[str] = [];
    has ordering_failed: bool = False;

    can start with Root entry {
        visit [-->];
    }

    can report with DiscoveryCache entry {
        visit [-->];
    }

    can report with Plugin entry {
        tag = here.outcome;
        extra = f" reason={here.reject_reason}" if here.reject_reason else "";
        loaded = " LOADED" if here.plugin_id in self.load_order else "";
        print(f"[final] {here.plugin_id} {tag}{extra}{loaded}");
        visit [-->];
    }
}

