"""Call-graph findPath: fan-in hubs show naive BFS enqueue blowup vs enqueue-once guard."""

node Func {
    has name: str = "";
}

edge Calls { }

node PathUtils {
    def contains(nodes: list, needle: Func) -> bool {
        for n in nodes {
            if n is needle {
                return True;
            }
        }
        return False;
    }

    def dequeue(queue: list) -> list {
        if len(queue) == 0 {
            return [];
        }
        head = queue[0];
        tail = [];
        for (i, item) in enumerate(queue) {
            if i > 0 {
                tail.append(item);
            }
        }
        return [head, tail];
    }
}

walker SuccFetch {
    has items: list = [];

    can start with Func entry {
        visit [->:Calls:->] else { disengage; };
    }

    can collect with Func entry {
        self.items.append(here);
    }
}

walker NameLookup {
    has target: str = "";
    has found: Func | None = None;

    can start with Root entry {
        visit [-->];
    }

    can seek with Func entry {
        if here.name == self.target {
            self.found = here;
            disengage;
        }
        visit [-->];
    }
}

walker GraphWalk {
    can start with Root entry {
        visit [-->];
    }

    can step with Func entry {
        print(f"  at {here.name}");
        visit [->:Calls:->] else { disengage; };
    }
}

walker NaivePathFinder {
    has origin_name: str = "";
    has goal_name: str = "";
    has enqueue_events: int = 0;
    has path_copy_events: int = 0;
    has hop_count: int = 0;

    def lookup(graph_root: root, label: str) -> Func | None {
        w = NameLookup(target=label);
        graph_root spawn w;
        return w.found;
    }

    def outgoing(node: Func) -> list {
        w = SuccFetch();
        node spawn w;
        return w.items;
    }

    def find_path(graph_root: root) -> None {
        origin = self.lookup(graph_root, self.origin_name);
        goal = self.lookup(graph_root, self.goal_name);
        if origin is None or goal is None {
            return;
        }
        queue = [[origin, []]];
        visited = [];
        while len(queue) > 0 {
            step = PathUtils.dequeue(queue);
            current = step[0];
            queue = step[1];
            node = current[0];
            path = current[1];
            if PathUtils.contains(visited, node) {
                continue;
            }
            visited.append(node);
            if node is goal {
                self.hop_count = len(path);
                return;
            }
            for next_node in self.outgoing(node) {
                if not PathUtils.contains(visited, next_node) {
                    self.enqueue_events += 1;
                    self.path_copy_events += 1;
                    extended = path + [node];
                    queue.append([next_node, extended]);
                }
            }
        }
    }

    can start with Root entry {
        self.find_path(root);
        disengage;
    }
}

walker GuardedPathFinder {
    has origin_name: str = "";
    has goal_name: str = "";
    has enqueue_events: int = 0;
    has path_copy_events: int = 0;
    has hop_count: int = 0;

    def lookup(graph_root: root, label: str) -> Func | None {
        w = NameLookup(target=label);
        graph_root spawn w;
        return w.found;
    }

    def outgoing(node: Func) -> list {
        w = SuccFetch();
        node spawn w;
        return w.items;
    }

    def find_path(graph_root: root) -> None {
        origin = self.lookup(graph_root, self.origin_name);
        goal = self.lookup(graph_root, self.goal_name);
        if origin is None or goal is None {
            return;
        }
        queue = [[origin, []]];
        visited = [];
        enqueued = [origin];
        while len(queue) > 0 {
            step = PathUtils.dequeue(queue);
            current = step[0];
            queue = step[1];
            node = current[0];
            path = current[1];
            if PathUtils.contains(visited, node) {
                continue;
            }
            visited.append(node);
            if node is goal {
                self.hop_count = len(path);
                return;
            }
            for next_node in self.outgoing(node) {
                if not PathUtils.contains(visited, next_node)
                    and not PathUtils.contains(enqueued, next_node) {
                    enqueued.append(next_node);
                    self.enqueue_events += 1;
                    self.path_copy_events += 1;
                    extended = path + [node];
                    queue.append([next_node, extended]);
                }
            }
        }
    }

    can start with Root entry {
        self.find_path(root);
        disengage;
    }
}

with entry {
    main_fn = Func(name="main");
    hub = Func(name="shared_helper");
    sink = Func(name="sink");
    root ++> main_fn;
    hub +>:Calls:+> sink;
    fan_in = 6;
    for i in range(fan_in) {
        worker = Func(name=f"worker_{i}");
        main_fn +>:Calls:+> worker;
        worker +>:Calls:+> hub;
    }
    root spawn GraphWalk();
    naive = NaivePathFinder(origin_name="main", goal_name="sink");
    root spawn naive;
    guarded = GuardedPathFinder(origin_name="main", goal_name="sink");
    root spawn guarded;
    print(f"fan_in={fan_in} shortest_hops naive={naive.hop_count} guarded={guarded.hop_count}");
    print(f"naive enqueue={naive.enqueue_events} path_copies={naive.path_copy_events}");
    print(f"guarded enqueue={guarded.enqueue_events} path_copies={guarded.path_copy_events}");
}

