"""Issue #253: DependencyReducer re-parses shared csproj files per deploy candidate unless xmlCache is hoisted to repo scope."""

node Repo {
    has name: str = "";
    has xml_cache: dict[str, bool] = {};

    def evict(path: str) {
        if path in self.xml_cache {
            del self.xml_cache[path];
            print(f"  [EVICT] {path} (reducer rewrote csproj)");
        }
    }
}

node Project {
    has name: str = "";
    has path: str = "";
    has deploy_candidate: bool = False;
    has disk_parse_count: int = 0;

    def simulate_disk_load() {
        self.disk_parse_count += 1;
        print(f"    XmlDocument.Load: {self.path}");
    }
}

