"""Call-graph findPath: fan-in hubs show naive BFS enqueue blowup vs enqueue-once guard."""

node Func {
    has name: str = "";
}

edge Calls { }

node PathUtils {
    def contains(items: list, needle: Func) -> bool {
        for n in items {
            if n is needle {
                return True;
            }
        }
        return False;
    }

    def dequeue(queue: list) -> list {
        if len(queue) == 0 {
            return [];
        }
        head = queue[0];
        tail = [];
        for (i, item) in enumerate(queue) {
            if i > 0 {
                tail.append(item);
            }
        }
        return [head, tail];
    }
}

walker SuccFetch {
    has items: list = [];

    can start with Func entry {
        visit [->:Calls:->] else { disengage; };
    }

    can collect with Func entry {
        self.items.append(here);
    }
}

walker NameLookup {
    has target: str = "";
    has found: Func | None = None;

    can start with Root entry {
        visit [-->];
    }

    can seek with Func entry {
        if here.name == self.target {
            self.found = here;
            disengage;
        }
        visit [-->];
    }
}

walker GraphWalk {
    can start with Root entry {
        visit [-->];
    }

    can step with Func entry {
        print(f"  at {here.name}");
        visit [->:Calls:->] else { disengage; };
    }
}

walker NaivePathFinder {
    has origin_name: str = "";
    has goal_name: str = "";
    has enqueue_events: int = 0;
    has path_copy_events: int = 0;
    has hop_count: int = 0;

    def lookup(graph_root: root, label: str) -> Func | None {
        w = NameLookup(target=label);
        graph_root spawn w;
        return w.found;
    }

    def outgoing(callee: Func) -> list {
        w = SuccFetch();
        callee spawn w;
        return w.items;
    }

    def find_path(graph_root: root) -> None {
        origin = self.lookup(graph_root, self.origin_name);
        goal = self.lookup(graph_root, self.goal_name);
        if origin is None or goal is None {
            return;
        }
        queue = [[origin, []]];
        visited = [];
        while len(queue) > 0 {
            step = PathUtils.dequeue(queue);
            current = step[0];
            queue = step[1];
            cur_fn = current[0];
            path = current[1];
            if PathUtils.contains(visited, cur_fn) {
                continue;
            }
            visited.append(cur_fn);
            if cur_fn is goal {
                self.hop_count = len(path);
                return;
            }
            for next_fn in self.outgoing(cur_fn) {
                if not PathUtils.contains(visited, next_fn) {
                    self.enqueue_events += 1;
                    self.path_copy_events += 1;
                    extended = path + [cur_fn];
                    queue.append([next_fn, extended]);
                }
            }
        }
    }

    can start with Root entry {
        self.find_path(root);
        disengage;
    }
}

walker GuardedPathFinder {
    has origin_name: str = "";
    has goal_name: str = "";
    has enqueue_events: int = 0;
