"""Pre-ATN parser rule inlining: walk the rule-call graph, reject unsafe candidates, and accept cost-bounded pure single-use inlines."""

node ParserRule {
    has name: str = "";
    has body_size: int = 0;
    has use_count: int = 0;
    has sole_caller: str = "";
    has is_pure: bool = True;
    has has_actions: bool = False;
    has has_labels: bool = False;
    has is_left_recursive: bool = False;
    has in_precedence: bool = False;
}

node LexerRule {
    has name: str = "";
    has priority: int = 0;
}

edge Calls { }

walker CycleChecker {
    has stack: list[str] = [];
    has cyclic: bool = False;

    can descend with ParserRule entry {
        if here.name in self.stack {
            self.cyclic = True;
            disengage;
        }
        self.stack.append(here.name);
        visit [->:Calls:->] else { disengage; };
    }

    can ascend with ParserRule exit {
        if len(self.stack) > 0 and self.stack[len(self.stack) - 1] == here.name {
            self.stack.pop();
        }
    }
}

walker InliningPass {
    has manifest: list[str] = [];
    has growth_used: int = 0;
    has growth_cap: int = 12;

    can start with Root entry {
        print("=== Recognition-preserving pre-ATN rule inlining (dry-run) ===");
        visit [-->];
        print("--- Eligibility manifest ---");
        for line in self.manifest {
            print(line);
        }
        print(f"--- Expansion budget used: {self.growth_used}/{self.growth_cap} body tokens ---");
    }

    can skip_lexer with LexerRule entry {
        self.manifest.append(
            f"DECLINE {here.name}: lexer rule (out of scope; order defines token priority)"
        );
        visit [-->];
    }

    can audit with ParserRule entry {
        decline_reason = "";
        if here.has_actions {
            decline_reason = "contains actions, predicates, or @init/@after blocks";
        } else {
            if here.has_labels {
                decline_reason = "alternative or element labels would rebind generated accessors";
            } else {
                if here.is_left_recursive or here.in_precedence {
                    decline_reason = "left-recursive or precedence-rule participant";
                } else {
                    checker = CycleChecker();
                    here spawn checker;
                    if checker.cyclic {
                        decline_reason = "acyclic constraint violated (direct or mutual recursion)";
                    }
                }
            }
        }
        if decline_reason != "" {
            self.manifest.append(f"DECLINE {here.name}: {decline_reason}");
        } else {
            if here.use_count != 1 {
                self.manifest.append(
                    f"DECLINE {here.name}: use_count={here.use_count} (requires single-use call site)"
                );
            } else {
                if not here.is_pure {
                    self.manifest.append(f"DECLINE {here.name}: not a pure structural parser rule");
                } else {
                    projected = self.growth_used + here.body_size;
                    if projected > self.growth_cap {
                        self.manifest.append(
                            f"DECLINE {here.name}: expansion cap exceeded ({projected}>{self.growth_cap})"
                        );
                    } else {
                        caller_label = here.sole_caller;
                        if caller_label == "" {
                            caller_label = "unknown";
                        }
                        self.manifest.append(
                            f"ACCEPT {here.name}: inline structurally at sole call site (tokens={here.body_size})"
                        );
                        self.manifest.append(
                            f"REWRITE {caller_label} -> ({here.name})  # parenthesized structural copy"
                        );
                        self.growth_used = projected;
                    }
                }
            }
        }
        visit [-->];
    }
}

with entry {
    id_unpack = ParserRule(
        name="identifiers_to_unpack", body_size=4, use_count=1, sole_caller="assignment"
    );
