"""Version-keyed cache staleness: a Set keyed at v1 can hold data that only reflects v0."""

node DepVersion {
    has namespace: str = "";
    has version: int = 0;
}

node CacheQuery {
    has query_hash: str = "";
}

node QueryExecution {
    has result_value: str = "";
}

node InvalidationWrite {
    has reason: str = "";
}

node CacheStore {
    has query_hash: str = "";
}

node CacheVerify {
    has label: str = "";
}

edge DependsOn { }
edge Invalidates { }

walker StalenessRace {
    has snapshot_version: int = 0;
    has current_version: int = 0;
    has query_value: str = "";
    has stored_key_version: int = 0;
    has snapped: bool = False;
    has bumped: bool = False;
    has stored: bool = False;

    can start with Root entry {
        visit [-->];
    }

    can on_miss with CacheQuery entry {
        if not self.snapped {
            self.snapped = True;
            visit [->:DependsOn:->];
        } else {
            print(f"[GET] miss for {here.query_hash}; dep snapshot v{self.snapshot_version}");
            visit [-->];
        }
    }

    can capture_snapshot with DepVersion entry {
        self.snapshot_version = here.version;
        print(f"[GET] QueryKey fold captured at v{self.snapshot_version}");
        visit [<--];
    }

    can on_exec with QueryExecution entry {
        self.query_value = here.result_value;
        print(f"[EXEC] result={self.query_value} (reflects writes through v{self.snapshot_version})");
        visit [-->];
    }

    can on_bump with InvalidationWrite entry {
        if not self.bumped {
            self.bumped = True;
            visit [->:Invalidates:->];
        } else {
            visit [-->];
        }
    }

    can apply_bump with DepVersion entry {
        here.version = here.version + 1;
        self.current_version = here.version;
        print(f"[INVALIDATE] {here.namespace} bumped v{self.snapshot_version} -> v{here.version}");
        visit [<--];
    }

    can on_store with CacheStore entry {
        if not self.stored {
            self.stored = True;
            visit [->:DependsOn:->];
        } else {
            visit [-->];
        }
    }

    can store_read_version with DepVersion entry {
        self.stored_key_version = here.version;
        stale_claim = self.stored_key_version > self.snapshot_version;
        verdict = "STALE KEY" if stale_claim else "consistent";
        print(f"[SET] filed result under key version v{self.stored_key_version} ({verdict})");
        print(f"      data reflects v{self.snapshot_version}, key claims v{self.stored_key_version}");
        visit [<--];
    }

    can on_verify with CacheVerify entry {
        stale_hit = self.stored_key_version > self.snapshot_version;
        status = "STALE HIT" if stale_hit else "fresh hit";
        print(f"[GET] HIT on v{self.stored_key_version} -> {self.query_value} ({status})");
        visit [-->];
    }
}

