"""LedgerLens hot paths as OSP: cycle-safe trade-flow SCC probe and Benford window digit audit."""

node Wallet {
    has label: str = "";
    has wallet_id: int = 0;
    has tarjan_idx: int = -1;
    has lowlink: int = -1;
}

node BenfordWindow {
    has horizon: str = "";
}

node LedgerEntry {
    has amount: float = 0.0;
}

edge TradeFlow {
    has notional: float = 0.0;
}

edge Windowed { }

def leading_digit(amount: float) -> int {
    if amount <= 0.0 {
        return 0;
    }
    text = str(int(abs(amount)));
    return int(text[0]);
}

walker TradeFlowProbe {
    has visited: list[int] = [];
    has active_path: list[int] = [];
    has stack: list[int] = [];
    has counter: int = 0;
    has cycle_detected: bool = False;
    has component_count: int = 0;
    has probes: int = 0;

    can start with Root entry {
        self.visited = [];
        self.active_path = [];
        self.stack = [];
        self.counter = 0;
        self.cycle_detected = False;
        self.component_count = 0;
        self.probes = 0;
        visit [-->];
        verdict = "CYCLIC" if self.cycle_detected else "ACYCLIC";
        print(
            f"[graph_engine] Tarjan-style probe done: {verdict}, "
            f"components={self.component_count}, probes={self.probes}"
        );
    }

    can explore with Wallet entry {
        wid = here.wallet_id;
        self.probes += 1;
        if wid in self.active_path {
            self.cycle_detected = True;
            print(f"[graph_engine] back-edge to {here.label} — SCC ring detected");
            disengage;
        }
        if wid in self.visited {
            visit [->:TradeFlow:->] else { disengage; };
            disengage;
        }
        here.tarjan_idx = self.counter;
        here.lowlink = self.counter;
        self.counter += 1;
        self.visited.append(wid);
        self.active_path.append(wid);
        self.stack.append(wid);
        print(f"[graph_engine] enter {here.label} idx={here.tarjan_idx}");
        visit [->:TradeFlow:->] else { disengage; };
        if here.lowlink == here.tarjan_idx {
            self.component_count += 1;
            members = [];
            while self.stack {
                popped = self.stack.pop();
                members.append(popped);
                if popped == wid {
                    break;
                }
            }
            print(f"[graph_engine] SCC #{self.component_count} ids={members}");
        }
        _ = self.active_path.pop();
    }
}

walker BenfordAuditor {
    has horizon: str = "";
    has digit_tally: list[int] = [0, 0, 0, 0, 0, 0, 0, 0, 0];

    can start with Root entry {
        visit [-->[?:BenfordWindow]];
    }

    can audit with BenfordWindow entry {
        self.horizon = here.horizon;
        self.digit_tally = [0, 0, 0, 0, 0, 0, 0, 0, 0];
        visit [->:Windowed:->] else { disengage; };
        total = 0;
        for tally in self.digit_tally {
            total += tally;
        }
        chi = 0.0;
        if total > 0 {
            for i in range(9) {
                observed = float(self.digit_tally[i]);
                expected = total * 0.301 if i == 0 else total * 0.176;
                if i == 1 {
                    expected = total * 0.125;
                } elif i == 2 {
                    expected = total * 0.097;
                } elif i == 3 {
                    expected = total * 0.079;
                } elif i == 4 {
                    expected = total * 0.067;
                } elif i == 5 {
                    expected = total * 0.058;
                } elif i == 6 {
                    expected = total * 0.051;
                } elif i == 7 {
                    expected = total * 0.046;
                } else {
                    expected = total * 0.042;
                }
                diff = observed - expected;
                chi += (diff * diff) / expected;
            }
        }
        print(
            f"[benford_engine] window={self.horizon} n={total} "
            f"tally={self.digit_tally} chi2={chi:.2f}"
        );
    }

    can tally with LedgerEntry entry {
        lead = leading_digit(here.amount);
        if lead >= 1 and lead <= 9 {
            self.digit_tally[lead - 1] += 1;
        }
    }
}

