"""Version-keyed cache staleness: Set keyed at v1 can hold data that only reflects v0."""

node DependencyNamespace {
    has namespace: str = "";
    has version: int = 0;
    has step: str = "";
}

node CacheQuery {
    has query_hash: str = "";
}

node QueryExecution {
    has result_value: str = "";
}

node InvalidationEvent {
    has reason: str = "";
}

node CacheStore {
    has query_hash: str = "";
}

node CacheVerify {
    has label: str = "";
}

edge DependsOn { }
edge Invalidates { }

walker StalenessRace {
    has snapshot_version: int = 0;
    has stored_key_version: int = 0;
    has query_value: str = "";
    has query_logged: bool = False;

    can start with Root entry {
        visit [-->];
    }

    can on_query with CacheQuery entry {
        if not self.query_logged {
            self.query_logged = True;
            print(f"[GET] miss for {here.query_hash}");
        }
        visit [->:DependsOn:->];
    }

    can on_dep with DependencyNamespace entry {
        if here.step == "snapshot" {
            self.snapshot_version = here.version;
            print(f"      QueryKey folded at v{self.snapshot_version}");
            visit [-->];
        } elif here.step == "bump" {
            bumped = here.version + 1;
            here.version = bumped;
            print(f"[INVALIDATE] {here.namespace} bumped to v{bumped}");
            visit [-->];
        } elif here.step == "store_key" {
            self.stored_key_version = here.version;
            verdict = "STALE KEY" if self.stored_key_version > self.snapshot_version else "consistent";
            print(f"[SET] filed result under v{self.stored_key_version} ({verdict})");
            print(f"      data reflects v{self.snapshot_version}, key claims v{self.stored_key_version}");
            visit [-->];
        } else {
            visit [-->];
        }
    }

    can on_exec with QueryExecution entry {
        self.query_value = here.result_value;
        print(f"[EXEC] result={self.query_value} (reflects writes through v{self.snapshot_version})");
        visit [-->];
    }

    can on_invalidate with InvalidationEvent entry {
        print(f"[INVALIDATE] {here.reason}");
        visit [->:Invalidates:->];
    }

    can on_store with CacheStore entry {
        visit [-->];
    }

    can on_verify with CacheVerify entry {
        stale_hit = self.stored_key_version > self.snapshot_version;
        status = "STALE HIT" if stale_hit else "fresh hit";
        print(f"[GET] HIT on v{self.stored_key_version} -> {self.query_value} ({status})");
        visit [-->] else { disengage; }
    }
}

