"""Objective decomposition and prerequisite closure over a pinned curriculum graph.

Models atomic teaching objectives, knowledge components, curriculum standards,
and misconceptions as graph nodes; prerequisite lineage and alignment claims as
typed edges; and walkers that replace hand-rolled adjacency recursion with
deterministic closure, cycle detection, and alignment classification.
"""

node ContentUnit {
    has unit_id: str = "";
    has title: str = "";
}

node Objective(ContentUnit) {
    has is_atomic: bool = False;
    has scope: str = "";
}

node KnowledgeComponent(ContentUnit) {
}

node CurriculumStandard {
    has standard_id: str = "";
    has title: str = "";
    has reviewed: bool = False;
}

node Misconception {
    has misconception_id: str = "";
    has description: str = "";
}

edge Requires {
    has status: str = "deferred";
}

edge PartOf {
}

edge AlignsTo {
    has alignment_type: str = "unsupported";
}

edge Covers {
}

edge Targets {
}

walker Decomposer {
    has depth: int = 0;
    has max_depth: int = 4;

    can start with Root entry {
        visit [-->];
    }

    can decompose with Objective entry {
        if here.is_atomic {
            indent = "  " * self.depth;
            print(f"{indent}[atomic] {here.unit_id}: {here.title}");
            visit [-->];
            return;
        }
        indent = "  " * self.depth;
        print(f"{indent}[broad]  {here.unit_id}: {here.title}");
        self.depth += 1;
        if self.depth > self.max_depth {
            print(f"{indent}  [scope] depth limit reached — hidden scope crossing blocked");
            self.depth -= 1;
            visit [-->];
            return;
        }
        visit [<--:PartOf:--] else {
            self.depth -= 1;
            visit [-->];
        };
    }
}

walker PrerequisiteAuditor {
    has target_id: str = "";
    has started: bool = False;
    has visited: list[str] = [];
    has active_path: list[str] = [];
    has closure: list[str] = [];
    has statuses: list[str] = [];
    has cycle_detected: bool = False;
    has cycle_nodes: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can audit with Objective entry {
        node_id = here.unit_id;
        if not self.started {
            if node_id != self.target_id {
                visit [-->];
                return;
            }
            self.started = True;
        }
        if node_id in self.active_path {
            self.cycle_detected = True;
            self.cycle_nodes = self.active_path + [node_id];
            print(f"[cycle] prerequisite loop detected: {' -> '.join(self.cycle_nodes)}");
            disengage;
        }
        if node_id not in self.visited {
            self.visited.append(node_id);
            self.closure.append(node_id);
        }
        self.active_path.append(node_id);
        visit [->:Requires:->] else {
            self.active_path.pop();
            if node_id == self.target_id {
                disengage;
            }
            return;
        };
        self.active_path.pop();
    }

    can record_status with Objective entry {
        for req in [<-:Requires:--] {
            edge_status = req[-->:Requires:-->].status;
            note = f"{req.unit_id} --({edge_status})--> {here.unit_id}";
            if note not in self.statuses {
                self.statuses.append(note);
            }
        }
    }
}

walker AlignmentResolver {
    has current_obj: str = "";

    can start with Root entry {
        visit [-->];
    }

    can resolve with Objective entry {
        if not here.is_atomic {
            visit [-->];
            return;
        }
        self.current_obj = here.unit_id;
        visit [->:AlignsTo:->] else {
            label = "unsupported";
            print(f"[{label}] {here.unit_id}: no pinned standard node");
            self.current_obj = "";
            visit [-->];
        };
    }

    can classify with CurriculumStandard entry {
        edge_label = "certified";
        for obj in [<-:AlignsTo:--] {
            claimed = obj[-->:AlignsTo:-->].alignment_type;
            if claimed == "generic" {
                edge_label = "generic";
            } elif claimed == "candidate" {
                edge_label = "candidate" if edge_label == "certified" else edge_label;
            }
        }
        if here.reviewed {
            final_label = edge_label if edge_label != "unsupported" else "certified";
        } else {
            final_label = "candidate" if edge_label != "generic" else "generic";
        }
        print(f"[{final_label}] {self.current_obj} -> {here.standard_id} ({here.title})");
        self.current_obj = "";
        visit [-->];
    }
}

walker MisconceptionScanner {
    can start with Root entry {
        visit [-->];
    }

    can scan with Objective | KnowledgeComponent entry {
        print(f"evidence scope: {here.unit_id} — {here.title}");
        visit [->:Targets:->] else {
            print(f"  (no attached misconceptions)");
            visit [-->];
        };
    }

    can report with Misconception entry {
        print(f"  misconception {here.misconception_id}: {here.description}");
        visit [-->];
    }
}

