        bitmap_prewhere_enabled=True
    );

  otel_old = OtelTracesTable(table_name="otel_traces");
    bloom = BloomIndex(index_name="idx_trace_id");
    otel_old +>:IndexedBy:+> bloom;

    g0 = Granule(granule_id=0, bloom_positive=True);
    g1 = Granule(granule_id=1, bloom_positive=False);
    g2 = Granule(granule_id=2, bloom_positive=True);
    bloom ++> g0 ++> g1 ++> g2;

    r00 = TraceRow(trace_id="abc123", part_offset=42, service_name="checkout");
    r01 = TraceRow(trace_id="xyz999", part_offset=43, service_name="search");
    r02 = TraceRow(trace_id="abc123", part_offset=44, service_name="checkout");
    r10 = TraceRow(trace_id="def456", part_offset=100, service_name="auth");
    r20 = TraceRow(trace_id="abc123", part_offset=200, service_name="payment");
