    r_b1 = TraceRow(trace_id="abc123", part_offset=44, service_name="checkout");
    r_b2 = TraceRow(trace_id="abc123", part_offset=200, service_name="payment");
    otel_new +>:StoresRow:+> r_b0;
    otel_new +>:StoresRow:+> r_b1;
    otel_new +>:StoresRow:+> r_b2;

    ch_new ++> otel_new;

    root ++> ch_old ++> ch_new;

