"""Multi-agent coordination overhead tracker: model team runs, agents, handoffs, and file overlap as a native graph walked by auditors."""

node TeamRun {
    has label: str = "";
    has agent_count: int = 0;
    has available: bool = True;
}

node Agent {
    has name: str = "";
    has active_ms: int = 0;
    has idle_ms: int = 0;
    has waiting_ms: int = 0;
    has conflict_ms: int = 0;
    has available: bool = True;
}

edge OnTeam { }

edge Handoff {
    has duration_ms: int = 0;
}

edge SharesFile {
    has filepath: str = "";
}

edge DependsOn { }

walker CoordinationAuditor {
    has run_label: str = "";
    has team_size: int = 0;
    has measured: list = [];
    has total_active: int = 0;
    has total_idle: int = 0;
    has total_waiting: int = 0;
    has total_conflict: int = 0;
    has total_handoff: int = 0;
    has overlap_count: int = 0;
    has recommendation: str = "";

    can start with Root entry {
        visit [-->];
    }

    can inspect_run with TeamRun entry {
        self.run_label = here.label;
        self.team_size = here.agent_count;
        visit [->:OnTeam:->] else { disengage; };
    }

    can inspect_agent with Agent entry {
        already = False;
        for prior in self.measured {
            if prior is here {
                already = True;
            }
        }
        if already {
            disengage;
        }
        self.measured.append(here);
        self.total_active += here.active_ms;
        self.total_idle += here.idle_ms;
        self.total_waiting += here.waiting_ms;
        self.total_conflict += here.conflict_ms;
        visit [->:Handoff:->];
        visit [->:SharesFile:->];
        visit [-->] else { disengage; };
    }

    can tally_handoff with Handoff entry {
        self.total_handoff += here.duration_ms;
        visit [-->] else { disengage; };
    }

    can tally_overlap with SharesFile entry {
        self.overlap_count += 1;
        visit [-->] else { disengage; };
    }

    can summarize with Root exit {
        total_ms = self.total_active + self.total_idle + self.total_waiting + self.total_conflict;
        coord_ms = self.total_waiting + self.total_handoff + self.total_conflict;
        ratio_pct = (coord_ms * 100.0 / total_ms) if total_ms > 0 else 0.0;
        print(f"Run {self.run_label}: coordination overhead {ratio_pct:.1f}%");
        print(
            f"  active={self.total_active} idle={self.total_idle} "
            f"waiting={self.total_waiting} conflict={self.total_conflict} "
            f"handoff={self.total_handoff} overlaps={self.overlap_count}"
        );
        rec = "hold current team size";
        if self.team_size > 3 and ratio_pct > 40.0 {
            rec = f"reduce from {self.team_size} to 2 agents";
        } elif self.overlap_count > 0 {
            rec = "split overlapping file assignments across agents";
        } elif ratio_pct > 50.0 and self.team_size >= 2 {
            rec = "use --worktree for isolated parallel edits";
        }
        self.recommendation = rec;
        print(f"  RECOMMEND: {self.recommendation}");
    }
}

walker DependencyChecker {
    has start_agent: Agent;
    has started: bool = False;
    has dep_path: list = [];
    has cycle_detected: bool = False;

    can start with Agent entry {
        if not self.started {
            if here is not self.start_agent {
                disengage;
            }
            self.started = True;
        } else {
            for prior in self.dep_path {
                if prior is here {
                    self.cycle_detected = True;
                    disengage;
                }
            }
        }
        self.dep_path.append(here);
        visit [->:DependsOn:->] else { disengage; };
    }

    can cross_dep with DependsOn entry {
        visit [-->] else { disengage; };
    }
}

with entry {
    run = TeamRun(label="shipwright-team-analyze", agent_count=4);
    alpha = Agent(name="alpha", active_ms=4200, idle_ms=600, waiting_ms=1100, conflict_ms=900);
    beta = Agent(name="beta", active_ms=3100, idle_ms=800, waiting_ms=2100, conflict_ms=1600);
    gamma = Agent(name="gamma", active_ms=2800, idle_ms=700, waiting_ms=1700, conflict_ms=500);
    delta = Agent(name="delta", active_ms=2200, idle_ms=900, waiting_ms=2400, conflict_ms=2100);

    root +>:OnTeam:+> run;
    run +>:OnTeam:+> alpha;
    run +>:OnTeam:+> beta;
    run +>:OnTeam:+> gamma;
    run +>:OnTeam:+> delta;

    alpha +>:Handoff(duration_ms=650):+> beta;
    beta +>:Handoff(duration_ms=480):+> gamma;
    gamma +>:Handoff(duration_ms=390):+> delta;
    alpha +>:SharesFile(filepath="src/shipwright/cli.py"):+> gamma;
    beta +>:SharesFile(filepath="src/shipwright/team.py"):+> delta;

    beta +>:DependsOn:+> alpha;
    gamma +>:DependsOn:+> beta;
    delta +>:DependsOn:+> gamma;
    beta +>:DependsOn:+> delta;

    auditor = CoordinationAuditor();
    checker = DependencyChecker(start_agent=beta);
    root spawn auditor;
    beta spawn checker;
    if checker.cycle_detected {
        print("  RECOMMEND: break circular task dependencies before next run");
    }
}

"""Task graph advance: bounded deterministic waves over a dependency DAG."""

node TaskHub {
    has label: str = "runtime-session";
}

node Subtask {
    has name: str = "";
    has status: str = "pending";
    has outcome: str = "";
    has intent_ok: bool = True;
    has scope_ok: bool = True;
    has blocked: bool = False;
    has changes_requested: bool = False;
}

edge DependsOn { }

walker DepChecker {
    has ready: bool = True;
    has first: bool = True;

    can check with Subtask entry {
        if self.first {
            self.first = False;
        } else {
            if here.status == "failed" {
                self.ready = False;
                disengage;
            }
            if here.status != "done" {
                self.ready = False;
                disengage;
            }
        }
        visit [->:DependsOn:->] else {
            disengage;
        }
    }
}

walker GraphAdvancer {
    has max_waves: int = 3;
    has max_concurrency: int = 2;
    has wave: int = 0;
    has phase: str = "plan";
    has stop_reason: str = "";
    has plans: list[str] = [];
    has selected: list[str] = [];
    has outcomes: list[str] = [];
    has dispatched: list[str] = [];
    has frontier_batch: list[str] = [];
    has visited_pass: list[str] = [];

    can start with Root entry {
        while self.wave < self.max_waves and self.stop_reason == "" {
            self.wave += 1;
            plan_name = f"wave-{self.wave}-plan";
            self.plans.append(plan_name);
            print(f"=== {plan_name} ===");
            self.phase = "plan";
            self.frontier_batch = [];
            self.visited_pass = [];
            visit [-->];
            if len(self.frontier_batch) == 0 {
                self.stop_reason = "no_frontier";
                disengage;
            }
            self.frontier_batch.sort();
            self.selected = [];
            for (i, pick) in enumerate(self.frontier_batch) {
                if i < self.max_concurrency {
                    self.selected.append(pick);
                }
            }
            print(f"frontier {self.frontier_batch} -> selected {self.selected}");
            self.phase = "execute";
            self.visited_pass = [];
            visit [-->];
            if self.stop_reason != "" {
                disengage;
            }
        }
        final_reason = self.stop_reason;
        if final_reason == "" {
            final_reason = "max_waves_reached";
            self.stop_reason = final_reason;
        }
        print(f"stop_reason={self.stop_reason}");
        print(f"plans={self.plans}");
        print(f"outcomes={self.outcomes}");
        print(f"dispatched={self.dispatched}");
    }

    can relay with TaskHub entry {
        visit [-->];
    }

    can advance with Subtask entry {
        if here.name in self.visited_pass {
            self.stop_reason = "cycle_detected";
            disengage;
        }
        self.visited_pass.append(here.name);
        if self.phase == "plan" {
            if here.status == "pending" and here.name not in self.dispatched {
                gate = DepChecker();
                here spawn gate;
                if gate.ready {
                    self.frontier_batch.append(here.name);
                }
            }
        } else {
            if here.name in self.selected {
                if not here.intent_ok {
                    self.stop_reason = "intent_conflict";
                    disengage;
                }
                if here.blocked {
                    self.stop_reason = "blocked_work";
                    disengage;
                }
                if here.changes_requested {
                    self.stop_reason = "changes_requested";
                    disengage;
                }
                if not here.scope_ok {
                    self.stop_reason = "scope_policy_failure";
                    disengage;
                }
                here.status = "done";
                run_outcome = "success";
                here.outcome = run_outcome;
                self.outcomes.append(f"{here.name}:{run_outcome}");
                self.dispatched.append(here.name);
                print(f"  executed {here.name} -> {run_outcome}");
            }
        }
        visit [-->];
    }
}

with entry {
    hub = TaskHub(label="healthy-session");
    fetch = Subtask(name="fetch");
    lint = Subtask(name="lint");
    test = Subtask(name="test");
    integrate = Subtask(name="integrate");
    release = Subtask(name="release");
    root ++> hub;
    hub ++> fetch;
    hub ++> lint;
    hub ++> test;
    hub ++> integrate;
    hub ++> release;
    lint +>:DependsOn:+> fetch;
    test +>:DependsOn:+> fetch;
    integrate +>:DependsOn:+> lint;
    integrate +>:DependsOn:+> test;
    release +>:DependsOn:+> integrate;
    root spawn GraphAdvancer(max_waves=3, max_concurrency=2);
}

