"""Trace-by-id lookup: bloom granule skipping vs exact _part_offset projection."""

node ClickHouseRelease {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has version: str = "24.8";
    has bitmap_prewhere_enabled: bool = False;

    def supports_part_offset_projection() -> bool {
        parts = self.version.split(".");
        major = int(parts[0]) if len(parts) > 0 else 0;
        minor = int(parts[1]) if len(parts) > 1 else 0;
        return (major > 25) or (major == 25 and minor >= 5);
    }

    def supports_bitmap_prewhere() -> bool {
        parts = self.version.split(".");
        major = int(parts[0]) if len(parts) > 0 else 0;
        minor = int(parts[1]) if len(parts) > 1 else 0;
        return (major > 25) or (major == 25 and minor >= 11);
    }
}

node OtelTracesTable {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has table_name: str = "otel_traces";
}

node BloomIndex {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has index_name: str = "idx_trace_id";
    has granularity: int = 8192;
}

node TraceProjection {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has projection_name: str = "proj_trace_id";
    has materialized: bool = False;
}

node TraceRow {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has trace_id: str = "";
    has part_offset: int = 0;
    has service_name: str = "";
}

node Granule {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has granule_id: int = 0;
    has bloom_positive: bool = True;
}

edge IndexedBy { }
edge ProjectionOn { }
edge StoresRow { }
edge ResolvesTo { }

walker SchemaBootstrap {
    has installed: int = 0;
    has skipped: int = 0;

    can start with Root entry {
        print("schemaboot: evaluating version-conditional DDL gates");
        visit [-->];
    }

    can gate_projection with ClickHouseRelease entry {
        if here.supports_part_offset_projection() {
            visit [->:ProjectionOn:->];
        } else {
            print(f"  SKIP proj_trace_id: ClickHouse {here.version} < 25.5");
            self.skipped += 1;
            visit [-->];
        }
    }

    can install_projection with OtelTracesTable entry {
        visit [->:ProjectionOn:->] else {
            visit [-->];
        };
    }

    can materialize with TraceProjection entry {
        if not here.materialized {
            here.materialized = True;
            self.installed += 1;
            print(f"  ADD PROJECTION {here.projection_name} "
                  f"(TraceId, _part_offset ORDER BY TraceId)");
        }
        visit [-->];
    }
}

walker TraceIdLookup {
    has target_trace_id: str = "";
    has rows_read: int = 0;
    has granules_scanned: int = 0;
    has lookup_path: str = "unknown";
    has visited_rows: list[str] = [];

    can start with Root entry {
        print(f"lookup: TraceId={self.target_trace_id}");
        visit [-->];
    }

    can choose_path with ClickHouseRelease entry {
        if here.supports_bitmap_prewhere() and here.bitmap_prewhere_enabled {
            self.lookup_path = "bitmap_prewhere";
            print(f"  path=bitmap PREWHERE (CH {here.version}, "
                  f"setting enabled)");
        } elif here.supports_part_offset_projection() {
            self.lookup_path = "part_offset_projection";
            print(f"  path=_part_offset projection (CH {here.version})");
        } else {
            self.lookup_path = "bloom_granule_skip";
            print(f"  path=bloom_filter granule skip (CH {here.version})");
        }
        visit [-->];
    }

    can scan_table with OtelTracesTable entry {
        if self.lookup_path == "part_offset_projection" {
            visit [->:ProjectionOn:->];
        } elif self.lookup_path == "bloom_granule_skip" {
            visit [->:IndexedBy:->];
        } else {
            visit [->:StoresRow:->];
        }
    }

    can probe_bloom with BloomIndex entry {
        print(f"  bloom probe {here.index_name} "
              f"(granularity={here.granularity})");
        visit [-->];
    }

    can skip_granules with Granule entry {
        self.granules_scanned += 1;
        if here.bloom_positive {
            print(f"    granule {here.granule_id}: bloom positive, "
                  f"scanning rows (may include false positives)");
            visit [->:StoresRow:->];
        } else {
            print(f"    granule {here.granule_id}: bloom negative, skip");
            visit [-->];
        }
    }

    can project_lookup with TraceProjection entry {
        if not here.materialized {
            print(f"  projection {here.projection_name} not materialized, "
                  f"falling back to primary");
            visit [-->];
        } else {
            print(f"  projection {here.projection_name}: exact row addressing");
            visit [->:ResolvesTo:->];
        }
    }

    can read_trace_row with TraceRow entry {
        if self.lookup_path == "part_offset_projection" {
            if here.trace_id == self.target_trace_id {
                self.rows_read += 1;
                hit = f"{here.trace_id}@{here.part_offset}";
                self.visited_rows.append(hit);
                print(f"    [PROJECTION] exact hit _part_offset={here.part_offset} "
                      f"service={here.service_name}");
            }
            visit [-->];
        } elif self.lookup_path == "bitmap_prewhere" {
            if here.trace_id == self.target_trace_id {
                self.rows_read += 1;
                hit = f"{here.trace_id}@{here.part_offset}";
                self.visited_rows.append(hit);
                print(f"    [BITMAP] exact hit _part_offset={here.part_offset} "
                      f"service={here.service_name}");
            }
            visit [-->];
        } else {
            self.rows_read += 1;
            if here.trace_id == self.target_trace_id {
