"""Build pipeline graph: dependency ordering, cycle detection, reachability, and priority pick."""

node BuildTask {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has priority: int = 0;
}

edge DependsOn {
    has weight: int = 1;
}

walker CycleGuard {
    has trail: list[str] = [];
    has has_cycle: bool = False;

    can start with Root entry {
        visit [-->];
    }

    can probe with BuildTask entry {
        if here.title in self.trail {
            self.has_cycle = True;
            disengage;
        }
        self.trail.append(here.title);
        visit [->:DependsOn:->] else { };
        if len(self.trail) > 0 {
            ignore = self.trail.pop();
        }
        visit [-->];
    }
}

walker TopoSort {
    has ordered: list[str] = [];
    has seen: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can emit with BuildTask entry {
        if here.title in self.seen {
            visit [-->];
        } else {
            visit [<-:DependsOn:<-] else { };
            self.seen.append(here.title);
            self.ordered.append(here.title);
            visit [-->];
        }
    }
}

walker ReachFinder {
    has goal: str = "";
    has reachable: bool = False;

    can start with BuildTask entry {
        if here.title == self.goal {
            self.reachable = True;
            disengage;
        }
        visit [<-:DependsOn:<-] else { disengage; };
    }
}

walker PriorityPick {
    has chosen: str = "";
    has best: int = -1;

    can start with Root entry {
        visit [-->];
    }

    can consider with BuildTask entry {
        if here.available {
            if here.priority > self.best {
                self.best = here.priority;
                self.chosen = here.title;
            }
        }
        visit [-->];
    }
}

walker HopMeasure {
    has target: str = "";
    has hops: int = 0;
    has shortest: int = -1;

    can start with BuildTask entry {
        if here.title == self.target {
            if self.shortest < 0 {
                self.shortest = self.hops;
            } else {
                if self.hops < self.shortest {
                    self.shortest = self.hops;
                }
            }
            disengage;
        }
        visit [<-:DependsOn:<-] else { disengage; };
    }

    can walk_edge with DependsOn entry {
        saved = self.hops;
        self.hops = saved + here.weight;
        visit [-->];
        self.hops = saved;
    }
}

with entry {
    parse = BuildTask(title="parse", priority=1, year=1);
    compile = BuildTask(title="compile", priority=3, year=2);
    link = BuildTask(title="link", priority=5, year=3);
    test = BuildTask(title="test", priority=2, year=4);
    root ++> parse ++> compile ++> link ++> test;
    compile +>:DependsOn:+> parse;
    link +>:DependsOn(weight=1):+> compile;
    link +>:DependsOn(weight=1):+> parse;
    test +>:DependsOn(weight=1):+> link;

    topo = TopoSort();
    root spawn topo;

    reach = ReachFinder(goal="parse");
    test spawn reach;

    picker = PriorityPick();
    root spawn picker;

    hops = HopMeasure(target="parse");
    test spawn hops;

    bad_a = BuildTask(title="bad_a", available=False);
    bad_b = BuildTask(title="bad_b", available=False);
    root ++> bad_a ++> bad_b;
    bad_a +>:DependsOn:+> bad_b;
    bad_b +>:DependsOn:+> bad_a;

    guard = CycleGuard();
    root spawn guard;
}

"""Agent parent-chain depth with cycle guards.

Models cadis agent_depth: walk ParentOf edges upward, count ancestors,
and halt safely when persisted parent references form a cycle or exceed
a depth cap — matching recover_agent_records cycle detection needs.
"""

node Agent {
    has agent_id: str = "";
    has title: str = "";
    has available: bool = True;
}

edge ParentOf { }

walker AgentDepthWalker {
    has depth: int = 0;
    has visited: list[str] = [];
    has max_depth: int = 100;
    has cycle_detected: bool = False;
    has at_origin: bool = True;

    def seen(agent_id: str) -> bool {
        for vid in self.visited {
            if vid == agent_id {
                return True;
            }
        }
        return False;
    }

    can measure with Agent entry {
        if self.seen(here.agent_id) {
            print(
                f"WARNING: parent-chain cycle detected at agent {here.agent_id}"
            );
            self.cycle_detected = True;
            disengage;
        }
        self.visited.append(here.agent_id);
        if self.at_origin {
            self.at_origin = False;
        } else {
            self.depth += 1;
            if self.depth >= self.max_depth {
                print(
                    f"WARNING: agent_depth capped at {self.max_depth} "
                    f"near agent {here.agent_id}"
                );
                disengage;
            }
        }
        visit [->:ParentOf:->] else { disengage; }
    }
}

walker StateRecoverer {
    has recovered: int = 0;
    has cycle_count: int = 0;

    can start with Root entry {
        print("recover_agent_records: scanning persisted agents");
        visit [-->];
    }

    can recover with Agent entry {
        probe = AgentDepthWalker(max_depth=100);
        here spawn probe;
        if probe.cycle_detected {
            self.cycle_count += 1;
            print(
                f"WARNING: recover rejected cyclic chain rooted at "
                f"{here.agent_id}"
            );
        } else {
            self.recovered += 1;
            print(
                f"OK: agent {here.agent_id} parent depth = {probe.depth}"
            );
        }
        visit [-->];
    }
}

with entry {
    alpha = Agent(agent_id="alpha", title="Root Agent");
    beta = Agent(agent_id="beta", title="Mid Agent");
    gamma = Agent(agent_id="gamma", title="Leaf Agent");
    gamma +>:ParentOf:+> beta;
    beta +>:ParentOf:+> alpha;

    agent_a = Agent(agent_id="agent_a", title="Cyclic A");
    agent_b = Agent(agent_id="agent_b", title="Cyclic B");
    agent_a +>:ParentOf:+> agent_b;
    agent_b +>:ParentOf:+> agent_a;

    root ++> gamma;
    root ++> agent_a;

    print("--- agent_depth on healthy parent chain ---");
    healthy = AgentDepthWalker(max_depth=100);
    gamma spawn healthy;
    print(f"agent_depth(gamma) = {healthy.depth}");

    print("--- agent_depth on cyclic chain (must not hang) ---");
    cyclic = AgentDepthWalker(max_depth=100);
    agent_a spawn cyclic;
    halted = "yes" if cyclic.cycle_detected else "no";
    print(
