    print("--- recover_agent_records sweep ---");
    root spawn StateRecoverer();
}

"""Multi-agent coordination overhead tracker: model team runs, agents, handoffs, and file overlap as a native graph walked by auditors."""

node TeamRun {
    has label: str = "";
    has agent_count: int = 0;
    has available: bool = True;
}

node Agent {
    has name: str = "";
    has active_ms: int = 0;
    has idle_ms: int = 0;
    has waiting_ms: int = 0;
    has conflict_ms: int = 0;
    has available: bool = True;
}

node TaskHandoff {
    has duration_ms: int = 0;
    has available: bool = True;
}

node FileOverlap {
    has filepath: str = "";
    has available: bool = True;
}

edge OnTeam { }

edge SharesPath { }

edge Blocks { }

walker CoordinationAuditor {
    has run_label: str = "";
    has team_size: int = 0;
    has total_active: int = 0;
    has total_idle: int = 0;
    has total_waiting: int = 0;
    has total_conflict: int = 0;
    has total_handoff: int = 0;
    has overlap_count: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can inspect_run with TeamRun entry {
        self.run_label = here.label;
        self.team_size = here.agent_count;
        visit [->:OnTeam:->];
        visit [-->];
    }

    can inspect_agent with Agent entry {
        self.total_active += here.active_ms;
        self.total_idle += here.idle_ms;
        self.total_waiting += here.waiting_ms;
        self.total_conflict += here.conflict_ms;
        visit [->:SharesPath:->];
        visit [-->];
    }

    can inspect_handoff with TaskHandoff entry {
        self.total_handoff += here.duration_ms;
        visit [-->];
    }

    can inspect_overlap with FileOverlap entry {
        self.overlap_count += 1;
    }
}

walker DependencyChecker {
    has origin: Agent;
    has on_path: list[Agent] = [];
    has cycle_detected: bool = False;
    has seeded: bool = False;

    can start with Agent entry {
        if not self.seeded {
            if here is not self.origin {
                disengage;
            }
            self.seeded = True;
        } else {
            for prior in self.on_path {
                if prior is here {
                    self.cycle_detected = True;
                    disengage;
                }
            }
        }
        self.on_path.append(here);
        visit [->:Blocks:->] else { disengage; };
    }
}

with entry {
    run = TeamRun(label="shipwright-team-analyze", agent_count=4);
    alpha = Agent(name="alpha", active_ms=4200, idle_ms=600, waiting_ms=1100, conflict_ms=900);
    beta = Agent(name="beta", active_ms=3100, idle_ms=800, waiting_ms=2100, conflict_ms=1600);
    gamma = Agent(name="gamma", active_ms=2800, idle_ms=700, waiting_ms=1700, conflict_ms=500);
    delta = Agent(name="delta", active_ms=2200, idle_ms=900, waiting_ms=2400, conflict_ms=2100);

    h_ab = TaskHandoff(duration_ms=650);
    h_bg = TaskHandoff(duration_ms=480);
    h_gd = TaskHandoff(duration_ms=390);
    overlap_cli = FileOverlap(filepath="src/shipwright/cli.py");
    overlap_team = FileOverlap(filepath="src/shipwright/team.py");

    root ++> run;
    run +>:OnTeam:+> alpha;
    run +>:OnTeam:+> beta;
    run +>:OnTeam:+> gamma;
    run +>:OnTeam:+> delta;
    run ++> h_ab ++> h_bg ++> h_gd;

    alpha +>:SharesPath:+> overlap_cli;
    gamma +>:SharesPath:+> overlap_cli;
    beta +>:SharesPath:+> overlap_team;
    delta +>:SharesPath:+> overlap_team;

    beta +>:Blocks:+> alpha;
    gamma +>:Blocks:+> beta;
    delta +>:Blocks:+> gamma;
    beta +>:Blocks:+> delta;

    auditor = CoordinationAuditor();
    root spawn auditor;

    total_ms = (
        auditor.total_active + auditor.total_idle
        + auditor.total_waiting + auditor.total_conflict
    );
    coord_ms = auditor.total_waiting + auditor.total_handoff + auditor.total_conflict;
    ratio_pct = (coord_ms * 100.0 / total_ms) if total_ms > 0 else 0.0;

    print(f"Run {auditor.run_label}: coordination overhead {ratio_pct:.1f}%");
    print(
        f"  active={auditor.total_active} idle={auditor.total_idle} "
        f"waiting={auditor.total_waiting} conflict={auditor.total_conflict} "
        f"handoff={auditor.total_handoff} overlaps={auditor.overlap_count}"
    );

    rec = "hold current team size";
    if auditor.team_size > 3 and ratio_pct > 40.0 {
        rec = f"reduce from {auditor.team_size} to 2 agents";
    } elif auditor.overlap_count > 0 {
        rec = "split overlapping file assignments across agents";
    } elif ratio_pct > 50.0 and auditor.team_size >= 2 {
        rec = "use --worktree for isolated parallel edits";
    }
    print(f"  RECOMMEND: {rec}");

    checker = DependencyChecker(origin=beta);
    beta spawn checker;
    if checker.cycle_detected {
        print("  RECOMMEND: break circular task dependencies before next run");
    }
}

