"""Build pipeline graph: dependency ordering, cycle detection, reachability, and priority pick."""

node BuildTask {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has priority: int = 0;
}

edge DependsOn {
    has weight: int = 1;
}

walker CycleGuard {
    has trail: list[str] = [];
    has visited: list[str] = [];
    has has_cycle: bool = False;

    can start with Root entry {
        visit [-->];
    }

    can probe with BuildTask entry {
        if here.title in self.visited {
            visit [-->];
        } else {
            if here.title in self.trail {
                self.has_cycle = True;
                disengage;
            }
            self.visited.append(here.title);
            self.trail.append(here.title);
            visit [->:DependsOn:->] else { };
            if len(self.trail) > 0 {
                ignore = self.trail.pop();
            }
            visit [-->];
        }
    }
}

walker TopoSort {
    has ordered: list[str] = [];
    has done: list[str] = [];
    has stack: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can emit with BuildTask entry {
        if here.title in self.done {
            visit [-->];
        } else {
            if here.title in self.stack {
                disengage;
            }
            self.stack.append(here.title);
            visit [->:DependsOn:->] else { };
            if len(self.stack) > 0 {
                ignore = self.stack.pop();
            }
            self.done.append(here.title);
            self.ordered.append(here.title);
            visit [-->];
        }
    }
}

walker ReachFinder {
    has goal: str = "";
    has reachable: bool = False;
    has visited: list[str] = [];

    can start with BuildTask entry {
        if here.title in self.visited {
            disengage;
        }
        self.visited.append(here.title);
        if here.title == self.goal {
            self.reachable = True;
            disengage;
        }
        visit [->:DependsOn:->] else { disengage; };
    }
}

walker PriorityPick {
    has chosen: str = "";
    has best: int = -1;
    has visited: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can consider with BuildTask entry {
        if here.title in self.visited {
            visit [-->];
        } else {
            self.visited.append(here.title);
            if here.available {
                if here.priority > self.best {
                    self.best = here.priority;
                    self.chosen = here.title;
                }
            }
            visit [-->];
        }
    }
}

walker HopMeasure {
    has target: str = "";
    has hops: int = 0;
    has shortest: int = -1;
    has visited: list[str] = [];

    can start with BuildTask entry {
        if here.title in self.visited {
            disengage;
        }
        self.visited.append(here.title);
        if here.title == self.target {
            if self.shortest < 0 {
                self.shortest = self.hops;
            } else {
                if self.hops < self.shortest {
                    self.shortest = self.hops;
                }
            }
            disengage;
        }
        saved = self.hops;
        self.hops = saved + 1;
        visit [->:DependsOn:->] else { disengage; };
        self.hops = saved;
    }
}

with entry {
    parse = BuildTask(title="parse", priority=1, year=1);
    compile = BuildTask(title="compile", priority=3, year=2);
    link = BuildTask(title="link", priority=5, year=3);
    test = BuildTask(title="test", priority=2, year=4);
    root ++> parse ++> compile ++> link ++> test;
    compile +>:DependsOn:+> parse;
    link +>:DependsOn(weight=1):+> compile;
    link +>:DependsOn(weight=1):+> parse;
    test +>:DependsOn(weight=1):+> link;

    topo = TopoSort();
    root spawn topo;

    reach = ReachFinder(goal="parse");
    test spawn reach;

    picker = PriorityPick();
    root spawn picker;

    hops = HopMeasure(target="parse");
    test spawn hops;

    bad_a = BuildTask(title="bad_a", available=False);
    bad_b = BuildTask(title="bad_b", available=False);
    root ++> bad_a ++> bad_b;
    bad_a +>:DependsOn:+> bad_b;
    bad_b +>:DependsOn:+> bad_a;

    guard = CycleGuard();
    root spawn guard;
}

"""Git checkout: preflight a verified commit tree, reject hostile paths and modes, then materialize blobs into staging."""

def list_contains(items: list[str], needle: str) -> bool {
    for item in items {
        if item == needle {
            return True;
        }
    }
    return False;
}

def path_is_hostile(name: str) -> bool {
    if name == "" or name == "." or name == ".." {
        return True;
    }
    if "/" in name or "\\" in name {
        return True;
    }
  if "\x00" in name {
        return True;
    }
    lowered = name.lower();
    if lowered == ".git" or lowered.startswith(".git") {
        return True;
    }
    if lowered == "con" or lowered == "pro" or lowered == "aux" {
        return True;
    }
    if name.endswith(".") or name.endswith(" ") {
        return True;
    }
    return False;
}

def mode_is_rejected(mode: int) -> bool {
    if mode == 120000 or mode == 160000 {
        return True;
    }
    if mode == 100644 or mode == 100755 or mode == 40000 {
        return False;
    }
    return True;
}

node GitObject {
    has object_id: str = "";
    has git_mode: int = 0;
}

node Blob(GitObject) {
    has payload: str = "";
    has byte_len: int = 0;
}

node Tree(GitObject) {
    has tree_label: str = "";
}

node Entry {
    has entry_name: str = "";
    has entry_mode: int = 100644;
}

node StagingDir {
    has staging_id: str = "";
}

edge StagedUnder { }
edge Contained { }

walker CheckoutPreflight {
    has visited_ids: list[str] = [];
    has seen_paths: list[str] = [];
    has violations: list[str] = [];
    has inventory: list[str] = [];
    has depth: int = 0;
    has max_depth: int = 64;
    has rel_prefix: str = "";

    can start with Root entry {
        visit [-->] else { disengage; };
    }

    can open_staging with StagingDir entry {
        print(f"preflight staging {here.staging_id}");
        visit [->:StagedUnder:->] else { disengage; };
    }

    can walk_tree with Tree entry {
        oid = here.object_id;
        if list_contains(self.visited_ids, oid) {
            msg = f"cycle at tree {oid}";
            self.violations = self.violations + [msg];
            disengage;
        }
        self.visited_ids = self.visited_ids + [oid];
        if self.depth > self.max_depth {
            msg = f"depth cap at {oid}";
            self.violations = self.violations + [msg];
            disengage;
        }
        self.depth += 1;
        visit [->:Contained:->] else { disengage; };
        self.depth -= 1;
    }

    can audit_entry with Entry entry {
        name = here.entry_name;
        mode = here.entry_mode;
        full = name;
        if self.rel_prefix != "" {
            full = f"{self.rel_prefix}/{name}";
        }
        if path_is_hostile(name) {
            msg = f"hostile path component: {full}";
            self.violations = self.violations + [msg];
        }
        if mode_is_rejected(mode) {
            msg = f"rejected mode {mode}: {full}";
            self.violations = self.violations + [msg];
            visit [-->] else { disengage; };
        }
        if list_contains(self.seen_paths, full) {
            msg = f"duplicate destination: {full}";
            self.violations = self.violations + [msg];
        }
        self.seen_paths = self.seen_paths + [full];
        old_prefix = self.rel_prefix;
        self.rel_prefix = full;
        visit [->:Contained:->] else { disengage; };
        self.rel_prefix = old_prefix;
    }

    can scan_blob with Blob entry {
        oid = here.object_id;
        row = f"{full}|{here.git_mode}|blob|{oid}|{here.byte_len}";
        row = f"{self.rel_prefix}|{here.git_mode}|blob|{oid}|{here.byte_len}";
        self.inventory = self.inventory + [row];
        visit [-->] else { disengage; };
    }
}

walker CheckoutMaterialize {
    has write_log: list[str] = [];
    has rel_prefix: str = "";
    has allowed: bool = False;

    can start with Root entry {
        if not self.allowed {
            disengage;
        }
        visit [-->] else { disengage; };
    }

    can open_staging with StagingDir entry {
        visit [->:StagedUnder:->] else { disengage; };
    }

    can walk_tree with Tree entry {
        visit [->:Contained:->] else { disengage; };
    }

    can descend_entry with Entry entry {
        name = here.entry_name;
        full = name;
        if self.rel_prefix != "" {
            full = f"{self.rel_prefix}/{name}";
        }
        old_prefix = self.rel_prefix;
        self.rel_prefix = full;
        visit [->:Contained:->] else { disengage; };
        self.rel_prefix = old_prefix;
    }

    can write_blob with Blob entry {
        msg = f"MATERIALIZE {self.rel_prefix} <- {here.object_id} ({here.byte_len}b)";
        self.write_log = self.write_log + [msg];
        visit [-->] else { disengage; };
    }
}

with entry {
    staging = StagingDir(staging_id="stage-7a2f");
    root ++> staging;

    readme = Blob(object_id="blob_readme", git_mode=100644, payload="hello", byte_len=5);
    main_rs = Blob(object_id="blob_main", git_mode=100755, payload="fn main(){}", byte_len=10);
    src_tree = Tree(object_id="tree_src", git_mode=40000, tree_label="src");
    root_tree = Tree(object_id="tree_root", git_mode=40000, tree_label="commit");

    staging +>:StagedUnder:+> root_tree;
    root_tree +>:Contained:+> (e_readme := Entry(entry_name="README", entry_mode=100644));
    e_readme +>:Contained:+> readme;
    root_tree +>:Contained:+> (e_src := Entry(entry_name="src", entry_mode=40000));
    e_src +>:Contained:+> src_tree;
    src_tree +>:Contained:+> (e_main := Entry(entry_name="main.rs", entry_mode=100755));
    e_main +>:Contained:+> main_rs;
    root_tree +>:Contained:+> (e_link := Entry(entry_name="escape", entry_mode=120000));

    pre = CheckoutPreflight();
    root spawn pre;

    print(f"violations ({len(pre.violations)}):");
    for v in pre.violations {
