    }
    print(f"inventory ({len(pre.inventory)}):");
    for row in pre.inventory {
        print(f"  {row}");
    }

    if pre.violations == [] {
        mat = CheckoutMaterialize(allowed=True);
        root spawn mat;
        print(f"writes ({len(mat.write_log)}):");
        for w in mat.write_log {
            print(f"  {w}");
        }
    } else {
        print("checkout blocked — no files materialized");
    }
}

"""TPG composition audit: Objects own Layers and Keyframes; walkers traverse the graph to enforce animation complexity caps before moderation."""

node Object {
    has title: str = "";
    has is_animation: bool = False;
    has published: bool = False;
    has fps: int = 12;
}

node Layer {
    has name: str = "";
    has opacity: float = 1.0;
    has visible: bool = True;
}

node Keyframe {
    has time_ms: int = 0;
    has duration_ms: int = 100;
    has hold: bool = False;
}

edge HasLayer {
    has z_order: int = 0;
}

edge HasKeyframe { }

walker CompositionAuditor {
    has active_title: str = "";
    has layer_count: int = 0;
    has keyframe_count: int = 0;
    has timeline_ms: int = 0;
    has max_layers: int = 8;
    has max_keyframes: int = 64;

    can start with Root entry {
        visit [-->];
    }

    can inspect_object with Object entry {
        self.active_title = here.title;
        self.layer_count = 0;
        self.keyframe_count = 0;
        self.timeline_ms = 0;
        visit [->:HasLayer:->] else { disengage; };
        over_layers = self.layer_count > self.max_layers;
        over_frames = self.keyframe_count > self.max_keyframes;
        verdict = "REJECT" if (over_layers or over_frames) else "APPROVE";
        gate = "BLOCKED" if (over_layers or over_frames) else ("LIVE" if here.published else "MODERATION");
        kind = "animation" if here.is_animation else "static";
        print(
            f"[{verdict}] '{self.active_title}' ({kind}, {gate}) — "
            f"layers {self.layer_count}/{self.max_layers}, "
            f"keyframes {self.keyframe_count}/{self.max_keyframes}, "
            f"timeline {self.timeline_ms}ms @ {here.fps}fps"
        );
    }

    can scan_layer with Layer entry {
        if here.visible {
            self.layer_count += 1;
        }
        visit [->:HasKeyframe:->] else { disengage; };
    }

    can measure_keyframe with Keyframe entry {
        self.keyframe_count += 1;
        end_ms = here.time_ms + here.duration_ms;
        next_timeline = end_ms if end_ms > self.timeline_ms else self.timeline_ms;
        self.timeline_ms = next_timeline;
        visit [-->];
    }
}

with entry {
    sunrise = Object(title="Sunrise Moment", is_animation=True, published=True, fps=24);
    root ++> sunrise;
    sky = Layer(name="Sky");
    sun = Layer(name="Sun");
    foreground = Layer(name="Foreground");
    sunrise +>:HasLayer(z_order=0):+> sky;
    sunrise +>:HasLayer(z_order=1):+> sun;
    sunrise +>:HasLayer(z_order=2):+> foreground;
