"""Rehype HAST transform: stack-safe walker descent replaces recursive parent traversal."""

node HastElement {
    has tag: str = "div";
    has level: int = 0;
    has should_skip: bool = False;
}

node HastText {
    has source: str = "";
    has value: str = "";
    has covered: bool = False;
}

edge Child { }

walker RehypeTransform {
    has depth: int = 0;
    has max_depth: int = 0;
    has visited: int = 0;
    has covered_count: int = 0;

    can start with Root entry {
        print("rehype: stack-safe parent transform begin");
        visit [->:Child:->] else { disengage; };
    }

    can transform_parent with HastElement entry {
        self.depth += 1;
        if self.depth > self.max_depth {
            self.max_depth = self.depth;
        }
        self.visited += 1;
        if here.should_skip {
            print(f"[skip] <{here.tag}> subtree ignored");
            disengage;
        }
        visit [->:Child:->] else { disengage; };
    }

    can leave_element with HastElement exit {
        self.depth -= 1;
    }

    can cover_text with HastText entry {
        self.visited += 1;
        if here.covered {
            print(f"[idempotent] leaf already covered; source kept: {here.source}");
            disengage;
        }
        is_profane = False;
        if "damn" in here.value {
            is_profane = True;
        }
        if is_profane {
            preserved = here.source;
            here.value = "[covered]";
            here.covered = True;
            self.covered_count += 1;
            print(f"[cover] masked profanity; source preserved: {preserved}");
        } else {
            print(f"[text] {here.value}");
        }
        disengage;
    }
}

