    transformer = RehypeTransform();
    root spawn transformer;
    print(
        f"pass 2 (idempotent): visited={transformer.visited} covered={transformer.covered_count} "
        f"leaf still={deep_leaf.value} source still={deep_leaf.source}"
    );
}

