"""Hadolint CI gate: path filters that never self-trigger and a literal glob dockerfile arg."""

node Repository {
    has name: str = "";
}

node Workflow {
    has name: str = "";
    has workflow_path: str = "";
    has dockerfile_arg: str = "";
    has use_recursive: bool = False;
}

node Dockerfile {
    has path: str = "";
    has linted: bool = False;
}

node PathPattern {
    has glob: str = "";

    def matches(target: str) -> bool {
        if self.glob == "**/Dockerfile" {
            return target == "Dockerfile" or target.endswith("/Dockerfile");
        }
        if self.glob == "**/Dockerfile.*" {
            return "Dockerfile." in target;
        }
        if self.glob == "**/.hadolint.yaml" {
            return target.endswith(".hadolint.yaml");
        }
        return target == self.glob;
    }
}

edge Contains { }
edge TriggersOn { }

walker TriggerAuditor {
    has ci_file: str = ".github/workflows/hadolint.yml";
    has self_edit_triggers: bool = False;

    can start with Root entry {
        visit [-->];
    }

    can bridge with Repository entry {
        visit [-->];
    }

    can audit with Workflow entry {
        visit [->:TriggersOn:->];
        if not self.self_edit_triggers {
            print(
                f"[FILTER] '{here.name}' path filters never match "
                f"{self.ci_file}, so workflow edits produce zero runs"
            );
        }
        disengage;
    }

    can scan with PathPattern entry {
        if here.matches(self.ci_file) {
            self.self_edit_triggers = True;
        }
    }
}

walker LiteralGlobLinter {
    has literal: str = "";
    has found: bool = False;

    can start with Root entry {
        visit [-->];
    }

    can bridge with Repository entry {
        visit [-->];
    }

    can bind with Workflow entry {
        self.literal = here.dockerfile_arg;
        visit [<--];
    }

    can scan with Repository entry {
        visit [->:Contains:->];
        if not self.found {
            print(
                f"hadolint: {self.literal}: does not exist "
                f"(No such file or directory)"
            );
        }
        disengage;
    }

    can probe with Dockerfile entry {
        if here.path == self.literal {
            self.found = True;
            here.linted = True;
            print(f"[LINT] {here.path}");
        }
        visit [-->];
    }
}

walker RecursiveLinter {
    can walk with Repository entry {
        visit [->:Contains:->] else { disengage; };
    }

    can lint with Dockerfile entry {
        here.linted = True;
        print(f"[LINT] {here.path}");
        visit [->:Contains:->] else { disengage; };
    }
}

with entry {
    repo = Repository(name="nchat");
    wf = Workflow(
        name="hadolint",
        workflow_path=".github/workflows/hadolint.yml",
        dockerfile_arg="**/Dockerfile",
        use_recursive=False
    );
    df_root = Dockerfile(path="Dockerfile");
    df_web = Dockerfile(path="frontend/Dockerfile");

    root ++> repo;
    repo ++> wf;
    repo ++> df_root;
    repo ++> df_web;

    wf +>:TriggersOn:+> PathPattern(glob="**/Dockerfile");
    wf +>:TriggersOn:+> PathPattern(glob="**/Dockerfile.*");
    wf +>:TriggersOn:+> PathPattern(glob="**/.hadolint.yaml");

    print("=== path filter audit ===");
    root spawn TriggerAuditor();

    print("=== broken literal glob invocation ===");
    root spawn LiteralGlobLinter();

    print("=== fixed recursive tree walk (recursive: true) ===");
    wf.use_recursive = True;
    repo spawn RecursiveLinter();
}

"""Subagent topology and usage attribution: model parent-child delegation, lifecycle facets, and descendant-inclusive token rollup."""

node Session {
    has session_id: str = "";
    has title: str = "";
    has direct_tokens: int = 0;
    has lifecycle: str = "running";
    has topology_facet: str = "Pending";
    has available: bool = True;
}

edge Delegation {
    has spawned_at: str = "";
}

walker TopologyAuditor {
    has visited_ids: list[str] = [];
    has child_sums: list[int] = [];

    can start with Root entry {
        visit [-->];
    }

    can attribute with Session entry {
        if here.session_id in self.visited_ids {
            print(f"[CYCLE] delegation loop at {here.session_id}");
            disengage;
        }
        self.visited_ids.append(here.session_id);
        self.child_sums.append(0);
        visit [->:Delegation:->] else { };
    }

    can attribute with Session exit {
        child_total = self.child_sums.pop();
        attributed = here.direct_tokens + child_total;
        if self.child_sums {
            parent_slot = len(self.child_sums) - 1;
            self.child_sums[parent_slot] += attributed;
        }
        scope = "descendant-inclusive" if attributed > here.direct_tokens else "direct-only";
        print(
            f"[{here.topology_facet}] {here.session_id} {here.title} "
            f"lifecycle={here.lifecycle} direct={here.direct_tokens} "
            f"attributed={attributed} ({scope})"
        );
    }
}

