}

"""Comment import: same-thread parent cycles bypass guards and never render."""

node Comment {
    has source_id: str = "";
    has thread_source_id: str = "";
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has depth: int = 0;
    has re_rooted: bool = False;
    has rendered: bool = False;
}

node Thread {
    has title: str = "";
    has thread_source_id: str = "";
    has year: int = 0;
    has available: bool = True;
}

edge ParentOf { }
edge InThread { }

walker ParentPeek {
    has has_parent: bool = False;

    can start with Comment entry {
        visit [->:ParentOf:->] else { disengage; };
    }

    can peek with Comment entry {
        self.has_parent = True;
        disengage;
    }
}

walker CycleProbe {
    has seen: list[str] = [];
    has hit_cycle: bool = False;

    can start with Comment entry {
        sid = here.source_id;
        if sid in self.seen {
            self.hit_cycle = True;
            disengage;
        }
        self.seen.append(sid);
        visit [->:ParentOf:->] else { disengage; };
    }

    can ascend with Comment entry {
        sid = here.source_id;
        if sid in self.seen {
            self.hit_cycle = True;
            disengage;
        }
        self.seen.append(sid);
        visit [->:ParentOf:->] else { disengage; };
    }
}

walker DelParent {
    has child: Comment;

    can start with Comment entry {
        self.child = here;
        visit [->:ParentOf:->] else { disengage; };
    }

    can sever with Comment entry {
        self.child del ->:ParentOf:-> here;
        disengage;
    }
}

walker DepthOf {
    has seen: list[str] = [];
    has depth: int = 0;

    can start with Comment entry {
        sid = here.source_id;
        self.seen.append(sid);
        visit [->:ParentOf:->] else { disengage; };
    }

    can measure with Comment entry {
        sid = here.source_id;
        if sid in self.seen {
            self.depth = 1;
            disengage;
        }
        self.seen.append(sid);
        self.depth += 1;
        visit [->:ParentOf:->] else { disengage; };
    }
}

walker FeedTally {
    has total: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can scan with Thread entry {
        visit [->:InThread:->];
        visit [-->];
    }

    can count with Comment entry {
        self.total += 1;
        visit [-->];
    }
}

walker PageRenderer {
    has rendered: int = 0;

    can start with Root entry {
        print("Page render from roots (recursive CTE walk)");
        visit [-->];
    }

    can enter with Thread entry {
        visit [->:InThread:->];
        visit [-->];
    }

    can seek_roots with Comment entry {
        peek = ParentPeek();
        here spawn peek;
        if not peek.has_parent {
            visit [<-:ParentOf:<-];
        }
        visit [-->];
    }

    can paint with Comment entry {
        here.rendered = True;
        self.rendered += 1;
        print(f"  [page] {here.title} (depth {here.depth})");
        visit [<-:ParentOf:<-] else { disengage; };
    }
}

walker CycleReRooter {
    has rerooted: int = 0;

    can start with Root entry {
        print("Import: scanning parent chains for same-thread cycles");
        visit [-->];
    }

    can walk_threads with Thread entry {
        visit [->:InThread:->];
        visit [-->];
    }

    can screen with Comment entry {
        probe = CycleProbe();
        here spawn probe;
        if probe.hit_cycle {
            cutter = DelParent();
            here spawn cutter;
            here.re_rooted = True;
            print(f"  reroot {here.source_id} (cycle detected)");
            self.rerooted += 1;
        }
        depth_walk = DepthOf();
        here spawn depth_walk;
        here.depth = depth_walk.depth;
        visit [-->];
    }
}

with entry {
    t = Thread(
        title="KingPin thread",
        thread_source_id="thread-1",
        year=2026,
    );
    root ++> t;

    a = Comment(
        source_id="cmt-A",
        thread_source_id="thread-1",
        title="Alpha reply",
        year=1,
    );
    b = Comment(
        source_id="cmt-B",
        thread_source_id="thread-1",
        title="Beta reply",
        year=2,
    );
    d = Comment(
        source_id="cmt-D",
        thread_source_id="thread-1",
        title="Delta root",
        year=4,
    );
    c = Comment(
        source_id="cmt-C",
        thread_source_id="thread-1",
        title="Gamma child",
        year=3,
    );

    t +>:InThread:+> a;
    t +>:InThread:+> b;
    t +>:InThread:+> d;
    t +>:InThread:+> c;

    a +>:ParentOf:+> b;
    b +>:ParentOf:+> a;

    c +>:ParentOf:+> d;

    feed = FeedTally();
    root spawn feed;
    print(f"RSS feed counts {feed.total} comments");

