"""Project version control: object-store blobs, linear commits, restore, and GC."""

node Project {
    has name: str = "";
    has is_versioned: bool = False;
    has next_version: int = 1;
    has live_hashes: list[str] = [];
}

node Blob {
    has hash: str = "";
    has label: str = "";
}

node Manifest {
    has title: str = "";
}

node Commit {
    has message: str = "";
    has timestamp: str = "";
    has provenance: str = "";
    has version_num: int = 0;
    has tag_mix: bool = False;
}

edge TipOf { }
edge Composes { }
edge Snapshots { }
edge Timeline { }
edge Stores { }

walker Committer {
    has message: str = "";
    has provenance: str = "";
    has tag_mix: bool = False;
    has stamp: str = "";
    has proj: Project | None = None;
    has snap: Manifest | None = None;
    has ver: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can freeze with Project entry {
        self.proj = here;
        if not here.is_versioned {
            here.is_versioned = True;
            print(f"[migrate] {here.name} -> object store");
        }
        self.ver = here.next_version;
        here.next_version += 1;
        self.snap = Manifest(title=f"v{self.ver}");
        visit [->:TipOf:->];
    }

    can harvest with Manifest entry {
        visit [->:Composes:->] else {
            if self.proj is None {
                disengage;
            }
            if self.snap is None {
                disengage;
            }
            p = self.proj;
            s = self.snap;
            c = Commit(
                message=self.message,
                timestamp=self.stamp,
                provenance=self.provenance,
                version_num=self.ver,
                tag_mix=self.tag_mix
            );
            p +>:Timeline:+> c;
            c +>:Snapshots:+> s;
            kind = "mix" if self.tag_mix else "full";
            print(f"[commit v{self.ver}] {self.message} ({kind}) <- {self.provenance}");
            disengage;
        }
    }

    can share with Blob entry {
        if self.snap is None {
            disengage;
        }
        s = self.snap;
        s +>:Composes:+> here;
    }
}

walker Historian {
    has proj: Project | None = None;

    can start with Root entry {
        visit [-->];
    }

    can walk with Project entry {
        self.proj = here;
        print(f"timeline for {here.name}:");
        visit [->:Timeline:->] else {
            disengage;
        }
    }

    can note with Commit entry {
        kind = "mix" if here.tag_mix else "full";
        print(f"  v{here.version_num}: {here.message} [{kind}] @ {here.timestamp}");
        visit [->:Timeline:->];
    }
}

walker Restorer {
    has target: int = 1;
    has stage: str = "capture";
    has proj: Project | None = None;
    has old_tip: Manifest | None = None;
    has new_tip: Manifest | None = None;
    has found: bool = False;

    can start with Root entry {
        visit [-->];
    }

    can work with Project entry {
        self.proj = here;
        visit [->:TipOf:->];
    }

    can on_manifest with Manifest entry {
        if self.stage == "capture" {
            self.old_tip = here;
            self.stage = "seek";
            visit [->:Timeline:->] else {
                disengage;
            }
        } else {
            if self.stage == "rebuild" {
                if self.proj is None {
                    disengage;
                }
                if self.old_tip is None {
                    disengage;
                }
                pr = self.proj;
                old = self.old_tip;
                if self.new_tip is None {
                    self.new_tip = Manifest(title="working-tip");
                    pr del ->:TipOf:-> old;
                    pr +>:TipOf:+> self.new_tip;
                }
                visit [->:Composes:->] else {
                    print(f"[restore] copied v{self.target} forward into working tip");
                    disengage;
                }
            }
        }
    }

    can seek with Commit entry {
        if here.version_num == self.target {
            self.found = True;
            self.stage = "rebuild";
            visit [->:Snapshots:->];
            disengage;
        }
        visit [->:Timeline:->] else {
            if not self.found {
                print(f"[restore] v{self.target} not found");
            }
            disengage;
        }
    }

    can relink with Blob entry {
        if self.stage == "rebuild" {
            if self.new_tip is None {
                disengage;
            }
            nt = self.new_tip;
            nt +>:Composes:+> here;
        }
    }
}

walker BlobGc {
    has proj: Project | None = None;
    has removed: int = 0;
    has phase: str = "mark";
    has after_tip: bool = False;

    can start with Root entry {
        visit [-->];
    }

    can run with Project entry {
        self.proj = here;
        if self.phase == "mark" {
            visit [->:TipOf:->];
        } else {
            visit [->:Stores:->] else {
                print(f"[gc] purged {self.removed} orphan blob(s)");
                disengage;
            }
        }
    }

    can mark_manifest with Manifest entry {
        visit [->:Composes:->] else {
            if not self.after_tip {
                self.after_tip = True;
                visit [->:Timeline:->] else {
                    self.phase = "sweep";
                    visit [-->];
                }
            } else {
                visit [->:Timeline:->] else {
                    self.phase = "sweep";
                    visit [-->];
                }
            }
        }
    }

    can pin with Blob entry {
        if self.proj is None {
            disengage;
        }
        p = self.proj;
        seen = False;
        for h in p.live_hashes {
            if h == here.hash {
                seen = True;
                break;
            }
        }
        if not seen {
            p.live_hashes.append(here.hash);
        }
    }

    can mark_commit with Commit entry {
        visit [->:Snapshots:->];
