"""Hadolint CI gate: path filters that never self-trigger and a literal glob dockerfile arg."""

node Repository {
    has name: str = "";
}

node Workflow {
    has name: str = "";
    has workflow_path: str = "";
    has dockerfile_arg: str = "";
    has use_recursive: bool = False;
}

node Dockerfile {
    has path: str = "";
    has linted: bool = False;
}

node PathPattern {
    has glob: str = "";

    def matches(target: str) -> bool {
        if self.glob == "**/Dockerfile" {
            return target == "Dockerfile" or target.endswith("/Dockerfile");
        }
        if self.glob == "**/Dockerfile.*" {
            return "Dockerfile." in target;
        }
        if self.glob == "**/.hadolint.yaml" {
            return target.endswith(".hadolint.yaml");
        }
        return target == self.glob;
    }
}

edge Contains { }
edge TriggersOn { }

walker TriggerAuditor {
    has ci_file: str = ".github/workflows/hadolint.yml";
    has self_edit_triggers: bool = False;

    can start with Root entry {
        visit [-->];
    }

    can bridge with Repository entry {
        visit [-->];
    }

    can audit with Workflow entry {
        visit [->:TriggersOn:->];
        if not self.self_edit_triggers {
            print(
                f"[FILTER] '{here.name}' path filters never match "
                f"{self.ci_file}, so workflow edits produce zero runs"
            );
        }
        disengage;
    }

    can scan with PathPattern entry {
        if here.matches(self.ci_file) {
            self.self_edit_triggers = True;
        }
    }
}

walker LiteralGlobLinter {
    has literal: str = "";
    has found: bool = False;

    can start with Root entry {
        visit [-->];
    }

    can bridge with Repository entry {
        visit [-->];
    }

    can bind with Workflow entry {
        self.literal = here.dockerfile_arg;
        visit [<--];
    }

    can scan with Repository entry {
        visit [->:Contains:->];
        if not self.found {
            print(
                f"hadolint: {self.literal}: does not exist "
                f"(No such file or directory)"
            );
        }
        disengage;
    }

    can probe with Dockerfile entry {
        if here.path == self.literal {
            self.found = True;
            here.linted = True;
            print(f"[LINT] {here.path}");
        }
        visit [-->];
    }
}

walker RecursiveLinter {
    can walk with Repository entry {
        visit [->:Contains:->] else { disengage; };
    }

    can lint with Dockerfile entry {
        here.linted = True;
        print(f"[LINT] {here.path}");
        visit [->:Contains:->] else { disengage; };
    }
}

with entry {
