"""Subagent topology and usage attribution: model parent-child delegation, lifecycle facets, and descendant-inclusive token rollup."""

node Session {
    has session_id: str = "";
    has title: str = "";
    has direct_tokens: int = 0;
    has lifecycle: str = "running";
    has topology_facet: str = "Pending";
    has available: bool = True;
}

edge Delegation {
    has spawned_at: str = "";
}

walker TopologyAuditor {
    has visited_ids: list[str] = [];
    has child_sums: list[int] = [];

    can start with Root entry {
        visit [-->];
    }

    can descend with Session entry {
        if here.session_id in self.visited_ids {
            print(f"[CYCLE] delegation loop at {here.session_id}");
            disengage;
        }
        self.visited_ids.append(here.session_id);
        self.child_sums.append(0);
        visit [->:Delegation:->] else { disengage; }
    }

    can rollup with Session exit {
        child_total = self.child_sums.pop();
        attributed = here.direct_tokens + child_total;
        if self.child_sums {
            parent_slot = len(self.child_sums) - 1;
            self.child_sums[parent_slot] += attributed;
        }
        scope = "descendant-inclusive" if attributed > here.direct_tokens else "direct-only";
        print(
            f"[{here.topology_facet}] {here.session_id} {here.title} "
            f"lifecycle={here.lifecycle} direct={here.direct_tokens} "
            f"attributed={attributed} ({scope})"
        );
    }
}

