}

walker DependencyAuditor {
    has visited: list[str] = [];
    has vuln_count: int = 0;

    can start with Root entry {
        print("CVE scan: traversing Gemfile.lock dependency tree");
        visit [-->];
    }

    can scan with Project | Lockfile entry {
        print(here.summary_line());
        visit [->:DependsOn:->] else { disengage; };
