    can start with Root entry {
        visit [-->];
    }

    can traverse with Project | Lockfile entry {
        visit [->:DependsOn:->] else { disengage; };
    }

    can remediate with Gem entry {
        if here.vulnerable {
            action = f"upgrade {here.name} to {here.fixed_version}";
