"""Friendship graph: recursive path cycle guarding mirrors SQL recursive CTEs, and PGQL-style MATCH/COLUMNS over typed friends edges."""

node User {
    has user_id: int = 0;
    has name: str = "";
}

edge Friends {
    has since: str = "";
}

walker CycleDetect {
    has path: list[int] = [];

    can detect with User entry {
        if here.user_id in self.path {
            print(f"WHERE NOT (friend_id = ANY(path)) blocked at {here.user_id}, path={self.path}");
        } else {
            next_path: list[int] = [];
            for pid in self.path {
                next_path.append(pid);
            }
            next_path.append(here.user_id);
            saved_path = self.path;
            self.path = next_path;
            print(f"cycle_detect: user_id={here.user_id}, path={self.path}");
            visit [->:Friends:->];
            self.path = saved_path;
        }
    }
}

walker PgqlMatcher {
    has anchor_name: str = "Alice";
    has phase: str = "seek";
    has anchor: User | None = None;
    has matched_since: str = "";

    can start with Root entry {
        visit [-->];
    }

    can capture with Friends entry {
        self.matched_since = here.since;
    }

    can walk with User entry {
        if self.phase == "seek" {
            if here.name != self.anchor_name {
                visit [-->];
            } else {
                self.anchor = here;
                self.phase = "match";
                print(f"MATCH (a IS users)-[e IS friends]->(b IS users) WHERE a.name = '{here.name}'");
                visit [->:Friends:->] else { disengage; };
            }
        } else if self.phase == "match" {
            anchor_label = self.anchor.name if self.anchor else "";
            print(f"COLUMNS ({anchor_label}, {here.name}, {self.matched_since})");
        }
    }
}

with entry {
    alice = User(user_id=1, name="Alice");
    bob = User(user_id=2, name="Bob");
    carol = User(user_id=3, name="Carol");
    dave = User(user_id=4, name="Dave");

    root ++> alice;
    alice +>:Friends(since="2019"):+> bob;
    bob +>:Friends(since="2020"):+> carol;
    carol +>:Friends(since="2021"):+> alice;
    bob +>:Friends(since="2022"):+> dave;

    print("=== recursive CTE cycle_detect from user_id=1 ===");
    CycleDetect() spawn alice;

    print("=== GRAPH_TABLE social_network MATCH from Alice ===");
    root spawn PgqlMatcher(anchor_name="Alice");
}

"""Podwiki source normalization: walk wiki pages in source order, emit typed chip records, and guard citation cycles."""

node Chip {
    has target_key: str = "";
    has alias_label: str = "";
    has timestamp: str = "";
    has citation_label: str = "";
}

node CitationChip(Chip) { }

node WikiRefChip(Chip) { }

node PersonChip(Chip) { }

node WikiPage {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has source_key: str = "";
    has checksum: str = "";
}

edge SourceOrder { }

edge Contains {
    has seq: int = 0;
}

edge Cites { }

walker SourceNormalizer {
    has repo: str = "DataTalksClub/podwiki";
    has commit: str = "";
    has tree: str = "";
    has page_count: int = 0;
    has occurrence_count: int = 0;

    can start with Root entry {
        print(f"Adapter bind: {self.repo}@{self.commit} tree={self.tree}");
        visit [->:SourceOrder:->] else { disengage; };
    }

    can normalize with WikiPage entry {
        self.page_count += 1;
        print(f"PAGE [{self.page_count}] {here.source_key} :: {here.title} ({here.checksum})");
        visit [->:Contains:->];
        visit [->:SourceOrder:->] else { disengage; };
    }

    can emit with CitationChip | WikiRefChip | PersonChip entry {
        self.occurrence_count += 1;
        chip_kind = "citation" if here is CitationChip else "wiki" if here is WikiRefChip else "person";
        stamp = f" ts={here.timestamp}" if here.timestamp else "";
        print(
            f"  CHIP #{self.occurrence_count} [{chip_kind}] "
            f"target={here.target_key} alias={here.alias_label}{stamp}"
        );
    }

    can finish with Root exit {
        print(
            f"Normalized {self.page_count} pages, "
            f"{self.occurrence_count} ordered chip occurrences"
        );
    }
}

walker CitationCycleGuard {
    has seen: list[str] = [];
    has cycle_detected: bool = False;

    can start with Root entry {
        visit [->:SourceOrder:->] else { disengage; };
    }

    can audit with WikiPage entry {
        page_key = here.source_key;
        if page_key in self.seen {
            print(f"CYCLE: citation graph revisits {page_key}");
            self.cycle_detected = True;
            disengage;
        }
        self.seen.append(page_key);
        visit [->:Cites:->] else { disengage; };
    }
}

