    has confidence: float = 1.0;
    has evidence_ref: str = "";
}

walker ProvenanceAuditor {
    has violations: list[str] = [];
    has passed: int = 0;

    can start with Root entry {
        print("=== Provenance audit (TraceMap evidence) ===");
        visit [-->];
    }

    can inspect with EvidenceSource | Component entry {
        if here.evidence_ref == "" {
            label = here.title if here.title != "" else "untitled";
            self.violations += [f"missing evidence_ref: {label}"];
            print(f"[REJECT] untagged entity: {label}");
        } else {
            self.passed += 1;
            print(f"[OK] {here.title} bound to {here.evidence_ref}");
        }
        visit [->:Contains:->] else { disengage; };
    }
}

