    has digest: list[str] = [];

    can start with Root entry {
        print("=== LikeC4 projection (generated, not canonical) ===");
        visit [-->];
    }

    can emit with EvidenceSource entry {
        stable_id = f"source.{here.revision}";
        line = f"{stable_id} metadata.ref={here.evidence_ref}";
        self.digest += [line];
        print(f".c4 {line}");
        visit [->:Contains:->] else { disengage; };
    }

    can emit with Component entry {
        if here.projected_id == "" {
            kind_label = here.kind if here.kind != "" else "component";
            here.projected_id = f"{kind_label}.{here.title}";
        }
        line = f"{here.projected_id} metadata.ref={here.evidence_ref}";
