walker ChainCompiler {
    has depth: int = 0;
    has lambda_paths: int = 1;
    has chain_limit: int = 22;

    can compile with ModelClass entry {
        nav_label = "optional [0..1]" if here.multiplicity == "optional" else "required [1]";
        next_paths = self.lambda_paths * 2 if here.multiplicity == "optional" else self.lambda_paths;
        print(f"  depth={self.depth} nav {here.name} ({nav_label}) lambda_paths={next_paths}");
        self.lambda_paths = next_paths;
        self.depth += 1;
        if self.depth >= self.chain_limit {
            disengage;
        }
        visit [->:NextAssoc:->] else { disengage; };
    }
}

