"""Rosetta Execution Spine v0.1: trace the shortest credible proof path from bootstrap baseline to Text-Core Green."""

node TrackableItem {
    has issue_id: int = 0;
    has title: str = "";
    def is_clear() -> bool {
        return True;
    }
    def spine_record_line(step_num: int) -> str {
        return f"  [{step_num}] item #{self.issue_id} {self.title}";
    }
}

node BaselineProof(TrackableItem) {
    override def spine_record_line(step_num: int) -> str {
        return f"  [{step_num}] baseline #{self.issue_id} {self.title}";
    }
}

node SpineStep(TrackableItem) {
    has phase: str = "";
    has done: bool = False;
    override def is_clear() -> bool {
        return self.done;
    }
    override def spine_record_line(step_num: int) -> str {
        status = "DONE" if self.done else "PENDING";
        return f"  [{step_num}] {self.phase} #{self.issue_id} [{status}] {self.title}";
    }
}

node RungClaim {
    has name: str = "";
    has reachable: bool = False;
}

node BacklogItem {
    has issue_id: int = 0;
    has title: str = "";
}

edge Unblocks { }
edge TowardRung { }

walker ExecutionSpine {
    has seen: list[int] = [];
    has steps: int = 0;

    can start with Root entry {
        print("Execution Spine v0.1 — shortest proof path audit");
        visit [->:Unblocks:->] else { disengage; };
    }

    can record with BaselineProof | SpineStep entry {
        if here.issue_id in self.seen {
            print(f"CYCLE: #{here.issue_id} revisits the dependency graph");
            disengage;
        }
        self.seen.append(here.issue_id);
        self.steps += 1;
        print(here.spine_record_line(self.steps));
        if not here.is_clear() {
            print(f"  HALT: maturity claim blocked until #{here.issue_id} is proven");
            disengage;
        }
        visit [->:Unblocks:->] else {
            visit [->:TowardRung:->] else { disengage; };
        };
    }

    can reach with RungClaim entry {
        here.reachable = True;
        print(f"  TARGET: {here.name} is credibly reachable along the spine");
        disengage;
    }
}

