}

node Layer {
    has label: str = "";
}

node Completion {
    has id: str = "";
    has finished: bool = False;
}

edge LinksTo { }
edge CurrentAt { }
edge SpawnedFrom { }
edge PublishedTo { }

walker ReachCollector {
    has seen: list[str] = [];
    has labels: list[str] = [];

    can gather with Layer entry {
        if here.label in self.seen {
            disengage;
        }
        self.seen.append(here.label);
        self.labels.append(here.label);
        visit [->:LinksTo:->] else { disengage; };
    }
}

walker CompletionNavigator {
    has seen: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can walk with Completion entry {
        if here.id in self.seen {
            disengage;
        }
        self.seen.append(here.id);
        state = "active" if not here.finished else "done";
        print(f"[{state}] completion {here.id}");
        visit [->:CurrentAt:->];
        visit [->:SpawnedFrom:->] else { disengage; };
    }

    can show_current with Layer entry {
        print(f"  current -> {here.label}");
        disengage;
    }

    can read_published with Completion entry {
        visit [->:PublishedTo:->] else { disengage; };
    }

    can show_published with Layer entry {
        print(f"  published (read-only) -> {here.label}");
        disengage;
    }
}

walker AdvanceGuard {
    has old_reach: list[str] = [];
    has new_reach: list[str] = [];

    can check_subset with Root entry {
        ok = True;
        for label in self.old_reach {
            if label not in self.new_reach {
                ok = False;
            }
        }
        verdict = "VALID" if ok else "INVALID";
        print(f"advance accessibility: {verdict}");
        disengage;
    }
}

walker PointerAdvancer {
    has from_layer: Layer;
    has to_layer: Layer;

    can advance with Completion entry {
        here del --> self.from_layer;
        here +>:CurrentAt:+> self.to_layer;
        disengage;
    }
}

with entry {
    ix = Interaction(title="analyze_repo");
    root ++> ix;

    l_initial = Layer(label="initial");
    l_work = Layer(label="working_v2");
    l_hist = Layer(label="history_initial");
    l_bad = Layer(label="broken_v3");
    l_child = Layer(label="child_result");

    ix ++> l_initial;
    l_work +>:LinksTo:+> l_hist;
    l_hist +>:LinksTo:+> l_initial;

    parent = Completion(id="parent");
    root ++> parent;
    parent +>:CurrentAt:+> l_initial;

    sub_ix = Interaction(title="sub_task");
    ix ++> sub_ix;
    child = Completion(id="child");
    sub_ix ++> child;
    child +>:CurrentAt:+> l_child;
    child +>:PublishedTo:+> l_child;
    parent +>:SpawnedFrom:+> child;

    old_rc = ReachCollector();
    l_initial spawn old_rc;
    good_rc = ReachCollector();
    l_work spawn good_rc;
    bad_rc = ReachCollector();
    l_bad spawn bad_rc;

    root spawn AdvanceGuard(
        old_reach=old_rc.labels,
        new_reach=good_rc.labels
    );

    root spawn AdvanceGuard(
        old_reach=old_rc.labels,
        new_reach=bad_rc.labels
    );

    parent spawn PointerAdvancer(from_layer=l_initial, to_layer=l_work);

    root spawn CompletionNavigator();
}

"""C-Next #include cycles: tolerated warning leaves topo order arbitrary, so per-file header generation sees an incomplete symbol accumulator."""

node SourceFile {
    has path: str = "";
    has defines_types: list[str] = [];
    has needs_types: list[str] = [];
}

edge Includes { }

walker CycleChecker {
    has stack: list[str] = [];
    has cycle_found: bool = False;
    has warning_msg: str = "";

    can detect with SourceFile entry {
        if here.path in self.stack {
            self.cycle_found = True;
            self.warning_msg = "WARNING: #include cycle detected; topological sort returns arbitrary order";
            disengage;
        }
        self.stack.append(here.path);
        visit [->:Includes:->] else { disengage; };
    }
}

walker TopoCollector {
    has visited: list[str] = [];
    has sorted_order: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can collect with SourceFile entry {
        if here.path in self.visited {
            disengage;
        }
        self.visited.append(here.path);
        self.sorted_order.append(here.path);
        visit [->:Includes:->] else { disengage; };
    }
}

walker HeaderBuilder {
    has visited: list[str] = [];
    has accumulator: list[str] = [];
    has header_gaps: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can transpile with SourceFile entry {
        if here.path in self.visited {
            disengage;
        }
        self.visited.append(here.path);
        for need in here.needs_types {
            if need not in self.accumulator {
                gap = f"{here.path}: generateHeaderForFile missing '{need}' — accumulator only has files transpiled so far";
                self.header_gaps.append(gap);
            }
        }
        for sym in here.defines_types {
            if sym not in self.accumulator {
                self.accumulator.append(sym);
            }
        }
        visit [->:Includes:->] else { disengage; };
    }
}

with entry {
    types_cnx = SourceFile(
        path="types.cnx",
        defines_types=["Point"],
        needs_types=["UtilFn"]
    );
    utils_cnx = SourceFile(
        path="utils.cnx",
        defines_types=["UtilFn"],
        needs_types=["Point"]
    );
    root ++> utils_cnx;
    root ++> types_cnx;
    types_cnx +>:Includes:+> utils_cnx;
    utils_cnx +>:Includes:+> types_cnx;

    checker = CycleChecker();
    types_cnx spawn checker;
    if checker.cycle_found {
        print(checker.warning_msg);
    }

    topo = TopoCollector();
    root spawn topo;
    print(f"arbitrary topo order: {topo.sorted_order}");

    builder = HeaderBuilder();
    root spawn builder;
    print(f"accumulator after pass: {builder.accumulator}");
    for gap in builder.header_gaps {
        print(gap);
    }
}

"""Odoo registry inspection: read-only metadata walk over models, fields, XML refs, and test profiling."""

node OdooModel {
    has title: str = "";
    has description: str = "";
    has table_name: str = "";
    has abstract: bool = False;
    has transient: bool = False;
    has available: bool = True;
}

node FieldMeta {
    has title: str = "";
    has field_type: str = "";
    has label: str = "";
    has required: bool = False;
    has readonly: bool = False;
    has store: bool = True;
    has index: bool = False;
    has has_relation: bool = False;
    has has_compute: bool = False;
    has available: bool = True;
}

node XmlRef {
    has title: str = "";
    has xmlid: str = "";
    has model_name: str = "";
    has display_name: str = "";
    has record_id: int = 0;
    has available: bool = True;
}

node TestCase {
    has title: str = "";
    has test_id: str = "";
    has duration: float = 0.0;
    has query_count: int = 0;
    has available: bool = True;
}

edge HasField { }

edge RelatesTo { }

edge ResolvesTo { }

walker RegistryInspector {
    has inspected: int = 0;
    has visited_keys: list[str] = [];

    def seen(key: str) -> bool {
        for k in self.visited_keys {
            if k == key {
                return True;
            }
        }
        return False;
    }

    def mark(key: str) {
        self.visited_keys.append(key);
    }

    can start with Root entry {
        print("=== inspect: registry (read-only, commit=False) ===");
        visit [-->];
        print(f"--- bounded facts for {self.inspected} objects (no record field dump) ---");
    }

    can inspect_model with OdooModel entry {
        key = f"model:{here.title}";
        if self.seen(key) {
            visit [-->];
        } else {
            self.mark(key);
            exists_flag = "true" if here.available else "false";
            if not here.available {
                print(f"[model] name={here.title} exists={exists_flag}");
            } else {
                kind = "concrete";
                if here.abstract {
                    kind = "abstract";
                }
                if here.transient {
                    kind = "transient";
                }
                print(
                    f"[model] name={here.title} exists={exists_flag} "
                    f"table={here.table_name} kind={kind} desc={here.description}"
                );
                self.inspected += 1;
            }
            visit [->:HasField:->];
            visit [-->];
        }
    }

    can inspect_field with FieldMeta entry {
        key = f"field:{here.title}";
        if self.seen(key) {
            visit [-->];
        } else {
            self.mark(key);
            exists_flag = "true" if here.available else "false";
            rel = "yes" if here.has_relation else "no";
            compute = "yes" if here.has_compute else "no";
            print(
                f"[field] name={here.title} exists={exists_flag} type={here.field_type} "
                f"label={here.label} required={here.required} readonly={here.readonly} "
                f"store={here.store} index={here.index} relation={rel} compute={compute}"
            );
            self.inspected += 1;
            visit [->:RelatesTo:->] else {
                visit [-->];
            };
        }
    }

    can inspect_ref with XmlRef entry {
        key = f"ref:{here.xmlid}";
        if self.seen(key) {
            visit [-->];
        } else {
            self.mark(key);
            exists_flag = "true" if here.available else "false";
            print(
                f"[ref] xmlid={here.xmlid} exists={exists_flag} model={here.model_name} "
                f"record_id={here.record_id} display_name={here.display_name}"
            );
            self.inspected += 1;
            visit [->:ResolvesTo:->] else {
                visit [-->];
            };
        }
    }
}

walker TestProfiler {
    has test_ids: list[str] = [];
    has durations: list[float] = [];
    has query_counts: list[int] = [];

    can start with Root entry {
        visit [-->];
    }

    can collect with TestCase entry {
        self.test_ids.append(here.test_id);
        self.durations.append(here.duration);
        self.query_counts.append(here.query_count);
        visit [-->];
    }

    report {
        n = len(self.test_ids);
        total_dur = 0.0;
        total_q = 0;
        for i in range(n) {
            total_dur += self.durations[i];
            total_q += self.query_counts[i];
        }
        print(f"=== test --profile ({n} tests, totals: {total_dur}s, {total_q} queries) ===");
        remaining = n;
        while remaining > 0 {
            best = -1;
            for j in range(n) {
                if self.durations[j] < 0.0 {
                    continue;
                }
                if best < 0 {
                    best = j;
                } else if self.durations[j] > self.durations[best] {
                    best = j;
                } else if (
                    self.durations[j] == self.durations[best]
                    and self.test_ids[j] < self.test_ids[best]
                ) {
                    best = j;
                }
            }
            print(
                f"  {self.test_ids[best]} duration={self.durations[best]}s "
                f"queries={self.query_counts[best]}"
            );
            self.durations[best] = -1.0;
            remaining -= 1;
        }
    }
}

