"""Relationship currentness: evaluate requirement–slice–seam and evidence edges against reviewed basis identities."""

node Endpoint {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has relationship_id: str = "";
    has review_basis: str = "";
    has canonical_owner: str = "";
}

node Requirement(Endpoint) {
    has req_id: str = "";
    has generation: str = "";
    has scope_id: str = "";
    has is_historical: bool = False;
}

node ImplementationSlice(Endpoint) {
    has slice_id: str = "";
    has target_id: str = "";
    has seam_owner: str = "";
    has reviewed_generation: str = "";
    has reviewed_target: str = "";
    has reviewed_scope: str = "";
}

node ImplementationSeam {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has seam_id: str = "";
    has owner_id: str = "";
    has reviewed_owner: str = "";
}

node EvidenceSubject(Endpoint) {
    has subject_id: str = "";
    has body_id: str = "";
    has purpose: str = "";
    has reviewed_body: str = "";
    has reviewed_purpose: str = "";
}

node AuthorityFact {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has fact_id: str = "";
    has authority_kind: str = "";
}

node ProposalStub {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has stub_id: str = "";
}

edge Satisfies { }
edge OwnsSeam { }
edge Evidences { }
edge GovernedBy { has supplied: bool = True; }
edge AdrSpecLink { }
edge GeneratedReverse { has is_canonical: bool = False; }

walker RelationshipCurrentnessEvaluator {
    has report: list[str] = [];
    has seen: list[str] = [];
    has slice_ctx: ImplementationSlice | None = None;
    has subject_ctx: EvidenceSubject | None = None;
    has query_scope: str = "";

    can start with Root entry {
        visit [-->];
    }

    can evaluate_requirement with Requirement entry {
        if self.slice_ctx is not None {
            sl = self.slice_ctx;
            req = here;
            rel = sl.relationship_id;
            status = "CurrentReviewed";
            route = "none";
            if sl.review_basis == "" {
                status = "Unsupported";
                route = "supply missing authority adapter/fact";
            } elif req.generation != sl.reviewed_generation {
                status = "Stale";
                route = "review existing relationship against current endpoint meaning";
            } elif req.scope_id != sl.reviewed_scope {
                status = "Stale";
                route = "recompile after source/profile movement";
            } elif sl.target_id != sl.reviewed_target {
                status = "Stale";
                route = "refresh slice target/seam mapping";
            }
            owner = sl.canonical_owner;
            self.report.append(
                f"relationship-currentness {rel}: {status} owner={owner} route={route}"
            );
            self.slice_ctx = None;
            visit [->:OwnsSeam:->];
            visit [->:Satisfies:->];
            visit [-->] else { disengage; };
        } elif self.subject_ctx is not None {
            subj = self.subject_ctx;
            req = here;
            rel = subj.relationship_id;
            status = "CurrentReviewed";
            route = "none";
            if subj.review_basis == "" {
                status = "Unsupported";
                route = "supply missing authority adapter/fact";
            } elif subj.body_id != subj.reviewed_body {
                status = "Stale";
                route = "refresh exact evidence subject mapping";
            } elif subj.purpose != subj.reviewed_purpose {
                status = "Stale";
                route = "refresh evidence-purpose discriminator";
            } elif req.scope_id != self.query_scope and self.query_scope != "" {
                status = "Stale";
                route = "recompile after source/profile movement";
            }
            owner = subj.canonical_owner;
            self.report.append(
                f"relationship-currentness {rel}: {status} owner={owner} route={route}"
            );
            self.subject_ctx = None;
            visit [->:Satisfies:->];
            visit [->:Evidences:->];
            visit [-->] else { disengage; };
        } elif here.is_historical {
            rel = here.relationship_id;
            self.report.append(
                f"historical-reverse {rel}: queryable-not-canonical route=review existing relationship against current endpoint meaning"
            );
            visit [-->] else { disengage; };
        } else {
            visit [->:Satisfies:->];
            visit [->:Evidences:->];
            visit [->:GovernedBy:->];
            visit [->:AdrSpecLink:->];
            visit [<--:GeneratedReverse:--];
            visit [-->] else { disengage; };
        }
    }

    can inspect_slice with ImplementationSlice entry {
        self.slice_ctx = here;
        visit [<--:Satisfies:--];
    }

    can inspect_subject with EvidenceSubject entry {
        self.subject_ctx = here;
        visit [<--:Evidences:--];
    }

    can audit_seam with ImplementationSeam entry {
        key = here.seam_id;
        if key in self.seen {
            self.report.append(
                f"seam-ownership {key}: cycle-detected route=resolve contradictory canonical owners"
            );
            disengage;
        }
        self.seen.append(key);
        status = "CurrentReviewed";
        route = "none";
        if here.owner_id != here.reviewed_owner {
            status = "Stale";
            route = "amend canonical owner source";
        }
        self.report.append(f"seam-ownership {key}: {status} route={route}");
        visit [-->] else { disengage; };
    }

    can accept_authority with AuthorityFact entry {
        self.report.append(
            f"governed-by {here.fact_id}: CurrentReviewed owner={here.authority_kind} route=none"
        );
        visit [-->] else { disengage; };
    }

    can reject_adr with ProposalStub entry {
        self.report.append(
            f"adr-reuse {here.stub_id}: Unsupported route=supply missing authority adapter/fact"
        );
        visit [-->] else { disengage; };
    }
}

walker GoverningRelationsQuery {
    has scope_id: str = "";
    has hits: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can bounded_scan with Requirement entry {
        if here.scope_id != self.scope_id {
            visit [-->] else { disengage; };
        } else {
            rel = here.relationship_id;
            if rel != "" {
                self.hits.append(rel);
            }
            visit [->:Satisfies:->];
            visit [-->] else { disengage; };
        }
    }

    can collect_slice with ImplementationSlice entry {
        rel = here.relationship_id;
        if rel != "" {
            self.hits.append(rel);
        }
        visit [-->] else { disengage; };
    }

    can skip_other with ImplementationSeam | EvidenceSubject | AuthorityFact | ProposalStub entry {
        visit [-->] else { disengage; };
    }
}

