"""Deterministic semantic dependency closure: resolve transitive dependencies with identity verification, cycle and conflict rejection, and lock export."""

node SemanticPackage {
    has name: str = "";
    has hash: str = "";
    has verified: bool = False;
}

edge DependsOn { }

walker DependencyResolver {
    has closure: list[SemanticPackage] = [];
    has edge_lines: list[str] = [];
    has visiting: list[str] = [];
    has error: str = "";
    has root_name: str = "";

    can start with Root entry {
        visit [-->] else { disengage; };
    }

    can resolve with SemanticPackage entry {
        if here.name in self.visiting {
            self.error = f"cycle detected involving {here.name}";
            disengage;
        }
        if len(self.visiting) > 0 {
            parent = self.visiting[len(self.visiting) - 1];
            rec = f"edge        {parent}  {here.name}";
            found_edge = False;
            for existing in self.edge_lines {
                if existing == rec {
                    found_edge = True;
                    break;
                }
            }
            if not found_edge {
                self.edge_lines.append(rec);
            }
        }
        self.visiting.append(here.name);
        for pkg in self.closure {
            if pkg.name == here.name and pkg.hash != here.hash {
                self.error = (
                    f"conflict: {here.name} requires "
                    f"{pkg.hash} and {here.hash}"
                );
                disengage;
            }
        }
        already_seen = False;
        for pkg in self.closure {
            if pkg.name == here.name {
                already_seen = True;
                break;
            }
        }
        if not already_seen {
            if not here.verified {
                self.error = f"unverified package: {here.name}";
                disengage;
            }
            self.closure.append(here);
        }
        visit [->:DependsOn:->] else { };
        if len(self.visiting) > 0 {
            _ = self.visiting.pop();
        }
    }

    def lookup(name: str) -> SemanticPackage | None {
        for pkg in self.closure {
            if pkg.name == name {
                return pkg;
            }
        }
        return None;
    }

    def sort_strings(items: list[str]) -> list[str] {
        sorted_items: list[str] = [];
        for item in items {
            sorted_items.append(item);
        }
        for i in range(len(sorted_items)) {
            for j in range(len(sorted_items) - 1 - i) {
                if sorted_items[j] > sorted_items[j + 1] {
                    tmp = sorted_items[j];
                    sorted_items[j] = sorted_items[j + 1];
                    sorted_items[j + 1] = tmp;
                }
            }
        }
        return sorted_items;
    }

    def export_lock() -> str {
        if self.error != "" {
            return f"ERROR: {self.error}";
        }
        names: list[str] = [];
        for pkg in self.closure {
            names.append(pkg.name);
        }
        lines: list[str] = [];
        lines.append(f"root        {self.root_name}");
        for nm in self.sort_strings(names) {
            pkg = self.lookup(nm);
            if pkg is not None {
                lines.append(f"dependency  {pkg.name}  {pkg.hash}");
            }
        }
        for edge_line in self.sort_strings(self.edge_lines) {
            lines.append(edge_line);
        }
        out = "";
        for line in lines {
            prefix = "" if out == "" else "\n";
            out = f"{out}{prefix}{line}";
        }
        return out;
    }
}

