"""Room-01 portal evidence: checksum-bound revision, portal rails, and route probes."""

edge BindsPortal { }
edge RegistersRail { }
edge RetainsControl { }
edge SchedulesProbe { }

node RoomRevision {
    has label: str = "";
    has checksum: str = "";
    has closed_door_control: bool = False;
    has traversable: bool = False;
    has status: str = "held_missing_evidence";
}

node Portal {
    has name: str = "";
    has clear_width_m: float = 0.0;
    has clear_height_m: float = 0.0;
    has trajectory_crossed: bool = False;
}

node EvidenceRail {
    has zone: str = "";
    has rgb_d_count: int = 0;
    has required: bool = True;
    has satisfied: bool = False;
}

node WalkProbe {
    has name: str = "";
    has passed: bool = False;
    has frozen: bool = True;
}

walker PortalEvidenceAuditor {
    has missing_rails: int = 0;
    has authority_granted: bool = False;
    has receipt_sha: str = "";

    can start with Root entry {
        print("=== Portal evidence audit: Room-01 open-door revision ===");
        visit [->:BindsPortal:->] else { disengage; };
    }

    can audit_room with RoomRevision entry {
        control_tag = " [closed-door control]" if here.closed_door_control else "";
        print(f"Revision {here.label}{control_tag}");
        print(f"  checksum: {here.checksum}");
        print(f"  status: {here.status}");
        if here.closed_door_control {
            visit [->:RetainsControl:->] else { disengage; };
        } else {
            visit [->:BindsPortal:->] else { disengage; };
        }
    }

    can inspect_portal with Portal entry {
        cross = "yes" if here.trajectory_crossed else "no";
        print(f"Portal {here.name}: {here.clear_width_m}m x {here.clear_height_m}m, crossed={cross}");
        visit [->:RegistersRail:->] else { disengage; };
    }

    can tally_rail with EvidenceRail entry {
        here.satisfied = here.rgb_d_count > 0;
        req = "required" if here.required else "optional";
        mark = "PASS" if here.satisfied else "MISS";
        print(f"  rail [{here.zone}] rgb_d={here.rgb_d_count} ({req}) -> {mark}");
        if here.required and not here.satisfied {
            self.missing_rails += 1;
        }
        visit [->:RegistersRail:->] else { disengage; };
    }

    can finish with RoomRevision exit {
        if here.closed_door_control {
            disengage;
        }
        all_rails = self.missing_rails == 0;
        portal_ok = here.traversable and all_rails;
        here.traversable = portal_ok and not here.closed_door_control;
        self.authority_granted = here.traversable;
        verdict = "traversable" if here.traversable else "held";
        print(f"Receipt decision: {verdict}; missing_rails={self.missing_rails}; authority={self.authority_granted}");
        self.receipt_sha = here.checksum;
        visit [->:SchedulesProbe:->] else { disengage; };
    }
}

walker RouteProbeRunner {
    has probes_run: int = 0;
    has probes_passed: int = 0;
    has depth: int = 0;
    has max_depth: int = 8;
    has visited: list[str] = [];

    can start with Root entry {
        print("=== Walk capsule probes (frozen, depth-capped) ===");
        visit [->:SchedulesProbe:->] else { disengage; };
    }

    can run_probe with WalkProbe entry {
        key = f"{here}";
        if key in self.visited {
            print(f"  cycle guard: skip re-probe {here.name}");
            disengage;
        }
        self.visited.append(key);
        if self.depth >= self.max_depth {
            print(f"  depth cap reached before {here.name}");
            disengage;
        }
        self.depth += 1;
        self.probes_run += 1;
        result = "PASS" if here.passed else "HOLD";
        frozen_tag = "frozen" if here.frozen else "live";
        print(f"  probe {here.name} ({frozen_tag}): {result}");
        if here.passed {
            self.probes_passed += 1;
        }
        visit [->:SchedulesProbe:->] else {
            self.depth -= 1;
            disengage;
        };
    }

    can unwind with WalkProbe exit {
        self.depth -= 1;
    }

    can summarize with RoomRevision entry {
        ratio = f"{self.probes_passed}/{self.probes_run}";
        print(f"Probe summary: {ratio} passed; collision/navigation authority remains false until receipt clears");
        disengage;
    }
}

