"""Hello Algo Interactive core: stable entity IDs, semantic markers,
immutable snapshot frames, step-guarded timeline play, and backward seek."""

node AlgoRun {
    has name: str = "";
    has step_guard: int = 10000;
}

node Marker {
    has step: int = 0;
    has event_kind: str = "";
    has note: str = "";
}

node Entity {
    has entity_id: str = "";
    has value: int = 0;
    has slot: int = 0;
}

node Frame {
    has step: int = 0;
    has layout: str = "";
}

edge NextMarker { }
edge SnapshotOf { }
edge OwnsEntity { }

walker EntityRegistrar {
    can begin with AlgoRun entry {
        print(f"Registry for {here.name}: stable IDs (not index/value)");
        visit [->:OwnsEntity:->] else { disengage; };
    }

    can read with Entity entry {
        print(f"  {here.entity_id} value={here.value} origin_slot={here.slot}");
    }
}

walker StepGuardedPlayer {
    has steps_taken: int = 0;
    has step_limit: int = 10000;
    has guard_tripped: bool = False;

    can begin with AlgoRun entry {
        self.step_limit = here.step_guard;
        self.steps_taken = 0;
        self.guard_tripped = False;
        print(f"== Play {here.name} (Step Guard={self.step_limit}) ==");
        visit [->:NextMarker:->] else { disengage; };
    }

    can on_marker with Marker entry {
        self.steps_taken += 1;
        if self.steps_taken > self.step_limit {
            self.guard_tripped = True;
            halt_msg = f"Step Guard HALT at marker {self.steps_taken}";
            print(halt_msg);
            disengage;
        }
        print(f"  [{here.step}] {here.event_kind}: {here.note}");
        visit [->:NextMarker:->] else {
            done_msg = f"== Timeline end: {self.steps_taken} markers ==";
            print(done_msg);
            disengage;
        };
    }
}

walker SnapshotSeeker {
    has target_step: int = 0;
    has found_layout: str = "";

    can begin with Marker entry {
        if here.step == self.target_step {
            visit [->:SnapshotOf:->] else { disengage; };
        } else {
            visit [<--:NextMarker:<--] else {
                miss_msg = f"Seek failed: step {self.target_step} not on timeline";
                print(miss_msg);
                disengage;
            };
        }
    }

    can capture with Frame entry {
        self.found_layout = here.layout;
        print(f"Snapshot@{here.step}: {here.layout}");
        disengage;
    }
}

with entry {
    run = AlgoRun(name="bubble-sort", step_guard=10000);
    root ++> run;

    e1 = Entity(entity_id="e1", value=3, slot=0);
    e2 = Entity(entity_id="e2", value=1, slot=1);
    e3 = Entity(entity_id="e3", value=2, slot=2);
    run +>:OwnsEntity:+> e1;
    run +>:OwnsEntity:+> e2;
    run +>:OwnsEntity:+> e3;

    m0 = Marker(step=0, event_kind="init", note="layout e1@0,e2@1,e3@2");
    f0 = Frame(step=0, layout="e1@0,e2@1,e3@2");
    m0 +>:SnapshotOf:+> f0;
    run +>:NextMarker:+> m0;

    m1 = Marker(step=1, event_kind="compare", note="e1(3) vs e2(1) — highlight");
    f1 = Frame(step=1, layout="e1@0,e2@1,e3@2");
    m1 +>:SnapshotOf:+> f1;
    m0 +>:NextMarker:+> m1;

    m2 = Marker(step=2, event_kind="swap", note="swap by ID: e1<->e2");
    f2 = Frame(step=2, layout="e2@0,e1@1,e3@2");
    m2 +>:SnapshotOf:+> f2;
    m1 +>:NextMarker:+> m2;

    m3 = Marker(step=3, event_kind="compare", note="e1(3) vs e3(2) — highlight");
    f3 = Frame(step=3, layout="e2@0,e1@1,e3@2");
    m3 +>:SnapshotOf:+> f3;
    m2 +>:NextMarker:+> m3;

    m4 = Marker(step=4, event_kind="swap", note="swap by ID: e1<->e3");
    f4 = Frame(step=4, layout="e2@0,e3@1,e1@2");
    m4 +>:SnapshotOf:+> f4;
    m3 +>:NextMarker:+> m4;

    print("--- stable entity registry ---");
    run spawn EntityRegistrar();

    print("--- forward semantic timeline ---");
    run spawn StepGuardedPlayer();

    print("--- backward seek to step 2 (O(1) snapshot) ---");
    m4 spawn SnapshotSeeker(target_step=2);

    guard_run = AlgoRun(name="guard-demo", step_guard=2);
    guard_run +>:NextMarker:+> m0;
    print("--- Step Guard trip (limit=2) ---");
    guard_run spawn StepGuardedPlayer();
}

"""Hadolint CI gate: silent path filters and glob literals that never expand."""

node Repository {
    has name: str = "";
}

node CiWorkflow {
    has name: str = "";
    has watched_paths: str = "";
    has execution_count: int = 0;
}

node Dockerfile {
    has rel_path: str = "";
    has linted: bool = False;
}

node GlobLiteral {
    has pattern: str = "";
    has file_exists: bool = False;
}

edge Houses { }
edge ConfiguredFor { }
edge Targets { has recursive: bool = False; }

walker GateAuditor {
    can start with Root entry {
        visit [-->];
    }

    can audit with Repository entry {
        print(f"auditing repo {here.name}");
        visit [->:ConfiguredFor:->];
        visit [->:Houses:->];
    }

    can audit with CiWorkflow entry {
        if "hadolint.yml" not in here.watched_paths {
            print(
                f"{here.name}: paths={here.watched_paths} — workflow not in filter, gate stayed silent"
            );
        }
        visit [->:Targets:->];
    }

    can audit with GlobLiteral entry {
        if not here.file_exists {
            print(
                f"hadolint dockerfile input: {here.pattern} — literal path missing (no glob expansion)"
            );
        }
        visit [-->] else { disengage; };
    }

    can audit with Dockerfile entry {
        status_label = "never linted" if not here.linted else "linted";
        print(f"  {here.rel_path}: {status_label}");
        visit [-->] else { disengage; };
    }
}

walker HadolintRunner {
    has use_recursive: bool = False;
    has linted_count: int = 0;
    has error_msg: str = "";

    can start with Root entry {
        visit [-->];
    }

    can run with Repository entry {
        if self.use_recursive {
            print("hadolint recursive=true — walking tree for Dockerfiles");
            visit [->:Houses:->];
        } else {
            visit [->:ConfiguredFor:->];
        }
    }

    can run with CiWorkflow entry {
        visit [->:Targets:->];
    }

    can run with GlobLiteral entry {
        if not here.file_exists {
            self.error_msg = f"{here.pattern}: withBinaryFile does not exist";
            print(f"hadolint failed: {self.error_msg}");
        }
        visit [-->] else { disengage; };
    }

    can run with Dockerfile entry {
        here.linted = True;
        self.linted_count += 1;
        print(f"hadolint ok: {here.rel_path}");
        visit [-->] else { disengage; };
    }
}

with entry {
    clawde = Repository(name="nself-org/clawde");
    hadolint_wf = CiWorkflow(
        name="hadolint.yml",
        watched_paths="**/Dockerfile,**/.hadolint.yaml"
    );
    bogus = GlobLiteral(pattern="**/Dockerfile", file_exists=False);
    api_df = Dockerfile(rel_path="services/api/Dockerfile");
    desktop_df = Dockerfile(rel_path="desktop/Dockerfile");

    root ++> clawde;
    clawde +>:Houses:+> api_df;
    clawde +>:Houses:+> desktop_df;
    clawde +>:ConfiguredFor:+> hadolint_wf;
    hadolint_wf +>:Targets(recursive=False):+> bogus;

    print("--- defect snapshot ---");
    root spawn GateAuditor();
    root spawn HadolintRunner(use_recursive=False);

    print("--- fix: recursive scan ---");
    root spawn HadolintRunner(use_recursive=True);
    all_clean = api_df.linted and desktop_df.linted;
    print(f"after fix: linted {all_clean} dockerfiles under {clawde.name}");
