edge ChildDir { }

walker RecallAgent {
    has query: str = "";

    can start with MemoryStore entry {
        print(f"[recall] scanning {here.canonical_path} for '{self.query}'");
        visit [->:Stores:->] else { disengage; }
    }

    can rank with MemoryRecord entry {
        if here.active {
            needle = self.query.lower();
            haystack = here.content.lower();
            if needle in haystack {
                label = "ACTIVE" if here.active else "STALE";
                print(f"  [{label}] {here.record_id}: {here.content}");
            }
        }
        visit [->:Stores:->] else { disengage; }
    }
}

walker ChainAuditor {
    has visited_ids: list[str] = [];

    can start with MemoryRecord entry {
        head_label = "ACTIVE" if here.active else "SUPERSEDED";
        print(f"[audit] supersession chain from {here.record_id} [{head_label}]");
        visit [->:Supersedes:->] else { disengage; }
    }

    can walk_older with MemoryRecord entry {
        if here.record_id in self.visited_ids {
            print(f"  [cycle-guard] stopped at {here.record_id}");
            disengage;
        }
        self.visited_ids.append(here.record_id);
        older_label = "SUPERSEDED" if not here.active else "ACTIVE";
        print(f"  -> [{older_label}] {here.record_id}: {here.content}");
        visit [->:Supersedes:->] else { disengage; }
    }
}

walker ForgetAgent {
    has purged_ids: list[str] = [];
    has visited_ids: list[str] = [];

    can start with MemoryRecord entry {
        print(f"[forget] physical purge from {here.record_id}");
        if here.record_id not in self.visited_ids {
