"""Repository audit re-run: traverse acyclic story dependencies, scan audit areas, and reconcile stale completion documents."""

node AuditStory {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has verified: bool = False;
}

node AuditArea {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has scope: str = "";
}

node CompletionDoc {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has claims_complete: bool = True;
    has reconciled: bool = False;
}

node Finding {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has severity: str = "medium";
    has filed: bool = False;
}

edge DependsOn { has prerequisite: str = ""; }
edge Covers { }
edge Documents { }
edge SurfacesIn { }

walker DependencyAuditor {
    has trail: list[str] = [];
    has cycle_found: bool = False;
    has areas_scanned: int = 0;
    has findings_filed: int = 0;

    can start with Root entry {
        print("Re-running repository audit against default-branch artifacts");
        visit [-->];
    }

    can walk_story with AuditStory entry {
        if self.cycle_found {
            disengage;
        }
        for marker in self.trail {
            if marker == here.title {
                print(f"[CYCLE] dependency loop at {here.title}");
                self.cycle_found = True;
                disengage;
            }
        }
        self.trail.append(here.title);
        visit [->:DependsOn:->] else {
            gate = "CLEARED" if here.verified else "BLOCKED";
            print(f"[STORY] {here.title} ({gate})");
            visit [->:Covers:->] else { disengage; };
        };
        self.trail.pop();
    }

    can scan_area with AuditArea entry {
        if here.available {
            self.areas_scanned += 1;
            status = "ACTIVE" if here.available else "INACTIVE";
            print(f"[AREA] {status} {here.scope}: {here.title}");
        }
        visit [->:SurfacesIn:->] else { disengage; };
    }

    can record with Finding entry {
        if not here.filed and here.available {
            here.filed = True;
            self.findings_filed += 1;
            print(f"[FINDING] {here.severity} evidence filed: {here.title}");
        }
    }
}

walker DocReconciler {
    has reconciled_count: int = 0;
    has retired_count: int = 0;

    can start with Root entry {
        print("Documentation reconciliation pass");
        visit [-->];
    }

    can reconcile with CompletionDoc entry {
        if here.claims_complete and not here.reconciled {
            action = "CORRECT" if here.available else "ARCHIVE";
            print(f"[DOC] {action} stale claim ({here.year}): {here.title}");
            here.reconciled = True;
            self.reconciled_count += 1;
            if not here.available {
                self.retired_count += 1;
            }
        }
        visit [-->];
    }

    can inspect with AuditStory | AuditArea entry {
        label = "verified" if here.available else "retired";
        print(f"[CHECK] {here.title} marked {label}");
        visit [->:Documents:->] else {
            visit [-->];
        };
    }
}

with entry {
    s701 = AuditStory(title="S7-01", year=7, verified=True);
