"""Directory-scoped long-term memory: isolated stores, supersession chains, and proactive recall."""

node MemoryStore {
    has canonical_path: str = "";
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

node MemoryRecord {
    has record_id: str = "";
    has content: str = "";
    has active: bool = True;
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

edge Stores { }
edge Supersedes { has reason: str = ""; }
edge ChildDir { }

walker RecallAgent {
    has query: str = "";
    has scope_path: str = "";

    can start with Root entry {
        visit [-->];
    }

    can scan_store with MemoryStore entry {
        if self.scope_path != "" and here.canonical_path != self.scope_path {
            visit [->:ChildDir:->] else { visit [-->]; };
        } else {
            print(f"[recall] scanning {here.canonical_path} for '{self.query}'");
            visit [->:Stores:->] else { disengage; };
        }
    }

    can rank with MemoryRecord entry {
        if here.active {
            needle = self.query.lower();
            haystack = here.content.lower();
            if needle in haystack {
                label = "ACTIVE" if here.active else "STALE";
                print(f"  [{label}] {here.record_id}: {here.content}");
            }
        }
        visit [-->] else { disengage; };
    }
}

walker ChainAuditor {
    has visited_ids: list[str] = [];
    has head_id: str = "";

    can start with Root entry {
        visit [-->];
    }

    can bridge_store with MemoryStore entry {
        visit [->:Stores:->] else { };
        visit [->:ChildDir:->] else { };
        visit [-->];
    }

    can audit_head with MemoryRecord entry {
        if self.head_id != "" and here.record_id != self.head_id {
            visit [-->] else { disengage; };
        } else {
            head_label = "ACTIVE" if here.active else "SUPERSEDED";
            print(f"[audit] supersession chain from {here.record_id} [{head_label}]");
            self.visited_ids.append(here.record_id);
            print(f"  -> [{head_label}] {here.record_id}: {here.content}");
            visit [->:Supersedes:->] else { disengage; };
        }
    }

    can walk_older with MemoryRecord entry {
        if here.record_id in self.visited_ids {
            print(f"  [cycle-guard] stopped at {here.record_id}");
            disengage;
        } else {
            self.visited_ids.append(here.record_id);
            older_label = "SUPERSEDED" if not here.active else "ACTIVE";
            print(f"  -> [{older_label}] {here.record_id}: {here.content}");
            visit [->:Supersedes:->] else { disengage; };
        }
    }
}

walker ForgetAgent {
    has purged_ids: list[str] = [];
    has visited_ids: list[str] = [];
    has head_id: str = "";

    can start with Root entry {
        visit [-->];
    }

    can bridge_store with MemoryStore entry {
        visit [->:Stores:->] else { };
        visit [->:ChildDir:->] else { };
        visit [-->];
    }

    can purge_head with MemoryRecord entry {
        if self.head_id != "" and here.record_id != self.head_id {
            visit [-->] else { disengage; };
        } else {
            print(f"[forget] physical purge from {here.record_id}");
            if here.record_id not in self.visited_ids {
                self.visited_ids.append(here.record_id);
                here.active = False;
                self.purged_ids.append(here.record_id);
                print(f"  removed {here.record_id} from active index");
            }
            visit [->:Supersedes:->] else {
                print(f"  purged chain: {self.purged_ids}");
                disengage;
            }
        }
    }

    can purge_older with MemoryRecord entry {
        if here.record_id in self.visited_ids {
            print(f"  purged chain: {self.purged_ids}");
            disengage;
        } else {
            self.visited_ids.append(here.record_id);
            here.active = False;
            self.purged_ids.append(here.record_id);
            print(f"  removed {here.record_id} from active index");
            visit [->:Supersedes:->] else {
                print(f"  purged chain: {self.purged_ids}");
                disengage;
            }
        }
    }
}

