"""Crash-safe product workspace: revision ledger, preserved idea, and deterministic staleness propagation."""

node ProductWorkspace {
    has name: str = "";
    has stage: str = "init";
    has next_action: str = "";
}

node Idea {
    has original_text: str = "";
    has preserved: bool = True;
}

node Revision {
    has label: str = "";
    has content_hash: str = "";
    has revision_no: int = 0;
    has approved: bool = False;
    has stale: bool = False;
    has is_current: bool = False;
}

edge Contains { }

edge ParentOf { }

edge DependsOn {
    has note: str = "";
}

walker ResumeClerk {
    can start with Root entry {
        visit [-->];
    }

    can snapshot_workspace with ProductWorkspace entry {
        print(f"[RESUME] workspace={here.name} stage={here.stage} next={here.next_action}");
        visit [->:Contains:->];
    }

    can snapshot_idea with Idea entry {
        print(f"[RESUME] original_idea={here.original_text} preserved={here.preserved}");
    }

    can snapshot_revision with Revision entry {
        status_label = "STALE" if here.stale else "OK";
        head_label = "HEAD" if here.is_current else "history";
        appr_label = "approved" if here.approved else "draft";
        print(f"[RESUME] rev{here.revision_no} {here.label} ({head_label}/{appr_label}/{status_label}) hash={here.content_hash}");
    }
}

walker InvalidateUpstream {
    has trigger_hash: str = "";
    has found: bool = False;

    can audit with ProductWorkspace entry {
        visit [->:Contains:->];
        if self.found {
            print(f"[LEDGER] upstream hash={self.trigger_hash} superseded; stale dependents propagated");
        } else {
            print(f"[LEDGER] hash={self.trigger_hash} not found");
        }
    }

    can match with Revision entry {
        if here.content_hash == self.trigger_hash and not self.found {
            self.found = True;
            here.approved = False;
            here.is_current = False;
            here spawn (marker := CascadeMarker());
            print(f"[LEDGER] invalidated rev{here.revision_no} {here.label}; cascade marked {marker.marked} dependent(s)");
        }
        visit [-->];
    }
}

walker CascadeMarker {
    has origin_hash: str = "";
    has seen: list[str] = [];
    has marked: int = 0;

    can cascade with Revision entry {
        if not self.origin_hash {
            self.origin_hash = here.content_hash;
        }
        key = here.content_hash;
        if key != self.origin_hash {
            if key in self.seen {
                disengage;
            }
            self.seen.append(key);
            here.stale = True;
            here.is_current = False;
            if here.approved {
                here.approved = False;
            }
            self.marked += 1;
        }
        visit [<--:DependsOn:--] else { disengage; };
    }
}

