node Module {
    has name: str = "";
    has line_count: int = 0;
    has importable: bool = True;
}

node CliCommand {
    has name: str = "";
    has line_count: int = 0;
    has has_error_boundary: bool = False;
    has renders_before_write: bool = False;
}

node LibraryFn {
    has name: str = "";
    has line_count: int = 0;
    has returns_structured: bool = False;
}

node PrologueStep {
    has name: str = "";
    has order: int = 0;
    has required: bool = True;
}

edge Imports { }
edge ShouldCall { }
edge Reimplements { }
edge Requires { }

walker ImportCycleAuditor {
    has trail: list[str] = [];
    has cycles: int = 0;

    can start with Root entry {
        visit [-->[?:Module]];
    }

    can follow with Module entry {
        if here.name in self.trail {
            self.cycles += 1;
            print(f"[CYCLE] import SCC touches {here.name} (depth {len(self.trail)})");
            disengage;
        }
        self.trail.append(here.name);
        visit [->:Imports:->] else {
            disengage;
        };
        self.trail.pop();
    }
}

walker DelegationAuditor {
    has drift_count: int = 0;
    has checking_delegate: bool = False;

    can start with Root entry {
        visit [-->[?:CliCommand]];
    }

    can inspect with CliCommand entry {
        boundary = "thin" if here.has_error_boundary else "fat";
        policy = "render-then-write" if here.renders_before_write else "interleaved";
        print(f"[CMD] {here.name}: {here.line_count} lines, {boundary} boundary, {policy}");
        self.checking_delegate = True;
        visit [->:ShouldCall:->];
        self.checking_delegate = False;
        visit [->:Reimplements:->] else {
            disengage;
        };
    }

    can on_library with LibraryFn entry {
        if self.checking_delegate {
            print(f"  ok -> {here.name} (structured={here.returns_structured})");
        } else {
            self.drift_count += 1;
            print(f"  DRIFT: reimplements {here.name} instead of one shared renderer");
        }
        disengage;
    }
}

walker PrologueAuditor {
    has seen_orders: list[int] = [];

    can start with Root entry {
        visit [-->[?:CliCommand]];
    }

    can audit with CliCommand entry {
        self.seen_orders = [];
        print(f"[PROLOGUE] {here.name} wired steps:");
        visit [->:Requires:->] else {
            print("  (none)");
        };
        disengage;
    }

    can step with PrologueStep entry {
        self.seen_orders.append(here.order);
        flag = "required" if here.required else "optional";
        print(f"  [{here.order}] {here.name} ({flag})");
        disengage;
    }
}

walker PrologueGapReporter {
    has expected: list[int] = [1, 2, 3, 4];
    has cmd_name: str = "";
    has missing: list[str] = [];
    has seen_orders: list[int] = [];

    can start with Root entry {
        visit [-->[?:CliCommand]];
    }

    can begin with CliCommand entry {
        self.cmd_name = here.name;
        self.missing = [];
        self.seen_orders = [];
        visit [->:Requires:->] else {
            disengage;
        };
        for want in self.expected {
            if want not in self.seen_orders {
                self.missing.append(str(want));
            }
        }
        if len(self.missing) > 0 {
            gap = ", ".join(self.missing);
            print(f"[GAP] {self.cmd_name} skips prologue orders: {gap}");
        } else {
            print(f"[OK] {self.cmd_name} prologue complete");
        }
        disengage;
    }

    can capture with PrologueStep entry {
        self.seen_orders.append(here.order);
        disengage;
    }
}

