"""Agent fleet hierarchy: enforce parentless-orchestrator parents and contrast boolean vs true depth rendering."""

node Agent {
    has name: str = "";
    has created_order: int = 0;
    has available: bool = True;
}

node Orchestrator(Agent) {
}

node Worker(Agent) {
}

edge Manages {
}

walker DepthGuard {
    has violations: list[str] = [];
    has trace_depth: int = 0;

    can start with Root entry {
        visit [->:Manages:->] else { disengage; }
    }

    can descend with Orchestrator | Worker entry {
        next_depth = self.trace_depth + 1;
        if next_depth > 2 {
            self.violations.append(
                f"reject --parent: {here.name} would sit at depth {next_depth} (max 2)"
            );
        }
        saved = self.trace_depth;
        self.trace_depth = next_depth;
        visit [->:Manages:->] else { }
        self.trace_depth = saved;
    }
}

walker ParentPolicy {
    has violations: list[str] = [];

    can start with Root entry {
        visit [->:Manages:->] else { disengage; }
    }

    can scan_fleet with Orchestrator entry {
        visit [->:Manages:->] else { }
    }

    can probe_worker with Worker entry {
        visit [<-:Manages:<-] else {
            self.violations.append(f"{here.name}: worker has no parent link");
            visit [->:Manages:->] else { }
            disengage;
        }
    }

    can accept_orchestrator_parent with Orchestrator entry {
        visit [<-:Manages:<-] else {
            visit [->:Manages:->] else { }
            disengage;
        }
        self.violations.append(
            f"--parent must name parentless orchestrator, not nested {here.name}"
        );
        visit [->:Manages:->] else { }
        disengage;
    }

    can reject_worker_parent with Worker entry {
        self.violations.append(
            f"--parent must be orchestrator, not worker {here.name}"
        );
        visit [->:Manages:->] else { }
        disengage;
    }
}

