}

edge BenchmarkedBy { }
edge Precedes { }

walker MatrixAuditor {
    has targets_checked: int = 0;
    has targets_passed: int = 0;
    has first_failure: str = "";
    has report_lines: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can open_matrix with PerformanceSprint entry {
        here.matrix_complete = True;
        print(f"=== matrix iteration {here.iteration} for {here.plan_name} ===");
        visit [->:BenchmarkedBy:->] else { disengage; }
    }

    can score_target with BenchmarkTarget entry {
        self.targets_checked += 1;
        passed = here.meets_threshold();
        if passed {
            self.targets_passed += 1;
            line = f"[PASS] {here.name}: {here.actual_ms}ms <= {here.threshold_ms}ms";
        } else {
            if self.first_failure == "" {
                self.first_failure = here.name;
                line = f"[ACTIVE] {here.name}: {here.actual_ms}ms > {here.threshold_ms}ms";
            } else {
