            }
        }
        self.report_lines.append(line);
        print(line);
        visit [->:Precedes:->] else { disengage; }
    }

    can finalize with PerformanceSprint exit {
        if here.blocked_reason != "" {
            here.status = "blocked";
            print(f"BLOCKED: {here.blocked_reason}");
            return;
