        if self.first_failure == "" {
            here.status = "passed";
            here.active_target = "";
            print(f"CLOSURE: all {self.targets_checked} targets pass threshold");
        } else {
            here.status = "remediating";
            here.active_target = self.first_failure;
            print(f"REMEDIATING: active target remains {here.active_target}");
