"""Granular file shares: three permission levels, folder inheritance, and group targets."""

node FileItem {
    has path: str = "";
    has title: str = "";
}

node Folder(FileItem) { }

node File(FileItem) { }

node User {
    has name: str = "";
}

node Group {
    has name: str = "";
}

edge Child { }

edge OwnedBy { }

edge GroupOwned { }

edge MemberOf { }

edge ShareRo { }

edge ShareRw { }

edge ShareRwd { }

walker PermissionAuditor {
    has subject_name: str = "";
    has effective: int = 0;
    has pending_level: int = 0;
    has phase: str = "idle";
    has visited_paths: list[str] = [];

    def bump(level: int) {
        if level > self.effective {
            self.effective = level;
        }
    }

    def level_label() -> str {
        if self.effective >= 40 {
            return "MANAGE";
        }
        if self.effective >= 30 {
            return "EDIT";
        }
        if self.effective >= 20 {
            return "WRITE";
        }
        if self.effective >= 10 {
            return "VIEW";
        }
        return "NONE";
    }

    can start with Root entry {
        visit [-->];
    }

    can resolve_item with File | Folder entry {
        if self.phase != "idle" {
            disengage;
        }
        self.effective = 0;
        self.phase = "resolve";
        self.visited_paths = [];
        visit [->:OwnedBy:->];
        self.pending_level = 30;
        visit [->:GroupOwned:->];
        self.pending_level = 10;
        visit [->:ShareRo:->];
        self.pending_level = 20;
        visit [->:ShareRw:->];
        self.pending_level = 30;
        visit [->:ShareRwd:->];
        visit [<--:Child:<-];
        label = self.level_label();
        print(
            f"[PERM] {self.subject_name} on {here.title} ({here.path}): "
            f"{label} ({self.effective})"
        );
        self.phase = "idle";
        visit [-->];
    }

    can climb with Folder entry {
        if self.phase != "resolve" {
            disengage;
        }
        if here.path in self.visited_paths {
            print(f"[WARN] folder ancestry cycle at {here.path}");
            disengage;
        }
        self.visited_paths.append(here.path);
        self.pending_level = 10;
        visit [->:ShareRo:->];
        self.pending_level = 20;
        visit [->:ShareRw:->];
        self.pending_level = 30;
        visit [->:ShareRwd:->];
        visit [<--:Child:<-] else { disengage; }
    }

    can owner_hit with User exit {
        if self.phase == "resolve" && here.name == self.subject_name {
            self.bump(40);
        }
    }

    can share_group with Group entry {
        if self.phase != "resolve" {
            disengage;
        }
        visit [<-:MemberOf:<-];
    }

    can member_hit with User exit {
        if self.phase == "resolve" && here.name == self.subject_name {
            self.bump(self.pending_level);
        }
    }
}

with entry {
    alice = User(name="alice");
    bob = User(name="bob");
    carol = User(name="carol");
    team = Group(name="team");

    projects = Folder(path="/projects", title="Projects");
    specs = Folder(path="/projects/specs", title="Specs");
    readme = File(path="/projects/readme.md", title="Readme");
    doc = File(path="/projects/specs/doc.txt", title="Doc");

    bob +>:MemberOf:+> team;

    projects +>:OwnedBy:+> alice;
    projects +>:Child:+> specs;
    projects +>:Child:+> readme;
    specs +>:Child:+> doc;
    projects +>:ShareRwd:+> team;
    doc +>:ShareRo:+> carol;

    root ++> projects;

    root spawn PermissionAuditor(subject_name="alice");
    root spawn PermissionAuditor(subject_name="bob");
    root spawn PermissionAuditor(subject_name="carol");
}

