"""Gated graph-expansion evaluation: diagnose multi-hop retrieval failures, compare chunk, proposition, and entity-graph retrieval, and approve or reject schema expansion based on measured gain."""

node BenchmarkSubset {
    has label: str = "";
    has ready: bool = True;
}

node BaselineRun {
    has name: str = "";
    has ready: bool = True;
}

node EvalGate {
    has task_name: str = "";
    has approved: bool = False;
    has target_gain_pct: float = 0.0;
    has recorded_rejection: bool = False;
}

node RetrievalQuery {
    has text: str = "";
    has required_hops: int = 1;
}

node DocumentChunk {
    has content: str = "";
    has citation: str = "";
}

node Proposition {
    has statement: str = "";
    has confidence: float = 0.0;
    has provenance: str = "";
    has active: bool = True;
}

node NamedEntity {
    has surface_form: str = "";
    has canonical_name: str = "";
    has confidence: float = 0.0;
    has provenance: str = "";
    has active: bool = True;
}

edge DependsOn {
    has issue_ref: str = "";
}

edge SourcedFrom {
}

edge EntityLink {
    has predicate: str = "";
    has confidence: float = 0.0;
}

edge Supersedes {
    has reason: str = "";
}

walker DependencyGate {
    has subset_ok: bool = False;
    has baseline_ok: bool = False;

    can start with Root entry {
        visit [-->[?:EvalGate]];
    }

    can enter_gate with EvalGate entry {
        print(f"Entry criteria for: {here.task_name}");
        visit [->:DependsOn:->] else { disengage; };
    }

    can verify_subset with BenchmarkSubset entry {
        if here.ready {
            self.subset_ok = True;
            print(f"  satisfied #59 labeled subset: {here.label}");
        }
    }

    can verify_baseline with BaselineRun entry {
        if here.ready {
            self.baseline_ok = True;
            print(f"  satisfied #63 hybrid baseline: {here.name}");
        }
    }
}

walker MultiHopEvaluator {
    has query_text: str = "";
    has required_hops: int = 0;
    has chunk_count: int = 0;
    has proposition_count: int = 0;
    has entity_edge_hops: int = 0;
    has seen_entities: list[str] = [];
    has chunks_resolve: bool = False;
    has proposition_resolves: bool = False;
    has graph_resolves: bool = False;

    can start with Root entry {
        visit [-->[?:RetrievalQuery]];
    }

    can begin_query with RetrievalQuery entry {
        self.query_text = here.text;
        self.required_hops = here.required_hops;
        self.chunk_count = 0;
        self.proposition_count = 0;
        self.entity_edge_hops = 0;
        self.seen_entities = [];
        self.chunks_resolve = False;
        self.proposition_resolves = False;
        self.graph_resolves = False;
        print(f"\nDiagnosing query: {here.text}");
        print(f"  target multi-hop depth: {here.required_hops}");
        visit [-->[?:DocumentChunk]] else { disengage; };
    }

    can scan_chunk with DocumentChunk entry {
        self.chunk_count += 1;
        print(f"  [chunks-only] {here.citation}: {here.content}");
        visit [->:SourcedFrom:->] else { disengage; };
    }

    can scan_proposition with Proposition entry {
        if here.active {
            self.proposition_count += 1;
            print(
                f"  [proposition] conf={here.confidence} "
                f"prov={here.provenance}: {here.statement}"
            );
        }
    }

    can traverse_entity with NamedEntity entry {
        visit [<--:Supersedes:--] else { };
        if not here.active {
            disengage;
        }
        if here.canonical_name in self.seen_entities {
            disengage;
        }
        if len(self.seen_entities) > 0 {
            self.entity_edge_hops += 1;
        }
        self.seen_entities.append(here.canonical_name);
        hop_no = len(self.seen_entities);
        print(
            f"  [entity-graph] hop {hop_no}: {here.surface_form} "
            f"-> {here.canonical_name} (conf={here.confidence})"
        );
        visit [->:EntityLink:->] else { disengage; };
    }

    def summarize() {
        self.chunks_resolve = False;
        self.proposition_resolves = (
            self.proposition_count > 0
            and self.entity_edge_hops < self.required_hops
        );
        self.graph_resolves = self.entity_edge_hops >= self.required_hops;
        chunk_label = "FAIL" if not self.chunks_resolve else "PASS";
        prop_label = "PARTIAL" if self.proposition_resolves else "FAIL";
        graph_label = "PASS" if self.graph_resolves else "FAIL";
        print(f"  compare chunks-only: {chunk_label} ({self.chunk_count} chunks, no cross-link)");
        print(
            f"  compare proposition: {prop_label} "
            f"({self.proposition_count} propositions, no full hop chain)"
        );
        print(
            f"  compare entity-graph: {graph_label} "
            f"({self.entity_edge_hops} hops across entities)"
        );
    }
}

with entry {
    subset = BenchmarkSubset(label="multi-hop-labeled-subset", ready=True);
    baseline = BaselineRun(name="hybrid-retrieval-baseline", ready=True);
    gate = EvalGate(
        task_name="graph-expansion-eval",
        target_gain_pct=10.0
    );

    query = RetrievalQuery(
        text="Who maintains homelab DNS?",
        required_hops=2
    );
    chunk_infra = DocumentChunk(
        content="homelab runs Pi-hole for local DNS",
        citation="doc:infra/1"
    );
    chunk_meta = DocumentChunk(
        content="gwkline maintains homelab infrastructure repos",
        citation="doc:meta/2"
    );

    prop_dns = Proposition(
        statement="Pi-hole serves homelab DNS",
        confidence=0.82,
        provenance="doc:infra/1"
    );
    ent_homelab = NamedEntity(
        surface_form="homelab",
        canonical_name="infra:homelab",
        confidence=0.91,
        provenance="doc:infra/1"
    );
    ent_gwkline = NamedEntity(
        surface_form="gwkline",
        canonical_name="user:gwkline",
        confidence=0.88,
        provenance="doc:meta/2"
    );
    ent_dns = NamedEntity(
        surface_form="homelab DNS",
        canonical_name="service:homelab-dns",
        confidence=0.93,
        provenance="doc:infra/1"
    );
    ent_dns_old = NamedEntity(
        surface_form="dns",
        canonical_name="service:dns-legacy",
        confidence=0.35,
        provenance="doc:infra/0",
        active=False
    );

    root ++> gate;
    gate +>:DependsOn(issue_ref="#59"):+> subset;
    gate +>:DependsOn(issue_ref="#63"):+> baseline;

    root ++> query;
    query ++> chunk_infra;
    query ++> chunk_meta;

    chunk_infra +>:SourcedFrom:+> prop_dns;
    chunk_infra +>:SourcedFrom:+> ent_homelab;
    chunk_infra +>:SourcedFrom:+> ent_dns;
    chunk_meta +>:SourcedFrom:+> ent_gwkline;

    ent_homelab +>:EntityLink(predicate="owned_by", confidence=0.87):+> ent_gwkline;
    ent_gwkline +>:EntityLink(predicate="maintains", confidence=0.91):+> ent_dns;
    ent_dns +>:Supersedes(reason="canonicalization"):+> ent_dns_old;

    gate_walker = DependencyGate();
    root spawn gate_walker;

    if gate_walker.subset_ok and gate_walker.baseline_ok {
        gate.approved = True;
        print("\nEntry criteria met — running retrieval comparison");
        auditor = MultiHopEvaluator();
        root spawn auditor;
        auditor.summarize();
        measured_gain = float(auditor.entity_edge_hops) * 25.0;
        if auditor.graph_resolves and not auditor.chunks_resolve {
            if measured_gain >= gate.target_gain_pct {
                print(
                    f"\nAPPROVED: graph expansion justified "
                    f"(measured gain {measured_gain}% >= "
                    f"target {gate.target_gain_pct}%)"
                );
            } else {
                gate.recorded_rejection = True;
                print(
                    f"\nREJECTED: gain {measured_gain}% below target "
                    f"{gate.target_gain_pct}% — record rejection"
                );
            }
        } else {
            gate.recorded_rejection = True;
            print(
                "\nREJECTED: entity graph did not outperform chunks-only "
                "on multi-hop failures — record rejection"
            );
        }
    } else {
        gate.recorded_rejection = True;
        print("\nBLOCKED: waiting on #59 labeled subset and #63 baseline");
    }
}

"""Granular file shares: three permission levels, folder inheritance, and group targets."""

node FileItem {
    has path: str = "";
    has title: str = "";
}

node Folder(FileItem) { }

node File(FileItem) { }

node User {
    has name: str = "";
}

node Group {
    has name: str = "";
}

edge Child { }

edge OwnedBy { }

edge GroupOwned { }

edge MemberOf { }

edge ShareRo { }

edge ShareRw { }

edge ShareRwd { }

walker PermissionAuditor {
    has subject_name: str = "";
    has effective: int = 0;
    has pending_level: int = 0;
    has phase: str = "idle";
    has visited_paths: list[str] = [];

    def bump(level: int) {
        if level > self.effective {
            self.effective = level;
        }
    }

    def level_label() -> str {
        if self.effective >= 40 {
            return "MANAGE";
        }
        if self.effective >= 30 {
            return "EDIT";
        }
        if self.effective >= 20 {
            return "WRITE";
        }
        if self.effective >= 10 {
            return "VIEW";
        }
        return "NONE";
    }

    can start with Root entry {
        visit [-->];
    }

    can resolve_item with File | Folder entry {
        if self.phase != "idle" {
            disengage;
        }
        self.effective = 0;
        self.phase = "resolve";
        self.visited_paths = [];
        visit [->:OwnedBy:->];
        self.pending_level = 40;
        visit [->:GroupOwned:->];
        self.pending_level = 30;
        visit [->:ShareRo:->];
        self.pending_level = 10;
        visit [->:ShareRw:->];
        self.pending_level = 20;
        visit [->:ShareRwd:->];
        self.pending_level = 30;
        visit [<--:Child:--];
        label = self.level_label();
        print(
            f"[PERM] {self.subject_name} on {here.title} ({here.path}): "
            f"{label} ({self.effective})"
        );
        self.phase = "idle";
        visit [-->];
    }

    can climb with Folder entry {
        if self.phase != "resolve" {
            disengage;
        }
        if here.path in self.visited_paths {
            print(f"[WARN] folder ancestry cycle at {here.path}");
            disengage;
        }
        self.visited_paths.append(here.path);
        visit [->:ShareRo:->];
        self.pending_level = 10;
        visit [->:ShareRw:->];
        self.pending_level = 20;
        visit [->:ShareRwd:->];
        self.pending_level = 30;
        visit [<--:Child:--] else { disengage; }
    }

    can owner_hit with User exit {
        if self.phase == "resolve" && here.name == self.subject_name {
            self.bump(self.pending_level);
        }
    }

    can share_group with Group entry {
        if self.phase != "resolve" {
            disengage;
        }
        visit [<--:MemberOf:--];
    }

    can member_hit with User exit {
        if self.phase == "resolve" && here.name == self.subject_name {
            self.bump(self.pending_level);
        }
    }
}

with entry {
    alice = User(name="alice");
    bob = User(name="bob");
    carol = User(name="carol");
    team = Group(name="team");

    projects = Folder(path="/projects", title="Projects");
    specs = Folder(path="/projects/specs", title="Specs");
    readme = File(path="/projects/readme.md", title="Readme");
    doc = File(path="/projects/specs/doc.txt", title="Doc");

    bob +>:MemberOf:+> team;

    projects +>:OwnedBy:+> alice;
    projects +>:Child:+> specs;
    projects +>:Child:+> readme;
    specs +>:Child:+> doc;
    projects +>:ShareRwd:+> team;
    doc +>:ShareRo:+> carol;

    root ++> projects;

    root spawn PermissionAuditor(subject_name="alice");
    root spawn PermissionAuditor(subject_name="bob");
    root spawn PermissionAuditor(subject_name="carol");
}

"""Master upgrade backlog: builder bots reconcile repo evidence against behavioral verification."""

node BacklogEntry {
    has title: str = "";
    has has_evidence: bool = False;
    has verified: bool = False;

    def is_scaffold() -> bool {
        return self.has_evidence and not self.verified;
    }
}

node Foundation(BacklogEntry) {
    has verified: bool = True;
}

node GapItem(BacklogEntry) { }

node BacklogSection {
    has name: str = "";
}

edge Contains { }

edge DependsOn { }

walker BuilderReconciler {
    has scaffold_count: int = 0;
    has active_gap_count: int = 0;
    has foundation_count: int = 0;
    has dependency_stack: list[str] = [];

    can start with Root entry {
        print("=== Master Upgrade reconciliation ===");
        visit [->:Contains:->] else { disengage; };
    }

    can enter_section with BacklogSection entry {
        print(f"\n-- {here.name} --");
        visit [->:Contains:->];
        visit [-->];
    }

    can reconcile with GapItem | Foundation entry {
        if here.title in self.dependency_stack {
            print(f"[CYCLE] dependency loop at {here.title}");
            disengage;
        }
        self.dependency_stack.append(here.title);
        visit [->:DependsOn:->];
        if here.is_scaffold() {
            self.scaffold_count += 1;
            print(f"[SCAFFOLD] {here.title} - repo evidence without behavioral verification");
        } elif here.verified {
            self.foundation_count += 1;
            print(f"[FOUNDATION] {here.title}");
        } else {
            self.active_gap_count += 1;
            print(f"[ACTIVE] {here.title}");
        }
        self.dependency_stack = self.dependency_stack[:-1];
    }
}

with entry {
    buddy_sec = BacklogSection(name="Buddy core and UX");
    builder_sec = BacklogSection(name="Builder team and repo improvement");
    verify_sec = BacklogSection(name="Universal verification");

    root +>:Contains:+> buddy_sec;
    root +>:Contains:+> builder_sec;
    root +>:Contains:+> verify_sec;

    uv_contract = Foundation(title="Universal Verification contract");
    verify_sec +>:Contains:+> uv_contract;

    orchestrator = GapItem(title="Buddy as primary orchestrator", has_evidence=True, verified=False);
    mission_control = GapItem(title="Mission Control dashboard");
    buddy_sec +>:Contains:+> orchestrator;
    buddy_sec +>:Contains:+> mission_control;
    mission_control +>:DependsOn:+> orchestrator;

    reconciler_flow = Foundation(title="Builder Issue Reconciler workflow");
    daily_loop = GapItem(title="Builder daily readiness loop", has_evidence=True, verified=False);
    builder_sec +>:Contains:+> reconciler_flow;
    builder_sec +>:Contains:+> daily_loop;
    daily_loop +>:DependsOn:+> reconciler_flow;

    runner = Foundation(title="Verification runner foundation");
    expand_uv = GapItem(title="Production-grade verification expansion");
    verify_sec +>:Contains:+> runner;
    verify_sec +>:Contains:+> expand_uv;
    expand_uv +>:DependsOn:+> runner;

    bot = BuilderReconciler();
    root spawn bot;

    print(f"\nSummary: {bot.foundation_count} foundations, "
          f"{bot.active_gap_count} active gaps, "
          f"{bot.scaffold_count} scaffolds (evidence-only)");
}

