"""CEL modules: namespaced module_decl graph, local and asset imports, export resolution."""

node Project {
    has title: str = "";
}

node CelModule {
    has name: str = "";
    has domain: str = "general";
    has asset_id: str = "";
}

node Symbol {
    has sym_name: str = "";
    has exported: bool = True;
}

edge Contains { }
edge LocalImport { has alias: str = ""; }
edge AssetImport { has alias: str = ""; has asset_id: str = ""; }
edge Exports { }

walker ModuleResolver {
    has stack: list = [];
    has qualified_exports: list = [];
    has saw_cycle: bool = False;

    can start with Root entry {
        visit [-->];
    }

    can enter_project with Project entry {
        print(f"=== resolving CEL modules for {here.title} ===");
        visit [->:Contains:->] else { disengage; };
    }

    can resolve with CelModule entry {
        if here.name in self.stack {
            print(f"[CYCLE] import graph loops at '{here.name}'");
            self.saw_cycle = True;
            disengage;
        }
        self.stack.append(here.name);
        kind = "asset-ref" if here.asset_id else "local";
        depth = len(self.stack);
        print(f"{'  ' * depth}[module] {here.name} domain={here.domain} source={kind}");
        if here.asset_id {
            print(f"{'  ' * depth}  asset_id={here.asset_id}");
        }
        visit [->:Exports:->];
        visit [->:LocalImport:->];
        visit [->:AssetImport:->];
        self.stack.pop();
    }

    can catalog with Symbol entry {
        owner = self.stack[len(self.stack) - 1];
        qual = f"{owner}::{here.sym_name}";
        label = "export" if here.exported else "private";
        depth = len(self.stack) + 1;
        print(f"{'  ' * depth}[{label}] {qual}");
        self.qualified_exports.append(qual);
    }
}

walker AssetCatalogMirror {
    has records: list = [];

    can start with Root entry {
        visit [-->];
    }

    can scan with Project entry {
        visit [->:Contains:->] else { disengage; };
    }

    can mirror with CelModule entry {
        if here.asset_id {
            record = f"celModule|{here.asset_id}|{here.name}|{here.domain}";
            self.records.append(record);
            print(f"[asset-catalog] {record}");
        }
        visit [->:LocalImport:->];
        visit [->:AssetImport:->];
    }
}

with entry {
