        asset_id="cel-mod-audio-001",
    );
    math_mod = CelModule(name="mathcore", domain="general");

    suite +>:Contains:+> main_mod;
    main_mod +>:LocalImport(alias="vecutils"):+> vec_mod;
    main_mod +>:AssetImport(alias="dsp", asset_id="cel-mod-audio-001"):+> dsp_mod;
    vec_mod +>:LocalImport(alias="math"):+> math_mod;

    vec_mod +>:Exports:+> Symbol(sym_name="vec_add", exported=True);
    vec_mod +>:Exports:+> Symbol(sym_name="vec_dot", exported=True);
    dsp_mod +>:Exports:+> Symbol(sym_name="biquad", exported=True);
    dsp_mod +>:Exports:+> Symbol(sym_name="gain", exported=True);
    math_mod +>:Exports:+> Symbol(sym_name="clamp", exported=False);

    root spawn ModuleResolver();
    root spawn AssetCatalogMirror();

    print(f"qualified exports: {ModuleResolver().spawn root.qualified_exports}");
}

