"""Model OCC demo: CAS-guarded metadata, parent-token child writes, and cascade delete."""

node Model {
    has name: str = "";
    has current_version: int = 1;
    has last_version: int = 1;
    has deleted: bool = False;

    def try_alter(expected_version: int, new_name: str) -> str {
        if self.deleted {
            return "NoSuchEntityException";
        }
        if self.current_version != expected_version {
            return "OptimisticLockException";
        }
        self.name = new_name;
        next_token = self.current_version + 1;
        self.current_version = next_token;
        self.last_version = next_token;
        return "OK";
    }

    def try_cas_bump(expected_version: int) -> str {
        if self.deleted {
            return "NoSuchEntityException";
        }
        if self.current_version != expected_version {
            return "OptimisticLockException";
        }
        next_token = self.current_version + 1;
        self.current_version = next_token;
        self.last_version = next_token;
        return "OK";
    }

    def try_delete(expected_version: int) -> str {
        if self.deleted {
            return "NoSuchEntityException";
        }
        if self.current_version != expected_version {
            return "OptimisticLockException";
        }
        self.deleted = True;
        next_token = self.current_version + 1;
        self.current_version = next_token;
        self.last_version = next_token;
        return "OK";
    }
}

node ModelVersion {
    has version_num: int = 0;
    has uri: str = "";
    has purged: bool = False;
}

node Alias {
    has alias_name: str = "";
    has purged: bool = False;
}

edge HasVersion { }

edge HasAlias { }

walker ModelAlter {
    has expected_version: int = 0;
    has new_name: str = "";
    has outcome: str = "";

    can start with Model entry {
        self.outcome = here.try_alter(self.expected_version, self.new_name);
        label = "committed" if self.outcome == "OK" else self.outcome;
        print(f"[ModelAlter] {label} token={here.current_version} name={here.name}");
        disengage;
    }
}

walker VersionRegistrar {
    has expected_version: int = 0;
    has version_num: int = 0;
    has uri: str = "";
    has outcome: str = "";

    can start with Model entry {
        bump = here.try_cas_bump(self.expected_version);
        if bump != "OK" {
            self.outcome = bump;
            print(f"[VersionRegistrar] blocked before child write: {self.outcome}");
            disengage;
        }
        child = ModelVersion(version_num=self.version_num, uri=self.uri);
        here +>:HasVersion:+> child;
        self.outcome = "OK";
        print(f"[VersionRegistrar] registered v{self.version_num} at token {here.current_version}");
        disengage;
    }
}

walker CascadeDeleter {
    has expected_version: int = 0;
    has outcome: str = "";

    can start with Model entry {
        self.outcome = here.try_delete(self.expected_version);
        if self.outcome != "OK" {
            print(f"[CascadeDeleter] blocked: {self.outcome}");
            disengage;
        }
        visit [->:HasVersion:->];
        visit [->:HasAlias:->];
        print(f"[CascadeDeleter] root CAS ok; dependents purged at token {here.current_version}");
        disengage;
    }

    can purge_version with ModelVersion entry {
        here.purged = True;
    }

    can purge_alias with Alias entry {
        here.purged = True;
    }
}

walker InventoryAuditor {
    can start with Root entry {
        visit [-->] else { disengage; };
    }

    can inspect_model with Model entry {
        flag = "DELETED" if here.deleted else "ACTIVE";
        print(f"MODEL {here.name} [{flag}] occ={here.current_version}/{here.last_version}");
        visit [->:HasVersion:->];
        visit [->:HasAlias:->];
        visit [-->] else { disengage; };
    }

    can inspect_version with ModelVersion entry {
        flag = "PURGED" if here.purged else "LIVE";
        print(f"  VERSION {here.version_num} {here.uri} [{flag}]");
        visit [-->] else { disengage; };
    }

    can inspect_alias with Alias entry {
        flag = "PURGED" if here.purged else "LIVE";
        print(f"  ALIAS {here.alias_name} [{flag}]");
        visit [-->] else { disengage; };
    }
}

with entry {
    model = Model(name="llama3", current_version=1, last_version=1);
    root ++> model;
    model +>:HasVersion:+> ModelVersion(version_num=1, uri="s3://bucket/v1");
    model +>:HasAlias:+> Alias(alias_name="latest");

    print("== two alters from token 1 (one wins, one conflicts) ==");
    ModelAlter(expected_version=1, new_name="llama3-plus") spawn model;
    ModelAlter(expected_version=1, new_name="llama3-stale") spawn model;

    print("== version register bumps parent token before child insert ==");
    VersionRegistrar(expected_version=2, version_num=2, uri="s3://bucket/v2") spawn model;

    print("== stale version register blocked (no partial child row) ==");
    VersionRegistrar(expected_version=2, version_num=3, uri="s3://bucket/v3") spawn model;

    print("== inventory after races ==");
    root spawn InventoryAuditor();

    print("== stale delete conflicts ==");
    CascadeDeleter(expected_version=2) spawn model;

    print("== current delete CAS then cascade purge ==");
    CascadeDeleter(expected_version=3) spawn model;

    print("== alter on deleted model -> NoSuchEntityException ==");
    ModelAlter(expected_version=4, new_name="ghost") spawn model;

    print("== final inventory ==");
    root spawn InventoryAuditor();
}

"""Read-only lazy graph traversal: ResourceHandle resolve on enter, release on leave, cycle-safe dispatch."""

node CaseResource {
    has uid: str = "";
    has title: str = "";
    has materialized: bool = False;

    def resolve() -> None {
        if not self.materialized {
            self.materialized = True;
        }
    }

    def release() -> None {
        self.materialized = False;
    }

    def kind_name() -> str {
        return "Resource";
    }
}

node CaseFile(CaseResource) {
    has docket: str = "";
    override def kind_name() -> str {
        return "CaseFile";
    }
}

node EvidenceItem(CaseResource) {
    has exhibit: str = "";
    override def kind_name() -> str {
        return "EvidenceItem";
    }
}

node LegalEffectNode(CaseResource) {
    has effect: str = "";
    override def kind_name() -> str {
        return "LegalEffect";
    }
}

edge References {
    has property_name: str = "";
}

edge LegalEffect {
    has statute: str = "";
}

walker ReadOnlyDispatcher {
    has visited: list[str] = [];
    has active_handles: int = 0;
    has stopped: bool = False;
    has prune_legal: bool = False;

    def indent() -> str {
        depth = len(self.visited);
        return "  " * depth;
    }

    can start with Root entry {
        print("=== read-only lazy traversal (resolve before enter, release after leave) ===");
        visit [-->];
        print(f"=== traversal finished; active_handles={self.active_handles} ===");
    }

    can dispatch with CaseResource entry {
        if self.stopped {
            disengage;
        }
        uid = here.uid;
        for prior in self.visited {
            if prior == uid {
                print(f"{self.indent()}[CYCLE] blocked revisit of {uid}");
                disengage;
            }
        }
        self.visited.append(uid);
        here.resolve();
        self.active_handles += 1;
        print(
            f"{self.indent()}[ENTER] {here.kind_name()} {uid} "
            f"title={here.title} materialized={here.materialized}"
        );
        if uid == "ev-102" {
            print(f"{self.indent()}[STOP] visitor requested early halt at {uid}");
            self.stopped = True;
            here.release();
            self.active_handles -= 1;
            print(
                f"{self.indent()}[LEAVE] {here.kind_name()} {uid} "
                f"released materialized={here.materialized}"
            );
            self.visited.pop();
            disengage;
        }
        visit [->:References:->] else { };
        if not self.prune_legal {
            visit [->:LegalEffect:->] else { };
        } else {
            print(f"{self.indent()}[PRUNE] legal-effect edges omitted from walk");
        }
        here.release();
        self.active_handles -= 1;
        print(
            f"{self.indent()}[LEAVE] {here.kind_name()} {uid} "
            f"released materialized={here.materialized}"
        );
        self.visited.pop();
    }

    can walk_reference with References entry {
        print(
            f"{self.indent()}  [EDGE/References] property={here.property_name}"
        );
        visit [-->];
    }

    can walk_legal with LegalEffect entry {
        print(f"{self.indent()}  [EDGE/LegalEffect] statute={here.statute}");
        visit [-->];
    }
}

with entry {
    root ++> (case_root := CaseFile(
        uid="case-001",
        title="Smith v. City",
        docket="24-CV-100"
    ));
    case_root +>:References(property_name="exhibit_a"):+> (ev_a := EvidenceItem(
        uid="ev-101",
        title="Bodycam footage",
        exhibit="A"
    ));
    case_root +>:References(property_name="exhibit_b"):+> EvidenceItem(
        uid="ev-102",
        title="IA report",
        exhibit="B"
    );
    case_root +>:LegalEffect(statute="42-USC-1983"):+> LegalEffectNode(
        uid="le-01",
        title="Dismissal barred",
        effect="res judicata"
    );
    ev_a +>:References(property_name="parent_case"):+> case_root;
    root spawn ReadOnlyDispatcher(prune_legal=False);
    print("--- second pass: prune legal-effect branch ---");
    root spawn ReadOnlyDispatcher(prune_legal=True);
}

"""Workshop order graph: audit environment checks reachable before tool install."""

node Page {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has slug: str = "";
    has learner_position: int = 0;
}

node SideQuest(Page) {
    has branches_from: int = 0;
}

node Tool {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has cli_name: str = "";
    has install_at_step: int = 0;
}

node VerifyCheck {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has command: str = "";
}

edge Next { }
edge BranchesFrom { }
edge HasCheck { }
edge NeedsTool { }

walker OrderAuditor {
    has visited_slugs: list[str] = [];
    has findings: list[str] = [];
    has current_slug: str = "";
    has current_position: int = 0;
    has pending_command: str = "";

    can start with Root entry {
        visit [-->];
    }

    can audit with Page | SideQuest entry {
        if here.slug in self.visited_slugs {
            disengage;
        }
        self.visited_slugs.append(here.slug);
        self.current_slug = here.slug;
        self.current_position = here.learner_position;
        visit [->:HasCheck:->];
        visit [->:Next:->];
        visit [->:BranchesFrom:->];
    }

    can read_check with VerifyCheck entry {
        self.pending_command = here.command;
        visit [->:NeedsTool:->];
    }

    can probe_tool with Tool entry {
        if here.install_at_step > self.current_position {
            line = (
                f"[ORDERING] {self.current_slug} runs "
                f"'{self.pending_command}' but {here.cli_name} "
                f"is not installed until step {here.install_at_step} "
                f"(learner at step {self.current_position})"
            );
            self.findings.append(line);
            print(line);
        }
    }
}

