"""SECB-WP-FWK-078: materialize Git evidence prerequisites and forbid green required-test skips."""

node GitObject {
    has label: str = "";
    has materialized: bool = False;
}

node GitCommit(GitObject) {
    has oid: str = "";
}

node GitRef(GitObject) {
    has ref_name: str = "";
}

node ObservationContract {
    has observation_id: str = "";
    has checkout_profile: str = "HEAD_ONLY";
    has skip_policy: str = "FORBIDDEN";
    has ancestry_state: str = "NOT_REQUIRED";
    has check_state: str = "NOT_RUN";
}

node RequiredAssertion {
    has name: str = "";
    has measurement_state: str = "NOT_RUN";
}

edge Requires { }
edge Cites { }

walker EvidenceVerifier {
    has workspace_profile: str = "HEAD_ONLY";
    has absent: list[str] = [];
    has passed: int = 0;
    has incomplete: int = 0;
    has prerequisite_fail: bool = False;
    has seen_labels: list[str] = [];

    can start with Root entry {
        print(f"workspace checkout profile: {self.workspace_profile}");
        visit [-->];
    }

    can audit with ObservationContract entry {
        profile_ok = True;
        if here.checkout_profile == "ANCESTRY_PATH" and self.workspace_profile == "HEAD_ONLY" {
            profile_ok = False;
            self.prerequisite_fail = True;
            print(
                f"[PREFLIGHT] {here.observation_id}: HEAD_ONLY under-provisions ANCESTRY_PATH"
            );
        }
        if here.ancestry_state != "PROVEN" and here.checkout_profile == "ANCESTRY_PATH" {
            self.prerequisite_fail = True;
            print(f"[ANCESTRY] state={here.ancestry_state}, required PROVEN");
        }
        if not profile_ok or here.ancestry_state != "PROVEN" {
            here.check_state = "NON_SUCCESS";
        }
        visit [->:Cites:->] else { };
        visit [->:Requires:->] else { };
        visit [-->];
    }

    can probe with GitCommit | GitRef entry {
        key = here.label;
        if key not in self.seen_labels {
            self.seen_labels.append(key);
            if not here.materialized {
                self.absent.append(key);
                print(f"[ABSENT] {key} not materialized locally");
            }
        }
        visit [-->] else { disengage; };
    }

    can execute with RequiredAssertion entry {
        blocked = self.prerequisite_fail or len(self.absent) > 0;
        if blocked {
            here.measurement_state = "INCOMPLETE";
            self.incomplete += 1;
            print(f"[INCOMPLETE] {here.name}: prerequisite missing (skip forbidden)");
        } else {
            here.measurement_state = "RECOMPUTED";
            self.passed += 1;
            print(f"[VERIFIED] {here.name}");
        }
        visit [-->] else { disengage; };
    }
}

