"""Model OCC demo: CAS-guarded metadata, parent-token child writes, and cascade delete."""

edge OwnsVersion { }

edge OwnsAlias { }

node Model {
    has name: str = "";
    has current_version: int = 1;
    has last_version: int = 1;
    has deleted: bool = False;

    def try_alter(expected_version: int, new_name: str) -> str {
        if self.deleted {
            return "NoSuchEntityException";
        }
        if self.current_version != expected_version {
            return "OptimisticLockException";
        }
        self.name = new_name;
        next_token = self.current_version + 1;
        self.current_version = next_token;
        self.last_version = next_token;
        return "OK";
    }

    def try_cas_bump(expected_version: int) -> str {
        if self.deleted {
            return "NoSuchEntityException";
        }
        if self.current_version != expected_version {
            return "OptimisticLockException";
        }
        next_token = self.current_version + 1;
        self.current_version = next_token;
        self.last_version = next_token;
        return "OK";
    }

    def try_delete(expected_version: int) -> str {
        if self.deleted {
            return "NoSuchEntityException";
        }
        if self.current_version != expected_version {
            return "OptimisticLockException";
        }
        self.deleted = True;
        next_token = self.current_version + 1;
        self.current_version = next_token;
        self.last_version = next_token;
        return "OK";
    }
}

node ModelVersion {
    has version_num: int = 0;
    has uri: str = "";
    has purged: bool = False;
}

node Alias {
    has alias_name: str = "";
    has purged: bool = False;
}

walker ModelAlter {
    has expected_version: int = 0;
    has new_name: str = "";
    has outcome: str = "";

    can start with Model entry {
        self.outcome = here.try_alter(self.expected_version, self.new_name);
        label = "committed" if self.outcome == "OK" else self.outcome;
        print(f"[ModelAlter] {label} token={here.current_version} name={here.name}");
        disengage;
    }
}

walker VersionRegistrar {
    has expected_version: int = 0;
    has version_num: int = 0;
    has uri: str = "";
    has outcome: str = "";

    can start with Model entry {
        bump = here.try_cas_bump(self.expected_version);
        if bump != "OK" {
            self.outcome = bump;
            print(f"[VersionRegistrar] blocked before child write: {self.outcome}");
            disengage;
        }
        child = ModelVersion(version_num=self.version_num, uri=self.uri);
        here +>:OwnsVersion:+> child;
        self.outcome = "OK";
        print(f"[VersionRegistrar] registered v{self.version_num} at token {here.current_version}");
        disengage;
    }
}

walker CascadeDeleter {
    has expected_version: int = 0;
    has outcome: str = "";

    can start with Model entry {
        self.outcome = here.try_delete(self.expected_version);
        if self.outcome != "OK" {
            print(f"[CascadeDeleter] blocked: {self.outcome}");
            disengage;
        }
        visit [->:OwnsVersion:->];
        visit [->:OwnsAlias:->];
        print(f"[CascadeDeleter] root CAS ok; dependents purged at token {here.current_version}");
        disengage;
    }

    can purge_version with ModelVersion entry {
        here.purged = True;
        visit [-->] else { disengage; };
    }

    can purge_alias with Alias entry {
        here.purged = True;
        visit [-->] else { disengage; };
    }
}

walker InventoryAuditor {
    can start with Root entry {
        visit [-->] else { disengage; };
    }

    can inspect_model with Model entry {
        flag = "DELETED" if here.deleted else "ACTIVE";
        print(f"MODEL {here.name} [{flag}] occ={here.current_version}/{here.last_version}");
        visit [->:OwnsVersion:->];
        visit [->:OwnsAlias:->];
        visit [-->] else { disengage; };
    }

    can inspect_version with ModelVersion entry {
        flag = "PURGED" if here.purged else "LIVE";
        print(f"  VERSION {here.version_num} {here.uri} [{flag}]");
        visit [-->] else { disengage; };
    }

    can inspect_alias with Alias entry {
        flag = "PURGED" if here.purged else "LIVE";
        print(f"  ALIAS {here.alias_name} [{flag}]");
        visit [-->] else { disengage; };
    }
}

with entry {
    model = Model(name="llama3", current_version=1, last_version=1);
    root ++> model;
    model +>:OwnsVersion:+> ModelVersion(version_num=1, uri="s3://bucket/v1");
    model +>:OwnsAlias:+> Alias(alias_name="latest");

    print("== two alters from token 1 (one wins, one conflicts) ==");
    model spawn ModelAlter(expected_version=1, new_name="llama3-plus");
    model spawn ModelAlter(expected_version=1, new_name="llama3-stale");

    print("== version register bumps parent token before child insert ==");
    model spawn VersionRegistrar(expected_version=2, version_num=2, uri="s3://bucket/v2");

    print("== stale version register blocked (no partial child row) ==");
    model spawn VersionRegistrar(expected_version=2, version_num=3, uri="s3://bucket/v3");

    print("== inventory after races ==");
    root spawn InventoryAuditor();

    print("== stale delete conflicts ==");
    model spawn CascadeDeleter(expected_version=2);

    print("== current delete CAS then cascade purge ==");
    model spawn CascadeDeleter(expected_version=3);

    print("== alter on deleted model -> NoSuchEntityException ==");
    model spawn ModelAlter(expected_version=4, new_name="ghost");

    print("== final inventory ==");
    root spawn InventoryAuditor();
}

"""Runtime dependency ratchet: witness that dev-only packages and commands stay off the fak runtime closure."""

node Package {
    has name: str = "";
    has dev_only: bool = False;
}

node Command {
    has verb: str = "";
    has dev_only: bool = False;
}

node Binary {
    has name: str = "";
    has surface: str = "runtime";
}

edge Imports { }

edge Dispatches { }

walker DependencyRatchet {
    has violations: list[str] = [];
    has seen: list[str] = [];
    has auditing_runtime: bool = False;

    can start with Root entry {
        visit [-->];
    }

    can audit_binary with Binary entry {
        if here.surface == "runtime" {
            self.auditing_runtime = True;
            self.seen = [];
            print(f"[ratchet] auditing {here.name} dependency closure");
            visit [->:Imports:->] else { disengage; }
            visit [->:Dispatches:->] else { disengage; }
            passed = len(self.violations) == 0;
            status = "OK" if passed else "FAILED";
            print(f"[ratchet] {here.name}: {status} — {len(self.violations)} violation(s)");
            self.auditing_runtime = False;
        } else {
            print(f"[skip] {here.name} is a dev-owned binary surface");
        }
        visit [-->];
    }

    can walk_package with Package entry {
        if not self.auditing_runtime {
            disengage;
        }
        if here.name in self.seen {
            print(f"  [cycle-guard] already visited {here.name}");
            disengage;
        }
        self.seen.append(here.name);
        if here.dev_only {
            leak = f"runtime closure reaches dev-only package {here.name}";
            self.violations.append(leak);
            print(f"  [LEAK] {here.name}");
        } else {
            print(f"  [pkg] {here.name}");
        }
        visit [->:Imports:->] else { disengage; }
    }

    can walk_command with Command entry {
        if not self.auditing_runtime {
            disengage;
        }
        if here.dev_only {
            leak = f"runtime surface dispatches dev-only verb {here.verb}";
            self.violations.append(leak);
            print(f"  [LEAK] dev verb '{here.verb}' registered on runtime");
        } else {
            print(f"  [cmd] {here.verb}");
        }
        disengage;
    }
}

with entry {
    fak = Binary(name="fak", surface="runtime");
    fak_dev = Binary(name="fak-dev", surface="dev");

    cmd_fak = Package(name="cmd/fak", dev_only=False);
    guard_pkg = Package(name="internal/guard", dev_only=False);
    serve_pkg = Package(name="internal/serve", dev_only=False);
    devindex = Package(name="internal/devindex", dev_only=True);
    issuecontract = Package(name="internal/issuecontract", dev_only=True);
