    guard_cmd = Command(verb="guard", dev_only=False);
    serve_cmd = Command(verb="serve", dev_only=False);
    wiki_cmd = Command(verb="wiki", dev_only=True);
    index_cmd = Command(verb="index", dev_only=True);

    root ++> fak;
    root ++> fak_dev;

    fak +>:Imports:+> cmd_fak;
    cmd_fak +>:Imports:+> guard_pkg;
    cmd_fak +>:Imports:+> serve_pkg;
    cmd_fak +>:Imports:+> devindex;
    devindex +>:Imports:+> issuecontract;

    fak +>:Dispatches:+> guard_cmd;
    fak +>:Dispatches:+> serve_cmd;
    fak +>:Dispatches:+> wiki_cmd;

    fak_dev +>:Dispatches:+> wiki_cmd;
    fak_dev +>:Dispatches:+> index_cmd;
    fak_dev +>:Imports:+> wiki_pkg;
    fak_dev +>:Imports:+> devindex;

    ratchet = DependencyRatchet();
    root spawn ratchet;

    witness_ok = len(ratchet.violations) == 0;
    verdict = "PASS" if witness_ok else "FAIL";
    print(f"\ngraph witness: {verdict} — ratchet must reach zero before #6022 closes");
}

