"""Ontime optional extras: model minimal core install vs heavy ML backend dependencies."""

node Package {
    has name: str = "";
    has version: str = "0.1.0";
}

node Module {
    has name: str = "";
    has is_core: bool = False;
    has size_mb: int = 0;
}

node Extra {
    has name: str = "";
    has pip_spec: str = "";
    has installed: bool = False;
}

edge PartOf { }
edge NeedsExtra { }
edge Includes { }

walker MinimalInstallAuditor {
    has core_modules: list[str] = [];
    has heavy_modules: list[str] = [];
    has total_core_mb: int = 0;
    has total_heavy_mb: int = 0;

    can start with Root entry {
        print("=== Auditing ontime install footprint ===");
        visit [-->];
    }

    can enter with Package entry {
        print(f"Package: {here.name} v{here.version}");
        visit [->:PartOf:->] else { disengage; };
        print(f"--- Summary: core {self.total_core_mb} MB ({len(self.core_modules)} modules), "
              f"heavy {self.total_heavy_mb} MB ({len(self.heavy_modules)} modules need extras) ---");
    }

    can catalog with Module entry {
        if here.is_core {
            self.core_modules.append(here.name);
            self.total_core_mb += here.size_mb;
            print(f"  [CORE] {here.name} ({here.size_mb} MB)");
        } else {
            self.heavy_modules.append(here.name);
            self.total_heavy_mb += here.size_mb;
            print(f"  [HEAVY] {here.name} ({here.size_mb} MB) — optional extra required");
        }
        visit [->:NeedsExtra:->] else { visit [-->] else { disengage; }; };
    }

    can note_extra with Extra entry {
        status_label = "installed" if here.installed else "missing";
        print(f"    -> extra '{here.name}' [{status_label}]: pip install ontime[{here.pip_spec}]");
        visit [-->] else { disengage; };
    }
}

walker ImportGate {
    has target_module: str = "";
    has allowed: bool = False;
    has error_msg: str = "";

    can start with Root entry {
        print(f"=== Import gate: ontime.{self.target_module} ===");
        visit [-->];
    }

    can scan with Package entry {
        visit [->:PartOf:->] else { disengage; };
    }

    can probe with Module entry {
        if here.name == self.target_module {
            if here.is_core {
                self.allowed = True;
                print(f"OK: {here.name} available in base install");
                disengage;
            } else {
                visit [->:NeedsExtra:->] else {
                    self.error_msg = f"ontime.{self.target_module} has no extra mapping";
                    print(f"ERROR: {self.error_msg}");
                    disengage;
                };
            }
        } else {
            visit [-->] else { disengage; };
        }
    }

    can verify_extra with Extra entry {
        if here.installed {
            self.allowed = True;
            print(f"OK: '{here.name}' extra satisfies {self.target_module}");
        } else {
            self.error_msg = f"ontime.{self.target_module} requires the '{here.name}' extra: pip install ontime[{here.pip_spec}]";
            print(f"ERROR: {self.error_msg}");
        }
        disengage;
    }
}

walker ExtraResolver {
    has target_extra: str = "all";
    has resolved: list[str] = [];
    has visited: list[str] = [];

    def already_seen(extra_name: str) -> bool {
        for prior in self.visited {
            if prior == extra_name {
                return True;
            }
        }
        return False;
    }

    def mark(extra_name: str) -> bool {
        if self.already_seen(extra_name) {
            print(f"CYCLE detected at extra '{extra_name}'");
            return False;
        }
        self.visited.append(extra_name);
        if extra_name not in self.resolved {
            self.resolved.append(extra_name);
        }
        return True;
    }

    can start with Root entry {
        print(f"=== Resolving extra '{self.target_extra}' dependency tree ===");
        visit [-->[?:Extra]];
    }

    can locate with Extra entry {
        if here.name != self.target_extra {
            visit [-->] else { disengage; };
        } else {
            if self.mark(here.name) {
                print(f"resolve: {here.name} -> pip install ontime[{here.pip_spec}]");
                visit [->:Includes:->] else { disengage; };
            } else {
                disengage;
            }
        }
    }

    can expand with Extra entry {
        if self.mark(here.name) {
            print(f"  includes: {here.name} -> pip install ontime[{here.pip_spec}]");
            visit [->:Includes:->] else { disengage; };
        } else {
            disengage;
        }
    }
}

