"""Runtime dependency ratchet: witness that dev-only packages and commands stay off the fak runtime closure."""

node Package {
    has name: str = "";
    has dev_only: bool = False;
}

node Command {
    has verb: str = "";
    has dev_only: bool = False;
}

node Binary {
    has name: str = "";
    has surface: str = "runtime";
}

edge Imports { }

edge Dispatches { }

walker DependencyRatchet {
    has violations: list[str] = [];
    has seen: list[str] = [];
    has auditing_runtime: bool = False;

    can start with Root entry {
        visit [-->];
    }

    can audit_binary with Binary entry {
        if here.surface == "runtime" {
            self.auditing_runtime = True;
            self.seen = [];
            print(f"[ratchet] auditing {here.name} dependency closure");
            visit [->:Imports:->] else { disengage; }
            visit [->:Dispatches:->] else { disengage; }
            passed = len(self.violations) == 0;
            status = "OK" if passed else "FAILED";
            print(f"[ratchet] {here.name}: {status} — {len(self.violations)} violation(s)");
            self.auditing_runtime = False;
        } else {
            print(f"[skip] {here.name} is a dev-owned binary surface");
        }
        visit [-->];
    }

    can walk_package with Package entry {
        if not self.auditing_runtime {
            disengage;
        }
        if here.name in self.seen {
            print(f"  [cycle-guard] already visited {here.name}");
            disengage;
        }
        self.seen.append(here.name);
        if here.dev_only {
            leak = f"runtime closure reaches dev-only package {here.name}";
            self.violations.append(leak);
            print(f"  [LEAK] {here.name}");
        } else {
            print(f"  [pkg] {here.name}");
        }
        visit [->:Imports:->] else { disengage; }
    }

    can walk_command with Command entry {
        if not self.auditing_runtime {
            disengage;
        }
        if here.dev_only {
            leak = f"runtime surface dispatches dev-only verb {here.verb}";
            self.violations.append(leak);
            print(f"  [LEAK] dev verb '{here.verb}' registered on runtime");
        } else {
            print(f"  [cmd] {here.verb}");
        }
        disengage;
    }
}

