"""Relay scoped delegation: broker-owned task tree, narrow-only grants, cycle guard, revoke cascade."""

node Task {
    has task_id: str = "";
    has depth: int = 0;
    has grant_max_depth: int = 0;
    has remaining_budget: int = 0;
    has max_children: int = 0;
    has child_count: int = 0;
    has read_only: bool = True;
    has provider: str = "";
    has spawn_allowed: bool = False;
    has revoked: bool = False;
}

edge DelegatesTo { }
edge SiblingGrant { }

walker CycleGuard {
    has hunt_id: str = "";
    has detected: bool = False;

    can climb with Task entry {
        if here.task_id == self.hunt_id {
            self.detected = True;
            disengage;
        }
        visit [<--:DelegatesTo:--] else { disengage; };
    }
}

walker RevokeCascade {
    can cascade with Task entry {
        here.revoked = True;
        visit [->:DelegatesTo:->] else { disengage; };
    }
}

walker SiblingProbe {
    has visible: list[str] = [];

    can start with Task entry {
        visit [->:SiblingGrant:->] else { disengage; };
    }

    can peer with Task entry {
        self.visible.append(here.task_id);
        disengage;
    }
}

walker GrantAuditor {
    has revoked_ids: list[str] = [];
    has active_ids: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can scan with Task entry {
        if here.revoked {
            self.revoked_ids.append(here.task_id);
        } else {
            self.active_ids.append(here.task_id);
        }
        visit [->:DelegatesTo:->] else { disengage; };
    }
}

walker DelegationBroker {
    has violations: list[str] = [];
    has approvals: list[str] = [];

    def authorize_spawn(parent: Task, child: Task, reserve: int) -> bool {
        if parent.revoked {
            self.violations.append(f"{child.task_id}:parent_revoked");
            return False;
        }
        if not parent.spawn_allowed {
            self.violations.append(f"{child.task_id}:spawn_disabled");
            return False;
        }
        next_depth = parent.depth + 1;
        if next_depth > parent.grant_max_depth {
            self.violations.append(f"{child.task_id}:depth_violation");
            return False;
        }
        if parent.child_count >= parent.max_children {
            self.violations.append(f"{child.task_id}:fanout_exceeded");
            return False;
        }
        if child.remaining_budget > parent.remaining_budget {
            self.violations.append(f"{child.task_id}:budget_widen");
            return False;
        }
        if reserve > parent.remaining_budget {
            self.violations.append(f"{child.task_id}:budget_reserve");
            return False;
        }
        if not child.read_only {
            self.violations.append(f"{child.task_id}:readonly_widen");
            return False;
        }
        guard = CycleGuard(hunt_id=child.task_id);
        parent spawn guard;
        if guard.detected {
            self.violations.append(f"{child.task_id}:cycle");
            return False;
        }
        parent +>:DelegatesTo:+> child;
        parent.child_count += 1;
        parent.remaining_budget -= reserve;
        child.depth = next_depth;
        narrowed_depth = child.grant_max_depth if child.grant_max_depth < parent.grant_max_depth else parent.grant_max_depth;
        child.grant_max_depth = narrowed_depth;
        child.spawn_allowed = parent.grant_max_depth > next_depth;
        self.approvals.append(child.task_id);
        return True;
    }
}

