"""Const expression evaluation in dependency order with cycle detection.

Models HIR const nodes, function-hosted nested consts, and a
pending/evaluating/done state machine that evaluates dependencies before
dependents while caching done results and rejecting recursive cycles.
"""

node ConstExpr {
    has name: str = "";
    has base_cost: int = 1;
    has value: int = 0;
    has state: str = "pending";
    has eval_count: int = 0;
}

node FnSymbol {
    has name: str = "";
}

edge DependsOn { }

edge Invokes { }

edge NestedIn { }

def sum_const_dependencies(host: ConstExpr) -> int {
    total = 0;
    for dep in [host->:DependsOn:->] {
        if dep is ConstExpr {
            total += dep.value;
        }
    }
    for callee in [host->:Invokes:->] {
        for nested in [callee->:NestedIn:->] {
            if nested is ConstExpr {
                total += nested.value;
            }
        }
    }
    return total;
}

walker ConstEvaluator {
    has eval_order: list[str] = [];
    has cycle_errors: list[str] = [];
    has charged_cost: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can resolve_symbol with FnSymbol entry {
        visit [->:NestedIn:->];
    }

    can evaluate with ConstExpr entry {
        if here.state == "done" {
            visit [-->];
        } elif here.state == "evaluating" {
            self.cycle_errors.append(f"dependency cycle at '{here.name}'");
            disengage;
        } else {
            here.state = "evaluating";
            visit [->:DependsOn:->];
            visit [->:Invokes:->];
            deps_total = sum_const_dependencies(here);
            here.value = here.base_cost + deps_total;
            here.state = "done";
            here.eval_count += 1;
            self.eval_order.append(here.name);
            self.charged_cost += here.base_cost;
            visit [-->];
        }
    }
}

with entry {
    shared = ConstExpr(name="SHARED", base_cost=10);
    inner = ConstExpr(name="INNER", base_cost=7);
    helper = FnSymbol(name="helper_fn");
    helper +>:NestedIn:+> inner;

    mid = ConstExpr(name="MID", base_cost=3);
    top = ConstExpr(name="TOP", base_cost=2);
    mid +>:DependsOn:+> shared;
