"""Const expression evaluation in dependency order with cycle detection.

Models HIR const nodes, function-hosted nested consts, and a
pending/evaluating/done state machine that evaluates dependencies before
dependents while caching done results and rejecting recursive cycles.
"""

node ConstExpr {
    has name: str = "";
    has base_cost: int = 1;
    has value: int = 0;
    has state: str = "pending";
    has eval_count: int = 0;
}

node FnSymbol {
    has name: str = "";
}

edge DependsOn { }

edge Invokes { }

edge NestedIn { }

walker ConstEvaluator {
    has eval_order: list[str] = [];
    has cycle_errors: list[str] = [];
    has charged_cost: int = 0;
    has accum: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can resolve_fn with FnSymbol entry {
        visit [->:NestedIn:->];
    }

    can tally_dep with ConstExpr exit {
        if here.state == "done" {
            new_accum = self.accum + here.value;
            self.accum = new_accum;
        }
    }

    can evaluate with ConstExpr entry {
        if here.state == "done" {
            visit [-->];
        } elif here.state == "evaluating" {
            self.cycle_errors.append(f"dependency cycle at '{here.name}'");
            disengage;
        } else {
            here.state = "evaluating";
            parent_accum = self.accum;
            self.accum = 0;
            visit [->:DependsOn:->];
            visit [->:Invokes:->];
            deps_total = self.accum;
            self.accum = parent_accum;
            new_value = here.base_cost + deps_total;
            here.value = new_value;
            here.state = "done";
            new_count = here.eval_count + 1;
            here.eval_count = new_count;
            self.eval_order.append(here.name);
            new_charged = self.charged_cost + here.base_cost;
            self.charged_cost = new_charged;
            visit [-->];
        }
    }
}

with entry {
    shared = ConstExpr(name="SHARED", base_cost=10);
    inner = ConstExpr(name="INNER", base_cost=7);
    helper = FnSymbol(name="helper_fn");
    helper +>:NestedIn:+> inner;

    mid = ConstExpr(name="MID", base_cost=3);
    top = ConstExpr(name="TOP", base_cost=2);
    mid +>:DependsOn:+> shared;
    mid +>:Invokes:+> helper;
    top +>:DependsOn:+> mid;

    user_a = ConstExpr(name="USER_A", base_cost=1);
    user_b = ConstExpr(name="USER_B", base_cost=1);
    user_a +>:DependsOn:+> shared;
    user_b +>:DependsOn:+> shared;

    root ++> top ++> user_a ++> user_b;

    main_pass = ConstEvaluator();
    root spawn main_pass;

    cyc_a = ConstExpr(name="CYC_A", base_cost=1);
    cyc_b = ConstExpr(name="CYC_B", base_cost=1);
    cyc_a +>:DependsOn:+> cyc_b;
    cyc_b +>:DependsOn:+> cyc_a;

    cycle_pass = ConstEvaluator();
    cyc_a spawn cycle_pass;
}

"""Decision Board: durable briefs, bounded Grill Room, readiness fog, and locked-revision compiler."""

node DecisionBrief {
    has project: str = "";
    has is_locked: bool = False;
}

node Decision {
    has title: str = "";
    has blocking: bool = True;
    has resolved: bool = False;
    has deferred: bool = False;
    has conflict: bool = False;
    has rationale: str = "";
}

node Assumption {
    has text: str = "";
    has invalidated: bool = False;
    has required: bool = True;
}

node Revision {
    has rev_num: int = 1;
    has promoted_thread: str = "";
}

node ImplTask {
    has name: str = "";
}

edge HasDecision { }
edge HasAssumption { }
edge LockedAs { }
edge Snapshots { }
edge CompilesTo { }
edge DependsOn { }

walker GrillMaster {
    has round: int = 1;
    has asked_this_round: int = 0;
    has max_rounds: int = 2;
    has max_per_round: int = 3;

    can grill with DecisionBrief entry {
        if here.is_locked {
            print(f"[Grill] {here.project} already locked — disengage");
            disengage;
        }
        print(f"[Grill] Enter Grill Room for {here.project} (Stop/Pause available)");
        self.round = 1;
        self.asked_this_round = 0;
        visit [->:HasDecision:->];
    }

    can question with Decision entry {
        if here.deferred or here.conflict {
            visit [-->] else { disengage; }
        } else {
            if here.blocking and here.resolved == False {
                if self.round > self.max_rounds {
                    print("[Grill] Round cap — Stop");
                    disengage;
                }
                if self.asked_this_round >= self.max_per_round {
                    self.round += 1;
                    self.asked_this_round = 0;
                    if self.round > self.max_rounds {
                        print("[Grill] Two rounds complete — Pause");
                        disengage;
                    }
                }
                print(f"[Grill R{self.round}] Consequential fork: {here.title}?");
                self.asked_this_round += 1;
            }
            visit [-->] else { disengage; }
        }
    }
}

walker ReadinessAuditor {
    has fog_score: int = 0;
    has can_lock: bool = True;

    can audit with DecisionBrief entry {
        self.fog_score = 0;
        self.can_lock = True;
        visit [->:HasDecision:->];
        visit [->:HasAssumption:->];
        label = "CLEAR" if self.can_lock else "FOGGY";
        print(f"[Readiness] {here.project}: {label} fog={self.fog_score} lockable={self.can_lock}");
    }

    can scan_decision with Decision entry {
        if here.blocking and here.resolved == False and here.deferred == False {
            self.fog_score += 1;
            self.can_lock = False;
            print(f"[Fog] blocking unresolved: {here.title}");
        }
        if here.conflict {
            self.fog_score += 1;
            self.can_lock = False;
            print(f"[Fog] conflict blocks lock: {here.title}");
        }
        visit [-->] else { disengage; }
    }

    can scan_assumption with Assumption entry {
        if here.required and here.invalidated {
            self.fog_score += 1;
            self.can_lock = False;
            print(f"[Fog] invalidated required assumption: {here.text}");
        }
        visit [-->] else { disengage; }
    }
}

walker BriefCompiler {
    can compile with Revision entry {
        print(f"[Compile] Preview for locked revision {here.rev_num}:");
        visit [->:Snapshots:->];
        visit [->:CompilesTo:->];
    }

    can show_decision with Decision entry {
        tag = "LOCKED" if here.resolved else "OPEN";
        print(f"  frozen decision [{tag}]: {here.title} — {here.rationale}");
        visit [-->] else { disengage; }
    }

    can show_task with ImplTask entry {
        print(f"  task target: {here.name}");
        visit [->:DependsOn:->];
        visit [-->] else { disengage; }
    }
}

walker TaskOrderer {
    has ordered: list[str] = [];
    has stack: list[str] = [];

    can begin with Revision entry {
        print("[Order] Dependency-safe schedule:");
        visit [->:CompilesTo:->];
    }

    can schedule with ImplTask entry {
        name = here.name;
        if name in self.ordered {
            visit [-->] else { disengage; }
        } else {
            if name in self.stack {
                print(f"[Cycle] dependency cycle at {name}");
                disengage;
            }
            self.stack.append(name);
            visit [->:DependsOn:->];
            self.stack.pop();
            self.ordered.append(name);
            print(f"[Order] {name}");
            visit [-->] else { disengage; }
        }
    }
}

walker PromotionSaga {
    can promote with Revision entry {
        if here.promoted_thread != "" {
            print(f"[Saga] idempotent skip — thread {here.promoted_thread} already exists");
