"""Flame graph: validate flat depth-first stack frames and build call-tree hierarchy."""

node Frame {
    has label: str = "";
    has level: int = 0;
    has value: float = 0.0;
    has self_val: float = 0.0;
    has color: str = "";
}

edge NextRow { }
edge StackChild { }

walker HierarchyBuilder {
    has parents: list = [];
    has diagnostics: list = [];
    has saw_first: bool = False;
    has prior_level: int = 0;

    can adapt with Frame entry {
        if not self.saw_first {
            if here.level != 0 {
                self.diagnostics.append("first row must start at level 0");
            }
            self.saw_first = True;
        } else {
            if here.level > self.prior_level + 1 {
                self.diagnostics.append(
                    f"depth jump at {here.label}: level {self.prior_level} -> {here.level}"
                );
            }
        }
        if here.self_val > here.value {
            self.diagnostics.append(
                f"self exceeds inclusive value at {here.label}"
            );
        }
        self.prior_level = here.level;

        while len(self.parents) > here.level {
            self.parents.pop();
        }
        if here.level > 0 and len(self.parents) >= here.level {
            parent = self.parents[here.level - 1];
            parent +>:StackChild:+> here;
        }
        self.parents.append(here);

        visit [->:NextRow:->] else {
            if self.diagnostics {
                print(f"[diagnostic] {len(self.diagnostics)} issue(s):");
                for msg in self.diagnostics {
                    print(f"  - {msg}");
                }
            } else {
                print("[ok] flat row contract validated");
            }
            disengage;
        };
    }
}

walker FlameRenderer {
    can render with Frame entry {
        pad = "";
        i = 0;
        while i < here.level {
            pad += "  ";
            i += 1;
        }
        color_hint = here.color if here.color else "auto";
        print(
            f"{pad}{here.label}  inclusive={here.value}  self={here.self_val}  color={color_hint}"
        );
        visit [->:StackChild:->];
    }
}

walker SpanAuditor {
    has sum_stack: list = [];
    has diagnostics: list = [];

    can start with Frame entry {
        self.sum_stack.append(0.0);
        visit [->:StackChild:->] else {
            children_sum = self.sum_stack.pop();
            if children_sum > here.value + 0.0001 {
                self.diagnostics.append(
                    f"child spans overflow {here.label}: {children_sum} > {here.value}"
                );
            }
            if self.diagnostics {
                for msg in self.diagnostics {
                    print(f"[span] {msg}");
                }
            } else {
                print("[ok] child spans fit within parents");
            }
            disengage;
        };
    }

    can descend with Frame entry {
        self.sum_stack.append(0.0);
        visit [->:StackChild:->];
    }

    can ascend with Frame exit {
        children_sum = self.sum_stack.pop();
        if children_sum > here.value + 0.0001 {
            self.diagnostics.append(
                f"child spans overflow {here.label}: {children_sum} > {here.value}"
            );
        }
        if len(self.sum_stack) > 0 {
            idx = len(self.sum_stack) - 1;
            self.sum_stack[idx] += here.value;
        }
    }
}

