"""Topological-order fold on a definition subgraph: critical-path max vs set-style node totals."""

node DefNode {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has def_name: str = "";
    has compute_time_s: float = 0.0;
    has has_compute_key: bool = True;
    has folded: float = 0.0;
    has is_target: bool = False;
}

edge DependsOn { }

walker TopologicalFolder {
    has default_val: float = 0.0;
    has use_max: bool = True;
    has seen: list[str] = [];
    has result: float = 0.0;

    can start with Root entry {
        visit [-->] else { disengage; };
    }

    can launch with DefNode entry {
        if here.is_target {
            if here.def_name in self.seen {
                disengage;
            }
            self.seen.append(here.def_name);
            visit [->:DependsOn:->] else { };
        } else {
            visit [-->] else { disengage; };
        }
    }

    can climb with DefNode entry {
        if here.def_name in self.seen {
            disengage;
        }
        self.seen.append(here.def_name);
        visit [->:DependsOn:->] else { };
    }

    can fold with DefNode exit {
        dep_part = self.default_val;
        for dep in here[->:DependsOn:->] {
            if self.use_max {
                pick = dep.folded if dep.folded > dep_part else dep_part;
                dep_part = pick;
            } else {
                dep_part = dep_part + dep.folded;
            }
        }
        own_val = here.compute_time_s if here.has_compute_key else self.default_val;
        here.folded = own_val + dep_part;
        if here.is_target {
            self.result = here.folded;
        }
    }
}

walker SetAggregator {
    has total: float = 0.0;

    can start with Root entry {
        visit [-->] else { disengage; };
    }

    can tally with DefNode entry {
        add_val = here.compute_time_s if here.has_compute_key else 0.0;
        self.total += add_val;
        visit [-->] else { disengage; };
    }
}

with entry {
    a = DefNode(def_name="A", title="load", compute_time_s=1.0);
    b = DefNode(def_name="B", title="branch_b", compute_time_s=2.0);
    c = DefNode(def_name="C", title="branch_c", compute_time_s=3.0);
    d = DefNode(
        def_name="D",
        title="merge",
        compute_time_s=4.0,
        is_target=True
    );
    gate = DefNode(
        def_name="G",
        title="unprofiled",
        has_compute_key=False,
        compute_time_s=99.0
    );

    d +>:DependsOn:+> b;
    d +>:DependsOn:+> c;
    b +>:DependsOn:+> a;
    b +>:DependsOn:+> gate;
    c +>:DependsOn:+> a;

    root ++> a ++> b ++> c ++> d ++> gate;

    print("diamond DAG: shared upstream A feeds merge target D");
    print("value(node) = own(node) + combine(value(dep) for deps); missing key -> default");

    max_fold = TopologicalFolder(default_val=0.0, use_max=True);
    root spawn max_fold;
    parallel_time = max_fold.result;
    print(f"subgraph.fold(combine=max, default=0.0) -> {parallel_time}s at target D");

    sum_fold = TopologicalFolder(default_val=0.0, use_max=False);
    root spawn sum_fold;
    path_sum = sum_fold.result;
    print(
        f"subgraph.fold(combine=sum, default=0.0) -> {path_sum}s "
        f"(shared deps counted per path; not a node-set total)"
    );

    agg = SetAggregator();
    root spawn agg;
    sequential_total = agg.total;
    print(f"set-aggregate over subgraph.nodes -> {sequential_total}s (each node once)");

    cmp_label = "<" if parallel_time < sequential_total else ">=";
    print(
        f"critical-path {parallel_time}s {cmp_label} sequential total "
        f"{sequential_total}s; fold(sum)={path_sum}s double-counts shared A"
    );
}

"""Horus default trigger scope: first-task trigger silently drops sibling-root tasks outside ancestor/descendant reach."""

node Task {
    has title: str = "";
    has year: int = 0;
    has task_id: str = "";
    has completed: bool = False;
    has available: bool = True;
}

edge DependsOn { }

walker ScopeResolver {
    has scope_ids: list[str] = [];
    has seen: list[str] = [];

    can start with Task entry {
        if self.record(here) {
            visit [->:DependsOn:->];
            visit [<--:DependsOn:--];
        }
    }

    can expand with Task entry {
        if self.record(here) {
            visit [->:DependsOn:->];
            visit [<--:DependsOn:--];
        }
    }

    def record(task: Task) -> bool {
        if task.task_id in self.seen {
            return False;
        }
        self.seen.append(task.task_id);
        self.scope_ids.append(task.task_id);
        return True;
    }
}

walker PrereqChecker {
    has satisfied: bool = True;

    can start with Task entry {
        visit [<--:DependsOn:--] else { disengage; };
    }

    can verify with Task entry {
        if not here.completed {
            self.satisfied = False;
            disengage;
        }
        visit [<--:DependsOn:--] else { disengage; };
    }
}

walker CycleProbe {
    has on_path: list[str] = [];
    has found: bool = False;

    can start with Task entry {
        if here.task_id in self.on_path {
            self.found = True;
            disengage;
        }
        self.on_path.append(here.task_id);
        visit [->:DependsOn:->] else { disengage; };
    }

    can walk with Task entry {
        if here.task_id in self.on_path {
            self.found = True;
            disengage;
        }
        self.on_path.append(here.task_id);
        visit [->:DependsOn:->] else { disengage; };
    }
}

walker StuckScanner {
    has scope_ids: list[str] = [];
    has stuck_tasks: list[Task] = [];

    can start with Root entry {
        visit [-->];
    }

    can collect with Task entry {
        if here.task_id in self.scope_ids and not here.completed {
            self.stuck_tasks.append(here);
        }
        visit [-->];
    }
}

walker OutOfScopeBlocker {
    has scope_ids: list[str] = [];
    has blocker_id: str = "";

    can start with Task entry {
        visit [<--:DependsOn:--] else { disengage; };
    }

    can inspect with Task entry {
        if not here.completed and here.task_id not in self.scope_ids {
            self.blocker_id = here.task_id;
            disengage;
        }
        visit [<--:DependsOn:--] else { disengage; };
    }
}

walker AllTaskScanner {
    has all_ids: list[str] = [];
    has skipped_ids: list[str] = [];
    has scope_ids: list[str] = [];

    can start with Root entry {
        visit [-->];
        for tid in self.all_ids {
            if tid not in self.scope_ids {
                self.skipped_ids.append(tid);
            }
        }
    }

    can gather with Task entry {
        self.all_ids.append(here.task_id);
        visit [-->];
    }
}

walker HorusRunner {
    has trigger_id: str = "";
    has scope_ids: list[str] = [];
    has executed: list[str] = [];
    has status: str = "RUNNING";
    has round: int = 0;
    has progressed: bool = True;

    can start with Root entry {
        print(f"horus run: default trigger={self.trigger_id} (no --trigger flag)");
        scope_label = ", ".join(self.scope_ids);
        print(f"scope = ancestors|descendants = {{{scope_label}}}");
        while self.progressed and self.round < 12 {
            self.progressed = False;
            self.round += 1;
            visit [-->];
        }
        self.finish();
    }

    can dispatch with Task entry {
        if here.task_id in self.scope_ids and not here.completed {
            gate = PrereqChecker();
            here spawn gate;
            if gate.satisfied {
                here.completed = True;
                self.executed.append(here.task_id);
                self.progressed = True;
                print(f"  EXEC {here.task_id}");
            }
        }
        visit [-->];
    }

    def finish() {
        scanner = StuckScanner(scope_ids=self.scope_ids);
        root spawn scanner;
        if len(scanner.stuck_tasks) > 0 {
            probe = CycleProbe();
            scanner.stuck_tasks[0] spawn probe;
            if not probe.found {
                print("stuck tasks remain but no cycle detected inside scope — exiting quietly");
                for stuck in scanner.stuck_tasks {
                    blocker = OutOfScopeBlocker(scope_ids=self.scope_ids);
                    stuck spawn blocker;
                    if blocker.blocker_id != "" {
                        print(
                            f"  task {stuck.task_id} blocked: depends on {blocker.blocker_id} "
                            f"(outside trigger scope)"
                        );
                    } else {
                        print(f"  task {stuck.task_id} blocked: unmet in-scope prerequisites");
                    }
                }
            }
        }
        catalog = AllTaskScanner(scope_ids=self.scope_ids);
        root spawn catalog;
        skip_label = ", ".join(catalog.skipped_ids);
        if skip_label != "" {
            print(f"never scheduled (out of scope): {skip_label}");
        }
        ran_label = ", ".join(self.executed);
        self.status = "COMPLETED";
        print(f"Workflow COMPLETED — executed: [{ran_label}]");
    }
}

with entry {
    ta = Task(task_id="a", title="download_checkpoint");
    tb = Task(task_id="b", title="fetch_source");
    tc = Task(task_id="c", title="generate");
    ta +>:DependsOn:+> tc;
    tb +>:DependsOn:+> tc;
    root ++> ta ++> tb ++> tc;

    trigger = ta;

    resolver = ScopeResolver();
    trigger spawn resolver;

    runner = HorusRunner(
        trigger_id=trigger.task_id,
        scope_ids=resolver.scope_ids
    );
    root spawn runner;
}

"""TCZ package dependency resolution: install ordering, reverse-dependency guards, cycle detection, and dry-run planning for virtos-update."""

node Package {
    has name: str = "";
    has installed: bool = False;
    has version: str = "1.0";
}

edge DependsOn { }

walker DepTreeWalker {
    has indent: int = 0;
    has path: list[str] = [];

    can show with Package entry {
        pad = "  " * self.indent;
        branch = "└─ " if self.indent > 0 else "";
        print(f"{pad}{branch}{here.name} ({here.version})");
        if here.name in self.path {
            print(f"{pad}  ** circular dependency at {here.name} **");
            disengage;
        }
        self.path.append(here.name);
        self.indent += 1;
        visit [->:DependsOn:->] else { disengage; }
        self.indent -= 1;
        self.path.pop();
    }
}

walker InstallPlanner {
    has dry_run: bool = True;
    has plan: list[str] = [];
    has stack: list[str] = [];
    has has_cycle: bool = False;

    can resolve with Package entry {
        if here.name in self.stack {
            chain = " -> ".join(self.stack) + f" -> {here.name}";
            print(f"CYCLE: {chain}");
            self.has_cycle = True;
            disengage;
        }
        if here.name in self.plan {
            disengage;
        }
        self.stack.append(here.name);
        visit [->:DependsOn:->];
        self.stack.pop();
        if not here.installed {
            self.plan.append(here.name);
            action = "WOULD INSTALL" if self.dry_run else "INSTALLED";
            print(f"{action}: {here.name}");
            if not self.dry_run {
                here.installed = True;
            }
        }
        disengage;
    }
}

walker RemoveGuard {
    has dependents: list[str] = [];
    has target_name: str = "";

    can audit with Package entry {
        if self.target_name == "" {
            self.target_name = here.name;
            print(f"Remove audit: {here.name}");
            visit [<--:DependsOn:--] else {
                print(f"  OK: no packages depend on {here.name}");
                disengage;
            }
            joined = ", ".join(self.dependents);
            print(f"  BLOCKED: {here.name} is required by {joined}");
            disengage;
        }
        self.dependents.append(here.name);
        print(f"  WARN: {here.name} depends on {self.target_name}");
        disengage;
    }
}

with entry {
    libcore = Package(name="libcore", version="2.4");
    tools = Package(name="tools", version="1.1");
    app = Package(name="app", version="3.0");
    bad_a = Package(name="bad-a", version="0.1");
    bad_b = Package(name="bad-b", version="0.2");

    root ++> libcore ++> tools ++> app;
    root ++> bad_a ++> bad_b;

    app +>:DependsOn:+> libcore;
    app +>:DependsOn:+> tools;
    tools +>:DependsOn:+> libcore;
    bad_a +>:DependsOn:+> bad_b;
    bad_b +>:DependsOn:+> bad_a;

    print("=== Dependency tree: app ===");
    app spawn DepTreeWalker();

    print("\n=== Dry-run install: app ===");
    app spawn InstallPlanner(dry_run=True);

    print("\n=== Remove check: libcore ===");
    libcore spawn RemoveGuard();

    print("\n=== Dry-run install: bad-a (cycle) ===");
    bad_a spawn InstallPlanner(dry_run=True);
}

"""Quake bot ambush: predict an item route, lurk silently, hold, then spring or abort."""

node Arena {
    has map_name: str = "";
}

node LurkSpot {
    has label: str = "";
    has off_sightline: bool = True;
    has clear_shot: bool = True;
    has has_escape: bool = True;
}

node KillZone {
    has entry_name: str = "";
    has eta_seconds: int = 0;
    has confidence: float = 0.0;
}

node Bot {
    has callsign: str = "";
    has silent_mode: bool = False;
    has holding: bool = False;
    has undetected: bool = True;
}

node Enemy {
    has handle: str = "";
    has spots_bot: bool = False;
    has in_zone: bool = False;
}

edge SilentPath {
    has noisy_hops: int = 0;
}

edge Overlooks {
    has firing_angle: int = 0;
}

edge PredictedRoute {
    has item_timer: int = 0;
}

walker AmbushOperator {
    has max_ticks: int = 8;
    has zone_name: str = "";
    has lurk_label: str = "";
    has outcome: str = "pending";
    has visited: list[str] = [];

    can start with Root entry {
        print("=== ambush: evaluate, lurk, hold, spring or abort ===");
        visit [-->];
    }

    can begin with Arena entry {
        print(f"--- arena {here.map_name} ---");
        visit [->:PredictedRoute:->];
    }

    can gate_opportunity with KillZone entry {
        if here.confidence < 0.7 or here.eta_seconds <= 0 {
            print(f"[SKIP] {here.entry_name}: insufficient opportunity");
            visit [-->] else { disengage; };
        } else {
            self.zone_name = here.entry_name;
            self.max_ticks = here.eta_seconds + 2;
            print(
                f"[OPP] enemy routing to {here.entry_name} in ~{here.eta_seconds}s "
                f"(confidence {here.confidence})"
            );
            visit [<--:Overlooks:--] else {
                print("[ABORT] no overlook positions on predicted path");
                self.outcome = "abort_no_spot";
                disengage;
            };
        }
    }

    can pick_spot with LurkSpot entry {
        if not (here.off_sightline and here.clear_shot) {
            print(f"[REJECT] '{here.label}' fails sightline or firing angle");
            visit [-->] else {
                print("[ABORT] no valid lurk position");
                self.outcome = "abort_no_spot";
                disengage;
            };
        } else {
            self.lurk_label = here.label;
            escape_note = "yes" if here.has_escape else "no";
            print(f"[LURK] selected '{here.label}' (escape={escape_note})");
            visit [<--:SilentPath:--] else { visit [-->]; };
        }
    }

    can crawl with SilentPath entry {
        key = f"silent:{here.noisy_hops}";
        if key in self.visited {
            print("[ABORT] cycle detected on silent path");
            self.outcome = "abort_cycle";
            disengage;
        }
        self.visited.append(key);
        if here.noisy_hops > 0 {
            print(f"[REJECT] silent route has {here.noisy_hops} noisy hops");
            visit [-->] else { disengage; };
        } else {
            print("  crawling silent: no jumps, speed under footstep threshold");
            visit [->:SilentPath:->] else { visit [-->]; };
        }
    }

    can arm with Bot entry {
        if not here.undetected {
            print(f"[ABORT] {here.callsign} already detected before hold");
            self.outcome = "abort_detected";
            disengage;
        }
        here.silent_mode = True;
        here.holding = True;
        print(
            f"[HOLD] {here.callsign} frozen at '{self.lurk_label}', "
            f"pre-aimed at {self.zone_name} (no fire, no jumps)"
        );
        visit [-->];
    }

    can spring_or_abort with Enemy entry {
        for tick in range(self.max_ticks + 1) {
            if here.spots_bot {
                print(f"[ABORT] spotted by {here.handle} at t={tick}");
                self.outcome = "abort_detected";
                disengage;
            }
            if here.in_zone and tick >= self.max_ticks - 1 {
                print(f"[SPRING] first shot on {here.handle} at {self.zone_name}");
                self.outcome = "sprung";
                disengage;
            }
            if tick >= self.max_ticks {
                print(f"[ABORT] timeout past ETA for {self.zone_name}");
                self.outcome = "abort_timeout";
                disengage;
            }
        }
        print(f"=== outcome: {self.outcome} ===");
    }
}

with entry {
    arena = Arena(map_name="q3dm6");
    mega = KillZone(entry_name="MegaHealth", eta_seconds=6, confidence=0.88);
    open_plat = LurkSpot(
        label="open plat",
        off_sightline=False,
        clear_shot=True,
        has_escape=False
    );
    nook = LurkSpot(
        label="pillar nook",
        off_sightline=True,
        clear_shot=True,
        has_escape=True
    );
    raiser = Bot(callsign="raiser", undetected=True);
    cyan = Enemy(handle="cyan", spots_bot=False, in_zone=True);

    root ++> arena;
    arena +>:PredictedRoute(item_timer=30):+> mega;
    open_plat +>:Overlooks(firing_angle=5):+> mega;
    nook +>:Overlooks(firing_angle=42):+> mega;
    open_plat ++> nook;
    arena +>:SilentPath(noisy_hops=3):+> open_plat;
    arena +>:SilentPath(noisy_hops=0):+> nook;
    nook ++> raiser ++> cyan;

    root spawn AmbushOperator();
}

