"""Topological-order fold on a definition subgraph: critical-path max vs set-style node totals."""

node DefNode {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has def_name: str = "";
    has compute_time_s: float = 0.0;
    has has_compute_key: bool = True;
    has folded: float = 0.0;
    has is_target: bool = False;
}

edge DependsOn { }

walker TopologicalFolder {
    has default_val: float = 0.0;
    has use_max: bool = True;
    has acc_stack: list[float] = [];
    has result: float = 0.0;

    can fold with DefNode entry {
        self.acc_stack.append(self.default_val);
        visit [->:DependsOn:->] else { };
        dep_part = self.default_val;
        if len(self.acc_stack) > 0 {
            dep_part = self.acc_stack[len(self.acc_stack) - 1];
            self.acc_stack.pop();
        }
        own_val = here.compute_time_s if here.has_compute_key else self.default_val;
        here.folded = own_val + dep_part;
        if here.is_target {
            self.result = here.folded;
        }
    }

    can gather_dep with DefNode exit {
        if len(self.acc_stack) == 0 {
            disengage;
        }
        idx = len(self.acc_stack) - 1;
        current = self.acc_stack[idx];
        if self.use_max {
            merged = here.folded if here.folded > current else current;
            self.acc_stack[idx] = merged;
        } else {
            self.acc_stack[idx] = current + here.folded;
        }
    }
}

walker SetAggregator {
    has total: float = 0.0;
    has default_val: float = 0.0;

    can start with Root entry {
        visit [-->] else { disengage; };
    }

    can tally with DefNode entry {
        add_val = here.compute_time_s if here.has_compute_key else self.default_val;
        self.total = self.total + add_val;
        visit [-->] else { disengage; };
    }
}

with entry {
    a = DefNode(def_name="A", title="load", compute_time_s=1.0);
    b = DefNode(def_name="B", title="branch_b", compute_time_s=2.0);
    c = DefNode(def_name="C", title="branch_c", compute_time_s=3.0);
    d = DefNode(
        def_name="D",
        title="merge",
        compute_time_s=4.0,
        is_target=True
    );
    gate = DefNode(
        def_name="G",
        title="unprofiled",
        has_compute_key=False,
        compute_time_s=99.0
    );

    d +>:DependsOn:+> b;
    d +>:DependsOn:+> c;
    b +>:DependsOn:+> a;
    b +>:DependsOn:+> gate;
    c +>:DependsOn:+> a;

    root ++> a ++> b ++> c ++> d ++> gate;

    print("diamond DAG: shared upstream A feeds merge target D");
    print("value(node) = own(node) + combine(value(dep) for deps); missing key -> default");

    max_fold = TopologicalFolder(default_val=0.0, use_max=True);
    d spawn max_fold;
    parallel_time = max_fold.result;
    print(f"subgraph.fold(combine=max, default=0.0) -> {parallel_time}s at target D");

    sum_fold = TopologicalFolder(default_val=0.0, use_max=False);
    d spawn sum_fold;
    path_sum = sum_fold.result;
    print(
        f"subgraph.fold(combine=sum, default=0.0) -> {path_sum}s "
        f"(shared deps counted per path; not a node-set total)"
    );

    agg = SetAggregator(default_val=0.0);
    root spawn agg;
    sequential_total = agg.total;
    print(f"set-aggregate over subgraph.nodes -> {sequential_total}s (each node once)");

    cmp_label = "<" if parallel_time < sequential_total else ">=";
    print(
        f"critical-path {parallel_time}s {cmp_label} sequential total "
        f"{sequential_total}s; fold(sum)={path_sum}s double-counts shared A"
    );
}

"""Nested request groups: sidebar directory listing, breadcrumbs, and cycle detection."""

node Group {
    has name: str = "";
    has gid: int = 0;
}

node Request {
    has title: str = "";
    has method: str = "GET";
    has active: bool = True;
}

edge SubGroup { }
edge Holds { }

walker CycleGuard {
    has stack: list[int] = [];
    has ok: bool = True;

    can start with Root entry {
        visit [-->] else { disengage; }
    }

    can scan with Group entry {
        if here.gid in self.stack {
            print(f"ERROR: circular group dependency at '{here.name}' (id={here.gid})");
            self.ok = False;
            disengage;
        }
        self.stack.append(here.gid);
        visit [->:SubGroup:->] else { disengage; }
    }

    can unwind with Group exit {
        if self.stack {
            last = self.stack[-1];
            if last == here.gid {
                trimmed: list[int] = [];
                for (i, g) in enumerate(self.stack) {
                    if i < len(self.stack) - 1 {
                        trimmed.append(g);
                    }
                }
                self.stack = trimmed;
            }
        }
    }
}

walker BreadcrumbWalker {
    has parts: list[str] = [];

    def crumbs_line() -> str {
        line = "";
        for (i, p) in enumerate(self.parts) {
            sep = " > " if i > 0 else "";
            line = f"{line}{sep}{p}";
        }
        return line;
    }

    can start with Group entry {
        self.parts = [here.name];
        visit [<--:SubGroup:--] else {
            print(f"Breadcrumbs: {self.crumbs_line()}");
            disengage;
        }
    }

    can ascend with Group entry {
        merged: list[str] = [here.name];
        for p in self.parts {
            merged.append(p);
        }
        self.parts = merged;
        visit [<--:SubGroup:--] else {
            print(f"Breadcrumbs: {self.crumbs_line()}");
            disengage;
        }
    }
}

walker DirectoryLister {
    has at_root: bool = False;

    can start with Group entry {
        self.at_root = here.gid == 0;
        here spawn BreadcrumbWalker();
        print(f"--- Listing: {here.name} ---");
        if not self.at_root {
            print("  ..");
        }
        visit [->:SubGroup:->] else { }
        visit [->:Holds:->] else { disengage; }
    }

