    has year: int = 0;
    has available: bool = True;
}

node ResultCache {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

edge Contains { }
edge Requests { }
edge CachedAt { has ttl_sec: int = 300; }

walker ColdAnalyzer {
    has files_scanned: int = 0;
    has scan_cost_ms: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can analyze with ApiEndpoint entry {
        cache_label = "result-cache" if here.available else "no result-cache";
        print(f"[COLD] GET {here.title} ({cache_label}) — full analyze_directory()");
        visit [->:Requests:->];
    }

    can scan_tree with CodeSource entry {
        print(f"  rglob *.py under {here.title} ({here.year} files in tree)");
        visit [->:Contains:->];
    }

    can scan_file with PythonFile entry {
        if here.available {
            self.files_scanned += 1;
            self.scan_cost_ms += here.year;
            print(f"    analyze_file({here.title}) +{here.year}ms");
        }
        visit [->:Contains:->] else { disengage; };
    }
}

walker CacheResponder {
    has files_scanned: int = 0;
    has cache_hit: bool = False;

    can start with Root entry {
        visit [-->];
    }

    can analyze with ApiEndpoint entry {
        if here.available {
            visit [->:CachedAt:->] else {
                print(f"[MISS] GET {here.title} — no Redis entry, scanning tree");
                visit [->:Requests:->];
            };
        } else {
            print(f"[NO-CACHE] GET {here.title} — endpoint has no result cache");
            visit [->:Requests:->];
        }
    }

    can serve_cache with ResultCache entry {
        self.cache_hit = True;
        print(f"[HIT] {here.title} ttl={here.year}s — skipped {here.year}ms cold scan");
        disengage;
    }

    can scan_tree with CodeSource entry {
        visit [->:Contains:->];
    }

    can scan_file with PythonFile entry {
        if here.available {
            self.files_scanned += 1;
            print(f"    scan {here.title}");
        }
        visit [->:Contains:->] else { disengage; };
    }
}

