"""Nested request groups: sidebar directory listing, breadcrumbs, and cycle detection."""

node Group {
    has name: str = "";
    has gid: int = 0;
}

node Request {
    has title: str = "";
    has method: str = "GET";
    has active: bool = True;
}

edge SubGroup { }
edge Holds { }

walker CycleGuard {
    has stack: list[int] = [];
    has ok: bool = True;

    can start with Root entry {
        visit [-->] else { disengage; }
    }

    can scan with Group entry {
        if here.gid in self.stack {
            print(f"ERROR: circular group dependency at '{here.name}' (id={here.gid})");
            self.ok = False;
            disengage;
        }
        self.stack.append(here.gid);
        visit [->:SubGroup:->] else { disengage; }
    }

    can unwind with Group exit {
        if self.stack {
            last = self.stack[-1];
            if last == here.gid {
                trimmed: list[int] = [];
                for (i, g) in enumerate(self.stack) {
                    if i < len(self.stack) - 1 {
                        trimmed.append(g);
                    }
                }
                self.stack = trimmed;
            }
        }
    }
}

walker BreadcrumbWalker {
    has parts: list[str] = [];

    def crumbs_line() -> str {
        line = "";
        for (i, p) in enumerate(self.parts) {
            sep = " > " if i > 0 else "";
            line = f"{line}{sep}{p}";
        }
        return line;
    }

    can climb with Group entry {
        merged: list[str] = [here.name];
        for p in self.parts {
            merged.append(p);
        }
        self.parts = merged;
        visit [<--:SubGroup:--] else {
            print(f"Breadcrumbs: {self.crumbs_line()}");
            disengage;
        }
    }
}

walker DirectoryLister {
    has at_root: bool = False;

    can start with Group entry {
        self.at_root = here.gid == 0;
        here spawn BreadcrumbWalker();
        print(f"--- Listing: {here.name} ---");
        if not self.at_root {
            print("  ..");
        }
        visit [->:SubGroup:->];
        visit [->:Holds:->] else { disengage; }
    }

    can show_dir with Group entry {
        print(f"  [DIR]  {here.name}/");
        disengage;
    }

    can show_req with Request entry {
        status = "ON" if here.active else "OFF";
        print(f"  [REQ]  {here.method} {here.title} ({status})");
        disengage;
    }
}

walker GoUp {
    can start with Group entry {
        visit [<--:SubGroup:--] else {
            print("(already at root)");
            disengage;
        }
    }

    can land with Group entry {
        print(f"\n<< Backspace: returned to '{here.name}'");
        here spawn DirectoryLister();
        disengage;
    }
}

with entry {
    root_grp = Group(name="Root", gid=0);
    api = Group(name="API", gid=1);
    auth = Group(name="Auth", gid=2);
    users = Group(name="Users", gid=3);

    root ++> root_grp;
    root_grp +>:SubGroup:+> api;
    root_grp +>:SubGroup:+> users;
    api +>:SubGroup:+> auth;

    users +>:Holds:+> Request(title="List Users", method="GET");
    users +>:Holds:+> Request(title="Create User", method="POST", active=False);
    auth +>:Holds:+> Request(title="Login", method="POST");
    auth +>:Holds:+> Request(title="Refresh Token", method="POST");

    print("=== Startup: cycle check ===");
    guard = CycleGuard();
    root spawn guard;
    if guard.ok {
        print("Hierarchy OK: no circular dependencies.\n");
    } else {
        print("Startup aborted: fix group hierarchy.\n");
    }

    print("=== Browse Root (sidebar root listing) ===");
    root_grp spawn DirectoryLister();

    print("\n=== Navigate into API (like selecting a folder) ===");
    api spawn DirectoryLister();

    print("\n=== Navigate into Auth (deeper path) ===");
    auth spawn DirectoryLister();

    print("\n=== Backspace from Auth -> API ===");
    auth spawn GoUp();

    print("\n=== Browse Users branch ===");
    users spawn DirectoryLister();
}

