"""Unattended workflow promotion: dependency cycles, readiness gates, and pool starvation.

Models harness #1885 — circular upstream dependency deadlock, human-readiness
gates in unattended runtime, LocalReview downgrades, and dispatchable-pool
starvation with explicit cycle detection (fail-closed, no silent auto-advance).
"""

edge DependsOn { }
edge GatedBy { }
edge InPool { }

node WorkflowIssue {
    has issue_id: int = 0;
    has title: str = "";
    has status: str = "blocked";
    has blocker: str = "";
}

node ReadinessGate {
    has gate_name: str = "";
    has requires_human: bool = True;
    has disposition: str = "block";
    has evidence: str = "";
}

node RuntimePool {
    has pool_name: str = "";
    has starved: bool = False;
}

walker DependencyCycleDetector {
    has path: list[int] = [];
    has found: bool = False;
    has cycle_evidence: list[int] = [];

    can detect with WorkflowIssue entry {
        if self.found {
            disengage;
        }
        for pid in self.path {
            if pid == here.issue_id {
                self.found = True;
                self.cycle_evidence = self.path + [here.issue_id];
                print(
                    f"IssueDependencyCycleDetected: {self.cycle_evidence}"
                );
                disengage;
            }
        }
        self.path.append(here.issue_id);
        visit [here->:DependsOn:->] else { disengage; };
        if len(self.path) > 0 {
            _ = self.path.pop();
        }
    }
}

walker RuntimePoolAuditor {
    has unattended_mode: bool = True;
    has mode: str = "pool";
    has dispatchable_count: int = 0;
    has gated_count: int = 0;
    has dep_blocked: bool = False;
    has gate_blocked: bool = False;
    has blocker_msg: str = "";
    has upstream_seen: list[int] = [];

    can start with Root entry {
        visit [-->];
    }

    can enter_pool with RuntimePool entry {
        self.dispatchable_count = 0;
        self.gated_count = 0;
        visit [->:InPool:->] else { disengage; };
        if self.dispatchable_count == 0 {
            pool_kind = "gated-work" if self.gated_count > 0 else "no-work";
            here.starved = True;
            print(
                f"runtime_pool_starved ({pool_kind}): "
                f"0 dispatchable commands in {here.pool_name}"
            );
        } else {
            print(
                f"{here.pool_name}: {self.dispatchable_count} dispatchable"
            );
        }
    }

    can evaluate with WorkflowIssue entry {
        if self.mode != "pool" {
            disengage;
        }
        self.dep_blocked = False;
        self.gate_blocked = False;
        self.blocker_msg = "";
        self.upstream_seen = [here.issue_id];
        self.mode = "upstream";
        visit [here->:DependsOn:->] else { disengage; };
        self.mode = "gate";
        visit [here->:GatedBy:->] else { disengage; };
        self.mode = "pool";
        still_blocked = self.dep_blocked or self.gate_blocked;
        if still_blocked {
            here.status = "blocked";
            here.blocker = self.blocker_msg;
            self.gated_count += 1;
            print(
                f"[BLOCKED] #{here.issue_id} {here.title}: {here.blocker}"
            );
        } else {
            next_status = (
                "dispatchable" if here.status != "failed" else "failed"
            );
            here.status = next_status;
            if here.status == "dispatchable" {
                self.dispatchable_count += 1;
                print(f"[READY] #{here.issue_id} {here.title}");
            }
        }
    }

    can check_upstream with WorkflowIssue entry {
        if self.mode != "upstream" {
            disengage;
        }
        for seen_id in self.upstream_seen {
            if seen_id == here.issue_id {
                self.dep_blocked = True;
                self.blocker_msg = (
                    "IssueDependencyCycleDetected: mutual upstream wait"
                );
                disengage;
            }
        }
        self.upstream_seen.append(here.issue_id);
        upstream_ready = (
            here.status == "dispatchable"
            or here.status == "scheduled"
        );
        if not upstream_ready {
            self.dep_blocked = True;
            self.blocker_msg = "upstream dependencies are not ready";
        }
    }

    can check_gate with ReadinessGate entry {
        if self.mode != "gate" {
            disengage;
        }
        if self.unattended_mode and here.requires_human {
            if here.disposition == "block" {
                self.gate_blocked = True;
                gate_msg = f"Human readiness gate missing: {here.gate_name}";
                self.blocker_msg = gate_msg;
                print(gate_msg);
            } else {
                print(
                    f"readiness_gate unattended skip_with_evidence: "
                    f"{here.evidence}"
                );
            }
        }
    }
}

