"""Multi-hop document link lineage: bidirectional supersession chains with cycle detection, depth caps, and stop-at-inaccessible policy."""

node Document {
    has title: str = "";
    has year: int = 0;
    has accessible: bool = True;
}

edge DocumentLink {
    has relation: str = "supersedes";
}

walker ForwardLineage {
    has max_depth: int = 5;
    has depth: int = 0;
    has seen: list[str] = [];
    has origin_title: str = "";
    has begun: bool = False;

    can start with Root entry {
        visit [-->];
    }

    can traverse with Document entry {
        if self.origin_title != "" and here.title != self.origin_title and not self.begun {
            visit [-->];
        } else if not self.begun {
            self.begun = True;
            print(f"Supersedes chain from {here.title} (older direction):");
            self.seen.append(here.title);
            visit [->:DocumentLink:->] else {
                print("  (no older documents)");
                disengage;
            };
        } else {
            if not here.accessible {
                print(f"  [stop] inaccessible intermediate: {here.title}");
                disengage;
            }
            if here.title in self.seen {
                print(f"  [cycle] detected at {here.title}");
                disengage;
            }
            if self.depth >= self.max_depth {
                print(f"  [depth cap] reached at depth {self.depth}");
                disengage;
            }
            self.seen.append(here.title);
            print(f"  -> {here.title}");
            self.depth += 1;
            visit [->:DocumentLink:->] else {
                disengage;
            };
        }
    }
}

walker BackwardLineage {
    has max_depth: int = 5;
    has depth: int = 0;
    has seen: list[str] = [];
    has origin_title: str = "";
    has begun: bool = False;

    can start with Root entry {
        visit [-->];
    }

    can traverse with Document entry {
        if self.origin_title != "" and here.title != self.origin_title and not self.begun {
            visit [-->];
        } else if not self.begun {
            self.begun = True;
            print(f"Superseded-by chain from {here.title} (newer direction):");
            self.seen.append(here.title);
            visit [<-:DocumentLink:<-] else {
                print("  (no newer documents)");
                disengage;
            };
        } else {
            if not here.accessible {
                print(f"  [stop] inaccessible intermediate: {here.title}");
                disengage;
            }
            if here.title in self.seen {
                print(f"  [cycle] detected at {here.title}");
                disengage;
            }
            if self.depth >= self.max_depth {
                print(f"  [depth cap] reached at depth {self.depth}");
                disengage;
            }
            self.seen.append(here.title);
            print(f"  <- {here.title}");
            self.depth += 1;
            visit [<-:DocumentLink:<-] else {
                disengage;
            };
        }
    }
}

