"""Wiki TrustGraph: provenance-aware graph retrieval from validated wiki pages."""

node WikiPage {
    has title: str = "";
    has route: str = "";
    has validation_score: float = 1.0;
}

node Claim {
    has text: str = "";
    has confidence: float = 1.0;
    has is_stale: bool = False;
    has claim_id: str = "";
}

edge ExtractedFrom {
    has git_commit: str = "";
    has extracted_at: str = "";
}

edge Supports {
    has weight: float = 1.0;
}

walker ProvenanceTracer {
    has citations: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can trace_claim with Claim entry {
        band = "HIGH" if here.confidence >= 0.75 else "LOW";
        print(f"[{band}] {here.text}");
        visit [->:ExtractedFrom:->] else { disengage; };
    }

    can cite_source with WikiPage entry {
        cite = f"  └─ source: {here.title} <{here.route}> "
               f"(validation={here.validation_score})";
        self.citations.append(cite);
        print(cite);
        disengage;
    }
}

walker TrustRepairAuditor {
    has min_confidence: float = 0.75;
    has repair_queue: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can audit with Claim entry {
        needs_repair = here.is_stale or here.confidence < self.min_confidence;
        if needs_repair {
            reason = "stale" if here.is_stale else "low-confidence";
            item = f"REPAIR ({reason}): {here.claim_id} — {here.text}";
            self.repair_queue.append(item);
            print(item);
        }
        visit [-->];
    }
}

walker NeighborhoodRetriever {
    has max_depth: int = 3;
    has depth: int = 0;
    has visited: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can expand with Claim entry {
        if here.claim_id in self.visited {
            print(f"  [cycle guard] skipping {here.claim_id}");
            disengage;
        }
        if self.depth > self.max_depth {
            disengage;
        }
        self.visited.append(here.claim_id);
        trust_label = "trusted" if here.confidence >= 0.75 else "low-trust";
        print(f"  [d={self.depth}] {here.claim_id}: {here.text} ({trust_label})");
        self.depth += 1;
        visit [->:Supports:->] else { disengage; };
    }
}

