walker BindingDeriver {
    has current_field: str = "";
    has current_value: str = "";
    has pending_type: str = "";
    has evidence_hits: int = 0;
    has matched_referent: str = "";
    has derived_total: int = 0;
    has suppressed_total: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can on_provider with Provider entry {
        if not here.derive_enabled {
            disengage;
        }
        visit [->:OwnsType:->];
    }

    can on_pack_type with ResourceType entry {
        if self.current_value == "" {
            visit [->:DeclaresField:->] else { disengage; };
        } else {
            self.pending_type = here.type_name;
            visit [->:Stocks:->] else { disengage; };
        }
    }

    can on_inventory with InventoryItem entry {
        if here.item_id == self.current_value {
            self.evidence_hits += 1;
            self.matched_referent = self.pending_type;
        }
        visit [-->] else { disengage; };
    }

    can derive with SchemaField entry {
        self.current_field = here.field_name;
        self.current_value = here.literal_value;
        self.evidence_hits = 0;
        self.matched_referent = "";

        if here.suppressed {
            print(f"SUPPRESSED {here.field_name} (pack false)");
            self.suppressed_total += 1;
        } elif here.pinned_referent != "" {
            pin_key = here.pinned_key;
            if pin_key == "" {
                pin_key = "name";
            }
            print(
                f"PINNED {here.field_name} -> "
                f"{here.pinned_referent}.{pin_key}"
            );
        } elif not here.field_name.endswith("_id") {
            print(
                f"LITERAL {here.field_name}={here.literal_value} "
                f"(not id-shaped)"
            );
        } else {
            visit [->:CandidateFor:->] else {
                print(
                    f"LITERAL {here.field_name} "
                    f"(no referent type match)"
                );
            };
            if self.evidence_hits == 1 {
                print(
                    f"DERIVED {self.current_field} -> "
                    f"{self.matched_referent} "
                    f"(inventory confirmed)"
                );
                self.derived_total += 1;
            } elif self.evidence_hits == 0 {
                print(
                    f"LITERAL {here.field_name}={here.literal_value} "
                    f"(id_absent)"
                );
            } else {
                print(
                    f"LITERAL {here.field_name} "
                    f"(ambiguous: {self.evidence_hits} inventories)"
                );
            }
        }

        self.current_value = "";
        visit [-->] else { disengage; };
    }
}

walker CycleAuditor {
    has stack: list[object] = [];
    has fatal: bool = False;

    can start with Root entry {
        visit [-->];
    }

    can walk with StateResource entry {
        for seen in self.stack {
            if seen is here {
                print(f"CYCLE FATAL: dependency loop at {here.title}");
                self.fatal = True;
                disengage;
            }
        }
        self.stack.append(here);
        visit [->:StateDep:->] else { disengage; };
    }

    can unwind with StateResource exit {
        if len(self.stack) > 0 {
            self.stack.pop();
        }
    }
}

