"""Discover project sheets by walking child-sheet hierarchy with cycle guards and orphan union."""

node Entity {
    has ref_name: str = "";
    has loaded: bool = False;
}

node Sheet(Entity) {
    has rel_path: str = "";
    has listed_in_project: bool = False;
}

node Project {
    has name: str = "";
}

edge ProjectRoot { }

edge ProjectListing { }

edge ChildSheet {
    has bare_ref: str = "";
}

node RefRegistry {
    has keys: list[str] = [];
    has owners: list[str] = [];

    def claim(bare_ref: str, parent_ref: str) -> bool {
        for (i, key) in enumerate(self.keys) {
            if key == bare_ref {
                if self.owners[i] != parent_ref {
                    print(
                        f"[COLLISION] '{bare_ref}' kept by "
                        f"{self.owners[i]}, ignored {parent_ref}"
                    );
                    return False;
                }
                return True;
            }
        }
        self.keys.append(bare_ref);
        self.owners.append(parent_ref);
        return True;
    }
}

walker SheetDiscoverer {
    has visiting: list[str] = [];
    has discovered: list[str] = [];
    has cycles_blocked: int = 0;
    has sweep_orphans: bool = False;

    can start with Root entry {
        visit [-->[?:Project]] else { disengage; };
    }

    can on_project with Project entry {
        if self.sweep_orphans {
            visit [->:ProjectListing:->] else { disengage; };
        } else {
            visit [->:ProjectRoot:->] else { disengage; };
        }
    }

    can walk with Sheet entry {
        if self.sweep_orphans {
            if here.listed_in_project and here.ref_name not in self.discovered {
                self.discovered.append(here.ref_name);
                here.loaded = True;
                print(
                    f"[LOAD] {here.ref_name} (orphan from .snxprj) "
                    f"at {here.rel_path}"
                );
            }
            disengage;
        }
        if here.ref_name in self.visiting {
            print(f"[CYCLE] blocked re-entry to {here.ref_name}");
            self.cycles_blocked += 1;
            disengage;
        }
        self.visiting.append(here.ref_name);
        if here.ref_name not in self.discovered {
            self.discovered.append(here.ref_name);
            here.loaded = True;
            load_src = "listed+walked" if here.listed_in_project else "hierarchy-only";
            print(f"[LOAD] {here.ref_name} via {load_src} at {here.rel_path}");
        }
        visit [->:ChildSheet:->] else { disengage; };
    }

    can unwind with Sheet exit {
        if len(self.visiting) > 0 and self.visiting[-1] == here.ref_name {
            self.visiting.pop();
        }
    }
}

