    root ++> pickaxe ++> stick ++> plank ++> iron;
    root ++> sticks_from_planks ++> pickaxe_core;

    root spawn CraftPlanner(goal_item="pickaxe", goal_count=1);

    echo = Item(name="echo_shard", on_hand=0);
