    echo +>:Needs(qty=1):+> mirror;
    mirror +>:Makes(qty=1):+> echo;
    echo +>:Needs(qty=1):+> ghost;
    ghost +>:Makes(qty=1):+> echo;
    root ++> echo ++> mirror ++> ghost;

    root spawn CycleProbe();
}

