    print("--- hierarchy discovery from root (child absent from .snxprj) ---");
    root spawn SheetDiscoverer();

    print("--- orphan sweep (.snxprj listing union) ---");
    proj spawn SheetDiscoverer(sweep_orphans=True);
}

