"""Deterministic multi-step magic crafting: recursive recipe planning with stock, bounds, and cycle detection."""

node Item {
    has name: str = "";
    has on_hand: int = 0;
}

node Recipe {
    has recipe_id: str = "";
    has batch_out: int = 1;
}

edge Needs {
    has qty: int = 1;
}

edge Makes {
    has qty: int = 1;
}

walker CraftPlanner {
    has goal_item: str = "";
    has goal_count: int = 1;
    has max_depth: int = 10;
    has depth: int = 0;
    has open_recipes: list[str] = [];
    has plan: list[str] = [];
    has ok: bool = True;
    has fail_reason: str = "";
    has purse: dict[str, int] = {};
    has pending_name: str = "";
    has pending_qty: int = 0;
    has resolving: bool = False;
    has ingredient_pass: bool = False;
    has batch_count: int = 1;

    def purse_of(name: str) -> int {
        if name in self.purse {
            return self.purse[name];
        }
        return 0;
    }

    def purse_seed(item: Item) -> None {
        if item.name not in self.purse {
            self.purse[item.name] = item.on_hand;
        }
    }

    def purse_take(name: str, amount: int) -> None {
        cur = self.purse_of(name);
        self.purse[name] = cur - amount;
    }

    def purse_give(name: str, amount: int) -> None {
        cur = self.purse_of(name);
        self.purse[name] = cur + amount;
    }

    def fail(msg: str) -> None {
        self.ok = False;
        self.fail_reason = msg;
    }

    def batches_needed(want: int, per_batch: int) -> int {
        if per_batch < 1 {
            return want;
        }
        extra = 0 if (want % per_batch) == 0 else 1;
        return (want // per_batch) + extra;
    }

    can start with Root entry {
        print(f"== Atomic plan: {self.goal_count}x {self.goal_item} ==");
        self.pending_name = self.goal_item;
        self.pending_qty = self.goal_count;
        self.resolving = True;
        visit [-->[?:Item]] else { disengage; };
        if self.ok {
            print("-- planned steps --");
            for (i, line) in enumerate(self.plan) {
                print(f"  {i + 1}. {line}");
            }
            print("-- virtual purse after simulation --");
            for (name, left) in self.purse.items() {
                print(f"  {name}: {left}");
            }
            print("commit: single net transaction (no partial state)");
        } else {
            print(f"abort: {self.fail_reason}");
        }
    }

    can handle with Item entry {
        if not self.ok {
            disengage;
        }
        self.purse_seed(here);
        if self.ingredient_pass {
            need = edge.qty * self.batch_count;
            if need < 1 {
                need = 1;
            }
            self.pending_name = here.name;
            self.pending_qty = need;
            self.resolving = True;
            visit [-->[?:Item]] else { disengage; };
            disengage;
        }
        if self.resolving && here.name == self.pending_name {
            self.resolving = False;
            have = self.purse_of(here.name);
            if have >= self.pending_qty {
                self.purse_take(here.name, self.pending_qty);
                self.plan += [f"reserve {self.pending_qty}x {here.name} from stock"];
                disengage;
            }
            partial = have if have > 0 else 0;
            if partial > 0 {
                self.purse_take(here.name, partial);
                self.plan += [f"reserve {partial}x {here.name} from partial stock"];
            }
            short = self.pending_qty - partial;
            if short <= 0 {
                disengage;
            }
            self.pending_qty = short;
            self.pending_name = here.name;
            visit [<--:Makes:--] else {
                self.fail(f"no recipe produces {here.name}");
                disengage;
            };
            disengage;
        }
        visit [-->];
    }

    can expand with Recipe entry {
        if not self.ok {
            disengage;
        }
        if self.depth >= self.max_depth {
            self.fail("planning depth bound exceeded");
            disengage;
        }
        if here.recipe_id in self.open_recipes {
            self.fail(f"recipe cycle at {here.recipe_id}");
            disengage;
        }
        self.open_recipes += [here.recipe_id];
        self.depth += 1;
        batches = self.batches_needed(self.pending_qty, here.batch_out);
        self.batch_count = batches;
        total_out = batches * here.batch_out;
        self.plan += [f"craft {batches}x via {here.recipe_id} (-> {total_out}x {self.pending_name})"];
        self.purse_give(self.pending_name, total_out);
        self.purse_take(self.pending_name, self.pending_qty);
        self.ingredient_pass = True;
        visit [->:Needs:->] else {
            self.fail(f"recipe {here.recipe_id} has no inputs");
            disengage;
        };
        self.ingredient_pass = False;
        self.depth -= 1;
        n = len(self.open_recipes);
        if n > 0 {
            self.open_recipes = self.open_recipes[0:n - 1];
        }
        disengage;
    }
}

walker CycleProbe {
    has seen: list[str] = [];
    has hit_cycle: bool = False;

    can start with Root entry {
        visit [-->];
        if self.hit_cycle {
            print("cycle probe: FAIL (loop detected)");
        } else {
            print("cycle probe: OK");
        }
    }

    can check with Recipe entry {
        if here.recipe_id in self.seen {
            self.hit_cycle = True;
            disengage;
        }
        self.seen += [here.recipe_id];
        visit [->:Needs:->] else { disengage; };
    }

    can bridge with Item entry {
        visit [<--:Makes:--] else { disengage; };
    }
}

