child Skills while proactive model routing stays blocked."""

node Skill {
    has name: str = "";
    has allow_user: bool = True;
    has allow_proactive: bool = False;
    has allow_delegated: bool = True;
}

node LaunchPad {
    has label: str = "";
    has mode: str = "user";
}

edge DelegatesTo { }

walker InvocationGate {
    has mode: str = "user";
    has authorized: list[str] = [];
    has blocked: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can bootstrap with LaunchPad entry {
        self.mode = here.mode;
        print(f"=== {here.label} ===");
        visit [-->] else { disengage; };
    }

    can authorize with Skill entry {
        permit = False;
        if self.mode == "user" and here.allow_user {
            permit = True;
        }
        if self.mode == "proactive" and here.allow_proactive {
            permit = True;
        }
        if self.mode == "delegated" and here.allow_delegated {
            permit = True;
        }
        if permit {
            print(f"  [{self.mode}] {here.name}: authorized");
            self.authorized += [here.name];
            saved_mode = self.mode;
            self.mode = "delegated";
            visit [->:DelegatesTo:->] else { disengage; };
            self.mode = saved_mode;
            disengage;
        } else {
            print(f"  [{self.mode}] {here.name}: blocked");
            self.blocked += [here.name];
            disengage;
        }
    }
}

with entry {
    feedback = Skill(
        name="request-critical-feedback",
        allow_user=True,
        allow_proactive=False,
        allow_delegated=True,
    );
    create_issue = Skill(
        name="create-new-issue",
        allow_user=True,
        allow_proactive=True,
        allow_delegated=True,
    );
    resolve_issue = Skill(
        name="resolve-issue",
        allow_user=True,
        allow_proactive=True,
        allow_delegated=True,
    );
    create_issue +>:DelegatesTo:+> feedback;
    resolve_issue +>:DelegatesTo:+> feedback;

    direct = LaunchPad(
        label="user -> request-critical-feedback",
        mode="user",
    );
    via_create = LaunchPad(
        label="user -> create-new-issue -> child",
        mode="user",
    );
    via_resolve = LaunchPad(
        label="user -> resolve-issue -> child",
        mode="user",
    );
    proactive = LaunchPad(
