        mode="proactive",
    );

    direct ++> feedback;
    via_create ++> create_issue;
    via_resolve ++> resolve_issue;
    proactive ++> feedback;

    root ++> direct;
    root ++> via_create;
    root ++> via_resolve;
    root ++> proactive;

    direct spawn InvocationGate();
    via_create spawn InvocationGate();
    via_resolve spawn InvocationGate();
    proactive spawn InvocationGate();
}

