    can inspect with ConsumerCheck entry {
        mark = "OK" if here.passed else "X";
        print(f"  [{mark}] {here.step_name}");
        if not here.passed {
            visit [->:Reports:->];
        }
        visit [->:Executes:->] else { disengage; };
    }

    can cite with Violation entry {
