"""Organization hierarchy: durable org graph with sync traversal, cycle guards, and partial-snapshot reconcile."""

node Entity {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has internal_id: str = "";
    has external_id: str = "";
    has sync_state: str = "active";
}

node Organization(Entity) { }
node OrganizationalUnit(Entity) { }
node Team(Entity) { }
node Project(Entity) { }

edge Contains { }
edge Owns { has primary: bool = True; }
edge MemberOf { has role: str = "contributor"; }

walker HierarchySync {
    has imported: int = 0;
    has stale: int = 0;
    has blocked: int = 0;

    can start with Root entry {
        print("Hierarchy sync: walking durable org projection");
        visit [-->];
    }

    can scan with Organization | OrganizationalUnit | Team entry {
        if here.sync_state == "active" {
            self.imported += 1;
            print(f"[ACTIVE] {here.title} ({here.internal_id})");
        } else {
            if here.sync_state == "stale" {
                self.stale += 1;
                print(f"[STALE] {here.title} ({here.internal_id})");
            } else {
                self.blocked += 1;
                print(f"[BLOCKED] {here.title} ({here.internal_id})");
            }
        }
        visit [->:Contains:->] else {
            visit [->:Owns:->];
        }
    }

    can scan_project with Project entry {
        badge = "ACTIVE" if here.sync_state == "active" else here.sync_state.upper();
        print(f"[PROJECT] {here.title}: {badge}");
        if here.sync_state == "active" {
            self.imported += 1;
        } else {
            if here.sync_state == "stale" {
                self.stale += 1;
            } else {
                self.blocked += 1;
            }
        }
        visit [-->] else { disengage; }
    }
}

walker CycleGuard {
    has trail: list[str] = [];
    has found_cycle: bool = False;

    can start with Project entry {
        if here.internal_id in self.trail {
            self.found_cycle = True;
            disengage;
        }
        self.trail.append(here.internal_id);
        visit [<--:Owns:--] else { disengage; }
    }

    can ascend_team with Team entry {
        if here.internal_id in self.trail {
            self.found_cycle = True;
            disengage;
        }
        self.trail.append(here.internal_id);
        visit [<--:Contains:--] else { disengage; }
    }

    can ascend_unit with OrganizationalUnit entry {
        if here.internal_id in self.trail {
            self.found_cycle = True;
            disengage;
        }
        self.trail.append(here.internal_id);
        visit [<--:Contains:--] else { disengage; }
    }

    can ascend_org with Organization entry {
        if here.internal_id in self.trail {
            self.found_cycle = True;
            disengage;
        }
        self.trail.append(here.internal_id);
        print(f"CycleGuard: lineage {self.trail} — no cycle");
        disengage;
    }
}

walker ReconcileProbe {
    has snapshot_ids: list[str] = [];
    has preserved: int = 0;

    can start with Root entry {
        print("Partial snapshot reconcile: missing rows must not be deleted");
        visit [-->];
    }

    can probe with Organization | OrganizationalUnit | Team | Project entry {
        in_snapshot = here.external_id in self.snapshot_ids;
        if not in_snapshot and here.available {
            here.sync_state = "stale";
            self.preserved += 1;
            print(f"[RECONCILE] preserved {here.title} as stale (absent from snapshot)");
        }
        visit [-->];
    }
}

