"""UX case receipt v2: a pass receipt is valid only when every recorded check passed."""

node UxCase {
    has case_id: str = "";
    has target_name: str = "";
    has full_test_name: str = "";
    has plan_digest: str = "";
}

node CheckRecord {
    has check_name: str = "";
    has passed: bool = True;
    has detail: str = "";
}

node ReceiptDraft {
    has schema_version: str = "v2";
    has requested_result: str = "";
    has result: str = "";
    has assertions_failed: int = 0;
    has valid: bool = False;
    has validation_note: str = "";
}

edge RecordsCheck { }

edge DraftsReceipt { }

walker ReceiptFinalizer {
    has checks_seen: int = 0;
    has failed_checks: int = 0;
    has pass_allowed: bool = True;
    has summary: str = "";

    can start with Root entry {
        visit [-->];
    }

    can inspect_case with UxCase entry {
        visit [->:RecordsCheck:->];
        visit [->:DraftsReceipt:->];
    }

    can count_check with CheckRecord entry {
        self.checks_seen += 1;
        if not here.passed {
            self.failed_checks += 1;
            self.pass_allowed = False;
        }
        visit [-->];
    }

    can finalize with ReceiptDraft entry {
        here.assertions_failed = self.failed_checks;
        if here.requested_result == "pass" {
            if self.pass_allowed and self.failed_checks == 0 {
                here.result = "pass";
                here.valid = True;
                here.validation_note = "pass invariant satisfied";
            } else {
                here.result = "pass_rejected";
                here.valid = False;
                blocked_reason = "failed checks recorded" if self.failed_checks > 0 else "evidence incomplete";
                here.validation_note = f"finish_pass blocked: {blocked_reason}";
            }
        } else {
            here.result = here.requested_result;
            here.valid = self.failed_checks == 0;
            here.validation_note = "fail receipt accepted from recorded evidence";
        }
        self.summary = (
            f"checks={self.checks_seen} failed={self.failed_checks} "
            f"valid={here.valid} result={here.result}"
        );
        print(
            f"[{here.schema_version}] {here.validation_note}; "
            f"assertions_failed={here.assertions_failed}"
        );
        visit [-->];
    }
}

with entry {
    case = UxCase(
        case_id="ux::perl-lsp::hover::basic",
