"""CPM network validation: detect circular dependencies before backward pass corrupts late-finish values."""

node Activity {
    has name: str = "";
    has duration: int = 0;
    has dangling_pred: str = "";
}

edge Precedes { }

walker ActivityCatalog {
    has names: list[str] = [];

    can start with Root entry {
        visit [-->[?:Activity]] else { disengage; };
    }

    can record with Activity entry {
        self.names += [here.name];
        visit [-->];
    }
}

walker ReferenceValidator {
    has known: list[str] = [];
    has ref_error: str = "";

    can start with Root entry {
        visit [-->[?:Activity]] else { disengage; };
    }

    can check with Activity entry {
        if self.ref_error == "" and here.dangling_pred != "" {
            found = False;
            for k in self.known {
                if k == here.dangling_pred {
                    found = True;
                }
            }
            if not found {
                avail = ", ".join(self.known);
                self.ref_error = f"Activity '{here.name}' references predecessor '{here.dangling_pred}' which does not exist in the network. Available activities: [{avail}]";
                disengage;
            }
        }
        visit [-->];
    }
}

walker CycleDetector {
    has stack: list[str] = [];
    has done: list[str] = [];
    has found_cycle: bool = False;
    has cycle_report: str = "";

    can start with Root entry {
        visit [-->[?:Activity]] else { disengage; };
    }

    can dfs with Activity entry {
        for d in self.done {
            if d == here.name {
                disengage;
            }
        }
        for n in self.stack {
            if n == here.name {
                self.found_cycle = True;
                cycle_parts = [];
                for i in range(len(self.stack)) {
                    u = self.stack[i];
                    v = here.name;
                    if i + 1 < len(self.stack) {
                        v = self.stack[i + 1];
                    }
                    cycle_parts += [f"{u}→{v}"];
                }
                cycle_str = " → ".join(cycle_parts);
                self.cycle_report = f"Circular dependency detected in the network: {cycle_str}. Project networks must be Directed Acyclic Graphs (DAGs). Check your predecessor assignments for the activities in this cycle.";
                disengage;
            }
        }
        self.stack += [here.name];
        visit [->:Precedes:->] else { };
    }

    can unwind with Activity exit {
        new_stack = [];
        if len(self.stack) > 0 {
            for i in range(len(self.stack) - 1) {
                new_stack += [self.stack[i]];
            }
        }
        self.stack = new_stack;
        self.done += [here.name];
    }
}

with entry {
    o = Activity(name="O", duration=0);
    a = Activity(name="A", duration=2);
    b = Activity(name="B", duration=3);
    c = Activity(name="C", duration=1);
    root ++> o;
    root ++> a;
    root ++> b;
    root ++> c;
    o +>:Precedes:+> a;
    a +>:Precedes:+> b;
    b +>:Precedes:+> c;
    c +>:Precedes:+> a;

    catalog = ActivityCatalog();
    root spawn catalog;

    detector = CycleDetector();
    root spawn detector;
    if detector.found_cycle {
        print(detector.cycle_report);
    } else {
        print("Cycle check passed: network is a valid DAG.");
    }

    ghost = Activity(name="Ghost", duration=4, dangling_pred="Missing");
    root ++> ghost;

    catalog2 = ActivityCatalog();
    root spawn catalog2;

    ref_check = ReferenceValidator(known=catalog2.names);
    root spawn ref_check;
    if ref_check.ref_error != "" {
        print(ref_check.ref_error);
    } else {
        print("Reference check passed: all predecessors exist.");
    }
}

