"""Build performance report: model crate dependency graph, walk critical path, and surface duplicate versions."""

node Crate {
    has name: str = "";
    has version: str = "";
    has stage: str = "";
    has duration_secs: float = 0.0;
    has features: str = "";
}

node BuildReport {
    has report_date: str = "";
    has total_secs: float = 0.0;
    has unit_count: int = 0;
}

edge DependsOn {
    has via: str = "";
}

edge CriticalPath {
}

edge DuplicateOf {
    has root_cause: str = "";
}

walker CriticalPathAuditor {
    has path_secs: float = 0.0;
    has bottleneck: str = "";
    has visited: list = [];

    can start with Root entry {
        visit [-->];
    }

    can open_report with BuildReport entry {
        print(f"=== Build Performance Report — {here.report_date} ===");
        print(f"Total: {here.total_secs}s across {here.unit_count} compilation units");
        visit [->:CriticalPath:->] else { disengage; };
    }

    can trace with Crate entry {
        if here.name in self.visited {
            print(f"[CYCLE] re-entered {here.name} — stopping branch");
            disengage;
        }
        self.visited.append(here.name);
        self.path_secs += here.duration_secs;
        if here.duration_secs > 0.0 {
            label = f"{here.name} v{here.version} ({here.stage}, {here.duration_secs}s)";
            if self.bottleneck == "" or here.duration_secs > self._bottleneck_secs() {
                self.bottleneck = label;
            }
            print(f"  critical: {label}");
        }
        visit [->:CriticalPath:->] else { disengage; };
    }

    def _bottleneck_secs() -> float {
        if self.bottleneck == "" {
            return 0.0;
        }
        parts = self.bottleneck.split("(");
        if len(parts) < 2 {
            return 0.0;
        }
        tail = parts[1].split("s)")[0];
        return float(tail.split(", ")[-1]);
    }
}

walker DuplicateScanner {
    has seen: dict = {};
    has dup_count: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can scan with Crate entry {
        if here.name in self.seen {
            prior = self.seen[here.name];
            if prior != here.version {
                self.dup_count += 1;
                print(f"[DUPLICATE] {here.name}: {prior} vs {here.version}");
                visit [->:DuplicateOf:->];
            }
        } else {
            self.seen[here.name] = here.version;
        }
        visit [->:DependsOn:->];
        visit [-->];
    }

    can explain with Crate entry {
        if here.name in self.seen and self.seen[here.name] != here.version {
            print(f"  cause: {here.name} v{here.version} pulled by dependency graph");
        }
        visit [-->];
    }
}

walker BuildOptimizer {
    has savings_secs: float = 0.0;

    can start with Root entry {
        print("=== Optimization Recommendations ===");
        visit [-->];
    }

    can audit with Crate entry {
        if here.name == "aws-lc-sys" and here.stage == "run-custom-build" {
            print(f"[HIGH] Eliminate {here.name} from build-script path (~{here.duration_secs}s)");
            print("  -> jsonschema build-dep: default-features = false");
            self.savings_secs += here.duration_secs;
        }
        if here.name == "rustls" {
            visit [->:DependsOn:->];
        }
        visit [->:DependsOn:->];
    }

    can check_tls with Crate entry {
        if here.name == "rustls" {
            print(f"[MEDIUM] Unify rustls TLS backends (~23s duplicate compile)");
            print(f"  -> ring backend for ureq, aws-lc-rs for reqwest/jsonschema");
            self.savings_secs += here.duration_secs * 0.5;
        }
        visit [-->];
    }

    can finish with BuildReport entry {
        print(f"Estimated recoverable time: ~{self.savings_secs}s on cold builds");
        disengage;
    }
}

