"""CPM network validation: detect circular dependencies before backward pass corrupts late-finish values."""

node Activity {
    has name: str = "";
    has duration: int = 0;
    has pred_ref: str = "";
}

edge Precedes { }

walker NameCollector {
    has names: list[str] = [];

    can start with Root entry {
        visit [-->[?:Activity]] else { disengage; };
    }

    can record with Activity entry {
        self.names += [here.name];
    }
}

walker ReferenceValidator {
    has known: list[str] = [];
    has ref_error: str = "";

    can start with Root entry {
        visit [-->[?:Activity]] else { disengage; };
    }

    can check with Activity entry {
        if self.ref_error == "" and here.pred_ref != "" {
            found = False;
            for k in self.known {
                if k == here.pred_ref {
                    found = True;
                }
            }
            if not found {
                avail = ", ".join(self.known);
                self.ref_error = f"Activity '{here.name}' references predecessor '{here.pred_ref}' which does not exist in the network. Available activities: [{avail}]";
                disengage;
            }
        }
    }
}

walker CycleDetector {
    has stack: list[str] = [];
    has finished: list[str] = [];
    has cycle_error: str = "";

    can start with Root entry {
        visit [-->[?:Activity]] else { disengage; };
    }

    can dfs with Activity entry {
        if self.cycle_error != "" {
            disengage;
        }
        for f in self.finished {
            if f == here.name {
                disengage;
            }
        }
        for i in range(len(self.stack)) {
            if self.stack[i] == here.name {
                cycle_parts = [];
                for j in range(i, len(self.stack) - 1) {
                    cycle_parts += [f"{self.stack[j]}→{self.stack[j + 1]}"];
                }
                cycle_parts += [f"{self.stack[len(self.stack) - 1]}→{here.name}"];
                cycle_str = " → ".join(cycle_parts);
                self.cycle_error = f"Circular dependency detected in the network: {cycle_str}. Project networks must be Directed Acyclic Graphs (DAGs). Check your predecessor assignments for the activities in this cycle.";
                disengage;
            }
        }
        self.stack += [here.name];
        visit [->:Precedes:->] else { };
    }

    can unwind with Activity exit {
        if self.cycle_error != "" {
            disengage;
        }
        new_stack = [];
        if len(self.stack) > 0 {
            for i in range(len(self.stack) - 1) {
                new_stack += [self.stack[i]];
            }
        }
        self.stack = new_stack;
        self.finished += [here.name];
    }
}

with entry {
    o = Activity(name="O", duration=0);
    a = Activity(name="A", duration=2);
    b = Activity(name="B", duration=3);
    c = Activity(name="C", duration=1);
    root ++> o;
    root ++> a;
    root ++> b;
    root ++> c;
    o +>:Precedes:+> a;
    a +>:Precedes:+> b;
    b +>:Precedes:+> c;
    c +>:Precedes:+> a;

    cycle_check = CycleDetector();
    root spawn cycle_check;
    if cycle_check.cycle_error != "" {
        print(cycle_check.cycle_error);
    } else {
        print("Cycle check passed: network is a valid DAG.");
    }

    ghost = Activity(name="Ghost", duration=4, pred_ref="Missing");
