"""Recursive ADT property generation: uniform constructor choice has no depth control and can diverge."""

node AdtSchema {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has mean_arity: float = 1.0;
    has ctor_count: int = 0;
}

node Ctor {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has ordinal: int = 0;
}

node EndCtor(Ctor) { }

node OneCtor(Ctor) { }

node TwoCtor(Ctor) { }

node ThreeCtor(Ctor) { }

node Datum {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

edge Offers { }

edge Child { has idx: int = 0; }

walker UniformGenUser {
    has rng_state: int = 123456789;
    has depth: int = 0;
    has depth_budget: int = 0;
    has nodes_built: int = 0;
    has node_cap: int = 24;
    has pick: int = 0;
    has schema: AdtSchema = None;
    has hook: Datum = None;
    has root_val: Datum = None;

    def lcg() -> int {
        self.rng_state = (self.rng_state * 1103515245 + 12345) & 2147483647;
        return self.rng_state;
    }

    can start with Root entry {
        visit [-->];
    }

    can gen_for_type with AdtSchema entry {
        self.schema = here;
        self.depth = 0;
        self.hook = None;
        self.root_val = None;
        self.nodes_built = 0;
        self.pick = self.lcg() % here.ctor_count;
        visit [->:Offers:->] else { disengage; }
        label = here.title;
        mean = here.mean_arity;
        built = self.nodes_built;
        budget = self.depth_budget;
        print(f"genUser {label} mean_arity={mean} nodes_built={built} depth_budget={budget}");
        visit [-->];
    }

    can gen_user with EndCtor | OneCtor | TwoCtor | ThreeCtor entry {
        if here.ordinal != self.pick {
            return;
        }
        val = Datum(title=here.title, year=self.depth);
        self.nodes_built += 1;
        if self.hook is None {
            self.root_val = val;
        } else {
            self.hook +>:Child:+> val;
        }
        slots = here.year;
        if slots == 0 {
            visit [-->];
            return;
        }
        if self.depth_budget > 0 and self.depth >= self.depth_budget {
            prune = Datum(title="End", year=self.depth + 1);
            self.nodes_built += 1;
            val +>:Child:+> prune;
            visit [-->];
            return;
        }
        if self.nodes_built >= self.node_cap {
            tag = self.schema.title;
            mean = self.schema.mean_arity;
            print(f"  [{tag}] generation capped at {self.node_cap} nodes (mean_arity={mean}, no depth bias)");
            disengage;
        }
        saved_hook = self.hook;
        child_depth = self.depth + 1;
        for (slot, _i) in enumerate(range(slots)) {
            self.hook = val;
            self.depth = child_depth;
            self.pick = self.lcg() % self.schema.ctor_count;
            visit [self.schema->:Offers:->];
        }
        self.hook = saved_hook;
        visit [-->];
    }
}

with entry {
    critical = AdtSchema(title="R", mean_arity=1.0, ctor_count=3);
    critical +>:Offers:+> EndCtor(title="End", ordinal=0, year=0);
    critical +>:Offers:+> OneCtor(title="One", ordinal=1, year=1);
    critical +>:Offers:+> TwoCtor(title="Two", ordinal=2, year=2);

    super_t = AdtSchema(title="T", mean_arity=1.5, ctor_count=2);
    super_t +>:Offers:+> EndCtor(title="Leaf", ordinal=0, year=0);
    super_t +>:Offers:+> ThreeCtor(title="Node", ordinal=1, year=3);

    root ++> critical;
    root ++> super_t;

    print("critical ADT R — uniform ctor choice, no depth budget:");
    critical spawn UniformGenUser(depth_budget=0, node_cap=24);

    print("supercritical ADT T — diverges with positive probability:");
    super_t spawn UniformGenUser(depth_budget=0, node_cap=24);

    print("critical ADT R — depth budget favors base constructors:");
    critical spawn UniformGenUser(depth_budget=3, node_cap=24);
}

