"""Cycle detection: directed DFS 3-color and undirected union-find for DAG validation."""

node Task {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

node Junction {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

node Bridge {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has endpoint_a: str = "";
    has endpoint_b: str = "";
}

node GraphBundle {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has is_directed: bool = True;
}

edge DependsOn { }

walker CycleAuditor {
    has found_cycle: bool = False;
    has color: dict[str, int] = {};
    has parent: dict[str, str] = {};
    has directed: bool = True;

    def find_root(name: str) -> str {
        if name not in self.parent {
            self.parent[name] = name;
        }
        root_label: str = self.parent[name];
        if root_label != name {
            resolved: str = self.find_root(root_label);
            self.parent[name] = resolved;
            root_label = resolved;
        }
        return root_label;
    }

    def unite(a: str, b: str) {
        ra: str = self.find_root(a);
        rb: str = self.find_root(b);
        if ra == rb {
            self.found_cycle = True;
        } else {
            self.parent[rb] = ra;
        }
    }

    can start with GraphBundle entry {
        self.directed = here.is_directed;
        visit [-->];
        kind: str = "directed" if self.directed else "undirected";
        verdict: str = "CYCLIC" if self.found_cycle else "ACYCLIC";
        print(f"{here.title} ({kind}): {verdict}");
    }

    can probe with Task entry {
        if not self.directed {
            visit [-->];
        } else {
            key: str = here.title;
            prior: int = self.color.get(key, 0);
            if prior == 1 {
                self.found_cycle = True;
                disengage;
            }
            if prior == 2 {
                visit [-->];
            } else {
                self.color[key] = 1;
                visit [->:DependsOn:->] else { disengage; };
                self.color[key] = 2;
                visit [-->] else { disengage; };
            }
        }
    }

    can register with Junction entry {
        if self.directed {
            visit [-->];
        } else {
            label: str = here.title;
            if label not in self.parent {
                self.parent[label] = label;
            }
            visit [-->];
        }
    }

    can absorb with Bridge entry {
        if self.directed {
            visit [-->];
        } else {
            self.unite(here.endpoint_a, here.endpoint_b);
            visit [-->];
        }
    }
}

walker CycleDemo {
    can start with Root entry {
        visit [-->];
    }

    can open with GraphBundle entry {
        auditor = CycleAuditor();
        here spawn auditor;
        visit [-->];
    }
}

with entry {
    dir_cycle = GraphBundle(title="directed_cyclic", is_directed=True);
    ta = Task(title="A", year=1);
    tb = Task(title="B", year=2);
    tc = Task(title="C", year=3);
    dir_cycle ++> ta;
    ta +>:DependsOn:+> tb;
    tb +>:DependsOn:+> tc;
    tc +>:DependsOn:+> ta;

    dir_acy = GraphBundle(title="directed_acyclic", is_directed=True);
    tx = Task(title="X", year=1);
    ty = Task(title="Y", year=2);
    tz = Task(title="Z", year=3);
    dir_acy ++> tx;
    tx +>:DependsOn:+> ty;
    ty +>:DependsOn:+> tz;

    und_cycle = GraphBundle(title="undirected_cyclic", is_directed=False);
    j1 = Junction(title="J1", year=1);
    j2 = Junction(title="J2", year=2);
    j3 = Junction(title="J3", year=3);
    b12 = Bridge(title="e12", endpoint_a="J1", endpoint_b="J2");
    b23 = Bridge(title="e23", endpoint_a="J2", endpoint_b="J3");
    b31 = Bridge(title="e31", endpoint_a="J3", endpoint_b="J1");
    und_cycle ++> j1 ++> j2 ++> j3 ++> b12 ++> b23 ++> b31;

    und_acy = GraphBundle(title="undirected_acyclic", is_directed=False);
    r1 = Junction(title="R1", year=1);
    r2 = Junction(title="R2", year=2);
    r3 = Junction(title="R3", year=3);
    e12 = Bridge(title="t12", endpoint_a="R1", endpoint_b="R2");
    e23 = Bridge(title="t23", endpoint_a="R2", endpoint_b="R3");
    und_acy ++> r1 ++> r2 ++> r3 ++> e12 ++> e23;

    root ++> dir_cycle ++> dir_acy ++> und_cycle ++> und_acy;
    root spawn CycleDemo();
}

"""lifecycle_guard: content-derived doc recursion blocks harmless read commands."""

node File {
    has path: str = "";
    has body: str = "";
    has is_markdown: bool = True;
}

node TerminalCommand {
    has payload: str = "";
    has cwd: str = "";
    has probe_id: int = 0;
}

edge Reads { }
edge References { }

walker ShallowGuard {
    has unsafe: bool = False;
    has probe_id: int = -1;

    def matches_lifecycle(text: str) -> bool {
        if text.find("hermes gateway stop") >= 0 {
            return True;
        }
        if text.find("hermes gateway restart") >= 0 {
            return True;
        }
        if text.find("systemctl restart hermes-gateway") >= 0 {
            return True;
        }
        if text.find("pkill -f 'hermes gateway'") >= 0 {
            return True;
        }
        return False;
    }

    can start with Root entry {
        visit [-->] else { disengage; }
    }

    can scan with TerminalCommand entry {
        if self.probe_id >= 0 && here.probe_id != self.probe_id {
            disengage;
        }
        hit = self.matches_lifecycle(here.payload);
        print(f"SHALLOW command probe={here.probe_id} pattern_hit={hit}");
        if hit {
            self.unsafe = True;
        }
        disengage;
    }
}

walker RecursiveGuard {
    has unsafe: bool = False;
    has depth: int = 0;
    has max_depth: int = 8;
    has probe_id: int = -1;
    has visited: list[str] = [];

    def matches_lifecycle(text: str) -> bool {
        if text.find("hermes gateway stop") >= 0 {
