"""aipm build-timings: model crate dependency trees, audit critical-path bottlenecks, and flag duplicate versions."""

node BuildReport {
    has date: str = "";
    has total_sec: float = 0.0;
}

node Crate {
    has name: str = "";
    has version: str = "";
    has duration_sec: float = 0.0;
    has stage: str = "compile";
}

edge DependsOn {
    has feature_gate: str = "";
}

walker DependencyAuditor {
    has label: str = "audit";
    has seen: list[str] = [];
    has sum_sec: float = 0.0;
    has peak_name: str = "";
    has peak_sec: float = 0.0;
    has depth: int = 0;
    has max_depth: int = 64;

    can start with Root entry {
        visit [-->[?:BuildReport]];
    }

    can open_report with BuildReport entry {
        print(f"[{self.label}] cold build {here.date}: {here.total_sec}s");
        visit [-->];
    }

    can inspect with Crate entry {
        if self.depth >= self.max_depth {
            print(f"depth cap hit at {here.name}");
            disengage;
        }
        key = f"{here.name}@{here.version}";
        for prior in self.seen {
            if prior == key {
                print(f"cycle detected at {key}");
                disengage;
            }
        }
        self.seen.append(key);
        self.sum_sec += here.duration_sec;
        if here.duration_sec > self.peak_sec {
            self.peak_sec = here.duration_sec;
            self.peak_name = here.name;
        }
        indent = "";
        for _ in range(self.depth) {
            indent += "  ";
        }
        print(f"{indent}{here.name} v{here.version} [{here.stage}] {here.duration_sec}s");
        self.depth += 1;
        visit [->:DependsOn:->] else { disengage; };
        self.depth -= 1;
    }
}

walker DuplicateVersionScanner {
    has versions: dict[str, str] = {};
    has conflicts: int = 0;

    can start with Root entry {
        visit [-->[?:Crate]];
    }

    can scan with Crate entry {
        crate_name = here.name;
        crate_ver = here.version;
        if crate_name in self.versions {
            if self.versions[crate_name] != crate_ver {
                self.conflicts += 1;
                print(
                    f"duplicate crate: {crate_name} "
                    f"{self.versions[crate_name]} + {crate_ver}"
                );
            }
        } else {
            self.versions[crate_name] = crate_ver;
        }
        visit [-->];
    }
}

