"""TB-IR vs v1 whole-record-read parity for nested struct fields."""

node Inner {
    has a: int = 0;
}

node Outer {
    has r: int = 0;
}

node RecordType {
    has name: str = "";
}

edge NestedField { }
edge TypeDependsOn { }

walker FieldChainProbe {
    has depth: int = 0;
    has resolved: str = "";
    has value: int = 0;

    can start with Outer entry {
        self.depth = 1;
        visit [->:NestedField:->] else {
            self.resolved = "Outer";
            disengage;
        };
    }

    can at_leaf with Inner entry {
        self.depth = 2;
        self.resolved = "Inner";
        self.value = here.a;
        disengage;
    }
}

walker WholeReadParity {
    has backend: str = "v1";
    has ok: bool = False;
    has copied_a: int = 0;
    has note: str = "";

    can start with Outer entry {
        if self.backend == "tbir" {
            self.ok = False;
            self.note = "tbir rejects let d : Inner = o.inner";
            disengage;
        }
        visit [->:NestedField:->] else {
            self.note = "missing Inner field";
            disengage;
        };
    }

    can bind with Inner entry {
        self.copied_a = here.a;
        self.ok = True;
        self.note = "v1 accepts whole-record read";
        disengage;
    }
}

walker NestedFieldWrite {
    has scratch_a: int = 0;
    has wrote: bool = False;

    can start with Outer entry {
        visit [->:NestedField:->] else { disengage; };
    }

    can touch with Inner entry {
        if self.scratch_a == 0 {
            self.scratch_a = here.a;
            disengage;
        } else {
            here.a = self.scratch_a;
            self.wrote = True;
            disengage;
        }
    }
}

walker TypeEmitter {
    has inner_defined: bool = False;
    has outer_defined: bool = False;

    can start with Root entry {
        visit [-->] else { disengage; };
    }

    can define with RecordType entry {
        if here.name == "Inner" {
            self.inner_defined = True;
        } else {
            if here.name == "Outer" {
                if self.inner_defined {
                    self.outer_defined = True;
                }
            }
        }
        visit [-->] else { disengage; };
    }
}

with entry {
    inner_def = RecordType(name="Inner");
    outer_def = RecordType(name="Outer");
    root ++> inner_def ++> outer_def;
    outer_def +>:TypeDependsOn:+> inner_def;

    emitter = TypeEmitter();
    root spawn emitter;

    inner_val = Inner(a=5);
    o = Outer(r=7);
    root ++> o;
    o +>:NestedField:+> inner_val;

    p = Outer(r=0);
    p_inner = Inner(a=0);
    root ++> p;
    p +>:NestedField:+> p_inner;

    probe = FieldChainProbe();
    o spawn probe;

    v1 = WholeReadParity(backend="v1");
    o spawn v1;

    tbir = WholeReadParity(backend="tbir");
    o spawn tbir;

    read_src = NestedFieldWrite();
    o spawn read_src;
    write_dst = NestedFieldWrite();
    write_dst.scratch_a = read_src.scratch_a;
    p spawn write_dst;
}

"""Adaptive context sufficiency gate: dependency walk decides READ_MORE vs REASON_NOW."""

node HarnessTask {
    has name: str = "";
    has failure_signature: str = "";
    has attempt_count: int = 0;
    has context_bytes: int = 0;
    has prior_verify_failed: bool = False;
}

node SourceFile {
    has path: str = "";
    has nbytes: int = 0;
    has read: bool = False;
}

node Symbol {
    has name: str = "";
    has resolved: bool = False;
    has cited_in_failure: bool = False;
}

edge NeedsContext { }
edge Defines { }
edge DependsOn { }

walker StaticGate {
    has unresolved: int = 0;
    has unread_definers: int = 0;
    has decision: str = "";

    can start with Root entry {
        visit [-->[?:HarnessTask]];
    }

    can evaluate with HarnessTask entry {
        self.unresolved = 0;
        self.unread_definers = 0;
        print(f"[STATIC] {here.name}: failure={here.failure_signature}");
        visit [->:NeedsContext:->] else { disengage; };
        if self.unread_definers > 0 {
            self.decision = "READ_MORE";
        } else {
            if here.prior_verify_failed && here.attempt_count < 2 {
                self.decision = "READ_MORE";
            } else {
                self.decision = "REASON_NOW";
            }
        }
        print(
            f"  unresolved={self.unresolved} unread_definers={self.unread_definers} "
            f"context={here.context_bytes}b -> {self.decision}"
        );
    }

    can tally_symbol with Symbol entry {
        if here.cited_in_failure && !here.resolved {
            self.unresolved += 1;
            visit [<-:Defines:--] else { disengage; };
        } else {
            disengage;
        }
    }

    can tally_definer with SourceFile entry {
        if !here.read {
            self.unread_definers += 1;
        }
        disengage;
    }
}

walker LearnedGate {
    has w_unresolved: float = 1.5;
    has w_unread: float = 2.0;
    has w_context: float = -0.002;
    has w_retry: float = 1.2;
    has unresolved: int = 0;
    has unread_definers: int = 0;
    has score: float = 0.0;
    has decision: str = "";

    can start with Root entry {
        visit [-->[?:HarnessTask]];
    }

    can score with HarnessTask entry {
        self.unresolved = 0;
        self.unread_definers = 0;
        visit [->:NeedsContext:->] else { disengage; };
        retry = 1.0 if (here.prior_verify_failed && here.attempt_count < 2) else 0.0;
        self.score = (
            self.w_unresolved * float(self.unresolved)
            + self.w_unread * float(self.unread_definers)
            + self.w_context * float(here.context_bytes)
            + self.w_retry * retry
        );
        verdict = "READ_MORE" if self.score > 0.0 else "REASON_NOW";
        self.decision = verdict;
        print(f"[LEARNED-LINEAR] {here.name}: score={self.score} -> {self.decision}");
    }

    can tally_symbol with Symbol entry {
        if here.cited_in_failure && !here.resolved {
            self.unresolved += 1;
            visit [<-:Defines:--] else { disengage; };
        } else {
            disengage;
        }
    }

    can tally_definer with SourceFile entry {
        if !here.read {
            self.unread_definers += 1;
        }
        disengage;
    }
}

walker ContextReader {
    has seen: list[str] = [];
    has bytes_added: int = 0;

    can start with Root entry {
        visit [-->[?:HarnessTask]];
    }

    can acquire with HarnessTask entry {
        self.seen = [];
        self.bytes_added = 0;
        print(f"[READ] acquiring context for {here.name}");
        visit [->:NeedsContext:->] else { disengage; };
        here.context_bytes += self.bytes_added;
        print(f"  gathered {self.bytes_added}b; total context={here.context_bytes}b");
    }

    can follow_symbol with Symbol entry {
        if here.cited_in_failure && !here.resolved {
            visit [<-:Defines:--] else { disengage; };
        } else {
            disengage;
        }
    }

    can open_file with SourceFile entry {
        if here.path in self.seen {
            disengage;
        }
        self.seen.append(here.path);
        if !here.read {
            here.read = True;
            self.bytes_added += here.nbytes;
            print(f"  read {here.path} ({here.nbytes}b)");
        }
        visit [->:DependsOn:->] else { disengage; };
    }
}

with entry {
    t_enough = HarnessTask(
        name="calc_add",
        failure_signature="NameError: add",
        context_bytes=420,
        attempt_count=0
    );
    f_calc = SourceFile(path="calc.py", nbytes=420, read=True);
    s_add = Symbol(name="add", resolved=True, cited_in_failure=True);
    t_enough +>:NeedsContext:+> s_add;
    f_calc +>:Defines:+> s_add;

    t_gap = HarnessTask(
        name="patch_helper",
        failure_signature="AttributeError: helper",
        context_bytes=180,
        attempt_count=0
    );
    f_main = SourceFile(path="main.py", nbytes=180, read=True);
    f_utils = SourceFile(path="utils.py", nbytes=310, read=False);
    s_helper = Symbol(name="helper", resolved=False, cited_in_failure=True);
    t_gap +>:NeedsContext:+> s_helper;
    f_utils +>:Defines:+> s_helper;
    f_main +>:DependsOn:+> f_utils;

    t_recover = HarnessTask(
        name="recover_cycle",
        failure_signature="TypeError: coerce",
        context_bytes=95,
        attempt_count=1,
        prior_verify_failed=True
    );
    f_types = SourceFile(path="types.py", nbytes=95, read=True);
    s_coerce = Symbol(name="coerce", resolved=True, cited_in_failure=True);
    t_recover +>:NeedsContext:+> s_coerce;
    f_types +>:Defines:+> s_coerce;

    root ++> t_enough ++> t_gap ++> t_recover;

    root spawn StaticGate();
    root spawn LearnedGate();
    root spawn ContextReader();

    print(
        f"after reads: utils.read={f_utils.read} "
        f"gap.context={t_gap.context_bytes}b"
    );
}

"""aipm build-timings: model crate dependency trees, audit critical-path bottlenecks, and flag duplicate versions."""

node BuildReport {
    has date: str = "";
    has total_sec: float = 0.0;
}

node Crate {
    has name: str = "";
    has version: str = "";
    has duration_sec: float = 0.0;
    has stage: str = "compile";
}

edge DependsOn {
    has feature_gate: str = "";
}

walker DependencyAuditor {
    has label: str = "audit";
    has seen: list[str] = [];
    has sum_sec: float = 0.0;
    has peak_name: str = "";
    has peak_sec: float = 0.0;
    has depth: int = 0;
    has max_depth: int = 64;

    can start with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can open_report with BuildReport entry {
        print(f"[{self.label}] cold build {here.date}: {here.total_sec}s");
        visit [-->] else {
            disengage;
        }
    }

    can inspect with Crate entry {
        if self.depth >= self.max_depth {
            print(f"depth cap hit at {here.name}");
            disengage;
        }
        key = f"{here.name}@{here.version}";
        for prior in self.seen {
            if prior == key {
                print(f"cycle detected at {key}");
                disengage;
            }
        }
        self.seen.append(key);
        self.sum_sec += here.duration_sec;
        if here.duration_sec > self.peak_sec {
            self.peak_sec = here.duration_sec;
            self.peak_name = here.name;
        }
        print(f"depth={self.depth} {here.name} v{here.version} [{here.stage}] {here.duration_sec}s");
        self.depth += 1;
        visit [->:DependsOn:->] else {
            disengage;
        }
        self.depth -= 1;
    }
}

walker DuplicateVersionScanner {
    has versions: dict[str, str] = {};
    has conflicts: int = 0;

    can start with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can scan with Crate entry {
        crate_name = here.name;
        crate_ver = here.version;
        if crate_name in self.versions {
            if self.versions[crate_name] != crate_ver {
                self.conflicts += 1;
                print(
                    f"duplicate crate: {crate_name} "
                    f"{self.versions[crate_name]} + {crate_ver}"
                );
            }
        } else {
            self.versions[crate_name] = crate_ver;
        }
        visit [-->] else {
            disengage;
        }
    }
}

