    spec_crate +>:DependsOn:+> libgit2_crate;

    print("=== dependency critical-path audit (full tree) ===");
    full_audit = DependencyAuditor(label="full");
    root spawn full_audit;
    print(
        f"bottleneck: {full_audit.peak_name} ({full_audit.peak_sec}s); "
        f"reachable compile cost {full_audit.sum_sec}s"
    );

    print("=== duplicate version scan ===");
    dup_scan = DuplicateVersionScanner();
