        name="libaipm-engine-spec",
        version="0.1.0",
        duration_sec=2.0,
        stage="build.rs"
    );
    jsonschema_pruned = Crate(name="jsonschema", version="0.46", duration_sec=22.3);
    libgit2_pruned = Crate(
        name="libgit2-sys",
        version="0.17.0",
        duration_sec=71.9,
        stage="build script"
    );

    root ++> pruned_report ++> spec_pruned;
    spec_pruned +>:DependsOn:+> jsonschema_pruned;
    spec_pruned +>:DependsOn:+> libgit2_pruned;

    print("=== pruned tree (resolve-http disabled on jsonschema) ===");
    pruned_audit = DependencyAuditor(label="pruned");
    pruned_report spawn pruned_audit;
    saved = full_audit.sum_sec - pruned_audit.sum_sec;
    print(
        f"pruned reachable cost {pruned_audit.sum_sec}s; "
        f"est. savings ~{saved}s by dropping reqwest→aws-lc-sys chain"
    );
}

