"""Author and seal Juana talking-bust references from a master character sheet.

Models a bounded authoring DAG over generation tasks with typed dependencies,
staged hash-verified candidates never auto-approved, explicit promotion into a
sealed CharacterDesignPackage, and resume-aware orchestration that skips
approved work without clobbering accepted references.
"""

node MasterSheet {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has revision: str = "";
}

node GenerationTask {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has status: str = "pending";
    has retry_count: int = 0;
    has max_retries: int = 3;
}

node Candidate {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has content_hash: str = "";
    has approved: bool = False;
    has rejected: bool = False;
}

node ApprovedRef {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has content_hash: str = "";
}

edge SourcedFrom { }
edge DependsOn { }
edge Produces { }
edge PromotedTo { }

walker AuthoringRunner {
    has visited: list[str] = [];
    has cycle_detected: bool = False;
    has executed: int = 0;
    has skipped: int = 0;
    has checking_deps: bool = False;
    has deps_blocked: bool = False;
    has waiting_task: str = "";

    can start with Root entry {
        print("Bounded Juana reference-authoring run (resume-aware DAG)");
        visit [-->];
    }

    can from_master with MasterSheet entry {
        print(f"Master sheet: {here.title} rev={here.revision}");
        visit [->:SourcedFrom:->] else {
            visit [-->] else { disengage; };
        };
    }

    can run_task with GenerationTask entry {
        if self.checking_deps {
            if here.status != "approved" {
                self.deps_blocked = True;
            }
            disengage;
        }

        name = here.title;
        if name in self.visited {
            self.cycle_detected = True;
            print(f"CYCLE guard tripped at task {name}");
            disengage;
        }
        self.visited.append(name);

        if here.status == "approved" {
            print(f"RESUME skip approved: {name}");
            self.skipped += 1;
            visit [-->] else { disengage; };
        } elif here.retry_count >= here.max_retries {
            print(f"RETRIES exhausted: {name}");
            visit [-->] else { disengage; };
        } else {
            self.deps_blocked = False;
            self.waiting_task = name;
            self.checking_deps = True;
            visit [->:DependsOn:->];
            self.checking_deps = False;
            if self.deps_blocked {
                print(f"BLOCKED deps: {name}");
                visit [-->] else { disengage; };
            } else {
                attempt_num = here.retry_count + 1;
                here.retry_count = attempt_num;
                print(f"EXECUTE {name} attempt {attempt_num}");
                visit [->:Produces:->];
                here.status = "approved";
                self.executed += 1;
                visit [-->] else { disengage; };
            }
        }
    }

    can stage with Candidate entry {
        tag = "rejected-audit" if here.rejected else "staged";
        print(f"  {tag} {here.title} hash={here.content_hash}");
        visit [-->] else { disengage; };
    }
}

