"""Adaptive context sufficiency gate: dependency walk decides READ_MORE vs REASON_NOW."""

node HarnessTask {
    has name: str = "";
    has failure_signature: str = "";
    has attempt_count: int = 0;
    has context_bytes: int = 0;
    has prior_verify_failed: bool = False;
}

node SourceFile {
    has path: str = "";
    has nbytes: int = 0;
    has read: bool = False;
}

node Symbol {
    has name: str = "";
    has resolved: bool = False;
    has cited_in_failure: bool = False;
}

edge NeedsContext { }
edge Defines { }
edge DependsOn { }

walker StaticGate {
    has unresolved: int = 0;
    has unread_definers: int = 0;
    has decision: str = "";

    can start with Root entry {
        visit [-->];
    }

    can evaluate with HarnessTask entry {
        self.unresolved = 0;
        self.unread_definers = 0;
        print(f"[STATIC] {here.name}: failure={here.failure_signature}");
        visit [->:NeedsContext:->] else { disengage; };
        if self.unread_definers > 0 {
            self.decision = "READ_MORE";
        } elif here.prior_verify_failed and here.attempt_count < 2 {
            self.decision = "READ_MORE";
        } else {
            self.decision = "REASON_NOW";
        }
        print(
            f"  unresolved={self.unresolved} unread_definers={self.unread_definers} "
            f"context={here.context_bytes}b -> {self.decision}"
        );
    }

    can tally_symbol with Symbol entry {
        if here.cited_in_failure and not here.resolved {
            self.unresolved += 1;
            visit [<--:Defines:--] else { disengage; };
        } else {
            disengage;
        }
    }

    can tally_definer with SourceFile entry {
        if not here.read {
            self.unread_definers += 1;
        }
        disengage;
    }
}

walker LearnedGate {
    has w_unresolved: float = 1.5;
    has w_unread: float = 2.0;
    has w_context: float = -0.002;
    has w_retry: float = 1.2;
    has unresolved: int = 0;
    has unread_definers: int = 0;
    has score: float = 0.0;
    has decision: str = "";

    can start with Root entry {
        visit [-->];
    }

    can score with HarnessTask entry {
        self.unresolved = 0;
        self.unread_definers = 0;
        visit [->:NeedsContext:->] else { disengage; };
        retry = 1.0 if (here.prior_verify_failed and here.attempt_count < 2) else 0.0;
        self.score = (
            self.w_unresolved * float(self.unresolved)
            + self.w_unread * float(self.unread_definers)
            + self.w_context * float(here.context_bytes)
            + self.w_retry * retry
        );
        verdict = "READ_MORE" if self.score > 0.0 else "REASON_NOW";
        self.decision = verdict;
        print(f"[LEARNED-LINEAR] {here.name}: score={self.score} -> {self.decision}");
    }

    can tally_symbol with Symbol entry {
        if here.cited_in_failure and not here.resolved {
            self.unresolved += 1;
            visit [<--:Defines:--] else { disengage; };
        } else {
            disengage;
        }
    }

    can tally_definer with SourceFile entry {
        if not here.read {
            self.unread_definers += 1;
        }
        disengage;
    }
}

walker ContextReader {
    has seen: list[str] = [];
    has bytes_added: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can acquire with HarnessTask entry {
        self.seen = [];
        self.bytes_added = 0;
        print(f"[READ] acquiring context for {here.name}");
        visit [->:NeedsContext:->] else { disengage; };
        here.context_bytes += self.bytes_added;
        print(f"  gathered {self.bytes_added}b; total context={here.context_bytes}b");
    }

    can follow_symbol with Symbol entry {
        if here.cited_in_failure and not here.resolved {
            visit [<--:Defines:--] else { disengage; };
        } else {
            disengage;
        }
    }

    can open_file with SourceFile entry {
        if here.path in self.seen {
            disengage;
        }
        self.seen.append(here.path);
        if not here.read {
            here.read = True;
            self.bytes_added += here.nbytes;
            print(f"  read {here.path} ({here.nbytes}b)");
        }
        visit [->:DependsOn:->] else { disengage; };
    }
}

