        name="calc_add",
        failure_signature="NameError: add",
        context_bytes=420,
        attempt_count=0
    );
    f_calc = SourceFile(path="calc.py", nbytes=420, read=True);
    s_add = Symbol(name="add", resolved=True, cited_in_failure=True);
    t_enough +>:NeedsContext:+> s_add;
    f_calc +>:Defines:+> s_add;

    t_gap = HarnessTask(
        name="patch_helper",
        failure_signature="AttributeError: helper",
        context_bytes=180,
