    );
    f_main = SourceFile(path="main.py", nbytes=180, read=True);
    f_utils = SourceFile(path="utils.py", nbytes=310, read=False);
    s_helper = Symbol(name="helper", resolved=False, cited_in_failure=True);
    t_gap +>:NeedsContext:+> s_helper;
    f_utils +>:Defines:+> s_helper;
    f_main +>:DependsOn:+> f_utils;

    t_recover = HarnessTask(
        name="recover_cycle",
        failure_signature="TypeError: coerce",
        context_bytes=95,
        attempt_count=1,
        prior_verify_failed=True
    );
    f_types = SourceFile(path="types.py", nbytes=95, read=True);
