"""IABV backlog demo: change-impact propagation over organism dependencies,
knowledge derivation chains, and bounded cognitive checkpoint resume."""

node Auditable {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

node SystemComponent(Auditable) {
    has name: str = "";
    has kind: str = "";
}

node ChangeRecord(Auditable) {
    has commit_id: str = "";
    has summary: str = "";
}

node KnowledgeItem(Auditable) {
    has category: str = "unknown";
    has content: str = "";
}

node TrackedWork(Auditable) {
    has label: str = "";
}

node CognitiveProcess(TrackedWork) {
    has process_id: str = "";
    has goal: str = "";
    has status: str = "active";
    has phase: str = "init";
}

node Checkpoint(TrackedWork) {
    has step: int = 0;
    has work_phase: str = "init";
    has remaining: str = "unknown";
}

edge DependsOn { }

edge DirectlyChanged {
    has classification: str = "DIRECTLY_CHANGED";
}

edge DerivesFrom { }

edge CheckpointLink { }

edge NextCheckpoint { }

walker ImpactAuditor {
    has seen: list[str] = [];
    has mark: str = "DIRECTLY_CHANGED";

    can start with Root entry {
        visit [-->] else { disengage; };
    }

    can begin_change with ChangeRecord entry {
        print(f"Organism impact audit: {here.commit_id} — {here.summary}");
        self.mark = "DIRECTLY_CHANGED";
        visit [->:DirectlyChanged:->] else { disengage; };
    }

    can assess with SystemComponent entry {
        if here.name in self.seen {
            disengage;
        }
        self.seen.append(here.name);
        impact = self.mark;
        print(f"  {impact}: {here.name} ({here.kind})");
        saved = self.mark;
        self.mark = "INDIRECTLY_AT_RISK";
        visit [<-:DependsOn:<-] else { disengage; };
        self.mark = saved;
    }

    can summarize with ChangeRecord | SystemComponent entry {
        state = "open" if here.available else "closed";
        print(f"  auditable [{state}] {here.title} ({here.year})");
    }
}

walker KnowledgeCurator {
    has lessons: int = 0;

    can start with Root entry {
        visit [-->] else { disengage; };
    }

    can trace with KnowledgeItem entry {
        if here.category == "observation" {
            print("Knowledge lineage (incident → rule):");
        }
        print(f"  [{here.category}] {here.content}");
        self.lessons += 1;
        visit [->:DerivesFrom:->] else { disengage; };
    }
}

walker CognitiveResumer {
    has chunks_done: int = 0;

    can start with Root entry {
        visit [-->] else { disengage; };
    }

    can resume_process with CognitiveProcess entry {
        print(
            f"Cognitive resume: {here.process_id} goal={here.goal} "
            f"status={here.status} phase={here.phase}"
        );
        visit [->:CheckpointLink:->] else { disengage; };
    }

    can consume_chunk with CognitiveProcess | Checkpoint entry {
        if here is not CognitiveProcess {
            print(
                f"  chunk step={here.step} phase={here.work_phase} "
                f"remaining={here.remaining}"
            );
            self.chunks_done += 1;
            visit [->:NextCheckpoint:->] else { disengage; };
        }
    }
}

