"""TB-IR vs v1 whole-record-read parity for nested struct fields."""

node Inner {
    has a: int = 0;
}

node Outer {
    has r: int = 0;
}

node RecordDef {
    has name: str = "";
}

edge NestedField { }
edge DependsOn { }

walker FieldChainResolve {
    has depth: int = 0;
    has leaf_a: int = 0;
    has ok: bool = False;

    can at_outer with Outer entry {
        self.depth = 1;
        visit [->:NestedField:->] else { disengage; };
    }

    can at_inner with Inner entry {
        self.depth = 2;
        self.leaf_a = here.a;
        self.ok = True;
        disengage;
    }
}

walker V1LetBind {
    has copied_a: int = 0;
    has ok: bool = False;

    can attempt with Outer entry {
        visit [->:NestedField:->] else { disengage; };
    }

    can whole_read with Inner entry {
        self.copied_a = here.a;
        self.ok = True;
        disengage;
    }
}

walker TbirLetBind {
    has ok: bool = False;
    has reason: str = "";

    can attempt with Outer entry {
        visit [->:NestedField:->] else { disengage; };
    }

    can reject_bind with Inner entry {
        self.ok = False;
        self.reason = "TB-IR rejects let d : Inner = o.inner";
        disengage;
    }
}

walker FieldCopyRead {
    has captured_a: int = 0;

    can from_outer with Outer entry {
        visit [->:NestedField:->] else { disengage; };
    }

    can take with Inner entry {
        self.captured_a = here.a;
        disengage;
    }
}

walker FieldCopyWrite {
    has source_a: int = 0;
    has done: bool = False;

    can into_outer with Outer entry {
        visit [->:NestedField:->] else { disengage; };
    }

    can paste with Inner entry {
        here.a = self.source_a;
        self.done = True;
        disengage;
    }
}

walker EmitOrder {
    has phase: int = 0;
    has ordered: bool = False;

    can walk with RecordDef entry {
        if self.phase == 0 && here.name == "Outer" {
            self.phase = 1;
            visit [<--:DependsOn:--] else { disengage; };
        } elif self.phase == 1 && here.name == "Inner" {
            self.ordered = True;
            disengage;
        } else {
            disengage;
        }
    }
}

with entry {
    inner_def = RecordDef(name="Inner");
    outer_def = RecordDef(name="Outer");
    root ++> inner_def;
    root ++> outer_def;
    outer_def +>:DependsOn:+> inner_def;

    src_inner = Inner(a=5);
    o = Outer(r=7);
    root ++> o;
    o +>:NestedField:+> src_inner;

    dst_inner = Inner(a=0);
    p = Outer(r=0);
    root ++> p;
    p +>:NestedField:+> dst_inner;

    o spawn FieldChainResolve();
    o spawn V1LetBind();
    o spawn TbirLetBind();

    reader = FieldCopyRead();
    o spawn reader;
    writer = FieldCopyWrite(source_a=reader.captured_a);
    p spawn writer;

    outer_def spawn EmitOrder();
}

