"""ADR-006 T3 runtime spike: evaluate browser embedding candidates against security gates, dependency order, and patch-path drill."""

node SpikeTask {
    has title: str = "";
    has priority: str = "";
    has target_tier: str = "T3";
}

node RuntimeCandidate {
    has name: str = "";
    has tier: str = "T3";
    has bundled_chromium: bool = False;
    has site_isolation: bool = False;
    has sandbox_enabled: bool = True;
    has patch_path_controllable: bool = False;
    has cross_site_oopif: bool = False;
}

node SecurityGate {
    has gate_name: str = "";
    has is_hard_veto: bool = True;
    has requires_bundled: bool = False;
}

node PatchPhase {
    has phase_name: str = "";
    has phase_order: int = 0;
    has elapsed_hours: float = 0.0;
}

edge DependsOn { }
edge Evaluates { }
edge RequiresGate { }
edge NextPhase { }

walker DependencyResolver {
    has visiting: list[str] = [];
    has resolved: list[str] = [];
    has cycle_detected: bool = False;

    can start with Root entry {
        print("=== Dependency Resolution (#30 -> #23) ===");
        visit [-->];
    }

    can resolve with SpikeTask entry {
        if here.title in self.visiting {
            print(f"[CYCLE] blocked at {here.title}");
            self.cycle_detected = True;
            disengage;
        }
        self.visiting.append(here.title);
        visit [->:DependsOn:->] else {
            self.resolved.append(here.title);
            if len(self.visiting) > 0 {
                self.visiting.pop();
            }
            if len(self.visiting) == 0 {
                print(f"[DEPS] execution order: {self.resolved}");
            }
        };
    }
}

walker RuntimeAuditor {
    has current_candidate: str = "";
    has candidate_tier: str = "T3";
    has candidate_bundled: bool = False;
    has candidate_site_iso: bool = False;
    has candidate_sandbox: bool = True;
    has candidate_patch: bool = False;
    has candidate_oopif: bool = False;
    has passes_all: bool = True;
    has qualified: list[str] = [];
    has vetoed: list[str] = [];
    has gate_failures: int = 0;

    can start with Root entry {
        print("=== T3 Runtime Candidate Audit (ADR-006) ===");
        visit [-->];
    }

    can begin_spike with SpikeTask entry {
        visit [->:Evaluates:->] else { disengage; };
    }

    can audit with RuntimeCandidate entry {
        self.current_candidate = here.name;
        self.candidate_tier = here.tier;
        self.candidate_bundled = here.bundled_chromium;
        self.candidate_site_iso = here.site_isolation;
        self.candidate_sandbox = here.sandbox_enabled;
        self.candidate_patch = here.patch_path_controllable;
        self.candidate_oopif = here.cross_site_oopif;
        self.passes_all = True;

        if here.tier != "T3" {
            self.passes_all = False;
            print(f"  ! HARD VETO: tier {here.tier} insufficient for T3 foreign-app gate");
        }

        visit [->:RequiresGate:->] else { disengage; };

        verdict = "QUALIFIED" if self.passes_all else "VETOED";
        bundle_label = "bundled-chromium" if here.bundled_chromium else "system-webview";
        print(f"[{verdict}] {here.name} ({bundle_label})");

        if self.passes_all {
            self.qualified.append(here.name);
        } else {
            self.vetoed.append(here.name);
        }
        disengage;
    }

    can check_gate with SecurityGate entry {
        gate_ok = True;
        if here.gate_name == "site-per-process" {
            gate_ok = self.candidate_site_iso;
        }
        if here.gate_name == "no-sandbox-escape" {
            gate_ok = self.candidate_sandbox;
        }
        if here.gate_name == "controllable-patch-path" {
            gate_ok = self.candidate_patch and self.candidate_bundled;
        }
        if here.gate_name == "cross-site-oopif-isolation" {
            gate_ok = self.candidate_oopif;
        }
        if here.requires_bundled and not self.candidate_bundled {
            gate_ok = False;
        }
        if not gate_ok {
            self.passes_all = False;
            self.gate_failures += 1;
            severity = "HARD VETO" if here.is_hard_veto else "soft fail";
            print(f"  ! {severity}: {here.gate_name} failed for {self.current_candidate}");
        }
        visit [-->] else { disengage; };
    }

    can finish_spike with SpikeTask exit {
        print(f"[AUDIT] qualified={self.qualified} vetoed={self.vetoed} gate_failures={self.gate_failures}");
    }
}

walker PatchDrill {
    has total_hours: float = 0.0;
    has phases_done: int = 0;

    can start with Root entry {
        print("=== Patch-Path Drill (upstream-fix -> staged rollout) ===");
        visit [-->];
    }

    can execute with PatchPhase entry {
        self.total_hours += here.elapsed_hours;
        self.phases_done += 1;
        print(f"  [{here.phase_order}] {here.phase_name} ({here.elapsed_hours}h)");
        visit [->:NextPhase:->] else {
            print(f"[DRILL] {self.phases_done} phases, {self.total_hours}h total elapsed");
            disengage;
        };
    }
}

