    detect = PatchPhase(phase_name="Detect upstream Chromium release", phase_order=1, elapsed_hours=4.0);
    identify = PatchPhase(phase_name="Identify applicable CVEs", phase_order=2, elapsed_hours=8.0);
    build = PatchPhase(phase_name="Build all platforms", phase_order=3, elapsed_hours=24.0);
    regress = PatchPhase(phase_name="Run isolation/security corpus", phase_order=4, elapsed_hours=12.0);
    sbom = PatchPhase(phase_name="Generate SBOM and provenance", phase_order=5, elapsed_hours=3.0);
    stage = PatchPhase(phase_name="Stage rollout", phase_order=6, elapsed_hours=6.0);
    rollback = PatchPhase(phase_name="Rollback and recovery drill", phase_order=7, elapsed_hours=4.0);
    record = PatchPhase(phase_name="Record latency metrics", phase_order=8, elapsed_hours=1.0);

    detect +>:NextPhase:+> identify;
    identify +>:NextPhase:+> build;
    build +>:NextPhase:+> regress;
    regress +>:NextPhase:+> sbom;
    sbom +>:NextPhase:+> stage;
    stage +>:NextPhase:+> rollback;
    rollback +>:NextPhase:+> record;

    root ++> spike;
    root ++> detect;

    root spawn DependencyResolver();
    root spawn RuntimeAuditor();
    root spawn PatchDrill();
