"""Lazy DNS for remote_servers: build cluster topology without blocking startup on peer DNS."""

node Cluster {
    has name: str = "";
    has ready: bool = False;
}

node Host {
    has hostname: str = "";
    has resolved_ip: str = "";
    has is_local: bool = False;
    has dns_resolved: bool = False;
    has dns_fail: bool = False;
    has resolver_timeout_ms: int = 5000;

    def try_resolve() -> bool {
        if self.dns_resolved {
            return True;
        }
        if self.dns_fail {
            print(f"    getaddrinfo timeout ({self.resolver_timeout_ms}ms): {self.hostname}");
            return False;
        }
        ip = "127.0.0.1" if self.hostname == "localhost" else "10.42.0.7";
        self.resolved_ip = ip;
        self.dns_resolved = True;
        self.is_local = self.hostname == "localhost" or self.hostname.endswith(".svc.local");
        print(f"    resolved {self.hostname} -> {self.resolved_ip}, is_local={self.is_local}");
        return True;
    }

    def simulate_dns_recovery() -> None {
        self.dns_fail = False;
    }
}

edge MemberOf { has shard: int = 0; }

walker EagerStartupLoader {
    has blocked_ms: int = 0;
    has resolved_count: int = 0;

    can start with Root entry {
        print("EAGER: setClustersConfig walks every host and calls getaddrinfo serially");
        visit [-->];
    }

    can load_cluster with Cluster entry {
        print(f"EAGER: building topology for cluster '{here.name}'");
        visit [-->];
    }

    can resolve_at_startup with Host entry {
        if not here.dns_resolved {
            if here.dns_fail {
                self.blocked_ms += here.resolver_timeout_ms;
                here.is_local = False;
            } elif here.try_resolve() {
                self.resolved_count += 1;
            }
        }
        visit [-->];
    }

    can mark_not_ready with Cluster exit {
        here.ready = False;
    }
}

walker LazyTopologyBuilder {
    can start with Root entry {
        print("LAZY: wiring remote_servers topology — zero DNS on startup path");
        visit [-->];
    }

    can register_cluster with Cluster entry {
        here.ready = True;
        print(f"LAZY: cluster '{here.name}' ready (no DNS calls)");
        visit [->:MemberOf:->] else { visit [-->]; }
    }

    can register_host with Host entry {
        print(f"LAZY: registered {here.hostname} (address unresolved, is_local deferred)");
        visit [-->];
    }
}

walker DistributedQueryRouter {
    has target_host: str = "localhost";

    can start with Root entry {
        print(f"QUERY: first use — resolve '{self.target_host}' on demand");
        visit [-->[?:Host]] else { disengage; }
    }

    can route with Host entry {
        if here.hostname != self.target_host {
            visit [-->];
        } else {
            ok = here.try_resolve();
            path = "prefer_localhost_replica" if (ok and here.is_local) else "remote path";
            print(f"QUERY: {here.hostname} -> connection pool uses {path}");
            disengage;
        }
    }
}

walker DNSCacheUpdater {
    has refreshed: int = 0;

    can start with Root entry {
        print("DNSCacheUpdater: refresh stale is_local after transient startup failure");
        visit [-->];
    }

    can refresh with Host entry {
        if here.dns_resolved {
            visit [-->];
        } else {
