"""ByroRedux NIF import: worker pool parallelises cheap parse; mesh+collision drains serially on main."""

node NifAsset {
    has path: str = "";
    has parse_ms: float = 0.0;
    has emitter_ms: float = 0.0;
    has collision_ms: float = 0.0;
    has mesh_ms: float = 0.0;
    has worker_done: bool = False;
    has main_done: bool = False;

    def worker_cost() -> float {
        return self.parse_ms + self.emitter_ms;
    }

    def main_cost() -> float {
        return self.collision_ms + self.mesh_ms;
    }
}

node WorkerPool {
    has threads: int = 16;
}

node MainThread {
    has string_pool_locked: bool = True;
}

edge InDrainQueue {
    has order: int = 0;
}

edge NeedsStringPool {
}

walker PoolWorker {
    has parallel_ms: float = 0.0;
    has files_parsed: int = 0;

    can start with Root entry {
        visit [-->[?:WorkerPool]];
    }

    can parallelise with WorkerPool entry {
        print(f"[pool] {here.threads} threads absorb parse+emitters (cheap ~15-30%)");
        visit [->:InDrainQueue:->];
    }

    can parse_nif with NifAsset entry {
        if not here.worker_done {
            cost = here.worker_cost();
            self.parallel_ms += cost;
            self.files_parsed += 1;
            here.worker_done = True;
            print(f"[worker] {here.path}: {cost:.1f} ms");
        }
        visit [->:InDrainQueue:->] else { disengage; };
    }
}

walker FinishImports {
    has serial_ms: float = 0.0;
    has budget_units: int = 1;
    has drained: int = 0;

    can start with Root entry {
        visit [-->[?:MainThread]];
    }

    can gate with MainThread entry {
        if not here.string_pool_locked {
            disengage;
        }
        print("[MAIN] FinishImports drain — 1 import per budget unit (string_pool bound)");
        visit [->:InDrainQueue:->];
    }

    can drain_one with NifAsset entry {
        if not here.worker_done {
            disengage;
        }
        if here.main_done {
            visit [->:InDrainQueue:->] else { disengage; };
        }
        cost = here.main_cost();
        self.serial_ms += cost;
        self.drained += 1;
        here.main_done = True;
        phase = "mesh+collision" if here.mesh_ms > 0.0 else "collision summarize";
        print(f"[MAIN] {here.path} {phase} {cost:.1f} ms");
        disengage;
    }
}

with entry {
    pool = WorkerPool(threads=16);
    main = MainThread(string_pool_locked=True);
    root ++> pool;
    root ++> main;

    skyrim = NifAsset(
        path="Skyrim/meshes/armor.nif",
        parse_ms=84.8,
        emitter_ms=10.3,
        collision_ms=1.7,
        mesh_ms=260.2
    );
    fnv = NifAsset(
        path="FNV/meshes/rifle.nif",
        parse_ms=40.6,
        emitter_ms=10.0,
        collision_ms=2.0,
        mesh_ms=225.8
    );
    oblivion = NifAsset(
        path="Oblivion/meshes/crate.nif",
        parse_ms=57.2,
        emitter_ms=7.2,
        collision_ms=0.0,
        mesh_ms=128.0
    );

    pool +>:InDrainQueue(order=0):+> skyrim
        +>:InDrainQueue(order=1):+> fnv
        +>:InDrainQueue(order=2):+> oblivion;
    main +>:InDrainQueue(order=0):+> skyrim;

    skyrim +>:NeedsStringPool:+> main;
    fnv +>:NeedsStringPool:+> main;
    oblivion +>:NeedsStringPool:+> main;

    root spawn PoolWorker();

    root spawn FinishImports(budget_units=1);
    root spawn FinishImports(budget_units=1);
    root spawn FinishImports(budget_units=1);

    w_total = skyrim.worker_cost() + fnv.worker_cost() + oblivion.worker_cost();
    m_total = skyrim.main_cost() + fnv.main_cost() + oblivion.main_cost();
    all = w_total + m_total;
    w_pct = 100.0 * w_total / all;
    m_pct = 100.0 * m_total / all;
    print(f"per-NIF CPU: worker {w_pct:.1f}% | MAIN {m_pct:.1f}% — pool idle during mesh walk");
}

