"""Body HIR exception model: try/catch/finally regions, eval boundaries, defer LIFO cleanup, and ordinary vs exceptional CFG traversal."""

node HIRRegion {
    has label: str = "";
    has rid: int = 0;
}

node TryScope(HIRRegion) {
    has has_catch: bool = False;
    has has_finally: bool = False;
}

node EvalScope(HIRRegion) {
    has is_dynamic: bool = False;
}

node DeferStmt {
    has action: str = "";
    has seq: int = 0;
}

edge Nests { }
edge SuccNormal { }
edge SuccThrow { }
edge Defers { has register_order: int = 0; }
edge FinallyLink { }

walker CFGWalker {
    has visited: list[int] = [];
    has defer_stack: list[str] = [];
    has path: str = "ordinary";

    def run_defers(owner: str) {
        i = len(self.defer_stack) - 1;
        while i >= 0 {
            print(f"[DEFER/{owner}] {self.defer_stack[i]}");
            i -= 1;
        }
        self.defer_stack = [];
    }

    can launch with Root entry {
        mode = "EXCEPTIONAL" if self.path == "exceptional" else "ORDINARY";
        print(f"=== CFG walk ({mode}) ===");
        visit [->:Nests:->] else { visit [-->]; };
    }

    can open with HIRRegion entry {
        if here.rid in self.visited {
            print(f"[CYCLE-GUARD] block re-entry at {here.label}");
            disengage;
        }
        self.visited.append(here.rid);
        print(f"[REGION] {here.label}");
        visit [here->:Defers:->];
        if self.path == "exceptional" {
            visit [->:SuccThrow:->] else { visit [-->]; };
        } else {
            visit [->:SuccNormal:->] else { visit [-->]; };
        }
    }

    can tag_eval with EvalScope entry {
        boundary = "STRING_DYNAMIC" if here.is_dynamic else "BLOCK_PROTECTED";
        print(f"  [EVAL/{boundary}] {here.label}");
    }

    can register with DeferStmt entry {
        token = f"{here.action}#{here.seq}";
        self.defer_stack.append(token);
        print(f"  [REGISTER] defer {token}");
    }

    can close with HIRRegion exit {
        self.run_defers(here.label);
    }

    can close_try with TryScope exit {
        if here.has_finally {
            print(f"[FINALLY] {here.label}");
            visit [->:FinallyLink:->] else { disengage; };
        }
    }
}

with entry {
    outer = TryScope(
        label="outer_try",
        rid=1,
        has_catch=True,
        has_finally=True,
    );
    body = EvalScope(label="string_eval", rid=2, is_dynamic=True);
    stmt = HIRRegion(label="stmt", rid=3);
    catch_h = HIRRegion(label="catch_handler", rid=4);
    fin = HIRRegion(label="finally_block", rid=5);
    d1 = DeferStmt(action="log_close", seq=1);
    d2 = DeferStmt(action="flush_buf", seq=2);
    d3 = DeferStmt(action="localize_restore", seq=1);

    root +>:Nests:+> outer;
    outer +>:Defers(register_order=1):+> d1;
    outer +>:Defers(register_order=2):+> d2;
    outer +>:SuccNormal:+> body;
    outer +>:SuccThrow:+> catch_h;
    outer +>:FinallyLink:+> fin;
    body +>:Defers(register_order=1):+> d3;
    body +>:SuccNormal:+> stmt;

    root spawn CFGWalker(path="ordinary");
    root spawn CFGWalker(path="exceptional");
}

"""Proposal lifecycle: confirm, reject, and revise processing proposals without direct agent writes."""

node AgentGrant {
    has scope: str = "proposals_only";
}

node WriteTarget {
    has result_label: str = "";

    def perform_write() -> str {
        return "";
    }
}

node DatabaseTarget(WriteTarget) {
    has name: str = "";
    has item_count: int = 0;

    override def perform_write() -> str {
        self.item_count += 1;
        self.result_label = f"{self.name}#{self.item_count}";
        return f"db:{self.name}:{self.item_count}";
    }
}

node PageTarget(WriteTarget) {
    has title: str = "";
    has block_count: int = 0;

    override def perform_write() -> str {
        self.block_count += 1;
        self.result_label = f"{self.title}#{self.block_count}";
        return f"page:{self.title}:{self.block_count}";
    }
}

node Proposal {
    has proposal_id: str = "";
    has entity_kind: str = "database";
    has status: str = "processing";
    has result_item_id: str = "";
    has result_label: str = "";
    has locked: bool = False;
    has history: list[str] = [];
}

edge MayModify { has role: str = "agent"; }
edge ProposedFor { has linked_at: str = ""; }
edge Supersedes { has note: str = ""; }

walker GrantAuditor {
    has seen_ids: list[str] = [];

    can start with Root entry {
        visit [->:MayModify:->];
    }

    can audit_grant with AgentGrant entry {
        print(f"grant scope={here.scope} (proposals only, no destination writes)");
        visit [->:MayModify:->] else { visit [-->]; };
    }

    can audit_proposal with Proposal entry {
        if here.proposal_id in self.seen_ids {
            print(f"CYCLE guard: proposal chain revisits {here.proposal_id}");
            disengage;
            return;
        }
        self.seen_ids.append(here.proposal_id);
        print(f"agent may modify proposal {here.proposal_id} status={here.status}");
        visit [->:Supersedes:->] else { disengage; };
    }
}

walker ConfirmClerk {
    has sealing: bool = False;
    has draft_item_id: str = "";
    has draft_label: str = "";
    has destination_writes: int = 0;

    can confirm with Proposal entry {
        if here.locked and here.status == "confirmed" {
            print(f"CONFIRM idempotent {here.proposal_id} -> {here.result_item_id}");
            visit [->:Supersedes:->] else { disengage; };
            return;
        }
        if self.sealing {
            here.result_item_id = self.draft_item_id;
            here.result_label = self.draft_label;
            here.status = "confirmed";
            here.locked = True;
            print(f"CONFIRMED {here.proposal_id} -> {here.result_item_id} ({here.result_label})");
            self.sealing = False;
            self.draft_item_id = "";
            self.draft_label = "";
            visit [->:Supersedes:->] else { disengage; };
            return;
        }
        if here.status != "processing" or here.locked {
            print(f"CONFIRM blocked {here.proposal_id} status={here.status}");
            visit [->:Supersedes:->] else { disengage; };
            return;
        }
        self.sealing = True;
        visit [->:ProposedFor:->];
    }

    can execute with WriteTarget entry {
        self.draft_item_id = here.perform_write();
        self.draft_label = here.result_label;
        self.destination_writes += 1;
        visit [<-:ProposedFor:<-];
    }
}

walker RejectClerk {
    can reject with Proposal entry {
        if here.locked and here.status == "rejected" {
            print(f"REJECT idempotent {here.proposal_id}");
            visit [->:Supersedes:->] else { disengage; };
            return;
        }
        if here.status != "processing" or here.locked {
            print(f"REJECT blocked {here.proposal_id} status={here.status}");
            visit [->:Supersedes:->] else { disengage; };
            return;
        }
        here.status = "rejected";
        here.locked = True;
        print(f"REJECTED {here.proposal_id} (no destination write)");
        visit [->:Supersedes:->] else { disengage; };
    }
}

walker ReviseClerk {
    has message: str = "";
    has replacement_kind: str = "";

    can revise with Proposal entry {
        if here.locked {
            print(f"REVISE blocked locked {here.proposal_id}");
            visit [->:Supersedes:->] else { disengage; };
            return;
        }
        if here.status != "processing" {
            print(f"REVISE blocked {here.proposal_id} status={here.status}");
            visit [->:Supersedes:->] else { disengage; };
            return;
        }
        here.history.append(self.message);
        old_kind = here.entity_kind;
        new_kind = self.replacement_kind if self.replacement_kind != "" else here.entity_kind;
        here.entity_kind = new_kind;
        kind_note = f"{old_kind}->{new_kind}" if old_kind != new_kind else old_kind;
        print(f"REVISED {here.proposal_id} kind={kind_note} history+= \"{self.message}\"");
        visit [->:Supersedes:->] else { disengage; };
    }
}

