node VerificationHub {
    has label: str = "";
}

node BuildArtifact {
    has name: str = "";
    has ready: bool = False;
}

node AdHocCheck {
    has script_name: str = "";
    has migrated: bool = False;
}

node VitestCase {
    has test_file: str = "";
    has phase: int = 0;
}

edge RequiresBuild { }

edge ReplacedBy { }

walker MigrationAuditor {
    has pending: list[str] = [];
    has covered: list[str] = [];
    has build_ok: bool = False;

    can start with Root entry {
        print("Auditing Greplica check-script migration to Vitest");
        visit [-->];
