"""Body HIR exception model: try/catch/finally regions, eval boundaries, defer LIFO cleanup, and ordinary vs exceptional CFG traversal."""

node HIRRegion {
    has label: str = "";
    has rid: int = 0;
    has has_finally: bool = False;

    def entry_banner() -> str {
        return f"[REGION] {self.label}";
    }
}

node TryScope(HIRRegion) {
    has has_catch: bool = False;

    override def entry_banner() -> str {
        return f"[TRY] {self.label}";
    }
}

node EvalScope(HIRRegion) {
    has is_dynamic: bool = False;

    override def entry_banner() -> str {
        boundary = "STRING_DYNAMIC" if self.is_dynamic else "BLOCK_PROTECTED";
        return f"  [EVAL/{boundary}] {self.label}";
    }
}

node DeferStmt {
    has action: str = "";
    has seq: int = 0;
    has owner_rid: int = 0;
}

edge Nests { }
edge SuccNormal { }
edge SuccThrow { }
edge Defers { has register_order: int = 0; }
edge FinallyLink { }

walker CFGWalker {
    has visited: list[int] = [];
    has defer_stack: list[str] = [];
    has defer_owners: list[int] = [];
    has path: str = "ordinary";

    def run_defers_for(owner_rid: int) {
        pending = [];
        i = len(self.defer_owners) - 1;
        while i >= 0 {
            if self.defer_owners[i] == owner_rid {
                pending.append(self.defer_stack[i]);
                self.defer_owners.pop(i);
                self.defer_stack.pop(i);
            }
            i -= 1;
        }
        j = len(pending) - 1;
        while j >= 0 {
            print(f"[DEFER/{owner_rid}] {pending[j]}");
            j -= 1;
        }
    }

    can launch with Root entry {
        mode = "EXCEPTIONAL" if self.path == "exceptional" else "ORDINARY";
        print(f"=== CFG walk ({mode}) ===");
        visit [->:Nests:->] else { visit [-->] else { disengage; }; };
    }

    can open with HIRRegion entry {
        if here.rid in self.visited {
            print(f"[CYCLE-GUARD] block re-entry at {here.label}");
            visit [-->] else { disengage; };
        } else {
            self.visited.append(here.rid);
            print(here.entry_banner());
            visit [here->:Defers:->];
            if self.path == "exceptional" {
                visit [->:SuccThrow:->] else { visit [-->] else { disengage; }; };
            } else {
                visit [->:SuccNormal:->] else { visit [-->] else { disengage; }; };
            }
        }
    }

    can register with DeferStmt entry {
        token = f"{here.action}#{here.seq}";
        self.defer_stack.append(token);
        self.defer_owners.append(here.owner_rid);
        print(f"  [REGISTER] defer {token}");
        visit [-->] else { disengage; };
    }

    can leave with HIRRegion exit {
        if here.has_finally {
            print(f"[FINALLY] {here.label}");
            visit [->:FinallyLink:->] else { visit [-->] else { disengage; }; };
        }
        self.run_defers_for(here.rid);
        visit [-->] else { disengage; };
    }
}

with entry {
    outer = TryScope(
        label="outer_try",
        rid=1,
        has_catch=True,
        has_finally=True,
    );
    body = EvalScope(label="string_eval", rid=2, is_dynamic=True);
    stmt = HIRRegion(label="stmt", rid=3);
    catch_h = HIRRegion(label="catch_handler", rid=4);
    fin = HIRRegion(label="finally_block", rid=5);
    d1 = DeferStmt(action="log_close", seq=1, owner_rid=1);
    d2 = DeferStmt(action="flush_buf", seq=2, owner_rid=1);
    d3 = DeferStmt(action="localize_restore", seq=1, owner_rid=2);

    root +>:Nests:+> outer;
    outer +>:Defers(register_order=1):+> d1;
    outer +>:Defers(register_order=2):+> d2;
    outer +>:SuccNormal:+> body;
    outer +>:SuccThrow:+> catch_h;
    outer +>:FinallyLink:+> fin;
    body +>:Defers(register_order=1):+> d3;
    body +>:SuccNormal:+> stmt;

    root spawn CFGWalker(path="ordinary");
    root spawn CFGWalker(path="exceptional");
}

"""Source provenance manifest and deterministic attribution gate audit.

Models manifest artifacts, audit findings, and reviewed baselines as a
native graph. A gate walker traverses the manifest chain, enforces cycle
guards on lineage hops, compares evidence hashes against baselines, and
fails closed on unreviewed vendoring or open similarity findings.
"""

node ProvenanceEntry {
    has title: str = "";
    has path: str = "";
    has year: int = 0;
    has available: bool = True;

    def review_status() -> str {
        return "unknown";
    }
}

node SourceArtifact(ProvenanceEntry) {
    has classification: str = "";
    has evidence_hash: str = "";
    has origin_url: str = "";
    has license_name: str = "";
    has reviewer: str = "";
    has last_reviewed: int = 0;

    override def review_status() -> str {
        return "reviewed" if self.reviewer else "unreviewed";
    }
}

node AuditFinding(ProvenanceEntry) {
    has kind: str = "";
    has reviewed: bool = False;
    has severity: str = "fail";

    override def review_status() -> str {
        return "cleared" if self.reviewed else "open";
    }
}

node BaselineRecord(ProvenanceEntry) {
    has symbol: str = "";
    has evidence_hash: str = "";
    has reviewer: str = "";

    override def review_status() -> str {
        return f"baseline:{self.reviewer}";
    }
}

edge InManifest { }
edge Flags { has reason: str = ""; }
edge DerivedFrom { has revision: str = ""; }
edge MatchesBaseline { }

walker AttributionGate {
    has visited_paths: list[str] = [];
    has gate_passed: bool = True;
    has checked: int = 0;
    has open_findings: int = 0;
    has current_path: str = "";
    has current_hash: str = "";

    can start with Root entry {
        print("=== Provenance Attribution Gate (offline t0) ===");
        visit [->:InManifest:->] else { disengage; };
    }

    can walk_manifest with SourceArtifact entry {
        if here.path in self.visited_paths {
            print(f"CYCLE guard: skip re-visit {here.path}");
            disengage;
        }
        self.visited_paths.append(here.path);
        self.checked += 1;
        print(
            f"[{here.classification}] {here.path} "
            f"({here.review_status()}) hash={here.evidence_hash}"
        );
        if here.classification != "first_party" and here.reviewer == "" {
            self.gate_passed = False;
            print(f"  FAIL: unreviewed {here.classification} at {here.path}");
        }
        self.current_path = here.path;
        self.current_hash = here.evidence_hash;
        visit [->:Flags:->];
        visit [->:MatchesBaseline:->];
        visit [->:DerivedFrom:->];
        visit [->:InManifest:->] else { disengage; };
    }

    can inspect with AuditFinding | BaselineRecord entry {
        if here is AuditFinding {
            if here.review_status() == "open" {
                self.gate_passed = False;
                self.open_findings += 1;
                print(
                    f"  FAIL: {here.kind} — {here.title} at {here.path}"
                );
            }
        } elif here is BaselineRecord {
            if here.evidence_hash != self.current_hash {
                self.gate_passed = False;
                print(
                    f"  FAIL: generator drift at {self.current_path} "
                    f"(baseline {here.evidence_hash} "
                    f"!= manifest {self.current_hash})"
                );
            } else {
                print(f"  OK: baseline matches {self.current_path}");
            }
        }
        visit [-->];
    }

    can check_lineage with SourceArtifact entry {
        print(
            f"  lineage hop -> {here.path} "
            f"(rev from parent scope)"
        );
        if here.path in self.visited_paths {
            disengage;
        }
        self.visited_paths.append(here.path);
        visit [->:DerivedFrom:->] else { disengage; };
    }

    can summarize with Root exit {
        verdict = "PASS" if self.gate_passed else "FAIL";
        print(
            f"--- Gate {verdict}: checked {self.checked} artifacts, "
            f"{self.open_findings} open findings ---"
        );
    }
}

