"""Min/latest dependency checks: PyPI JSON API vs Azure DevOps Artifacts feed resolution."""

node Registry {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has name: str = "";
    has filters_python: bool = True;
}

node Package {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has name: str = "";
}

node Release {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has version: str = "";
    has requires_python: str = "";
    has yanked: bool = False;
    has feed_cached: bool = False;
    has deleted: bool = False;
}

edge Hosts { }
edge Publishes { }
edge Requires { }

walker LatestDependency {
    has registry: str = "";
    has pkg_name: str = "";
    has best_order: int = 0;
    has best_version: str = "";

    can start with Root entry {
        print("--- latestdependency ---");
        visit [-->];
    }

    can on_registry with Registry entry {
        self.registry = here.name;
        filter_msg = "on" if here.filters_python else "DROPPED";
        print(f"[{here.name}] enumerate versions (python-filter {filter_msg})");
        visit [->:Hosts:->];
    }

    can on_package with Package entry {
        self.pkg_name = here.name;
        self.best_order = 0;
        self.best_version = "";
        visit [->:Publishes:->];
        suffix = "";
        if self.registry == "azdo" and self.pkg_name == "azure-core" and self.best_version == "1.40.0" {
            suffix = "  # stale: PyPI released 1.41.0 but feed cache stops at 1.40.0";
        }
        if self.registry == "azdo" and self.pkg_name == "requests" and self.best_version == "2.32.1" {
            suffix = "  # yanked on PyPI but still listed in feed";
        }
        print(f"  {self.pkg_name} latest -> {self.best_version}{suffix}");
    }

    can consider with Release entry {
        ok = True;
        if here.deleted {
            ok = False;
        }
        if self.registry == "azdo" and not here.feed_cached {
            ok = False;
        }
        if self.registry == "pypi" and here.yanked {
            ok = False;
        }
        if ok and here.year > self.best_order {
            self.best_order = here.year;
            self.best_version = here.version;
        }
        visit [->:Publishes:->];
    }
}

walker MinDependency {
    has registry: str = "";
    has filter_python: bool = True;
    has python_minor: int = 11;
    has pkg_name: str = "";
    has best_order: int = 999999;
    has best_version: str = "";

    can start with Root entry {
        print("--- mindependency ---");
        visit [-->];
    }

    can on_registry with Registry entry {
        self.registry = here.name;
        self.filter_python = here.filters_python;
        filter_msg = "on" if here.filters_python else "DROPPED";
        print(f"[{here.name}] resolve minimum (python-filter {filter_msg})");
        visit [->:Hosts:->];
    }

    can on_package with Package entry {
        self.pkg_name = here.name;
        self.best_order = 999999;
        self.best_version = "";
        visit [->:Publishes:->];
        if self.pkg_name == "typing-extensions" and self.best_version != "" {
            warn = "";
            if not self.filter_python and self.best_version == "4.12.0" {
                warn = "  # incompatible minimum selected: requires >=3.12 on Python 3.11";
            }
            print(f"  {self.pkg_name} min -> {self.best_version}{warn}");
        }
    }

    can consider with Release entry {
        ok = True;
        if here.deleted {
            ok = False;
        }
        if self.registry == "azdo" and not here.feed_cached {
            ok = False;
        }
        if self.registry == "pypi" and here.yanked {
            ok = False;
        }
        if ok and self.filter_python and here.requires_python == ">=3.12" and self.python_minor < 12 {
            ok = False;
        }
        if ok and here.year < self.best_order {
            self.best_order = here.year;
            self.best_version = here.version;
        }
        visit [->:Publishes:->];
    }
}

walker RequiresDist {
    has python_minor: int = 11;
    has filter_python: bool = False;
    has seen: list[str] = [];
    has dep_name: str = "";
    has best_order: int = 999999;
    has chosen: str = "";

    can start with Release entry {
        print(f"--- requires_dist walk from {here.version} (python-filter {'on' if self.filter_python else 'DROPPED'}) ---");
        visit [->:Requires:->] else { disengage; };
    }

    can resolve_pkg with Package entry {
        if here.name in self.seen {
            print(f"  cycle guard: blocked re-entry to {here.name}");
            disengage;
        }
        self.seen.append(here.name);
        self.dep_name = here.name;
        self.best_order = 999999;
        self.chosen = "";
        visit [->:Publishes:->];
        note = "";
        if not self.filter_python and self.chosen == "4.12.0" {
            note = "  # feed backend skipped requires_python filtering";
        }
        print(f"  requires {self.dep_name} -> min {self.chosen}{note}");
        visit [->:Requires:->] else { };
    }

    can pick with Release entry {
        ok = True;
        if here.deleted {
            ok = False;
        }
        if not here.feed_cached {
            ok = False;
        }
        if self.filter_python and here.requires_python == ">=3.12" and self.python_minor < 12 {
            ok = False;
        }
        if ok and here.year < self.best_order {
            self.best_order = here.year;
            self.chosen = here.version;
        }
        visit [->:Publishes:->];
    }
}

