"""Templates and Recurring converge: one operator portal, two flows, safe graph walks."""

node Template {
    has name: str = "";
    has revision: int = 0;
    has available: bool = True;
}

node Card {
    has title: str = "";
    has applied_revision: int = 0;
    has needs_update: bool = False;
    has available: bool = True;
}

node RecurringSchedule {
    has name: str = "";
    has active: bool = True;
    has dirty: bool = False;
    has validation_ok: bool = True;
}

node Task {
    has title: str = "";
    has status: str = "pending";
    has available: bool = True;
}

edge PortalSection {
    has area: str = "";
}

edge ProjectedFrom {
    has stale: bool = False;
}

edge Generates { }

walker OperatorAuditor {
    has templates_seen: int = 0;
    has schedules_seen: int = 0;
    has stale_cards: int = 0;
    has tasks_seen: int = 0;

    can start with Root entry {
        print("=== Converged operator audit: Templates + Recurring ===");
        visit [->:PortalSection:->] else { disengage; };
    }

    can browse_templates with Template entry {
        self.templates_seen += 1;
        access = "read-only" if here.available else "locked";
        print(f"[Templates] {here.name} ({access}, revision {here.revision})");
        visit [->:ProjectedFrom:->] else { disengage; };
    }

    can browse_recurring with RecurringSchedule entry {
        self.schedules_seen += 1;
        mode = "Active" if here.active else "Paused";
        dirty_note = ", dirty" if here.dirty else "";
        print(f"[Recurring] {here.name} ({mode}{dirty_note})");
        if here.dirty and not here.validation_ok {
            print("  -> save blocked: fix validation or discard changes");
            disengage;
        }
        visit [->:Generates:->] else { disengage; };
    }

    can inspect_card with Card entry {
        if here.needs_update {
            self.stale_cards += 1;
            lag = "unapplied" if here.applied_revision == 0 else "behind";
            print(f"  [Card] {here.title} {lag} (applied rev {here.applied_revision})");
        } else {
            print(f"  [Card] {here.title} current");
        }
    }

    can inspect_task with Task entry {
        self.tasks_seen += 1;
        phase = here.status if here.available else "unavailable";
        print(f"  [Task] {here.title} ({phase})");
    }
}

walker TemplateApplier {
    has target_revision: int = 0;
    has applied: int = 0;
    has conflicts: int = 0;

    can start with Root entry {
        print("=== Template batch apply preview ===");
        visit [->:PortalSection:->] else { disengage; };
    }

    can skip_recurring with RecurringSchedule entry {
        disengage;
    }

    can preview with Template entry {
        self.target_revision = here.revision;
        print(f"Preview apply '{here.name}' -> revision {here.revision}");
        visit [->:ProjectedFrom:->] else { disengage; };
    }

    can apply_to with Card entry {
        if here.applied_revision >= self.target_revision {
            self.conflicts += 1;
            print(f"  CONFLICT: '{here.title}' already at rev {here.applied_revision}");
        } else {
            here.applied_revision = self.target_revision;
            here.needs_update = False;
            self.applied += 1;
            print(f"  APPLIED: '{here.title}' now revision {self.target_revision}");
        }
    }
}

with entry {
    etl = Template(name="ETL Pipeline", revision=3);
    daily = RecurringSchedule(name="Nightly Sync", active=True);
    paused = RecurringSchedule(
        name="Weekly Report",
