"""Renderer draw hot path: per-frame GpuInstance loop resolves albedo and alpha via dense texture-index edges instead of HashMap probes."""

node TextureRegistry {
    has name: str = "gpu_textures";
}

node TextureEntry {
    has handle: int = 0;
    has path: str = "";
    has has_alpha: bool = False;
    has avg_r: float = 0.0;
    has avg_g: float = 0.0;
    has avg_b: float = 0.0;
}

node DrawCommand {
    has cmd_id: int = 0;
    has is_alpha_blend: bool = False;
    has fallback_r: float = 0.5;
    has fallback_g: float = 0.5;
    has fallback_b: float = 0.5;
}

edge Registered { }
edge UsesTexture { }

walker LoadRegistrar {
    can start with Root entry {
        visit [-->];
    }

    can open_registry with TextureRegistry entry {
        print(f"registry '{here.name}': stamping dense handles");
        visit [->:Registered:->];
    }

    can stamp with TextureEntry entry {
        print(f"  load handle={here.handle} path={here.path} "
              f"alpha={here.has_alpha} rgb=({here.avg_r},{here.avg_g},{here.avg_b})");
    }
}

walker FrameDrawer {
    has frame_id: int = 0;
    has draws: int = 0;
    has rgb_probes: int = 0;
    has alpha_probes: int = 0;
    has current_blend: bool = False;

    can start with DrawCommand entry {
        print(f"--- frame {self.frame_id}: draw-command loop ---");
        self.draws += 1;
        self.current_blend = here.is_alpha_blend;
        visit [->:UsesTexture:->] else {
            print(f"  cmd {here.cmd_id}: texture miss -> "
                  f"fallback ({here.fallback_r},{here.fallback_g},{here.fallback_b})");
        };
        visit [-->];
    }

    can step with DrawCommand entry {
        self.draws += 1;
        self.current_blend = here.is_alpha_blend;
        visit [->:UsesTexture:->] else {
            print(f"  cmd {here.cmd_id}: texture miss -> "
                  f"fallback ({here.fallback_r},{here.fallback_g},{here.fallback_b})");
        };
        visit [-->];
    }

    can resolve_rgb with TextureEntry entry {
        self.rgb_probes += 1;
        albedo_r = here.avg_r;
        albedo_g = here.avg_g;
        albedo_b = here.avg_b;
        blend_tag = "";
        if self.current_blend {
            self.alpha_probes += 1;
            blend_tag = " [alpha-blend]" if here.has_alpha else " [opaque]";
        }
        print(f"  handle {here.handle} albedo=({albedo_r},{albedo_g},{albedo_b}){blend_tag}");
    }
}

