}

"""Source-backed company knowledge: ACL-scoped retrieval and dependency invalidation."""

edge AuthorizedFor {
    has active: bool = True;
}

edge SourcedFrom {
    has ingested_at: str = "";
}

edge Summarizes {
    has weight: float = 1.0;
}

node Actor {
    has name: str = "";
    has office: str = "";
    has clearance: str = "public";
}

node KnowledgeSource {
    has source_id: str = "";
    has title: str = "";
    has acl_level: str = "public";
    has revision: str = "";
    has deleted: bool = False;
}

node Evidence {
    has claim: str = "";
    has location: str = "";
    has revision_hash: str = "";
    has freshness: str = "current";
    has ingestion_state: str = "indexed";
    has citation_span: str = "";
}

node DerivedSummary {
    has summary: str = "";
    has invalidated: bool = False;
}

walker Retriever {
    has actor_name: str = "";
    has actor_clearance: str = "public";
    has citation_count: int = 0;

    def clearance_allows(actor_level: str, source_level: str) -> bool {
        actor_rank = 0;
        source_rank = 0;
        for (i, lvl) in enumerate(["public", "internal", "restricted"]) {
            if lvl == actor_level {
                actor_rank = i;
            }
            if lvl == source_level {
                source_rank = i;
            }
        }
        return actor_rank >= source_rank;
    }

    def evidence_eligible(ev: Evidence) -> bool {
        if ev.ingestion_state != "indexed" {
            return False;
        }
        if ev.freshness != "current" {
            return False;
        }
        return True;
    }

    can start with Root entry {
        visit [-->];
    }

    can begin with Actor entry {
        if here.name == self.actor_name {
            self.actor_clearance = here.clearance;
            print(
                f"Actor {here.name} ({here.office}, {here.clearance}) "
                f"entering authorized source scope"
            );
            visit [->:AuthorizedFor:->] else { disengage; };
        } else {
            visit [-->];
        }
    }

    can scope with KnowledgeSource entry {
        if here.deleted {
            print(f"  [SKIP] deleted source: {here.title}");
            visit [->:AuthorizedFor:->] else { disengage; };
        } else {
            if not self.clearance_allows(self.actor_clearance, here.acl_level) {
                print(
                    f"  [DENIED] {here.title} "
                    f"(requires {here.acl_level}, actor {self.actor_clearance})"
                );
                visit [->:AuthorizedFor:->] else { disengage; };
            } else {
                print(f"  [AUTHORIZED] {here.title} revision={here.revision}");
                visit [->:SourcedFrom:->];
                visit [->:AuthorizedFor:->] else { disengage; };
            }
        }
    }

    can cite with Evidence entry {
        if self.evidence_eligible(here) {
            label = (
                f"{here.claim} @ {here.location} "
                f"[{here.citation_span}, hash={here.revision_hash}]"
            );
            self.citation_count += 1;
            print(f"    [ELIGIBLE] {label}");
            visit [->:Summarizes:->];
        } else {
            status = (
                "partial-index"
                if here.ingestion_state != "indexed"
                else "stale"
            );
            print(f"    [INELIGIBLE:{status}] {here.claim}");
        }
    }

    can include_derived with DerivedSummary entry {
        if here.invalidated {
            print(f"    [DERIVED:DISCARDED] {here.summary}");
        } else {
            print(f"    [DERIVED] {here.summary}");
        }
        disengage;
    }
}

walker Invalidator {
    has target_source_id: str = "";
    has new_revision: str = "";
    has stale_evidence: int = 0;
    has stale_summaries: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can pass_actor with Actor entry {
        visit [-->];
    }

    can reconcile with KnowledgeSource entry {
        if here.source_id == self.target_source_id {
            here.revision = self.new_revision;
            print(
                f"Reconciling {here.title} -> revision {self.new_revision}; "
                f"invalidating dependent evidence and summaries"
            );
            visit [->:SourcedFrom:->];
            visit [-->];
        } else {
            visit [-->];
        }
    }

    can invalidate_evidence with Evidence entry {
        here.freshness = "stale";
        self.stale_evidence += 1;
        print(f"  Evidence stale: {here.claim}");
        visit [->:Summarizes:->];
    }

    can invalidate_summary with DerivedSummary entry {
        here.invalidated = True;
        self.stale_summaries += 1;
        print(f"  Summary invalidated: {here.summary}");
        disengage;
    }
}

