"""Transitive skill dependencies: recursively resolve nested ai.json skills into a flat lock, deduplicated by (git, commit, path), with cycle and version-conflict guards."""

node Manifest {
    has title: str = "";
}

node Skill {
    has name: str = "";
    has git: str = "";
    has commit: str = "";
    has path: str = "";

    def pin_key() -> str {
        return f"{self.git}@{self.commit}:{self.path}";
    }

    def repo_path_key() -> str {
        return f"{self.git}:{self.path}";
    }
}

edge ListedIn { }

edge DependsOn {
    has spec: str = "";
}

walker DependencyResolver {
    has resolving: list[str] = [];
    has resolved: list[str] = [];
    has lock: list[str] = [];
    has cycles: list[str] = [];
    has conflicts: list[str] = [];
    has pin_keys: list[str] = [];
    has pin_commits: list[str] = [];

    def in_list(needle: str, haystack: list[str]) -> bool {
        for item in haystack {
            if item == needle {
                return True;
            }
        }
        return False;
    }

    def push_resolving(key: str) -> None {
        self.resolving.append(key);
    }

    def pop_resolving(key: str) -> None {
        kept = [];
        for k in self.resolving {
            if k != key {
                kept.append(k);
            }
        }
        self.resolving = kept;
    }

    def record_pin(skill: Skill) -> None {
        ck = skill.repo_path_key();
        for (i, pk) in enumerate(self.pin_keys) {
            if pk == ck {
                if self.pin_commits[i] != skill.commit {
                    self.conflicts.append(
                        f"{ck}: locked {self.pin_commits[i]} vs wants {skill.commit}"
                    );
                }
                return;
            }
        }
        self.pin_keys.append(ck);
        self.pin_commits.append(skill.commit);
    }

    can start with Root entry {
        print("spm resolve: walking manifest and transitive ai.json skills");
        visit [-->];
        print("--- ai.lock (flat, deduped by git@commit:path) ---");
        for line in self.lock {
            print(line);
        }
        if len(self.cycles) > 0 {
            print("cycle guards tripped:");
            for msg in self.cycles {
                print(f"  ! {msg}");
            }
        }
        if len(self.conflicts) > 0 {
            print("version conflicts (error-on-conflict):");
            for msg in self.conflicts {
                print(f"  ! {msg}");
            }
        }
    }

    can open with Manifest entry {
        print(f"manifest: {here.title}");
        visit [->:ListedIn:->] else { visit [-->]; };
    }

    can resolve with Skill entry {
        key = here.pin_key();

        if self.in_list(key, self.resolved) {
            disengage;
        }
        if self.in_list(key, self.resolving) {
            self.cycles.append(f"cycle at {here.name} ({key})");
            disengage;
        }

        self.push_resolving(key);
        self.record_pin(here);

        visit [->:DependsOn:->] else { };

        lock_line = f"  {here.name}: {key}";
        self.lock.append(lock_line);
        self.resolved.append(key);
        self.pop_resolving(key);

        visit [-->];
    }
}

