    utils = Skill(
        name="common-utils",
        git="https://git.example/common-utils",
        commit="ddd111",
        path="/"
    );
    lint = Skill(
        name="linting",
        git="https://git.example/linting",
        commit="bbb222",
        path="/skills/lint"
    );
    test = Skill(
