walker SynchronizedVerifier {
    has candidate_proven: bool = False;
    has blocker_found: bool = False;
    has delivered_count: int = 0;
    has sessions_closed: int = 0;
    has evidence_gaps: int = 0;
    has visited_titles: list[str] = [];

    can start with Root entry {
        print("=== Pre-execution Sannux consumer verification ===");
        visit [-->[?:Candidate]] else {
            self.blocker_found = True;
            self.evidence_gaps += 1;
            print("BLOCKER: no candidate reachable before execution");
            disengage;
        };
        if self.blocker_found {
            disengage;
        }
        visit [-->[?:VerificationTicket]] else {
            disengage;
        };
        verdict = "BLOCKED" if self.blocker_found else "PASSED";
        print(
            f"=== Evidence report: {verdict} | delivered={self.delivered_count} "
            f"closed_sessions={self.sessions_closed} gaps={self.evidence_gaps} ==="
        );
    }

    can prove_candidate with Candidate entry {
        if not here.proven or here.safe_hash == "" {
            self.blocker_found = True;
            self.evidence_gaps += 1;
            print(f"BLOCKER: candidate identity unproven ({here.title})");
            disengage;
        }
        self.candidate_proven = True;
        print(f"Candidate proven: commit={here.source_commit} hash={here.safe_hash}");
        visit [->:SyncsTo:->] else {
            self.blocker_found = True;
            self.evidence_gaps += 1;
            print("BLOCKER: candidate has no consumer snapshot destination");
            disengage;
        };
    }

    can verify_snapshot with Consumer entry {
        if here.snapshot_hash == "" {
            self.blocker_found = True;
            self.evidence_gaps += 1;
            print(f"BLOCKER: consumer {here.name} missing snapshot hash");
            disengage;
        }
        here.synced = True;
        print(f"Snapshot synchronized to consumer {here.name} ({here.snapshot_hash})");
        visit [-->] else { disengage; };
    }

    can run_ticket with VerificationTicket entry {
        if self.blocker_found {
            disengage;
        }
        if here.title in self.visited_titles {
            self.blocker_found = True;
            self.evidence_gaps += 1;
            print(f"BLOCKER: dependency cycle detected at {here.title}");
            disengage;
        }
        self.visited_titles.append(here.title);
        if not self.candidate_proven {
            self.blocker_found = True;
            self.evidence_gaps += 1;
            print(f"BLOCKER: ticket {here.title} blocked — candidate not proven pre-execution");
            disengage;
        }
        if here.status == "delivered" {
            visit [-->];
        } else {
            if here.status == "cancellation_fixture" {
                cancel_label = "confirmed" if here.disposable else "rejected";
                print(f"Matching cancellation {cancel_label}: {here.title}");
                visit [-->] else { disengage; };
            } else {
                visit [->:DependsOn:->] else {
                    if not here.disposable {
                        self.blocker_found = True;
                        self.evidence_gaps += 1;
                        print(f"BLOCKER: ticket {here.title} is not disposable-safe");
                        disengage;
                    }
                    here.status = "delivered";
                    self.delivered_count += 1;
                    stage_label = here.stage if here.stage != "" else "unknown";
                    print(f"Ticket delivered [{stage_label}]: {here.title}");
                    visit [->:NestedCall:->] else {
                        visit [-->];
                    };
                };
            }
        }
    }

    can fulfill_prerequisite with VerificationTicket entry {
        if here.status != "delivered" {
            visit [->:DependsOn:->] else {
                if not here.disposable {
                    self.blocker_found = True;
                    self.evidence_gaps += 1;
                    print(f"BLOCKER: prerequisite {here.title} not disposable-safe");
                    disengage;
                }
                here.status = "delivered";
                self.delivered_count += 1;
                print(f"Prerequisite delivered [{here.stage}]: {here.title}");
                visit [-->] else { disengage; };
            };
        } else {
            visit [-->] else { disengage; };
        }
    }

    can close_pi_session with PiSession entry {
        if here.managed and not here.closed {
            here.closed = True;
            self.sessions_closed += 1;
            role_label = here.role if here.role != "" else "pi";
            print(f"Closed managed {role_label} session: {here.title} (no orphan)");
        }
        visit [-->] else { disengage; };
    }
}

