walker PublicationIntegrator {
    has reconciled: int = 0;
    has blocked: bool = False;
    has evidence_bound: int = 0;
    has visited_keys: list[str] = [];

    can start with Root entry {
        print("ORION-04 publication integration: dependency gate then claim reconciliation");
        visit [-->];
    }

    can gate_dependency with Issue entry {
        if not here.merged {
            print(f"BLOCKED: issue #{here.number} not merged — cannot integrate");
            self.blocked = True;
            disengage;
        }
        print(f"dependency satisfied: #{here.number} {here.title}");
        visit [-->];
    }

    can read_evidence with EvidencePacket entry {
        if here.admitted {
            if here.support_bound > self.evidence_bound {
                self.evidence_bound = here.support_bound;
            }
            print(f"admitted evidence: {here.packet_name} → support>={here.support_bound}");
        } else {
            print(f"excluded from theorem authority: {here.packet_name} (support>={here.support_bound})");
        }
        visit [-->];
    }

    can audit_manuscript with Manuscript entry {
        print(f"auditing {here.version}: header support>={here.support_stated}, frontier {here.frontier_stated}");
        visit [->:SupportedBy:->];
        if here.support_stated < self.evidence_bound {
            here.support_stated = self.evidence_bound;
            if here.frontier_stated == "M1-M3" {
                here.frontier_stated = "M1-M4";
            }
            print(f"  header updated → support>={here.support_stated}, {here.frontier_stated}");
        }
        visit [->:Contains:->] else {
            visit [-->];
        }
    }

    can reconcile with Claim entry {
        key = here.title;
        if key in self.visited_keys {
            disengage;
        }
        self.visited_keys.append(key);
        visit [->:GroundedIn:->];
        if self.blocked or self.evidence_bound == 0 {
            disengage;
        }
        old_support = here.support_min;
        if old_support < self.evidence_bound {
            here.support_min = self.evidence_bound;
            here.status = "SUPPORTED_INTERNAL";
            if here.frontier == "M1-M3" {
                here.frontier = "M1-M4";
            }
            self.reconciled += 1;
            print(f"  RECONCILED [{here.title}]: >={old_support} → >={here.support_min}, {here.frontier}");
        } else {
            print(f"  OK [{here.title}]: >={here.support_min} [{here.status}]");
        }
        visit [-->];
    }
}

