"""Bounded-range VLP: finite hop ranges expand as UNION ALL of flat join chains, not recursive CTE."""

node User {
    has name: str = "";
}

node Network {
    has label: str = "social";
}

node QuerySpec {
    has min_hops: int = 1;
    has max_hops: int = 0;
    has rel_label: str = "FOLLOWS";
}

edge Follows { }

walker RangePlanner {
    can start with Root entry {
        visit [-->];
    }

    can plan with QuerySpec entry {
        label = here.rel_label;
        if here.max_hops > 0 and here.max_hops >= here.min_hops {
            if here.min_hops == here.max_hops {
                print(f"PLAN {label}*{here.min_hops} -> flat INNER JOIN chain (no WITH RECURSIVE)");
                root spawn FixedHopWalker(k=here.min_hops);
            } else {
                print(f"PLAN {label}*{here.min_hops}..{here.max_hops} -> UNION ALL of flat chains (no WITH RECURSIVE)");
                for k in range(here.min_hops, here.max_hops + 1) {
                    root spawn FixedHopWalker(k=k);
                }
            }
        } else {
            print(f"PLAN {label}*{here.min_hops}.. -> WITH RECURSIVE fixpoint (unbounded range)");
            root spawn RecursiveReachability(min_hops=here.min_hops);
        }
        visit [-->];
    }
}

walker FixedHopWalker {
    has k: int = 1;
    has depth: int = 0;
    has trail: list[str] = [];
    has on_path: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can enter_graph with Network entry {
        visit [-->];
    }

    can chain with User entry {
        if self.depth > 0 and here.name in self.on_path {
            disengage;
        }
        if self.depth == 0 {
            self.trail = [here.name];
            self.on_path = [here.name];
        } else {
            self.trail.append(here.name);
            self.on_path.append(here.name);
        }
        if self.depth == self.k {
            line = " -> ".join(self.trail);
            print(f"  [chain k={self.k}] {line}");
            disengage;
        }
        self.depth += 1;
        visit [->:Follows:->] else { disengage; };
    }
}

walker RecursiveReachability {
    has min_hops: int = 1;
    has depth: int = 0;
    has trail: list[str] = [];
    has on_path: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can enter_graph with Network entry {
        visit [-->];
    }

    can fixpoint with User entry {
        if self.depth > 0 and here.name in self.on_path {
            disengage;
        }
        if self.depth == 0 {
            self.trail = [here.name];
            self.on_path = [here.name];
        } else {
            self.trail.append(here.name);
            self.on_path.append(here.name);
        }
        hops = self.depth;
        if hops >= self.min_hops {
            line = " -> ".join(self.trail);
            print(f"  [recursive CTE hop={hops}] {line}");
        }
        self.depth += 1;
        visit [->:Follows:->] else { disengage; };
    }
}

with entry {
    alice = User(name="alice");
    bob = User(name="bob");
    carol = User(name="carol");
    dave = User(name="dave");

    net = Network(label="social_benchmark");
    root ++> net ++> alice;
    alice +>:Follows:+> bob;
    bob +>:Follows:+> carol;
    carol +>:Follows:+> dave;
    bob +>:Follows:+> alice;

    bounded = QuerySpec(min_hops=1, max_hops=3, rel_label="FOLLOWS");
    exact = QuerySpec(min_hops=3, max_hops=3, rel_label="FOLLOWS");
    unbounded = QuerySpec(min_hops=1, max_hops=0, rel_label="FOLLOWS");

    root ++> bounded ++> exact ++> unbounded;

    root spawn RangePlanner();
}

"""DuckDB #25074: VariantVisitor unbounded VARIANT nesting traversal.

Models deeply nested VARIANT values built by repeated one-element LIST wraps
(e.g. recursive CTE [v]::VARIANT) and VariantVisitor::Visit dispatching to
VisitArray/VisitScalar with no depth cap — stack overflow at ~3500 levels.
"""

node VariantValue {
    has depth: int = 0;
}

node VariantScalar(VariantValue) {
    has value: int = 0;
}

node VariantArray(VariantValue) {
    has element_count: int = 1;
}

edge Contains { }

walker VariantVisitor {
    has max_depth: int = 0;
    has visit_depth: int = 0;
    has nodes_seen: int = 0;

    can start with Root entry {
        print(f"VariantVisitor::Visit() max_depth={self.max_depth} (0=unbounded)");
        visit [-->];
    }

    can visit with VariantArray | VariantScalar entry {
        self.visit_depth += 1;
        self.nodes_seen += 1;
        kind = "Array" if here is VariantArray else "Scalar";
        print(f"VariantVisitor::Visit{kind}() call_depth={self.visit_depth} nesting={here.depth}");

        if self.max_depth > 0 and self.visit_depth > self.max_depth {
            print(f"ABORT depth={self.visit_depth}: unbounded recursion risks stack overflow (#25074)");
            self.visit_depth -= 1;
            disengage;
        }

        if here is VariantArray {
            visit [->:Contains:->] else {
                self.visit_depth -= 1;
                disengage;
            }
        }
        self.visit_depth -= 1;
    }
}

with entry {
    leaf = VariantScalar(value=1, depth=0);
    top = leaf;
    for d in range(1, 16) {
        wrapper = VariantArray(depth=d, element_count=1);
        wrapper +>:Contains:+> top;
        top = wrapper;
    }
    root ++> top;

    unbounded = VariantVisitor(max_depth=0);
    root spawn unbounded;
    print(f"unbounded visitor finished: {unbounded.nodes_seen} nodes traversed");

    bounded = VariantVisitor(max_depth=5);
    root spawn bounded;
    print(f"bounded visitor finished: {bounded.nodes_seen} nodes before depth cap");
}

