"""Block tag inheritance: materialize ancestor tags on descendants and query with include_inherited."""

node Block {
    has title: str = "";
    has available: bool = True;
}

node Tag {
    has name: str = "";
}

edge ParentOf { }
edge DirectTag { }
edge InheritedTag { has from_title: str = ""; }

walker InheritancePropagator {
    has carry_tags: list = [];
    has carry_sources: list = [];

    can start with Root entry {
        print("== materialize block_tag_inherited cache ==");
        self.carry_tags = [];
        self.carry_sources = [];
        visit [-->];
    }

    can propagate with Block entry {
        if not here.available {
            disengage;
        }
        idx = 0;
        while idx < len(self.carry_tags) {
            tg = self.carry_tags[idx];
            src = self.carry_sources[idx];
            here +>:InheritedTag(from_title=src):+> tg;
            print(f"  [{here.title}] inherits '{tg.name}' from {src}");
            idx += 1;
        }
        ancestor_tags = self.carry_tags;
        ancestor_sources = self.carry_sources;
        self.carry_tags = [];
        self.carry_sources = [];
        visit [->:DirectTag:->];
        block_title = here.title;
        direct_tags = self.carry_tags;
        merged_tags = [];
        merged_sources = [];
        for tg in ancestor_tags {
            merged_tags.append(tg);
        }
        for src in ancestor_sources {
            merged_sources.append(src);
        }
        for tg in direct_tags {
            merged_tags.append(tg);
            merged_sources.append(block_title);
        }
        self.carry_tags = merged_tags;
        self.carry_sources = merged_sources;
        visit [->:ParentOf:->] else { disengage; };
    }

    can absorb_direct with Tag entry {
        self.carry_tags.append(here);
        self.carry_sources.append("");
    }
}

walker TagQuery {
    has target: str = "";
    has include_inherited: bool = False;
    has hit: bool = False;

    can start with Root entry {
        label = "ON" if self.include_inherited else "OFF";
        print(f"== query tag='{self.target}' include_inherited={label} ==");
        visit [-->];
    }

    can scan with Block entry {
        if not here.available {
            visit [->:ParentOf:->] else { disengage; };
        }
        self.hit = False;
        visit [->:DirectTag:->];
        if not self.hit and self.include_inherited {
            visit [->:InheritedTag:->];
        }
        if self.hit {
            print(f"  match: {here.title}");
        }
        visit [->:ParentOf:->] else { disengage; };
    }

    can check_tag with Tag entry {
        if here.name == self.target {
            self.hit = True;
        }
    }
}

with entry {
    urgent = Tag(name="urgent");
    project = Tag(name="project");

    docs = Block(title="Docs");
    chapter = Block(title="Chapter");
    section = Block(title="Section");

    root ++> docs;
    docs +>:ParentOf:+> chapter +>:ParentOf:+> section;
    docs +>:DirectTag:+> urgent;
    chapter +>:DirectTag:+> project;

    root spawn InheritancePropagator();
    root spawn TagQuery(target="urgent", include_inherited=False);
    root spawn TagQuery(target="urgent", include_inherited=True);
