"""Recursive planner _buildSubGraph: discarded fromTasks; stale depends_on vs filtered edges.

Models frankenbeast issue #4363 — PlanGraph.fromTasks is called for cycle
detection but its validated result is thrown away; createWithRawEdges returns
nodes whose depends_on still list cross-graph ids stripped from DependsOn edges.
"""

node PlanTask {
    has task_id: str = "";
    has title: str = "";
    has depends_on: list[str] = [];
}

node SubGraph {
    has reason: str = "recursive expansion";
}

edge DependsOn {
    has dep_id: str = "";
}

walker FromTasksValidator {
    has scope: list[str] = [];
    has visiting: list[str] = [];
    has done: list[str] = [];
    has order: list[str] = [];
    has valid: bool = True;

    can start with Root entry {
        visit [-->];
    }

    can validate with PlanTask entry {
        if here.task_id not in self.scope {
            visit [-->];
        } else {
            if here.task_id in self.visiting {
                self.valid = False;
                disengage;
            }
            if here.task_id in self.done {
                disengage;
            }
            self.visiting.append(here.task_id);
            visit [->:DependsOn:->] else { disengage; };
            popped = self.visiting.pop();
            self.done.append(here.task_id);
            self.order.append(here.task_id);
            visit [-->];
        }
    }
}

walker ConsistencyAuditor {
    has scope: list[str] = [];
    has phantoms: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can audit with PlanTask entry {
        if here.task_id in self.scope {
            for dep_id in here.depends_on {
                if dep_id not in self.scope {
                    self.phantoms += 1;
                    print(
                        f"  STALE: {here.task_id}.depends_on -> '{dep_id}' "
                        f"(absent from sub-graph nodes and edges)"
                    );
                }
            }
        }
        visit [-->];
    }
}

walker EdgeReporter {
    has from_id: str = "";

    can start with Root entry {
        print("DependsOn edges (scheduling truth via getDependencies):");
        visit [-->];
    }

    can scan with PlanTask entry {
        self.from_id = here.task_id;
        visit [->:DependsOn:->] else {
            print(f"  {here.task_id} -> (none)");
            visit [-->];
        };
    }

    can follow with PlanTask entry {
        print(f"  {self.from_id} -> {here.task_id}");
        visit [-->];
    }
}

walker MetadataReporter {
    can start with Root entry {
        print("PlanTask.depends_on metadata (may be stale):");
        visit [-->];
    }

    can show with PlanTask entry {
        dep_label = ", ".join(here.depends_on) if here.depends_on else "(none)";
        print(f"  {here.task_id}: [{dep_label}]");
        visit [-->];
    }
}

walker FromTasksSanitizer {
    has scope: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can rebuild with PlanTask entry {
        if here.task_id in self.scope {
            internal: list[str] = [];
            for dep_id in here.depends_on {
                if dep_id in self.scope {
                    internal.append(dep_id);
                }
            }
            here.depends_on = internal;
        }
        visit [-->];
    }
}

walker SubGraphBuilder {
    has scope: list[str] = [];
    has discard_validated: bool = True;

    can start with Root entry {
        visit [-->];
    }

    can build with SubGraph entry {
        validator = FromTasksValidator(scope=self.scope);
        root spawn validator;
        if not validator.valid {
            print(f"CyclicDependencyError during {here.reason}");
            disengage;
        }
        if self.discard_validated {
            path_label = (
                "BUG: fromTasks validated graph discarded; "
                "createWithRawEdges keeps stale depends_on"
            );
            print(f"[{path_label}]");
            root spawn MetadataReporter();
            root spawn EdgeReporter();
            auditor = ConsistencyAuditor(scope=self.scope);
            root spawn auditor;
            print(f"phantom depends_on entries: {auditor.phantoms}");
        } else {
            path_label = "FIX: return PlanGraph.fromTasks(tasksWithInternalDependencies)";
            print(f"[{path_label}]");
            root spawn FromTasksSanitizer(scope=self.scope);
            root spawn MetadataReporter();
            root spawn EdgeReporter();
            auditor = ConsistencyAuditor(scope=self.scope);
            root spawn auditor;
            print(f"phantom depends_on entries: {auditor.phantoms}");
        }
        visit [-->];
    }
}

with entry {
    scope = ["compile", "link", "test"];

    compile = PlanTask(task_id="compile", title="Compile", depends_on=[]);
    link = PlanTask(
        task_id="link",
        title="Link",
        depends_on=["compile", "install-deps"]
    );
    test = PlanTask(task_id="test", title="Run tests", depends_on=["link"]);

    sg = SubGraph(reason="recursive expansion");
    root ++> sg;
    sg ++> compile ++> link ++> test;

    link +>:DependsOn(dep_id="compile"):+> compile;
    test +>:DependsOn(dep_id="link"):+> link;

    print("=== Buggy _buildSubGraph (validate then discard) ===");
    root spawn SubGraphBuilder(scope=scope, discard_validated=True);

    print("=== Fixed _buildSubGraph (return fromTasks) ===");
    root spawn SubGraphBuilder(scope=scope, discard_validated=False);
}

