"""Lattice graph store: issues under versioned runs, blocking and advisory dependency edges, and walkers that read the latest snapshot and audit blocking cycles."""

node Issue {
    has key: str = "";
    has title: str = "";
}

node Run {
    has run_id: str = "";
    has is_latest: bool = False;
}

edge Blocks {
    has source: str = "llm";
    has pinned: bool = False;
    has suppressed: bool = False;
}

edge Suggests {
    has source: str = "llm";
    has confidence: float = 0.0;
}

walker StoreReader {
    has issue_count: int = 0;

    can start with Root entry {
        visit [-->[?:Run]];
    }

    can pick_latest with Run entry {
        if here.is_latest {
            print(f"[store] latest_run_id={here.run_id} (consistent read)");
            visit [-->[?:Issue]];
        } else {
            visit [-->];
        }
    }

    can snapshot with Issue entry {
        self.issue_count += 1;
        print(f"  issue {here.key}: {here.title}");
        visit [-->];
    }

    can finish with Root exit {
        print(f"[store] graph holds {self.issue_count} issues; sub-threshold edges are stored, not discarded");
    }
}

walker CycleAuditor {
    has visited: list[str] = [];
    has path: list[str] = [];
    has cycle_found: bool = False;

    can start with Root entry {
        visit [-->[?:Run]];
    }

    can enter_run with Run entry {
        if here.is_latest {
            visit [-->[?:Issue]];
        } else {
            visit [-->];
        }
    }

    can probe with Issue entry {
        if here.key in self.path {
            self.cycle_found = True;
            trail = "";
            for step in self.path {
                sep = " -> " if trail else "";
                trail = f"{trail}{sep}{step}";
            }
            print(f"[cycle] blocking loop: {trail} -> {here.key}");
            print("[cycle] given-source edges are immutable and win over inference");
            disengage;
        }
        if here.key in self.visited {
            visit [-->];
        } else {
            self.visited.append(here.key);
            self.path.append(here.key);
            visit [->:Blocks:->] else { disengage; };
            if len(self.path) > 0 {
                self.path = self.path[0:-1];
            }
            visit [-->];
        }
    }

    can report with Root exit {
        status = "FOUND" if self.cycle_found else "none";
        print(f"[audit] blocking cycle: {status}");
    }
}

walker Scheduler {
    has visited: list[str] = [];
    has order: list[str] = [];
    has blocked: bool = False;

    can start with Root entry {
        visit [-->[?:Run]];
    }

    can enter_run with Run entry {
        if here.is_latest {
            visit [-->[?:Issue]];
        } else {
            visit [-->];
        }
    }

    can plan with Issue entry {
        if here.key in self.visited {
            visit [-->];
        } else {
            self.visited.append(here.key);
            visit [->:Blocks:->] else { disengage; };
            self.order.append(here.key);
            visit [-->];
        }
    }

    can emit with Root exit {
        if self.blocked {
            print("[schedule] no topological order while a blocking cycle exists");
        } else {
            seq = "";
            for item in self.order {
                sep = ", " if seq else "";
                seq = f"{seq}{sep}{item}";
            }
            print(f"[schedule] blocking execution order: {seq}");
        }
    }
}

with entry {
    stale = Run(run_id="run-041", is_latest=False);
    latest = Run(run_id="run-042", is_latest=True);
    root ++> stale ++> latest;

    types = Issue(key="#1", title="Shared types contract");
