    can start with Root entry {
        print("--- Dependency audit (bounded, cycle-aware) ---");
        visit [-->];
        if self.cycle_detected {
            print("RESULT: cyclic candidate bundle rejected");
        } else {
            print("RESULT: acyclic bundle accepted");
            print(f"Deterministic admission order: {self.admission_log}");
        }
    }

    can audit with Claim | Proof entry {
        if self.cycle_detected {
            disengage;
        }
        oid = here.object_id;
        if self.depth >= self.max_depth {
            print(f"BOUND exceeded at depth {self.depth} on {oid}");
            self.cycle_detected = True;
            disengage;
        }
        for marker in self.on_path {
            if marker == oid {
                print(f"CYCLE: {oid} reappears on active dependency path");
                self.cycle_detected = True;
                disengage;
            }
