        oid = here.object_id;
        already_done = False;
        for done_id in self.finished {
            if done_id == oid {
                already_done = True;
            }
        }
        if not already_done {
            self.finished.append(oid);
            entry_label = f"{here.kind}:{oid}";
            self.admission_log.append(entry_label);
            here.admitted = True;
            print(f"  admit {entry_label} :: {here.summary}");
