"""TiDB parallel HashAgg VAR_SAMP (#70637): identical group inputs must yield zero sample variance."""

node AggGroup {
    has group_key: int = 0;
    has constant_value: int = 89;
    has row_count: int = 1000;
}

node PartialShard {
    has shard_id: int = 0;
    has count: int = 0;
    has sum_val: float = 0.0;
    has sum_sq: float = 0.0;
}

node ExecPlan {
    has partial_concurrency: int = 1;
    has path_name: str = "sequential";
}

edge Runs { }

edge ShardOf { }

walker HashAggExecutor {
    has partial_concurrency: int = 1;
    has path_name: str = "";
    has merge_count: int = 0;
    has merge_sum: float = 0.0;
    has merge_sum_sq: float = 0.0;
    has original_variance: float = 0.0;
    has materialized_variance: float = 0.0;

    can start with Root entry {
        visit [-->];
    }

    can execute with ExecPlan entry {
        self.partial_concurrency = here.partial_concurrency;
        self.path_name = here.path_name;
        self.merge_count = 0;
        self.merge_sum = 0.0;
        self.merge_sum_sq = 0.0;
        visit [->:Runs:->];
    }

    can aggregate with AggGroup entry {
        val = float(here.constant_value);
        n = here.row_count;
        if self.partial_concurrency <= 1 {
            self.merge_count = n;
            self.merge_sum = val * n;
            self.merge_sum_sq = val * val * n;
        } else {
            visit [->:ShardOf:->] else { disengage; };
        }
        sample_var = 0.0;
        if self.merge_count >= 2 {
            mean = self.merge_sum / self.merge_count;
            pop_var = self.merge_sum_sq / self.merge_count - mean * mean;
            sample_var = pop_var * self.merge_count / (self.merge_count - 1);
        }
        shard_parts = self.partial_concurrency if self.partial_concurrency > 1 else 1;
        final_var = sample_var;
        if shard_parts > 1 and sample_var == 0.0 {
            final_var = 8.7e-30;
        }
        path = self.path_name;
        print(f"[{path}] group {here.group_key} "
              f"(rows={n}, value={here.constant_value}): VAR_SAMP={final_var}");
        if path == "original" {
            self.original_variance = final_var;
        } else {
            self.materialized_variance = final_var;
        }
        visit [-->];
    }

    can absorb with PartialShard entry {
        self.merge_count += here.count;
        self.merge_sum += here.sum_val;
        self.merge_sum_sq += here.sum_sq;
    }
}

with entry {
    og = AggGroup(group_key=3, constant_value=89, row_count=1000);
    orig = ExecPlan(partial_concurrency=1, path_name="original");
    root ++> orig;
    orig +>:Runs:+> og;

    mg = AggGroup(group_key=3, constant_value=89, row_count=1000);
    mat = ExecPlan(partial_concurrency=4, path_name="materialized");
    root ++> mat;
    mat +>:Runs:+> mg;
    mg +>:ShardOf:+> PartialShard(shard_id=0, count=250, sum_val=22250.0, sum_sq=1980250.0);
    mg +>:ShardOf:+> PartialShard(shard_id=1, count=250, sum_val=22250.0, sum_sq=1980250.0);
    mg +>:ShardOf:+> PartialShard(shard_id=2, count=250, sum_val=22250.0, sum_sq=1980250.0);
    mg +>:ShardOf:+> PartialShard(shard_id=3, count=250, sum_val=22250.0, sum_sq=1980250.0);

    w = HashAggExecutor();
    root spawn w;

    print("expected: both oracle paths return VAR_SAMP=0.0");
    print(f"observed: original={w.original_variance}, materialized={w.materialized_variance}");
    if w.materialized_variance != 0.0 {
        print(f"UNION DISTINCT exposes extra row {w.materialized_variance} (parallel HashAgg bug)");
    }
}

