            print(f"Deterministic admission order: {self.admission_log}");
        }
    }

    can descend with Claim | Proof entry {
        if self.cycle_detected {
            disengage;
        }
        oid = here.object_id;
        if self.depth >= self.max_depth {
            print(f"BOUND exceeded at depth {self.depth} on {oid}");
            self.cycle_detected = True;
            disengage;
        }
        for marker in self.on_path {
            if marker == oid {
                print(f"CYCLE: {oid} reappears on active dependency path");
                self.cycle_detected = True;
                disengage;
            }
        }
        self.depth += 1;
        self.on_path.append(oid);
        visit [->:DependsOn:->] else { disengage; }
    }

    can ascend with Claim | Proof exit {
        if self.cycle_detected {
            disengage;
        }
        oid = here.object_id;
        already_done = False;
        for done_id in self.finished {
            if done_id == oid {
                already_done = True;
            }
        }
        if not already_done {
            self.finished.append(oid);
            entry_label = f"{here.kind}:{oid}";
            self.admission_log.append(entry_label);
            here.admitted = True;
            print(f"  admit {entry_label} :: {here.summary}");
        }
        if len(self.on_path) > 0 {
            self.on_path = self.on_path[: len(self.on_path) - 1];
        }
        self.depth -= 1;
        visit [-->];
    }
}

walker NameResolver {
    has query_name: str = "";
    has resolved_id: str = "";
    has resolved_kind: str = "";
    has found: bool = False;

    can start with Root entry {
        print(f"--- Resolving name binding for '{self.query_name}' ---");
        visit [-->];
