"""Track specification cluster completion before implementation replanning resumes."""

node Trackable {
    has title: str = "";
}

node GlobalIndex(Trackable) {
    has planning_resumed: bool = False;
}

node ClusterUmbrella(Trackable) {
    has cluster_num: int = 0;
    has status: str = "pending";
}

node WorkItem(Trackable) {
    has merged: bool = False;
}

edge Owns { }

edge DependsOn { }

walker HierarchyReader {
    has level: int = 0;

    can start with Root entry {
        print("=== Read from top of hierarchy ===");
        visit [-->];
    }

    can read_global with GlobalIndex entry {
        print(f"[L{self.level}] GLOBAL INDEX: {here.title}");
        self.level += 1;
        visit [->:Owns:->];
        self.level -= 1;
    }

    can read_cluster with ClusterUmbrella entry {
        if here.status == "complete" {
            badge = "COMPLETE";
        } elif here.status == "active" {
            badge = "ACTIVE";
        } else {
            badge = "PENDING";
        }
        print(f"[L{self.level}] CLUSTER {here.cluster_num}: {here.title} [{badge}]");
        self.level += 1;
        visit [->:Owns:->] else { # no nested work items };
        self.level -= 1;
    }

    can read_work with WorkItem entry {
        state = "MERGED" if here.merged else "OPEN";
        print(f"[L{self.level}] WORK ITEM: {here.title} [{state}]");
    }
}

walker CompletionGatekeeper {
    has all_complete: bool = True;
    has blockers: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can check_global with GlobalIndex entry {
        visit [->:Owns:->];
        if self.all_complete {
            here.planning_resumed = True;
            print("HANDOFF: all clusters complete — implementation planning may resume.");
        } else {
            print("BLOCKED: implementation planning paused until every cluster is complete.");
            for blocker in self.blockers {
                print(f"  - incomplete: {blocker}");
            }
        }
    }

    can check_cluster with ClusterUmbrella entry {
        if here.status != "complete" {
            self.all_complete = False;
            self.blockers.append(here.title);
        }
        visit [->:Owns:->] else { # cluster leaf };
    }
}

walker DependencyWalker {
    has chain: list[str] = [];

    can traverse with ClusterUmbrella entry {
        step = f"{here.cluster_num}:{here.title}";
        self.chain.append(step);
        visit [->:DependsOn:->] else { disengage; };
    }
}

