}

"""Gradle dependency detection: lockfile-only static scan versus full dependency-engine resolution."""

node GradleProject {
    has name: str = "";
    has uses_kotlin_dsl: bool = False;
    has has_lockfile: bool = False;
}

node Component {
    has group_id: str = "";
    has artifact_id: str = "";
    has version: str = "";

    def coordinates() -> str {
        return f"{self.group_id}:{self.artifact_id}:{self.version}";
    }
}

node ResolvedComponent(Component) {
    has is_transitive: bool = False;
    has excluded: bool = False;
}

node LockfileComponent(Component) {
}

edge Subproject { }

edge DependsOn {
    has configuration: str = "runtimeClasspath";
    has substituted: bool = False;
}

edge DeclaredInLockfile { }

walker LockfileScanner {
    has inventory: list[str] = [];

    can start with Root entry {
        visit [->:Subproject:->];
    }

    can scan with GradleProject entry {
        if here.has_lockfile {
            visit [->:DeclaredInLockfile:->];
        } else {
            print(f"[lockfile] {here.name}: no gradle.lockfile — build.gradle not evaluated");
        }
        visit [->:Subproject:->];
    }

    can record with LockfileComponent entry {
        coords = here.coordinates();
        self.inventory.append(coords);
        print(f"[lockfile] static entry {coords}");
        visit [-->] else { disengage; };
    }
}

walker GradleResolver {
    has inventory: list[str] = [];
    has seen_keys: list[str] = [];
    has depth_cap: int = 8;
    has depth: int = 0;

    can start with Root entry {
        visit [->:Subproject:->];
    }

    can resolve with GradleProject entry {
        script = "build.gradle.kts" if here.uses_kotlin_dsl else "build.gradle";
        print(f"[gradle] invoking resolution engine on {here.name} ({script})");
        self.depth = 0;
        visit [->:DependsOn:->];
        visit [->:Subproject:->];
    }

    can walk with ResolvedComponent entry {
        key = f"{here.group_id}:{here.artifact_id}";
        if key in self.seen_keys {
            print(f"[gradle] cycle guard: {key} already on resolved graph");
            disengage;
        }
        if here.excluded {
            print(f"[gradle] exclusion applied: {key}");
            disengage;
        }
        if self.depth >= self.depth_cap {
            print(f"[gradle] depth cap at {key}");
            disengage;
        }
        self.seen_keys.append(key);
        role = "transitive" if here.is_transitive else "direct";
        coords = here.coordinates();
        self.inventory.append(coords);
        print(f"[gradle] resolved {role} {coords}");
        next_depth = self.depth + 1;
        self.depth = next_depth;
        visit [->:DependsOn:->];
        self.depth = next_depth - 1;
    }
}

with entry {
    app = GradleProject(name="app", uses_kotlin_dsl=True, has_lockfile=True);
    lib = GradleProject(name="lib", has_lockfile=False);
    root +>:Subproject:+> app;
    root +>:Subproject:+> lib;

    okhttp = ResolvedComponent(
        group_id="com.squareup.okhttp3", artifact_id="okhttp", version="4.9.0");
    okio = ResolvedComponent(
        group_id="com.squareup.okio", artifact_id="okio", version="2.8.0",
        is_transitive=True);
    gson = ResolvedComponent(
        group_id="com.google.code.gson", artifact_id="gson", version="2.8.6");

    app +>:DependsOn(configuration="runtimeClasspath"):+> okhttp;
    okhttp +>:DependsOn:+> okio;
    lib +>:DependsOn:+> gson;

    locked_okhttp = LockfileComponent(
        group_id="com.squareup.okhttp3", artifact_id="okhttp", version="4.9.0");
    app +>:DeclaredInLockfile:+> locked_okhttp;

    print("--- Lockfile-only detector ---");
    lock_scan = LockfileScanner();
    root spawn lock_scan;

    print("--- Gradle dependency engine ---");
    resolver = GradleResolver();
    root spawn resolver;

    print(f"lockfile inventory ({len(lock_scan.inventory)}): misses transitive and unlocked subprojects");
    print(f"gradle inventory ({len(resolver.inventory)}): full resolved graph with parent-child edges");
}

