"""Team workflow DAG: validate acyclic dependencies and execute read-only tasks in order."""

node Workflow {
    has goal: str = "";
    has max_parallel: int = 1;
    has base_sha: str = "";
}

node Task {
    has task_id: str = "";
    has title: str = "";
    has status: str = "pending";
    has attempt: int = 0;
    has read_only: bool = True;
}

edge DependsOn { }

walker AcyclicValidator {
    has stack: list[str] = [];
    has acyclic: bool = True;
    has error_msg: str = "";

    can start with Root entry {
        visit [-->[?:Task]] else { disengage; };
    }

    can dfs with Task entry {
        if here.task_id in self.stack {
            self.acyclic = False;
            self.error_msg = f"cycle detected at {here.task_id}";
            disengage;
        }
        self.stack.append(here.task_id);
        visit [<-:DependsOn:<-] else { }
        self.stack = self.stack[:-1];
        visit [-->] else { disengage; };
    }
}

walker DagExecutor {
    has max_parallel: int = 1;
    has completed: list[str] = [];
    has execution_log: list[str] = [];

    can start with Root entry {
        print(f"Scheduling read-only tasks (max_parallel={self.max_parallel})");
        visit [-->[?:Task]] else { disengage; };
    }

    can execute with Task entry {
        if here.task_id in self.completed {
            visit [->:DependsOn:->] else { disengage; };
        } else {
            visit [<-:DependsOn:<-] else {
                if not here.read_only {
                    here.status = "failed";
                    self.execution_log.append(
                        f"[REJECTED] {here.task_id}: write-mode not allowed in this slice"
                    );
                    disengage;
                }
                here.status = "running";
                here.attempt += 1;
                here.status = "completed";
                self.completed.append(here.task_id);
                self.execution_log.append(
                    f"[{here.task_id}] {here.title} attempt={here.attempt} status=completed"
                );
                visit [->:DependsOn:->] else { disengage; };
            };
        }
    }
}

with entry {
