    plan_task +>:DependsOn:+> research;
    review_task +>:DependsOn:+> plan_task;

    checker = AcyclicValidator();
    root spawn checker;
    valid_label = "VALID" if checker.acyclic else "INVALID";
    msg = checker.error_msg if checker.error_msg else "no cycles";
    print(f"DAG validation: {valid_label} ({msg})");

    if checker.acyclic {
