"""Team workflow DAG: validate acyclic dependencies and execute read-only tasks in order."""

node Workflow {
    has goal: str = "";
    has max_parallel: int = 1;
    has base_sha: str = "";
}

node Task {
    has task_id: str = "";
    has title: str = "";
    has status: str = "pending";
    has attempt: int = 0;
    has read_only: bool = True;
}

edge DependsOn { }

walker AcyclicValidator {
    has on_stack: list[str] = [];
    has finished: list[str] = [];
    has acyclic: bool = True;
    has error_msg: str = "";

    can start with Root entry {
        visit [-->] else { disengage; };
    }

    can scan with Workflow entry {
        visit [-->];
    }

    can visit_task with Task entry {
        if here.task_id in self.finished {
            disengage;
        }
        if here.task_id in self.on_stack {
            self.acyclic = False;
            self.error_msg = f"cycle detected at {here.task_id}";
            disengage;
        }
        self.on_stack.append(here.task_id);
        visit [<-:DependsOn:<-] else { };
        self.on_stack = self.on_stack[:-1];
        self.finished.append(here.task_id);
        disengage;
    }
}

walker DagExecutor {
    has max_parallel: int = 1;
    has completed: list[str] = [];
    has execution_log: list[str] = [];
    has checking: bool = False;
    has blocked: bool = False;
    has total_tasks: int = 3;

    can start with Root entry {
        for _ in range(self.total_tasks) {
            visit [-->] else { };
        }
        disengage;
    }

    can scan with Workflow entry {
        visit [-->];
    }

    can run_task with Task entry {
        if self.checking {
            if here.task_id not in self.completed {
                self.blocked = True;
            }
            disengage;
        }
        if here.task_id in self.completed {
            disengage;
        }
        self.checking = True;
        self.blocked = False;
        visit [<-:DependsOn:<-] else { self.checking = False; };
        if self.blocked {
            self.checking = False;
            disengage;
        }
        self.checking = False;
        if not here.read_only {
            here.status = "failed";
            self.execution_log.append(
                f"[REJECTED] {here.task_id}: write-mode not allowed in this slice"
            );
            disengage;
        }
        here.status = "running";
        here.attempt += 1;
        here.status = "completed";
        self.completed.append(here.task_id);
        self.execution_log.append(
            f"[{here.task_id}] {here.title} attempt={here.attempt} status=completed"
        );
        disengage;
    }
}

