"""React.do useMemo codemod: positional scope walk over let bindings."""

node ScopedName {
    has name: str = "";
    has bound_at: int = -1;
}

node DoBlock {
    has label: str = "";
    has is_react_do: bool = False;
}

node LetBinding(ScopedName) {
    has is_jsx: bool = False;
}

node StableName(ScopedName) { }

edge Contains { }

edge DependsOn { }

edge NestedDo { }

walker MemoAnalyzer {
    has memo_count: int = 0;
    has binding_pos: int = 0;
    has binding_name: str = "";
    has scope_ok: bool = True;
    has checking_deps: bool = False;

    can start with Root entry {
        print("MemoCodemod v1: harvest DoLets under React.do only");
        visit [-->];
    }

    can scan_block with DoBlock entry {
        if !here.is_react_do {
            print(f"  [NESTED-SKIP] {here.label}: Effect do, no DoLet harvest");
            disengage;
        }
        print(f"Scanning {here.label}");
        visit [->:Contains:->] else { disengage; };
    }

    can audit_stable_dep with StableName entry {
        if !self.checking_deps {
            disengage;
        }
        if here.bound_at >= self.binding_pos {
            self.scope_ok = False;
            print(
                f"  [{self.binding_name}] scope fail: {here.name} "
                f"@ {here.bound_at} not before {self.binding_pos}"
            );
        }
    }

    can audit_let_dep with LetBinding entry {
        if !self.checking_deps {
            disengage;
        }
        if here.bound_at >= self.binding_pos {
            self.scope_ok = False;
            print(
                f"  [{self.binding_name}] scope fail: {here.name} "
                f"@ {here.bound_at} not before {self.binding_pos}"
            );
        }
    }

    can analyze_binding with LetBinding entry {
        if self.checking_deps {
            disengage;
        }
        self.binding_name = here.name;
        self.binding_pos = here.bound_at;
        self.scope_ok = True;
        self.checking_deps = True;
        visit [->:DependsOn:->];
        self.checking_deps = False;
        eligible = False;
        verdict = "";
        if !self.scope_ok {
            verdict = "forward-reference";
        } elif here.is_jsx {
            eligible = True;
            verdict = "jsx-bailout-point";
        } elif here.name == "currentSquares" {
            eligible = True;
            verdict = "stabilizes-jsx-key";
        } else {
            verdict = "zero-bailout-ceiling";
        }
        if eligible {
            self.memo_count += 1;
            print(f"  [MEMO] {here.name} @ {here.bound_at}: {verdict}");
        } else {
            print(f"  [SKIP] {here.name} @ {here.bound_at}: {verdict}");
        }
        visit [->:NestedDo:->];
        visit [-->] else { disengage; };
    }
}

