    history = StableName(name="history", bound_at=-1);
    set_state = StableName(name="setState", bound_at=-1);

    react_do = DoBlock(label="Main.reactDo", is_react_do=True);
    x_is_next = LetBinding(name="xIsNext", bound_at=0);
    current_squares = LetBinding(name="currentSquares", bound_at=1);
