"""Source acquisition: bounded pagination crawl with fingerprint cycle guard and provenance audit."""

node ScraperDef {
    has name: str = "";
    has version: str = "";
    has max_pages: int = 10;
}

node AcquireSession {
    has idempotency_key: str = "";
    has pages_fetched: int = 0;
    has terminal: str = "pending";
}

node PageRequest {
    has page_no: int = 0;
    has fingerprint: str = "";
    has status: str = "pending";
}

node SearchItem {
    has title: str = "";
    has url: str = "";
}

edge UsesScraper { }
edge StartsAt { }
edge NextPage { }
edge EmitsItem { }

walker AcquisitionCrawler {
    has max_pages: int = 10;
    has visited_fps: list[str] = [];
    has items_found: int = 0;
    has active_session: AcquireSession | None = None;

    can start with Root entry {
        visit [-->];
    }

    can begin with AcquireSession entry {
        self.active_session = here;
        print(f"acquire accepted key={here.idempotency_key}");
        visit [->:UsesScraper:->];
        visit [->:StartsAt:->] else { disengage; };
    }

    can bind_scraper with ScraperDef entry {
        self.max_pages = here.max_pages;
        print(f"scraper {here.name} v{here.version} max_pages={here.max_pages}");
    }

    can crawl with PageRequest entry {
        if here.fingerprint in self.visited_fps {
            here.status = "cycle_blocked";
            if self.active_session is not None {
                self.active_session.terminal = "blocked";
            }
            print(f"cycle detected page={here.page_no} fp={here.fingerprint}");
            disengage;
        }
        self.visited_fps.append(here.fingerprint);
        here.status = "fetched";
        if self.active_session is not None {
            self.active_session.pages_fetched += 1;
        }
        print(f"fetch page={here.page_no} fp={here.fingerprint}");
        visit [->:EmitsItem:->];
        if self.active_session is not None {
            if self.active_session.pages_fetched >= self.max_pages {
                self.active_session.terminal = "partial";
                print(f"max_pages={self.max_pages} policy exhausted");
                disengage;
            }
        }
        visit [->:NextPage:->] else {
            if self.active_session is not None {
                self.active_session.terminal = "success";
            }
            print("pagination terminal=success");
            disengage;
        };
    }

    can harvest with SearchItem entry {
        self.items_found += 1;
        print(f"  emit item title={here.title} url={here.url}");
    }
}

walker ProvenanceAuditor {
    can audit with SearchItem entry {
        print(f"provenance audit: {here.title}");
        visit [<--:EmitsItem:--] else { disengage; };
    }

    can from_page with PageRequest entry {
        print(f"  sourced page={here.page_no} fp={here.fingerprint}");
    }
}

