    scraper = ScraperDef(name="searx-search", version="1", max_pages=10);
    session = AcquireSession(idempotency_key="idem-7a3f");

    p1 = PageRequest(page_no=1, fingerprint="q=osi&p=1");
    p2 = PageRequest(page_no=2, fingerprint="q=osi&p=2");
    p3 = PageRequest(page_no=3, fingerprint="q=osi&p=1");

    r1 = SearchItem(title="OSINT primer", url="https://example.com/a");
    r2 = SearchItem(title="Scraper patterns", url="https://example.com/b");

    root ++> session;
    session +>:UsesScraper:+> scraper;
    session +>:StartsAt:+> p1;
    p1 +>:NextPage:+> p2;
    p2 +>:NextPage:+> p3;
    p1 +>:EmitsItem:+> r1;
    p2 +>:EmitsItem:+> r2;

    crawler = AcquisitionCrawler();
    root spawn crawler;
    r1 spawn ProvenanceAuditor();
    r2 spawn ProvenanceAuditor();

    print(f"session {session.idempotency_key} terminal={session.terminal} "
          f"items={crawler.items_found}");
