"""Sound temporary-borrow optimization for managed projections.

Models owned roots, nested managed projections with transitive parent
links, and a lifetime prover that elides conservative +1 retains only when
an owned root dominates every derived use — failing closed on escapes,
broken provenance, cycles, and dead roots.
"""

node LifetimeValue {
    has label: str = "";

    def is_live() -> bool {
        return True;
    }

    def display_name() -> str {
        return self.label;
    }
}

node OwnedRoot(LifetimeValue) {
    has name: str = "";
    has live: bool = True;

    override def display_name() -> str {
        return self.name;
    }

    override def is_live() -> bool {
        return self.live;
    }
}

node ManagedProjection(LifetimeValue) {
    has depth: int = 0;
}

node UseSite {
    has op_name: str = "";
}

node EscapeHazard {
    has reason: str = "";
}

edge DerivesFrom { }
edge AtUse { }
edge MayEscapeVia { }

walker LifetimeProver {
    has elisions: int = 0;
    has retains: int = 0;
    has visited: list[str] = [];
    has blocked: bool = False;

    can start with Root entry {
        visit [-->];
    }

    can audit_use with UseSite entry {
        self.visited = [];
        self.blocked = False;
        visit [<-:MayEscapeVia:--] else {
            self.blocked = False;
        };
        if not self.blocked {
            visit [<-:AtUse:--] else {
                print(f"[RETAIN +1] {here.op_name}: missing projection provenance");
                self.retains += 1;
            };
        }
        visit [-->];
    }

    can fail_escape with EscapeHazard entry {
        print(f"[FAIL CLOSED] {here.reason}: cannot prove borrow extent");
        self.retains += 1;
        self.blocked = True;
    }

    can climb_parent with ManagedProjection entry {
        tag = here.display_name();
        if tag in self.visited {
            print(f"[FAIL CLOSED] cycle at {tag}: nested projection loop");
            self.retains += 1;
            disengage;
        }
        self.visited.append(tag);
        visit [<-:DerivesFrom:--] else {
            print(f"[FAIL CLOSED] {tag}: broken transitive parent chain");
            self.retains += 1;
            disengage;
        };
    }

    can prove_root with OwnedRoot entry {
        root_name = here.display_name();
        if here.is_live() {
            print(f"[ELIDE RETAIN] owned root {root_name} dominates derived use");
            self.elisions += 1;
        } else {
            print(f"[RETAIN +1] root {root_name} not live for full extent");
            self.retains += 1;
        }
    }
}

