"""Dispatch run receipt inventory: classify live vs completed receipts and safely reap proven history."""

node DispatchRoot {
    has label: str = ".dispatch-runs/";
}

node RunReceipt {
    has run_id: str = "";
    has wave_id: str = "";
    has issue_id: str = "";
    has age_days: int = 0;
    has bytes: int = 0;
    has parse_state: str = "valid";
    has terminal_marker: bool = False;
    has classification: str = "unknown";
    has reaped: bool = False;
}

node Lease {
    has run_id: str = "";
    has active: bool = False;
}

node Worker {
    has run_id: str = "";
    has active: bool = False;
}

edge HousedIn { }
edge BoundLease { }
edge BoundWorker { }

walker InventoryAuditor {
    has probe_live: bool = False;
    has live_count: int = 0;
    has completed_count: int = 0;
    has unknown_count: int = 0;
    has malformed_count: int = 0;

    can start with Root entry {
        print("=== DISPATCH INVENTORY PREVIEW (read-only) ===");
        visit [-->];
    }

    can enter_root with DispatchRoot entry {
        visit [->:HousedIn:->];
    }

    can classify with RunReceipt entry {
        self.probe_live = False;
        visit [<-:BoundLease:<-] else { };
        visit [<-:BoundWorker:<-] else { };
        if here.parse_state == "malformed" {
            cls = "malformed";
            self.malformed_count += 1;
        } else if self.probe_live {
            cls = "live";
            self.live_count += 1;
        } else if here.terminal_marker {
            cls = "completed";
            self.completed_count += 1;
        } else {
            cls = "unknown";
            self.unknown_count += 1;
        }
        here.classification = cls;
        tag = "LIVE" if cls == "live" else cls.upper();
        print(f"[{tag}] run={here.run_id} wave={here.wave_id} "
              f"issue={here.issue_id} age={here.age_days}d bytes={here.bytes}");
    }

    can check_binding with Lease | Worker entry {
        if here.active {
            self.probe_live = True;
        }
    }
}

walker ReapOperator {
    has grace_days: int = 7;
    has max_keep: int = 2;
    has probe_live: bool = False;
    has completed_seen: int = 0;
    has reaped_count: int = 0;
    has reaped_bytes: int = 0;
    has preserved_count: int = 0;

    can start with Root entry {
        print("");
        print("=== DISPATCH REAP APPLY (quarantine + reclaim) ===");
        visit [-->];
    }

    can enter_root with DispatchRoot entry {
        visit [->:HousedIn:->];
    }

    can reap with RunReceipt entry {
        if here.classification != "completed" {
            reason = here.classification;
            print(f"PRESERVE ({reason}): {here.run_id}");
            self.preserved_count += 1;
        } else if here.age_days <= self.grace_days {
            print(f"PRESERVE (within grace): {here.run_id}");
            self.preserved_count += 1;
        } else {
            self.completed_seen += 1;
            if self.completed_seen <= self.max_keep {
                print(f"PRESERVE (retention slot): {here.run_id}");
                self.preserved_count += 1;
            } else {
                self.probe_live = False;
                visit [<-:BoundLease:<-] else { };
                visit [<-:BoundWorker:<-] else { };
                if self.probe_live {
                    print(f"PRESERVE (reactivated): {here.run_id}");
                    self.preserved_count += 1;
                } else {
                    here.reaped = True;
                    self.reaped_count += 1;
                    self.reaped_bytes += here.bytes;
                    print(f"REAPED: {here.run_id} ({here.bytes} bytes -> quarantine)");
                }
            }
        }
    }

    can recheck_binding with Lease | Worker entry {
        if here.active {
            self.probe_live = True;
        }
    }
}

