"""Ghostfleet migration planner: dependency ordering, cycle detection, and engine selection."""

node TargetObject {
    has name: str = "";
    has source_fp: str = "";
    has dest_fp: str = "";
}

node SchemaChange {
    has op_id: str = "";
    has op_kind: str = "";
    has needs_gh_ost: bool = False;
    has engine: str = "";
}

edge DependsOn { }

edge AppliesTo { }

walker DependencyPlanner {
    has ordered: list[str] = [];
    has visiting: list[str] = [];
    has done: list[str] = [];
    has cycle_at: str = "";
    has bind_name: str = "";
    has bind_src: str = "";
    has bind_dst: str = "";

    can start with Root entry {
        visit [-->[?:SchemaChange]] else { disengage; };
    }

    can order with SchemaChange entry {
        key = here.op_id;
        if key in self.done {
            # dependency already satisfied
        } else {
            if here.op_kind == "unsupported_op" {
                print(f"[FAIL-AC02] unsupported operation: {here.op_kind}");
                disengage;
            }
            if key in self.visiting {
                self.cycle_at = key;
                print(f"[FAIL-AC02] dependency cycle at {key}");
                disengage;
            }
            self.visiting.append(key);
            visit [->:DependsOn:->] else { };
            self.visiting.pop();
            self.done.append(key);
            self.bind_name = "";
            self.bind_src = "";
            self.bind_dst = "";
            visit [->:AppliesTo:->] else { };
            picked = "gh-ost" if here.needs_gh_ost else "native-mysql";
            here.engine = picked;
            self.ordered.append(key);
            print(
                f"[AC04] step {key} ({here.op_kind}) "
                f"target={self.bind_name} "
                f"fp {self.bind_src}->{self.bind_dst} "
                f"engine={picked}"
            );
        }
    }

    can resolve_target with TargetObject entry {
        self.bind_name = here.name;
        self.bind_src = here.source_fp;
        self.bind_dst = here.dest_fp;
    }
}

