        bytes=6144,
        terminal_marker=True
    );
    done_c = RunReceipt(
        run_id="run-done-c",
        wave_id="w2",
        issue_id="8362",
        age_days=15,
        bytes=12288,
        terminal_marker=True
    );
    unknown_rcpt = RunReceipt(
        run_id="run-orphan",
        wave_id="",
        issue_id="",
        age_days=20,
