    store +>:HousedIn:+> done_c;
    store +>:HousedIn:+> unknown_rcpt;
    store +>:HousedIn:+> bad_rcpt;

    live_rcpt +>:BoundLease:+> Lease(run_id="run-active-001", active=True);
    unknown_rcpt +>:BoundWorker:+> Worker(run_id="run-orphan", active=False);

    auditor = InventoryAuditor();
