    print("");
    print(
        f"Preview totals: live={auditor.live_count} "
        f"completed={auditor.completed_count} "
        f"unknown={auditor.unknown_count} "
        f"malformed={auditor.malformed_count}"
    );
    print(
        f"Reap totals: reaped={reaper.reaped_count} "
        f"bytes={reaper.reaped_bytes} preserved={reaper.preserved_count}"
    );
