"""JJQ mapper processor: compile-time generated bindings vs reflection fallback."""

node RecordType {
    has name: str = "";
    has available: bool = True;
}

node FieldDef {
    has field_name: str = "";
    has jq_path: str = "";
    has java_type: str = "String";
    has ignored: bool = False;
}

node GeneratedMapper {
    has class_name: str = "";
}

edge Declares {
    has ordinal: int = 0;
}

edge GeneratesFor { }

edge NestedRecord { }

walker MapperResolver {
    has resolved: int = 0;
    has pending_record: str = "";

    can start with Root entry {
        print("JqMapper.getMapping: generated *_JqMapping first, else reflection");
        visit [-->] else { disengage; };
    }

    can probe with RecordType entry {
        self.pending_record = here.name;
        visit [<--:GeneratesFor:--] else {
            print(f"  {here.name} -> ClassMapping.forRecord()");
            self.resolved += 1;
        };
        visit [-->] else { disengage; };
    }

    can pick_generated with GeneratedMapper entry {
        print(f"  {self.pending_record} -> {here.class_name} (compile-time)");
        self.resolved += 1;
        disengage;
    }
}

walker FieldBinder {
    has depth: int = 0;
    has max_depth: int = 6;
    has stack: list[str] = [];
    has emitted: int = 0;

    can start with Root entry {
        print("Annotation processor field walk + nested bind (cycle guarded)");
        visit [-->] else { disengage; };
    }

    can walk_record with RecordType entry {
        if here.name in self.stack {
            print(f"  [CYCLE] skip re-entry into {here.name}");
            disengage;
        }
        if self.depth >= self.max_depth {
            print(f"  [DEPTH] cap at {here.name}");
            disengage;
        }
        self.stack.append(here.name);
        self.depth += 1;
        print(f"Record {here.name} (depth {self.depth})");
        visit [->:Declares:->] else { };
        self.depth -= 1;
        if self.stack {
            self.stack = self.stack[:-1];
        }
        visit [-->] else { disengage; };
    }

    can emit_field with FieldDef entry {
        if here.ignored {
            print(f"  @JqIgnore {here.field_name}");
            visit [-->] else { disengage; };
            return;
        }
        prog = f"P_{here.field_name.upper()} = JqProgram.compile(\"{here.jq_path}\")";
        conv = ".asString(null)";
        if here.java_type == "int" {
            conv = "(int) .asLong(0)";
        } elif here.java_type == "long" {
            conv = ".asLong(0)";
        }
        print(f"  static {prog}");
        print(f"    bind {here.field_name} via {conv}");
        self.emitted += 1;
        visit [->:NestedRecord:->] else {
            visit [-->] else { disengage; };
        };
    }
}

with entry {
    user = RecordType(name="User");
    address = RecordType(name="Address");
    order = RecordType(name="Order");

    user_name = FieldDef(field_name="name", jq_path=".name", java_type="String");
    user_age = FieldDef(field_name="age", jq_path=".age", java_type="int");
    user_city = FieldDef(
        field_name="city", jq_path=".address.city", java_type="String"
    );
    user_internal = FieldDef(
        field_name="internal", jq_path=".internal", ignored=True
    );
    addr_city = FieldDef(field_name="city", jq_path=".city", java_type="String");

    user +>:Declares(ordinal=0):+> user_name;
    user +>:Declares(ordinal=1):+> user_age;
    user +>:Declares(ordinal=2):+> user_city;
    user +>:Declares(ordinal=3):+> user_internal;
    user_city +>:NestedRecord:+> address;
    address +>:Declares(ordinal=0):+> addr_city;

    user_map = GeneratedMapper(class_name="User_JqMapping");
    user_map +>:GeneratesFor:+> user;

    order_id = FieldDef(field_name="id", jq_path=".id", java_type="String");
    order_total = FieldDef(field_name="total", jq_path=".total", java_type="long");
    order +>:Declares(ordinal=0):+> order_id;
    order +>:Declares(ordinal=1):+> order_total;

    root ++> user ++> order;

    resolver = MapperResolver();
    binder = FieldBinder();
    root spawn resolver;
    root spawn binder;

    print(
        f"Resolved {resolver.resolved} mappings; "
        f"emitted {binder.emitted} static JqProgram fields"
    );
}

