node Package {
    has name: str = "";
    has domain: str = "";
}

node Component {
    has name: str = "";
    has domain: str = "";
    has superseded: bool = False;
    has reachable: bool = False;
    has removal_pending: bool = False;
}

node Artifact {
    has path: str = "";
    has stale: bool = True;
    has removal_pending: bool = False;
}

edge Exports { }
edge DependsOn { }
edge Supersedes { }
edge Registers { }
edge CopiesFrom { }

walker ReachabilityWalker {
    has visited: list[str] = [];

    can start with Root entry {
        visit [-->[?:Package]];
    }

    can enter_package with Package entry {
        visit [->:Exports:->];
        visit [->:Registers:->];
    }

    can mark_live with Component entry {
        if here.name in self.visited {
            disengage;
        }
        self.visited.append(here.name);
        here.reachable = True;
        visit [->:DependsOn:->] else { disengage; };
    }
}

walker ContractionWalker {
    has removal_count: int = 0;

    can start with Root entry {
        visit [-->[?:Component]];
    }

    can flag_superseded with Component entry {
        if here.superseded {
            here.removal_pending = True;
            label = "SUPERSEDED" if here.superseded else "ORPHAN";
            print(f"[{label}] component {here.name} ({here.domain})");
            self.removal_count += 1;
            visit [->:CopiesFrom:->];
        }
        visit [-->];
    }

    can flag_orphan with Component entry {
        if (not here.reachable) and (not here.removal_pending) {
            here.removal_pending = True;
            print(f"[ORPHAN] component {here.name} ({here.domain})");
            self.removal_count += 1;
        }
        visit [-->];
    }

    can purge_artifact with Artifact entry {
        if here.stale {
            here.removal_pending = True;
            print(f"[STALE ARTIFACT] {here.path}");
            self.removal_count += 1;
        }
        visit [-->];
    }
}

walker DependencyOrderWalker {
    has ordered: list[str] = [];
    has visiting: list[str] = [];
    has cycle_found: bool = False;

    can start with Root entry {
        visit [-->[?:Component]];
    }

    can order with Component entry {
        if here.removal_pending {
            if here.name in self.visiting {
                self.cycle_found = True;
                print(f"[CYCLE] dependency loop at {here.name}");
                disengage;
            }
            self.visiting.append(here.name);
            visit [->:DependsOn:->] else { disengage; };
            self.visiting.pop();
            if here.name not in self.ordered {
                self.ordered.append(here.name);
                print(f"[REMOVE ORDER] {here.name}");
            }
        }
        visit [-->];
    }
}

