walker HoloPanelContraction {
    has visited: list[str] = [];
    has removal_count: int = 0;
    has ordered: list[str] = [];
    has visiting: list[str] = [];
    has phase: int = 0;

    can start with Root entry {
        print("Phase 1: mark live exports from umbrella package");
        self.phase = 1;
        visit [-->[?:Package]] else { disengage; };
        print("Phase 2: flag superseded, orphan, and stale artifacts");
        self.phase = 2;
        visit [-->];
        print("Phase 3: compute safe removal order");
        self.phase = 3;
        visit [-->];
        print(f"Contraction complete: {self.removal_count} items flagged");
    }

    can scan_package with Package entry {
        if self.phase == 1 {
            visit [->:Exports:->];
            visit [->:Registers:->];
        } else if self.phase == 2 {
            visit [->:Exports:->];
            visit [->:Registers:->];
            visit [->:CopiesFrom:->];
        } else {
            visit [->:Exports:->];
            visit [->:CopiesFrom:->];
        }
        visit [-->];
    }

    can inspect_component with Component entry {
        if self.phase == 1 {
            if here.name in self.visited {
                disengage;
            }
            self.visited.append(here.name);
            here.reachable = True;
            visit [->:DependsOn:->] else { disengage; };
        } else if self.phase == 2 {
            if here.superseded and (not here.removal_pending) {
                here.removal_pending = True;
                print(f"[SUPERSEDED] component {here.name} ({here.domain})");
                self.removal_count += 1;
            } else if (not here.reachable) and (not here.removal_pending) {
                here.removal_pending = True;
                print(f"[ORPHAN] component {here.name} ({here.domain})");
                self.removal_count += 1;
            }
            visit [->:DependsOn:->];
            visit [->:Supersedes:->];
