                    print(f"[REMOVE ORDER] {here.name}");
                }
            }
            visit [->:DependsOn:->];
            visit [->:Supersedes:->];
            visit [-->];
        }
    }

    can inspect_artifact with Artifact entry {
        if self.phase == 2 and here.stale and (not here.removal_pending) {
            here.removal_pending = True;
            print(f"[STALE ARTIFACT] {here.path}");
            self.removal_count += 1;
