"""Video availableLanguages: cascade recompute to ancestors and bottom-up publish ordering to prevent parent-before-child races."""

edge ParentOf { }

node Video {
    has title: str = "";
    has own_langs: str = "";
    has available_langs: str = "";
    has published: bool = False;

    def rollup() -> None {
        merged = self.own_langs;
        for ch in self[->:ParentOf:->] {
            merged = merge_langs(merged, ch.available_langs);
        }
        self.available_langs = merged;
    }
}

def merge_langs(a: str, b: str) -> str {
    if a == "" {
        return b;
    }
    if b == "" {
        return a;
    }
    return f"{a}|{b}";
}

walker FixCascade {
    has new_langs: str = "";
    has seen: list[str] = [];

    can start with Video entry {
        if here.title in self.seen {
            disengage;
        }
        self.seen.append(here.title);
        if self.new_langs != "" {
            here.own_langs = self.new_langs;
        }
        here.rollup();
        visit [<--:ParentOf:--] else { disengage; }
    }

    can ascend with Video entry {
        if here.title in self.seen {
            disengage;
        }
        self.seen.append(here.title);
        here.rollup();
        visit [<--:ParentOf:--] else { disengage; }
    }
}

walker OrderedPublish {
    has seen: list[str] = [];

    can start with Video entry {
        if here.title in self.seen {
            disengage;
        }
        self.seen.append(here.title);
        visit [->:ParentOf:->] else { }
        here.published = True;
        here.rollup();
        print(f"[commit] {here.title} -> {here.available_langs}");
        visit [-->];
    }

    can descend with Video entry {
        if here.title in self.seen {
            disengage;
        }
        self.seen.append(here.title);
        visit [->:ParentOf:->] else { }
        here.published = True;
        here.rollup();
        print(f"[commit] {here.title} -> {here.available_langs}");
        visit [-->];
    }
}

