"""Plan graph DAG validation: addTask must reject cyclic task dependencies."""

node PlanGraph {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

node Task {
    has task_id: str = "";
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

edge Contains { }
edge DependsOn { }

walker CycleDetector {
    has stack: list[str] = [];
    has found_cycle: bool = False;

    can start with Task entry {
        self.stack.append(here.task_id);
        visit [->:DependsOn:->] else {
            if len(self.stack) > 0 {
                self.stack.pop();
            }
            disengage;
        };
    }

    can descend with Task entry {
        if here.task_id in self.stack {
            self.found_cycle = True;
            disengage;
        }
        self.stack.append(here.task_id);
        visit [->:DependsOn:->] else {
            if len(self.stack) > 0 {
                self.stack.pop();
            }
            disengage;
        };
    }
}

walker PlanAuditor {
    has cyclic: bool = False;
    has seen: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can review with PlanGraph entry {
        visit [->:Contains:->];
    }

    can inspect with Task entry {
        if here.task_id not in self.seen {
            self.seen.append(here.task_id);
            probe = CycleDetector();
            here spawn probe;
            if probe.found_cycle {
                self.cyclic = True;
            }
        }
        visit [->:Contains:->] else { disengage; };
    }
}

def simulate_add_task(graph: PlanGraph, task: Task, deps: list, safe: bool) {
    for dep in deps {
        task +>:DependsOn:+> dep;
    }
    if safe {
        probe = CycleDetector();
        task spawn probe;
        if probe.found_cycle {
            for dep in deps {
                task del ->:DependsOn:-> dep;
            }
            print(f"CyclicDependencyError: rejected addTask({task.task_id})");
            return;
        }
    }
    graph +>:Contains:+> task;
    note = "validated" if safe else "UNSAFE — no cycle check";
    print(f"addTask({task.task_id}) accepted ({note})");
}

with entry {
    plan = PlanGraph(title="franken-planner", year=1, available=True);
    root ++> plan;

    fetch = Task(task_id="fetch", title="Fetch sources", year=1);
    build = Task(task_id="build", title="Compile", year=2);
    test = Task(task_id="test", title="Run tests", year=3);

    plan +>:Contains:+> fetch;
    plan +>:Contains:+> build;
    plan +>:Contains:+> test;

    build +>:DependsOn:+> fetch;
    test +>:DependsOn:+> build;

    auditor = PlanAuditor();
    root spawn auditor;
    label = "acyclic" if not auditor.cyclic else "cyclic";
    print(f"fromTasks graph is {label}");

    lint = Task(task_id="lint", title="Lint sources", year=4);
    simulate_add_task(plan, lint, [fetch], safe=True);

    hotfix = Task(task_id="hotfix", title="Hotfix", year=5);
    simulate_add_task(plan, hotfix, [test], safe=True);

    print("Unsafe addTask bypass: fetch now depends on test");
    fetch +>:DependsOn:+> test;

    auditor2 = PlanAuditor();
    root spawn auditor2;
    verdict = "acyclic" if not auditor2.cyclic else "CYCLIC";
    print(f"Graph after bypass is {verdict}");

    fetch del ->:DependsOn:-> test;

    cycle_task = Task(task_id="cycle", title="Cycle probe", year=6);
    cycle_task +>:DependsOn:+> hotfix;
    hotfix +>:DependsOn:+> cycle_task;
    probe = CycleDetector();
    cycle_task spawn probe;
    if probe.found_cycle {
        for dep in [hotfix] {
            cycle_task del ->:DependsOn:-> dep;
            hotfix del ->:DependsOn:-> cycle_task;
        }
        print("CyclicDependencyError: rejected addTask(cycle)");
    }
}

"""JJQ mapper processor: compile-time generated bindings vs reflection fallback."""

node RecordType {
    has name: str = "";
    has available: bool = True;
}

node FieldDef {
    has field_name: str = "";
    has jq_path: str = "";
    has java_type: str = "String";
    has ignored: bool = False;
}

node GeneratedMapper {
    has class_name: str = "";
}

edge Declares {
    has ordinal: int = 0;
}

edge GeneratesFor { }

edge NestedRecord { }

walker MapperResolver {
    has resolved: int = 0;
    has pending_record: str = "";

    can start with Root entry {
        print("JqMapper.getMapping: generated *_JqMapping first, else reflection");
        visit [-->] else { disengage; };
    }

    can probe with RecordType entry {
        self.pending_record = here.name;
        visit [<--:GeneratesFor:--] else {
            print(f"  {here.name} -> ClassMapping.forRecord()");
            self.resolved += 1;
        };
        visit [-->] else { disengage; };
    }

    can pick_generated with GeneratedMapper entry {
        print(f"  {self.pending_record} -> {here.class_name} (compile-time)");
        self.resolved += 1;
        disengage;
    }
}

walker FieldBinder {
    has depth: int = 0;
    has max_depth: int = 6;
    has stack: list[str] = [];
    has emitted: int = 0;

    can start with Root entry {
        print("Annotation processor field walk + nested bind (cycle guarded)");
        visit [-->] else { disengage; };
    }

    can walk_record with RecordType entry {
        if here.name in self.stack {
            print(f"  [CYCLE] skip re-entry into {here.name}");
            disengage;
        }
        if self.depth >= self.max_depth {
            print(f"  [DEPTH] cap at {here.name}");
            disengage;
        }
        self.stack.append(here.name);
        self.depth += 1;
        print(f"Record {here.name} (depth {self.depth})");
        visit [->:Declares:->] else { };
        self.depth -= 1;
        self.stack.pop();
        visit [-->] else { disengage; };
    }

    can emit_field with FieldDef entry {
        if here.ignored {
            print(f"  @JqIgnore {here.field_name}");
        } else {
            prog = f"P_{here.field_name.upper()} = JqProgram.compile('{here.jq_path}')";
            conv = ".asString(null)";
            if here.java_type == "int" {
                conv = "(int) .asLong(0)";
            } elif here.java_type == "long" {
                conv = ".asLong(0)";
            }
            print(f"  static {prog}");
            print(f"    bind {here.field_name} via {conv}");
            self.emitted += 1;
            visit [->:NestedRecord:->] else {
                visit [-->] else { disengage; };
            };
        }
        visit [-->] else { disengage; };
    }
}

