}

edge Contains { }
edge DependsOn { }

walker CycleDetector {
    has stack: list[str] = [];
    has found_cycle: bool = False;

    can start with Task entry {
        self.stack.append(here.task_id);
        visit [->:DependsOn:->] else {
            if len(self.stack) > 0 {
                self.stack.pop();
            }
            disengage;
        };
    }

    can follow with Task entry {
        if here.task_id in self.stack {
            self.found_cycle = True;
            disengage;
        }
        self.stack.append(here.task_id);
        visit [->:DependsOn:->] else {
            if len(self.stack) > 0 {
                self.stack.pop();
            }
            disengage;
        };
    }
}

walker PlanAuditor {
    has cyclic: bool = False;
    has seen: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can review with PlanGraph entry {
        visit [->:Contains:->] else { disengage; };
    }

    can inspect with Task entry {
        if here.task_id not in self.seen {
            self.seen.append(here.task_id);
            probe = CycleDetector();
            here spawn probe;
            if probe.found_cycle {
                self.cyclic = True;
            }
        }
        visit [->:Contains:->] else { disengage; };
    }
}

