}

"""Startup reliability orchestration: phased bootstrap with compatibility admission, dependency lanes, and bounded recovery."""

node StartupPhase {
    has phase_name: str = "";
    has status: str = "pending";
    has reason_code: str = "";
}

node RuntimeComponent {
    has component_name: str = "";
    has lane: str = "base";
    has compat_status: str = "unknown";
    has admitted: bool = False;
    has available: bool = True;
}

node CompatIdentity {
    has app_version: str = "";
    has r_version: str = "";
    has arch: str = "";
    has cache_digest: str = "";
}

edge LeadsTo { }
edge DependsOn { }
edge RequiresCompat { has expected_digest: str = ""; }

walker StartupOrchestrator {
    has phases_done: int = 0;
    has workbench_ready: bool = False;

    can start with Root entry {
        print("=== Startup orchestration begin ===");
        visit [->:LeadsTo:->];
        visit [-->[?:RuntimeComponent]];
    }

    can advance with StartupPhase entry {
        here.status = "active";
        print(f"  [{here.phase_name}] entering");
        visit [->:RequiresCompat:->];
        here.status = "complete";
        self.phases_done += 1;
        if here.phase_name == "WORKBENCH_READY" {
            self.workbench_ready = True;
        }
        visit [->:LeadsTo:->] else {
            disengage;
        }
    }

    can gate with CompatIdentity entry {
        print(f"    compat identity: R={here.r_version} arch={here.arch} digest={here.cache_digest}");
    }

    can admit with RuntimeComponent entry {
        verdict = "compatible";
        if not here.available {
            verdict = "requires_user_action";
        } elif here.compat_status == "stale" {
            verdict = "cache_stale";
        } elif here.compat_status == "mismatch" {
            verdict = "runtime_manifest_mismatch";
        }
        here.admitted = verdict == "compatible";
        lane_tag = here.lane.upper();
        admit_label = "ADMIT" if here.admitted else "REJECT";
        print(f"    [{lane_tag}] {here.component_name}: {admit_label} ({verdict})");
        visit [->:DependsOn:->];
    }
}

walker RecoveryPatrol {
    has visited_keys: list[str] = [];
    has recovery_steps: int = 0;
    has halted: bool = False;

    can start with Root entry {
        print("=== Recovery patrol (cycle-bounded) ===");
        visit [-->[?:RuntimeComponent]];
    }

    can probe with RuntimeComponent entry {
        key = here.component_name;
        for existing in self.visited_keys {
            if existing == key {
                print(f"  [HALT] cycle detected at {key} — Needs Attention");
                self.halted = True;
                disengage;
            }
        }
        self.visited_keys.append(key);
        if here.compat_status == "repairable" {
            self.recovery_steps += 1;
            print(f"  [REPAIR] {here.component_name} (step {self.recovery_steps})");
        } elif here.compat_status == "exhausted" {
            print(f"  [STOP] {here.component_name} recovery exhausted — Needs Attention");
            self.halted = True;
            disengage;
        } else {
            print(f"  [SKIP] {here.component_name} not repairable");
        }
        visit [->:DependsOn:->] else {
            disengage;
        }
    }
}

with entry {
    identity = CompatIdentity(
        app_version="0.9.0",
        r_version="4.4.1",
        arch="aarch64",
        cache_digest="sha256:abc"
    );

    cold = StartupPhase(phase_name="COLD");
    discovering = StartupPhase(phase_name="DISCOVERING");
    compat_check = StartupPhase(phase_name="COMPATIBILITY_CHECK");
    base_ready = StartupPhase(phase_name="BASE_RUNTIME_READY");
    workbench = StartupPhase(phase_name="WORKBENCH_READY");

    base_r = RuntimeComponent(
        component_name="BaseR",
        lane="base",
        compat_status="compatible"
    );
    ark = RuntimeComponent(
        component_name="Ark",
        lane="base",
        compat_status="compatible"
    );
