    print(f"--- phases completed: {orch.phases_done}, workbench ready: {orch.workbench_ready} ---");
    print(f"--- base R admitted: {base_r.admitted}, agent lane admitted: {agent_pkgs.admitted}, provider admitted: {provider.admitted} ---");

    patrol = RecoveryPatrol();
    root spawn patrol;
    print(f"--- recovery steps: {patrol.recovery_steps}, halted: {patrol.halted} ---");
}

"""Video availableLanguages: cascade recompute to ancestors and bottom-up publish ordering to prevent parent-before-child races."""

edge ParentOf { }

node Video {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has own_langs: str = "";
    has available_langs: str = "";
    has published: bool = False;
}

def merge_langs(a: str, b: str) -> str {
    if a == "" {
        return b;
    }
    if b == "" {
        return a;
    }
    return f"{a}|{b}";
}

walker LangRollup {
    has merged: str = "";
    has merging: bool = False;

    can rollup with Video entry {
        if self.merging {
            self.merged = merge_langs(self.merged, here.available_langs);
            disengage;
        }
        visit [->:ParentOf:->] else { disengage; }
        self.merged = here.own_langs;
        self.merging = True;
        visit [->:ParentOf:->] else { disengage; }
        self.merging = False;
        here.available_langs = self.merged;
    }
}

walker FixCascade {
    has new_langs: str = "";
    has seen: list[str] = [];

    can repair with Video entry {
        if here.title in self.seen {
            disengage;
        }
        self.seen.append(here.title);
        if self.new_langs != "" {
            here.own_langs = self.new_langs;
        }
        rollup = LangRollup();
        here spawn rollup;
        visit [<-:ParentOf:<-] else { disengage; }
    }
}

walker OrderedPublish {
    has seen: list[str] = [];
    has merged: str = "";
    has merging: bool = False;

    can publish with Video entry {
        if self.merging {
            self.merged = merge_langs(self.merged, here.available_langs);
            disengage;
        }
        if here.title in self.seen {
            disengage;
        }
        self.seen.append(here.title);
        visit [->:ParentOf:->] else { disengage; }
        here.published = True;
        self.merged = here.own_langs;
        self.merging = True;
        visit [->:ParentOf:->] else { disengage; }
        self.merging = False;
        here.available_langs = self.merged;
        print(f"[commit] {here.title} -> {here.available_langs}");
        visit [-->];
    }
}

with entry {
    root ++> (gp := Video(title="Grandparent", own_langs="en"))
        +>:ParentOf:+> (pa := Video(title="Parent", own_langs="de"))
        +>:ParentOf:+> (leaf := Video(title="Leaf", own_langs="fr"));

    init = LangRollup();
    gp spawn init;
    print(
        f"initial  leaf={leaf.available_langs} "
        f"parent={pa.available_langs} "
