"""InferencePool ancestry through virtual AgentgatewayModel failover targets.

Demonstrates gateway-to-pool reachability: a direct backend-ref walk misses
virtual-model failover chains; a failover-aware propagator credits every gateway
that can route traffic to the pool.
"""

node Gateway {
    has name: str = "";
}

node AgentgatewayModel {
    has name: str = "";
    has is_virtual: bool = False;
}

node InferencePool {
    has name: str = "";
    has direct_parents: list[str] = [];
    has full_parents: list[str] = [];
}

edge AttachedTo { }

edge FailoverTarget { }

edge BackendRef { }

walker DirectBackendIndexer {
    has gateway_name: str = "";

    can start with Gateway entry {
        self.gateway_name = here.name;
        visit [->:AttachedTo:->] else { disengage; };
    }

    can on_model with AgentgatewayModel entry {
        if here.is_virtual {
            disengage;
        }
        visit [->:BackendRef:->] else { disengage; };
    }

    can on_pool with InferencePool entry {
        if self.gateway_name not in here.direct_parents {
            here.direct_parents.append(self.gateway_name);
        }
        disengage;
    }
}

walker AncestorPropagator {
    has gateway_name: str = "";
    has seen_models: list[str] = [];

    can start with Gateway entry {
        self.gateway_name = here.name;
        visit [->:AttachedTo:->] else { disengage; };
    }

    can descend with AgentgatewayModel entry {
        if here.name in self.seen_models {
            disengage;
        }
        self.seen_models.append(here.name);
        if here.is_virtual {
            visit [->:FailoverTarget:->] else { disengage; };
        } else {
            visit [->:BackendRef:->] else { disengage; };
        }
    }

    can register with InferencePool entry {
        if self.gateway_name not in here.full_parents {
            here.full_parents.append(self.gateway_name);
        }
        disengage;
    }
}

with entry {
    pool = InferencePool(name="llama-pool");
    local_llama = AgentgatewayModel(name="local-llama", is_virtual=False);
    resilient = AgentgatewayModel(name="resilient-model", is_virtual=True);
    public_gw = Gateway(name="public-gateway");
    internal_gw = Gateway(name="internal-gateway");

    public_gw +>:AttachedTo:+> resilient;
    resilient +>:FailoverTarget:+> local_llama;
    internal_gw +>:AttachedTo:+> local_llama;
    local_llama +>:BackendRef:+> pool;

    root ++> public_gw;
    root ++> internal_gw;
    root ++> resilient;
    root ++> local_llama;
    root ++> pool;

    public_gw spawn DirectBackendIndexer();
    internal_gw spawn DirectBackendIndexer();
    print(f"Direct index (misses failover): {pool.direct_parents}");

    public_gw spawn AncestorPropagator();
    internal_gw spawn AncestorPropagator();
    print(f"Failover-aware index: {pool.full_parents}");
}

"""Startup reliability orchestration: phased bootstrap with compatibility admission, dependency lanes, and bounded recovery."""

node StartupPhase {
    has phase_name: str = "";
    has status: str = "pending";
    has reason_code: str = "";
}

node RuntimeComponent {
    has component_name: str = "";
    has lane: str = "base";
    has compat_status: str = "unknown";
    has admitted: bool = False;
    has available: bool = True;
}

node CompatIdentity {
    has app_version: str = "";
    has r_version: str = "";
    has arch: str = "";
    has cache_digest: str = "";
}

edge DependsOn { }
edge RequiresCompat { has expected_digest: str = ""; }

walker StartupOrchestrator {
    has phases_done: int = 0;
    has workbench_ready: bool = False;

    can start with Root entry {
        print("=== Startup orchestration begin ===");
        visit [-->[?:StartupPhase]];
        visit [-->[?:RuntimeComponent]];
    }

    can advance with StartupPhase entry {
        here.status = "active";
        print(f"  [{here.phase_name}] entering");
        visit [->:RequiresCompat:->];
        here.status = "complete";
        self.phases_done += 1;
        if here.phase_name == "WORKBENCH_READY" {
            self.workbench_ready = True;
        }
        visit [-->[?:StartupPhase]] else {
            disengage;
        }
    }

    can gate with CompatIdentity entry {
        print(f"    compat identity: R={here.r_version} arch={here.arch} digest={here.cache_digest}");
    }

    can admit with RuntimeComponent entry {
        verdict = "compatible";
        if not here.available {
            verdict = "requires_user_action";
        } elif here.compat_status == "stale" {
            verdict = "cache_stale";
        } elif here.compat_status == "mismatch" {
            verdict = "runtime_manifest_mismatch";
        }
        here.admitted = verdict == "compatible";
        lane_tag = here.lane.upper();
        admit_label = "ADMIT" if here.admitted else "REJECT";
        print(f"    [{lane_tag}] {here.component_name}: {admit_label} ({verdict})");
        visit [->:DependsOn:->];
    }
}

walker RecoveryPatrol {
    has visited_keys: list[str] = [];
    has recovery_steps: int = 0;
    has halted: bool = False;

    can start with Root entry {
        print("=== Recovery patrol (cycle-bounded) ===");
        visit [-->[?:RuntimeComponent]];
    }

    can probe with RuntimeComponent entry {
        key = here.component_name;
        for existing in self.visited_keys {
            if existing == key {
                print(f"  [HALT] cycle detected at {key} — Needs Attention");
                self.halted = True;
                disengage;
            }
        }
        self.visited_keys.append(key);
        if here.compat_status == "repairable" {
            self.recovery_steps += 1;
            print(f"  [REPAIR] {here.component_name} (step {self.recovery_steps})");
        } elif here.compat_status == "exhausted" {
            print(f"  [STOP] {here.component_name} recovery exhausted — Needs Attention");
            self.halted = True;
            disengage;
        } else {
            print(f"  [SKIP] {here.component_name} not repairable");
        }
        visit [->:DependsOn:->] else {
            disengage;
        }
    }
}

with entry {
    identity = CompatIdentity(
        app_version="0.9.0",
        r_version="4.4.1",
        arch="aarch64",
        cache_digest="sha256:abc"
    );

    cold = StartupPhase(phase_name="COLD");
    discovering = StartupPhase(phase_name="DISCOVERING");
    compat_check = StartupPhase(phase_name="COMPATIBILITY_CHECK");
    base_ready = StartupPhase(phase_name="BASE_RUNTIME_READY");
    workbench = StartupPhase(phase_name="WORKBENCH_READY");

    base_r = RuntimeComponent(
        component_name="BaseR",
        lane="base",
        compat_status="compatible"
    );
    ark = RuntimeComponent(
        component_name="Ark",
        lane="base",
        compat_status="compatible"
    );
    agent_pkgs = RuntimeComponent(
        component_name="AgentPackages",
        lane="agent",
        compat_status="stale"
    );
    provider = RuntimeComponent(
        component_name="Provider",
        lane="provider",
        compat_status="compatible",
        available=False
    );
    stale_cache = RuntimeComponent(
        component_name="RuntimeCache",
        lane="base",
        compat_status="repairable"
    );
    broken_bridge = RuntimeComponent(
        component_name="BridgeTransport",
        lane="base",
        compat_status="exhausted"
    );

    root ++> identity;
    root ++> cold ++> discovering ++> compat_check ++> base_ready ++> workbench;

    compat_check +>:RequiresCompat(expected_digest="sha256:abc"):+> identity;
    base_ready +>:RequiresCompat(expected_digest="sha256:abc"):+> identity;

    base_r +>:DependsOn:+> ark;
    ark +>:DependsOn:+> agent_pkgs;
    root ++> base_r ++> ark ++> agent_pkgs;
    root ++> provider;

    stale_cache +>:DependsOn:+> broken_bridge;
    broken_bridge +>:DependsOn:+> stale_cache;
    root ++> stale_cache;

    orch = StartupOrchestrator();
    root spawn orch;

    print(f"--- phases completed: {orch.phases_done}, workbench ready: {orch.workbench_ready} ---");
    print(f"--- base R admitted: {base_r.admitted}, agent lane admitted: {agent_pkgs.admitted}, provider admitted: {provider.admitted} ---");

    patrol = RecoveryPatrol();
    root spawn patrol;
    print(f"--- recovery steps: {patrol.recovery_steps}, halted: {patrol.halted} ---");
}

"""Cloud Streams subscriber retry policy bypass: failed dispatches recurse with no backoff.

Models neuroglia-io/cloud-streams#131 — RetryDispatchAsync and DispatchAsync mutually
recurse, resetting Polly counters and inflating TotalDeliveryFailures instead of honoring
maxAttempts, backoffDuration, and circuitBreaker settings.
"""

node RetryPolicy {
    has max_attempts: int = 3;
    has backoff_seconds: int = 3;
    has break_after: int = 3;
    has break_duration_seconds: int = 5;
}

node Subscription {
    has name: str = "";
    has subscriber_uri: str = "";
    has policy: RetryPolicy = RetryPolicy();
    has available: bool = True;
}

node Subscriber {
    has uri: str = "";
    has returns_success: bool = False;
}

node DispatchAttempt {
    has offset: int = 0;
    has http_status: int = 503;
}

edge RetryToDispatch { }
edge DispatchToRetry { }
edge DeliversTo { has since_offset: int = 0; }

walker BrokenBroker {
    has delivery_failures: int = 0;
    has policy_builds: int = 0;
    has attempt_in_policy: int = 0;
    has recursion_depth: int = 0;
    has max_demo_depth: int = 6;

    can start with Root entry {
        print("=== Broken path: mutual recursion bypasses retry policy ===");
        visit [-->];
    }

    can retry_dispatch with Subscription entry {
        self.policy_builds += 1;
        self.attempt_in_policy = 0;
        print(
            f"RetryDispatch: fresh Polly policy #{self.policy_builds} "
            f"(maxAttempts={here.policy.max_attempts} never reached)"
        );
        visit [->:RetryToDispatch:->] else { disengage; };
    }

    can dispatch_async with DispatchAttempt entry {
        self.recursion_depth += 1;
        self.attempt_in_policy += 1;
        self.delivery_failures += 1;
        outcome = "FAIL" if here.http_status >= 400 else "OK";
        print(
            f"  DispatchAsync(retryOnError=false) depth={self.recursion_depth} "
            f"status={here.http_status} [{outcome}] "
            f"policy_attempt={self.attempt_in_policy} "
            f"total_failures={self.delivery_failures}"
        );
        if here.http_status >= 400 {
            if self.recursion_depth >= self.max_demo_depth {
                print(
                    f"  Demo cap at depth {self.max_demo_depth}; "
                    f"real broker recurses with NO backoff and NO cap"
                );
                disengage;
            }
            visit [->:DispatchToRetry:->] else { disengage; };
        } else {
            visit [-->];
        }
    }
}

walker PolicyBroker {
    has attempts: int = 0;
    has delivery_failures: int = 0;
    has consecutive_failures: int = 0;
    has circuit_open: bool = False;

    can start with Root entry {
        print("=== Correct path: single policy governs bounded retries ===");
        visit [-->];
    }

    can apply_policy with Subscription entry {
        if self.circuit_open {
            print(
                f"Circuit OPEN — delivery paused to {here.subscriber_uri} "
                f"for {here.policy.break_duration_seconds}s"
            );
            disengage;
        }
        while self.attempts < here.policy.max_attempts {
            self.attempts += 1;
            self.delivery_failures += 1;
            self.consecutive_failures += 1;
            print(
                f"  Polly attempt {self.attempts}/{here.policy.max_attempts} "
                f"-> {here.subscriber_uri} [503 FAIL]"
            );
            if self.consecutive_failures >= here.policy.break_after {
                self.circuit_open = True;
                print(
                    f"  Circuit breaker opened after "
                    f"{here.policy.break_after} consecutive failures"
                );
                break;
            }
            if self.attempts < here.policy.max_attempts {
                print(
                    f"  Backoff: waiting {here.policy.backoff_seconds}s "
                    f"before next attempt"
                );
            }
        }
        print(
            f"Policy stopped after {self.attempts} real attempts, "
            f"failures={self.delivery_failures}, "
            f"circuit_open={self.circuit_open}"
        );
        visit [-->];
    }
}

with entry {
    failing_sub = Subscriber(
        uri="http://localhost:8888/some-endpoint",
        returns_success=False
    );
    sub = Subscription(
        name="all-events",
        subscriber_uri="http://localhost:8888/some-endpoint",
        policy=RetryPolicy(
            max_attempts=3,
            backoff_seconds=3,
            break_after=3,
            break_duration_seconds=5
        )
    );
    attempt = DispatchAttempt(offset=-1, http_status=503);

    root ++> sub;
    sub +>:RetryToDispatch:+> attempt;
    attempt +>:DispatchToRetry:+> sub;
    sub +>:DeliversTo(since_offset=-1):+> failing_sub;

    root spawn BrokenBroker();
    root spawn PolicyBroker();
}

"""Descendant subagent permission routing: session trees, hidden child requests, and policy delegation."""

node Conversation {
    has title: str = "";
    has approval_policy: str = "manual";
}

node Session {
    has session_id: str = "";
    has is_busy: bool = True;
    has is_root: bool = False;
}

node PermissionRequest {
    has pattern: str = "";
    has permission_type: str = "external_directory";
    has resolved: bool = False;
    has resolution: str = "";
    has surfaced: bool = False;
}

edge Owns { }
edge Spawns { }
edge Awaits { }

walker LegacyEventFilter {
    has surfaced_count: int = 0;

    can start with Conversation entry {
        visit [->:Owns:->];
    }

    can inspect with Session entry {
        if not here.is_root {
            disengage;
        }
        visit [->:Awaits:->] else { disengage; };
    }

    can handle with PermissionRequest entry {
        here.surfaced = True;
        self.surfaced_count += 1;
        print(f"[legacy] surfaced {here.permission_type} {here.pattern}");
    }
}

walker DeadlockProbe {
    has root_busy: bool = False;
    has unresolved_descendant_requests: int = 0;
    has visited_ids: list[str] = [];

    can start with Conversation entry {
        visit [->:Owns:->];
    }

    can scan with Session entry {
        if here.session_id in self.visited_ids {
            disengage;
        }
        self.visited_ids.append(here.session_id);
        if here.is_root {
            self.root_busy = here.is_busy;
        }
        visit [->:Awaits:->];
        visit [->:Spawns:->] else { disengage; };
    }

    can tally with PermissionRequest entry {
        if not here.resolved {
            self.unresolved_descendant_requests += 1;
        }
    }
}

walker PermissionRouter {
    has owner_policy: str = "manual";
    has auto_resolved: int = 0;
    has manual_surfaced: int = 0;
    has visited_ids: list[str] = [];

    can start with Conversation entry {
        self.owner_policy = here.approval_policy;
        print(f"[router] inheriting policy '{self.owner_policy}' for descendants");
        visit [->:Owns:->];
    }

    can descend with Session entry {
        if here.session_id in self.visited_ids {
            disengage;
        }
        self.visited_ids.append(here.session_id);
        visit [->:Awaits:->];
        visit [->:Spawns:->] else { disengage; };
    }

    can route with PermissionRequest entry {
        if self.owner_policy == "auto_approve" {
            here.resolved = True;
            here.resolution = "allow";
            self.auto_resolved += 1;
            print(f"[router] auto-approved descendant {here.permission_type} {here.pattern}");
        } else {
            here.surfaced = True;
            self.manual_surfaced += 1;
            print(f"[router] surfaced descendant {here.permission_type} {here.pattern} for review");
        }
    }
}

with entry {
    conv = Conversation(title="Designer task run", approval_policy="auto_approve");
    root ++> conv;
    conv +>:Owns:+> (root_ses := Session(session_id="ses_root", is_root=True));
    root_ses +>:Spawns:+> (child_ses := Session(session_id="ses_child"));
    child_ses +>:Spawns:+> (grandchild_ses := Session(session_id="ses_grandchild"));
    child_ses +>:Awaits:+> PermissionRequest(pattern="/root/.cc/*");
    grandchild_ses +>:Awaits:+> PermissionRequest(pattern="/root/.config/*");

    print("=== Before fix: descendant permissions stay hidden ===");
    legacy = LegacyEventFilter();
    root spawn legacy;
    print(f"legacy filter surfaced {legacy.surfaced_count} requests (child tree ignored)");

    before = DeadlockProbe();
    root spawn before;
    print(f"deadlock risk: root_busy={before.root_busy}, "
          f"unresolved descendant requests={before.unresolved_descendant_requests}");

    print("=== After fix: router walks descendants and applies root policy ===");
    router = PermissionRouter();
    root spawn router;
    print(f"router auto-resolved {router.auto_resolved}, manual surfaced {router.manual_surfaced}");

    after = DeadlockProbe();
    root spawn after;
    print(f"after routing: unresolved descendant requests={after.unresolved_descendant_requests}");
}

