"""Cloud Streams subscriber retry policy bypass: failed dispatches recurse with no backoff.

Models neuroglia-io/cloud-streams#131 — RetryDispatchAsync and DispatchAsync mutually
recurse, resetting Polly counters and inflating TotalDeliveryFailures instead of honoring
maxAttempts, backoffDuration, and circuitBreaker settings.
"""

edge RetryToDispatch {
    has label: str = "retry";
}

edge DispatchToRetry {
    has label: str = "dispatch";
}

edge DeliversTo {
    has since_offset: int = 0;
}

node RetryPolicy {
    has max_attempts: int = 3;
    has backoff_seconds: int = 3;
    has break_after: int = 3;
    has break_duration_seconds: int = 5;
}

node Subscription {
    has name: str = "";
    has subscriber_uri: str = "";
    has policy: RetryPolicy = RetryPolicy();
    has available: bool = True;
}

node Subscriber {
    has uri: str = "";
    has returns_success: bool = False;
    has available: bool = True;
}

node DispatchAttempt {
    has offset: int = 0;
    has http_status: int = 503;
    has available: bool = True;
}

walker BrokenBroker {
    has delivery_failures: int = 0;
    has policy_builds: int = 0;
    has attempt_in_policy: int = 0;
    has recursion_depth: int = 0;
    has max_demo_depth: int = 6;

    can start with Root entry {
        print("=== Broken path: mutual recursion bypasses retry policy ===");
        visit [-->];
    }

    can retry_dispatch with Subscription entry {
        self.policy_builds += 1;
        self.attempt_in_policy = 0;
        print(
            f"RetryDispatch: fresh Polly policy #{self.policy_builds} "
            f"(maxAttempts={here.policy.max_attempts} never reached)"
        );
        visit [->:RetryToDispatch:->] else { disengage; };
    }

    can dispatch_async with DispatchAttempt entry {
        self.recursion_depth += 1;
        self.attempt_in_policy += 1;
        self.delivery_failures += 1;
        outcome = "FAIL" if here.http_status >= 400 else "OK";
        print(
            f"  DispatchAsync(retryOnError=false) depth={self.recursion_depth} "
            f"status={here.http_status} [{outcome}] "
            f"policy_attempt={self.attempt_in_policy} "
            f"total_failures={self.delivery_failures}"
        );
        if here.http_status >= 400 {
            if self.recursion_depth >= self.max_demo_depth {
                print(
                    f"  Demo cap at depth {self.max_demo_depth}; "
                    f"real broker recurses with NO backoff and NO cap"
                );
                disengage;
            }
            visit [->:DispatchToRetry:->] else { disengage; };
        } else {
            visit [-->];
        }
    }
}

walker PolicyBroker {
    has attempts: int = 0;
    has delivery_failures: int = 0;
    has consecutive_failures: int = 0;
    has circuit_open: bool = False;

    can start with Root entry {
        print("=== Correct path: single policy governs bounded retries ===");
        visit [-->];
    }

    can apply_policy with Subscription entry {
        if self.circuit_open {
            print(
                f"Circuit OPEN — delivery paused to {here.subscriber_uri} "
                f"for {here.policy.break_duration_seconds}s"
            );
            disengage;
        }
        while self.attempts < here.policy.max_attempts {
            self.attempts += 1;
            self.delivery_failures += 1;
            self.consecutive_failures += 1;
            print(
                f"  Polly attempt {self.attempts}/{here.policy.max_attempts} "
                f"-> {here.subscriber_uri} [503 FAIL]"
            );
            if self.consecutive_failures >= here.policy.break_after {
                self.circuit_open = True;
                print(
                    f"  Circuit breaker opened after "
                    f"{here.policy.break_after} consecutive failures"
                );
                break;
            }
            if self.attempts < here.policy.max_attempts {
                print(
                    f"  Backoff: waiting {here.policy.backoff_seconds}s "
                    f"before next attempt"
                );
            }
        }
        print(
            f"Policy stopped after {self.attempts} real attempts, "
            f"failures={self.delivery_failures}, "
            f"circuit_open={self.circuit_open}"
        );
        visit [-->];
    }
}

with entry {
    failing_sub = Subscriber(
        uri="http://localhost:8888/some-endpoint",
        returns_success=False
    );
    sub = Subscription(
        name="all-events",
        subscriber_uri="http://localhost:8888/some-endpoint",
        policy=RetryPolicy(
            max_attempts=3,
            backoff_seconds=3,
            break_after=3,
            break_duration_seconds=5
        )
    );
    attempt = DispatchAttempt(offset=-1, http_status=503);

    root ++> sub;
    sub +>:RetryToDispatch:+> attempt;
    attempt +>:DispatchToRetry:+> sub;
    sub +>:DeliversTo(since_offset=-1):+> failing_sub;

    root spawn BrokenBroker();
    root spawn PolicyBroker();
}

"""CX local source packages: resolve transitive manifests, detect cycles, and merge build inputs."""

node Project {
    has name: str = "";
    has root_manifest: str = "";
}

node Package {
    has name: str = "";
    has version: str = "";
    has manifest_path: str = "";
    has canonical_path: str = "";
}

node SourceFile {
    has path: str = "";
}

edge DeclaresPackage { }

edge HasSource { }

walker ManifestLoader {
    has ref_chain: list[str] = [];
    has loaded_canonical: list[str] = [];
    has names_seen: dict[str, str] = {};
    has errors: list[str] = [];
    has merged_sources: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can load with Project entry {
        print(f"resolving project '{here.name}' from {here.root_manifest}");
        visit [->:DeclaresPackage:->];
        visit [->:HasSource:->];
    }

    can resolve with Package entry {
        canon = here.canonical_path;
        if canon in self.ref_chain {
            trail = " -> ".join(self.ref_chain + [canon]);
            self.errors.append(f"package reference cycle: {trail}");
            disengage;
        }
        if canon in self.loaded_canonical {
            disengage;
        }
        self.ref_chain.append(canon);
        self.loaded_canonical.append(canon);
        if here.name in self.names_seen {
            if self.names_seen[here.name] != canon {
                prior = self.names_seen[here.name];
                self.errors.append(
                    f"conflicting package '{here.name}': {prior} vs {canon}"
                );
            }
        } else {
            self.names_seen[here.name] = canon;
        }
        print(
            f"  loaded package {here.name} v{here.version} "
            f"({here.manifest_path})"
        );
        visit [->:DeclaresPackage:->];
        visit [->:HasSource:->];
    }

    can unwind with Package exit {
        if self.ref_chain and self.ref_chain[-1] == here.canonical_path {
            self.ref_chain.pop();
        }
    }

    can absorb with SourceFile entry {
        label = here.path;
        if label not in self.merged_sources {
            self.merged_sources.append(label);
            print(f"    merged source {label}");
        }
    }
}

with entry {
    app = Project(name="app", root_manifest="cx.toml");
    php = Package(
        name="php",
        version="0.1.0",
        manifest_path="packages/php/php.toml",
        canonical_path="/workspace/packages/php/php.toml",
    );
    common = Package(
        name="common",
        version="0.1.0",
        manifest_path="packages/common/common.toml",
        canonical_path="/workspace/packages/common/common.toml",
    );
    app +>:DeclaresPackage:+> php;
    php +>:DeclaresPackage:+> common;
    app +>:HasSource:+> SourceFile(path="src/main.cx");
    php +>:HasSource:+> SourceFile(path="packages/php/src/bindings.cx");
    common +>:HasSource:+> SourceFile(path="packages/common/src/log.cx");

    root ++> app;
    loader = ManifestLoader();
    root spawn loader;

    print("--- acyclic composition ---");
    if loader.errors {
        for err in loader.errors {
            print(f"ERROR: {err}");
        }
    } else {
        print("package graph OK");
    }
    print(f"compiler inputs ({len(loader.merged_sources)} files):");
    for src in sorted(loader.merged_sources) {
        print(f"  {src}");
    }

    cycle_app = Project(name="cycle-demo", root_manifest="demo/cycle/cx.toml");
    alpha = Package(
        name="alpha",
        version="0.0.1",
        manifest_path="a.toml",
        canonical_path="/workspace/demo/a.toml",
    );
    beta = Package(
        name="beta",
        version="0.0.1",
        manifest_path="b.toml",
        canonical_path="/workspace/demo/b.toml",
    );
    cycle_app +>:DeclaresPackage:+> alpha;
    alpha +>:DeclaresPackage:+> beta;
    beta +>:DeclaresPackage:+> alpha;

    cycle_loader = ManifestLoader();
    cycle_app spawn cycle_loader;

    print("--- cyclic reference ---");
    if cycle_loader.errors {
        for err in cycle_loader.errors {
            print(f"ERROR: {err}");
        }
    } else {
        print("no cycle detected");
    }
}

