    has executor_label: str = "";
}

node Story(WorkItem) { }

node Task(WorkItem) { }

node Bug(WorkItem) { }

node Epic(WorkItem) { }

node Feature(WorkItem) { }

node UnresolvedRef {
    has ref_text: str = "";
    has number: int = 0;
    has title: str = "";
}

edge HardDependsOn { }

walker PromotionDispatcher {
    has dry_run: bool = False;
    has checking_deps: bool = False;
    has current_blocked: int = 0;
    has current_unresolvable: bool = False;

    can start with Root entry {
        print("dispatcher-poll: scanning Refined items for dependency promotion");
        visit [-->];
    }

    can evaluate with Story | Task | Bug entry {
        if self.checking_deps {
            if not here.resolved {
                self.current_blocked = here.number;
            }
        } else if here.status != "Refined" {
            visit [-->];
        } else {
            self.current_blocked = 0;
            self.current_unresolvable = False;
            self.checking_deps = True;
            visit [->:HardDependsOn:->] else { self.checking_deps = False; };
            self.checking_deps = False;
            if self.current_unresolvable {
                print(f"unresolvable-deps: #{here.number} {here.title}");
            } else if self.current_blocked > 0 {
                print(f"still-blocked-by: #{self.current_blocked} for #{here.number}");
            } else {
                label = here.executor_label if here.executor_label != "" else "executor:cursor";
                if not self.dry_run {
                    here.status = "ReadyForImplementation";
                    here.executor_label = label;
                }
                print(f"promoted: #{here.number} {here.title} label={label}");
            }
            visit [-->];
        }
    }

    can bad_ref with UnresolvedRef entry {
        if self.checking_deps {
            self.current_unresolvable = True;
        }
    }

    can skip_non_executable with Epic | Feature entry {
        if here.status == "Refined" {
            print(f"skipped-non-executable: #{here.number} {here.title}");
        }
        visit [-->];
    }
}

