"""Reference-suite mining: corpora yield fixtures; nest depth beyond two pins walls; unminable patterns defer."""

node Pattern {
    has name: str = "";
    has nest_depth: int = 0;

    def depth_limit() -> int {
        return 2;
    }

    def is_within_boundary() -> bool {
        return self.nest_depth <= self.depth_limit();
    }
}

node ReferenceCorpus {
    has corpus_name: str = "";
}

node VotingFixture(Pattern) {
    has pattern_kind: str = "";
}

node WallPin(Pattern) {
    has wall_kind: str = "";
}

node FutureBlocker {
    has blocker_id: str = "";
    has mined_rank: int = 0;
    has needs_feature: str = "";
}

edge MinedFrom { }
edge DeferredWork { }

walker ReferenceMiner {
    has vote_tally: int = 0;
    has wall_tally: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can sweep with ReferenceCorpus entry {
        visit [->:MinedFrom:->];
    }

    can assess with VotingFixture | WallPin entry {
        if here.is_within_boundary() {
            label = "VOTE";
            self.vote_tally += 1;
        } else {
            label = "WALL";
            self.wall_tally += 1;
        }
        print(f"[{label}] {here.name} depth={here.nest_depth}");
        visit [-->] else { disengage; }
    }
}

walker FutureWorkScanner {
    has blocker_count: int = 0;

    can start with Root entry {
        visit [->:DeferredWork:->];
    }

    can catalog with FutureBlocker entry {
        self.blocker_count += 1;
        print(f"#{here.mined_rank} {here.blocker_id}: needs {here.needs_feature}");
        visit [-->] else { disengage; }
    }
}

