edge DependsOn { }

walker ReleaseReconciler {
    has visited: list[str] = [];
    has sbom_lines: list[str] = [];
    has rejected: bool = False;
    has reject_reason: str = "";

    can start with Root entry {
        print("=== GizOS release reconcile (fail-closed) ===");
        visit [-->];
    }

    can scope with ReleaseBundle entry {
        print(f"Public scope: {here.release_name} [{here.workflow}]");
        visit [->:Includes:->] else { disengage; };
    }

    can map_artifact with ReleaseArtifact entry {
        print(f"  Release artifact: {here.artifact_name} v{here.version}");
        visit [->:Redistributes:->] else { disengage; };
    }

    can audit with VendorPackage entry {
        if not here.is_redistributed {
            disengage;
        }
        if here.spdx_name in self.visited {
            disengage;
        }
        if not here.has_provenance {
            self.rejected = True;
            self.reject_reason = f"{here.spdx_name}@{here.pkg_version} missing provenance";
            print(f"  [REJECT] {self.reject_reason}");
            disengage;
        }
        if not here.has_license_text {
            self.rejected = True;
            self.reject_reason = f"{here.spdx_name}@{here.pkg_version} missing license text";
            print(f"  [REJECT] {self.reject_reason}");
            disengage;
        }
        line = f"{here.spdx_name}@{here.pkg_version} [{here.license_expr}]";
        self.sbom_lines.append(line);
        self.visited.append(here.spdx_name);
        digest_prefix = here.archive_sha256[:16];
        print(f"  [OK] {line} url={here.source_url} sha256={digest_prefix}...");
        visit [->:DependsOn:->] else { disengage; };
    }
}

