        if batch_auditor.verdict != "ALLOW" {
            batch_verdict_bad = "DENY";
            break;
        }
    }
    print(
        f"multi-group schema:read {batch_bad} -> {batch_verdict_bad}"
    );
}

"""Two-fluid pipe stiff drag: model pipe sections as nodes and walk downstream to audit Schiller-Naumann drag stability."""

node PipeSection {
    has name: str = "";
    has section_id: str = "";
    has diameter: float = 0.05;
    has alpha_liquid: float = 0.8;
    has alpha_gas: float = 0.2;
    has u_gas: float = 0.0;
    has u_liquid: float = 1.0;
    has bubble_diameter: float = 0.0024375;
    has drag_coeff: float = 0.44;
    has rho_liquid: float = 1000.0;
    has rho_gas: float = 50.0;
    has area: float = 0.0019635;
    has regime: str = "dispersed_bubble";

    def rel_slip() -> float {
        return self.u_gas - self.u_liquid;
    }

    def corrected_drag_per_length() -> float {
        u_r = self.rel_slip();
        abs_u = u_r if u_r >= 0.0 else -u_r;
        vol_force = 0.75 * self.drag_coeff * self.rho_liquid;
        vol_force = vol_force * self.alpha_gas * self.alpha_gas * abs_u * u_r;
        vol_force = vol_force / self.bubble_diameter;
        return vol_force * self.area;
    }

    def erroneous_drag_per_length() -> float {
        u_r = self.rel_slip();
        abs_u = u_r if u_r >= 0.0 else -u_r;
        f_i = self.drag_coeff * self.bubble_diameter / (4.0 * self.diameter);
        a_i = 6.0 * self.alpha_gas / self.bubble_diameter;
        return f_i * a_i * abs_u * u_r * self.area;
    }

    def drag_stiffness_tau() -> float {
        u_r = self.rel_slip();
        abs_u = u_r if u_r >= 0.0 else -u_r;
        if abs_u < 1.0e-12 {
            return 1.0e30;
        }
        m_g = self.alpha_gas * self.rho_gas * self.area;
        m_l = self.alpha_liquid * self.rho_liquid * self.area;
        if m_g < 1.0e-12 {
            m_g = 1.0e-12;
        }
        if m_l < 1.0e-12 {
            m_l = 1.0e-12;
        }
        K = 0.75 * self.drag_coeff * self.rho_liquid * self.alpha_gas * self.area;
        K = K / self.bubble_diameter;
        inv_mass = 1.0 / m_g + 1.0 / m_l;
        return 1.0 / (K * inv_mass * abs_u);
    }

    def implicit_slip_step(dt: float) -> float {
        u_old = self.rel_slip();
        abs_u = u_old if u_old >= 0.0 else -u_old;
        if abs_u < 1.0e-12 {
            return u_old;
        }
        m_g = self.alpha_gas * self.rho_gas * self.area;
        m_l = self.alpha_liquid * self.rho_liquid * self.area;
        if m_g < 1.0e-12 {
            m_g = 1.0e-12;
        }
        if m_l < 1.0e-12 {
            m_l = 1.0e-12;
        }
        K = 0.75 * self.drag_coeff * self.rho_liquid * self.alpha_gas * self.area;
        K = K / self.bubble_diameter;
        inv_mass = 1.0 / m_g + 1.0 / m_l;
        denom = 1.0 + dt * K * inv_mass * abs_u;
        return u_old / denom;
    }
}

node Pipeline {
    has name: str = "";
    has dt: float = 0.1;
    has section_count: int = 0;
}

edge Downstream { }

walker DragStabilityAuditor {
    has dt: float = 0.1;
    has stable_sections: int = 0;
    has stiff_sections: int = 0;
    has bubble_samples: int = 0;
    has dispersed_samples: int = 0;
    has visited: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can begin with Pipeline entry {
        self.dt = here.dt;
        print(f"Auditing pipeline '{here.name}' ({here.section_count} sections) at dt={self.dt}s");
        visit [->:Downstream:->] else { disengage; };
    }

    can audit with PipeSection entry {
        if here.section_id in self.visited {
            print(f"cycle detected at section {here.name}; disengaging");
            disengage;
        }
        self.visited.append(here.section_id);

        regime = here.regime;
        if regime == "bubble" {
            self.bubble_samples += 1;
        } else if regime == "dispersed_bubble" {
            self.dispersed_samples += 1;
        }

        u_r = here.rel_slip();
        f_correct = here.corrected_drag_per_length();
        f_wrong = here.erroneous_drag_per_length();
        tau_d = here.drag_stiffness_tau();
        force_ratio = f_wrong / f_correct if f_correct != 0.0 else 0.0;
        dt_ratio = self.dt / tau_d;
        stable_label = "STABLE" if dt_ratio < 1.0 else "STIFF";

        if dt_ratio < 1.0 {
            self.stable_sections += 1;
        } else {
            self.stiff_sections += 1;
        }

        print(f"[{stable_label}] {here.name}: F_correct={f_correct:.4f} N/m, F_old={f_wrong:.4f} N/m, force_ratio={force_ratio:.5f}, tau_D={tau_d:.6f}s, dt/tau_D={dt_ratio:.2f}");

        if dt_ratio >= 1.0 {
            u_implicit = here.implicit_slip_step(self.dt);
            print(f"  implicit slip update: u_r {u_r:.4f} -> {u_implicit:.4f} (conservative stiff-source treatment)");
        }

        visit [->:Downstream:->] else { disengage; };
    }
}

with entry {
    D = 0.05;
    A = 3.1415926535 * D * D / 4.0;
    d_b = D * 0.04875;

    riser = Pipeline(name="Tengesdal-12-section-riser", dt=0.1, section_count=3);

    s1 = PipeSection(
        name="riser-base",
        section_id="s0",
        diameter=D,
        area=A,
        alpha_liquid=0.8,
        alpha_gas=0.2,
        u_gas=0.0,
        u_liquid=1.0,
        bubble_diameter=d_b,
        regime="dispersed_bubble"
    );
    s2 = PipeSection(
        name="riser-mid",
        section_id="s1",
        diameter=D,
        area=A,
        alpha_liquid=0.85,
        alpha_gas=0.15,
        u_gas=0.5,
        u_liquid=0.8,
        bubble_diameter=d_b,
        regime="bubble"
    );
    s3 = PipeSection(
        name="riser-top",
        section_id="s2",
        diameter=D,
        area=A,
        alpha_liquid=0.7,
        alpha_gas=0.3,
        u_gas=1.2,
        u_liquid=0.5,
        bubble_diameter=d_b,
        regime="dispersed_bubble"
    );

    root ++> riser;
    riser +>:Downstream:+> s1 +>:Downstream:+> s2 +>:Downstream:+> s3;

    auditor = DragStabilityAuditor(dt=riser.dt);
    root spawn auditor;

    total = auditor.bubble_samples + auditor.dispersed_samples;
    bubble_pct = 100.0 * auditor.bubble_samples / total if total > 0 else 0.0;
    print(f"Regime tally: bubble={auditor.bubble_samples}, dispersed={auditor.dispersed_samples} ({bubble_pct:.0f}% bubble+dispersed samples)");
    print(f"Stability: {auditor.stable_sections} explicit-ok, {auditor.stiff_sections} need implicit drag treatment");
}

