"""LearnM8 classification support: propagate task_type through learners, select cycle metrics, and plan implementation dependencies."""

edge ConfiguredWith { }
edge UsesLearner { }
edge SelectsMetric { }
edge DependsOn { }

node TaskConfig {
    has task_type: str = "regression";
    has dataset: str = "";
}

node Learner {
    has name: str = "";
    has task_type: str = "";
    has backend: str = "";
    def describe() -> str {
        return f"{self.backend}/{self.task_type}";
    }
}

node SklearnLearner(Learner) {
    has backend: str = "sklearn";
    override def describe() -> str {
        family = "Classifier" if self.task_type == "classification" else "Regressor";
        return f"sklearn/{family}";
    }
}

node TorchLearner(Learner) {
    has backend: str = "torch";
    has n_classes: int = 2;
    override def describe() -> str {
        if self.task_type == "regression" {
            return "torch/MSELoss";
        }
        loss = "CrossEntropyLoss" if self.n_classes > 2 else "BCEWithLogitsLoss";
        return f"torch/{loss}";
    }
}

node MetricSuite {
    has metric_name: str = "";
    has applies_to: str = "regression";
}

node EvalCycle {
    has cycle_no: int = 0;
    has n_samples: int = 0;
}

node ImplTask {
    has task_name: str = "";
    has status: str = "pending";
}

walker TaskTypeRollout {
    has active_type: str = "regression";
    has validation_ok: bool = True;

    can start with Root entry {
        print("=== LearnM8 classification rollout ===");
        visit [-->];
    }

    can load_config with TaskConfig entry {
        self.active_type = here.task_type;
        print(f"Config: dataset={here.dataset} task_type={here.task_type}");
        visit [->:ConfiguredWith:->];
        visit [-->];
    }

    can wire_learner with SklearnLearner | TorchLearner entry {
        tag = "OK" if here.task_type == self.active_type else "MISMATCH";
        if tag == "MISMATCH" {
            self.validation_ok = False;
        }
        print(f"[{tag}] wired {here.name}: {here.describe()}");
        visit [-->];
    }

    can run_cycle with EvalCycle entry {
        print(f"--- cycle {here.cycle_no} ({here.n_samples} compounds) ---");
        visit [->:UsesLearner:->];
        visit [->:SelectsMetric:->];
    }

    can attach_learner with SklearnLearner | TorchLearner entry {
        print(f"  training: {here.name} ({here.describe()})");
        visit [->:UsesLearner:->] else { disengage; };
    }

    can score with MetricSuite entry {
        if here.applies_to == self.active_type {
            print(f"  metric: {here.metric_name}");
        } else {
            print(f"  skip: {here.metric_name} (for {here.applies_to})");
        }
        visit [->:SelectsMetric:->] else { disengage; };
    }
}

walker DependencyPlanner {
    has seen: list[str] = [];

    can start with Root entry {
        print("=== implementation dependency order ===");
        visit [->:DependsOn:->];
    }

    can schedule with ImplTask entry {
        if here.task_name in self.seen {
            print(f"[CYCLE] blocked at {here.task_name}");
            disengage;
        }
        self.seen.append(here.task_name);
        print(f"  schedule: {here.task_name} [{here.status}]");
        visit [->:DependsOn:->] else { disengage; };
    }
}

with entry {
    cfg = TaskConfig(task_type="classification", dataset="morgan_fp");
    rf = SklearnLearner(name="RandomForest", task_type="classification");
    xgb = SklearnLearner(name="XGBoost", task_type="classification");
    mlp = TorchLearner(name="MLP", task_type="classification", n_classes=3);
    f1 = MetricSuite(metric_name="F1", applies_to="classification");
    auc = MetricSuite(metric_name="ROC-AUC", applies_to="classification");
    rmse = MetricSuite(metric_name="RMSE", applies_to="regression");
    cycle = EvalCycle(cycle_no=1, n_samples=128);

    root ++> cfg ++> cycle;
    cfg +>:ConfiguredWith:+> rf;
    cfg +>:ConfiguredWith:+> xgb;
    cfg +>:ConfiguredWith:+> mlp;
    cycle +>:UsesLearner:+> rf;
    cycle +>:UsesLearner:+> xgb;
    cycle +>:UsesLearner:+> mlp;
    cycle +>:SelectsMetric:+> f1;
    cycle +>:SelectsMetric:+> auc;
    cycle +>:SelectsMetric:+> rmse;

    t1 = ImplTask(task_name="Task1_base_interfaces", status="done");
    t2 = ImplTask(task_name="Task2_sklearn_learners", status="pending");
    t3 = ImplTask(task_name="Task3_torch_learners", status="pending");
    t4 = ImplTask(task_name="Task4_cycle_metrics", status="pending");
    t5 = ImplTask(task_name="Task5_api_cli", status="pending");
    root +>:DependsOn:+> t1;
