    t1 +>:DependsOn:+> t3;
    t2 +>:DependsOn:+> t4;
    t3 +>:DependsOn:+> t4;
    t4 +>:DependsOn:+> t5;

    root spawn TaskTypeRollout();
    root spawn DependencyPlanner();
}

"""BanyanDB RBAC: explicit-allow authorization with group-scoped role bindings."""

node Principal {
    has username: str = "";
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

node Role {
    has role_name: str = "";
    has schema_read: bool = False;
    has schema_write: bool = False;
    has data_read: bool = False;
    has data_write: bool = False;
    has cluster_read: bool = False;
    has cluster_admin: bool = False;
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

node Group {
    has group_name: str = "";
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

node ApiOperation {
    has method: str = "";
    has permission: str = "";
    has target_group: str = "";
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

edge AssignedRole { }

edge ScopedTo {
    has is_global: bool = False;
}

walker AuthorizationAuditor {
    has pending_op: ApiOperation;
    has verdict: str = "DENY";
    has active_role: Role | None = None;

    def permission_ok(role: Role, perm: str) -> bool {
        if perm == "schema:read" {
            return role.schema_read;
        }
        if perm == "schema:write" {
            return role.schema_write;
        }
        if perm == "data:read" {
            return role.data_read;
        }
        if perm == "data:write" {
            return role.data_write;
        }
        if perm == "cluster:read" {
            return role.cluster_read;
        }
        if perm == "cluster:admin" {
            return role.cluster_admin;
        }
        return False;
    }

    can begin with Principal entry {
        visit [->:AssignedRole:->] else { disengage; };
    }

    can check_role with Role entry {
        if self.permission_ok(here, self.pending_op.permission) {
            self.active_role = here;
            visit [->:ScopedTo:->] else { visit [-->]; };
        } else {
            visit [-->];
        }
    }

    can check_scope with Group entry {
        if self.verdict == "ALLOW" {
            visit [-->];
        } else {
            scope_ok = False;
            if self.pending_op.permission.startswith("cluster:") {
                if here.group_name == "*" {
                    scope_ok = True;
                }
            } else {
                if here.group_name == "*" {
                    scope_ok = True;
                }
                if here.group_name == self.pending_op.target_group {
                    scope_ok = True;
                }
            }
            if scope_ok {
                self.verdict = "ALLOW";
                disengage;
            } else {
                visit [-->];
            }
        }
    }
}

walker GroupRegistryLister {
    has visible_groups: list[str] = [];
    has has_global_schema_read: bool = False;

    can begin with Principal entry {
        visit [->:AssignedRole:->] else { disengage; };
    }

    can collect_roles with Role entry {
        if here.schema_read {
            visit [->:ScopedTo:->] else { visit [-->]; };
        } else {
            visit [-->];
        }
    }

    can note_scope with Group entry {
        if here.group_name == "*" {
            self.has_global_schema_read = True;
        } else {
            if here.group_name not in self.visible_groups {
                self.visible_groups.append(here.group_name);
            }
        }
        visit [-->];
    }
}

walker AllGroupsEnumerator {
    has lister: GroupRegistryLister;

    can start with Root entry {
        visit [-->[?:Group]] else { disengage; };
    }

    can pick with Group entry {
        if here.group_name != "*" {
            if here.group_name not in self.lister.visible_groups {
                self.lister.visible_groups.append(here.group_name);
            }
        }
        visit [-->];
    }
}

