"""BUSCO lineage prefetch: per-chunk redundant CDN downloads vs one shared offline cache."""

node Lineage {
    has name: str = "";
    has download_count: int = 0;
    has cached: bool = False;
}

node BuscoTask {
    has chunk_id: str = "";
    has stage: str = "";
}

edge NeedsLineage { }

walker RedundantBusco {
    has total_downloads: int = 0;

    can start with Root entry {
        print("=== Without --busco_lineages_path: every task hits the CDN ===");
        visit [-->];
    }

    can run_chunk with BuscoTask entry {
        visit [->:NeedsLineage:->];
        visit [-->] else { disengage; };
    }

    can hit_cdn with Lineage entry {
        here.download_count += 1;
        self.total_downloads += 1;
        print(f"  CDN fetch {here.name} (hit #{here.download_count})");
        disengage;
    }
}

walker LineagePrefetch {
    has unique_downloads: int = 0;

    can start with Root entry {
        print("=== BUSCO_DOWNLOAD once per lineage, broadcast via --offline ===");
        visit [-->];
    }

    can scan_tasks with BuscoTask entry {
        visit [->:NeedsLineage:->];
        visit [-->] else { disengage; };
    }

    can download_once with Lineage entry {
        if not here.cached {
            here.cached = True;
            here.download_count += 1;
            self.unique_downloads += 1;
            print(f"  BUSCO_DOWNLOAD {here.name} -> local cache");
        }
        disengage;
    }
}

walker OfflineBusco {
    has reused: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can run_offline with BuscoTask entry {
        label = f"{here.stage}/{here.chunk_id}";
        print(f"  BUSCO offline {label} (--download_path)");
        visit [->:NeedsLineage:->];
        visit [-->] else { disengage; };
    }

    can use_cache with Lineage entry {
        if here.cached {
            self.reused += 1;
        }
        disengage;
    }
}

with entry {
    bacteria = Lineage(name="bacteria_odb10");
    t1 = BuscoTask(chunk_id="raw_01", stage="raw");
    t2 = BuscoTask(chunk_id="raw_02", stage="raw");
    t3 = BuscoTask(chunk_id="filt_01", stage="filtered");
    t4 = BuscoTask(chunk_id="pd_01", stage="purge_dups");
    t5 = BuscoTask(chunk_id="ph_01", stage="purge_haplotigs");

    root ++> t1 ++> t2 ++> t3 ++> t4 ++> t5;

    t1 +>:NeedsLineage:+> bacteria;
    t2 +>:NeedsLineage:+> bacteria;
    t3 +>:NeedsLineage:+> bacteria;
    t4 +>:NeedsLineage:+> bacteria;
    t5 +>:NeedsLineage:+> bacteria;

    flaky = RedundantBusco();
    root spawn flaky;
