"""Declarative game system ordering: LoadAfter and LoadBefore constraints resolved at boot."""

node GameSystem {
    has name: str = "";
    has declare_order: int = 0;
}

edge LoadAfter { }
edge LoadBefore { }

walker PrereqResolver {
    has planning: list[str] = [];
    has error: str = "";

    can resolve with GameSystem entry {
        if self.error != "" {
            disengage;
        }
        if here.name in self.planning {
            self.error = f"build error: ordering cycle at {here.name}";
            disengage;
        }
        self.planning.append(here.name);
        visit [->:LoadAfter:->] else { };
        visit [<--:LoadBefore:--] else { };
    }

    can resolve_exit with GameSystem exit {
        cleaned: list[str] = [];
        for n in self.planning {
            if n != here.name {
                cleaned.append(n);
            }
        }
        self.planning = cleaned;
    }
}

walker BootSorter {
    has boot_order: list[str] = [];
    has placed: list[str] = [];
    has build_error: str = "";

    can start with Root entry {
        visit [-->[?:GameSystem]] else { disengage; };
    }

    can schedule with GameSystem entry {
        if self.build_error != "" {
            disengage;
        }
        if here.name not in self.placed {
            resolver = PrereqResolver();
            here spawn resolver;
            if resolver.error != "" {
                self.build_error = resolver.error;
                disengage;
            }
            self.placed.append(here.name);
            self.boot_order.append(here.name);
        }
        visit [-->[?:GameSystem]] else { disengage; };
    }
}

