}

"""Pactline tracker adapter: spec hierarchy, dependency blocking, frontier promotion, and cycle guard."""

node WorkUnit {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has phase: str = "backlog";
    has triage_label: str = "needs-triage";

    def is_done() -> bool {
        return self.phase == "done";
    }

    def is_claimable() -> bool {
        return (
            self.triage_label == "ready-for-agent"
            and self.phase != "done"
            and self.phase != "wontfix"
        );
    }
}

node Spec(WorkUnit) { }

node Ticket(WorkUnit) {
    has claimed: bool = False;
}

edge ChildOf { }
edge DependsOn { has note: str = ""; }

walker BlockCheck {
    has clear: bool = True;

    can begin with Ticket entry {
        visit [->:DependsOn:->] else { disengage; }
    }

    can check with Ticket entry {
        if not here.is_done() {
            self.clear = False;
            disengage;
        }
    }
}

walker FrontierAuditor {
    has frontier: list[str] = [];
    has promoted: int = 0;

    can start with Root entry {
        print("=== Pactline frontier audit ===");
        visit [-->];
        print(f"Claimable frontier: {self.frontier}");
        print(f"Promoted to ready: {self.promoted}");
    }

    can audit with Spec entry {
        print(f"[SPEC] #{here.year} {here.title}");
        visit [->:ChildOf:->];
        visit [-->];
    }

    can audit with Ticket entry {
        checker = BlockCheck();
        here spawn checker;
        blocked = not checker.clear;
        if here.is_claimable() and not blocked {
            badge = "CLAIM" if here.available else "READY";
            self.frontier.append(here.title);
            print(f"[{badge}] #{here.year} {here.title} phase={here.phase}");
        } else {
            reason = "blocked" if blocked else here.triage_label;
            print(f"[HOLD] #{here.year} {here.title} ({reason})");
        }
        if not blocked and here.is_claimable() and here.phase == "backlog" {
            here.phase = "ready";
            self.promoted += 1;
            print(f"  promoted {here.title} to ready");
        }
        visit [-->];
    }
}

walker CycleGuard {
    has stack: list[str] = [];
    has cycle: bool = False;

    can start with Root entry {
        print("=== Dependency cycle probe ===");
        visit [-->];
        if self.cycle {
            print("Cycle detected in dependency graph");
        } else {
            print("Dependency graph is acyclic");
        }
    }

    can map with Spec entry {
        visit [->:ChildOf:->];
        visit [-->];
