    can dfs with Ticket entry {
        if here.title in self.stack {
            self.cycle = True;
            print(f"[CYCLE] loop at #{here.year} {here.title}");
            disengage;
        }
        self.stack.append(here.title);
        visit [->:DependsOn:->] else { disengage; }
    }

    can unwind with Ticket exit {
        if len(self.stack) > 0 {
            _drop = self.stack.pop();
        }
    }
}

