"""Marvin hourly-check: unbounded issue-queue re-triage burns agent tokens.

Models hourly-check re-walking an open-issue queue with growing per-turn
context, duplicate resolve mandate with fix-issues, watermark skip when the
queue revision is unchanged, and an optional turn ceiling to bound cost.
"""

node Issue {
    has title: str = "";
    has issue_id: int = 0;
    has body_chars: int = 0;
    has resolved: bool = False;
}

node IssueQueue {
    has title: str = "";
    has revision: int = 0;
    has watermark: int = 0;
    has open_count: int = 0;
}

node AgentScript {
    has title: str = "";
    has runs_per_day: int = 0;
    has can_resolve: bool = False;
}

edge Queued { }
edge CompetesWith { has reason: str = ""; }

walker HourlyChecker {
    has turns: int = 0;
    has tokens: int = 0;
    has turn_budget: int = 0;
    has peak_context: int = 0;
    has base_prompt: int = 15000;
    has growth_per_turn: int = 8000;
    has use_watermark: bool = False;
    has label: str = "hourly-check";

    can start with Root entry {
        print(f"=== {self.label} spawn ===");
        visit [-->];
    }

    can scan_queue with IssueQueue entry {
        if self.use_watermark and here.revision == here.watermark {
            print(
                f"[SKIP] '{here.title}' unchanged "
                f"(rev={here.revision}) — cheap detection cycle"
            );
            visit [-->] else { disengage; };
        } else {
            delta = here.revision - here.watermark;
            churn = "CHANGED" if delta > 0 else "STALE";
            print(
                f"[TRIAGE] {here.open_count} issues on '{here.title}' "
                f"({churn}, rev={here.revision}, wm={here.watermark})"
            );
            visit [->:Queued:->];
            visit [-->] else { disengage; };
        }
    }

    can work_issue with Issue entry {
        if self.turn_budget == 0 or self.turns < self.turn_budget {
            self.turns += 1;
            ctx = self.base_prompt + (self.turns * self.growth_per_turn);
            self.tokens += ctx;
            if ctx > self.peak_context {
                self.peak_context = ctx;
            }
            state = "OPEN" if not here.resolved else "RESOLVED";
            print(
                f"  turn {self.turns}: #{here.issue_id} '{here.title}' "
                f"[{state}] +{ctx} tok (peak~{self.peak_context})"
            );
            if self.turn_budget > 0 and self.turns >= self.turn_budget {
                print(
                    f"  [CEILING] turn budget {self.turn_budget} hit — run bounded"
                );
            }
        }
        visit [->:Queued:->] else { disengage; };
    }

    can inspect_scripts with AgentScript entry {
        role = "resolve" if here.can_resolve else "detect";
        print(f"  script '{here.title}' {role}s {here.runs_per_day}x/day");
        visit [->:CompetesWith:->];
        if here.title == "hourly-check" {
            print(f"    overlaps same queue mandate as 'fix-issues'");
        }
        visit [-->] else { disengage; };
    }
}

with entry {
    hourly = AgentScript(title="hourly-check", runs_per_day=24, can_resolve=True);
    fixer = AgentScript(title="fix-issues", runs_per_day=4, can_resolve=True);
