    spec +>:ChildOf:+> triage_hold;
    api +>:DependsOn(note="design before api"):+> design;
    adapter +>:DependsOn(note="api before adapter"):+> api;

    root spawn FrontierAuditor();
    root spawn CycleGuard();
}

"""Declarative game system ordering: LoadAfter and LoadBefore constraints resolved at boot."""

node GameSystem {
    has name: str = "";
    has declare_order: int = 0;
}

edge LoadAfter { }
edge LoadBefore { }

walker BootSorter {
    has boot_order: list[str] = [];
    has placed: list[str] = [];
    has planning: list[str] = [];
    has build_error: str = "";

    can start with Root entry {
        visit [-->];
    }

    can schedule with GameSystem entry {
        if self.build_error != "" {
            disengage;
        }
        if here.name in self.placed {
            visit [-->];
        } else {
            if here.name in self.planning {
                self.build_error = f"build error: ordering cycle at {here.name}";
                disengage;
            }
            self.planning.append(here.name);
            visit [->:LoadAfter:->];
            visit [<-:LoadBefore:<-];
        }
    }

    can schedule_exit with GameSystem exit {
        if self.build_error != "" {
            disengage;
        }
        if here.name not in self.placed {
            cleaned: list[str] = [];
            for n in self.planning {
                if n != here.name {
                    cleaned.append(n);
                }
            }
            self.planning = cleaned;
            self.placed.append(here.name);
            self.boot_order.append(here.name);
        }
        visit [-->];
    }
}

