    } else {
        seq = ", ".join(sorter.boot_order);
        print(f"boot sequence: {seq}");
    }
}

"""Bounded filesystem walk vs bare read_dir recursion — models banso walk-safety gate blind spots."""

node FsEntry {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has name: str = "";
}

node Directory(FsEntry) { }

node File(FsEntry) {
    has bytes: int = 0;
}

node Crate {
    has name: str = "";
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

node WalkCallSite {
    has label: str = "";
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has uses_walkdir: bool = False;
    has uses_read_dir_recursion: bool = False;
    has has_entry_cap: bool = False;
    has has_depth_cap: bool = False;
}

edge Contains {
}

edge Junction {
}

edge Hosts {
}

walker BoundedWalker {
    has max_depth: int = 32;
    has max_entries: int = 100;
    has depth: int = 0;
    has count: int = 0;
    has seen: list[str] = [];
    has log: list[str] = [];
    has fail_reason: str = "";

    can start with Root entry {
        print(f"walk_files_bounded(max_depth={self.max_depth}, max_entries={self.max_entries})");
        visit [-->];
    }

    can descend with Directory entry {
        if self.count >= self.max_entries {
            self.fail_reason = "entry_cap";
            disengage;
        }
        if self.depth >= self.max_depth {
            self.fail_reason = "depth_cap";
            disengage;
        }
        if here.name in self.seen {
            disengage;
        }
        self.seen.append(here.name);
        self.count += 1;
        self.log.append(f"dir/{here.name}");
        self.depth += 1;
        visit [->:Contains:->];
        visit [->:Junction:->];
        self.depth -= 1;
    }

    can scan with File entry {
        if self.count >= self.max_entries {
            self.fail_reason = "entry_cap";
            disengage;
        }
        self.count += 1;
        self.log.append(f"file/{here.name}");
    }
}

walker BareReadDirWalker {
    has count: int = 0;
    has log: list[str] = [];

    can start with Root entry {
        print("bare read_dir recursion (no entry cap, no cycle guard on junctions)");
        visit [-->];
    }

    can recurse with Directory entry {
        self.count += 1;
        self.log.append(f"dir/{here.name}");
        visit [->:Contains:->];
        visit [->:Junction:->];
    }

    can pick_up with File entry {
        self.count += 1;
        self.log.append(f"file/{here.name}");
    }
}

walker WalkSafetyAuditor {
    has gate_flagged: list[str] = [];
    has gate_blind: list[str] = [];
    has truly_unsafe: list[str] = [];

    can start with Root entry {
        print("audit walk-safety gate (WalkDir needle only, no entry-cap check)");
        visit [-->];
    }

    can inspect with Crate entry {
        visit [->:Hosts:->];
        visit [-->];
    }

    can audit with WalkCallSite entry {
        if here.uses_walkdir and (not here.has_depth_cap) {
            self.gate_flagged.append(here.label);
        }
        if here.uses_walkdir and (not here.has_entry_cap) {
            self.gate_blind.append(f"{here.label}:entry_cap_unchecked");
        }
        if here.uses_read_dir_recursion {
            self.gate_blind.append(f"{here.label}:read_dir_recursion_invisible");
        }
        needs_cap = (not here.has_entry_cap) or (not here.has_depth_cap);
        is_unsafe = False;
        if here.uses_read_dir_recursion and needs_cap {
            is_unsafe = True;
        }
        if here.uses_walkdir and needs_cap {
            is_unsafe = True;
        }
        if is_unsafe {
            self.truly_unsafe.append(here.label);
        }
    }
}

