"""DTCR-D1 fact plane: bounded blast-radius over dependency edges with cycle and depth guards."""

node Repository {
    has name: str = "";
    has commit: str = "";
}

node SourceFile {
    has path: str = "";
    has blob_digest: str = "";
}

node Symbol {
    has name: str = "";
    has kind: str = "";
}

node AdapterLane {
    has lane_id: str = "";
    has provider_version: str = "";
    has digest_present: bool = False;
}

edge Declares { }
edge DependsOn { has via: str = ""; }
edge WiresLane { }

walker FactPlaneVerifier {
    has violations: list[str] = [];
    has lanes_checked: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can on_repo with Repository entry {
        print(f"[D1] exact-source-subject {here.name}@{here.commit}");
        visit [-->];
    }

    can admit_lane with AdapterLane entry {
        self.lanes_checked += 1;
        if not here.digest_present {
            self.violations.append("TREE_SITTER_QUERY_DIGEST_ABSENT");
            print(f"  REJECT {here.lane_id}: provider digest absent");
        } else {
            print(f"  adapter {here.lane_id} provider={here.provider_version} ready");
        }
        visit [-->];
    }

    can scan_file with SourceFile entry {
        print(f"  syntax-match {here.path} blob={here.blob_digest}");
        visit [-->];
    }
}

walker BlastRadiusAuditor {
    has max_depth: int = 3;
    has depth: int = 0;
    has visited: list[str] = [];
    has blast_radius: list[str] = [];
    has violations: list[str] = [];

    def sym_key(sym: Symbol) -> str {
        return f"{sym.name}@{sym.kind}";
    }

    def admit_symbol(sym: Symbol) -> bool {
        key = self.sym_key(sym);
        if key in self.visited {
            self.violations.append("CYCLE_PATH_DUPLICATION");
            print(f"  REJECT CYCLE_PATH_DUPLICATION at {key}");
            return False;
        }
        if self.depth > self.max_depth {
            self.violations.append("UNBOUNDED_RECURSIVE_CTE");
            print(f"  REJECT UNBOUNDED_RECURSIVE_CTE at {key}");
            return False;
        }
        self.visited.append(key);
        self.blast_radius.append(key);
        print(f"  blast-radius-path depth={self.depth} symbol={key}");
        return True;
    }

    can start with Symbol entry {
        if not self.admit_symbol(here) {
            disengage;
        }
        next_depth = self.depth + 1;
        self.depth = next_depth;
        visit [->:DependsOn:->] else { disengage; };
    }

    can ripple with Symbol entry {
        if not self.admit_symbol(here) {
            disengage;
        }
        next_depth = self.depth + 1;
        self.depth = next_depth;
        visit [->:DependsOn:->] else { disengage; };
    }

    can step_back with Symbol exit {
        prev_depth = self.depth - 1;
        self.depth = prev_depth if prev_depth >= 0 else 0;
    }
}

