}

"""MaveDB relationship seals: block accidental lazy traversal on hot edges while
permission rules and explicit eager loads keep working, including cascade delete."""

node Collection {
    has name: str = "";
}

node ScoreSet {
    has urn: str = "";
}

node ScoreCalibration {
    has method: str = "";
}

node Member {
    has handle: str = "";
}

node Variant {
    has hgvs: str = "";
}

edge Owns { }
edge Calibrates { }
edge UserAssoc { }
edge MapsTo { }

walker PermissionProbe {
    has checks: int = 0;

    can start with Root entry {
        visit [-->[?:Collection]];
    }

    can audit_collection with Collection entry {
        print(f"permission rule on collection {here.name}");
        visit [->:UserAssoc:->];
        visit [-->] else { disengage; };
    }

    can audit_member with Member entry {
        self.checks += 1;
        print(f"  permission read: member {here.handle}");
        visit [-->] else { disengage; };
    }

    can audit_calibration with ScoreCalibration entry {
        self.checks += 1;
        print(f"  permission read: calibration {here.method}");
        visit [->:Calibrates:->];
    }

    can audit_score_set with ScoreSet entry {
        print(f"  permission read: score_set {here.urn} (unsealed Calibrates)");
        visit [-->] else { disengage; };
    }
}

walker StreamExporter {
    has eager_loads: list[str] = [];
    has rows: int = 0;
    has violations: int = 0;

    def edge_allowed(edge_name: str) -> bool {
        if edge_name == "Calibrates" or edge_name == "UserAssoc" {
            return True;
        }
        return edge_name in self.eager_loads;
    }

    can start with Root entry {
        visit [-->[?:Collection]];
    }

    can export_collection with Collection entry {
        if self.edge_allowed("Owns") {
            visit [->:Owns:->];
        } else {
            print(f"InvalidRequestError: Owns not eager-loaded for {here.name}");
            self.violations += 1;
        }
        visit [-->] else { disengage; };
    }

    can export_score_set with ScoreSet entry {
        self.rows += 1;
        print(f"  stream row: {here.urn}");
        visit [-->] else { disengage; };
    }

    can export_variant with Variant entry {
        if self.edge_allowed("MapsTo") {
            visit [->:MapsTo:->];
        } else {
            print(f"InvalidRequestError: MapsTo not eager-loaded for {here.hgvs}");
            self.violations += 1;
        }
        visit [-->] else { disengage; };
    }

    can export_mapped with Variant entry {
        label = here.hgvs;
        print(f"  mapped variant: {label}");
        visit [-->] else { disengage; };
    }
}

walker CascadePurge {
    has deleted: int = 0;

    can start with Root entry {
        visit [-->[?:Collection]];
    }

    can purge_collection with Collection entry {
        print(f"cascade: explicit eager Owns on {here.name}");
        visit [->:Owns:->];
        visit [-->] else { disengage; };
    }

    can purge_score_set with ScoreSet entry {
        visit [<--:Calibrates:--] else { };
        print(f"cascade: deleting score_set {here.urn}");
        del here;
        self.deleted += 1;
        visit [-->] else { disengage; };
    }
}

with entry {
    bench = Collection(name="benchmark");
    member = Member(handle="curator");
    primary = ScoreSet(urn="urn:mave:score-set:1");
    spare = ScoreSet(urn="urn:mave:score-set:2");
    cal = ScoreCalibration(method="spearman");
    parent_var = Variant(hgvs="c.123A>G");
    child_var = Variant(hgvs="c.456C>T");

