    bench +>:UserAssoc:+> member;
    bench +>:Owns:+> primary;
    bench +>:Owns:+> spare;
    cal +>:Calibrates:+> primary;
    root ++> cal;
    root ++> parent_var;
    parent_var +>:MapsTo:+> child_var;

    print("=== permission probe (no eager loads; unsealed edges only) ===");
    root spawn PermissionProbe();

    print("=== stream export without eager loads (sealed edges should block) ===");
    blocked = StreamExporter();
    root spawn blocked;

    print("=== stream export with explicit eager loads (sealed edges allowed) ===");
    eager = StreamExporter(eager_loads=["Owns", "MapsTo"]);
    root spawn eager;

    print("=== cascade delete with explicit eager Owns ===");
    root spawn CascadePurge();

    print(f"blocked violations={blocked.violations}, eager rows={eager.rows}, "
          f"purged={CascadePurge.deleted}");
}

