    primary = ScoreSet(urn="urn:mave:score-set:1");
    spare = ScoreSet(urn="urn:mave:score-set:2");
    cal = ScoreCalibration(method="spearman");
    parent_var = Variant(hgvs="c.123A>G");
    child_var = MappedVariant(hgvs="c.456C>T");

    root ++> bench;
    bench +>:UserAssoc:+> member;
    bench +>:Owns:+> primary;
    bench +>:Owns:+> spare;
    cal +>:Calibrates:+> primary;
