    j_ben = Judge(name="Ben", severity=-0.15, period=1);
    j_cara = Judge(name="Cara", severity=0.10, period=1);

    r1 = Rating(score=4, period=1, criterion="clarity");
    r2 = Rating(score=3, period=1, criterion="completeness");
    r3 = Rating(score=3, period=1, criterion="clarity");
    r4 = Rating(score=4, period=2, criterion="clarity");

    root ++> alpha ++> beta ++> gamma;
    root ++> issue_100 ++> issue_250;

    j_ada +>:MemberOf:+> alpha;
    j_ada_p2 +>:MemberOf:+> alpha;
    j_ben +>:MemberOf:+> beta;
    j_cara +>:MemberOf:+> gamma;

    j_ada +>:Contributed:+> r1;
    r1 +>:ObservedOn:+> issue_100;

    j_ben +>:Contributed:+> r2;
    r2 +>:ObservedOn:+> issue_100;

    j_cara +>:Contributed:+> r3;
    r3 +>:ObservedOn:+> issue_250;

    j_ada_p2 +>:Contributed:+> r4;
    r4 +>:ObservedOn:+> issue_250;

    auditor = ParameterRecoveryValidator();
    root spawn auditor;

    print(f"--- Summary: recovered={auditor.recovered} "
          f"non_identifiable={auditor.flagged} "
          f"sparse_design=connected ---");
}

