"""Enterprise judge-effect validation: recover issue standing, task difficulty, and judge severity over a sparse connected multi-judge rating graph."""

node Issue {
    has title: str = "";
    has standing: float = 0.0;
    has year: int = 0;
    has available: bool = True;
}

node TaskRevision {
    has name: str = "";
    has difficulty: float = 0.0;
    has year: int = 0;
    has available: bool = True;
}

node Judge {
    has name: str = "";
    has severity: float = 0.0;
    has period: int = 0;
    has year: int = 0;
    has available: bool = True;
}

node JudgeFamily {
    has name: str = "";
    has effect: float = 0.0;
    has year: int = 0;
    has available: bool = True;
}

node Rating {
    has score: int = 0;
    has period: int = 0;
    has criterion: str = "";
    has year: int = 0;
    has available: bool = True;
}

edge MemberOf { }
edge Contributed { }
edge ObservedOn { }

walker ParameterRecoveryValidator {
    has family_effect: float = 0.0;
    has judge_label: str = "";
    has judge_severity: float = 0.0;
    has issue_title: str = "";
    has issue_standing: float = 0.0;
    has obs_score: int = 0;
    has obs_criterion: str = "";
    has recovered: int = 0;
    has flagged: int = 0;
    has guard: list[str] = [];

    can start with Root entry {
        print("=== Enterprise parameter-recovery audit (sparse multi-judge) ===");
        visit [-->];
    }

    can audit_family with JudgeFamily entry {
        fam_key = f"family:{here.name}";
        if fam_key in self.guard {
            disengage;
        }
        self.guard.append(fam_key);
        self.family_effect = here.effect;
        print(f"[Family] {here.name} family_effect={here.effect}");
        visit [<--:MemberOf:<--];
        visit [-->] else { disengage; };
    }

    can audit_judge with Judge entry {
        judge_key = f"judge:{here.name}:p{here.period}";
        if judge_key in self.guard {
            disengage;
        }
        self.guard.append(judge_key);
        self.judge_label = here.name;
        self.judge_severity = here.severity + self.family_effect;
        drift_label = "stable" if here.period == 1 else "temporal_drift";
        print(f"  Judge {here.name} period={here.period} ({drift_label}) "
              f"effective_severity={self.judge_severity}");
        visit [->:Contributed:->];
        visit [-->] else { disengage; };
    }

    can inspect_rating with Rating entry {
        rate_key = f"rating:{self.judge_label}:{here.period}:{here.criterion}";
        if rate_key in self.guard {
            disengage;
        }
        self.guard.append(rate_key);
        self.obs_score = here.score;
        self.obs_criterion = here.criterion;
        visit [->:ObservedOn:->] else { disengage; };
    }

    can gather_issue with Issue entry {
        issue_key = f"issue:{here.title}";
        if issue_key in self.guard {
            disengage;
        }
        self.guard.append(issue_key);
        self.issue_title = here.title;
        self.issue_standing = here.standing;
        visit [-->];
    }

    can recover_params with TaskRevision entry {
        latent = self.issue_standing - here.difficulty + self.judge_severity;
        approx = int(latent + 3.0);
        delta = approx - self.obs_score;
        if delta < 0 {
            delta = -delta;
        }
        verdict = "RECOVERED" if delta <= 1 else "NONID";
        if verdict == "RECOVERED" {
            self.recovered += 1;
        } else {
            self.flagged += 1;
        }
        print(f"    [{verdict}] {self.issue_title}/{here.name} "
              f"criterion={self.obs_criterion} obs={self.obs_score} "
              f"recovered~{approx} (standing={self.issue_standing} "
              f"diff={here.difficulty} sev={self.judge_severity})");
        visit [-->] else { disengage; };
    }
}

with entry {
    alpha = JudgeFamily(name="Alpha", effect=0.20);
    beta = JudgeFamily(name="Beta", effect=-0.10);
    gamma = JudgeFamily(name="Gamma", effect=0.05);

    task_a = TaskRevision(name="TASK-A-rev2", difficulty=0.40);
