"""Quick-batch coordinator: capacity-limited task dispatch, dependency gates, and ordered merge verification."""

node BatchHost {
    has name: str = "gsd-quick-batch";
    has capacity: int = 2;
    has isolation: str = "harness-worktree";
}

node QuickTask {
    has title: str = "";
    has status: str = "pending";
    has merge_rank: int = 0;
    has verified: bool = False;
}

edge DependsOn { }
edge InBatch { }

walker CycleGuard {
    has trail: list[str] = [];
    has safe: bool = True;

    can start with Root entry {
        visit [->:InBatch:->];
    }

    can enter with BatchHost entry {
        visit [->:InBatch:->];
    }

    can probe with QuickTask entry {
        label = here.title;
        for prior in self.trail {
            if prior == label {
                self.safe = False;
                print(f"[CYCLE] dependency loop at {label}");
                disengage;
            }
        }
        self.trail.append(label);
        visit [->:DependsOn:->] else { };
        trimmed: list[str] = [];
        for prior in self.trail {
            if prior != label {
                trimmed.append(prior);
            }
        }
        self.trail = trimmed;
        visit [-->];
    }

    can leave with BatchHost exit {
        if self.safe {
            print("[AUDIT] dependency graph acyclic");
        }
    }
}

walker Dispatcher {
    has active: int = 0;
    has cap: int = 2;

    can start with Root entry {
        visit [->:InBatch:->];
    }

    can boot with BatchHost entry {
        cap_val = 1 if here.isolation == "none" else here.capacity;
        self.cap = cap_val;
        print(f"[BATCH] {here.name} jobs={self.cap} isolation={here.isolation}");
        visit [->:InBatch:->];
    }

    can dispatch with QuickTask entry {
        blocked = False;
        for dep in [-->:DependsOn:--] {
            if dep.status != "merged" or not dep.verified {
                blocked = True;
            }
        }
        if not blocked and here.status == "pending" and self.active < self.cap {
            here.status = "running";
            self.active += 1;
            print(f"[DISPATCH] {here.title} (active {self.active}/{self.cap})");
        }
        visit [-->];
    }
}

walker MergeVerifier {
    has target_rank: int = 0;

    can start with Root entry {
        visit [->:InBatch:->];
    }

    can reconcile with BatchHost entry {
        picked: QuickTask = None;
        for task in [->:InBatch:->] {
            if task.merge_rank == self.target_rank and task.status == "running" {
                picked = task;
            }
        }
        if picked is not None {
            picked.status = "merged";
            picked.verified = True;
            print(f"[MERGE] #{picked.merge_rank} {picked.title} verified=True");
        } else {
            print(f"[MERGE] rank {self.target_rank} not ready");
        }
        disengage;
    }
}

walker StatusReporter {
    can start with Root entry {
        visit [->:InBatch:->];
    }

    can summarize with BatchHost entry {
        for task in [->:InBatch:->] {
            gate = "open" if task.verified else "blocked";
            print(f"[STATUS] {task.title} status={task.status} verified={task.verified} gate={gate}");
        }
        disengage;
    }
}

with entry {
    host = BatchHost(name="qb-run", capacity=2, isolation="harness-worktree");
    t_fix = QuickTask(title="fix-lint", merge_rank=0);
    t_test = QuickTask(title="add-tests", merge_rank=1);
    t_api = QuickTask(title="refactor-api", merge_rank=2);
    t_docs = QuickTask(title="update-docs", merge_rank=3);

    root ++> host;
    host +>:InBatch:+> t_fix;
    host +>:InBatch:+> t_test;
    host +>:InBatch:+> t_api;
    host +>:InBatch:+> t_docs;
    t_test +>:DependsOn:+> t_fix;
    t_docs +>:DependsOn:+> t_api;

    root spawn CycleGuard();
    root spawn Dispatcher();
    root spawn MergeVerifier(target_rank=0);
    root spawn MergeVerifier(target_rank=2);
    root spawn Dispatcher();
    root spawn MergeVerifier(target_rank=1);
    root spawn MergeVerifier(target_rank=3);
    root spawn StatusReporter();
}

