"""Deterministic synthetic FX trader replay over a market tape.

Frozen strategy catalog entries bind to traders; a walker advances the
tape bar-by-bar, applies point-in-time rule transitions
S_{t+1} = G(S_t, X_<=t; theta), emits fictional order deltas, and
records contemporaneous strategy-response rows. Cycle guards keep replay
finite when the bar chain is malformed.
"""

edge NextBar { }
edge BoundTo { }
edge TradesPair { }
edge Emits { }

node MarketBar {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has pair: str = "";
    has close_px: float = 0.0;
    has spread: float = 0.0;
    has bar_index: int = 0;
}

node StrategyCatalog {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has strategy_id: int = 0;
    has catalog_sha: str = "";
    has theta_version: str = "";
}

node ResponseEntity {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;

    def row_label() -> str {
        return self.title;
    }
}

node Trader(ResponseEntity) {
    has strategy_id: int = 0;
    has pair: str = "";
    has current_position: float = 0.0;
    has desired_position: float = 0.0;
    has decision_code: str = "INIT";

    override def row_label() -> str {
        return f"trader:{self.title}";
    }
}

node OrderDelta(ResponseEntity) {
    has delta_qty: float = 0.0;
    has bar_index: int = 0;
    has pair: str = "";

    override def row_label() -> str {
        return f"order@{self.bar_index}";
    }
}

walker PopulationReplayer {
    has seen_bars: list[int] = [];
    has current_close: float = 0.0;
    has current_bar_index: int = 0;
    has order_count: int = 0;
    has feature_rows: list[str] = [];

    can start with Root entry {
        print("=== deterministic synthetic-trader population replay ===");
        visit [->:NextBar:->] else { disengage; };
    }

    can advance with MarketBar entry {
        if here.bar_index in self.seen_bars {
            print(f"[CYCLE] refusing re-visit of bar {here.bar_index}");
            disengage;
        }
        self.seen_bars.append(here.bar_index);
        self.current_close = here.close_px;
        self.current_bar_index = here.bar_index;
        print(
            f"[tape t={here.bar_index}] {here.pair} "
            f"close={here.close_px} spread={here.spread}"
        );
        visit [->:TradesPair:->] else { disengage; };
        visit [->:NextBar:->] else { disengage; };
    }

    can decide with Trader entry {
        if here.available == False {
            print(f"  [{here.title}] inactive — skipped");
        } else {
            visit [->:BoundTo:->] else {
                # unbound trader falls back to inline strategy_id only
            };
            target = (
                1.0
                if self.current_close > 1.0855
                else -1.0
                if self.current_close < 1.0850
                else 0.0
            );
            prev_pos = here.current_position;
            here.desired_position = target;
            delta = here.desired_position - prev_pos;
            code = (
                "ENTER_LONG"
                if delta > 0.0
                else "ENTER_SHORT"
                if delta < 0.0
                else "HOLD"
            );
            here.decision_code = code;
            here.current_position = here.desired_position;
            if delta != 0.0 {
                od = OrderDelta(
                    title=f"ord-{here.title}",
                    pair=here.pair,
                    delta_qty=delta,
                    bar_index=self.current_bar_index
                );
                here +>:Emits:+> od;
                self.order_count += 1;
            }
            row = (
                f"{here.strategy_id}|bar={self.current_bar_index}|"
                f"{code}|pos={here.current_position}|dq={delta}"
            );
            self.feature_rows.append(row);
            print(
                f"  [{here.title}] #{here.strategy_id} {code} "
                f"dq={delta} pos={here.current_position}"
            );
        }
    }

    can bind_rules with StrategyCatalog entry {
        short_sha = here.catalog_sha[:12];
        print(
            f"    ruleset {here.theta_version} "
            f"(catalog#{here.strategy_id} sha={short_sha}...)"
        );
    }

    can fingerprint with Trader | OrderDelta entry {
        print(f"    [row] {here.row_label()} available={here.available}");
    }
}

