    has design_name: str = "";
}

node YosysCell {
    has cell_type: str = "";
    has validated: bool = False;
    has imported: bool = False;
    has refuse_reason: str = "";
}

node CircuitElement {
    has kind: str = "";
}

edge Declares { }
edge InNetlist { }
edge GovernedBy { }
edge RealizedAs { }

walker CellValidator {
    has pass_count: int = 0;
    has fail_count: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can announce with CellCatalog entry {
        print(f"=== CellValidator against {here.label} ===");
        visit [->:Declares:->];
        visit [-->];
    }

    can list_row with CatalogEntry entry {
        tag = "realizer" if here.has_realizer else "accept-only";
        print(f"  catalog row {here.cell_type} [{tag}]");
        visit [-->];
    }

    can scan with Netlist entry {
        print(f"--- validating netlist {here.design_name} ---");
        visit [->:InNetlist:->];
    }

    can validate with YosysCell entry {
        cell = here;
        accepted = False;
        realizable = False;
        for row in cell [->:GovernedBy:->] {
            if row.validator_accepts {
                accepted = True;
            }
            if row.has_realizer {
                realizable = True;
            }
        }
        if accepted {
            cell.validated = True;
            self.pass_count += 1;
            status_tag = "REALIZABLE" if realizable else "VALID-ONLY";
            print(f"[VALID/{status_tag}] {cell.cell_type}");
        } else {
            self.fail_count += 1;
            print(f"[REJECT] {cell.cell_type}");
        }
        visit [-->];
