    host +>:InBatch:+> t_docs;
    t_test +>:DependsOn:+> t_fix;
    t_docs +>:DependsOn:+> t_api;

    root spawn CycleGuard();
    root spawn Dispatcher();
    root spawn MergeVerifier(target_rank=0);
    root spawn MergeVerifier(target_rank=2);
    root spawn Dispatcher();
    root spawn MergeVerifier(target_rank=1);
    root spawn MergeVerifier(target_rank=3);
