"""Quick-batch coordinator: capacity-limited dispatch, dependency gates, cycle audit, and ordered merge verification."""

edge DependsOn { }
edge InBatch { }

node BatchHost {
    has name: str = "gsd-quick-batch";
    has capacity: int = 2;
    has isolation: str = "harness-worktree";
}

node QuickTask {
    has title: str = "";
    has status: str = "pending";
    has merge_rank: int = 0;
    has verified: bool = False;
}

walker CycleGuard {
    has trail: list[str] = [];
    has safe: bool = True;

    can start with Root entry {
        visit [-->] else { disengage; }
    }

    can enter with BatchHost entry {
        visit [->:InBatch:->] else { disengage; }
    }

    can probe with QuickTask entry {
        label = here.title;
        for prior in self.trail {
            if prior == label {
                self.safe = False;
                print(f"[CYCLE] dependency loop at {label}");
                disengage;
            }
        }
        self.trail.append(label);
        visit [->:DependsOn:->];
        trimmed: list[str] = [];
        for prior in self.trail {
            if prior != label {
                trimmed.append(prior);
            }
        }
        self.trail = trimmed;
        visit [-->] else { disengage; }
    }

    can leave with BatchHost exit {
        if self.safe {
            print("[AUDIT] dependency graph acyclic");
        }
    }
}

walker Dispatcher {
    has active: int = 0;
    has cap: int = 2;

    can start with Root entry {
        visit [-->] else { disengage; }
    }

    can boot with BatchHost entry {
        cap_val = 1 if here.isolation == "none" else here.capacity;
        self.cap = cap_val;
        print(f"[BATCH] {here.name} jobs={self.cap} isolation={here.isolation}");
        visit [->:InBatch:->] else { disengage; }
    }

    can dispatch with QuickTask entry {
        blocked = False;
        for dep in [->:DependsOn:->] {
            if dep.status != "merged" or not dep.verified {
                blocked = True;
            }
        }
        if not blocked and here.status == "pending" and self.active < self.cap {
            here.status = "running";
            self.active += 1;
            print(f"[DISPATCH] {here.title} (active {self.active}/{self.cap})");
        }
        visit [-->] else { disengage; }
    }
}

walker MergeVerifier {
    has target_rank: int = 0;
    has found: bool = False;

    can start with Root entry {
        visit [-->] else { disengage; }
    }

    can reconcile with BatchHost entry {
        self.found = False;
        visit [->:InBatch:->] else { disengage; }
        if not self.found {
            print(f"[MERGE] rank {self.target_rank} not ready");
        }
        disengage;
    }

    can merge_task with QuickTask entry {
        if (
            here.merge_rank == self.target_rank
            and here.status == "running"
            and not self.found
        ) {
            here.status = "merged";
            here.verified = True;
            self.found = True;
            print(f"[MERGE] #{here.merge_rank} {here.title} verified=True");
        }
    }
}

walker StatusReporter {
    can start with Root entry {
        visit [-->] else { disengage; }
    }

    can summarize with BatchHost entry {
        for task in [->:InBatch:->] {
            gate = "open" if task.verified else "blocked";
            print(f"[STATUS] {task.title} status={task.status} verified={task.verified} gate={gate}");
        }
        disengage;
    }
}

with entry {
    host = BatchHost(name="qb-run", capacity=2, isolation="harness-worktree");
    t_fix = QuickTask(title="fix-lint", merge_rank=0);
    t_test = QuickTask(title="add-tests", merge_rank=1);
    t_api = QuickTask(title="refactor-api", merge_rank=2);
    t_docs = QuickTask(title="update-docs", merge_rank=3);

    root ++> host;
    host +>:InBatch:+> t_fix;
    host +>:InBatch:+> t_test;
    host +>:InBatch:+> t_api;
    host +>:InBatch:+> t_docs;
    t_test +>:DependsOn:+> t_fix;
    t_docs +>:DependsOn:+> t_api;

    root spawn CycleGuard();
    root spawn Dispatcher();
    root spawn MergeVerifier(target_rank=0);
    root spawn MergeVerifier(target_rank=2);
    root spawn Dispatcher();
    root spawn MergeVerifier(target_rank=1);
    root spawn MergeVerifier(target_rank=3);
    root spawn StatusReporter();
}

"""Yosys netlist import: CellCatalog unifies validator acceptance and importer realization."""

node CellCatalog {
    has label: str = "";
}

node CatalogEntry {
    has cell_type: str = "";
    has validator_accepts: bool = True;
    has has_realizer: bool = False;
    has realizer_kind: str = "";
}

node Netlist {
    has design_name: str = "";
}

node YosysCell {
    has cell_type: str = "";
    has validated: bool = False;
    has imported: bool = False;
    has refuse_reason: str = "";
}

node CircuitElement {
    has kind: str = "";
}

edge Declares { }
edge InNetlist { }
edge GovernedBy { }
edge RealizedAs { }

walker CellValidator {
    has pass_count: int = 0;
    has fail_count: int = 0;
    has accepted: bool = False;
    has realizable: bool = False;

    can start with Root entry {
        visit [-->];
    }

    can announce with CellCatalog entry {
        print(f"=== CellValidator against {here.label} ===");
        visit [->:Declares:->];
        visit [-->];
    }

    can list_row with CatalogEntry entry {
        tag = "realizer" if here.has_realizer else "accept-only";
        print(f"  catalog row {here.cell_type} [{tag}]");
        visit [-->];
    }

    can scan with Netlist entry {
        print(f"--- validating netlist {here.design_name} ---");
        visit [->:InNetlist:->];
    }

    can validate with YosysCell entry {
        self.accepted = False;
        self.realizable = False;
        visit [->:GovernedBy:->];
        if self.accepted {
            here.validated = True;
            self.pass_count += 1;
            status_tag = "REALIZABLE" if self.realizable else "VALID-ONLY";
            print(f"[VALID/{status_tag}] {here.cell_type}");
        } else {
            self.fail_count += 1;
            print(f"[REJECT] {here.cell_type}");
        }
        visit [-->];
    }

    can check_row with CatalogEntry entry {
        if here.validator_accepts {
            self.accepted = True;
        }
        if here.has_realizer {
            self.realizable = True;
        }
    }
}

walker NetlistImporter {
    has realized: int = 0;
    has drift_refused: int = 0;
    has mapped: bool = False;
    has current_cell: YosysCell | None = None;

    can start with Root entry {
        visit [-->];
    }

    can scan with Netlist entry {
        print(f"--- importing netlist {here.design_name} ---");
        visit [->:InNetlist:->];
    }

    can map_cell with YosysCell entry {
        if not here.validated {
            visit [-->];
        } else {
            self.current_cell = here;
            self.mapped = False;
            visit [->:GovernedBy:->];
            if not self.mapped {
                self.current_cell.refuse_reason = "importer increment does not yet realize";
                self.drift_refused += 1;
                print(f"[IMPORT-FAIL] {self.current_cell.cell_type}: {self.current_cell.refuse_reason}");
            }
            visit [-->];
        }
    }

    can realize_row with CatalogEntry entry {
        if here.has_realizer and self.current_cell is not None {
            kind = here.realizer_kind;
            if kind == "" {
                kind = here.cell_type;
            }
            elem = CircuitElement(kind=kind);
            self.current_cell +>:RealizedAs:+> elem;
            self.current_cell.imported = True;
            self.realized += 1;
            self.mapped = True;
            print(f"[IMPORT] {self.current_cell.cell_type} -> {kind}");
        }
    }
}

walker ResetCells {
    can start with Netlist entry {
        visit [->:InNetlist:->];
    }

    can reset with YosysCell entry {
        here.validated = False;
        here.imported = False;
        here.refuse_reason = "";
        visit [-->];
    }
}

with entry {
