"""Deterministic strength-aware path selection for candidate routes.

Policy (stable tie-breaks):
1. Shortest hop count wins.
2. Equal length: higher bottleneck (minimum edge strength) wins.
3. Still tied: lexicographically smaller node-name path wins.
Cycles: nodes already on the active path are skipped.
"""

node Milestone {
    has name: str = "";
}

edge Connects {
    has strength: float = 1.0;

    can push_strength with RoutePicker entry {
        visitor.strength_trace.append(self.strength);
    }

    can pop_strength with RoutePicker exit {
        if len(visitor.strength_trace) > 0 {
            visitor.strength_trace.pop();
        }
    }
}

walker RoutePicker {
    has source_name: str = "";
    has target_name: str = "";
    has best_len: int = 999999;
    has best_bottleneck: float = -1.0;
    has best_path: list[str] = [];
    has path_stack: list[str] = [];
    has path_set: dict[str, bool] = {};
    has strength_trace: list[float] = [];
    has found_any: bool = False;

    can start with Root entry {
        visit [-->];
    }

    can explore with Milestone entry {
        if len(self.path_stack) == 0 {
            if here.name != self.source_name {
                visit [-->];
            } else {
                self.reset_trace();
                self.path_stack.append(here.name);
                self.path_set[here.name] = True;
                self.consider_if_target();
                visit [->:Connects:->] else { disengage; };
            }
        } else {
            if here.name in self.path_set {
                disengage;
            } else {
                next_len = len(self.path_stack) + 1;
                if self.found_any and next_len > self.best_len {
                    disengage;
                }
                self.path_stack.append(here.name);
                self.path_set[here.name] = True;
                self.consider_if_target();
                visit [->:Connects:->] else { disengage; };
            }
        }
    }

    can explore with Milestone exit {
        if len(self.path_stack) > 0 {
            last = self.path_stack.pop();
            if last in self.path_set {
                del self.path_set[last];
            }
        }
    }

    def reset_trace() {
        self.path_stack = [];
        self.path_set = {};
        self.strength_trace = [];
    }

    def consider_if_target() {
        if here.name == self.target_name {
            self.consider_path();
        }
    }

    def bottleneck_of_trace() -> float {
        if len(self.strength_trace) == 0 {
            return 0.0;
        }
        bottleneck = self.strength_trace[0];
        for s in self.strength_trace {
            if s < bottleneck {
                bottleneck = s;
            }
        }
        return bottleneck;
    }

    def copy_path() -> list[str] {
        copied: list[str] = [];
        for n in self.path_stack {
            copied.append(n);
        }
        return copied;
    }

    def lex_less(candidate: list[str], incumbent: list[str]) -> bool {
        if len(incumbent) == 0 {
            return True;
        }
        limit = len(candidate);
        if len(incumbent) < limit {
            limit = len(incumbent);
        }
        for i in range(limit) {
            if candidate[i] < incumbent[i] {
                return True;
            }
            if candidate[i] > incumbent[i] {
                return False;
            }
        }
        return len(candidate) < len(incumbent);
    }

    def consider_path() {
        length = len(self.path_stack);
        bottleneck = self.bottleneck_of_trace();
        if length < self.best_len {
            self.best_len = length;
            self.best_bottleneck = bottleneck;
            self.best_path = self.copy_path();
            self.found_any = True;
        } else {
            if length == self.best_len {
                if bottleneck > self.best_bottleneck {
                    self.best_bottleneck = bottleneck;
                    self.best_path = self.copy_path();
                } else {
                    if bottleneck == self.best_bottleneck {
                        if self.lex_less(self.path_stack, self.best_path) {
                            self.best_path = self.copy_path();
                        }
                    }
                }
            }
        }
    }
}

