"""PREL X01 canary pipeline: three PDF-derived product archetypes traverse an execution DAG while a closure monitor audits artifacts and open lanes."""

node Auditable {
    def is_clear() -> bool {
        return True;
    }

    def report_label() -> str {
        return "unknown";
    }
}

node EvidencePacket {
    has locator: str = "";
    has pinned: bool = True;
}

node Canary {
    has name: str = "";
    has mechanism: str = "";
    has falsifier: str = "";
    has build_gate: bool = False;
}

node ArtifactSlot(Auditable) {
    has kind: str = "";
    has ready: bool = False;

    override def is_clear() -> bool {
        return self.ready;
    }

    override def report_label() -> str {
        return f"artifact {self.kind}";
    }
}

node ClosureLane(Auditable) {
    has lane: str = "";
    has satisfied: bool = False;

    override def is_clear() -> bool {
        return self.satisfied;
    }

    override def report_label() -> str {
        return f"{self.lane} lane";
    }
}

edge Feeds {
}

edge Requires {
}

edge Gates {
}

edge DependsOn {
}

walker ClosureMonitor {
    has gaps: list[str] = [];

    can start with Root entry {
        print("=== Closure Monitor ===");
        visit [-->];
    }

    can pin_source with EvidencePacket entry {
        status = "PINNED" if here.pinned else "UNPINNED";
        print(f"source {here.locator}: {status}");
        visit [->:Feeds:->];
    }

    can audit_canary with Canary entry {
        print(
            f"canary {here.name}: {here.mechanism} "
            f"(falsifier: {here.falsifier})"
        );
        visit [->:Requires:->];
        visit [->:Gates:->];
    }

    can inspect with ArtifactSlot | ClosureLane entry {
        if not here.is_clear() {
            self.gaps.append(here.report_label());
        }
        visit [-->];
    }
}

walker ExecutionRunner {
    has order: list[str] = [];
    has seen: list[str] = [];

    can start with Root entry {
        print("=== Execution DAG ===");
        visit [-->];
    }

    can consume with EvidencePacket entry {
        visit [->:Feeds:->];
    }

    can prep_dep with ArtifactSlot entry {
        state = "READY" if here.ready else "PENDING";
        print(f"  dependency {here.kind}: {state}");
        visit [-->];
    }

    can run with Canary entry {
        if here.name in self.seen {
            print(f"CYCLE guard blocked at {here.name}");
            disengage;
        }
        self.seen.append(here.name);
        visit [<-:DependsOn:<-];
        if not here.build_gate {
            print(f"HALT {here.name}: buyer/adoption gate not passed");
        } else {
            print(f"RUN {here.name} (falsifier: {here.falsifier})");
            self.order.append(here.name);
            visit [->:Requires:->];
        }
        visit [->:DependsOn:->] else { disengage; };
    }

    can mark_artifact with ArtifactSlot entry {
        state = "READY" if here.ready else "PENDING";
        print(f"  required {here.kind}: {state}");
        visit [-->];
    }
}

