"""FPGA mask-to-contour pipeline: model PL/ARM stages, contour hierarchy, and walk bottlenecks."""

node PipelineStage {
    has name: str = "";
    has runs_on: str = "PL";
    has latency_us: float = 0.0;
    has stage_order: int = 0;
}

node ContourObject {
    has object_id: int = 0;
    has area: float = 0.0;
    has centroid_x: float = 0.0;
    has centroid_y: float = 0.0;
    has valid: bool = True;
    has min_area: float = 10.0;
}

node EquivalencePolicy {
    has contract_version: int = 2;
    has centroid_tolerance_px: float = 2.0;
    has area_tolerance_pct: float = 5.0;
}

edge Feeds { }
edge Produces { }
edge NestedIn { has ring_role: str = "outer"; }

walker PipelineProfiler {
    has total_us: float = 0.0;
    has arm_us: float = 0.0;
    has slowest_stage: str = "";
    has slowest_us: float = 0.0;
    has stages_done: int = 0;

    can start with Root entry {
        print("=== Pipeline profiler: mask-to-metrics traversal ===");
        visit [->:Feeds:->] else { disengage; };
    }

    can profile with PipelineStage entry {
        self.total_us += here.latency_us;
        self.stages_done += 1;
        if here.runs_on == "ARM" {
            self.arm_us += here.latency_us;
        }
        if here.latency_us > self.slowest_us {
            self.slowest_us = here.latency_us;
            self.slowest_stage = here.name;
        }
        loc = "PL" if here.runs_on == "PL" else "ARM";
        print(f"  [{here.stage_order}] {here.name} on {loc}: {here.latency_us} us");
        visit [->:Feeds:->] else {
            arm_share = (self.arm_us / self.total_us * 100.0) if self.total_us > 0.0 else 0.0;
            print(f"Total {self.total_us} us across {self.stages_done} stages; ARM {self.arm_us} us ({arm_share:.1f}%)");
            print(f"Next bottleneck: {self.slowest_stage} ({self.slowest_us} us)");
            disengage;
        };
    }
}

walker ContourExtractor {
    has visited: list[int] = [];
    has noise_rejected: int = 0;
    has objects_kept: int = 0;
    has ring_pairs: int = 0;
    has parent_valid: bool = False;

    can start with Root entry {
        print("=== Contour extractor: stage-6 hierarchy walk ===");
        visit [->:Feeds:->] else { disengage; };
    }

    can seek_contours with PipelineStage entry {
        if here.name == "FindContours" {
            visit [->:Produces:->] else { disengage; };
        } else {
            visit [->:Feeds:->] else { disengage; };
        }
    }

    can process with ContourObject entry {
        if here.object_id in self.visited {
            print(f"  cycle guard: object {here.object_id} already visited");
            disengage;
        }
        self.visited.append(here.object_id);

        if here.area < here.min_area {
            here.valid = False;
            self.noise_rejected += 1;
            print(f"  [NOISE] id={here.object_id} area={here.area} < min {here.min_area}");
        } else {
            self.objects_kept += 1;
            print(f"  [OBJ] id={here.object_id} area={here.area} centroid=({here.centroid_x},{here.centroid_y})");
            if self.parent_valid {
                self.ring_pairs += 1;
                print(f"  [RING] inner {here.object_id} paired with outer parent");
            }
        }

        saved_parent = self.parent_valid;
        self.parent_valid = here.valid;
        visit [->:NestedIn:->];
        self.parent_valid = saved_parent;
        visit [->:Produces:->] else { disengage; };
    }
}

walker ScienceValidator {
    has policy_version: int = 0;
    has centroid_tol: float = 0.0;
    has area_tol: float = 0.0;

    can start with Root entry {
        print("=== Science validator: object-record equivalence policy ===");
        visit [-->];
    }

    can read_policy with EquivalencePolicy entry {
        self.policy_version = here.contract_version;
        self.centroid_tol = here.centroid_tolerance_px;
        self.area_tol = here.area_tolerance_pct;
        print(f"  contract v{here.contract_version}: centroid ±{here.centroid_tolerance_px}px, area ±{here.area_tolerance_pct}%");
        disengage;
    }
}

