walker IncidentAnalyst {
    has as_of: int = 0;
    has env: str = "prod";
    has max_depth: int = 5;
    has depth: int = 0;
    has visited: list[str] = [];
    has trace: list[str] = [];
    has graph_hops: int = 0;

    def log(line: str) {
        self.trace.append(line);
        print(line);
    }

    def mark(token: str) -> bool {
        for t in self.visited {
            if t == token {
                return True;
            }
        }
        self.visited.append(token);
        return False;
    }

    def edge_active(from_ts: int, to_ts: int) -> bool {
        if from_ts > self.as_of {
            return False;
        }
        if to_ts > 0 and to_ts < self.as_of {
            return False;
        }
        return True;
    }

    can start with Root entry {
        self.log(f"=== RCA @ t={self.as_of} env={self.env} (max_depth={self.max_depth}) ===");
        visit [-->[?:Incident]] else { disengage; };
    }

    can enforce_scope with Service | Incident entry {
        if here.environment != self.env {
            self.log(f"[AUTH] blocked cross-environment access ({here.environment})");
            disengage;
        }
    }

    can investigate with Incident entry {
        tok = f"incident:{here.title}";
        if self.mark(tok) {
            self.log(f"[CYCLE] revisited {tok}");
            disengage;
        }
        self.log(f"[INCIDENT] {here.title} @ t={here.occurred_at}");
        if self.depth >= self.max_depth {
            self.log("[BOUND] depth cap at incident");
            disengage;
        }
        self.depth += 1;
        visit [->:MitigatedBy:->] else { };
        visit [<-:EscalatedTo:-] else { };
        self.depth -= 1;
        visit [-->];
    }

    can follow_alert with Alert entry {
        tok = f"alert:{here.message}";
        if self.mark(tok) {
            self.log(f"[CYCLE] revisited {tok}");
            disengage;
        }
        kind = "INFERRED" if here.is_inferred else "OBSERVED";
        self.log(f"[ALERT/{kind}] {here.severity}: {here.message} @ t={here.fired_at}");
        self.graph_hops += 1;
        visit [->:TriggeredOn:->] else { visit [-->]; };
    }

    can map_topology with Service entry {
        if here.since > self.as_of {
            self.log(f"[STALE] {here.name} not deployed @ t={self.as_of}");
            disengage;
        }
        tok = f"service:{here.name}";
        if self.mark(tok) {
            self.log(f"[CYCLE] revisited {tok}");
            disengage;
        }
        self.log(f"[SERVICE] {here.name} (since t={here.since})");
        self.graph_hops += 1;
        if self.depth >= self.max_depth {
            self.log("[BOUND] depth cap at service");
            disengage;
        }
        self.depth += 1;
        visit [->:DependsOn:->] else { self.depth -= 1; visit [-->]; };
        self.depth -= 1;
        visit [-->];
    }

    can record_fix with Remediation entry {
        tok = f"fix:{here.action}";
        if self.mark(tok) {
            self.log(f"[CYCLE] revisited {tok}");
            disengage;
        }
        self.log(f"[REMEDIATION] {here.action} -> {here.outcome}");
        self.graph_hops += 1;
        visit [-->];
    }
}

