    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

node Resource {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

edge Has {
    has ordinal: int = 0;
}

walker RelationshipExpander {
    has hub_title: str = "";
    has relationship_count: int = 0;
    has streamed_steps: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can expand_hub with Hub entry {
        self.hub_title = here.title;
        visit [->:Has:->] else { disengage; };
    }

    can count_edge with Resource entry {
        self.relationship_count += 1;
        self.streamed_steps += 1;
    }
}

