        f"MATCH (:Hub {{title: '{expander.hub_title}'}})-[r:HAS]->() "
        f"RETURN count(r) => {expander.relationship_count} "
        f"(streamed {expander.streamed_steps} edges, O(1) working memory)"
    );
}

