"""Compaction sweep: delete redundant blob prefixes only when a surviving proof chain reconstructs them."""

node Shard {
    has name: str = "";
}

node Blob {
    has digest: str = "";
    has content: list[int] = [];
    has age_days: int = 0;
}

node Manifest {
    has manifest_id: str = "";
    has age_days: int = 0;
    has parseable: bool = True;
}

edge Holds { }
edge Anchors { }
edge PrefixOf { }

walker CompactionSweep {
    has grace_days: int = 7;
    has deleted: int = 0;
    has kept: int = 0;
    has refused: int = 0;
    has active_manifest: Manifest = None;
    has survivor: Blob = None;
    has preds: list = [];

    def prefix_digest(data: list[int], length: int) -> str {
        total = 0;
        for i in range(length) {
            total += data[i];
        }
        return f"pfx-{total}";
    }

    def bytes_match_prefix(survivor: Blob, pred: Blob) -> bool {
        plen = len(pred.content);
        slen = len(survivor.content);
        if plen == 0 or plen >= slen {
            return False;
        }
        for i in range(plen) {
            if survivor.content[i] != pred.content[i] {
                return False;
            }
        }
        return True;
    }

    def verify_chain(survivor: Blob, preds: list) -> bool {
        for pred in preds {
            if not self.bytes_match_prefix(survivor, pred) {
                return False;
            }
            expected = self.prefix_digest(survivor.content, len(pred.content));
            if pred.digest != expected {
                return False;
            }
        }
        return True;
    }

    def grace_elapsed(manifest: Manifest, survivor: Blob) -> bool {
        return manifest.age_days >= self.grace_days and survivor.age_days >= self.grace_days;
    }

    def reset_chain() {
        self.active_manifest = None;
        self.survivor = None;
        self.preds = [];
    }

    def finish_chain() {
        manifest = self.active_manifest;
        survivor = self.survivor;
        if manifest is None or survivor is None {
            self.reset_chain();
            return;
        }
        if len(self.preds) == 0 {
            print(f"OK {manifest.manifest_id}: tip {survivor.digest} has no compactable predecessors");
            self.reset_chain();
            return;
        }
        ok = self.verify_chain(survivor, self.preds);
        grace_ok = self.grace_elapsed(manifest, survivor);
        if ok and grace_ok {
            for pred in self.preds {
                print(f"DELETE {pred.digest} — reconstructed from {survivor.digest} via {manifest.manifest_id}");
                del pred;
                self.deleted += 1;
            }
        } else {
            reason = "verification failed" if not ok else "grace period active";
            print(f"KEEP chain for {manifest.manifest_id}: {reason}");
            self.kept += 1;
        }
        self.reset_chain();
    }

    can start with Root entry {
        print("Weekly idle compaction sweep (local shard only)");
        visit [-->];
    }

    can enter_shard with Shard entry {
        print(f"Sweeping shard {here.name}");
        visit [->:Holds:->];
    }

    can sweep_manifest with Manifest entry {
        self.active_manifest = here;
        if not here.parseable {
            print(f"REFUSE: unparseable manifest {here.manifest_id} — update required");
            self.refused += 1;
            self.reset_chain();
        } else {
            visit [->:Anchors:->] else {
                print(f"SKIP {here.manifest_id}: no anchored survivor");
                self.reset_chain();
            };
        }
    }

    can at_tip with Blob entry {
        if self.survivor is not None {
            visit [-->] else { disengage; };
            return;
        }
        self.survivor = here;
        self.preds = [];
        visit [<--:PrefixOf:--] else {
            self.finish_chain();
            disengage;
        };
    }

    can at_pred with Blob entry {
        self.preds.append(here);
        visit [<--:PrefixOf:--] else {
            self.finish_chain();
            disengage;
        };
    }
}

with entry {
    shard = Shard(name="machine-a-local");
    root ++> shard;

    tip_ok = Blob(digest="pfx-100", content=[10, 20, 30, 40, 50], age_days=10);
