"""Incident knowledge graph: temporal topology reconstruction and bounded causal RCA traversal."""

node Scoped {
    has environment: str = "prod";
}

node Service(Scoped) {
    has name: str = "";
    has since: int = 0;
}

node Alert {
    has message: str = "";
    has severity: str = "warning";
    has fired_at: int = 0;
    has is_inferred: bool = False;
}

node Incident(Scoped) {
    has title: str = "";
    has occurred_at: int = 0;
}

node Remediation {
    has action: str = "";
    has outcome: str = "pending";
}

edge DependsOn {
    has valid_from: int = 0;
    has valid_to: int = 0;
    has is_inferred: bool = False;
    has confidence: float = 1.0;
}

edge TriggeredOn {
    has valid_from: int = 0;
    has valid_to: int = 0;
    has is_inferred: bool = False;
}

edge EscalatedTo {
    has valid_from: int = 0;
    has valid_to: int = 0;
    has is_inferred: bool = False;
}

edge MitigatedBy {
    has valid_from: int = 0;
    has valid_to: int = 0;
    has is_inferred: bool = False;
}

walker IncidentAnalyst {
    has as_of: int = 0;
    has env: str = "prod";
    has max_depth: int = 5;
    has depth: int = 0;
    has visited: list[str] = [];
    has trace: list[str] = [];
    has graph_hops: int = 0;

    def log(line: str) {
        self.trace.append(line);
        print(line);
    }

    def already_seen(token: str) -> bool {
        for t in self.visited {
            if t == token {
                return True;
            }
        }
        return False;
    }

    def remember(token: str) {
        self.visited.append(token);
    }

    can start with Root entry {
        self.log(
            f"=== RCA @ t={self.as_of} env={self.env} (max_depth={self.max_depth}) ==="
        );
        visit [-->] else { disengage; };
    }

    can enforce_scope with Service | Incident entry {
        if here.environment != self.env {
            self.log(
                f"AUTH blocked cross-environment access ({here.environment})"
            );
            disengage;
        }
    }

    can investigate with Incident entry {
        tok = f"incident:{here.title}";
        if self.already_seen(tok) {
            self.log(f"CYCLE revisited {tok}");
            disengage;
        }
        self.remember(tok);
        self.log(f"INCIDENT {here.title} @ t={here.occurred_at}");
        if self.depth >= self.max_depth {
            self.log("BOUND depth cap at incident");
            disengage;
        }
        self.depth = self.depth + 1;
        visit [->:MitigatedBy:->];
        visit [<--:EscalatedTo:--];
        self.depth = self.depth - 1;
        visit [-->] else { disengage; };
    }

    can follow_alert with Alert entry {
        tok = f"alert:{here.message}";
        if self.already_seen(tok) {
            self.log(f"CYCLE revisited {tok}");
            disengage;
        }
        self.remember(tok);
        kind = "INFERRED" if here.is_inferred else "OBSERVED";
        self.log(
            f"ALERT/{kind} {here.severity}: {here.message} @ t={here.fired_at}"
        );
        self.graph_hops = self.graph_hops + 1;
        visit [->:TriggeredOn:->] else { visit [-->]; };
    }

    can map_topology with Service entry {
        if here.since > self.as_of {
            self.log(f"STALE {here.name} not deployed @ t={self.as_of}");
            disengage;
        }
        tok = f"service:{here.name}";
        if self.already_seen(tok) {
            self.log(f"CYCLE revisited {tok}");
            disengage;
        }
        self.remember(tok);
        self.log(f"SERVICE {here.name} (since t={here.since})");
        self.graph_hops = self.graph_hops + 1;
        if self.depth >= self.max_depth {
            self.log("BOUND depth cap at service");
            disengage;
        }
        self.depth = self.depth + 1;
        visit [->:DependsOn:->] else {
            self.depth = self.depth - 1;
            visit [-->] else { disengage; };
        };
        self.depth = self.depth - 1;
        visit [-->] else { disengage; };
    }

    can record_fix with Remediation entry {
        tok = f"fix:{here.action}";
        if self.already_seen(tok) {
            self.log(f"CYCLE revisited {tok}");
            disengage;
        }
        self.remember(tok);
        self.log(f"REMEDIATION {here.action} -> {here.outcome}");
        self.graph_hops = self.graph_hops + 1;
        visit [-->] else { disengage; };
    }
}

