"""Windows MCP taskkill stale PPID: unsafe /T parent walk vs job-scoped cleanup."""

node Process {
    has pid: int = 0;
    has name: str = "";
    has birth_tick: int = 0;
    has alive: bool = True;
    has owned_by_codex: bool = False;
}

edge ParentOf {
    has observed_tick: int = 0;
}

walker StaleEdgeAuditor {
    has stale_edges: list[str] = [];
    has seen_pids: list[int] = [];
    has probing: bool = False;
    has probe_child_birth: int = 0;
    has probe_child_name: str = "";
    has probe_child_pid: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can inspect with Process entry {
        if self.probing {
            disengage;
        }
        if here.pid in self.seen_pids {
            disengage;
        }
        self.seen_pids.append(here.pid);
        self.probe_child_birth = here.birth_tick;
        self.probe_child_name = here.name;
        self.probe_child_pid = here.pid;
        self.probing = True;
        visit [<--:ParentOf:--];
        self.probing = False;
        visit [-->];
    }

    can parent_check with Process entry {
        if not self.probing {
            disengage;
        }
        if here.birth_tick > self.probe_child_birth {
            note = f"{self.probe_child_name}({self.probe_child_pid}) -> {here.name}({here.pid})";
            self.stale_edges.append(note);
        }
        disengage;
    }
}

walker TaskKillTraverser {
    has killed: list[str] = [];
    has seen_pids: list[int] = [];

    can start with Process entry {
        self.mark_terminated();
        visit [->:ParentOf:->];
        visit [<--:ParentOf:--] else { disengage; };
    }

    can sweep with Process entry {
        if here.pid in self.seen_pids {
            disengage;
        }
        self.mark_terminated();
        visit [->:ParentOf:->];
        visit [<--:ParentOf:--] else { disengage; };
    }

    def mark_terminated() {
        if here.pid in self.seen_pids {
            return;
        }
        self.seen_pids.append(here.pid);
        if here.alive {
            here.alive = False;
            self.killed.append(here.name);
        }
    }
}

walker JobObjectCleanup {
    has killed: list[str] = [];

    can start with Process entry {
        self.terminate_if_owned();
        visit [->:ParentOf:->] else { disengage; };
    }

    can cascade with Process entry {
        self.terminate_if_owned();
        visit [->:ParentOf:->] else { disengage; };
    }

    def terminate_if_owned() {
        if here.owned_by_codex and here.alive {
            here.alive = False;
            self.killed.append(here.name);
        }
    }
}

