"""Git clean -fX scope guard: dry-run detects ignored-parent expansion before data loss."""

node PathEntry {
    has name: str = "";
    has ignored: bool = False;
    has slated: bool = False;
}

node Workspace {
    has comparison_root: str = "";
}

node IgnoredDir(PathEntry) {
    override has ignored: bool = True;
}

node NestedDir(PathEntry) { }

node GeneratedFile(PathEntry) {
    has generated: bool = True;
}

node DataAsset {
    has name: str = "";
    has kind: str = "";
    has lost: bool = False;
}

edge Contains { }
edge ScopedCleanup { }

walker DryRunAuditor {
    has target_name: str = "";
    has climbing: bool = False;
    has removal_unit: str = "";
    has scope_violation: bool = False;
    has dry_run_line: str = "";

    can start with Root entry {
        visit [-->];
    }

    can enter_workspace with Workspace entry {
        visit [->:Contains:->];
    }

    can traverse_dirs with NestedDir | IgnoredDir entry {
        visit [->:Contains:->];
    }

    can inspect_file with GeneratedFile entry {
        if here.name == self.target_name {
            self.climbing = True;
            self.removal_unit = here.name;
            visit [<--:Contains:--];
        }
    }

    can climb with NestedDir | IgnoredDir entry {
        if self.climbing {
            if here.ignored {
                self.removal_unit = here.name;
                self.dry_run_line = f"Removing {here.name}/";
                if here.name != self.target_name {
                    self.scope_violation = True;
                }
                disengage;
            } else {
                visit [<--:Contains:--] else { disengage; };
            }
        }
    }
}

walker CleanupGuard {
    has blocked: bool = False;
    has removal_unit: str = "";
    has dry_run_line: str = "";

    can start with Root entry {
        if self.blocked {
            print(f"BLOCKED git clean -fX: dry-run '{self.dry_run_line}' "
                  f"expands beyond scoped file into ignored '{self.removal_unit}'");
            disengage;
        }
        visit [-->];
    }

    can refuse with IgnoredDir entry {
        if here.name == self.removal_unit {
            print(f"Refusing cascade delete of ignored tree '{here.name}'");
            disengage;
        }
    }
}

walker UnguardedSimulator {
    has removal_unit: str = "";
    has wiping: bool = False;

    can start with Root entry {
        visit [-->];
    }

    can ignite with IgnoredDir entry {
        if here.name == self.removal_unit {
            self.wiping = True;
            here.slated = True;
            print(f"Removing {here.name}/");
            visit [->:Contains:->];
        }
    }

    can sweep_dirs with NestedDir entry {
        if self.wiping {
            here.slated = True;
            visit [->:Contains:->];
        }
    }

    can sweep_files with GeneratedFile entry {
        if self.wiping {
            here.slated = True;
        }
    }

    can sweep_data with DataAsset entry {
        if self.wiping {
            here.lost = True;
        }
    }
}

with entry {
    ws = Workspace(comparison_root="comparison-root");
    data_dir = IgnoredDir(name="data");
    nested = NestedDir(name="nested");
    pyc = GeneratedFile(name="target.pyc");
    corpus = DataAsset(name="corpus.sqlite", kind="sqlite");

    root ++> ws;
    ws +>:Contains:+> data_dir;
    data_dir +>:Contains:+> nested;
    nested +>:Contains:+> pyc;
    data_dir +>:Contains:+> corpus;
    ws +>:ScopedCleanup:+> pyc;

    auditor = DryRunAuditor(target_name="target.pyc");
    root spawn auditor;

    print(f"scoped target: {pyc.name}");
    print(f"dry-run: {auditor.dry_run_line}");
    print(f"scope violation: {auditor.scope_violation}");

    guard = CleanupGuard(
        blocked=auditor.scope_violation,
        removal_unit=auditor.removal_unit,
        dry_run_line=auditor.dry_run_line
    );
    root spawn guard;

    reckless = UnguardedSimulator(removal_unit=auditor.removal_unit);
    root spawn reckless;

    corpus_status = "LOST" if corpus.lost else "SAFE";
    pyc_status = "REMOVED" if pyc.slated else "KEPT";
    print(f"after guarded block: corpus {corpus_status}, bytecode {pyc_status}");
    print(f"unguarded simulation: corpus lost={corpus.lost}, data slated={data_dir.slated}");
}

