    reason = agent.stop_reason if agent.stop_reason else "queue_exhausted";
    print(f"[DONE] actions={agent.actions_taken} disposition={reason}");
}

"""Falryn hooks engine: deterministic ordering, dependency cycle guard, filters, deadlines, and cancellation."""

node LifecyclePoint {
    has title: str = "";
