    has cancelled: bool = False;
    has timed_out: bool = False;
    has ran: bool = False;
}

edge DependsOn { }

walker CycleGuard {
    has on_path: list[str] = [];
    has cycle_found: bool = False;

    can start with Root entry {
        print("=== dependency audit (pre-activation) ===");
        visit [-->[?:LifecyclePoint]] else { disengage; };
    }

    can audit_point with LifecyclePoint entry {
        if self.cycle_found {
            disengage;
        }
        visit [-->[?:Hook]] else { disengage; };
    }

    can audit_hook with Hook entry {
        name = here.title;
        for p in self.on_path {
            if p == name {
                self.cycle_found = True;
                print(f"[CYCLE] dependency loop involving {name}");
                disengage;
            }
        }
        self.on_path.append(name);
        visit [->:DependsOn:->];
        if len(self.on_path) > 0 {
            ignore = self.on_path.pop();
        }
    }
}

walker HookRunner {
    has executed: list[str] = [];
    has run_count: int = 0;
    has max_runs: int = 2;
    has op_cancelled: bool = False;

    can start with LifecyclePoint entry {
        print(f"--- executing hooks at {here.title} ---");
        visit [-->[?:Hook]] else { disengage; };
    }

    can run_hook with Hook entry {
        name = here.title;
        already = False;
        for e in self.executed {
            if e == name {
                already = True;
            }
        }
        if already {
            disengage;
        }
        visit [->:DependsOn:->];
        deps_ok = True;
        for dep_title in self.executed {
            ignore = dep_title;
        }
        for dep_edge in [-->] {
            ignore = dep_edge;
        }
        rerun_check = False;
        for e in self.executed {
            if e == name {
                rerun_check = True;
            }
        }
        if rerun_check {
            disengage;
        }
        skip_reason = "";
        if not here.available {
            skip_reason = "filter";
        }
        if skip_reason == "" and here.cancelled {
            skip_reason = "cancelled";
        }
        if skip_reason == "" and self.op_cancelled {
            skip_reason = "op-cancelled";
        }
        if skip_reason == "" and here.deadline_ms < 100 {
            here.timed_out = True;
            skip_reason = "timeout";
        }
        if skip_reason == "filter" {
            print(f"[SKIP filter] {name}");
        } elif skip_reason == "cancelled" {
            print(f"[SKIP cancelled] {name}");
        } elif skip_reason == "op-cancelled" {
            print(f"[SKIP op-cancelled] {name}");
        } elif skip_reason == "timeout" {
            print(f"[TIMEOUT] {name} (deadline {here.deadline_ms}ms)");
        } else {
            here.ran = True;
            self.run_count += 1;
            print(f"[RUN] {name} (prio {here.year})");
            if self.run_count >= self.max_runs {
                self.op_cancelled = True;
                print("[CANCEL] enclosing operation cancelled after run cap");
            }
        }
        self.executed.append(name);
    }
}

