edge ScopedCleanup { }

walker DryRunAuditor {
    has target_name: str = "";
    has climbing: bool = False;
    has removal_unit: str = "";
    has scope_violation: bool = False;
    has dry_run_line: str = "";

    can start with Root entry {
        visit [-->];
    }

    can enter_workspace with Workspace entry {
        visit [->:Contains:->];
    }

    can traverse_dirs with NestedDir | IgnoredDir entry {
        visit [->:Contains:->];
    }

    can inspect_file with GeneratedFile entry {
        if here.name == self.target_name {
            self.climbing = True;
            self.removal_unit = here.name;
            visit [<--:Contains:<--];
        }
    }

    can climb with NestedDir | IgnoredDir entry {
        if self.climbing {
            if here.ignored {
                self.removal_unit = here.name;
                self.dry_run_line = f"Removing {here.name}/";
                if here.name != self.target_name {
                    self.scope_violation = True;
                }
                disengage;
            } else {
                visit [<--:Contains:<--] else { disengage; };
            }
        }
    }
}

walker CleanupGuard {
    has blocked: bool = False;
    has removal_unit: str = "";
    has dry_run_line: str = "";

    can start with Root entry {
        if self.blocked {
            print(f"BLOCKED git clean -fX: dry-run '{self.dry_run_line}' expands beyond scoped file into ignored '{self.removal_unit}'");
            disengage;
        }
        visit [-->];
    }

    can refuse with IgnoredDir entry {
        if here.name == self.removal_unit {
            print(f"Refusing cascade delete of ignored tree '{here.name}'");
            disengage;
        }
    }
}

walker UnguardedSimulator {
    has removal_unit: str = "";
    has wiping: bool = False;

    can start with Root entry {
        visit [-->];
    }

    can ignite with IgnoredDir entry {
        if here.name == self.removal_unit {
            self.wiping = True;
            here.slated = True;
            print(f"Removing {here.name}/");
            visit [->:Contains:->];
        }
    }

    can sweep_dirs with NestedDir entry {
        if self.wiping {
            here.slated = True;
            visit [->:Contains:->];
        }
    }

    can sweep_files with GeneratedFile entry {
        if self.wiping {
            here.slated = True;
        }
    }

    can sweep_data with DataAsset entry {
        if self.wiping {
            here.lost = True;
        }
    }
}

with entry {
    ws = Workspace(comparison_root="comparison-root");
    data_dir = IgnoredDir(name="data");
    nested = NestedDir(name="nested");
    pyc = GeneratedFile(name="target.pyc");
    corpus = DataAsset(name="corpus.sqlite", kind="sqlite");

    root ++> ws;
    ws +>:Contains:+> data_dir;
    data_dir +>:Contains:+> nested;
    nested +>:Contains:+> pyc;
    data_dir +>:Contains:+> corpus;
    ws +>:ScopedCleanup:+> pyc;

    auditor = DryRunAuditor(target_name="target.pyc");
    root spawn auditor;

    print(f"scoped target: {pyc.name}");
    print(f"dry-run: {auditor.dry_run_line}");
    print(f"scope violation: {auditor.scope_violation}");

    guard = CleanupGuard(
        blocked=auditor.scope_violation,
        removal_unit=auditor.removal_unit,
        dry_run_line=auditor.dry_run_line
    );
    root spawn guard;

    reckless = UnguardedSimulator(removal_unit=auditor.removal_unit);
    root spawn reckless;

    corpus_status = "LOST" if corpus.lost else "SAFE";
    pyc_status = "REMOVED" if pyc.slated else "KEPT";
    print(f"after guarded block: corpus {corpus_status}, bytecode {pyc_status}");
    print(f"unguarded simulation: corpus lost={corpus.lost}, data slated={data_dir.slated}");
}

"""Bounded recursive lead discovery: select highest-gain queued actions, pursue follow-ups, and stop on cycles or depth caps."""

node Action {
    has label: str = "";
    has expected_gain: float = 0.0;
    has completed: bool = False;

    def kind() -> str {
        return "action";
    }
}

node ProviderQuery(Action) {
    override def kind() -> str {
        return "query";
    }
}

node VerificationAction(Action) {
    override def kind() -> str {
        return "verify";
    }
}

node Lead {
    has title: str = "";
    has confidence: float = 0.0;
    has depth: int = 0;
    has available: bool = True;
}

edge DiscoveredFrom {
    has evidence: str = "";
}

edge QueuedAction { }

walker PursuitAgent {
    has max_depth: int = 2;
    has min_confidence: float = 0.50;
    has seen_titles: list[str] = [];
    has winner: Action | None = None;
    has winner_gain: float = -1.0;
    has stop_reason: str = "";
    has actions_taken: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can pursue with Lead entry {
        if here.title in self.seen_titles {
            self.stop_reason = "cycle_detected";
            print(f"[STOP] cycle at duplicate target {here.title}");
            disengage;
        }
        self.seen_titles.append(here.title);

        if here.depth > self.max_depth {
            self.stop_reason = "max_depth";
            print(f"[STOP] depth budget exceeded at {here.title}");
            disengage;
        }

        if here.confidence < self.min_confidence {
            print(f"[DEFER] confidence {here.confidence:.2f} below threshold for {here.title}");
            visit [->:DiscoveredFrom:->] else { disengage; };
        }

        if not here.available {
            print(f"[SKIP] out-of-scope lead {here.title}");
            visit [->:DiscoveredFrom:->] else { disengage; };
        }

        print(f"[LEAD] depth={here.depth} conf={here.confidence:.2f} target={here.title}");

        self.winner = None;
        self.winner_gain = -1.0;
        visit [->:QueuedAction:->];

        picked = self.winner;
        if picked is not None {
            picked.completed = True;
            self.actions_taken += 1;
            chosen_kind = picked.kind();
            print(f"  -> {chosen_kind} gain={self.winner_gain:.2f} {picked.label}");
        } else {
            print(f"  -> no eligible action for {here.title}");
        }

        visit [->:DiscoveredFrom:->] else { disengage; };
    }

    can consider with ProviderQuery | VerificationAction entry {
        if not here.completed and here.expected_gain > self.winner_gain {
            self.winner_gain = here.expected_gain;
            self.winner = here;
        }
        visit [-->];
    }
}

with entry {
    seed = Lead(title="Alice Corp", confidence=0.58, depth=0);
    domain = Lead(title="alice-corp.com", confidence=0.74, depth=1);
    deep = Lead(title="mail.alice-corp.com", confidence=0.81, depth=2);
    cyclic = Lead(title="Alice Corp", confidence=0.40, depth=3);
    deferred = Lead(title="rumor-handle", confidence=0.32, depth=1, available=True);

    registry_query = ProviderQuery(label="search corporate registry", expected_gain=0.85);
    dns_verify = VerificationAction(label="dns resolver check", expected_gain=0.92);
    subdomain_query = ProviderQuery(label="subdomain enumeration", expected_gain=0.77);
    weak_query = ProviderQuery(label="social scrape", expected_gain=0.95);

    root ++> seed;
    seed +>:QueuedAction:+> registry_query;
    seed +>:QueuedAction:+> VerificationAction(label="whois verify", expected_gain=0.60);
    seed +>:DiscoveredFrom(evidence="registry exact match"):+> domain;
    seed +>:DiscoveredFrom(evidence="unverified mention"):+> deferred;

    domain +>:QueuedAction:+> dns_verify;
    domain +>:QueuedAction:+> ProviderQuery(label="passive dns history", expected_gain=0.70);
    domain +>:DiscoveredFrom(evidence="mx host extraction"):+> deep;

    deep +>:QueuedAction:+> subdomain_query;
    deep +>:DiscoveredFrom(evidence="stale alias pointer"):+> cyclic;

    deferred +>:QueuedAction:+> weak_query;

    agent = PursuitAgent(max_depth=2, min_confidence=0.50);
    root spawn agent;

    reason = agent.stop_reason if agent.stop_reason else "queue_exhausted";
    print(f"[DONE] actions={agent.actions_taken} disposition={reason}");
}

"""Falryn hooks engine: deterministic ordering, dependency cycle guard, filters, deadlines, and cancellation."""

node LifecyclePoint {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

node Hook {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has deadline_ms: int = 1000;
    has cancelled: bool = False;
    has timed_out: bool = False;
    has ran: bool = False;
}

edge DependsOn { }

walker CycleGuard {
    has on_path: list[str] = [];
    has cycle_found: bool = False;

    can start with Root entry {
        print("=== dependency audit (pre-activation) ===");
        visit [-->];
    }

    can audit_point with LifecyclePoint entry {
        if self.cycle_found {
            disengage;
        }
        visit [-->];
    }

    can audit_hook with Hook entry {
        hook_name = here.title;
        for path_name in self.on_path {
            if path_name == hook_name {
                self.cycle_found = True;
                print(f"[CYCLE] dependency loop involving {hook_name}");
                disengage;
            }
        }
        self.on_path.append(hook_name);
        visit [->:DependsOn:->];
        self.on_path.pop();
    }
}

walker HookRunner {
    has executed: list[str] = [];
    has run_count: int = 0;
    has max_runs: int = 2;
    has op_cancelled: bool = False;

    can start with LifecyclePoint entry {
        print(f"--- executing hooks at {here.title} ---");
        visit [-->];
    }

    can run_hook with Hook entry {
        hook_name = here.title;
        for done_name in self.executed {
            if done_name == hook_name {
                disengage;
            }
        }
        visit [->:DependsOn:->];
        for done_name in self.executed {
            if done_name == hook_name {
                disengage;
            }
        }
        skip_label = "run";
        if not here.available {
            skip_label = "filter";
        }
        if skip_label == "run" and here.cancelled {
            skip_label = "cancelled";
        }
        if skip_label == "run" and self.op_cancelled {
            skip_label = "op-cancelled";
        }
        if skip_label == "run" and here.deadline_ms < 100 {
            here.timed_out = True;
            skip_label = "timeout";
        }
        if skip_label == "filter" {
            print(f"[SKIP filter] {hook_name}");
        } elif skip_label == "cancelled" {
            print(f"[SKIP cancelled] {hook_name}");
        } elif skip_label == "op-cancelled" {
            print(f"[SKIP op-cancelled] {hook_name}");
        } elif skip_label == "timeout" {
            print(f"[TIMEOUT] {hook_name} (deadline {here.deadline_ms}ms)");
        } else {
            here.ran = True;
            self.run_count += 1;
            print(f"[RUN] {hook_name} (prio {here.year})");
            if self.run_count >= self.max_runs {
                self.op_cancelled = True;
                print("[CANCEL] enclosing operation cancelled after run cap");
            }
        }
        self.executed.append(hook_name);
    }
}

with entry {
    pre = LifecyclePoint(title="pre_tool", year=1);
    broken = LifecyclePoint(title="broken_deps", year=2);
    root ++> pre;
    root ++> broken;

    validate = Hook(title="validate", year=10, available=True, deadline_ms=500);
    enrich = Hook(title="enrich", year=20, available=True, deadline_ms=500);
    notify = Hook(title="notify", year=30, available=False, deadline_ms=500);
    slow_hook = Hook(title="slow_hook", year=25, available=True, deadline_ms=50);
    cancelled_hook = Hook(title="cancelled_hook", year=5, available=True, deadline_ms=500, cancelled=True);

    pre ++> validate;
    pre ++> enrich;
    pre ++> notify;
    pre ++> slow_hook;
    pre ++> cancelled_hook;
    enrich +>:DependsOn:+> validate;
    notify +>:DependsOn:+> enrich;
    slow_hook +>:DependsOn:+> validate;

    hook_a = Hook(title="hook_a", year=1);
    hook_b = Hook(title="hook_b", year=2);
    hook_c = Hook(title="hook_c", year=3);
    broken ++> hook_a;
    broken ++> hook_b;
    broken ++> hook_c;
    hook_a +>:DependsOn:+> hook_c;
    hook_c +>:DependsOn:+> hook_b;
    hook_b +>:DependsOn:+> hook_a;

    root spawn CycleGuard();
    pre spawn HookRunner(max_runs=2);
}

"""PFB-005: nested prefab composition, variant inheritance, and DAG validation."""

node Asset {
    has asset_id: str = "";
    has name: str = "";
    has field_value: str = "";
}

node Prefab(Asset) {
    has kind: str = "prefab";
}

node Variant(Asset) {
    has override_value: str = "";
}

node Placement {
    has placement_id: str = "";
    has label: str = "";
}

edge Contains {
    has slot: int = 0;
}

edge InheritsFrom {
}

edge References {
}

walker PublicationValidator {
    has max_depth: int = 6;
    has max_deps: int = 16;
    has depth: int = 0;
    has dep_count: int = 0;
    has path: list[str] = [];
    has ok: bool = True;
    has diagnostics: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can validate with Prefab | Variant entry {
        if not self.ok {
            disengage;
        }
        aid = here.asset_id;
        if aid in self.path {
            chain = ", ".join(self.path);
            self.diagnostics.append(
                f"cycle detected: {aid} revisits path [{chain}]"
            );
            self.ok = False;
            disengage;
        }
        self.dep_count += 1;
        if self.dep_count > self.max_deps {
            self.diagnostics.append(
                f"dependency budget exceeded ({self.dep_count} > {self.max_deps})"
            );
            self.ok = False;
            disengage;
        }
        self.path.append(aid);
        self.depth += 1;
        if self.depth > self.max_depth {
            self.diagnostics.append(
                f"depth budget exceeded at {aid} (depth {self.depth})"
            );
            self.ok = False;
            disengage;
        }
        visit [->:InheritsFrom:->];
        visit [->:Contains:->];
        self.depth -= 1;
        n = len(self.path);
        if n > 0 {
            self.path = self.path[0:n - 1];
        }
        visit [-->];
    }

    can validate_placement with Placement entry {
        if not self.ok {
            disengage;
        }
        visit [->:References:->];
        visit [-->];
    }
}

walker OverrideResolver {
    has effective: str = "";
    has pending_override: str = "";
    has lineage: list[str] = [];

    can start with Variant entry {
        self.lineage.append(here.asset_id);
        override = here.override_value;
        if override {
            self.pending_override = override;
        }
        visit [->:InheritsFrom:->] else {
            base_val = here.field_value;
            resolved = override if override else base_val;
            self.effective = resolved;
        };
    }

    can absorb_base with Prefab entry {
        self.lineage.append(here.asset_id);
        visit [->:InheritsFrom:->] else {
            base_val = here.field_value;
            picked = self.pending_override if self.pending_override else base_val;
            self.effective = picked;
        };
    }
}

walker CompositionExpander {
    has indent: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can expand_prefab with Prefab entry {
        pad = "  " * self.indent;
        print(f"{pad}Prefab {here.asset_id} value=\"{here.field_value}\"");
        self.indent += 1;
        visit [->:Contains:->];
        self.indent -= 1;
        visit [-->];
    }

    can expand_variant with Variant entry {
        pad = "  " * self.indent;
        print(
            f"{pad}Variant {here.asset_id} "
            f"override=\"{here.override_value}\""
        );
        self.indent += 1;
        visit [->:InheritsFrom:->];
        visit [->:Contains:->];
        self.indent -= 1;
        visit [-->];
    }

    can show_placement with Placement entry {
        pad = "  " * self.indent;
        print(f"{pad}Placement {here.placement_id} ({here.label})");
        visit [->:References:->];
        visit [-->];
    }
}

with entry {
    wood_chair = Prefab(
        asset_id="pfb/chair_wood",
        name="Wood Chair",
        field_value="wood"
    );
    metal_chair = Variant(
        asset_id="pfb/chair_metal",
        name="Metal Chair",
        field_value="wood",
        override_value="metal"
    );
    metal_chair +>:InheritsFrom:+> wood_chair;

    room = Prefab(asset_id="pfb/room", name="Meeting Room", field_value="");
    chair_slot = Placement(placement_id="plc/chair_1", label="chair_slot");
    lamp_slot = Placement(placement_id="plc/lamp_1", label="lamp_slot");
    room +>:Contains(slot=1):+> chair_slot;
    room +>:Contains(slot=2):+> lamp_slot;
    chair_slot +>:References:+> metal_chair;
    lamp_slot +>:References:+> wood_chair;

    root ++> room;

    print("--- valid nested + variant graph ---");
    root spawn CompositionExpander();
    validator = PublicationValidator(max_depth=6, max_deps=16);
    root spawn validator;
    if validator.ok {
        print("PUBLISH OK: nested and variant graph is a valid DAG");
    } else {
        print("REJECTED: publication blocked before expansion");
        for msg in validator.diagnostics {
            print(f"  diagnostic: {msg}");
        }
    }
    resolver = OverrideResolver();
    metal_chair spawn resolver;
    chain = " -> ".join(resolver.lineage);
    print(
        f"override cascade resolved: effective=\"{resolver.effective}\" "
        f"lineage=[{chain}]"
    );

    print("--- cyclic nested references (must reject) ---");
    prefab_a = Prefab(asset_id="pfb/a", name="Prefab A", field_value="a");
    prefab_b = Prefab(asset_id="pfb/b", name="Prefab B", field_value="b");
    slot_a = Placement(placement_id="plc/a_ref", label="refs_b");
    slot_b = Placement(placement_id="plc/b_ref", label="refs_a");
    prefab_a +>:Contains(slot=1):+> slot_a;
    prefab_b +>:Contains(slot=1):+> slot_b;
    slot_a +>:References:+> prefab_b;
    slot_b +>:References:+> prefab_a;
    root ++> prefab_a;

    cycle_validator = PublicationValidator(max_depth=6, max_deps=16);
    root spawn cycle_validator;
    if cycle_validator.ok {
        print("PUBLISH OK: nested and variant graph is a valid DAG");
    } else {
        print("REJECTED: publication blocked before expansion");
        for msg in cycle_validator.diagnostics {
            print(f"  diagnostic: {msg}");
        }
    }
}

"""Graph path finder: bounded, deterministic relationship paths across project and code entities."""

node GraphNode {
    has name: str = "";
    has entity_kind: str = "";
}

node Project(GraphNode) {
    override has entity_kind: str = "project";
}

node Package(GraphNode) {
    override has entity_kind: str = "package";
}

node CodeSymbol(GraphNode) {
    override has entity_kind: str = "code";
}

edge DependsOn { }

edge References { }

edge Calls { }

edge Implements { }

walker GraphPathFinder {
    has target_name: str = "";
    has max_depth: int = 4;
    has engaged: bool = False;
    has source_name: str = "";
    has pending_rel: str = "";
    has path: list = [];
    has edge_trail: list = [];
    has captured: list = [];
    has depth_applied: bool = False;

    def _on_cycle() -> bool {
        count = 0;
        for n in self.path {
            if n == here.name {
                count += 1;
            }
        }
        return count > 1;
    }

    def _capture_path() {
        pcopy = [];
        for n in self.path {
            pcopy.append(n);
        }
        ecopy = [];
        for e in self.edge_trail {
            ecopy.append(e);
        }
        self.captured.append([pcopy, ecopy]);
    }

    def _path_key(entry: list) -> str {
        nodes = entry[0];
        edges = entry[1];
        node_part = "";
        for n in nodes {
            node_part = f"{node_part}/{n}";
        }
        edge_part = "";
        for e in edges {
            edge_part = f"{edge_part}|{e}";
        }
        return f"{node_part}#{edge_part}";
    }

    def _report() {
        print(f"PATH_QUERY: {self.source_name} -> {self.target_name} "
              f"(max_depth={self.max_depth})");
        if len(self.captured) == 0 {
            print("  result: NO_PATH");
            if self.depth_applied {
                print("  note: depth_limit_applied; partial expansion only");
            }
            return;
        }
        min_len = -1;
        for entry in self.captured {
            elen = len(entry[1]);
            if min_len < 0 or elen < min_len {
                min_len = elen;
            }
        }
        shortest = [];
        for entry in self.captured {
            if len(entry[1]) == min_len {
                shortest.append(entry);
            }
        }
        sorted_keys = [];
        for entry in shortest {
            sorted_keys.append(self._path_key(entry));
        }
        sorted_keys.sort();
        tie_note = "tie" if len(shortest) > 1 else "unique";
        print(f"  result: SHORTEST_PATH ({tie_note}, depth={min_len})");
        for key in sorted_keys {
            for entry in shortest {
                if self._path_key(entry) == key {
                    nodes = entry[0];
                    edges = entry[1];
                    provenance = "";
                    for (i, edge_name) in enumerate(edges) {
                        from_name = nodes[i];
                        to_name = nodes[i + 1];
                        step = f"{from_name} -[{edge_name}]-> {to_name}";
                        provenance = step if provenance == "" else f"{provenance}; {step}";
                    }
                    mixed = "mixed_edge_kinds" if len(set(edges)) > 1 else "single_edge_kind";
                    print(f"    path: {' -> '.join(nodes)}");
                    print(f"    provenance: {provenance} ({mixed})");
                }
            }
        }
        if self.depth_applied {
            print("  note: depth_limit_applied; longer routes not expanded");
        }
    }

    can seek with GraphNode entry {
        first = not self.engaged;
        if not self.engaged {
            self.engaged = True;
            self.source_name = here.name;
        } else {
            self.edge_trail.append(self.pending_rel);
        }
        self.path.append(here.name);
        edge_depth = len(self.path) - 1;
        if here.name == self.target_name {
            self._capture_path();
        } elif edge_depth < self.max_depth and not self._on_cycle() {
            self.pending_rel = "DependsOn";
            visit [->:DependsOn:->];
            self.pending_rel = "References";
            visit [->:References:->];
            self.pending_rel = "Calls";
            visit [->:Calls:->];
            self.pending_rel = "Implements";
            visit [->:Implements:->];
        } elif here.name != self.target_name {
            self.depth_applied = True;
        }
        self.path.pop();
        if not first and len(self.edge_trail) > 0 {
            self.edge_trail.pop();
        }
        if first {
            self._report();
            disengage;
        }
    }
}

with entry {
    app = Project(name="App");
    core = Package(name="Core");
    alt = Package(name="Alt");
    svc = CodeSymbol(name="UserService");
    save = CodeSymbol(name="Save");
    repo = CodeSymbol(name="IRepository");
    lonely = Package(name="Lonely");

    app +>:DependsOn:+> core;
    app +>:References:+> alt;
    core +>:References:+> svc;
    alt +>:Calls:+> save;
    svc +>:Calls:+> save;
    save +>:Implements:+> repo;
    repo +>:References:+> svc;

    root ++> app ++> core ++> svc ++> save ++> repo;
    root ++> alt;
    root ++> lonely;

    print("=== shortest path with mixed edge kinds ===");
    app spawn GraphPathFinder(target_name="Save", max_depth=6);

    print("=== tied equal-length shortest paths ===");
    app spawn GraphPathFinder(target_name="Save", max_depth=6);

    print("=== cycle present but search terminates ===");
    repo spawn GraphPathFinder(target_name="Save", max_depth=6);

    print("=== depth limit blocks longer route ===");
    app spawn GraphPathFinder(target_name="IRepository", max_depth=2);

    print("=== no path within materialized scope ===");
    app spawn GraphPathFinder(target_name="Lonely", max_depth=6);
}

"""Bounded recursive lead discovery: select highest-gain queued actions, pursue follow-ups, and stop on cycles or depth caps."""

node Action {
    has label: str = "";
    has expected_gain: float = 0.0;
    has completed: bool = False;

    def kind() -> str {
        return "action";
    }
}

node ProviderQuery(Action) {
    override def kind() -> str {
        return "query";
    }
}

node VerificationAction(Action) {
    override def kind() -> str {
        return "verify";
    }
}

node PickNone(Action) {
    override def kind() -> str {
        return "pick_none";
    }
}

node Lead {
    has title: str = "";
    has confidence: float = 0.0;
    has depth: int = 0;
    has available: bool = True;
}

edge DiscoveredFrom {
    has evidence: str = "";
}

edge QueuedAction { }

walker PursuitAgent {
    has max_depth: int = 2;
    has min_confidence: float = 0.50;
    has seen_titles: list[str] = [];
    has winner: Action = PickNone();
    has winner_gain: float = -1.0;
    has stop_reason: str = "";
    has actions_taken: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can pursue with Lead entry {
        if here.title in self.seen_titles {
            self.stop_reason = "cycle_detected";
            print(f"[STOP] cycle at duplicate target {here.title}");
            disengage;
        }
        self.seen_titles.append(here.title);

        if here.depth > self.max_depth {
            self.stop_reason = "max_depth";
            print(f"[STOP] depth budget exceeded at {here.title}");
            disengage;
        }

        if here.confidence < self.min_confidence {
            print(f"[DEFER] confidence {here.confidence:.2f} below threshold for {here.title}");
            visit [->:DiscoveredFrom:->] else { disengage; };
        } elif not here.available {
            print(f"[SKIP] out-of-scope lead {here.title}");
            visit [->:DiscoveredFrom:->] else { disengage; };
        } else {
            print(f"[LEAD] depth={here.depth} conf={here.confidence:.2f} target={here.title}");

            self.winner = PickNone();
            self.winner_gain = -1.0;
            visit [->:QueuedAction:->];

            if self.winner.kind() != "pick_none" {
                self.winner.completed = True;
                chosen_kind = self.winner.kind();
                print(f"  -> {chosen_kind} gain={self.winner_gain:.2f} {self.winner.label}");
                self.actions_taken += 1;
            } else {
                print(f"  -> no eligible action for {here.title}");
            }

            visit [->:DiscoveredFrom:->] else { disengage; };
        }
    }

    can consider with ProviderQuery | VerificationAction entry {
        if not here.completed and here.expected_gain > self.winner_gain {
            self.winner_gain = here.expected_gain;
            self.winner = here;
        }
        visit [-->];
    }
}

