"""Long dictation: bounded durable segments, immutable privacy routing, and honest paste."""

node DictationSession {
    has session_id: str = "";
    has stopped: bool = False;
    has guard_reached: bool = False;
}

node Segment {
    has index: int = 0;
    has transcript: str = "";
    has durable: bool = False;
}

node PrivacyRoute {
    has saved: str = "";
    has effective: str = "";
}

node PasteTarget {
    has target_id: str = "";
    has pasted: bool = False;
    has final_text: str = "";
}

edge SessionSegment {
    has order: int = 0;
}

edge NextSegment { }

edge BoundRoute { }

edge PasteTo { }

walker DictationAssembler {
    has transcript_buf: str = "";
    has all_durable: bool = True;
    has route_ok: bool = True;
    has session_stopped: bool = False;

    can start with Root entry {
        print("=== Dictation assembly and honest paste audit ===");
        visit [-->];
    }

    can process_session with DictationSession entry {
        self.transcript_buf = "";
        self.all_durable = True;
        self.route_ok = True;
        self.session_stopped = here.stopped;
        guard_note = " (guard reached)" if here.guard_reached else "";
        print(
            f"\n[SESSION] {here.session_id} stopped={here.stopped}{guard_note}"
        );
        visit [->:SessionSegment:->];
        visit [->:BoundRoute:->];
        if here.stopped and self.all_durable and self.route_ok {
            visit [->:PasteTo:->];
        } else {
            partial = self.transcript_buf.strip();
            reason = "still recording" if not here.stopped else "segments not durable";
            print(f"[RECOVERY] partial='{partial}' — paste withheld ({reason})");
        }
    }

    can walk_segment with Segment entry {
        status = "DURABLE" if here.durable else "PENDING";
        print(f"  [SEG {here.index}] {status}: {here.transcript}");
        if not here.durable {
            self.all_durable = False;
        }
        self.transcript_buf += here.transcript + " ";
        visit [->:NextSegment:->] else {
            disengage;
        };
    }

    can audit_route with PrivacyRoute entry {
        if here.saved != here.effective {
            self.route_ok = False;
            print(
                f"  [ROUTE] MISMATCH saved={here.saved} effective={here.effective}"
            );
        } else {
            print(
                f"  [ROUTE] {here.effective} (immutable for this invocation)"
            );
        }
        disengage;
    }

    can honest_paste with PasteTarget entry {
        if not self.session_stopped {
            print(f"  [PASTE -> {here.target_id}] withheld — session not stopped");
        } elif not self.all_durable {
            print(f"  [PASTE -> {here.target_id}] withheld — segments not durable");
        } elif not self.route_ok {
            print(f"  [PASTE -> {here.target_id}] withheld — route invalid");
        } elif here.pasted {
            print(
                f"  [PASTE -> {here.target_id}] idempotent skip — '{here.final_text}'"
            );
        } else {
            here.final_text = self.transcript_buf.strip();
            here.pasted = True;
            print(
                f"  [PASTE -> {here.target_id}] complete — '{here.final_text}'"
            );
        }
        disengage;
    }
}

