"""Graph path finder: bounded, deterministic relationship paths across project and code entities."""

node GraphNode {
    has name: str = "";
    has entity_kind: str = "";
}

node Project(GraphNode) { }

node Package(GraphNode) { }

node CodeSymbol(GraphNode) { }

edge DependsOn { }

edge References { }

edge Calls { }

edge Implements { }

walker GraphPathFinder {
    has target_name: str = "";
    has max_depth: int = 4;
    has engaged: bool = False;
    has source_name: str = "";
    has pending_rel: str = "";
    has path: list[str] = [];
    has edge_trail: list[str] = [];
    has captured_nodes: list[list[str]] = [];
    has captured_edges: list[list[str]] = [];
    has depth_applied: bool = False;

    def _on_cycle() -> bool {
        count = 0;
        for n in self.path {
            if n == here.name {
                count += 1;
            }
        }
        return count > 1;
    }

    def _capture_path() {
        pcopy: list[str] = [];
        for n in self.path {
            pcopy.append(n);
        }
        ecopy: list[str] = [];
        for e in self.edge_trail {
            ecopy.append(e);
        }
        self.captured_nodes.append(pcopy);
        self.captured_edges.append(ecopy);
    }

    def _path_key(idx: int) -> str {
        nodes = self.captured_nodes[idx];
        edges = self.captured_edges[idx];
        node_part = "";
        for n in nodes {
            node_part = f"{node_part}/{n}";
        }
        edge_part = "";
        for e in edges {
            edge_part = f"{edge_part}|{e}";
        }
        return f"{node_part}#{edge_part}";
    }

    def _path_line(nodes: list[str]) -> str {
        line = "";
        for n in nodes {
            line = f"{line} via {n}" if line != "" else n;
        }
        return line;
    }

    def _edge_kind_tag(edges: list[str]) -> str {
        if len(edges) <= 1 {
            return "single_edge_kind";
        }
        baseline = edges[0];
        for e in edges {
            if e != baseline {
                return "mixed_edge_kinds";
            }
        }
        return "single_edge_kind";
    }

    def _report() {
        print(
            f"PATH_QUERY: {self.source_name} to {self.target_name} "
            f"(max_depth={self.max_depth})"
        );
        if len(self.captured_nodes) == 0 {
            print("  result: NO_PATH");
            if self.depth_applied {
                print("  note: depth_limit_applied; partial expansion only");
            }
            return;
        }
        min_len = -1;
        for edges in self.captured_edges {
            elen = len(edges);
            if min_len < 0 or elen < min_len {
                min_len = elen;
            }
        }
        shortest_idxs: list[int] = [];
        for (idx, edges) in enumerate(self.captured_edges) {
            if len(edges) == min_len {
                shortest_idxs.append(idx);
            }
        }
        sorted_keys: list[str] = [];
        for idx in shortest_idxs {
            sorted_keys.append(self._path_key(idx));
        }
        sorted_keys.sort();
        tie_note = "tie" if len(shortest_idxs) > 1 else "unique";
        print(f"  result: SHORTEST_PATH ({tie_note}, depth={min_len})");
        for key in sorted_keys {
            for (idx, probe) in enumerate(shortest_idxs) {
                if self._path_key(probe) == key {
                    nodes = self.captured_nodes[probe];
                    edges = self.captured_edges[probe];
                    provenance = "";
                    for (i, edge_name) in enumerate(edges) {
                        from_name = nodes[i];
                        to_name = nodes[i + 1];
                        step = f"{from_name} -[{edge_name}]- {to_name}";
                        provenance = step if provenance == "" else f"{provenance}; {step}";
                    }
                    kind_tag = self._edge_kind_tag(edges);
                    print(f"    path: {self._path_line(nodes)}");
                    print(f"    provenance: {provenance} ({kind_tag})");
                }
            }
        }
        if self.depth_applied {
            print("  note: depth_limit_applied; longer routes not expanded");
        }
    }

    can seek with GraphNode entry {
        first = not self.engaged;
        if not self.engaged {
            self.engaged = True;
            self.source_name = here.name;
        } else {
            self.edge_trail.append(self.pending_rel);
        }
        self.path.append(here.name);
        edge_depth = len(self.path) - 1;
        if here.name == self.target_name {
            self._capture_path();
        } elif edge_depth < self.max_depth and not self._on_cycle() {
            self.pending_rel = "DependsOn";
            visit [->:DependsOn:->];
            self.pending_rel = "References";
            visit [->:References:->];
            self.pending_rel = "Calls";
            visit [->:Calls:->];
            self.pending_rel = "Implements";
            visit [->:Implements:->];
        } elif here.name != self.target_name {
            self.depth_applied = True;
        }
        self.path.pop();
        if not first and len(self.edge_trail) > 0 {
            self.edge_trail.pop();
        }
        if first {
            self._report();
            disengage;
        }
    }
}

