"""Mushroom production lineage: explicit culture-to-product edges with bounded downstream and upstream walkers."""

node LotEntity {
    has lot_id: str = "";
    has strain: str = "";
    has contaminated: bool = False;
}

node Culture(LotEntity) {
    has culture_type: str = "LC";
}

node Grain(LotEntity) {
    has colonize_days: int = 0;
}

node FruitingBlock(LotEntity) {
    has yield_score: int = 0;
}

node Harvest {
    has harvest_id: str = "";
    has weight_g: float = 0.0;
}

node Product {
    has product_id: str = "";
    has sku: str = "";
}

edge CultureToGrain {
    has inoculated_at: str = "";
}

edge GrainToBlock {
    has transferred_at: str = "";
}

edge BlockToHarvest {
    has harvested_at: str = "";
}

edge HarvestToProduct {
    has packed_at: str = "";
}

walker DownstreamTracer {
    has max_depth: int = 6;
    has depth: int = 0;
    has visited: list[str] = [];

    def seen(key: str) -> bool {
        for v in self.visited {
            if v == key {
                return True;
            }
        }
        return False;
    }

    def indent() -> str {
        pad = "";
        for _ in range(self.depth) {
            pad += "  ";
        }
        return pad;
    }

    def admit(key: str, label: str) -> bool {
        if self.seen(key) {
            print(f"{self.indent()}[cycle-guard] skip {key}");
            return False;
        }
        self.visited.append(key);
        if self.depth > self.max_depth {
            print(f"{self.indent()}[depth-cap] stop at {label}");
            return False;
        }
        print(f"{self.indent()}-> {label}");
        self.depth += 1;
        return True;
    }

    def retreat() {
        self.depth -= 1;
    }

    def contam_tag() -> str {
        tag = "";
        if here.contaminated {
            tag = " [CONTAMINATED]";
        }
        return tag;
    }

    can traverse with Culture entry {
        key = f"culture:{here.lot_id}";
        label = f"Culture [{here.culture_type}] {here.lot_id} ({here.strain})";
        if not self.admit(key, label) {
            disengage;
        }
        visit [->:CultureToGrain:->] else {
            self.retreat();
            disengage;
        }
        self.retreat();
    }

    can traverse with Grain entry {
        key = f"grain:{here.lot_id}";
        label = f"Grain {here.lot_id} ({here.strain}, {here.colonize_days}d colonize)";
        if not self.admit(key, label) {
            disengage;
        }
        visit [->:GrainToBlock:->] else {
            self.retreat();
            disengage;
        }
        self.retreat();
    }

    can traverse with FruitingBlock entry {
        key = f"block:{here.lot_id}";
        label = f"FruitingBlock {here.lot_id} (yield={here.yield_score}){self.contam_tag()}";
        if not self.admit(key, label) {
            disengage;
        }
        visit [->:BlockToHarvest:->] else {
            self.retreat();
            disengage;
        }
        self.retreat();
    }

    can traverse with Harvest entry {
        key = f"harvest:{here.harvest_id}";
        label = f"Harvest {here.harvest_id} ({here.weight_g}g)";
        if not self.admit(key, label) {
            disengage;
        }
        visit [->:HarvestToProduct:->] else {
            self.retreat();
            disengage;
        }
        self.retreat();
    }

    can traverse with Product entry {
        key = f"product:{here.product_id}";
        label = f"Product {here.product_id} [{here.sku}]";
        if not self.admit(key, label) {
            disengage;
        }
        disengage;
    }
}

walker UpstreamTracer {
    has max_depth: int = 6;
    has depth: int = 0;
    has visited: list[str] = [];

    def seen(key: str) -> bool {
        for v in self.visited {
            if v == key {
                return True;
            }
        }
        return False;
    }

    def indent() -> str {
        pad = "";
        for _ in range(self.depth) {
            pad += "  ";
        }
        return pad;
    }

    def admit(key: str, label: str) -> bool {
        if self.seen(key) {
            print(f"{self.indent()}[cycle-guard] skip {key}");
            return False;
        }
        self.visited.append(key);
        if self.depth > self.max_depth {
            print(f"{self.indent()}[depth-cap] stop at {label}");
            return False;
        }
        print(f"{self.indent()}<- {label}");
        self.depth += 1;
        return True;
    }

    def retreat() {
        self.depth -= 1;
    }

    can traverse with Product entry {
        key = f"product:{here.product_id}";
        label = f"Product {here.product_id} [{here.sku}]";
        if not self.admit(key, label) {
            disengage;
        }
        visit [<-:HarvestToProduct:--] else {
            self.retreat();
            disengage;
        }
        self.retreat();
    }

    can traverse with Harvest entry {
        key = f"harvest:{here.harvest_id}";
        label = f"Harvest {here.harvest_id} ({here.weight_g}g)";
        if not self.admit(key, label) {
            disengage;
        }
        visit [<-:BlockToHarvest:--] else {
            self.retreat();
            disengage;
        }
        self.retreat();
    }

    can traverse with FruitingBlock entry {
        key = f"block:{here.lot_id}";
        contam = " [CONTAMINATED]" if here.contaminated else "";
        label = f"FruitingBlock {here.lot_id}{contam}";
        if not self.admit(key, label) {
            disengage;
        }
        visit [<-:GrainToBlock:--] else {
            self.retreat();
            disengage;
        }
        self.retreat();
    }

    can traverse with Grain entry {
        key = f"grain:{here.lot_id}";
        label = f"Grain {here.lot_id} ({here.strain})";
        if not self.admit(key, label) {
            disengage;
        }
        visit [<-:CultureToGrain:--] else {
            self.retreat();
            disengage;
        }
        self.retreat();
    }

    can traverse with Culture entry {
        key = f"culture:{here.lot_id}";
        label = f"Culture [{here.culture_type}] {here.lot_id} ({here.strain})";
        if not self.admit(key, label) {
            disengage;
        }
        disengage;
    }
}

