"""Research Commons Wiki: consent-bound ingestion, contradiction scan, and reuse admissibility."""

node ResearchArtifact {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has consent_granted: bool = False;
    has admitted: bool = False;
    has validated: bool = False;
    has projection: str = "private";
    has artifact_hash: str = "";
}

node WikiTopic {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has topic_id: str = "";
}

node ProtocolDraft {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has protocol_id: str = "";
}

edge Supports { }
edge Contradicts { }
edge Replicates { }
edge Supersedes { }
edge Reuses { }

walker CommonsIngestor {
    has log: list[str] = [];

    can start with Root entry {
        print("=== governed ingestion pipeline ===");
        visit [-->];
    }

    can enter_topic with WikiTopic entry {
        print(f"topic {here.topic_id}: {here.title}");
        visit [-->[?:ResearchArtifact]] else { disengage; };
    }

    can review_artifact with ResearchArtifact entry {
        if not here.consent_granted {
            line = f"BLOCK consent:{here.title}";
            self.log.append(line);
            print(line);
            disengage;
        } else {
            if not here.admitted {
                line = f"SHARED-NOT-ADMITTED:{here.title}";
                self.log.append(line);
                print(line);
                disengage;
            } else {
                if here.validated {
                    posture = "validated";
                } else {
                    posture = "admitted-not-validated";
                }
                line = f"ADMIT:{here.title}:{posture}:{here.projection}";
                self.log.append(line);
                print(line);
                disengage;
            }
        }
    }
}

walker ContradictionProbe {
    has source_title: str = "";

    can start with ResearchArtifact entry {
        visit [->:Contradicts:->] else {
            print(f"clean: {here.title}");
            disengage;
        };
    }

    can at_rival with ResearchArtifact entry {
        print(f"[CONFLICT] {self.source_title} contradicts {here.title}");
        disengage;
    }
}

walker ReuseAdmissibility {
    has label: str = "";
    has ok: bool = True;
    has chain: list[str] = [];

    can start with ProtocolDraft entry {
        print(f"=== reuse audit [{self.label}] {here.protocol_id} ===");
        visit [->:Reuses:->] else {
            print("  no priors — admissible");
            disengage;
        };
    }

    can audit_prior with ResearchArtifact entry {
        id = here.title;
        if id in self.chain {
            print(f"  CYCLE at {id} — inadmissible");
            self.ok = False;
            disengage;
        }
        self.chain.append(id);
        if not here.consent_granted {
            print(f"  missing consent: {id}");
            self.ok = False;
            disengage;
        }
        if not here.admitted {
            print(f"  not admitted: {id}");
            self.ok = False;
            disengage;
        }
        if here.validated {
            posture = "validated";
        } else {
            posture = "admitted-not-validated";
        }
        print(f"  prior {id} ({posture}, {here.projection})");
        visit [->:Reuses:->] else { disengage; };
    }
}

walker ProjectionWalker {
    can start with WikiTopic entry {
        print("=== site projection manifest ===");
        visit [-->[?:ResearchArtifact]] else { disengage; };
    }

    can project with ResearchArtifact entry {
        if here.admitted {
            vis = here.projection;
            print(f"PROJECT {here.title} -> {vis}");
        } else {
            print(f"SKIP {here.title} (not admitted)");
        }
        disengage;
    }
}

