walker DownstreamTracer {
    has max_depth: int = 6;
    has depth: int = 0;
    has visited: list[str] = [];

    def seen(key: str) -> bool {
        for v in self.visited {
            if v == key {
                return True;
            }
        }
        return False;
    }

    def indent() -> str {
        pad = "";
        for _ in range(self.depth) {
            pad += "  ";
        }
        return pad;
    }

    def admit(key: str, label: str) -> bool {
        if self.seen(key) {
            print(f"{self.indent()}[cycle-guard] skip {key}");
            return False;
        }
        self.visited.append(key);
        if self.depth > self.max_depth {
            print(f"{self.indent()}[depth-cap] stop at {label}");
            return False;
        }
        print(f"{self.indent()}-> {label}");
        self.depth += 1;
        return True;
    }

    def retreat() {
        self.depth -= 1;
    }

    def contam_tag() -> str {
        tag = "";
        if here.contaminated {
            tag = " [CONTAMINATED]";
        }
        return tag;
    }

    can traverse with Culture entry {
        key = f"culture:{here.lot_id}";
        label = f"Culture [{here.culture_type}] {here.lot_id} ({here.strain})";
        admitted = self.admit(key, label);
        if not admitted {
            disengage;
        }
        visit [->:CultureToGrain:->] else {
            self.retreat();
            disengage;
        }
        self.retreat();
    }

    can traverse with Grain entry {
        key = f"grain:{here.lot_id}";
        label = f"Grain {here.lot_id} ({here.strain}, {here.colonize_days}d colonize)";
        admitted = self.admit(key, label);
        if not admitted {
            disengage;
        }
        visit [->:GrainToBlock:->] else {
            self.retreat();
            disengage;
        }
        self.retreat();
    }

    can traverse with FruitingBlock entry {
        key = f"block:{here.lot_id}";
        label = f"FruitingBlock {here.lot_id} (yield={here.yield_score}){self.contam_tag()}";
        admitted = self.admit(key, label);
        if not admitted {
            disengage;
        }
        visit [->:BlockToHarvest:->] else {
