"""Bounded Knowledge context for coding: one Capsule attached to one no-effect task, bounded passage retrieval with citations and policy states."""

node CodingTask {
    has task_id: str = "";
    has no_effect: bool = True;
    has permitted: bool = True;
}

node KnowledgeCapsule {
    has title: str = "";
    has generation: int = 1;
    has active_generation: int = 1;
}

node Passage {
    has excerpt: str = "";
    has source_uri: str = "";
    has token_count: int = 0;
}

edge AttachedContext {
    has trust_label: str = "untrusted";
}

edge ContainsPassage { }

walker ContextPackBuilder {
    has max_passages: int = 10;
    has max_tokens: int = 500;
    has passage_count: int = 0;
    has token_total: int = 0;
    has state: str = "pending";
    has current_task: str = "";
    has capsule_title: str = "";

    can start with Root entry {
        visit [-->];
    }

    can build with CodingTask entry {
        self.current_task = here.task_id;
        self.passage_count = 0;
        self.token_total = 0;
        self.state = "pending";
        self.capsule_title = "";
        if not here.no_effect {
            self.state = "denied";
            print(f"[{self.current_task}] state=denied (task is not no-effect)");
            visit [-->];
        } elif not here.permitted {
            self.state = "denied";
            print(f"[{self.current_task}] state=denied (caller not permitted)");
            visit [-->];
        } else {
            visit [->:AttachedContext:->] else {
                self.state = "unavailable";
                print(f"[{self.current_task}] state=unavailable (no capsule attached)");
                visit [-->];
            };
        }
    }

    can open_capsule with KnowledgeCapsule entry {
        self.capsule_title = here.title;
        if here.generation != here.active_generation {
            self.state = "stale";
            print(f"[{self.current_task}] state=stale (capsule generation {here.generation} != active {here.active_generation})");
            visit [-->];
        } else {
            self.state = "retrieving";
            print(f"[{self.current_task}] opening capsule '{here.title}' [{self.trust_label_from_edge()}]");
            visit [->:ContainsPassage:->] else {
                end_state = "empty";
                self.state = end_state;
