"""Trusted RC borrow inference: optimistic borrowed parameters, call-graph
forwarding transfer, and fail-closed demotion on recursive re-entry."""

node Parameter {
    has index: int = 0;
    has borrowed: bool = True;
}

node Function {
    has name: str = "";
    has in_recursive_scc: bool = False;
    has requires_owned_arg0: bool = False;
}

edge HasParam { }
edge Calls {
    has caller_arg: int = 0;
    has callee_arg: int = 0;
}

walker BorrowInferencer {
    has changed: bool = False;
    has visiting: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can infer with Function entry {
        if here.name in self.visiting {
            here.in_recursive_scc = True;
            for param in here[->:HasParam:->] {
                if param is Parameter {
                    if param.borrowed {
                        param.borrowed = False;
                        self.changed = True;
                    }
                }
            }
            disengage;
        }
        self.visiting.append(here.name);

        visit [->:Calls:->];

        if here.requires_owned_arg0 {
            for param in here[->:HasParam:->] {
                if param is Parameter {
                    if param.index == 0 and param.borrowed {
                        param.borrowed = False;
                        self.changed = True;
                    }
                }
            }
        }
        for callee in here[->:Calls:->] {
            if callee is Function {
                target = callee;
                callee_arg0_borrowed = False;
                for param in target[->:HasParam:->] {
                    if param is Parameter {
                        if param.index == 0 {
                            callee_arg0_borrowed = param.borrowed;
                        }
                    }
                }
                if not callee_arg0_borrowed {
                    for param in here[->:HasParam:->] {
                        if param is Parameter {
                            if param.index == 0 and param.borrowed {
                                param.borrowed = False;
                                self.changed = True;
                            }
                        }
                    }
                }
            }
        }
    }
}

walker SummaryReporter {
    can start with Root entry {
        visit [-->];
    }

    can report_fn with Function entry {
        arg0_borrowed = False;
        arg1_borrowed = False;
        for param in here[->:HasParam:->] {
            if param is Parameter {
                if param.index == 0 {
                    arg0_borrowed = param.borrowed;
                } else {
                    if param.index == 1 {
                        arg1_borrowed = param.borrowed;
                    }
                }
            }
        }
        b0_label = "borrowed" if arg0_borrowed else "owned";
        b1_label = "borrowed" if arg1_borrowed else "owned";
        print(f"{here.name}: arg0={b0_label} arg1={b1_label} "
              f"recursive_scc={here.in_recursive_scc}");
        visit [->:HasParam:->];
        visit [->:Calls:->];
    }

    can report_param with Parameter entry {
        state = "borrowed" if here.borrowed else "owned";
        print(f"  param{here.index} {state}");
        visit [-->] else { disengage; };
    }
}

with entry {
    main_fn = Function(name="main");
    helper_fn = Function(name="helper");
    worker_fn = Function(name="worker");
    leaf_fn = Function(name="leaf", requires_owned_arg0=True);

    root ++> main_fn;

    main_fn +>:HasParam:+> Parameter(index=0);
    main_fn +>:HasParam:+> Parameter(index=1);
    helper_fn +>:HasParam:+> Parameter(index=0);
    worker_fn +>:HasParam:+> Parameter(index=0);
    leaf_fn +>:HasParam:+> Parameter(index=0);

    main_fn +>:Calls(caller_arg=0, callee_arg=0):+> helper_fn;
    helper_fn +>:Calls(caller_arg=0, callee_arg=0):+> leaf_fn;
    helper_fn +>:Calls(caller_arg=0, callee_arg=0):+> worker_fn;
    worker_fn +>:Calls(caller_arg=0, callee_arg=0):+> helper_fn;

    for round in range(8) {
        inferencer = BorrowInferencer();
        root spawn inferencer;
        if not inferencer.changed {
            break;
        }
    }

    root spawn SummaryReporter();
}

