"""Ember data catalog: trace dataset lineage and flag sources missing acquisition receipts."""

node CatalogEntity {
    has identity: str = "";
}

node Source(CatalogEntity) {
    has url: str = "";
    has revision: str = "";
    has license: str = "";
}

node ImmutableObject(CatalogEntity) {
    has sha256: str = "";
    has bytes: int = 0;
    has locator: str = "";
}

node DatasetVersion(CatalogEntity) {
    has producer: str = "";
    has config_hash: str = "";
    has split: str = "";
}

node Receipt {
    has receipt_id: str = "";
    has authority: str = "";
    has valid: bool = True;
}

edge DerivedFrom { }

edge Receipted { }

walker LineageAuditor {
    has blockers: list[str] = [];
    has lineage: list[str] = [];
    has visited: list[str] = [];

    can trace_version with DatasetVersion entry {
        id = here.identity;
        if id in self.visited {
            self.blockers.append(f"lineage cycle at dataset {id}");
            disengage;
        }
        self.visited.append(id);
        row = f"version:{id} producer={here.producer} split={here.split}";
        self.lineage.append(row);
        visit [<-:DerivedFrom:<-] else {
            visit [-->] else { disengage; };
        };
    }

    can trace_source with Source entry {
        id = here.identity;
        if id in self.visited {
            disengage;
        }
        self.visited.append(id);
        row = f"source:{id} url={here.url} license={here.license}";
        self.lineage.append(row);
        visit [->:Receipted:->] else {
            self.blockers.append(f"missing receipt for source {id}");
            visit [-->] else { disengage; };
        };
    }

    can trace_object with ImmutableObject entry {
        id = here.identity;
        if id in self.visited {
            disengage;
        }
        self.visited.append(id);
        short_hash = here.sha256[:16];
        row = f"object:{id} sha256={short_hash} bytes={here.bytes}";
        self.lineage.append(row);
        visit [<-:DerivedFrom:<-] else {
            visit [-->] else { disengage; };
        };
    }

    can trace_receipt with Receipt entry {
        if not here.valid {
            note = f"invalid receipt {here.receipt_id} from {here.authority}";
            self.blockers.append(note);
