"""Code-graph foundation: converge divergent extractor identities onto one resolver and canonical node id."""

def module_stem(path: str) -> str {
    parts = path.split("/");
    filename = parts[len(parts) - 1];
    return filename.replace(".py", "");
}

def legacy_indexer_id(module_path: str, name: str) -> str {
    stem = module_stem(module_path);
    safe = name.replace(".", "_");
    return f"{stem}::{safe}";
}

def canonical_func_id(module_path: str, class_name: str, name: str) -> str {
    qual = name;
    if class_name != "" {
        qual = f"{class_name}.{name}";
    }
    return f"{module_path}.{qual}";
}

node Module {
    has path: str = "";
}

node Function {
    has name: str = "";
    has module_path: str = "";
    has class_name: str = "";
    has canonical_id: str = "";
    has legacy_id: str = "";
}

node IndexerHit {
    has node_id: str = "";
}

node CallGraphHit {
    has func_id: str = "";
}

edge DefinedIn { }

edge Calls {
    has raw_callee: str = "";
}

edge Indexed { }

edge InCallGraph { }

walker IdentityUnifier {
    can start with Root entry {
        visit [-->[?:Module]] else { disengage; };
    }

    can scan_module with Module entry {
        visit [-->[?:Function]] else { disengage; };
    }

    can unify with Function entry {
        here.legacy_id = legacy_indexer_id(here.module_path, here.name);
        here.canonical_id = canonical_func_id(
            here.module_path, here.class_name, here.name
        );
        old_label = here.legacy_id;
        new_label = here.canonical_id;
        if old_label != new_label {
            print(f"[UNIFY] {old_label} => {new_label}");
        }
        visit [-->];
    }
}

walker IndexerExtractor {
    can start with Root entry {
        visit [-->[?:Function]] else { disengage; };
    }

    can record with Function entry {
        hit = IndexerHit(node_id=here.canonical_id);
        here +>:Indexed:+> hit;
        print(f"[INDEXER] stored {hit.node_id}");
        visit [-->];
    }
}

walker CallGraphExtractor {
    can start with Root entry {
        visit [-->[?:Function]] else { disengage; };
    }

    can record with Function entry {
        hit = CallGraphHit(func_id=here.canonical_id);
        here +>:InCallGraph:+> hit;
        print(f"[CALL_GRAPH] stored {hit.func_id}");
        visit [-->];
    }
}

walker SharedCalleeResolver {
    has pending_caller: str = "";
    has seen: list[str] = [];

    can start with Root entry {
        visit [-->[?:Function]] else { disengage; };
    }

    can resolve with Function entry {
        if here.canonical_id in self.seen {
            disengage;
        }
        self.seen.append(here.canonical_id);
        if self.pending_caller != "" {
            callee_id = here.canonical_id;
            print(f"[RESOLVER] {self.pending_caller} -> {callee_id}");
            self.pending_caller = "";
            visit [-->];
        } else {
            self.pending_caller = here.canonical_id;
            visit [->:Calls:->] else {
                self.pending_caller = "";
                visit [-->];
            };
        }
    }
}

walker JoinByCanonicalId {
    has idx_id: str = "";
    has graph_id: str = "";

    can start with Root entry {
        visit [-->[?:Function]] else { disengage; };
    }

    can join with Function entry {
        self.idx_id = "";
        self.graph_id = "";
        visit [-->[?:IndexerHit]] else { visit [-->]; };
    }

    can read_indexer with IndexerHit entry {
        self.idx_id = here.node_id;
        visit [-->[?:CallGraphHit]] else { visit [-->]; };
    }

    can read_call_graph with CallGraphHit entry {
        self.graph_id = here.func_id;
        if self.idx_id == self.graph_id {
            print(f"[JOIN] indexer and call-graph agree on {self.graph_id}");
        }
        visit [-->];
    }
}

