"""HRM traverse: hop edges must originate from the expanded node, not the first neighbor."""

node Memory {
    has mem_id: str = "";
}

node TraversalLedger {
    has expanded: list[str] = [];
    has hop_log: list[str] = [];
}

edge ReportsNeighbor {
    has similarity: float = 0.0;
}

walker HrmTraverse {
    has buggy: bool = False;
    has ledger: TraversalLedger;
    has pending_init: bool = False;
    has expander: Memory = None;
    has hop_first: str = "";
    has wiring: bool = False;

    can start with Root entry {
        visit [-->[?:Memory]];
    }

    can init with Memory entry {
        if not self.pending_init {
            disengage;
        }
        self.pending_init = False;
        if here.mem_id in self.ledger.expanded {
            disengage;
        }
        self.ledger.expanded.append(here.mem_id);
        self.expander = here;
        self.hop_first = "";
        self.wiring = True;
        visit [->:ReportsNeighbor:->] else {
            self.wiring = False;
            disengage;
        };
    }

    can expand with Memory entry {
        if self.pending_init {
            disengage;
        }
        if self.wiring {
            disengage;
        }
        if here.mem_id in self.ledger.expanded {
            disengage;
        }
        self.ledger.expanded.append(here.mem_id);
        self.expander = here;
        self.hop_first = "";
        self.wiring = True;
        visit [->:ReportsNeighbor:->] else {
            self.wiring = False;
            disengage;
        };
    }

    can wire with Memory entry {
        if not self.wiring {
            disengage;
        }
        if self.hop_first == "" {
            self.hop_first = here.mem_id;
        }
        skip = here.mem_id == self.hop_first and self.expander.mem_id != here.mem_id;
        if not skip {
            src_id = self.hop_first if self.buggy else self.expander.mem_id;
            self.ledger.hop_log.append(f"{src_id} -> {here.mem_id}");
        }
        if not (here.mem_id in self.ledger.expanded) {
            child = HrmTraverse(
                buggy=self.buggy,
                ledger=self.ledger,
                pending_init=True
            );
            here spawn child;
        }
        visit [->:ReportsNeighbor:->] else {
            self.wiring = False;
            disengage;
        };
    }
}

