"""github-workflows self-test gap: untested actions, blocked tasks, and weaker release contracts."""

node Repo {
    has name: str = "";
}

node Workflow {
    has name: str = "";
    has os: str = "";
    has is_release: bool = False;
}

node CompositeAction {
    has name: str = "";
    has security_sensitive: bool = False;
    has strictness: int = 0;
}

node Fixture {
    has name: str = "";
    has os: str = "";
}

node Task {
    has id: str = "";
    has title: str = "";
    has blocked: bool = False;
}

edge Uses { }
edge Tests { }
edge DependsOn { }

walker SelfTestAuditor {
    has phase: int = 0;
    has on_release_path: bool = False;
    has tested_actions: list[str] = [];
    has untested_sensitive: list[str] = [];
    has release_contract: str = "";
    has unused_strict: str = "";
    has gate_blocked: bool = False;
    has visited_tasks: list[str] = [];

    can start with Root entry {
        print("Auditing github-workflows self-test coverage");
        self.phase = 1;
        visit [-->[?:Fixture]] else { disengage; };
        print("Fixture trace complete; scanning for gaps");
        self.phase = 2;
        visit [-->[?:Repo]] else { disengage; };
    }

    can audit_repo with Repo entry {
        if self.phase != 2 {
            disengage;
        }
        visit [-->[?:Workflow]] else { disengage; };
        visit [-->[?:CompositeAction]] else { disengage; };
        visit [-->[?:Task]] else { disengage; };
    }

    can trace_fixture with Fixture entry {
        if self.phase != 1 {
            disengage;
        }
        print(f"Fixture {here.name} ({here.os}) exercises workflows");
        visit [->:Tests:->] else { disengage; };
    }

    can follow_workflow with Workflow entry {
        if here.is_release and self.phase == 2 {
            self.on_release_path = True;
            visit [->:Uses:->] else { disengage; };
            self.on_release_path = False;
        } elif self.phase == 1 {
            visit [->:Uses:->] else { disengage; };
        } else {
            disengage;
        }
    }

    can inspect_action with CompositeAction entry {
        if self.phase == 1 {
            if here.name not in self.tested_actions {
                self.tested_actions.append(here.name);
                print(f"  covered: {here.name}");
            }
            disengage;
        }
        if self.on_release_path {
            self.release_contract = here.name;
        }
        if here.security_sensitive and here.name not in self.tested_actions {
            self.untested_sensitive.append(here.name);
            print(f"UNTESTED SENSITIVE: {here.name}");
        }
        if here.strictness > 1 and here.name not in self.tested_actions {
            self.unused_strict = here.name;
        }
        disengage;
    }

    can check_task with Task entry {
        if self.phase != 2 {
            disengage;
        }
        if here.id in self.visited_tasks {
            disengage;
        }
        self.visited_tasks.append(here.id);
        if here.blocked {
            self.gate_blocked = True;
            print(f"GATE BLOCKED: {here.id} cannot proceed until dependencies clear");
        }
        visit [->:DependsOn:->] else { disengage; };
    }

    can summarize with Root exit {
        print("--- audit summary ---");
        if self.gate_blocked {
            print("ATYA-027 remains blocked on ATYA-019");
        } else {
            print("ATYA-027 gate open");
        }
        if self.untested_sensitive {
            for name in self.untested_sensitive {
                print(f"decay risk: {name}");
            }
        } else {
            print("all sensitive actions on tested paths");
        }
        if self.unused_strict and self.release_contract {
            print(f"CONTRACT GAP: release uses {self.release_contract}, "
                  f"stricter {self.unused_strict} unused");
        }
    }
}

with entry {
    repo = Repo(name="github-workflows");
    root ++> repo;

    ci_linux = Workflow(name="ci-linux", os="linux");
    ci_windows = Workflow(name="ci-windows", os="windows");
