    root spawn SelfTestAuditor();
}

"""PlanGraph addTask: reject prerequisite edges that would break DAG integrity."""

node Task {
    has task_id: str = "";
    has name: str = "";
}

node PlanGraph {
    has graph_name: str = "";

    def add_task(task: Task, prereq: Task) -> bool {
        probe = prereq spawn CycleProbe(seek_id=task.task_id);
        if probe.would_cycle {
            return False;
        }
        task +>:Requires:+> prereq;
        return True;
    }
}

edge Requires { }

walker CycleProbe {
    has seek_id: str = "";
    has seen: list[str] = [];
    has would_cycle: bool = False;

    can trace with Task entry {
        if here.task_id == self.seek_id {
            self.would_cycle = True;
            disengage;
        }
        if here.task_id in self.seen {
            disengage;
        }
        self.seen.append(here.task_id);
        visit [->:Requires:->] else { disengage; };
    }
}

walker TopoReporter {
    has order: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can emit with PlanGraph entry {
        visit [-->];
    }

    can emit with Task entry {
        if here.task_id not in self.order {
            self.order.append(here.task_id);
        }
        visit [->:Requires:->] else { visit [-->]; };
    }
}

with entry {
    graph = PlanGraph(graph_name="release");
    build = Task(task_id="1", name="build");
    test = Task(task_id="2", name="test");
    deploy = Task(task_id="3", name="deploy");

    root ++> graph ++> build ++> test ++> deploy;

    ok_build_test = graph.add_task(test, build);
    print(f"addTask test requires build: {'accepted' if ok_build_test else 'rejected'}");

    ok_deploy_test = graph.add_task(deploy, test);
    print(f"addTask deploy requires test: {'accepted' if ok_deploy_test else 'rejected'}");

    ok_cycle_chain = graph.add_task(build, deploy);
    chain_label = "rejected" if not ok_cycle_chain else "accepted";
    print(f"addTask build requires deploy (closes chain cycle): {chain_label}");

    ok_two_cycle = graph.add_task(build, test);
    two_label = "rejected" if not ok_two_cycle else "accepted";
    print(f"addTask build requires test (direct 2-cycle): {two_label}");

    reporter = root spawn TopoReporter();
    print(f"remaining DAG task order: {reporter.order}");
}

