"""Sites plugin MCP: model Volta shim and cmd.exe recursion when VOLTA_HOME is not forwarded to the child process."""

node ProcessUnit {
    has label: str = "";
    has unit_type: str = "";
    has stable: bool = False;
}

node VoltaShim(ProcessUnit) {
    has unit_type: str = "shim";
}

node CmdProxy(ProcessUnit) {
    has unit_type: str = "cmd";
}

node RealRuntime(ProcessUnit) {
    has unit_type: str = "real";
}

node McpServer(ProcessUnit) {
    has name: str = "";
    has script: str = "";
    has unit_type: str = "server";
}

node LaunchContext {
    has command: str = "node";
    has args: str = "./mcp/server.mjs";
    has cwd: str = ".";
    has volta_home_present: bool = False;
}

node Scenario {
    has title: str = "";
}

edge SpawnsVia {
    has mechanism: str = "";
}

edge ResolvesTo { }

walker SpawnProbe {
    has visited_keys: list[str] = [];
    has spawn_total: int = 0;
    has max_spawns: int = 25;
    has env_volta_home: bool = False;
    has aborted_cycle: bool = False;
    has truncated: bool = False;
    has reached_server: bool = False;

    can run with Scenario entry {
        visit [-->];
    }

    can begin with LaunchContext entry {
        self.env_volta_home = here.volta_home_present;
        visit [-->];
    }

    can dispatch with VoltaShim | CmdProxy | RealRuntime | McpServer entry {
        key = f"{here.unit_type}:{here.label}";
        if key in self.visited_keys {
            self.aborted_cycle = True;
            disengage;
        }
        self.visited_keys += [key];
        self.spawn_total += 1;
        if self.spawn_total >= self.max_spawns {
            self.truncated = True;
            disengage;
        }
        if here.unit_type == "shim" {
            if self.env_volta_home {
                visit [->:ResolvesTo:->] else { disengage; };
            } else {
                visit [->:SpawnsVia:->] else { disengage; };
            }
        } else {
            if here.unit_type == "cmd" {
                visit [->:SpawnsVia:->] else { disengage; };
            } else {
                if here.unit_type == "real" {
                    visit [->:SpawnsVia:->] else { disengage; };
                } else {
                    here.stable = True;
                    self.reached_server = True;
                    disengage;
                }
            }
        }
    }
}

with entry {
    root ++> (bad_case := Scenario(title="VOLTA_HOME absent"));
    bad_case ++> (ctx_bad := LaunchContext(
        command="node",
        args="./mcp/server.mjs",
        cwd=".",
        volta_home_present=False
    )) ++> (shim := VoltaShim(label="volta-node-shim"));
    (cmd := CmdProxy(label="cmd.exe"));
    shim +>:SpawnsVia(mechanism="cmd /C node ./mcp/server.mjs"):+> cmd;
    cmd +>:SpawnsVia(mechanism="shim-reinvoke"):+> shim;
    probe_bad = SpawnProbe(max_spawns=20);
    bad_case spawn probe_bad;

    root ++> (good_case := Scenario(title="VOLTA_HOME forwarded"));
    good_case ++> (ctx_good := LaunchContext(
        command="node",
        args="./mcp/server.mjs",
        cwd=".",
        volta_home_present=True
    )) ++> (shim2 := VoltaShim(label="volta-node-shim"));
    (real := RealRuntime(label="node-24.14.0"));
    (server := McpServer(
        name="sites-design-picker",
        script="./mcp/server.mjs",
        label="server.mjs"
    ));
    shim2 +>:ResolvesTo:+> real;
    real +>:SpawnsVia(mechanism="direct-exec"):+> server;
    probe_good = SpawnProbe(max_spawns=20);
    good_case spawn probe_good;

    print(f"missing VOLTA_HOME: descendants={probe_bad.spawn_total} "
          f"cycle_halt={probe_bad.aborted_cycle} "
          f"truncated={probe_bad.truncated} "
          f"server_reached={probe_bad.reached_server}");
