    }

    can begin with LaunchContext entry {
        self.env_volta_home = here.volta_home_present;
        visit [-->];
    }

    can dispatch with VoltaShim | CmdProxy | RealRuntime | McpServer entry {
        key = f"{here.unit_type}:{here.label}";
        if key in self.visited_keys {
            self.aborted_cycle = True;
            disengage;
        }
        self.visited_keys += [key];
        self.spawn_total += 1;
        if self.spawn_total >= self.max_spawns {
            self.truncated = True;
            disengage;
        }
