"""Sparse-array backend contract: validate CSR/CSC inputs, audit backends, and reject silent densification."""

node PipelineStage {
    has name: str = "";

    def kind() -> str {
        return "stage";
    }
}

node SparseMatrix {
    has label: str = "";
    has format: str = "csr";
    has device: str = "cpu";
    has values_finite: bool = True;
    has canonical: bool = True;

    def format_ok() -> bool {
        return self.format == "csr" or self.format == "csc";
    }

    def valid_buffers() -> bool {
        return self.values_finite and self.canonical;
    }
}

node Backend(PipelineStage) {
    has version: str = "1.0";
    has accepts_csr: bool = True;
    has accepts_csc: bool = True;

    override def kind() -> str {
        return "backend";
    }
}

node Estimator(PipelineStage) {
    has sparse_capable: bool = False;

    override def kind() -> str {
        return "estimator";
    }
}

edge HostedOn {
    has validated: bool = False;
}

edge FitsWith {
    has approved: bool = False;
}

walker ContractAuditor {
    has rejections: int = 0;
    has approvals: int = 0;
    has active_label: str = "";
    has active_format: str = "";
    has active_device: str = "";

    can start with Root entry {
        print("=== Sparse contract audit v1.0 ===");
        visit [-->];
        print(f"=== Audit complete: {self.approvals} approved, {self.rejections} rejected ===");
    }

    can inspect with SparseMatrix entry {
        if not here.format_ok() {
            print(f"[REJECT] {here.label}: format '{here.format}' outside contract (CSR/CSC only)");
            self.rejections += 1;
            disengage;
        }
        if not here.valid_buffers() {
            detail = "non-finite values" if not here.values_finite else "non-canonical indices";
            print(f"[REJECT] {here.label}: {detail}");
            self.rejections += 1;
            disengage;
        }
        self.active_label = here.label;
        self.active_format = here.format;
        self.active_device = here.device;
        print(f"[CHECK] {here.label} ({here.format}, {here.device})");
        visit [->:HostedOn:->] else {
            print(f"[REJECT] {here.label}: no backend host — cannot proceed");
            self.rejections += 1;
            disengage;
        };
    }

    can announce with Backend | Estimator entry {
        print(f"  -> {here.kind()}: {here.name}");
    }

    can audit_backend with Backend entry {
        fmt_ok = here.accepts_csr if self.active_format == "csr" else here.accepts_csc;
        if not fmt_ok {
            print(f"[REJECT] {here.name} cannot host {self.active_format} without explicit conversion");
            self.rejections += 1;
            disengage;
        }
        if self.active_device == "cuda" and here.name == "SciPy" {
            print(f"[REJECT] {self.active_label}: cross-device CPU fallback blocked under device=cuda");
            self.rejections += 1;
            disengage;
        }
        if self.active_device == "cpu" and here.name == "CuPy" {
            print(f"[REJECT] {here.name}: no implicit GPU path for CPU-resident sparse data");
            self.rejections += 1;
            disengage;
        }
        print(f"[OK] {here.name} v{here.version} hosts {self.active_format} on {self.active_device}");
        visit [->:FitsWith:->] else {
            print(f"[REJECT] no estimator linked for {self.active_label} on {here.name}");
            self.rejections += 1;
            disengage;
        };
    }

    can verify_estimator with Estimator entry {
        if not here.sparse_capable {
            print(f"[REJECT] {here.name}: sparse input unsupported — silent densification forbidden");
            self.rejections += 1;
            disengage;
        }
        print(f"[APPROVED] {here.name} may fit {self.active_label} without densification");
        self.approvals += 1;
        disengage;
    }
}

walker CompatibilityReporter {
    has traced: int = 0;

    can begin with Estimator entry {
        if not here.sparse_capable {
            disengage;
        }
        print(f"[COMPAT] tracing sparse path for {here.name}");
        visit [<--:FitsWith:<--] else {
            print(f"[COMPAT] {here.name}: no backend link");
            disengage;
        };
    }

    can trace_backend with Backend entry {
        print(f"  backend hop: {here.name} v{here.version}");
        visit [<--:HostedOn:<--] else {
            print(f"  backend {here.name}: no sparse matrix attached");
            disengage;
        };
    }

    can trace_matrix with SparseMatrix entry {
        guard = "dense estimate blocked" if here.format_ok() else "format rejected";
        print(f"  matrix hop: {here.label} ({here.format}, {here.device}) — {guard}");
        self.traced += 1;
        disengage;
    }
}

with entry {
    scipy_ridge = Backend(name="SciPy", version="1.11", accepts_csr=True, accepts_csc=True);
    scipy_ols = Backend(name="SciPy", version="1.11", accepts_csr=True, accepts_csc=True);
    cupy_gpu = Backend(name="CuPy", version="12.0", accepts_csr=True, accepts_csc=True);
    torch_cpu = Backend(name="Torch", version="2.1", accepts_csr=True, accepts_csc=False);

    ridge = Estimator(name="Ridge", sparse_capable=True);
    lasso = Estimator(name="Lasso", sparse_capable=True);
    ols = Estimator(name="LinearRegression", sparse_capable=False);

    x_train = SparseMatrix(label="X_train", format="csr", device="cpu", canonical=True);
    x_fold = SparseMatrix(label="X_fold", format="csc", device="cuda", canonical=True);
    x_coo = SparseMatrix(label="X_coo", format="coo", device="cpu");
    x_ols = SparseMatrix(label="X_ols", format="csr", device="cpu", canonical=True);
    x_torch = SparseMatrix(label="X_torch", format="csc", device="cpu", canonical=True);

    root ++> x_train;
    x_train +>:HostedOn(validated=True):+> scipy_ridge;
    scipy_ridge +>:FitsWith:+> ridge;

    root ++> x_fold;
    x_fold +>:HostedOn(validated=True):+> cupy_gpu;
    cupy_gpu +>:FitsWith:+> lasso;

    root ++> x_coo;

    root ++> x_ols;
    x_ols +>:HostedOn:+> scipy_ols;
    scipy_ols +>:FitsWith:+> ols;

    root ++> x_torch;
    x_torch +>:HostedOn:+> torch_cpu;
    torch_cpu +>:FitsWith:+> ridge;

    root spawn ContractAuditor();
    ridge spawn CompatibilityReporter();
    lasso spawn CompatibilityReporter();
}

