"""HRM traverse: hop edges must originate from the expanded node, not the first neighbor."""

node Memory {
    has mem_id: str = "";
}

node TraversalLedger {
    has expanded: list[str] = [];
    has hop_log: list[str] = [];
}

edge ReportsNeighbor {
    has similarity: float = 0.0;
}

walker HrmTraverse {
    has buggy: bool = False;
    has ledger: TraversalLedger = None;
    has pending_init: bool = False;
    has expander_id: str = "";
    has hop_first: str = "";
    has wiring: bool = False;

    can start with Root entry {
        visit [-->];
    }

    can init with Memory entry {
        if not self.pending_init {
            disengage;
        }
        self.pending_init = False;
        if here.mem_id in self.ledger.expanded {
            disengage;
        }
        self.ledger.expanded.append(here.mem_id);
        self.expander_id = here.mem_id;
        self.hop_first = "";
        self.wiring = True;
        visit [->:ReportsNeighbor:->] else { self.wiring = False; disengage; };
    }

    can expand with Memory entry {
        if self.pending_init {
            disengage;
        }
        if self.wiring {
            disengage;
        }
        if here.mem_id in self.ledger.expanded {
            disengage;
        }
        self.ledger.expanded.append(here.mem_id);
        self.expander_id = here.mem_id;
        self.hop_first = "";
        self.wiring = True;
        visit [->:ReportsNeighbor:->] else { self.wiring = False; disengage; };
    }

    can wire with Memory entry {
        if not self.wiring {
            disengage;
        }
        if self.hop_first == "" {
            self.hop_first = here.mem_id;
        }
        skip = here.mem_id == self.expander_id;
        if not skip {
            src_id = self.hop_first if self.buggy else self.expander_id;
            hop = src_id + " " + "-" + "> " + here.mem_id;
            self.ledger.hop_log.append(hop);
        }
        if not (here.mem_id in self.ledger.expanded) {
            child = HrmTraverse(buggy=self.buggy, ledger=self.ledger, pending_init=True);
            here spawn child;
        }
        visit [->:ReportsNeighbor:->] else { self.wiring = False; disengage; };
    }
}

with entry {
    seed = Memory(mem_id="seed");
    a = Memory(mem_id="A");
    b = Memory(mem_id="B");
    c = Memory(mem_id="C");
    d = Memory(mem_id="D");
    e = Memory(mem_id="E");
    f = Memory(mem_id="F");

    root ++> seed;
    seed +>:ReportsNeighbor(similarity=0.90):+> a;
    seed +>:ReportsNeighbor(similarity=0.80):+> b;
    seed +>:ReportsNeighbor(similarity=0.70):+> c;
    a +>:ReportsNeighbor(similarity=1.00):+> a;
    a +>:ReportsNeighbor(similarity=0.60):+> d;
    b +>:ReportsNeighbor(similarity=1.00):+> b;
    b +>:ReportsNeighbor(similarity=0.50):+> e;
    c +>:ReportsNeighbor(similarity=1.00):+> c;
    c +>:ReportsNeighbor(similarity=0.40):+> f;

    buggy_ledger = TraversalLedger();
    root spawn HrmTraverse(buggy=True, ledger=buggy_ledger);
    print(f"buggy (first-neighbor source): {buggy_ledger.hop_log}");

    fixed_ledger = TraversalLedger();
    root spawn HrmTraverse(buggy=False, ledger=fixed_ledger);
    print(f"fixed (expanded-node source): {fixed_ledger.hop_log}");
}

