"""NuGet cyclic dependency install: in-progress stack breaks recursive install loops."""

node Package {
    has id: str = "";
    has version: str = "";
    has installed: bool = False;
}

edge DependsOn { }

walker PackageInstaller {
    has slim_restore: bool = False;
    has in_progress: list[str] = [];
    has completed: list[str] = [];
    has cycle_short_circuits: int = 0;

    def on_install_stack(pkg_id: str) -> bool {
        for (pid) in self.in_progress {
            if pid == pkg_id {
                return True;
            }
        }
        return False;
    }

    can start with Root entry {
        visit [-->];
    }

    can install_pkg with Package entry {
        if here.installed {
            visit [-->] else { disengage; };
        } else if self.on_install_stack(here.id) {
            self.cycle_short_circuits += 1;
            visit [-->] else { disengage; };
        } else {
            self.in_progress += [here.id];
            if not self.slim_restore {
                visit [->:DependsOn:->];
            }
            here.installed = True;
            label = f"{here.id}@{here.version}";
            self.completed += [label];
            visit [-->] else { disengage; };
        }
    }
}

