"""Code_Book issue #8 graph utilities: model algorithm tasks as nodes, dependencies as typed edges, and walk for cycle detection and topological ordering."""

node WorkItem {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

node BuildTask(WorkItem) {
    has build_minutes: int = 0;
}

node TestTask(WorkItem) {
    has test_cases: int = 0;
}

edge DependsOn { }

walker CycleDetector {
    has on_stack: list = [];
    has finished: list = [];
    has found_cycle: bool = False;

    can start with Root entry {
        visit [-->] else { disengage; };
    }

    can probe with BuildTask | TestTask entry {
        if self.found_cycle {
            disengage;
        }
        for item in self.on_stack {
            if item is here {
                self.found_cycle = True;
                disengage;
            }
        }
        for item in self.finished {
            if item is here {
                disengage;
            }
        }
        self.on_stack.append(here);
        visit [->:DependsOn:->] else { disengage; };
    }

    can unwind with BuildTask | TestTask exit {
        new_stack = [];
        for item in self.on_stack {
            if item is not here {
                new_stack.append(item);
            }
        }
        self.on_stack = new_stack;
        self.finished.append(here);
    }
}

walker TopoPlanner {
    has build_order: list = [];
    has on_stack: list = [];
    has finished: list = [];
    has aborted: bool = False;

    can start with Root entry {
        visit [-->] else { disengage; };
    }

    can descend with BuildTask | TestTask entry {
        if self.aborted {
            disengage;
        }
        for item in self.on_stack {
            if item is here {
                self.aborted = True;
                disengage;
            }
        }
        for item in self.finished {
            if item is here {
                disengage;
            }
        }
        self.on_stack.append(here);
        visit [->:DependsOn:->] else { disengage; };
    }

    can emit with BuildTask | TestTask exit {
        new_stack = [];
        for item in self.on_stack {
            if item is not here {
                new_stack.append(item);
            }
        }
        self.on_stack = new_stack;
        self.finished.append(here);
        if self.aborted {
            disengage;
        }
        already = False;
        for item in self.build_order {
            if item is here {
                already = True;
            }
        }
        if not already {
            self.build_order.append(here);
        }
    }
}

