"""Circuit outline navigation: traverse elements, nets, and subcircuit boundaries with spoken name, role, and connection-context announcements."""

edge Drives { }
edge OnNet { }
edge Contains { }
edge BoundaryPort {
    has direction: str = "in";
}

node OutlineItem {
    has spoken_name: str = "";
    has role_label: str = "";

    def connection_context() -> str {
        return "circuit outline item";
    }
}

node Element(OutlineItem) {
    has element_kind: str = "";

    override def connection_context() -> str {
        return f"{self.element_kind}; follow drives or on-net links to adjacent stops";
    }
}

node Net(OutlineItem) {
    override def connection_context() -> str {
        return "net carrying signal; move along it to elements at the other end";
    }
}

node SubCircuit(OutlineItem) {
    override def connection_context() -> str {
        return "subcircuit boundary; descend into contained items or cross ports";
    }
}

walker CircuitNavigator {
    has max_hops: int = 16;
    has visited_keys: list[str] = [];
    has stop_count: int = 0;

    can start with Root entry {
        print("Keyboard outline traversal: follow connections across nets and subcircuits");
        visit [-->] else { disengage; }
    }

    can announce with Element | Net | SubCircuit entry {
        key = f"{here.role_label}:{here.spoken_name}";
        if key in self.visited_keys {
            print(f"[cycle guard] already visited {here.spoken_name}; disengaging branch");
            disengage;
        }
        if self.stop_count >= self.max_hops {
            print(f"[hop cap] limit reached at {here.spoken_name}");
            disengage;
        }
        self.visited_keys.append(key);
        self.stop_count += 1;
        ctx = here.connection_context();
        print(f"Stop {self.stop_count}: {here.spoken_name}");
        print(f"  role: {here.role_label}");
        print(f"  connection context: {ctx}");
        visit [->:Drives:->];
        visit [<-:Drives:-];
        visit [->:OnNet:->];
        visit [<-:OnNet:-];
        visit [->:Contains:->];
        visit [<-:Contains:-];
        visit [->:BoundaryPort:->];
        visit [<-:BoundaryPort:-];
    }
}

