"""Nutrient rollup for composite foods: fill panel gaps from ingredient components."""

node Food {
    has name: str = "";
    has composite: bool = False;
    has kcal: float = -1.0;
    has protein: float = -1.0;
    has carbs: float = -1.0;
    has fat: float = -1.0;
    has salt: float = -1.0;
    has fiber: float = -1.0;
    has kcal_explicit: bool = False;
    has protein_explicit: bool = False;
    has carbs_explicit: bool = False;
    has fat_explicit: bool = False;
    has salt_explicit: bool = False;
    has fiber_explicit: bool = False;
}

node IngredientRow {
    has amount_g: float = -1.0;
}

edge Includes { }
edge SourceOf { }

walker NutrientRollup {
    has visited: list[str] = [];
    has depth: int = 0;
    has max_depth: int = 10;
    has rolling: bool = False;
    has roll_field: str = "";
    has sum_value: float = 0.0;
    has lower_bound: bool = False;
    has pending_amount_g: float = -1.0;

    def nutrient_value(food: Food, field: str) -> float {
        if field == "salt" {
            return food.salt;
        }
        return food.fiber;
    }

    def set_nutrient(food: Food, field: str, value: float) -> None {
        if field == "salt" {
            food.salt = value;
        } else {
            food.fiber = value;
        }
    }

    def is_explicit(food: Food, field: str) -> bool {
        if field == "salt" {
            return food.salt_explicit;
        }
        return food.fiber_explicit;
    }

    def begin_rollup(field: str) -> None {
        self.rolling = True;
        self.roll_field = field;
        self.sum_value = 0.0;
        self.lower_bound = False;
    }

    def finish_rollup(food: Food) -> None {
        self.set_nutrient(food, self.roll_field, self.sum_value);
        bound_label = "lower bound" if self.lower_bound else "complete";
        print(f"  => {self.roll_field}={self.sum_value} ({bound_label})");
        self.rolling = False;
    }

    def contribute_from(food: Food) -> None {
        if food.composite and food.name in self.visited {
            print(f"[CYCLE] component '{food.name}' revisited during rollup");
            self.lower_bound = True;
            return;
        }
        amount = self.pending_amount_g;
        if amount < 0.0 {
            print(f"[UNKNOWN-QTY] '{food.name}' has no amount_g");
            self.lower_bound = True;
            return;
        }
        val = self.nutrient_value(food, self.roll_field);
        if val < 0.0 {
            print(f"[UNKNOWN-NUTRIENT] '{food.name}' lacks {self.roll_field}");
            self.lower_bound = True;
            return;
        }
        piece = val * (amount / 100.0);
        self.sum_value += piece;
        print(f"    + {food.name}: {self.roll_field} {val}/100g x {amount}g => {piece}");
    }

    can start with Root entry {
        visit [-->];
    }

    can audit with Food entry {
        if self.rolling {
            self.contribute_from(here);
            disengage;
        }
        if not here.composite {
            visit [-->];
        } else {
            if here.name in self.visited {
                print(f"[CYCLE] aborting rollup at '{here.name}'");
                disengage;
            }
            if self.depth >= self.max_depth {
                print(f"[DEPTH] cap reached at '{here.name}'");
                disengage;
            }
            self.visited.append(here.name);
            self.depth += 1;
            print(f"Auditing composite '{here.name}'");

            if not self.is_explicit(here, "salt") {
                print(f"  rolling up missing salt for '{here.name}'");
                self.begin_rollup("salt");
                visit [->:Includes:->] else {
                    print(f"  no ingredients to roll salt from");
                    self.lower_bound = True;
                };
                self.finish_rollup(here);
            }

            if not self.is_explicit(here, "fiber") {
                print(f"  rolling up missing fiber for '{here.name}'");
                self.begin_rollup("fiber");
                visit [->:Includes:->] else {
                    print(f"  no ingredients to roll fiber from");
                    self.lower_bound = True;
                };
                self.finish_rollup(here);
            }

            kcal_tag = "explicit" if here.kcal_explicit else "unknown";
            salt_tag = "explicit" if here.salt_explicit else "rolled";
            fiber_tag = "explicit" if here.fiber_explicit else "rolled";
            print(
                f"Panel {here.name}: kcal={here.kcal} ({kcal_tag}), "
                f"protein={here.protein}, carbs={here.carbs}, fat={here.fat}, "
                f"salt={here.salt} ({salt_tag}), fiber={here.fiber} ({fiber_tag})"
            );
            self.depth -= 1;
            visit [-->];
        }
    }

    can resolve_row with IngredientRow entry {
        if not self.rolling {
            disengage;
        }
        self.pending_amount_g = here.amount_g;
        visit [->:SourceOf:->] else {
            print(f"[UNRESOLVED] ingredient row has no linked food");
            self.lower_bound = True;
        };
    }
}

with entry {
    rotselleri = Food(
        name="Rotselleri",
        salt=0.05,
        fiber=1.8
    );
    morot = Food(name="Morot", salt=0.06, fiber=2.8);
    water = Food(name="Water", salt=0.0, fiber=0.0);

    soup = Food(
        name="Hemlagad Linssoppa",
        composite=True,
        kcal=2350.0,
        protein=137.0,
        carbs=366.0,
        fat=11.0,
        kcal_explicit=True,
        protein_explicit=True,
        carbs_explicit=True,
        fat_explicit=True
    );

    row_celery = IngredientRow(amount_g=160.0);
    row_carrot = IngredientRow(amount_g=195.0);
    row_water = IngredientRow(amount_g=-1.0);

    soup +>:Includes:+> row_celery +>:SourceOf:+> rotselleri;
    soup +>:Includes:+> row_carrot +>:SourceOf:+> morot;
    soup +>:Includes:+> row_water +>:SourceOf:+> water;

    cycle_a = Food(name="CycleA", composite=True);
    cycle_b = Food(name="CycleB", composite=True);
    row_ab = IngredientRow(amount_g=100.0);
    row_ba = IngredientRow(amount_g=100.0);
    cycle_a +>:Includes:+> row_ab +>:SourceOf:+> cycle_b;
    cycle_b +>:Includes:+> row_ba +>:SourceOf:+> cycle_a;

    root ++> soup ++> cycle_a ++> cycle_b;

    root spawn NutrientRollup();
}

