"""Task Tools v3: durable task graph with dependency readiness, immutable attempt history, and acceptance-gated completion — worker stop never implies task completion."""

node Task {
    has title: str = "";
    has status: str = "open";
    has readiness: str = "waiting_dependencies";
    has acceptance: str = "not_submitted";
}

node Attempt {
    has attempt_id: int = 0;
    has attempt_status: str = "started";
}

edge DependsOn { }
edge HasAttempt { }

walker UpstreamAuditor {
    has all_accepted: bool = True;
    has seen: list[str] = [];

    can start with Root entry {
        disengage;
    }

    can audit with Task entry {
        for t in self.seen {
            if t == here.title {
                self.all_accepted = False;
                disengage;
            }
        }
        self.seen.append(here.title);
        if here.status != "completed" || here.acceptance != "accepted" {
            self.all_accepted = False;
        }
        visit [<-:DependsOn:<-] else {
            disengage;
        };
    }
}

walker Orchestrator {
    has claims: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can process with Task entry {
        auditor = UpstreamAuditor();
        here spawn auditor;
        if auditor.all_accepted {
            here.readiness = "ready";
        } else {
            here.readiness = "waiting_dependencies";
        }
        if here.readiness == "ready" && here.status == "open" {
            here.status = "active";
            here.readiness = "claimed";
            att = Attempt(attempt_id=self.claims + 1, attempt_status="started");
            here +>:HasAttempt:+> att;
            self.claims += 1;
            print(f"CLAIM {here.title} token attempt={att.attempt_id}");
        }
        visit [-->];
    }
}

walker AcceptanceGate {
    can start with Root entry {
        visit [-->];
    }

    can review with Task entry {
        if here.acceptance == "pending_review" {
            here.acceptance = "accepted";
            here.status = "completed";
            print(f"ACCEPT {here.title} — completion requires explicit acceptance");
        }
        visit [-->];
    }
}

with entry {
    design = Task(
        title="Design Schema",
        status="completed",
        acceptance="accepted",
        readiness="ready"
    );
    build = Task(title="Build API");
    deploy = Task(title="Deploy Service");
    root ++> design ++> build ++> deploy;
    build +>:DependsOn:+> design;
    deploy +>:DependsOn:+> build;

  print("--- upstream design already accepted ---");
    root spawn Orchestrator();

    print("--- worker terminates without acceptance ---");
    build.status = "open";
    build.readiness = "ready";
    stopped = Attempt(attempt_id=1, attempt_status="abandoned");
    build +>:HasAttempt:+> stopped;
    print(f"WORKER STOP {build.title} status={build.status} acceptance={build.acceptance}");

    print("--- retry reuses task identity, new attempt ---");
    build.status = "active";
    build.readiness = "claimed";
    retry = Attempt(attempt_id=2, attempt_status="submitted");
    build +>:HasAttempt:+> retry;
    build.status = "awaiting_acceptance";
    build.acceptance = "pending_review";
    print(f"RETRY {build.title} attempt={retry.attempt_id} status={build.status}");

    pre = UpstreamAuditor();
    deploy spawn pre;
    blocked_label = "blocked" if not pre.all_accepted else "ready";
    print(f"DEPLOY before build accepted: {blocked_label}");

    root spawn AcceptanceGate();

    post = UpstreamAuditor();
    deploy spawn post;
    ready_label = "ready" if post.all_accepted else "blocked";
    print(f"DEPLOY after build accepted: {ready_label}");

    root spawn Orchestrator();
    print(f"FINAL build={build.status} deploy readiness={deploy.readiness} status={deploy.status}");
}

"""Workflow graphs: versioned generations, dependency scheduling, cycle guards, and crash recovery."""

node WorkflowGraph {
    has name: str = "";
    has version: int = 1;
    has generation: int = 1;
}

node WorkflowNode {
    has label: str = "";
    has status: str = "pending";
    has uncertain_effects: bool = False;
    has retry_count: int = 0;
    has max_retries: int = 3;
    has schedulable: bool = False;
    has resume_safe: bool = False;
}

node Checkpoint {
    has checkpoint_id: str = "";
    has captured_at: str = "";
}

edge DependsOn { }
edge MemberOf { }
edge CheckpointedAt { }

walker DependencyScheduler {
    has ready_count: int = 0;
    has blocked_count: int = 0;

    can start with Root entry {
        visit [-->] else { disengage; }
    }

    can open_graph with WorkflowGraph entry {
        print(
            f"Scheduling {here.name} v{here.version} generation {here.generation}"
        );
        visit [->:MemberOf:->] else { disengage; }
    }

    can evaluate with WorkflowNode entry {
        deps_met = True;
        for prereq in here -->:DependsOn:--> {
            if prereq.status != "succeeded" {
                deps_met = False;
            }
        }
        if here.status == "pending" and deps_met {
            here.schedulable = True;
            self.ready_count += 1;
            print(f"  [READY] {here.label}");
        } else {
            if here.status == "pending" {
                self.blocked_count += 1;
                print(f"  [BLOCKED] {here.label} (waiting on dependencies)");
            } else {
                state_tag = here.status.upper();
                print(f"  [{state_tag}] {here.label}");
            }
        }
        visit [-->] else { disengage; }
    }
}

walker RecoveryAuditor {
    has resume_count: int = 0;
    has skip_count: int = 0;

    can start with Root entry {
        print("Recovery audit after partial failure:");
        visit [-->] else { disengage; }
    }

    can open_graph with WorkflowGraph entry {
        visit [->:MemberOf:->] else { disengage; }
    }

    can inspect with WorkflowNode entry {
        deps_ok = True;
        for prereq in here -->:DependsOn:--> {
            if prereq.status != "succeeded" {
                deps_ok = False;
            }
        }
        has_checkpoint = False;
        for _cp in here -->:CheckpointedAt:--> {
            has_checkpoint = True;
        }
        can_resume = False;
        skip_reason = "";
        if here.status == "failed" or here.status == "running" {
            if deps_ok {
                if here.uncertain_effects and not has_checkpoint {
                    skip_reason = "uncertain effects — no silent replay";
                } else {
                    if here.retry_count >= here.max_retries {
                        skip_reason = "retry budget exhausted";
                    } else {
                        can_resume = True;
                    }
                }
            } else {
                skip_reason = "dependencies incomplete";
            }
        }
        if can_resume {
            here.resume_safe = True;
            here.status = "recovered";
            self.resume_count += 1;
            print(f"  [RESUME] {here.label}");
        } else {
            if here.status == "failed" or here.status == "running" {
                self.skip_count += 1;
                reason_text = skip_reason;
                print(f"  [SKIP] {here.label}: {reason_text}");
            }
        }
        visit [-->] else { disengage; }
    }
}

walker CycleGuard {
    has path: list[str] = [];

    can probe with WorkflowNode entry {
        if here.label in self.path {
            trail = " -> ".join(self.path);
            print(f"[CYCLE] {trail} -> {here.label}");
            disengage;
        }
        self.path.append(here.label);
        visit [->:DependsOn:->];
        self.path.pop();
    }
}

with entry {
    graph = WorkflowGraph(name="DeployPipeline", version=2, generation=3);
    root ++> graph;

    lint = WorkflowNode(label="lint", status="succeeded");
    test = WorkflowNode(label="test", status="succeeded");
    build = WorkflowNode(label="build", status="failed", retry_count=1);
    deploy = WorkflowNode(
        label="deploy", status="failed", uncertain_effects=True
    );
    publish = WorkflowNode(
        label="publish", status="failed", uncertain_effects=True
    );
    publish_cp = Checkpoint(checkpoint_id="cp-42", captured_at="t+120s");

    graph +>:MemberOf:+> lint;
    graph +>:MemberOf:+> test;
    graph +>:MemberOf:+> build;
    graph +>:MemberOf:+> deploy;
    graph +>:MemberOf:+> publish;

    test +>:DependsOn:+> lint;
    build +>:DependsOn:+> test;
    deploy +>:DependsOn:+> build;
    publish +>:DependsOn:+> deploy;
    publish +>:CheckpointedAt:+> publish_cp;

    print("=== Dependency scheduling ===");
    root spawn DependencyScheduler();

    print("");
    print("=== Recovery audit ===");
    root spawn RecoveryAuditor();

    print("");
    print("=== Cycle detection ===");
    task_a = WorkflowNode(label="task_a");
    task_b = WorkflowNode(label="task_b");
    task_c = WorkflowNode(label="task_c");
    root ++> task_a;
    task_a +>:DependsOn:+> task_b;
    task_b +>:DependsOn:+> task_c;
    task_c +>:DependsOn:+> task_a;
    task_a spawn CycleGuard();
}

"""NuGet cyclic dependency install: in-progress stack breaks recursive install loops."""

node Package {
    has id: str = "";
    has version: str = "";
    has installed: bool = False;
}

edge DependsOn { }

walker PackageInstaller {
    has slim_restore: bool = False;
    has in_progress: list[str] = [];
    has completed: list[str] = [];
    has cycle_short_circuits: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can install_pkg with Package entry {
        if here.installed {
            visit [-->] else { disengage; };
        } else {
            if here.id in self.in_progress {
                next_guards = self.cycle_short_circuits + 1;
                self.cycle_short_circuits = next_guards;
                visit [-->] else { disengage; };
            } else {
                self.in_progress.append(here.id);
                if not self.slim_restore {
                    visit [->:DependsOn:->];
                }
                here.installed = True;
                label = f"{here.id}@{here.version}";
                self.completed.append(label);
                visit [-->] else { disengage; };
            }
        }
    }
}

with entry {
    logging = Package(
        id="Chartboost.CSharp.Logging.Unity",
        version="1.1.0",
    );
