    );
    root ++> logging;
    logging +>:DependsOn:+> utilities;
    utilities +>:DependsOn:+> logging;

    full_install = PackageInstaller(slim_restore=False);
    root spawn full_install;

    logging_slim = Package(
        id="Chartboost.CSharp.Logging.Unity",
        version="1.1.0",
    );
    utilities_slim = Package(
        id="Chartboost.CSharp.Utilities.Unity",
        version="1.0.4",
    );
    root ++> logging_slim;
    logging_slim +>:DependsOn:+> utilities_slim;
    utilities_slim +>:DependsOn:+> logging_slim;

    slim_install = PackageInstaller(slim_restore=True);
    root spawn slim_install;

    print(
        f"full install: {full_install.completed}, "
        f"cycle guards={full_install.cycle_short_circuits}"
    );
    print(
        f"slim restore: entry installed={logging_slim.installed}, "
        f"cycle partner installed={utilities_slim.installed}"
    );
}

