"""OpenShell path-glob policy: * matches one segment, ** crosses / boundaries."""

def canonicalize_path(p: str) -> str {
    if p == "" {
        return "/";
    }
    res = p;
    while len(res) > 1 && res.endswith("/") {
        res = res[0:-1];
    }
    if not res.startswith("/") {
        res = "/" + res;
    }
    return res;
}

def split_path_segments(p: str) -> list[str] {
    canon = canonicalize_path(p);
    if canon == "/" {
        return [];
    }
    body = canon[1:];
    if body == "" {
        return [];
    }
    return body.split("/");
}

def match_component_glob(pat: str, seg: str) -> bool {
    return _glob_recurse(pat, seg, 0, 0);
}

def _glob_recurse(pat: str, text: str, pi: int, ti: int) -> bool {
    if pi >= len(pat) {
        return ti >= len(text);
    }
    ch = pat[pi];
    if ch == "*" {
        j = ti;
        while j <= len(text) {
            if _glob_recurse(pat, text, pi + 1, j) {
                return True;
            }
            j += 1;
        }
        return False;
    }
    if ch == "?" {
        if ti >= len(text) {
            return False;
        }
        return _glob_recurse(pat, text, pi + 1, ti + 1);
    }
    if ti >= len(text) || text[ti] != ch {
        return False;
    }
    return _glob_recurse(pat, text, pi + 1, ti + 1);
}

def match_path_segments(pats: list[str], paths: list[str], pi: int, pj: int) -> bool {
    if pi >= len(pats) {
        return pj >= len(paths);
    }
    if pats[pi] == "**" {
        skip = pi;
        while skip < len(pats) && pats[skip] == "**" {
            skip += 1;
        }
        if skip >= len(pats) {
            return True;
        }
        j = pj;
        while j <= len(paths) {
            if match_path_segments(pats, paths, skip, j) {
                return True;
            }
            j += 1;
        }
        return False;
    }
    if pj >= len(paths) {
        return False;
    }
    if not match_component_glob(pats[pi], paths[pj]) {
        return False;
    }
    return match_path_segments(pats, paths, pi + 1, pj + 1);
}

def path_glob_matches(pattern: str, path: str) -> bool {
    pats = split_path_segments(pattern);
    paths = split_path_segments(path);
    return match_path_segments(pats, paths, 0, 0);
}

node PolicySuite {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

node GlobPattern {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has pattern: str = "";
}

node RequestPath {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has path: str = "";
}

edge HasPattern { }

edge TestsAgainst {
    has expect_match: bool = True;
}

walker PathAuditor {
    has active_pattern: str = "";
    has passed: int = 0;
    has failed: int = 0;
    has total: int = 0;

    can start with Root entry {
        print("Auditing path-glob wildcard semantics (OpenShell #2586)");
        visit [-->];
    }

    can audit_suite with PolicySuite entry {
        print(f"Suite: {here.title}");
        visit [->:HasPattern:->];
    }

    can read_pattern with GlobPattern entry {
        self.active_pattern = here.pattern;
        visit [->:TestsAgainst:->];
    }

    can verify with RequestPath entry {
        self.total += 1;
        got = path_glob_matches(self.active_pattern, here.path);
        ok = got == here.expect_match;
        label = "PASS" if ok else "FAIL";
        if ok {
            self.passed += 1;
        } else {
            self.failed += 1;
        }
        print(
            f"[{label}] pattern={self.active_pattern!r} "
            f"path={here.path!r} expected={here.expect_match} got={got}"
        );
        visit [-->] else { disengage; };
    }
}

with entry {
    suite = PolicySuite(title="path-glob acceptance");
    root ++> suite;

    star_v1 = GlobPattern(title="single-segment star", pattern="/v1/*");
    suite +>:HasPattern:+> star_v1;
    star_v1 +>:TestsAgainst(expect_match=True):+> RequestPath(
        title="chat", path="/v1/chat"
    );
    star_v1 +>:TestsAgainst(expect_match=False):+> RequestPath(
        title="nested chat", path="/v1/chat/messages"
    );

    dbl_v1 = GlobPattern(title="recursive double-star", pattern="/v1/**");
    suite +>:HasPattern:+> dbl_v1;
    dbl_v1 +>:TestsAgainst(expect_match=True):+> RequestPath(
        title="prefix only", path="/v1"
    );
    dbl_v1 +>:TestsAgainst(expect_match=True):+> RequestPath(
        title="deep tree", path="/v1/chat/messages"
    );

    repos = GlobPattern(title="middle star segment", pattern="/repos/*/issues");
    suite +>:HasPattern:+> repos;
    repos +>:TestsAgainst(expect_match=True):+> RequestPath(
        title="acme issues", path="/repos/acme/issues"
    );
    repos +>:TestsAgainst(expect_match=False):+> RequestPath(
        title="private nested", path="/repos/acme/private/issues"
    );

  glob_info = GlobPattern(title="leading double-star", pattern="/**/info/refs*");
    suite +>:HasPattern:+> glob_info;
    glob_info +>:TestsAgainst(expect_match=True):+> RequestPath(
        title="git refs", path="/org/repo/info/refs"
    );

    auditor = PathAuditor();
    root spawn auditor;
    print(
        f"Summary: {auditor.passed}/{auditor.total} passed, "
        f"{auditor.failed} failed"
    );
}

