    has attempt_id: int = 0;
    has attempt_status: str = "started";
}

edge DependsOn { }
edge HasAttempt { }

walker Orchestrator {
    has claims: int = 0;
    has probing: bool = False;
    has probe_seen: list[str] = [];
    has probe_ok: bool = True;

    can start with Root entry {
        visit [-->];
    }

    can probe_dep with Task entry {
        if not self.probing {
            disengage;
        }
        for t in self.probe_seen {
            if t == here.title {
                self.probe_ok = False;
                disengage;
            }
        }
        self.probe_seen.append(here.title);
        if here.status != "completed" || here.acceptance != "accepted" {
            self.probe_ok = False;
        }
        visit [->:DependsOn:->] else {
            disengage;
        };
    }

    can process with Task entry {
        if self.probing {
            disengage;
        }
        self.probe_seen = [];
        self.probe_ok = True;
        self.probing = True;
        visit [->:DependsOn:->] else { };
        self.probing = False;
        ready_val = "ready" if self.probe_ok else "waiting_dependencies";
        here.readiness = ready_val;
        if here.readiness == "ready" && here.status == "open" {
            here.status = "active";
            here.readiness = "claimed";
            att = Attempt(attempt_id=self.claims + 1, attempt_status="started");
            here +>:HasAttempt:+> att;
            self.claims += 1;
            print(f"CLAIM {here.title} token attempt={att.attempt_id}");
        }
        visit [-->];
    }
}

