    has deps_met: bool = True;
    has probing: bool = False;
    has probe_seen: list[str] = [];

    can start with Root entry {
        disengage;
    }

    can probe_dep with Task entry {
        if not self.probing {
            disengage;
        }
        for t in self.probe_seen {
            if t == here.title {
                self.deps_met = False;
                disengage;
            }
        }
        self.probe_seen.append(here.title);
        if here.status != "completed" || here.acceptance != "accepted" {
            self.deps_met = False;
        }
        visit [->:DependsOn:->] else {
            disengage;
        };
    }

    can check with Task entry {
        if self.probing {
            disengage;
        }
        self.probe_seen = [];
        self.deps_met = True;
        self.probing = True;
        visit [->:DependsOn:->] else { };
        self.probing = False;
        label = "ready" if self.deps_met else "blocked";
        print(f"DEPLOY dependency check: {label}");
        disengage;
    }
}

