"""Extended argumentation frameworks: named attacks and attacks-on-attacks.

Models EAF/AFRA-style graphs where attack(att1) from a1 to a2 registers a
named attack edge and a3 may undermine that attack instead of an argument.
Survey and chain-resolver walkers traverse Origin, Strikes, and Undermines
edges; an explicit guard set detects cycles because Jac 0.36 does not dedupe
repeated visits on cyclic attack graphs.
"""

node FrameworkEntity {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;

    def tag() -> str {
        return "?";
    }
}

node Argument(FrameworkEntity) {
    has label: str = "";

    override def tag() -> str {
        return self.label;
    }
}

node NamedAttack(FrameworkEntity) {
    has name: str = "";

    override def tag() -> str {
        return self.name;
    }
}

edge Origin { }
edge Strikes { }
edge Undermines { }

walker FrameworkSurvey {
    can start with Root entry {
        print("=== Framework survey ===");
        visit [-->];
    }

    can catalog_argument with Argument entry {
        status = "OK" if here.available else "defeated";
        print(f"Argument {here.tag()} ({here.title}) [{status}]");
        visit [->:Origin:->];
        visit [->:Undermines:->];
    }

    can catalog_attack with NamedAttack entry {
        print(f"  NamedAttack({here.tag()}) — {here.title}");
        visit [->:Strikes:->];
    }

    can show_strike_target with Argument | NamedAttack entry {
        print(f"    strikes -> {here.tag()}");
    }
}

walker ChainResolver {
    has guard: list[str] = [];

    can start with Argument entry {
        print(f"--- Resolve chain from {here.label} ---");
        visit [->:Undermines:->] else {
            print("  (no undermining attacks)");
            disengage;
        };
    }

    can follow_undermine with NamedAttack entry {
        if here.name in self.guard {
            print(f"[CYCLE] named attack {here.name} revisited");
            disengage;
        }
        self.guard.append(here.name);
        print(f"  undermines attack({here.name})");
        visit [->:Strikes:->] else {
            print(f"  attack({here.name}) has no strike target");
            disengage;
        };
    }

    can resolve_argument with Argument entry {
        print(f"  ultimate target: argument {here.label} ({here.title})");
        disengage;
    }

    can resolve_attack_chain with NamedAttack entry {
        if here.name in self.guard {
            print(f"[CYCLE] strike chain through {here.name}");
            disengage;
        }
        self.guard.append(here.name);
        print(f"  attack({here.name}) targets another attack");
        visit [->:Strikes:->] else {
            print(f"  attack({here.name}) has no strike target");
            disengage;
        };
    }
}

walker CycleProbe {
    has guard: list[str] = [];

    can start with Root entry {
        print("=== Cycle probe on reflexive undermining edge ===");
        visit [-->[?:NamedAttack]] else {
            disengage;
        };
    }

    can probe_attack with NamedAttack entry {
        if here.name in self.guard {
            print(f"[CYCLE] detected at attack({here.name})");
            disengage;
        }
        self.guard.append(here.name);
        print(f"  probing attack({here.name})");
        visit [->:Undermines:->] else {
            print("  dead end");
            disengage;
        };
    }
}

with entry {
    a1 = Argument(label="a1", title="Premise", year=1);
    a2 = Argument(label="a2", title="Conclusion", year=2);
    a3 = Argument(label="a3", title="Skeptic", year=3);
    att1 = NamedAttack(name="att1", title="a1 attacks a2", year=10);
    att2 = NamedAttack(name="att2", title="reflexive probe", year=11);

    root ++> a1;
    root ++> a3;
    a1 +>:Origin:+> att1;
    att1 +>:Strikes:+> a2;
    a3 +>:Undermines:+> att1;

    att2 +>:Undermines:+> att2;

    root spawn FrameworkSurvey();
    a3 spawn ChainResolver();
    root spawn CycleProbe();
}

"""JSONB set_path depth guard: parse_path rejects paths whose segment count exceeds MAX_JSONB_DEPTH before set_path can build over-deep documents and serde serialization risks stack overflow."""

node JsonDocument {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has max_depth: int = 1000;
    has value_literal: str = "1";
}

node PathSegment {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has key: str = "k";
    has pos: int = 0;
}

node NestedLevel {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has depth: int = 0;
    has payload: str = "";
}

edge HasPath { }
edge NextSegment { }
edge BuiltRoot { }
edge Nests { }

walker PathAuditor {
    has segment_count: int = 0;
    has max_allowed: int = 1000;
    has active_doc: JsonDocument;

    can start with Root entry {
        visit [-->];
    }

    can audit_doc with JsonDocument entry {
        self.active_doc = here;
        self.max_allowed = here.max_depth;
        self.segment_count = 0;
        visit [->:HasPath:->] else {
            print(f"[REJECT] parse_path: empty path on {here.title}");
            here.available = False;
        };
    }

    can count_segment with PathSegment entry {
        self.segment_count += 1;
        visit [->:NextSegment:->] else {
            if self.segment_count > self.max_allowed {
                self.active_doc.available = False;
                print(
                    f"[REJECT] parse_path: {self.segment_count} segments "
                    f"exceeds MAX_JSONB_DEPTH={self.max_allowed}"
                );
            } else {
                print(
                    f"[OK] parse_path: {self.segment_count} segments "
                    f"<= MAX_JSONB_DEPTH={self.max_allowed}"
                );
            }
        };
    }
}

walker SetPathBuilder {
    has built_depth: int = 0;
    has leaf_value: str = "1";
    has active_doc: JsonDocument;
    has parent_level: NestedLevel;

    can start with Root entry {
        visit [-->];
    }

    can prepare with JsonDocument entry {
        if not here.available {
            print(
                f"[SKIP] set_path on {here.title}: path rejected at parse"
            );
            visit [-->];
        } else {
            self.active_doc = here;
            self.leaf_value = here.value_literal;
            self.built_depth = 0;
            visit [->:HasPath:->] else {
                print(f"[SKIP] set_path on {here.title}: no path");
            };
        }
    }

    can nest with PathSegment entry {
        self.built_depth += 1;
        level = NestedLevel(title=here.title, depth=self.built_depth);
        if self.built_depth == 1 {
            self.active_doc +>:BuiltRoot:+> level;
        } else {
            self.parent_level +>:Nests:+> level;
        }
        self.parent_level = level;
        visit [->:NextSegment:->] else {
            level.payload = self.leaf_value;
            print(
                f"[BUILD] set_path {self.active_doc.title}: "
                f"nested depth={self.built_depth} value={self.leaf_value}"
            );
        };
    }
}

walker SerializeProbe {
    has stack_depth: int = 0;
    has max_safe: int = 1000;

    can start with Root entry {
        visit [-->];
    }

    can status with JsonDocument | NestedLevel entry {
        gate = "open" if here.available else "closed";
        print(f"[STATUS] {here.title}: gate={gate}");
    }

    can probe_doc with JsonDocument entry {
        if not here.available {
            print(
                f"[SKIP SERIALIZE] {here.title}: blocked before "
                f"unbounded serde_json::to_string recursion"
            );
            visit [-->];
        } else {
            visit [->:BuiltRoot:->] else {
                print(f"[SKIP SERIALIZE] {here.title}: nothing built");
            };
        }
    }

    can descend with NestedLevel entry {
        self.stack_depth = here.depth;
        visit [->:Nests:->] else {
            if self.stack_depth > self.max_safe {
                print(
                    f"[RISK] serde to_string stack overflow at depth "
                    f"{self.stack_depth}"
                );
            } else {
                print(
                    f"[SERIALIZE] depth={self.stack_depth} "
                    f"payload={here.payload}"
                );
            }
        };
    }
}

with entry {
    attack = JsonDocument(title="attack_path", max_depth=1000);
    safe = JsonDocument(title="safe_path", max_depth=1000, value_literal="42");
    root ++> attack;
    root ++> safe;

    head_attack = PathSegment(title="k", key="k", pos=0);
    attack +>:HasPath:+> head_attack;
    tail = head_attack;
    for i in range(1, 1001) {
        nxt = PathSegment(title="k", key="k", pos=i);
        tail +>:NextSegment:+> nxt;
        tail = nxt;
    }

    head_safe = PathSegment(title="a", key="a", pos=0);
    safe +>:HasPath:+> head_safe;
    mid_safe = PathSegment(title="b", key="b", pos=1);
    leaf_safe = PathSegment(title="c", key="c", pos=2);
    head_safe +>:NextSegment:+> mid_safe +>:NextSegment:+> leaf_safe;

    root spawn PathAuditor();
    root spawn SetPathBuilder();
    root spawn SerializeProbe();
}

"""Task Tools v3: durable task graph with dependency readiness, immutable attempt history, and acceptance-gated completion — worker stop never implies task completion."""

node Task {
    has title: str = "";
    has status: str = "open";
    has readiness: str = "waiting_dependencies";
    has acceptance: str = "not_submitted";
}

node Attempt {
    has attempt_id: int = 0;
    has attempt_status: str = "started";
}

edge DependsOn { }
edge HasAttempt { }

walker Orchestrator {
    has next_attempt: int = 1;
    has probing: bool = False;
    has probe_seen: list[str] = [];
    has deps_ok: bool = True;

    can start with Root entry {
        visit [-->];
    }

    can walk_deps with Task entry {
        if self.probing {
            for t in self.probe_seen {
                if t == here.title {
                    self.deps_ok = False;
                    disengage;
                }
            }
            self.probe_seen.append(here.title);
            if here.status != "completed" || here.acceptance != "accepted" {
                self.deps_ok = False;
            }
            visit [->:DependsOn:->] else { };
        }
    }

    can evaluate with Task entry {
        if not self.probing {
            self.probe_seen = [];
            self.deps_ok = True;
            self.probing = True;
            visit [->:DependsOn:->] else { };
            self.probing = False;
            ready_label = "ready" if self.deps_ok else "waiting_dependencies";
            here.readiness = ready_label;
            if here.readiness == "ready" && here.status == "open" {
                here.status = "active";
                here.readiness = "claimed";
                att = Attempt(attempt_id=self.next_attempt, attempt_status="started");
                here +>:HasAttempt:+> att;
                self.next_attempt += 1;
                print(f"CLAIM {here.title} attempt={att.attempt_id}");
            }
            visit [-->];
        }
    }
}

walker AcceptanceGate {
    can start with Root entry {
        visit [-->];
    }

    can accept with Task entry {
        if here.acceptance == "pending_review" {
            here.acceptance = "accepted";
            here.status = "completed";
            print(f"ACCEPT {here.title} — completion requires explicit acceptance");
        }
        visit [-->];
    }
}

with entry {
    design = Task(
        title="Design Schema",
        status="completed",
        acceptance="accepted",
        readiness="ready"
    );
    build = Task(title="Build API");
    deploy = Task(title="Deploy Service");
    root ++> design ++> build ++> deploy;
    build +>:DependsOn:+> design;
    deploy +>:DependsOn:+> build;

    print("--- orchestrator selects ready work from accepted deps ---");
    root spawn Orchestrator();

    print("--- worker terminates without acceptance ---");
    build.status = "active";
    build.readiness = "claimed";
    stop_att = Attempt(attempt_id=1, attempt_status="abandoned");
    build +>:HasAttempt:+> stop_att;
    print(f"WORKER STOP {build.title} status={build.status} acceptance={build.acceptance}");

    print("--- retry reuses task identity, new attempt ---");
    retry_att = Attempt(attempt_id=2, attempt_status="submitted");
    build +>:HasAttempt:+> retry_att;
    build.status = "awaiting_acceptance";
    build.acceptance = "pending_review";
    print(f"RETRY {build.title} attempt={retry_att.attempt_id} status={build.status}");

    print("--- explicit acceptance unlocks downstream readiness ---");
    root spawn AcceptanceGate();
    root spawn Orchestrator();

    print(f"FINAL build={build.status} deploy_readiness={deploy.readiness} deploy_status={deploy.status}");
}

