"""ilverify UnsafeAccessor verification: statically validate accessor target resolution without runtime invocation."""

node Assembly {
    has name: str = "";
}

node Member {
    has name: str = "";
    has signature: str = "";
    has available: bool = True;
}

node UnsafeAccessor {
    has name: str = "";
    has target_name: str = "";
    has target_signature: str = "";
}

edge DependsOn { }
edge Defines { }
edge Declares { }
edge ResolvesTo { }

walker IlVerifier {
    has failures: int = 0;
    has passes: int = 0;
    has current_assembly: str = "";
    has resolving: bool = False;

    can start with Root entry {
        print("ilverify --verify-unsafe-accessors");
        visit [-->];
    }

    can scan_assembly with Assembly entry {
        self.current_assembly = here.name;
        print(f"verifying assembly {here.name}");
        visit [->:Defines:->];
        visit [->:Declares:->];
        visit [-->] else { disengage; };
    }

    can on_member with Member entry {
        if self.resolving {
            if here.available {
                print(f"  PASS {here.name}{here.signature} resolved for accessor");
                self.passes += 1;
            } else {
                print(f"  FAIL {here.name}{here.signature} inaccessible after refactor");
                self.failures += 1;
            }
            self.resolving = False;
            disengage;
        }
        print(f"  defines {here.name}{here.signature}");
        visit [-->] else { disengage; };
    }

    can on_accessor with UnsafeAccessor entry {
        self.resolving = True;
        visit [->:ResolvesTo:->] else {
            print(f"  FAIL {here.name} -> {here.target_name}{here.target_signature} not resolved");
            self.failures += 1;
            self.resolving = False;
            disengage;
        };
        disengage;
    }
}

with entry {
    core = Assembly(name="LibCore");
    helper = Assembly(name="LibHelper");

    core +>:DependsOn:+> helper;
