"""Leaderboard assembly: walk the match log, tally per-model rates, and group rivals by connectivity."""

node League {
    has category: str = "default";
    has total_votes: int = 0;
}

node Model {
    has model_id: str = "";
    has rating: int = 1000;
    has games: int = 0;
    has wins: float = 0.0;
    has decisive_games: int = 0;
    has decisive_wins: int = 0;
    has tie_count: int = 0;
    has both_bad_count: int = 0;
    has provisional: bool = True;
    has component: int = -1;
}

node Match {
    has kind: str = "decisive";
    has score_lo: float = 1.0;
    has blind: bool = True;
}

edge LoSide { }
edge HiSide { }

walker MatchTally {
    has active_kind: str = "decisive";
    has active_score: float = 1.0;
    has on_lo_side: bool = True;

    can start with Root entry {
        visit [-->];
    }

    can count with Match entry {
        self.active_kind = here.kind;
        self.active_score = here.score_lo;
        self.on_lo_side = True;
        visit [->:LoSide:->];
        self.on_lo_side = False;
        visit [->:HiSide:->];
        visit [-->];
    }

    can credit with Model entry {
        here.games += 1;
        if self.on_lo_side {
            contrib = self.active_score;
        } else {
            contrib = 1.0 - self.active_score;
        }
        here.wins += contrib;
        if self.active_kind == "decisive" {
            here.decisive_games += 1;
            if contrib >= 1.0 {
                here.decisive_wins += 1;
            }
        } else {
            if self.active_kind == "tie" {
                here.tie_count += 1;
            } else {
                if self.active_kind == "both_bad" {
                    here.both_bad_count += 1;
                }
            }
        }
    }
}

walker ComponentGrouper {
    has comp: int = 0;
    has stamp: list[str] = [];
    has flooding: bool = False;

    can start with Root entry {
        visit [-->[?:Model]] else { disengage; }
    }

    can partition with Model entry {
        if here.model_id in self.stamp {
            disengage;
        }
        if not self.flooding {
            if here.component >= 0 {
                visit [-->];
            } else {
                self.comp += 1;
                self.stamp = [];
                self.flooding = True;
                here.component = self.comp;
                self.stamp.append(here.model_id);
                visit [<-:LoSide:<-];
                visit [<-:HiSide:<-];
                self.flooding = False;
                visit [-->];
            }
        } else {
            here.component = self.comp;
            self.stamp.append(here.model_id);
            visit [<-:LoSide:<-];
            visit [<-:HiSide:<-];
        }
    }

    can cross with Match entry {
        visit [->:LoSide:->];
        visit [->:HiSide:->];
    }
}

walker LeaderboardReporter {
    has known_ids: list[str] = [];
    has unrated: list[str] = [];

    can start with Root entry {
        visit [-->[?:Model]] else { disengage; }
    }

    can report with Model entry {
        if here.games == 0 {
            if here.model_id in self.known_ids {
                self.unrated.append(here.model_id);
            }
        } else {
            flag = "provisional" if here.games < 10 else "rated";
            if here.decisive_games > 0 {
                wr = here.decisive_wins / here.decisive_games;
            } else {
                wr = None;
            }
            tr = here.tie_count / here.games;
            br = here.both_bad_count / here.games;
            print(
                f"{here.model_id} comp={here.component} rating={here.rating} "
                f"games={here.games} wins={here.wins} win_rate={wr} "
                f"tie_rate={tr} both_bad_rate={br} {flag}"
            );
        }
        visit [-->];
    }
}

with entry {
    league = League(category="default");
    a = Model(model_id="A", rating=1050);
    b = Model(model_id="B", rating=950);
    c = Model(model_id="C");
    root ++> league ++> a ++> b ++> c;

    m1 = Match(kind="decisive", score_lo=1.0);
    m2 = Match(kind="decisive", score_lo=1.0);
    m3 = Match(kind="tie", score_lo=0.5);
    m4 = Match(kind="both_bad", score_lo=0.5);
    root ++> m1 ++> m2 ++> m3 ++> m4;
    m1 +>:LoSide:+> a;
    m1 +>:HiSide:+> b;
    m2 +>:LoSide:+> a;
    m2 +>:HiSide:+> b;
    m3 +>:LoSide:+> a;
    m3 +>:HiSide:+> b;
    m4 +>:LoSide:+> a;
    m4 +>:HiSide:+> b;

    tally = MatchTally();
    root spawn tally;
    league.total_votes = 4;

    root spawn ComponentGrouper();
    root spawn LeaderboardReporter(known_ids=["A", "B", "C"]);

    print(f"total_votes={league.total_votes}");
    print(f"unrated_models={['C']}");
}

"""TableEvent v1: adapt table-kit ledger rows to dmcheck transcript semantics and refuse false-clean handoffs."""

node Session {
    has session_id: str = "";
    has campaign_id: str = "";
    has closed: bool = False;
}

node LedgerRow {
    has event_id: str = "";
    has actor: str = "";
    has text: str = "";
    has sequence: int = 0;
    has event_type: str = "";
}

node TranscriptEvent {
    has event_id: str = "";
    has author: str = "";
    has content: str = "";
    has correlation_id: str = "";
    has provenance: str = "observed";
}

edge InSession { }
edge AdaptedTo { has preserved_event_id: str = ""; }

walker CompatibilityAdapter {
    has compatible: int = 0;
    has examined: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can open_session with Session entry {
        self.compatible = 0;
        self.examined = 0;
        print(f"=== session {here.session_id} (campaign {here.campaign_id}) ===");
        visit [->:InSession:->] else {
            print("empty ledger");
            disengage;
        };
    }

    can adapt_row with LedgerRow entry {
        self.examined += 1;
        if here.actor == "" and here.text == "" {
            print(f"[SKIP] {here.event_id} ({here.event_type}): incompatible actor/text");
        } else {
            author = here.actor;
            content = here.text;
            tx = TranscriptEvent(
                event_id=here.event_id,
                author=author,
                content=content,
                correlation_id=here.event_id,
                provenance="observed"
            );
            here +>:AdaptedTo(preserved_event_id=here.event_id):+> tx;
            self.compatible += 1;
            print(f"[ADAPT] {here.event_id} ({here.event_type}): actor to author, text to content");
        }
        visit [-->] else {
            outcome = "REFUSE" if (self.examined > 0 and self.compatible == 0) else "OK";
            if outcome == "REFUSE" {
                print("REFUSE: zero-compatible input would false-clean");
            } else {
                print(f"Adapted {self.compatible}/{self.examined} rows");
            }
            disengage;
        };
    }
}

walker CorrelationAuditor {
    has preserved: int = 0;
    has gaps: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can audit_session with Session entry {
        visit [->:InSession:->];
    }

    can audit_row with LedgerRow entry {
        visit [->:AdaptedTo:->] else {
            self.gaps += 1;
            print(f"[GAP] {here.event_id}: no adapter output");
        };
        visit [-->] else {
            disengage;
        };
    }

    can verify with TranscriptEvent entry {
        if here.correlation_id == here.event_id and here.author != "" {
            self.preserved += 1;
            print(f"[JOIN] {here.event_id} identity and correlation preserved");
        } else {
            print(f"[BREAK] {here.event_id} join reference broken");
        }
    }
}

