"""A2 audit: trace identity, persistence, and authorization invariants across framework entrypoints."""

node Principal {
    has principal_id: str = "";
    has tenant: str = "";
}

node EntityRecord {
    has record_id: str = "";
    has machine_name: str = "";
    has cache_valid: bool = True;
}

node EntryPoint {
    has surface: str = "";
    has path: str = "";
}

node PolicyEngine {
    has engine_name: str = "";
    has authoritative: bool = True;
}

edge RoutesTo { }
edge Persists { }
edge Governs { }
edge AlternateOf { }

walker AuditTracer {
    has findings: list[str] = [];
    has seen_paths: list[str] = [];

    can start with Root entry {
        print("FW-ARCH-2026-08 A2: auditing identity, persistence, authorization");
        visit [-->];
    }

    can inspect with EntryPoint entry {
        label = f"{here.surface}:{here.path}";
        if label in self.seen_paths {
            self.findings.append(f"cycle at entrypoint {label}");
            disengage;
        }
        self.seen_paths.append(label);
        print(f"[ENTRY] {label}");
        visit [->:RoutesTo:->];
        visit [->:Governs:->];
        visit [->:Persists:->];
        visit [-->];
    }

    can verify_identity with Principal entry {
        scope = f"{here.principal_id}@{here.tenant}";
        print(f"  identity round-trip OK: {scope}");
        visit [-->] else { disengage; };
    }

    can verify_policy with PolicyEngine entry {
        role = "authoritative" if here.authoritative else "alternate";
        print(f"  policy engine {here.engine_name} [{role}]");
        if not here.authoritative {
            self.findings.append(f"divergent policy engine: {here.engine_name}");
        }
        visit [->:AlternateOf:->];
        visit [-->] else { disengage; };
    }

    can verify_record with EntityRecord entry {
        identity = f"id={here.record_id} name={here.machine_name}";
        print(f"  persistence round-trip OK: {identity}");
        if here.cache_valid {
            here.cache_valid = False;
            print(f"  cache invalidated for record {here.record_id}");
            self.findings.append(f"cache invalidated: {here.record_id}");
        }
        visit [-->] else { disengage; };
    }
}

