    root ++> m1 ++> m2 ++> m3 ++> m4;
    m1 +>:LoSide:+> a;
    m1 +>:HiSide:+> b;
    m2 +>:LoSide:+> a;
    m2 +>:HiSide:+> b;
    m3 +>:LoSide:+> a;
    m3 +>:HiSide:+> b;
    m4 +>:LoSide:+> a;
