"""NMP clone shrink: audit MP3 reachability across retained refs, gate on an exclusive maintenance window, rewrite master history, and block new binaries."""

edge RefTip { }
edge AncestorOf { }
edge TracksBlob { }
edge HostedAt { }

node MaintenanceWindow {
    has exclusive: bool = False;
    has backup_ready: bool = False;
    has refs_inventoried: bool = False;
    has master_sha: str = "";
}

node GitRef {
    has ref_name: str = "";
    has retained: bool = True;
}

node Commit {
    has sha: str = "";
    has rewritten: bool = False;
}

node Mp3Blob {
    has path: str = "";
    has size_mib: float = 0.0;
    has externalized: bool = False;
}

node ReleaseStore {
    has url_base: str = "";
}

walker MaintenanceGate {
    has cleared: bool = False;

    can start with Root entry {
        visit [-->];
    }

    can validate with MaintenanceWindow entry {
        ready = here.exclusive and here.backup_ready and here.refs_inventoried;
        if ready {
            self.cleared = True;
            print(f"Gate cleared for master@{here.master_sha}");
        } else {
            print("Gate blocked: exclusive maintenance window requirements unmet");
            disengage;
        }
        visit [-->];
    }
}

walker ReachabilityAuditor {
    has blob_count: int = 0;
    has total_mib: float = 0.0;
    has seen_shas: list[str] = [];

    can start with Root entry {
        visit [->:RefTip:->] else {
            print(f"Reachable: {self.blob_count} MP3s, {self.total_mib:.2f} MiB");
            disengage;
        };
    }

    can scan_ref with GitRef entry {
        if here.retained {
            print(f"Scanning retained ref: {here.ref_name}");
            visit [->:RefTip:->];
        }
        visit [-->];
    }

    can walk_commit with Commit entry {
        if here.sha in self.seen_shas {
            disengage;
        }
        self.seen_shas.append(here.sha);
        visit [->:AncestorOf:->];
        visit [->:TracksBlob:->];
    }

    can tally with Mp3Blob entry {
        if not here.externalized {
            self.blob_count += 1;
            self.total_mib += here.size_mib;
            print(f"  reachable blob: {here.path} ({here.size_mib} MiB)");
        }
    }
}

walker HistoryRewriter {
    has stripped: int = 0;

    can start with Root entry {
        visit [->:RefTip:->];
    }

    can rewrite_ref with GitRef entry {
        if here.ref_name == "master" {
            visit [->:RefTip:->];
        }
        visit [-->];
    }

    can rewrite_commit with Commit entry {
        if not here.rewritten {
            here.rewritten = True;
            visit [->:TracksBlob:->];
        }
        visit [->:AncestorOf:->];
    }

    can strip_blob with Mp3Blob entry {
        if not here.externalized {
            here.externalized = True;
            self.stripped += 1;
            print(f"Removed from rewritten history: {here.path}");
        }
    }
}

walker BinaryGuard {
    has rejected: bool = False;

    can start with Root entry {
        visit [->:RefTip:->] else { disengage; };
    }

    can scan_ref with GitRef entry {
        if here.retained {
            visit [->:RefTip:->];
        }
        visit [-->];
    }

    can walk_commit with Commit entry {
        visit [->:TracksBlob:->];
        visit [->:AncestorOf:->];
    }

    can reject with Mp3Blob entry {
        if not here.externalized {
            print(f"PREVENTION: rejected unapproved binary {here.path} ({here.size_mib} MiB)");
            self.rejected = True;
            disengage;
        }
    }
}

with entry {
    store = ReleaseStore(url_base="https://releases.example/nmp/audio");
    gate = MaintenanceWindow(
        exclusive=True,
        backup_ready=True,
        refs_inventoried=True,
        master_sha="7620c3a5"
    );

    c1_old = Commit(sha="aaa111-old");
    c1_new = Commit(sha="aaa111-new", rewritten=True);
    c2 = Commit(sha="bbb222");
    c3 = Commit(sha="ccc333");

    mp3_old = Mp3Blob(path="docs/legacy/chime.mp3", size_mib=2.1);
    mp3_pulse = Mp3Blob(path="docs/status/reports/pulse.mp3", size_mib=3.5);
    mp3_esc = Mp3Blob(path="docs/escalation/alert.mp3", size_mib=49.31);

    master = GitRef(ref_name="master", retained=True);
    stale_tag = GitRef(ref_name="v1-archive", retained=True);

    root ++> gate;
    root +>:RefTip:+> master;
    root +>:RefTip:+> stale_tag;

    master +>:RefTip:+> c3;
    c3 +>:AncestorOf:+> c2;
    c2 +>:AncestorOf:+> c1_new;

    stale_tag +>:RefTip:+> c1_old;

    c1_old +>:TracksBlob:+> mp3_old;
