    c3 +>:TracksBlob:+> mp3_esc;

    mp3_old +>:HostedAt:+> store;
    mp3_pulse +>:HostedAt:+> store;
    mp3_esc +>:HostedAt:+> store;

    print("=== Pre-rewrite reachability (master + stale tag) ===");
    root spawn ReachabilityAuditor();

    print("=== Maintenance gate ===");
    root spawn MaintenanceGate();

    print("=== Rewrite master ancestry only ===");
    rewriter = HistoryRewriter();
    root spawn rewriter;
    print(f"Stripped {rewriter.stripped} blobs from master chain");

    print("=== Post-rewrite reachability (stale tag still retains old blob) ===");
    root spawn ReachabilityAuditor();

    stale_tag.retained = False;
