"""prod_dgx_full load characterisation: feeds, staged episodes, and a GO/NO-GO audit."""

node Feed {
    has name: str = "";
    has episode_quota: int = 1;
}

node Episode {
    has label: str = "";
    has transcribe_sec: float = 0.0;
    has summary_sec: float = 0.0;
    has total_sec: float = 0.0;
    has gpu_temp_peak: float = 0.0;
    has gpu_util_avg: float = 0.0;
    has gates_pass: bool = True;
    has had_ollama_fallback: bool = False;
    has processed: bool = False;
}

node Stage {
    has name: str = "";
    has wall_sec: float = 0.0;
    has gpu_util: float = 0.0;
}

edge InFeed { }

edge StageNext { }

edge StartsPipeline { }

walker BatchProcessor {
    has single_flight_busy: bool = False;
    has idle_gaps: int = 0;
    has episodes_done: int = 0;

    can start with Root entry {
        print("prod_dgx_full: serial stage runner (single-flight lock)");
        visit [-->];
    }

    can open_feed with Feed entry {
        print(f"feed {here.name} quota={here.episode_quota}");
        visit [->:InFeed:->];
    }

    can run_episode with Episode entry {
        if here.processed {
            visit [-->];
        } else {
            print(f"  episode {here.label}");
            visit [->:StartsPipeline:->];
            here.processed = True;
            self.episodes_done += 1;
            visit [-->];
        }
    }

    can execute_stage with Stage entry {
        if self.single_flight_busy {
            self.idle_gaps += 1;
            print(f"    idle gap before {here.name} (lock held)");
        }
        self.single_flight_busy = True;
        print(f"    stage {here.name}: {here.wall_sec}s util={here.gpu_util}%");
        visit [->:StageNext:->] else {
            self.single_flight_busy = False;
        }
    }
}

walker LoadAuditor {
    has phase_label: str = "Phase A";
    has peak_temp: float = 0.0;
    has sum_util: float = 0.0;
    has util_samples: int = 0;
    has any_ollama: bool = False;
    has any_gate_fail: bool = False;
    has go: bool = True;

    can start with Root entry {
        print(f"{self.phase_label} measurement audit");
        visit [-->];
    }

    can tally_feed with Feed entry {
        visit [->:InFeed:->];
    }

    can measure with Episode entry {
        temp_peak = here.gpu_temp_peak;
        if temp_peak > self.peak_temp {
            self.peak_temp = temp_peak;
        }
        self.sum_util += here.gpu_util_avg;
        self.util_samples += 1;
        if here.had_ollama_fallback {
            self.any_ollama = True;
        }
        if not here.gates_pass {
            self.any_gate_fail = True;
        }
        print(
            f"  [{here.label}] total={here.total_sec}s "
            f"temp={here.gpu_temp_peak}C util={here.gpu_util_avg}% "
            f"gates={'PASS' if here.gates_pass else 'FAIL'}"
        );
        visit [-->];
    }

    can verdict with Root exit {
        avg_util = 0.0;
        if self.util_samples > 0 {
            avg_util = self.sum_util / self.util_samples;
        }
        thermal_ok = self.peak_temp <= 80.0;
        gates_ok = not self.any_gate_fail;
        fallback_ok = not self.any_ollama;
        self.go = thermal_ok and gates_ok and fallback_ok;
        go_label = "GO" if self.go else "NO-GO";
        print(
            f"audit: peak_temp={self.peak_temp}C avg_util={avg_util}% "
            f"ollama_fallback={self.any_ollama} gates_fail={self.any_gate_fail} "
            f"-> {go_label}"
        );
        disengage;
    }
}

