    has selection_enabled: bool = False;
    has labels_configured: int = 0;
    has visit_depth: int = 0;
    has max_depth: int = 32;

    can start with Root entry {
        visit [->:Child:->] else { disengage; };
    }

    can enter_modifier with TextSelectionModifier entry {
        if self.visit_depth >= self.max_depth {
            disengage;
        }
        self.visit_depth += 1;
        self.selection_enabled = here.enabled;
        mode = "enabled" if here.enabled else "disabled";
        print(f"textSelection({mode}) on '{here.name}'");
        visit [->:Child:->] else { disengage; };
        self.visit_depth -= 1;
    }

    can descend with Container entry {
        if self.visit_depth >= self.max_depth {
            disengage;
        }
        self.visit_depth += 1;
        visit [->:Child:->] else { disengage; };
        self.visit_depth -= 1;
    }

    can configure with GtkLabel | WebText entry {
        here.apply_selection(self.selection_enabled);
        self.labels_configured += 1;
    }
}

