"""TableEvent v1: adapt table-kit ledger rows to dmcheck transcript semantics and refuse false-clean handoffs."""

edge InSession { }
edge AdaptedTo { has preserved_event_id: str = ""; }

node Session {
    has session_id: str = "";
    has campaign_id: str = "";
    has closed: bool = False;
}

node LedgerRow {
    has event_id: str = "";
    has actor: str = "";
    has text: str = "";
    has sequence: int = 0;
    has event_type: str = "";
}

node TranscriptEvent {
    has event_id: str = "";
    has author: str = "";
    has content: str = "";
    has correlation_id: str = "";
    has provenance: str = "observed";
}

walker CompatibilityAdapter {
    has compatible: int = 0;
    has examined: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can open_session with Session entry {
        self.compatible = 0;
        self.examined = 0;
        print(f"=== session {here.session_id} (campaign {here.campaign_id}) ===");
        visit [->:InSession:->] else {
            print("empty ledger");
            disengage;
        };
    }

    can adapt_row with LedgerRow entry {
        self.examined += 1;
        if here.actor == "" and here.text == "" {
            print(f"[SKIP] {here.event_id} ({here.event_type}): incompatible actor/text");
        } else {
            author = here.actor;
            content = here.text;
            tx = TranscriptEvent(
                event_id=here.event_id,
                author=author,
                content=content,
                correlation_id=here.event_id,
                provenance="observed"
            );
            here +>:AdaptedTo(preserved_event_id=here.event_id):+> tx;
            self.compatible += 1;
            print(f"[ADAPT] {here.event_id} ({here.event_type}): actor to author, text to content");
        }
        visit [-->] else {
            outcome = "REFUSE" if (self.examined > 0 and self.compatible == 0) else "OK";
            if outcome == "REFUSE" {
                print("REFUSE: zero-compatible input would false-clean");
            } else {
                print(f"Adapted {self.compatible}/{self.examined} rows");
            }
            disengage;
        };
    }
}

walker CorrelationAuditor {
    has preserved: int = 0;
    has gaps: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can audit_session with Session entry {
        visit [->:InSession:->];
    }

    can audit_row with LedgerRow entry {
        visit [->:AdaptedTo:->] else {
            self.gaps += 1;
            print(f"[GAP] {here.event_id}: no adapter output");
        };
        visit [-->] else {
            disengage;
        };
    }

    can verify with TranscriptEvent entry {
        if here.correlation_id == here.event_id and here.author != "" {
            self.preserved += 1;
            print(f"[JOIN] {here.event_id} identity and correlation preserved");
        } else {
            print(f"[BREAK] {here.event_id} join reference broken");
        }
        visit [-->];
    }
}

