"""Astro-plan topology: dependency resolution and cascade invalidation over native typed edges."""

node AstroPlan {
    has title: str = "";
    has status: str = "pending";
    has valid: bool = True;
}

node Target {
    has name: str = "";
    has magnitude: float = 0.0;
    has reachable: bool = True;
}

edge DependsOn {
    has rule: str = "";
}

edge Observes {
    has exposure_sec: int = 60;
}

walker DependencyResolver {
    has visited: list[str] = [];
    has order: list[str] = [];
    has cycle_found: bool = False;

    can resolve with AstroPlan entry {
        if here.title in self.visited {
            self.cycle_found = True;
            print(f"  CYCLE detected at '{here.title}' — halting branch");
            disengage;
        }
        self.visited.append(here.title);
        print(f"  prerequisite: {here.title} (status={here.status})");
        visit [->:DependsOn:->] else { disengage; };
        self.order.append(here.title);
    }
}

walker CascadeInvalidator {
    has visited: list[str] = [];

    can invalidate with AstroPlan entry {
        if here.title in self.visited {
            disengage;
        }
        self.visited.append(here.title);
        here.valid = False;
        here.status = "invalidated";
        print(f"  cascade -> '{here.title}'");
        visit [<-:DependsOn:<-] else { disengage; };
    }
}

walker PlanCatalog {
    can start with Root entry {
        print("Final topology state:");
        visit [-->];
    }

    can show_plan with AstroPlan entry {
        valid_tag = "VALID" if here.valid else "INVALID";
        print(f"  [{valid_tag}] {here.title} — {here.status}");
        visit [->:Observes:->] else { disengage; };
        visit [-->];
    }

    can show_target with Target entry {
        vis_tag = "visible" if here.reachable else "blocked";
        print(f"  [TARGET] {here.name} (mag={here.magnitude}, {vis_tag})");
    }
}

with entry {
    telemetry = AstroPlan(title="telemetry-check", status="ready");
    weather = AstroPlan(title="weather-window", status="ready");
    launch = AstroPlan(title="launch-sequence", status="ready");
    imaging = AstroPlan(title="deep-imaging", status="pending");
    m31 = Target(name="M31", magnitude=3.4, reachable=True);

    root ++> telemetry ++> weather ++> launch ++> imaging;
    launch +>:DependsOn(rule="window"):+> weather;
    launch +>:DependsOn(rule="telemetry"):+> telemetry;
    imaging +>:DependsOn(rule="sequence"):+> launch;
    imaging +>:Observes(exposure_sec=300):+> m31;

    print("=== Dependency resolution (native walk vs SQLite recursive CTE) ===");
    print(f"Resolving dependencies for '{imaging.title}'");
    resolver = DependencyResolver();
    imaging spawn resolver;
    result_tag = "CYCLIC" if resolver.cycle_found else "acyclic";
    print(f"Resolution complete ({result_tag}): {resolver.order}");

    print("=== Cascade invalidation (transactional CAS propagation) ===");
    print(f"Invalidating seed plan '{weather.title}'");
    cascade = CascadeInvalidator();
    weather spawn cascade;

    root spawn PlanCatalog();
}

"""Internal data network: cables, switches, risers, and connected-component flow routing."""

node NetworkEndpoint {
    has name: str = "";
    has floor: int = 0;
    has online: bool = True;
    has flops: int = 0;
}

node DataSwitch {
    has name: str = "";
    has floor: int = 0;
    has online: bool = True;
}

edge DataCable {
    has bandwidth: int = 100;
    has latency_ms: int = 1;
    has condition: float = 1.0;
}

edge VerticalRiser {
    has bandwidth: int = 50;
    has latency_ms: int = 5;
    has condition: float = 1.0;
}

walker ComponentScanner {
    has label: str = "facility";
    has members: list[str] = [];
    has seen: list[str] = [];

    can scan with NetworkEndpoint | DataSwitch entry {
        if here.name in self.seen {
            disengage;
        }
        if not here.online {
            print(f"[scan:{self.label}] offline barrier at {here.name}");
            disengage;
        }
        self.seen.append(here.name);
        self.members.append(here.name);
        visit [->:DataCable:->] else {
            visit [->:VerticalRiser:->] else {
                print(
                    f"[scan:{self.label}] component size={len(self.members)} "
                    f"members={self.members}"
                );
                disengage;
            };
        };
    }
}

walker FlowRouter {
    has target: str = "";
    has seen: list[str] = [];
    has reachable: bool = False;
    has prev_floor: int = -1;
    has min_bandwidth: int = 9999;
    has total_latency: int = 0;

    can route with NetworkEndpoint | DataSwitch entry {
        if here.name in self.seen {
            disengage;
        }
        if not here.online {
            print(f"[flow] broken node {here.name} invalidates path this tick");
            disengage;
        }
        self.seen.append(here.name);
        if self.prev_floor >= 0 {
            if here.floor != self.prev_floor {
                self.total_latency += 5;
                hop_bw = 50;
            } else {
                self.total_latency += 1;
                hop_bw = 100;
            }
            next_min = hop_bw if hop_bw < self.min_bandwidth else self.min_bandwidth;
            self.min_bandwidth = next_min;
        }
        self.prev_floor = here.floor;
        if here.name == self.target {
            self.reachable = True;
            print(
                f"[flow] route OK hops={self.seen} "
                f"bottleneck={self.min_bandwidth}Mbps "
                f"latency={self.total_latency}ms"
            );
            disengage;
        }
        visit [->:DataCable:->] else {
            visit [->:VerticalRiser:->] else {
                print(
                    f"[flow] no data path to {self.target} "
                    f"(visited={self.seen})"
                );
                disengage;
            };
        };
    }
}

with entry {
    gateway = NetworkEndpoint(name="gateway", floor=0, flops=120);
    storage = NetworkEndpoint(name="storage", floor=1, flops=800);
    compute = NetworkEndpoint(name="compute", floor=1, flops=400);
    orphan = NetworkEndpoint(name="orphan", floor=2, flops=90);

    sw_ground = DataSwitch(name="sw-ground", floor=0);
    sw_orbit = DataSwitch(name="sw-orbit", floor=1);

    root ++> gateway ++> sw_ground;
    root ++> storage ++> compute ++> orphan;

    gateway +>:DataCable(bandwidth=100, latency_ms=1, condition=1.0):+> sw_ground;
    sw_ground
        +>:VerticalRiser(bandwidth=50, latency_ms=5, condition=0.95):+> sw_orbit;
    sw_orbit +>:DataCable(bandwidth=100, latency_ms=1, condition=1.0):+> storage;
    sw_orbit +>:DataCable(bandwidth=80, latency_ms=2, condition=0.9):+> compute;

    print("=== connected component from gateway (cross-floor via riser) ===");
    gateway spawn ComponentScanner(label="ground-mesh");

    print("=== isolated endpoint (no data edges) ===");
    orphan spawn ComponentScanner(label="isolated");

    print("=== FLOPS share attempt: gateway -> storage (same component) ===");
    ok = FlowRouter(target="storage");
    gateway spawn ok;
    if ok.reachable {
        shared = gateway.flops + storage.flops;
        print(f"[flops] shared pool={shared} across connected endpoints");
    } else {
        print("[flops] BLOCKED: disconnected components cannot share FLOPS");
    }

    print("=== deterministic reroute after switch failure on same tick ===");
    sw_ground.online = False;
    retry = FlowRouter(target="storage");
    gateway spawn retry;
    if retry.reachable {
        print("[flops] reroute succeeded");
    } else {
        print(
            "[flops] BLOCKED after failure: no alternate data path this tick"
        );
    }
}

"""User scalar functions: call-graph cycle guard, work tally, and elementwise lifting."""

node ScalarFn {
    has name: str = "";
    has work_per_element: int = 0;
    has on_path: bool = False;
    has resolved: bool = False;
}

node Formal {
    has name: str = "";
    has dtype: str = "Double";
}

node FormalRef {
    has formal_name: str = "";
    has value: float = 0.0;
}

node BuiltinCall {
    has op: str = "";
    has scalar_work: int = 1;
    has value: float = 0.0;
}

node InputElt {
    has value: float = 0.0;
    has lifted: float = 0.0;
}

edge HasFormal { }
edge Depends { }
edge BodyRoot { }
edge LeftArg { }
edge RightArg { }
edge ReadsFormal { }
edge Applies { }

walker CycleGuard {
    has found_cycle: bool = False;
    has cycle_at: str = "";

    can start with Root entry {
        visit [-->];
        if self.found_cycle {
            print(f"CYCLE_REJECTED: mutual recursion at {self.cycle_at}");
        } else {
            print("CALL_GRAPH: acyclic");
        }
    }

    can probe with ScalarFn entry {
        if self.found_cycle {
            disengage;
        }
        if here.on_path {
            self.found_cycle = True;
            self.cycle_at = here.name;
            disengage;
        }
        here.on_path = True;
        visit [->:Depends:->] else { disengage; };
        here.on_path = False;
        visit [-->];
    }
}

walker WorkResolver {
    has scratch: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can resolve with ScalarFn entry {
        if here.resolved {
            visit [-->];
        }
        visit [->:Depends:->] else { disengage; };
        self.scratch = 0;
        visit [->:BodyRoot:->] else { disengage; };
        here.work_per_element = self.scratch;
        here.resolved = True;
        print(f"work({here.name}) = {here.work_per_element}");
        visit [-->];
    }

    can count_builtin with BuiltinCall entry {
        self.scratch += here.scalar_work;
        visit [->:LeftArg:->] else { disengage; };
        visit [->:RightArg:->] else { disengage; };
    }
}

walker LiftEval {
    has scalar_x: float = 0.0;
    has arg_value: float = 0.0;

    can start with Root entry {
        visit [-->];
    }

    can lift with InputElt entry {
        self.scalar_x = here.value;
        visit [->:Applies:->] else { disengage; };
        here.lifted = self.arg_value;
        print(f"square({self.scalar_x}) = {here.lifted}");
        visit [-->];
    }

    can enter_fn with ScalarFn entry {
        visit [->:BodyRoot:->] else { disengage; };
    }

    can eval_ref with FormalRef entry {
        here.value = self.scalar_x;
        self.arg_value = here.value;
    }

    can eval_mul with BuiltinCall entry {
        if here.op != "mul" {
            disengage;
        }
        visit [->:LeftArg:->] else { disengage; };
        left_v = self.arg_value;
        visit [->:RightArg:->] else { disengage; };
        right_v = self.arg_value;
        here.value = left_v * right_v;
        self.arg_value = here.value;
    }
}

with entry {
    x_formal = Formal(name="x", dtype="Double");
    ref_l = FormalRef(formal_name="x");
    ref_r = FormalRef(formal_name="x");
    mul_body = BuiltinCall(op="mul", scalar_work=1);
    square = ScalarFn(name="square");
    bad_a = ScalarFn(name="bad_a");
    bad_b = ScalarFn(name="bad_b");
    in1 = InputElt(value=1.0);
    in2 = InputElt(value=2.0);
