    mul_body +>:RightArg:+> ref_r;
    ref_l +>:ReadsFormal:+> x_formal;
    ref_r +>:ReadsFormal:+> x_formal;
    bad_a +>:Depends:+> bad_b;
    bad_b +>:Depends:+> bad_a;
    in1 +>:Applies:+> square;
