"""Example spec variables: declaration-order lint and dependency cycle detection."""

node Spec {
    has path: str = "";
    has columns: list[str] = [];
}

node Variable {
    has name: str = "";
    has expr: str = "";
    has is_source: bool = False;
}

edge NextDecl { }
edge DependsOn { }

walker OrderAuditor {
    has defined: list[str] = [];
    has issues: list[str] = [];
    has current: str = "";
    has checking_prereqs: bool = False;

    can start with Root entry {
        visit [-->[?:Spec]] else { disengage; };
    }

    can audit with Spec entry {
        print(f"\n== Order audit: {here.path} ==");
        self.defined = [];
        self.issues = [];
        visit [->:NextDecl:->] else {
            print("  [OK] variables declared in dependency order");
        };
        if len(self.issues) > 0 {
            for issue in self.issues {
                print(f"  [LINT] {issue}");
            }
        } else {
            print("  [OK] variables declared in dependency order");
        }
        col_text = ", ".join(here.columns);
        print(f"  output.columns (unchanged): [{col_text}]");
        visit [-->[?:Spec]] else { disengage; };
    }

    can walk_decl with Variable entry {
        if self.checking_prereqs {
            if here.name not in self.defined {
                msg = (
                    f"forward reference: {self.current} uses {here.name} "
                    + "before it is declared"
                );
                self.issues.append(msg);
            }
            disengage;
        }
        self.current = here.name;
        self.checking_prereqs = True;
        visit [->:DependsOn:->] else { };
        self.checking_prereqs = False;
        self.defined.append(here.name);
        kind = "source" if here.is_source else "derived";
        print(f"  declare ({kind}) {here.name} = {here.expr}");
        visit [->:NextDecl:->] else { disengage; };
    }
}

walker CycleDetector {
    has stack: list[str] = [];
    has cycles: list[str] = [];
    has phase: str = "chain";

    can start with Root entry {
        visit [-->[?:Spec]] else { disengage; };
    }

    can scan with Spec entry {
        print(f"\n== Cycle scan: {here.path} ==");
        self.cycles = [];
        self.phase = "chain";
        visit [->:NextDecl:->] else { disengage; };
        if len(self.cycles) > 0 {
            for cycle in self.cycles {
                print(f"  [CYCLE] {cycle}");
            }
        } else {
            print("  [OK] no dependency cycles");
        }
        visit [-->[?:Spec]] else { disengage; };
    }

    can analyze with Variable entry {
        if self.phase == "chain" {
            self.stack = [];
            self.phase = "probe";
            visit [->:DependsOn:->] else { };
            self.phase = "chain";
            visit [->:NextDecl:->] else { disengage; };
        } else {
            if here.name in self.stack {
                chain = " -> ".join(self.stack) + f" -> {here.name}";
                self.cycles.append(chain);
                disengage;
            }
            self.stack.append(here.name);
            visit [->:DependsOn:->] else { };
            self.stack.pop();
            disengage;
        }
    }
}

