"""Symlink resolution: ROUTE_BY_LINK_LOCATION scans by link location, expands directory links, and blocks ancestor escapes."""

node FsEntry {
    has name: str = "";
    has path: str = "";
}

node Directory(FsEntry) {
    has entry_count: int = 0;
}

node File(FsEntry) {
    has content: str = "";
}

node Symlink(FsEntry) {
    has target_path: str = "";
    has is_native_link: bool = True;
}

edge Contains { }

edge PointsTo {
    has via: str = "";
}

walker InputResolver {
    has rule: str = "ROUTE_BY_LINK_LOCATION";
    has scope_name: str = "";
    has scope_prefix: str = "";
    has visited: list[str] = [];
    has route_path: str = "";
    has checked_count: int = 0;
    has blocked_escapes: int = 0;
    has expanded_links: int = 0;

    can start with Root entry {
        print(f"rule={self.rule} scope={self.scope_name} prefix={self.scope_prefix}");
        visit [-->];
    }

    can enter_dir with Directory entry {
        in_scope = self.scope_prefix == "" or here.path.startswith(self.scope_prefix);
        via_link = self.route_path != "";
        if not in_scope and not via_link {
            visit [-->] else { disengage; };
        } else {
            if here.path in self.visited {
                visit [-->] else { disengage; };
            } else {
                self.visited.append(here.path);
                if via_link {
                    print(f"[EXPAND] linked dir {here.path} via {self.route_path}");
                } else {
                    print(f"[DIR] {here.path}");
                }
                visit [->:Contains:->] else { disengage; };
            }
        }
    }

    can route_link with Symlink entry {
        link_path = here.path;
        in_scope = self.scope_prefix == "" or link_path.startswith(self.scope_prefix);
        if not in_scope {
            visit [-->] else { disengage; };
        } else {
            if link_path in self.visited {
                visit [-->] else { disengage; };
            } else {
                self.visited.append(link_path);
                self.route_path = link_path;
                kind = "SYMLINK" if here.is_native_link else "POINTER";
                print(f"[{kind}] route at {link_path} -> {here.target_path}");
                if here.target_path == ".." or here.target_path.endswith("/..") {
                    print(f"[BLOCKED] ancestor link at {link_path} would escape {self.scope_prefix}");
                    self.blocked_escapes += 1;
                    self.route_path = "";
                    visit [-->] else { disengage; };
                } else {
                    self.expanded_links += 1;
                    visit [->:PointsTo:->] else {
                        self.route_path = "";
                        disengage;
                    };
                }
            }
        }
    }

    can check_file with File entry {
        if self.route_path != "" {
            report_path = self.route_path;
        } else {
            report_path = here.path;
        }
        banned = "eval(" in here.content;
        status = "BANNED" if banned else "ok";
        self.checked_count += 1;
        print(f"[CHECK] route={report_path} content={here.path} -> {status}");
        self.route_path = "";
        visit [-->] else { disengage; };
    }
}

