"""Paper Library exam catalog: one-level libraries hold source papers; exam walkers traverse ready papers and cascade delete preserves the question bank."""

node PaperLibrary {
    has name: str = "";
    has llm_model: str = "extract-v2";
    has pdf_parser: str = "pymupdf";
    has failure_strategy: str = "manual_retry";
}

node Paper {
    has title: str = "";
    has display_name: str = "";
    has paper_id: str = "";
    has sha256: str = "";
    has status: str = "pending";
}

node SavedQuestion {
    has question_num: int = 0;
    has prompt: str = "";
}

edge Contains {
    has slot: int = 0;
}

edge SavedFrom {
}

walker ExamSession {
    has pick_library: str = "";
    has ready_count: int = 0;

    can start with Root entry {
        visit [-->[?:PaperLibrary]] else { disengage; }
    }

    can select_library with PaperLibrary entry {
        target = self.pick_library.strip().lower();
        current = here.name.strip().lower();
        if current == target {
            print(
                f"[Exam] '{here.name}' — llm={here.llm_model}, "
                f"parser={here.pdf_parser}, on_fail={here.failure_strategy}"
            );
            visit [->:Contains:->] else {
                print("  (library has no papers)");
                disengage;
            }
        } else {
            visit [-->[?:PaperLibrary]] else { disengage; }
