"""Internal data network: cables, switches, risers, and connected-component flow routing."""

node NetworkDevice {
    has name: str = "";
    has floor: int = 0;
    has online: bool = True;
}

node NetworkEndpoint(NetworkDevice) {
    has flops: int = 0;
}

node DataSwitch(NetworkDevice) {
}

edge DataCable {
    has bandwidth: int = 100;
    has latency_ms: int = 1;
    has condition: float = 1.0;
}

edge VerticalRiser {
    has bandwidth: int = 50;
    has latency_ms: int = 5;
    has condition: float = 1.0;
}

walker ComponentScanner {
    has label: str = "facility";
    has members: list[str] = [];
    has seen: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can scan with NetworkEndpoint | DataSwitch entry {
        if not here.online {
            disengage;
        }
        if here.name in self.seen {
            disengage;
        }
        self.seen.append(here.name);
        self.members.append(here.name);
        visit [->:DataCable:->] else {
            visit [->:VerticalRiser:->] else {
                print(
                    f"[scan:{self.label}] component size={len(self.members)} "
                    f"members={self.members}"
                );
                disengage;
            };
        };
    }
}

walker FlowRouter {
    has source: str = "";
    has target: str = "";
    has tracing: bool = False;
    has hops: list[str] = [];
    has seen: list[str] = [];
    has reachable: bool = False;
    has prev_floor: int = -999;
    has min_bandwidth: int = 999999;
    has total_latency: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can route with NetworkEndpoint | DataSwitch entry {
        if not here.online {
            disengage;
        }
        if not self.tracing {
            if here.name == self.source {
                self.tracing = True;
                self.prev_floor = here.floor;
                self.hops.append(here.name);
                self.seen.append(here.name);
            }
        } else {
            if here.name in self.seen {
                disengage;
            }
            self.seen.append(here.name);
            if len(self.hops) > 0 {
                cross_floor = here.floor != self.prev_floor;
                hop_latency = 5 if cross_floor else 1;
                hop_bw = 50 if cross_floor else 100;
                self.total_latency += hop_latency;
                next_min = hop_bw if hop_bw < self.min_bandwidth else self.min_bandwidth;
                self.min_bandwidth = next_min;
            }
            self.prev_floor = here.floor;
            self.hops.append(here.name);
            if here.name == self.target {
                self.reachable = True;
            }
        }
        visit [->:DataCable:->] else {
            visit [->:VerticalRiser:->] else {
                if self.tracing {
                    if self.reachable {
                        print(
                            f"[flow] route OK hops={self.hops} "
                            f"bottleneck={self.min_bandwidth}Mbps "
                            f"latency={self.total_latency}ms"
                        );
                    } else {
                        print(
                            f"[flow] no data path to {self.target} "
                            f"(visited={self.hops})"
                        );
                    }
                }
                disengage;
            };
        };
    }
}

with entry {
    gateway = NetworkEndpoint(name="gateway", floor=0, flops=120);
    storage = NetworkEndpoint(name="storage", floor=1, flops=800);
    compute = NetworkEndpoint(name="compute", floor=1, flops=400);
    orphan = NetworkEndpoint(name="orphan", floor=2, flops=90);

    sw_ground = DataSwitch(name="sw-ground", floor=0);
    sw_orbit = DataSwitch(name="sw-orbit", floor=1);

    root ++> gateway;
    root ++> orphan;

    gateway +>:DataCable(bandwidth=100, latency_ms=1, condition=1.0):+> sw_ground;
    sw_ground
        +>:VerticalRiser(bandwidth=50, latency_ms=5, condition=0.95):+> sw_orbit;
    sw_orbit +>:DataCable(bandwidth=100, latency_ms=1, condition=1.0):+> storage;
    sw_orbit +>:DataCable(bandwidth=80, latency_ms=2, condition=0.9):+> compute;

    print("=== connected component from gateway (cross-floor via riser) ===");
    gateway spawn ComponentScanner(label="ground-mesh");

    print("=== isolated endpoint (no data edges) ===");
    orphan spawn ComponentScanner(label="isolated");

    print("=== FLOPS share attempt: gateway -> storage (same component) ===");
    ok = FlowRouter(source="gateway", target="storage");
    gateway spawn ok;
    if ok.reachable {
        shared = gateway.flops + storage.flops;
        print(f"[flops] shared pool={shared} across connected endpoints");
    } else {
        print("[flops] BLOCKED: disconnected components cannot share FLOPS");
    }

    print("=== deterministic invalidation after switch failure on same tick ===");
    sw_ground.online = False;
    del sw_ground;
    retry = FlowRouter(source="gateway", target="storage");
    gateway spawn retry;
    if retry.reachable {
        print("[flops] reroute succeeded");
    } else {
        print(
            "[flops] BLOCKED after failure: no alternate data path this tick"
        );
    }
}

"""Example spec variables: declaration-order lint and dependency cycle detection."""

node Spec {
    has path: str = "";
    has columns: list[str] = [];
}

node Variable {
    has name: str = "";
    has expr: str = "";
    has is_source: bool = False;
}

edge NextDecl { }
edge DependsOn { }

walker OrderAuditor {
    has defined: list[str] = [];
    has issues: list[str] = [];
    has current: str = "";
    has checking_prereqs: bool = False;

    can start with Root entry {
        visit [-->];
    }

    can audit with Spec entry {
        print(f"\n== Order audit: {here.path} ==");
        self.defined = [];
        self.issues = [];
        visit [->:NextDecl:->] else { disengage; };
        if len(self.issues) > 0 {
            for issue in self.issues {
                print(f"  [LINT] {issue}");
            }
        } else {
            print("  [OK] variables declared in dependency order");
        }
        col_text = ", ".join(here.columns);
        print(f"  output.columns (unchanged): [{col_text}]");
        visit [-->];
    }

    can walk_decl with Variable entry {
        if self.checking_prereqs {
            if here.name not in self.defined {
                msg = (
                    f"forward reference: {self.current} uses {here.name} "
                    + "before it is declared"
                );
                self.issues.append(msg);
            }
            disengage;
        }
        self.current = here.name;
        self.checking_prereqs = True;
        visit [->:DependsOn:->] else { };
        self.checking_prereqs = False;
        self.defined.append(here.name);
        kind = "source" if here.is_source else "derived";
        print(f"  declare ({kind}) {here.name} = {here.expr}");
        visit [->:NextDecl:->] else { disengage; };
    }
}

walker CycleDetector {
    has stack: list[str] = [];
    has cycles: list[str] = [];
    has phase: str = "chain";

    can start with Root entry {
        visit [-->];
    }

    can scan with Spec entry {
        print(f"\n== Cycle scan: {here.path} ==");
        self.cycles = [];
        self.phase = "chain";
        visit [->:NextDecl:->] else { disengage; };
        if len(self.cycles) > 0 {
            for cycle in self.cycles {
                print(f"  [CYCLE] {cycle}");
            }
        } else {
            print("  [OK] no dependency cycles");
        }
        visit [-->];
    }

    can analyze with Variable entry {
        if self.phase == "chain" {
            self.stack = [];
            self.phase = "probe";
            visit [->:DependsOn:->] else { };
            self.phase = "chain";
            visit [->:NextDecl:->] else { disengage; };
        } else {
            if here.name in self.stack {
                chain = " -> ".join(self.stack) + f" -> {here.name}";
                self.cycles.append(chain);
                disengage;
            }
            self.stack.append(here.name);
            visit [->:DependsOn:->] else { };
            self.stack.pop();
            disengage;
        }
    }
}

with entry {
    good = Spec(
        path="yaml/examples/good/spec.yaml",
        columns=["total", "base_price", "tax_rate"]
    );
    bad = Spec(
        path="yaml/examples/bad/spec.yaml",
