    good +>:NextDecl:+> gp;
    gp +>:NextDecl:+> gt;
    gt +>:NextDecl:+> gd;
    gd +>:DependsOn:+> gp;
    gd +>:DependsOn:+> gt;

    bt = Variable(name="total", expr="base_price * (1 + tax_rate)");
    bb = Variable(name="base_price", expr="input", is_source=True);
