    cyclic +>:NextDecl:+> ca;
    ca +>:NextDecl:+> cb;
    ca +>:DependsOn:+> cb;
    cb +>:DependsOn:+> ca;

    root spawn OrderAuditor();
    root spawn CycleDetector();
}

