"""Scenario evaluation: read-only what-if analysis over an attributable base revision."""

node Revision {
    has rev_id: str = "";
    has author: str = "";
    has label: str = "";
}

node Component {
    has name: str = "";
    has kind: str = "";
    has boundary: str = "";
}

node GovernanceCheck {
    has check_id: str = "";
    has rule: str = "";
    has description: str = "";
}

node Scenario {
    has name: str = "";
    has description: str = "";
}

node ChangeProposal {
    has change_type: str = "";
    has from_component: str = "";
    has to_component: str = "";
}

edge DependsOn { has kind: str = ""; }
edge BaseRevision { }
edge ProposesChange { }
edge HasCheck { }

walker ScenarioEvaluator {
    has phase: str = "current";
    has virtual_tag: str = "virtual";
    has authority_tag: str = "notAuthoritative";
    has scenario_name: str = "";
    has base_rev_id: str = "";
    has base_author: str = "";
    has overlay_from: str = "";
    has overlay_to: str = "";
    has overlay_to_boundary: str = "";
    has visited: list[str] = [];
    has current_violations: list[str] = [];
    has scenario_violations: list[str] = [];
    has changes_applied: list[str] = [];
    has ctx_parent_name: str = "";
    has ctx_parent_boundary: str = "";
    has cycle_detected: bool = False;

    can start with Root entry {
        visit [-->];
    }

    can evaluate with Scenario entry {
        self.scenario_name = here.name;
        print(f"=== [{self.virtual_tag}/{self.authority_tag}] scenario evaluation ===");
        print(f"Scenario: {here.name} — {here.description}");
        print("Limits: non-structural runtime, staffing, and cost impacts are out of scope.");
        visit [->:ProposesChange:->] else { disengage; };
        visit [->:BaseRevision:->];
        self.phase = "scenario";
        self.visited = [];
        self.cycle_detected = False;
        self.ctx_parent_name = "";
        self.ctx_parent_boundary = "";
        visit [->:BaseRevision:->];
        self.emit_comparison();
        disengage;
    }

    can load_proposal with ChangeProposal entry {
        self.overlay_from = here.from_component;
        self.overlay_to = here.to_component;
        applied = f"{here.change_type}: {here.from_component} -> {here.to_component}";
        self.changes_applied.append(applied);
        print(f"  proposal [{self.virtual_tag}]: {applied}");
    }

    can load_base with Revision entry {
        self.base_rev_id = here.rev_id;
        self.base_author = here.author;
        phase_label = "CURRENT" if self.phase == "current" else "SCENARIO";
        print(f"  [{phase_label}] base {here.rev_id} by {here.author} ({here.label})");
        visit [->:HasCheck:->] else { disengage; };
        visit [-->];
    }

    can note_rule with GovernanceCheck entry {
        print(f"    check {here.check_id}: {here.rule} — {here.description}");
        disengage;
    }

    can inspect with Component entry {
        if here.name in self.visited {
            self.cycle_detected = True;
            cycle_msg = f"GOV-02 cycle: evidence: loop revisits {here.name}";
            if self.phase == "current" {
                self.current_violations.append(cycle_msg);
            } else {
                self.scenario_violations.append(cycle_msg);
            }
            disengage;
        }
        self.visited.append(here.name);

        if self.ctx_parent_boundary != "" {
            effective_name = here.name;
            effective_boundary = here.boundary;
            if self.phase == "scenario" and effective_name == self.overlay_from {
                effective_name = self.overlay_to;
                effective_boundary = self.overlay_to_boundary;
            }
            if self.ctx_parent_boundary != effective_boundary {
                evidence = (
                    f"evidence: {self.ctx_parent_name}({self.ctx_parent_boundary})"
                    f" -> {effective_name}({effective_boundary})"
                );
                violation = f"GOV-01 cross-boundary: {evidence}";
                if self.phase == "current" {
                    self.current_violations.append(violation);
                } else {
                    self.scenario_violations.append(violation);
                }
            }
        }

        self.ctx_parent_name = here.name;
        self.ctx_parent_boundary = here.boundary;
        visit [->:DependsOn:->] else {
            self.ctx_parent_name = "";
            self.ctx_parent_boundary = "";
            disengage;
        };
        self.ctx_parent_name = "";
        self.ctx_parent_boundary = "";
    }

    def emit_comparison() -> None {
        print(f"--- [{self.virtual_tag}/{self.authority_tag}] comparison for {self.scenario_name} ---");
        print(f"Base: {self.base_rev_id} (author: {self.base_author})");
        print(f"Hypothetical changes: {self.changes_applied}");
        print(f"CURRENT violations ({len(self.current_violations)}):");
        for (i, item) in enumerate(self.current_violations) {
            print(f"  {i + 1}. {item}");
        }
        print(f"SCENARIO violations ({len(self.scenario_violations)}):");
        for (i, item) in enumerate(self.scenario_violations) {
            print(f"  {i + 1}. {item}");
        }
        current_count = len(self.current_violations);
        scenario_count = len(self.scenario_violations);
        delta = current_count - scenario_count;
        verdict = "improves" if delta > 0 else "unchanged";
        worse_verdict = "worsens" if delta < 0 else verdict;
        print(
            f"Result [{self.virtual_tag}]: architecture {worse_verdict} "
            f"({current_count} -> {scenario_count} violations); "
            f"no EvolutionEvent, no canonical write."
        );
    }
}

