"""Tempo structural search: two-phase rank-then-hydrate over recursive span closure."""

node Trace {
    has trace_id: str = "";
    has rank_score: float = 0.0;
    has in_top_n: bool = False;
}

node Span {
    has span_id: str = "";
    has trace_id: str = "";
    has operation: str = "";
    has wide_payload: str = "";
    has hydrated: bool = False;
}

edge Contains { }
edge ChildOf { }

def mark_top_n(traces: list[Trace], n: int) {
    ranked = traces;
    for i in range(len(ranked)) {
        best_idx = i;
        for j in range(i + 1, len(ranked)) {
            if ranked[j].rank_score > ranked[best_idx].rank_score {
                best_idx = j;
            }
        }
        tmp = ranked[i];
        ranked[i] = ranked[best_idx];
        ranked[best_idx] = tmp;
    }
    limit = n if n < len(ranked) else len(ranked);
    for i in range(limit) {
        ranked[i].in_top_n = True;
    }
}

def bump_trace_score(registry: list[Trace], trace_id: str, delta: float) {
    for tr in registry {
        if tr.trace_id == trace_id {
            tr.rank_score += delta;
        }
    }
}

walker PhaseARanker {
    has parent_op: str = "";
    has child_op: str = "";
    has top_n: int = 2;
    has trace_registry: list[Trace] = [];
    has seeking_child: bool = False;
    has visited_span_ids: list[str] = [];
    has depth: int = 0;
    has max_depth: int = 32;

    can start with Root entry {
        print("=== Phase A: narrow recursive closure, rank top-N traces ===");
        visit [-->];
        print("=== Phase A complete ===");
    }

    can scan_trace with Trace entry {
        self.visited_span_ids = [];
        self.depth = 0;
        self.seeking_child = False;
        visit [->:Contains:->] else { visit [-->]; };
    }

    can scan_span with Span entry {
        if self.depth > self.max_depth {
            visit [-->];
        } elif self.seeking_child {
            if here.operation == self.child_op {
                bump_trace_score(self.trace_registry, here.trace_id, 1.0);
                print(
                    f"  [A] structural match {self.parent_op} >> {self.child_op} "
                    f"in {here.trace_id}"
                );
            }
            if here.span_id not in self.visited_span_ids {
                self.visited_span_ids.append(here.span_id);
                saved_depth = self.depth;
                self.depth = saved_depth + 1;
                visit [->:ChildOf:->] else { disengage; };
                self.depth = saved_depth;
            }
            visit [-->];
        } elif here.operation == self.parent_op {
            if here.span_id in self.visited_span_ids {
                visit [-->];
            } else {
                self.visited_span_ids.append(here.span_id);
                self.seeking_child = True;
                saved_depth = self.depth;
                self.depth = saved_depth + 1;
                visit [->:ChildOf:->] else { disengage; };
                self.seeking_child = False;
                self.depth = saved_depth;
                visit [-->];
            }
        } else {
            visit [-->];
        }
    }
}

walker PhaseBHydrator {
    can start with Root entry {
        print("=== Phase B: re-run closure restricted to top-N trace ids ===");
        visit [-->];
        print("=== Phase B complete ===");
    }

    can hydrate_trace with Trace entry {
        if here.in_top_n {
            print(f"  [B] restrictStructural -> {here.trace_id} (score={here.rank_score})");
            visit [->:Contains:->] else { visit [-->]; };
        } else {
            visit [-->];
        }
    }

    can hydrate_span with Span entry {
        if not here.hydrated {
            payload = (
                f"tags+logs+events:{here.span_id}"
                if here.wide_payload == "NARROW"
                else here.wide_payload
            );
            here.wide_payload = payload;
            here.hydrated = True;
            print(f"    hydrated {here.span_id} ({here.operation})");
        }
        visit [-->];
    }
}

walker SingleQuerySearch {
    has parent_op: str = "";
    has child_op: str = "";
    has trace_registry: list[Trace] = [];
    has seeking_child: bool = False;
    has visited_span_ids: list[str] = [];
    has depth: int = 0;
    has max_depth: int = 32;
    has round_trips: int = 0;

    can start with Root entry {
        self.round_trips = 1;
        print("=== Single-query: fused closure rank + hydrate (one round trip) ===");
        visit [-->];
        print(f"=== Single-query complete (round_trips={self.round_trips}) ===");
    }

    can scan_trace with Trace entry {
        self.visited_span_ids = [];
        self.depth = 0;
        self.seeking_child = False;
        visit [->:Contains:->] else { visit [-->]; };
    }

    can scan_span with Span entry {
        if self.depth > self.max_depth {
            visit [-->];
        } elif self.seeking_child {
            if here.operation == self.child_op {
                bump_trace_score(self.trace_registry, here.trace_id, 1.0);
                if not here.hydrated {
                    here.wide_payload = f"tags+logs+events:{here.span_id}";
                    here.hydrated = True;
                }
                print(
                    f"  [1Q] match+hydrate {self.parent_op} >> {self.child_op} "
                    f"in {here.trace_id}"
                );
            }
            if here.span_id not in self.visited_span_ids {
                self.visited_span_ids.append(here.span_id);
                saved_depth = self.depth;
                self.depth = saved_depth + 1;
                visit [->:ChildOf:->] else { disengage; };
                self.depth = saved_depth;
            }
            visit [-->];
        } elif here.operation == self.parent_op {
            if here.span_id in self.visited_span_ids {
                visit [-->];
            } else {
                self.visited_span_ids.append(here.span_id);
                self.seeking_child = True;
                saved_depth = self.depth;
                self.depth = saved_depth + 1;
                visit [->:ChildOf:->] else { disengage; };
                self.seeking_child = False;
                self.depth = saved_depth;
                visit [-->];
            }
        } else {
            visit [-->];
        }
    }
}

