    has label: str = "";
    has platform: str = "";
    has protected_room: bool = False;
    override def tag() -> str {
        return f"meeting:{self.platform}:{self.label}";
    }
}

node BrowserLane(GraphEntity) {
    has product: str = "";
    has generation: int = 0;
    has playwright: str = "";
    has revision: str = "";
    has stock_image: bool = True;
    override def tag() -> str {
        return f"lane:{self.product}-{self.generation}";
    }
