"""Task work.db backfill: parent-ordered resumable migration, canonical event IDs, and shadow validation."""

node Task {
    has task_id: str = "";
    has title: str = "";
    has migrated: bool = False;
    has event_count: int = 0;
}

node WorkTask {
    has task_id: str = "";
    has title: str = "";
    has event_count: int = 0;
}

node TaskEvent {
    has event_id: int = 0;
    has kind: str = "";
}

node TaskDependency {
    has satisfied_by_event_id: int = 0;
}

edge ChildOf { }
edge HasEvent { }
edge ShadowOf { }
edge HasDependency { }
edge RequiresTask { }

walker ResumableBackfill {
    has rows_per_batch: int = 10;
    has rows_this_run: int = 0;
    has max_event_id: int = 0;

    can start with Root entry {
        print("=== Resumable backfill into work.db ===");
        visit [-->];
    }

    can backfill with Task entry {
        if here.migrated {
            visit [-->];
        } else {
            ready = True;
            for p in here-->:ChildOf:--> {
                if not p.migrated {
                    ready = False;
                    break;
                }
            }
            if ready {
                for ev in here-->:HasEvent:--> {
                    if ev.event_id > self.max_event_id {
                        self.max_event_id = ev.event_id;
                    }
                    print(f"    event {ev.event_id} ({ev.kind}) copied verbatim");
                }
                dest = WorkTask(
                    task_id=here.task_id,
                    title=here.title,
                    event_count=here.event_count
                );
                here +>:ShadowOf:+> dest;
                here.migrated = True;
                self.rows_this_run += 1;
                print(
                    f"  backfilled {here.task_id} "
                    f"(events={here.event_count}, max_eid={self.max_event_id})"
                );
                if self.rows_this_run >= self.rows_per_batch {
                    print(f"  checkpoint: pausing after {self.rows_this_run} rows");
                    disengage;
                }
            }
            visit [-->];
        }
    }
}

walker DependencyAuditor {
    has violations: int = 0;

    can start with Root entry {
        print("=== Dependency satisfied_by_event_id audit ===");
        visit [-->];
    }

    can audit_task with Task entry {
        for dep in here-->:HasDependency:--> {
            sat_id = dep.satisfied_by_event_id;
            found = False;
            for ev in here-->:HasEvent:--> {
                if ev.event_id == sat_id {
                    found = True;
                    break;
                }
            }
            if found {
                print(f"  {here.task_id}: event {sat_id} canonical [OK]");
            } else {
                self.violations += 1;
                print(
                    f"  {here.task_id}: event {sat_id} missing "
                    f"[QUARANTINE]"
                );
            }
        }
        visit [-->];
    }
}

walker ShadowValidator {
    has ok: int = 0;
    has bad: int = 0;

    can start with Root entry {
        print("=== Shadow validation (legacy authoritative) ===");
        visit [-->[?:Task]];
    }

    can compare with Task entry {
        if not here.migrated {
            self.bad += 1;
            print(f"[FAIL] {here.task_id}: not backfilled (no fallback)");
        } else {
            found = False;
            for shadow in here-->:ShadowOf:--> {
                found = True;
                if shadow.task_id != here.task_id {
                    self.bad += 1;
                    print(
                        f"[FAIL] {here.task_id}: id mismatch "
                        f"dest={shadow.task_id}"
                    );
                } elif shadow.event_count != here.event_count {
                    self.bad += 1;
                    print(
                        f"[FAIL] {here.task_id}: count mismatch "
                        f"src={here.event_count} dest={shadow.event_count}"
                    );
                } else {
                    self.ok += 1;
                    print(
                        f"[PASS] {here.task_id}: ids, counts, order preserved"
                    );
                }
                break;
            }
            if not found {
                self.bad += 1;
                print(
                    f"[FAIL] {here.task_id}: missing destination row"
                );
            }
        }
        visit [-->] else { disengage; };
    }
}

with entry {
    epic = Task(task_id="T-1", title="Migrate core tasks", event_count=2);
    story = Task(task_id="T-2", title="Backfill task events", event_count=1);
    sub = Task(task_id="T-3", title="Validate dependencies", event_count=1);

    story +>:ChildOf:+> epic;
    sub +>:ChildOf:+> story;

    e1 = TaskEvent(event_id=100, kind="created");
    e2 = TaskEvent(event_id=101, kind="assigned");
    e3 = TaskEvent(event_id=102, kind="dep_satisfied");
    e4 = TaskEvent(event_id=103, kind="created");

    epic +>:HasEvent:+> e1;
    epic +>:HasEvent:+> e2;
    story +>:HasEvent:+> e3;
    sub +>:HasEvent:+> e4;

    dep = TaskDependency(satisfied_by_event_id=102);
    sub +>:HasDependency:+> dep;
    dep +>:RequiresTask:+> story;

    root ++> epic ++> story ++> sub;

    print("--- phase 1: interrupted backfill (batch=2) ---");
    root spawn ResumableBackfill(rows_per_batch=2);

    print("--- phase 2: resume (idempotent, completes remainder) ---");
    root spawn ResumableBackfill(rows_per_batch=10);

    auditor = DependencyAuditor();
    root spawn auditor;
    print(f"dependency violations: {auditor.violations}");

    validator = ShadowValidator();
    root spawn validator;
    print(
        f"shadow validation: {validator.ok} passed, "
        f"{validator.bad} failed"
    );
}

"""Selected call-target traversal for assembly call-graph projection.

Resolve external MemberRef operands through owner-retained, active assembly
participants against a frozen correspondence manifest. Physical call-site
identity stays separate from logical member correspondence; inactive shadows
and ambiguous candidates are never indexed or traversed.
"""

node BodyArtifact {
    has assembly_name: str = "";
    has manifest_frozen: bool = False;
}

node RetainedParticipant {
    has name: str = "";
    has active: bool = True;
    has ambiguous: bool = False;
    has platform_close: bool = False;
    has available: bool = True;
}

node PhysicalCallSite {
    has site_id: str = "";
    has target_member: str = "";
    has target_declaring: str = "";
}

node CatalogMember {
    has member_name: str = "";
    has declaring_type: str = "";
    has signature: str = "";
    has is_forwarder: bool = False;
}

node ManifestRequest {
    has kind: str = "";
    has present: bool = True;
}

node DeclaringRequest(ManifestRequest) { }
node ParameterRequest(ManifestRequest) { }
node ReturnRequest(ManifestRequest) { }

edge ExternalOperand { }
edge SelectedParticipant { }
edge SuppliesDefinition { }
edge PlanDeclares { }
edge TypeForwards { }

walker CallTargetResolver {
    has physical_site: str = "";
    has logical_sig: str = "";
    has pending_member: str = "";
    has pending_declaring: str = "";
    has outcome: str = "";
    has found_match: bool = False;

    can start with Root entry {
        visit [-->];
    }

    can scope with BodyArtifact entry {
        if not here.manifest_frozen {
            self.outcome = "correspondence-incomplete";
            print(f"[correspondence-incomplete] manifest open on {here.assembly_name}");
            disengage;
        }
        print(f"Projecting call targets for {here.assembly_name} (manifest frozen)");
        visit [->:ExternalOperand:->] else { disengage; };
    }

    can at_operand with PhysicalCallSite entry {
        self.physical_site = here.site_id;
        self.pending_member = here.target_member;
        self.pending_declaring = here.target_declaring;
        self.found_match = False;
        self.outcome = "";
        visit [->:SelectedParticipant:->] else {
            self.outcome = "invalid-reference";
            print(f"[invalid-reference] site={self.physical_site} has no selected participant");
            disengage;
        };
    }

    can pick_participant with RetainedParticipant entry {
        if here.ambiguous or not here.active {
            print(f"[skip] shadow/ambiguous candidate {here.name} never traversed");
            disengage;
        }
        if not here.available {
            self.outcome = "candidate-unavailable";
            print(f"[candidate-unavailable] site={self.physical_site} participant={here.name}");
            disengage;
        }
        visit [->:SuppliesDefinition:->] else {
            missing_label = "member-missing" if here.platform_close else "invalid-reference";
            self.outcome = missing_label;
            print(f"[{missing_label}] site={self.physical_site} seeking "
                  f"{self.pending_declaring}::{self.pending_member} in {here.name}");
            disengage;
        };
    }

    can bind_definition with CatalogMember entry {
        if here.member_name == self.pending_member
            and here.declaring_type == self.pending_declaring {
            self.found_match = True;
            self.logical_sig = here.signature;
            self.outcome = "resolved-definition";
            print(f"[resolved-definition] physical={self.physical_site} "
                  f"logical={self.pending_declaring}::{here.member_name} "
                  f"sig={self.logical_sig}");
            if here.is_forwarder {
                visit [->:TypeForwards:->] else { disengage; };
            } else {
                disengage;
            }
        }
    }

    can resolve_forward with CatalogMember entry {
        print(f"  type-forward Metadata outcome -> "
              f"{here.declaring_type}::{here.member_name} ({here.signature})");
        disengage;
    }
}

walker ManifestAuditor {
    has removed_kind: str = "";
    has saw_expansion: bool = False;

    can start with Root entry {
        visit [-->];
    }

    can freeze_check with BodyArtifact entry {
        visit [->:PlanDeclares:->] else { disengage; };
    }

    can audit_request with DeclaringRequest | ParameterRequest | ReturnRequest entry {
        if here.kind == self.removed_kind and not here.present {
            self.saw_expansion = True;
            print(f"[plan-expansion] removed signature request kind={here.kind}");
        }
        visit [->:PlanDeclares:->] else {
            if self.saw_expansion {
                print("[correspondence-incomplete] frozen plan would be incomplete after removal");
            } else {
                print("[ok] declaring, parameter, return requests present — manifest complete");
            }
            disengage;
        };
    }
}

with entry {
    index = BodyArtifact(assembly_name="Contoso.Core", manifest_frozen=True);

    selected = RetainedParticipant(
