node GuestNameField {
    has target_name: str = "";
    has read_value: str = "";
    has settled: bool = False;
    has attempt_index: int = 0;
    has needs_repair: bool = False;

    def apply_write() {
        self.read_value = self.target_name;
    }

    def verify_twice() -> bool {
        first_ok = self.read_value == self.target_name;
        second_ok = self.read_value == self.target_name and not self.needs_repair;
        return first_ok and second_ok;
    }

    def repair_once() {
        self.needs_repair = False;
        self.read_value = self.target_name;
    }
}

node RtmsClause {
    has clause_text: str = "";
    has detected: bool = False;
}

node JoinSession {
    has admission: str = "waiting";
    has bot_left: bool = False;
    has teardown_reported: bool = False;
}

edge PlatformTarget { }
edge CandidateLane { }
edge PrejoinStage { has order: int = 0; }
edge RtmsLink { }
edge SessionFor { }

walker LaneRouter {
    has want_firefox: bool = False;
    has selected_lane: str = "";

    can start with Root entry {
        visit [-->];
    }

    can profile with JoinProfile entry {
        self.want_firefox = here.unsigned_guest and not here.authenticated;
        visit [->:PlatformTarget:->] else { disengage; }
    }

    can meeting with MeetingRoom entry {
        visit [->:CandidateLane:->] else { disengage; }
    }

    can pick with BrowserLane entry {
        firefox_ok = self.want_firefox and here.product == "Firefox";
        chromium_ok = not self.want_firefox and here.product == "Chromium";
        if firefox_ok or chromium_ok {
            self.selected_lane = here.tag();
            disengage;
        } else {
            visit [-->];
        }
    }
}

walker GuestNameAuditor {
    has terminal: str = "pending";
    has repairs_used: int = 0;
    has max_repairs: int = 1;
    has max_attempts: int = 3;

    can start with Root entry {
        visit [->:PrejoinStage:->] else { disengage; }
    }

    can try_entry with GuestNameField entry {
        if here.attempt_index > self.max_attempts {
            self.terminal = "name_entry_exhausted";
            disengage;
        }
        here.apply_write();
        if here.needs_repair and self.repairs_used < self.max_repairs {
            self.repairs_used += 1;
            here.repair_once();
        }
        verified = here.verify_twice();
        if verified {
            here.settled = True;
            self.terminal = "join_enabled";
            disengage;
        } else {
            visit [->:PrejoinStage:->] else {
                self.terminal = "name_entry_failed";
                disengage;
            }
        }
    }
}

walker PolicyClassifier {
    has required_clauses: int = 3;
    has matched_clauses: int = 0;
    has verdict: str = "clear";

    can start with Root entry {
        visit [-->];
    }

    can scan with MeetingRoom entry {
        visit [->:RtmsLink:->] else { disengage; }
    }

    can tally with RtmsClause entry {
        if here.detected {
            self.matched_clauses += 1;
        }
        visit [->:RtmsLink:->] else {
            if self.matched_clauses >= self.required_clauses {
                self.verdict = "rtms_policy_wall";
            } else {
                partial_label = "partial_signals" if self.matched_clauses > 0 else "no_policy_wall";
                self.verdict = partial_label;
            }
            disengage;
        }
    }
}

walker TeardownGuard {
    has violations: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can audit with JoinSession entry {
        if here.teardown_reported and not here.bot_left {
            self.violations += 1;
            print(f"invalid teardown before leave on session admission={here.admission}");
        }
        visit [-->];
    }
}

walker StatusReporter {
    can start with Root entry {
        visit [-->];
    }

    can report with MeetingRoom | BrowserLane entry {
        entity_tag = here.tag();
        print(f"join graph entity {entity_tag}");
        visit [-->];
    }

    can hop with JoinProfile entry {
        visit [-->];
    }
}

