"""Task work.db backfill: parent-ordered resumable migration, canonical event IDs, and shadow validation."""

node Task {
    has task_id: str = "";
    has title: str = "";
    has migrated: bool = False;
    has event_count: int = 0;
}

node WorkTask {
    has task_id: str = "";
    has title: str = "";
    has event_count: int = 0;
}

node TaskEvent {
    has event_id: int = 0;
    has kind: str = "";
}

node TaskDependency {
    has satisfied_by_event_id: int = 0;
}

edge ChildOf { }
edge HasEvent { }
edge ShadowOf { }
edge HasDependency { }
edge RequiresTask { }

walker ResumableBackfill {
    has rows_per_batch: int = 10;
    has rows_this_run: int = 0;
    has max_event_id: int = 0;

    can start with Root entry {
        print("=== Resumable backfill into work.db ===");
        visit [-->];
    }

    can backfill with Task entry {
        if here.migrated {
            visit [-->];
        } else {
            ready = True;
            for p in here->:ChildOf:-> {
                if not p.migrated {
                    ready = False;
                    break;
                }
            }
            if ready {
                for ev in here->:HasEvent:-> {
                    if ev.event_id > self.max_event_id {
                        self.max_event_id = ev.event_id;
                    }
                    print(f"    event {ev.event_id} ({ev.kind}) copied verbatim");
                }
                dest = WorkTask(
                    task_id=here.task_id,
                    title=here.title,
                    event_count=here.event_count
                );
                here +>:ShadowOf:+> dest;
                here.migrated = True;
                self.rows_this_run += 1;
                print(
                    f"  backfilled {here.task_id} "
                    f"(events={here.event_count}, max_eid={self.max_event_id})"
                );
                if self.rows_this_run >= self.rows_per_batch {
                    print(f"  checkpoint: pausing after {self.rows_this_run} rows");
                    disengage;
                }
            }
            visit [-->];
        }
    }
}

walker DependencyAuditor {
    has violations: int = 0;

    can start with Root entry {
        print("=== Dependency satisfied_by_event_id audit ===");
        visit [-->];
    }

    can audit_task with Task entry {
        for dep in here->:HasDependency:-> {
            sat_id = dep.satisfied_by_event_id;
            found = False;
            for req in dep->:RequiresTask:-> {
                for ev in req->:HasEvent:-> {
                    if ev.event_id == sat_id {
                        found = True;
                        break;
                    }
                }
            }
            if found {
                print(f"  {here.task_id}: event {sat_id} canonical [OK]");
            } else {
                self.violations += 1;
                print(
                    f"  {here.task_id}: event {sat_id} missing "
                    f"[QUARANTINE]"
                );
            }
        }
        visit [-->];
    }
}

walker ShadowValidator {
    has ok: int = 0;
    has bad: int = 0;

    can start with Root entry {
        print("=== Shadow validation (legacy authoritative) ===");
        visit [-->];
    }

    can compare with Task entry {
        if not here.migrated {
            self.bad += 1;
            print(f"[FAIL] {here.task_id}: not backfilled (no fallback)");
        } else {
            found = False;
            for shadow in here->:ShadowOf:-> {
                found = True;
                if shadow.task_id != here.task_id {
                    self.bad += 1;
                    print(
                        f"[FAIL] {here.task_id}: id mismatch "
                        f"dest={shadow.task_id}"
                    );
                } else if shadow.event_count != here.event_count {
                    self.bad += 1;
                    print(
                        f"[FAIL] {here.task_id}: count mismatch "
                        f"src={here.event_count} dest={shadow.event_count}"
                    );
                } else {
                    self.ok += 1;
                    print(
                        f"[PASS] {here.task_id}: ids, counts, order preserved"
                    );
                }
                break;
            }
            if not found {
                self.bad += 1;
                print(
                    f"[FAIL] {here.task_id}: missing destination row"
                );
            }
        }
        visit [-->] else {
            disengage;
        }
    }
}

