    epic = Task(task_id="T-1", title="Migrate core tasks", event_count=2);
    story = Task(task_id="T-2", title="Backfill task events", event_count=1);
    sub = Task(task_id="T-3", title="Validate dependencies", event_count=1);

    story +>:ChildOf:+> epic;
    sub +>:ChildOf:+> story;

    e1 = TaskEvent(event_id=100, kind="created");
    e2 = TaskEvent(event_id=101, kind="assigned");
    e3 = TaskEvent(event_id=102, kind="dep_satisfied");
    e4 = TaskEvent(event_id=103, kind="created");

    epic +>:HasEvent:+> e1;
    epic +>:HasEvent:+> e2;
    story +>:HasEvent:+> e3;
    sub +>:HasEvent:+> e4;

    dep = TaskDependency(satisfied_by_event_id=102);
    sub +>:HasDependency:+> dep;
    dep +>:RequiresTask:+> story;

    root ++> epic ++> story ++> sub;

    print("--- phase 1: interrupted backfill (batch=2) ---");
    root spawn ResumableBackfill(rows_per_batch=2);

    print("--- phase 2: resume (idempotent, completes remainder) ---");
