    can scope with BodyArtifact entry {
        if not here.manifest_frozen {
            self.outcome = "correspondence-incomplete";
            print(f"[correspondence-incomplete] manifest open on {here.assembly_name}");
            disengage;
        }
        print(f"Projecting call targets for {here.assembly_name} (manifest frozen)");
        visit [->:ExternalOperand:->] else { disengage; };
    }

    can at_operand with PhysicalCallSite entry {
        self.physical_site = here.site_id;
        self.pending_member = here.target_member;
        self.pending_declaring = here.target_declaring;
        self.found_match = False;
        self.forwarding = False;
        self.outcome = "";
        visit [->:SelectedParticipant:->] else {
            self.outcome = "invalid-reference";
            print(f"[invalid-reference] site={self.physical_site} has no selected participant");
            disengage;
        };
    }

    can pick_participant with RetainedParticipant entry {
        if here.ambiguous or not here.active {
            print(f"[skip] shadow/ambiguous candidate {here.name} never traversed");
            disengage;
        }
        if not here.available {
            self.outcome = "candidate-unavailable";
            print(f"[candidate-unavailable] site={self.physical_site} participant={here.name}");
            disengage;
        }
        visit [->:SuppliesDefinition:->] else {
            missing_label = "member-missing" if here.platform_close else "invalid-reference";
            self.outcome = missing_label;
            print(f"[{missing_label}] site={self.physical_site} seeking "
                  f"{self.pending_declaring}::{self.pending_member} in {here.name}");
            disengage;
        };
    }

    can bind_definition with CatalogMember entry {
        if self.forwarding {
            print(f"  type-forward Metadata outcome -> "
                  f"{here.declaring_type}::{here.member_name} ({here.signature})");
            disengage;
        } elif here.member_name == self.pending_member
            and here.declaring_type == self.pending_declaring {
            self.found_match = True;
            self.logical_sig = here.signature;
            self.outcome = "resolved-definition";
            print(f"[resolved-definition] physical={self.physical_site} "
                  f"logical={self.pending_declaring}::{here.member_name} "
                  f"sig={self.logical_sig}");
            if here.is_forwarder {
                self.forwarding = True;
                visit [->:TypeForwards:->] else { disengage; };
            } else {
                disengage;
            }
        } else {
            visit [-->];
        }
    }
}

walker ManifestAuditor {
    has removed_kind: str = "";
    has saw_expansion: bool = False;

    can start with Root entry {
        visit [-->];
    }

    can freeze_check with BodyArtifact entry {
        visit [->:PlanDeclares:->] else { disengage; };
    }

    can audit_request with ManifestRequest entry {
        if here.kind == self.removed_kind and not here.present {
            self.saw_expansion = True;
            print(f"[plan-expansion] removed signature request kind={here.kind}");
        }
        visit [->:PlanDeclares:->] else {
            if self.saw_expansion {
                print("[correspondence-incomplete] frozen plan would be incomplete after removal");
            } else {
                print("[ok] declaring, parameter, return requests present — manifest complete");
            }
            disengage;
        };
    }
}

