"""Identity toolkit-db escape hatches as OSP: recursive org subchart, atomic role guards, and latest-per-partition bindings."""

node Person {
    has person_id: str = "";
    has name: str = "";
}

node Role {
    has role_id: str = "";
    has title: str = "";
    has is_admin: bool = False;
}

node PersonRole {
    has person_role_id: str = "";
    has role_id: str = "";
    has valid_to: str = "";
    has reason: str = "";
}

node AccountBinding {
    has source_type: str = "";
    has source_id: str = "";
    has account_id: str = "";
    has created_at: int = 0;
    has seq_id: int = 0;
}

edge OrgReports { }
edge RoleAssignment { }

walker SubchartWalker {
    has max_depth: int = 1;
    has depth: int = 0;
    has visited: list[str] = [];
    has names: list[str] = [];

    can explore with Person entry {
        if here.person_id in self.visited {
            print(f"[cycle] blocked at {here.name}");
            disengage;
        }
        self.visited.append(here.person_id);
        self.names.append(here.name);
        can_recurse = self.max_depth < 0 or self.depth < self.max_depth;
        if can_recurse {
            child_depth = self.depth + 1;
            self.depth = child_depth;
            visit [->:OrgReports:->] else { disengage; };
            self.depth = self.depth - 1;
        } else {
            disengage;
        }
    }
}

walker RoleGuard {
    has target_pr_id: str = "";
    has admin_role_id: str = "admin";
    has revoke_reason: str = "";
    has pass_num: int = 0;
    has active_admin_count: int = 0;
    has target_role_id: str = "";
    has revoked: bool = False;

    can start with Root entry {
        self.pass_num = 1;
        visit [-->[?:PersonRole]];
        self.pass_num = 2;
        visit [-->[?:PersonRole]];
    }

    can audit with PersonRole entry {
        if self.pass_num == 1 {
            if here.valid_to == "" and here.role_id == self.admin_role_id {
                self.active_admin_count += 1;
            }
            if here.person_role_id == self.target_pr_id {
                self.target_role_id = here.role_id;
            }
            visit [-->] else { disengage; };
        } else {
            if here.person_role_id == self.target_pr_id and here.valid_to == "" {
                is_safe = (
                    here.role_id != self.admin_role_id
                    or self.active_admin_count > 1
                );
                if is_safe {
                    here.valid_to = "revoked";
                    new_reason = (
                        self.revoke_reason
                        if self.revoke_reason != ""
                        else here.reason
                    );
                    here.reason = new_reason;
                    self.revoked = True;
                    tag = "revoked";
                } else {
                    tag = "blocked-last-admin";
                }
                print(
                    f"[{tag}] {here.person_role_id} "
                    f"(active_admins={self.active_admin_count})"
                );
            }
            visit [-->] else { disengage; };
        }
    }
}

walker BindingRanker {
    has partition_keys: list[str] = [];
    has best_created: list[int] = [];
    has best_seq: list[int] = [];
    has winners: list[str] = [];

    can start with Root entry {
        visit [-->[?:AccountBinding]];
        for (i, key) in enumerate(self.partition_keys) {
            label = (
                f"{key} -> seq={self.best_seq[i]} "
                f"@t={self.best_created[i]}"
            );
            self.winners.append(label);
        }
    }

    can rank with AccountBinding entry {
        key = (
            f"{here.source_type}|{here.source_id}|{here.account_id}"
        );
        if key in self.partition_keys {
            idx = self.partition_keys.index(key);
            newer = here.created_at > self.best_created[idx];
            tie = (
                here.created_at == self.best_created[idx]
                and here.seq_id > self.best_seq[idx]
            );
            if newer or tie {
                self.best_created[idx] = here.created_at;
                self.best_seq[idx] = here.seq_id;
            }
        } else {
            self.partition_keys.append(key);
            self.best_created.append(here.created_at);
            self.best_seq.append(here.seq_id);
        }
        visit [-->] else { disengage; };
    }
}

walker UnusedRolePurge {
    has target_role_id: str = "";
    has pass_num: int = 0;
    has in_use: bool = False;
    has deleted: bool = False;

    can start with Root entry {
        self.pass_num = 1;
        visit [-->[?:PersonRole]];
        self.pass_num = 2;
        visit [-->[?:Role]];
    }

    can check_ref with PersonRole entry {
        if here.role_id == self.target_role_id and here.valid_to == "" {
            self.in_use = True;
        }
        visit [-->] else { disengage; };
    }

    can try_delete with Role entry {
        if here.role_id == self.target_role_id {
            if self.in_use {
                print(f"[keep] role {here.title} still referenced");
            } else {
                print(f"[purge] deleting unused role {here.title}");
                del here;
                self.deleted = True;
            }
        }
        visit [-->] else { disengage; };
    }
}

