"""Perry compile: cycle-safe static reachability for trusted JS AOT promotion.

Models collect_modules stack overflow when a package subpath resolves back to
an ancestor — unbounded recursion without an explicit visited guard.
"""

node JsPackage {
    has name: str = "";
    has trusted: bool = False;
    has has_route_entry: bool = False;
    has aot_compiled: bool = False;
}

edge Imports {
    has specifier: str = "";
}

edge SubpathResolvesTo {
    has subpath: str = "";
}

walker StaticReachabilityCollector {
    has visited: list[str] = [];
    has reachable: list[str] = [];
    has aot_promoted: list[str] = [];
    has cycles_blocked: int = 0;

    can start with Root entry {
        print("collect_modules: static reachability walk");
        visit [-->];
    }

    can collect with JsPackage entry {
        if here.name in self.visited {
            self.cycles_blocked += 1;
            print(f"[GUARD] cycle on {here.name} — would stack-overflow without visited set");
            disengage;
        }
        self.visited.append(here.name);
        self.reachable.append(here.name);
        route_label = "route" if here.has_route_entry else "no-route";
        print(f"  reach: {here.name} trusted={here.trusted} {route_label}");

        if here.trusted and not here.has_route_entry and not here.aot_compiled {
            here.aot_compiled = True;
            self.aot_promoted.append(here.name);
            print(f"  AOT-promote: {here.name}");
        }

        visit [->:Imports:->];
        visit [->:SubpathResolvesTo:->];
    }
}

with entry {
    app = JsPackage(name="app-entry", trusted=False, has_route_entry=True);
    trusted_lib = JsPackage(name="@vendor/trusted-lib", trusted=True, has_route_entry=False);
    utils = JsPackage(name="@vendor/utils", trusted=True, has_route_entry=False);
    leaf = JsPackage(name="leaf", trusted=False, has_route_entry=False);

    root ++> app;
    app +>:Imports(specifier="./trusted-lib"):+> trusted_lib;
    trusted_lib +>:Imports(specifier="./utils"):+> utils;
    trusted_lib +>:Imports(specifier="./leaf"):+> leaf;
    utils +>:SubpathResolvesTo(subpath="trusted-lib/index"):+> trusted_lib;

    collector = root spawn StaticReachabilityCollector();

    print(f"reachable={collector.reachable}");
    print(f"aot_promoted={collector.aot_promoted}");
    print(f"cycles_blocked={collector.cycles_blocked}");
    print(f"trusted_lib.aot_compiled={trusted_lib.aot_compiled}");
    print(f"utils.aot_compiled={utils.aot_compiled}");
}

"""TypeScript 5.6 module resolution cache pollution: unrelated imports share a lookup-location cache and pick the wrong convex/server types."""

node Package {
    has name: str = "";
    has lookup_location: str = "@convex-dev";
    has dist_type: str = "module";
}

node AggregatePkg(Package) {
    has dist_type: str = "commonjs";
    has is_broken: bool = True;
}

node MigrationsPkg(Package) {
    has is_broken: bool = False;
}

node ConvexModule {
    has module_name: str = "convex/server";
}

node ProgramUnit {
    has label: str = "";
}

edge Imports { }
edge DependsOn { }
edge PollutesCacheFor { }

walker ModuleResolver {
    has cache_scope: str = "";
    has cache_module: str = "";
    has cached_path: str = "";
    has last_resolution: str = "";

    def cache_get(scope: str, module: str) -> str {
        if self.cache_scope == scope and self.cache_module == module and self.cached_path != "" {
            return self.cached_path;
        }
        return "";
    }

    def cache_put(scope: str, module: str, path: str) {
        self.cache_scope = scope;
        self.cache_module = module;
        self.cached_path = path;
    }

    def resolve_convex(for_pkg: Package) -> str {
        scope = for_pkg.lookup_location;
        mod = "convex/server";
        hit = self.cache_get(scope, mod);
        if hit != "" {
            self.last_resolution = hit;
            print(f"  [CACHE HIT] {for_pkg.name} reuses {hit}");
            return hit;
        }
        resolved = "convex/dist/esm-types/server/index.d.ts";
        if for_pkg.dist_type == "commonjs" {
            resolved = "convex/dist/cjs-types/server/index.d.ts";
        }
        self.cache_put(scope, mod, resolved);
        self.last_resolution = resolved;
        ctx_label = "broken CJS" if for_pkg.dist_type == "commonjs" else "ESM";
        print(f"  [RESOLVE] {for_pkg.name} ({ctx_label}) -> {resolved}");
        return resolved;
    }

    can start with Root entry {
        visit [-->];
    }

    can start with ProgramUnit entry {
        print(f"=== {here.label} ===");
        visit [->:Imports:->] else { disengage; };
    }

    can import_pkg with AggregatePkg | MigrationsPkg entry {
        visit [->:DependsOn:->] else { disengage; };
        self.resolve_convex(here);
        visit [->:PollutesCacheFor:->] else { visit [-->]; };
    }

    can reach_dependency with ConvexModule entry {
        visit [-->];
    }
}

with entry {
    convex = ConvexModule(module_name="convex/server");
    aggregate = AggregatePkg(name="@convex-dev/aggregate");
    migrations = MigrationsPkg(name="@convex-dev/migrations");
    aggregate +>:DependsOn:+> convex;
    migrations +>:DependsOn:+> convex;
    aggregate +>:PollutesCacheFor:+> migrations;

    clean = ProgramUnit(label="migrations only (expected ESM types)");
    root ++> clean;
    clean +>:Imports:+> migrations;
    clean spawn ModuleResolver();

    print("");

    polluted = ProgramUnit(label="aggregate then migrations (TS 5.6 cache pollution)");
    root ++> polluted;
    polluted +>:Imports:+> aggregate;
    polluted spawn ModuleResolver();
}

"""Selected call-target traversal for assembly call-graph projection.

Resolve external MemberRef operands through owner-retained, active assembly
participants against a frozen correspondence manifest. Physical call-site
identity stays separate from logical member correspondence; inactive shadows
and ambiguous candidates are never indexed or traversed.
"""

node BodyArtifact {
    has assembly_name: str = "";
    has manifest_frozen: bool = False;
}

node RetainedParticipant {
    has name: str = "";
    has active: bool = True;
    has ambiguous: bool = False;
    has platform_close: bool = False;
    has available: bool = True;
}

node PhysicalCallSite {
    has site_id: str = "";
    has target_member: str = "";
    has target_declaring: str = "";
}

node CatalogMember {
    has member_name: str = "";
    has declaring_type: str = "";
    has signature: str = "";
    has is_forwarder: bool = False;
}

node ManifestRequest {
    has kind: str = "";
    has present: bool = True;
}

edge ExternalOperand { }
edge SelectedParticipant { }
edge SuppliesDefinition { }
edge PlanDeclares { }
edge TypeForwards { }

walker CallTargetResolver {
    has physical_site: str = "";
    has logical_sig: str = "";
    has pending_member: str = "";
    has pending_declaring: str = "";
    has outcome: str = "";
    has found_match: bool = False;
    has forwarding: bool = False;

    can start with Root entry {
        visit [-->];
    }

    can scope with BodyArtifact entry {
        if not here.manifest_frozen {
            self.outcome = "correspondence-incomplete";
            print(f"[correspondence-incomplete] manifest open on {here.assembly_name}");
            disengage;
        }
        print(f"Projecting call targets for {here.assembly_name} (manifest frozen)");
        visit [->:ExternalOperand:->] else { disengage; };
    }

    can at_operand with PhysicalCallSite entry {
        self.physical_site = here.site_id;
        self.pending_member = here.target_member;
        self.pending_declaring = here.target_declaring;
        self.found_match = False;
        self.forwarding = False;
        self.outcome = "";
        visit [->:SelectedParticipant:->] else {
            self.outcome = "invalid-reference";
            print(f"[invalid-reference] site={self.physical_site} has no selected participant");
            disengage;
        };
    }

    can pick_participant with RetainedParticipant entry {
        if here.ambiguous or not here.active {
            print(f"[skip] shadow/ambiguous candidate {here.name} never traversed");
            disengage;
        }
        if not here.available {
            self.outcome = "candidate-unavailable";
            print(f"[candidate-unavailable] site={self.physical_site} participant={here.name}");
            disengage;
        }
        visit [->:SuppliesDefinition:->] else {
            missing_label = "member-missing" if here.platform_close else "invalid-reference";
            self.outcome = missing_label;
            print(f"[{missing_label}] site={self.physical_site} seeking "
                  f"{self.pending_declaring}::{self.pending_member} in {here.name}");
            disengage;
        };
    }

    can bind_definition with CatalogMember entry {
        if self.forwarding {
            print(f"  type-forward Metadata outcome -> "
                  f"{here.declaring_type}::{here.member_name} ({here.signature})");
            disengage;
        } elif here.member_name == self.pending_member
            and here.declaring_type == self.pending_declaring {
            self.found_match = True;
            self.logical_sig = here.signature;
            self.outcome = "resolved-definition";
            print(f"[resolved-definition] physical={self.physical_site} "
                  f"logical={self.pending_declaring}::{here.member_name} "
                  f"sig={self.logical_sig}");
            if here.is_forwarder {
                self.forwarding = True;
                visit [->:TypeForwards:->] else { disengage; };
            } else {
                disengage;
            }
        } else {
            visit [-->];
        }
    }
}

walker ManifestAuditor {
    has removed_kind: str = "";
    has saw_expansion: bool = False;

    can start with Root entry {
        visit [-->];
    }

    can freeze_check with BodyArtifact entry {
        visit [->:PlanDeclares:->] else { disengage; };
    }

    can audit_request with ManifestRequest entry {
        if here.kind == self.removed_kind and not here.present {
            self.saw_expansion = True;
            print(f"[plan-expansion] removed signature request kind={here.kind}");
        }
        visit [-->] else {
            if self.saw_expansion {
                print("[correspondence-incomplete] frozen plan would be incomplete after removal");
            } else {
                print("[ok] declaring, parameter, return requests present — manifest complete");
            }
            disengage;
        };
    }
}

