    print("=== correspondence manifest audit ===");
    root spawn ManifestAuditor(removed_kind="parameter");
}

"""Identity toolkit-db escape hatches as OSP: recursive org subchart, atomic role guards, and latest-per-partition bindings."""

node Person {
    has person_id: str = "";
    has name: str = "";
}

node Role {
    has role_id: str = "";
    has title: str = "";
    has is_admin: bool = False;
}

node PersonRole {
    has person_role_id: str = "";
    has role_id: str = "";
    has valid_to: str = "";
    has reason: str = "";
}

node AccountBinding {
    has source_type: str = "";
    has source_id: str = "";
    has account_id: str = "";
    has created_at: int = 0;
    has seq_id: int = 0;
}

edge OrgReports { }
edge RoleAssignment { }

walker SubchartWalker {
    has max_depth: int = 1;
    has depth: int = 0;
    has visited: list[str] = [];
    has names: list[str] = [];

    can explore with Person entry {
        if here.person_id in self.visited {
            print(f"[cycle] blocked at {here.name}");
            disengage;
        }
        self.visited.append(here.person_id);
        self.names.append(here.name);
        can_recurse = self.max_depth < 0 or self.depth < self.max_depth;
        if can_recurse {
            child_depth = self.depth + 1;
            self.depth = child_depth;
            visit [->:OrgReports:->] else { disengage; };
            self.depth = self.depth - 1;
        } else {
            disengage;
        }
    }
}

walker RoleGuard {
    has target_pr_id: str = "";
    has admin_role_id: str = "admin";
    has revoke_reason: str = "";
    has pass_num: int = 0;
    has active_admin_count: int = 0;
    has target_role_id: str = "";
    has revoked: bool = False;

    can start with Root entry {
        self.pass_num = 1;
        visit [-->[?:PersonRole]];
        self.pass_num = 2;
        visit [-->[?:PersonRole]];
    }

    can audit with PersonRole entry {
        if self.pass_num == 1 {
            if here.valid_to == "" and here.role_id == self.admin_role_id {
                self.active_admin_count += 1;
            }
            if here.person_role_id == self.target_pr_id {
                self.target_role_id = here.role_id;
            }
            visit [-->] else { disengage; };
        } else {
            if here.person_role_id == self.target_pr_id and here.valid_to == "" {
                is_safe = (
                    here.role_id != self.admin_role_id
                    or self.active_admin_count > 1
