                if is_safe {
                    here.valid_to = "revoked";
                    new_reason = (
                        self.revoke_reason
                        if self.revoke_reason != ""
                        else here.reason
                    );
                    here.reason = new_reason;
                    self.revoked = True;
                    tag = "revoked";
                } else {
                    tag = "blocked-last-admin";
                }
                print(
                    f"[{tag}] {here.person_role_id} "
                    f"(active_admins={self.active_admin_count})"
                );
            }
            visit [-->] else { disengage; };
        }
    }
