"""TypeScript 5.6 module resolution cache pollution: unrelated imports share a lookup-location cache and pick the wrong convex/server types."""

node Package {
    has name: str = "";
    has lookup_location: str = "@convex-dev";
    has dist_type: str = "module";
}

node AggregatePkg(Package) {
    has dist_type: str = "commonjs";
    has is_broken: bool = True;
}

node MigrationsPkg(Package) {
    has is_broken: bool = False;
}

node ConvexModule {
    has module_name: str = "convex/server";
}

node ProgramUnit {
    has label: str = "";
}

edge Imports { }
edge DependsOn { }
edge PollutesCacheFor { }

walker ModuleResolver {
    has cache_scope: str = "";
    has cache_module: str = "";
    has cached_path: str = "";
    has last_resolution: str = "";

    def cache_get(scope: str, module: str) -> str {
        if self.cache_scope == scope and self.cache_module == module and self.cached_path != "" {
            return self.cached_path;
        }
        return "";
    }

    def cache_put(scope: str, module: str, path: str) {
        self.cache_scope = scope;
        self.cache_module = module;
        self.cached_path = path;
    }

    def resolve_convex(for_pkg: Package) -> str {
        scope = for_pkg.lookup_location;
        mod = "convex/server";
        hit = self.cache_get(scope, mod);
        if hit != "" {
            self.last_resolution = hit;
            print(f"  [CACHE HIT] {for_pkg.name} reuses {hit}");
            return hit;
        }
        resolved = "convex/dist/esm-types/server/index.d.ts";
        if for_pkg.dist_type == "commonjs" {
            resolved = "convex/dist/cjs-types/server/index.d.ts";
        }
        self.cache_put(scope, mod, resolved);
        self.last_resolution = resolved;
        ctx_label = "broken CJS" if for_pkg.dist_type == "commonjs" else "ESM";
        print(f"  [RESOLVE] {for_pkg.name} ({ctx_label}) -> {resolved}");
        return resolved;
    }

    can start with ProgramUnit entry {
        print(f"=== {here.label} ===");
        visit [->:Imports:->] else { disengage; };
    }

    can import_pkg with AggregatePkg | MigrationsPkg entry {
        visit [->:DependsOn:->] else { disengage; };
        self.resolve_convex(here);
        visit [->:PollutesCacheFor:->] else { visit [-->]; };
    }

    can reach_dependency with ConvexModule entry {
        visit [-->];
    }
}

with entry {
    convex = ConvexModule(module_name="convex/server");
    aggregate = AggregatePkg(name="@convex-dev/aggregate");
    migrations = MigrationsPkg(name="@convex-dev/migrations");
    aggregate +>:DependsOn:+> convex;
    migrations +>:DependsOn:+> convex;
    aggregate +>:PollutesCacheFor:+> migrations;

    clean = ProgramUnit(label="migrations only (expected ESM types)");
    root ++> clean;
    clean +>:Imports:+> migrations;
    clean spawn ModuleResolver();

    print("");

    polluted = ProgramUnit(label="aggregate then migrations (TS 5.6 cache pollution)");
    root ++> polluted;
    polluted +>:Imports:+> aggregate;
    polluted spawn ModuleResolver();
}

