"""Stacked merge-request dependency dispatch: blockers, review gates, and branch-base selection."""

node WorkflowConfig {
    has stacked_branches_enabled: bool = False;
    has default_branch: str = "main";
}

node Issue {
    has title: str = "";
    has status: str = "Todo";
    has branch: str = "";
    has head_sha: str = "";
    has has_open_pr: bool = False;
    has pr_draft: bool = False;
    has pr_merged: bool = False;
}

node DependentIssue(Issue) { }

node BlockerIssue(Issue) { }

edge Blocks { }

edge StackedFrom {
    has parent_sha: str = "";
}

walker CycleGuard {
    has stack: list[str] = [];
    has cycle_detected: bool = False;

    can start with DependentIssue entry {
        self.stack.append(here.title);
        visit [<--:Blocks:--] else {
            if self.stack {
                self.stack.pop();
            }
            disengage;
        };
    }

    can walk with BlockerIssue entry {
        if here.title in self.stack {
            self.cycle_detected = True;
            disengage;
        }
        self.stack.append(here.title);
        visit [<--:Blocks:--] else {
            if self.stack {
                self.stack.pop();
            }
            disengage;
        };
    }
}

walker StackedDispatchAuditor {
    has stacked_enabled: bool = False;
    has default_branch: str = "main";
    has unmerged: int = 0;
    has review_eligible: int = 0;
    has parent_branch: str = "";
    has parent_title: str = "";
    has parent_sha: str = "";
    has decision: str = "hold";
    has base_branch: str = "";
    has wait_reason: str = "";

    def apply_policy() -> None {
        if self.unmerged == 0 {
            self.decision = "dispatch";
            self.base_branch = self.default_branch;
            self.wait_reason = "all_blockers_merged";
        } elif not self.stacked_enabled {
            self.decision = "hold";
            self.wait_reason = "stacked_disabled_pending_blockers";
        } elif self.unmerged >= 2 {
            self.decision = "hold";
            self.wait_reason = "multiple_unmerged_blockers";
        } elif self.review_eligible >= 2 {
            self.decision = "hold";
            self.wait_reason = "multiple_human_review_parents";
        } elif self.unmerged == 1 and self.review_eligible == 1 {
            self.decision = "dispatch_stacked";
            self.base_branch = self.parent_branch;
            self.wait_reason = "stacked_from_human_review_parent";
        } else {
            self.decision = "hold";
            self.wait_reason = "blocker_not_eligible_for_stack";
        }
    }

    can evaluate with DependentIssue entry {
        visit [<--:Blocks:--] else {
            self.apply_policy();
            disengage;
        };
    }

    can inspect with BlockerIssue entry {
        merged = here.status == "Merged" or here.pr_merged;
        if not merged {
            self.unmerged += 1;
            review_ready = (
                here.status == "Human Review"
                and here.has_open_pr
                and not here.pr_draft
                and not here.pr_merged
                and here.branch != ""
            );
            if review_ready {
                self.review_eligible += 1;
                self.parent_branch = here.branch;
                self.parent_title = here.title;
                self.parent_sha = here.head_sha;
            }
        }
        disengage;
    }
}

walker ReanchorAuditor {
    has default_branch: str = "main";
    has action: str = "waiting";
    has old_base: str = "";
    has new_base: str = "";

    can start with DependentIssue entry {
        visit [<--:Blocks:--] else {
            disengage;
        };
    }

    can on_parent with BlockerIssue entry {
        if here.status == "Merged" or here.pr_merged {
            self.action = "retarget_pr_to_main";
            self.old_base = here.branch;
            self.new_base = self.default_branch;
        } else {
            self.action = "pause_until_parent_merges";
            self.old_base = here.branch;
            self.new_base = here.branch;
        }
        disengage;
    }
}

with entry {
    cfg = WorkflowConfig(stacked_branches_enabled=True, default_branch="main");
    root ++> cfg;

    merged_blocker = BlockerIssue(
        title="auth-hardening",
        status="Merged",
        branch="feat/auth-hardening",
        head_sha="aaa111",
        has_open_pr=True,
        pr_merged=True
    );
    review_parent = BlockerIssue(
        title="api-contract",
        status="Human Review",
        branch="feat/api-contract",
        head_sha="bbb222",
        has_open_pr=True
    );
    stacked_child = DependentIssue(title="stacked-ui", status="Todo");
    clean_child = DependentIssue(title="docs-only", status="Todo");
    cyclic_a = BlockerIssue(title="cycle-a", status="In Progress", branch="feat/cycle-a");
    cyclic_b = BlockerIssue(title="cycle-b", status="In Progress", branch="feat/cycle-b");
    cyclic_child = DependentIssue(title="cycle-child", status="Todo");

    merged_blocker +>:Blocks:+> clean_child;
    review_parent +>:Blocks:+> stacked_child;
    cyclic_a +>:Blocks:+> cyclic_b;
    cyclic_b +>:Blocks:+> cyclic_a;
    cyclic_a +>:Blocks:+> cyclic_child;

    root ++> merged_blocker ++> review_parent ++> stacked_child;
    root ++> clean_child;
    root ++> cyclic_child;

    cycle_guard = CycleGuard();
    cyclic_child spawn cycle_guard;

    stacked_audit = StackedDispatchAuditor(
        stacked_enabled=cfg.stacked_branches_enabled,
        default_branch=cfg.default_branch
    );
    stacked_child spawn stacked_audit;
    if stacked_audit.decision == "dispatch_stacked" {
        review_parent +>:StackedFrom(parent_sha=stacked_audit.parent_sha):+> stacked_child;
    }

    clean_audit = StackedDispatchAuditor(
        stacked_enabled=cfg.stacked_branches_enabled,
        default_branch=cfg.default_branch
    );
    clean_child spawn clean_audit;

    reanchor = ReanchorAuditor(default_branch=cfg.default_branch);
    stacked_child spawn reanchor;

    print(f"[cycle] cyclic_child cycle_detected={cycle_guard.cycle_detected}");
    print(
        f"[stacked] {stacked_child.title} decision={stacked_audit.decision} "
        f"base={stacked_audit.base_branch} reason={stacked_audit.wait_reason} "
        f"parent={stacked_audit.parent_title}@{stacked_audit.parent_sha}"
    );
    print(
        f"[merged] {clean_child.title} decision={clean_audit.decision} "
        f"base={clean_audit.base_branch} reason={clean_audit.wait_reason}"
    );
    print(
        f"[reanchor] parent merged -> action={reanchor.action} "
        f"old_base={reanchor.old_base} new_base={reanchor.new_base}"
    );
}

"""Windows command execution hang: descendant processes inherit stdout/stderr handles and block EOF indefinitely."""

node ShellCommand {
    has title: str = "";
    has timeout_sec: int = 0;
    has timed_out: bool = False;
    has completed: bool = False;
    has status: str = "pending";
}

node Process {
    has title: str = "";
    has pid: int = 0;
    has alive: bool = True;
    has exited: bool = False;
}

node PipeHandle {
    has title: str = "";
    has stream: str = "";
    has eof: bool = False;
    has open_writers: int = 0;
}

node JobObject {
    has title: str = "";
    has closed: bool = False;
    has kill_on_close: bool = True;
}

edge Contains { }
edge Spawns { }
edge Inherits { }
edge Monitors { }

walker EofWaiter {
    has stuck_forever: bool = False;
    has seen_pids: list[int] = [];

    can start with Root entry {
        visit [-->] else { disengage; };
    }

    can on_command with ShellCommand entry {
        print(f"Running '{here.title}' with {here.timeout_sec}s timeout");
        if here.timed_out {
            print("Parent shell process exited; harness still awaiting pipe EOF");
        }
        visit [->:Contains:->];
        visit [->:Monitors:->];
    }

    can on_job with JobObject entry {
        visit [->:Contains:->] else { visit [-->]; };
    }

    can on_process with Process entry {
        state_label = "alive" if here.alive else "exited";
        print(f"  process pid={here.pid} ({here.title}): {state_label}");
        if here.pid in self.seen_pids {
            disengage;
        }
        self.seen_pids.append(here.pid);
        visit [->:Inherits:->];
        visit [->:Spawns:->] else { visit [-->]; };
    }

    can on_pipe with PipeHandle entry {
        if here.open_writers > 0 and not here.eof {
            self.stuck_forever = True;
            print(
                f"HANG on {here.stream}: {here.open_writers} descendant(s) "
                f"still hold the write end; EOF never arrives"
            );
            disengage;
        }
        eof_label = "received" if here.eof else "pending";
        print(f"  pipe {here.stream}: EOF {eof_label}");
        visit [-->];
    }
}

walker BoundedCleanup {
    has tree_killed: bool = False;
    has pipes_closed: int = 0;
    has seen_pids: list[int] = [];

    can start with Root entry {
        visit [-->] else { disengage; };
    }

    can on_command with ShellCommand entry {
        if not here.timed_out {
            disengage;
        }
        print(f"Timeout on '{here.title}': closing job and detaching pipes");
        here.status = "cleanup";
        visit [->:Contains:->];
        visit [->:Monitors:->] else { disengage; };
        here.completed = True;
        done_label = "timeout" if here.timed_out else "ok";
        here.status = done_label;
        print(
            f"Command '{here.title}' finished promptly: "
            f"tree_killed={self.tree_killed}, pipes_closed={self.pipes_closed}"
        );
        disengage;
    }

    can on_job with JobObject entry {
        if here.kill_on_close and not here.closed {
            here.closed = True;
            print(f"  job '{here.title}' closed (KILL_ON_JOB_CLOSE)");
        }
        visit [->:Contains:->] else { visit [-->]; };
    }

    can on_process with Process entry {
        if here.pid not in self.seen_pids {
            self.seen_pids.append(here.pid);
            if here.alive {
                here.alive = False;
                here.exited = True;
                self.tree_killed = True;
                print(f"  terminated pid {here.pid} ({here.title})");
            }
        }
        visit [->:Spawns:->] else { visit [-->]; };
    }

    can on_pipe with PipeHandle entry {
        if not here.eof {
            here.open_writers = 0;
            here.eof = True;
            self.pipes_closed += 1;
            print(f"  detached {here.stream} handle; EOF signaled");
        }
        visit [-->];
    }
}

with entry {
    stdout_pipe = PipeHandle(title="stdout", stream="stdout", open_writers=1);
    stderr_pipe = PipeHandle(title="stderr", stream="stderr", open_writers=1);
    parent = Process(title="dotnet test", pid=1001, alive=False, exited=True);
    worker = Process(title="MSBuild nodemode worker", pid=1042, alive=True);
    job = JobObject(title="command_job", kill_on_close=True);
    cmd = ShellCommand(
        title="dotnet test Tests.csproj -c Release",
        timeout_sec=30,
        timed_out=True
    );

    root ++> cmd;
    cmd +>:Monitors:+> stdout_pipe;
    cmd +>:Monitors:+> stderr_pipe;
    cmd +>:Contains:+> job;
    job +>:Contains:+> parent;
    parent +>:Spawns:+> worker;
    parent +>:Inherits:+> stdout_pipe;
    parent +>:Inherits:+> stderr_pipe;
    worker +>:Inherits:+> stdout_pipe;
    worker +>:Inherits:+> stderr_pipe;

    print("=== Broken path: completion waits on uncontrolled descendants ===");
    waiter = EofWaiter();
    root spawn waiter;
    print(f"agent turn stuck={waiter.stuck_forever}");

    print("");
    print("=== Fixed path: job teardown bounds cleanup and returns ===");
    cleanup = BoundedCleanup();
    root spawn cleanup;
    print(f"cmd.completed={cmd.completed}, cmd.status={cmd.status}");
}

