"""Windows command execution hang: descendant processes inherit stdout/stderr handles and block EOF indefinitely."""

node ShellCommand {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has timeout_sec: int = 0;
    has timed_out: bool = False;
    has completed: bool = False;
    has status: str = "pending";
}

node Process {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has pid: int = 0;
    has alive: bool = True;
    has exited: bool = False;
}

node PipeHandle {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has stream: str = "";
    has eof: bool = False;
    has open_writers: int = 0;
}

node JobObject {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has closed: bool = False;
    has kill_on_close: bool = True;
}

edge Encloses { }
edge Spawns { }
edge Inherits { }
edge Monitors { }

walker EofWaiter {
    has stuck_forever: bool = False;
    has seen_pids: list[int] = [];

    can start with Root entry {
        visit [-->] else { disengage; };
    }

    can on_command with ShellCommand entry {
        print(f"Running '{here.title}' with {here.timeout_sec}s timeout");
        if here.timed_out {
            print("Parent shell process exited; harness still awaiting pipe EOF");
        }
        visit [->:Encloses:->];
        visit [->:Monitors:->];
    }

    can on_job with JobObject entry {
        visit [->:Encloses:->] else { visit [-->]; };
    }

    can on_process with Process entry {
        state_label = "alive" if here.alive else "exited";
        print(f"  process pid={here.pid} ({here.title}): {state_label}");
        if here.pid in self.seen_pids {
            disengage;
        }
        self.seen_pids.append(here.pid);
        visit [->:Inherits:->];
        visit [->:Spawns:->] else { visit [-->]; };
    }

    can on_pipe with PipeHandle entry {
        if here.open_writers > 0 and not here.eof {
            self.stuck_forever = True;
            print(
                f"HANG on {here.stream}: {here.open_writers} descendant(s) "
                f"still hold the write end; EOF never arrives"
            );
            disengage;
        }
        eof_label = "received" if here.eof else "pending";
        print(f"  pipe {here.stream}: EOF {eof_label}");
        visit [-->];
    }
}

walker BoundedCleanup {
    has tree_killed: bool = False;
    has pipes_closed: int = 0;
    has seen_pids: list[int] = [];

    can start with Root entry {
        visit [-->] else { disengage; };
    }

    can on_command with ShellCommand entry {
        if not here.timed_out {
            disengage;
        }
        print(f"Timeout on '{here.title}': closing job and detaching pipes");
        here.status = "cleanup";
        visit [->:Encloses:->];
        visit [->:Monitors:->] else { disengage; };
        here.completed = True;
        done_label = "timeout" if here.timed_out else "ok";
        here.status = done_label;
        print(
            f"Command '{here.title}' finished promptly: "
            f"tree_killed={self.tree_killed}, pipes_closed={self.pipes_closed}"
        );
        disengage;
    }

    can on_job with JobObject entry {
        if here.kill_on_close and not here.closed {
            here.closed = True;
            print(f"  job '{here.title}' closed (KILL_ON_JOB_CLOSE)");
        }
        visit [->:Encloses:->] else { visit [-->]; };
    }

    can on_process with Process entry {
        if here.pid not in self.seen_pids {
            self.seen_pids.append(here.pid);
            if here.alive {
                here.alive = False;
                here.exited = True;
                self.tree_killed = True;
                print(f"  terminated pid {here.pid} ({here.title})");
            }
        }
        visit [->:Spawns:->] else { visit [-->]; };
    }

    can on_pipe with PipeHandle entry {
        if not here.eof {
            here.open_writers = 0;
            here.eof = True;
            self.pipes_closed += 1;
            print(f"  detached {here.stream} handle; EOF signaled");
        }
        visit [-->];
    }
}

with entry {
    stdout_pipe = PipeHandle(title="stdout", stream="stdout", open_writers=1);
    stderr_pipe = PipeHandle(title="stderr", stream="stderr", open_writers=1);
    parent = Process(title="dotnet test", pid=1001, alive=False, exited=True);
    worker = Process(title="MSBuild nodemode worker", pid=1042, alive=True);
    job = JobObject(title="command_job", kill_on_close=True);
    cmd = ShellCommand(
        title="dotnet test Tests.csproj -c Release",
        timeout_sec=30,
        timed_out=True
    );

    root ++> cmd;
    cmd +>:Monitors:+> stdout_pipe;
    cmd +>:Monitors:+> stderr_pipe;
    cmd +>:Encloses:+> job;
    job +>:Encloses:+> parent;
    parent +>:Spawns:+> worker;
    parent +>:Inherits:+> stdout_pipe;
    parent +>:Inherits:+> stderr_pipe;
    worker +>:Inherits:+> stdout_pipe;
    worker +>:Inherits:+> stderr_pipe;

    print("=== Broken path: completion waits on uncontrolled descendants ===");
    waiter = EofWaiter();
    root spawn waiter;
    print(f"agent turn stuck={waiter.stuck_forever}");

    print("");
    print("=== Fixed path: job teardown bounds cleanup and returns ===");
    cleanup = BoundedCleanup();
    root spawn cleanup;
    print(f"cmd.completed={cmd.completed}, cmd.status={cmd.status}");
}

"""Stacked merge-request dependency dispatch: blockers, review gates, and branch-base selection."""

node WorkflowConfig {
    has stacked_branches_enabled: bool = False;
    has default_branch: str = "main";
}

node Issue {
    has title: str = "";
    has status: str = "Todo";
    has branch: str = "";
    has head_sha: str = "";
    has has_open_pr: bool = False;
    has pr_draft: bool = False;
    has pr_merged: bool = False;
}

node DependentIssue(Issue) { }

node BlockerIssue(Issue) { }

edge Blocks { }

edge StackedFrom {
    has parent_sha: str = "";
}

walker CycleGuard {
    has stack: list[str] = [];
    has cycle_detected: bool = False;

    can start with DependentIssue entry {
        self.stack.append(here.title);
        visit [<-:Blocks:-] else {
            if self.stack {
                self.stack.pop();
            }
            disengage;
        };
    }

    can walk with BlockerIssue entry {
        if here.title in self.stack {
            self.cycle_detected = True;
            disengage;
        }
        self.stack.append(here.title);
        visit [<-:Blocks:-] else {
            if self.stack {
                self.stack.pop();
            }
            disengage;
        };
    }
}

walker StackedDispatchAuditor {
    has stacked_enabled: bool = False;
    has default_branch: str = "main";
    has unmerged: int = 0;
    has review_eligible: int = 0;
    has parent_branch: str = "";
    has parent_title: str = "";
    has parent_sha: str = "";
    has decision: str = "hold";
    has base_branch: str = "";
    has wait_reason: str = "";

    def apply_policy() {
        if self.unmerged == 0 {
            self.decision = "dispatch";
            self.base_branch = self.default_branch;
            self.wait_reason = "all_blockers_merged";
        } elif not self.stacked_enabled {
            self.decision = "hold";
            self.wait_reason = "stacked_disabled_pending_blockers";
        } elif self.unmerged >= 2 {
            self.decision = "hold";
            self.wait_reason = "multiple_unmerged_blockers";
        } elif self.review_eligible >= 2 {
            self.decision = "hold";
            self.wait_reason = "multiple_human_review_parents";
        } elif self.unmerged == 1 and self.review_eligible == 1 {
            self.decision = "dispatch_stacked";
            self.base_branch = self.parent_branch;
            self.wait_reason = "stacked_from_human_review_parent";
        } else {
            self.decision = "hold";
            self.wait_reason = "blocker_not_eligible_for_stack";
        }
    }

    can evaluate with DependentIssue entry {
        visit [<-:Blocks:-] else {
            self.apply_policy();
            disengage;
        };
    }

    can inspect with BlockerIssue entry {
        merged = here.status == "Merged" or here.pr_merged;
        if not merged {
            self.unmerged += 1;
            review_ready = (
                here.status == "Human Review"
                and here.has_open_pr
                and not here.pr_draft
                and not here.pr_merged
                and here.branch != ""
            );
            if review_ready {
                self.review_eligible += 1;
                self.parent_branch = here.branch;
                self.parent_title = here.title;
                self.parent_sha = here.head_sha;
            }
        }
    }
}

walker ReanchorAuditor {
    has default_branch: str = "main";
    has action: str = "waiting";
    has old_base: str = "";
    has new_base: str = "";

    can start with DependentIssue entry {
        visit [<-:Blocks:-] else {
            disengage;
        };
    }

    can on_parent with BlockerIssue entry {
        if here.status == "Merged" or here.pr_merged {
            self.action = "retarget_pr_to_main";
            self.old_base = here.branch;
            self.new_base = self.default_branch;
        } else {
            self.action = "pause_until_parent_merges";
            self.old_base = here.branch;
            self.new_base = here.branch;
        }
    }
}

with entry {
    cfg = WorkflowConfig(stacked_branches_enabled=True, default_branch="main");
    root ++> cfg;

    merged_blocker = BlockerIssue(
        title="auth-hardening",
        status="Merged",
        branch="feat/auth-hardening",
        head_sha="aaa111",
        has_open_pr=True,
        pr_merged=True
    );
    review_parent = BlockerIssue(
        title="api-contract",
        status="Human Review",
        branch="feat/api-contract",
        head_sha="bbb222",
        has_open_pr=True
    );
    stacked_child = DependentIssue(title="stacked-ui", status="Todo");
    clean_child = DependentIssue(title="docs-only", status="Todo");
    cyclic_a = BlockerIssue(title="cycle-a", status="In Progress", branch="feat/cycle-a");
    cyclic_b = BlockerIssue(title="cycle-b", status="In Progress", branch="feat/cycle-b");
    cyclic_child = DependentIssue(title="cycle-child", status="Todo");

    merged_blocker +>:Blocks:+> clean_child;
    review_parent +>:Blocks:+> stacked_child;
    cyclic_a +>:Blocks:+> cyclic_b;
    cyclic_b +>:Blocks:+> cyclic_a;
    cyclic_a +>:Blocks:+> cyclic_child;

    root ++> merged_blocker ++> review_parent ++> stacked_child;
    root ++> clean_child;
    root ++> cyclic_child;

    cycle_guard = CycleGuard();
    cyclic_child spawn cycle_guard;

    stacked_audit = StackedDispatchAuditor(
        stacked_enabled=cfg.stacked_branches_enabled,
        default_branch=cfg.default_branch
    );
    stacked_child spawn stacked_audit;
    if stacked_audit.decision == "dispatch_stacked" {
        review_parent +>:StackedFrom(parent_sha=stacked_audit.parent_sha):+> stacked_child;
    }

    clean_audit = StackedDispatchAuditor(
        stacked_enabled=cfg.stacked_branches_enabled,
        default_branch=cfg.default_branch
    );
    clean_child spawn clean_audit;

    reanchor = ReanchorAuditor(default_branch=cfg.default_branch);
    clean_child spawn reanchor;

    print(f"[cycle] cyclic_child cycle_detected={cycle_guard.cycle_detected}");
    print(
        f"[stacked] {stacked_child.title} decision={stacked_audit.decision} "
        f"base={stacked_audit.base_branch} reason={stacked_audit.wait_reason} "
        f"parent={stacked_audit.parent_title}@{stacked_audit.parent_sha}"
    );
    print(
        f"[merged] {clean_child.title} decision={clean_audit.decision} "
        f"base={clean_audit.base_branch} reason={clean_audit.wait_reason}"
    );
    print(
        f"[reanchor] parent merged -> action={reanchor.action} "
        f"old_base={reanchor.old_base} new_base={reanchor.new_base}"
    );
}

"""Floyd-Warshall city audit: find the city with fewest neighbors within a distance threshold."""

node Region {
    has name: str = "";
    has threshold: int = 0;
}

node City {
    has city_id: int = 0;

    can publish_roads with FloydWarshall entry {
        i = visitor.index_of(self.city_id);
        for nb in self-->:Road:--> {
            j = visitor.index_of(nb.city_id);
            w = (self -:Road:- nb).weight;
            if w < visitor.dist[i][j] {
                visitor.dist[i][j] = w;
                visitor.dist[j][i] = w;
            }
        }
    }
}

edge InRegion { }
edge Road {
    has weight: int = 0;
}

walker FloydWarshall {
    has threshold: int = 0;
    has phase: int = 0;
    has inf: int = 1000000000;
    has ids: list[int] = [];
    has dist: list[list[int]] = [];
    has best_city: int = -1;
    has best_count: int = 1000000000;

    def index_of(city_id: int) -> int {
        for (i, cid) in enumerate(self.ids) {
            if cid == city_id {
                return i;
            }
        }
        return -1;
    }

    def setup_matrix() -> None {
        self.ids.sort();
        n = len(self.ids);
        self.dist = [];
        for i in range(n) {
            row = [];
            for j in range(n) {
                cell = 0 if i == j else self.inf;
                row.append(cell);
            }
            self.dist.append(row);
        }
    }

    def relax_all() -> None {
        n = len(self.dist);
        for k in range(n) {
            for i in range(n) {
                if self.dist[i][k] == self.inf {
                    continue;
                }
                for j in range(n) {
                    via = self.dist[i][k] + self.dist[k][j];
                    if via < self.dist[i][j] {
                        self.dist[i][j] = via;
                    }
                }
            }
        }
    }

    def pick_winner() -> None {
        n = len(self.ids);
        self.best_city = -1;
        self.best_count = self.inf;
        for i in range(n) {
            cnt = 0;
            for j in range(n) {
                if i != j && self.dist[i][j] <= self.threshold {
                    cnt += 1;
                }
            }
            if cnt < self.best_count {
                self.best_count = cnt;
                self.best_city = self.ids[i];
            } elif cnt == self.best_count && self.ids[i] > self.best_city {
                self.best_city = self.ids[i];
            }
        }
    }

    can start with Root entry {
        visit [-->];
    }

    can begin with Region entry {
        self.threshold = here.threshold;
        self.phase = 0;
        self.ids = [];
        visit [->:InRegion:->] else { disengage; };
        self.setup_matrix();
        self.phase = 1;
        visit [->:InRegion:->] else { disengage; };
        self.relax_all();
        self.pick_winner();
        print(
            f"Region {here.name}: city {self.best_city} has the fewest "
            f"neighbors ({self.best_count}) within distance {self.threshold}"
        );
        disengage;
    }

    can catalog with City entry {
        if self.phase == 0 {
            self.ids.append(here.city_id);
        }
        disengage;
    }
}

with entry {
    metro = Region(name="LeetCode-1334", threshold=4);
    root ++> metro;
    c0 = City(city_id=0);
    c1 = City(city_id=1);
    c2 = City(city_id=2);
    c3 = City(city_id=3);
    metro +>:InRegion:+> c0;
    metro +>:InRegion:+> c1;
    metro +>:InRegion:+> c2;
    metro +>:InRegion:+> c3;
    c0 +>:Road(weight=3):+> c1;
    c1 +>:Road(weight=1):+> c2;
    c1 +>:Road(weight=4):+> c3;
    c2 +>:Road(weight=1):+> c3;
    root spawn FloydWarshall();
}

"""Bounded RFC 5280 certificate path construction and validation demo.

Models peer-supplied intermediates plus explicit trust anchors, walks issuer
chains with cycle/depth/budget guards, and validates policy at an injected UTC
instant. V1 reports revocation-not-checked and performs no network fetch.
"""

node Certificate {
    has subject: str = "";
    has issuer: str = "";
    has not_before: int = 0;
    has not_after: int = 0;
    has is_ca: bool = False;
    has path_len: int = -1;
    has server_auth: bool = False;
    has sig_valid: bool = True;
}

node TrustAnchor {
    has subject: str = "";
    has label: str = "";
}

node ValidationPolicy {
    has validation_time: int = 0;
    has max_depth: int = 8;
    has search_budget: int = 32;
    has clock_available: bool = True;
}

edge Issues { }

walker PathConstructor {
    has budget: int = 16;
    has target_subject: str = "";
    has seen: list[str] = [];
    has path: list[str] = [];

    can start with Certificate entry {
        self.seen.append(here.subject);
        self.path.append(here.subject);
        if here.subject == self.target_subject {
            print(f"built candidate path: {self.path}");
            disengage;
        }
        visit [->:Issues:->] else { disengage; }
    }

    can extend with Certificate entry {
        if self.budget <= 0 {
            print("FAIL: construction budget exhausted");
            disengage;
        }
        self.budget -= 1;
        if here.subject in self.seen {
            disengage;
        }
        self.seen.append(here.subject);
        self.path.append(here.subject);
        if here.subject == self.target_subject {
            print(f"built candidate path: {self.path}");
            disengage;
        }
        visit [->:Issues:->] else { disengage; }
    }
}

walker CertPathValidator {
    has validation_time: int = 0;
    has max_depth: int = 8;
    has budget: int = 32;
    has trust_subjects: list[str] = [];
    has seen: list[str] = [];
    has depth: int = 0;
    has valid: bool = False;
    has status: str = "";

    def check_time(cert: Certificate) -> bool {
        return (
            self.validation_time >= cert.not_before
            and self.validation_time <= cert.not_after
        );
    }

    def finish_chain(top: Certificate) {
        if top.issuer in self.trust_subjects {
            self.valid = True;
            self.status = "valid";
            print(
                f"PASS: chain anchors at trusted '{top.issuer}' "
                f"(revocation-not-checked)"
            );
        } else {
            self.status = "untrusted-root";
            print(f"FAIL: untrusted issuer '{top.issuer}'");
        }
    }

    def process_cert(cert: Certificate, is_leaf: bool) {
        if self.budget <= 0 {
            self.status = "budget-exhausted";
            print("FAIL: validation search budget exhausted");
            disengage;
        }
        self.budget -= 1;

        if cert.subject in self.seen {
            self.status = "cycle-or-duplicate";
            print(f"FAIL: duplicate certificate '{cert.subject}'");
            disengage;
        }
        self.seen.append(cert.subject);
        self.depth += 1;

        if self.depth > self.max_depth {
            self.status = "excessive-depth";
            print("FAIL: excessive path depth");
            disengage;
        }

        if not self.check_time(cert) {
            self.status = "validity";
            print(
                f"FAIL: '{cert.subject}' outside validity at "
                f"t={self.validation_time}"
            );
            disengage;
        }

        if not cert.sig_valid {
            self.status = "signature";
            print(f"FAIL: bad signature on '{cert.subject}'");
            disengage;
        }

        if is_leaf {
            if not cert.server_auth {
                self.status = "policy";
                print("FAIL: leaf missing TLS serverAuth EKU");
                disengage;
            }
            if cert.is_ca {
                self.status = "policy";
                print("FAIL: TLS leaf must not be a CA");
                disengage;
            }
        } else {
            if not cert.is_ca {
                self.status = "policy";
                print(f"FAIL: '{cert.subject}' is not a CA");
                disengage;
            }
            if cert.path_len != -1 and cert.path_len < self.depth - 1 {
                self.status = "policy";
                print(f"FAIL: pathLen violated on '{cert.subject}'");
                disengage;
            }
        }
    }

    can start with Certificate entry {
        self.process_cert(here, is_leaf=True);
        visit [<--:Issues:--] else {
            self.finish_chain(here);
            disengage;
        }
    }

    can ascend with Certificate entry {
        self.process_cert(here, is_leaf=False);
        visit [<--:Issues:--] else {
            self.finish_chain(here);
            disengage;
        }
    }
}

with entry {
    policy = ValidationPolicy(
        validation_time=2000,
        max_depth=8,
        search_budget=32,
        clock_available=True
    );
    ta = TrustAnchor(subject="Root CA", label="corp-root");
    inter = Certificate(
        subject="Intermediate CA",
        issuer="Root CA",
        is_ca=True,
        path_len=0,
        not_before=1000,
        not_after=3000,
        sig_valid=True
    );
    leaf = Certificate(
        subject="server.example",
        issuer="Intermediate CA",
        server_auth=True,
        is_ca=False,
        not_before=1000,
        not_after=3000,
        sig_valid=True
    );

    inter +>:Issues:+> leaf;
    root ++> policy ++> ta;
    root ++> inter;
    root ++> leaf;

    if not policy.clock_available {
        print("FAIL: wall clock unavailable — fail closed");
    } else {
        print("--- bounded path construction ---");
        inter spawn PathConstructor(budget=16, target_subject="server.example");

        print("--- RFC 5280 path validation ---");
        leaf spawn CertPathValidator(
            validation_time=policy.validation_time,
            max_depth=policy.max_depth,
            budget=policy.search_budget,
            trust_subjects=["Root CA"]
        );
    }
}

