    cleanup = BoundedCleanup();
    root spawn cleanup;
    print(f"cmd.completed={cmd.completed}, cmd.status={cmd.status}");
}

"""Bounded RFC 5280 certificate path construction and validation demo.

Models peer-supplied intermediates plus explicit trust anchors, walks issuer
chains with cycle/depth/budget guards, and validates policy at an injected UTC
instant. V1 reports revocation-not-checked and performs no network fetch.
"""

node Certificate {
    has subject: str = "";
    has issuer: str = "";
    has not_before: int = 0;
    has not_after: int = 0;
    has is_ca: bool = False;
    has path_len: int = -1;
    has server_auth: bool = False;
    has sig_valid: bool = True;
}

node TrustAnchor {
    has subject: str = "";
    has label: str = "";
}

node ValidationPolicy {
    has validation_time: int = 0;
    has max_depth: int = 8;
    has search_budget: int = 32;
    has clock_available: bool = True;
}

edge Issues { }

walker PathConstructor {
    has budget: int = 16;
    has target_subject: str = "";
    has seen: list[str] = [];
    has path: list[str] = [];

    can start with Certificate entry {
        self.seen.append(here.subject);
        self.path.append(here.subject);
        if here.subject == self.target_subject {
            print(f"built candidate path: {self.path}");
            disengage;
        }
        visit [->:Issues:->] else { disengage; }
    }

    can extend with Certificate entry {
        if self.budget <= 0 {
            print("FAIL: construction budget exhausted");
            disengage;
        }
        self.budget -= 1;
        if here.subject in self.seen {
            disengage;
        }
        self.seen.append(here.subject);
        self.path.append(here.subject);
        if here.subject == self.target_subject {
            print(f"built candidate path: {self.path}");
            disengage;
        }
        visit [->:Issues:->] else { disengage; }
    }
}

walker CertPathValidator {
    has validation_time: int = 0;
    has max_depth: int = 8;
    has budget: int = 32;
    has trust_subjects: list[str] = [];
    has seen: list[str] = [];
    has depth: int = 0;
    has valid: bool = False;
    has status: str = "";

    def check_time(cert: Certificate) -> bool {
        return (
            self.validation_time >= cert.not_before
            and self.validation_time <= cert.not_after
        );
    }

    def finish_chain(top: Certificate) {
        if top.issuer in self.trust_subjects {
            self.valid = True;
            self.status = "valid";
            print(
                f"PASS: chain anchors at trusted '{top.issuer}' "
                f"(revocation-not-checked)"
            );
        } else {
            self.status = "untrusted-root";
            print(f"FAIL: untrusted issuer '{top.issuer}'");
        }
    }

    def process_cert(cert: Certificate, is_leaf: bool) -> bool {
        if self.budget <= 0 {
            self.status = "budget-exhausted";
            print("FAIL: validation search budget exhausted");
            return False;
        }
        self.budget -= 1;

        if cert.subject in self.seen {
            self.status = "cycle-or-duplicate";
            print(f"FAIL: duplicate certificate '{cert.subject}'");
            return False;
        }
        self.seen.append(cert.subject);
        self.depth += 1;

        if self.depth > self.max_depth {
            self.status = "excessive-depth";
            print("FAIL: excessive path depth");
            return False;
        }

        if not self.check_time(cert) {
            self.status = "validity";
            print(
                f"FAIL: '{cert.subject}' outside validity at "
                f"t={self.validation_time}"
            );
            return False;
        }

        if not cert.sig_valid {
            self.status = "signature";
            print(f"FAIL: bad signature on '{cert.subject}'");
            return False;
        }

        if is_leaf {
            if not cert.server_auth {
                self.status = "policy";
                print("FAIL: leaf missing TLS serverAuth EKU");
                return False;
            }
            if cert.is_ca {
                self.status = "policy";
                print("FAIL: TLS leaf must not be a CA");
                return False;
            }
        } else {
            if not cert.is_ca {
                self.status = "policy";
                print(f"FAIL: '{cert.subject}' is not a CA");
                return False;
            }
            if cert.path_len != -1 and cert.path_len < self.depth - 1 {
                self.status = "policy";
                print(f"FAIL: pathLen violated on '{cert.subject}'");
                return False;
            }
        }
        return True;
    }

    can start with Certificate entry {
        if not self.process_cert(here, is_leaf=True) {
            disengage;
        }
        visit [<--:Issues:<--] else {
            self.finish_chain(here);
            disengage;
        }
    }

    can ascend with Certificate entry {
        if not self.process_cert(here, is_leaf=False) {
            disengage;
        }
        visit [<--:Issues:<--] else {
            self.finish_chain(here);
            disengage;
        }
    }
}

with entry {
    policy = ValidationPolicy(
        validation_time=2000,
        max_depth=8,
        search_budget=32,
        clock_available=True
    );
    ta = TrustAnchor(subject="Root CA", label="corp-root");
    inter = Certificate(
        subject="Intermediate CA",
        issuer="Root CA",
        is_ca=True,
        path_len=0,
        not_before=1000,
        not_after=3000,
        sig_valid=True
    );
    leaf = Certificate(
        subject="server.example",
        issuer="Intermediate CA",
        server_auth=True,
        is_ca=False,
        not_before=1000,
        not_after=3000,
        sig_valid=True
    );

    inter +>:Issues:+> leaf;
    root ++> policy ++> ta;
    root ++> inter;
    root ++> leaf;

    if not policy.clock_available {
        print("FAIL: wall clock unavailable - fail closed");
    } else {
        print("--- bounded path construction ---");
        inter spawn PathConstructor(budget=16, target_subject="server.example");

        print("--- RFC 5280 path validation ---");
        leaf spawn CertPathValidator(
            validation_time=policy.validation_time,
            max_depth=policy.max_depth,
            budget=policy.search_budget,
            trust_subjects=["Root CA"]
        );
    }
}

"""Unified cache contract demo: principal isolation, dependency generation checks, and deletion invalidation cascade."""

node Cacheable {
    has label: str = "";

    def dependency_tag() -> str {
        return self.label;
    }
}

node Principal {
    has name: str = "";
    has scope_id: str = "";
}

node ContentSource(Cacheable) {
    has title: str = "";
    has generation: int = 0;
    has deleted: bool = False;

    override def dependency_tag() -> str {
        return f"{self.title}:g{self.generation}";
    }
}

node CacheEntry(Cacheable) {
    has key: str = "";
    has artifact_class: str = "answer";
    has principal_scope: str = "";
    has captured_generation: int = 0;
    has valid: bool = True;

    override def dependency_tag() -> str {
        state = "live" if self.valid else "tombstone";
        return f"{self.key}:{state}";
    }
}

edge OwnedBy { }
edge DependsOn { }
edge InvalidatedBy { has reason: str = ""; }

walker CacheResolver {
    has principal_scope: str = "";
    has query_key: str = "";
    has outcome: str = "MISS";
    has pending_generation: int = -1;

    can start with Root entry {
        visit [-->];
    }

    can probe with CacheEntry entry {
        if here.key != self.query_key {
            visit [-->];
        } else if not here.valid {
            print(f"BYPASS tombstoned {here.key}");
            self.outcome = "BYPASS";
            visit [-->];
        } else if here.principal_scope != self.principal_scope {
            print(f"ISOLATION deny {here.key} scope={here.principal_scope}");
            visit [-->];
        } else {
            self.pending_generation = here.captured_generation;
            visit [->:DependsOn:->];
        }
    }

    can check_generation with ContentSource entry {
        if here.deleted {
            self.outcome = "BYPASS";
            print(f"BYPASS deleted source {here.title}");
        } else if self.pending_generation != here.generation {
            self.outcome = "BYPASS";
            print(f"BYPASS generation drift {self.pending_generation} vs {here.generation}");
        } else {
            self.outcome = "HIT";
            print(f"HIT {self.query_key} scope={self.principal_scope} gen={here.generation}");
        }
        self.pending_generation = -1;
        disengage;
    }
}

walker InvalidationCascade {
    has reason: str = "";
    has invalidated_count: int = 0;
    has source_ref: ContentSource = None;

    can start with Root entry {
        visit [-->[?:ContentSource]];
    }

    can on_delete with ContentSource entry {
        if not here.deleted {
            visit [-->];
        } else {
            self.source_ref = here;
            print(f"cascade invalidation from {here.title}");
            visit [<-:DependsOn:<-] else { visit [-->]; };
        }
    }

    can tombstone with CacheEntry entry {
        if here.valid {
            here.valid = False;
            self.invalidated_count += 1;
            if self.source_ref is not None {
                self.source_ref +>:InvalidatedBy(reason=self.reason):+> here;
            }
            print(f"tombstone {here.key} reason={self.reason}");
        }
        visit [-->] else { disengage; };
    }
}

walker DependencyReporter {
    can start with Root entry {
        visit [-->];
    }

    can inspect with CacheEntry | ContentSource entry {
        print(f"dependency {here.dependency_tag()}");
        visit [-->];
    }
}

with entry {
    alice = Principal(name="Alice", scope_id="tenant-a");
    bob = Principal(name="Bob", scope_id="tenant-b");
    doc = ContentSource(title="Policy", label="policy-doc", generation=3);

    alice_hit = CacheEntry(
        key="summarize",
        label="alice-summarize",
        artifact_class="answer",
        principal_scope="tenant-a",
        captured_generation=3
    );
    alice_hit +>:OwnedBy:+> alice;
    alice_hit +>:DependsOn:+> doc;

    bob_entry = CacheEntry(
        key="summarize",
        label="bob-summarize",
        artifact_class="answer",
        principal_scope="tenant-b",
        captured_generation=2
    );
    bob_entry +>:OwnedBy:+> bob;
    bob_entry +>:DependsOn:+> doc;

    root ++> alice ++> bob;
    root ++> doc;
    root ++> alice_hit ++> bob_entry;

    print("--- dependency inventory ---");
    root spawn DependencyReporter();

    print("--- Alice lookup (expect HIT) ---");
    root spawn CacheResolver(principal_scope="tenant-a", query_key="summarize");

    print("--- Bob lookup (expect BYPASS generation drift) ---");
    root spawn CacheResolver(principal_scope="tenant-b", query_key="summarize");

    print("--- Charlie cross-tenant (expect ISOLATION deny) ---");
    root spawn CacheResolver(principal_scope="tenant-c", query_key="summarize");

    print("--- delete source and cascade tombstones ---");
    doc.deleted = True;
    root spawn InvalidationCascade(reason="delete");

    print(f"invalidated {InvalidationCascade().invalidated_count} entries during cascade demo wiring");

    print("--- Alice after delete (expect BYPASS) ---");
    root spawn CacheResolver(principal_scope="tenant-a", query_key="summarize");
}

"""Stacked merge-request dependency dispatch: blockers, review gates, and branch-base selection."""

node WorkflowConfig {
    has stacked_branches_enabled: bool = False;
    has default_branch: str = "main";
}

node Issue {
    has title: str = "";
    has status: str = "Todo";
    has branch: str = "";
    has head_sha: str = "";
    has has_open_pr: bool = False;
    has pr_draft: bool = False;
    has pr_merged: bool = False;
}

node DependentIssue(Issue) { }

node BlockerIssue(Issue) { }

edge BlockedBy { }

edge StackedFrom {
    has parent_sha: str = "";
}

walker CycleGuard {
    has stack: list[str] = [];
    has cycle_detected: bool = False;

    can start with DependentIssue entry {
        self.stack.append(here.title);
        visit [->:BlockedBy:->] else {
            if len(self.stack) > 0 {
                self.stack.pop();
            }
            disengage;
        };
    }

    can walk with BlockerIssue entry {
        if here.title in self.stack {
            self.cycle_detected = True;
            disengage;
        }
        self.stack.append(here.title);
        visit [->:BlockedBy:->] else {
            if len(self.stack) > 0 {
                self.stack.pop();
            }
            disengage;
        };
    }
}

walker StackedDispatchAuditor {
    has stacked_enabled: bool = False;
    has default_branch: str = "main";
    has unmerged: int = 0;
    has review_eligible: int = 0;
    has parent_branch: str = "";
    has parent_title: str = "";
    has parent_sha: str = "";
    has decision: str = "hold";
    has base_branch: str = "";
    has wait_reason: str = "";

    def apply_policy() {
        if self.unmerged == 0 {
            self.decision = "dispatch";
            self.base_branch = self.default_branch;
            self.wait_reason = "all_blockers_merged";
        } else {
            if self.stacked_enabled == False {
                self.decision = "hold";
                self.wait_reason = "stacked_disabled_pending_blockers";
            } else {
                if self.unmerged >= 2 {
                    self.decision = "hold";
                    self.wait_reason = "multiple_unmerged_blockers";
                } else {
                    if self.review_eligible >= 2 {
                        self.decision = "hold";
                        self.wait_reason = "multiple_human_review_parents";
                    } else {
                        if self.unmerged == 1 {
                            if self.review_eligible == 1 {
                                self.decision = "dispatch_stacked";
                                self.base_branch = self.parent_branch;
                                self.wait_reason = "stacked_from_human_review_parent";
                            } else {
                                self.decision = "hold";
                                self.wait_reason = "blocker_not_eligible_for_stack";
                            }
                        } else {
                            self.decision = "hold";
                            self.wait_reason = "blocker_not_eligible_for_stack";
                        }
                    }
                }
            }
        }
    }

    can audit with DependentIssue entry {
        visit [->:BlockedBy:->];
    }

    can audit with DependentIssue exit {
        self.apply_policy();
    }

    can inspect with BlockerIssue entry {
        merged = False;
        if here.status == "Merged" {
            merged = True;
        }
        if here.pr_merged == True {
            merged = True;
        }
        if merged == False {
            self.unmerged += 1;
            review_ready = False;
            if here.status == "Human Review" {
                if here.has_open_pr == True {
                    if here.pr_draft == False {
                        if here.pr_merged == False {
                            if here.branch != "" {
                                review_ready = True;
                            }
                        }
                    }
                }
            }
            if review_ready == True {
                self.review_eligible += 1;
                self.parent_branch = here.branch;
                self.parent_title = here.title;
                self.parent_sha = here.head_sha;
            }
        }
    }
}

walker ReanchorAuditor {
    has default_branch: str = "main";
    has action: str = "waiting";
    has old_base: str = "";
    has new_base: str = "";

    can start with DependentIssue entry {
        visit [->:BlockedBy:->] else {
            disengage;
        };
    }

    can on_parent with BlockerIssue entry {
        parent_merged = False;
        if here.status == "Merged" {
            parent_merged = True;
        }
        if here.pr_merged == True {
            parent_merged = True;
        }
        if parent_merged == True {
            self.action = "retarget_pr_to_main";
            self.old_base = here.branch;
            self.new_base = self.default_branch;
        } else {
            self.action = "pause_until_parent_merges";
            self.old_base = here.branch;
            self.new_base = here.branch;
        }
    }
}

with entry {
    cfg = WorkflowConfig(stacked_branches_enabled=True, default_branch="main");
    root ++> cfg;

    merged_blocker = BlockerIssue(
        title="auth-hardening",
        status="Merged",
        branch="feat/auth-hardening",
        head_sha="aaa111",
        has_open_pr=True,
        pr_merged=True
    );
    review_parent = BlockerIssue(
        title="api-contract",
        status="Human Review",
        branch="feat/api-contract",
        head_sha="bbb222",
        has_open_pr=True
    );
    stacked_child = DependentIssue(title="stacked-ui", status="Todo");
    clean_child = DependentIssue(title="docs-only", status="Todo");
    cyclic_a = BlockerIssue(title="cycle-a", status="In Progress", branch="feat/cycle-a");
    cyclic_b = BlockerIssue(title="cycle-b", status="In Progress", branch="feat/cycle-b");
    cyclic_child = DependentIssue(title="cycle-child", status="Todo");

    clean_child +>:BlockedBy:+> merged_blocker;
    stacked_child +>:BlockedBy:+> review_parent;
    cyclic_child +>:BlockedBy:+> cyclic_a;
    cyclic_b +>:BlockedBy:+> cyclic_a;
    cyclic_a +>:BlockedBy:+> cyclic_b;

    root ++> merged_blocker ++> review_parent ++> stacked_child;
    root ++> clean_child;
    root ++> cyclic_child;

    cycle_guard = CycleGuard();
    cyclic_child spawn cycle_guard;

    stacked_audit = StackedDispatchAuditor(
        stacked_enabled=cfg.stacked_branches_enabled,
        default_branch=cfg.default_branch
    );
    stacked_child spawn stacked_audit;
    if stacked_audit.decision == "dispatch_stacked" {
        review_parent +>:StackedFrom(parent_sha=stacked_audit.parent_sha):+> stacked_child;
    }

    clean_audit = StackedDispatchAuditor(
        stacked_enabled=cfg.stacked_branches_enabled,
        default_branch=cfg.default_branch
    );
    clean_child spawn clean_audit;

    reanchor = ReanchorAuditor(default_branch=cfg.default_branch);
    clean_child spawn reanchor;

    print(f"[cycle] cyclic_child cycle_detected={cycle_guard.cycle_detected}");
    print(
        f"[stacked] {stacked_child.title} decision={stacked_audit.decision} "
        f"base={stacked_audit.base_branch} reason={stacked_audit.wait_reason} "
        f"parent={stacked_audit.parent_title}@{stacked_audit.parent_sha}"
    );
    print(
        f"[merged] {clean_child.title} decision={clean_audit.decision} "
        f"base={clean_audit.base_branch} reason={clean_audit.wait_reason}"
    );
    print(
        f"[reanchor] parent merged -> action={reanchor.action} "
        f"old_base={reanchor.old_base} new_base={reanchor.new_base}"
    );
}

