"""Floyd-Warshall city audit: find the city with fewest neighbors within a distance threshold."""

node Region {
    has name: str = "";
    has threshold: int = 0;
}

node City {
    has city_id: int = 0;

    can publish_roads with FloydWarshall entry {
        if visitor.phase != 1 {
            disengage;
        }
        i = visitor.index_of(self.city_id);
        for nb in self[->:Road:->] {
            j = visitor.index_of(nb.city_id);
            w = (self -:Road:- nb).weight;
            if w < visitor.dist[i][j] {
                visitor.dist[i][j] = w;
                visitor.dist[j][i] = w;
            }
        }
    }
}

edge InRegion { }
edge Road {
    has weight: int = 0;
}

walker FloydWarshall {
    has threshold: int = 0;
    has phase: int = 0;
    has inf: int = 1000000000;
    has ids: list[int] = [];
    has dist: list[list[int]] = [];
    has best_city: int = -1;
    has best_count: int = 1000000000;

    def index_of(city_id: int) -> int {
        for (i, cid) in enumerate(self.ids) {
            if cid == city_id {
                return i;
            }
        }
        return -1;
    }

    def setup_matrix() -> None {
        self.ids.sort();
        n = len(self.ids);
        self.dist = [];
        for i in range(n) {
            row = [];
            for j in range(n) {
                cell = 0 if i == j else self.inf;
                row.append(cell);
            }
            self.dist.append(row);
        }
    }

    def relax_all() -> None {
        n = len(self.dist);
        for k in range(n) {
            for i in range(n) {
                if self.dist[i][k] == self.inf {
                    continue;
                }
                for j in range(n) {
                    via = self.dist[i][k] + self.dist[k][j];
                    if via < self.dist[i][j] {
                        self.dist[i][j] = via;
                    }
                }
            }
        }
    }

    def pick_winner() -> None {
        n = len(self.ids);
        self.best_city = -1;
        self.best_count = self.inf;
        for i in range(n) {
            cnt = 0;
            for j in range(n) {
                if i != j && self.dist[i][j] <= self.threshold {
                    cnt += 1;
                }
            }
            if cnt < self.best_count {
                self.best_count = cnt;
                self.best_city = self.ids[i];
            } elif cnt == self.best_count && self.ids[i] > self.best_city {
                self.best_city = self.ids[i];
            }
        }
    }

    can start with Root entry {
        visit [-->];
    }

    can begin with Region entry {
        self.threshold = here.threshold;
        self.phase = 0;
        self.ids = [];
        visit [->:InRegion:->] else { disengage; };
        self.setup_matrix();
        self.phase = 1;
        visit [->:InRegion:->] else { disengage; };
        self.relax_all();
        self.pick_winner();
        print(
            f"Region {here.name}: city {self.best_city} has the fewest "
            f"neighbors ({self.best_count}) within distance {self.threshold}"
        );
        disengage;
    }

    can catalog with City entry {
        if self.phase == 0 {
            self.ids.append(here.city_id);
        }
    }
}

