    has value: int = 0;
}

edge LeftChild { }

edge RightChild { }

walker InsertWalk {
    has target: int = 0;
    has inserted: bool = False;
    has steps: int = 0;
    has max_steps: int = 128;

    can start with Root entry {
        visit [-->] else {
            root ++> BstNode(value=self.target);
            self.inserted = True;
            disengage;
        };
    }

    can seek with BstNode entry {
        if self.inserted {
            disengage;
        }
        self.steps += 1;
        if self.steps > self.max_steps {
            print("insert aborted: depth limit exceeded");
            disengage;
        }
        if here.value == self.target {
            disengage;
        }
        go_left = self.target < here.value;
        if go_left {
            visit [->:LeftChild:->] else {
                here +>:LeftChild:+> BstNode(value=self.target);
                self.inserted = True;
                disengage;
            };
        } else {
            visit [->:RightChild:->] else {
                here +>:RightChild:+> BstNode(value=self.target);
                self.inserted = True;
                disengage;
            };
        }
    }
}

