    can draw with BstNode entry {
        row = f"{self.indent}{here.value}";
        print(row);
        saved = self.indent;
        self.indent = f"{saved}│ ";
        visit [->:LeftChild:->];
        self.indent = f"{saved}  ";
        visit [->:RightChild:->];
        self.indent = saved;
    }
}

