"""PF SetNestedBlock: positional index matching crosses nested tag_name values."""

node SpansMetric {
    has resource_name: str = "";
}

node GroupByElement {
    has path: str = "";
    has configured_tag: str = "";
    has tag_name: str = "";
    has tag_is_unknown: bool = True;
}

node CorrelationFrame {
    has step: int = 0;
}

edge AtConfig { }
edge AtPlan { }
edge NextFrame { }
edge FirstFrame { }

walker PositionalBridge {
    has staged_tag: str = "";

    can start with SpansMetric entry {
        visit [->:FirstFrame:->];
    }

    can correlate with CorrelationFrame entry {
        visit [->:AtConfig:->];
        visit [->:AtPlan:->];
        visit [->:NextFrame:->] else { disengage; };
    }

    can capture_config with GroupByElement entry {
        self.staged_tag = here.configured_tag;
    }

    can apply_to_plan with GroupByElement entry {
        if self.staged_tag != "" {
            here.tag_name = self.staged_tag;
            here.tag_is_unknown = False;
        }
        shown = here.tag_name if not here.tag_is_unknown else "unknown";
        print(f"{here.path}.tag_name = {shown}");
    }
}

with entry {
  stream = GroupByElement(path="@stream", configured_tag="stream");
  tier = GroupByElement(path="@tier", configured_tag="tier");
  service = GroupByElement(path="service");
  status = GroupByElement(path="status");

  f0 = CorrelationFrame(step=0);
  f0 +>:AtConfig:+> service;
  f0 +>:AtPlan:+> stream;

  f1 = CorrelationFrame(step=1);
  f1 +>:AtConfig:+> status;
  f1 +>:AtPlan:+> tier;

  f2 = CorrelationFrame(step=2);
  f2 +>:AtConfig:+> stream;
  f2 +>:AtPlan:+> service;

  f3 = CorrelationFrame(step=3);
  f3 +>:AtConfig:+> tier;
  f3 +>:AtPlan:+> status;

  metric = SpansMetric(resource_name="SpansMetric");
  root ++> metric;
  metric +>:FirstFrame:+> f0;
  f0 +>:NextFrame:+> f1 +>:NextFrame:+> f2 +>:NextFrame:+> f3;

  print("Pulumi config order: service, status, @stream, @tier");
  print("Terraform plan order: @stream, @tier, service, status");
  print("Positional bridge pairs config[i] into plan[i]:");
  metric spawn PositionalBridge();
  print("Expected: @stream=stream @tier=tier service=unknown status=unknown");
}

"""Arithma layer rule: model src/ import knots, audit upward DependsOn edges, and detect cycles."""

node Module {
    has name: str = "";
    has layer: int = 0;
    has layer_name: str = "";
}

edge DependsOn { }

walker LayerRuleAuditor {
    has parent_name: str = "";
    has parent_layer: int = -1;
    has trail: list[str] = [];
    has violation_count: int = 0;

    can start with Root entry {
        visit [-->[?:Module]] else { disengage; }
    }

    can audit with Module entry {
        if here.name in self.trail {
            disengage;
        }
        if self.parent_name != "" and here.layer > self.parent_layer {
            print(
                f"UPWARD {self.parent_name}({self.parent_layer})"
                f" -> {here.name}({here.layer}) [{here.layer_name}]"
            );
            self.violation_count += 1;
        }
        saved_name = self.parent_name;
        saved_layer = self.parent_layer;
        self.parent_name = here.name;
        self.parent_layer = here.layer;
        self.trail.append(here.name);
        visit [->:DependsOn:->] else {
            self.trail.pop();
            self.parent_name = saved_name;
            self.parent_layer = saved_layer;
            disengage;
        }
    }
}

walker CycleGuard {
    has stack: list[str] = [];
    has cycles_found: int = 0;

    can start with Root entry {
        visit [-->[?:Module]] else { disengage; }
    }

    can probe with Module entry {
        if here.name in self.stack {
            print(f"CYCLE knot: {here.name} closes an import loop");
            self.cycles_found += 1;
            disengage;
        }
        self.stack.append(here.name);
        visit [->:DependsOn:->] else {
            self.stack.pop();
            disengage;
        }
    }
}

with entry {
    node_mod = Module(name="node", layer=0, layer_name="foundation");
    tokenizer = Module(name="tokenizer", layer=1, layer_name="language");
    parser = Module(name="parser", layer=1, layer_name="language");
    expression = Module(name="expression", layer=2, layer_name="math");
    simplify = Module(name="simplify", layer=3, layer_name="engine");
    status = Module(name="status", layer=4, layer_name="validation");

    node_mod +>:DependsOn:+> tokenizer;
    parser +>:DependsOn:+> simplify;
    simplify +>:DependsOn:+> status;
    status +>:DependsOn:+> simplify;
    expression +>:DependsOn:+> simplify;
    simplify +>:DependsOn:+> expression;

    root ++> node_mod;
    root ++> tokenizer;
    root ++> parser;
    root ++> expression;
    root ++> simplify;
    root ++> status;

    print("--- upward dependency scan (layer rule) ---");
    auditor = LayerRuleAuditor();
    root spawn auditor;
    print(f"upward edges found: {auditor.violation_count}");

    print("--- cycle scan (knots 2 and 4) ---");
    guard = CycleGuard();
    root spawn guard;
    print(f"cycles found: {guard.cycles_found}");
}

"""Native POSIX spawn: propagate direct errno and file-action setup failures."""

node Executable {
    has path: str = "";
    has accessible: bool = True;
}

node FileAction {
    has label: str = "";
    has setup_ok: bool = True;
    has fail_errno: int = 0;
}

node FdRegistry {
    has extra_count: int = 0;
    has released: bool = False;
}

node SpawnRequest {
    has posix_errno: int = 0;
    has pid: int = 0;
    has status: str = "pending";
    has path_echo: str = "";
}

edge Invokes { }
edge Prepares { }
edge Owns { }

walker PosixSpawnAuditor {
    has fixed_hangs: int = 0;
    has propagated_errors: int = 0;
    has clean_releases: int = 0;
    has successes: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can review with SpawnRequest entry {
        visit [->:Prepares:->];
        visit [->:Owns:->];
        visit [->:Invokes:->];
        if here.posix_errno != 0 {
            propagated = here.status != "pending";
            if here.pid == 0 and here.status == "hung" {
                here.status = "failed";
                propagated = True;
                self.fixed_hangs += 1;
