"""Native POSIX spawn: propagate direct errno and file-action setup failures."""

node Executable {
    has path: str = "";
    has accessible: bool = True;
}

node FileAction {
    has label: str = "";
    has setup_ok: bool = True;
    has fail_errno: int = 0;
}

node FdRegistry {
    has extra_count: int = 0;
    has released: bool = False;
}

node SpawnRequest {
    has posix_errno: int = 0;
    has pid: int = 0;
    has status: str = "pending";
    has path_echo: str = "";
}

edge Invokes { }
edge SpawnSetup { }
edge Owns { }

walker PosixSpawnAuditor {
    has fixed_hangs: int = 0;
    has propagated_errors: int = 0;
    has clean_releases: int = 0;
    has successes: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can review with SpawnRequest entry {
        visit [->:SpawnSetup:->];
        visit [->:Owns:->];
        visit [->:Invokes:->];
        if here.posix_errno != 0 {
            propagated = here.status != "pending";
            if here.pid == 0 and here.status == "hung" {
                here.status = "failed";
                propagated = True;
                self.fixed_hangs += 1;
                print(
                    f"[FIX] {here.path_echo}: direct errno {here.posix_errno} "
                    f"propagated; aborted wait on pid 0"
                );
            } elif not propagated {
                here.status = "failed";
                propagated = True;
                self.propagated_errors += 1;
                print(
                    f"[ERR] {here.path_echo}: posix_spawn errno {here.posix_errno}"
                );
            }
        } elif here.pid > 0 and here.status == "pending" {
            here.status = "success";
            self.successes += 1;
            print(f"[OK] {here.path_echo}: spawned pid {here.pid}");
        }
        visit [-->] else { disengage; };
    }

    can inspect_setup with FileAction entry {
        if not here.setup_ok {
            print(
                f"[FAIL] file-action '{here.label}' setup errno {here.fail_errno}"
            );
        }
        visit [-->] else { disengage; };
    }

    can release_fds with FdRegistry entry {
        if not here.released {
            here.released = True;
            self.clean_releases += 1;
            print(
                f"[CLEAN] released {here.extra_count} extra-fd registrations"
            );
        }
        visit [-->] else { disengage; };
    }

    can resolve_target with Executable entry {
        access_note = "reachable" if here.accessible else "missing";
        print(f"[TARGET] {here.path} ({access_note})");
        visit [-->] else { disengage; };
    }
}

with entry {
