}

"""Git object graph: validate refs, peel annotated tag chains with cycle guards, and trace commit parents."""

node GitObject {
    has oid: str = "";
    has object_type: str = "";
}

node Commit(GitObject) {
    has message: str = "";
    has tree_oid: str = "";
    has year: int = 0;
    has available: bool = True;
}

node AnnotatedTag(GitObject) {
    has tag_name: str = "";
    has tagger: str = "";
    has year: int = 0;
    has available: bool = True;
}

node Ref {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

node Tree {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

edge Parent { }

edge ObjectRef { }

edge RefTarget { }

edge TreeLink { }

walker TagPeeler {
    has max_depth: int = 10;
    has depth: int = 0;
    has seen: list[str] = [];
    has result_oid: str = "";
    has result_type: str = "";
    has error: str = "";

    can start with Ref entry {
        if not here.available {
            self.error = f"invalid refname: {here.title}";
            disengage;
        }
        if here.title == "" {
            self.error = "empty refname rejected";
            disengage;
        }
        visit [->:RefTarget:->] else {
            self.error = f"ref {here.title} has no target";
            disengage;
        };
    }

    can peel with AnnotatedTag entry {
        if here.oid in self.seen {
            self.error = f"tag peel cycle at {here.oid}";
            disengage;
        }
        if self.depth >= self.max_depth {
            self.error = f"tag peel depth exceeded at {here.oid}";
            disengage;
        }
        self.seen += [here.oid];
        self.depth += 1;
        visit [->:ObjectRef:->] else {
            self.error = f"annotated tag {here.tag_name} missing object";
            disengage;
        };
    }

    can resolve with Commit entry {
        self.result_oid = here.oid;
        self.result_type = here.object_type;
        disengage;
    }
}

walker ParentTracer {
    has max_depth: int = 32;
    has depth: int = 0;
    has chain: list[str] = [];

    can start with Commit entry {
        self.chain += [here.oid];
        visit [->:Parent:->] else {
            disengage;
        };
    }

    can ascend with Commit entry {
        if self.depth >= self.max_depth {
            disengage;
        }
        self.depth += 1;
        self.chain += [here.oid];
        visit [->:Parent:->] else {
            disengage;
        };
    }
}

