"""StarLang scraper declaration and typed acquisition IR: audit closed capability refs, reject malformed identities and raw secrets, and trace provenance from request through artifact to emitted document."""

edge NeedsCapability { }
edge Emits { }
edge Targets { }
edge Produces { }
edge Yields { }

node SchemaType {
    has name: str = "";
}

node ScraperDef {
    has name: str = "";
    has version: str = "";
    has input_type: str = "";
    has approved: bool = False;
}

node CapabilityReq {
    has kind: str = "";
}

node AcqRequest {
    has req_id: str = "";
    has cred_ref: str = "";
}

node SourceArtifact {
    has artifact_id: str = "";
    has from_req: str = "";
}

node EmittedDoc {
    has doc_type: str = "";
    has from_artifact: str = "";
}

walker DeclarationValidator {
    has closed_caps: list[str] = ["http", "dom", "browser", "feed"];
    has errors: list[str] = [];
    has checked: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can validate with ScraperDef entry {
        self.checked += 1;
        if here.version == "" {
            self.errors.append(f"malformed identity: {here.name}");
        }
        if not here.approved {
            self.errors.append(f"awaiting operator approval: {here.name}");
        }
        visit [->:NeedsCapability:->];
        visit [->:Emits:->];
        visit [-->] else { disengage; };
    }

    can check_cap with CapabilityReq entry {
        allowed = here.kind in self.closed_caps;
        if not allowed {
            self.errors.append(f"undeclared capability: {here.kind}");
        }
        visit [-->] else { disengage; };
    }

    can check_schema with SchemaType entry {
        if here.name == "" {
            self.errors.append("undeclared output schema");
        }
        visit [-->] else { disengage; };
    }

    can skip_acq with AcqRequest | SourceArtifact | EmittedDoc entry {
        visit [-->] else { disengage; };
    }
}

walker ProvenanceTracer {
    has trail: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can begin with AcqRequest entry {
        self.trail = [];
        self.trail.append(f"req:{here.req_id}");
        if here.cred_ref.startswith("token:") {
            print(f"REJECT raw credential literal in {here.req_id}");
            disengage;
        }
        visit [->:Targets:->];
        visit [->:Produces:->] else { disengage; };
    }

    can at_source with ScraperDef entry {
        self.trail.append(f"src:{here.name}/{here.version}");
        visit [-->] else { disengage; };
    }

    can via_artifact with SourceArtifact entry {
        self.trail.append(f"artifact:{here.artifact_id}(from {here.from_req})");
        visit [->:Yields:->] else { disengage; };
    }

    can finish with EmittedDoc entry {
        self.trail.append(f"emit:{here.doc_type}(from {here.from_artifact})");
        chain = " > ".join(self.trail);
        print(f"provenance chain: {chain}");
        visit [-->] else { disengage; };
    }
}

