"""Safe stack: prove the deepest kernel call path fits within kernel stack budget."""

node KernelFunction {
    has name: str = "";
    has frame_bytes: int = 0;
    has is_entry: bool = False;
}

node StackBudget {
    has limit_bytes: int = 4096;
    has exception_reserve: int = 512;
}

edge Calls { }

walker StackDepthAnalyzer {
    has stack_limit: int = 0;
    has exception_reserve: int = 0;
    has max_depth: int = 0;
    has path_depth: int = 0;
    has active: list[str] = [];
    has cycle_detected: bool = False;
    has cycle_note: str = "";

    can start with Root entry {
        visit [-->];
    }

    can load_budget with StackBudget entry {
        self.stack_limit = here.limit_bytes;
        self.exception_reserve = here.exception_reserve;
        visit [-->];
    }

    can measure with KernelFunction entry {
        if not here.is_entry and self.path_depth == 0 {
            return;
        }
        for (_, frame_name) in enumerate(self.active) {
            if frame_name == here.name {
                self.cycle_detected = True;
                self.cycle_note = f"recursive cycle at {here.name}";
                disengage;
            }
        }
        self.active.append(here.name);
        self.path_depth += here.frame_bytes;
        if self.path_depth > self.max_depth {
            self.max_depth = self.path_depth;
        }
        visit [->:Calls:->] else { disengage; }
    }

    can unwind with KernelFunction exit {
        if self.path_depth > 0
            and len(self.active) > 0
            and self.active[-1] == here.name {
            self.path_depth -= here.frame_bytes;
            self.active.pop();
        }
    }
}

with entry {
    budget = StackBudget(limit_bytes=4096, exception_reserve=512);
    root ++> budget;

    syscall_entry = KernelFunction(
        name="syscall_entry", frame_bytes=256, is_entry=True
    );
    vfs_read = KernelFunction(name="vfs_read", frame_bytes=512);
    inode_read = KernelFunction(name="inode_read", frame_bytes=768);
    block_io = KernelFunction(name="block_io", frame_bytes=1024);

    root ++> syscall_entry;
    syscall_entry +>:Calls:+> vfs_read;
    vfs_read +>:Calls:+> inode_read;
    inode_read +>:Calls:+> block_io;

    irq_entry = KernelFunction(
        name="irq_dispatch", frame_bytes=128, is_entry=True
    );
    mutual_a = KernelFunction(name="mutual_a", frame_bytes=96);
    mutual_b = KernelFunction(name="mutual_b", frame_bytes=96);

    root ++> irq_entry;
    irq_entry +>:Calls:+> mutual_a;
    mutual_a +>:Calls:+> mutual_b;
    mutual_b +>:Calls:+> mutual_a;

    analyzer = StackDepthAnalyzer();
    root spawn analyzer;

    required = analyzer.max_depth + analyzer.exception_reserve;
    if analyzer.cycle_detected {
        print(
            f"COMPILE ERROR: no finite stack bound — {analyzer.cycle_note}"
        );
    } else {
        if required > analyzer.stack_limit {
            print(
                f"COMPILE ERROR: deepest path {required}B "
                f"exceeds KERNEL_PROCESS_STACK_SIZE "
                f"{analyzer.stack_limit}B"
            );
        } else {
            print(
                f"static_assert passed: deepest path "
                f"{analyzer.max_depth}B + exception "
                f"{analyzer.exception_reserve}B "
                f"<= stack {analyzer.stack_limit}B"
            );
        }
    }
}

"""Weave graph: idempotent observation reconciliation and bounded task context compilation."""

node Task {
    has name: str = "";
    has max_depth: int = 2;
    has max_facts: int = 5;
}

node Resource {
    has name: str = "";
    has weave_uri: str = "";
    has tenant_id: str = "";
    has source_rank: int = 5;
    has inferred: bool = False;
}

node WeaveEntity {
    has label: str = "";
    has tenant_id: str = "";
    has kind: str = "";
    has source_rank: int = 5;
    has inferred: bool = False;
}

node Observation {
    has digest: str = "";
    has source_rank: int = 5;
    has confidence: float = 0.0;
    has ttl: int = 3;
    has age: int = 0;
    has contributes: bool = False;
}

edge Grants {
    has authorized: bool = True;
}

edge Observed {
    has relation: str = "";
}

edge Evidence { }

edge Alias { }

walker Reconciler {
    has digests: list[str] = [];
    has accepted: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can ingest with Observation entry {
        if here.digest in self.digests {
            print(f"[IDEMPOTENT] skip digest {here.digest}");
        } else {
            self.digests.append(here.digest);
            if here.age > here.ttl {
                here.contributes = False;
                print(f"[EXPIRED] {here.digest} age={here.age} ttl={here.ttl}");
            } else {
                here.contributes = True;
                self.accepted += 1;
                tier = "contract" if here.source_rank <= 2 else "detector";
                print(f"[RECONCILE] {here.digest} tier={tier} conf={here.confidence}");
            }
        }
        visit [-->];
    }
}

walker ContextCompiler {
    has depth: int = 0;
    has cap_depth: int = 2;
    has cap_facts: int = 5;
    has fact_count: int = 0;
    has seen: list[str] = [];
    has anchor_tenant: str = "";
    has via_alias: bool = False;

    can start with Root entry {
        visit [-->];
    }

    can begin with Task entry {
        self.cap_depth = here.max_depth;
        self.cap_facts = here.max_facts;
        self.depth = 0;
        self.fact_count = 0;
        self.seen = [];
        self.anchor_tenant = "";
        self.via_alias = False;
        print(f"[COMPILE] task={here.name} depth<={here.max_depth} facts<={here.max_facts}");
        visit [->:Grants:->] else { disengage; };
    }

    can enter with Resource entry {
        if self.fact_count >= self.cap_facts {
            disengage;
        }
        rank_note = "explicit" if not here.inferred else "inferred";
        line = f"grant {here.weave_uri} ({rank_note})";
        self.fact_count += 1;
        print(f"  fact[{self.fact_count}]: {line}");
        if self.depth < self.cap_depth {
            self.depth += 1;
            visit [->:Observed:->] else { self.depth -= 1; };
            self.depth -= 1;
        }
    }

    can walk with WeaveEntity entry {
        if self.fact_count >= self.cap_facts {
            disengage;
        }
        if self.via_alias {
            self.via_alias = False;
            if here.tenant_id != self.anchor_tenant {
                print(f"  [TENANT-BLOCK] alias {self.anchor_tenant} -> {here.tenant_id}");
                disengage;
            }
        } else {
            self.anchor_tenant = here.tenant_id;
        }
        key = f"{here.tenant_id}:{here.label}";
        if key in self.seen {
            print(f"  [CYCLE-GUARD] {here.label}");
            disengage;
        }
        self.seen.append(key);
        rank_note = "explicit" if here.source_rank <= 2 and not here.inferred else "inferred";
        line = f"{here.kind}:{here.label} ({rank_note})";
        self.fact_count += 1;
        print(f"  fact[{self.fact_count}]: {line}");
        if self.depth < self.cap_depth {
            self.depth += 1;
            visit [->:Observed:->] else {
                self.via_alias = True;
                visit [->:Alias:->] else { self.depth -= 1; };
            };
            self.depth -= 1;
        }
    }
}

with entry {
    deploy = Task(name="deploy-api", max_depth=2, max_facts=4);

    api = Resource(
        name="payments-api",
        weave_uri="weave://acme/payments-api",
        tenant_id="acme",
        source_rank=2,
        inferred=False
    );
    shadow = Resource(
        name="shadow-api",
        weave_uri="weave://other/shadow-api",
        tenant_id="other",
        source_rank=5,
        inferred=True
    );

    svc = WeaveEntity(
        label="payments",
        tenant_id="acme",
        kind="service",
        source_rank=2,
        inferred=False
    );
    peer = WeaveEntity(
        label="payments-peer",
        tenant_id="other",
        kind="service",
        source_rank=5,
        inferred=True
    );
    loop = WeaveEntity(
        label="cache",
        tenant_id="acme",
        kind="service",
        source_rank=4,
        inferred=False
    );

    obs_fresh = Observation(
        digest="sha256:deploy-v3",
        source_rank=2,
        confidence=0.95,
        ttl=5,
        age=1
    );
    obs_stale = Observation(
        digest="sha256:old-scan",
        source_rank=5,
        confidence=0.4,
        ttl=2,
        age=4
    );
    obs_dup = Observation(
        digest="sha256:deploy-v3",
        source_rank=2,
        confidence=0.95,
        ttl=5,
