    );

    root ++> deploy;
    deploy +>:Grants(authorized=True):+> api;
    deploy --> shadow;
    api +>:Observed(relation="hosts"):+> svc;
    svc +>:Observed(relation="depends"):+> loop;
    loop +>:Observed(relation="depends"):+> svc;
    svc +>:Alias:+> peer;
    obs_fresh +>:Evidence:+> api;
    obs_stale +>:Evidence:+> api;
    root ++> obs_fresh ++> obs_stale ++> obs_dup;

    print("=== reconciliation ===");
