    print(f"active observations: {obs_fresh.contributes}, stale: {obs_stale.contributes}");

    print("=== bounded context ===");
    root spawn ContextCompiler();
}

"""Interior cell reference load: resumable cursor stepped under streaming budget.

Models issue #3671 — the interior path still calls load_references with an
unlimited FrameTimeBudget while exterior/persistent cells already advance
load_references_budgeted under STREAMING_APPLY_BUDGET (16 ms per frame).
"""

node InteriorCell {
    has name: str = "";
    has textures_flushed: bool = False;
    has apply_complete: bool = False;
}

node PlacedRef {
    has ref_id: str = "";
    has load_cost_ms: int = 0;
    has loaded: bool = False;
}

node NpcSpawn {
    has npc_id: str = "";
    has spawn_cost_ms: int = 0;
    has spawned: bool = False;
}

edge ContainsRef { }
edge SpawnsNpc { }

walker UnbudgetedInteriorLoad {
    has target_name: str = "";
    has budget_ms: int = 2147483647;
    has spent_ms: int = 0;
    has frame_stall_ms: int = 0;

    can start with Root entry {
        print("[UNBUDGETED] load_references — FrameTimeBudget::unlimited()");
        visit [-->];
    }

    can apply with InteriorCell entry {
        if here.name != self.target_name {
            visit [-->];
        } else {
            print(f"  interior transition into {here.name}");
            visit [->:ContainsRef:->] else {
                here.textures_flushed = True;
                here.apply_complete = True;
                self.frame_stall_ms = self.spent_ms;
                print(f"  flush_pending_cell_textures (fence wait)");
                print(f"[UNBUDGETED] single-frame stall: {self.frame_stall_ms} ms "
                      f"(npc_spawn_wall logged, no lever attached)");
            };
        }
    }

    can load_ref with PlacedRef entry {
        if not here.loaded {
            self.spent_ms += here.load_cost_ms;
            here.loaded = True;
            print(f"  loaded ref {here.ref_id} (+{here.load_cost_ms} ms)");
        }
        visit [->:SpawnsNpc:->] else { visit [-->]; };
    }

    can spawn_npc with NpcSpawn entry {
        if not here.spawned {
            self.spent_ms += here.spawn_cost_ms;
            here.spawned = True;
            print(f"  spawned NPC {here.npc_id} (+{here.spawn_cost_ms} ms)");
        }
        visit [-->];
    }
}

walker InteriorCellApplyJob {
    has target_name: str = "";
    has budget_ms: int = 16;
    has spent_ms: int = 0;
    has frame_idx: int = 0;
    has yielded: bool = False;
    has total_ms: int = 0;

    can start with Root entry {
        label = "resume" if self.frame_idx > 0 else "start";
        print(f"[BUDGETED] InteriorCellApplyJob::{label} "
              f"(frame {self.frame_idx}, budget {self.budget_ms} ms)");
        visit [-->];
    }

    can apply with InteriorCell entry {
        if here.name != self.target_name {
            visit [-->];
        } else if here.apply_complete {
            disengage;
        } else {
            visit [->:ContainsRef:->] else {
                if not here.textures_flushed {
                    here.textures_flushed = True;
                    print(f"  flush_pending_cell_textures (fence wait)");
                }
                here.apply_complete = True;
                print(f"[BUDGETED] apply complete across frames — total {self.total_ms} ms");
                disengage;
            };
        }
    }

    can load_ref with PlacedRef entry {
        if not here.loaded {
            need = here.load_cost_ms;
            left = self.budget_ms - self.spent_ms;
            if need > left {
                self.yielded = True;
                print(f"  YIELD before ref {here.ref_id} (need {need} ms, left {left} ms)");
                print(f"  stamp_cell_root_range (transition reclaimable on cancel)");
                disengage;
            }
            self.spent_ms += need;
            self.total_ms += need;
            here.loaded = True;
            print(f"  loaded ref {here.ref_id} (+{need} ms)");
        }
        visit [->:SpawnsNpc:->] else { visit [-->]; };
    }

    can spawn_npc with NpcSpawn entry {
        if not here.spawned {
            need = here.spawn_cost_ms;
            left = self.budget_ms - self.spent_ms;
            if need > left {
                self.yielded = True;
                print(f"  YIELD before NPC {here.npc_id} (need {need} ms, left {left} ms)");
                print(f"  stamp_cell_root_range (transition reclaimable on cancel)");
                disengage;
            }
            self.spent_ms += need;
            self.total_ms += need;
            here.spawned = True;
            print(f"  spawned NPC {here.npc_id} (+{need} ms)");
        }
        visit [-->];
    }
}

with entry {
    stall_cell = InteriorCell(name="M45.1 Bunker");
    stream_cell = InteriorCell(name="Dense Quarters");

    root ++> stall_cell ++> stream_cell;

    stall_cell +>:ContainsRef:+> PlacedRef(ref_id="REFR_A", load_cost_ms=10)
        +>:SpawnsNpc:+> NpcSpawn(npc_id="Guard_01", spawn_cost_ms=8)
        +>:SpawnsNpc:+> NpcSpawn(npc_id="Guard_02", spawn_cost_ms=8)
        ++> PlacedRef(ref_id="REFR_B", load_cost_ms=12)
        +>:SpawnsNpc:+> NpcSpawn(npc_id="Vendor", spawn_cost_ms=6)
        ++> PlacedRef(ref_id="REFR_C", load_cost_ms=9)
        +>:SpawnsNpc:+> NpcSpawn(npc_id="Patrol_03", spawn_cost_ms=7);

    stream_cell +>:ContainsRef:+> PlacedRef(ref_id="SCOL_01", load_cost_ms=8)
        +>:SpawnsNpc:+> NpcSpawn(npc_id="Clerk", spawn_cost_ms=5)
        ++> PlacedRef(ref_id="PKIN_02", load_cost_ms=11)
        +>:SpawnsNpc:+> NpcSpawn(npc_id="Bartender", spawn_cost_ms=6)
        +>:SpawnsNpc:+> NpcSpawn(npc_id="Regular", spawn_cost_ms=5)
        ++> PlacedRef(ref_id="SCOL_03", load_cost_ms=7)
        +>:SpawnsNpc:+> NpcSpawn(npc_id="Drifter", spawn_cost_ms=4);

    root spawn UnbudgetedInteriorLoad(target_name="M45.1 Bunker");

    print("---");

    frame = 0;
    done = False;
    total_tracked = 0;
    while not done {
        job = InteriorCellApplyJob(
            target_name="Dense Quarters",
            budget_ms=16,
            frame_idx=frame
        );
        root spawn job;
        total_tracked = job.total_ms;
        done = not job.yielded;
        frame += 1;
    }

    print(f"budgeted path finished in {frame} frame(s), "
          f"tracked work {total_tracked} ms");
}

"""Pluggable GraphRAG extractors: registry catalog, method resolution, and entity-relation harvest."""

node ExtractorRegistry {
    has name: str = "graphrag";
}

node Document {
    has doc_id: str = "";
    has chunk_preview: str = "";
    has language: str = "English";
    has method: str = "light";
}

node KGExtractor {
    has method_key: str = "";
    has builtin: bool = True;
    has endpoint_url: str = "";
}

node LightKGExtractor(KGExtractor) {
    has method_key: str = "light";
}

node GeneralKGExtractor(KGExtractor) {
    has method_key: str = "general";
}

node NerKGExtractor(KGExtractor) {
    has method_key: str = "ner";
}

node ExternalKGExtractor(KGExtractor) {
    has method_key: str = "external";
    has builtin: bool = False;
    has endpoint_url: str = "http://extractor:8080/extract";
}

node GraphEntity {
    has name: str = "";
    has entity_type: str = "";
}

node GraphRelation {
    has predicate: str = "";
}

edge Registered {
    has method: str = "";
}

edge Yields { }

edge Subject { }

edge Object { }

walker RegistryCatalog {
    has slot_count: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can list_registry with ExtractorRegistry entry {
        print(f"Extractor registry '{here.name}':");
        visit [->:Registered:->] else { disengage; };
    }

    can catalog_slot with KGExtractor entry {
        self.slot_count += 1;
        kind = "builtin" if here.builtin else "external";
        print(f"  register_graphrag_extractor(\"{here.method_key}\", {kind})");
        visit [-->] else { disengage; };
    }
}

walker PipelineOrchestrator {
    has target_method: str = "";
    has entity_count: int = 0;
    has relation_count: int = 0;
    has visited_names: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can process_doc with Document entry {
        self.target_method = here.method;
        print(f"GraphRAG doc={here.doc_id} method={here.method} lang={here.language}");
        visit [-->];
    }

    can resolve_registry with ExtractorRegistry entry {
        visit [->:Registered:->] else { disengage; };
    }

    can resolve_extractor with LightKGExtractor | GeneralKGExtractor | NerKGExtractor | ExternalKGExtractor entry {
        if here.method_key == self.target_method {
            kind = "builtin" if here.builtin else "external";
            detail = here.method_key if here.builtin else here.endpoint_url;
            print(f"  resolved {kind} extractor -> {detail}");
            visit [->:Yields:->] else {
                print("  extractor yielded no entities");
                disengage;
            };
        } else {
            visit [-->] else { disengage; };
        }
    }

    can collect_entity with GraphEntity entry {
        if here.name in self.visited_names {
            print(f"  [cycle-guard] skip {here.name}");
            disengage;
        }
        self.visited_names.append(here.name);
        self.entity_count += 1;
        print(f"  entity: {here.name} <{here.entity_type}>");
        visit [->:Subject:->] else {
            visit [-->] else { disengage; };
        };
    }

    can read_relation with GraphRelation entry {
        self.relation_count += 1;
        print(f"    relation: {here.predicate}");
        visit [->:Object:->] else { disengage; };
    }
}

with entry {
    registry = ExtractorRegistry(name="graphrag");
    light = LightKGExtractor();
    general = GeneralKGExtractor();
    ner = NerKGExtractor();
    external = ExternalKGExtractor();

    registry +>:Registered(method="light"):+> light;
    registry +>:Registered(method="general"):+> general;
