"""Pluggable GraphRAG extractors: registry catalog, method resolution, and entity-relation harvest."""

node ExtractorRegistry {
    has name: str = "graphrag";
}

node Document {
    has doc_id: str = "";
    has chunk_preview: str = "";
    has language: str = "English";
    has extractor_method: str = "light";
}

node KGExtractor {
    has method_key: str = "";
    has builtin: bool = True;
    has endpoint_url: str = "";
}

node LightKGExtractor(KGExtractor) {
    has method_key: str = "light";
}

node GeneralKGExtractor(KGExtractor) {
    has method_key: str = "general";
}

node NerKGExtractor(KGExtractor) {
    has method_key: str = "ner";
}

node ExternalKGExtractor(KGExtractor) {
    has method_key: str = "external";
    has builtin: bool = False;
    has endpoint_url: str = "http://extractor:8080/extract";
}

node GraphEntity {
    has name: str = "";
    has entity_type: str = "";
}

node GraphRelation {
    has predicate: str = "";
}

edge RegistrySlot {
    has slot_key: str = "";
}

edge Yields { }

edge RelSubject { }

edge RelTarget { }

walker RegistryCatalog {
    has slot_count: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can list_registry with ExtractorRegistry entry {
        print(f"Extractor registry '{here.name}':");
        visit [->:RegistrySlot:->] else { disengage; };
    }

    can catalog_slot with KGExtractor entry {
        self.slot_count += 1;
        kind = "builtin" if here.builtin else "external";
        print(f"  register_graphrag_extractor(\"{here.method_key}\", {kind})");
        visit [-->] else { disengage; };
    }
}

walker PipelineOrchestrator {
    has target_method: str = "";
    has entity_count: int = 0;
    has relation_count: int = 0;
    has visited_names: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can process_doc with Document entry {
        self.target_method = here.extractor_method;
        print(f"GraphRAG doc={here.doc_id} method={here.extractor_method} lang={here.language}");
        visit [-->];
    }

    can resolve_registry with ExtractorRegistry entry {
        visit [->:RegistrySlot:->] else { disengage; };
    }

    can resolve_extractor with LightKGExtractor | GeneralKGExtractor | NerKGExtractor | ExternalKGExtractor entry {
        if here.method_key == self.target_method {
            kind = "builtin" if here.builtin else "external";
            detail = here.method_key if here.builtin else here.endpoint_url;
            print(f"  resolved {kind} extractor -> {detail}");
            visit [->:Yields:->] else {
                print("  extractor yielded no entities");
                disengage;
            };
        } else {
            visit [-->] else { disengage; };
        }
    }

    can collect_entity with GraphEntity entry {
        if here.name in self.visited_names {
            print(f"  [cycle-guard] skip {here.name}");
            disengage;
        }
        self.visited_names.append(here.name);
        self.entity_count += 1;
        print(f"  entity: {here.name} <{here.entity_type}>");
        visit [->:RelSubject:->] else {
            visit [-->] else { disengage; };
        };
    }

    can read_relation with GraphRelation entry {
        self.relation_count += 1;
        print(f"    relation: {here.predicate}");
        visit [->:RelTarget:->] else { disengage; };
    }
}

