"""System-wide onboarding blueprint DAG: validate acyclic dependencies and emit topological order."""

node SystemBlueprint {
    has title: str = "System Onboarding Blueprint";
    has version: int = 1;
    has year: int = 0;
    has available: bool = True;
    has status: str = "ACTIVE";
}

node SystemBlueprintStep {
    has title: str = "";
    has step_id: str = "";
    has year: int = 0;
    has available: bool = True;
    has description: str = "";
    has position: int = 0;
    has audience: str = "";
    has requirement: str = "";
}

edge DependsOn { }

edge InBlueprint { }

walker DagValidator {
    has stack: list[str] = [];
    has finished: list[str] = [];
    has is_dag: bool = True;
    has cycle_step: str = "";

    can start with Root entry {
        print(f"Validating blueprint v{self.blueprint_version} ({self.blueprint_status})");
        visit [-->[?:SystemBlueprintStep]] else {
            if self.is_dag {
                print("ACCEPT: dependency graph is a valid DAG");
            }
            disengage;
        }
    }

    can probe with SystemBlueprintStep entry {
        if here.step_id in self.finished {
            visit [-->];
            return;
        }
        if here.step_id in self.stack {
            self.is_dag = False;
            self.cycle_step = here.step_id;
            print(f"REJECT 400: cycle involves step {here.step_id}");
            disengage;
        }
        self.stack.append(here.step_id);
        visit [->:DependsOn:->];
        trimmed = [];
        for sid in self.stack {
            if sid != here.step_id {
                trimmed.append(sid);
            }
        }
        self.stack = trimmed;
        self.finished.append(here.step_id);
        visit [-->];
    }

    has blueprint_version: int = 1;
    has blueprint_status: str = "ACTIVE";
}

walker TopoOrderer {
    has order: list[str] = [];
    has visited: list[str] = [];

    can start with Root entry {
        print("Computing topological onboarding order");
        visit [-->[?:SystemBlueprintStep]] else {
            idx = 0;
            for sid in self.order {
                idx += 1;
                print(f"  {idx}. {sid}");
            }
            disengage;
        }
    }

    can sort with SystemBlueprintStep entry {
        if here.step_id in self.visited {
            visit [-->];
            return;
        }
        self.visited.append(here.step_id);
        visit [->:DependsOn:->];
        self.order.append(here.step_id);
        visit [-->];
    }
}

walker BlueprintAuditor {
    has retired: bool = False;

    can start with Root entry {
        visit [-->[?:SystemBlueprint]] else { disengage; }
    }

    can audit with SystemBlueprint entry {
        status_label = "ARCHIVED" if self.retired else here.status;
        avail_label = "retired" if self.retired else "active";
        print(
            f"Blueprint '{here.title}' v{here.version} "
            f"status={status_label} ({avail_label})"
        );
        visit [-->[?:SystemBlueprintStep]] else { disengage; }
    }

    can inspect with SystemBlueprintStep entry {
        req = here.requirement if here.requirement else "none";
        print(
            f"  [{here.step_id}] {here.title} "
            f"(pos={here.position}, audience={here.audience}, req={req})"
        );
        visit [-->];
    }
}

