"""Interior cell reference load: resumable cursor stepped under streaming budget.

Models issue #3671 — the interior path still calls load_references with an
unlimited FrameTimeBudget while exterior/persistent cells already advance
load_references_budgeted under STREAMING_APPLY_BUDGET (16 ms per frame).
"""

edge ContainsRef {
}

edge SpawnsNpc {
}

node InteriorCell {
    has name: str = "";
    has textures_flushed: bool = False;
    has apply_complete: bool = False;
}

node PlacedRef {
    has ref_id: str = "";
    has load_cost_ms: int = 0;
    has loaded: bool = False;
}

node NpcSpawn {
    has npc_id: str = "";
    has spawn_cost_ms: int = 0;
    has spawned: bool = False;
}

walker UnbudgetedInteriorLoad {
    has target_name: str = "";
    has budget_ms: int = 2147483647;
    has spent_ms: int = 0;
    has frame_stall_ms: int = 0;

    can start with Root entry {
        print("[UNBUDGETED] load_references — FrameTimeBudget::unlimited()");
        visit [-->];
    }

    can apply with InteriorCell entry {
        if here.name != self.target_name {
            visit [-->];
        } else {
            print(f"  interior transition into {here.name}");
            visit [->:ContainsRef:->] else {
                here.textures_flushed = True;
                here.apply_complete = True;
                self.frame_stall_ms = self.spent_ms;
                print(f"  flush_pending_cell_textures (fence wait)");
                print(f"[UNBUDGETED] single-frame stall: {self.frame_stall_ms} ms "
                      f"(npc_spawn_wall logged, no lever attached)");
            };
        }
    }

    can load_ref with PlacedRef entry {
        if not here.loaded {
            self.spent_ms += here.load_cost_ms;
            here.loaded = True;
            print(f"  loaded ref {here.ref_id} (+{here.load_cost_ms} ms)");
        }
        visit [->:SpawnsNpc:->] else { visit [-->]; };
    }

    can spawn_npc with NpcSpawn entry {
        if not here.spawned {
            self.spent_ms += here.spawn_cost_ms;
            here.spawned = True;
            print(f"  spawned NPC {here.npc_id} (+{here.spawn_cost_ms} ms)");
        }
        visit [-->];
    }
}

walker InteriorCellApplyJob {
    has target_name: str = "";
    has budget_ms: int = 16;
    has spent_ms: int = 0;
    has frame_idx: int = 0;
    has yielded: bool = False;
    has total_ms: int = 0;

    can start with Root entry {
        label = "resume" if self.frame_idx > 0 else "start";
        print(f"[BUDGETED] InteriorCellApplyJob::{label} "
              f"(frame {self.frame_idx}, budget {self.budget_ms} ms)");
        visit [-->];
    }

    can apply with InteriorCell entry {
        if here.name != self.target_name {
            visit [-->];
        } else {
            if here.apply_complete {
                disengage;
            } else {
                visit [->:ContainsRef:->] else {
                    if not here.textures_flushed {
                        here.textures_flushed = True;
                        print(f"  flush_pending_cell_textures (fence wait)");
                    }
                    here.apply_complete = True;
                    print(f"[BUDGETED] apply complete across frames — total {self.total_ms} ms");
                    disengage;
                };
            }
        }
    }

    can load_ref with PlacedRef entry {
        if not here.loaded {
            need = here.load_cost_ms;
            left = self.budget_ms - self.spent_ms;
            if need > left {
                self.yielded = True;
                print(f"  YIELD before ref {here.ref_id} (need {need} ms, left {left} ms)");
                print(f"  stamp_cell_root_range (transition reclaimable on cancel)");
                disengage;
            }
            self.spent_ms += need;
            self.total_ms += need;
            here.loaded = True;
            print(f"  loaded ref {here.ref_id} (+{need} ms)");
        }
        visit [->:SpawnsNpc:->] else { visit [-->]; };
    }

    can spawn_npc with NpcSpawn entry {
        if not here.spawned {
            need = here.spawn_cost_ms;
            left = self.budget_ms - self.spent_ms;
            if need > left {
                self.yielded = True;
                print(f"  YIELD before NPC {here.npc_id} (need {need} ms, left {left} ms)");
                print(f"  stamp_cell_root_range (transition reclaimable on cancel)");
                disengage;
            }
            self.spent_ms += need;
            self.total_ms += need;
            here.spawned = True;
            print(f"  spawned NPC {here.npc_id} (+{need} ms)");
        }
        visit [-->];
    }
}

with entry {
    stall_cell = InteriorCell(name="M45.1 Bunker");
    stream_cell = InteriorCell(name="Dense Quarters");

    root ++> stall_cell ++> stream_cell;

    refr_a = PlacedRef(ref_id="REFR_A", load_cost_ms=10);
    guard_01 = NpcSpawn(npc_id="Guard_01", spawn_cost_ms=8);
