    refr_b = PlacedRef(ref_id="REFR_B", load_cost_ms=12);
    vendor = NpcSpawn(npc_id="Vendor", spawn_cost_ms=6);
    refr_c = PlacedRef(ref_id="REFR_C", load_cost_ms=9);
    patrol_03 = NpcSpawn(npc_id="Patrol_03", spawn_cost_ms=7);

    stall_cell +>:ContainsRef:+> refr_a;
    refr_a +>:SpawnsNpc:+> guard_01;
    guard_01 ++> guard_02;
    guard_02 ++> refr_b;
    refr_b +>:SpawnsNpc:+> vendor;
    vendor ++> refr_c;
    refr_c +>:SpawnsNpc:+> patrol_03;

    scol_01 = PlacedRef(ref_id="SCOL_01", load_cost_ms=8);
    clerk = NpcSpawn(npc_id="Clerk", spawn_cost_ms=5);
    pkin_02 = PlacedRef(ref_id="PKIN_02", load_cost_ms=11);
