"""Pluggable GraphRAG extractors: registry catalog, method resolution, and entity-relation harvest."""

edge RegistrySlot {
    has slot_key: str = "";
}

edge Yields { }

edge RelSubject { }

edge RelTarget { }

node ExtractorRegistry {
    has name: str = "graphrag";
}

node Document {
    has doc_id: str = "";
    has chunk_preview: str = "";
    has language: str = "English";
    has extractor_method: str = "light";
}

node KGExtractor {
    has method_key: str = "";
    has builtin: bool = True;
    has endpoint_url: str = "";
}

node LightKGExtractor(KGExtractor) {
    has method_key: str = "light";
}

node GeneralKGExtractor(KGExtractor) {
    has method_key: str = "general";
}

node NerKGExtractor(KGExtractor) {
    has method_key: str = "ner";
}

node ExternalKGExtractor(KGExtractor) {
    has method_key: str = "external";
    has builtin: bool = False;
    has endpoint_url: str = "http://extractor:8080/extract";
}

node GraphEntity {
    has name: str = "";
    has entity_type: str = "";
}

node GraphRelation {
    has predicate: str = "";
}

walker RegistryCatalog {
    has slot_count: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can list_registry with ExtractorRegistry entry {
        print(f"Extractor registry '{here.name}':");
        visit [->:RegistrySlot:->] else { disengage; };
    }

    can catalog_slot with LightKGExtractor | GeneralKGExtractor | NerKGExtractor | ExternalKGExtractor entry {
        self.slot_count += 1;
        kind = "builtin" if here.builtin else "external";
        print(f"  register_graphrag_extractor(\"{here.method_key}\", {kind})");
        visit [->:RegistrySlot:->] else { disengage; };
    }
}

walker PipelineOrchestrator {
    has target_method: str = "";
    has entity_count: int = 0;
    has relation_count: int = 0;
    has visited_names: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can process_doc with Document entry {
        self.target_method = here.extractor_method;
        print(f"GraphRAG doc={here.doc_id} method={here.extractor_method} lang={here.language}");
        visit [-->];
    }

    can resolve_registry with ExtractorRegistry entry {
        visit [->:RegistrySlot:->] else { disengage; };
    }

    can resolve_extractor with LightKGExtractor | GeneralKGExtractor | NerKGExtractor | ExternalKGExtractor entry {
        if here.method_key != self.target_method {
            disengage;
        }
        kind = "builtin" if here.builtin else "external";
        detail = here.method_key if here.builtin else here.endpoint_url;
        print(f"  resolved {kind} extractor -> {detail}");
        visit [->:Yields:->] else {
            print("  extractor yielded no entities");
            disengage;
        };
    }

    can collect_entity with GraphEntity entry {
        if here.name in self.visited_names {
            print(f"  [cycle-guard] skip {here.name}");
            disengage;
        }
        self.visited_names.append(here.name);
        self.entity_count += 1;
        print(f"  entity: {here.name} <{here.entity_type}>");
        visit [->:RelSubject:->] else { disengage; };
    }

    can read_relation with GraphRelation entry {
        self.relation_count += 1;
        print(f"    relation: {here.predicate}");
        visit [->:RelTarget:->] else { disengage; };
    }
}

with entry {
    registry = ExtractorRegistry(name="graphrag");
    light = LightKGExtractor();
    general = GeneralKGExtractor();
    ner = NerKGExtractor();
    external = ExternalKGExtractor();

    registry +>:RegistrySlot(slot_key="light"):+> light;
    registry +>:RegistrySlot(slot_key="general"):+> general;
    registry +>:RegistrySlot(slot_key="ner"):+> ner;
    registry +>:RegistrySlot(slot_key="external"):+> external;

    doc = Document(
        doc_id="repo-001",
        chunk_preview="class OrdersService { void sync() { ... } }",
        language="English",
        extractor_method="external"
    );

    pkg = GraphEntity(name="com.acme.orders", entity_type="package");
    svc = GraphEntity(name="OrdersService", entity_type="service");
    tbl = GraphEntity(name="orders_table", entity_type="table");
    contains = GraphRelation(predicate="contains");
    reads = GraphRelation(predicate="reads_from");

    external +>:Yields:+> pkg;
    external +>:Yields:+> svc;
    external +>:Yields:+> tbl;
    pkg +>:RelSubject:+> contains;
    contains +>:RelTarget:+> svc;
    svc +>:RelSubject:+> reads;
    reads +>:RelTarget:+> tbl;

    root ++> registry ++> doc;

    catalog = RegistryCatalog();
    pipeline = PipelineOrchestrator();
    root spawn catalog;
    root spawn pipeline;

    print(f"registered {catalog.slot_count} extractors; "
          f"harvested {pipeline.entity_count} entities and "
          f"{pipeline.relation_count} relations");
}

"""Content-addressed cross-run asset cache: walk a pipeline DAG, explain cache keys, and surface explicit cache hits."""

node Artifact {
    has name: str = "";
    has content_hash: str = "";
    has available: bool = True;
}

node Asset {
    has name: str = "";
    has code_hash: str = "";
    has cache_mode: str = "off";
    has cacheable: bool = False;
    has status: str = "pending";
}

node CacheEntry {
    has cache_key: str = "";
    has manifest: str = "";
    has output_hash: str = "";
    has expired: bool = False;
    has reuse_count: int = 0;
}

node CacheStore {
    has namespace: str = "project";
    has scope: str = "project";
}

edge DependsOn { }
edge Produces { }
edge ReadsInput { }
edge StoredIn { }
edge CachedFor { }

walker CachePlanner {
    has namespace: str = "project";
    has upstream_hash: str = "";
    has hits: int = 0;
    has misses: int = 0;
    has visited: list[str] = [];
    has lookup_key: str = "";
    has input_buf: str = "";
    has gathering: bool = False;
    has found_hit: bool = False;

    can start with Root entry {
        print("Planning pipeline with content-addressed cache...");
        visit [-->];
    }

    can note_store with CacheStore entry {
        self.namespace = here.namespace;
        visit [-->];
    }

    can gather with Artifact entry {
        if self.gathering and here.available {
            chunk = here.content_hash;
            merged = f"{self.input_buf},{chunk}" if self.input_buf else chunk;
            self.input_buf = merged;
        }
    }

    can plan with Asset entry {
        if here.name in self.visited {
            print(f"[ERROR] cycle detected at asset '{here.name}'");
            disengage;
        }
        self.visited.append(here.name);

        self.input_buf = "";
        self.gathering = True;
        visit [<-:ReadsInput:<-];
        self.gathering = False;

        inputs = self.input_buf if self.input_buf else self.upstream_hash;
        blank = "";
        inputs = inputs if inputs else "sha256:root";

        manifest = f"asset={here.name};code={here.code_hash};inputs=[{inputs}]";
        key = f"{self.namespace}:{here.name}:{here.code_hash}:{inputs}";

        if not here.cacheable or here.cache_mode == "off" {
            status_out = "EXECUTE";
            here.status = "executed";
            self.misses += 1;
            print(f"[{status_out}] {here.name} (cache disabled)");
            print(f"  manifest: {manifest}");
            fresh = f"sha256:{here.name}-live";
            self.upstream_hash = fresh;
            visit [->:DependsOn:->] else { visit [-->]; };
        } else {
            self.lookup_key = key;
            self.found_hit = False;
            visit [<-:CachedFor:<-] else { self.found_hit = False; };

            if self.found_hit {
                here.status = "cached";
                self.hits += 1;
                status_out = "CACHED";
                print(f"[{status_out}] {here.name} — reused prior successful result");
                print(f"  key: {key}");
                print(f"  manifest: {manifest}");
            } else {
                here.status = "executed";
                self.misses += 1;
                status_out = "EXECUTE";
                print(f"[{status_out}] {here.name} (cache miss — inputs or code changed)");
                print(f"  key: {key}");
                print(f"  manifest: {manifest}");
                fresh = f"sha256:{here.name}-live";
                self.upstream_hash = fresh;
            }
            visit [->:DependsOn:->] else { visit [-->]; };
        }
    }

    can probe_hit with CacheEntry entry {
        if here.cache_key == self.lookup_key and not here.expired {
            self.found_hit = True;
            here.reuse_count += 1;
            self.upstream_hash = here.output_hash;
            print(f"  reuse count: {here.reuse_count}, stored manifest: {here.manifest}");
        }
    }
}

with entry {
    store = CacheStore(namespace="bruin-project", scope="project");

    raw = Artifact(name="accounts_archive.xml", content_hash="sha256:archive-aaa");
    parsed = Artifact(name="parsed_accounts", content_hash="sha256:parsed-bbb");

    parse_xml = Asset(
        name="parse_xml",
        code_hash="impl-v3",
        cache_mode="read_write",
        cacheable=True
    );
    embeddings = Asset(
        name="embeddings",
        code_hash="model-v2",
        cache_mode="read_write",
        cacheable=True
    );
    train_model = Asset(
        name="train_model",
        code_hash="trainer-v1",
        cache_mode="read_write",
