    );

    prior_parse = CacheEntry(
        cache_key="bruin-project:parse_xml:impl-v3:sha256:archive-aaa",
        manifest="asset=parse_xml;code=impl-v3;inputs=[sha256:archive-aaa]",
        output_hash="sha256:parsed-bbb",
        reuse_count=2
    );
    prior_embed = CacheEntry(
        cache_key="bruin-project:embeddings:model-v2:sha256:parsed-bbb",
        manifest="asset=embeddings;code=model-v2;inputs=[sha256:parsed-bbb]",
