    );

    root ++> store;
    store +>:StoredIn:+> prior_parse;
    store +>:StoredIn:+> prior_embed;

    root ++> parse_xml ++> embeddings ++> train_model;

    raw +>:ReadsInput:+> parse_xml;
    parse_xml +>:Produces:+> parsed;
    parsed +>:ReadsInput:+> embeddings;
    embeddings +>:DependsOn:+> parse_xml;
    train_model +>:DependsOn:+> embeddings;

    prior_parse +>:CachedFor:+> parse_xml;
    prior_embed +>:CachedFor:+> embeddings;

    planner = CachePlanner(namespace="bruin-project");
    root spawn planner;

    print(f"summary: {planner.hits} cache hits, {planner.misses} executed — "
          f"unchanged upstream assets skipped explicitly");
}

