"""Task blocking: condition-key store queries return silently empty while graph traversal finds dependents."""

node Task {
    has task_id: int = 0;
    has title: str = "";
}

node BlockLink {
    has link_id: int = 0;
    has reason: str = "";
}

edge BlockerRef { }
edge BlockedRef { }

walker DriverKeyQuery {
    has driver: str = "postgres";
    has blocker_task_id: int = 1;
    has hits: int = 0;

    can start with Root entry {
        driver_label = "postgres" if self.driver == "postgres" else "json";
        key_name = "blocker_id" if self.driver == "postgres" else "blocker";
        print(f"=== findAll(task-block, {{{key_name}: {self.blocker_task_id}}}) [{driver_label}] ===");
        visit [-->] else { disengage; }
    }

    can scan with BlockLink entry {
        key_name = "blocker_id" if self.driver == "postgres" else "blocker";
        print(f"  record #{here.link_id}: no scalar field '{key_name}' on BlockLink -> skip");
        visit [-->];
    }

    can done with Root exit {
        empty_msg = "[] (silent empty — reads as 'nothing is blocked')";
        print(f"  result: {empty_msg}\n");
    }
}

walker BlockTraversal {
    has blocker_task_id: int = 1;
    has found: int = 0;

    can start with Root entry {
        print(f"=== traverse blocks for task {self.blocker_task_id} (idiomatic path) ===");
        visit [-->[?:Task]] else { disengage; }
    }

    can from_blocker with Task entry {
        if here.task_id == self.blocker_task_id {
            visit [<--:BlockerRef:--] else { visit [-->]; }
        } else {
            visit [-->];
        }
    }

    can via_link with BlockLink entry {
        print(f"  link #{here.link_id}: {here.reason}");
        visit [->:BlockedRef:->] else { visit [-->]; }
    }

    can show_blocked with Task entry {
        print(f"    blocks -> {here.title} (task {here.task_id})");
        self.found += 1;
    }
}

with entry {
    deploy = Task(task_id=1, title="Deploy");
    qa = Task(task_id=2, title="QA signoff");
    release = Task(task_id=3, title="Release");

    link_qa = BlockLink(link_id=10, reason="QA incomplete");
    link_qa +>:BlockerRef:+> deploy;
    link_qa +>:BlockedRef:+> qa;

    link_rel = BlockLink(link_id=11, reason="deploy gate");
    link_rel +>:BlockerRef:+> deploy;
    link_rel +>:BlockedRef:+> release;

    root ++> deploy ++> qa ++> release;
    root ++> link_qa ++> link_rel;

    root spawn DriverKeyQuery(driver="postgres", blocker_task_id=1);
    root spawn DriverKeyQuery(driver="json", blocker_task_id=1);
    traversal = BlockTraversal(blocker_task_id=1);
    root spawn traversal;
