"""Task blocking: condition-key store queries return silently empty while graph traversal finds dependents."""

node Task {
    has task_id: int = 0;
    has title: str = "";
}

node BlockLink {
    has link_id: int = 0;
    has reason: str = "";
}

edge BlockerRef { }
edge BlockedRef { }

walker DriverKeyQuery {
    has driver: str = "postgres";
    has blocker_task_id: int = 1;

    can start with Root entry {
        driver_label = "postgres" if self.driver == "postgres" else "json";
        key_name = "blocker_id" if self.driver == "postgres" else "blocker";
        print(f"=== findAll(task-block, {{{key_name}: {self.blocker_task_id}}}) [{driver_label}] ===");
        visit [-->];
    }

    can scan with BlockLink entry {
        key_name = "blocker_id" if self.driver == "postgres" else "blocker";
        print(f"  record #{here.link_id}: no scalar field '{key_name}' on BlockLink -> skip");
        visit [-->];
    }

    can finish with Root exit {
        empty_msg = "[] (silent empty — reads as 'nothing is blocked')";
        print(f"  result: {empty_msg}\n");
    }
}

walker BlockTraversal {
    has found: int = 0;
    has seek_blocker: bool = True;

    can on_task with Task entry {
        if self.seek_blocker {
            print(f"=== traverse blocks for task {here.task_id} (idiomatic path) ===");
            self.seek_blocker = False;
            visit [<-:BlockerRef:<-] else { disengage; };
        } else {
            print(f"    blocks -> {here.title} (task {here.task_id})");
            self.found += 1;
        }
    }

    can via_link with BlockLink entry {
        print(f"  link #{here.link_id}: {here.reason}");
        visit [->:BlockedRef:->];
    }
}

