node Issue {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has number: int = 0;
    has accessible: bool = True;

    def normalized_title() -> str {
        lowered = here.title.lower();
        return lowered;
    }
}

node ExactSignal {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has evidence: str = "";
}

node NearSignal {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has evidence: str = "";
    has sufficient: bool = False;
}

node LabelSignal {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has evidence: str = "";
}

edge HasSignal { }
edge CandidateOf { }
edge DuplicateOf { }
edge ExplicitCanonical { }

walker CandidateAnalyzer {
    has subject_number: int = 0;
    has subject_year: int = 0;
    has phase: str = "";
    has pending_bucket: str = "";
    has likely_duplicate: list[int] = [];
    has likely_dup_years: list[int] = [];
    has likely_related: list[int] = [];
    has uncertain: list[int] = [];
    has canonical_number: int = 0;
    has skip_reason: str = "";

    can begin with Issue entry {
        if self.phase != "" {
            disengage;
        }
        if here.number != self.subject_number {
            disengage;
        }
        if not here.accessible or not here.available {
            disengage;
        }
        self.phase = "explicit";
        visit [->:ExplicitCanonical:->];
        self.phase = "signals";
        visit [->:HasSignal:->];
        self.phase = "done";
        finalize_canonical();
    }

    can honor_explicit with Issue entry {
        if self.phase != "explicit" {
            disengage;
        }
        if not here.available or not here.accessible {
            self.skip_reason = "revalidation";
            disengage;
        }
        self.canonical_number = here.number;
        disengage;
    }

    can tally_exact with ExactSignal entry {
        self.pending_bucket = "duplicate";
        visit [->:CandidateOf:->];
    }

    can tally_near with NearSignal entry {
        bucket = "uncertain";
        if here.sufficient {
            bucket = "duplicate";
        }
        self.pending_bucket = bucket;
        visit [->:CandidateOf:->];
    }

    can tally_label with LabelSignal entry {
        self.pending_bucket = "related";
        visit [->:CandidateOf:->];
    }

    can record with Issue entry {
        if self.phase != "signals" {
            disengage;
        }
        if self.pending_bucket == "" {
            disengage;
        }
        if here.number == self.subject_number {
            self.pending_bucket = "";
            disengage;
        }
        if not here.accessible or not here.available {
            self.pending_bucket = "";
            disengage;
        }
        if self.pending_bucket == "duplicate" {
            self.likely_duplicate.append(here.number);
            self.likely_dup_years.append(here.year);
        } elif self.pending_bucket == "related" {
            self.likely_related.append(here.number);
        } else {
            self.uncertain.append(here.number);
        }
        self.pending_bucket = "";
        disengage;
    }

    def finalize_canonical() {
        if self.skip_reason != "" {
            return;
        }
        if self.canonical_number != 0 {
            return;
        }
        if len(self.likely_duplicate) == 0 {
            return;
        }
        best_num = self.subject_number;
        best_year = self.subject_year;
        for (i, cand_num) in enumerate(self.likely_duplicate) {
            cand_year = self.likely_dup_years[i];
            if cand_year < best_year {
                best_year = cand_year;
                best_num = cand_num;
            } elif cand_year == best_year and cand_num < best_num {
                best_num = cand_num;
            }
        }
        self.canonical_number = best_num;
    }
}

walker CycleGuard {
    has trail: list[int] = [];
    has origin: int = 0;
    has alerts: list[str] = [];

    can traverse with Issue entry {
        if len(self.trail) == 0 {
            self.origin = here.number;
