"""Shared observability and resilience: correlation-id propagation across outbound service hops with circuit-breaker guards."""

node Service {
    has name: str = "";
    has request_count: int = 0;
    has breaker_open: bool = False;
    has failure_count: int = 0;
    has failure_threshold: int = 3;
}

node RequestContext {
    has correlation_id: str = "";
    has trace_id: str = "";
    has outcome: str = "pending";
}

node ObservabilityStarter {
    has module_name: str = "platform-observability";
    has json_logging: bool = True;
}

node ResilienceStarter {
    has module_name: str = "platform-resilience";
    has breaker_threshold: int = 3;
}

edge OutboundCall {
    has timeout_ms: int = 5000;
    has simulated_latency_ms: int = 50;
}

edge InstrumentedBy {
    has version: str = "1.0";
}

edge ProtectedBy {
    has version: str = "1.0";
}

walker CorrelationPipeline {
    has correlation_id: str = "";
    has trace_id: str = "";
    has hops: int = 0;
    has max_hops: int = 8;
    has visited_services: list[str] = [];
    has downstream_errors: int = 0;
    has outcome: str = "ok";

    can start with Root entry {
        visit [-->];
    }

    can ingest with RequestContext entry {
        self.correlation_id = here.correlation_id;
        self.trace_id = here.trace_id;
        here.outcome = "in-flight";
        visit [-->];
    }

    can serve with Service entry {
        if here.name in self.visited_services {
            print(f"[ERROR] cycle detected at {here.name} correlation={self.correlation_id}");
            self.outcome = "cycle";
            disengage;
        }
        if self.hops >= self.max_hops {
            print(f"[ERROR] depth limit at {here.name}");
            self.outcome = "depth_exceeded";
            disengage;
        }
        if here.breaker_open {
            self.downstream_errors += 1;
            self.outcome = "circuit_open";
            print(f"[METRIC] downstream_errors service={here.name} correlation={self.correlation_id}");
            print(f"[LOG] correlationId={self.correlation_id} traceId={self.trace_id} "
                  f"service={here.name} status=CIRCUIT_OPEN");
            disengage;
        }
        self.visited_services.append(here.name);
        self.hops += 1;
        here.request_count += 1;
        print(f"[LOG] correlationId={self.correlation_id} traceId={self.trace_id} "
              f"service={here.name} status=ok request_count={here.request_count}");
        print(f"[METRIC] request_total service={here.name} correlation={self.correlation_id}");
        visit [->:OutboundCall:->] else {
            self.outcome = "complete";
            disengage;
        };
    }
}

walker StarterCatalog {
    has cataloged: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can forward with RequestContext entry {
        visit [-->];
    }

    can inventory with Service entry {
        print(f"[catalog] scanning starters for {here.name}");
        visit [->:InstrumentedBy:->];
        visit [->:ProtectedBy:->];
        visit [-->];
    }

    can record with ObservabilityStarter | ResilienceStarter entry {
        self.cataloged += 1;
        print(f"[catalog] attached {here.module_name}");
        disengage;
    }
}

walker ResilienceProbe {
    has target_name: str = "";
    has trips: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can forward with RequestContext entry {
        visit [-->];
    }

    can stress with Service entry {
        if here.name != self.target_name {
            visit [-->];
        } elif here.breaker_open {
            print(f"[probe] breaker already open on {here.name}");
            disengage;
        } else {
            here.failure_count += 1;
            print(f"[probe] simulated timeout on {here.name} "
                  f"failures={here.failure_count}/{here.failure_threshold}");
            if here.failure_count >= here.failure_threshold {
                here.breaker_open = True;
                self.trips += 1;
                print(f"[METRIC] circuit_breaker_open service={here.name}");
            }
            disengage;
        }
    }

    can skip_starter with ObservabilityStarter | ResilienceStarter entry {
        visit [-->];
    }
}

with entry {
    gateway = Service(name="gateway");
    inventory = Service(name="inventory");
    payment = Service(name="payment", failure_threshold=3);

    obs = ObservabilityStarter();
    res = ResilienceStarter();

    inbound = RequestContext(
        correlation_id="corr-9f3a",
        trace_id="trace-7b2c"
    );

    gateway +>:InstrumentedBy(version="1.0"):+> obs;
    gateway +>:ProtectedBy(version="1.0"):+> res;
    inventory +>:InstrumentedBy(version="1.0"):+> obs;
    inventory +>:ProtectedBy(version="1.0"):+> res;
    payment +>:InstrumentedBy(version="1.0"):+> obs;
    payment +>:ProtectedBy(version="1.0"):+> res;

    root ++> inbound ++> gateway;
    gateway +>:OutboundCall(timeout_ms=3000, simulated_latency_ms=40):+> inventory;
    inventory +>:OutboundCall(timeout_ms=2000, simulated_latency_ms=120):+> payment;

    print("--- starter inventory across services ---");
    catalog = StarterCatalog();
    root spawn catalog;
    print(f"cataloged {catalog.cataloged} starter attachments");

    print("--- happy path: correlation propagates through chain ---");
    flow = CorrelationPipeline();
