    tracker.relaxed_loads = 0;
    root spawn LockOrderProbe(naive_path=False);
}

"""Policy field classification registry: inventory composable pointers, bind merge strategies, and flag unclassified composition targets."""

node PolicyPointer {
    has pointer: str = "";
    has is_present: bool = True;
    has identity_field: str = "";

    def kind_name() -> str {
        return "pointer";
    }
}

node ScalarPointer(PolicyPointer) {
    override def kind_name() -> str {
        return "scalar";
    }
}

node ObjectPointer(PolicyPointer) {
    override def kind_name() -> str {
        return "object";
    }
}

node CollectionPointer(PolicyPointer) {
    override def kind_name() -> str {
        return "collection";
    }
}

node StrategyEntry {
    has entry_id: str = "";
    has pointer_pattern: str = "";
    has classification: str = "";
    has merge_strategy_id: str = "";
    has presence_semantics: str = "missing-inherit";
    has status: str = "active";
}

edge SchemaChild { }
edge BoundStrategy { }
edge ComposesOver { }

walker RegistryAuditor {
    has seen: list[str] = [];
    has issues: list[str] = [];
    has classified: int = 0;
    has unclassified: int = 0;
    has depth: int = 0;
    has max_depth: int = 12;

    can start with Root entry {
        print("Strategy Registry v1 audit — composable pointer inventory");
        visit [->:SchemaChild:->] else {
            visit [->:ComposesOver:->] else { disengage; };
        };
    }

    can compose with ObjectPointer entry {
        print(f"composition overlay: {here.pointer}");
        visit [->:SchemaChild:->] else { disengage; };
    }

    can audit with ScalarPointer | ObjectPointer | CollectionPointer entry {
        if here.pointer in self.seen {
            self.issues.append(f"cycle at {here.pointer}");
            disengage;
        }
        self.seen.append(here.pointer);

        if self.depth >= self.max_depth {
            self.issues.append(f"depth cap at {here.pointer}");
            disengage;
        }
        self.depth += 1;

        kind = here.kind_name();
        present_label = "present" if here.is_present else "absent";
        print(f"auditing [{kind}] {here.pointer} ({present_label})");

        if kind == "collection" {
            if here.identity_field == "" {
                self.issues.append(
                    f"collection {here.pointer} lacks explicit identity field"
                );
            } else {
                print(f"  collection identity keyed by '{here.identity_field}'");
            }
        }

        visit [->:BoundStrategy:->] else {
            self.unclassified += 1;
            msg = f"UNCLASSIFIED: {here.pointer} would receive unsafe generic merge";
            self.issues.append(msg);
            print(f"  !! {msg}");
        };

        if kind == "object" {
            visit [->:SchemaChild:->];
            visit [->:ComposesOver:->];
        }

        self.depth -= 1;
        visit [-->];
    }

    can validate with StrategyEntry entry {
        strategy_note = here.merge_strategy_id;
        if strategy_note == "" {
            strategy_note = "none";
        }
        print(
            f"  -> registry {here.entry_id}: {here.classification} "
            f"merge={strategy_note} presence={here.presence_semantics}"
        );
        self.classified += 1;

        if here.classification == "unsupported-in-composition" {
            self.issues.append(f"unsupported pointer {here.pointer_pattern}");
        }

        if here.classification == "keyed-ordered-collection" {
            if here.merge_strategy_id == "" {
                self.issues.append(
                    f"missing merge strategy for keyed collection {here.pointer_pattern}"
                );
            }
        }

        if here.classification == "object-recursive" {
            if here.merge_strategy_id == "" {
                self.issues.append(
                    f"object-recursive {here.pointer_pattern} requires descendant registry lookup"
                );
            }
        }
    }
}

with entry {
    policy = ObjectPointer(pointer="/policy", is_present=True);
    routes = CollectionPointer(
        pointer="/policy/routes", identity_field="id", is_present=True
    );
    enabled = ScalarPointer(pointer="/policy/enabled", is_present=True);
