"""Compass Hook 6 recovery: audit the construction authorization chain, detect scope collapse, and verify evidence boundaries before publication."""

node AuthorityPacket {
    has title: str = "";
    has scope_breadth: int = 0;
    has status: str = "ACTIVE";
}

node ConstructionCandidate {
    has pr_id: str = "";
    has scope_breadth: int = 0;
    has disposition: str = "PENDING";
}

node EvidenceBoundary {
    has gate_name: str = "";
    has passed: bool = False;
}

node PracticeDomain {
    has name: str = "";
}

node CompassWing {
    has cardinal: str = "";
}

edge Supersedes { }
edge Authorizes { }
edge RequiresEvidence { }
edge AlignsWith { }

walker AuthorityAuditor {
    has strategy_scope: int = 0;
    has scope_violations: int = 0;
    has gates_blocked: int = 0;
    has deltas_recorded: int = 0;

    can start with Root entry {
        print("=== Hook 6 pre-construction authority audit ===");
        visit [-->];
    }

    can audit with AuthorityPacket entry {
        if self.strategy_scope > 0 {
            if here.scope_breadth < self.strategy_scope {
                self.scope_violations += 1;
                print(
                    f"[DELTA] SUPERSEDE stale assumption: "
                    f"scope {self.strategy_scope} -> {here.scope_breadth} "
                    f"at {here.title}"
                );
            } else {
                if here.scope_breadth != self.strategy_scope {
                    self.deltas_recorded += 1;
                    print(f"[DELTA] succession recorded at {here.title}");
                }
            }
        }
        if here.scope_breadth > 0 {
            self.strategy_scope = here.scope_breadth;
        }
        print(f"[AUTH] {here.title} breadth={here.scope_breadth} status={here.status}");
        visit [->:Supersedes:->];
        visit [->:Authorizes:->];
        visit [->:RequiresEvidence:->];
    }

    can inspect with ConstructionCandidate entry {
        if here.scope_breadth < self.strategy_scope {
            self.scope_violations += 1;
            verdict = "SCOPE_COLLAPSE";
        } else {
            verdict = "SCOPE_OK";
        }
        print(
            f"[BUILD] PR#{here.pr_id} {verdict} "
            f"disposition={here.disposition} breadth={here.scope_breadth}"
        );
    }

    can qualify with EvidenceBoundary entry {
        gate_status = "PASS" if here.passed else "BLOCK";
        print(f"[GATE] {here.gate_name}: {gate_status}");
        if not here.passed {
            self.gates_blocked += 1;
        }
    }

    can reconcile with CompassWing entry {
        print(f"[WING] {here.cardinal}");
        visit [->:AlignsWith:->];
        visit [-->];
    }

    can map with PracticeDomain entry {
        print(f"  aligns -> {here.name}");
    }
}

