"""Lily SDK errors: model error chains as nodes and walk causes for JSON and toString serialization."""

node LilySdkError {
    has uid: str = "";
    has name: str = "LilySdkError";
    has message: str = "";
    has code: str = "";
    has status_code: int = 0;
    has details: str = "";
}

node LilyApiError(LilySdkError) {
    has name: str = "LilyApiError";
}

edge CausedBy { }

walker JsonSerializer {
    has seen_uids: list[str] = [];
    has current_child_json: str = "null";
    has report: str = "";

    can start with Root entry {
        visit [-->];
    }

    can descend with LilySdkError entry {
        if here.uid in self.seen_uids {
            disengage;
        }
        self.seen_uids.append(here.uid);
        self.current_child_json = "null";
        visit [->:CausedBy:->] else { };
    }

    can ascend with LilySdkError exit {
        cause_json = self.current_child_json;
        code_json = f'"{here.code}"';
        details_json = f'"{here.details}"';
        status_json = str(here.status_code);
        fragment = f'{{"name":"{here.name}","message":"{here.message}","code":{code_json},"statusCode":{status_json},"details":{details_json},"cause":{cause_json}}}';
        self.current_child_json = fragment;
        self.report = fragment;
    }
}

walker ErrorStringifier {
    has seen_uids: list[str] = [];
    has report: str = "";

    can start with Root entry {
        visit [-->];
    }

    can walk with LilySdkError entry {
        if here.uid in self.seen_uids {
            disengage;
        }
        self.seen_uids.append(here.uid);
        visit [->:CausedBy:->] else { };
    }

    can narrate with LilySdkError exit {
        code_suffix = "";
        if here.code != "" {
            code_suffix = f" [{here.code}]";
        }
        status_suffix = "";
        if here.status_code != 0 {
            status_suffix = f" (status {here.status_code})";
        }
        piece = f"{here.name}:{code_suffix}{status_suffix} {here.message}";
        if self.report == "" {
            self.report = piece;
        } else {
            self.report = f"{piece} caused by {self.report}";
        }
    }
}

