    inventory +>:ProtectedBy:+> res;
    payment +>:InstrumentedBy:+> obs;
    payment +>:ProtectedBy:+> res;

    root ++> inbound ++> gateway;
    gateway +>:OutboundCall:+> inventory;
    inventory +>:OutboundCall:+> payment;

    print("--- starter inventory across services ---");
    catalog = StarterCatalog();
    root spawn catalog;
    print(f"cataloged {catalog.cataloged} starter attachments");

    print("--- happy path: correlation propagates through chain ---");
    flow = CorrelationPipeline();
    root spawn flow;
    print(f"flow outcome={flow.outcome} hops={flow.hops}");

    print("--- resilience probe: trip payment circuit breaker ---");
    root spawn ResilienceProbe(target_name="payment");
    root spawn ResilienceProbe(target_name="payment");
    root spawn ResilienceProbe(target_name="payment");

    print("--- post-trip: outbound call blocked by open breaker ---");
    blocked = CorrelationPipeline();
    root spawn blocked;
    print(f"blocked outcome={blocked.outcome} downstream_errors={blocked.downstream_errors}");
}

