"""ExecWitness CLI: recursively discover trace files under directories and analyze valid traces."""

node FsEntry {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has name: str = "";
    has path: str = "";

    def label() -> str {
        return f"{self.path}/{self.name}";
    }

    def classify_line() -> str {
        return f"[UNKNOWN] {self.label()}";
    }

    def classify_bucket() -> str {
        return "";
    }
}

node Directory(FsEntry) {
    has discover_order: int = 0;
}

node TraceFile(FsEntry) {
    has event_count: int = 0;
    has format_version: str = "1.0";

    override def classify_line() -> str {
        return f"[TRACE] {self.label()} ({self.event_count} events, format v{self.format_version})";
    }

    override def classify_bucket() -> str {
        return "discovered";
    }
}

node UnsupportedFile(FsEntry) {
    has reason: str = "";

    override def classify_line() -> str {
        return f"[SKIP] {self.label()}: {self.reason}";
    }

    override def classify_bucket() -> str {
        return "skipped";
    }
}

node MalformedTrace(FsEntry) {
    has error_msg: str = "";

    override def classify_line() -> str {
        return f"[PARSE_FAIL] {self.label()}: {self.error_msg}";
    }

    override def classify_bucket() -> str {
        return "failed";
    }
}

edge Contains { }

walker TraceDiscoverer {
    has discovered: list[str] = [];
    has skipped: list[str] = [];
    has failed: list[str] = [];
    has visit_stack: list[str] = [];

    can start with Root entry {
        print("execwitness-cli v0.1.0");
        print("Scanning input path...");
        visit [->:Contains:->] else { disengage; };
        print(f"Discovery complete: {len(self.discovered)} traces, "
              f"{len(self.skipped)} skipped, {len(self.failed)} parse failures");
    }

    can scan with Directory entry {
        key = f"{here.path}/{here.name}";
        if key in self.visit_stack {
            print(f"[ERROR] cycle detected at {key}");
            disengage;
        }
        self.visit_stack.append(key);
        print(f"[DISCOVER] {key}/ (order={here.discover_order})");
        visit [->:Contains:->] else { };
        popped = self.visit_stack.pop();
    }

    can classify with TraceFile | UnsupportedFile | MalformedTrace entry {
        line = here.classify_line();
        print(line);
        bucket = here.classify_bucket();
        if bucket == "discovered" {
            self.discovered.append(here.label());
        } elif bucket == "skipped" {
            self.skipped.append(here.label());
        } elif bucket == "failed" {
            self.failed.append(here.label());
        }
        visit [->:Contains:->] else { };
    }
}

walker TraceAnalyzer {
    has analyzed_count: int = 0;
    has pass_count: int = 0;

    can start with Root entry {
        print("Analyzing discovered traces...");
        visit [->:Contains:->] else { disengage; };
        print(f"Analysis complete: {self.pass_count}/{self.analyzed_count} traces passed");
    }

    can descend with Directory entry {
        visit [->:Contains:->] else { };
