"""Bound search indexing and trash summarization on large trees.

Models bounded tree walks with depth and entry budgets, cycle detection,
cancellation, and partial results for adversarial tree structures.
"""

node TreeEntry {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has size_bytes: int = 0;
    has in_trash: bool = False;
}

node Folder(TreeEntry) { }

node File(TreeEntry) { }

edge Child { }

walker TrashSummarizer {
    has depth_budget: int = 100;
    has entry_budget: int = 1000;
    has current_depth: int = 0;
    has entries_walked: int = 0;
    has trash_count: int = 0;
    has trash_bytes: int = 0;
    has cancelled: bool = False;
    has partial: bool = False;
    has visited_keys: list[str] = [];

    can start with Root entry {
        print(f"Trash summarization (depth_budget={self.depth_budget}, "
              f"entry_budget={self.entry_budget})");
        visit [-->] else { disengage; }
    }

    can summarize with Folder | File entry {
        if self.cancelled {
            visit [-->] else { disengage; }
        } elif self.entries_walked >= self.entry_budget {
            self.partial = True;
            self.cancelled = True;
            visit [-->] else { disengage; }
        } else {
            key = here.title;
            if key in self.visited_keys {
                print(f"[CYCLE] re-visit blocked at {key}");
                visit [-->] else { disengage; }
            } else {
                self.visited_keys += [key];
                self.entries_walked += 1;
                if here.in_trash {
                    self.trash_count += 1;
                    self.trash_bytes += here.size_bytes;
                }
                flag = "TRASH" if here.in_trash else "live";
                print(f"  [{self.current_depth}] {here.title} ({flag})");
                if self.current_depth >= self.depth_budget {
                    self.partial = True;
                } else {
                    self.current_depth += 1;
                    visit [->:Child:->] else { disengage; }
                }
                visit [-->] else { disengage; }
            }
        }
    }
}

walker SearchIndexer {
    has entry_budget: int = 1000;
    has indexed_count: int = 0;
    has index_titles: list[str] = [];
    has cancelled: bool = False;
    has partial: bool = False;
    has visited_keys: list[str] = [];

    can start with Root entry {
        print(f"Search indexing (entry_budget={self.entry_budget})");
        visit [-->] else { disengage; }
    }

    can index with Folder | File entry {
        if self.cancelled {
            visit [-->] else { disengage; }
        } elif self.indexed_count >= self.entry_budget {
            self.partial = True;
            self.cancelled = True;
            visit [-->] else { disengage; }
        } else {
            key = here.title;
            if key in self.visited_keys {
                visit [-->] else { disengage; }
            } else {
                self.visited_keys += [key];
                if here.available {
                    self.index_titles += [here.title];
                    self.indexed_count += 1;
                }
                if self.indexed_count >= self.entry_budget {
                    self.partial = True;
                    self.cancelled = True;
                } else {
                    visit [->:Child:->] else { disengage; }
                }
                visit [-->] else { disengage; }
            }
        }
    }
}

