"""Task comment threading: legacy id backfill, reply-cycle sanitization, depth-bounded log render."""

node Task {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

node Comment {
    has id: str = "";
    has text: str = "";
    has author: str = "";
    has reply_to: str = "";
    has excluded: bool = False;
}

edge OnTask { }
edge HasReply { }
edge ReplyRef { }

walker LegacyInferer {
    has prior_id: str = "";
    has prior_author: str = "";
    has verdict: str = "ok";

    can start with Root entry {
        visit [-->];
    }

    can on_task with Task entry {
        visit [->:OnTask:->];
    }

    can scan with Comment entry {
        if self.prior_author != "" and here.author == self.prior_author and self.prior_id == "" {
            self.verdict = "reply_to=null (legacy parent lacked id)";
        }
        if here.id != "" {
            self.prior_id = here.id;
        } else {
            self.prior_id = "";
        }
        self.prior_author = here.author;
        visit [-->];
    }
}

walker IdBackfiller {
    has seq: int = 1;

    can start with Root entry {
        visit [-->];
    }

    can on_task with Task entry {
        visit [->:OnTask:->];
    }

    can fill with Comment entry {
        if here.id == "" {
            here.id = f"c{self.seq}";
            self.seq += 1;
            print(f"backfilled {here.id} for {here.author}");
        }
        visit [-->];
    }
}

walker ReplyLinker {
    has phase: str = "scan";
    has want_parent: str = "";
    has want_child: Comment;
    has linked: bool = False;

    can start with Root entry {
        visit [-->];
    }

    can on_task with Task entry {
        self.phase = "scan";
        visit [->:OnTask:->];
    }

    can on_comment with Comment entry {
        if self.phase == "scan" {
            if here.reply_to != "" {
                self.want_parent = here.reply_to;
                self.want_child = here;
                self.linked = False;
                self.phase = "match";
                visit [->:OnTask:->];
                self.phase = "scan";
            }
            visit [-->];
        } else {
            if !self.linked and here.id == self.want_parent {
                here +>:HasReply:+> self.want_child;
                self.want_child +>:ReplyRef:+> here;
                self.linked = True;
            }
            visit [-->];
        }
    }
}

walker CycleSanitizer {
    has stack: list[str] = [];
    has cycle_hits: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can on_task with Task entry {
        visit [->:OnTask:->];
    }

    can probe with Comment entry {
        if here.excluded {
            visit [-->];
        } elif here.reply_to == "" {
            visit [-->];
        } else {
            self.stack = [];
            self.cycle_hits = [];
            visit [->:ReplyRef:->] else {
                visit [-->];
            };
        }
    }

    can climb with Comment entry {
        cid = here.id;
        if cid in self.stack {
            for sid in self.stack {
                if sid not in self.cycle_hits {
                    self.cycle_hits.append(sid);
                }
            }
            if cid not in self.cycle_hits {
                self.cycle_hits.append(cid);
            }
            for hid in self.cycle_hits {
                print(f"cycle excludes comment {hid}");
            }
            disengage;
        }
        self.stack.append(cid);
        visit [->:ReplyRef:->] else {
            self.stack = [];
            disengage;
        };
    }
}

walker CycleMarker {
    has doomed: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can on_task with Task entry {
        visit [->:OnTask:->];
    }

    can mark with Comment entry {
        if here.id in self.doomed {
            here.excluded = True;
        }
        visit [-->];
    }
}

walker CommentLog {
    has max_depth: int = 3;
    has depth: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can on_task with Task entry {
        print(f"--- log: {here.title} ---");
        visit [->:OnTask:->];
    }

    can show with Comment entry {
        if here.excluded {
            visit [-->];
        } elif here.reply_to != "" {
            visit [-->];
        } else {
            self.depth = 0;
            pad = "";
            i = 0;
            while i < self.depth {
                pad += "  ";
                i += 1;
            }
            print(f"{pad}{here.author}: {here.text}");
            visit [->:HasReply:->] else {
                visit [-->];
            };
        }
    }

    can show_reply with Comment entry {
        if here.excluded {
            visit [-->];
        } else {
            next_depth = self.depth + 1;
            if next_depth > self.max_depth {
                pad = "";
                i = 0;
                while i < self.max_depth {
                    pad += "  ";
                    i += 1;
                }
                print(f"{pad}... (depth cap)");
                visit [-->];
            } else {
                self.depth = next_depth;
                pad = "";
                j = 0;
                while j < self.depth {
                    pad += "  ";
                    j += 1;
                }
                print(f"{pad}{here.author}: {here.text}");
                visit [->:HasReply:->] else {
                    visit [-->];
                };
            }
        }
    }
}

with entry {
    threading = Task(title="Deploy auth service");
    root +>:OnTask:+> threading;
    threading +>:OnTask:+> Comment(text="Shipped v1", author="Alex");
    threading +>:OnTask:+> Comment(text="Nice work", author="Alex");
    threading +>:OnTask:+> Comment(text="Thanks!", author="Alex", reply_to="c1");
    threading +>:OnTask:+> Comment(text="On it", author="Alex", reply_to="c2");
    threading +>:OnTask:+> Comment(text="LGTM", author="Alex", reply_to="c3");
    threading +>:OnTask:+> Comment(text="Merged", author="Alex", reply_to="c4");
    threading +>:OnTask:+> Comment(text="Done", author="Alex", reply_to="c5");

    infer = LegacyInferer();
    root spawn infer;
    print(infer.verdict);

    root spawn IdBackfiller();
    root spawn ReplyLinker();

    root spawn CommentLog(max_depth=3);

    corrupt = Task(title="Imported board");
