"""Grove checkpoint: audit production frontend dependencies and remediate vulnerable packages."""

node GroveFrontend {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has name: str = "";
    has checkpoint: str = "";
}

node NpmPackage {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has name: str = "";
    has version: str = "";
    has is_production: bool = True;
    has patched: bool = False;

    def bump_to(fixed_version: str) -> bool {
        if fixed_version == "" or not self.is_production {
            return False;
        }
        self.version = fixed_version;
        self.patched = True;
        return True;
    }
}

node SecurityAdvisory {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has advisory_id: str = "";
    has severity: str = "";
    has fixed_version: str = "";
}

edge DependsOn {
    has is_direct: bool = True;
}

edge HasFinding { }

walker ProductionAuditor {
    has blocking: int = 0;
    has seen: list[str] = [];

    can start with Root entry {
        print("=== Grove production-only npm audit ===");
        visit [-->];
        verdict = "PASS" if self.blocking == 0 else "FAIL";
        print(f"Audit {verdict}: {self.blocking} high/moderate production finding(s)");
    }

    can scan_app with GroveFrontend entry {
        print(f"Scanning {here.name} for checkpoint {here.checkpoint}");
        visit [->:DependsOn:->] else { disengage; };
    }

    can scan_pkg with NpmPackage entry {
        if here.name in self.seen {
            disengage;
        }
        self.seen.append(here.name);
        scope = "prod" if here.is_production else "dev";
        print(f"  dep [{scope}] {here.name}@{here.version}");
        if here.is_production and not here.patched {
            visit [->:HasFinding:->];
        }
        visit [->:DependsOn:->] else { disengage; };
    }

    can tally with SecurityAdvisory entry {
        sev = here.severity;
        if sev == "high" or sev == "moderate" {
            self.blocking += 1;
            print(f"    [{sev.upper()}] {here.advisory_id}: {here.title}");
        }
    }
}

walker DependencyRemediator {
    has fixes: int = 0;
    has target: NpmPackage | None = None;

    can start with Root entry {
        print("=== Applying upstream dependency fixes ===");
        visit [-->];
        print(f"Applied {self.fixes} production update(s)");
    }

    can enter_app with GroveFrontend entry {
        visit [->:DependsOn:->] else { disengage; };
    }

    can upgrade_pkg with NpmPackage entry {
        self.target = here;
        if here.is_production and not here.patched {
            visit [->:HasFinding:->];
        }
        self.target = None;
        visit [->:DependsOn:->] else { disengage; };
    }

    can apply_fix with SecurityAdvisory entry {
        pkg = self.target;
        if pkg is not None and pkg.is_production and here.fixed_version != "" {
            old_ver = pkg.version;
            if pkg.bump_to(here.fixed_version) {
                self.fixes += 1;
                print(f"  {pkg.name}: {old_ver} -> {here.fixed_version} ({here.advisory_id})");
            }
        }
    }
}

