"""CI release gates: dependency-ordered scheduling and browser-state matrix traversal."""

node ReleaseGate {
    has name: str = "";
    has layer: str = "build";
    has gate_id: int = 0;
    has passed: bool = False;
}

node BrowserProject {
    has name: str = "";
    has engine: str = "";
}

node TestState {
    has name: str = "";
    has theme: str = "light";
}

edge DependsOn { }
edge RunsOn { has tier: int = 1; }
edge RequiresState { }

walker GateScheduler {
    has schedule: list[str] = [];
    has visiting: list[int] = [];
    has visited: list[int] = [];
    has cycle_detected: bool = False;

    can start with Root entry {
        print("=== Resolving release-gate dependency order ===");
        visit [-->[?:ReleaseGate]] else { disengage; }
    }

    can resolve with ReleaseGate entry {
        if here.gate_id in self.visiting {
            self.cycle_detected = True;
            print(f"[CYCLE] blocked at gate {here.name} (id {here.gate_id})");
            disengage;
        }
        if here.gate_id in self.visited {
            disengage;
        }
        self.visiting.append(here.gate_id);
        visit [->:DependsOn:->] else { }
        popped = self.visiting.pop();
        self.visited.append(here.gate_id);
        self.schedule.append(here.name);
        print(f"[ORDER] {here.layer}: {here.name}");
    }
}

walker MatrixRunner {
    has runs: int = 0;
    has current_gate: str = "";

    can start with Root entry {
        print("=== Executing browser x state matrix per gate ===");
        visit [-->[?:ReleaseGate]] else { disengage; }
    }

    can run_gate with ReleaseGate entry {
        self.current_gate = here.name;
        print(f"[GATE] {here.layer} :: {here.name}");
        visit [->:RunsOn:->] else {
            print(f"  (no browser targets for {here.name})");
        }
        visit [->:RequiresState:->] else {
            label = f"{self.current_gate} (default state)";
            print(f"    -> {label}");
            self.runs += 1;
        }
    }

    can run_browser with BrowserProject entry {
        print(f"  browser: {here.name} ({here.engine})");
        self.runs += 1;
    }

    can apply_state with TestState entry {
        combo = f"{self.current_gate} | {here.name} | {here.theme}";
        print(f"    state: {here.name} ({here.theme}) -> {combo}");
        self.runs += 1;
    }
}

