    threading +>:OnTask:+> Comment(text="Done", author="Alex", reply_to="c5");

    infer = LegacyInferer();
    root spawn infer;
    print(infer.verdict);

    root spawn IdBackfiller();
    root spawn ReplyLinker();

    root spawn CommentLog(max_depth=3);

    corrupt = Task(title="Imported board");
    root +>:OnTask:+> corrupt;
    corrupt +>:OnTask:+> (a := Comment(id="A", text="alpha", author="Sam", reply_to="B"));
    corrupt +>:OnTask:+> (b := Comment(id="B", text="beta", author="Sam", reply_to="A"));
    a +>:ReplyRef:+> b;
    b +>:ReplyRef:+> a;

    sanitizer = CycleSanitizer();
    root spawn sanitizer;
    marker = CycleMarker(doomed=sanitizer.cycle_hits);
    root spawn marker;

    root spawn CommentLog(max_depth=3);
}

