"""Dependency-cruiser no-cycles audit: model CLI and sync-engine import graphs and detect circular dependency groups."""

node Module {
    has path: str = "";
    has export_count: int = 0;
}

edge Imports {
    has type_only: bool = False;
}

walker DependencyCruiser {
    has violations: int = 0;
    has trail: list[str] = [];

    can start with Root entry {
        print("dependency-cruiser: 251 modules, scanning import edges for cycles");
        visit [-->];
    }

    can audit with Module entry {
        module_path = here.path;
        if module_path in self.trail {
            cycle_start = 0;
            for (i, prior) in enumerate(self.trail) {
                if prior == module_path {
                    cycle_start = i;
                    break;
                }
            }
            cycle_chain = [];
            for (j, prior) in enumerate(self.trail) {
                if j >= cycle_start {
                    cycle_chain.append(prior);
                }
            }
            cycle_chain.append(module_path);
            chain = " -> ".join(cycle_chain);
            print(f"info no-cycles: {chain}");
            self.violations += 1;
            disengage;
        }
        self.trail.append(module_path);
        visit [->:Imports:->] else { disengage; };
        self.trail.pop();
    }
}

