"""Task comment threading: legacy id backfill, reply-cycle sanitization, depth-bounded log render."""

node Task {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

node Comment {
    has id: str = "";
    has text: str = "";
    has author: str = "";
    has reply_to: str = "";
    has excluded: bool = False;
}

edge OnTask { }
edge HasReply { }
edge ReplyRef { }

walker LegacyInferer {
    has prior_id: str = "";
    has prior_author: str = "";
    has verdict: str = "ok";

    can start with Root entry {
        visit [-->];
    }

    can on_task with Task entry {
        visit [->:OnTask:->];
    }

    can scan with Comment entry {
        if self.prior_author != "" and here.author == self.prior_author and self.prior_id == "" {
            self.verdict = "reply_to=null (legacy parent lacked id)";
        }
        if here.id != "" {
            self.prior_id = here.id;
        } else {
            self.prior_id = "";
        }
        self.prior_author = here.author;
        visit [-->];
    }
}

walker IdBackfiller {
    has seq: int = 1;

    can start with Root entry {
        visit [-->];
    }

    can on_task with Task entry {
        visit [->:OnTask:->];
    }

    can fill with Comment entry {
        if here.id == "" {
            here.id = f"c{self.seq}";
            self.seq += 1;
            print(f"backfilled {here.id} for {here.author}");
        }
        visit [-->];
    }
}

walker ReplyLinker {
    has phase: str = "scan";
    has want_parent: str = "";
    has want_child: Comment | None = None;
    has linked: bool = False;
    has skip_task_reset: bool = False;

    can start with Root entry {
        visit [-->];
    }

    can on_task with Task entry {
        if not self.skip_task_reset {
            self.phase = "scan";
        }
        self.skip_task_reset = False;
        visit [->:OnTask:->];
    }

    can on_comment with Comment entry {
        if self.phase == "scan" {
            if here.reply_to != "" {
                self.want_parent = here.reply_to;
                self.want_child = here;
                self.linked = False;
                self.phase = "match";
                self.skip_task_reset = True;
                visit [<-:OnTask:<-];
                self.phase = "scan";
            }
            visit [-->];
        } else {
            if not self.linked and here.id == self.want_parent and self.want_child is not None {
                here +>:HasReply:+> self.want_child;
                self.want_child +>:ReplyRef:+> here;
                self.linked = True;
            }
            visit [-->];
        }
    }
}

walker CycleSanitizer {
    has stack: list[str] = [];
    has cycle_hits: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can on_task with Task entry {
        visit [->:OnTask:->];
    }

    can probe with Comment entry {
        if here.excluded {
            visit [-->];
        } elif here.reply_to == "" {
            visit [-->];
        } else {
            self.stack = [];
            self.cycle_hits = [];
            visit [->:ReplyRef:->] else {
                visit [-->];
            };
        }
    }

    can climb with Comment entry {
        cid = here.id;
        if cid in self.stack {
            for sid in self.stack {
                if sid not in self.cycle_hits {
                    self.cycle_hits.append(sid);
                }
            }
            if cid not in self.cycle_hits {
                self.cycle_hits.append(cid);
            }
            for hid in self.cycle_hits {
                print(f"cycle excludes comment {hid}");
            }
            disengage;
        }
        self.stack.append(cid);
        visit [->:ReplyRef:->] else {
            self.stack = [];
            disengage;
        };
    }
}

walker CycleMarker {
    has doomed: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can on_task with Task entry {
        visit [->:OnTask:->];
    }

    can mark with Comment entry {
        if here.id in self.doomed {
            here.excluded = True;
        }
        visit [-->];
    }
}

walker CommentLog {
    has max_depth: int = 3;
    has depth: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can on_task with Task entry {
        print(f"--- log: {here.title} ---");
        visit [->:OnTask:->];
    }

    can render with Comment entry {
        if here.excluded {
            visit [-->];
        } elif here.reply_to != "" and self.depth == 0 {
            visit [-->];
        } else {
            pad = self.make_indent(self.depth);
            print(f"{pad}{here.author}: {here.text}");
            next_depth = self.depth + 1;
            if next_depth > self.max_depth {
                cap_pad = self.make_indent(self.max_depth);
                print(f"{cap_pad}... (depth cap)");
                visit [-->];
            } else {
                saved_depth = self.depth;
                self.depth = next_depth;
                visit [->:HasReply:->] else {
                    self.depth = saved_depth;
                };
                self.depth = saved_depth;
                visit [-->];
            }
        }
    }

    def make_indent(level: int) -> str {
        spaces = "";
        i = 0;
        while i < level {
            spaces += "  ";
            i += 1;
        }
        return spaces;
    }
}

