"""Connect n ontology entities: metric-closure MST Steiner heuristic over typed links."""

node OntologyEntity {
    has label: str = "";
    has uri: str = "";
    has kind: str = "";
}

node Concept(OntologyEntity) {
    has kind: str = "concept";
}

node Property(OntologyEntity) {
    has kind: str = "property";
}

node Class(OntologyEntity) {
    has kind: str = "class";
}

edge SubClassOf {
}

edge RelatedTo {
    has weight: int = 1;
}

walker BoundedPath {
    has goal_label: str = "";
    has hop_cap: int = 1;
    has path_labels: list[str] = [];
    has found: bool = False;
    has seen: list[OntologyEntity] = [];

    def follow_links() {
        visit [->:RelatedTo:->] else {
            visit [->:SubClassOf:->] else {
                visit [<-:RelatedTo:<-] else {
                    visit [<-:SubClassOf:<-] else {
                        disengage;
                    };
                };
            };
        };
    }

    can seek with OntologyEntity entry {
        self.path_labels = [here.label];
        if here.label == self.goal_label {
            self.found = True;
            disengage;
        }
        self.follow_links();
    }

    can extend with Concept | Property | Class entry {
        if self.found {
            disengage;
        }
        for s in self.seen {
            if s is here {
                disengage;
            }
        }
        self.seen.append(here);
        next_path = self.path_labels + [here.label];
        self.path_labels = next_path;
        if here.label == self.goal_label {
            self.found = True;
            disengage;
        }
        edge_count = len(next_path) - 1;
        if edge_count >= self.hop_cap {
            disengage;
        }
        self.follow_links();
    }
}

walker CycleGuard {
    has seen: list[OntologyEntity] = [];
    has hops: int = 0;
    has max_hops: int = 16;

    def follow_links() {
        visit [->:RelatedTo:->] else {
            visit [->:SubClassOf:->] else {
                disengage;
            };
        };
    }

    can start with Root entry {
        print("Auditing ontology reachability (cycle-guarded):");
        self.follow_links();
    }

    can audit with Concept | Property | Class entry {
        for s in self.seen {
            if s is here {
                print(f"  CYCLE blocked at {here.label}");
                disengage;
            }
        }
        self.seen.append(here);
        print(f"  hop {self.hops}: {here.label} [{here.kind}]");
        self.hops += 1;
        if self.hops >= self.max_hops {
            disengage;
        }
        self.follow_links();
    }
}

walker SteinerLinker {
    has pick_nodes: list[OntologyEntity] = [];
    has dist_rows: list[list[int]] = [];
    has path_rows: list[list[list[str]]] = [];
    has mst_lines: list[str] = [];
    has expanded: list[str] = [];

    def shortest_hops(origin: OntologyEntity, dest_label: str) -> int {
        cap = 1;
        while cap <= 12 {
            probe = BoundedPath(goal_label=dest_label, hop_cap=cap);
            origin spawn probe;
            if probe.found {
                return len(probe.path_labels) - 1;
            }
            cap += 1;
        }
        return 999999;
    }

    def shortest_path(origin: OntologyEntity, dest_label: str) -> list[str] {
        cap = 1;
        while cap <= 12 {
            probe = BoundedPath(goal_label=dest_label, hop_cap=cap);
            origin spawn probe;
            if probe.found {
                return probe.path_labels;
            }
            cap += 1;
        }
        return [];
    }

    def cache_closure() {
        n = len(self.pick_nodes);
        self.dist_rows = [];
        self.path_rows = [];
        for _i in range(n) {
            self.dist_rows.append([]);
            self.path_rows.append([]);
        }
        for i in range(n) {
            for j in range(n) {
                if i == j {
                    self.dist_rows[i].append(0);
                    self.path_rows[i].append([self.pick_nodes[i].label]);
                } else {
                    origin = self.pick_nodes[i];
                    dest = self.pick_nodes[j].label;
                    path = self.shortest_path(origin, dest);
                    dist = 999999;
                    if len(path) > 0 {
                        dist = len(path) - 1;
                    }
                    self.dist_rows[i].append(dist);
                    self.path_rows[i].append(path);
                }
            }
        }
    }

    def run_prim() {
        n = len(self.pick_nodes);
        if n < 2 {
            return;
        }
        in_tree = [];
        for _k in range(n) {
            in_tree.append(False);
        }
        in_tree[0] = True;
        self.mst_lines = [];
        added = 1;
        while added < n {
            best_i = -1;
            best_j = -1;
            best_d = 999999;
            for i in range(n) {
                if in_tree[i] == False {
                    continue;
                }
                for j in range(n) {
                    if in_tree[j] == True {
                        continue;
                    }
                    d = self.dist_rows[i][j];
                    if d < best_d {
                        best_d = d;
                        best_i = i;
                        best_j = j;
                    }
                }
            }
            if best_j < 0 {
                break;
            }
            in_tree[best_j] = True;
            added += 1;
            a = self.pick_nodes[best_i].label;
            b = self.pick_nodes[best_j].label;
            line = f"{a} --({best_d} hops)-- {b}";
            self.mst_lines.append(line);
        }
    }

    def expand_tree() {
        n = len(self.pick_nodes);
        if n < 2 {
            return;
        }
        in_tree = [];
        for _k in range(n) {
            in_tree.append(False);
        }
        in_tree[0] = True;
        self.expanded = [];
        added = 1;
        while added < n {
            best_i = -1;
            best_j = -1;
            best_d = 999999;
            for i in range(n) {
                if in_tree[i] == False {
                    continue;
                }
                for j in range(n) {
                    if in_tree[j] == True {
                        continue;
                    }
                    d = self.dist_rows[i][j];
                    if d < best_d {
                        best_d = d;
                        best_i = i;
                        best_j = j;
                    }
                }
            }
            if best_j < 0 {
                break;
            }
            in_tree[best_j] = True;
            added += 1;
            path = self.path_rows[best_i][best_j];
            chain = " -> ".join(path);
            self.expanded.append(chain);
        }
    }

    def follow_links() {
        visit [->:RelatedTo:->] else {
            visit [->:SubClassOf:->] else {
                disengage;
            };
        };
    }

    can start with Root entry {
        n = len(self.pick_nodes);
        print(f"Connecting {n} ontology entities (Steiner heuristic):");
        for nd in self.pick_nodes {
            print(f"  pick: {nd.label} ({nd.kind})");
        }
        self.cache_closure();
        print("Metric closure (pairwise hop distances):");
        for i in range(n) {
            row_parts = [];
            for j in range(n) {
                d = self.dist_rows[i][j];
                row_parts.append(str(d));
            }
            row_text = ", ".join(row_parts);
            print(f"  {self.pick_nodes[i].label}: [{row_text}]");
        }
        self.run_prim();
        print("MST over closure (within 2x optimal Steiner bound):");
        for line in self.mst_lines {
            print(f"  {line}");
        }
        self.expand_tree();
        print("Expanded underlying paths:");
        for chain in self.expanded {
            print(f"  {chain}");
        }
        self.follow_links();
    }
}

