walker StampGrouper {
    has window_sec: int = 8;
    has min_size: int = 4;
    has anchor_stamp: int = -1;
    has in_window: int = 0;
    has mixed_cycles: bool = False;
    has first_cycle: str = "";

    can start with Root entry {
        visit [-->];
    }

    can sweep with Employer entry {
        print(f"== stamp-window grouping for {here.name} ==");
        self.anchor_stamp = -1;
        self.in_window = 0;
        self.mixed_cycles = False;
        self.first_cycle = "";
        visit [<-:WorksAt:<-] else { disengage; };
    }

    can count with Role entry {
        if self.anchor_stamp < 0 {
            self.anchor_stamp = here.visible_at;
        }
        delta = here.visible_at - self.anchor_stamp;
        if delta <= self.window_sec {
            self.in_window += 1;
            cycle = f"{here.lifecycle}/{here.season}";
            if self.first_cycle == "" {
                self.first_cycle = cycle;
            } elif cycle != self.first_cycle {
                self.mixed_cycles = True;
            }
        }
    }
}

walker EvidenceGrouper {
    has max_card_size: int = 3;
    has cards_built: int = 0;
    has bucket: str = "";
    has bucket_size: int = 0;
    has active_card: GroupCard | None = None;

    can start with Root entry {
        visit [-->];
    }

    can at_employer with Employer entry {
        print(f"== evidence-based grouping for {here.name} ==");
        self.bucket = "";
        self.bucket_size = 0;
        self.active_card = None;
        visit [<-:WorksAt:<-] else { disengage; };
    }

    can place with Role entry {
        if not here.release_evidence {
            print(f"  SKIP {here.title}: baseline/backfill timestamp only");
            disengage;
        }
        key = f"{here.lifecycle}|{here.season}";
        if self.bucket != "" and key != self.bucket {
            print(f"  SPLIT incompatible cycle {key} vs {self.bucket}");
            self.bucket = key;
            self.bucket_size = 0;
            self.active_card = None;
        }
        if self.bucket == "" {
            self.bucket = key;
        }
        if self.active_card is None {
            card = GroupCard(
                kind="employer-release",
                label=f"{here.name}:{key}#{self.cards_built}",
                size=0
            );
            root ++> card;
            self.active_card = card;
            self.cards_built += 1;
            print(f"  NEW card {card.label}");
        } elif self.bucket_size >= self.max_card_size {
            card = GroupCard(
                kind="employer-release",
                label=f"{here.name}:{key}#{self.cards_built}",
                size=0
            );
            root ++> card;
            self.active_card = card;
            self.cards_built += 1;
            self.bucket_size = 0;
            print(f"  SPLIT size cap -> {card.label}");
        }
        here +>:InCard:+> self.active_card;
        self.active_card.size += 1;
        self.bucket_size += 1;
        print(f"  + {here.title} ({here.discipline})");
    }
}

