    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has module_path: str = "";
    has is_doctor_render: bool = False;
}

node AsyncRoutine {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has symbol: str = "";
    has depth: int = 0;
}

edge Runs { }
edge Spawns { }
edge TailCalls { }

walker LibSuiteAuditor {
    has stack_ceiling: int = 6;
    has passed: int = 0;
    has stall_count: int = 0;
    has segfault: bool = False;
    has frames_walked: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can load_crate with EEArtifact entry {
        self.stack_ceiling = here.thread_stack_kb // 340;
        print(
            f"crate={here.crate_name} tag={here.release_tag} "
            f"thread_stack_kb={here.thread_stack_kb} ceiling={self.stack_ceiling}"
        );
        visit [->:Runs:->] else { disengage; }
    }

    can run_test with LibTest entry {
        if here.is_doctor_render {
            self.stall_count += 1;
            print(f"STALL {here.module_path}::{here.title}");
            visit [->:Spawns:->] else { visit [->:Runs:->] else { disengage; } }
        } else {
            if here.available {
                self.passed += 1;
                print(f"ok {here.module_path}::{here.title}");
            }
            visit [->:Runs:->] else { disengage; }
        }
    }

    can unwind_async with AsyncRoutine entry {
        self.frames_walked += 1;
        print(f"  frame depth={here.depth} {here.symbol}");
        if here.depth >= self.stack_ceiling {
            self.segfault = True;
            print(
                f"SIGSEGV signal=11 depth={here.depth} "
                f"ceiling={self.stack_ceiling} frames={self.frames_walked}"
            );
            disengage;
        }
        visit [->:TailCalls:->] else { disengage; }
    }
}

