"""GDP disjunct semantics: OR, select_one, and truth_xor over overlapping feasible sets."""

node GDPModel {
    has name: str = "";
    has semantics: str = "or";
    has primal_x: float = 0.0;
}

node Disjunct {
    has label: str = "";

    def holds_at(x: float) -> bool {
        return False;
    }
}

node LeDisjunct(Disjunct) {
    has bound: float = 1.0;

    override def holds_at(x: float) -> bool {
        return x <= self.bound;
    }
}

node GeDisjunct(Disjunct) {
    has bound: float = 0.0;

    override def holds_at(x: float) -> bool {
        return x >= self.bound;
    }
}

node ReformStage {
    has stage_name: str = "";
    has preserves_semantics: bool = True;
}

edge InModel { }
edge NextStage { }

walker SemanticsAuditor {
    has primal_x: float = 0.0;
    has mode: str = "or";
    has true_labels: list[str] = [];
    has false_labels: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can begin with GDPModel entry {
        self.primal_x = here.primal_x;
        self.mode = here.semantics;
        self.true_labels = [];
        self.false_labels = [];
        visit [->:InModel:->];
    }

    can evaluate with Disjunct entry {
        if here.holds_at(self.primal_x) {
            self.true_labels += [here.label];
        } else {
            self.false_labels += [here.label];
        }
    }

    can conclude with GDPModel exit {
        n_true = len(self.true_labels);
        feasible = False;
        if self.mode == "or" {
            feasible = n_true >= 1;
        } elif self.mode == "select_one" {
            feasible = n_true >= 1;
        } else {
            feasible = n_true == 1;
        }
        status = "FEASIBLE" if feasible else "INFEASIBLE";
        truths = ", ".join(self.true_labels) if self.true_labels else "(none)";
        print(f"[{self.mode}] x={self.primal_x} on {here.name}: {status} (true: {truths})");
    }
}

walker ReformulationWalker {
    has path: list[str] = [];
    has visited: list[str] = [];

    can traverse with ReformStage entry {
        if here.stage_name in self.visited {
            print(f"CYCLE at reform stage '{here.stage_name}' — disengaging");
            disengage;
        }
        self.visited += [here.stage_name];
        tag = "semantic" if here.preserves_semantics else "lowered";
        self.path += [f"{here.stage_name}({tag})"];
        visit [->:NextStage:->] else { disengage; };
    }

    can finish with ReformStage exit {
        chain = " -> ".join(self.path);
        print(f"reformulation path: {chain}");
    }
}

with entry {
    print("=== Overlap: x=0.5 in S1={x<=1} AND S2={x>=0} ===");
    modes = ["or", "select_one", "truth_xor"];
    for mode in modes {
        m = GDPModel(name="overlap", semantics=mode, primal_x=0.5);
        root ++> m;
        m +>:InModel:+> LeDisjunct(label="S1:x<=1", bound=1.0);
        m +>:InModel:+> GeDisjunct(label="S2:x>=0", bound=0.0);
    }
    root spawn SemanticsAuditor();

    print("=== Reformulation pipeline: complementarity -> GDP -> continuous NLP ===");
    comp = ReformStage(stage_name="complementarity", preserves_semantics=False);
    gdp = ReformStage(stage_name="gdp_disjunction", preserves_semantics=True);
    nlp = ReformStage(stage_name="continuous_nlp", preserves_semantics=False);
    root ++> comp +>:NextStage:+> gdp +>:NextStage:+> nlp;
    comp spawn ReformulationWalker();
}

"""GR bootstrap startup probe races full-cluster-crash recovery.

Models Percona operator issue #1467: bootstrap calls exit(1) on transient
no-peer states during full-cluster-crash recovery. With startupProbe
failureThreshold=1 and no crash-marker bypass on startup, the probe kills
the clone donor mid-recovery and the operator loops on crash detection.
"""

node Cluster {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has crash_detected: bool = False;
    has recovery_active: bool = False;
    has readiness_bypass: bool = False;
    has startup_bypass: bool = False;
}

node MySQLPod {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has role: str = "secondary";
    has alive: bool = True;
    has peers_reachable: bool = False;
    has clone_pct: int = 0;
    has killed_by_probe: bool = False;
}

node RecoveryMarker {
    has title: str = "full-cluster-crash";
    has year: int = 0;
    has available: bool = True;
    has covers_readiness: bool = True;
    has covers_startup: bool = False;
}

edge MemberOf { }
edge CloneFrom { has pct: int = 0; }
edge MarkerOn { }
edge PeerLink { }

walker CrashRecovery {
    has cycle: int = 0;
    has max_cycles: int = 3;
    has donor_killed: bool = False;

    can start with Root entry {
        visit [-->];
    }

    can reboot with Cluster entry {
        if not here.crash_detected {
            disengage;
        }
        if self.cycle >= self.max_cycles {
            print(f"Recovery halted after {self.cycle} cycles (demo cap)");
            disengage;
        }
        self.cycle += 1;
        here.recovery_active = True;
        here.readiness_bypass = True;
        here.startup_bypass = False;
        print(f"Cycle {self.cycle}: rebootClusterFromCompleteOutage on {here.title}");
        visit [->:MemberOf:->];
    }

    can stage_pod with MySQLPod entry {
        if not here.alive {
            visit [-->] else { disengage; };
        } else {
            here.peers_reachable = False;
            here.clone_pct = 0;
            role_label = "primary" if here.role == "primary" else "secondary";
            print(f"  staging {here.title} ({role_label}): GR peers unreachable (transient)");
            if here.role == "secondary" {
                visit [->:CloneFrom:->];
            } else {
                visit [-->] else { disengage; };
            }
        }
    }

    can note_donor with MySQLPod exit {
        if here.role == "primary" and not here.alive and here.killed_by_probe {
            self.donor_killed = True;
            print(f"  clone donor {here.title} lost — in-flight CLONE aborted");
        }
    }
}

walker BootstrapProbe {
    has failure_threshold: int = 1;
    has kills: int = 0;
    has donor_killed: bool = False;
    has cluster_startup_bypass: bool = False;

    can start with Root entry {
        visit [-->];
    }

    can scan_cluster with Cluster entry {
        self.cluster_startup_bypass = here.startup_bypass;
        bypass_note = "readiness/liveness bypass ON, startup bypass OFF";
        print(f"Probing cluster {here.title}: {bypass_note}");
        visit [->:MemberOf:->];
    }

    can probe_pod with MySQLPod entry {
        if not here.alive {
            visit [-->] else { disengage; };
        } else {
            if not here.peers_reachable and not self.cluster_startup_bypass {
                here.alive = False;
                here.killed_by_probe = True;
                self.kills += 1;
                if here.role == "primary" {
                    self.donor_killed = True;
                }
                print(f"  startup probe exit(1): killed {here.title} (no peers, threshold={self.failure_threshold})");
            } else {
                wait_label = "waiting (transient)" if not here.peers_reachable else "ok";
                print(f"  startup probe {wait_label}: {here.title}");
            }
            visit [-->] else { disengage; };
        }
    }
}

walker LoopAuditor {
    has seen_cycles: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can audit with Cluster entry {
        tag = f"{here.title}:crash={here.crash_detected}:recovery={here.recovery_active}";
        if tag in self.seen_cycles {
            print(f"LOOP DETECTED: repeated recovery signature [{tag}]");
        } else {
            self.seen_cycles.append(tag);
        }
        visit [->:MemberOf:->];
    }

    can tally with MySQLPod entry {
        state = "DEAD" if not here.alive else "alive";
        probe_flag = " probe-kill" if here.killed_by_probe else "";
        print(f"  pod {here.title} {state}{probe_flag} clone={here.clone_pct}%");
        visit [-->] else { disengage; };
    }
}

with entry {
    cluster = Cluster(title="db-gr", crash_detected=True);
    primary = MySQLPod(title="mysql-0", role="primary", peers_reachable=False);
    secondary_a = MySQLPod(title="mysql-1", role="secondary", peers_reachable=False);
    secondary_b = MySQLPod(title="mysql-2", role="secondary", peers_reachable=False);
    marker = RecoveryMarker();

    root ++> cluster;
    cluster +>:MemberOf:+> primary;
    cluster +>:MemberOf:+> secondary_a;
    cluster +>:MemberOf:+> secondary_b;
    cluster +>:MarkerOn:+> marker;
    secondary_a +>:CloneFrom(pct=12):+> primary;
    secondary_b +>:CloneFrom(pct=8):+> primary;
    primary +>:PeerLink:+> secondary_a;
    secondary_a +>:PeerLink:+> secondary_b;
    secondary_b +>:PeerLink:+> primary;

    recovery = CrashRecovery(max_cycles=2);
    root spawn recovery;

    probe = BootstrapProbe(failure_threshold=1);
    root spawn probe;

    extra_kills = 0;
    extra_cycles = 0;
    if probe.donor_killed {
        cluster.crash_detected = True;
        print("FullClusterCrashDetected: donor killed during clone window");
        recovery2 = CrashRecovery(max_cycles=1);
        root spawn recovery2;
        extra_cycles = recovery2.cycle;
        probe2 = BootstrapProbe(failure_threshold=1);
        root spawn probe2;
        extra_kills = probe2.kills;
    }

    auditor = LoopAuditor();
    root spawn auditor;

    print(f"Summary: probe kills={probe.kills + extra_kills}, "
          f"recovery cycles={recovery.cycle + extra_cycles}, "
          f"primary alive={primary.alive}");
}

"""Catalog groups: evidence-based release cards over ingestion-timestamp coincidences."""

node Employer {
    has name: str = "";
}

node Role {
    has title: str = "";
    has lifecycle: str = "";
    has season: str = "";
    has discipline: str = "";
    has education: str = "";
    has visible_at: int = 0;
    has release_evidence: bool = False;
}

node LiveSnapshot {
    has observed_at: int = 0;
    has source: str = "";
    has healthy: bool = True;
}

node ProgramUmbrella {
    has program_id: str = "";
}

node GroupCard {
    has kind: str = "";
    has label: str = "";
    has size: int = 0;
}

edge WorksAt { }
edge ObservedIn { }
edge ProgramMember { }
edge InCard { }
edge MetadataPeer { }

walker StampGrouper {
    has window_sec: int = 8;
    has min_size: int = 4;
    has anchor_stamp: int = -1;
    has in_window: int = 0;
    has mixed_cycles: bool = False;
    has first_cycle: str = "";

    can start with Root entry {
        visit [-->];
    }

    can sweep with Employer entry {
        print(f"== stamp-window grouping for {here.name} ==");
        self.anchor_stamp = -1;
        self.in_window = 0;
        self.mixed_cycles = False;
        self.first_cycle = "";
        visit [<-:WorksAt:<-] else { disengage; };
    }

    can count with Role entry {
        if self.anchor_stamp < 0 {
            self.anchor_stamp = here.visible_at;
        }
        delta = here.visible_at - self.anchor_stamp;
        if delta <= self.window_sec {
            self.in_window += 1;
            cycle = f"{here.lifecycle}/{here.season}";
            if self.first_cycle == "" {
                self.first_cycle = cycle;
            } elif cycle != self.first_cycle {
                self.mixed_cycles = True;
            }
        }
    }
}

walker EvidenceGrouper {
    has max_card_size: int = 3;
    has cards_built: int = 0;
    has employer_label: str = "";
    has bucket: str = "";
    has bucket_size: int = 0;
    has active_card: GroupCard | None = None;

    can start with Root entry {
        visit [-->];
    }

    can at_employer with Employer entry {
        print(f"== evidence-based grouping for {here.name} ==");
        self.employer_label = here.name;
        self.bucket = "";
        self.bucket_size = 0;
        self.active_card = None;
        visit [<-:WorksAt:<-] else { disengage; };
    }

    can place with Role entry {
        if not here.release_evidence {
            print(f"  SKIP {here.title}: baseline/backfill timestamp only");
        } else {
            key = f"{here.lifecycle}|{here.season}";
            if self.bucket != "" and key != self.bucket {
                print(f"  SPLIT incompatible cycle {key} vs {self.bucket}");
                self.bucket = key;
                self.bucket_size = 0;
                self.active_card = None;
            }
            if self.bucket == "" {
                self.bucket = key;
            }
            if self.active_card is None {
                card = GroupCard(
                    kind="employer-release",
                    label=f"{self.employer_label}:{key}#{self.cards_built}",
                    size=0
                );
                root ++> card;
                self.active_card = card;
                self.cards_built += 1;
                print(f"  NEW card {card.label}");
            } elif self.bucket_size >= self.max_card_size {
                card = GroupCard(
                    kind="employer-release",
                    label=f"{self.employer_label}:{key}#{self.cards_built}",
                    size=0
                );
                root ++> card;
                self.active_card = card;
                self.cards_built += 1;
                self.bucket_size = 0;
                print(f"  SPLIT size cap -> {card.label}");
            }
            here +>:InCard:+> self.active_card;
            self.active_card.size += 1;
            self.bucket_size += 1;
            print(f"  + {here.title} ({here.discipline})");
        }
    }
}

walker ProgramAuditor {
    can start with Root entry {
        visit [-->];
    }

    can audit with ProgramUmbrella entry {
        print(f"== program-group audit: {here.program_id} ==");
        visit [<-:ProgramMember:<-] else {
            print("  REJECT: no explicit program members");
            disengage;
        };
    }

    can member with Role entry {
        print(f"  OK {here.title} ({here.discipline}) via program_id");
    }
}

walker MetadataProbe {
    has first_discipline: str = "";

    can start with Role entry {
        self.first_discipline = here.discipline;
        print(f"  metadata peer A: {here.title} ({here.discipline})");
        visit [->:MetadataPeer:->] else { disengage; };
    }

    can compare with Role entry {
        print(f"  metadata peer B: {here.title} ({here.discipline})");
        print("== metadata-only program-group attempt ==");
        if self.first_discipline != here.discipline {
            print(
                f"  REJECT: cross-discipline "
                f"{self.first_discipline} vs {here.discipline}"
            );
        } else {
            print("  REJECT: shared metadata without explicit program_id");
        }
        disengage;
    }
}

walker CatalogReporter {
    can start with Root entry {
        visit [-->];
    }

    can show_card with GroupCard entry {
        print(f"[CARD] {here.kind} {here.label} size={here.size}");
        visit [-->];
    }

    can show_program with ProgramUmbrella entry {
        print(f"[PROGRAM] umbrella {here.program_id}");
        visit [-->];
    }
}

