"""GDP disjunct semantics: OR, select_one, and truth_xor over overlapping feasible sets."""

node GDPModel {
    has name: str = "";
    has semantics: str = "or";
    has primal_x: float = 0.0;
}

node Disjunct {
    has label: str = "";

    def holds_at(x: float) -> bool {
        return False;
    }
}

node LeDisjunct(Disjunct) {
    has bound: float = 1.0;

    override def holds_at(x: float) -> bool {
        return x <= self.bound;
    }
}

node GeDisjunct(Disjunct) {
    has bound: float = 0.0;

    override def holds_at(x: float) -> bool {
        return x >= self.bound;
    }
}

node ReformStage {
    has stage_name: str = "";
    has preserves_semantics: bool = True;
}

edge InModel { }
edge NextStage { }

walker SemanticsAuditor {
    has primal_x: float = 0.0;
    has mode: str = "or";
    has true_labels: list[str] = [];
    has false_labels: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can begin with GDPModel entry {
        self.primal_x = here.primal_x;
        self.mode = here.semantics;
        self.true_labels = [];
        self.false_labels = [];
        visit [->:InModel:->];
    }

    can evaluate with Disjunct entry {
        if here.holds_at(self.primal_x) {
            self.true_labels += [here.label];
        } else {
            self.false_labels += [here.label];
        }
    }

    can conclude with GDPModel exit {
        n_true = len(self.true_labels);
        feasible = False;
        if self.mode == "or" {
            feasible = n_true >= 1;
        } elif self.mode == "select_one" {
            feasible = n_true >= 1;
        } else {
            feasible = n_true == 1;
        }
        status = "FEASIBLE" if feasible else "INFEASIBLE";
        truths = ", ".join(self.true_labels) if self.true_labels else "(none)";
        print(f"[{self.mode}] x={self.primal_x} on {here.name}: {status} (true: {truths})");
    }
}

walker ReformulationWalker {
    has path: list[str] = [];
    has visited: list[str] = [];

    can traverse with ReformStage entry {
        if here.stage_name in self.visited {
            print(f"CYCLE at reform stage '{here.stage_name}' — disengaging");
            disengage;
        }
        self.visited += [here.stage_name];
        tag = "semantic" if here.preserves_semantics else "lowered";
        self.path += [f"{here.stage_name}({tag})"];
        visit [->:NextStage:->] else { disengage; };
    }

    can finish with ReformStage exit {
        chain = " -> ".join(self.path);
        print(f"reformulation path: {chain}");
    }
}

with entry {
    print("=== Overlap: x=0.5 in S1={x<=1} AND S2={x>=0} ===");
    modes = ["or", "select_one", "truth_xor"];
    for mode in modes {
        m = GDPModel(name="overlap", semantics=mode, primal_x=0.5);
        root ++> m;
        m +>:InModel:+> LeDisjunct(label="S1:x<=1", bound=1.0);
        m +>:InModel:+> GeDisjunct(label="S2:x>=0", bound=0.0);
    }
    root spawn SemanticsAuditor();

    print("=== Reformulation pipeline: complementarity -> GDP -> continuous NLP ===");
    comp = ReformStage(stage_name="complementarity", preserves_semantics=False);
    gdp = ReformStage(stage_name="gdp_disjunction", preserves_semantics=True);
    nlp = ReformStage(stage_name="continuous_nlp", preserves_semantics=False);
    root ++> comp +>:NextStage:+> gdp +>:NextStage:+> nlp;
    comp spawn ReformulationWalker();
}

"""Pibo sessions-to-v2 migration: skipped newer targets must not mutate runtime bindings."""

node Session {
    has session_id: str = "";
    has pi_session_id: str = "";
    has title: str = "";
    has updated_at: str = "";
}

node RuntimeBinding {
    has native_session_id: str = "";
    has binding_state: str = "bound";
    has revision: int = 1;
    has updated_at: str = "";
}

node LegacyRow {
    has session_id: str = "";
    has pi_session_id: str = "";
    has title: str = "";
    has updated_at: str = "";
}

edge SourceFor { }

edge HasBinding { }

walker SessionsToV2Migrator {
    has read: int = 0;
    has inserted: int = 0;
    has updated: int = 0;
    has skipped: int = 0;
    has legacy_session_id: str = "";
    has legacy_pi_id: str = "";
    has legacy_title: str = "";
    has legacy_updated_at: str = "";
    has force_binding_sync: bool = False;

    can start with Root entry {
        visit [-->] else { disengage; }
    }

    can ingest with LegacyRow entry {
        self.read += 1;
        self.legacy_session_id = here.session_id;
        self.legacy_pi_id = here.pi_session_id;
        self.legacy_title = here.title;
        self.legacy_updated_at = here.updated_at;
        visit [->:SourceFor:->];
    }

    can reconcile with Session entry {
        if here.session_id != self.legacy_session_id {
            visit [-->] else { disengage; }
        } else {
            target_is_newer = here.updated_at > self.legacy_updated_at;
            if target_is_newer {
                self.skipped += 1;
                print(f"skipped: {here.session_id} (target newer)");
            } else {
                self.updated += 1;
                here.pi_session_id = self.legacy_pi_id;
                here.title = self.legacy_title;
                here.updated_at = self.legacy_updated_at;
                print(f"updated: {here.session_id}");
            }
            self.force_binding_sync = True;
            visit [->:HasBinding:->];
        }
    }

    can patch_binding with RuntimeBinding entry {
        if self.force_binding_sync {
            here.native_session_id = self.legacy_pi_id;
            here.revision += 1;
            here.updated_at = self.legacy_updated_at;
            self.force_binding_sync = False;
        }
        visit [-->] else { disengage; }
    }
}

with entry {
    collision_binding = RuntimeBinding(
        native_session_id="pi_target_newer",
        binding_state="bound",
        revision=1,
        updated_at="2026-08-30T06:31:29.537Z"
    );
    collision_session = Session(
        session_id="ps_synthetic_binding_collision",
        pi_session_id="pi_target_newer",
        title="Target newer row",
        updated_at="2026-08-30T06:31:29.537Z"
    );
    collision_session +>:HasBinding:+> collision_binding;

    legacy = LegacyRow(
        session_id="ps_synthetic_binding_collision",
        pi_session_id="pi_legacy_older",
        title="Legacy older row",
        updated_at="2026-08-29T00:01:00.000Z"
    );
    legacy +>:SourceFor:+> collision_session;

    control_binding = RuntimeBinding(
        native_session_id="pi_control",
        binding_state="bound",
        revision=1,
        updated_at="2026-08-30T06:31:29.537Z"
    );
    control_session = Session(
        session_id="ps_synthetic_control",
        pi_session_id="pi_control",
        title="Unmatched control",
        updated_at="2026-08-30T06:31:29.537Z"
    );
    control_session +>:HasBinding:+> control_binding;

    root ++> legacy;
    root ++> control_session;

    run1 = SessionsToV2Migrator();
    root spawn run1;
    print(
        f"run1 read={run1.read} inserted={run1.inserted} "
        f"updated={run1.updated} skipped={run1.skipped}"
    );
    print(
        f"collision after run1: pi_session_id={collision_session.pi_session_id} "
        f"native_session_id={collision_binding.native_session_id} "
        f"revision={collision_binding.revision} "
        f"binding_updated_at={collision_binding.updated_at}"
    );

    run2 = SessionsToV2Migrator();
    root spawn run2;
    print(
        f"run2 read={run2.read} inserted={run2.inserted} "
        f"updated={run2.updated} skipped={run2.skipped}"
    );
    print(
        f"collision after run2: pi_session_id={collision_session.pi_session_id} "
        f"native_session_id={collision_binding.native_session_id} "
        f"revision={collision_binding.revision}"
    );
    print(
        f"control unchanged: pi_session_id={control_session.pi_session_id} "
        f"native_session_id={control_binding.native_session_id} "
        f"revision={control_binding.revision}"
    );
}

"""GR bootstrap startup probe races full-cluster-crash recovery.

Models Percona operator issue #1467: bootstrap exits on transient no-peer
states during full-cluster-crash recovery. With startupProbe failureThreshold=1
and no crash-marker bypass on startup, the probe kills the clone donor and
recovery loops on large datasets.
"""

node Cluster {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has crash_detected: bool = False;
    has recovery_active: bool = False;
    has startup_bypass: bool = False;
}

node MySQLPod {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has role: str = "secondary";
    has alive: bool = True;
    has peers_reachable: bool = False;
    has clone_pct: int = 0;
    has killed_by_probe: bool = False;
}

node RecoveryMarker {
    has title: str = "full-cluster-crash";
    has year: int = 0;
    has available: bool = True;
    has covers_startup: bool = False;
}

edge MemberOf { }
edge CloneFrom { has pct: int = 0; }
edge MarkerOn { }

walker CrashRecovery {
    has cycle: int = 0;
    has max_cycles: int = 2;
    has donor_lost: bool = False;

    can start with Root entry {
        visit [-->];
    }

    can reboot with Cluster entry {
        if not here.crash_detected {
            disengage;
        }
        if self.cycle >= self.max_cycles {
            print(f"Recovery halted after {self.cycle} cycles (demo cap)");
            disengage;
        }
        self.cycle += 1;
        here.recovery_active = True;
        here.startup_bypass = False;
        print(f"Cycle {self.cycle}: rebootClusterFromCompleteOutage on {here.title}");
        visit [->:MemberOf:->];
    }

    can stage_pod with MySQLPod entry {
        if not here.alive {
            disengage;
        }
        here.peers_reachable = False;
        role_label = "primary" if here.role == "primary" else "secondary";
        print(f"  staging {here.title} ({role_label}): GR peers unreachable (transient)");
        if here.role == "secondary" {
            here.clone_pct = 10;
            visit [->:CloneFrom:->];
        } else {
            disengage;
        }
    }

    can note_donor with MySQLPod exit {
        if here.role == "primary" and not here.alive and here.killed_by_probe {
            self.donor_lost = True;
            print(f"  clone donor {here.title} lost — in-flight CLONE aborted");
        }
    }
}

walker BootstrapProbe {
    has failure_threshold: int = 1;
    has kills: int = 0;
    has donor_killed: bool = False;
    has startup_bypass: bool = False;

    can start with Root entry {
        visit [-->];
    }

    can scan_cluster with Cluster entry {
        self.startup_bypass = here.startup_bypass;
        bypass_note = "startup bypass ON" if here.startup_bypass else "startup bypass OFF";
        print(f"Probing cluster {here.title}: {bypass_note}");
        visit [->:MemberOf:->];
    }

    can probe_pod with MySQLPod entry {
        if not here.alive {
            disengage;
        }
        if not here.peers_reachable and not self.startup_bypass {
            here.alive = False;
            here.killed_by_probe = True;
            self.kills += 1;
            if here.role == "primary" {
                self.donor_killed = True;
            }
            print(f"  startup probe exit(1): killed {here.title} (no peers, threshold={self.failure_threshold})");
        } else {
            wait_label = "waiting (transient)" if not here.peers_reachable else "ok";
            print(f"  startup probe {wait_label}: {here.title}");
        }
        disengage;
    }
}

walker LoopAuditor {
    has signatures: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can audit with Cluster entry {
        sig = f"{here.title}:crash={here.crash_detected}:recovery={here.recovery_active}";
        if sig in self.signatures {
            print(f"LOOP DETECTED: repeated recovery signature [{sig}]");
        } else {
            self.signatures.append(sig);
        }
        visit [->:MemberOf:->];
    }

    can tally with MySQLPod entry {
        state = "DEAD" if not here.alive else "alive";
        flag = " probe-kill" if here.killed_by_probe else "";
        print(f"  pod {here.title} {state}{flag} clone={here.clone_pct}%");
        disengage;
    }
}

with entry {
    cluster = Cluster(title="db-gr", crash_detected=True);
    primary = MySQLPod(title="mysql-0", role="primary", peers_reachable=False);
    secondary_a = MySQLPod(title="mysql-1", role="secondary", peers_reachable=False);
    secondary_b = MySQLPod(title="mysql-2", role="secondary", peers_reachable=False);
    marker = RecoveryMarker(covers_startup=False);

    root ++> cluster;
    cluster +>:MemberOf:+> primary;
    cluster +>:MemberOf:+> secondary_a;
    cluster +>:MemberOf:+> secondary_b;
    cluster +>:MarkerOn:+> marker;
    secondary_a +>:CloneFrom(pct=12):+> primary;
    secondary_b +>:CloneFrom(pct=8):+> primary;

    recovery = CrashRecovery(max_cycles=2);
    root spawn recovery;

    probe = BootstrapProbe(failure_threshold=1);
    root spawn probe;

    total_kills = probe.kills;
    total_cycles = recovery.cycle;
    if probe.donor_killed {
        cluster.crash_detected = True;
        print("FullClusterCrashDetected: donor killed during clone window");
        recovery2 = CrashRecovery(max_cycles=1);
        root spawn recovery2;
        total_cycles += recovery2.cycle;
        probe2 = BootstrapProbe(failure_threshold=1);
        root spawn probe2;
        total_kills += probe2.kills;
    }

    auditor = LoopAuditor();
    root spawn auditor;

    print(f"Summary: probe kills={total_kills}, recovery cycles={total_cycles}, primary alive={primary.alive}");
}

