node GDPModel {
    has name: str = "";
    has semantics: str = "or";
    has primal_x: float = 0.0;
}

node Disjunct {
    has label: str = "";

    def holds_at(x: float) -> bool {
        return False;
    }
}

node LeDisjunct(Disjunct) {
    has bound: float = 1.0;

    override def holds_at(x: float) -> bool {
        return x <= self.bound;
    }
