"""Vite/Rolldown module graph: walk import edges, detect cycles, and classify cross-chunk hazards.

Models issue #262: the Rollup cross-chunk cycle guard went silent after migration,
while a broader circular-dependency check surfaces first-party and vendor cycles.
"""

node Chunk {
    has name: str = "";
    has is_initial: bool = False;
}

node Module {
    has path: str = "";
    has chunk: str = "initial";
    has is_vendor: bool = False;
}

edge BundledIn { }
edge Imports { has is_dynamic: bool = False; }

walker BuildAuditor {
    has path_stack: list[str] = [];
    has chunk_stack: list[str] = [];
    has vendor_stack: list[bool] = [];
    has all_cycles: list[str] = [];
    has cross_chunk_cycles: list[str] = [];
    has first_party_cycles: list[str] = [];
    has vendor_cycles: list[str] = [];
    has rolldown_mode: bool = True;

    def pop_frame() {
        if len(self.path_stack) == 0 {
            return;
        }
        new_paths = [];
        new_chunks = [];
        new_vendors = [];
        for (i, p) in enumerate(self.path_stack) {
            if i < len(self.path_stack) - 1 {
                new_paths.append(p);
                new_chunks.append(self.chunk_stack[i]);
                new_vendors.append(self.vendor_stack[i]);
            }
        }
        self.path_stack = new_paths;
        self.chunk_stack = new_chunks;
        self.vendor_stack = new_vendors;
    }

    def join_cycle(parts: list[str]) -> str {
        label = "";
        for (i, part) in enumerate(parts) {
            sep = " -> " if i > 0 else "";
            label += f"{sep}{part}";
        }
        return label;
    }

    def record_cycle(start_idx: int) {
        parts = [];
        chunks_seen = [];
        has_first_party = False;
        for (i, p) in enumerate(self.path_stack) {
            if i >= start_idx {
                parts.append(p);
                c = self.chunk_stack[i];
                if c not in chunks_seen {
                    chunks_seen.append(c);
                }
                if not self.vendor_stack[i] {
                    has_first_party = True;
                }
            }
        }
        parts.append(here.path);
        if here.chunk not in chunks_seen {
            chunks_seen.append(here.chunk);
        }
        if not here.is_vendor {
            has_first_party = True;
        }
        cycle_text = self.join_cycle(parts);
        if cycle_text in self.all_cycles {
            return;
        }
        self.all_cycles.append(cycle_text);
        if len(chunks_seen) > 1 {
            self.cross_chunk_cycles.append(cycle_text);
        }
        if has_first_party {
            self.first_party_cycles.append(cycle_text);
        } else {
            self.vendor_cycles.append(cycle_text);
        }
    }

    can audit with Root entry {
        print("BuildAuditor: scanning module graph for circular dependencies");
        visit [-->] else { disengage; }
    }

    can audit with Chunk entry {
        visit [-->] else { disengage; }
    }

    can trace with Module entry {
        cycle_start = -1;
        for (i, p) in enumerate(self.path_stack) {
            if p == here.path {
                cycle_start = i;
            }
        }
        if cycle_start >= 0 {
            self.record_cycle(cycle_start);
            disengage;
        }
        self.path_stack.append(here.path);
        self.chunk_stack.append(here.chunk);
        self.vendor_stack.append(here.is_vendor);
        visit [->:Imports:->] else { };
        self.pop_frame();
    }
}

walker CrossChunkGuard {
