    root +>:BundledIn:+> lazy_a;
    root +>:BundledIn:+> lazy_b;

    api +>:Imports:+> api_runtime;
    api_runtime +>:Imports:+> api;
    ensure +>:Imports:+> orch_helper;
    orch_helper +>:Imports:+> ensure;
    zod_mod +>:Imports:+> zod_schema;
    zod_schema +>:Imports:+> zod_mod;
    lazy_a +>:Imports:+> lazy_b;
    lazy_b +>:Imports(is_dynamic=True):+> lazy_a;

    auditor = BuildAuditor(rolldown_mode=True);
    root spawn auditor;

    print(f"CIRCULAR_DEPENDENCY: {len(auditor.all_cycles)} distinct cycles");
    for cycle in auditor.all_cycles {
        tag = "vendor";
        if cycle in auditor.first_party_cycles {
            tag = "first-party";
        }
        span = "intra-chunk";
        if cycle in auditor.cross_chunk_cycles {
            span = "cross-chunk";
        }
        print(f"  [{tag}/{span}] {cycle}");
    }

    legacy_guard_fires = (
        (not auditor.rolldown_mode) and len(auditor.cross_chunk_cycles) > 0
    );
    broad_check_blocks = len(auditor.first_party_cycles) > 0;
    guard_status = "FIRE" if legacy_guard_fires else "inert";
    broad_status = "BLOCK" if broad_check_blocks else "pass";

    print(
        f"Legacy Rollup cross-chunk guard: {guard_status} "
        f"({len(auditor.cross_chunk_cycles)} cross-chunk hazards)"
    );
    print(
        f"Broad circularDependency check: {broad_status} "
        f"({len(auditor.first_party_cycles)} first-party cycles)"
    );

    guard = CrossChunkGuard(
        rolldown_mode=True, hazards=auditor.cross_chunk_cycles
    );
    root spawn guard;
}

"""dotnet-inspect v1.0 tracking: goal areas, linked issues, and closure readiness audit."""

node TrackingIssue {
    has title: str = "";
    has version: str = "";
}

node GoalArea {
    has number: int = 0;
    has name: str = "";
}

node LinkedIssue {
    has issue_id: int = 0;
    has title: str = "";
    has resolved: bool = False;
}

node FoundationalWork {
    has pr_id: int = 0;
    has title: str = "";
}

edge Tracks { }
edge LinksTo { }
edge IncludesMerged { }

walker ReleaseAuditor {
    has open_blockers: list[str] = [];
    has goals_audited: int = 0;
    has goals_clear: int = 0;
    has open_on_goal: int = 0;
    has visited_goals: list[int] = [];

    can start with Root entry {
        visit [-->];
    }

    can audit_tracking with TrackingIssue entry {
        print(f"=== {here.title} ({here.version}) ===");
        visit [->:Tracks:->] else { disengage; };
    }

    can enter_goal with GoalArea entry {
        if here.number in self.visited_goals {
            print(f"[CYCLE] goal {here.number} revisited — halting branch");
            disengage;
        }
        self.visited_goals.append(here.number);
        self.goals_audited += 1;
        self.open_on_goal = 0;
        print(f"\nGoal {here.number}: {here.name}");
        visit [->:IncludesMerged:->];
        visit [->:LinksTo:->];
    }

    can note_merged with FoundationalWork entry {
        print(f"  [merged] PR #{here.pr_id}: {here.title}");
    }

    can check_issue with LinkedIssue entry {
        status = "done" if here.resolved else "open";
        if not here.resolved {
            self.open_on_goal += 1;
            self.open_blockers.append(f"#{here.issue_id} {here.title}");
        }
        print(f"  [{status}] #{here.issue_id}: {here.title}");
    }

    can leave_goal with GoalArea exit {
        label = "CLEAR" if self.open_on_goal == 0 else "BLOCKED";
        if self.open_on_goal == 0 {
            self.goals_clear += 1;
        }
        print(f"  -> goal {here.number} {label}");
    }

    can finish_tracking with TrackingIssue exit {
        ready = self.goals_clear == self.goals_audited;
        verdict = "CLOSABLE" if ready else "BLOCKED";
        print(f"\n=== Verdict: {verdict} "
              f"({self.goals_clear}/{self.goals_audited} goals clear) ===");
        if not ready {
            print("Remaining blockers:");
            for (i, b) in enumerate(self.open_blockers) {
                print(f"  {i + 1}. {b}");
            }
        }
    }
}

