"""Durable approval gates: suspend pipeline runs at manual review points, release workers, and resume after auditable decisions."""

node PipelineRun {
    has run_id: str = "";
    has status: str = "running";
}

node PipelineAsset {
    has name: str = "";
    has asset_type: str = "task";
    has completed: bool = False;
}

node ApprovalGate {
    has gate_id: str = "";
    has title: str = "";
    has instructions: str = "";
    has status: str = "pending";
    has input_fingerprint: str = "";
    has require_comment: bool = True;
    has resumed: bool = False;
    has terminal_action: str = "";
}

node DecisionRecord {
    has decision_id: str = "";
    has action: str = "";
    has comment: str = "";
    has actor: str = "";
    has payload_json: str = "";
    has fingerprint: str = "";
}

edge DependsOn { }
edge OwnsGate { }
edge LoggedDecision { }

walker PipelineExecutor {
    has pass_label: str = "initial";

    can start with Root entry {
        print(f"=== PipelineExecutor ({self.pass_label}) ===");
        visit [-->] else { disengage; }
    }

    can enter_run with PipelineRun entry {
        if here.status == "cancelled" {
            print(f"  run {here.run_id} cancelled — halting");
            disengage;
        }
        print(f"  run {here.run_id} status={here.status}");
        visit [-->] else { disengage; }
    }

    can run_asset with PipelineAsset entry {
        if here.completed {
            visit [-->] else { disengage; }
        }
        print(f"    [asset] completed {here.name}");
        here.completed = True;
        visit [-->] else { disengage; }
    }

    can reach_gate with ApprovalGate entry {
        if here.status == "pending" {
            here.status = "waiting_for_approval";
            print(f"    [gate] SUSPENDED {here.gate_id}: {here.title}");
            print(f"           fingerprint={here.input_fingerprint} — worker released");
            disengage;
        } elif here.status == "waiting_for_approval" {
            print(f"    [gate] still waiting on {here.gate_id}");
            disengage;
        } elif here.status == "approved" and not here.resumed {
            print(f"    [gate] resuming past approved {here.gate_id}");
            here.resumed = True;
            visit [-->] else { disengage; }
        } elif here.status == "approved" and here.resumed {
            visit [-->] else { disengage; }
        } else {
            halt_label = here.terminal_action if here.terminal_action != "" else here.status;
            print(f"    [gate] terminal on {here.gate_id}: {halt_label}");
            disengage;
        }
    }
}

walker ApprovalDecider {
    has target_gate_id: str = "";
    has action: str = "approve";
    has comment: str = "";
    has actor: str = "reviewer";
    has submitted_fingerprint: str = "";
    has payload_json: str = "";
    has decision_seq: int = 0;

    can start with Root entry {
        visit [-->] else { disengage; }
    }

    can decide with ApprovalGate entry {
        if here.gate_id != self.target_gate_id {
            visit [-->] else { disengage; }
        }
        if here.status == "approved" or here.status == "rejected" or here.status == "cancelled" {
            print(f"  [decide] idempotent — {here.gate_id} already {here.status}");
            disengage;
        }
        if here.status != "waiting_for_approval" {
            print(f"  [decide] skip {here.gate_id} (status={here.status})");
            disengage;
        }
        if self.submitted_fingerprint != here.input_fingerprint {
            print(f"  [decide] STALE rejected for {here.gate_id}: "
                  f"expected {here.input_fingerprint}, got {self.submitted_fingerprint}");
            disengage;
        }
        if here.require_comment and self.comment == "" {
            print(f"  [decide] comment required for {here.gate_id}");
            disengage;
        }
        new_status = "approved" if self.action == "approve" else self.action;
        here.status = new_status;
        here.terminal_action = self.action;
        self.decision_seq += 1;
        decision = DecisionRecord(
            decision_id=f"{here.gate_id}-evt-{self.decision_seq}",
            action=self.action,
            comment=self.comment,
            actor=self.actor,
            payload_json=self.payload_json,
            fingerprint=here.input_fingerprint
        );
        here +>:LoggedDecision:+> decision;
        print(f"  [decide] {self.action} on {here.gate_id} by {self.actor}: \"{self.comment}\"");
        disengage;
    }
}

walker RunCanceller {
    has target_run_id: str = "";

    can start with Root entry {
        print("=== RunCanceller ===");
        visit [-->] else { disengage; }
    }

    can cancel_run with PipelineRun entry {
        if here.run_id != self.target_run_id {
            visit [-->] else { disengage; }
        }
        here.status = "cancelled";
        print(f"  cancelled run {here.run_id}");
        visit [->:OwnsGate:->] else { disengage; }
    }

    can close_gate with ApprovalGate entry {
        if here.status == "waiting_for_approval" {
            here.status = "cancelled";
            here.terminal_action = "cancel";
            print(f"    closed outstanding gate {here.gate_id}");
        }
        disengage;
    }
}

walker GateAuditor {
    has pending_count: int = 0;

    can start with Root entry {
        print("=== GateAuditor (pending) ===");
        visit [-->] else { disengage; }
    }

    can audit_run with PipelineRun entry {
        visit [->:OwnsGate:->] else { visit [-->] else { disengage; } };
    }

    can inspect with ApprovalGate entry {
        if here.status == "waiting_for_approval" {
            self.pending_count += 1;
            print(f"  pending {here.gate_id}: {here.title} (fp={here.input_fingerprint})");
        }
        visit [->:LoggedDecision:->] else { disengage; }
    }

    can read_decision with DecisionRecord entry {
        print(f"    decision {here.decision_id}: {here.action} by {here.actor}");
        disengage;
    }
}

with entry {
  run = PipelineRun(run_id="run-42");
  extract = PipelineAsset(name="extract_matches", asset_type="ingest");
  transform = PipelineAsset(name="build_review_report", asset_type="transform");
  gate = ApprovalGate(
