  root spawn PipelineExecutor(pass_label="resume-after-approve");

  print("--- stale approval attempt ---");
  gate_stale = ApprovalGate(
      gate_id="appr-002",
      title="Review schema-contract change",
      input_fingerprint="fp-v2",
      require_comment=True
  );
  run2 = PipelineRun(run_id="run-99");
  root ++> run2 ++> gate_stale;
  run2 +>:OwnsGate:+> gate_stale;
  gate_stale.status = "waiting_for_approval";
  root spawn ApprovalDecider(
      target_gate_id="appr-002",
      action="approve",
      comment="Looks fine",
      actor="bob",
      submitted_fingerprint="fp-v1"
  );

  print("--- parent cancellation closes gate ---");
  run3 = PipelineRun(run_id="run-cancel");
  gate3 = ApprovalGate(
      gate_id="appr-003",
      title="Authorize destructive migration",
      input_fingerprint="fp-mig",
      status="waiting_for_approval"
  );
  root ++> run3;
  run3 +>:OwnsGate:+> gate3;
  root spawn RunCanceller(target_run_id="run-cancel");

  root spawn GateAuditor();
}

