"""TROE ADR 0035: kernel-linked modules, dependency-ordered migration, and protected IPC hop profiling."""

node KernelBoundary {
    has label: str = "";
}

node LinkedModule {
    has crate_name: str = "";
    has removable: bool = True;
}

node IsolatedServer {
    has service_name: str = "";
    has persistent: bool = True;
    has peer_name: str = "";
}

node DeviceBroker {
    has broker_kind: str = "";
    has peer_name: str = "";
}

edge KernelLink { }
edge Requires { has gate: str = ""; }
edge MigratedTo { }
edge IpcHop {
    has req_copies: int = 2;
    has rep_copies: int = 2;
    has tlb_flush: bool = True;
}

walker KernelSlimmer {
    has visited: list[str] = [];
    has removal_order: list[str] = [];
    has cycle_detected: bool = False;
    has migration_targets: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can enter_kernel with KernelBoundary entry {
        visit [->:KernelLink:->] else { disengage; };
    }

    can plan_module with LinkedModule entry {
        key = here.crate_name;
        if key in self.visited {
            self.cycle_detected = True;
            print(f"[CYCLE] dependency loop at {key}");
            disengage;
        }
        self.visited.append(key);
        visit [->:Requires:->];
        self.removal_order.append(key);
        visit [->:MigratedTo:->] else { disengage; };
    }

    can at_broker with DeviceBroker entry {
        visit [->:Requires:->] else { disengage; };
    }

    can record_target with IsolatedServer entry {
        target = here.service_name;
        if target not in self.migration_targets {
            self.migration_targets.append(target);
        }
        disengage;
    }
}

walker IpcProfiler {
    has hop_count: int = 0;
    has req_copies: int = 0;
    has rep_copies: int = 0;
    has tlb_flushes: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can begin_call with KernelBoundary entry {
        visit [->:IpcHop:->] else { disengage; };
    }

    can tally_hop with IsolatedServer | DeviceBroker entry {
        self.hop_count += 1;
        self.req_copies += here->:IpcHop:->.req_copies;
        self.rep_copies += here->:IpcHop:->.rep_copies;
        if here->:IpcHop:->.tlb_flush {
            self.tlb_flushes += 1;
        }
        visit [->:IpcHop:->] else { disengage; };
    }
}

with entry {
    kernel = KernelBoundary(label="TROE monolith");
    root ++> kernel;

    vfs = LinkedModule(crate_name="troe-vfs");
    ext4 = LinkedModule(crate_name="troe-ext4");
    net = LinkedModule(crate_name="troe-net");
    block_broker = DeviceBroker(broker_kind="block", peer_name="block-broker");
    packet_broker = DeviceBroker(broker_kind="packet", peer_name="packet-broker");

    kernel +>:KernelLink:+> vfs;
    kernel +>:KernelLink:+> ext4;
    kernel +>:KernelLink:+> net;
    kernel +>:KernelLink:+> block_broker;
    kernel +>:KernelLink:+> packet_broker;

    vfs +>:Requires(gate="block-region"):+> block_broker;
    ext4 +>:Requires(gate="namespace"):+> vfs;
    net +>:Requires(gate="packet-device"):+> packet_broker;

    storage_srv = IsolatedServer(
        service_name="storage-server",
        persistent=True,
        peer_name="storage-server"
    );
    net_srv = IsolatedServer(
        service_name="network-server",
        persistent=True,
        peer_name="network-server"
    );
    diag_srv = IsolatedServer(
        service_name="diagnostics",
        persistent=False,
        peer_name="diagnostics"
    );

    vfs +>:MigratedTo:+> storage_srv;
    ext4 +>:MigratedTo:+> storage_srv;
    net +>:MigratedTo:+> net_srv;

    kernel +>:IpcHop(req_copies=2, rep_copies=2, tlb_flush=True):+> storage_srv;
    storage_srv +>:IpcHop(req_copies=2, rep_copies=2, tlb_flush=True):+> block_broker;
    kernel +>:IpcHop(req_copies=2, rep_copies=2, tlb_flush=True):+> net_srv;
    net_srv +>:IpcHop(req_copies=2, rep_copies=2, tlb_flush=True):+> packet_broker;

    slimmer = KernelSlimmer();
    kernel spawn slimmer;
    print(f"kernel slimming cycle={slimmer.cycle_detected}");
    print(f"removal order (deps first): {slimmer.removal_order}");
    print(f"migration targets: {slimmer.migration_targets}");
    print(f"ephemeral per-request server kept out of plan: {diag_srv.service_name} "
          f"(persistent={diag_srv.persistent})");

    profiler = IpcProfiler();
    kernel spawn profiler;
    per_fragment = profiler.req_copies + profiler.rep_copies;
    print(f"protected IPC path: {profiler.hop_count} hops, "
          f"{per_fragment} payload copies per fragment, "
          f"{profiler.tlb_flushes} TLB invalidations");
}

