"""Semantic contract drift: review doctrine cannot stop unadmitted facts, split interpreters, or dependency cycles."""

node Interpreter {
    has name: str = "";

    def is_canonical() -> bool {
        return False;
    }
}

node CanonicalOwner {
    has name: str = "";
    has doctrine: str = "";
}

node SemanticFact {
    has key: str = "";
    has payload: str = "";
    has generation: int = 0;
    has admitted: bool = False;
}

node Consumer(Interpreter) {
    has joined_proof_matrix: bool = False;

    override def is_canonical() -> bool {
        return self.joined_proof_matrix;
    }
}

node ShadowRepair(Interpreter) {
    override def is_canonical() -> bool {
        return False;
    }
}

edge Owns { }
edge Requires { }
edge Reads { }
edge Interprets { }

walker SemanticAuditor {
    has violations: list[str] = [];
    has dependency_seen: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can audit_owner with CanonicalOwner entry {
        print(f"canonical owner [{here.name}]: {here.doctrine}");
        visit [->:Owns:->];
    }

    can inspect_fact with SemanticFact entry {
        if not here.admitted {
            self.violations.append(f"unadmitted fact: {here.key}");
        }
        if here.generation == 0 {
            self.violations.append(f"generation-unbound: {here.key}");
        }
        if here.key in self.dependency_seen {
            self.violations.append(f"dependency cycle at: {here.key}");
            disengage;
        }
        self.dependency_seen.append(here.key);
        visit [->:Requires:->];
        visit [->:Interprets:->];
        visit [->:Reads:->] else { disengage; };
    }

    can flag_split with Consumer | ShadowRepair entry {
        if not here.is_canonical() {
            self.violations.append(f"split authority: {here.name}");
        }
        visit [-->] else { disengage; };
    }

    can report with Root exit {
        total = len(self.violations);
        print(f"structural audit found {total} semantic violation(s)");
        for v in self.violations {
            print(f"  [{v}]");
        }
    }
}

