"""Very Good CLI recursive test: reject positional targets with --recursive.

Models a monorepo where ``very_good test --recursive`` forwards the same
positional test path into every package root. One package resolves the
target; the others fail to load (exit 69). The guarded runner rejects
the incompatible combination before fan-out.
"""

node PathCarrier {
    has path: str = "";
}

node Package {
    has name: str = "";
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

node TestFile(PathCarrier) {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

node PositionalTarget(PathCarrier) {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

edge InMonorepo { }
edge Hosts { }

walker BuggyRecursiveTest {
    has target_path: str = "";
    has load_successes: int = 0;
    has load_failures: int = 0;
    has saw_match: bool = False;

    can start with Root entry {
        visit [-->[?:PositionalTarget]];
        visit [->:InMonorepo:->] else { disengage; };
    }

    can capture with PositionalTarget entry {
        self.target_path = here.path;
    }

    can fan_out with Package entry {
        self.saw_match = False;
        visit [->:Hosts:->] else {
            self.load_failures += 1;
            visit [->:InMonorepo:->] else { disengage; };
            disengage;
        };
        if self.saw_match {
            self.load_successes += 1;
        } else {
            self.load_failures += 1;
        }
        visit [->:InMonorepo:->] else { disengage; };
    }

    can resolve with TestFile entry {
        if here.path == self.target_path {
            self.saw_match = True;
        }
        visit [->:Hosts:->] else { disengage; };
    }
}

walker GuardedTestRunner {
    has recursive: bool = True;
    has has_positional: bool = False;
    has blocked: bool = False;
    has target_path: str = "";
    has load_successes: int = 0;
    has load_failures: int = 0;
    has saw_match: bool = False;

    can start with Root entry {
        visit [-->[?:PositionalTarget]];
        if self.recursive and self.has_positional {
            self.blocked = True;
            disengage;
        }
        visit [->:InMonorepo:->] else { disengage; };
    }

    can note with PositionalTarget entry {
        self.has_positional = True;
        self.target_path = here.path;
    }

    can run_pkg with Package entry {
        self.saw_match = False;
        visit [->:Hosts:->] else {
            self.load_failures += 1;
            visit [->:InMonorepo:->] else { disengage; };
            disengage;
        };
        if self.saw_match {
            self.load_successes += 1;
        } else {
            self.load_failures += 1;
        }
        visit [->:InMonorepo:->] else { disengage; };
    }

    can resolve with TestFile | PositionalTarget entry {
        if here.path == self.target_path {
            self.saw_match = True;
        }
        visit [->:Hosts:->] else { disengage; };
    }
}

with entry {
    target = PositionalTarget(path="test/a_test.dart", title="a_test.dart");
    pkg_a = Package(name="a", title="packages/a");
    pkg_b = Package(name="b", title="packages/b");
  root ++> target;
    root +>:InMonorepo:+> pkg_a +>:Hosts:+> TestFile(path="test/a_test.dart", title="a_test.dart");
    root +>:InMonorepo:+> pkg_b +>:Hosts:+> TestFile(path="test/b_test.dart", title="b_test.dart");

    buggy = BuggyRecursiveTest();
    root spawn buggy;
    print(f"buggy fan-out: {buggy.load_successes} pass, {buggy.load_failures} load errors");

    guarded = GuardedTestRunner(recursive=True);
    root spawn guarded;
    verdict = "blocked" if guarded.blocked else "ran";
    print(f"guarded runner: {verdict} (positional + recursive is invalid)");
}

