"""Local context engine: privacy-scoped assembly, derived-cache invalidation, and explainable routing."""

node ContextSource {
    has path: str = "";
    has tokens: int = 0;
    has is_sensitive: bool = False;
    has is_stale: bool = False;
    has available: bool = True;
}

node ContextBundle {
    has name: str = "";
    has token_budget: int = 8000;
}

node CacheEntry {
    has key: str = "";
    has valid: bool = True;
}

node RouteTarget {
    has provider: str = "";
    has capability: str = "";
    has pinned: bool = False;
    has allowed: bool = True;
    has deny_reason: str = "";
}

edge Provides { }
edge DerivedFrom { }

walker ContextAssembler {
    has included: int = 0;
    has excluded: int = 0;
    has tokens_used: int = 0;
    has budget_limit: int = 8000;

    can start with Root entry {
        print("=== Context assembly (privacy + token budget) ===");
        visit [-->[?:ContextBundle]] else { disengage; }
    }

    can budget with ContextBundle entry {
        self.budget_limit = here.token_budget;
        print(f"Bundle '{here.name}' budget: {here.token_budget} tokens");
        visit [->:Provides:->] else { disengage; }
    }

    can select with ContextSource entry {
        if here.is_sensitive {
            self.excluded += 1;
            print(f"[EXCLUDE] {here.path} — privacy boundary");
        } elif here.is_stale {
            self.excluded += 1;
            print(f"[EXCLUDE] {here.path} — stale worktree");
        } elif not here.available {
            self.excluded += 1;
            print(f"[EXCLUDE] {here.path} — unavailable");
        } elif self.tokens_used + here.tokens > self.budget_limit {
            self.excluded += 1;
            print(f"[EXCLUDE] {here.path} — token budget exhausted");
        } else {
            self.included += 1;
            self.tokens_used += here.tokens;
            print(f"[INCLUDE] {here.path} ({here.tokens} tok, total {self.tokens_used})");
        }
        disengage;
    }
}

walker CacheInvalidator {
    has invalidated: int = 0;

    can start with Root entry {
        print("=== Privacy/stale propagation into derived caches ===");
        visit [-->[?:ContextBundle]] else { disengage; }
    }

    can reach_bundle with ContextBundle entry {
        visit [->:Provides:->] else { disengage; }
    }

    can scan with ContextSource entry {
        if here.is_sensitive {
            cause = "privacy exclusion";
            print(f"[SCAN] {here.path} — {cause}");
            visit [<-:DerivedFrom:<-] else { disengage; }
        } elif here.is_stale {
            cause = "stale provenance";
            print(f"[SCAN] {here.path} — {cause}");
            visit [<-:DerivedFrom:<-] else { disengage; }
        } else {
            disengage;
        }
    }

    can purge with CacheEntry entry {
        if here.valid {
            here.valid = False;
            self.invalidated += 1;
            print(f"[INVALIDATE] cache '{here.key}'");
        }
        disengage;
    }
}

walker RouteExplainer {
    has selected: str = "";
    has explanation: str = "no-route: no pinned provider matched";

    can start with Root entry {
        print("=== Deterministic capability routing ===");
        visit [-->[?:RouteTarget]] else { disengage; }
    }

    can decide with RouteTarget entry {
        if self.selected != "" {
            disengage;
        }
        if here.pinned and here.allowed {
            self.selected = here.provider;
            self.explanation = f"pinned {here.capability} → {here.provider}";
            print(f"[ROUTE] {self.explanation}");
            disengage;
        } elif not here.allowed {
            print(f"[DENY] {here.provider} — {here.deny_reason}");
            visit [-->];
        } else {
            print(f"[SKIP] {here.provider} — not pinned");
            visit [-->];
        }
    }
}

with entry {
