"""Job-shop scheduling: unsound vs sound cycle guards on precedence graphs.

SwapAdjacentOps can introduce cycles in the disjunctive graph. The legacy
guard inferred acyclicity from a positive critical-path makespan; on cyclic
graphs that value is computed over only the reachable subgraph and can fall
below the known optimum. The sound fix rejects any move whose topological
walk does not visit every scheduled operation.
"""

node Schedule {
    has name: str = "";
    has op_count: int = 0;
    has bks: int = 0;
}

node Operation {
    has op_id: str = "";
    has duration: int = 0;
    has start_time: int = 0;
    has available: bool = True;
}

edge Precedes { }

walker UnsoundGuard {
    has makespan: int = 0;
    has visited: list[str] = [];
    has schedule_name: str = "";

    can start with Root entry {
        visit [-->];
    }

    can audit with Schedule entry {
        self.schedule_name = here.name;
        visit [-->];
    }

    can measure with Operation entry {
        if here.op_id in self.visited {
            visit [->:Precedes:->] else { disengage; };
        }
        self.visited += [here.op_id];
        finish = here.start_time + here.duration;
        candidate = finish if finish > self.makespan else self.makespan;
        self.makespan = candidate;
        visit [->:Precedes:->] else { disengage; };
    }

    can report with Schedule exit {
        if self.makespan > 0 {
            print(
                f"UnsoundGuard[{self.schedule_name}]: accepts move, "
                f"ms={self.makespan} (positive => assumed acyclic)"
            );
        }
    }
}

walker SoundGuard {
    has expected_ops: int = 0;
    has topo_count: int = 0;
    has makespan: int = 0;
    has on_path: list[str] = [];
    has schedule_name: str = "";
    has bks: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can audit with Schedule entry {
        self.schedule_name = here.name;
        self.expected_ops = here.op_count;
        self.bks = here.bks;
        visit [-->];
    }

    can topo with Operation entry {
        if here.op_id in self.on_path {
            self.topo_count = 0;
            disengage;
        }
        self.on_path += [here.op_id];
        self.topo_count += 1;
        finish = here.start_time + here.duration;
        candidate = finish if finish > self.makespan else self.makespan;
        self.makespan = candidate;
        visit [->:Precedes:->] else { disengage; };
    }

    can report with Schedule exit {
        rejected = False;
        final_ms = self.makespan;
        if self.topo_count != self.expected_ops {
            rejected = True;
            final_ms = 2147483647;
        }
        verdict = "REJECT cycle/incomplete topo" if rejected else "ACCEPT feasible";
        print(
            f"SoundGuard[{self.schedule_name}]: {verdict}, "
            f"topo={self.topo_count}/{self.expected_ops}, ms={final_ms}, "
            f"bks={self.bks}"
        );
        if (not rejected) and (final_ms < self.bks) {
            print(
                f"  warning: ms {final_ms} < bks {self.bks} would be "
                f"physically impossible on a feasible schedule"
            );
        }
    }
}

with entry {
    sched = Schedule(name="ta01-mini", op_count=3, bks=1231);
    op_a = Operation(op_id="A", duration=400, start_time=0);
    op_b = Operation(op_id="B", duration=300, start_time=400);
    op_c = Operation(op_id="C", duration=140, start_time=0);

    root ++> sched ++> op_a ++> op_b ++> op_c;
    op_a +>:Precedes:+> op_b;
    op_b +>:Precedes:+> op_c;
    op_c +>:Precedes:+> op_a;

    print(
        f"Disjunctive graph after bad SwapAdjacentOps move on {sched.name}; "
        f"known optimum bks={sched.bks}"
    );
    root spawn UnsoundGuard();
    root spawn SoundGuard();
}

"""Session digest store path: caller schema_version demotes decisions to raw_fragments."""

node EntityType {
    has type_name: str = "";
    has canonical_version: str = "";
}

node SchemaVersion {
    has version: str = "";
}

node FieldSpec {
    has field_name: str = "";
    has description: str = "";
}

node SessionDigest {
    has entity_id: str = "";
    has caller_schema_version: str = "";
    has decisions: list[str] = [];
    has topics: list[str] = [];
    has raw_fragment_keys: list[str] = [];
    has snapshot_has_decisions: bool = False;
}

edge CanonicalVersion { }
edge RegisteredVersion { }
edge DeclaresField { }
edge InstanceOf { }

walker FieldDeclaredProbe {
    has field_name: str = "";
    has declared: bool = False;

    can start with SchemaVersion entry {
        visit [->:DeclaresField:->];
        disengage;
    }

    can inspect with FieldSpec entry {
        if here.field_name == self.field_name {
            self.declared = True;
        }
    }
}

walker StoreAuditor {
    has use_canonical: bool = False;
    has label: str = "buggy";
    has registry_canonical: str = "1.4.0";

    can start with Root entry {
        visit [-->[?:SessionDigest]] else {
            visit [-->];
        };
    }

    can audit with SessionDigest entry {
        validation_version = here.caller_schema_version;
        if self.use_canonical {
            validation_version = self.registry_canonical;
        }
        print(
            f"[STORE/{self.label}] {here.entity_id}: "
            f"caller v{here.caller_schema_version}, "
            f"canonical v{self.registry_canonical}, "
            f"validating fields against v{validation_version}"
        );
        decisions_declared = False;
        for et in [here->:InstanceOf:->] {
            if et is EntityType {
                decisions_declared = self.probe_field_on_type(
                    et, validation_version, "decisions"
                );
            }
        }
        self.apply_store(here, validation_version, decisions_declared);
        visit [-->];
    }

    def probe_field_on_type(
        entity_type: EntityType, version_label: str, field_name: str
    ) -> bool {
        probe = FieldDeclaredProbe(field_name=field_name);
        for sv in [entity_type->:RegisteredVersion:->] {
            if sv is SchemaVersion {
                if sv.version == version_label {
                    sv spawn probe;
                    return probe.declared;
                }
            }
        }
        return False;
    }

    def apply_store(
        digest: SessionDigest, validation_version: str, decisions_declared: bool
    ) {
        if decisions_declared {
            digest.snapshot_has_decisions = len(digest.decisions) > 0;
            print(
                f"  decisions: declared in v{validation_version} "
                f"-> snapshot ({len(digest.decisions)} item(s))"
            );
        } else {
            if len(digest.decisions) > 0 {
                warn_msg = (
                    f"undeclared field 'decisions' "
                    f"(validated against v{validation_version}) -> raw_fragments"
                );
                print(f"  WARNING: {warn_msg}");
                digest.raw_fragment_keys.append("decisions");
                digest.snapshot_has_decisions = False;
            }
        }
    }
}

walker SnapshotReader {
    can start with Root entry {
        visit [-->[?:SessionDigest]] else {
            disengage;
        };
    }

    can read with SessionDigest entry {
        provenance = ["topics", "artifacts", "commitments"];
        if here.snapshot_has_decisions {
            provenance.append("decisions");
        }
        if "decisions" in here.raw_fragment_keys {
            print(
                f"[SNAPSHOT] {here.entity_id}: no 'decisions' key; "
                f"provenance={provenance}; "
                f"content stranded in raw_fragments={here.raw_fragment_keys}"
            );
        } else {
            print(
                f"[SNAPSHOT] {here.entity_id}: decisions visible; "
                f"provenance={provenance}"
            );
        }
        visit [-->];
    }
}

