}

"""Job-shop scheduling: unsound vs sound cycle guards on precedence graphs.

SwapAdjacentOps can introduce cycles in the disjunctive graph. The legacy
guard inferred acyclicity from a positive critical-path makespan; on cyclic
graphs that value is computed over only the reachable subgraph and can fall
below the known optimum. The sound fix rejects any move whose topological
sort cannot visit every scheduled operation.
"""

node Schedule {
    has name: str = "";
    has op_count: int = 0;
    has bks: int = 0;
}

node Operation {
    has op_id: str = "";
    has duration: int = 0;
    has start_time: int = 0;
    has available: bool = True;
    has in_deg: int = 0;
}

edge Precedes { }

walker UnsoundGuard {
    has makespan: int = 0;
    has seen: list[str] = [];
    has schedule_name: str = "";
    has bks: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can audit with Schedule entry {
        self.schedule_name = here.name;
        self.bks = here.bks;
        visit [-->[?:Operation]] else { disengage; };
        print(
            f"UnsoundGuard[{self.schedule_name}]: accepts move, "
            f"ms={self.makespan} (positive => assumed acyclic), "
            f"bks={self.bks}"
        );
        if self.makespan > 0 and self.makespan < self.bks {
            print(
                f"  warning: ms {self.makespan} < bks {self.bks} is "
                f"physically impossible on a feasible schedule"
            );
        }
    }

    can measure with Operation entry {
        if here.op_id in self.seen {
            disengage;
        }
        self.seen += [here.op_id];
        finish = here.start_time + here.duration;
        candidate = finish if finish > self.makespan else self.makespan;
        self.makespan = candidate;
        visit [->:Precedes:->] else { disengage; };
    }
}

walker SoundGuard {
    has expected_ops: int = 0;
    has topo_count: int = 0;
    has makespan: int = 0;
    has schedule_name: str = "";
    has bks: int = 0;
    has ids: list[str] = [];
    has durations: list[int] = [];
    has starts: list[int] = [];
    has indegs: list[int] = [];

    can start with Root entry {
        visit [-->];
    }

    can audit with Schedule entry {
        self.schedule_name = here.name;
        self.expected_ops = here.op_count;
        self.bks = here.bks;
        visit [-->[?:Operation]] else { disengage; };
        queue: list[int] = [];
        for (i, deg) in enumerate(self.indegs) {
            if deg == 0 {
                queue += [i];
            }
        }
        rem = self.indegs;
        sorted_n = 0;
        ms = 0;
        while len(queue) > 0 {
            idx = queue[0];
            queue = queue[1:];
            sorted_n += 1;
            finish = self.starts[idx] + self.durations[idx];
            ms = finish if finish > ms else ms;
            for (j, pred_deg) in enumerate(rem) {
                if pred_deg > 0 {
                    rem[j] = pred_deg - 1;
                    if rem[j] == 0 {
                        queue += [j];
                    }
                }
            }
        }
        self.topo_count = sorted_n;
        self.makespan = ms;
        rejected = self.topo_count != self.expected_ops;
        final_ms = 2147483647 if rejected else self.makespan;
        verdict = "REJECT cycle/incomplete topo" if rejected else "ACCEPT feasible";
        print(
            f"SoundGuard[{self.schedule_name}]: {verdict}, "
            f"topo={self.topo_count}/{self.expected_ops}, ms={final_ms}, "
            f"bks={self.bks}"
        );
    }

    can gather with Operation entry {
        if here.op_id in self.ids {
            disengage;
        }
        self.ids += [here.op_id];
        self.durations += [here.duration];
        self.starts += [here.start_time];
        self.indegs += [here.in_deg];
        visit [->:Precedes:->] else { disengage; };
    }
}

