"""Sandman standalone workflow: compose implementation, review cycle, and merge without managed lifecycle authority."""

node WorkItem {
    has title: str = "";
    has implementation_done: bool = False;
}

node PullRequest {
    has pr_number: int = 0;
    has head_sha: str = "";
    has is_open: bool = True;
    has approved: bool = False;
}

node CIStatus {
    has status: str = "pending";
    has dirty: bool = False;
}

node ReviewTrigger {
    has command_prefix: str = "";
    has comment_id: int = 0;
    has confirmed: bool = False;
}

edge WorkflowStep {
    has skill_name: str = "";
}

edge RequiresCI { }

edge TriggersReview { }

edge InvalidatesApproval { }

walker SandmanRun {
    has standalone: bool = True;

    can orchestrate with Root entry {
        mode = "standalone" if self.standalone else "managed";
        print(f"sandman-run: starting {mode} workflow");
        visit [-->];
    }

    can implement with WorkItem entry {
        if not here.implementation_done {
            print(f"  implement: {here.title}");
            here.implementation_done = True;
        }
        visit [->:WorkflowStep:->];
    }

    can handoff with PullRequest entry {
        print(f"  PR #{here.pr_number} ready at head {here.head_sha}");
        visit [-->] else { disengage; };
    }
}

walker ReviewCycle {
    has request_posted: bool = False;
    has cycle_count: int = 0;
    has max_cycles: int = 3;
    has visited_prs: list[int] = [];
    has current_pr: PullRequest | None = None;
    has ci_ready: bool = False;

    can start_cycle with PullRequest entry {
        if here.pr_number in self.visited_prs {
            print(f"  cycle guard: PR #{here.pr_number} already visited");
            disengage;
        }
        self.visited_prs.append(here.pr_number);
        self.current_pr = here;
        if not here.is_open {
            print(f"  PR #{here.pr_number} is closed; disengaging");
            disengage;
        }
        print(f"review-cycle: observing PR #{here.pr_number} head={here.head_sha}");
        if here.approved {
            visit [->:InvalidatesApproval:->];
        }
        visit [->:RequiresCI:->];
    }

    can invalidate_stale with ReviewTrigger entry {
        if not here.confirmed and self.current_pr is not None and self.current_pr.approved {
            self.current_pr.approved = False;
            print(f"  stale approval invalidated on PR #{self.current_pr.pr_number}");
        }
        disengage;
    }

    can wait_ci with CIStatus entry {
        if here.dirty {
            print("  CI dirty/conflict; back-merge required");
            disengage;
        }
        ci_label = "passed" if here.status == "passed" else "waiting";
        print(f"  CI status: {ci_label}");
        if here.status != "passed" {
            disengage;
        }
        self.ci_ready = True;
        if self.current_pr is not None {
            self.current_pr spawn self;
        }
        disengage;
    }

    can deliver_request with PullRequest entry {
        if not self.ci_ready {
            disengage;
        }
        if self.cycle_count >= self.max_cycles {
            print(f"  max review cycles ({self.max_cycles}) reached");
            disengage;
        }
        if not self.request_posted {
            print("  invoking sandman-review-request for trigger delivery");
            self.request_posted = True;
            visit [->:TriggersReview:->];
        }
        visit [-->] else { disengage; };
    }

    can observe_trigger with ReviewTrigger entry {
        if here.confirmed {
            print(f"  confirmed trigger: {here.command_prefix} id={here.comment_id}");
            self.cycle_count += 1;
            self.request_posted = False;
            self.ci_ready = False;
        } else {
            print("  delivery refused: trigger not confirmed");
            disengage;
        }
        if self.current_pr is not None {
            self.current_pr spawn self;
        }
        disengage;
    }

    can merge_gate with PullRequest entry {
        if here.approved and here.is_open {
            print(f"  merge gate: PR #{here.pr_number} approved and mergeable");
        } else {
            approval_label = "approved" if here.approved else "pending";
            print(f"  merge gate blocked: approval={approval_label}");
        }
        disengage;
    }
}

walker ReviewRequestDelivery {
    has delivery_confirmed: bool = False;

    can start with Root entry {
        visit [-->];
    }

    can deliver with ReviewTrigger entry {
        if here.confirmed {
            print(f"sandman-review-request: confirmed {here.command_prefix} id={here.comment_id}");
            self.delivery_confirmed = True;
        } else {
            print("sandman-review-request: delivery refused");
            disengage;
        }
        visit [-->] else { disengage; };
    }
}

