"""Mirror-minimum ptkdb hooks: inventory stable hook sites and mirror bounded DAP events."""

node Debuggee {
    has name: str = "";
    has stopped: bool = False;
    has terminal: bool = False;
}

node HookSite {
    has symbol: str = "";
    has path_digest: str = "";
    has timing: str = "";
    has file_line: str = "";
}

node PeerSession {
    has endpoint: str = "";
    has authenticated: bool = False;
    has session_id: str = "";
    has protocol_version: str = "";
}

node TraceStep {
    has phase: str = "";
    has payload: str = "";
}

edge PeerBound { }
edge RegistersAt { has anchor: str = ""; }

walker HookInventory {
    has recorded: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can on_debuggee with Debuggee entry {
        visit [->:RegistersAt:->];
    }

    can on_hook with HookSite entry {
        row = f"{here.path_digest}:{here.symbol}:{here.timing}";
        self.recorded.append(row);
        visit [-->] else { disengage; }
    }
}

walker MirrorEmitter {
    has stopped_events: int = 0;
    has output_events: int = 0;
    has terminal_events: int = 0;
    has suppressed_nested: int = 0;
    has rejected_late: int = 0;
    has events_live: bool = False;
    has dbg_stopped: bool = False;
    has dbg_terminal: bool = False;

    can start with Root entry {
        visit [-->];
    }

    can on_peer with PeerSession entry {
        if here.authenticated and here.session_id != "" {
            self.events_live = True;
        } else {
            disengage;
        }
        visit [-->] else { disengage; }
    }

    can on_debuggee with Debuggee entry {
        self.dbg_stopped = here.stopped;
        self.dbg_terminal = here.terminal;
        visit [-->] else { disengage; }
    }

    can on_step with TraceStep entry {
        if not self.events_live {
            disengage;
        }
        if self.dbg_terminal {
            self.rejected_late += 1;
            visit [-->] else { disengage; }
        }
        phase = here.phase;
        if phase == "stop" {
            if self.dbg_stopped {
                self.suppressed_nested += 1;
            } else {
                self.stopped_events += 1;
                self.dbg_stopped = True;
            }
        } else if phase == "output" {
            self.output_events += 1;
        } else if phase == "resume" {
            self.dbg_stopped = False;
        } else if phase == "terminal" {
            self.terminal_events += 1;
            self.dbg_terminal = True;
        }
        visit [-->] else { disengage; }
    }
}

