"""Daily student attendance: class roster walk, mark tally, closure-void days."""

node ClassUnit {
    has standard_level: str = "";
    has academic_year: str = "";
    has campus: str = "";
}

node Student {
    has name: str = "";
}

node SchoolDay {
    has date: str = "";
    has closed: bool = False;
}

node Attendance {
    has status: str = "";
    has marked_by: str = "";
}

edge ClassRoster { }

edge HasMark { }

edge OnDay { }

walker AttendanceAuditor {
    has class_label: str = "";
    has pending_status: str = "";
    has cur_present: int = 0;
    has cur_absent: int = 0;
    has cur_voided: int = 0;
    has total_present: int = 0;
    has total_absent: int = 0;
    has total_voided: int = 0;

    can start with Root entry {
        print("=== Daily attendance audit (late=present, closures void marks) ===");
        visit [-->];
    }

    can audit_class with ClassUnit entry {
        self.class_label = f"{here.standard_level} {here.academic_year} @ {here.campus}";
        print(f"Register: {self.class_label}");
        visit [->:ClassRoster:->] else { disengage; };
    }

    can tally_student with Student entry {
        self.cur_present = 0;
        self.cur_absent = 0;
        self.cur_voided = 0;
        visit [->:HasMark:->] else { disengage; };
        counted = self.cur_present + self.cur_absent;
        if counted > 0 {
            pct = (self.cur_present * 100) / counted;
            print(f"  {here.name}: {self.cur_present}/{counted} present ({pct}%)");
        } else {
            void_suffix = f", {self.cur_voided} voided" if self.cur_voided > 0 else "";
            print(f"  {here.name}: no countable marks{void_suffix}");
        }
        self.total_present += self.cur_present;
        self.total_absent += self.cur_absent;
        self.total_voided += self.cur_voided;
    }

    can score_mark with Attendance entry {
        self.pending_status = here.status;
        visit [->:OnDay:->] else { disengage; };
    }

    can day_gate with SchoolDay entry {
        if here.closed {
            self.cur_voided += 1;
            print(f"    [VOID] {self.pending_status} on {here.date} (closure)");
        } elif self.pending_status == "present" or self.pending_status == "late" {
            self.cur_present += 1;
        } else {
            self.cur_absent += 1;
        }
        disengage;
    }
}

