"""Mirror-minimum ptkdb hooks: inventory stable hook sites and mirror bounded DAP events."""

node Debuggee {
    has name: str = "";
    has stopped: bool = False;
    has terminal: bool = False;
}

node HookSite {
    has symbol: str = "";
    has path_digest: str = "";
    has timing: str = "";
    has file_line: str = "";
}

node PeerSession {
    has endpoint: str = "";
    has authenticated: bool = False;
    has session_id: str = "";
    has protocol_version: str = "";
}

node TraceStep {
    has phase: str = "";
    has payload: str = "";
}

edge PeerBound { }
edge RegistersAt { has anchor: str = ""; }

walker HookInventory {
    has recorded: list[str] = [];

    can start with Root entry {
        print("inventory: mapping pinned ptkdb hook sites");
        visit [-->];
    }

    can relay with PeerSession entry {
        visit [-->];
    }

    can on_debuggee with Debuggee entry {
        visit [->:RegistersAt:->];
    }

    can on_hook with HookSite entry {
        row = f"{here.path_digest}:{here.symbol}:{here.timing}";
        self.recorded.append(row);
        print(f"  hook {row} @ {here.file_line}");
        visit [-->] else { disengage; }
    }
}

walker MirrorEmitter {
    has stopped_events: int = 0;
    has output_events: int = 0;
    has terminal_events: int = 0;
    has suppressed_nested: int = 0;
    has rejected_late: int = 0;
    has events_live: bool = False;
    has dbg_stopped: bool = False;
    has dbg_terminal: bool = False;

    can start with Root entry {
        print("mirror: awaiting peer/hello rendezvous");
        visit [-->];
    }

    can on_peer with PeerSession entry {
        if here.authenticated and here.session_id != "" {
            self.events_live = True;
            print(f"  peer/hello ok session={here.session_id} v={here.protocol_version}");
        } else {
            print("  peer/hello rejected — disengaging");
            disengage;
        }
        visit [-->] else { disengage; }
    }

    can on_debuggee with Debuggee entry {
        self.dbg_stopped = here.stopped;
        self.dbg_terminal = here.terminal;
        print(f"  debuggee bound: {here.name}");
        visit [-->] else { disengage; }
    }

    can on_step with TraceStep entry {
        if not self.events_live {
            disengage;
        }
        if self.dbg_terminal {
            self.rejected_late += 1;
            print(f"  REJECTED late {here.phase}: {here.payload}");
        } elif here.phase == "stop" {
            if self.dbg_stopped {
                self.suppressed_nested += 1;
                print(f"  SUPPRESSED nested stop: {here.payload}");
            } else {
                self.stopped_events += 1;
                self.dbg_stopped = True;
                print(f"  STOPPED {here.payload}");
            }
        } elif here.phase == "output" {
            self.output_events += 1;
            print(f"  OUTPUT {here.payload}");
        } elif here.phase == "resume" {
            self.dbg_stopped = False;
            print(f"  RESUME {here.payload}");
        } elif here.phase == "terminal" {
            self.terminal_events += 1;
            self.dbg_terminal = True;
            print(f"  TERMINAL {here.payload}");
        }
        visit [-->] else { disengage; }
    }
}

with entry {
    peer = PeerSession(
        endpoint="127.0.0.1:4711",
        authenticated=True,
        session_id="sess-mirror-1",
        protocol_version="1.0"
    );
    dbg = Debuggee(name="Devel-ptkdb-1.1091");
    hook_db = HookSite(
        symbol="DB::DB",
        path_digest="ptkdb/DB.pm#abc",
