"""Architecture layer DAG enforcement: opt-in cycle detection on declared dependency constraints."""

node ArchitectureLayer {
    has name: str = "";
    has tier: int = 0;
    has available: bool = True;
}

node ArchitectureContract {
    has consumer_name: str = "";
    has require_acyclic: bool = False;
    has title: str = "";
}

edge LayerDepends { }
edge Governs { }

walker CycleAuditor {
    has consumer_label: str = "";
    has cycle_found: bool = False;
    has cycle_diagnostic: str = "";
    has on_stack: list[str] = [];
    has finished: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can audit with ArchitectureContract entry {
        self.consumer_label = here.consumer_name;
        if not here.require_acyclic {
            print(f"SKIP: {here.consumer_name} — DAG enforcement not enabled");
            disengage;
        }
        print(f"CHECK: DAG enforcement for {here.consumer_name}");
        visit [->:Governs:->] else { disengage; };
    }

    can scan with ArchitectureLayer entry {
        if self.cycle_found {
            disengage;
        }
        if here.name in self.finished {
            disengage;
        }
        if here.name in self.on_stack {
            self.cycle_found = True;
            path_parts = "";
            for (i, n) in enumerate(self.on_stack) {
                path_parts = f"{path_parts}{n} -> ";
            }
            self.cycle_diagnostic = f"{path_parts}{here.name}";
            print(f"DIAGNOSTIC cycle path: {self.cycle_diagnostic}");
            disengage;
        }
        self.on_stack.append(here.name);
        visit [->:LayerDepends:->] else { disengage; };
        self.finished.append(here.name);
        trimmed = [];
        limit = len(self.on_stack) - 1;
        for (i, n) in enumerate(self.on_stack) {
            if i < limit {
                trimmed.append(n);
            }
        }
        self.on_stack = trimmed;
    }
}

