    legacy_contract +>:Governs:+> legacy_a;
    legacy_contract +>:Governs:+> legacy_b;
    root ++> legacy_contract;

    print("=== legacy contract without DAG opt-in ===");
    legacy_auditor = CycleAuditor();
    legacy_contract spawn legacy_auditor;
    if legacy_auditor.cycle_found {
        print(f"FAIL {legacy_auditor.consumer_label}: {legacy_auditor.cycle_diagnostic}");
    } else {
        print(f"PASS {legacy_auditor.consumer_label}: cycle analysis not required");
    }
}

