"""Forge run records, schema 0.2 migration, provenance capture, and atomic draft lifecycle."""

node SchemaVersion {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has version: str = "";
    has major: int = 0;
    has minor: int = 0;
}

node ForgeRun {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has run_id: str = "";
    has status: str = "pending";
    has provider: str = "";
    has model: str = "";
    has cost_summary: str = "";
    has diagnostics: str = "";
    has target_schema: str = "0.2.0";
}

node PackDraft {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has draft_id: str = "";
    has schema_version: str = "0.1.0";
    has validated: bool = False;
    has in_library: bool = False;
    has discarded: bool = False;
}

node PackQuestion {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has content_hash: str = "";
    has prompt: str = "";
    has includes_gen_metadata: bool = False;
}

edge MigratesTo { }

edge Produced { }

edge Contains { }

edge ImportPath {
    has accepted: bool = False;
}

walker MigrationGuard {
    has seen: list[str] = [];
    has forward_ok: bool = True;
    has prior_major: int = -1;
    has prior_minor: int = -1;

    can start with Root entry {
        print("MigrationGuard: checking forward-only schema chain (D-014)");
        visit [->:MigratesTo:->] else { disengage; };
    }

    can step with SchemaVersion entry {
        if here.version in self.seen {
            print(f"FAIL: cycle detected at schema {here.version}");
            self.forward_ok = False;
            disengage;
        }
        self.seen.append(here.version);
        if self.prior_major >= 0 {
            if here.major < self.prior_major {
                print(
                    f"FAIL: downgrade {self.prior_major}.{self.prior_minor} "
                    f"-> {here.major}.{here.minor}"
                );
                self.forward_ok = False;
                disengage;
            }
            if here.major == self.prior_major and here.minor < self.prior_minor {
                print(
                    f"FAIL: downgrade {self.prior_major}.{self.prior_minor} "
                    f"-> {here.major}.{here.minor}"
                );
                self.forward_ok = False;
                disengage;
            }
        }
        self.prior_major = here.major;
        self.prior_minor = here.minor;
        print(f"  schema {here.version} OK");
        visit [->:MigratesTo:->] else { disengage; };
    }
}

walker ForgeAuditor {
    has provenance_clean: bool = True;
    has d007_ok: bool = True;
    has drafts_in_library: int = 0;
    has drafts_pending: int = 0;

    can start with Root entry {
        print("ForgeAuditor: run records, provenance, draft visibility");
        visit [-->];
    }

    can inspect_run with ForgeRun entry {
        leak = "api_key=" in here.diagnostics;
        if leak {
            print(f"FAIL: credentials in run {here.run_id} diagnostics");
            self.provenance_clean = False;
        } else {
            print(
                f"run {here.run_id} [{here.status}] "
                f"{here.provider}/{here.model} cost={here.cost_summary}"
            );
        }
        visit [->:Produced:->] else { visit [-->]; };
    }

    can inspect_draft with PackDraft entry {
        if here.discarded {
            print(f"draft {here.draft_id} discarded — not library-visible");
            visit [->:Contains:->] else { disengage; };
        }
        if here.in_library {
            self.drafts_in_library += 1;
            print(f"draft {here.draft_id} visible in library (schema {here.schema_version})");
        } else {
            self.drafts_pending += 1;
            label = "validated" if here.validated else "unvalidated";
            print(f"draft {here.draft_id} hidden from library ({label})");
        }
        visit [->:Contains:->] else { disengage; };
    }

    can audit_question with PackQuestion entry {
        if here.includes_gen_metadata {
            print(f"D-007 FAIL: gen metadata touched hash {here.content_hash}");
            self.d007_ok = False;
        } else {
            print(f"  Q hash={here.content_hash} prompt={here.prompt}");
        }
        visit [-->];
    }
}

walker DiscardCleaner {
    has runs_scanned: int = 0;
    has drafts_purged: int = 0;
    has diagnostics_kept: int = 0;

    can start with Root entry {
        print("DiscardCleaner: crash/cancel leaves recoverable draft or diagnostics only");
        visit [-->];
    }

    can handle_run with ForgeRun entry {
        self.runs_scanned += 1;
        terminal = here.status == "cancelled" or here.status == "crashed";
        if terminal {
            print(f"terminal run {here.run_id} status={here.status}");
            visit [->:Produced:->] else {
                print(f"  no draft — keeping diagnostics: {here.diagnostics}");
                self.diagnostics_kept += 1;
                disengage;
            };
        } else {
            visit [-->];
        }
    }

    can purge_draft with PackDraft entry {
        if here.validated and not here.discarded {
            print(f"  recoverable draft {here.draft_id} kept (validated)");
            disengage;
        }
        here.discarded = True;
        here.in_library = False;
        here.available = False;
        self.drafts_purged += 1;
        print(f"  purged junk draft {here.draft_id}");
        disengage;
    }
}

walker LibraryImporter {
    has imported: int = 0;
    has rejected: int = 0;

    can start with Root entry {
        print("LibraryImporter: atomic add-to-library via ImportPath");
        visit [->:ImportPath:->] else { disengage; };
    }

    can accept with PackDraft entry {
        if not here.validated {
            print(f"REJECT draft {here.draft_id}: not validated");
            self.rejected += 1;
            disengage;
        }
        if here.discarded {
            print(f"REJECT draft {here.draft_id}: discarded");
            self.rejected += 1;
            disengage;
        }
        here.in_library = True;
        self.imported += 1;
        print(f"IMPORTED draft {here.draft_id} schema {here.schema_version}");
        disengage;
    }
}

with entry {
    s01 = SchemaVersion(version="0.1.0", major=0, minor=1, title="legacy");
