walker MigrationGuard {
    has seen: list[str] = [];
    has forward_ok: bool = True;
    has prior_major: int = -1;
    has prior_minor: int = -1;

    can start with Root entry {
        print("MigrationGuard: checking forward-only schema chain (D-014)");
        visit [->:MigratesTo:->] else { disengage; };
    }

    can step with SchemaVersion entry {
        if here.version in self.seen {
            print(f"FAIL: cycle detected at schema {here.version}");
            self.forward_ok = False;
            disengage;
        }
        self.seen.append(here.version);
        if self.prior_major >= 0 {
            if here.major < self.prior_major {
                print(
                    f"FAIL: downgrade {self.prior_major}.{self.prior_minor} "
                    f"-> {here.major}.{here.minor}"
                );
                self.forward_ok = False;
                disengage;
            }
            if here.major == self.prior_major and here.minor < self.prior_minor {
                print(
                    f"FAIL: downgrade {self.prior_major}.{self.prior_minor} "
                    f"-> {here.major}.{here.minor}"
                );
                self.forward_ok = False;
                disengage;
            }
        }
        self.prior_major = here.major;
        self.prior_minor = here.minor;
        print(f"  schema {here.version} OK");
        visit [->:MigratesTo:->] else { disengage; };
    }
