"""Compiler interprocedural: compose callable semantics across bounded project call graphs."""

node Callable {
    has name: str = "";
    has result_fact: str = "";
    has effect_fact: str = "";
    has summary_ready: bool = False;
    has stale: bool = False;
}

edge Calls {
    has site_label: str = "";
}

walker Composer {
    has depth: int = 0;
    has max_depth: int = 4;
    has trail: str = "";
    has composed: int = 0;

    can start with Root entry {
        print("--- bounded interprocedural composition ---");
        visit [-->];
    }

    can compose with Callable entry {
        if here.stale {
            print(f"[STALE] skip composition at {here.name}");
            disengage;
        }
        frame = f"|{here.name}|";
        if self.trail.find(frame) >= 0 {
            widened_result = f"widened_scc({here.result_fact})";
            here.result_fact = widened_result;
            here.summary_ready = True;
            print(f"[SCC] monotone widen {here.name}: {widened_result}");
            disengage;
        }
        if self.depth >= self.max_depth {
            capped_result = f"bounded({here.result_fact})";
            here.result_fact = capped_result;
            here.summary_ready = True;
            print(f"[DEPTH] resource cap {here.name}: {capped_result}");
            disengage;
        }
        saved_trail = self.trail;
        saved_depth = self.depth;
        self.trail = f"{self.trail}{frame}";
        self.depth = saved_depth + 1;

        visit [->:Calls:->] else { };

        composed_result = f"compose({here.name}|{here.result_fact})";
        composed_effect = f"merge_fx({here.name}|{here.effect_fact})";
        here.result_fact = composed_result;
        here.effect_fact = composed_effect;
        here.summary_ready = True;
        self.composed += 1;
        print(
            f"[COMPOSED] {here.name} @ depth {saved_depth} "
            f"result={composed_result} effect={composed_effect}"
        );

        self.trail = saved_trail;
        self.depth = saved_depth;
        visit [-->];
    }
}

walker Invalidator {
    has origin: str = "";

    can start with Callable entry {
        print(f"[MUTATION] callee {here.name} summary changed");
        visit [<--:Calls:<--] else { disengage; };
    }

    can ripple with Callable entry {
        here.stale = True;
        print(f"[INVALIDATE] caller {here.name} summary stale via {self.origin}");
        visit [<--:Calls:<--] else { disengage; };
    }
}

