"""Compiler interprocedural: compose callable summaries across a bounded call graph and ripple callee-only invalidation to callers."""

node CallGraph {
    has project: str = "";
    has max_depth: int = 6;
}

node Callable {
    has name: str = "";
    has returns: str = "void";
    has effects: str = "none";
    has exact: bool = True;
    has stale: bool = False;
    has composed: bool = False;
}

