    has site: str = "";
}

walker Composer {
    has depth: int = 0;
    has limit: int = 6;
    has stack: list[str] = [];

    can start with Root entry {
        print("=== Bounded callable semantic composition ===");
        visit [-->] else { disengage; };
    }

    can begin with CallGraph entry {
        self.limit = here.max_depth;
        print(f"horizon={here.project} depth_bound={self.limit}");
        visit [-->] else { disengage; };
    }

    can compose with Callable entry {
        if here.name in self.stack {
            print(f"[CYCLE] residual summary at {here.name} (monotone widen)");
            visit [-->] else { disengage; };
        } elif self.depth >= self.limit {
            print(f"[REFUSE] depth cap at {here.name}");
            visit [-->] else { disengage; };
        } else {
            self.stack.append(here.name);
            self.depth += 1;
            visit [->:Calls:->] else {
                note = 0;
            };
            facet = "EXACT" if here.exact else "BOUNDARY";
            print(f"[COMPOSE] {here.name} {facet} returns={here.returns} effects={here.effects}");
            here.composed = True;
            here.stale = False;
            self.depth -= 1;
            popped = self.stack.pop();
            visit [-->] else { disengage; };
        }
    }
}

