    can start with Callable entry {
        print(f"=== Callee-only invalidation seed: {here.name} ===");
        visit [<--:Calls:--] else {
            print("=== Invalidation frontier empty ===");
            disengage;
        };
    }

    can ripple with Callable entry {
        here.stale = True;
        here.composed = False;
        print(f"[STALE] caller {here.name} must recompose");
        visit [<--:Calls:--] else { disengage; };
    }
}

