"""Recursive call-component closure: bounded monotone fixed-point over callable summary facets."""

node FacetCarrier {
    has reads: list[str] = [];
    has writes: list[str] = [];
    has effects: list[str] = [];

    def join_places(acc: list[str], more: list[str]) -> list[str] {
        out: list[str] = [];
        for p in acc {
            if p not in out {
                out.append(p);
            }
        }
        for p in more {
            if p not in out {
                out.append(p);
            }
        }
        return out;
    }
}

node CallComponent {
    has component_id: str = "";
    has max_rounds: int = 10;
}

node Callable(FacetCarrier) {
    has name: str = "";
    has local_reads: list[str] = [];
    has local_writes: list[str] = [];
    has local_effects: list[str] = [];

    def reset_to_local() {
        self.reads = self.local_reads;
        self.writes = self.local_writes;
        self.effects = self.local_effects;
    }

    def absorb_summary(r: list[str], w: list[str], e: list[str]) -> bool {
        nr = self.join_places(self.reads, r);
        nw = self.join_places(self.writes, w);
        ne = self.join_places(self.effects, e);
        changed = (nr != self.reads) or (nw != self.writes) or (ne != self.effects);
        self.reads = nr;
        self.writes = nw;
        self.effects = ne;
        return changed;
    }
}

node ExternalSummary(FacetCarrier) {
    has name: str = "";
}

edge InternalCall {
    has call_site: str = "";
}

edge OutgoingCall {
    has call_site: str = "";
}

walker ClosureSolver {
    has round: int = 0;
    has max_rounds: int = 10;
    has round_changed: bool = False;
    has status: str = "running";
    has caller: Callable | None = None;
    has buf_reads: list[str] = [];
    has buf_writes: list[str] = [];
    has buf_effects: list[str] = [];

    can start with Root entry {
        visit [-->] else { disengage; };
    }

    can solve with CallComponent entry {
        self.max_rounds = here.max_rounds;
        print(f"=== recursive_component_semantic_closure.v1 :: {here.component_id} ===");
        self.round = 1;
        self.round_changed = False;
        visit [-->] else { disengage; };
    }

    can compose with Callable entry {
        self.caller = here;
        self.buf_reads = [];
        self.buf_writes = [];
        self.buf_effects = [];
        visit [->:OutgoingCall:->] else {
            visit [->:InternalCall:->] else {
                if self.caller is not None {
                    ch = self.caller.absorb_summary(
                        self.buf_reads, self.buf_writes, self.buf_effects
                    );
                    if ch {
                        self.round_changed = True;
                    }
                }
                visit [-->] else {
                    if self.round_changed {
                        visit [<--];
                        visit [<--];
                        visit [<--];
                        next_round = self.round + 1;
                        self.round = next_round;
                        if self.round > self.max_rounds {
                            self.status = "bounded_conservative";
                            print(f"STATUS {self.status} policy cap {self.max_rounds} rounds");
                            self.report_packet();
                            disengage;
                        }
                        self.round_changed = False;
                        visit [-->] else { disengage; };
                    } else {
                        self.status = "exact";
                        print(f"STATUS {self.status} converged in {self.round} rounds");
                        self.report_packet();
                        disengage;
                    };
                };
            };
        };
    }

    can pull with Callable | ExternalSummary entry {
        if self.caller is not None {
            self.buf_reads = self.caller.join_places(self.buf_reads, here.reads);
            self.buf_writes = self.caller.join_places(self.buf_writes, here.writes);
            self.buf_effects = self.caller.join_places(self.buf_effects, here.effects);
        }
        disengage;
    }

    def report_packet() {
        print(f"rounds={self.round} status={self.status}");
        for label in ["f0", "f1", "f2"] {
            print(f"  member {label} pending facet dump");
        }
    }
}

