"""Codewiki callers accuracy: buggy reverse call traversal, collapsed call sites, and cascade edge loss on re-index."""

node SourceFile {
    has path: str = "";
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

node Function {
    has name: str = "";
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

edge Defines { }

edge Calls {
    has line: int = 0;
}

walker BuggyCallers {
    has target_name: str = "";
    has max_depth: int = 2;
    has depth: int = 0;
    has seen: list[str] = [];
    has rows: int = 0;

    can start with Function entry {
        self.target_name = here.name;
        self.seen.append(here.name);
        print(f"Buggy callers of {here.name} (depth<={self.max_depth}):");
        visit [<--:Calls:--] else {
            print("  (none)");
            disengage;
        }
    }

    can climb with Function entry {
        if self.depth >= self.max_depth {
            visit [<--:Calls:--] else { disengage; }
        } else {
            caller = here.name;
            if caller in self.seen {
                visit [<--:Calls:--] else { disengage; }
            } else {
                self.seen.append(caller);
                print(f"  {caller} --[calls]--> {self.target_name}");
                self.rows += 1;
                next_depth = self.depth + 1;
                self.depth = next_depth;
                visit [<--:Calls:--] else { disengage; }
                self.depth = next_depth - 1;
            }
        }
    }
}

walker AccurateCallers {
    has target_name: str = "";
    has max_depth: int = 2;
    has depth: int = 0;
    has on_path: list[str] = [];
    has emitted: list[str] = [];
    has rows: int = 0;

    can start with Function entry {
        self.target_name = here.name;
        print(f"Accurate callers of {here.name} (depth<={self.max_depth}):");
        visit [<--:Calls:--] else {
            print("  (none)");
            disengage;
        }
    }

    can climb with Function entry {
        if self.depth >= self.max_depth {
            visit [<--:Calls:--] else { disengage; }
        } else {
            caller = here.name;
            if caller in self.on_path {
                disengage;
            } else {
                self.on_path.append(caller);
                hop_label = f"{self.depth + 1}-hop";
                site_key = f"{caller}->{self.target_name}@{hop_label}";
                if site_key not in self.emitted {
                    self.emitted.append(site_key);
                    print(f"  [{hop_label}] {caller} --[calls]--> {self.target_name}");
                    self.rows += 1;
                }
                next_depth = self.depth + 1;
                self.depth = next_depth;
                visit [<--:Calls:--] else { disengage; }
                self.depth = next_depth - 1;
                _ = self.on_path.pop();
            }
        }
    }
}

walker CallSiteCounter {
    has target_name: str = "";
    has sites: int = 0;

    can start with Function entry {
        self.target_name = here.name;
        visit [->:Calls:->] else { disengage; }
    }

    can count with Function entry {
        if here.name == self.target_name {
            self.sites += 1;
        }
        visit [->:Calls:->] else { disengage; }
    }
}

walker ReIndexer {
    has purged: int = 0;

    can start with SourceFile entry {
        print(f"Re-index {here.path}: delete defined symbols (CASCADE incoming edges)");
        visit [-->:Defines:--] else { disengage; }
    }

    can purge with Function entry {
        self.purged += 1;
        del here;
        disengage;
    }
}

with entry {
    api = SourceFile(path="api.ts", title="api.ts");
    app = SourceFile(path="app.ts", title="app.ts");

    handler = Function(name="handler", title="handler");
    main_fn = Function(name="main", title="main");
