    print("=== Self-recursive symbol: callee seeded into visited set ===");
    helper spawn BuggyCallers(max_depth=1);

    print("");
    print("=== Call-site recall before re-index ===");
    probe = CallSiteCounter(target_name="handler");
    main_fn spawn probe;
    print(f"  main -> handler edges remaining: {probe.sites}");

