"""Task domain model: dependencies as typed edges with validation, cycle detection, and consistent serialization."""

node Task {
    has task_id: str = "";
    has title: str = "";
    has priority: int = 0;
    has assignee: str = "";
    has attempt_count: int = 0;
    has timeout_seconds: int = 0;
    has status: str = "pending";
    has acceptance_criteria: list[str] = [];
}

edge DependsOn { }

walker SelfDepGuard {
    has rejected: list[str] = [];
    has checking_for: str = "";

    can audit with Root entry {
        visit [-->];
    }

    can validate with Task entry {
        if self.checking_for != "" {
            if here.task_id == self.checking_for {
                self.rejected.append(here.task_id);
            }
            disengage;
        }
        self.checking_for = here.task_id;
        visit [->:DependsOn:->] else {
            self.checking_for = "";
            visit [-->];
        };
    }
}

walker CycleGuard {
    has stack: list[str] = [];
    has cycle_found: bool = False;
    has cycle_detail: str = "";

    can probe with Root entry {
        visit [-->];
    }

    can walk with Task entry {
        if here.task_id in self.stack {
            self.cycle_found = True;
            self.cycle_detail = f"cycle detected at {here.task_id}";
            disengage;
        }
        self.stack.append(here.task_id);
        visit [->:DependsOn:->] else {
            self.stack.pop();
            visit [-->];
        };
    }
}

walker DependencySerializer {
    has lines: list[str] = [];
    has collecting_for: str = "";
    has dep_ids: list[str] = [];
    has dep_stack: list[str] = [];

    can audit with Root entry {
        visit [-->];
    }

    can serialize with Task entry {
        if self.collecting_for != "" {
            if here.task_id in self.dep_stack {
                disengage;
            }
            self.dep_stack.append(here.task_id);
            if here.task_id != self.collecting_for {
                self.dep_ids.append(here.task_id);
            }
            visit [->:DependsOn:->] else {
                self.dep_stack.pop();
                disengage;
            };
        }
        self.collecting_for = here.task_id;
        self.dep_ids = [];
        self.dep_stack = [];
        visit [->:DependsOn:->] else {
            sorted_ids = sorted(self.dep_ids);
            dep_str = "";
            for dep_id in sorted_ids {
                next_sep = "," if dep_str != "" else "";
                dep_str = f"{dep_str}{next_sep}{dep_id}";
            }
            self.lines.append(f"{here.task_id}:[{dep_str}]");
            self.collecting_for = "";
            visit [-->];
        };
    }
}

walker TaskReporter {
    has shown: list[str] = [];

    can survey with Root entry {
        visit [-->];
    }

    can describe with Task entry {
        if here.task_id in self.shown {
            visit [-->];
        }
        self.shown.append(here.task_id);
        criteria = "";
        for item in here.acceptance_criteria {
            next_sep = "; " if criteria != "" else "";
            criteria = f"{criteria}{next_sep}{item}";
        }
        assignee_label = here.assignee if here.assignee != "" else "unassigned";
        print(
            f"[{here.status}] {here.task_id} {here.title} "
            f"p{here.priority} {assignee_label} "
            f"attempts={here.attempt_count} timeout={here.timeout_seconds}s "
            f"criteria=[{criteria}]"
        );
        visit [-->];
    }
}

with entry {
    us01 = Task(
        task_id="E01-US01",
        title="Core Contracts",
        priority=1,
        status="done"
    );
    us02 = Task(
