    cyc_b = Task(task_id="CYC-B", title="Cycle Beta", priority=9, status="blocked");
    cyc_c = Task(task_id="CYC-C", title="Cycle Gamma", priority=9, status="blocked");

    root ++> us01 ++> us02 ++> us03 ++> self_task ++> cyc_a;
    us02 +>:DependsOn:+> us01;
    us03 +>:DependsOn:+> us01;
    us03 +>:DependsOn:+> us02;
    self_task +>:DependsOn:+> self_task;
