"""Task domain model: typed dependencies with self-dep rejection, cycle detection, and sorted serialization."""

node Task {
    has task_id: str = "";
    has title: str = "";
    has priority: int = 0;
    has assignee: str = "";
    has attempt_count: int = 0;
    has timeout_seconds: int = 0;
    has status: str = "pending";
    has acceptance_criteria: list[str] = [];
}

edge DependsOn { }

walker TaskReporter {
    has visited: list[str] = [];

    can survey with Root entry {
        visit [-->];
    }

    can describe with Task entry {
        if here.task_id in self.visited {
            visit [-->];
        }
        self.visited.append(here.task_id);
        criteria = "";
        for item in here.acceptance_criteria {
            next_sep = "; " if criteria != "" else "";
            criteria = f"{criteria}{next_sep}{item}";
        }
        assignee_label = here.assignee if here.assignee != "" else "unassigned";
        print(
            f"[{here.status}] {here.task_id} {here.title} "
            f"p{here.priority} {assignee_label} "
            f"attempts={here.attempt_count} timeout={here.timeout_seconds}s "
            f"criteria=[{criteria}]"
        );
        visit [-->];
    }
}

walker SelfDepGuard {
    has rejected: list[str] = [];
    has owner_id: str = "";
    has scanning: bool = False;

    can audit with Root entry {
        visit [-->];
    }

    can validate with Task entry {
        if self.scanning {
            if here.task_id == self.owner_id {
                if self.owner_id not in self.rejected {
                    self.rejected.append(self.owner_id);
                }
            }
        } else {
            self.owner_id = here.task_id;
            self.scanning = True;
            visit [->:DependsOn:->] else {
                self.scanning = False;
                visit [-->];
            };
        }
    }
}

walker CycleGuard {
    has stack: list[str] = [];
    has cycle_found: bool = False;
    has cycle_detail: str = "";

    can probe with Task entry {
        if here.task_id in self.stack {
            self.cycle_found = True;
            self.cycle_detail = f"cycle detected at {here.task_id}";
            disengage;
        }
        self.stack.append(here.task_id);
        visit [->:DependsOn:->] else {
            self.stack.pop();
        };
    }
}

walker DependencySerializer {
    has lines: list[str] = [];
    has owner_id: str = "";
    has dep_ids: list[str] = [];
    has scanning: bool = False;

    can audit with Root entry {
        visit [-->];
    }

    can serialize with Task entry {
        if self.scanning {
            if here.task_id != self.owner_id {
                self.dep_ids.append(here.task_id);
            }
        } else {
            self.owner_id = here.task_id;
            self.dep_ids = [];
            self.scanning = True;
            visit [->:DependsOn:->] else {
                self.scanning = False;
                sorted_ids = sorted(self.dep_ids);
                dep_str = "";
                for dep_id in sorted_ids {
                    next_sep = "," if dep_str != "" else "";
                    dep_str = f"{dep_str}{next_sep}{dep_id}";
                }
                self.lines.append(f"{here.task_id}:[{dep_str}]");
                visit [-->];
            };
        }
    }
}

