"""VibeScript History finalization: dependency-ordered traversal with cycle guard, stale-doc rejection, and unified activity status."""

node Document {
    has uid: str = "";
    has incarnation: int = 0;
    has title: str = "";
}

node Operation {
    has name: str = "";
    has ordinal: int = 0;
    has status: str = "pending";
    has doc_uid: str = "";
    has incarnation: int = 0;
}

node StatusSurface {
    has state: str = "idle";
    has channel: str = "";
}

node HistoryLedger(StatusSurface) {
    has phase: str = "idle";
    has total: int = 0;
    has finalized: int = 0;
    override has channel: str = "History";
}

node ActivityStatus(StatusSurface) {
    has job: str = "";
    override has channel: str = "Activity";
}

edge DependsOn { }
edge MemberOf { }
edge InHistory { has sequence: int = 0; }

walker HistoryFinalizer {
    has active_uid: str = "";
    has active_incarnation: int = 0;
    has phase: str = "scanning";
    has visiting: list[str] = [];
    has stale_count: int = 0;
    has cycle_hit: bool = False;
    has ops_finalized: int = 0;

    can start with Root entry {
        self.phase = "finalizing";
        visit [-->];
    }

    can surface_phase with HistoryLedger | ActivityStatus entry {
        here.state = self.phase;
        if here.channel == "Activity" {
            here.job = "VibeScript publication";
            print(f"[{here.channel}] {here.job}: {here.state}");
            visit [-->];
        } else {
            here.phase = self.phase;
            print(f"[{here.channel}] entering {here.phase} ({here.total} queued)");
            visit [->:InHistory:->] else {
                next_phase = "rollback" if self.cycle_hit else "committing";
                self.phase = next_phase;
                here.phase = next_phase;
                here.finalized = self.ops_finalized;
                print(
                    f"[{here.channel}] atomic {next_phase}: "
                    f"{self.ops_finalized} finalized, {self.stale_count} stale rejected"
                );
                disengage;
            };
        }
    }

    can resolve_op with Operation entry {
        if here.status == "finalized" {
            disengage;
        }

        op_key = f"{here.doc_uid}:{here.ordinal}";
        if op_key in self.visiting {
            self.cycle_hit = True;
            here.status = "cycle_blocked";
            print(f"[CYCLE] forward-dep loop at op #{here.ordinal}");
            disengage;
        }
        self.visiting.append(op_key);

        is_stale = (
            here.doc_uid != self.active_uid
            or here.incarnation != self.active_incarnation
        );
        if is_stale {
            here.status = "stale";
            self.stale_count += 1;
            print(
                f"[STALE] op #{here.ordinal} rejected "
                f"(incarnation {here.incarnation} != {self.active_incarnation})"
            );
        } else if here.status != "cycle_blocked" {
            visit [->:DependsOn:->];
            if not self.cycle_hit {
                here.status = "finalized";
                self.ops_finalized += 1;
                print(f"[FINALIZE] op #{here.ordinal} {here.name}");
            }
        }

        self.visiting.pop();
        visit [->:InHistory:->] else { disengage; };
    }
}

