"""Evidence-bound README release gate: dependency ordering, orphan-claim detection, and validation sweep."""

node Task {
    has issue_id: int = 0;
    has title: str = "";
    has year: int = 0;
    has complete: bool = False;
}

node DocArtifact {
    has name: str = "";
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

node Claim {
    has statement: str = "";
    has value: float = 0.0;
    has year: int = 0;
}

node Evidence {
    has source: str = "";
    has title: str = "";
    has year: int = 0;
    has accepted: bool = True;
}

node GateCheck {
    has check_name: str = "";
    has title: str = "";
    has passed: bool = False;
}

edge DependsOn { }
edge BlockedBy { }
edge Contains { }
edge EvidencedBy { has ref: str = ""; }
edge Validates { }

walker DependencyResolver {
    has seen: list[int] = [];
    has blockers: list[str] = [];
    has deps_clear: bool = False;

    can start with Root entry {
        print("--- Dependency audit for issue #55 ---");
        visit [-->[?:Task]] else { disengage; };
    }

    can audit with Task entry {
        if here.issue_id in self.seen {
            print(f"CYCLE detected at issue #{here.issue_id}");
            disengage;
        }
        self.seen.append(here.issue_id);

        if here.issue_id == 55 {
            visit [->:DependsOn:->] else { };
            visit [->:BlockedBy:->] else { };
            blocker_count = len(self.blockers);
            if blocker_count == 0 {
                self.deps_clear = True;
                print("#55 dependency graph satisfied");
            } else {
                print(f"#55 cannot ship: {blocker_count} open blocker(s)");
            }
        }

        if (not here.complete) and (here.issue_id != 55) {
            label = f"#{here.issue_id} {here.title}";
            self.blockers.append(label);
            print(f"  [WAIT] {label}");
        } else {
            if here.issue_id != 55 {
                print(f"  [OK] #{here.issue_id} {here.title}");
            }
        }

        visit [-->];
    }
}

walker ClaimAuditor {
    has orphans: list[str] = [];
    has linked: int = 0;

    can start with Root entry {
        print("--- Orphan claim scan (check_claims.py) ---");
        visit [-->[?:DocArtifact]] else { disengage; };
    }

    can scan_doc with DocArtifact entry {
        print(f"Scanning {here.name}");
        visit [->:Contains:->];
        visit [-->];
    }

    can scan_claim with Claim entry {
        visit [->:EvidencedBy:->] else {
            self.orphans.append(here.statement);
            print(f"  ORPHAN: {here.statement} (value={here.value})");
        };
    }

    can confirm with Evidence entry {
        if here.accepted {
            self.linked += 1;
            print(f"  evidenced -> {here.source}");
        }
        visit [-->];
    }
}

walker GateRunner {
    has pass_count: int = 0;
    has fail_count: int = 0;

    can start with Root entry {
        print("--- Release gate sweep (check_docs.py) ---");
        visit [-->[?:DocArtifact]] else { disengage; };
    }

    can on_doc with DocArtifact entry {
        print(f"Validating gates for {here.title}");
        visit [->:Validates:->];
        visit [-->];
    }

    can run_gate with GateCheck entry {
        status = "PASS" if here.passed else "FAIL";
        print(f"  [{status}] {here.check_name}");
        if here.passed {
            self.pass_count += 1;
        } else {
            self.fail_count += 1;
        }
        visit [-->];
    }
}

