    runner = GateRunner();
    root spawn resolver;
    root spawn auditor;
    root spawn runner;

    print("--- Publish verdict ---");
    orphan_count = len(auditor.orphans);
    if resolver.deps_clear and orphan_count == 0 and runner.fail_count == 0 {
        print("READY: evidence-bound README may publish");
    } else {
        print(
            f"HELD: deps_clear={resolver.deps_clear}, "
            f"orphans={orphan_count}, gate_fails={runner.fail_count}"
        );
    }
    print(
        "Limitation: Cartesian grid routes around meshing; "
        "solver output is not engineering ground truth."
    );
}

"""Page composition V2: shells, slots, nested blocks, cycle guard, and sibling-order audit."""

node Shell {
    has shell_id: str = "";
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

node Slot {
    has slot_name: str = "";
    has required: bool = True;
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

node Block {
    has block_id: str = "";
    has block_type: str = "";
    has title: str = "";
    has catalogue_version: str = "";
    has year: int = 0;
    has available: bool = True;
}

node Page {
    has page_id: str = "";
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

edge UsesShell { }
edge Hosts { has position: int = 0; }
edge Fills { has order: int = 0; }
edge Nests { has order: int = 0; }
edge DependsOn { has catalogue_version: str = ""; }

walker CompositionValidator {
    has errors: list[str] = [];
    has path: list[str] = [];
    has depth: int = 0;
    has max_depth: int = 6;

    can start with Root entry {
        print("=== Page Composition Validation (V2) ===");
        visit [-->];
        print("");
        if self.errors {
            print(f"RESULT: INVALID ({len(self.errors)} issue(s))");
            for (i, err) in enumerate(self.errors) {
                print(f"  {i + 1}. {err}");
            }
        } else {
            print("RESULT: VALID — shells, slots, and blocks pass checks");
        }
    }

    can validate_page with Page entry {
        print(f"\n[Page] {here.title} ({here.page_id})");
        visit [->:UsesShell:->] else {
            print("  (no shell — default main slot)");
        };
    }

    can check_shell with Shell entry {
        print(f"  [Shell] {here.title} ({here.shell_id})");
        visit [->:Hosts:->];
    }

    can audit_slot with Slot entry {
        req_label = "REQUIRED" if here.required else "optional";
        print(f"    [Slot:{here.slot_name}] ({req_label})");
        visit [->:Fills:->] else {
            if here.required {
                self.errors += [f"missing required slot '{here.slot_name}'"];
            } else {
                print("      (empty optional slot)");
            }
        };
    }

    can inspect_block with Block entry {
        if here.block_id in self.path {
            self.errors += [f"cycle detected at block '{here.block_id}'"];
            disengage;
        }
        self.path += [here.block_id];
        self.depth += 1;
        if self.depth > self.max_depth {
            self.errors += [f"depth limit {self.max_depth} exceeded at '{here.block_id}'"];
            disengage;
        }
        status = "active" if here.available else "inactive";
        print(f"      [Block:{here.block_type}] {here.title} "
              f"id={here.block_id} ({status}) depth={self.depth}");
        visit [->:Nests:->];
    }

    can unwind_block with Block exit {
        if self.path and self.path[-1] == here.block_id {
            self.path = self.path[:-1];
        }
        self.depth -= 1;
    }
}

walker CatalogueAuditor {
    has resolve_log: list[str] = [];

    can start with Root entry {
        print("\n=== Platform Block Dependency Order ===");
        visit [-->];
        print(f"Resolved: {' -> '.join(self.resolve_log)}");
    }

    can walk_page with Page entry {
        visit [->:UsesShell:->];
    }

    can walk_shell with Shell entry {
        visit [->:Hosts:->];
    }

    can walk_slot with Slot entry {
        visit [->:Fills:->];
    }

    can resolve_block with Block entry {
        if here.catalogue_version == "" {
            self.resolve_log += [f"{here.block_id}(unversioned)"];
        } else {
            self.resolve_log += [f"{here.block_id}@{here.catalogue_version}"];
        }
        visit [->:DependsOn:->];
        visit [->:Nests:->];
    }
}

with entry {
    app_shell = Shell(shell_id="shell-001", title="Standard App Shell");
    header_slot = Slot(slot_name="header", required=True);
    main_slot = Slot(slot_name="main", required=True);
    footer_slot = Slot(slot_name="footer", required=False);

    app_shell +>:Hosts(position=0):+> header_slot;
    app_shell +>:Hosts(position=1):+> main_slot;
    app_shell +>:Hosts(position=2):+> footer_slot;

    nav = Block(
        block_id="blk-nav",
