    bare_shell = Shell(shell_id="shell-empty", title="Incomplete Shell");
    bare_main = Slot(slot_name="main", required=True);
    bare_shell +>:Hosts(position=0):+> bare_main;

    draft = Page(page_id="pg-draft", title="Unpublished Draft");
    draft +>:UsesShell:+> bare_shell;

    root ++> home ++> draft;

    root spawn CompositionValidator(max_depth=6);
    root spawn CatalogueAuditor();
