}

node CreativeBranch {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has name: str = "";
    has control_mode: str = "collaborative";
}

node Guidance {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has message: str = "";
    has active: bool = True;
}

edge VersionOf { }
edge DerivesFrom { }
edge ForkedFrom { }
edge HeadOn { }
