walker ProvenanceAuditor {
    has visited: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can catalog with Artifact entry {
        print(f"=== {here.title} ===");
        visit [<--:Targets:--];
        visit [<--:VersionOf:--];
        visit [-->];
    }

    can show_guidance with Guidance entry {
        tag = "ACTIVE" if here.active else "STALE";
        print(f"[GUIDANCE {tag}] {here.message}");
    }

    can trace with ArtifactVersion entry {
        if here.content in self.visited {
            disengage;
        }
        self.visited.append(here.content);
        lock_tag = " LOCKED" if here.locked else "";
        print(f"  [{here.author_kind}/{here.state}{lock_tag}] {here.content}  ({here.provenance})");
        visit [->:DerivesFrom:->];
        visit [->:ForkedFrom:->];
    }

    can onward with CreativeBranch entry {
        visit [-->];
    }
}

walker RefinementAgent {
    has proposal: str = "";

    can start with Root entry {
        visit [-->];
    }

    can begin with CreativeBranch entry {
        print(f"Refining branch '{here.name}' ({here.control_mode})");
        if here.control_mode == "locked" or here.control_mode == "paused" {
            print(f"  [SKIP] branch control blocks autonomous work");
            disengage;
        }
        visit [->:HeadOn:->] else { disengage; }
    }

    can refine with ArtifactVersion entry {
        if here.locked {
            print(f"  [CONFLICT] locked version '{here.content}' — refinement rejected");
            disengage;
        }
        print(f"  [OK] would create new version from '{here.content}': {self.proposal}");
        disengage;
    }

    can onward with Artifact | Guidance entry {
        visit [-->];
    }
}

