"""Creative graph fan-out: one Goal and CreativeBrief coordinate parallel artifact
branches with shared decisions, targeted invalidation, and isolated branch refinement."""

node Traceable {
    has valid: bool = True;
    has revision: int = 1;

    def trace_label() -> str {
        return "traceable";
    }
}

node ProjectGoal {
    has revision: int = 0;
    has agent: str = "";
    has outcome: str = "";
}

node CreativeBrief(Traceable) {
    has version: int = 1;
    has audience: str = "";
    has core_message: str = "";

    override def trace_label() -> str {
        return f"brief-v{self.version}";
    }
}

node SharedDecision(Traceable) {
    has kind: str = "";
    has content: str = "";

    override def trace_label() -> str {
        return f"{self.kind}-rev{self.revision}";
    }
}

node Artifact {
    has name: str = "";
    has status: str = "pending";
    has generation: int = 0;
}

edge InformedBy { }
edge Feeds { }

walker FanOutExecutor {
    has fail_branch: str = "";
    has mode: str = "forward";
    has deps_ok: bool = True;
    has accepted: int = 0;
    has seen: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can bind with ProjectGoal entry {
        print(f"Goal rev={here.revision} agent={here.agent} outcome={here.outcome}");
        visit [-->];
    }

    can upstream with CreativeBrief | SharedDecision entry {
        state = "OK" if here.valid else "STALE";
        print(f"[{state}] {here.trace_label()}");
        if here is CreativeBrief {
            visit [->:InformedBy:->];
        } else {
            visit [->:Feeds:->];
        }
    }

    can check_feed with SharedDecision entry {
        if self.mode == "check_deps" {
            if not here.valid {
                self.deps_ok = False;
            }
            disengage;
        } else {
            visit [-->];
        }
    }

    can generate with Artifact entry {
        if here.name in self.seen {
            print(f"[CYCLE] blocked re-entry on {here.name}");
            disengage;
        }
        self.seen.append(here.name);
        self.deps_ok = True;
        self.mode = "check_deps";
        visit [<--:Feeds:--] else { self.mode = "forward"; };
        self.mode = "forward";
        if not self.deps_ok {
            here.status = "pending";
            print(f"[HOLD] {here.name}: waiting on valid upstream decisions");
        } else if here.status == "pending" or here.status == "stale" {
            next_gen = here.generation + 1;
            here.generation = next_gen;
            if here.name == self.fail_branch {
                here.status = "failed";
                print(f"[FAIL] {here.name} gen #{here.generation}");
            } else {
                here.status = "accepted";
                self.accepted += 1;
                print(f"[OK] {here.name} gen #{here.generation} accepted");
            }
        } else if here.status == "refining" {
            next_gen = here.generation + 1;
            here.generation = next_gen;
            here.status = "accepted";
            self.accepted += 1;
            print(f"[REFINED] {here.name} gen #{here.generation} accepted");
        } else if here.status == "accepted" {
            print(f"[SKIP] {here.name} already accepted gen #{here.generation}");
        } else {
            print(f"[SKIP] {here.name} status={here.status}");
        }
        visit [-->];
    }
}

walker BranchRefiner {
    has branch_name: str = "";

    can start with Root entry {
        visit [-->];
    }

    can refine with Artifact entry {
        if here.name == self.branch_name and here.status == "failed" {
            here.status = "refining";
            print(f"[RETRY] isolated refinement for {here.name}");
        }
        visit [-->];
    }
}

walker TargetedInvalidator {
    has invalidate_kind: str = "message";
    has stale_names: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can walk_brief with CreativeBrief entry {
        visit [->:InformedBy:->];
    }

    can poison with SharedDecision entry {
        if here.kind == self.invalidate_kind {
            here.valid = False;
            bumped = here.revision + 1;
            here.revision = bumped;
            print(f"[INVALIDATE] {here.kind} -> rev {here.revision}");
            visit [->:Feeds:->];
        } else {
            print(f"[KEEP] {here.kind} decision untouched");
            visit [-->];
        }
    }

    can stale_artifact with Artifact entry {
        if here.status == "accepted" {
            here.status = "stale";
            self.stale_names.append(here.name);
            print(f"[STALE] {here.name} targeted downstream");
        }
        visit [-->];
    }
}

walker GoalRevisionInvalidator {
    has new_revision: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can bump with ProjectGoal entry {
        here.revision = self.new_revision;
        print(f"[GOAL] revision bumped to {here.revision}");
        visit [-->];
    }

    can void with CreativeBrief | SharedDecision entry {
        here.valid = False;
        bumped = here.revision + 1;
        here.revision = bumped;
        print(f"[GOAL-CASCADE] voided {here.trace_label()}");
        visit [-->];
    }

    can stale_all with Artifact entry {
        if here.status == "accepted" {
            here.status = "stale";
            print(f"[STALE] {here.name} from goal revision");
        }
        visit [-->];
    }
}

with entry {
    goal = ProjectGoal(revision=4, agent="mAIstro", outcome="Unified product launch");
    brief = CreativeBrief(
        version=2,
        audience="Enterprise CTOs",
        core_message="Ship with confidence"
    );
    msg = SharedDecision(kind="message", content="Outcome-led headline architecture");
    vis = SharedDecision(kind="visual", content="Navy palette, sparse motion accents");
    site = Artifact(name="website");
    deck = Artifact(name="deck");
    poster = Artifact(name="poster");

    root ++> goal ++> brief;
    brief +>:InformedBy:+> msg;
    brief +>:InformedBy:+> vis;
    msg +>:Feeds:+> site;
    msg +>:Feeds:+> deck;
    vis +>:Feeds:+> site;
    vis +>:Feeds:+> poster;

    print("== Phase 1: fan-out generation (deck planted to fail) ==");
    root spawn FanOutExecutor(fail_branch="deck");

    print("== Phase 2: refine failed deck only; siblings stay accepted ==");
    root spawn BranchRefiner(branch_name="deck");
    root spawn FanOutExecutor();

    print("== Phase 3: audience change invalidates message dependents only ==");
    brief.valid = False;
    brief.audience = "Startup founders";
    root spawn TargetedInvalidator(invalidate_kind="message");

    print("== Phase 4: visual-only change spares deck copy ==");
    root spawn TargetedInvalidator(invalidate_kind="visual");

    print("== Phase 5: canonical Goal revision explicit downstream invalidation ==");
    root spawn GoalRevisionInvalidator(new_revision=5);
    root spawn FanOutExecutor();
}

