            print(f"[RETRY] isolated refinement for {here.name}");
        }
        visit [-->];
    }
}

walker TargetedInvalidator {
    has invalidate_kind: str = "message";
    has stale_names: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can walk_brief with CreativeBrief entry {
        visit [->:InformedBy:->];
