    can poison with SharedDecision entry {
        if here.kind == self.invalidate_kind {
            here.valid = False;
            bumped = here.revision + 1;
            here.revision = bumped;
            print(f"[INVALIDATE] {here.kind} -> rev {here.revision}");
            visit [->:Feeds:->];
        } else {
            print(f"[KEEP] {here.kind} decision untouched");
            visit [-->];
        }
    }

    can stale_artifact with Artifact entry {
        if here.status == "accepted" {
            here.status = "stale";
            self.stale_names.append(here.name);
            print(f"[STALE] {here.name} targeted downstream");
        }
        visit [-->];
    }
}

walker GoalRevisionInvalidator {
    has new_revision: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can bump with ProjectGoal entry {
        here.revision = self.new_revision;
        print(f"[GOAL] revision bumped to {here.revision}");
        visit [-->];
