"""Visual perception canonical pipeline: deterministic stage ordering, append-only evidence, selective refinement, and post-stage quality audits."""

node Region {
    has region_id: str = "";
    has geometry_locked: bool = True;
}

node Evidence {
    has claim: str = "";
    has resolved: bool = False;
    has provenance: str = "";
}

node SceneContext {
    has context_name: str = "";
}

node Claim {
    has relation_kind: str = "";
    has source_stage: str = "";
}

node PipelineStage {
    has stage_name: str = "";
    has stage_order: int = 0;
    has adds_claims: bool = False;
    has local_failed: bool = False;
}

edge StageOrder { }
edge HasEvidence { }
edge HasContext { }
edge ProducesClaim { }

walker CanonicalRunner {
    has audit_count: int = 0;
    has stages_run: list[str] = [];
    has visited_stages: list[str] = [];
    has total_claims: int = 0;
    has current_stage: str = "";
    has refinement_ran: bool = False;

    def audit() {
        self.audit_count += 1;
        print(f"    [AUDIT #{self.audit_count}] quality check on post-stage state");
    }

    can start with Root entry {
        print("=== Canonical visual-perception pipeline ===");
        visit [->:StageOrder:->] else { disengage; };
    }

    can execute with PipelineStage entry {
        for prior in self.visited_stages {
            if prior == here.stage_name {
                print(f"[CYCLE GUARD] blocked re-entry at {here.stage_name}");
                disengage;
            }
        }
        self.visited_stages.append(here.stage_name);
        self.current_stage = here.stage_name;

        if here.local_failed {
            print(f"[STAGE {here.stage_order}] {here.stage_name} — local failure, prior evidence preserved");
            visit [->:StageOrder:->] else { disengage; };
        }

        self.stages_run.append(here.stage_name);
        print(f"[STAGE {here.stage_order}] {here.stage_name}");

        visit [-->[?:Region]] else { };

        if here.adds_claims {
            geo_claim = Claim(relation_kind="geometric_proximal", source_stage=here.stage_name);
            sem_claim = Claim(relation_kind="semantic_supports", source_stage=here.stage_name);
            here +>:ProducesClaim:+> geo_claim;
            here +>:ProducesClaim:+> sem_claim;
            self.total_claims += 2;
            print(f"    + claims: {geo_claim.relation_kind}, {sem_claim.relation_kind} (append-only)");
            self.audit();
        }

        if here.stage_name == "final_audit" {
            self.audit();
        }

        visit [->:StageOrder:->] else {
            refined_label = "yes" if self.refinement_ran else "no";
            print(f"=== Pipeline complete: {len(self.stages_run)} stages, "
                  f"{self.audit_count} audits, {self.total_claims} claims, "
                  f"refinement_ran={refined_label} ===");
            disengage;
        };
    }

    can process_region with Region entry {
        lock_label = "locked" if here.geometry_locked else "mutable";
        print(f"  region {here.region_id} geometry={lock_label}");
        visit [->:HasContext:->] else { };
        visit [->:HasEvidence:->] else { };

        if self.current_stage == "reconcile_context" {
            print(f"    -> intra-frame reconciliation (geometry unchanged, evidence preserved)");
        }

        visit [-->];
    }

    can apply_context with SceneContext entry {
        print(f"    scene context: {here.context_name}");
        visit [-->];
    }

    can review_evidence with Evidence entry {
        status = "OK" if here.resolved else "UNRESOLVED";
        print(f"    evidence [{status}] {here.claim} (provenance={here.provenance})");

        if self.current_stage == "selective_refinement" and not here.resolved {
            refined_provenance = here.provenance + "+refinement";
            print(f"    -> selective refinement applied (geometry unchanged, evidence appended)");
            here.provenance = refined_provenance;
            here.resolved = True;
            self.refinement_ran = True;
        }

        visit [-->];
    }

    can inspect_claim with Claim entry {
        print(f"    stored claim: {here.relation_kind} from {here.source_stage}");
        visit [-->];
    }
}

with entry {
    ctx = SceneContext(context_name="indoor_kitchen");
    r1 = Region(region_id="R-101", geometry_locked=True);
    ev_dense = Evidence(claim="pixel_aligned_surface", resolved=True, provenance="dense_ingest");
    ev_open = Evidence(claim="occluded_edge", resolved=False, provenance="dense_ingest");

    r1 +>:HasContext:+> ctx;
    r1 +>:HasEvidence:+> ev_dense;
