    s1 = PipelineStage(stage_name="ingest_evidence", stage_order=1);
    s2 = PipelineStage(stage_name="calibrate_support", stage_order=2, local_failed=True);
    s3 = PipelineStage(stage_name="selective_refinement", stage_order=3);
    s4 = PipelineStage(stage_name="reconcile_context", stage_order=4);
    s5 = PipelineStage(stage_name="generate_relations", stage_order=5, adds_claims=True);
    s6 = PipelineStage(stage_name="final_audit", stage_order=6);

    s1 ++> r1;
    s2 ++> r1;
    s3 ++> r1;
    s4 ++> r1;
    s5 ++> r1;
    s6 ++> r1;

    root +>:StageOrder:+> s1
        +>:StageOrder:+> s2
        +>:StageOrder:+> s3
        +>:StageOrder:+> s4
        +>:StageOrder:+> s5
        +>:StageOrder:+> s6;

    root spawn CanonicalRunner();
}

"""Nucula roadmap: sessions and board targets linked by DependsOn edges; RoadmapPlanner walks prerequisites to find executable work."""

node RoadmapItem {
    has title: str = "";
    has year: int = 2026;
    has available: bool = True;

    def is_satisfied() -> bool {
        return self.available;
    }
}

node Session(RoadmapItem) {
    has complete: bool = False;
    has priority: int = 0;

    override def is_satisfied() -> bool {
        return self.complete;
    }
}

node BoardTarget(RoadmapItem) {
    has building_green: bool = True;

    override def is_satisfied() -> bool {
        return self.building_green;
    }
}

edge DependsOn { }
edge Targets { }

walker RoadmapPlanner {
    has ready: list[str] = [];
    has blocked: list[str] = [];
    has prereqs_ok: bool = True;
    has seen: list[str] = [];

    can start with Root entry {
        print("=== Nucula session roadmap audit ===");
        visit [-->];
        print(f"\nExecutable next: {self.ready}");
        print(f"Still blocked: {self.blocked}");
        disengage;
    }

    can audit with Session entry {
        self.prereqs_ok = True;
        self.seen = [];
        visit [<--:DependsOn:--] else { }
        status = "DONE" if here.complete else ("READY" if self.prereqs_ok else "BLOCKED");
        print(f"[{status}] P{here.priority}: {here.title}");
        if not here.complete {
            if self.prereqs_ok {
                self.ready += [here.title];
            } else {
                self.blocked += [here.title];
            }
        }
        visit [->:Targets:->];
        visit [-->];
    }

    can check_dep with Session | BoardTarget entry {
        if here.title in self.seen {
            print(f"  [CYCLE] dependency loop at {here.title}");
            disengage;
        }
        self.seen += [here.title];
        if not here.is_satisfied() {
            self.prereqs_ok = False;
        }
        visit [<--:DependsOn:--] else { };
    }

    can board_label with BoardTarget entry {
        board_status = "green" if here.building_green else "down";
        print(f"  -> board [{board_status}]: {here.title}");
    }
}

