"""HQL textual frontend: validate rule AST nodes and compile them to canonical matcher IR."""

node HqlRule {
    has rule_name: str = "";
    has severity: str = "info";
    has evidence: str = "signal";
    has valid: bool = True;
    has ir_summary: str = "";
    has root_conds: list[Condition] = [];
}

node Condition {
    has ir_fragment: str = "";
    has children: list[Condition] = [];
}

node AllOf(Condition) { }
node AnyOf(Condition) { }
node NotCond(Condition) { }

node CallMatch(Condition) {
    has callee: str = "";
    has field_name: str = "callee";
}

node FactMatch(Condition) {
    has fact_kind: str = "";
    has attr_name: str = "";
    has attr_value: str = "";
}

edge RootCondition { }
edge Child { has ordinal: int = 0; }

walker SchemaValidator {
    has rule_ok: bool = True;
    has rule_errors: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can validate with HqlRule entry {
        self.rule_ok = True;
        self.rule_errors = [];
        visit [->:RootCondition:->] else {
            self.rule_ok = False;
            self.rule_errors += ["error HQL1001: rule has no root condition"];
            disengage;
        }
    }

    can validate with HqlRule exit {
        here.valid = self.rule_ok;
        if not self.rule_ok {
            for err in self.rule_errors {
                print(f"{here.rule_name}: {err}");
            }
        }
    }

    can validate with AllOf | AnyOf | NotCond entry {
        visit [->:Child:->] else { disengage; }
    }

    can validate with CallMatch entry {
        if here.field_name != "callee" {
            self.rule_ok = False;
            self.rule_errors += [
                f"error HQL1007: field '{here.field_name}' does not exist on CCallExpr"
            ];
        }
        visit [->:Child:->] else { disengage; }
    }

    can validate with FactMatch entry {
        known = (
            here.fact_kind == "summary-ownership"
            or here.fact_kind == "summary-barrier"
        );
        if not known {
            self.rule_ok = False;
            self.rule_errors += [
                f"error HQL1008: unknown fact kind '{here.fact_kind}'"
            ];
        }
        visit [->:Child:->] else { disengage; }
    }
}

walker HqlCompiler {
    can start with Root entry {
        visit [-->];
    }

    can compile with HqlRule entry {
        if not here.valid {
            print(f"SKIP {here.rule_name}: schema validation failed");
            disengage;
        }
        visit [->:RootCondition:->] else { disengage; }
    }

    can compile with HqlRule exit {
        if len(here.root_conds) > 0 {
            root_node = here.root_conds[0];
            here.ir_summary = root_node.ir_fragment;
        }
    }

    can compile with CallMatch entry {
        here.ir_fragment = f"call.callee == \"{here.callee}\"";
        visit [->:Child:->] else { disengage; }
    }

    can compile with FactMatch entry {
        here.ir_fragment = (
            f"fact {here.fact_kind}({here.attr_name} = \"{here.attr_value}\")"
        );
        visit [->:Child:->] else { disengage; }
    }

    can compile with NotCond entry {
        visit [->:Child:->] else { disengage; }
    }

    can compile with NotCond exit {
        for child in here.children {
            here.ir_fragment = f"not {child.ir_fragment}";
        }
    }

    can compile with AllOf entry {
        visit [->:Child:->] else { disengage; }
    }

    can compile with AllOf exit {
        body = "";
        for child in here.children {
            sep = "; " if body != "" else "";
            body = f"{body}{sep}{child.ir_fragment}";
        }
        here.ir_fragment = f"all {{ {body} }}";
    }

    can compile with AnyOf entry {
        visit [->:Child:->] else { disengage; }
    }

    can compile with AnyOf exit {
        body = "";
        for child in here.children {
            sep = "; " if body != "" else "";
            body = f"{body}{sep}{child.ir_fragment}";
        }
        here.ir_fragment = f"any {{ {body} }}";
    }
}

with entry {
    malloc_leaf = CallMatch(callee="malloc");
    own_leaf = FactMatch(
        fact_kind="summary-ownership",
        attr_name="ownershipKind",
        attr_value="allocate"
    );
