    bad_root.children = [bad_leaf];
    bad_root +>:Child(ordinal=0):+> bad_leaf;

    bad_rule = HqlRule(
        rule_name="memory.bad_field",
        severity="info",
        evidence="signal"
    );
    bad_rule.root_conds = [bad_root];
    bad_rule +>:RootCondition:+> bad_root;

    root ++> mem_rule ++> timing_rule ++> bad_rule;

    validator = SchemaValidator();
    root spawn validator;

    compiler = HqlCompiler();
