    print(f"IR [{mem_rule.rule_name}]: {mem_rule.ir_summary}");
    print(f"IR [{timing_rule.rule_name}]: {timing_rule.ir_summary}");
    print(f"IR [{bad_rule.rule_name}]: valid={bad_rule.valid} summary='{bad_rule.ir_summary}'");
}

