walker ReleasePackager {
    has seen_ids: list[str] = [];
    has stamp_split: str = "";

    can start with Root entry {
        print("");
        print("--- Packaging release: stamp splits through lineage ---");
        visit [-->[?:MenuGroup]];
    }

    can stamp_group with MenuGroup entry {
        self.stamp_split = here.split_name;
        self.seen_ids = [];
        print(f"Group {here.group_key} bound to split '{self.stamp_split}'");
        visit [<--:MemberOf:--];
    }

    can stamp_image with MenuImage entry {
        if here.image_id in self.seen_ids {
            disengage;
        }
        self.seen_ids.append(here.image_id);
        here.split_name = self.stamp_split;
        kind = "SOURCE" if here.is_source else "AUG";
        print(f"  stamp {here.image_id} [{kind}] -> {self.stamp_split}");
        visit [->:DerivedFrom:->] else { disengage; };
    }
}

walker LeakageAuditor {
    has violations: int = 0;
    has lineage_seen: list[str] = [];
    has root_split: str = "";
    has in_lineage_walk: bool = False;

    can start with Root entry {
        print("");
        print("=== Auditing split leakage across derivative lineage ===");
        visit [-->[?:MenuImage]];
    }

    can inspect with MenuImage entry {
        if self.in_lineage_walk {
            if here.image_id in self.lineage_seen {
                print(f"  [CYCLE] {here.image_id}");
                self.violations += 1;
                self.in_lineage_walk = False;
                disengage;
            }
            self.lineage_seen.append(here.image_id);
            status = "OK" if here.split_name == self.root_split else "LEAK";
            if status == "LEAK" {
                self.violations += 1;
                print(f"  [{status}] {here.image_id} in '{here.split_name}', want '{self.root_split}'");
            } else {
                print(f"  [{status}] derivative {here.image_id}");
            }
            visit [->:DerivedFrom:->] else {
                self.in_lineage_walk = False;
                disengage;
            };
        } elif here.is_source {
            self.root_split = here.split_name;
            self.lineage_seen = [];
            self.in_lineage_walk = True;
            print(f"Lineage root {here.image_id} (split='{self.root_split}')");
            visit [->:DerivedFrom:->] else {
                self.in_lineage_walk = False;
                disengage;
            };
            visit [-->];
        } else {
            visit [-->];
        }
    }
}

