"""Offline map-building composition: wire mapping modules through typed edges and traverse the pipeline deterministically."""

node ObservationSequence {
    has name: str = "";
    has frame_count: int = 0;
    has validated: bool = True;
}

node InputAdapter {
    has name: str = "";
    has resolved: bool = True;
}

node RuntimeComposition {
    has name: str = "";
    has loaded: bool = True;
}

node PipelineModule {
    has label: str = "";
    has ready: bool = True;
    has diagnostic: str = "";
    has ran: bool = False;
}

node StateEstimator(PipelineModule) { }
node GeometricMapper(PipelineModule) { }
node VisualProcessor(PipelineModule) { }
node PointRepresentation(PipelineModule) { }
node Association(PipelineModule) { }
node SemanticFusion(PipelineModule) { }
node SemanticMapper(PipelineModule) { }

edge Observes { }
edge Composes { has order: int = 0; }
edge DependsOn { }

walker MapBuilder {
    has run_id: str = "";
    has steps: list[str] = [];
    has errors: list[str] = [];
    has completed: list[str] = [];
    has executing: list[str] = [];
    has resolving_deps: bool = False;

    can start with Root entry {
        print(f"[{self.run_id}] offline map-building workflow start");
        visit [-->];
    }

    can ingest with ObservationSequence entry {
        if not here.validated {
            self.errors.append(f"observations invalid: {here.name}");
            visit [-->] else { disengage; };
            disengage;
        }
        print(f"[{self.run_id}] observations {here.name} ({here.frame_count} frames)");
        visit [->:Observes:->] else { disengage; };
    }

    can resolve with InputAdapter entry {
        if not here.resolved {
            self.errors.append(f"adapter unresolved: {here.name}");
            visit [-->] else { disengage; };
            disengage;
        }
        print(f"[{self.run_id}] input adapter {here.name}");
        visit [-->];
    }

    can bootstrap with RuntimeComposition entry {
        if not here.loaded {
            self.errors.append(f"composition not loaded: {here.name}");
            visit [-->] else { disengage; };
            disengage;
        }
        print(f"[{self.run_id}] runtime composition {here.name}");
        visit [->:Composes:->] else { disengage; };
    }

    can execute with StateEstimator | GeometricMapper | VisualProcessor | PointRepresentation | Association | SemanticFusion | SemanticMapper entry {
        key = here.label;
        if key in self.completed {
            visit [->:Composes:->] else { disengage; };
            disengage;
        }
        if key in self.executing {
            self.errors.append(f"cycle detected at {key}");
            visit [->:Composes:->] else { disengage; };
            disengage;
        }
        self.executing.append(key);
        self.resolving_deps = True;
        visit [->:DependsOn:->] else { visit [-->] else { disengage; }; };
        self.resolving_deps = False;
        self.executing.pop();
        if not here.ready {
            diag = f"{here.label}: {here.diagnostic}";
            self.errors.append(diag);
            print(f"DIAG [{self.run_id}] {diag}");
        } else {
            here.ran = True;
            self.steps.append(here.label);
            print(f"[{self.run_id}] stage {here.label}");
        }
        self.completed.append(key);
        if self.resolving_deps {
            visit [-->] else { disengage; };
            disengage;
        }
        visit [->:Composes:->] else { disengage; };
    }

    can finish with Root exit {
        order = ", ".join(self.steps);
        print(f"[{self.run_id}] provenance: {order}");
        if self.errors {
            joined = "; ".join(self.errors);
            print(f"DIAG [{self.run_id}] {joined}");
        } else {
            print(f"[{self.run_id}] diagnostics: none");
        }
    }
}

