"""Relational component audit: hierarchy binding resolution, atomic cache tiers, and singleton lifecycle transitions."""

node SceneObject {
    has name: str = "";
    has active: bool = True;
    has destroyed: bool = False;
}

node BindingTarget(SceneObject) { }

node RelationalBinding {
    has field_name: str = "";
    has cardinality: str = "single";
    has optional: bool = False;
}

node CacheEntry {
    has tier: str = "reflection";
    has published: bool = False;
    has value: str = "";
    has atomic_ready: bool = False;
    has invalidated: bool = False;
}

node RuntimeSingleton {
    has service_name: str = "";
    has state: str = "Uninitialized";
}

edge ChildOf { }
edge OwnsBinding { }
edge Targets { has match_order: int = 0; }
edge CachedPlan { has warm: bool = False; }

walker BindingAuditor {
    has visited: list = [];
    has depth: int = 0;
    has max_depth: int = 16;
    has resolved: int = 0;
    has resolving: bool = False;

    can start with Root entry {
        print("--- Relational binding audit ---");
        visit [-->];
    }

    can audit_scene with SceneObject entry {
        if self.resolving {
            if not here.destroyed and here.active {
                print(f"    -> match: {here.name} order={self.resolved}");
            }
            self.resolving = False;
            disengage;
        }
        if here.destroyed {
            print(f"[DESTROYED] {here.name}: purge binding caches");
            visit [->:OwnsBinding:->];
            disengage;
        }
        if here.name in self.visited {
            print(f"[CYCLE] halt at {here.name}");
            disengage;
        }
        self.visited.append(here.name);
        label = "active" if here.active else "inactive";
        print(f"[{label}] {here.name} depth={self.depth}");
        visit [->:OwnsBinding:->];
        if self.depth >= self.max_depth {
            disengage;
        }
        self.depth += 1;
        visit [->:ChildOf:->] else { disengage; };
    }

    can leave_scene with SceneObject exit {
        if not self.resolving {
            self.depth -= 1;
        }
    }

    can resolve_binding with RelationalBinding entry {
        req = "optional" if here.optional else "required";
        print(f"  binding {here.field_name} ({here.cardinality}, {req})");
        self.resolving = True;
        visit [->:Targets:->] else {
            if not here.optional {
                print(f"  [MISSING] required field {here.field_name}");
            }
        };
        self.resolved += 1;
        visit [->:CachedPlan:->];
    }

    can purge_binding with RelationalBinding entry {
        visit [->:CachedPlan:->];
    }

    can purge_cache with CacheEntry entry {
        here.invalidated = True;
        here.published = False;
        here.atomic_ready = False;
        print(f"  [CACHE PURGE] was tier={here.tier}");
    }
}

walker CachePublisher {
    can start with Root entry {
        print("--- Cache tier publication ---");
        visit [-->];
    }

    can publish with CacheEntry entry {
        if here.invalidated {
            print(f"[SKIP] purged entry value={here.value}");
            disengage;
        }
        if here.published and here.atomic_ready {
            tier_label = "generated" if here.tier == "generated" else here.tier;
            print(f"[WARM] tier={tier_label} value={here.value}");
            disengage;
        }
        draft_tier = here.tier;
        draft_value = here.value;
        if draft_value == "" {
            print(f"[COLD] building plan tier={draft_tier}");
            draft_value = f"plan:{draft_tier}:v1";
        }
        next_tier = "generated" if draft_tier == "reflection" else draft_tier;
        here.value = draft_value;
        here.tier = next_tier;
        here.atomic_ready = True;
        here.published = True;
        print(f"[PUBLISH] atomic tier={here.tier} value={here.value}");
        visit [-->];
    }
}

walker SingletonAuditor {
    has seen: list = [];
    has duplicates: int = 0;
    has transitions: int = 0;

    can start with Root entry {
        print("--- Singleton lifecycle audit ---");
        visit [-->];
    }

    can audit with RuntimeSingleton entry {
        if here.state == "NeverCreate" {
            print(f"[BLOCKED] {here.service_name} NeverCreate");
            disengage;
        }
        if here.state == "Destroyed" {
            print(f"[INVALID] {here.service_name} accessed after destroy");
            disengage;
        }
        if here.service_name in self.seen {
            self.duplicates += 1;
            print(f"[DUPLICATE] {here.service_name} state={here.state}");
            disengage;
        }
        self.seen.append(here.service_name);
        prev = here.state;
        next_state = prev;
        if prev == "Uninitialized" {
            next_state = "RuntimeCreated";
        } else if prev == "Authored" {
            next_state = "Active";
        } else if prev == "ResourceLoaded" {
            next_state = "Active";
        } else if prev == "RuntimeCreated" {
            next_state = "Active";
        }
        if next_state != prev {
            here.state = next_state;
            self.transitions += 1;
            print(f"{here.service_name}: {prev} -> {next_state}");
        } else {
            print(f"{here.service_name}: hold {prev}");
        }
        visit [-->];
    }
}

