        field_name="weapon", cardinality="single", optional=False
    );
    stale_bind = RelationalBinding(
        field_name="stale", cardinality="single", optional=True
    );
    player +>:OwnsBinding:+> weapon_bind;
    manager +>:OwnsBinding:+> stale_bind;
    weapon_bind +>:Targets(match_order=0):+> weapon;
    stale_bind +>:Targets(match_order=0):+> stale;

    cold_cache = CacheEntry(tier="reflection");
    warm_cache = CacheEntry(tier="generated", published=True,
        value="plan:generated:v1", atomic_ready=True);
    weapon_bind +>:CachedPlan(warm=False):+> cold_cache;
    stale_bind +>:CachedPlan(warm=False):+> warm_cache;

    root ++> cold_cache ++> warm_cache;

    audio = RuntimeSingleton(service_name="Audio", state="Uninitialized");
    input = RuntimeSingleton(service_name="Input", state="Authored");
    resources = RuntimeSingleton(service_name="Resources", state="ResourceLoaded");
    blocked = RuntimeSingleton(service_name="Diagnostics", state="NeverCreate");
    ghost = RuntimeSingleton(service_name="Ghost", state="Destroyed");
    dupe = RuntimeSingleton(service_name="Audio", state="RuntimeCreated");

    root ++> audio ++> input ++> resources ++> blocked ++> ghost ++> dupe;

    root spawn BindingAuditor();
    root spawn CachePublisher();
    singleton = SingletonAuditor();
    root spawn singleton;
    print(f"singleton transitions={singleton.transitions} "
          f"duplicates={singleton.duplicates}");
}

"""Braavo domain lifecycles: same-package award invariants, frozen quote snapshots, and visible physical schema design."""

node Package {
    has name: str = "";
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

node CatalogItem {
    has title: str = "";
    has unit_price: int = 0;
    has pk_design: str = "";
    has pk_indexed: bool = False;
    has available: bool = True;
}

node Bid {
    has label: str = "";
    has status: str = "open";
    has year: int = 0;
    has available: bool = True;
}

node QuoteSnapshot {
    has label: str = "";
    has frozen_title: str = "";
    has frozen_price: int = 0;
    has year: int = 0;
    has available: bool = True;
}

edge InPackage { }

edge Awards { }

edge SnapshotOf {
    has captured_at: str = "";
}

walker IntegrityPatrol {
    has active_pkg: str = "";
    has bid_home_pkg: str = "";
    has checking_award: bool = False;

    can start with Root entry {
        visit [-->];
    }

    can on_package with Package entry {
        if self.checking_award {
            verdict = "OK" if here.name == self.bid_home_pkg else "VIOLATION";
            detail = "same-package award" if here.name == self.bid_home_pkg else "cross-package award blocked";
            print(f"  [{verdict}] bid in {self.bid_home_pkg} awards item in {here.name}: {detail}");
            self.checking_award = False;
            disengage;
        }
        self.active_pkg = here.name;
        print(f"Auditing package '{self.active_pkg}'");
        visit [->:InPackage:->] else { disengage; }
    }

    can on_bid with Bid entry {
        self.bid_home_pkg = self.active_pkg;
        self.checking_award = True;
        visit [->:Awards:->] else {
            self.checking_award = False;
            disengage;
        }
    }

    can on_catalog with CatalogItem entry {
        if self.checking_award {
            visit [<--:InPackage:--] else {
                print("  [VIOLATION] awarded item has no owning package");
                self.checking_award = False;
                disengage;
            }
        } else {
            print(f"  member item '{here.title}' in {self.active_pkg}");
            disengage;
        }
    }
}

walker SnapshotGuard {
    can start with Root entry {
        visit [-->];
    }

    can traverse_pkg with Package entry {
        visit [->:InPackage:->] else { disengage; }
    }

    can guard with CatalogItem entry {
        print(f"Live catalog now reads: {here.title} @ {here.unit_price}");
        visit [->:SnapshotOf:->] else { disengage; }
    }

    can read_snapshot with QuoteSnapshot entry {
        print(f"  Snapshot {here.label} still means: {here.frozen_title} @ {here.frozen_price}");
        disengage;
    }
}

walker SchemaReviewer {
    can start with Root entry {
        visit [-->];
    }

    can traverse_pkg with Package entry {
        visit [->:InPackage:->] else { disengage; }
    }

    can review_catalog with CatalogItem entry {
        kind = "INDEX" if here.pk_indexed else "KEY";
        print(f"  CatalogItem '{here.title}': physical {kind} '{here.pk_design}' (reviewed design, not silent DDL)");
        disengage;
    }

    can review_bid with Bid entry {
        print(f"  Bid '{here.label}': relation target validated via Awards edge, not implicit FK");
        disengage;
    }
}

with entry {
    procurement = Package(name="procurement", title="Procurement");
    external_vendor = Package(name="external_vendor", title="External Vendor");
    root ++> procurement;
    root ++> external_vendor;

    widget = CatalogItem(
        title="Widget",
        unit_price=100,
