    root spawn IntegrityPatrol();
    root spawn SnapshotGuard();
    root spawn SchemaReviewer();
}

"""DeltaSense OSP demo: validate ordered local image pairs, then run a selected
detection or segmentation checkpoint on both frames with shared settings."""

node ComparisonPair {
    has pair_id: str = "";
    has status: str = "pending";
    has reject_reason: str = "";
    has before_width: int = 0;
    has before_height: int = 0;
}

node ImageAsset {
    has path: str = "";
    has format: str = "";
    has width: int = 0;
    has height: int = 0;
    has orientation: int = 1;
    has readable: bool = True;
    has is_directory: bool = False;
    has is_remote: bool = False;
}

node ModelCheckpoint {
    has name: str = "";
    has task: str = "";
    has weights_present: bool = True;
}

node InferenceSettings {
    has device: str = "cpu";
    has conf_threshold: float = 0.25;
    has iou_threshold: float = 0.45;
}

node Prediction {
    has class_id: int = 0;
    has class_name: str = "";
    has score: float = 0.0;
    has box_x: int = 0;
    has box_y: int = 0;
    has box_w: int = 0;
    has box_h: int = 0;
}

edge BeforeFrame { }
edge AfterFrame { }
edge SelectedModel { }
edge EffectiveSettings { }
edge EmitsPrediction { }

walker PairValidator {
    has slot: str = "";
    has errors: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can audit with ComparisonPair entry {
        self.errors = [];
        self.slot = "before";
        here.status = "validating";
        visit [->:BeforeFrame:->];
        if self.errors {
            here.status = "rejected";
            here.reject_reason = self.errors[0];
            print(f"[REJECT] {here.pair_id}: {here.reject_reason}");
            visit [-->];
            return;
        }
        self.slot = "after";
        visit [->:AfterFrame:->];
        if self.errors {
            here.status = "rejected";
            here.reject_reason = self.errors[0];
            print(f"[REJECT] {here.pair_id}: {here.reject_reason}");
            visit [-->];
            return;
        }
        visit [->:SelectedModel:->];
        if self.errors {
            here.status = "rejected";
            here.reject_reason = self.errors[0];
            print(f"[REJECT] {here.pair_id}: {here.reject_reason}");
            visit [-->];
            return;
        }
        here.status = "validated";
        print(f"[OK] {here.pair_id} inputs ({here.before_width}x{here.before_height})");
        visit [-->];
    }

    can inspect with ImageAsset entry {
        allowed = here.format in ["jpeg", "png"];
        if here.is_directory {
            self.errors.append(f"{here.path} is a directory");
        } elif here.is_remote {
            self.errors.append(f"{here.path} is not a local path");
        } elif not allowed {
            self.errors.append(f"{here.path} format {here.format} unsupported");
        } elif not here.readable {
            self.errors.append(f"{here.path} unreadable or corrupt");
        }
        if self.slot == "before" {
            here.pair_ref.before_width = here.width;
            here.pair_ref.before_height = here.height;
            orient_note = "upright" if here.orientation == 1 else f"oriented({here.orientation})";
            print(f"  before {here.path} {here.width}x{here.height} {orient_note}");
        } else {
            if here.width != here.pair_ref.before_width or here.height != here.pair_ref.before_height {
                self.errors.append(
                    f"dimension mismatch {here.pair_ref.before_width}x{here.pair_ref.before_height}"
                    f" vs {here.width}x{here.height}"
                );
            } else {
                orient_note = "upright" if here.orientation == 1 else f"oriented({here.orientation})";
                print(f"  after  {here.path} {here.width}x{here.height} {orient_note}");
            }
        }
    }

    can verify with ModelCheckpoint entry {
        supported = here.task in ["detect", "segment"];
        if not here.weights_present {
            self.errors.append(f"checkpoint {here.name} missing weights");
        } elif not supported {
            self.errors.append(f"task {here.task} not supported");
        } else {
            print(f"  model  {here.name} ({here.task})");
        }
    }
}

walker InferenceRunner {
    has resolved_device: str = "cpu";
    has resolved_conf: float = 0.25;
    has resolved_iou: float = 0.45;
    has resolved_model: str = "";
    has resolved_task: str = "";

    can start with Root entry {
        visit [-->];
    }

    can run with ComparisonPair entry {
        if here.status != "validated" {
            visit [-->];
            return;
        }
        visit [->:EffectiveSettings:->];
        visit [->:SelectedModel:->];
        print(
            f"[INFER] {here.pair_id} model={self.resolved_model} "
            f"task={self.resolved_task} device={self.resolved_device} "
            f"conf={self.resolved_conf} iou={self.resolved_iou}"
        );
        visit [->:BeforeFrame:->];
        visit [->:AfterFrame:->];
        visit [-->];
    }

    can apply with InferenceSettings entry {
        self.resolved_device = here.device;
        self.resolved_conf = here.conf_threshold;
        self.resolved_iou = here.iou_threshold;
    }

    can bind with ModelCheckpoint entry {
        self.resolved_model = here.name;
        self.resolved_task = here.task;
    }

    can infer with ImageAsset entry {
        label = "before" if here is before_ref else "after";
        visit [->:EmitsPrediction:->] else {
            print(f"  {label} {here.path}: no predictions (empty)");
        };
    }

    can report with Prediction entry {
        print(
            f"    pred {here.class_name}#{here.class_id} "
            f"score={here.score:.2f} box=({here.box_x},{here.box_y},{here.box_w},{here.box_h})"
        );
    }
}

with entry {
