        width=320,
        height=240,
        readable=False
    );
    corrupt_after = ImageAsset(
        path="/data/site/after_03.png",
        format="png",
        width=320,
        height=240,
        readable=True
    );
    root ++> corrupt_pair;
    corrupt_pair +>:BeforeFrame:+> corrupt_before;
    corrupt_pair +>:AfterFrame:+> corrupt_after;
    corrupt_pair +>:SelectedModel:+> detect_ckpt;
    corrupt_pair +>:EffectiveSettings:+> settings;

    root spawn PairValidator();
    root spawn InferenceRunner();
}

"""Approved theme export: verify neutral vs branded semantic parity, then emit a version-pinned bundle with provenance and asset licensing."""

node ModelRevision {
    has revision_id: str = "";
    has title: str = "";
}

node WireframeView {
    has view_name: str = "";
    has fields: list[str] = [];
    has actions: list[str] = [];
    has bindings: list[str] = [];
    has nav_targets: list[str] = [];
    has is_branded: bool = False;

    def semantic_fingerprint() -> str {
        return (
            f"{self.fields}|{self.actions}|"
            f"{self.bindings}|{self.nav_targets}"
        );
    }
}

node BrandGuide {
    has source_ref: str = "";
    has extracted_at: str = "";
}

node BrandAsset {
    has asset_id: str = "";
    has license: str = "";
}

node ApprovedTheme {
    has theme_version: str = "";
    has theme_name: str = "";
    has approved: bool = True;
}

edge AdaptsModel { }
edge RendersView { has variant: str = "neutral"; }
edge ProvenanceFrom { }
edge IncludesAsset { }
edge BlockedBy { }

walker SemanticAuditor {
    has theme_version: str = "";
    has theme_name: str = "";
    has neutral_fp: str = "";
    has branded_fp: str = "";
    has views_seen: int = 0;
    has invariant: bool = True;

    can start with ApprovedTheme entry {
        self.theme_version = here.theme_version;
        self.theme_name = here.theme_name;
        visit [->:RendersView:->] else { disengage; };
    }

    can inspect with WireframeView entry {
        fp = here.semantic_fingerprint();
        if here.is_branded {
            self.branded_fp = fp;
        } else {
            self.neutral_fp = fp;
        }
        self.views_seen += 1;
        visit [-->] else { disengage; };
    }

    can report with ApprovedTheme exit {
        if self.neutral_fp != self.branded_fp {
            self.invariant = False;
            print(
                f"[DRIFT] {self.theme_name} ({self.theme_version}): "
                f"neutral/branded views differ"
            );
        } else {
            print(
                f"[OK] {self.theme_name} ({self.theme_version}): "
                f"semantic parity across {self.views_seen} previews"
            );
        }
    }
}

walker BundleExporter {
    has theme_version: str = "";
    has theme_name: str = "";
    has model_revision: str = "";
    has provenance: list[str] = [];
    has licenses: list[str] = [];
    has dependency_chain: list[str] = [];
    has seen_stages: list[str] = [];
    has cycle_detected: bool = False;

    can start with ApprovedTheme entry {
        self.theme_version = here.theme_version;
        self.theme_name = here.theme_name;
        stage_key = f"theme:{here.theme_version}";
        self.seen_stages.append(stage_key);
        self.dependency_chain.append(stage_key);
        visit [->:BlockedBy:->] else { disengage; };
    }

    can trace with ModelRevision | BrandGuide entry {
        stage_key = (
            f"model:{here.revision_id}"
            if here.revision_id
            else f"guide:{here.source_ref}"
        );
        if stage_key in self.seen_stages {
            self.cycle_detected = True;
            disengage;
        }
        self.seen_stages.append(stage_key);
        self.dependency_chain.append(stage_key);
        visit [->:BlockedBy:->] else {
            visit [->:AdaptsModel:->];
            visit [->:ProvenanceFrom:->];
            visit [->:IncludesAsset:->];
            disengage;
        };
    }

    can bind_model with ModelRevision entry {
        self.model_revision = here.revision_id;
    }

    can cite with BrandGuide entry {
        self.provenance.append(here.source_ref);
    }

    can license with BrandAsset entry {
        self.licenses.append(here.license);
    }

    can emit with ApprovedTheme exit {
        if self.cycle_detected {
            print(
                f"[BLOCKED] {self.theme_name} ({self.theme_version}): "
                f"dependency cycle in approval chain"
            );
        } else {
            chain = ", ".join(self.dependency_chain);
            sources = ", ".join(self.provenance);
            permits = ", ".join(self.licenses);
            print(
                f"EXPORT {self.theme_name} v{self.theme_version} "
                f"model={self.model_revision} chain=[{chain}] "
                f"provenance=[{sources}] licenses=[{permits}]"
            );
        }
    }
}

with entry {
    model = ModelRevision(
        revision_id="M-2026.08",
        title="Procurement wireframe base",
    );
    guide = BrandGuide(
        source_ref="brand/acme-style-guide.pdf",
        extracted_at="2026-08-28",
    );
    logo = BrandAsset(asset_id="logo.svg", license="CC-BY-4.0");
    icon = BrandAsset(asset_id="favicon.ico", license="Proprietary-Internal");

    neutral_ok = WireframeView(
        view_name="Home",
        fields=["title", "vendor", "amount"],
        actions=["submit", "save_draft"],
        bindings=["form.model", "cta.submit"],
        nav_targets=["/dashboard", "/settings"],
        is_branded=False,
    );
    branded_ok = WireframeView(
        view_name="Home",
        fields=["title", "vendor", "amount"],
        actions=["submit", "save_draft"],
        bindings=["form.model", "cta.submit"],
        nav_targets=["/dashboard", "/settings"],
        is_branded=True,
    );

    neutral_drift = WireframeView(
        view_name="Home",
        fields=["title", "vendor", "amount"],
        actions=["submit", "save_draft"],
        bindings=["form.model", "cta.submit"],
        nav_targets=["/dashboard", "/settings"],
        is_branded=False,
    );
    branded_drift = WireframeView(
        view_name="Home",
        fields=["title", "vendor", "amount"],
        actions=["submit", "save_draft"],
        bindings=["form.model", "cta.submit"],
        nav_targets=["/dashboard", "/settings", "/promo"],
        is_branded=True,
    );

    theme_ok = ApprovedTheme(
        theme_version="1.2.0",
        theme_name="Acme Procurement",
        approved=True,
    );
    theme_drift = ApprovedTheme(
        theme_version="0.9.0",
        theme_name="Acme Draft",
        approved=True,
    );

    root ++> theme_ok ++> theme_drift;

    theme_ok +>:BlockedBy:+> guide;
    guide +>:BlockedBy:+> model;

    theme_ok +>:AdaptsModel:+> model;
    theme_ok +>:RendersView(variant="neutral"):+> neutral_ok;
    theme_ok +>:RendersView(variant="branded"):+> branded_ok;
    theme_ok +>:ProvenanceFrom:+> guide;
    theme_ok +>:IncludesAsset:+> logo;
    theme_ok +>:IncludesAsset:+> icon;

    theme_drift +>:AdaptsModel:+> model;
    theme_drift +>:RendersView(variant="neutral"):+> neutral_drift;
    theme_drift +>:RendersView(variant="branded"):+> branded_drift;
    theme_drift +>:ProvenanceFrom:+> guide;
    theme_drift +>:IncludesAsset:+> logo;

    theme_ok spawn SemanticAuditor();
    theme_drift spawn SemanticAuditor();
    theme_ok spawn BundleExporter();
}

