"""Explainable state reachability diagnostics: distinguish reachable domain loops from disconnected cycles, surface external read-only references, and emit normalization advisories."""

node LifecycleState {
    has name: str = "";
    has is_initial: bool = False;
    has reachable: bool = False;
    has reference_list: str = "";
    has key_partial: str = "";
}

node ExternalCatalog {
    has name: str = "";
    has read_only: bool = True;
}

edge Transition {
    has label: str = "";
    has requires_screen: bool = True;
}

edge ExternalEntry {
    has rationale: str = "";
}

walker ReachabilityAuditor {
    can start with Root entry {
        visit [-->[?:LifecycleState]];
    }

    can explore with LifecycleState entry {
        if here.is_initial {
            self.flood_from(here);
        }
        visit [-->[?:LifecycleState]] else { disengage; };
    }

    def flood_from(origin: LifecycleState) {
        if origin.reachable {
            return;
        }
        origin.reachable = True;
        for target in [origin->:Transition:->] {
            self.flood_from(target);
        }
    }
}

walker StructuralDiagnostic {
    has findings: list[str] = [];
    has waived_state: str = "StalePending";
    has waiver_stale: bool = False;

    can start with Root entry {
        visit [-->[?:LifecycleState]];
    }

    can check_state with LifecycleState entry {
        if not here.reachable and self.in_local_cycle(here) {
            severity = "BLOCKING";
            evidence = f"cycle at '{here.name}' has transition edges but no path from any initial state";
            correction = "connect to an initial state, remove orphan transitions, or waive with rationale";
            msg = f"[{severity}] Disconnected state cycle — {evidence}; suggest: {correction}";
            self.findings.append(msg);
            print(msg);
            if here.name == self.waived_state {
                self.waiver_stale = True;
            }
        } else {
            if here.reachable and self.in_local_cycle(here) {
                severity = "INFO";
                msg = f"[{severity}] Valid reachable domain loop at '{here.name}' — intentional cyclic workflow";
                self.findings.append(msg);
                print(msg);
            }
        }
        if here.reachable and here.name == "Archived" {
            msg = "[INFO] Background transition reached 'Archived' — no mutating screen required";
            self.findings.append(msg);
            print(msg);
        }
        if here.reference_list != "" {
            msg = f"[ADVISORY] Repeating group in scalar field on '{here.name}' ({here.reference_list}) — decomposition suggested; functional dependencies not inferable";
            self.findings.append(msg);
            print(msg);
        }
        if here.key_partial != "" {
            msg = f"[ADVISORY] Incomplete key on '{here.name}' (partial='{here.key_partial}') — decision visible, no forced fiction";
            self.findings.append(msg);
            print(msg);
        }
        visit [-->[?:LifecycleState]] else {
            self.check_external_refs();
            disengage;
        };
    }

    def check_external_refs() {
        for catalog in [-->[?:ExternalCatalog]] {
            if catalog.read_only {
                for target in [catalog->:ExternalEntry:->] {
                    if not target.reachable {
                        msg = f"[ADVISORY] External catalog '{catalog.name}' references unreachable '{target.name}' — read-only data, no fictitious mutating screen";
                        self.findings.append(msg);
                        print(msg);
                    }
                }
            }
        }
        if self.waiver_stale {
            stale_msg = f"[ADVISORY] Waiver for '{self.waived_state}' is stale — relevant model facts still contradict the waiver";
            self.findings.append(stale_msg);
            print(stale_msg);
        }
        total = len(self.findings);
        print(f"--- diagnostic report: {total} finding(s) ---");
    }

    def in_local_cycle(state: LifecycleState) -> bool {
        for nxt in [state->:Transition:->] {
            for back in [nxt->:Transition:->] {
                if back == state {
                    return True;
                }
            }
        }
        return False;
    }
}

with entry {
    draft = LifecycleState(name="Draft", is_initial=True);
    review = LifecycleState(name="Review", reference_list="tag1,tag2,tag3");
    approved = LifecycleState(name="Approved");
    archived = LifecycleState(name="Archived");
    stale_pending = LifecycleState(name="StalePending", key_partial="vendor_id");
    stale_done = LifecycleState(name="StaleDone");

    vendor_catalog = ExternalCatalog(name="VendorCatalog", read_only=True);

    root ++> draft;
    draft +>:Transition(label="submit", requires_screen=True):+> review;
    review +>:Transition(label="approve", requires_screen=True):+> approved;
