    approved +>:Transition(label="archive", requires_screen=False):+> archived;
    stale_pending +>:Transition(label="process", requires_screen=True):+> stale_done;
    stale_done +>:Transition(label="requeue", requires_screen=True):+> stale_pending;
    vendor_catalog +>:ExternalEntry(rationale="read-only vendor SKU lookup"):+> stale_pending;

    root spawn ReachabilityAuditor();
    root spawn StructuralDiagnostic();
}

