"""Braavo model readiness: seeded phases, gate evaluation, advisories, and publication policy."""

node Product {
    has name: str = "";
    has guidance_seeded: bool = False;
}

node Phase {
    has title: str = "";
    has order: int = 0;
}

node Gate {
    has name: str = "";
    has explanation: str = "";
    has destination: str = "";
    has complete: bool = False;
    has structural_blocker: bool = False;
}

node Advisory {
    has topic: str = "";
    has acknowledged: bool = False;
    has requires_ack_for_publish: bool = True;
}

edge Guided { }
edge PhaseNext { }
edge HasGate { }
edge HasAdvisory { }

def seed_guidance(product: Product) -> None {
    if product.guidance_seeded {
        print(f"(seed skipped — guidance already present for {product.name})");
        return;
    }
    intent = Phase(title="Intent & Scope", order=1);
    structure = Phase(title="Model Structure", order=2);
    review = Phase(title="Publication Review", order=3);
    product +>:Guided:+> intent;
    intent +>:PhaseNext:+> structure;
    structure +>:PhaseNext:+> review;
    intent +>:HasGate:+> Gate(
        name="intent_captured",
        explanation="Document product intent and success criteria",
        destination="/intent",
        complete=True
    );
    intent +>:HasGate:+> Gate(
        name="stakeholders_identified",
        explanation="Identify stakeholders and ownership",
        destination="/stakeholders",
        complete=False
    );
    intent +>:HasAdvisory:+> Advisory(
        topic="Procurement is an example domain — label clearly in copy",
        acknowledged=False
    );
    structure +>:HasGate:+> Gate(
        name="entities_defined",
        explanation="Add or edit core entities and states",
        destination="/entities",
        complete=False,
        structural_blocker=True
    );
    structure +>:HasAdvisory:+> Advisory(
        topic="Wireframe composition is advisory until reviewed",
        acknowledged=False
    );
    review +>:HasGate:+> Gate(
