"""Brand theme provenance: audit draft tokens against uploaded assets and gate branded display on explicit approval."""

node BrandAsset {
    has name: str = "";
    has kind: str = "";
    has is_private: bool = True;
}

node ThemeToken {
    has key: str = "";
    has value: str = "";
    has is_inferred: bool = False;
}

node ThemeDraft {
    has name: str = "";
    has approved: bool = False;
}

node ThemeVersion {
    has label: str = "";
    has version: int = 1;
    has is_active: bool = False;
}

edge Provenance {
    has page: int = 0;
}

edge DraftHas { }

edge ExtractedFrom { }

edge ApprovedAs { }

walker ProvenanceAuditor {
    has violations: int = 0;
    has traced: int = 0;

    can start with Root entry {
        print("--- provenance audit ---");
        visit [-->[?:ThemeDraft]] else { disengage; };
    }

    can review_draft with ThemeDraft entry {
        print(f"draft: {here.name} (approved={here.approved})");
        visit [->:DraftHas:->] else {
            print("  (no tokens)");
            disengage;
        };
    }

    can inspect_token with ThemeToken entry {
        if here.is_inferred {
            print(f"  [INFERRED] {here.key}={here.value}");
        } else {
            print(f"  [ASSET-BACKED] {here.key}={here.value}");
            visit [->:Provenance:->] else {
                self.violations += 1;
                print(f"    VIOLATION: {here.key} lacks provenance edge");
            };
        }
        visit [-->];
    }

    can confirm_asset with BrandAsset entry {
        self.traced += 1;
        print(f"    -> source: {here.name} ({here.kind}, private={here.is_private})");
        disengage;
    }
}

walker ThemeApplicator {
    has branded: bool = False;

    can start with Root entry {
        print("--- theme display gate ---");
        visit [-->[?:ThemeVersion]] else {
            print("NEUTRAL: no approved theme versions");
            disengage;
        };
    }

    can apply with ThemeVersion entry {
        if here.is_active {
            print(f"BRANDED: {here.label} v{here.version}");
            self.branded = True;
            visit [<--:ApprovedAs:--] else { disengage; };
        } else {
            visit [-->];
        }
    }

    can load_draft with ThemeDraft entry {
        if not here.approved {
            print("NEUTRAL: draft not explicitly approved");
            disengage;
        }
        visit [->:DraftHas:->] else { disengage; };
    }

    can render with ThemeToken entry {
        origin = "inferred-default" if here.is_inferred else "provenance-backed";
        print(f"  {here.key}={here.value} [{origin}]");
        visit [-->];
    }
}

with entry {
    style_pdf = BrandAsset(name="StyleGuide.pdf", kind="pdf");
