"""PP1 dependency map: native parent/sub-issue and blocked-by edges with frontier, impact, and cycle walkers."""

node Issue {
    has title: str = "";
    has number: int = 0;
    has open: bool = True;
    has milestone: str = "";
    has assigned: bool = False;
    has needs_decision: bool = False;
}

edge SubIssue { }

edge BlockedBy { }

walker CycleGuard {
    has path: list[int] = [];
    has hit: bool = False;
    has detail: str = "";
    has in_dfs: bool = False;

    can start with Root entry {
        visit [-->];
    }

    can walk with Issue entry {
        if self.hit {
            disengage;
        }
        if self.in_dfs {
            for p in self.path {
                if p == here.number {
                    self.hit = True;
                    self.detail = f"BlockedBy cycle at issue #{here.number}";
                    print(f"[CYCLE] {self.detail}");
                    disengage;
                }
            }
            self.path.append(here.number);
            visit [->:BlockedBy:->] else { };
        } else {
            self.in_dfs = True;
            self.path = [];
            self.path.append(here.number);
            visit [->:BlockedBy:->] else { };
            self.in_dfs = False;
            self.path = [];
            visit [->:SubIssue:->];
            visit [-->];
        }
    }

    can walk with Issue exit {
        if self.in_dfs && len(self.path) > 0 {
            self.path.pop();
        }
    }
}

walker FrontierFinder {
    has horizon: str = "PP1";
    has open_blockers: int = 0;
    has checking: bool = False;

    can start with Root entry {
        print(f"=== PP1 frontier (horizon={self.horizon}) ===");
        visit [-->];
    }

    can scan with Issue entry {
        if self.checking {
            if here.open {
                self.open_blockers += 1;
            }
            disengage;
        }
        if here.open && here.milestone == self.horizon {
            self.open_blockers = 0;
            self.checking = True;
            visit [->:BlockedBy:->] else { };
            self.checking = False;
            status = "READY";
            if self.open_blockers > 0 {
                status = "BLOCKED";
            } elif here.needs_decision {
                status = "DECISION";
            } elif here.assigned {
                status = "IN_PROGRESS";
            }
            print(f"[{status}] #{here.number} {here.title}");
        } elif !here.open && here.milestone == self.horizon {
            print(f"[CLOSED] #{here.number} {here.title}");
        }
        visit [->:SubIssue:->];
        visit [-->];
    }
}

walker ImpactTracer {
    has phase: str = "up";

    can start with Issue entry {
        print(f"=== Impact trace for #{here.number} {here.title} ===");
        print("Upstream prerequisites (BlockedBy):");
        self.phase = "up";
        visit [->:BlockedBy:->] else {
            print("  (none)");
        };
        print("Downstream impact (blocks):");
        self.phase = "down";
        visit [<--:BlockedBy:--] else {
            print("  (none)");
        };
        disengage;
    }

    can trace with Issue entry {
        tag = "OPEN" if here.open else "CLOSED";
        print(f"  [{tag}] #{here.number} {here.title}");
        if self.phase == "up" {
            visit [->:BlockedBy:->];
        } else {
            visit [<--:BlockedBy:--];
        }
    }
}

walker HierarchyPrinter {
    has indent: int = 0;

    can start with Root entry {
        print("=== Parent/sub-issue hierarchy ===");
        visit [-->];
    }

    can show with Issue entry {
        pad = "";
        for _i in range(self.indent) {
            pad += "  ";
        }
        state = "open" if here.open else "closed";
        print(f"{pad}#{here.number} {here.title} ({state}, {here.milestone})");
        self.indent += 1;
        visit [->:SubIssue:->] else { };
        self.indent -= 1;
        visit [-->];
    }
}

