"""PP1 dependency map: native parent/sub-issue and blocked-by edges with frontier, impact, and cycle walkers."""

node Issue {
    has title: str = "";
    has number: int = 0;
    has open: bool = True;
    has milestone: str = "";
    has assigned: bool = False;
    has needs_decision: bool = False;

    def seen_in(items: list[int], val: int) -> bool {
        for x in items {
            if x == val {
                return True;
            }
        }
        return False;
    }
}

edge SubIssue { }

edge BlockedBy { }

walker CycleGuard {
    has path: list[int] = [];
    has hit: bool = False;
    has in_dfs: bool = False;
    has visited: list[int] = [];

    can start with Root entry {
        print("=== BlockedBy cycle scan ===");
        visit [-->];
    }

    can walk with Issue entry {
        if self.hit {
            disengage;
        }
        if self.in_dfs {
            if here.seen_in(self.path, here.number) {
                self.hit = True;
                print(f"[CYCLE] BlockedBy cycle at issue #{here.number}");
                disengage;
            }
            self.path.append(here.number);
            visit [->:BlockedBy:->] else { disengage; }
        } else {
            if here.seen_in(self.visited, here.number) {
                disengage;
            }
            self.visited.append(here.number);
            self.in_dfs = True;
            self.path = [];
            self.path.append(here.number);
            visit [->:BlockedBy:->] else { disengage; }
            self.in_dfs = False;
            self.path = [];
            if not self.hit {
                print(f"[OK] #{here.number} BlockedBy chain acyclic");
            }
            visit [->:SubIssue:->];
            visit [-->];
        }
    }

    can walk with Issue exit {
        if self.in_dfs and len(self.path) > 0 {
            self.path.pop();
        }
    }
}

walker FrontierFinder {
    has horizon: str = "PP1";
    has open_blockers: int = 0;
    has checking: bool = False;
    has visited: list[int] = [];

    can start with Root entry {
        print(f"=== PP1 frontier (horizon={self.horizon}) ===");
        visit [-->];
    }

    can scan with Issue entry {
        if self.checking {
            if here.open {
                self.open_blockers += 1;
            }
            disengage;
        }
        if here.seen_in(self.visited, here.number) {
            disengage;
        }
        self.visited.append(here.number);
        if here.open and here.milestone == self.horizon {
            self.open_blockers = 0;
            self.checking = True;
            visit [->:BlockedBy:->] else { disengage; }
            self.checking = False;
            status = "READY";
            if self.open_blockers > 0 {
                status = "BLOCKED";
            } else if here.needs_decision {
                status = "DECISION";
            } else if here.assigned {
                status = "IN_PROGRESS";
            }
            print(f"[{status}] #{here.number} {here.title}");
        } else if not here.open and here.milestone == self.horizon {
            print(f"[CLOSED] #{here.number} {here.title}");
        }
        visit [->:SubIssue:->];
        visit [-->];
    }
}

walker ImpactTracer {
    has phase: str = "up";
    has seen: list[int] = [];

    can start with Issue entry {
        print(f"=== Impact trace for #{here.number} {here.title} ===");
        print("Upstream prerequisites (BlockedBy):");
        self.phase = "up";
        self.seen = [];
        visit [->:BlockedBy:->] else {
            print("  (none)");
        }
        print("Downstream impact (blocks):");
        self.phase = "down";
        self.seen = [];
        visit [<--:BlockedBy:--] else {
            print("  (none)");
        }
        disengage;
    }

    can trace with Issue entry {
        if here.seen_in(self.seen, here.number) {
            disengage;
        }
        self.seen.append(here.number);
        tag = "OPEN" if here.open else "CLOSED";
        print(f"  [{tag}] #{here.number} {here.title}");
        if self.phase == "up" {
            visit [->:BlockedBy:->];
        } else {
            visit [<--:BlockedBy:--];
        }
    }
}

walker HierarchyPrinter {
    has indent: int = 0;
    has visited: list[int] = [];

    can start with Root entry {
        print("=== Parent/sub-issue hierarchy ===");
        visit [-->];
    }

    can show with Issue entry {
        if here.seen_in(self.visited, here.number) {
            disengage;
        }
        self.visited.append(here.number);
        pad = "";
        for _i in range(self.indent) {
            pad += "  ";
        }
        state = "open" if here.open else "closed";
        print(f"{pad}#{here.number} {here.title} ({state}, {here.milestone})");
        self.indent += 1;
        visit [->:SubIssue:->] else { disengage; }
        self.indent -= 1;
    }
}

