"""Avenx dev-server incrementality: per-file content-hash cache and dependency invalidation over IMPORTS, RENDERS, and ROUTES_TO."""

node SourceFile {
    has path: str = "";
    has content_hash: str = "";
    has compiled: bool = False;
    has cache_valid: bool = True;
    has needs_rebuild: bool = False;
}

node Component(SourceFile) {
    has unit_kind: str = "component";
}

node Stylesheet(SourceFile) {
    has unit_kind: str = "stylesheet";
}

edge Imports { }
edge Renders { }
edge RoutesTo { }

walker ColdBuild {
    has total: int = 0;

    can start with Root entry {
        print("=== Cold build (full project) ===");
        visit [-->[?:SourceFile]];
    }

    can compile with Component | Stylesheet entry {
        print(f"[COLD] {here.path} hash={here.content_hash}");
        here.compiled = True;
        here.cache_valid = True;
        here.needs_rebuild = False;
        self.total += 1;
        visit [-->] else { disengage; };
    }
}

walker DependencyInvalidator {
    has visited: list[str] = [];

    can start with SourceFile entry {
        here.needs_rebuild = True;
        here.cache_valid = False;
        print(f"[CHANGE] {here.path} -> hash={here.content_hash}");
        visit [<--:Imports:--], [<--:Renders:--], [<--:RoutesTo:--] else { disengage; };
    }

    can ripple with SourceFile entry {
        if here.path in self.visited {
            print(f"[CYCLE GUARD] {here.path}");
            disengage;
        }
        self.visited.append(here.path);
        here.needs_rebuild = True;
        here.cache_valid = False;
        print(f"[INVALIDATE] {here.path}");
        visit [<--:Imports:--], [<--:Renders:--], [<--:RoutesTo:--] else { disengage; };
    }
}

walker WatchRebuild {
    has recompiled: int = 0;
    has cached: int = 0;

    can start with Root entry {
        print("--- Watch incremental rebuild ---");
        visit [-->[?:SourceFile]];
    }

    can rebuild with Component | Stylesheet entry {
        if here.needs_rebuild {
            print(f"[REBUILD] {here.path} hash={here.content_hash}");
            here.compiled = True;
            here.cache_valid = True;
            here.needs_rebuild = False;
            self.recompiled += 1;
        } else {
            status = "HIT" if here.cache_valid else "MISS";
            print(f"[CACHE {status}] {here.path}");
            self.cached += 1;
        }
        visit [-->] else { disengage; };
    }
}

with entry {
    app = Component(path="src/app.ax", content_hash="aaa111", unit_kind="app");
    home = Component(path="src/pages/home.ax", content_hash="bbb222", unit_kind="page");
    widget = Component(path="src/components/Widget.ax", content_hash="ccc333", unit_kind="component");
