"""Braavo wireframe epic: model-backed screens, dependency blockers, and product ownership."""

node WorkItem {
    has title: str = "";
    has backlog_id: str = "";
    has level: str = "";
    has done: bool = False;
}

node Screen {
    has title: str = "";
    has archetype: str = "";
    has validated: bool = True;
}

node FieldSlot {
    has name: str = "";
    has binding: str = "";
}

node Product {
    has name: str = "";
    has steward: str = "";
}

edge BlockedBy { has reason: str = ""; }
edge ChildOf { }
edge Owns { }
edge Composes { has slot_name: str = ""; }

walker BlockerAuditor {
    has visited: list[str] = [];
    has pending: list[str] = [];
    has cycle_detected: bool = False;

    can audit with WorkItem entry {
        if here.backlog_id in self.visited {
            self.cycle_detected = True;
            disengage;
        }
        self.visited.append(here.backlog_id);
        if not here.done {
            self.pending.append(here.backlog_id);
        }
        visit [->:BlockedBy:->] else { disengage; };
    }
}

walker BacklogExpander {
    has child_ids: list[str] = [];

    can start with WorkItem entry {
        visit [<--:ChildOf:--] else { disengage; };
    }

    can collect with WorkItem entry {
        self.child_ids.append(here.backlog_id);
        disengage;
    }
}

walker CompositionValidator {
    has violations: list[str] = [];

    can start with Screen entry {
        status = "VALIDATED" if here.validated else "DRAFT";
        print(f"[{status}] {here.archetype} screen: {here.title}");
        visit [->:Composes:->] else { disengage; };
    }

    can inspect_slot with FieldSlot entry {
        if here.binding == "" {
            self.violations.append(here.name);
            print(f"  [INVALID] slot '{here.name}' has no model binding");
        } else {
            print(f"  [bound] {here.name} -> {here.binding}");
        }
        disengage;
    }
}

walker OwnershipPatrol {
    has actor: str = "";
    has steward: str = "";
    has denied: list[str] = [];

    can start with Product entry {
        self.steward = here.steward;
        visit [->:Owns:->] else { disengage; };
    }

    can gate_work with WorkItem entry {
        if self.actor != self.steward {
            self.denied.append(here.backlog_id);
        }
        disengage;
    }

    can gate_screen with Screen entry {
        if self.actor != self.steward {
            self.denied.append(here.title);
        }
        disengage;
    }
}

