"""CI/CD admission deadlock: candidate-intrinsic Master gates, governed deploys, post-deploy E2E."""

node Commit {
    has sha: str = "";
    has is_current_main: bool = True;
}

node Gate {
    has name: str = "";
    has passed: bool = False;
    has is_intrinsic: bool = True;
}

node DeployOwner {
    has name: str = "";
    has status: str = "pending";
    has sha: str = "";
}

node E2ERun {
    has phase: str = "post_deploy";
    has passed: bool = False;
    has identity_provisioned: bool = False;
    has identity_cleaned: bool = False;
}

edge Gates { has blocking: bool = True; }
edge Admits { }
edge RequiresBoth { }
edge DependsOn { }

walker CycleGuard {
    has visited: list[str] = [];
    has cycle_found: bool = False;

    can start with Root entry {
        visit [-->[?:Gate]] else {
            disengage;
        };
    }

    can enter with Gate entry {
        if here.name != "Quality Playwright smoke trusted" {
            disengage;
        }
        key = here.name;
        if key in self.visited {
            self.cycle_found = True;
            print(f"CYCLE: {key} revisited — pre-deploy E2E blocks deploy blocks runtime");
            disengage;
        }
        self.visited.append(key);
        visit [->:DependsOn:->] else {
            disengage;
        };
    }

    can probe with Gate | DeployOwner entry {
        key = here.name;
        if key in self.visited {
            self.cycle_found = True;
            print(f"CYCLE: {key} revisited — pre-deploy E2E blocks deploy blocks runtime");
            disengage;
        }
        self.visited.append(key);
        visit [->:DependsOn:->] else {
            disengage;
        };
    }
}

walker MasterAdmission {
    has intrinsic_pass: bool = True;
    has target_sha: str = "";

    can start with Root entry {
        visit [-->[?:Commit]] else {
            disengage;
        };
    }

    can on_commit with Commit entry {
        self.target_sha = here.sha;
        print(f"Evaluating push admission for {here.sha}");
        visit [-->[?:DeployOwner]] else {
            disengage;
        };
    }

    can on_master with DeployOwner entry {
        if here.name != "Master System" {
            disengage;
        }
        print("Master System: candidate-intrinsic gates only (no pre-deploy Production E2E)");
        visit [->:Gates:->] else {
            disengage;
        };
        if self.intrinsic_pass {
            here.status = "success";
            here.sha = self.target_sha;
            print("Master System: SUCCESS (candidate-intrinsic gates only)");
        } else {
            here.status = "failure";
            print("Master System: FAILURE");
        }
        disengage;
    }

    can on_gate with Gate entry {
        if here.is_intrinsic {
            gate_label = "PASS" if here.passed else "FAIL";
            print(f"  intrinsic [{here.name}]: {gate_label}");
            if not here.passed {
                self.intrinsic_pass = False;
            }
        } else {
            skip_label = "skipped (stale Production runtime)";
            print(f"  pre-deploy [{here.name}]: {skip_label}");
        }
    }
}

walker GovernedDeploy {
    has target_sha: str = "";

    can start with DeployOwner entry {
        if here.name != "Master System" {
            disengage;
        }
        if here.status != "success" {
            print("Deploy owners: REJECT (Master System not successful)");
            disengage;
        }
        self.target_sha = here.sha;
        print(f"Deploy owners: admit exact-SHA {self.target_sha}");
        visit [->:Admits:->] else {
            disengage;
        };
        disengage;
    }

    can deploy with DeployOwner entry {
        if self.target_sha == "" {
            disengage;
        }
        if here.name == "Deploy Standalone Edge Functions" {
            here.status = "success";
            here.sha = self.target_sha;
            print(f"Edge deploy: SUCCESS @ {here.sha}");
        }
        if here.name == "Cloudflare Frontend Acceptance" {
            here.status = "success";
            here.sha = self.target_sha;
            print(f"Cloudflare deploy: SUCCESS @ {here.sha}");
        }
    }
}

walker PostDeployE2E {
    has edge_sha: str = "";
    has cf_sha: str = "";
    has owners_seen: int = 0;

    can run with E2ERun entry {
        if here.phase != "post_deploy" {
            print(f"Post-deploy E2E: BLOCKED (phase={here.phase} forbidden in admission)");
            disengage;
        }
        visit [<--:RequiresBoth:--] else {
            if self.owners_seen < 2 {
                print("Post-deploy E2E: BLOCKED (deploy owners incomplete)");
                disengage;
            }
            if self.edge_sha == "" or self.cf_sha == "" {
                print("Post-deploy E2E: BLOCKED (deploy owners incomplete)");
                disengage;
            }
            if self.edge_sha != self.cf_sha {
                print(f"Post-deploy E2E: BLOCKED (SHA mismatch {self.edge_sha} vs {self.cf_sha})");
                disengage;
            }
            here.identity_provisioned = True;
            here.passed = True;
            here.identity_cleaned = True;
            print(f"Post-deploy authenticated E2E: PASS @ {self.edge_sha} (identity always cleaned)");
            disengage;
        };
    }

    can gather with DeployOwner entry {
        if here.status != "success" {
            disengage;
        }
        if here.name == "Deploy Standalone Edge Functions" {
            self.edge_sha = here.sha;
            self.owners_seen += 1;
        }
        if here.name == "Cloudflare Frontend Acceptance" {
            self.cf_sha = here.sha;
            self.owners_seen += 1;
        }
        disengage;
    }
}

with entry {
    sha = "fba61287109beea179ae7585b107a5aa03c764c8";
    commit = Commit(sha=sha, is_current_main=True);
    master = DeployOwner(name="Master System", status="pending", sha="");
    gate_repo = Gate(name="Quality repository+backend", passed=True, is_intrinsic=True);
    gate_fe = Gate(name="Quality frontend", passed=True, is_intrinsic=True);
