"""Site Locale Publication Contract v1: compile five critical families, detect cycles, evaluate readiness."""

node SiteLocale {
    has tag: str = "";
    has language: str = "";
}

node PublicationContract {
    has version: int = 1;
}

node ContractFamily {
    has key: str = "";
    has owner_adapter: str = "";
    has evidence: str = "checking";
}

node Proof {
    has proof_id: str = "";
    has resolved: bool = False;
}

node StoryPage {
    has title: str = "";
    has complete: bool = False;
}

edge ScopedTo { }
edge MemberOf { }
edge DependsOn { }
edge RequiresProof { }
edge OrdinaryStory { }

walker ContractCompiler {
    has seen_keys: list[str] = [];
    has dep_path: list[str] = [];
    has visit_mode: str = "member";
    has family_keys_seen: int = 0;
    has compile_ok: bool = True;

    can start with Root entry {
        visit [-->];
    }

    can scope with SiteLocale entry {
        visit [->:ScopedTo:->] else { disengage; }
    }

    can compile with PublicationContract entry {
        if here.version != 1 {
            self.compile_ok = False;
            print("reject unversioned contract change");
            disengage;
        }
        self.visit_mode = "member";
        visit [->:MemberOf:->] else {
            self.compile_ok = False;
            print("reject contract with no families");
            disengage;
        }
        if self.family_keys_seen != 5 {
            self.compile_ok = False;
            print(f"reject family count {self.family_keys_seen}, expected 5");
        }
        outcome = "OK" if self.compile_ok else "REJECTED";
        print(f"compilation {outcome}");
    }

    can audit with ContractFamily entry {
        if self.visit_mode == "member" {
            if here.key in self.seen_keys {
                self.compile_ok = False;
                print(f"reject duplicate family key {here.key}");
            } else {
                self.seen_keys.append(here.key);
            }
            self.family_keys_seen += 1;
            if here.owner_adapter == "" || here.owner_adapter == "unknown" {
                self.compile_ok = False;
                print(f"reject unknown owner adapter for {here.key}");
            }
            visit [->:RequiresProof:->] else { }
            self.dep_path = [];
            self.visit_mode = "deps";
            visit [->:DependsOn:->] else { }
            self.visit_mode = "member";
        } else {
            if here.key in self.dep_path {
                self.compile_ok = False;
                print(f"reject cyclic dependency at {here.key}");
                disengage;
            }
            self.dep_path.append(here.key);
            visit [->:DependsOn:->] else { }
        }
    }

    can verify_proof with Proof entry {
        if not here.resolved {
            self.compile_ok = False;
            print(f"reject unresolved proof {here.proof_id}");
        }
    }
}

walker PublicationEvaluator {
    has ready_count: int = 0;
    has blocking_count: int = 0;
    has missing_stories: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can scope with SiteLocale entry {
        visit [->:ScopedTo:->] else { disengage; }
        visit [->:OrdinaryStory:->] else { }
    }

    can summarize with PublicationContract entry {
        visit [->:MemberOf:->] else { disengage; }
        gate = "BLOCKED" if self.blocking_count > 0 else "NOT_BLOCKED";
        note = f"{self.missing_stories} ordinary stories missing (non-blocking)";
        print(f"locale publication {gate}; critical ready={self.ready_count}; {note}");
    }

    can read_evidence with ContractFamily entry {
        if here.evidence == "ready" {
            self.ready_count += 1;
            label = "ready";
        } elif here.evidence == "blocking" || here.evidence == "unavailable" {
            self.blocking_count += 1;
            label = here.evidence;
        } else {
            label = here.evidence;
        }
        print(f"[critical] {here.key} owner={here.owner_adapter} evidence={label}");
    }

    can tally_stories with StoryPage entry {
        if not here.complete {
            self.missing_stories += 1;
        }
        print(f"[non-critical] story '{here.title}' complete={here.complete}");
        visit [--> else { }];
    }
}

