"""AuthKit-style plugin discovery, compatibility gating, dependency ordering, and isolated loading."""

def parse_version(ver: str) -> list[int] {
    nums = [];
    for part in ver.split(".") {
        nums.append(int(part));
    }
    return nums;
}

def version_gte(host_ver: str, min_ver: str) -> bool {
    hv = parse_version(host_ver);
    mv = parse_version(min_ver);
    max_len = len(hv) if len(hv) > len(mv) else len(mv);
    for i in range(max_len) {
        h = hv[i] if i < len(hv) else 0;
        m = mv[i] if i < len(mv) else 0;
        if h > m {
            return True;
        }
        if h < m {
            return False;
        }
    }
    return True;
}

def validate_contract(plugin: Plugin) -> bool {
    return plugin.plugin_id != "";
}

node Host {
    has version: str = "1.0.0";
}

node Plugin {
    has plugin_id: str = "";
    has min_host_version: str = "0.0.0";
    has priority: int = 0;
    has registration_order: int = 0;
    has is_enabled: bool = True;
    has status: str = "pending";
    has context_id: str = "";
}

edge DependsOn { }

walker PluginDiscoverer {
    has host_version: str = "0.0.0";
    has cached_ids: list[str] = [];
    has discovered: list[str] = [];
    has rejected: list[str] = [];
    has disabled: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can read_host with Host entry {
        self.host_version = here.version;
        visit [-->];
    }

    can inspect with Plugin entry {
        if here.plugin_id in self.cached_ids {
            visit [-->];
        }
        self.cached_ids.append(here.plugin_id);
        if not here.is_enabled {
            here.status = "disabled";
            self.disabled.append(here.plugin_id);
        } elif version_gte(self.host_version, here.min_host_version) {
            here.status = "discovered";
            self.discovered.append(here.plugin_id);
        } else {
            here.status = "rejected";
            self.rejected.append(here.plugin_id);
        }
        visit [-->];
    }
}

walker PluginLoader {
    has load_order: list[str] = [];
    has visiting: list[str] = [];
    has cycle_detected: bool = False;
    has invalid: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can traverse with Host entry {
        visit [-->];
    }

    can load with Plugin entry {
        if here.status == "loaded" {
            visit [-->];
        }
        if here.status != "discovered" {
            visit [-->];
        }
        if here.plugin_id in self.visiting {
            here.status = "cycle_error";
            self.cycle_detected = True;
            disengage;
        }
        self.visiting.append(here.plugin_id);
        visit [->:DependsOn:->];
        if len(self.visiting) > 0 {
            self.visiting = self.visiting[: len(self.visiting) - 1];
        }
        if not validate_contract(here) {
            here.status = "invalid";
            self.invalid.append(here.plugin_id);
            visit [-->];
        }
        here.context_id = f"ALC-{here.plugin_id}";
        here.status = "loaded";
        self.load_order.append(here.plugin_id);
        visit [-->];
    }
}

