"""Gubbins location parent cycles: ancestor guards must terminate on existing loops."""

node Location {
    has name: str = "";
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

edge ParentOf { }

walker Catalog {
    can start with Root entry {
        visit [-->];
    }

    can list with Location entry {
        print(f"location: {here.name}");
        visit [-->];
    }
}

walker UnionAllGuard {
    has mover: Location;
    has vetoed: bool = False;
    has hops: int = 0;
    has hop_limit: int = 12;

    can audit with Location entry {
        self.hops += 1;
        if self.hops > self.hop_limit {
            print(
                f"[hang] UNION ALL walk from {here.name} blew past "
                f"{self.hop_limit} hops — tab would freeze"
            );
            disengage;
        }
        if here is self.mover {
            self.vetoed = True;
            disengage;
        }
        visit [<--:ParentOf:--] else { disengage; };
    }
}

walker AncestorGuard {
    has mover: Location;
    has vetoed: bool = False;
    has hops: int = 0;
    has seen: list[str] = [];

    can audit with Location entry {
        key = here.name;
        if key in self.seen {
            disengage;
        }
        self.seen.append(key);
        self.hops += 1;
        if here is self.mover {
            self.vetoed = True;
            disengage;
        }
        visit [<--:ParentOf:--] else { disengage; };
    }
}

with entry {
    a = Location(name="A", title="Shelf A");
    b = Location(name="B", title="Shelf B");
    c = Location(name="C", title="Shelf C");
    d = Location(name="D", title="Loose bin");

    a +>:ParentOf:+> c;
    c +>:ParentOf:+> b;
    b +>:ParentOf:+> a;

    root ++> a;
    root ++> d;

    print("=== catalog ===");
    root spawn Catalog();

    print("=== move D under B (cycle A→C→B→A already in data) ===");

    flawed = UnionAllGuard(mover=d);
    b spawn flawed;
    flawed_allowed = not flawed.vetoed;
    print(
        f"UNION ALL pre-check: vetoed={flawed.vetoed}, "
        f"hops={flawed.hops}, would_allow={flawed_allowed}"
    );

    fixed = AncestorGuard(mover=d);
    b spawn fixed;
    fixed_allowed = not fixed.vetoed;
    print(
        f"UNION pre-check: vetoed={fixed.vetoed}, "
        f"hops={fixed.hops}, would_allow={fixed_allowed}"
    );

    if fixed_allowed {
        d +>:ParentOf:+> b;
        print("relocated D under B");
    }

    print("=== self-descendant move B under C (must veto) ===");
    veto_probe = AncestorGuard(mover=b);
    c spawn veto_probe;
    vetoed = veto_probe.vetoed;
    print(f"UNION pre-check: vetoed={vetoed}, hops={veto_probe.hops}");
}

"""RAG corpus pipeline: parent-child chunk retrieval, sizing audit, cascade staleness, and stage ordering.

Models candidate_chatai improvement themes—oversized chunks, parent-child retrieval,
hybrid pipeline dependencies, and downstream invalidation—as native graph traversal.
"""

node Document {
    has title: str = "";
    has stale: bool = False;
}

node Section {
    has heading: str = "";
    has stale: bool = False;
}

node Chunk {
    has preview: str = "";
    has token_count: int = 0;
    has stale: bool = False;
    has is_match: bool = False;
}

node PipelineStage {
    has name: str = "";
    has done: bool = False;
}

edge Contains { }

edge ChildOf { }

edge DependsOn { }

walker SizingAuditor {
    has lo: int = 300;
    has hi: int = 500;
    has bad_count: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can audit_doc with Document entry {
        print(f"Auditing document: {here.title}");
        visit [->:Contains:->] else { disengage; };
    }

    can audit_section with Section entry {
        visit [->:Contains:->] else { disengage; };
    }

    can audit_chunk with Chunk entry {
        ok = here.token_count >= self.lo and here.token_count <= self.hi;
        label = "OK" if ok else "FIX";
        if not ok {
            self.bad_count += 1;
        }
        print(f"  [{label}] {here.preview} ({here.token_count} tokens)");
        disengage;
    }
}

walker StaleCascade {
    has invalidated: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can from_doc with Document entry {
        if not here.stale {
            disengage;
        }
        print(f"Cascading staleness from '{here.title}'");
        visit [->:Contains:->] else { disengage; };
    }

    can from_section with Section entry {
        here.stale = True;
        self.invalidated += 1;
        visit [->:Contains:->] else { disengage; };
    }

    can from_chunk with Chunk entry {
        here.stale = True;
        self.invalidated += 1;
        disengage;
    }
}

walker ParentRetriever {
    has parents_returned: list[str] = [];

    can start with Root entry {
        visit [-->[?:Chunk]];
    }

    can on_hit with Chunk entry {
        if not here.is_match {
            disengage;
        }
        print(f"Dense hit on precise chunk: '{here.preview}'");
        visit [<--:ChildOf:--] else { disengage; };
    }

    can lift_parent with Section entry {
        self.parents_returned.append(here.heading);
        print(f"Returning parent section '{here.heading}' to LLM context");
        disengage;
    }
}

walker PipelineRunner {
    has seen: list[str] = [];
    has order: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can run_stage with PipelineStage entry {
        if here.name in self.seen {
            print(f"[CYCLE] dependency loop at '{here.name}'");
            disengage;
        }
        self.seen.append(here.name);
        visit [->:DependsOn:->] else { disengage; };
        if not here.done {
            here.done = True;
            self.order.append(here.name);
            print(f"[STAGE] {here.name}");
        }
        disengage;
    }
}

with entry {
    guide = Document(title="RAG Architecture Guide");
    chunking_sec = Section(heading="Chunking");
    retrieval_sec = Section(heading="Hybrid Retrieval");
    huge = Chunk(preview="monolithic 4k block", token_count=4096);
    tight = Chunk(preview="recursive 420-token span", token_count=420, is_match=True);
    needle = Chunk(preview="BM25+dense fuse snippet", token_count=48, is_match=True);

    root ++> guide;
    guide +>:Contains:+> chunking_sec;
    chunking_sec +>:Contains:+> huge;
    chunking_sec +>:Contains:+> tight;
    tight +>:ChildOf:+> chunking_sec;
    guide +>:Contains:+> retrieval_sec;
    retrieval_sec +>:Contains:+> needle;
    needle +>:ChildOf:+> retrieval_sec;

    guide.stale = True;

    chunking = PipelineStage(name="chunking");
    indexing = PipelineStage(name="indexing");
    hybrid = PipelineStage(name="hybrid_retrieval");
    rerank = PipelineStage(name="rerank");
    generation = PipelineStage(name="generation");
    root ++> generation;
    generation +>:DependsOn:+> rerank;
    rerank +>:DependsOn:+> hybrid;
    hybrid +>:DependsOn:+> indexing;
    indexing +>:DependsOn:+> chunking;

    print("=== Sizing audit (issue #3: replace 4096-token chunks) ===");
    auditor = SizingAuditor();
    root spawn auditor;
    print(f"Chunks needing fix: {auditor.bad_count}");

    print("=== Cascade invalidation on document update ===");
    cascade = StaleCascade();
    root spawn cascade;
    print(f"Downstream nodes marked stale: {cascade.invalidated}");

    print("=== Parent-child retrieval (issue #4: match small, return parent) ===");
    retriever = ParentRetriever();
    root spawn retriever;
    print(f"Parent sections returned: {retriever.parents_returned}");

    print("=== Pipeline dependency ordering ===");
    runner = PipelineRunner();
    root spawn runner;
    print(f"Execution order: {runner.order}");
}

