"""Gubbins location parent cycles: ancestor guards must terminate on existing loops."""

node Location {
    has name: str = "";
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

edge ParentOf { }

walker Catalog {
    can start with Root entry {
        visit [-->];
    }

    can list with Location entry {
        print(f"location: {here.name}");
        visit [-->];
    }
}

walker UnionAllGuard {
    has mover: Location;
    has vetoed: bool = False;
    has hops: int = 0;
    has hop_limit: int = 12;

    can audit with Location entry {
        self.hops += 1;
        if self.hops > self.hop_limit {
            print(
                f"[hang] UNION ALL walk from {here.name} blew past "
                f"{self.hop_limit} hops — tab would freeze"
            );
            disengage;
        }
        if here is self.mover {
            self.vetoed = True;
            disengage;
        }
        visit [<-:ParentOf:<-] else { disengage; };
    }
}

walker AncestorGuard {
    has mover: Location;
    has vetoed: bool = False;
    has hops: int = 0;
    has seen: list[str] = [];

    can audit with Location entry {
        key = here.name;
        if key in self.seen {
            disengage;
        }
        self.seen.append(key);
        self.hops += 1;
        if here is self.mover {
            self.vetoed = True;
            disengage;
        }
        visit [<-:ParentOf:<-] else { disengage; };
    }
}

with entry {
    a = Location(name="A", title="Shelf A");
    b = Location(name="B", title="Shelf B");
    c = Location(name="C", title="Shelf C");
    d = Location(name="D", title="Loose bin");

    a +>:ParentOf:+> c;
    c +>:ParentOf:+> b;
    b +>:ParentOf:+> a;

    root ++> a;
    root ++> d;

    print("=== catalog ===");
    root spawn Catalog();

    print("=== move D under B (cycle A→C→B→A already in data) ===");

    flawed = UnionAllGuard(mover=d);
    b spawn flawed;
    flawed_allowed = not flawed.vetoed;
    print(
        f"UNION ALL pre-check: vetoed={flawed.vetoed}, "
        f"hops={flawed.hops}, would_allow={flawed_allowed}"
    );

    fixed = AncestorGuard(mover=d);
    b spawn fixed;
    fixed_allowed = not fixed.vetoed;
    print(
        f"UNION pre-check: vetoed={fixed.vetoed}, "
        f"hops={fixed.hops}, would_allow={fixed_allowed}"
    );

    if fixed_allowed {
        d +>:ParentOf:+> b;
        print("relocated D under B");
    }

    print("=== self-descendant move B under C (must veto) ===");
    veto_probe = AncestorGuard(mover=b);
    c spawn veto_probe;
    vetoed = veto_probe.vetoed;
    print(f"UNION pre-check: vetoed={vetoed}, hops={veto_probe.hops}");
}

"""Struct hashability: one shared visited set across field-type branches."""

node TypeDef {
    has name: str = "";
    has is_primitive: bool = False;
}

edge HasField {
    has slot: int = 0;
}

walker HashabilityAuditor {
    has visited: list[str] = [];
    has on_path: list[str] = [];
    has checks: int = 0;
    has hashable: bool = True;
    has reason: str = "";

    can audit with TypeDef entry {
        self.checks += 1;
        if here.name in self.on_path {
            self.hashable = False;
            self.reason = f"cycle at {here.name}";
            disengage;
        }
        if here.name in self.visited {
            disengage;
        }
        self.visited.append(here.name);
        self.on_path.append(here.name);
        if !here.is_primitive {
            visit [->:HasField:->] else { disengage; };
        }
        if len(self.on_path) > 0 {
            self.on_path = self.on_path[:-1];
        }
    }
}

walker DerivePass {
    has answer: bool = False;
    has detail: str = "";

    can derive with TypeDef entry {
        auditor = HashabilityAuditor();
        here spawn auditor;
        self.answer = auditor.hashable;
        detail_ok = "all field types hashable";
        detail_bad = auditor.reason;
        self.detail = detail_ok if self.answer else detail_bad;
        print(
            f"derive {here.name}: hashable={self.answer} "
            f"({self.detail}) in {auditor.checks} checks"
        );
    }
}

with entry {
    s0 = TypeDef(name="S0", is_primitive=True);
    s1 = TypeDef(name="S1");
    s1 +>:HasField(slot=0):+> s0;
    s1 +>:HasField(slot=1):+> s0;
    s1 +>:HasField(slot=2):+> s0;
    s1 +>:HasField(slot=3):+> s0;
    s2 = TypeDef(name="S2");
    s2 +>:HasField(slot=0):+> s1;
    s2 +>:HasField(slot=1):+> s1;
    s2 +>:HasField(slot=2):+> s1;
    s2 +>:HasField(slot=3):+> s1;
    s3 = TypeDef(name="S3");
    s3 +>:HasField(slot=0):+> s2;
    s3 +>:HasField(slot=1):+> s2;
    s3 +>:HasField(slot=2):+> s2;
    s3 +>:HasField(slot=3):+> s2;
    root ++> s3;
    s3 spawn DerivePass();
}

"""Gubbins location parent cycles: ancestor pre-check clears but update walks loop on existing loops."""

node Location {
    has name: str = "";
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

edge ParentOf { }

walker Catalog {
    can start with Root entry {
        visit [-->] else { disengage; };
    }

    can list with Location entry {
        print(f"location: {here.name}");
    }
}

walker Precheck {
    has mover: Location;
    has vetoed: bool = False;
    has seen: list[str] = [];

    can audit with Location entry {
        key = here.name;
        if key in self.seen {
            disengage;
        }
        self.seen.append(key);
        if here is self.mover {
            self.vetoed = True;
            disengage;
        }
        visit [<-:ParentOf:<-] else { disengage; };
    }
}

walker UpdateWalk {
    has hops: int = 0;
    has seen: list[str] = [];
    has frozen: bool = False;

    can rewrite with Location entry {
        key = here.name;
        if key in self.seen {
            self.frozen = True;
            print(
                f"[hang] locations.update re-hit {key} on cyclic "
                f"parentage — move never completes"
            );
            disengage;
        }
        self.seen.append(key);
        self.hops += 1;
        visit [<-:ParentOf:<-] else { disengage; };
    }
}

with entry {
    a = Location(name="A", title="Shelf A");
    b = Location(name="B", title="Shelf B");
    c = Location(name="C", title="Shelf C");
    d = Location(name="D", title="Loose bin");

    a +>:ParentOf:+> c;
    c +>:ParentOf:+> b;
    b +>:ParentOf:+> a;

    root ++> a;
    root ++> d;

    print("=== catalog ===");
    root spawn Catalog();

    print("=== move D under B (cycle A→C→B→A already in data) ===");
    pre = Precheck(mover=d);
    b spawn pre;
    allowed = not pre.vetoed;
    print(
        f"ancestor pre-check: vetoed={pre.vetoed}, "
        f"hops={pre.seen.length}, would_allow={allowed}"
    );

    print("=== self-descendant move B under C (must veto) ===");
    veto = Precheck(mover=b);
    c spawn veto;
    print(
        f"ancestor pre-check: vetoed={veto.vetoed}, "
        f"hops={veto.seen.length}"
    );

    if allowed {
        b +>:ParentOf:+> d;
        print("relocated D under B — running locations.update walk");
        upd = UpdateWalk();
        d spawn upd;
        done = not upd.frozen;
        print(f"update finished: frozen={upd.frozen}, hops={upd.hops}, done={done}");
    }
}

