"""Agentic dev bootstrap: task dependency graph, next-eligible dispatch, and cycle detection."""

node Milestone {
    has title: str = "";
    has version: str = "";
}

node Task {
    has title: str = "";
    has status: str = "PLANNED";
    has priority: int = 0;
}

edge DependsOn { }

walker NextTaskFinder {
    has found: bool = False;

    can start with Root entry {
        print("=== Next eligible task ===");
        visit [-->] else { disengage; }
    }

    can enter_milestone with Milestone entry {
        visit [-->];
    }

    can seek with Task entry {
        if not self.found {
            visit [->:DependsOn:->] else {
                if here.status == "PLANNED" {
                    self.found = True;
                    print(f"  NEXT -> {here.title} (priority {here.priority})");
                }
            };
        }
        visit [-->];
    }
}

walker CycleSentinel {
    has stack: list = [];
    has cyclic: bool = False;

    can begin with Root entry {
        print("=== Dependency cycle check ===");
        visit [-->] else { disengage; }
    }

    can enter_milestone with Milestone entry {
        visit [-->];
    }

    can walk with Task entry {
        for name in self.stack {
            if name == here.title {
                print(f"  CYCLE at {here.title}");
                self.cyclic = True;
                disengage;
            }
        }
        self.stack.append(here.title);
        visit [->:DependsOn:->] else {
            if self.stack {
                self.stack.pop();
            }
        };
        visit [-->];
    }
}

walker LifecycleReporter {
    can start with Root entry {
        print("=== Task lifecycle snapshot ===");
        visit [-->] else { disengage; }
    }

    can enter_milestone with Milestone entry {
        print(f"Milestone: {here.title} v{here.version}");
        visit [-->];
    }

    can report with Task entry {
        gate = "open" if here.status == "PLANNED" else "closed";
        print(f"  [{here.status}] {here.title} gate={gate}");
        visit [-->];
    }
}

with entry {
    bootstrap = Milestone(title="Agentic Bootstrap", version="1.0.0");
    root ++> bootstrap;

    state_machine = Task(title="State machine", status="DONE", priority=1);
    cli = Task(title="CLI orchestrator", status="PLANNED", priority=2);
    github_adapter = Task(title="GitHub adapter", status="PLANNED", priority=3);
    qa_pipeline = Task(title="QA pipeline", status="PLANNED", priority=4);

    bootstrap ++> state_machine ++> cli ++> github_adapter;
    bootstrap ++> qa_pipeline;

    cli +>:DependsOn:+> state_machine;
    github_adapter +>:DependsOn:+> cli;
    qa_pipeline +>:DependsOn:+> github_adapter;

    bootstrap spawn LifecycleReporter();
    bootstrap spawn NextTaskFinder();
    bootstrap spawn CycleSentinel();

    cycle_a = Task(title="Cyclic A", status="PLANNED", priority=99);
    cycle_b = Task(title="Cyclic B", status="PLANNED", priority=99);
    cycle_a +>:DependsOn:+> cycle_b;
    cycle_b +>:DependsOn:+> cycle_a;
    root ++> cycle_a;
    cycle_a spawn CycleSentinel();
}

